class Solution {
    public static int findMissingNumber(int[] nums) {
        int n = nums.length;
        int expectedSum = ((n + 1) * (n + 2)) / 2;
        int actualSum = 0;
        for (int i = 0; i < n; i++) {
            actualSum += nums[i];
        }
        return expectedSum - actualSum;
    }
}

class Solution {
    public static long numberSpiral(long y, long x) {
        if (y > x) {
            long ans = (y - 1) * (y - 1);
            return (y % 2 != 0) ? ans + x : ans + 2 * y - x;
        } else {
            long ans = (x - 1) * (x - 1);
            return (x % 2 == 0) ? ans + y : ans + 2 * x - y;
        }
    }
}

