class Solution {
    public static List<Integer> josephusOrder(int n) {
        List<Integer> people = new ArrayList<>();
        for (int i = 1; i <= n; i++) people.add(i);
        List<Integer> order = new ArrayList<>();
        int idx = 0;
        while (!people.isEmpty()) {
            idx = (idx + 1) % people.size();
            order.add(people.get(idx));
            people.remove(idx);
            if (idx == people.size()) idx = 0;
        }
        return order;
    }
}

