class Solution {
    public static int apartments(int m, int[] a, int[] b) {
        Arrays.sort(a);
        Arrays.sort(b);
        int i = 0, j = 0, count = 0;
        while (i < a.length && j < b.length) {
            if (Math.abs(a[i] - b[j]) <= m) {
                i++;
                j++;
                count++;
            } else if (a[i] < b[j]) {
                i++;
            } else {
                j++;
            }
        }
        return count;
    }
}

