class Solution {
    public static int ferrisWheel(int[] people, int limit) {
        Arrays.sort(people);
        int left = 0, right = people.length - 1;
        int gondolas = 0;
        while (left <= right) {
            if (left == right) { gondolas++; break; }
            if (people[left] + people[right] <= limit) left++;
            right--;
            gondolas++;
        }
        return gondolas;
    }
}

