class Solution {
    public static int restaurantCustomers(int[] arrivals, int[] departures) {
        Arrays.sort(arrivals);
        Arrays.sort(departures);
        int maxCustomers = 0, currentCustomers = 0, i = 0, j = 0;
        while (i < arrivals.length && j < departures.length) {
            if (arrivals[i] <= departures[j]) {
                currentCustomers++;
                i++;
            } else {
                currentCustomers--;
                j++;
            }
            maxCustomers = Math.max(maxCustomers, currentCustomers);
        }
        return maxCustomers;
    }
}

class Solution {
    public static int diceCombinations(int dice, int target) {
        int[] dp = new int[target + 1];
        dp[0] = 1;
        for (int i = 1; i <= target; i++) {
            int limit = Math.min(i, dice);
            for (int j = 1; j <= limit; j++) {
                dp[i] = (int)(((long)dp[i] + dp[i - j]) % 1000000007);
            }
        }
        return dp[target];
    }
}

