class Solution {
    public static int bookShop(int[] prices, int[] pages, int budget) {
        int n = prices.length;
        int[][] dp = new int[n + 1][budget + 1];
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= budget; j++) {
                if (prices[i - 1] > j) {
                    dp[i][j] = dp[i - 1][j];
                } else {
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i - 1][j - prices[i - 1]] + pages[i - 1]);
                }
            }
        }
        return dp[n][budget];
    }
}

