class Solution {
    public static int countRooms(int[][] grid) {
        int rooms = 0;
        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
        Set<String> visited = new HashSet<>();
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                if (grid[i][j] == 0 && !visited.contains(i + "," + j)) {
                    rooms++;
                    dfs(grid, i, j, visited, directions);
                }
            }
        }
        return rooms;
    }

    private static void dfs(int[][] grid, int i, int j, Set<String> visited, int[][] directions) {
        visited.add(i + "," + j);
        for (int[] dir : directions) {
            int ni = i + dir[0];
            int nj = j + dir[1];
            if (ni >= 0 && ni < grid.length && nj >= 0 && nj < grid[0].length) {
                if (grid[ni][nj] == 0 && !visited.contains(ni + "," + nj)) {
                    dfs(grid, ni, nj, visited, directions);
                }
            }
        }
    }
}

