class Solution {
    public static int[] buildTeams(int n, int[][] edges) {
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }
        int[] team = new int[n];
        for (int start = 0; start < n; start++) {
            if (team[start] != 0) continue;
            team[start] = 1;
            Queue<Integer> queue = new LinkedList<>();
            queue.add(start);
            while (!queue.isEmpty()) {
                int node = queue.poll();
                for (int nb : graph[node]) {
                    if (team[nb] == 0) {
                        team[nb] = team[node] == 1 ? 2 : 1;
                        queue.add(nb);
                    } else if (team[nb] == team[node]) {
                        return null;
                    }
                }
            }
        }
        return team;
    }
}

