class Solution {
    public static long[] investigation(int n, int[][] edges) {
        final long MOD = 1000000007;
        List<int[]>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) graph[e[0]].add(new int[]{e[1], e[2]});
        long[] dist = new long[n], ways = new long[n], minF = new long[n], maxF = new long[n];
        Arrays.fill(dist, Long.MAX_VALUE);
        Arrays.fill(minF, Long.MAX_VALUE);
        Arrays.fill(maxF, Long.MIN_VALUE);
        dist[0] = 0; ways[0] = 1; minF[0] = 0; maxF[0] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        pq.add(new long[]{0, 0});
        while (!pq.isEmpty()) {
            long[] top = pq.poll();
            long d = top[0]; int u = (int) top[1];
            if (d > dist[u]) continue;
            for (int[] edge : graph[u]) {
                int v = edge[0], w = edge[1];
                long nd = dist[u] + w;
                if (nd < dist[v]) {
                    dist[v] = nd;
                    ways[v] = ways[u];
                    minF[v] = minF[u] + 1;
                    maxF[v] = maxF[u] + 1;
                    pq.add(new long[]{nd, v});
                } else if (nd == dist[v]) {
                    ways[v] = (ways[v] + ways[u]) % MOD;
                    minF[v] = Math.min(minF[v], minF[u] + 1);
                    maxF[v] = Math.max(maxF[v], maxF[u] + 1);
                }
            }
        }
        return new long[]{dist[n-1], ways[n-1], minF[n-1], maxF[n-1]};
    }
}

