class Solution {
    public static double[] shortestRoutes(double[][] graph, int start) {
        int n = graph.length;
        double[] distances = new double[n];
        for (int i = 0; i < n; i++) {
            distances[i] = Double.POSITIVE_INFINITY;
        }
        distances[start] = 0.0;
        for (int i = 0; i < n - 1; i++) {
            for (int u = 0; u < n; u++) {
                for (int v = 0; v < graph[u].length; v++) {
                    if (graph[u][v] != 0.0 && distances[u] + graph[u][v] < distances[v]) {
                        distances[v] = distances[u] + graph[u][v];
                    }
                }
            }
        }
        for (int u = 0; u < n; u++) {
            for (int v = 0; v < graph[u].length; v++) {
                if (graph[u][v] != 0.0 && distances[u] + graph[u][v] < distances[v]) {
                    throw new RuntimeException("Graph contains a negative-weight cycle");
                }
            }
        }
        return distances;
    }
}

