class Solution {
    public static int[] findBorders(String word) {
        int[] border = new int[word.length()];
        int i = 1, j = 0;
        while (i < word.length()) {
            if (word.charAt(i) == word.charAt(j)) {
                j++;
                border[i] = j;
                i++;
            } else if (j != 0) {
                j = border[j - 1];
            } else {
                i++;
            }
        }
        return border;
    }
}

