class Solution {
    public static String longestPalindromicSubstring(String s) {
        int n = s.length();
        boolean[][] dp = new boolean[n][n];
        int maxLength = 1;
        int start = 0;
        for (int i = n - 1; i >= 0; i--) {
            dp[i][i] = true;
            for (int j = i + 1; j < n; j++) {
                if (s.charAt(i) == s.charAt(j) && (j - i == 1 || dp[i + 1][j - 1])) {
                    dp[i][j] = true;
                    int len = j - i + 1;
                    if (len > maxLength || (len == maxLength && i < start)) {
                        maxLength = len;
                        start = i;
                    }
                }
            }
        }
        return s.substring(start, start + maxLength);
    }
}

