class Solution {
    public static String convert(String s, int numRows) {
        if (numRows == 1 || s.length() <= numRows) {
            return s;
        }
        StringBuilder result = new StringBuilder(s.length());
        int cycleLen = 2 * (numRows - 1);
        for (int row = 0; row < numRows; row++) {
            for (int j = row; j < s.length(); j += cycleLen) {
                result.append(s.charAt(j));
                int inter = cycleLen - 2 * row;
                if (row != 0 && row != numRows - 1 && j + inter < s.length()) {
                    result.append(s.charAt(j + inter));
                }
            }
        }
        return result.toString();
    }
}

public class Solution {
    public static int reverse(int x) {
        boolean isNegative = x < 0;
        x = Math.abs(x);
        long reversed = 0;
        while (x > 0) {
            int digit = x % 10;
            x = x / 10;
            reversed = reversed * 10 + digit;
            if (reversed > 2147483647L) return 0;
        }
        return isNegative ? (int) -reversed : (int) reversed;
    }
}

