class Solution {
    private static class HeapNode {
        int val;
        int listIndex;
        ListNode node;
        HeapNode(int val, int listIndex, ListNode node) {
            this.val = val;
            this.listIndex = listIndex;
            this.node = node;
        }
    }

    public ListNode mergeKLists(ListNode[] lists) {
        List<HeapNode> minHeap = new ArrayList<>();
        for (int i = 0; i < lists.length; i++) {
            if (lists[i] != null) {
                minHeap.add(new HeapNode(lists[i].val, i, lists[i]));
            }
        }

        ListNode dummyHead = new ListNode(0);
        ListNode current = dummyHead;

        minHeap.sort((a, b) -> a.val - b.val);

        while (!minHeap.isEmpty()) {
            HeapNode smallestNode = minHeap.remove(0);
            current.next = smallestNode.node;
            current = current.next;
            if (smallestNode.node.next != null) {
                minHeap.add(new HeapNode(smallestNode.node.next.val, smallestNode.listIndex, smallestNode.node.next));
                minHeap.sort((a, b) -> a.val - b.val);
            }
        }

        return dummyHead.next;
    }
}

