class Solution {
    public static List<Integer> findSubstring(String s, String[] words) {
        int wordLength = words[0].length();
        int totalWords = words.length;
        int totalLength = wordLength * totalWords;
        Map<String, Integer> wordCount = new HashMap<>();
        for (String word : words) {
            wordCount.put(word, wordCount.getOrDefault(word, 0) + 1);
        }
        List<Integer> result = new ArrayList<>();
        for (int i = 0; i <= s.length() - totalLength; i++) {
            Map<String, Integer> windowCount = new HashMap<>(wordCount);
            for (int j = 0; j < totalWords; j++) {
                int start = i + j * wordLength;
                int end = start + wordLength;
                String word = s.substring(start, end);
                if (!windowCount.containsKey(word) || windowCount.get(word) == 0) {
                    break;
                }
                windowCount.put(word, windowCount.get(word) - 1);
                if (j == totalWords - 1) {
                    result.add(i);
                }
            }
        }
        return result;
    }
}

