        backtrack(candidates, target, new ArrayList<>(), 0, result);
        return result;
    }

    private static void backtrack(int[] candidates, int remain, List<Integer> comb, int start, List<List<Integer>> result) {
        if (remain == 0) {
            result.add(new ArrayList<>(comb));
            return;
        }
        for (int i = start; i < candidates.length; i++) {
            if (i > start && candidates[i] == candidates[i - 1]) continue;
            if (candidates[i] > remain) break;
            comb.add(candidates[i]);
            backtrack(candidates, remain - candidates[i], comb, i + 1, result);
            comb.remove(comb.size() - 1);
        }
    }
}

