class Solution {
    public static List<List<Integer>> permute(int[] nums) {
        List<List<Integer>> result = new ArrayList<>();
        List<Integer> initialRemaining = new ArrayList<>();
        for (int num : nums) {
            initialRemaining.add(num);
        }
        backtrack(result, new ArrayList<>(), initialRemaining);
        return result;
    }

    private static void backtrack(List<List<Integer>> result, List<Integer> current, List<Integer> remaining) {
        if (remaining.isEmpty()) {
            result.add(new ArrayList<>(current));
        } else {
            for (int i = 0; i < remaining.size(); i++) {
                current.add(remaining.get(i));
                List<Integer> newRemaining = new ArrayList<>(remaining);
                newRemaining.remove(i);
                backtrack(result, current, newRemaining);
                current.remove(current.size() - 1);
            }
        }
    }
}

