public class Solution {
    public static int totalNQueens(int n) {
        int[] board = new int[n];
        Arrays.fill(board, -1);
        return placeQueens(board, 0, n);
    }

    private static boolean isValid(int[] board, int row, int col) {
        for (int i = 0; i < row; i++) {
            if (board[i] == col ||
                board[i] - i == col - row ||
                board[i] + i == col + row) {
                return false;
            }
        }
        return true;
    }

    private static int placeQueens(int[] board, int row, int n) {
        if (row == n) {
            return 1;
        }
        int count = 0;
        for (int col = 0; col < n; col++) {
            if (isValid(board, row, col)) {
                board[row] = col;
                count += placeQueens(board, row + 1, n);
            }
        }
        return count;
    }
}

