class Solution {
    public static List<String> fullJustify(String[] words, int maxWidth) {
        List<String> result = new ArrayList<>();
        List<String> currentLine = new ArrayList<>();
        int currentWidth = 0;
        for (String word : words) {
            if (currentWidth + currentLine.size() + word.length() > maxWidth) {
                int spaces = maxWidth - currentWidth;
                int gaps = currentLine.size() - 1;
                StringBuilder line = new StringBuilder();
                if (gaps == 0) {
                    line.append(currentLine.get(0));
                    line.append(" ".repeat(spaces));
                } else {
                    int spacePerGap = spaces / gaps;
                    int extra = spaces % gaps;
                    for (int i = 0; i < currentLine.size(); i++) {
                        line.append(currentLine.get(i));
                        if (i < gaps) {
                            int repeat = spacePerGap + (i < extra ? 1 : 0);
                            line.append(" ".repeat(repeat));
                        }
                    }
                }
                result.add(line.toString());
                currentLine = new ArrayList<>();
                currentLine.add(word);
                currentWidth = word.length();
            } else {
                currentLine.add(word);
                currentWidth += word.length();
            }
        }
        String lastLine = String.join(" ", currentLine);
        result.add(lastLine + " ".repeat(maxWidth - lastLine.length()));
        return result;
    }
}

public class Solution {
    public static int mySqrt(int x) {
        int low = 0;
        int high = x;
        int result = 0;
        while (low <= high) {
            int mid = (low + high) / 2;
            if ((long)mid * mid <= x) {
                result = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return result;
    }
}

