class Solution {
    public static boolean searchMatrix(int[][] matrix, int target) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        int left = 0;
        int right = rows * cols - 1;
        while (left <= right) {
            int mid = (left + right) / 2;
            int midValue = matrix[mid / cols][mid % cols];
            if (midValue == target) {
                return true;
            } else if (midValue < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return false;
    }
}

class Solution {
    public static int[] sortColors(int[] nums) {
        int left = 0, right = nums.length - 1, current = 0;
        while (current <= right) {
            if (nums[current] == 0) {
                int temp = nums[left];
                nums[left] = nums[current];
                nums[current] = temp;
                left++;
                current++;
            } else if (nums[current] == 2) {
                int temp = nums[right];
                nums[right] = nums[current];
                nums[current] = temp;
                right--;
            } else {
                current++;
            }
        }
        return nums;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static String minWindow(String s, String t) {
        Map<Character, Integer> tCount = new HashMap<>();
        for (char c : t.toCharArray()) {
            tCount.put(c, tCount.getOrDefault(c, 0) + 1);
        }

        int left = 0;
        int minLen = Integer.MAX_VALUE;
        String minWindow = "";
        int count = tCount.size();
        int formed = 0;

        Map<Character, Integer> windowCounts = new HashMap<>();

        for (int right = 0; right < s.length(); right++) {
            char character = s.charAt(right);
            windowCounts.put(character, windowCounts.getOrDefault(character, 0) + 1);

            if (tCount.containsKey(character) && windowCounts.get(character).intValue() == tCount.get(character).intValue()) {
                formed++;
            }

            while (left <= right && formed == count) {
                if (right - left + 1 < minLen) {
                    minLen = right - left + 1;
                    minWindow = s.substring(left, right + 1);
                }

                char ch = s.charAt(left);
                windowCounts.put(ch, windowCounts.get(ch) - 1);
                if (tCount.containsKey(ch) && windowCounts.get(ch).intValue() < tCount.get(ch).intValue()) {
                    formed--;
                }
                left++;
            }
        }

        return minWindow;
    }
}

