class Solution {
    public static int removeDuplicates(int[] nums) {
        int writeIndex = 0;
        int count = 0;
        for (int readIndex = 0; readIndex < nums.length; readIndex++) {
            if (readIndex == 0 || nums[readIndex] != nums[readIndex - 1]) {
                count = 1;
            } else {
                count++;
            }
            if (count <= 2) {
                nums[writeIndex] = nums[readIndex];
                writeIndex++;
            }
        }
        return writeIndex;
    }
}

