class Solution {
    public static List<String> restoreIpAddresses(String s) {
        List<String> result = new ArrayList<>();
        backtrack(s, 0, new ArrayList<>(), result);
        return result;
    }

    private static boolean isValid(String segment) {
        return Integer.parseInt(segment) <= 255 && (segment.length() == 1 || segment.charAt(0) != '0');
    }

    private static void backtrack(String s, int start, List<String> path, List<String> result) {
        if (path.size() == 4) {
            if (start == s.length()) {
                result.add(String.join(".", path));
            }
            return;
        }
        for (int len = 1; len <= 3; len++) {
            if (start + len > s.length()) {
                break;
            }
            String segment = s.substring(start, start + len);
            if (isValid(segment)) {
                List<String> newPath = new ArrayList<>(path);
                newPath.add(segment);
                backtrack(s, start + len, newPath, result);
            }
        }
    }
}

