class Solution {
    public static TreeNode buildTree(int[] preorder, int[] inorder) {
        Map<Integer, Integer> inorderMap = new HashMap<>();
        for (int i = 0; i < inorder.length; i++) {
            inorderMap.put(inorder[i], i);
        }
        return recursiveBuild(preorder, 0, preorder.length - 1, inorder, 0, inorder.length - 1, inorderMap);
    }

    private static TreeNode recursiveBuild(int[] preorder, int preStart, int preEnd,
                                            int[] inorder, int inStart, int inEnd,
                                            Map<Integer, Integer> inorderMap) {
        if (preStart > preEnd) return null;
        TreeNode root = new TreeNode(preorder[preStart]);
        int inIndex = inorderMap.get(preorder[preStart]);
        int leftSize = inIndex - inStart;
        root.left = recursiveBuild(preorder, preStart + 1, preStart + leftSize,
                                   inorder, inStart, inIndex - 1, inorderMap);
        root.right = recursiveBuild(preorder, preStart + leftSize + 1, preEnd,
                                    inorder, inIndex + 1, inEnd, inorderMap);
        return root;
    }
}

