                postorderStart + leftSubtreeSize - 1, inorder, postorder, inorderIndexMap);
        root.right = recursiveBuildTree(inorderRootIndex + 1, inorderEnd, postorderStart + leftSubtreeSize,
                postorderEnd - 1, inorder, postorder, inorderIndexMap);
        return root;
    }
