class Solution {
    public static List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
        Set<String> wordSet = new HashSet<>(wordList);
        List<List<String>> results = new ArrayList<>();
        if (!wordSet.contains(endWord)) {
            return results;
        }
        Queue<List<String>> queue = new LinkedList<>();
        queue.offer(new ArrayList<>(Arrays.asList(beginWord)));
        int level = 1;
        int minLevel = Integer.MAX_VALUE;
        while (!queue.isEmpty()) {
            int size = queue.size();
            Set<String> visitedThisLevel = new HashSet<>();
            for (int i = 0; i < size; i++) {
                List<String> path = queue.poll();
                String last = path.get(path.size() - 1);
                if (path.size() > minLevel) {
                    continue;
                }
                if (last.equals(endWord)) {
                    if (path.size() < minLevel) {
                        results.clear();
                        minLevel = path.size();
                    }
                    results.add(new ArrayList<>(path));
                    continue;
                }
                char[] chars = last.toCharArray();
                for (int pos = 0; pos < chars.length; pos++) {
                    char original = chars[pos];
                    for (char c = 'a'; c <= 'z'; c++) {
                        if (c == original) continue;
                        chars[pos] = c;
                        String next = new String(chars);
                        if (wordSet.contains(next)) {
                            List<String> newPath = new ArrayList<>(path);
                            newPath.add(next);
                            queue.offer(newPath);
                            visitedThisLevel.add(next);
                        }
                    }
                    chars[pos] = original;
                }
            }
            wordSet.removeAll(visitedThisLevel);
            if (minLevel != Integer.MAX_VALUE && level >= minLevel) {
                break;
            }
            level++;
        }
        return results;
    }
}

