class Solution {
    public static char[][] solve(char[][] board) {
        if (board == null || board.length == 0) return board;
        int rows = board.length;
        int cols = board[0].length;
        for (int i = 0; i < rows; i++) {
            dfs(i, 0, board, rows, cols);
            dfs(i, cols - 1, board, rows, cols);
        }
        for (int i = 0; i < cols; i++) {
            dfs(0, i, board, rows, cols);
            dfs(rows - 1, i, board, rows, cols);
        }
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (board[i][j] == 'O') board[i][j] = 'X';
                else if (board[i][j] == 'N') board[i][j] = 'O';
            }
        }
        return board;
    }

    private static void dfs(int row, int col, char[][] board, int rows, int cols) {
        if (row < 0 || row >= rows || col < 0 || col >= cols || board[row][col] != 'O') return;
        board[row][col] = 'N';
        dfs(row - 1, col, board, rows, cols);
        dfs(row + 1, col, board, rows, cols);
        dfs(row, col - 1, board, rows, cols);
        dfs(row, col + 1, board, rows, cols);
    }
}

