class Solution {
    public static List<String> wordBreak(String s, List<String> wordDict) {
        Set<String> wordSet = new HashSet<>(wordDict);
        Map<Integer, List<List<String>>> memo = new HashMap<>();
        List<List<String>> allSentences = backtrack(s, wordSet, memo, 0);
        List<String> result = new ArrayList<>();
        for (List<String> words : allSentences) {
            result.add(String.join(" ", words));
        }
        result.sort((a, b) -> {
            int wordsA = a.isEmpty() ? 0 : a.split(" ").length;
            int wordsB = b.isEmpty() ? 0 : b.split(" ").length;
            if (wordsA != wordsB) {
                return Integer.compare(wordsB, wordsA);
            }
            int firstLenA = a.isEmpty() ? 0 : a.split(" ")[0].length();
            int firstLenB = b.isEmpty() ? 0 : b.split(" ")[0].length();
            if (firstLenA != firstLenB) {
                return Integer.compare(firstLenB, firstLenA);
            }
            return a.compareTo(b);
        });
        return result;
    }

    private static List<List<String>> backtrack(String s, Set<String> wordSet, Map<Integer, List<List<String>>> memo, int start) {
        if (start == s.length()) {
            List<List<String>> base = new ArrayList<>();
            base.add(new ArrayList<>());
            return base;
        }
        if (memo.containsKey(start)) {
            return memo.get(start);
        }
        List<List<String>> result = new ArrayList<>();
        for (int end = start + 1; end <= s.length(); end++) {
            String word = s.substring(start, end);
            if (wordSet.contains(word)) {
                List<List<String>> nextWords = backtrack(s, wordSet, memo, end);
                for (List<String> nextWord : nextWords) {
                    List<String> sentence = new ArrayList<>();
                    sentence.add(word);
                    sentence.addAll(nextWord);
                    result.add(sentence);
                }
            }
        }
        memo.put(start, result);
        return result;
    }
}

