public class Solution {
    public static CacheOperation LRUCache(final int capacity) {
        return new CacheOperation() {
            private final Map<Integer, Node> cache = new HashMap<>();
            private final Node head = new Node(0, 0);
            private final Node tail = new Node(0, 0);
            private int size = 0;
            {
                head.next = tail;
                tail.prev = head;
            }
            private class Node {
                int key;
                int value;
                Node prev;
                Node next;
                Node(int k, int v) {
                    key = k;
                    value = v;
                }
            }
            private void remove(Node node) {
                node.prev.next = node.next;
                node.next.prev = node.prev;
            }
            private void add(Node node) {
                node.prev = tail.prev;
                node.next = tail;
                tail.prev.next = node;
                tail.prev = node;
            }
            @Override
            public int apply(String operation, int key, int value) {
                if ("get".equals(operation)) {
                    Node node = cache.get(key);
                    if (node != null) {
                        remove(node);
                        add(node);
                        return node.value;
                    } else {
                        return -1;
                    }
                } else if ("put".equals(operation)) {
                    Node node = cache.get(key);
                    if (node != null) {
                        node.value = value;
                        remove(node);
                        add(node);
                    } else {
                        Node newNode = new Node(key, value);
                        cache.put(key, newNode);
                        add(newNode);
                        size++;
                        if (size > capacity) {
                            Node lruNode = head.next;
                            cache.remove(lruNode.key);
                            remove(lruNode);
                            size--;
                        }
                    }
                }
                return -1;
            }
        };
    }
    public interface CacheOperation {
        int apply(String operation, int key, int value);
    }
}

