class Solution {
    public static int maxPoints(int[][] points) {
        if (points == null || points.length == 0) return 0;
        int maxPoints = 0;
        for (int i = 0; i < points.length; i++) {
            Map<String, Integer> slopeMap = new HashMap<>();
            int samePoint = 1;
            for (int j = i + 1; j < points.length; j++) {
                if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
                    samePoint++;
                } else {
                    String slope = calculateSlope(points[i], points[j]);
                    slopeMap.put(slope, slopeMap.getOrDefault(slope, 0) + 1);
                }
            }
            int maxCount = 0;
            for (int count : slopeMap.values()) {
                if (count > maxCount) maxCount = count;
            }
            maxPoints = Math.max(maxPoints, maxCount + samePoint);
        }
        return maxPoints;
    }

    private static String calculateSlope(int[] point1, int[] point2) {
        int xDiff = point2[0] - point1[0];
        int yDiff = point2[1] - point1[1];
        if (xDiff == 0) return "Infinity";
        return Double.toString((double) yDiff / xDiff);
    }
}

import java.util.Stack;

class Solution {
    public static int evalRPN(String[] tokens) {
        Stack<Integer> stack = new Stack<>();
        for (int i = 0; i < tokens.length; i++) {
            if (tokens[i].equals("+") || tokens[i].equals("-") || tokens[i].equals("*") || tokens[i].equals("/")) {
                int num2 = stack.pop();
                int num1 = stack.pop();
                if (tokens[i].equals("+")) stack.push(num1 + num2);
                else if (tokens[i].equals("-")) stack.push(num1 - num2);
                else if (tokens[i].equals("*")) stack.push(num1 * num2);
                else stack.push(num1 / num2);
            } else {
                stack.push(Integer.parseInt(tokens[i]));
            }
        }
        return stack.peek();
    }
}

