public class Solution {
    public static int maximumGap(int[] nums) {
        if (nums == null || nums.length < 2) return 0;
        int minVal = Integer.MAX_VALUE;
        int maxVal = Integer.MIN_VALUE;
        for (int num : nums) {
            if (num < minVal) minVal = num;
            if (num > maxVal) maxVal = num;
        }
        if (minVal == maxVal) return 0;
        int bucketSize = Math.max(1, (maxVal - minVal) / (nums.length - 1));
        int bucketCount = (maxVal - minVal) / bucketSize + 1;
        Bucket[] buckets = new Bucket[bucketCount];
        for (int i = 0; i < bucketCount; i++) {
            buckets[i] = new Bucket();
        }
        for (int num : nums) {
            int index = (num - minVal) / bucketSize;
            Bucket b = buckets[index];
            if (num < b.min) b.min = num;
            if (num > b.max) b.max = num;
        }
        int maxGap = 0;
        int prevMax = buckets[0].max;
        for (int i = 1; i < bucketCount; i++) {
            if (buckets[i].min != Integer.MAX_VALUE) {
                maxGap = Math.max(maxGap, buckets[i].min - prevMax);
                prevMax = buckets[i].max;
            }
        }
        return maxGap;
    }

    private static class Bucket {
        int min = Integer.MAX_VALUE;
        int max = Integer.MIN_VALUE;
    }
}

