class Solution {
    public static int maxProfit(int k, int[] prices) {
        if (prices == null || prices.length == 0 || k == 0) {
            return 0;
        }
        int n = prices.length;
        if (k >= n / 2) {
            int profit = 0;
            for (int i = 1; i < n; i++) {
                if (prices[i] > prices[i - 1]) {
                    profit += prices[i] - prices[i - 1];
                }
            }
            return profit;
        }
        int m = 2 * k + 1;
        int[][] dp = new int[n][m];
        for (int j = 0; j < m; j++) {
            if (j == 0) {
                dp[0][j] = 0;
            } else if (j % 2 == 1) {
                dp[0][j] = -prices[0];
            } else {
                dp[0][j] = 0;
            }
        }
        for (int i = 1; i < n; i++) {
            dp[i][0] = 0;
            for (int j = 1; j < m; j++) {
                if (j % 2 == 1) {
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i - 1][j - 1] - prices[i]);
                } else {
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i - 1][j - 1] + prices[i]);
                }
            }
        }
        return dp[n - 1][m - 1];
    }
}

