        int n = nums.length;
        if (n == 0) return nums;
        k = k % n;
        if (k < 0) k += n;
        int[] temp = new int[n];
        System.arraycopy(nums, n - k, temp, 0, k);
        System.arraycopy(nums, 0, temp, k, n - k);
        System.arraycopy(temp, 0, nums, 0, n);
        return nums;
    }
}

