class Solution {
    public static String shortestPalindrome(String s) {
        String reversed = new StringBuilder(s).reverse().toString();
        String combined = s + "#" + reversed;
        int[] prefixSuffixLengths = new int[combined.length()];
        int prefixLength = 0;
        for (int i = 1; i < combined.length(); i++) {
            while (prefixLength > 0 && combined.charAt(i) != combined.charAt(prefixLength)) {
                prefixLength = prefixSuffixLengths[prefixLength - 1];
            }
            if (combined.charAt(i) == combined.charAt(prefixLength)) {
                prefixLength++;
            }
            prefixSuffixLengths[i] = prefixLength;
        }
        int maxLength = prefixSuffixLengths[combined.length() - 1];
        return reversed.substring(0, s.length() - maxLength) + s;
    }
}

