class Solution {
    public static int[] findOrder(int numCourses, int[][] prerequisites) {
        List<Integer>[] graph = new ArrayList[numCourses];
        for (int i = 0; i < numCourses; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] pair : prerequisites) {
            int course = pair[0];
            int prereq = pair[1];
            graph[prereq].add(course);
        }
        boolean[] visited = new boolean[numCourses];
        boolean[] onPath = new boolean[numCourses];
        List<Integer> order = new ArrayList<>();
        for (int i = 0; i < numCourses; i++) {
            if (!visited[i]) {
                if (!dfs(i, graph, visited, onPath, order)) {
                    return new int[0];
                }
            }
        }
        int[] result = new int[numCourses];
        for (int i = 0; i < numCourses; i++) {
            result[i] = order.get(numCourses - 1 - i);
        }
        return result;
    }

    private static boolean dfs(int node, List<Integer>[] graph, boolean[] visited, boolean[] onPath, List<Integer> order) {
        if (onPath[node]) {
            return false;
        }
        if (visited[node]) {
            return true;
        }
        onPath[node] = true;
        for (int neighbor : graph[node]) {
            if (!dfs(neighbor, graph, visited, onPath, order)) {
                return false;
            }
        }
        onPath[node] = false;
        visited[node] = true;
        order.add(node);
        return true;
    }
}

