class Solution {
    private static class TrieNode {
        Map<Character, TrieNode> children = new HashMap<>();
        boolean end = false;
    }

    public static List<String> findWords(char[][] board, String[] words) {
        TrieNode trie = new TrieNode();
        for (String word : words) {
            TrieNode node = trie;
            for (char ch : word.toCharArray()) {
                node = node.children.computeIfAbsent(ch, k -> new TrieNode());
            }
            node.end = true;
        }

        Set<String> resultSet = new HashSet<>();
        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[0].length; j++) {
                char startChar = board[i][j];
                TrieNode child = trie.children.get(startChar);
                if (child != null) {
                    backtrack(board, i, j, child, String.valueOf(startChar), resultSet, directions);
                }
            }
        }

        List<String> result = new ArrayList<>(resultSet);
        Collections.sort(result);
        return result;
    }

    private static void backtrack(char[][] board, int row, int col, TrieNode node, String word,
                                  Set<String> result, int[][] directions) {
        if (node.end) {
            result.add(word);
        }

        char temp = board[row][col];
        board[row][col] = '#';

        for (int[] dir : directions) {
            int nr = row + dir[0];
            int nc = col + dir[1];
            if (nr >= 0 && nr < board.length && nc >= 0 && nc < board[0].length) {
                char nextChar = board[nr][nc];
                TrieNode nextNode = node.children.get(nextChar);
                if (nextNode != null) {
                    backtrack(board, nr, nc, nextNode, word + nextChar, result, directions);
                }
            }
        }

        board[row][col] = temp;
    }
}

