import java.util.HashMap;
import java.util.Map;

class Solution {
    public static boolean containsNearbyAlmostDuplicate(int[] nums, int indexDiff, int valueDiff) {
        Map<Long, Integer> buckets = new HashMap<>();
        long bucketSize = (long) valueDiff + 1;
        for (int i = 0; i < nums.length; i++) {
            long bucketIndex = Math.floorDiv((long) nums[i], bucketSize);
            if (buckets.containsKey(bucketIndex)) {
                return true;
            }
            Integer left = buckets.get(bucketIndex - 1);
            if (left != null && Math.abs((long) nums[i] - left) <= valueDiff) {
                return true;
            }
            Integer right = buckets.get(bucketIndex + 1);
            if (right != null && Math.abs((long) nums[i] - right) <= valueDiff) {
                return true;
            }
            buckets.put(bucketIndex, nums[i]);
            if (i >= indexDiff) {
                long oldBucketIndex = Math.floorDiv((long) nums[i - indexDiff], bucketSize);
                buckets.remove(oldBucketIndex);
            }
        }
        return false;
    }
}

