        List<List<Integer>> result = new ArrayList<>();
        backtrack(1, new ArrayList<>(), n, k, result);
        return result;
    }

    private static void backtrack(int start, List<Integer> path, int target, int k, List<List<Integer>> result) {
        if (path.size() == k && target == 0) {
            result.add(new ArrayList<>(path));
        } else {
            for (int i = start; i <= 9; i++) {
                if (i > target) break;
                path.add(i);
                backtrack(i + 1, path, target - i, k, result);
                path.remove(path.size() - 1);
            }
        }
    }
}

import java.lang.Math;

class Solution {
    public static int maximalSquare(char[][] matrix) {
        int rows = matrix.length;
        if (rows == 0) return 0;
        int cols = matrix[0].length;

        int[][] dp = new int[rows][cols];
        int maxSize = 0;

        for (int i = 0; i < rows; i++) {
            dp[i][0] = matrix[i][0] == '1' ? 1 : 0;
            maxSize = Math.max(maxSize, dp[i][0]);
        }
        for (int j = 0; j < cols; j++) {
            dp[0][j] = matrix[0][j] == '1' ? 1 : 0;
            maxSize = Math.max(maxSize, dp[0][j]);
        }

        for (int i = 1; i < rows; i++) {
            for (int j = 1; j < cols; j++) {
                if (matrix[i][j] == '1') {
                    dp[i][j] = Math.min(Math.min(dp[i - 1][j], dp[i][j - 1]), dp[i - 1][j - 1]) + 1;
                    maxSize = Math.max(maxSize, dp[i][j]);
                }
            }
        }

        return maxSize * maxSize;
    }
}

