class Solution {
    public static List<int[]> getSkyline(int[][] buildings) {
        List<int[]> criticalPoints = new ArrayList<>();
        for (int[] building : buildings) {
            criticalPoints.add(new int[]{building[0], -building[2]});
            criticalPoints.add(new int[]{building[1], building[2]});
        }
        criticalPoints.sort((a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);
        List<int[]> result = new ArrayList<>();
        int currentHeight = 0;
        List<Integer> heights = new ArrayList<>();
        heights.add(0);
        for (int[] point : criticalPoints) {
            if (point[1] < 0) {
                heights.add(-point[1]);
            } else {
                int index = heights.indexOf(point[1]);
                heights.remove(index);
            }
            int newHeight = Collections.max(heights);
            if (newHeight != currentHeight) {
                result.add(new int[]{point[0], newHeight});
                currentHeight = newHeight;
            }
        }
        return result;
    }
}

