class Solution {
    public static int countNodes(TreeNode root) {
        int height = 0;
        TreeNode node = root;
        while (node != null) {
            height++;
            node = node.left;
        }
        if (height == 0) return 0;
        if (height == 1) return 1;
        int left = 1;
        int right = (int) Math.pow(2, height - 1);
        while (left <= right) {
            int mid = (left + right) / 2;
            TreeNode cur = root;
            int path = mid;
            for (int i = height - 2; i >= 0 && cur != null; i--) {
                cur = ((path & (1 << i)) != 0) ? cur.right : cur.left;
            }
            if (cur != null) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return (int) Math.pow(2, height - 1) - 1 + left;
    }
}

