class Solution {
    public static int calculate(String s) {
        int sign = 1, result = 0, num = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c >= '0' && c <= '9') {
                num = num * 10 + (c - '0');
            } else if (c == '+' || c == '-') {
                result += sign * num;
                num = 0;
                sign = c == '+' ? 1 : -1;
            } else if (c == ' ') {
                continue;
            }
        }
        result += sign * num;
        return result;
    }
