class Solution {
    public static List<Integer> majorityElement(int[] nums) {
        int count1 = 0, count2 = 0;
        Integer candidate1 = null, candidate2 = null;
        for (int num : nums) {
            if (candidate1 != null && num == candidate1) {
                count1++;
            } else if (candidate2 != null && num == candidate2) {
                count2++;
            } else if (count1 == 0) {
                candidate1 = num;
                count1 = 1;
            } else if (count2 == 0) {
                candidate2 = num;
                count2 = 1;
            } else {
                count1--;
                count2--;
            }
        }
        int actualCount1 = 0, actualCount2 = 0;
        for (int num : nums) {
            if (candidate1 != null && num == candidate1) actualCount1++;
            if (candidate2 != null && num == candidate2) actualCount2++;
        }
        List<Integer> result = new ArrayList<>();
        int threshold = nums.length / 3;
        if (actualCount1 > threshold) result.add(candidate1);
        if (actualCount2 > threshold) result.add(candidate2);
        return result;
    }
}

