class Solution {
    public static int[] productExceptSelf(int[] nums) {
        int length = nums.length;
        int[] answer = new int[length];
        Arrays.fill(answer, 1);
        int prefixProduct = 1;
        for (int i = 0; i < length; i++) {
            answer[i] *= prefixProduct;
            prefixProduct *= nums[i];
        }
        int suffixProduct = 1;
        for (int i = length - 1; i >= 0; i--) {
