class Solution {
    public static List<Integer> diffWaysToCompute(String expression) {
        Map<String, List<Integer>> memo = new HashMap<>();
        return compute(expression, memo);
    }

    private static List<Integer> compute(String expression, Map<String, List<Integer>> memo) {
        if (memo.containsKey(expression)) {
            return memo.get(expression);
        }
        try {
            int num = Integer.parseInt(expression);
            List<Integer> single = new ArrayList<>();
            single.add(num);
            memo.put(expression, single);
            return single;
        } catch (NumberFormatException e) {
            // continue
        }
        List<Integer> results = new ArrayList<>();
        for (int i = 0; i < expression.length(); i++) {
            char c = expression.charAt(i);
            if (c == '+' || c == '-' || c == '*') {
                List<Integer> leftResults = compute(expression.substring(0, i), memo);
                List<Integer> rightResults = compute(expression.substring(i + 1), memo);
                for (int left : leftResults) {
                    for (int right : rightResults) {
                        int val;
                        if (c == '+') {
                            val = left + right;
                        } else if (c == '-') {
                            val = left - right;
                        } else {
                            val = left * right;
                        }
                        results.add(val);
                    }
                }
            }
        }
        Collections.sort(results);
        memo.put(expression, results);
        return results;
    }
}

