class Solution {
    public static int hIndex(int[] citations) {
        int left = 0, right = citations.length - 1;
        while (left <= right) {
            int mid = (left + right) / 2;
            int h = Math.min(citations[mid], citations.length - mid);
            if (h == citations[mid]) {
                return h;
            } else if (h < citations[mid]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return citations.length - left;
    }
}

