class Solution {
    public static List<String> addOperators(String num, int target) {
        List<String> result = new ArrayList<>();
        backtrack(num, target, 0, "", 0, 0, result);
        return result;
    }

    private static void backtrack(String num, int target, int index, String path, long value, long prev, List<String> result) {
        if (index == num.length()) {
            if (value == target) {
                result.add(path);
            }
            return;
        }
        for (int i = index; i < num.length(); i++) {
            if (i != index && num.charAt(index) == '0') break;
            String str = num.substring(index, i + 1);
            long curr = Long.parseLong(str);
            if (index == 0) {
                backtrack(num, target, i + 1, str, curr, curr, result);
            } else {
                backtrack(num, target, i + 1, path + "*" + str, value - prev + prev * curr, prev * curr, result);
                backtrack(num, target, i + 1, path + "+" + str, value + curr, curr, result);
                backtrack(num, target, i + 1, path + "-" + str, value - curr, -curr, result);
            }
        }
    }
}

