                secretCount.put(s, secretCount.getOrDefault(s, 0) + 1);
                guessCount.put(g, guessCount.getOrDefault(g, 0) + 1);
            }
        }
        for (Map.Entry<Character, Integer> entry : secretCount.entrySet()) {
            char key = entry.getKey();
            if (guessCount.containsKey(key)) {
                cows += Math.min(entry.getValue(), guessCount.get(key));
            }
        }
        return bulls + "A" + cows + "B";
    }
}

