class Solution {
    public static int lengthOfLIS(int[] nums) {
        if (nums.length == 0) return 0;
        int[] dp = new int[nums.length];
        dp[0] = nums[0];
        int len = 1;
        for (int i = 1; i < nums.length; i++) {
            if (nums[i] > dp[len - 1]) {
                dp[len++] = nums[i];
            } else {
                int left = 0, right = len - 1;
                while (left < right) {
                    int mid = (left + right) / 2;
                    if (nums[i] > dp[mid]) left = mid + 1;
                    else right = mid;
                }
                dp[left] = nums[i];
            }
        }
        return len;
    }
}

