class Solution {
    public static List<String> removeInvalidParentheses(String s) {
        Set<String> level = new LinkedHashSet<>();
        level.add(s);
        while (true) {
            List<String> valid = new ArrayList<>();
            for (String str : level) {
                if (isValid(str)) {
                    valid.add(str);
                }
            }
            if (!valid.isEmpty()) {
                return valid;
            }
            Set<String> nextLevel = new LinkedHashSet<>();
            for (String str : level) {
                for (int i = 0; i < str.length(); i++) {
                    char c = str.charAt(i);
                    if (c == '(' || c == ')') {
                        String nextStr = str.substring(0, i) + str.substring(i + 1);
                        nextLevel.add(nextStr);
                    }
                }
            }
            level = nextLevel;
        }
    }

    private static boolean isValid(String str) {
        int count = 0;
        for (int i = 0; i < str.length(); i++) {
            char c = str.charAt(i);
            if (c == '(') {
                count++;
            } else if (c == ')') {
                count--;
            }
            if (count < 0) {
                return false;
            }
        }
        return count == 0;
    }
}

