class Solution {
    private int[] tree;
    private int n;

    public Solution(int[] nums) {
        this.tree = new int[4 * nums.length];
        this.n = nums.length;
        buildTree(nums, 0, 0, n - 1);
    }

    private void buildTree(int[] nums, int node, int start, int end) {
        if (start == end) {
            tree[node] = nums[start];
        } else {
            int mid = (start + end) / 2;
            buildTree(nums, 2 * node + 1, start, mid);
            buildTree(nums, 2 * node + 2, mid + 1, end);
            tree[node] = tree[2 * node + 1] + tree[2 * node + 2];
        }
    }

    public void update(int index, int val) {
        updateTree(0, 0, n - 1, index, val);
    }

    private void updateTree(int node, int start, int end, int idx, int val) {
        if (start == end) {
            tree[node] = val;
        } else {
            int mid = (start + end) / 2;
            if (idx <= mid) {
                updateTree(2 * node + 1, start, mid, idx, val);
            } else {
                updateTree(2 * node + 2, mid + 1, end, idx, val);
            }
            tree[node] = tree[2 * node + 1] + tree[2 * node + 2];
        }
    }

    public int sumRange(int left, int right) {
        return queryTree(0, 0, n - 1, left, right);
    }

    private int queryTree(int node, int start, int end, int l, int r) {
        if (r < start || end < l) {
            return 0;
        }
        if (l <= start && end <= r) {
            return tree[node];
        }
        int mid = (start + end) / 2;
        return queryTree(2 * node + 1, start, mid, l, r) + queryTree(2 * node + 2, mid + 1, end, l, r);
    }
}

public class Solution {
    public static int maxProfit(int[] prices) {
        int buy = Integer.MIN_VALUE;
        int sell = 0;
        int cooldown = 0;
        for (int i = 0; i < prices.length; i++) {
            int price = prices[i];
            int newBuy = Math.max(buy, cooldown - price);
            int newSell = Math.max(sell, buy + price);
            int newCooldown = Math.max(cooldown, sell);
            buy = newBuy;
            sell = newSell;
            cooldown = newCooldown;
        }
        return sell;
    }
}

