class Solution {
    public static int nthSuperUglyNumber(int n, int[] primes) {
        long[] uglyNumbers = new long[n];
        uglyNumbers[0] = 1L;
        int[] indices = new int[primes.length];
        int size = 1;
        while (size < n) {
            long nextUgly = Long.MAX_VALUE;
            for (int i = 0; i < primes.length; i++) {
                long candidate = uglyNumbers[indices[i]] * (long) primes[i];
                if (candidate < nextUgly) {
                    nextUgly = candidate;
                }
            }
            uglyNumbers[size++] = nextUgly;
            for (int i = 0; i < primes.length; i++) {
                if (uglyNumbers[indices[i]] * (long) primes[i] == nextUgly) {
                    indices[i]++;
                }
            }
        }
        return (int) uglyNumbers[n - 1];
    }
}

