        int mid = (n + 1) / 2;
        int[] small = Arrays.copyOfRange(sorted, 0, mid);
        int[] large = Arrays.copyOfRange(sorted, mid, n);
        for (int i = 0; i < mid; i++) nums[2 * i] = small[mid - 1 - i];
        for (int i = 0; i < large.length; i++) nums[2 * i + 1] = large[large.length - 1 - i];
    }
}

