class Solution {
    public static long countRangeSum(int[] nums, int lower, int upper) {
        int n = nums.length;
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }
        return sortAndCount(prefix, 0, n + 1, lower, upper);
    }

    private static long sortAndCount(long[] sums, int left, int right, int lower, int upper) {
        if (right - left <= 1) {
            return 0;
        }
        int mid = (left + right) >>> 1;
        long count = sortAndCount(sums, left, mid, lower, upper) + sortAndCount(sums, mid, right, lower, upper);
        int m = mid, n = mid;
        for (int i = left; i < mid; i++) {
            while (m < right && sums[m] - sums[i] < lower) {
                m++;
            }
            while (n < right && sums[n] - sums[i] <= upper) {
                n++;
            }
            count += n - m;
        }
        long[] temp = new long[right - left];
        int i = left, j = mid, k = 0;
        while (i < mid && j < right) {
            if (sums[i] <= sums[j]) {
                temp[k++] = sums[i++];
            } else {
                temp[k++] = sums[j++];
            }
        }
        while (i < mid) {
            temp[k++] = sums[i++];
        }
        while (j < right) {
            temp[k++] = sums[j++];
        }
        System.arraycopy(temp, 0, sums, left, temp.length);
        return count;
    }
}

