class Solution {
    public static int longestIncreasingPath(int[][] matrix) {
        if (matrix.length == 0) return 0;
        int rows = matrix.length;
        int cols = matrix[0].length;
        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
        int[][] memo = new int[rows][cols];
        int maxLength = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                maxLength = Math.max(maxLength, dfs(matrix, memo, directions, i, j));
            }
        }
        return maxLength;
    }

    private static int dfs(int[][] matrix, int[][] memo, int[][] directions, int row, int col) {
        if (memo[row][col] != 0) return memo[row][col];
        int longest = 1;
        for (int[] dir : directions) {
            int nr = row + dir[0];
            int nc = col + dir[1];
            if (nr >= 0 && nr < matrix.length && nc >= 0 && nc < matrix[0].length && matrix[nr][nc] > matrix[row][col]) {
                longest = Math.max(longest, 1 + dfs(matrix, memo, directions, nr, nc));
            }
        }
        memo[row][col] = longest;
        return longest;
    }
}

