class Solution {
    public static boolean isSelfCrossing(int[] distance) {
        for (int i = 3; i < distance.length; i++) {
            if (distance[i] >= distance[i - 2] && distance[i - 1] <= distance[i - 3]) {
                return true;
            }
            if (i >= 4) {
                if (distance[i - 1] == distance[i - 3] && distance[i] + distance[i - 4] >= distance[i - 2]) {
                    return true;
                }
            }
            if (i >= 5) {
                if (distance[i - 2] >= distance[i - 4]
                        && distance[i] >= distance[i - 2] - distance[i - 4]
                        && distance[i - 1] >= distance[i - 3] - distance[i - 5]
                        && distance[i - 1] <= distance[i - 3]
                        && distance[i - 3] > distance[i - 5]) {
                    return true;
                }
            }
        }
        return false;
    }
}

public class Solution {
    public static int maxCoins(int[] nums) {
        int n = nums.length + 2;
        int[] extended = new int[n];
        extended[0] = 1;
        extended[n - 1] = 1;
        System.arraycopy(nums, 0, extended, 1, nums.length);
        int[][] dp = new int[n][n];
        for (int length = 1; length < n - 1; length++) {
            for (int left = 0; left < n - length - 1; left++) {
                int right = left + length + 1;
                for (int i = left + 1; i < right; i++) {
                    int val = extended[left] * extended[i] * extended[right] + dp[left][i] + dp[i][right];
                    if (val > dp[left][right]) {
                        dp[left][right] = val;
                    }
                }
            }
        }
        return dp[0][n - 1];
    }
}

