class Solution {
    public static List<List<Integer>> palindromePairs(String[] words) {
        Map<String,Integer> idx = new HashMap<>();
        for (int i = 0; i < words.length; i++) idx.put(words[i], i);
        List<List<Integer>> result = new ArrayList<>();
        for (int i = 0; i < words.length; i++) {
            String w = words[i];
            int n = w.length();
            for (int cut = 0; cut <= n; cut++) {
                if (isPal(w, cut, n-1)) {
                    String leftRev = new StringBuilder(w.substring(0, cut)).reverse().toString();
                    if (idx.containsKey(leftRev) && idx.get(leftRev) != i) result.add(Arrays.asList(i, idx.get(leftRev)));
                }
                if (cut > 0 && isPal(w, 0, cut-1)) {
                    String rightRev = new StringBuilder(w.substring(cut)).reverse().toString();
                    if (idx.containsKey(rightRev) && idx.get(rightRev) != i) result.add(Arrays.asList(idx.get(rightRev), i));
                }
            }
        }
        return result;
    }
    private static boolean isPal(String w, int l, int r) {
        while (l < r) { if (w.charAt(l) != w.charAt(r)) return false; l++; r--; }
        return true;
    }
}

