public class Solution {
    private final Map<Integer, Set<Integer>> userFollowings = new HashMap<>();
    private final Map<Integer, List<Tweet>> tweets = new HashMap<>();
    private int time = 0;

    private static class Tweet {
        int id;
        int timestamp;
        Tweet(int id, int timestamp) {
            this.id = id;
            this.timestamp = timestamp;
        }
    }

    public void postTweet(int userId, int tweetId) {
        tweets.computeIfAbsent(userId, k -> new ArrayList<>()).add(new Tweet(tweetId, time++));
    }

    public List<Integer> getNewsFeed(int userId) {
        Set<Integer> users = new HashSet<>(userFollowings.getOrDefault(userId, Collections.emptySet()));
        users.add(userId);
        PriorityQueue<Tweet> heap = new PriorityQueue<>((a, b) -> b.timestamp - a.timestamp);
        for (int u : users) {
            List<Tweet> list = tweets.get(u);
            if (list != null) {
                for (int i = list.size() - 1; i >= Math.max(0, list.size() - 10); i--) {
                    heap.offer(list.get(i));
                }
            }
        }
        List<Integer> result = new ArrayList<>();
        int count = 0;
        while (!heap.isEmpty() && count < 10) {
            result.add(heap.poll().id);
            count++;
        }
        return result;
    }

    public void follow(int followerId, int followeeId) {
        userFollowings.computeIfAbsent(followerId, k -> new HashSet<>()).add(followeeId);
    }

    public void unfollow(int followerId, int followeeId) {
        if (followerId == followeeId) return;
        Set<Integer> set = userFollowings.get(followerId);
        if (set != null) set.remove(followeeId);
    }
}

