class Solution {
    public static boolean isPerfectSquare(int num) {
        int low = 1, high = num;
        while (low <= high) {
            int mid = (low + high) / 2;
            long square = (long) mid * mid;
            if (square == num) return true;
            else if (square > num) high = mid - 1;
            else low = mid + 1;
        }
        return false;
    }
}

