class Solution {
    public static int superPow(int a, int[] b) {
        int result = 1;
        for (int i = 0; i < b.length; i++) {
            result = (int)(((long)powMod(result, 10, 1337) * powMod(a, b[i], 1337)) % 1337);
        }
        return result;
    }

    private static int powMod(int base, int exp, int mod) {
        long res = 1;
        long b = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * b) % mod;
            }
            b = (b * b) % mod;
            exp >>= 1;
        }
        return (int) res;
    }
}

