class Solution {
    public static List<List<Integer>> kSmallestPairs(int[] nums1, int[] nums2, int k) {
        if (nums1.length == 0 || nums2.length == 0) {
            return new ArrayList<>();
        }
        List<int[]> minHeap = new ArrayList<>();
        for (int i = 0; i < nums1.length; i++) {
            minHeap.add(new int[]{nums1[i], nums2[0], i, 0});
        }
        List<List<Integer>> result = new ArrayList<>();
        while (!minHeap.isEmpty() && result.size() < k) {
            Collections.sort(minHeap, (a, b) -> Integer.compare(a[0] + a[1], b[0] + b[1]));
            int[] cur = minHeap.remove(0);
            int u = cur[0];
            int v = cur[1];
            int i = cur[2];
            int j = cur[3];
            result.add(Arrays.asList(u, v));
            if (j + 1 < nums2.length) {
                minHeap.add(new int[]{nums1[i], nums2[j + 1], i, j + 1});
            }
        }
        return result;
    }
}

class Solution {
    static int PICK;
    public static int guessNumber(int n) {
        int left = 1, right = n;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            int result = guess(mid);
            if (result == 0) {
                return mid;
            } else if (result == -1) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return -1;
    }
    private static int guess(int num) {
        if (num == PICK) return 0;
        return num > PICK ? -1 : 1;
    }
}

class Solution {
    public static int getMoneyAmount(int n) {
        int[][] dp = new int[n + 1][n + 1];
        for (int length = 2; length <= n; length++) {
            for (int i = 1; i <= n - length + 1; i++) {
                int j = i + length - 1;
                dp[i][j] = Integer.MAX_VALUE;
                for (int k = i; k <= j; k++) {
                    int left = (k - 1 >= i) ? dp[i][k - 1] : 0;
                    int right = (k + 1 <= j) ? dp[k + 1][j] : 0;
                    int cost = k + Math.max(left, right);
                    if (cost < dp[i][j]) {
                        dp[i][j] = cost;
                    }
                }
            }
        }
        return dp[1][n];
    }
}

public class Solution {
    public static int wiggleMaxLength(int[] nums) {
        int up = 1, down = 1;
        for (int i = 1; i < nums.length; i++) {
            if (nums[i] > nums[i - 1]) up = down + 1;
            else if (nums[i] < nums[i - 1]) down = up + 1;
        }
        return Math.max(up, down);
    }
}

public class Solution {
    public static int combinationSum4(int[] nums, int target) {
        int[] dp = new int[target + 1];
        dp[0] = 1;
        for (int i = 1; i <= target; i++) {
            for (int num : nums) {
                if (i - num >= 0) {
                    dp[i] += dp[i - num];
                }
            }
        }
        return dp[target];
    }
}

