class Solution {
    public static int kthSmallest(int[][] matrix, int k) {
        List<int[]> minHeap = new ArrayList<>();
        for (int i = 0; i < matrix.length; i++) {
            minHeap.add(new int[]{matrix[i][0], i, 0});
        }
        minHeap.sort((a, b) -> Integer.compare(a[0], b[0]));
        int count = 0;
        while (count < k) {
            int[] cur = minHeap.remove(0);
            count++;
            if (count == k) {
                return cur[0];
            }
            int row = cur[1];
            int col = cur[2];
            if (col + 1 < matrix[row].length) {
                minHeap.add(new int[]{matrix[row][col + 1], row, col + 1});
                minHeap.sort((a, b) -> Integer.compare(a[0], b[0]));
            }
        }
        return -1;
    }
}

