public class Solution {
    public static class RandomizedCollection {
        private List<Integer> nums;
        private Map<Integer, Set<Integer>> idxMap;
        private Random rand;

        public RandomizedCollection() {
            nums = new ArrayList<>();
            idxMap = new HashMap<>();
            rand = new Random();
        }

        public boolean insert(int val) {
            boolean contain = idxMap.containsKey(val);
            if (!contain) {
                idxMap.put(val, new HashSet<>());
            }
            idxMap.get(val).add(nums.size());
            nums.add(val);
            return !contain;
        }

        public boolean remove(int val) {
            Set<Integer> set = idxMap.get(val);
            if (set == null || set.isEmpty()) {
                return false;
            }
            int removeIdx = set.iterator().next();
            set.remove(removeIdx);
            int lastIdx = nums.size() - 1;
            int lastVal = nums.get(lastIdx);
            nums.set(removeIdx, lastVal);
            Set<Integer> lastSet = idxMap.get(lastVal);
            lastSet.add(removeIdx);
            lastSet.remove(lastIdx);
            nums.remove(lastIdx);
            if (set.isEmpty()) {
                idxMap.remove(val);
            }
            return true;
        }

        public int getRandom() {
            return nums.get(rand.nextInt(nums.size()));
        }
    }
}

