class Solution {
    public static Object deserialize(String s) {
        int[] pos = {0};
        return parse(s, pos);
    }

    private static Object parse(String s, int[] pos) {
        if (s.charAt(pos[0]) == '[') {
            pos[0]++;
            List<Object> list = new ArrayList<>();
            while (s.charAt(pos[0]) != ']') {
                list.add(parse(s, pos));
                if (s.charAt(pos[0]) == ',') pos[0]++;
            }
            pos[0]++;
            return list;
        } else {
            int start = pos[0];
            if (s.charAt(pos[0]) == '-') pos[0]++;
            while (pos[0] < s.length() && Character.isDigit(s.charAt(pos[0]))) pos[0]++;
            return Integer.parseInt(s.substring(start, pos[0]));
        }
    }
}

