class Solution {
    public static int lengthLongestPath(String input) {
        String[] paths = input.split("\n");
        List<String> stack = new ArrayList<>();
        int maxLen = 0;
        for (String path : paths) {
            int depth = path.lastIndexOf('\t') + 1;
            String name = path.replace("\t", "");
            if (name.contains(".")) {
                int sum = 0;
                for (int i = 0; i < depth && i < stack.size(); i++) {
                    sum += stack.get(i).length() + 1;
                }
                int absPathLen = name.length() + sum;
                maxLen = Math.max(maxLen, absPathLen);
            } else {
                while (stack.size() > depth) {
                    stack.remove(stack.size() - 1);
                }
                stack.add(name);
            }
        }
        return maxLen;
    }
}

