import java.util.*;

class Solution {
    public static boolean isRectangleCover(int[][] rectangles) {
        long area = 0;
        int x1 = Integer.MAX_VALUE, y1 = Integer.MAX_VALUE, x2 = Integer.MIN_VALUE, y2 = Integer.MIN_VALUE;
        Set<String> corners = new HashSet<>();
        for (int[] rect : rectangles) {
            int x = rect[0], y = rect[1], a = rect[2], b = rect[3];
            area += (long) (a - x) * (b - y);
            x1 = Math.min(x1, x);
            y1 = Math.min(y1, y);
            x2 = Math.max(x2, a);
            y2 = Math.max(y2, b);
            int[][] points = {{x, y}, {x, b}, {a, y}, {a, b}};
            for (int[] p : points) {
                String key = p[0] + "," + p[1];
                if (corners.contains(key)) {
                    corners.remove(key);
                } else {
                    corners.add(key);
                }
            }
        }
        if (area != (long) (x2 - x1) * (y2 - y1)) return false;
        int[][] expected = {{x1, y1}, {x1, y2}, {x2, y1}, {x2, y2}};
        for (int[] c : expected) {
            String key = c[0] + "," + c[1];
            if (!corners.contains(key)) return false;
        }
        return corners.size() == 4;
    }
}

