class Solution {
    public static int rotateFunction(int[] nums) {
        int n = nums.length;
        long total = 0;
        long f = 0;
        for (int i = 0; i < n; i++) {
            total += nums[i];
            f += (long) i * nums[i];
        }
        long max = f;
        for (int k = 1; k < n; k++) {
            f = f + total - (long) n * nums[n - k];
            if (f > max) {
                max = f;
            }
        }
        return (int) max;
    }
}

import java.util.Stack;

class Solution {
    public static String decodeString(String s) {
        Stack<Object> stack = new Stack<>();
        int curNum = 0;
        StringBuilder curString = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) {
                curNum = curNum * 10 + (c - '0');
            } else if (c >= 'a' && c <= 'z') {
                curString.append(c);
            } else if (c == '[') {
                stack.push(curString.toString());
                stack.push(curNum);
                curString.setLength(0);
                curNum = 0;
            } else if (c == ']') {
                int num = (int) stack.pop();
                String prevString = (String) stack.pop();
                curString = new StringBuilder(prevString + curString.toString().repeat(num));
            }
        }
        return curString.toString();
    }
}

import java.util.*;

class Solution {
    public static double[] calcEquation(List<List<String>> equations, double[] values, List<List<String>> queries) {
        Map<String, Map<String, Double>> graph = new HashMap<>();
        for (int i = 0; i < equations.size(); i++) {
            String dividend = equations.get(i).get(0);
            String divisor = equations.get(i).get(1);
            double value = values[i];
            graph.computeIfAbsent(dividend, k -> new HashMap<>()).put(divisor, value);
            graph.computeIfAbsent(divisor, k -> new HashMap<>()).put(dividend, 1.0 / value);
        }
        double[] result = new double[queries.size()];
        for (int i = 0; i < queries.size(); i++) {
            String dividend = queries.get(i).get(0);
            String divisor = queries.get(i).get(1);
            result[i] = dfs(dividend, divisor, graph, new HashSet<>());
        }
        return result;
    }

    private static double dfs(String start, String end, Map<String, Map<String, Double>> graph, Set<String> visited) {
        if (!graph.containsKey(start)) return -1.0;
        if (start.equals(end)) return 1.0;
        visited.add(start);
        double result = -1.0;
        for (Map.Entry<String, Double> entry : graph.get(start).entrySet()) {
            String neighbor = entry.getKey();
            double weight = entry.getValue();
            if (!visited.contains(neighbor)) {
                double temp = dfs(neighbor, end, graph, visited);
                if (temp != -1.0) {
                    result = weight * temp;
                    break;
                }
            }
        }
        visited.remove(start);
        return result;
    }
}

