class Solution {
    public static int findNthDigit(int n) {
        long length = 1;
        long count = 9;
        long start = 1;
        long nn = n;
        while (nn > length * count) {
            nn -= length * count;
            length += 1;
            count *= 10;
            start *= 10;
        }
        start += (nn - 1) / length;
        String str = Long.toString(start);
        return str.charAt((int) ((nn - 1) % length)) - '0';
    }
}

