class Solution {
    public static boolean canCross(int[] stones) {
        int n = stones.length;
        Set<Integer> stoneSet = new HashSet<>();
        for (int stone : stones) {
            stoneSet.add(stone);
        }
        Map<String, Boolean> memo = new HashMap<>();
        return dfs(stones[0], 1, stones, stoneSet, memo);
    }

    private static boolean dfs(int stone, int k, int[] stones, Set<Integer> stoneSet, Map<String, Boolean> memo) {
        String key = stone + "," + k;
        if (memo.containsKey(key)) {
            return memo.get(key);
        }
        if (stone == stones[stones.length - 1]) {
            return true;
        }
        for (int jump = k - 1; jump <= k + 1; jump++) {
            if (jump <= 0) continue;
            int next = stone + jump;
            if (stoneSet.contains(next)) {
                if (dfs(next, jump, stones, stoneSet, memo)) {
                    memo.put(key, true);
                    return true;
                }
            }
        }
        memo.put(key, false);
        return false;
    }
}

