public class Solution {
    public static String toHex(long num) {
        if (num < 0) num += (1L << 32);
        String result = "";
        while (num > 0) {
            long remainder = num % 16;
            if (remainder < 10) result = remainder + result;
            else result = (char)('a' + (int)remainder - 10) + result;
            num = num / 16;
        }
        if (result.isEmpty()) return "0";
        return result;
    }
}

