class Solution {
    public static int trapRainWater(int[][] heightMap) {
        int rows = heightMap.length;
        int cols = heightMap[0].length;
        List<int[]> minHeap = new ArrayList<>();
        boolean[][] visited = new boolean[rows][cols];
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        int water = 0;

        for (int i = 0; i < rows; i++) {
            minHeap.add(new int[]{heightMap[i][0], i, 0});
            minHeap.add(new int[]{heightMap[i][cols - 1], i, cols - 1});
            visited[i][0] = true;
            visited[i][cols - 1] = true;
        }
        for (int j = 1; j < cols - 1; j++) {
            minHeap.add(new int[]{heightMap[0][j], 0, j});
            minHeap.add(new int[]{heightMap[rows - 1][j], rows - 1, j});
            visited[0][j] = true;
            visited[rows - 1][j] = true;
        }

        minHeap.sort((a, b) -> Integer.compare(a[0], b[0]));

        while (!minHeap.isEmpty()) {
            int[] cell = minHeap.remove(0);
            int height = cell[0];
            int x = cell[1];
            int y = cell[2];

            for (int[] dir : directions) {
                int nx = x + dir[0];
                int ny = y + dir[1];
                if (nx >= 0 && nx < rows && ny >= 0 && ny < cols && !visited[nx][ny]) {
                    water += Math.max(0, height - heightMap[nx][ny]);
                    minHeap.add(new int[]{Math.max(height, heightMap[nx][ny]), nx, ny});
                    visited[nx][ny] = true;
                }
            }

            minHeap.sort((a, b) -> Integer.compare(a[0], b[0]));
        }

        return water;
    }
}

