class Solution {
    public static int thirdMax(int[] nums) {
        Set<Integer> set = new HashSet<>();
        for (int num : nums) {
            set.add(num);
        }
        List<Integer> uniqueNums = new ArrayList<>(set);
        if (uniqueNums.size() < 3) {
            int max = Integer.MIN_VALUE;
            for (int v : uniqueNums) {
                if (v > max) {
                    max = v;
                }
            }
            return max;
        } else {
            int max1 = Collections.max(uniqueNums);
            uniqueNums.remove(Integer.valueOf(max1));
