        }
    }
}

public class Solution {
    public static int numberOfArithmeticSlices(int[] nums) {
        long count = 0;
        int currentLength = 0;
        Integer lastDifference = null;
        for (int i = 0; i < nums.length - 1; i++) {
            int difference = nums[i + 1] - nums[i];
            if (lastDifference == null || lastDifference == difference) {
                currentLength++;
                lastDifference = difference;
            } else {
                count += (long) (currentLength - 1) * currentLength / 2;
                currentLength = 1;
                lastDifference = difference;
            }
        }
        count += (long) (currentLength - 1) * currentLength / 2;
        return (int) count;
    }
}

