class Solution {
    public static int splitArray(int[] nums, int k) {
        long left = 0;
        long right = 0;
        for (int num : nums) {
            if (num > left) left = num;
            right += num;
        }
        while (left < right) {
            long mid = (left + right) / 2;
            int count = 1;
            long sum = 0;
            for (int num : nums) {
                if (sum + num > mid) {
                    count++;
                    sum = num;
                } else {
                    sum += num;
                }
            }
            if (count <= k) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return (int) left;
    }
}

