class Solution {
    public static int strongPasswordChecker(String password) {
        int n = password.length();
        int missingTypes = 3;
        for (char c : password.toCharArray()) {
            if (Character.isLowerCase(c)) missingTypes--;
            else if (Character.isUpperCase(c)) missingTypes--;
            else if (Character.isDigit(c)) missingTypes--;
        }
        List<Integer> repeats = new ArrayList<>();
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && password.charAt(j) == password.charAt(i)) j++;
            int len = j - i;
            if (len >= 3) repeats.add(len);
            i = j;
        }
        if (n < 6) {
            return Math.max(missingTypes, 6 - n);
        }
        int replace = 0;
        for (int len : repeats) replace += len / 3;
        if (n <= 20) {
            return Math.max(missingTypes, replace);
        }
        int deletions = n - 20;
        int[] cnt = new int[3];
        for (int len : repeats) cnt[len % 3]++;
        int left = deletions;
        int use = Math.min(cnt[0], left);
        replace -= use;
        left -= use;
        use = Math.min(cnt[1] * 2, left);
        replace -= use / 2;
        left -= use;
        use = left;
        replace -= use / 3;
        left = 0;
        if (replace < 0) replace = 0;
        return deletions + Math.max(missingTypes, replace);
    }
}

