class Solution {
    public static List<List<Integer>> pacificAtlantic(int[][] heights) {
        int rows = heights.length;
        if (rows == 0) return new ArrayList<>();
        int cols = heights[0].length;
        Set<String> pacific = new HashSet<>();
        Set<String> atlantic = new HashSet<>();

        for (int i = 0; i < rows; i++) dfs(i, 0, heights, pacific, rows, cols);
        for (int j = 0; j < cols; j++) dfs(0, j, heights, pacific, rows, cols);
        for (int i = 0; i < rows; i++) dfs(i, cols - 1, heights, atlantic, rows, cols);
        for (int j = 0; j < cols; j++) dfs(rows - 1, j, heights, atlantic, rows, cols);

        List<List<Integer>> result = new ArrayList<>();
        for (String cell : pacific) {
            if (atlantic.contains(cell)) {
                String[] parts = cell.split(",");
                int row = Integer.parseInt(parts[0]);
                int col = Integer.parseInt(parts[1]);
                List<Integer> coord = new ArrayList<>(2);
                coord.add(row);
                coord.add(col);
                result.add(coord);
            }
        }
        result.sort(Comparator.comparingInt((List<Integer> a) -> a.get(0))
                .thenComparingInt(a -> a.get(1)));
        return result;
    }

    private static void dfs(int row, int col, int[][] heights, Set<String> ocean, int rows, int cols) {
        if (row < 0 || row >= rows || col < 0 || col >= cols) return;
        String key = row + "," + col;
        if (ocean.contains(key)) return;
        ocean.add(key);
        int currentHeight = heights[row][col];
        if (row > 0 && heights[row - 1][col] >= currentHeight) dfs(row - 1, col, heights, ocean, rows, cols);
        if (row < rows - 1 && heights[row + 1][col] >= currentHeight) dfs(row + 1, col, heights, ocean, rows, cols);
        if (col > 0 && heights[row][col - 1] >= currentHeight) dfs(row, col - 1, heights, ocean, rows, cols);
        if (col < cols - 1 && heights[row][col + 1] >= currentHeight) dfs(row, col + 1, heights, ocean, rows, cols);
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    private static class Node {
        Map<Integer, Node> child = new HashMap<>();
    }

    public static int findMaximumXOR(int[] nums) {
        Node trie = new Node();
        for (int num : nums) {
            Node node = trie;
            for (int i = 31; i >= 0; i--) {
                int bit = (num >> i) & 1;
                node.child.computeIfAbsent(bit, k -> new Node());
                node = node.child.get(bit);
            }
        }
        int maxResult = 0;
        for (int num : nums) {
            Node node = trie;
            int currResult = 0;
            for (int i = 31; i >= 0; i--) {
                int bit = (num >> i) & 1;
                int opposite = 1 - bit;
                if (node.child.containsKey(opposite)) {
                    currResult |= (1 << i);
                    node = node.child.get(opposite);
                } else {
                    node = node.child.get(bit);
                }
            }
            maxResult = Math.max(maxResult, currResult);
        }
        return maxResult;
    }
}

