class Solution {
    public static String originalDigits(String s) {
        int[] freq = new int[26];
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            freq[c - 'a']++;
        }
        int zeroCount = freq['z' - 'a'];
        int twoCount = freq['w' - 'a'];
        int fourCount = freq['u' - 'a'];
        int sixCount = freq['x' - 'a'];
        int eightCount = freq['g' - 'a'];
        int threeCount = freq['h' - 'a'] - eightCount;
        if (threeCount < 0) threeCount = 0;
        int fiveCount = freq['f' - 'a'] - fourCount;
        if (fiveCount < 0) fiveCount = 0;
        int sevenCount = freq['s' - 'a'] - sixCount;
        if (sevenCount < 0) sevenCount = 0;
        int oneCount = freq['n' - 'a'] - (sevenCount * 2);
        if (oneCount < 0) oneCount = 0;
        int nineCount = freq['i' - 'a'] - fiveCount - sixCount - eightCount;
        if (nineCount < 0) nineCount = 0;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < zeroCount; i++) sb.append('0');
        for (int i = 0; i < oneCount; i++) sb.append('1');
        for (int i = 0; i < twoCount; i++) sb.append('2');
        for (int i = 0; i < threeCount; i++) sb.append('3');
        for (int i = 0; i < fourCount; i++) sb.append('4');
        for (int i = 0; i < fiveCount; i++) sb.append('5');
        for (int i = 0; i < sixCount; i++) sb.append('6');
        for (int i = 0; i < sevenCount; i++) sb.append('7');
        for (int i = 0; i < eightCount; i++) sb.append('8');
        for (int i = 0; i < nineCount; i++) sb.append('9');
        return sb.toString();
    }
}

