class Solution {
    public static List<Object> construct(int[][] grid) {
        return constructQuadTree(grid, 0, 0, grid.length);
    }

    private static List<Object> constructQuadTree(int[][] grid, int x, int y, int n) {
        boolean isLeaf = true;
        int val = grid[x][y];
        for (int i = x; i < x + n; i++) {
            for (int j = y; j < y + n; j++) {
                if (grid[i][j] != val) {
                    isLeaf = false;
                    break;
                }
            }
            if (!isLeaf) break;
        }
        if (isLeaf) {
            return new ArrayList<>(Arrays.asList(1, val));
        } else {
            List<Object> node = new ArrayList<>(Arrays.asList(0, 0));
            node.add(constructQuadTree(grid, x, y, n / 2));
            node.add(constructQuadTree(grid, x, y + n / 2, n / 2));
            node.add(constructQuadTree(grid, x + n / 2, y, n / 2));
            node.add(constructQuadTree(grid, x + n / 2, y + n / 2, n / 2));
            return node;
        }
    }
}

