class ListNode {
    int val;
    ListNode prev;
    ListNode next;
    ListNode child;
    ListNode(int val) { this.val = val; }
}

class Solution {
    public static ListNode flatten(ListNode head) {
        dfs(head);
        return head;
    }
    private static ListNode dfs(ListNode node) {
        ListNode tail = node;
        while (node != null) {
            if (node.child != null) {
                ListNode child = node.child;
                ListNode childTail = dfs(child);
                if (node.next != null) {
                    childTail.next = node.next;
                    node.next.prev = childTail;
                }
                node.next = child;
                child.prev = node;
                tail = childTail;
                node.child = null;
            } else {
                tail = node;
            }
            node = node.next;
        }
        return tail;
    }
}

