class Solution {
    private static class Pair {
        String gene;
        int dist;
        Pair(String gene, int dist) {
            this.gene = gene;
            this.dist = dist;
        }
    }

    public static int minMutation(String startGene, String endGene, String[] bank) {
        Set<String> validGenes = new HashSet<>(Arrays.asList(bank));
        Queue<Pair> queue = new ArrayDeque<>();
        queue.offer(new Pair(startGene, 0));
        Set<String> visited = new HashSet<>();
        visited.add(startGene);
        char[] nucleotides = {'A', 'C', 'G', 'T'};
        while (!queue.isEmpty()) {
            Pair current = queue.poll();
            String currentGene = current.gene;
            int distance = current.dist;
            if (currentGene.equals(endGene)) {
                return distance;
            }
            for (int i = 0; i < 8; i++) {
                for (char nucleotide : nucleotides) {
                    String newGene = currentGene.substring(0, i) + nucleotide + currentGene.substring(i + 1);
                    if (validGenes.contains(newGene) && !visited.contains(newGene)) {
                        queue.offer(new Pair(newGene, distance + 1));
                        visited.add(newGene);
                    }
                }
            }
        }
        return -1;
    }
}

