        public void inc(String key) {
            if (countMap.containsKey(key)) {
                int c = countMap.get(key);
                bucketMap.get(c).remove(key);
                if (bucketMap.get(c).isEmpty() && minCount == c) minCount++;
                countMap.put(key, c + 1);
                bucketMap.computeIfAbsent(c + 1, k -> new LinkedHashSet<>()).add(key);
                maxCount = Math.max(maxCount, c + 1);
            } else {
                countMap.put(key, 1);
                bucketMap.computeIfAbsent(1, k -> new LinkedHashSet<>()).add(key);
                minCount = 1;
                maxCount = Math.max(maxCount, 1);
            }
        }
        public void dec(String key) {
            if (!countMap.containsKey(key)) return;
            int c = countMap.get(key);
            bucketMap.get(c).remove(key);
            if (bucketMap.get(c).isEmpty() && maxCount == c) maxCount--;
            if (c > 1) {
                countMap.put(key, c - 1);
                bucketMap.computeIfAbsent(c - 1, k -> new LinkedHashSet<>()).add(key);
                minCount = Math.min(minCount, c - 1);
            } else {
                countMap.remove(key);
                if (countMap.isEmpty()) {
                    minCount = 1;
                    maxCount = 1;
                } else {
                    int m = Integer.MAX_VALUE;
                    for (Map.Entry<Integer, Set<String>> e : bucketMap.entrySet()) {
                        if (!e.getValue().isEmpty() && e.getKey() < m) m = e.getKey();
                    }
                    minCount = m;
                }
            }
        }
        public String getMaxKey() {
            if (bucketMap.containsKey(maxCount) && !bucketMap.get(maxCount).isEmpty()) return bucketMap.get(maxCount).iterator().next();
            return "";
        }
        public String getMinKey() {
            if (bucketMap.containsKey(minCount) && !bucketMap.get(minCount).isEmpty()) return bucketMap.get(minCount).iterator().next();
            return "";
        }
    }
}

import java.util.Arrays;

class Solution {
    public static int[] findRightInterval(int[][] intervals) {
        int n = intervals.length;
        int[][] indexedIntervals = new int[n][3];
        for (int i = 0; i < n; i++) {
            indexedIntervals[i][0] = intervals[i][0];
            indexedIntervals[i][1] = intervals[i][1];
            indexedIntervals[i][2] = i;
        }
        Arrays.sort(indexedIntervals, (a, b) -> Integer.compare(a[0], b[0]));
        int[] result = new int[n];
        for (int i = 0; i < n; i++) {
            int left = 0, right = n - 1;
            while (left <= right) {
                int mid = (left + right) / 2;
                if (indexedIntervals[mid][0] >= intervals[i][1]) {
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            }
            if (left < n) {
                result[i] = indexedIntervals[left][2];
            } else {
                result[i] = -1;
            }
        }
        return result;
    }
}

