    public static int pathSum(TreeNode root, int targetSum) {
        count = 0;
        traverse(root, targetSum);
        return count;
    }
    private static void dfs(TreeNode node, int currentSum, int targetSum) {
        if (node == null) return;
        currentSum += node.val;
        if (currentSum == targetSum) count++;
        dfs(node.left, currentSum, targetSum);
        dfs(node.right, currentSum, targetSum);
    }
    private static void traverse(TreeNode node, int targetSum) {
        if (node == null) return;
        dfs(node, 0, targetSum);
        traverse(node.left, targetSum);
        traverse(node.right, targetSum);
    }
}

