class Solution {
    public static List<Integer> findAnagrams(String s, String p) {
        Map<Character, Integer> pCount = new HashMap<>();
        for (int i = 0; i < p.length(); i++) {
            char c = p.charAt(i);
            pCount.put(c, pCount.getOrDefault(c, 0) + 1);
        }
        List<Integer> result = new ArrayList<>();
        Map<Character, Integer> windowCount = new HashMap<>();
        int requiredChars = pCount.size();
        int formedChars = 0;
        int left = 0;
        for (int right = 0; right < s.length(); right++) {
            char character = s.charAt(right);
            if (pCount.containsKey(character)) {
                windowCount.put(character, windowCount.getOrDefault(character, 0) + 1);
                if (windowCount.get(character).intValue() == pCount.get(character).intValue()) {
                    formedChars++;
                }
            }
            while (right - left + 1 > p.length()) {
                char leftChar = s.charAt(left);
                if (pCount.containsKey(leftChar)) {
                    int count = windowCount.getOrDefault(leftChar, 0) - 1;
                    windowCount.put(leftChar, count);
                    if (count < pCount.get(leftChar)) {
                        formedChars--;
                    }
                }
                left++;
            }
            if (right - left + 1 == p.length() && formedChars == requiredChars) {
                result.add(left);
            }
        }
        return result;
    }
}

