class Solution {
    public static int findKthNumber(int n, int k) {
        long cur = 1;
        long kk = k - 1;
        while (kk > 0) {
            long step = 0;
            long first = cur;
            long last = cur + 1;
            while (first <= n) {
                step += Math.min((long) n + 1, last) - first;
                first *= 10;
                last *= 10;
            }
            if (kk >= step) {
                kk -= step;
                cur++;
            } else {
                kk--;
                cur *= 10;
            }
        }
        return (int) cur;
    }
}

