class Solution {
    public static int arrangeCoins(int n) {
        long left = 1;
        long right = n;
        while (left <= right) {
            long mid = left + (right - left) / 2;
            long totalCoins = mid * (mid + 1) / 2;
            if (totalCoins <= n) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return (int) right;
    }
}

public class Solution {
    public static int compress(char[] chars) {
        int writeIndex = 0;
        int count = 1;
        for (int readIndex = 1; readIndex <= chars.length; readIndex++) {
            if (readIndex == chars.length || chars[readIndex] != chars[readIndex - 1]) {
                chars[writeIndex++] = chars[readIndex - 1];
                if (count > 1) {
                    String countStr = Integer.toString(count);
                    for (int i = 0; i < countStr.length(); i++) {
                        chars[writeIndex++] = countStr.charAt(i);
                    }
                }
                count = 1;
            } else {
                count++;
            }
        }
        return writeIndex;
    }
}

