public class Solution {
    public static boolean circularArrayLoop(int[] nums) {
        for (int i = 0; i < nums.length; i++) {
            int slow = i, fast = i;
            boolean direction = nums[i] > 0;
            while (true) {
                slow = findNextIndex(nums, slow, direction);
                if (slow == -1) break;
                fast = findNextIndex(nums, fast, direction);
                if (fast == -1) break;
                fast = findNextIndex(nums, fast, direction);
                if (fast == -1) break;
                if (slow == fast) {
                    if (hasCycle(nums, slow, direction)) return true;
                    else break;
                }
            }
        }
        return false;
    }

    private static int findNextIndex(int[] nums, int current, boolean direction) {
        if ((nums[current] > 0) != direction) return -1;
        int n = nums.length;
        int next = ((current + nums[current]) % n + n) % n;
        if (next == current) return -1;
        return next;
    }

    private static boolean hasCycle(int[] nums, int start, boolean direction) {
        int count = 0;
        int idx = start;
        while (true) {
            idx = findNextIndex(nums, idx, direction);
            if (idx == -1) return false;
            count++;
            if (idx == start) break;
        }
        return count > 1;
    }
}

