import java.util.Map;

public class Solution {
    private class Node {
        int key;
        int value;
        int freq;
        Node prev;
        Node next;
        Node(int k, int v) {
            key = k;
            value = v;
            freq = 1;
        }
    }

    private class DoublyLinkedList {
        Node head;
        Node tail;
        DoublyLinkedList() {
            head = new Node(0, 0);
            tail = new Node(0, 0);
            head.next = tail;
            tail.prev = head;
        }
        void addFirst(Node node) {
            node.next = head.next;
            node.prev = head;
            head.next.prev = node;
            head.next = node;
        }
        void remove(Node node) {
            node.prev.next = node.next;
            node.next.prev = node.prev;
        }
        boolean isEmpty() {
            return head.next == tail;
        }
        Node removeLast() {
            if (isEmpty()) return null;
            Node node = tail.prev;
            remove(node);
            return node;
        }
    }

    public class LFUCache {
        private final int capacity;
        private int minFreq;
        private final Map<Integer, Node> keyMap;
        private final Map<Integer, DoublyLinkedList> freqMap;

        public LFUCache(int capacity) {
            this.capacity = capacity;
            this.minFreq = 1;
            this.keyMap = new HashMap<>();
            this.freqMap = new HashMap<>();
        }

        public int get(int key) {
            Node node = keyMap.get(key);
            if (node == null) return -1;
            update(node);
            return node.value;
        }

        public void put(int key, int value) {
            if (capacity == 0) return;
            if (keyMap.containsKey(key)) {
                Node node = keyMap.get(key);
                node.value = value;
                update(node);
                return;
            }
            if (keyMap.size() == capacity) {
                DoublyLinkedList list = freqMap.get(minFreq);
                Node evict = list.removeLast();
                if (evict != null) {
                    keyMap.remove(evict.key);
                }
            }
            Node newNode = new Node(key, value);
            keyMap.put(key, newNode);
            freqMap.computeIfAbsent(1, k -> new DoublyLinkedList()).addFirst(newNode);
            minFreq = 1;
        }

        private void update(Node node) {
            int freq = node.freq;
            DoublyLinkedList list = freqMap.get(freq);
            list.remove(node);
            if (freq == minFreq && list.isEmpty()) {
                minFreq++;
            }
            node.freq++;
            freqMap.computeIfAbsent(node.freq, k -> new DoublyLinkedList()).addFirst(node);
        }
    }
}

