class Solution {
    public static int findSubstringInWraproundString(String s) {
        Set<String> uniqueSubstrings = new HashSet<>();
        String currentSubstring = "";
        for (int i = 0; i < s.length(); i++) {
            if (i == 0 || (s.charAt(i) - s.charAt(i - 1) == 1) || (s.charAt(i) - s.charAt(i - 1) == -25)) {
                currentSubstring += s.charAt(i);
            } else {
                for (int j = 0; j < currentSubstring.length(); j++) {
                    for (int k = j + 1; k <= currentSubstring.length(); k++) {
                        uniqueSubstrings.add(currentSubstring.substring(j, k));
                    }
                }
                currentSubstring = String.valueOf(s.charAt(i));
            }
        }
        for (int j = 0; j < currentSubstring.length(); j++) {
            for (int k = j + 1; k <= currentSubstring.length(); k++) {
                uniqueSubstrings.add(currentSubstring.substring(j, k));
            }
        }
        return uniqueSubstrings.size();
    }
}

import java.util.*;

public class Solution {
    public static List<String> findAllConcatenatedWordsInADict(List<String> words) {
        Set<String> wordSet = new HashSet<>(words);
        List<String> result = new ArrayList<>();
        for (String word : words) {
            if (word.isEmpty()) continue;
            wordSet.remove(word);
            if (canForm(word, wordSet)) {
                result.add(word);
            }
            wordSet.add(word);
        }
        return result;
    }

    private static boolean canForm(String word, Set<String> wordSet) {
        int len = word.length();
        boolean[] dp = new boolean[len + 1];
        dp[0] = true;
        for (int i = 1; i <= len; i++) {
            for (int j = 0; j < i; j++) {
                if (dp[j] && wordSet.contains(word.substring(j, i))) {
                    dp[i] = true;
                    break;
                }
            }
        }
        return dp[len];
    }
}

import java.util.*;

class Solution {
    public static boolean makesquare(int[] matchsticks) {
        int totalLength = 0;
        for (int i = 0; i < matchsticks.length; i++) {
            totalLength += matchsticks[i];
        }
        if (totalLength % 4 != 0) return false;
        int sideLength = totalLength / 4;
        int[] sides = new int[4];
        Integer[] boxed = new Integer[matchsticks.length];
        for (int i = 0; i < matchsticks.length; i++) {
            boxed[i] = matchsticks[i];
        }
        Arrays.sort(boxed, Collections.reverseOrder());
        for (int i = 0; i < matchsticks.length; i++) {
            matchsticks[i] = boxed[i];
        }
        return backtrack(matchsticks, 0, sides, sideLength);
    }

    private static boolean backtrack(int[] matchsticks, int index, int[] sides, int sideLength) {
        if (index == matchsticks.length) {
            return sides[0] == sideLength && sides[1] == sideLength && sides[2] == sideLength && sides[3] == sideLength;
        }
        for (int i = 0; i < 4; i++) {
            if (sides[i] + matchsticks[index] > sideLength) continue;
            sides[i] += matchsticks[index];
            if (backtrack(matchsticks, index + 1, sides, sideLength)) return true;
            sides[i] -= matchsticks[index];
        }
        return false;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static boolean canIWin(int maxChoosableInteger, int desiredTotal) {
        if (desiredTotal <= 0) return true;
        long sum = (long) maxChoosableInteger * (maxChoosableInteger + 1) / 2;
        if (sum < desiredTotal) return false;
        if (sum == desiredTotal && (maxChoosableInteger & 1) == 1) return true;
        Map<Integer, Boolean> memo = new HashMap<>();
        return dp(0, desiredTotal, maxChoosableInteger, memo);
    }

    private static boolean dp(int mask, int remainingTotal, int maxChoosableInteger, Map<Integer, Boolean> memo) {
        if (memo.containsKey(mask)) return memo.get(mask);
        for (int i = 1; i <= maxChoosableInteger; i++) {
            int bitMask = 1 << (i - 1);
            if ((mask & bitMask) == 0) {
                if (i >= remainingTotal) {
                    memo.put(mask, true);
                    return true;
                }
                if (!dp(mask | bitMask, remainingTotal - i, maxChoosableInteger, memo)) {
                    memo.put(mask, true);
                    return true;
                }
            }
        }
        memo.put(mask, false);
        return false;
    }
}

import java.util.*;

class Solution {
    public static int findMaxForm(String[] strs, int m, int n) {
        int[][] dp = new int[m + 1][n + 1];
        for (String str : strs) {
            int zeros = 0, ones = 0;
            for (int k = 0; k < str.length(); k++) {
                char c = str.charAt(k);
                if (c == '0') zeros++;
                else ones++;
            }
            for (int i = m; i >= zeros; i--) {
                for (int j = n; j >= ones; j--) {
                    dp[i][j] = Math.max(dp[i][j], dp[i - zeros][j - ones] + 1);
                }
            }
        }
        return dp[m][n];
    }
}

public class Solution {
    public static int findComplement(int num) {
        int bits = (int)Math.floor(Math.log(num) / Math.log(2)) + 1;
        int mask = (1 << bits) - 1;
        return num ^ mask;
    }
}

