import java.util.*;

class Solution {
    public static int totalHammingDistance(int[] nums) {
        int totalDistance = 0;
        int maxNum = 0;
        for (int num : nums) {
            if (num > maxNum) {
                maxNum = num;
            }
        }
        int maxBits = (maxNum == 0) ? 0 : (32 - Integer.numberOfLeadingZeros(maxNum));
        for (int bit = 0; bit < maxBits; bit++) {
            int ones = 0, zeros = 0;
            for (int num : nums) {
                if (((num >> bit) & 1) == 1) {
                    ones++;
                } else {
                    zeros++;
                }
            }
            totalDistance += ones * zeros;
        }
        return totalDistance;
    }
}

import java.util.*;

class Solution {
    public static List<Double> medianSlidingWindow(int[] nums, int k) {
        List<Integer> minHeap = new ArrayList<>();
        List<Integer> maxHeap = new ArrayList<>();
        List<Double> result = new ArrayList<>();

        for (int i = 0; i < nums.length; i++) {
            if (maxHeap.isEmpty() || nums[i] < -maxHeap.get(0)) {
                maxHeap.add(-nums[i]);
                Collections.sort(maxHeap);
            } else {
                minHeap.add(nums[i]);
                Collections.sort(minHeap);
            }

            if (maxHeap.size() > minHeap.size() + 1) {
                int moved = -maxHeap.remove(0);
                minHeap.add(moved);
                Collections.sort(minHeap);
            } else if (minHeap.size() > maxHeap.size()) {
                int moved = minHeap.remove(0);
                maxHeap.add(-moved);
                Collections.sort(maxHeap);
            }

            if (i >= k - 1) {
                if (k % 2 == 0) {
                    double median = ((-maxHeap.get(0) + minHeap.get(0)) / 2.0);
                    result.add(median);
                } else {
                    double median = -maxHeap.get(0);
                    result.add(median);
                }

                int out = nums[i - k + 1];
                if (out <= -maxHeap.get(0)) {
                    int idx = maxHeap.indexOf(-out);
                    if (idx != -1) {
                        maxHeap.remove(idx);
                        Collections.sort(maxHeap);
                    }
                } else {
                    int idx = minHeap.indexOf(out);
                    if (idx != -1) {
                        minHeap.remove(idx);
                        Collections.sort(minHeap);
                    }
                }

                if (maxHeap.size() > minHeap.size() + 1) {
                    int moved = -maxHeap.remove(0);
                    minHeap.add(moved);
                    Collections.sort(minHeap);
                } else if (minHeap.size() > maxHeap.size()) {
                    int moved = minHeap.remove(0);
                    maxHeap.add(-moved);
                    Collections.sort(maxHeap);
                }
            }
        }

        return result;
    }
}

import java.lang.Math;

class Solution {
    public static int largestPalindromeProduct(int n) {
        int min = (int)Math.pow(10, n - 1);
        int max = (int)Math.pow(10, n) - 1;
        long result = 0;
        for (int i = max; i >= min; i--) {
            for (int j = i; j >= min; j--) {
                long product = (long)i * j;
                if (isPalindrome(product) && product > result) {
                    result = product;
                }
                if (product < result) {
                    break;
                }
            }
        }
        return (int)(result % 1337);
    }

    private static boolean isPalindrome(long num) {
        String s = Long.toString(num);
        int len = s.length();
        for (int i = 0; i < len / 2; i++) {
            if (s.charAt(i) != s.charAt(len - 1 - i)) {
                return false;
            }
        }
        return true;
    }
}

