public class Solution {
    public static int magicalString(int n) {
        ArrayList<Integer> magicalString = new ArrayList<>();
        magicalString.add(1);
        magicalString.add(2);
        magicalString.add(2);
        int nextGroupSizeIndex = 2;
        while (magicalString.size() < n) {
            int nextGroupSize = magicalString.get(nextGroupSizeIndex);
            int nextGroupValue = magicalString.get(magicalString.size() - 1) == 1 ? 2 : 1;
            for (int i = 0; i < nextGroupSize; i++) {
                magicalString.add(nextGroupValue);
            }
            nextGroupSizeIndex++;
        }
        int count = 0;
        for (int i = 0; i < n; i++) {
            if (magicalString.get(i) == 1) {
                count++;
            }
        }
        return count;
    }
}

public class Solution {
    public static String licenseKeyFormatting(String s, int k) {
        String str = s.replace("-", "").toUpperCase();
        int firstGroupLength = str.length() % k;
        if (firstGroupLength == 0) firstGroupLength = k;
        StringBuilder result = new StringBuilder(str.substring(0, firstGroupLength));
        for (int i = firstGroupLength; i < str.length(); i += k) {
            result.append('-').append(str.substring(i, i + k));
        }
        return result.toString();
    }
}

import java.math.BigInteger;

class Solution {
    public static String smallestGoodBase(String n) {
        BigInteger N = new BigInteger(n);
        for (int m = 63; m >= 1; m--) {
            long low = 2;
            long high = (long) Math.pow(N.doubleValue(), 1.0 / m) + 1;
            while (low <= high) {
                long mid = low + (high - low) / 2;
                BigInteger sum = geometricSum(mid, m);
                int cmp = sum.compareTo(N);
                if (cmp == 0) {
                    return Long.toString(mid);
                } else if (cmp < 0) {
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }
        }
        return N.subtract(BigInteger.ONE).toString();
    }

    private static BigInteger geometricSum(long base, int exponent) {
        BigInteger sum = BigInteger.ONE;
        BigInteger term = BigInteger.ONE;
        BigInteger b = BigInteger.valueOf(base);
        for (int i = 1; i <= exponent; i++) {
            term = term.multiply(b);
            sum = sum.add(term);
        }
        return sum;
    }
}

import java.util.Arrays;

class Solution {
    public static int findRadius(int[] houses, int[] heaters) {
        Arrays.sort(houses);
        Arrays.sort(heaters);
        int result = 0;
        int heaterIndex = 0;
        for (int i = 0; i < houses.length; i++) {
            while (heaterIndex < heaters.length - 1 && Math.abs(heaters[heaterIndex + 1] - houses[i]) <= Math.abs(heaters[heaterIndex] - houses[i])) {
                heaterIndex++;
            }
            result = Math.max(result, Math.abs(heaters[heaterIndex] - houses[i]));
        }
        return result;
    }
}

public class Solution {
    public static boolean PredictTheWinner(int[] nums) {
        int n = nums.length;
        int[][] dp = new int[n][n];
        for (int i = 0; i < n; i++) {
            dp[i][i] = nums[i];
        }
        for (int length = 1; length < n; length++) {
            for (int i = 0; i < n - length; i++) {
                int j = i + length;
                dp[i][j] = Math.max(nums[i] - dp[i + 1][j], nums[j] - dp[i][j - 1]);
            }
        }
        return dp[0][n - 1] >= 0;
    }
}

class Solution {
    public static int findMaxConsecutiveOnes(int[] nums) {
        int maxConsecutiveOnes = 0, currentConsecutiveOnes = 0;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] == 1) currentConsecutiveOnes++;
            else {
                maxConsecutiveOnes = Math.max(maxConsecutiveOnes, currentConsecutiveOnes);
                currentConsecutiveOnes = 0;
            }
        }
        maxConsecutiveOnes = Math.max(maxConsecutiveOnes, currentConsecutiveOnes);
        return maxConsecutiveOnes;
    }
}

import java.util.*;

class Solution {
    public static int findMinStep(String board, String hand) {
        Map<Character, Integer> handMap = new HashMap<>();
        for (char c : hand.toCharArray()) {
            handMap.put(c, handMap.getOrDefault(c, 0) + 1);
        }

        Queue<State> queue = new ArrayDeque<>();
        queue.add(new State(board, handMap));
        Set<String> visited = new HashSet<>();
        int steps = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                State cur = queue.poll();
                String curBoard = cur.board;
                Map<Character, Integer> curHand = cur.hand;
                String key = curBoard + curHand.toString();
                if (!visited.add(key)) {
                    continue;
                }
                if (curBoard.isEmpty()) {
                    return steps;
                }
                for (Map.Entry<Character, Integer> e : curHand.entrySet()) {
                    char color = e.getKey();
                    int cnt = e.getValue();
                    if (cnt == 0) continue;
                    for (int pos = 0; pos <= curBoard.length(); pos++) {
                        String newBoard = curBoard.substring(0, pos) + color + curBoard.substring(pos);
                        String reduced = reduceBoard(newBoard);
                        Map<Character, Integer> newHand = new HashMap<>(curHand);
                        newHand.put(color, cnt - 1);
                        queue.add(new State(reduced, newHand));
                    }
                }
            }
            steps++;
        }
        return -1;
    }

    private static String reduceBoard(String board) {
        boolean changed;
        do {
            changed = false;
            StringBuilder sb = new StringBuilder();
            int i = 0;
            while (i < board.length()) {
                int j = i;
                while (j < board.length() && board.charAt(j) == board.charAt(i)) {
                    j++;
                }
                if (j - i >= 3) {
                    changed = true;
                } else {
                    sb.append(board, i, j);
                }
                i = j;
            }
            board = sb.toString();
        } while (changed);
        return board;
    }

    private static class State {
        String board;
        Map<Character, Integer> hand;

        State(String board, Map<Character, Integer> hand) {
            this.board = board;
            this.hand = hand;
        }
    }
}

