import java.util.*;

class Solution {
    public static List<List<Integer>> findSubsequences(int[] nums) {
        Set<String> result = new LinkedHashSet<>();
        backtrack(0, nums, new ArrayList<>(), result);
        List<List<Integer>> ans = new ArrayList<>();
        for (String s : result) {
            List<Integer> list = new ArrayList<>();
            String inner = s.substring(1, s.length() - 1);
            if (!inner.isEmpty()) {
                for (String part : inner.split(",")) {
                    list.add(Integer.parseInt(part));
                }
            }
            ans.add(list);
        }
        return ans;
    }

    private static void backtrack(int start, int[] nums, List<Integer> current, Set<String> result) {
        if (current.size() >= 2) {
            result.add(toJson(current));
        }
        for (int i = start; i < nums.length; i++) {
            if (current.isEmpty() || nums[i] >= current.get(current.size() - 1)) {
                current.add(nums[i]);
                backtrack(i + 1, nums, current, result);
                current.remove(current.size() - 1);
            }
        }
    }

    private static String toJson(List<Integer> list) {
        StringBuilder sb = new StringBuilder();
        sb.append('[');
        for (int i = 0; i < list.size(); i++) {
            if (i > 0) sb.append(',');
            sb.append(list.get(i));
        }
        sb.append(']');
        return sb.toString();
    }
}

import java.util.*;

class Solution {
    public static int findTargetSumWays(int[] nums, int target) {
        Map<Integer, Integer> dp = new HashMap<>();
        dp.put(0, 1);
        for (int num : nums) {
            Map<Integer, Integer> temp = new HashMap<>();
            for (Map.Entry<Integer, Integer> entry : dp.entrySet()) {
                int sum = entry.getKey();
                int count = entry.getValue();
                int newSum = sum + num;
                temp.put(newSum, temp.getOrDefault(newSum, 0) + count);
                newSum = sum - num;
                temp.put(newSum, temp.getOrDefault(newSum, 0) + count);
            }
            dp = temp;
        }
        return dp.getOrDefault(target, 0);
    }
}

import java.util.*;

class Solution {
    private static long count;

    public static int reversePairs(int[] nums) {
        count = 0;
        if (nums == null || nums.length == 0) {
            return 0;
        }
        int[] arr = Arrays.copyOf(nums, nums.length);
        mergeSort(arr, 0, arr.length - 1);
        return (int) count;
    }

    private static void mergeSort(int[] arr, int left, int right) {
        if (left >= right) {
            return;
        }
        int mid = left + (right - left) / 2;
        mergeSort(arr, left, mid);
        mergeSort(arr, mid + 1, right);
        countPairs(arr, left, mid, right);
        merge(arr, left, mid, right);
    }

    private static void countPairs(int[] arr, int left, int mid, int right) {
        int j = mid + 1;
        for (int i = left; i <= mid; i++) {
            while (j <= right && (long) arr[i] > 2L * arr[j]) {
                j++;
            }
            count += j - (mid + 1);
        }
    }

    private static void merge(int[] arr, int left, int mid, int right) {
        int[] temp = new int[right - left + 1];
        int i = left, j = mid + 1, k = 0;
        while (i <= mid && j <= right) {
            if (arr[i] <= arr[j]) {
                temp[k++] = arr[i++];
            } else {
                temp[k++] = arr[j++];
            }
        }
        while (i <= mid) {
            temp[k++] = arr[i++];
        }
        while (j <= right) {
            temp[k++] = arr[j++];
        }
        System.arraycopy(temp, 0, arr, left, temp.length);
    }
}

