import java.util.Deque;

class Solution {
    public static int[] nextGreaterElement(int[] nums1, int[] nums2) {
        Map<Integer, Integer> nextGreaterMap = new HashMap<>();
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < nums2.length; i++) {
            while (!stack.isEmpty() && nums2[i] > stack.peek()) {
                nextGreaterMap.put(stack.pop(), nums2[i]);
            }
            stack.push(nums2[i]);
        }
        while (!stack.isEmpty()) {
            nextGreaterMap.put(stack.pop(), -1);
        }
        int[] result = new int[nums1.length];
        for (int i = 0; i < nums1.length; i++) {
            result[i] = nextGreaterMap.get(nums1[i]);
        }
        return result;
    }
}

import java.util.*;

class Solution {
    int[][] rects;
    long[] prefix;
    long total = 0;
    public Solution(int[][] rects) {
        this.rects = rects;
        prefix = new long[rects.length];
        for (int i = 0; i < rects.length; i++) {
            total += (long)(rects[i][2]-rects[i][0]+1) * (rects[i][3]-rects[i][1]+1);
            prefix[i] = total;
        }
    }
    public int[] pick() {
        long idx = (long)(Math.random() * total);
        for (int i = 0; i < rects.length; i++) {
            if (idx < prefix[i]) {
                int[] r = rects[i];
                int x = r[0] + (int)(Math.random() * (r[2]-r[0]+1));
                int y = r[1] + (int)(Math.random() * (r[3]-r[1]+1));
                return new int[]{x,y};
            }
        }
        return null;
    }
}

import java.util.*;

class Solution {
    public static int[] findDiagonalOrder(int[][] mat) {
        if (mat == null || mat.length == 0 || mat[0].length == 0) {
            return new int[0];
        }
        int rows = mat.length;
        int cols = mat[0].length;
        Map<Integer, List<Integer>> map = new HashMap<>();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int diagonal = i + j;
                map.computeIfAbsent(diagonal, k -> new ArrayList<>()).add(mat[i][j]);
            }
        }
        List<Integer> resultList = new ArrayList<>(rows * cols);
        for (int i = 0; i < rows + cols - 1; i++) {
            List<Integer> diag = map.get(i);
            if (i % 2 == 0) {
                Collections.reverse(diag);
            }
            resultList.addAll(diag);
        }
        int[] result = new int[resultList.size()];
        for (int i = 0; i < result.length; i++) {
            result[i] = resultList.get(i);
        }
        return result;
    }
}

import java.util.ArrayList;
import java.util.List;

class Solution {
    public static String[] findWords(String[] words) {
        String[] rows = {"qwertyuiop", "asdfghjkl", "zxcvbnm"};
        List<String> result = new ArrayList<>();
        for (String word : words) {
            String lower = word.toLowerCase();
            char firstChar = lower.charAt(0);
            boolean canBeTyped = true;
            String row;
            if (rows[0].indexOf(firstChar) >= 0) {
                row = rows[0];
            } else if (rows[1].indexOf(firstChar) >= 0) {
                row = rows[1];
            } else {
                row = rows[2];
            }
            for (char c : lower.toCharArray()) {
                if (row.indexOf(c) == -1) {
                    canBeTyped = false;
                    break;
                }
            }
            if (canBeTyped) {
                result.add(word);
            }
        }
        return result.toArray(new String[0]);
    }
}

import java.util.*;

class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

class Solution {
    public int[] findMode(TreeNode root) {
        Map<Integer, Integer> frequency = new HashMap<>();
        dfs(root, frequency);
        int maxFrequency = 0;
        for (int freq : frequency.values()) {
            if (freq > maxFrequency) {
                maxFrequency = freq;
            }
        }
        List<Integer> modesList = new ArrayList<>();
        for (Map.Entry<Integer, Integer> entry : frequency.entrySet()) {
            if (entry.getValue() == maxFrequency) {
                modesList.add(entry.getKey());
            }
        }
        int[] modes = new int[modesList.size()];
        for (int i = 0; i < modesList.size(); i++) {
            modes[i] = modesList.get(i);
        }
        return modes;
    }

    private void dfs(TreeNode node, Map<Integer, Integer> frequency) {
        if (node == null) return;
