class Solution {
    public static int findMaximizedCapital(int k, int w, int[] profits, int[] capital) {
        List<int[]> projects = new ArrayList<>();
        for (int i = 0; i < profits.length; i++) {
            projects.add(new int[]{profits[i], capital[i]});
        }
        projects.sort((a, b) -> Integer.compare(a[1], b[1]));
        List<Integer> pq = new ArrayList<>();
        int i = 0;
        while (k > 0) {
            while (i < projects.size() && projects.get(i)[1] <= w) {
                pq.add(projects.get(i)[0]);
                i++;
            }
            if (pq.isEmpty()) {
                break;
            }
            int maxProfit = Collections.max(pq);
            w += maxProfit;
            pq.remove(pq.indexOf(maxProfit));
            k--;
        }
        return w;
    }
}

