class Solution {
    public static boolean checkPerfectNumber(int num) {
        int sum = 1;
        for (int i = 2; (long) i * i <= num; i++) {
            if (num % i == 0) {
                sum += i;
                if ((long) i * i != num) sum += num / i;
            }
        }
        return sum == num;
    }
}

