class Solution {
    public static int findRotateSteps(String ring, String key) {
        if (key.isEmpty()) return 0;
        Map<Character, List<Integer>> charIndexMap = new HashMap<>();
        for (int i = 0; i < ring.length(); i++) {
            char c = ring.charAt(i);
            charIndexMap.computeIfAbsent(c, k -> new ArrayList<>()).add(i);
        }

        int n = key.length();
        int m = ring.length();
        int INF = Integer.MAX_VALUE / 2;
        int[][] dp = new int[n][m];
        for (int i = 0; i < n; i++) {
            Arrays.fill(dp[i], INF);
        }

        for (int j = 0; j < m; j++) {
            if (ring.charAt(j) == key.charAt(0)) {
                dp[0][j] = Math.min(j, m - j) + 1;
            }
        }

        for (int i = 1; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (ring.charAt(j) == key.charAt(i)) {
                    for (int k = 0; k < m; k++) {
                        if (dp[i - 1][k] != INF) {
                            int diff = Math.abs(j - k);
                            int minSteps = Math.min(diff, m - diff);
                            dp[i][j] = Math.min(dp[i][j], dp[i - 1][k] + minSteps + 1);
                        }
                    }
                }
            }
        }

        int minSteps = INF;
        for (int j = 0; j < m; j++) {
            if (dp[n - 1][j] != INF) {
                minSteps = Math.min(minSteps, dp[n - 1][j]);
            }
        }
        return minSteps;
    }
}

