class Solution {
    public static int findMinMoves(int[] machines) {
        long total = 0;
        for (int v : machines) total += v;
        int n = machines.length;
        if (total % n != 0) return -1;
        long avg = total / n;
        long maxMoves = 0;
        long cum = 0;
        for (int i = 0; i < n; i++) {
            cum += machines[i] - avg;
            long need = Math.max(Math.abs(cum), machines[i] - avg);
            if (need > maxMoves) maxMoves = need;
        }
        return (int) maxMoves;
    }
}

