class Solution {
    public static boolean checkSubarraySum(int[] nums, int k) {
        Map<Integer, Integer> prefixSumModulo = new HashMap<>();
        prefixSumModulo.put(0, -1);
        int currentSum = 0;
        for (int i = 0; i < nums.length; i++) {
            currentSum += nums[i];
            int currentSumModulo = currentSum % k;
            if (prefixSumModulo.containsKey(currentSumModulo) && i - prefixSumModulo.get(currentSumModulo) > 1) {
                return true;
            }
            if (!prefixSumModulo.containsKey(currentSumModulo)) {
                prefixSumModulo.put(currentSumModulo, i);
            }
        }
        return false;
    }
}

