class Solution {
    public static int findLUSlength(String[] strs) {
        Map<String, Integer> freqMap = new HashMap<>();
        for (String s : strs) {
            freqMap.put(s, freqMap.getOrDefault(s, 0) + 1);
        }
        Arrays.sort(strs, (a, b) -> Integer.compare(b.length(), a.length()));
        for (int i = 0; i < strs.length; i++) {
            if (freqMap.get(strs[i]) == 1) {
                boolean isSubsequence = false;
                for (int j = 0; j < strs.length; j++) {
                    if (i == j) continue;
                    if (isSubsequenceOf(strs[i], strs[j])) {
                        isSubsequence = true;
                        break;
                    }
                }
                if (!isSubsequence) return strs[i].length();
            }
        }
        return -1;
    }

    private static boolean isSubsequenceOf(String a, String b) {
        int i = 0, j = 0;
        while (i < a.length() && j < b.length()) {
            if (a.charAt(i) == b.charAt(j)) i++;
            j++;
        }
        return i == a.length();
    }
}

public class Solution {
    public static int longestPalindromicSubsequence(String s) {
        int n = s.length();
        int[][] dp = new int[n][n];
        for (int i = 0; i < n; i++) {
            dp[i][i] = 1;
        }
        for (int i = 0; i < n - 1; i++) {
            if (s.charAt(i) == s.charAt(i + 1)) {
                dp[i][i + 1] = 2;
            } else {
                dp[i][i + 1] = 1;
            }
        }
        for (int length = 3; length <= n; length++) {
            for (int i = 0; i < n - length + 1; i++) {
                int j = i + length - 1;
                if (s.charAt(i) == s.charAt(j)) {
                    dp[i][j] = dp[i + 1][j - 1] + 2;
                } else {
                    dp[i][j] = Math.max(dp[i + 1][j], dp[i][j - 1]);
                }
            }
        }
        return dp[0][n - 1];
    }
}

