class Solution {
    public static int countArrangement(int n) {
        int[] count = new int[1];
        boolean[] visited = new boolean[n + 1];
        backtrack(1, n, visited, count);
        return count[0];
    }

    private static void backtrack(int index, int n, boolean[] visited, int[] count) {
        if (index == n + 1) {
            count[0]++;
        } else {
            for (int i = 1; i <= n; i++) {
                if (!visited[i] && (i % index == 0 || index % i == 0)) {
                    visited[i] = true;
                    backtrack(index + 1, n, visited, count);
                    visited[i] = false;
                }
            }
        }
    }
}

