class Solution {
    double[] prefixSum;
    public Solution(int[] w) {
        prefixSum = new double[w.length];
        prefixSum[0] = w[0];
        for (int i = 1; i < w.length; i++) prefixSum[i] = prefixSum[i-1] + w[i];
    }
    public int pickIndex() {
        double target = Math.random() * prefixSum[prefixSum.length-1];
        int left = 0, right = prefixSum.length - 1;
        while (left < right) {
            int mid = (left+right)/2;
            if (target < prefixSum[mid]) right = mid; else left = mid+1;
        }
        return left;
    }
}

