class Solution {
    public static int findMinDifference(List<String> timePoints) {
        List<Integer> minutes = new ArrayList<>();
        for (String time : timePoints) {
            String[] parts = time.split(":");
            int total = Integer.parseInt(parts[0]) * 60 + Integer.parseInt(parts[1]);
            minutes.add(total);
        }
        Collections.sort(minutes);
        int minDiff = Integer.MAX_VALUE;
        for (int i = 0; i < minutes.size() - 1; i++) {
            minDiff = Math.min(minDiff, minutes.get(i + 1) - minutes.get(i));
        }
        minDiff = Math.min(minDiff, 24 * 60 - minutes.get(minutes.size() - 1) + minutes.get(0));
        return minDiff;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static int removeBoxes(int[] boxes) {
        if (boxes == null || boxes.length == 0) return 0;
        Map<String, Integer> memo = new HashMap<>();
        return dp(0, boxes.length - 1, 0, boxes, memo);
    }

    private static int dp(int left, int right, int k, int[] boxes, Map<String, Integer> memo) {
        if (left > right) return 0;
        String key = left + "," + right + "," + k;
        Integer cached = memo.get(key);
        if (cached != null) return cached;

        int origLeft = left, origK = k;
        while (left + 1 <= right && boxes[left] == boxes[left + 1]) {
            left++;
            k++;
        }

        int maxPoints = (k + 1) * (k + 1) + dp(left + 1, right, 0, boxes, memo);
        for (int i = left + 1; i <= right; i++) {
            if (boxes[i] == boxes[left]) {
                int points = dp(left + 1, i - 1, 0, boxes, memo) + dp(i, right, k + 1, boxes, memo);
                if (points > maxPoints) maxPoints = points;
            }
        }
        memo.put(origLeft + "," + right + "," + origK, maxPoints);
        return maxPoints;
    }
}

public class Solution {
    public static int findCircleNum(int[][] isConnected) {
        int n = isConnected.length;
        boolean[] visited = new boolean[n];
        int count = 0;
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                dfs(isConnected, visited, i);
                count++;
            }
        }
        return count;
    }
    private static void dfs(int[][] isConnected, boolean[] visited, int i) {
        visited[i] = true;
        for (int j = 0; j < isConnected.length; j++) {
            if (isConnected[i][j] == 1 && !visited[j]) {
                dfs(isConnected, visited, j);
            }
        }
    }
}

