class Solution {
    public static boolean checkRecord(String s) {
        int absenceCount = 0;
        int consecutiveLateCount = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == 'A') {
                absenceCount++;
                consecutiveLateCount = 0;
            } else if (c == 'L') {
                consecutiveLateCount++;
            } else {
                consecutiveLateCount = 0;
            }
            if (absenceCount >= 2 || consecutiveLateCount >= 3) {
                return false;
            }
        }
        return true;
    }
}

public class Solution {
    public static String optimalDivision(int[] nums) {
        if (nums.length == 1) return Integer.toString(nums[0]);
        if (nums.length == 2) return nums[0] + "/" + nums[1];
        StringBuilder sb = new StringBuilder();
        sb.append(nums[0]).append("/(");
        for (int i = 1; i < nums.length; i++) {
            sb.append(nums[i]);
            if (i != nums.length - 1) sb.append('/');
        }
        sb.append(')');
        return sb.toString();
    }
}

import java.lang.*;

class Solution {
    public static int checkRecord(int n) {
        final int MOD = 1_000_000_007;
        long[][] dp = new long[2][3];
        dp[0][0] = 1;
        for (int i = 0; i < n; i++) {
            long[][] ndp = new long[2][3];
            for (int a = 0; a <= 1; a++) {
                for (int l = 0; l <= 2; l++) {
                    long val = dp[a][l];
                    if (val == 0) continue;
                    ndp[a][0] = (ndp[a][0] + val) % MOD; // add 'P'
                    if (l < 2) {
                        ndp[a][l + 1] = (ndp[a][l + 1] + val) % MOD; // add 'L'
                    }
                    if (a == 0) {
                        ndp[1][0] = (ndp[1][0] + val) % MOD; // add 'A'
                    }
                }
            }
            dp = ndp;
        }
        long ans = 0;
        for (int a = 0; a <= 1; a++) {
            for (int l = 0; l <= 2; l++) {
                ans = (ans + dp[a][l]) % MOD;
            }
        }
        return (int) ans;
    }
}

