class Solution {
    public static int leastBricks(int[][] wall) {
        Map<Integer, Integer> edges = new HashMap<>();
        for (int i = 0; i < wall.length; i++) {
            int sum = 0;
            for (int j = 0; j < wall[i].length - 1; j++) {
                sum += wall[i][j];
                edges.put(sum, edges.getOrDefault(sum, 0) + 1);
            }
        }
        int maxEdges = 0;
        for (int count : edges.values()) {
            if (count > maxEdges) {
                maxEdges = count;
            }
        }
        return wall.length - maxEdges;
    }
}

