class Solution {
    public static int maxDepth(Node root) {
        if (root == null) return 0;
        Deque<Node> queue = new ArrayDeque<>();
        queue.add(root);
        int depth = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                Node node = queue.poll();
                if (node.children != null) {
                    for (Node child : node.children) {
                        queue.add(child);
                    }
                }
            }
            depth++;
        }
        return depth;
    }
}

import java.util.*;

class Solution {
    public static List<Object> intersect(List<Object> quadTree1, List<Object> quadTree2) {
        int leaf1 = (int) quadTree1.get(0);
        int leaf2 = (int) quadTree2.get(0);
        if (leaf1 == 1 && leaf2 == 1) {
            boolean val = (boolean) quadTree1.get(1) || (boolean) quadTree2.get(1);
            return Arrays.asList(1, val);
        }
        if (leaf1 == 1) {
            if ((boolean) quadTree1.get(1)) return Arrays.asList(1, true);
            return quadTree2;
        }
        if (leaf2 == 1) {
            if ((boolean) quadTree2.get(1)) return Arrays.asList(1, true);
            return quadTree1;
        }
        return Arrays.asList(
            0,
            intersect((List<Object>) quadTree1.get(1), (List<Object>) quadTree2.get(1)),
            intersect((List<Object>) quadTree1.get(2), (List<Object>) quadTree2.get(2)),
            intersect((List<Object>) quadTree1.get(3), (List<Object>) quadTree2.get(3)),
            intersect((List<Object>) quadTree1.get(4), (List<Object>) quadTree2.get(4))
        );
    }
}

import java.util.ArrayList;
import java.util.List;

class Solution {
    public static int[][] matrixReshape(int[][] mat, int r, int c) {
        if (mat.length * mat[0].length != r * c) {
            return mat;
        }
        List<List<Integer>> reshapedMatrix = new ArrayList<>();
        List<Integer> currentRow = new ArrayList<>();
        int columnIndex = 0;
        for (int i = 0; i < mat.length; i++) {
            for (int j = 0; j < mat[0].length; j++) {
                currentRow.add(mat[i][j]);
                if (++columnIndex == c) {
                    reshapedMatrix.add(currentRow);
                    currentRow = new ArrayList<>();
                    columnIndex = 0;
                }
            }
        }
        int[][] result = new int[r][c];
        for (int i = 0; i < r; i++) {
            List<Integer> row = reshapedMatrix.get(i);
            for (int j = 0; j < c; j++) {
                result[i][j] = row.get(j);
            }
        }
        return result;
    }
}

public class Solution {
    public static int arrayNesting(int[] nums) {
        int maxLength = 0;
        boolean[] visited = new boolean[nums.length];
        for (int i = 0; i < nums.length; i++) {
            if (!visited[i]) {
                int currentLength = 0;
                int currentIndex = i;
                while (!visited[currentIndex]) {
                    visited[currentIndex] = true;
                    currentLength++;
                    currentIndex = nums[currentIndex];
                }
                maxLength = Math.max(maxLength, currentLength);
            }
        }
        return maxLength;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static boolean checkInclusion(String s1, String s2) {
        Map<Character, Integer> s1Map = new HashMap<>();
        for (int i = 0; i < s1.length(); i++) {
            char c = s1.charAt(i);
            s1Map.put(c, s1Map.getOrDefault(c, 0) + 1);
        }
        int left = 0;
        int right = 0;
        int matched = 0;
        Map<Character, Integer> windowCounts = new HashMap<>();
        while (right < s2.length()) {
            char character = s2.charAt(right);
            if (s1Map.containsKey(character)) {
                windowCounts.put(character, windowCounts.getOrDefault(character, 0) + 1);
                if (windowCounts.get(character).intValue() == s1Map.get(character).intValue()) {
                    matched++;
                }
            }
            if (right - left + 1 == s1.length()) {
                if (matched == s1Map.size()) {
                    return true;
                }
                char leftChar = s2.charAt(left);
                if (s1Map.containsKey(leftChar)) {
                    if (windowCounts.get(leftChar).intValue() == s1Map.get(leftChar).intValue()) {
                        matched--;
                    }
                    windowCounts.put(leftChar, windowCounts.get(leftChar) - 1);
                }
                left++;
            }
            right++;
        }
        return false;
    }
}

class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

class Solution {
    public static boolean isSubtree(TreeNode root, TreeNode subRoot) {
        return dfs(root, subRoot);
    }
    private static boolean isMatch(TreeNode node1, TreeNode node2) {
        if (node1 == null && node2 == null) return true;
        if (node1 == null || node2 == null) return false;
        return node1.val == node2.val && isMatch(node1.left, node2.left) && isMatch(node1.right, node2.right);
    }
    private static boolean dfs(TreeNode node, TreeNode subRoot) {
        if (node == null) return false;
        if (isMatch(node, subRoot)) return true;
        return dfs(node.left, subRoot) || dfs(node.right, subRoot);
    }
}

