import java.util.HashMap;
import java.util.Map;

class Solution {
    public static int findPaths(int m, int n, int maxMove, int startRow, int startColumn) {
        final int MOD = 1_000_000_007;
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        Map<String, Integer> memo = new HashMap<>();
        return dfs(startRow, startColumn, maxMove, m, n, directions, memo, MOD);
    }

    private static int dfs(int row, int col, int moves, int m, int n, int[][] directions, Map<String, Integer> memo, int MOD) {
        if (row < 0 || row >= m || col < 0 || col >= n) return 1;
        if (moves == 0) return 0;
        String key = row + "," + col + "," + moves;
        if (memo.containsKey(key)) return memo.get(key);
        long res = 0;
        for (int[] d : directions) {
            res = (res + dfs(row + d[0], col + d[1], moves - 1, m, n, directions, memo, MOD)) % MOD;
        }
        int result = (int) res;
        memo.put(key, result);
        return result;
    }
}

import java.util.Arrays;

class Solution {
    public static int findUnsortedSubarray(int[] nums) {
        int[] sortedNums = Arrays.copyOf(nums, nums.length);
        Arrays.sort(sortedNums);
        int left = 0, right = nums.length - 1;
        while (left < nums.length && nums[left] == sortedNums[left]) left++;
        if (left == nums.length) return 0;
        while (right >= 0 && nums[right] == sortedNums[right]) right--;
        return right - left + 1;
    }
}

import java.util.*;

class Solution {
    public static int minDistance(String word1, String word2) {
        int[][] dp = new int[word1.length() + 1][word2.length() + 1];
        for (int i = 0; i <= word1.length(); i++) {
            dp[i][0] = 0;
        }
        for (int j = 0; j <= word2.length(); j++) {
            dp[0][j] = 0;
        }
        for (int i = 1; i <= word1.length(); i++) {
            for (int j = 1; j <= word2.length(); j++) {
                if (word1.charAt(i - 1) == word2.charAt(j - 1)) {
                    dp[i][j] = dp[i - 1][j - 1] + 1;
                } else {
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }
        return word1.length() + word2.length() - 2 * dp[word1.length()][word2.length()];
    }
}

class Solution {
    public int[][] outerTrees(int[][] trees) {
        int n = trees.length;
        if (n < 4) return trees;
        java.util.Arrays.sort(trees, (a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);
        int[][] hull = new int[2 * n + 1][];
        int size = 0;
        for (int i = 0; i < n; i++) {
            while (size >= 2 && cross(hull[size-2], hull[size-1], trees[i]) < 0) size--;
            hull[size++] = trees[i];
        }
        int lower = size + 1;
        for (int i = n - 2; i >= 0; i--) {
            while (size >= lower && cross(hull[size-2], hull[size-1], trees[i]) < 0) size--;
            hull[size++] = trees[i];
        }
        java.util.Set<String> seen = new java.util.LinkedHashSet<>();
        java.util.List<int[]> res = new java.util.ArrayList<>();
        for (int i = 0; i < size; i++) {
            String key = hull[i][0]+","+hull[i][1];
            if (seen.add(key)) res.add(hull[i]);
        }
        return res.toArray(new int[0][]);
    }
    private long cross(int[] o, int[] a, int[] b) {
        return (long)(a[0]-o[0])*(b[1]-o[1]) - (long)(a[1]-o[1])*(b[0]-o[0]);
    }
}

