class Solution {
    public static List<Integer> postorder(Node root) {
        Deque<Integer> result = new ArrayDeque<>();
        if (root == null) return new ArrayList<>();
        Deque<Node> stack = new ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            Node node = stack.pop();
            result.addFirst(node.val);
            if (node.children != null) {
                for (Node child : node.children) {
                    stack.push(child);
                }
            }
        }
        return new ArrayList<>(result);
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public static boolean isValid(String code) {
        int n = code.length();
        int i = 0;
        Deque<String> stack = new ArrayDeque<>();
        boolean hasRoot = false;
        while (i < n) {
            if (code.startsWith("<![CDATA[", i)) {
                if (stack.isEmpty()) return false;
                i += 9;
                int end = code.indexOf("]]>", i);
                if (end == -1) return false;
                i = end + 3;
            } else if (code.charAt(i) == '<') {
                int j = code.indexOf('>', i);
                if (j == -1) return false;
                String tag = code.substring(i + 1, j);
                if (tag.isEmpty()) return false;
                if (tag.charAt(0) == '/') {
                    String name = tag.substring(1);
                    if (!isValidTagName(name)) return false;
                    if (stack.isEmpty() || !stack.pop().equals(name)) return false;
                } else {
                    if (stack.isEmpty() && i != 0) return false;
                    if (!isValidTagName(tag)) return false;
                    stack.push(tag);
                    hasRoot = true;
                }
                i = j + 1;
            } else {
                if (stack.isEmpty()) return false;
                if (code.charAt(i) == '&') return false;
                i++;
            }
        }
        return stack.isEmpty() && hasRoot;
    }

    private static boolean isValidTagName(String s) {
        if (s.length() < 1 || s.length() > 9) return false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < 'A' || c > 'Z') return false;
        }
        return true;
    }
}

import java.util.*;

class Solution {
    public static String fractionAddition(String expression) {
        int i = 0;
        int n = expression.length();
        long num = 0;
        long den = 1;
        while (i < n) {
            int sign = 1;
            char ch = expression.charAt(i);
            if (ch == '+' || ch == '-') {
                sign = ch == '-' ? -1 : 1;
                i++;
            }
            long a = 0;
            while (i < n && Character.isDigit(expression.charAt(i))) {
                a = a * 10 + (expression.charAt(i) - '0');
                i++;
            }
            a *= sign;
            i++; // skip '/'
            long b = 0;
            while (i < n && Character.isDigit(expression.charAt(i))) {
                b = b * 10 + (expression.charAt(i) - '0');
                i++;
            }
            long newNum = num * b + a * den;
            long newDen = den * b;
            long g = gcd(Math.abs(newNum), newDen);
            num = newNum / g;
            den = newDen / g;
        }
        return num + "/" + den;
    }

    private static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

import java.util.Arrays;

class Solution {
    public static boolean validSquare(int[] p1, int[] p2, int[] p3, int[] p4) {
        int[] distances = new int[6];
        distances[0] = distance(p1, p2);
        distances[1] = distance(p1, p3);
        distances[2] = distance(p1, p4);
        distances[3] = distance(p2, p3);
        distances[4] = distance(p2, p4);
        distances[5] = distance(p3, p4);
        Arrays.sort(distances);
        return distances[0] == distances[1] && distances[1] == distances[2] && distances[2] == distances[3] && distances[4] == distances[5] && distances[0] < distances[4];
    }

    private static int distance(int[] a, int[] b) {
        int dx = a[0] - b[0];
        int dy = a[1] - b[1];
        return dx * dx + dy * dy;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static int findLHS(int[] nums) {
        Map<Integer, Integer> countMap = new HashMap<>();
        for (int num : nums) {
            countMap.put(num, countMap.getOrDefault(num, 0) + 1);
        }
        int longestLength = 0;
        for (int num : countMap.keySet()) {
            if (countMap.containsKey(num + 1)) {
                longestLength = Math.max(longestLength, countMap.get(num) + countMap.get(num + 1));
            }
        }
        return longestLength;
    }
}

