class Solution {
    public static int kInversePairs(int n, int k) {
        final int MOD = 1_000_000_007;
        int[][] dp = new int[n + 1][k + 1];
        for (int i = 1; i <= n; i++) {
            dp[i][0] = 1;
        }
        for (int i = 2; i <= n; i++) {
            for (int j = 1; j <= k; j++) {
                for (int p = 0; p <= i - 1 && p <= j; p++) {
                    dp[i][j] = (int) ((dp[i][j] + dp[i - 1][j - p]) % MOD);
                }
            }
        }
        return dp[n][k];
    }
}

