class Solution {
    public static int[] smallestRange(int[][] nums) {
        List<int[]> minHeap = new ArrayList<>();
        for (int i = 0; i < nums.length; i++) {
            minHeap.add(new int[]{nums[i][0], i, 0});
        }
        minHeap.sort((a, b) -> Integer.compare(a[0], b[0]));
        int minRange = Integer.MAX_VALUE;
        int maxVal = minHeap.stream().mapToInt(x -> x[0]).max().orElse(Integer.MIN_VALUE);
        int[] res = new int[]{-1, -1};
        while (minHeap.size() == nums.length) {
            int minVal = minHeap.get(0)[0];
            if (maxVal - minVal < minRange) {
                minRange = maxVal - minVal;
                res[0] = minVal;
                res[1] = maxVal;
            }
            int[] removed = minHeap.remove(0);
            int listIndex = removed[1];
            int elementIndex = removed[2];
            if (elementIndex + 1 < nums[listIndex].length) {
                int nextVal = nums[listIndex][elementIndex + 1];
                minHeap.add(new int[]{nextVal, listIndex, elementIndex + 1});
                minHeap.sort((a, b) -> Integer.compare(a[0], b[0]));
                if (nextVal > maxVal) {
                    maxVal = nextVal;
                }
            }
        }
        return res;
    }
}

