public class Solution {
    public static int shoppingOffers(int[] price, int[][] special, int[] needs) {
        Map<String, Integer> memo = new HashMap<>();
        return dfs(needs, price, special, memo);
    }

    private static int dfs(int[] needs, int[] price, int[][] special, Map<String, Integer> memo) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < needs.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(needs[i]);
        }
        String key = sb.toString();
        if (memo.containsKey(key)) {
            return memo.get(key);
        }
        int minCost = 0;
        for (int i = 0; i < needs.length; i++) {
            minCost += needs[i] * price[i];
        }
        for (int[] offer : special) {
            int[] clone = needs.clone();
            boolean valid = true;
            for (int i = 0; i < needs.length; i++) {
                clone[i] -= offer[i];
                if (clone[i] < 0) {
                    valid = false;
                    break;
                }
            }
            if (valid) {
                int offerPrice = offer[offer.length - 1];
                int cost = offerPrice + dfs(clone, price, special, memo);
                if (cost < minCost) {
                    minCost = cost;
                }
            }
        }
        memo.put(key, minCost);
        return minCost;
    }
}

