class Solution {
    public static int numDecodings(String s) {
        final long MOD = 1000000007L;
        int n = s.length();
        long[] dp = new long[n + 1];
        dp[0] = 1;
        for (int i = 1; i <= n; i++) {
            char cur = s.charAt(i - 1);
            if (cur == '*') {
                dp[i] = (dp[i] + dp[i - 1] * 9) % MOD;
            } else if (cur != '0') {
                dp[i] = (dp[i] + dp[i - 1]) % MOD;
            }
            if (i >= 2) {
                char prev = s.charAt(i - 2);
                if (prev == '*' && cur == '*') {
                    dp[i] = (dp[i] + dp[i - 2] * 15) % MOD;
                } else if (prev == '*') {
                    if (cur == '0') {
                        dp[i] = (dp[i] + dp[i - 2] * 2) % MOD;
                    } else if (cur >= '1' && cur <= '6') {
                        dp[i] = (dp[i] + dp[i - 2] * 2) % MOD;
                    } else {
                        dp[i] = (dp[i] + dp[i - 2]) % MOD;
                    }
                } else if (cur == '*') {
                    if (prev == '1') {
                        dp[i] = (dp[i] + dp[i - 2] * 9) % MOD;
                    } else if (prev == '2') {
                        dp[i] = (dp[i] + dp[i - 2] * 6) % MOD;
                    }
                } else {
                    int two = (prev - '0') * 10 + (cur - '0');
                    if (two >= 10 && two <= 26) {
                        dp[i] = (dp[i] + dp[i - 2]) % MOD;
                    }
                }
            }
        }
        return (int) dp[n];
    }
}

class Solution {
    public static String solveEquation(String equation) {
        int eq = equation.indexOf('=');
        String left = equation.substring(0, eq);
        String right = equation.substring(eq + 1);
        int[] leftRes = parseSide(left);
        int[] rightRes = parseSide(right);
        int xCoefficient = leftRes[0] - rightRes[0];
        int constant = rightRes[1] - leftRes[1];
        if (xCoefficient == 0) {
            return constant == 0 ? "Infinite solutions" : "No solution";
        }
        return "x=" + (constant / xCoefficient);
    }

    private static int[] parseSide(String side) {
        int xCoeff = 0, constant = 0;
        int i = 0, n = side.length();
        while (i < n) {
            int start = i;
            if (side.charAt(i) == '+' || side.charAt(i) == '-') i++;
            while (i < n && Character.isDigit(side.charAt(i))) i++;
            boolean hasX = (i < n && side.charAt(i) == 'x');
            String numPart = side.substring(start, i);
            if (hasX) {
                int coeff;
                if (numPart.isEmpty() || numPart.equals("+")) coeff = 1;
                else if (numPart.equals("-")) coeff = -1;
                else coeff = Integer.parseInt(numPart);
                xCoeff += coeff;
                i++;
            } else {
                constant += Integer.parseInt(numPart);
            }
        }
        return new int[]{xCoeff, constant};
    }
}

class Solution {
    int capacity, size, head, tail;
    int[] deque;
    public Solution(int k) { capacity=k; size=0; head=0; tail=0; deque=new int[k]; }
    public boolean insertFront(int value) {
        if (size==capacity) return false;
        head = (head-1+capacity)%capacity; deque[head]=value; size++;
        return true;
    }
    public boolean insertLast(int value) {
        if (size==capacity) return false;
        deque[tail]=value; tail=(tail+1)%capacity; size++;
        return true;
    }
    public boolean deleteFront() {
        if (size==0) return false;
        head=(head+1)%capacity; size--;
        return true;
    }
    public boolean deleteLast() {
        if (size==0) return false;
        tail=(tail-1+capacity)%capacity; size--;
        return true;
    }
    public int getFront() { return size==0 ? -1 : deque[head]; }
    public int getRear() { return size==0 ? -1 : deque[(tail-1+capacity)%capacity]; }
    public boolean isEmpty() { return size==0; }
    public boolean isFull() { return size==capacity; }
}

public class Solution {
    public static double findMaxAverage(int[] nums, int k) {
        double maxSum = 0;
        for (int i = 0; i < k; i++) {
            maxSum += nums[i];
        }
        double currentSum = maxSum;
        for (int i = k; i < nums.length; i++) {
            currentSum = currentSum - nums[i - k] + nums[i];
            if (currentSum > maxSum) {
                maxSum = currentSum;
            }
        }
        return maxSum / k;
    }
}

