class Solution {
    public static List<List<String>> printTree(TreeNode root) {
        int height = getHeight(root);
        int rows = height;
        int cols = (int) Math.pow(2, height) - 1;
        List<List<String>> res = new ArrayList<>(rows);
        for (int i = 0; i < rows; i++) {
            List<String> row = new ArrayList<>(Collections.nCopies(cols, ""));
            res.add(row);
        }
        Queue<NodeInfo> queue = new LinkedList<>();
        queue.offer(new NodeInfo(root, 0, 0, cols - 1));
        while (!queue.isEmpty()) {
            NodeInfo cur = queue.poll();
            TreeNode node = cur.node;
            int level = cur.level;
            int start = cur.start;
            int end = cur.end;
            int mid = (start + end) / 2;
            res.get(level).set(mid, Integer.toString(node.val));
            if (node.left != null) {
                queue.offer(new NodeInfo(node.left, level + 1, start, mid - 1));
            }
            if (node.right != null) {
                queue.offer(new NodeInfo(node.right, level + 1, mid + 1, end));
            }
        }
        return res;
    }

    private static int getHeight(TreeNode node) {
        if (node == null) return 0;
        int left = getHeight(node.left);
        int right = getHeight(node.right);
        return 1 + Math.max(left, right);
    }

    private static class NodeInfo {
        TreeNode node;
        int level;
        int start;
        int end;
