class Solution {
    public static boolean isPossible(int[] nums) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int num : nums) {
            freq.put(num, freq.getOrDefault(num, 0) + 1);
        }
        Map<Integer, Integer> need = new HashMap<>();
        for (int num : nums) {
            if (freq.getOrDefault(num, 0) == 0) {
                continue;
            }
            freq.put(num, freq.get(num) - 1);
            if (need.getOrDefault(num, 0) > 0) {
                need.put(num, need.get(num) - 1);
                need.put(num + 1, need.getOrDefault(num + 1, 0) + 1);
            } else {
                if (freq.getOrDefault(num + 1, 0) > 0 && freq.getOrDefault(num + 2, 0) > 0) {
                    freq.put(num + 1, freq.get(num + 1) - 1);
                    freq.put(num + 2, freq.get(num + 2) - 1);
                    need.put(num + 3, need.getOrDefault(num + 3, 0) + 1);
                } else {
                    return false;
                }
            }
        }
        return true;
    }
}

public class Solution {
    public static int[][] imageSmoother(int[][] img) {
        int rows = img.length;
        int cols = img[0].length;
        int[][] smoothedImg = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int sum = 0;
                int count = 0;
                for (int x = Math.max(0, i - 1); x <= Math.min(rows - 1, i + 1); x++) {
                    for (int y = Math.max(0, j - 1); y <= Math.min(cols - 1, j + 1); y++) {
                        sum += img[x][y];
                        count++;
                    }
                }
                smoothedImg[i][j] = sum / count;
            }
        }
        return smoothedImg;
    }
}

