public class Solution {
    public int widthOfBinaryTree(TreeNode root) {
        if (root == null) return 0;
        int maxWidth = 0;
        Deque<NodeInfo> queue = new ArrayDeque<>();
        queue.offer(new NodeInfo(root, 0L));
        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            long minIndex = queue.peekFirst().index;
            long maxIndex = minIndex;
            for (int i = 0; i < levelSize; i++) {
                NodeInfo cur = queue.pollFirst();
                TreeNode node = cur.node;
                long index = cur.index;
                if (index < minIndex) minIndex = index;
                if (index > maxIndex) maxIndex = index;
                if (node.left != null) queue.offer(new NodeInfo(node.left, 2 * index + 1));
                if (node.right != null) queue.offer(new NodeInfo(node.right, 2 * index + 2));
            }
            int width = (int) (maxIndex - minIndex + 1);
            if (width > maxWidth) maxWidth = width;
        }
        return maxWidth;
    }

    static class NodeInfo {
        TreeNode node;
        long index;
        NodeInfo(TreeNode node, long index) {
            this.node = node;
            this.index = index;
        }
    }
}

