class Solution {
    public static int strangePrinter(String s) {
        int n = s.length();
        if (n == 0) return 0;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (sb.length() == 0 || sb.charAt(sb.length() - 1) != c) {
                sb.append(c);
            }
        }
        String t = sb.toString();
        int m = t.length();
        int[][] dp = new int[m][m];
        for (int i = m - 1; i >= 0; i--) {
            dp[i][i] = 1;
            for (int j = i + 1; j < m; j++) {
                dp[i][j] = dp[i][j - 1] + 1;
                for (int k = i; k < j; k++) {
                    if (t.charAt(k) == t.charAt(j)) {
                        int val = dp[i][k] + (k + 1 <= j - 1 ? dp[k + 1][j - 1] : 0);
                        dp[i][j] = Math.min(dp[i][j], val);
                    }
                }
            }
        }
        return dp[0][m - 1];
    }
}

