class Solution {
    public static int cutOffTree(int[][] forest) {
        int rows = forest.length;
        int cols = forest[0].length;
        List<int[]> trees = new ArrayList<>();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (forest[i][j] > 1) {
                    trees.add(new int[]{forest[i][j], i, j});
                }
            }
        }
        trees.sort((a, b) -> Integer.compare(a[0], b[0]));
        int totalSteps = 0;
        int currX = 0;
        int currY = 0;
        for (int[] tree : trees) {
            int nextX = tree[1];
            int nextY = tree[2];
            int steps = bfs(forest, currX, currY, nextX, nextY);
            if (steps == -1) {
                return -1;
            }
            totalSteps += steps;
            currX = nextX;
            currY = nextY;
            forest[currX][currY] = 1;
        }
        return totalSteps;
    }

    private static int bfs(int[][] forest, int sx, int sy, int tx, int ty) {
        if (sx == tx && sy == ty) return 0;
        int rows = forest.length;
        int cols = forest[0].length;
        boolean[][] visited = new boolean[rows][cols];
        Queue<int[]> q = new ArrayDeque<>();
        q.offer(new int[]{sx, sy, 0});
        visited[sx][sy] = true;
        int[] dirs = {-1, 0, 1, 0, -1};
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int x = cur[0], y = cur[1], d = cur[2];
            for (int k = 0; k < 4; k++) {
                int nx = x + dirs[k];
                int ny = y + dirs[k + 1];
                if (nx >= 0 && nx < rows && ny >= 0 && ny < cols && !visited[nx][ny] && forest[nx][ny] != 0) {
                    if (nx == tx && ny == ty) {
                        return d + 1;
                    }
                    visited[nx][ny] = true;
                    q.offer(new int[]{nx, ny, d + 1});
                }
            }
        }
        return -1;
    }
}

class Solution {
    public static int findNumberOfLIS(int[] nums) {
        int n = nums.length;
        if (n == 0) {
            return 0;
        }
        int[] lengths = new int[n];
        int[] counts = new int[n];
        for (int i = 0; i < n; i++) {
            lengths[i] = 1;
            counts[i] = 1;
        }
        int maxLength = 1;
        for (int i = 1; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (nums[i] > nums[j]) {
                    if (lengths[j] + 1 > lengths[i]) {
                        lengths[i] = lengths[j] + 1;
                        counts[i] = counts[j];
                    } else if (lengths[j] + 1 == lengths[i]) {
                        counts[i] += counts[j];
                    }
                }
            }
            maxLength = Math.max(maxLength, lengths[i]);
        }
        int totalCount = 0;
        for (int i = 0; i < n; i++) {
            if (lengths[i] == maxLength) {
                totalCount += counts[i];
            }
        }
        return totalCount;
    }
}

