class Solution {
    public static boolean validUtf8(int[] data) {
        int bytesLeft = 0;
        for (int i = 0; i < data.length; i++) {
            String binary = Integer.toBinaryString(data[i] & 0xFF);
            if (binary.length() < 8) {
                binary = "0".repeat(8 - binary.length()) + binary;
            }
            if (bytesLeft == 0) {
                if (binary.charAt(0) == '0') {
                    continue;
                } else if (binary.charAt(0) == '1' && binary.charAt(1) == '1' && binary.charAt(2) == '0') {
                    bytesLeft = 1;
                } else if (binary.charAt(0) == '1' && binary.charAt(1) == '1' && binary.charAt(2) == '1' && binary.charAt(3) == '0') {
                    bytesLeft = 2;
                } else if (binary.charAt(0) == '1' && binary.charAt(1) == '1' && binary.charAt(2) == '1' && binary.charAt(3) == '1' && binary.charAt(4) == '0') {
                    bytesLeft = 3;
                } else {
                    return false;
                }
            } else {
                if (binary.charAt(0) == '1' && binary.charAt(1) == '0') {
                    bytesLeft--;
                } else {
                    return false;
                }
            }
        }
        return bytesLeft == 0;
    }
}

import java.util.*;

class Solution {
    public static int[] maxNumber(int[] nums1, int[] nums2, int k) {
        int[] max = new int[0];
        int start = Math.max(0, k - nums2.length);
        int end = Math.min(k, nums1.length);
        for (int i = start; i <= end; i++) {
            int[] candidate = merge(pickMax(nums1, i), pickMax(nums2, k - i));
            if (greater(candidate, max, 0, 0)) {
                max = candidate;
            }
        }
        return max;
    }

    private static int[] pickMax(int[] nums, int k) {
        int drop = nums.length - k;
        int[] stack = new int[nums.length];
        int top = -1;
        for (int num : nums) {
            while (top >= 0 && drop > 0 && stack[top] < num) {
                top--;
                drop--;
            }
            stack[++top] = num;
        }
        int[] out = new int[k];
        System.arraycopy(stack, 0, out, 0, k);
        return out;
    }

    private static boolean greater(int[] a, int[] b, int aIndex, int bIndex) {
        while (aIndex < a.length && bIndex < b.length) {
            if (a[aIndex] != b[bIndex]) {
                return a[aIndex] > b[bIndex];
            }
            aIndex++;
            bIndex++;
        }
        return aIndex < a.length;
    }

    private static int[] merge(int[] a, int[] b) {
        int[] out = new int[a.length + b.length];
        int i = 0, j = 0, idx = 0;
        while (i < a.length || j < b.length) {
            if (j == b.length || (i < a.length && greater(a, b, i, j))) {
                out[idx++] = a[i++];
            } else {
                out[idx++] = b[j++];
            }
        }
        return out;
    }
}

import java.util.ArrayDeque;

public class Solution {
    public static int shortestPathLength(int[][] graph) {
        int n = graph.length;
        int allNodesVisited = (1 << n) - 1;
        ArrayDeque<int[]> queue = new ArrayDeque<>();
        boolean[][] visited = new boolean[n][1 << n];
        for (int i = 0; i < n; i++) {
            queue.add(new int[]{i, 1 << i, 0});
            visited[i][1 << i] = true;
        }
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int node = cur[0];
            int bitmask = cur[1];
            int distance = cur[2];
            if (bitmask == allNodesVisited) {
                return distance;
            }
            for (int neighbor : graph[node]) {
                int newBitmask = bitmask | (1 << neighbor);
                if (!visited[neighbor][newBitmask]) {
                    queue.add(new int[]{neighbor, newBitmask, distance + 1});
                    visited[neighbor][newBitmask] = true;
                }
            }
        }
        return -1;
    }
}

