class Solution {
    public static boolean possibleBipartition(int n, int[][] dislikes) {
        List<Integer>[] graph = new ArrayList[n + 1];
        for (int i = 0; i <= n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] pair : dislikes) {
            int u = pair[0];
            int v = pair[1];
            graph[u].add(v);
            graph[v].add(u);
        }
        int[] color = new int[n + 1];
        Arrays.fill(color, -1);
        for (int i = 1; i <= n; i++) {
            if (color[i] == -1) {
                if (!dfs(graph, color, i, 0)) {
                    return false;
                }
            }
        }
        return true;
    }

    private static boolean dfs(List<Integer>[] graph, int[] color, int node, int c) {
        if (color[node] != -1) {
            return color[node] == c;
        }
        color[node] = c;
        for (int neighbor : graph[node]) {
            if (!dfs(graph, color, neighbor, 1 - c)) {
                return false;
            }
        }
        return true;
    }
}

