class Solution {
    private static String swap(String s, int i, int j) {
        char[] arr = s.toCharArray();
        char tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
        return new String(arr);
    }

    private static class Node {
        String str;
        int swaps;
        Node(String str, int swaps) {
            this.str = str;
            this.swaps = swaps;
        }
    }

    public static int kSimilarity(String s1, String s2) {
        Deque<Node> queue = new ArrayDeque<>();
        queue.offer(new Node(s1, 0));
        Set<String> visited = new HashSet<>();
        visited.add(s1);
        while (!queue.isEmpty()) {
            Node cur = queue.poll();
            String curr = cur.str;
            int swaps = cur.swaps;
            if (curr.equals(s2)) {
                return swaps;
            }
            for (int i = 0; i < curr.length(); i++) {
                if (curr.charAt(i) != s2.charAt(i)) {
                    for (int j = i + 1; j < curr.length(); j++) {
                        if (curr.charAt(j) == s2.charAt(i)) {
                            String next = swap(curr, i, j);
                            if (!visited.contains(next)) {
                                visited.add(next);
                                queue.offer(new Node(next, swaps + 1));
                            }
                        }
                    }
                    break;
                }
            }
        }
        return -1;
    }
}

