class Solution {
    public static int shortestPathAllKeys(String[] grid) {
        int rows = grid.length;
        int cols = grid[0].length();
        int keys = 0;
        int locks = 0;
        Deque<int[]> queue = new ArrayDeque<>();
        Set<String> visited = new HashSet<>();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                char c = grid[i].charAt(j);
                if (c == '@') {
                    queue.offer(new int[]{i, j, 0, 0});
                    visited.add(i + "," + j + ",0");
                } else if (c >= 'a' && c <= 'f') {
                    keys++;
                } else if (c >= 'A' && c <= 'F') {
                    locks++;
                }
            }
        }
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int x = cur[0];
            int y = cur[1];
            int collectedKeys = cur[2];
            int steps = cur[3];
            if (collectedKeys == (1 << keys) - 1) {
                return steps;
            }
            for (int[] dir : directions) {
                int nx = x + dir[0];
                int ny = y + dir[1];
                if (nx >= 0 && nx < rows && ny >= 0 && ny < cols) {
                    char newCell = grid[nx].charAt(ny);
                    if (newCell == '#') {
                        continue;
                    }
                    if (newCell >= 'a' && newCell <= 'f') {
                        int newCollectedKeys = collectedKeys | (1 << (newCell - 'a'));
                        String state = nx + "," + ny + "," + newCollectedKeys;
                        if (!visited.contains(state)) {
                            visited.add(state);
                            queue.offer(new int[]{nx, ny, newCollectedKeys, steps + 1});
                        }
                    } else if (newCell >= 'A' && newCell <= 'F') {
                        if ((collectedKeys & (1 << (newCell - 'A'))) != 0) {
                            String state = nx + "," + ny + "," + collectedKeys;
                            if (!visited.contains(state)) {
                                visited.add(state);
                                queue.offer(new int[]{nx, ny, collectedKeys, steps + 1});
                            }
                        }
                    } else {
                        String state = nx + "," + ny + "," + collectedKeys;
                        if (!visited.contains(state)) {
                            visited.add(state);
                            queue.offer(new int[]{nx, ny, collectedKeys, steps + 1});
                        }
                    }
                }
            }
        }
        return -1;
    }
}

