public class Solution {
    public static int dieSimulator(int n, int[] rollMax) {
        final int MOD = 1_000_000_007;
        int[][][] dp = new int[n + 1][6][16];
        for (int i = 0; i < 6; i++) {
            dp[1][i][1] = 1;
        }
        for (int i = 2; i <= n; i++) {
            for (int j = 0; j < 6; j++) {
                for (int k = 1; k <= 15; k++) {
                    for (int prev = 0; prev < 6; prev++) {
                        if (prev != j) {
                            dp[i][j][1] = (int) ((dp[i][j][1] + (long) dp[i - 1][prev][k]) % MOD);
                        } else if (k < rollMax[j]) {
                            dp[i][j][k + 1] = (int) ((dp[i][j][k + 1] + (long) dp[i - 1][prev][k]) % MOD);
                        }
                    }
                }
            }
        }
        int res = 0;
        for (int i = 0; i < 6; i++) {
            for (int j = 1; j <= 15; j++) {
                res = (int) ((res + (long) dp[n][i][j]) % MOD);
            }
        }
        return res;
    }
}

