class Solution {
    public static int maxEqualFreq(int[] nums) {
        Map<Integer, Integer> freq = new HashMap<>();
        Map<Integer, Integer> count = new HashMap<>();
        int maxLen = 0;
        for (int i = 0; i < nums.length; i++) {
            int num = nums[i];
            int oldFreq = freq.getOrDefault(num, 0);
            int newFreq = oldFreq + 1;
            freq.put(num, newFreq);
            if (oldFreq > 0) {
                int oldCount = count.get(oldFreq);
                if (oldCount == 1) {
                    count.remove(oldFreq);
                } else {
                    count.put(oldFreq, oldCount - 1);
                }
            }
            count.put(newFreq, count.getOrDefault(newFreq, 0) + 1);
            if (count.size() == 1) {
                int f = count.keySet().iterator().next();
                int c = count.get(f);
                if (f == 1 || c == 1) {
                    maxLen = i + 1;
                }
            } else if (count.size() == 2) {
                Iterator<Integer> it = count.keySet().iterator();
                int f1 = it.next();
                int f2 = it.next();
                int c1 = count.get(f1);
                int c2 = count.get(f2);
                if (f1 > f2) {
                    int tf = f1; f1 = f2; f2 = tf;
                    int tc = c1; c1 = c2; c2 = tc;
                }
                if (f1 == 1 && c1 == 1) {
                    maxLen = i + 1;
                } else if (f2 == f1 + 1 && c2 == 1) {
                    maxLen = i + 1;
                }
            }
        }
        return maxLen;
    }
}

