class Solution {
    public static String minimumInteger(String num, int k) {
        char[] digits = num.toCharArray();
        int n = digits.length;
        for (int i = 0; i < n; i++) {
            int minIndex = i;
            for (int j = i + 1; j <= i + k && j < n; j++) {
                if (digits[j] < digits[minIndex]) {
                    minIndex = j;
                }
            }
            for (int j = minIndex; j > i; j--) {
                char temp = digits[j];
                digits[j] = digits[j - 1];
                digits[j - 1] = temp;
                k--;
            }
            if (k == 0) {
                break;
            }
        }
        return new String(digits);
    }
}

