class Solution {
    public static int minNumberOfSemesters(int n, int[][] relations, int k) {
        List<Integer>[] graph = new ArrayList[n + 1];
        for (int i = 0; i <= n; i++) {
            graph[i] = new ArrayList<>();
        }
        int[] inDegree = new int[n + 1];
        for (int[] rel : relations) {
            int prev = rel[0];
            int next = rel[1];
            graph[prev].add(next);
            inDegree[next]++;
        }
        LinkedList<Integer> queue = new LinkedList<>();
        for (int i = 1; i <= n; i++) {
            if (inDegree[i] == 0) {
                queue.offer(i);
            }
        }
        int visited = 0;
        int result = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            int dequeueCount = 0;
            for (int i = 0; i < size && dequeueCount < k; i++) {
                int node = queue.poll();
                visited++;
                dequeueCount++;
                for (int neighbor : graph[node]) {
                    inDegree[neighbor]--;
                    if (inDegree[neighbor] == 0) {
                        queue.offer(neighbor);
                    }
                }
            }
            if (dequeueCount > 0) {
                result++;
            }
        }
        return result;
    }
}

