class Solution {
    public static long numSubmat(int[][] mat) {
        int m = mat.length;
        int n = mat[0].length;
        int[] height = new int[n];
        long count = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                height[j] = mat[i][j] == 1 ? height[j] + 1 : 0;
            }
            Deque<Integer> stack = new ArrayDeque<>();
            for (int j = 0; j <= n; j++) {
                while (!stack.isEmpty() && (j == n || height[j] < height[stack.peek()])) {
                    int h = height[stack.pop()];
                    int w = stack.isEmpty() ? j : j - stack.peek() - 1;
                    count += (long) h * w;
                }
                stack.push(j);
            }
        }
        return count;
    }
}

