class Solution {
    public static int closestToTarget(int[] arr, int target) {
        int best = Integer.MAX_VALUE;
        int[] prev = new int[32];
        int prevSize = 0;
        int[] cur = new int[32];
        for (int a : arr) {
            int curSize = 0;
            cur[curSize++] = a;
            for (int i = 0; i < prevSize; i++) {
                int v = prev[i] & a;
                if (v != cur[curSize - 1]) {
                    cur[curSize++] = v;
                }
            }
            for (int i = 0; i < curSize; i++) {
                int diff = Math.abs(cur[i] - target);
                if (diff < best) {
                    best = diff;
                    if (best == 0) return 0;
                }
            }
            // swap prev and cur arrays for next iteration
            int[] temp = prev;
            prev = cur;
            cur = temp;
            prevSize = curSize;
        }
        return best;
    }
}

