class Solution {
    static class Edge {
        int to;
        double prob;
        Edge(int to, double prob) {
            this.to = to;
            this.prob = prob;
        }
    }

    public static double maxProbability(int n, int[][] edges, double[] succProb, int start, int end) {
        List<List<Edge>> graph = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }
        for (int i = 0; i < edges.length; i++) {
            int u = edges[i][0];
            int v = edges[i][1];
            double p = succProb[i];
            graph.get(u).add(new Edge(v, p));
            graph.get(v).add(new Edge(u, p));
        }

        double[] maxProb = new double[n];
        maxProb[start] = 1.0;

        PriorityQueue<double[]> pq = new PriorityQueue<>((a, b) -> Double.compare(b[1], a[1]));
        pq.offer(new double[]{start, 1.0});

        while (!pq.isEmpty()) {
            double[] cur = pq.poll();
            int node = (int) cur[0];
            double prob = cur[1];
            if (node == end) {
                return prob;
            }
            if (prob < maxProb[node]) {
                continue;
            }
            for (Edge edge : graph.get(node)) {
                double newProb = prob * edge.prob;
                if (newProb > maxProb[edge.to]) {
                    maxProb[edge.to] = newProb;
                    pq.offer(new double[]{edge.to, newProb});
                }
            }
        }
        return 0.0;
    }
}

