        prefix[0] = candiesCount[0];
        for (int i = 1; i < n; i++) {
            prefix[i] = prefix[i - 1] + candiesCount[i];
        }
        boolean[] ans = new boolean[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int type = queries[i][0];
            int day = queries[i][1];
            int cap = queries[i][2];
            long minTotal = (long) day + 1;
            long maxTotal = (long) (day + 1) * cap;
            long before = type > 0 ? prefix[type - 1] : 0;
            long after = before + candiesCount[type];
            if (maxTotal >= before + 1 && minTotal <= after) {
                ans[i] = true;
            }
        }
        return ans;
    }
}

