public class Solution {
    public static int minimumSize(int[] nums, int maxOperations) {
        int left = 1;
        int right = 0;
        for (int num : nums) {
            if (num > right) {
                right = num;
            }
        }
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (canDivide(mid, nums, maxOperations)) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }

    private static boolean canDivide(int maxBalls, int[] nums, int maxOperations) {
        long operations = 0;
        for (int num : nums) {
            operations += (num + maxBalls - 1) / maxBalls - 1;
        }
        return operations <= maxOperations;
    }
}

