class Solution {
    public static int maxValue(int[][] events, int k) {
        Arrays.sort(events, (a, b) -> Integer.compare(a[0], b[0]));
        int n = events.length;
        int[] next = new int[n];
        for (int i = 0; i < n; i++) {
            int lo = i + 1, hi = n;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (events[mid][0] > events[i][1]) {
                    hi = mid;
                } else {
                    lo = mid + 1;
                }
            }
            next[i] = lo;
        }
        int[][] dp = new int[n + 1][k + 1];
        for (int i = n - 1; i >= 0; i--) {
            for (int j = 1; j <= k; j++) {
                int take = events[i][2] + dp[next[i]][j - 1];
                int skip = dp[i + 1][j];
                dp[i][j] = Math.max(skip, take);
            }
        }
        return dp[0][k];
    }
}

