class Solution {
    public static int secondHighest(String s) {
        Set<Integer> digits = new HashSet<>();
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (Character.isDigit(ch)) {
                digits.add(ch - '0');
