class Solution {
    public static int[] countPairsOfNodes(int n, int[][] edges, int[] queries) {
        int[] degree = new int[n + 1];
        Map<Long, Integer> edgeCount = new HashMap<>();
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            degree[u]++;
            degree[v]++;
            int a = Math.min(u, v);
            int b = Math.max(u, v);
            long key = ((long) a << 32) | b;
            edgeCount.merge(key, 1, Integer::sum);
        }
        int[] deg = new int[n];
        for (int i = 1; i <= n; i++) {
            deg[i - 1] = degree[i];
        }
        Arrays.sort(deg);
        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int q = queries[i];
            long count = 0;
            int l = 0, r = n - 1;
            while (l < r) {
                if (deg[l] + deg[r] > q) {
                    count += (r - l);
                    r--;
                } else {
                    l++;
                }
            }
            for (Map.Entry<Long, Integer> entry : edgeCount.entrySet()) {
                long key = entry.getKey();
                int u = (int) (key >>> 32);
                int v = (int) key;
                int c = entry.getValue();
                if (degree[u] + degree[v] > q && degree[u] + degree[v] - c <= q) {
                    count--;
                }
            }
            ans[i] = (int) count;
        }
        return ans;
    }
}

