class Solution {
    public static int minTrioDegree(int n, int[][] edges) {
        List<Integer>[] graph = new ArrayList[n + 1];
        for (int i = 0; i <= n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            graph[u].add(v);
            graph[v].add(u);
        }
        int minDegree = Integer.MAX_VALUE;
        for (int i = 1; i <= n; i++) {
            for (int j = i + 1; j <= n; j++) {
                if (!graph[i].contains(j)) continue;
                for (int k = j + 1; k <= n; k++) {
                    if (graph[i].contains(k) && graph[j].contains(k)) {
                        int degree = graph[i].size() + graph[j].size() + graph[k].size() - 6;
                        if (degree < minDegree) {
                            minDegree = degree;
                        }
                    }
                }
            }
        }
        return minDegree == Integer.MAX_VALUE ? -1 : minDegree;
    }
}

