public class Solution {
    public static int[] findRedundantDirectedConnection(int[][] edges) {
        int n = edges.length;
        int[] indegreeParent = new int[n + 1];
        int[] cand1 = null;
        int[] cand2 = null;
        for (int[] e : edges) {
            int u = e[0], v = e[1];
            if (indegreeParent[v] != 0) {
                cand1 = new int[]{indegreeParent[v], v};
                cand2 = new int[]{u, v};
            } else {
                indegreeParent[v] = u;
            }
        }
        int[] uf = new int[n + 1];
        for (int i = 1; i <= n; i++) uf[i] = i;
        for (int[] e : edges) {
            if (cand2 != null && e[0] == cand2[0] && e[1] == cand2[1]) continue;
            int uRoot = find(uf, e[0]);
            int vRoot = find(uf, e[1]);
            if (uRoot == vRoot) {
                return cand1 != null ? cand1 : e;
            }
            uf[vRoot] = uRoot;
        }
        return cand2;
    }

    private static int find(int[] uf, int x) {
        while (uf[x] != x) {
            uf[x] = uf[uf[x]];
            x = uf[x];
        }
        return x;
    }
}

