class Solution {
    public static double knightProbability(int n, int k, int row, int column) {
        int[][] moves = {
            {-2, -1}, {-1, -2}, {1, -2}, {2, -1},
            {-2, 1}, {-1, 2}, {1, 2}, {2, 1}
        };
        double[][][] memo = new double[n][n][k + 1];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                Arrays.fill(memo[i][j], -1.0);
            }
        }
        return dfs(row, column, k, n, moves, memo);
    }

    private static double dfs(int x, int y, int movesLeft, int n, int[][] moves, double[][][] memo) {
        if (x < 0 || x >= n || y < 0 || y >= n) {
            return 0.0;
        }
        if (movesLeft == 0) {
            return 1.0;
        }
        if (memo[x][y][movesLeft] != -1.0) {
            return memo[x][y][movesLeft];
        }
        double probability = 0.0;
        for (int[] move : moves) {
            probability += dfs(x + move[0], y + move[1], movesLeft - 1, n, moves, memo) / 8.0;
        }
        memo[x][y][movesLeft] = probability;
        return probability;
    }
}

