class Solution {
    public static int[] maxSumOfThreeSubarrays(int[] nums, int k) {
        int n = nums.length;
        int[] prefixSum = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + nums[i];
        }
        int[] sum1 = new int[n - k + 1];
        for (int i = 0; i <= n - k; i++) {
            sum1[i] = prefixSum[i + k] - prefixSum[i];
        }
        int[] sum2 = new int[n - 2 * k + 1];
        for (int i = 0; i <= n - 2 * k; i++) {
            int maxSum = Integer.MIN_VALUE;
            for (int j = i + k; j <= n - k; j++) {
                int candidate = sum1[i] + sum1[j];
                if (candidate > maxSum) {
                    maxSum = candidate;
                }
            }
            sum2[i] = maxSum;
        }
        int maxSum = Integer.MIN_VALUE;
        int[] result = new int[3];
        boolean first = true;
        for (int i = 0; i <= n - 3 * k; i++) {
            for (int j = i + k; j <= n - 2 * k; j++) {
                for (int m = j + k; m <= n - k; m++) {
                    int currentSum = sum1[i] + sum1[j] + sum1[m];
                    if (first || currentSum > maxSum) {
                        maxSum = currentSum;
                        result[0] = i;
                        result[1] = j;
                        result[2] = m;
                        first = false;
                    } else if (currentSum == maxSum) {
                        if (i < result[0] || (i == result[0] && j < result[1]) || (i == result[0] && j == result[1] && m < result[2])) {
                            result[0] = i;
                            result[1] = j;
                            result[2] = m;
                        }
                    }
                }
            }
        }
        return result;
    }
}

