class Solution {
    public static int minStickers(String[] stickers, String target) {
        int n = stickers.length;
        int[][] stickerCounts = new int[n][26];
        for (int i = 0; i < n; i++) {
            for (char c : stickers[i].toCharArray()) {
                stickerCounts[i][c - 'a']++;
            }
        }
        Map<String, Integer> memo = new HashMap<>();
        return dfs(buildCountString(target), stickerCounts, memo);
    }

    private static String buildCountString(String s) {
        int[] cnt = new int[26];
        for (char c : s.toCharArray()) cnt[c - 'a']++;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 26; i++) {
            for (int k = 0; k < cnt[i]; k++) sb.append((char) ('a' + i));
        }
        return sb.toString();
    }

    private static int dfs(String target, int[][] stickers, Map<String, Integer> memo) {
        if (target.isEmpty()) return 0;
        if (memo.containsKey(target)) return memo.get(target);
        int[] targetCnt = new int[26];
        for (char c : target.toCharArray()) targetCnt[c - 'a']++;
        int ans = Integer.MAX_VALUE;
        for (int[] sticker : stickers) {
            if (sticker[target.charAt(0) - 'a'] == 0) continue;
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 26; i++) {
                int remain = targetCnt[i] - sticker[i];
                for (int k = 0; k < Math.max(0, remain); k++) sb.append((char) ('a' + i));
            }
            String next = sb.toString();
            int sub = dfs(next, stickers, memo);
            if (sub != -1) ans = Math.min(ans, sub + 1);
        }
        int res = ans == Integer.MAX_VALUE ? -1 : ans;
        memo.put(target, res);
        return res;
    }
}

