class Solution {
    private static class Info {
        int frequency;
        int firstIndex;
        int lastIndex;
        Info(int index) {
            this.frequency = 0;
            this.firstIndex = index;
            this.lastIndex = index;
        }
    }

    public static int findShortestSubArray(int[] nums) {
        if (nums == null || nums.length == 0) {
            return 0;
        }
        Map<Integer, Info> map = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            int val = nums[i];
            Info info = map.get(val);
            if (info == null) {
                info = new Info(i);
                map.put(val, info);
            }
            info.frequency++;
            info.lastIndex = i;
        }
        int maxFrequency = 0;
        for (Info info : map.values()) {
            if (info.frequency > maxFrequency) {
                maxFrequency = info.frequency;
            }
        }
        int minLength = Integer.MAX_VALUE;
        for (Info info : map.values()) {
            if (info.frequency == maxFrequency) {
                int length = info.lastIndex - info.firstIndex + 1;
                if (length < minLength) {
                    minLength = length;
                }
            }
        }
        return minLength;
    }
}

import java.util.Arrays;

class Solution {
    public static boolean canPartitionKSubsets(int[] nums, int k) {
        int totalSum = 0;
        for (int num : nums) totalSum += num;
        if (totalSum % k != 0) return false;
        int targetSum = totalSum / k;
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        int n = sorted.length;
        int[] desc = new int[n];
        for (int i = 0; i < n; i++) desc[i] = sorted[n - 1 - i];
        int[] subsetSums = new int[k];
        return backtrack(0, desc, subsetSums, targetSum, k);
    }

    private static boolean backtrack(int index, int[] nums, int[] subsetSums, int targetSum, int k) {
        if (index == nums.length) {
            for (int sum : subsetSums) {
                if (sum != targetSum) return false;
            }
            return true;
        }
        int current = nums[index];
        for (int i = 0; i < k; i++) {
            if (subsetSums[i] + current > targetSum) continue;
            subsetSums[i] += current;
            if (backtrack(index + 1, nums, subsetSums, targetSum, k)) return true;
            subsetSums[i] -= current;
        }
        return false;
    }
}

