class Solution {
    public static int[] fallingSquares(int[][] positions) {
        List<int[]> heights = new ArrayList<>();
        int[] ans = new int[positions.length];
        int max = 0;
        for (int i = 0; i < positions.length; i++) {
            int left = positions[i][0];
            int side = positions[i][1];
            int right = left + side;
            int height = 0;
            for (int j = 0; j < heights.size(); j++) {
                int[] h = heights.get(j);
                if (h[0] < right && h[1] > left) {
                    height = Math.max(height, h[2]);
                }
            }
            height += side;
            heights.add(new int[]{left, right, height});
            max = Math.max(max, height);
            ans[i] = max;
        }
        return ans;
    }
}

