class Solution {
    public static long numSubarrayProductLessThanK(int[] nums, int k) {
        long count = 0;
        double product = 1.0;
        int left = 0;
        for (int right = 0; right < nums.length; right++) {
            product *= nums[right];
            while (product >= k && left <= right) {
                product /= nums[left];
                left++;
            }
            count += right - left + 1;
        }
        return count;
    }
}

public class Solution {
    public static int maxProfit(int[] prices, int fee) {
        int hold = -prices[0];
        int sold = 0;
        for (int i = 1; i < prices.length; i++) {
            int newHold = Math.max(hold, sold - prices[i]);
            int newSold = Math.max(sold, hold + prices[i] - fee);
            hold = newHold;
            sold = newSold;
        }
        return sold;
    }
}

