class RangeModule {
    private List<int[]> intervals;
    public RangeModule() { intervals = new ArrayList<>(); }
    public void addRange(int left, int right) {
        List<int[]> newIntervals = new ArrayList<>();
        boolean placed = false;
        for (int[] interval : intervals) {
            int l = interval[0], r = interval[1];
            if (r < left) newIntervals.add(new int[]{l,r});
            else if (right < l) {
                if (!placed) { newIntervals.add(new int[]{left,right}); placed = true; }
                newIntervals.add(new int[]{l,r});
            } else {
                left = Math.min(left,l); right = Math.max(right,r);
            }
        }
        if (!placed) newIntervals.add(new int[]{left,right});
        intervals = newIntervals;
    }
    public boolean queryRange(int left, int right) {
        for (int[] interval : intervals) if (interval[0]<=left && right<=interval[1]) return true;
        return false;
    }
    public void removeRange(int left, int right) {
        List<int[]> newIntervals = new ArrayList<>();
        for (int[] interval : intervals) {
            int l = interval[0], r = interval[1];
            if (r <= left || right <= l) newIntervals.add(new int[]{l,r});
            else {
                if (l < left) newIntervals.add(new int[]{l,left});
                if (right < r) newIntervals.add(new int[]{right,r});
            }
        }
        intervals = newIntervals;
    }
}

