class Solution {
    public static List<String> removeComments(String[] source) {
        List<String> result = new ArrayList<>();
        boolean blockComment = false;
        StringBuilder currentLine = new StringBuilder();
        for (int i = 0; i < source.length; i++) {
            String line = source[i];
            int j = 0;
            while (j < line.length()) {
                if (!blockComment && j + 1 < line.length() && line.charAt(j) == '/' && line.charAt(j + 1) == '*') {
                    blockComment = true;
                    j += 2;
                } else if (blockComment && j + 1 < line.length() && line.charAt(j) == '*' && line.charAt(j + 1) == '/') {
                    blockComment = false;
                    j += 2;
                } else if (!blockComment && j + 1 < line.length() && line.charAt(j) == '/' && line.charAt(j + 1) == '/') {
                    break;
                } else if (!blockComment) {
                    currentLine.append(line.charAt(j));
                    j++;
                } else {
                    j++;
                }
            }
            if (!blockComment) {
                String trimmed = currentLine.toString().trim();
                if (!trimmed.isEmpty()) {
                    result.add(trimmed);
                    currentLine.setLength(0);
                }
            }
        }
        return result;
    }
}

