class Solution {
    public static List<List<String>> accountsMerge(List<List<String>> accounts) {
        Map<String, String> parent = new HashMap<>();
        Map<String, String> name = new HashMap<>();
        for (List<String> account : accounts) {
            String personName = account.get(0);
            for (int i = 1; i < account.size(); i++) {
                String email = account.get(i);
                parent.put(email, email);
                name.put(email, personName);
            }
        }
        for (List<String> account : accounts) {
            for (int i = 1; i < account.size() - 1; i++) {
                union(account.get(i), account.get(i + 1), parent);
            }
        }
        Map<String, List<String>> merged = new HashMap<>();
        for (String email : parent.keySet()) {
            String parentEmail = find(email, parent);
            merged.computeIfAbsent(parentEmail, k -> new ArrayList<>()).add(email);
        }
        List<List<String>> result = new ArrayList<>();
        for (Map.Entry<String, List<String>> entry : merged.entrySet()) {
            List<String> emails = entry.getValue();
            Collections.sort(emails);
            List<String> mergedAccount = new ArrayList<>();
            mergedAccount.add(name.get(entry.getKey()));
            mergedAccount.addAll(emails);
            result.add(mergedAccount);
        }
        return result;
    }

    private static String find(String email, Map<String, String> parent) {
        if (parent.get(email).equals(email)) {
            return email;
        }
        String root = find(parent.get(email), parent);
        parent.put(email, root);
        return root;
    }

    private static void union(String email1, String email2, Map<String, String> parent) {
        String parent1 = find(email1, parent);
        String parent2 = find(email2, parent);
        if (!parent1.equals(parent2)) {
            parent.put(parent1, parent2);
        }
    }
}

class Solution {
    public static int pivotIndex(int[] nums) {
        int totalSum = 0;
        for (int i = 0; i < nums.length; i++) {
            totalSum += nums[i];
        }
        int leftSum = 0;
        for (int i = 0; i < nums.length; i++) {
            if (leftSum == totalSum - leftSum - nums[i]) {
                return i;
            }
            leftSum += nums[i];
        }
        return -1;
    }
}

