class ListNode {
    int val;
    ListNode next;
    ListNode(int x) { val = x; }
}

class Solution {
    public ListNode[] splitListToParts(ListNode head, int k) {
        int length = 0;
        ListNode temp = head;
        while (temp != null) {
            length++;
            temp = temp.next;
        }
        int size = length / k;
        int remainder = length % k;
        ListNode[] result = new ListNode[k];
        temp = head;
        for (int i = 0; i < k; i++) {
            int partSize = size + (i < remainder ? 1 : 0);
            ListNode partHead = temp;
            ListNode prev = null;
            for (int j = 0; j < partSize; j++) {
                prev = temp;
                temp = temp.next;
            }
            if (prev != null) prev.next = null;
            result[i] = partHead;
        }
        return result;
    }
}

