public class Solution {
    public static String countOfAtoms(String formula) {
        Deque<Map<String, Integer>> stack = new ArrayDeque<>();
        stack.push(new HashMap<>());
        int i = 0;
        int n = formula.length();
        while (i < n) {
            char ch = formula.charAt(i);
            if (Character.isUpperCase(ch)) {
                StringBuilder nameBuilder = new StringBuilder();
                nameBuilder.append(ch);
                i++;
                while (i < n && Character.isLowerCase(formula.charAt(i))) {
                    nameBuilder.append(formula.charAt(i));
                    i++;
                }
                String name = nameBuilder.toString();
                int count = 0;
                while (i < n && Character.isDigit(formula.charAt(i))) {
                    count = count * 10 + (formula.charAt(i) - '0');
                    i++;
                }
                if (count == 0) {
                    count = 1;
                }
                Map<String, Integer> current = stack.peek();
                current.put(name, current.getOrDefault(name, 0) + count);
            } else if (ch == '(') {
                stack.push(new HashMap<>());
                i++;
            } else if (ch == ')') {
                i++;
                int count = 0;
                while (i < n && Character.isDigit(formula.charAt(i))) {
                    count = count * 10 + (formula.charAt(i) - '0');
                    i++;
                }
                if (count == 0) {
                    count = 1;
                }
                Map<String, Integer> temp = stack.pop();
                Map<String, Integer> parent = stack.peek();
                for (Map.Entry<String, Integer> entry : temp.entrySet()) {
                    String name = entry.getKey();
                    int val = entry.getValue() * count;
                    parent.put(name, parent.getOrDefault(name, 0) + val);
                }
            } else {
                i++;
            }
        }
        Map<String, Integer> finalMap = stack.pop();
        List<String> keys = new ArrayList<>(finalMap.keySet());
        Collections.sort(keys);
        StringBuilder result = new StringBuilder();
        for (String name : keys) {
            result.append(name);
            int cnt = finalMap.get(name);
            if (cnt > 1) {
                result.append(cnt);
            }
        }
        return result.toString();
    }
}

