            if (isSelfDividing(i)) {
                result.add(i);
            }
        }
        return result;
    }

    private static boolean isSelfDividing(int num) {
        int temp = num;
        while (temp > 0) {
            int digit = temp % 10;
            if (digit == 0 || num % digit != 0) {
                return false;
            }
            temp /= 10;
        }
        return true;
    }
}

