class Solution {
    public static long countPalindromicSubsequences(String s) {
        final long MOD = 1_000_000_007L;
        int n = s.length();
        if (n == 0) return 0;
        long[][] dp = new long[n][n];
        int[][] next = new int[n][4];
        int[][] prev = new int[n][4];
        int[] nextPos = new int[4];
        Arrays.fill(nextPos, -1);
        for (int i = n - 1; i >= 0; i--) {
            nextPos[s.charAt(i) - 'a'] = i;
            for (int c = 0; c < 4; c++) {
                next[i][c] = nextPos[c];
            }
        }
        int[] prevPos = new int[4];
        Arrays.fill(prevPos, -1);
        for (int i = 0; i < n; i++) {
            prevPos[s.charAt(i) - 'a'] = i;
            for (int c = 0; c < 4; c++) {
                prev[i][c] = prevPos[c];
            }
        }
        for (int i = 0; i < n; i++) dp[i][i] = 1;
        for (int len = 2; len <= n; len++) {
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1;
                if (s.charAt(i) != s.charAt(j)) {
                    dp[i][j] = (dp[i + 1][j] + dp[i][j - 1] - dp[i + 1][j - 1]) % MOD;
                } else {
                    int c = s.charAt(i) - 'a';
                    int i2 = next[i + 1][c];
                    int j2 = prev[j - 1][c];
                    if (i2 == -1 || i2 > j2) {
                        dp[i][j] = (dp[i + 1][j - 1] * 2 + 2) % MOD;
                    } else if (i2 == j2) {
                        dp[i][j] = (dp[i + 1][j - 1] * 2 + 1) % MOD;
                    } else {
                        dp[i][j] = (dp[i + 1][j - 1] * 2 - dp[i2 + 1][j2 - 1]) % MOD;
                    }
                }
                if (dp[i][j] < 0) dp[i][j] += MOD;
            }
        }
        return dp[0][n - 1];
    }
}

