        if (row < 0 || row >= image.length || col < 0 || col >= image[0].length || image[row][col] != originalColor) {
            return;
        }
        image[row][col] = color;
        for (int[] direction : directions) {
            dfs(image, row + direction[0], col + direction[1], originalColor, color, directions);
        }
    }
}

