import java.util.Deque;

class Solution {
    public static int[] asteroidCollision(int[] asteroids) {
        Deque<Integer> stack = new ArrayDeque<>();
        for (int a : asteroids) {
            boolean alive = true;
            while (alive && a < 0 && !stack.isEmpty() && stack.peekLast() > 0) {
                int top = stack.peekLast();
                if (top < -a) {
                    stack.removeLast();
                } else if (top == -a) {
                    stack.removeLast();
                    alive = false;
                } else {
                    alive = false;
                }
            }
            if (alive) {
                stack.addLast(a);
            }
        }
        int[] result = new int[stack.size()];
        int i = 0;
        for (int v : stack) {
            result[i++] = v;
        }
        return result;
    }
}

import java.util.*;

class Solution {
    private static int idx;
    private static Map<String, Deque<Integer>> env;

    public static int evaluate(String expression) {
        idx = 0;
        env = new HashMap<>();
        return eval(expression);
    }

    private static int eval(String s) {
        skipSpaces(s);
        if (s.charAt(idx) == '(') {
            idx++; // skip '('
            skipSpaces(s);
            String op = nextToken(s);
            if ("let".equals(op)) {
                List<String> assigned = new ArrayList<>();
                while (true) {
                    skipSpaces(s);
                    if (s.charAt(idx) == ')') {
                        idx++; // skip ')'
                        break;
                    }
                    if (s.charAt(idx) == '(') {
                        int val = eval(s);
                        for (String var : assigned) {
                            Deque<Integer> stack = env.get(var);
                            stack.pop();
                            if (stack.isEmpty()) env.remove(var);
                        }
                        skipSpaces(s);
                        idx++; // skip ')'
                        return val;
                    }
                    String token = nextToken(s);
                    skipSpaces(s);
                    if (s.charAt(idx) == ')') {
                        int val = getValue(token);
                        for (String var : assigned) {
                            Deque<Integer> stack = env.get(var);
                            stack.pop();
                            if (stack.isEmpty()) env.remove(var);
                        }
                        idx++; // skip ')'
                        return val;
                    } else {
                        String var = token;
                        int val = eval(s);
                        env.computeIfAbsent(var, k -> new ArrayDeque<>()).push(val);
                        assigned.add(var);
                    }
                }
                return 0;
            } else if ("add".equals(op)) {
                int v1 = eval(s);
                int v2 = eval(s);
                skipSpaces(s);
                idx++; // skip ')'
                return v1 + v2;
            } else { // mult
                int v1 = eval(s);
                int v2 = eval(s);
                skipSpaces(s);
                idx++; // skip ')'
                return v1 * v2;
            }
        } else {
            String token = nextToken(s);
            return getValue(token);
        }
    }

    private static String nextToken(String s) {
        skipSpaces(s);
        int start = idx;
        while (idx < s.length() && s.charAt(idx) != ' ' && s.charAt(idx) != ')') {
            idx++;
        }
        return s.substring(start, idx);
    }

    private static void skipSpaces(String s) {
        while (idx < s.length() && s.charAt(idx) == ' ') idx++;
    }

    private static int getValue(String token) {
        if (token.charAt(0) == '-' || Character.isDigit(token.charAt(0))) {
            return Integer.parseInt(token);
        }
        return env.get(token).peek();
    }
}

