class Solution {
    public static int deleteAndEarn(int[] nums) {
        if (nums == null || nums.length == 0) {
            return 0;
        }
        Map<Integer, Integer> frequencyMap = new HashMap<>();
        for (int num : nums) {
            frequencyMap.put(num, frequencyMap.getOrDefault(num, 0) + 1);
        }
        int maxNum = Collections.max(frequencyMap.keySet());
        int[] dp = new int[maxNum + 1];
        dp[0] = 0;
        dp[1] = frequencyMap.getOrDefault(1, 0);
        for (int i = 2; i <= maxNum; i++) {
            int earn = frequencyMap.getOrDefault(i, 0) * i;
            dp[i] = Math.max(dp[i - 1], dp[i - 2] + earn);
        }
        return dp[maxNum];
    }
}

import java.util.*;

class Solution {
    public static int cherryPickup(int[][] grid) {
        int n = grid.length;
        int maxStep = 2 * n - 2;
        int[][][] memo = new int[maxStep + 1][n][n];
        for (int k = 0; k <= maxStep; k++) {
            for (int i = 0; i < n; i++) {
                Arrays.fill(memo[k][i], Integer.MIN_VALUE);
            }
        }
        int result = dfs(0, 0, 0, grid, memo);
        return Math.max(0, result);
    }

    private static int dfs(int k, int c1, int c2, int[][] grid, int[][][] memo) {
        int n = grid.length;
        int r1 = k - c1;
        int r2 = k - c2;
        if (r1 < 0 || r1 >= n || c1 < 0 || c1 >= n ||
            r2 < 0 || r2 >= n || c2 < 0 || c2 >= n) {
            return Integer.MIN_VALUE;
        }
        if (grid[r1][c1] == -1 || grid[r2][c2] == -1) {
            return Integer.MIN_VALUE;
        }
        if (k == 2 * n - 2) {
            return (c1 == c2) ? grid[r1][c1] : grid[r1][c1] + grid[r2][c2];
        }
        if (memo[k][c1][c2] != Integer.MIN_VALUE) {
            return memo[k][c1][c2];
        }
        int best = Integer.MIN_VALUE;
        for (int d1 = 0; d1 <= 1; d1++) {
            for (int d2 = 0; d2 <= 1; d2++) {
                int next = dfs(k + 1, c1 + d1, c2 + d2, grid, memo);
                if (next == Integer.MIN_VALUE) continue;
                int add = grid[r1][c1];
                if (c1 != c2) add += grid[r2][c2];
                best = Math.max(best, next + add);
            }
        }
        memo[k][c1][c2] = best;
        return best;
    }
}

