class Solution {
    public static int minCostClimbingStairs(int[] cost) {
        int minCostToReachPreviousStep = cost[0];
        int minCostToReachCurrentStep = cost[1];
        for (int i = 2; i < cost.length; i++) {
            int temp = minCostToReachCurrentStep;
            minCostToReachCurrentStep = Math.min(minCostToReachPreviousStep, minCostToReachCurrentStep) + cost[i];
            minCostToReachPreviousStep = temp;
        }
        return Math.min(minCostToReachPreviousStep, minCostToReachCurrentStep);
    }
}

