class Solution {
    public static int openLock(String[] deadends, String target) {
        Set<String> dead = new HashSet<>(Arrays.asList(deadends));
        if (dead.contains("0000")) return -1;
        Queue<Pair> queue = new ArrayDeque<>();
        queue.offer(new Pair("0000", 0));
        Set<String> visited = new HashSet<>();
        visited.add("0000");
        while (!queue.isEmpty()) {
            Pair cur = queue.poll();
            String state = cur.state;
            int turns = cur.turns;
            if (state.equals(target)) return turns;
            for (int i = 0; i < 4; i++) {
                char[] chars = state.toCharArray();
                chars[i] = (char) ((state.charAt(i) - '0' + 1) % 10 + '0');
                String nextState = new String(chars);
                if (!dead.contains(nextState) && !visited.contains(nextState)) {
                    queue.offer(new Pair(nextState, turns + 1));
                    visited.add(nextState);
                }
                chars[i] = (char) ((state.charAt(i) - '0' - 1 + 10) % 10 + '0');
                nextState = new String(chars);
                if (!dead.contains(nextState) && !visited.contains(nextState)) {
                    queue.offer(new Pair(nextState, turns + 1));
                    visited.add(nextState);
                }
            }
        }
        return -1;
    }

    private static class Pair {
        String state;
        int turns;
        Pair(String s, int t) {
            this.state = s;
            this.turns = t;
        }
    }
}

