class Solution {
    public static int containVirus(int[][] isInfected) {
        int m = isInfected.length;
        int n = isInfected[0].length;
        int walls = 0;
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (true) {
            List<List<int[]>> regions = new ArrayList<>();
            List<Set<String>> fronts = new ArrayList<>();
            List<Integer> wallsNeeded = new ArrayList<>();
            boolean[][] visited = new boolean[m][n];
            for (int i = 0; i < m; i++) {
                for (int j = 0; j < n; j++) {
                    if (isInfected[i][j] == 1 && !visited[i][j]) {
                        List<int[]> region = new ArrayList<>();
                        Set<String> front = new HashSet<>();
                        int wallCount = 0;
                        Deque<int[]> queue = new ArrayDeque<>();
                        queue.add(new int[]{i, j});
                        visited[i][j] = true;
                        while (!queue.isEmpty()) {
                            int[] cur = queue.poll();
                            int x = cur[0];
                            int y = cur[1];
                            region.add(cur);
                            for (int[] d : dirs) {
                                int nx = x + d[0];
                                int ny = y + d[1];
                                if (nx >= 0 && nx < m && ny >= 0 && ny < n) {
                                    if (isInfected[nx][ny] == 1 && !visited[nx][ny]) {
                                        queue.add(new int[]{nx, ny});
                                        visited[nx][ny] = true;
                                    } else if (isInfected[nx][ny] == 0) {
                                        wallCount++;
                                        front.add(nx + "," + ny);
                                    }
                                }
                            }
                        }
                        regions.add(region);
                        fronts.add(front);
                        wallsNeeded.add(wallCount);
                    }
                }
            }
            if (regions.isEmpty()) {
                break;
            }
            int maxThreatIdx = 0;
            int maxThreat = 0;
            for (int i = 0; i < fronts.size(); i++) {
                if (fronts.get(i).size() > maxThreat) {
                    maxThreat = fronts.get(i).size();
                    maxThreatIdx = i;
                }
            }
            walls += wallsNeeded.get(maxThreatIdx);
            for (int i = 0; i < regions.size(); i++) {
                if (i == maxThreatIdx) continue;
                for (int[] cell : regions.get(i)) {
                    int x = cell[0];
                    int y = cell[1];
                    for (int[] d : dirs) {
                        int nx = x + d[0];
                        int ny = y + d[1];
                        if (nx >= 0 && nx < m && ny >= 0 && ny < n && isInfected[nx][ny] == 0) {
                            isInfected[nx][ny] = 1;
                        }
                    }
                }
            }
            for (int[] cell : regions.get(maxThreatIdx)) {
                isInfected[cell[0]][cell[1]] = -1;
            }
        }
        return walls;
    }
}

class Solution {
    public static boolean validPalindrome(String s) {
        int left = 0, right = s.length() - 1;
        while (left < right) {
            if (s.charAt(left) != s.charAt(right)) {
                return isPalindrome(s, left + 1, right) || isPalindrome(s, left, right - 1);
            }
            left++;
            right--;
        }
        return true;
    }

    private static boolean isPalindrome(String s, int left, int right) {
        while (left < right) {
            if (s.charAt(left) != s.charAt(right)) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }
}

