class Solution {
    public static int findKthNumber(int m, int n, int k) {
        long left = 1;
        long right = (long) m * n;
        while (left < right) {
            long mid = (left + right) / 2;
            long count = 0;
            int j = n;
            for (int i = 1; i <= m; i++) {
                while (j >= 1 && (long) i * j > mid) {
                    j--;
                }
                count += j;
            }
            if (count < k) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return (int) left;
    }
}

