class Solution {
    public static boolean judgePoint24(double[] cards) {
        List<Double> list = new ArrayList<>();
        for (double v : cards) {
            list.add(v);
        }
        return dfs(list);
    }

    private static boolean dfs(List<Double> nums) {
        if (nums.size() == 1) {
            return Math.abs(nums.get(0) - 24) < 1e-6;
        }
        int n = nums.size();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                double a = nums.get(i);
                double b = nums.get(j);
                List<Double> rest = new ArrayList<>();
                for (int k = 0; k < n; k++) {
                    if (k != i && k != j) {
                        rest.add(nums.get(k));
                    }
                }
                List<Double> next = new ArrayList<>(rest);
                next.add(a + b);
                if (dfs(next)) return true;
                next = new ArrayList<>(rest);
                next.add(a - b);
                if (dfs(next)) return true;
                next = new ArrayList<>(rest);
                next.add(b - a);
                if (dfs(next)) return true;
                if (a * b != 0) {
                    next = new ArrayList<>(rest);
                    next.add(a * b);
                    if (dfs(next)) return true;
                }
                if (b != 0) {
                    next = new ArrayList<>(rest);
                    next.add(a / b);
                    if (dfs(next)) return true;
                }
                if (a != 0) {
                    next = new ArrayList<>(rest);
                    next.add(b / a);
                    if (dfs(next)) return true;
                }
            }
        }
        return false;
    }
}

