class Solution {
    public static String findClosestPalindrome(String n) {
        long num = Long.parseLong(n);
        int len = n.length();
        Set<String> candidates = new HashSet<>();

        // Edge cases: 10...01 and 9...9
        StringBuilder sb = new StringBuilder("1");
        for (int i = 0; i < len - 1; i++) sb.append('0');
        sb.append('1');
        candidates.add(sb.toString());

        sb = new StringBuilder();
        for (int i = 0; i < len - 1; i++) sb.append('9');
        if (sb.length() == 0) sb.append('0');
        candidates.add(sb.toString());

        // Prefix based candidates
        int prefixLen = (len + 1) / 2;
        long prefixNum = Long.parseLong(n.substring(0, prefixLen));
        for (int delta = -1; delta <= 1; delta++) {
            long newPrefix = prefixNum + delta;
            if (newPrefix < 0) continue;
            String prefixStr = Long.toString(newPrefix);
            StringBuilder pal = new StringBuilder(prefixStr);
            int start = (len % 2 == 0) ? prefixStr.length() - 1 : prefixStr.length() - 2;
            for (int i = start; i >= 0; i--) {
                pal.append(prefixStr.charAt(i));
            }
            candidates.add(pal.toString());
        }

        String best = "";
        long bestDiff = Long.MAX_VALUE;
        for (String cand : candidates) {
            if (cand.equals(n)) continue;
            long candNum = Long.parseLong(cand);
            long diff = Math.abs(candNum - num);
            if (diff < bestDiff || (diff == bestDiff && candNum < Long.parseLong(best))) {
                bestDiff = diff;
                best = cand;
            }
        }
        return best;
    }
}

