class Solution {
    public static String shortestCompletingWord(String licensePlate, String[] words) {
        Map<Character, Integer> licensePlateMap = new HashMap<>();
        for (char ch : licensePlate.toCharArray()) {
            if (Character.isLetter(ch)) {
                char lower = Character.toLowerCase(ch);
                licensePlateMap.put(lower, licensePlateMap.getOrDefault(lower, 0) + 1);
            }
        }

        String shortestWord = null;
        int shortestLength = Integer.MAX_VALUE;

        for (String word : words) {
            Map<Character, Integer> wordMap = new HashMap<>();
            for (char ch : word.toCharArray()) {
                char lower = Character.toLowerCase(ch);
                wordMap.put(lower, wordMap.getOrDefault(lower, 0) + 1);
            }

            boolean isCompletingWord = true;
            for (Map.Entry<Character, Integer> entry : licensePlateMap.entrySet()) {
                char c = entry.getKey();
                int required = entry.getValue();
                if (wordMap.getOrDefault(c, 0) < required) {
                    isCompletingWord = false;
                    break;
                }
            }

            if (isCompletingWord && word.length() < shortestLength) {
                shortestWord = word;
                shortestLength = word.length();
            }
        }

        return shortestWord;
    }
}

class Solution {
    public static int countPrimeSetBits(int left, int right) {
        int count = 0;
        for (int i = left; i <= right; i++) {
            int setBits = Integer.toBinaryString(i).split("1", -1).length - 1;
            if (isPrime(setBits)) {
                count++;
            }
        }
        return count;
    }
    private static boolean isPrime(int n) {
        if (n <= 1) return false;
        if (n <= 3) return true;
        if (n % 2 == 0 || n % 3 == 0) return false;
        for (int i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) return false;
        }
        return true;
    }
}

