class Solution {
    public static int minSwapsCouples(int[] row) {
        int n = row.length;
        int swaps = 0;
        for (int i = 0; i < n; i += 2) {
            if ((row[i] % 2 == 0 && row[i + 1] == row[i] + 1) || (row[i] % 2 == 1 && row[i + 1] == row[i] - 1)) {
                continue;
            }
            for (int j = i + 1; j < n; j++) {
                if ((row[i] % 2 == 0 && row[j] == row[i] + 1) || (row[i] % 2 == 1 && row[j] == row[i] - 1)) {
                    int temp = row[i + 1];
                    row[i + 1] = row[j];
                    row[j] = temp;
                    swaps++;
                    break;
                }
            }
        }
        return swaps;
    }
}

