class Solution {
    public static String reorganizeString(String s) {
        Map<Character, Integer> charFrequency = new HashMap<>();
        for (char c : s.toCharArray()) {
            charFrequency.put(c, charFrequency.getOrDefault(c, 0) + 1);
        }

        List<int[]> maxHeap = new ArrayList<>();
        for (Map.Entry<Character, Integer> entry : charFrequency.entrySet()) {
            maxHeap.add(new int[]{entry.getKey(), entry.getValue()});
        }
        maxHeap.sort((a, b) -> b[1] - a[1]);

        StringBuilder result = new StringBuilder();

        while (!maxHeap.isEmpty()) {
            if (result.length() > 0 && result.charAt(result.length() - 1) == (char) maxHeap.get(0)[0]) {
                if (maxHeap.size() == 1) {
                    return "";
                }
                int[] temp = maxHeap.get(0);
                maxHeap.set(0, maxHeap.get(1));
                maxHeap.set(1, temp);
            }

            int[] top = maxHeap.get(0);
            char ch = (char) top[0];
            int frequency = top[1];
            result.append(ch);
            top[1]--;

            if (top[1] == 0) {
                maxHeap.remove(0);
            }

            if (!maxHeap.isEmpty()) {
                maxHeap.sort((a, b) -> b[1] - a[1]);
            }
        }

        return result.toString();
    }
}

