        for (String pattern : allowed) {
            String key = pattern.substring(0, 2);
            char val = pattern.charAt(2);
            map.computeIfAbsent(key, k -> new ArrayList<>()).add(val);
        }

        List<String> currentRow = new ArrayList<>();
        currentRow.add(bottom);

        while (currentRow.get(0).length() > 1) {
            List<String> nextRow = new ArrayList<>();
            for (String row : currentRow) {
                Set<String> set = new HashSet<>();
                generateNextRows(row, 0, "", set, map);
                for (String next : set) {
                    nextRow.add(next);
                }
            }
            currentRow = nextRow;
            if (currentRow.isEmpty()) {
                return false;
            }
        }
        return true;
    }

    private static void generateNextRows(String row, int idx, String path, Set<String> set, Map<String, List<Character>> map) {
        if (idx == row.length() - 1) {
            set.add(path);
            return;
        }
        String key = row.substring(idx, idx + 2);
        List<Character> list = map.get(key);
        if (list == null) {
            return;
        }
        for (char c : list) {
            generateNextRows(row, idx + 1, path + c, set, map);
        }
    }
}

public class Solution {
