import java.util.*;

class Solution {
    public static List<String> basicCalculatorIV(String expression, String[] evalvars, int[] evalints) {
        Map<String, Integer> evalMap = new HashMap<>();
        for (int i = 0; i < evalvars.length; i++) {
            evalMap.put(evalvars[i], evalints[i]);
        }
        List<String> tokens = tokenize(expression);
        Parser parser = new Parser(tokens, evalMap);
        Polynomial poly = parser.parseExpression();
        return poly.toList();
    }

    private static List<String> tokenize(String s) {
        List<String> tokens = new ArrayList<>();
        int n = s.length();
        int i = 0;
        while (i < n) {
            char c = s.charAt(i);
            if (c == ' ') {
                i++;
            } else if (c == '+' || c == '-' || c == '*' || c == '(' || c == ')') {
                tokens.add(String.valueOf(c));
                i++;
            } else if (Character.isDigit(c)) {
                int j = i;
                while (j < n && Character.isDigit(s.charAt(j))) j++;
                tokens.add(s.substring(i, j));
                i = j;
            } else {
                int j = i;
                while (j < n && Character.isLetter(s.charAt(j))) j++;
                tokens.add(s.substring(i, j));
                i = j;
            }
        }
        return tokens;
    }

    private static class Parser {
        private final List<String> tokens;
        private final Map<String, Integer> evalMap;
        private int pos = 0;

        Parser(List<String> tokens, Map<String, Integer> evalMap) {
            this.tokens = tokens;
            this.evalMap = evalMap;
        }

        Polynomial parseExpression() {
            Polynomial left = parseTerm();
            while (hasNext() && (peek().equals("+") || peek().equals("-"))) {
                String op = next();
                Polynomial right = parseTerm();
                left = op.equals("+") ? left.add(right) : left.subtract(right);
            }
            return left;
        }

        Polynomial parseTerm() {
            Polynomial left = parseFactor();
            while (hasNext() && peek().equals("*")) {
                next();
                Polynomial right = parseFactor();
                left = left.multiply(right);
            }
            return left;
        }

        Polynomial parseFactor() {
            String token = next();
            if (token.equals("(")) {
                Polynomial inside = parseExpression();
                next(); // consume ')'
                return inside;
            } else if (Character.isDigit(token.charAt(0))) {
                return Polynomial.constant(Integer.parseInt(token));
            } else {
                if (evalMap.containsKey(token)) {
                    return Polynomial.constant(evalMap.get(token));
                }
                return Polynomial.variable(token);
            }
        }

        private boolean hasNext() {
            return pos < tokens.size();
        }

        private String peek() {
            return tokens.get(pos);
        }

        private String next() {
            return tokens.get(pos++);
        }
    }

    private static class Polynomial {
        private final Map<String, Integer> terms; // key: sorted variables joined by '*', "" for constant

        private Polynomial(Map<String, Integer> terms) {
            this.terms = terms;
        }

        static Polynomial constant(int value) {
            Map<String, Integer> map = new HashMap<>();
            if (value != 0) map.put("", value);
            return new Polynomial(map);
        }

        static Polynomial variable(String var) {
            Map<String, Integer> map = new HashMap<>();
            map.put(var, 1);
            return new Polynomial(map);
        }

        Polynomial add(Polynomial other) {
            Map<String, Integer> res = new HashMap<>(terms);
            for (Map.Entry<String, Integer> e : other.terms.entrySet()) {
                res.merge(e.getKey(), e.getValue(), Integer::sum);
                if (res.get(e.getKey()) == 0) res.remove(e.getKey());
            }
            return new Polynomial(res);
        }

        Polynomial subtract(Polynomial other) {
            Map<String, Integer> res = new HashMap<>(terms);
            for (Map.Entry<String, Integer> e : other.terms.entrySet()) {
                res.merge(e.getKey(), -e.getValue(), Integer::sum);
                if (res.get(e.getKey()) == 0) res.remove(e.getKey());
            }
            return new Polynomial(res);
        }

        Polynomial multiply(Polynomial other) {
            Map<String, Integer> res = new HashMap<>();
            for (Map.Entry<String, Integer> e1 : terms.entrySet()) {
                for (Map.Entry<String, Integer> e2 : other.terms.entrySet()) {
                    String newKey = combineKeys(e1.getKey(), e2.getKey());
                    int newCoeff = e1.getValue() * e2.getValue();
                    res.merge(newKey, newCoeff, Integer::sum);
                    if (res.get(newKey) == 0) res.remove(newKey);
                }
            }
            return new Polynomial(res);
        }

        private String combineKeys(String k1, String k2) {
            if (k1.isEmpty()) return k2;
            if (k2.isEmpty()) return k1;
            String[] vars1 = k1.split("\\*");
            String[] vars2 = k2.split("\\*");
            List<String> list = new ArrayList<>(Arrays.asList(vars1));
            list.addAll(Arrays.asList(vars2));
            Collections.sort(list);
            return String.join("*", list);
        }

        List<String> toList() {
            List<Map.Entry<String, Integer>> entries = new ArrayList<>(terms.entrySet());
            entries.sort((a, b) -> {
                int degA = a.getKey().isEmpty() ? 0 : a.getKey().split("\\*").length;
                int degB = b.getKey().isEmpty() ? 0 : b.getKey().split("\\*").length;
                if (degA != degB) return Integer.compare(degB, degA);
                return a.getKey().compareTo(b.getKey());
            });
            List<String> result = new ArrayList<>();
            for (Map.Entry<String, Integer> e : entries) {
                int coeff = e.getValue();
                String key = e.getKey();
                if (key.isEmpty()) {
                    result.add(String.valueOf(coeff));
                } else {
                    result.add(coeff + "*" + key);
                }
            }
            return result;
        }
    }
}

class Solution {
    public static boolean reachingPoints(int sx, int sy, int tx, int ty) {
        while (tx > sx && ty > sy) {
            if (tx > ty) {
                tx -= (tx / ty) * ty;
            } else {
                ty -= (ty / tx) * tx;
            }
        }
        return (tx == sx && ty >= sy && (ty - sy) % sx == 0) || (ty == sy && tx >= sx && (tx - sx) % sy == 0);
    }
}

import java.util.PriorityQueue;
import java.util.Comparator;

class Solution {
    public static int swimInWater(int[][] grid) {
        int n = grid.length;
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        pq.offer(new int[]{grid[0][0], 0, 0});
        boolean[][] visited = new boolean[n][n];
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int elevation = cur[0];
            int x = cur[1];
            int y = cur[2];
            if (x == n - 1 && y == n - 1) return elevation;
            if (visited[x][y]) continue;
            visited[x][y] = true;
            for (int[] d : directions) {
                int nx = x + d[0];
                int ny = y + d[1];
                if (nx >= 0 && nx < n && ny >= 0 && ny < n && !visited[nx][ny]) {
                    pq.offer(new int[]{Math.max(elevation, grid[nx][ny]), nx, ny});
                }
            }
        }
        return -1;
    }
}

