class Solution {
    public static boolean canTransform(String start, String result) {
        int i = 0, j = 0;
        int n = start.length();
        while (i < n && j < n) {
            while (i < n && start.charAt(i) == 'X') i++;
            while (j < n && result.charAt(j) == 'X') j++;
            if (i == n || j == n) break;
            if (start.charAt(i) != result.charAt(j)) return false;
            if (start.charAt(i) == 'L' && i < j) return false;
            if (start.charAt(i) == 'R' && i > j) return false;
            i++;
            j++;
        }
        while (i < n && start.charAt(i) == 'X') i++;
        while (j < n && result.charAt(j) == 'X') j++;
        return i == n && j == n;
    }
}

public class Solution {
    public static boolean isIdealPermutation(int[] nums) {
        int globalInversions = 0;
        for (int i = 0; i < nums.length; i++) {
            for (int j = i + 1; j < nums.length; j++) {
                if (nums[i] > nums[j]) globalInversions++;
            }
        }
        int localInversions = 0;
        for (int i = 0; i < nums.length - 1; i++) {
            if (nums[i] > nums[i + 1]) localInversions++;
        }
        return globalInversions == localInversions;
    }
}

