class Solution {
    private static class Node {
        int[] state;
        int moves;
        Node(int[] state, int moves) {
            this.state = state;
            this.moves = moves;
        }
    }

    public static int slidingPuzzle(int[][] board) {
        int[] target = {1, 2, 3, 4, 5, 0};
        int[] start = new int[6];
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < 3; j++) {
                start[i * 3 + j] = board[i][j];
            }
        }
        int[][] directions = {
            {1, 3},
            {0, 2, 4},
            {1, 5},
            {0, 4},
            {1, 3, 5},
            {2, 4}
        };
        Deque<Node> queue = new ArrayDeque<>();
        Set<String> visited = new HashSet<>();
        queue.offer(new Node(start, 0));
        visited.add(Arrays.toString(start));
        while (!queue.isEmpty()) {
            Node node = queue.poll();
            int[] state = node.state;
            int moves = node.moves;
            if (Arrays.equals(state, target)) {
                return moves;
            }
            int zeroIndex = -1;
            for (int i = 0; i < state.length; i++) {
                if (state[i] == 0) {
                    zeroIndex = i;
                    break;
                }
            }
            for (int dir : directions[zeroIndex]) {
                int[] newState = state.clone();
                int temp = newState[zeroIndex];
                newState[zeroIndex] = newState[dir];
                newState[dir] = temp;
                String key = Arrays.toString(newState);
                if (!visited.contains(key)) {
                    visited.add(key);
                    queue.offer(new Node(newState, moves + 1));
                }
            }
        }
        return -1;
    }
}

