class Solution {
    public static int minDiffInBST(TreeNode root) {
        int[] minDiff = new int[]{Integer.MAX_VALUE};
        Integer[] prev = new Integer[]{null};
        inOrderTraversal(root, minDiff, prev);
        return minDiff[0];
    }
    private static void inOrderTraversal(TreeNode node, int[] minDiff, Integer[] prev) {
        if (node == null) return;
        inOrderTraversal(node.left, minDiff, prev);
        if (prev[0] != null) {
            int diff = node.val - prev[0];
            if (diff < minDiff[0]) minDiff[0] = diff;
        }
        prev[0] = node.val;
        inOrderTraversal(node.right, minDiff, prev);
    }
}

