class Solution {
    public static int movesToMakeZigzag(int[][] board) {
        int n = board.length;
        int rowMask = 0, colMask = 0;
        for (int i = 0; i < n; i++) {
            rowMask = (rowMask << 1) | board[0][i];
            colMask = (colMask << 1) | board[i][0];
        }
        int revRowMask = ((1 << n) - 1) ^ rowMask;
        int revColMask = ((1 << n) - 1) ^ colMask;
        int rowCnt = 0, colCnt = 0;
        for (int i = 0; i < n; i++) {
            int curRowMask = 0, curColMask = 0;
            for (int j = 0; j < n; j++) {
                curRowMask = (curRowMask << 1) | board[i][j];
                curColMask = (curColMask << 1) | board[j][i];
            }
            if (curRowMask != rowMask && curRowMask != revRowMask) return -1;
            if (curColMask != colMask && curColMask != revColMask) return -1;
            if (curRowMask == rowMask) rowCnt++;
            if (curColMask == colMask) colCnt++;
        }
        if (Math.abs(rowCnt - n / 2) > n % 2) return -1;
        if (Math.abs(colCnt - n / 2) > n % 2) return -1;
        int rowSwaps = calculateSwaps(rowMask, n);
        int colSwaps = calculateSwaps(colMask, n);
        return rowSwaps + colSwaps;
    }

    private static int calculateSwaps(int mask, int n) {
        int ones = Integer.bitCount(mask);
        int pattern0 = 0;
        for (int i = 0; i < n; i++) {
            pattern0 = (pattern0 << 1) | (i % 2);
        }
        int pattern1 = ((1 << n) - 1) ^ pattern0;
        if (n % 2 == 0) {
            int diff0 = Integer.bitCount(mask ^ pattern0);
            int diff1 = Integer.bitCount(mask ^ pattern1);
            return Math.min(diff0, diff1) / 2;
        } else {
            if (ones * 2 > n) {
                return Integer.bitCount(mask ^ pattern1) / 2;
            } else {
                return Integer.bitCount(mask ^ pattern0) / 2;
            }
        }
    }
}

import java.util.List;
