                for (int j = 0; j < count; j++) {
                    result.append(c);
                }
                frequencyMap.put(c, 0);
            }
        }
        for (Map.Entry<Character, Integer> entry : frequencyMap.entrySet()) {
            int count = entry.getValue();
            if (count > 0) {
                char c = entry.getKey();
                for (int j = 0; j < count; j++) {
                    result.append(c);
                }
            }
        }
        return result.toString();
    }
}

