class Solution {
    public static int numTilings(int n) {
        int mod = 1_000_000_007;
        long[] dp = new long[Math.max(3, n + 1)];
        dp[0] = 1;
        dp[1] = 1;
        dp[2] = 2;
        for (int i = 3; i <= n; i++) {
            dp[i] = (2 * dp[i - 1] + dp[i - 3]) % mod;
        }
        return (int) dp[n];
    }
}

class Solution {
    public static int preimageSizeFZF(int k) {
        long left = 0;
        long right = 5L * k;
        while (left < right) {
            long mid = (left + right) / 2;
            long tz = findTrailingZeroes(mid);
            if (tz < k) {
                left = mid + 1;
            } else if (tz > k) {
                right = mid;
            } else {
                right = mid;
            }
        }
        if (findTrailingZeroes(left) == k) {
            if (findTrailingZeroes(left + 4) == k) {
                return 5;
            } else {
                return 1;
            }
        } else {
            return 0;
        }
    }

    private static long findTrailingZeroes(long x) {
        long count = 0;
        long i = 5;
        while (x / i >= 1) {
            count += x / i;
            i *= 5;
        }
        return count;
    }
}

