class Solution {
    public static boolean validTicTacToe(String[] board) {
        int xCount = 0, oCount = 0;
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                char c = board[i].charAt(j);
                if (c == 'X') xCount++;
                else if (c == 'O') oCount++;
            }
        }
        if (xCount < oCount || xCount > oCount + 1) return false;
        boolean xWin = checkWin(board, 'X');
        boolean oWin = checkWin(board, 'O');
        if (xWin && oWin) return false;
        if (xWin && xCount != oCount + 1) return false;
        if (oWin && xCount != oCount) return false;
        return true;
    }

    private static boolean checkWin(String[] board, char player) {
        for (int i = 0; i < 3; i++) {
            if (board[i].charAt(0) == player && board[i].charAt(1) == player && board[i].charAt(2) == player) return true;
            if (board[0].charAt(i) == player && board[1].charAt(i) == player && board[2].charAt(i) == player) return true;
        }
        if (board[0].charAt(0) == player && board[1].charAt(1) == player && board[2].charAt(2) == player) return true;
        if (board[0].charAt(2) == player && board[1].charAt(1) == player && board[2].charAt(0) == player) return true;
        return false;
    }
}

class Solution {
    public static int rotatedDigits(int n) {
        int count = 0;
        for (int i = 1; i <= n; i++) {
            boolean isGood = false;
            boolean isValid = true;
            int rotated = 0;
            int temp = i;
            int base = 1;
            while (temp > 0) {
                int digit = temp % 10;
                if (digit == 3 || digit == 4 || digit == 7) {
                    isValid = false;
                    break;
                }
                int rotatedDigit = (digit == 0) ? 0 : (digit == 1) ? 1 : (digit == 6) ? 9 : (digit == 8) ? 8 : (digit == 9) ? 6 : 9;
                if (rotatedDigit != digit) {
                    isGood = true;
                }
                rotated += rotatedDigit * base;
                base *= 10;
                temp = temp / 10;
            }
            if (isValid && isGood) {
                count++;
            }
        }
        return count;
    }
}

import java.util.*;

public class Solution {
    public static int findCheapestPrice(int n, int[][] flights, int src, int dst, int k) {
        List<int[]>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] f : flights) {
            graph[f[0]].add(new int[]{f[1], f[2]});
        }
        PriorityQueue<Node> pq = new PriorityQueue<>();
        pq.offer(new Node(src, 0, 0));
        int[][] visited = new int[n][k + 2];
        for (int i = 0; i < n; i++) {
            Arrays.fill(visited[i], Integer.MAX_VALUE);
        }
        visited[src][0] = 0;
        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            int city = cur.city;
            int cost = cur.cost;
            int stops = cur.stops;
            if (city == dst) {
                return cost;
            }
            if (stops > k) {
                continue;
            }
            for (int[] edge : graph[city]) {
                int neighbor = edge[0];
                int price = edge[1];
                int newCost = cost + price;
                int newStops = stops + 1;
                if (newStops < visited[0].length && newCost < visited[neighbor][newStops]) {
                    visited[neighbor][newStops] = newCost;
                    pq.offer(new Node(neighbor, newCost, newStops));
                }
            }
        }
        return -1;
    }

    private static class Node implements Comparable<Node> {
        int city;
        int cost;
        int stops;
        Node(int city, int cost, int stops) {
            this.city = city;
            this.cost = cost;
            this.stops = stops;
        }
        public int compareTo(Node other) {
            return Integer.compare(this.cost, other.cost);
        }
    }
}

