class Solution {
    public static List<List<Integer>> allPathsSourceTarget(List<List<Integer>> graph) {
        List<List<Integer>> result = new ArrayList<>();
        dfs(0, new ArrayList<>(), graph, result);
        return result;
    }

    private static void dfs(int currentNode, List<Integer> path, List<List<Integer>> graph, List<List<Integer>> result) {
        path.add(currentNode);
        if (currentNode == graph.size() - 1) {
            result.add(new ArrayList<>(path));
        } else {
            for (int neighbor : graph.get(currentNode)) {
                dfs(neighbor, path, graph, result);
            }
        }
        path.remove(path.size() - 1);
    }
}

class Solution {
    public static int bestRotation(int[] nums) {
        int maxScore = 0;
        int rotationIndex = 0;
        for (int k = 0; k < nums.length; k++) {
            int score = 0;
            for (int i = 0; i < nums.length; i++) {
                if (nums[(i + k) % nums.length] <= i) {
                    score++;
                }
            }
            if (score > maxScore) {
                maxScore = score;
                rotationIndex = k;
            } else if (score == maxScore) {
                rotationIndex = Math.min(rotationIndex, k);
            }
        }
        return rotationIndex;
    }
}

