public class Solution {
    public static int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length;
        int n = grid[0].length;
        int[][] original = new int[m][n];
        for (int i = 0; i < m; i++) {
            System.arraycopy(grid[i], 0, original[i], 0, n);
        }
        for (int[] hit : hits) {
            int r = hit[0], c = hit[1];
            if (grid[r][c] == 1) {
                grid[r][c] = 0;
            }
        }
        DSU dsu = new DSU(m * n + 1);
        int top = m * n;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    int idx = i * n + j;
                    if (i == 0) {
                        dsu.union(idx, top);
                    }
                    if (i > 0 && grid[i - 1][j] == 1) {
                        dsu.union(idx, (i - 1) * n + j);
                    }
                    if (j > 0 && grid[i][j - 1] == 1) {
                        dsu.union(idx, i * n + (j - 1));
                    }
                }
            }
        }
        int[] res = new int[hits.length];
        for (int k = hits.length - 1; k >= 0; k--) {
            int r = hits[k][0], c = hits[k][1];
            if (original[r][c] == 0) {
                res[k] = 0;
                continue;
            }
            int before = dsu.getSize(top);
            grid[r][c] = 1;
            int idx = r * n + c;
            if (r == 0) {
                dsu.union(idx, top);
            }
            int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == 1) {
                    dsu.union(idx, nr * n + nc);
                }
            }
            int after = dsu.getSize(top);
            res[k] = Math.max(0, after - before - 1);
        }
        return res;
    }

    private static class DSU {
        private final int[] parent;
        private final int[] size;

        DSU(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return;
            if (size[ra] < size[rb]) {
                int tmp = ra;
                ra = rb;
                rb = tmp;
            }
            parent[rb] = ra;
            size[ra] += size[rb];
        }

        int getSize(int x) {
            int root = find(x);
            return size[root];
        }
    }
}

