class Solution {
    public static double soupServings(int n) {
        int scaled = (int)Math.ceil(n / 25.0);
        if (scaled >= 179) return 1.0;
        double[][] memo = new double[scaled + 1][scaled + 1];
        return dfs(scaled, scaled, memo);
    }

    private static double dfs(int a, int b, double[][] memo) {
        if (a <= 0 && b <= 0) return 0.5;
        if (a <= 0) return 1.0;
        if (b <= 0) return 0.0;
        if (memo[a][b] != 0.0) return memo[a][b];
        memo[a][b] = 0.25 * (dfs(a - 4, b, memo)
                           + dfs(a - 3, b - 1, memo)
                           + dfs(a - 2, b - 2, memo)
                           + dfs(a - 1, b - 3, memo));
        return memo[a][b];
    }
}

