class Solution {
    public static int numComponents(ListNode head, int[] nums) {
        Set<Integer> numSet = new HashSet<>();
        for (int num : nums) {
            numSet.add(num);
        }
        int count = 0;
        while (head != null) {
            if (numSet.contains(head.val)) {
                count++;
                ListNode nextNode = head.next;
                while (nextNode != null && numSet.contains(nextNode.val)) {
                    nextNode = nextNode.next;
                }
                head = nextNode;
            } else {
                head = head.next;
            }
        }
        return count;
    }
}

