class Solution {
    public static int numBusesToDestination(int[][] routes, int source, int target) {
        if (source == target) return 0;
        Map<Integer, List<Integer>> routeMap = new HashMap<>();
        for (int i = 0; i < routes.length; i++) {
            for (int stop : routes[i]) {
                routeMap.computeIfAbsent(stop, k -> new ArrayList<>()).add(i);
            }
        }
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{source, 0});
        Set<Integer> visitedStops = new HashSet<>();
        visitedStops.add(source);
        Set<Integer> visitedRoutes = new HashSet<>();
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int stop = cur[0];
            int buses = cur[1];
            List<Integer> possibleRoutes = routeMap.get(stop);
            if (possibleRoutes == null) continue;
            for (int route : possibleRoutes) {
                if (!visitedRoutes.contains(route)) {
                    visitedRoutes.add(route);
                    for (int nextStop : routes[route]) {
                        if (nextStop == target) return buses + 1;
                        if (!visitedStops.contains(nextStop)) {
                            visitedStops.add(nextStop);
                            queue.offer(new int[]{nextStop, buses + 1});
                        }
                    }
                }
            }
        }
        return -1;
    }
}

