class Solution {
    public static List<String> ambiguousCoordinates(String s) {
        String inner = s.substring(1, s.length() - 1);
        List<String> result = new ArrayList<>();
        int n = inner.length();
        for (int i = 1; i < n; i++) {
            String leftPart = inner.substring(0, i);
            String rightPart = inner.substring(i);
            List<String> leftOptions = generateNumbers(leftPart);
            List<String> rightOptions = generateNumbers(rightPart);
            for (String left : leftOptions) {
                for (String right : rightOptions) {
                    result.add("(" + left + ", " + right + ")");
                }
            }
        }
        Collections.sort(result);
        return result;
    }

    private static List<String> generateNumbers(String s) {
        List<String> list = new ArrayList<>();
        int len = s.length();
        if (len == 0) return list;
        if (len == 1) {
            list.add(s);
            return list;
        }
        boolean startsZero = s.charAt(0) == '0';
        boolean endsZero = s.charAt(len - 1) == '0';
        if (startsZero && endsZero) {
            return list;
        }
        if (startsZero) {
            // only decimal form "0.xxx" if fractional part does not end with '0'
            if (!endsZero) {
                list.add("0." + s.substring(1));
            }
            return list;
        }
        if (endsZero) {
            // only integer form
            list.add(s);
            return list;
        }
        // integer form
        list.add(s);
        // decimal forms
        for (int i = 1; i < len; i++) {
            String left = s.substring(0, i);
            String right = s.substring(i);
            // right part must not end with '0' (already ensured by endsZero false)
            list.add(left + "." + right);
        }
        return list;
    }
}

import java.util.Arrays;

class Solution {
    public static double largestSumOfAverages(int[] nums, int k) {
        int n = nums.length;
        double[] prefixSum = new double[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + nums[i];
        }

        double[][] dp = new double[n][k + 1];
        for (int i = 0; i < n; i++) {
            Arrays.fill(dp[i], Double.NEGATIVE_INFINITY);
        }

        for (int i = 0; i < n; i++) {
            dp[i][1] = prefixSum[i + 1] / (i + 1);
        }

        for (int j = 2; j <= k; j++) {
            for (int i = j - 1; i < n; i++) {
                for (int x = j - 2; x < i; x++) {
                    double avg = (prefixSum[i + 1] - prefixSum[x + 1]) / (i - x);
                    dp[i][j] = Math.max(dp[i][j], dp[x][j - 1] + avg);
                }
            }
        }

        return dp[n - 1][k];
    }
}

