class Solution {
    public static int racecar(int target) {
        Deque<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{0, 1, 0});
        Set<String> visited = new HashSet<>();
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int position = cur[0];
            int speed = cur[1];
            int steps = cur[2];
            if (position == target) {
                return steps;
            }
            String key = position + "," + speed;
            if (visited.contains(key)) {
                continue;
            }
            visited.add(key);
            queue.offer(new int[]{position + speed, speed * 2, steps + 1});
            if ((speed > 0 && position + speed > target) || (speed < 0 && position + speed < target)) {
                queue.offer(new int[]{position, -1, steps + 1});
            }
        }
        return -1;
    }
}

