import java.util.HashMap;

public class Solution {
    public static int minimumLengthEncoding(String[] words) {
        Map<Character, Object> trie = new HashMap<>();
        for (String word : words) {
            Map<Character, Object> node = trie;
            for (int i = word.length() - 1; i >= 0; i--) {
                char c = word.charAt(i);
                if (!node.containsKey(c)) {
                    node.put(c, new HashMap<Character, Object>());
                }
                node = (Map<Character, Object>) node.get(c);
            }
        }
        return dfs(trie, 0);
    }

    private static int dfs(Map<Character, Object> node, int depth) {
        if (node.isEmpty()) {
            return depth + 1;
        }
        int sum = 0;
        for (Object child : node.values()) {
            sum += dfs((Map<Character, Object>) child, depth + 1);
        }
        return sum;
    }
}

import java.util.*;

class Solution {
    public static String toGoatLatin(String sentence) {
        String[] words = sentence.split(" ");
        List<String> result = new ArrayList<>();
        for (int i = 0; i < words.length; i++) {
            String word = words[i];
            char firstChar = word.charAt(0);
            boolean isVowel = "aeiouAEIOU".indexOf(firstChar) != -1;
            StringBuilder sb = new StringBuilder();
            if (isVowel) {
                sb.append(word);
            } else {
                sb.append(word.substring(1));
                sb.append(firstChar);
            }
            sb.append("ma");
            for (int j = 0; j <= i; j++) {
                sb.append('a');
            }
            result.add(sb.toString());
        }
        return String.join(" ", result);
    }
}

import java.util.*;

class Solution {
    public static int numFactoredBinaryTrees(int[] arr) {
        long MOD = 1_000_000_007L;
        Arrays.sort(arr);
        Map<Integer, Long> dp = new HashMap<>();
        long result = 0;
        for (int i = 0; i < arr.length; i++) {
            dp.put(arr[i], 1L);
            for (int j = 0; j < i; j++) {
                if (arr[i] % arr[j] == 0) {
                    int otherFactor = arr[i] / arr[j];
                    if (dp.containsKey(otherFactor)) {
                        long val = (dp.get(arr[i]) + dp.get(arr[j]) * dp.get(otherFactor)) % MOD;
                        dp.put(arr[i], val);
                    }
                }
            }
            result = (result + dp.get(arr[i])) % MOD;
        }
        return (int) result;
    }
}

