class Solution {
    public static int numFriendRequests(int[] ages) {
        int[] count = new int[121];
        for (int age : ages) {
            count[age]++;
        }
        int total = 0;
        for (int a = 15; a <= 120; a++) {
            if (count[a] == 0) continue;
            for (int b = 15; b <= a; b++) {
                if (count[b] == 0) continue;
                if (b <= 0.5 * a + 7) continue;
                if (a < 100 && b > 100) continue;
                if (a == b) {
                    total += count[a] * (count[a] - 1);
                } else {
                    total += count[a] * count[b];
                }
            }
        }
        return total;
    }
}

import java.util.Arrays;

class Solution {
    public static int[] shortestToChar(String s, char c) {
        int[] res = new int[s.length()];
        Arrays.fill(res, Integer.MAX_VALUE);
        int prev = Integer.MIN_VALUE;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == c) {
                prev = i;
                res[i] = 0;
            } else if (prev != Integer.MIN_VALUE) {
                res[i] = Math.min(res[i], i - prev);
            }
        }
        int next = Integer.MAX_VALUE;
        for (int i = s.length() - 1; i >= 0; i--) {
            if (s.charAt(i) == c) {
                next = i;
            } else if (next != Integer.MAX_VALUE) {
                res[i] = Math.min(res[i], next - i);
            }
        }
        return res;
    }
}

import java.util.Arrays;

class Solution {
    public static int maxProfitAssignment(int[] difficulty, int[] profit, int[] worker) {
        int n = difficulty.length;
        int[][] jobs = new int[n][2];
        for (int i = 0; i < n; i++) {
            jobs[i][0] = difficulty[i];
            jobs[i][1] = profit[i];
        }
        Arrays.sort(jobs, (a, b) -> Integer.compare(a[0], b[0]));
        int[] maxProfit = new int[n];
        maxProfit[0] = jobs[0][1];
        for (int i = 1; i < n; i++) {
            maxProfit[i] = Math.max(maxProfit[i - 1], jobs[i][1]);
        }
        int totalProfit = 0;
        for (int w : worker) {
            int left = 0, right = n - 1;
            while (left < right) {
                int mid = (left + right + 1) / 2;
                if (jobs[mid][0] <= w) {
                    left = mid;
                } else {
                    right = mid - 1;
                }
            }
            if (jobs[left][0] <= w) {
                totalProfit += maxProfit[left];
            }
        }
        return totalProfit;
    }
}

import java.util.Arrays;

class Solution {
    public static long countUniqueChars(String s) {
        int n = s.length();
        int[] prev = new int[n];
        int[] next = new int[n];
        int[] last = new int[256];
        Arrays.fill(last, -1);
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            prev[i] = last[c];
            last[c] = i;
        }
        Arrays.fill(last, n);
        for (int i = n - 1; i >= 0; i--) {
            char c = s.charAt(i);
            next[i] = last[c];
            last[c] = i;
        }
        long result = 0;
        for (int i = 0; i < n; i++) {
            long left = i - prev[i];
            long right = next[i] - i;
            result += left * right;
        }
        return result;
    }
}

