class Solution {
    public static int consecutiveNumbersSum(int n) {
        int count = 0;
        for (int start = 1; start <= n; start++) {
            int sum = 0;
            for (int end = start; end <= n; end++) {
                sum += end;
                if (sum == n) {
                    count++;
                } else if (sum > n) {
                    break;
                }
            }
        }
        return count;
    }
}

