class Solution {
    public static int largestIsland(int[][] grid) {
        int n = grid.length;
        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
        int islandIndex = 2;
        Map<Integer, Integer> islandSizes = new HashMap<>();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    int size = dfs(grid, i, j, islandIndex, directions);
                    islandSizes.put(islandIndex, size);
                    islandIndex++;
                }
            }
        }

        int maxSize = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 0) {
                    Set<Integer> seen = new HashSet<>();
                    int size = 1;
                    for (int[] dir : directions) {
                        int x = i + dir[0];
                        int y = j + dir[1];
                        if (x >= 0 && x < n && y >= 0 && y < n && grid[x][y] > 1 && !seen.contains(grid[x][y])) {
                            size += islandSizes.get(grid[x][y]);
                            seen.add(grid[x][y]);
                        }
                    }
                    if (size > maxSize) {
                        maxSize = size;
                    }
                }
            }
        }

        if (maxSize == 0) {
            int maxIsland = 0;
            for (int size : islandSizes.values()) {
                if (size > maxIsland) {
                    maxIsland = size;
                }
            }
            return maxIsland;
        }

        return maxSize;
    }

    private static int dfs(int[][] grid, int i, int j, int islandIndex, int[][] directions) {
        int n = grid.length;
        if (i < 0 || i >= n || j < 0 || j >= n || grid[i][j] != 1) {
            return 0;
        }
        grid[i][j] = islandIndex;
        int size = 1;
        for (int[] dir : directions) {
            size += dfs(grid, i + dir[0], j + dir[1], islandIndex, directions);
        }
        return size;
    }
}

