class Solution {
    public static List<List<Integer>> largeGroupPositions(String s) {
        List<List<Integer>> result = new ArrayList<>();
        int count = 1;
        for (int i = 0; i < s.length() - 1; i++) {
            if (s.charAt(i) == s.charAt(i + 1)) {
                count++;
            } else {
                if (count >= 3) {
                    List<Integer> interval = new ArrayList<>(2);
                    interval.add(i - count + 1);
                    interval.add(i);
                    result.add(interval);
                }
                count = 1;
            }
        }
        if (count >= 3) {
            List<Integer> interval = new ArrayList<>(2);
            interval.add(s.length() - count);
            interval.add(s.length() - 1);
            result.add(interval);
        }
        return result;
    }
}

