class Solution {
    public static String findReplaceString(String s, int[] indices, String[] sources, String[] targets) {
        int n = indices.length;
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> Integer.compare(indices[b], indices[a]));
        String result = s;
        for (int idx : order) {
            int index = indices[idx];
            String source = sources[idx];
            String target = targets[idx];
            if (index + source.length() <= result.length() && result.substring(index, index + source.length()).equals(source)) {
                result = result.substring(0, index) + target + result.substring(index + source.length());
            }
        }
        return result;
    }
}

import java.util.*;

class Solution {
    public static String maskPII(String s) {
        if (s.contains("@")) {
            String[] parts = s.split("@", 2);
            String local = parts[0].toLowerCase();
            String domain = parts[1].toLowerCase();
            String maskedLocal = "" + local.charAt(0) + "*****" + local.charAt(local.length() - 1);
            return maskedLocal + "@" + domain;
        } else {
            String digits = s.replaceAll("[^0-9]", "");
            String countryCode = "";
            if (digits.length() == 13) {
                countryCode = "+***-";
                digits = digits.substring(3);
            } else if (digits.length() == 12) {
                countryCode = "+**-";
                digits = digits.substring(2);
            } else if (digits.length() == 11) {
                countryCode = "+*-";
                digits = digits.substring(1);
            }
            String maskedDigits = countryCode + "***-***-" + digits.substring(digits.length() - 4);
            return maskedDigits;
        }
    }
}

