import java.util.Arrays;

class Solution {
    public static String pushDominoes(String dominoes) {
        int n = dominoes.length();
        char[] result = new char[n];
        Arrays.fill(result, '.');
        int[] force = new int[n];
        int f = 0;
        for (int i = 0; i < n; i++) {
            char c = dominoes.charAt(i);
            if (c == 'R') {
                f = n;
            } else if (c == 'L') {
                f = 0;
            } else {
                f = Math.max(f - 1, 0);
            }
            force[i] += f;
        }
        f = 0;
        for (int i = n - 1; i >= 0; i--) {
            char c = dominoes.charAt(i);
            if (c == 'L') {
                f = n;
            } else if (c == 'R') {
                f = 0;
            } else {
                f = Math.max(f - 1, 0);
            }
            force[i] -= f;
        }
        for (int i = 0; i < n; i++) {
            if (force[i] > 0) {
                result[i] = 'R';
            } else if (force[i] < 0) {
                result[i] = 'L';
            }
        }
        return new String(result);
    }
}

