class Solution {
    public static double new21Game(int n, int k, int maxPts) {
        if (k == 0 || n >= k + maxPts - 1) {
            return 1.0;
        }
        double[] dp = new double[n + 1];
        dp[0] = 1.0;
        double windowSum = 1.0;
        double ans = 0.0;
        for (int i = 1; i <= n; i++) {
            dp[i] = windowSum / maxPts;
            if (i < k) {
                windowSum += dp[i];
            } else {
                ans += dp[i];
            }
            if (i - maxPts >= 0 && i - maxPts < k) {
                windowSum -= dp[i - maxPts];
            }
        }
        return Math.round(ans * 100000.0) / 100000.0;
    }
}

import java.util.*;

class Solution {
    public static int[] sumOfDistancesInTree(int n, int[][] edges) {
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            graph[u].add(v);
            graph[v].add(u);
        }
        int[] count = new int[n];
        int[] answer = new int[n];
        Arrays.fill(count, 1);
        dfs(0, -1, graph, count, answer);
        dfs2(0, -1, graph, count, answer, n);
        return answer;
    }

    private static void dfs(int node, int parent, List<Integer>[] graph, int[] count, int[] answer) {
        for (int child : graph[node]) {
            if (child != parent) {
                dfs(child, node, graph, count, answer);
                count[node] += count[child];
                answer[node] += answer[child] + count[child];
            }
        }
    }

    private static void dfs2(int node, int parent, List<Integer>[] graph, int[] count, int[] answer, int n) {
        for (int child : graph[node]) {
            if (child != parent) {
                answer[child] = answer[node] - count[child] + (n - count[child]);
                dfs2(child, node, graph, count, answer, n);
            }
        }
    }
}

