class Solution {
    public static int numSimilarGroups(String[] strs) {
        int n = strs.length;
        int[] parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;

        java.util.function.IntUnaryOperator find = new java.util.function.IntUnaryOperator() {
            @Override
            public int applyAsInt(int x) {
                if (parent[x] != x) parent[x] = applyAsInt(parent[x]);
                return parent[x];
            }
        };

        java.util.function.BiConsumer<Integer, Integer> union = (x, y) -> {
            int rootX = find.applyAsInt(x);
            int rootY = find.applyAsInt(y);
            if (rootX != rootY) parent[rootX] = rootY;
        };

        java.util.function.BiPredicate<String, String> isSimilar = (s1, s2) -> {
            int count = 0;
            for (int i = 0; i < s1.length(); i++) {
                if (s1.charAt(i) != s2.charAt(i)) count++;
                if (count > 2) return false;
            }
            return count == 0 || count == 2;
        };

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (isSimilar.test(strs[i], strs[j])) union.accept(i, j);
            }
        }

        int count = 0;
        for (int i = 0; i < n; i++) {
            if (parent[i] == i) count++;
        }
        return count;
    }
}

