class Solution {
    public static List<Integer> splitIntoFibonacci(String num) {
        int n = num.length();
        List<Integer> result = new ArrayList<>();
        for (int i = 1; i <= Math.min(10, n - 2); i++) {
            if (num.charAt(0) == '0' && i > 1) break;
            long first = parse(num, 0, i);
            if (first > Integer.MAX_VALUE) break;
            for (int j = i + 1; j <= Math.min(i + 10, n - 1); j++) {
                if (num.charAt(i) == '0' && j - i > 1) break;
                long second = parse(num, i, j);
                if (second > Integer.MAX_VALUE) break;
                result.clear();
                result.add((int) first);
                result.add((int) second);
                if (backtrack(num, j, result)) {
                    return result;
                }
            }
        }
        return new ArrayList<>();
    }

    private static boolean backtrack(String num, int index, List<Integer> seq) {
        if (index == num.length()) {
            return seq.size() >= 3;
        }
        long a = seq.get(seq.size() - 2);
        long b = seq.get(seq.size() - 1);
        long sum = a + b;
        if (sum > Integer.MAX_VALUE) return false;
        String sumStr = Long.toString(sum);
        int end = index + sumStr.length();
        if (end > num.length()) return false;
        if (!num.substring(index, end).equals(sumStr)) return false;
        seq.add((int) sum);
        if (backtrack(num, end, seq)) return true;
        seq.remove(seq.size() - 1);
        return false;
    }

    private static long parse(String s, int start, int end) {
        return Long.parseLong(s.substring(start, end));
    }
}

class Solution {
    public static int peakIndexInMountainArray(int[] arr) {
        int left = 0, right = arr.length - 1;
        while (left < right) {
            int mid = (left + right) / 2;
            if (arr[mid] < arr[mid + 1]) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}

import java.util.*;

class Solution {
    public static String shiftingLetters(String s, int[] shifts) {
        for (int i = shifts.length - 2; i >= 0; i--) {
            shifts[i] += shifts[i + 1];
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            int newChar = ((s.charAt(i) - 'a' + shifts[i]) % 26) + 'a';
            sb.append((char) newChar);
        }
        return sb.toString();
    }
}

import java.lang.Math;

class Solution {
    public static int longestMountain(int[] arr) {
        int maxLength = 0;
        for (int i = 1; i < arr.length - 1; i++) {
            if (arr[i - 1] < arr[i] && arr[i] > arr[i + 1]) {
                int left = i - 1;
                int right = i + 1;
                while (left >= 0 && arr[left] < arr[left + 1]) {
                    left--;
                }
                while (right < arr.length && arr[right] < arr[right - 1]) {
                    right++;
                }
                maxLength = Math.max(maxLength, right - left - 1);
            }
        }
        return maxLength;
    }
}

import java.util.*;

class Solution {
    public static int[] loudAndRich(int[][] richer, int[] quiet) {
        int n = quiet.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        int[] indegree = new int[n];
        for (int i = 0; i < richer.length; i++) {
            graph[richer[i][0]].add(richer[i][1]);
            indegree[richer[i][1]]++;
        }
        int[] answer = new int[n];
        for (int i = 0; i < n; i++) {
            answer[i] = i;
        }
        Deque<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            if (indegree[i] == 0) {
                queue.add(i);
            }
        }
        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v : graph[u]) {
                if (quiet[answer[u]] < quiet[answer[v]]) {
                    answer[v] = answer[u];
                }
                indegree[v]--;
                if (indegree[v] == 0) {
                    queue.add(v);
                }
            }
        }
        return answer;
    }
}

class Solution {
    public static boolean backspaceCompare(String s, String t) {
        int i = s.length() - 1;
        int j = t.length() - 1;
        int backS = 0;
        int backT = 0;
        while (i >= 0 || j >= 0) {
            while (i >= 0) {
                if (s.charAt(i) == '#') {
                    backS++;
                    i--;
                } else if (backS > 0) {
                    backS--;
                    i--;
                } else {
                    break;
                }
            }
            while (j >= 0) {
                if (t.charAt(j) == '#') {
                    backT++;
                    j--;
                } else if (backT > 0) {
                    backT--;
                    j--;
                } else {
                    break;
                }
            }
            if (i < 0 && j < 0) {
                return true;
            }
            if (i < 0 || j < 0) {
                return false;
            }
            if (s.charAt(i) != t.charAt(j)) {
                return false;
            }
            i--;
            j--;
        }
        return true;
    }
}

import java.util.*;

class Solution {
    public static int rectangleArea(int[][] rectangles) {
        List<Integer> xs = new ArrayList<>();
        for (int[] r : rectangles) {
            xs.add(r[0]);
            xs.add(r[2]);
        }
        Collections.sort(xs);
        long MOD = 1_000_000_007L;
        long area = 0;
        for (int i = 0; i < xs.size() - 1; i++) {
            int x1 = xs.get(i);
            int x2 = xs.get(i + 1);
            int width = x2 - x1;
            if (width == 0) continue;
            List<int[]> intervals = new ArrayList<>();
            for (int[] r : rectangles) {
                if (r[0] <= x1 && r[2] >= x2) {
                    intervals.add(new int[]{r[1], r[3]});
                }
            }
            if (intervals.isEmpty()) continue;
            intervals.sort((a, b) -> Integer.compare(a[0], b[0]));
            int curStart = intervals.get(0)[0];
            int curEnd = intervals.get(0)[1];
            long yTotal = 0;
            for (int j = 1; j < intervals.size(); j++) {
                int s = intervals.get(j)[0];
                int e = intervals.get(j)[1];
                if (s > curEnd) {
                    yTotal += curEnd - curStart;
                    curStart = s;
                    curEnd = e;
                } else {
                    curEnd = Math.max(curEnd, e);
                }
            }
            yTotal += curEnd - curStart;
            area = (area + yTotal * width) % MOD;
        }
        return (int) area;
    }
}

