public class Solution {
    public static void findSecretWord(List<String> wordlist, Master master) {
        List<String> possibleWords = new ArrayList<>(wordlist);
        int allowedGuesses = 10;
        for (int i = 0; i < allowedGuesses; i++) {
            String wordToGuess = possibleWords.get(0);
            int maxMatches = 0;
            for (int j = 1; j < possibleWords.size(); j++) {
                int matches = 0;
                String wj = possibleWords.get(j);
                String w0 = possibleWords.get(0);
                for (int k = 0; k < wj.length(); k++) {
                    if (wj.charAt(k) == w0.charAt(k)) {
                        matches++;
                    }
                }
                if (matches > maxMatches) {
                    maxMatches = matches;
                    wordToGuess = wj;
                }
            }
            int matches = master.guess(wordToGuess);
            if (matches == 6) {
                return;
            }
            List<String> filtered = new ArrayList<>();
            for (String word : possibleWords) {
                int count = 0;
                for (int k = 0; k < word.length(); k++) {
                    if (word.charAt(k) == wordToGuess.charAt(k)) {
                        count++;
                    }
                }
                if (count == matches) {
                    filtered.add(word);
                }
            }
            possibleWords = filtered;
        }
    }
}

class Solution {
    public int mirrorReflection(int p, int q) {
        int g = gcd(p, q);
        p /= g; q /= g;
        boolean pOdd = (p % 2 == 1), qOdd = (q % 2 == 1);
        if (pOdd && qOdd) return 1;
        if (!qOdd) return 0;
        return 2;
    }
    private int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }
}

