class Solution {
    public static TreeNode subtreeWithAllDeepest(TreeNode root) {
        int maxDepth = dfs(root);
        return findLCA(root, maxDepth - 1);
    }
    private static int dfs(TreeNode node) {
        if (node == null) return 0;
        return 1 + Math.max(dfs(node.left), dfs(node.right));
    }
    private static TreeNode findLCA(TreeNode node, int depth) {
        if (node == null) return null;
        if (depth == 0) return node;
        int leftDepth = dfs(node.left);
        int rightDepth = dfs(node.right);
        if (leftDepth == rightDepth) return node;
        if (leftDepth > rightDepth) return findLCA(node.left, depth - 1);
        return findLCA(node.right, depth - 1);
    }
}

