class Solution {
    public List<Integer> distanceK(TreeNode root, TreeNode target, int k) {
        Map<Integer, TreeNode> parentMap = new HashMap<>();
        dfs(root, null, parentMap);
        Queue<Pair> queue = new LinkedList<>();
        Set<Integer> visited = new HashSet<>();
        List<Integer> result = new ArrayList<>();
        queue.offer(new Pair(target, 0));
        visited.add(target.val);
        while (!queue.isEmpty()) {
            Pair cur = queue.poll();
            TreeNode node = cur.node;
            int distance = cur.dist;
            if (distance == k) {
                result.add(node.val);
            }
            if (distance > k) {
                break;
            }
            TreeNode[] neighbors = new TreeNode[] {
                node.left,
                node.right,
                parentMap.get(node.val)
            };
            for (TreeNode neighbor : neighbors) {
                if (neighbor != null && !visited.contains(neighbor.val)) {
                    visited.add(neighbor.val);
                    queue.offer(new Pair(neighbor, distance + 1));
                }
            }
        }
        return result;
    }

    private void dfs(TreeNode node, TreeNode parent, Map<Integer, TreeNode> parentMap) {
        if (node == null) return;
        parentMap.put(node.val, parent);
        dfs(node.left, node, parentMap);
        dfs(node.right, node, parentMap);
    }

    private static class Pair {
        TreeNode node;
        int dist;
        Pair(TreeNode n, int d) {
            this.node = n;
            this.dist = d;
        }
    }
}

