class Solution {
    public static int minRefuelStops(int target, int startFuel, int[][] stations) {
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        int stops = 0;
        int prev = 0;
        int fuel = startFuel;
        int i = 0;
        while (i < stations.length) {
            int dist = stations[i][0];
            while (fuel < dist - prev) {
                if (maxHeap.isEmpty()) {
                    return -1;
                }
                fuel += maxHeap.poll();
                stops++;
            }
            fuel -= (dist - prev);
            prev = dist;
            maxHeap.add(stations[i][1]);
            i++;
        }
        while (fuel < target - prev) {
            if (maxHeap.isEmpty()) {
                return -1;
            }
            fuel += maxHeap.poll();
            stops++;
        }
        return stops;
    }
}

