class Solution {
    public static int matrixScore(int[][] grid) {
        int score = 0;
        int rows = grid.length;
        int cols = grid[0].length;
        for (int i = 0; i < rows; i++) {
            if (grid[i][0] == 0) {
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = 1 - grid[i][j];
                }
            }
        }
        for (int j = 1; j < cols; j++) {
            int ones = 0;
            for (int i = 0; i < rows; i++) {
                if (grid[i][j] == 1) {
                    ones++;
                }
            }
            if (ones * 2 < rows) {
                for (int i = 0; i < rows; i++) {
                    grid[i][j] = 1 - grid[i][j];
                }
            }
        }
        for (int i = 0; i < rows; i++) {
            int rowScore = 0;
            for (int j = 0; j < cols; j++) {
                rowScore += grid[i][j] * (1 << (cols - 1 - j));
            }
            score += rowScore;
        }
        return score;
    }
}

