class Solution {
    public String decodeAtIndex(String s, int k) {
        long size = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) {
                size *= c - '0';
            } else {
                size++;
            }
        }
        long kk = k;
        for (int i = s.length() - 1; i >= 0; i--) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) {
                kk %= size;
                size /= c - '0';
            } else {
                if (kk == size) {
                    return String.valueOf(c);
                }
                size--;
            }
        }
        return "";
    }
}

