class Solution {
    public static int minEatingSpeed(int[] piles, int h) {
        int left = 1;
        int right = 0;
        for (int pile : piles) {
            if (pile > right) right = pile;
        }
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (canEatAll(piles, mid, h)) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }

    private static boolean canEatAll(int[] piles, int k, int h) {
        long time = 0;
        for (int pile : piles) {
            time += (pile + k - 1) / k;
            if (time > h) return false;
        }
        return time <= h;
    }
}

