                    int prev = j - earn;
                    if (prev < 0) prev = 0;
                    dp[i][j] = (dp[i][j] + dp[i - members][prev]) % MOD;
                }
            }
        }
        int ans = 0;
        for (int i = 0; i <= n; i++) {
            ans = (ans + dp[i][minProfit]) % MOD;
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    private static class Node {
        int v;
        long d;
        Node(int v, long d) {
            this.v = v;
            this.d = d;
        }
    }

    public static int reachableNodes(int[][] edges, int maxMoves, int n) {
        List<int[]>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0], v = e[1], cnt = e[2];
            int w = cnt + 1;
            graph[u].add(new int[]{v, w});
            graph[v].add(new int[]{u, w});
        }

        long[] dist = new long[n];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[0] = 0;
        PriorityQueue<Node> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a.d));
        pq.offer(new Node(0, 0));

        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            if (cur.d != dist[cur.v]) continue;
            for (int[] nb : graph[cur.v]) {
                int to = nb[0];
                int w = nb[1];
                long nd = cur.d + w;
                if (nd < dist[to]) {
                    dist[to] = nd;
                    pq.offer(new Node(to, nd));
                }
            }
        }

        long ans = 0;
        for (long d : dist) {
            if (d <= maxMoves) ans++;
        }

        for (int[] e : edges) {
            int u = e[0], v = e[1], cnt = e[2];
            long fromU = dist[u] <= maxMoves ? maxMoves - dist[u] : 0;
            long fromV = dist[v] <= maxMoves ? maxMoves - dist[v] : 0;
            ans += Math.min(cnt, fromU + fromV);
        }

        return (int) ans;
    }
}

