class Solution {
    public TreeNode constructFromPrePost(int[] preorder, int[] postorder) {
        Map<Integer, Integer> postIndexMap = new HashMap<>();
        for (int i = 0; i < postorder.length; i++) {
            postIndexMap.put(postorder[i], i);
        }
        return construct(0, preorder.length - 1, 0, postorder.length - 1, preorder, postorder, postIndexMap);
    }

    private TreeNode construct(int preStart, int preEnd, int postStart, int postEnd, int[] preorder, int[] postorder, Map<Integer, Integer> postIndexMap) {
        if (preStart > preEnd) return null;
        TreeNode root = new TreeNode(preorder[preStart]);
        if (preStart + 1 > preEnd) return root;
        int leftChildPostIndex = postIndexMap.get(preorder[preStart + 1]);
        int leftSubtreeSize = leftChildPostIndex - postStart + 1;
        root.left = construct(preStart + 1, preStart + leftSubtreeSize, postStart, leftChildPostIndex, preorder, postorder, postIndexMap);
        root.right = construct(preStart + leftSubtreeSize + 1, preEnd, leftChildPostIndex + 1, postEnd - 1, preorder, postorder, postIndexMap);
        return root;
    }
}

