class Solution {
    public static int numPermsDISequence(String s) {
        int n = s.length();
        int MOD = 1_000_000_007;
        int[][] dp = new int[n + 1][n + 1];
        dp[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            if (s.charAt(i - 1) == 'I') {
                int sum = 0;
                for (int j = 0; j <= i; j++) {
                    dp[i][j] = sum;
                    if (j < i) {
                        sum = (sum + dp[i - 1][j]) % MOD;
                    }
                }
            } else {
                int sum = 0;
                for (int j = i - 1; j >= 0; j--) {
                    sum = (sum + dp[i - 1][j]) % MOD;
                    dp[i][j] = sum;
                }
            }
        }
        int res = 0;
        for (int j = 0; j <= n; j++) {
            res = (res + dp[n][j]) % MOD;
        }
        return res;
    }
}

