class Solution {
    public static List<String> findAndReplacePattern(String[] words, String pattern) {
        List<String> result = new ArrayList<>();
        for (String word : words) {
            if (match(word, pattern)) {
                result.add(word);
            }
        }
        return result;
    }

    private static boolean match(String word, String pattern) {
        if (word.length() != pattern.length()) {
            return false;
        }
        Map<Character, Character> pToW = new HashMap<>();
        Map<Character, Character> wToP = new HashMap<>();
        for (int i = 0; i < word.length(); i++) {
            char pc = pattern.charAt(i);
            char wc = word.charAt(i);
            if (pToW.containsKey(pc) && pToW.get(pc) != wc) {
                return false;
            }
            if (wToP.containsKey(wc) && wToP.get(wc) != pc) {
                return false;
            }
            pToW.put(pc, wc);
            wToP.put(wc, pc);
        }
        return true;
    }
}

