class SolutionHelper {
    static List<List<TreeNode>> allPossibleFBTNested(int n) {
        if (n % 2 == 0) return new ArrayList<>();
        if (n == 1) {
            List<List<TreeNode>> base = new ArrayList<>();
            List<TreeNode> single = new ArrayList<>();
            single.add(new TreeNode(0));
            base.add(single);
            return base;
        }
        List<List<TreeNode>> result = new ArrayList<>();
        for (int i = 1; i < n; i += 2) {
            List<List<TreeNode>> leftTrees = allPossibleFBTNested(i);
            List<List<TreeNode>> rightTrees = allPossibleFBTNested(n - i - 1);
            for (List<TreeNode> left : leftTrees) {
                for (List<TreeNode> right : rightTrees) {
                    TreeNode root = new TreeNode(0);
                    root.left = left.get(0);
                    root.right = right.get(0);
                    List<TreeNode> wrapped = new ArrayList<>();
                    wrapped.add(root);
                    result.add(wrapped);
                }
            }
        }
        return result;
    }
}

