import java.util.*;
class FreqStack {
    private Map<Integer, Integer> frequencyMap = new HashMap<>();
    private Map<Integer, Deque<Integer>> frequencyStacks = new HashMap<>();
    private int maxFrequency = 0;
    public void push(int x) {
        int freq = frequencyMap.getOrDefault(x, 0) + 1;
        frequencyMap.put(x, freq);
        if (freq > maxFrequency) maxFrequency = freq;
        frequencyStacks.computeIfAbsent(freq, k -> new ArrayDeque<>()).push(x);
    }
    public int pop() {
        Deque<Integer> stack = frequencyStacks.get(maxFrequency);
        int result = stack.pop();
        frequencyMap.put(result, frequencyMap.get(result) - 1);
        if (stack.isEmpty()) { frequencyStacks.remove(maxFrequency); maxFrequency--; }
        return result;
    }
}

