class Solution {
    public static int sumSubseqWidths(int[] nums) {
        final long MOD = 1_000_000_007L;
        Arrays.sort(nums);
        int n = nums.length;
        long[] pow2 = new long[n];
        pow2[0] = 1;
        for (int i = 1; i < n; i++) {
            pow2[i] = (pow2[i - 1] * 2) % MOD;
        }
        long res = 0;
        for (int i = 0; i < n; i++) {
            long add = (pow2[i] - pow2[n - 1 - i] + MOD) % MOD;
            res = (res + (nums[i] % MOD) * add) % MOD;
        }
        return (int) res;
    }
}

