class Solution {
    public int atMostNGivenDigitSet(String[] digits, int n) {
        String nStr = Integer.toString(n);
        int res = 0;
        for (int i = 1; i < nStr.length(); i++) {
            res += (int) Math.pow(digits.length, i);
        }
        int[] dp = new int[nStr.length()];
        for (int i = 0; i < digits.length; i++) {
            char d = digits[i].charAt(0);
            char first = nStr.charAt(0);
            if (d < first) {
                dp[0]++;
            } else if (d == first) {
                dp[0] = 1;
                break;
            }
        }
        for (int i = 1; i < nStr.length(); i++) {
            char cur = nStr.charAt(i);
            for (int j = 0; j < digits.length; j++) {
                char d = digits[j].charAt(0);
                if (d < cur) {
                    dp[i] += dp[i - 1] * digits.length;
                } else if (d == cur) {
                    dp[i] += dp[i - 1];
                }
            }
        }
        res += dp[nStr.length() - 1];
        return res;
    }
}

