class Solution {
    public static int sumSubarrayMins(int[] arr) {
        final long MOD = 1_000_000_007L;
        int n = arr.length;
        int[] left = new int[n];
        int[] right = new int[n];
        Arrays.fill(left, -1);
        Arrays.fill(right, n);
        ArrayDeque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && arr[stack.peekLast()] >= arr[i]) {
                stack.pollLast();
            }
            if (!stack.isEmpty()) {
                left[i] = stack.peekLast();
            }
            stack.addLast(i);
        }
        stack.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && arr[stack.peekLast()] > arr[i]) {
                stack.pollLast();
            }
            if (!stack.isEmpty()) {
                right[i] = stack.peekLast();
            }
            stack.addLast(i);
        }
        long sum = 0;
        for (int i = 0; i < n; i++) {
            long leftCount = i - left[i];
            long rightCount = right[i] - i;
            sum = (sum + leftCount * rightCount % MOD * arr[i] % MOD) % MOD;
        }
        return (int) sum;
    }
}

