class Solution {
    public static int snakesAndLadders(int[][] board) {
        int n = board.length;
        boolean[] visited = new boolean[n * n + 1];
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{1, 0});
        visited[1] = true;
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int cell = cur[0];
            int steps = cur[1];
            if (cell == n * n) {
                return steps;
            }
            for (int d = 1; d <= 6; d++) {
                int next = cell + d;
                if (next > n * n) {
                    continue;
                }
                int rowFromBottom = (next - 1) / n;
                int row = n - 1 - rowFromBottom;
                int col;
                if (rowFromBottom % 2 == 0) {
                    col = (next - 1) % n;
                } else {
                    col = n - 1 - (next - 1) % n;
                }
                int dest = board[row][col] != -1 ? board[row][col] : next;
                if (!visited[dest]) {
                    visited[dest] = true;
                    queue.offer(new int[]{dest, steps + 1});
                }
            }
        }
        return -1;
    }
}

