class Solution {
    public static int smallestRangeII(int[] nums, int k) {
        Arrays.sort(nums);
        int n = nums.length;
        if (n == 1) return 0;
        int result = nums[n - 1] - nums[0];
        int minPossible = nums[0] + k;
        int maxPossible = nums[n - 1] - k;
        for (int i = 0; i < n - 1; i++) {
            int low = Math.min(minPossible, nums[i + 1] - k);
            int high = Math.max(maxPossible, nums[i] + k);
            result = Math.min(result, high - low);
        }
        return result;
    }
}

