class Solution {
    public static boolean isNStraightHand(int[] deck) {
        Map<Integer, Integer> countMap = new HashMap<>();
        for (int i = 0; i < deck.length; i++) {
            int card = deck[i];
            countMap.put(card, countMap.getOrDefault(card, 0) + 1);
        }
        List<Integer> sortedCards = new ArrayList<>(countMap.keySet());
        Collections.sort(sortedCards);
        for (int i = 0; i < sortedCards.size(); i++) {
            int card = sortedCards.get(i);
            int count = countMap.getOrDefault(card, 0);
            if (count > 0) {
                for (int j = card; j < card + count; j++) {
                    Integer val = countMap.get(j);
                    if (val == null || val < count) {
                        return false;
                    }
                    countMap.put(j, val - count);
                }
            }
        }
        return true;
    }
}

