class TopVotedCandidate {
    int[] times;
    int[] leaders;
    public TopVotedCandidate(int[] persons, int[] times) {
        this.times = times;
        this.leaders = new int[persons.length];
        Map<Integer,Integer> counts = new HashMap<>();
        int leader = -1, maxCount = 0;
        for (int i = 0; i < persons.length; i++) {
            counts.merge(persons[i], 1, Integer::sum);
            if (counts.get(persons[i]) >= maxCount) { maxCount = counts.get(persons[i]); leader = persons[i]; }
            leaders[i] = leader;
        }
    }
    public int q(int t) {
        int left = 0, right = times.length - 1;
        while (left < right) {
            int mid = (left+right+1)/2;
            if (times[mid] <= t) left = mid; else right = mid-1;
        }
        return leaders[left];
    }
}

