class Solution {
    public static int catMouseGame(int[][] graph) {
        int n = graph.length;
        int[][][] result = new int[n][n][2]; // 0: draw, 1: mouse wins, 2: cat wins
        int[][][] degree = new int[n][n][2];

        Queue<int[]> queue = new ArrayDeque<>();

        for (int m = 0; m < n; m++) {
            for (int c = 0; c < n; c++) {
                if (m == 0) {
                    result[m][c][0] = 1;
                    result[m][c][1] = 1;
                    queue.offer(new int[]{m, c, 0});
                    queue.offer(new int[]{m, c, 1});
                } else if (m == c) {
                    result[m][c][0] = 2;
                    result[m][c][1] = 2;
                    queue.offer(new int[]{m, c, 0});
                    queue.offer(new int[]{m, c, 1});
                } else {
                    degree[m][c][0] = graph[m].length;
                    int cnt = 0;
                    for (int nxt : graph[c]) {
                        if (nxt != 0) cnt++;
                    }
                    degree[m][c][1] = cnt;
                }
            }
        }

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int mouse = cur[0];
            int cat = cur[1];
            int turn = cur[2];
            int curResult = result[mouse][cat][turn];

            // Find all parent states
            if (turn == 0) { // current turn is mouse, so previous was cat
                for (int prevCat : graph[cat]) {
                    if (prevCat == 0) continue; // cat cannot be at the hole
                    if (result[mouse][prevCat][1] != 0) continue;
                    // If current state is a win for mouse, cat wants to avoid it
                    if (curResult == 1) {
                        degree[mouse][prevCat][1]--;
                        if (degree[mouse][prevCat][1] == 0) {
                            result[mouse][prevCat][1] = 1;
                            queue.offer(new int[]{mouse, prevCat, 1});
                        }
                    } else if (curResult == 2) {
                        // cat can force a win
                        result[mouse][prevCat][1] = 2;
                        queue.offer(new int[]{mouse, prevCat, 1});
                    }
                }
            } else { // turn == 1, current turn is cat, previous was mouse
                for (int prevMouse : graph[mouse]) {
                    if (result[prevMouse][cat][0] != 0) continue;
                    if (curResult == 2) {
                        degree[prevMouse][cat][0]--;
                        if (degree[prevMouse][cat][0] == 0) {
                            result[prevMouse][cat][0] = 2;
                            queue.offer(new int[]{prevMouse, cat, 0});
                        }
                    } else if (curResult == 1) {
                        result[prevMouse][cat][0] = 1;
                        queue.offer(new int[]{prevMouse, cat, 0});
                    }
                }
            }
        }

        return result[1][2][0];
    }
}

class Solution {
