class Solution {
    public static long threeSumMulti(int[] arr, int target) {
        Arrays.sort(arr);
        long count = 0;
        int n = arr.length;
        for (int i = 0; i < n - 2; i++) {
            int left = i + 1;
            int right = n - 1;
            while (left < right) {
                int sum = arr[i] + arr[left] + arr[right];
                if (sum < target) {
                    left++;
                } else if (sum > target) {
                    right--;
                } else {
                    if (arr[left] == arr[right]) {
                        long cnt = right - left + 1;
                        count += cnt * (cnt - 1) / 2;
                        break;
                    } else {
                        long leftCount = 1;
                        while (left + 1 < right && arr[left] == arr[left + 1]) {
                            leftCount++;
                            left++;
                        }
                        long rightCount = 1;
                        while (right - 1 > left && arr[right] == arr[right - 1]) {
                            rightCount++;
                            right--;
                        }
                        count += leftCount * rightCount;
                        left++;
                        right--;
                    }
                }
            }
        }
        return count;
    }
}

