class Solution {
    public static int minFallingPathSum(int[][] matrix) {
        int n = matrix.length;
        int[] dp = matrix[0].clone();
        for (int i = 1; i < n; i++) {
            int[] temp = new int[n];
            Arrays.fill(temp, Integer.MAX_VALUE);
            for (int j = 0; j < n; j++) {
                if (j == 0) {
                    temp[j] = Math.min(dp[j], dp[j + 1]) + matrix[i][j];
                } else if (j == n - 1) {
                    temp[j] = Math.min(dp[j - 1], dp[j]) + matrix[i][j];
                } else {
                    int min = Math.min(dp[j - 1], dp[j]);
                    min = Math.min(min, dp[j + 1]);
                    temp[j] = min + matrix[i][j];
                }
            }
            dp = temp;
        }
        int min = dp[0];
        for (int val : dp) {
            if (val < min) {
                min = val;
            }
        }
        return min;
    }
}

