class Solution {
    private static int find(int x, int[] parent) {
        if (parent[x] != x) {
            parent[x] = find(parent[x], parent);
        }
        return parent[x];
    }

    private static void union(int x, int y, int[] parent, int[] rank) {
        int rootX = find(x, parent);
        int rootY = find(y, parent);
        if (rootX != rootY) {
            if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }

    public static int minMalwareSpread(int[][] graph, int[] initial) {
        int n = graph.length;
        int[] parent = new int[n];
        int[] rank = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 0;
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (graph[i][j] == 1) {
                    union(i, j, parent, rank);
                }
            }
        }

        Map<Integer, Integer> groupSize = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int root = find(i, parent);
            groupSize.put(root, groupSize.getOrDefault(root, 0) + 1);
        }

        Map<Integer, Integer> infectedCount = new HashMap<>();
        for (int node : initial) {
            int root = find(node, parent);
            infectedCount.put(root, infectedCount.getOrDefault(root, 0) + 1);
        }

        int minSize = Integer.MAX_VALUE;
        int nodeToRemove = -1;
        for (int node : initial) {
            int root = find(node, parent);
            if (infectedCount.get(root) == 1) {
                int size = groupSize.get(root);
                if (size < minSize) {
                    minSize = size;
                    nodeToRemove = node;
                } else if (size == minSize && node < nodeToRemove) {
                    nodeToRemove = node;
                }
            }
        }

        if (minSize == Integer.MAX_VALUE) {
            int min = Integer.MAX_VALUE;
            for (int node : initial) {
                if (node < min) {
                    min = node;
                }
            }
            return min;
        }

        return nodeToRemove;
    }
}

import java.util.*;

public class Solution {
    public static int minMalwareSpread(int[][] graph, int[] initial) {
        int n = graph.length;
        boolean[] isInitial = new boolean[n];
        for (int v : initial) isInitial[v] = true;
        int INF = n + 1;
        int[][] dist = new int[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(dist[i], INF);
            dist[i][i] = 0;
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (graph[i][j] == 1) dist[i][j] = 1;
            }
        }
        for (int k = 0; k < n; k++) {
            for (int i = 0; i < n; i++) {
                if (dist[i][k] == INF) continue;
                for (int j = 0; j < n; j++) {
                    if (dist[k][j] == INF) continue;
                    if (dist[i][j] > dist[i][k] + dist[k][j]) {
                        dist[i][j] = dist[i][k] + dist[k][j];
                    }
                }
            }
        }
        int[] saved = new int[n];
        for (int node = 0; node < n; node++) {
            if (isInitial[node]) continue;
            int bestDist = INF;
            int cnt = 0;
            int src = -1;
            for (int v : initial) {
                int d = dist[v][node];
                if (d < bestDist) {
                    bestDist = d;
                    cnt = 1;
                    src = v;
                } else if (d == bestDist) {
                    cnt++;
                }
            }
            if (bestDist < INF && cnt == 1) {
                saved[src]++;
            }
        }
        int answer = Integer.MAX_VALUE;
        int maxSaved = -1;
        for (int v : initial) {
            if (saved[v] > maxSaved || (saved[v] == maxSaved && v < answer)) {
                maxSaved = saved[v];
                answer = v;
            }
        }
        if (maxSaved == 0) {
            answer = Arrays.stream(initial).min().orElse(0);
        }
        return answer;
    }
}

