        Arrays.fill(dp, 1L);
        for (int i = 2; i <= n; i++) {
            long[] next = new long[10];
            for (int j = 0; j < 10; j++) {
                for (int move : moves[j]) {
                    next[j] = (next[j] + dp[move]) % MOD;
                }
            }
            dp = next;
        }
        long total = 0;
        for (long count : dp) {
            total = (total + count) % MOD;
        }
        return (int) total;
    }
}

