class Solution {
    public static int shortestBridge(int[][] grid) {
        List<int[]> island = new ArrayList<>();
        findIsland(grid, island);
        return bfs(grid, island);
    }

    private static void findIsland(int[][] grid, List<int[]> island) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                if (grid[i][j] == 1) {
                    dfs(grid, i, j, island);
                    return;
                }
            }
        }
    }

    private static void dfs(int[][] grid, int i, int j, List<int[]> island) {
        if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length || grid[i][j] != 1) {
            return;
        }
        grid[i][j] = -1;
        island.add(new int[]{i, j});
        dfs(grid, i - 1, j, island);
        dfs(grid, i + 1, j, island);
        dfs(grid, i, j - 1, island);
        dfs(grid, i, j + 1, island);
    }

    private static int bfs(int[][] grid, List<int[]> island) {
        Queue<int[]> queue = new LinkedList<>(island);
        int distance = 0;
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                int[] cur = queue.poll();
                int x = cur[0];
                int y = cur[1];
                for (int[] d : dirs) {
                    int nx = x + d[0];
                    int ny = y + d[1];
                    if (nx < 0 || nx >= grid.length || ny < 0 || ny >= grid[0].length) {
                        continue;
                    }
                    if (grid[nx][ny] == 1) {
                        return distance;
                    }
                    if (grid[nx][ny] == 0) {
                        grid[nx][ny] = -1;
                        queue.offer(new int[]{nx, ny});
                    }
                }
            }
            distance++;
        }
        return distance;
    }
}

