class Solution {
    public static String[] reorderLogFiles(String[] logs) {
        List<String> letterLogs = new ArrayList<>();
        List<String> digitLogs = new ArrayList<>();
        for (String log : logs) {
            int firstSpace = log.indexOf(' ');
            String rest = log.substring(firstSpace + 1);
            int secondSpace = rest.indexOf(' ');
            String token = secondSpace == -1 ? rest : rest.substring(0, secondSpace);
            if (Character.isDigit(token.charAt(0))) {
                digitLogs.add(log);
            } else {
                letterLogs.add(log);
            }
        }
        Collections.sort(letterLogs, new Comparator<String>() {
            public int compare(String a, String b) {
                String contentA = a.substring(a.indexOf(' ') + 1);
                String contentB = b.substring(b.indexOf(' ') + 1);
                int cmp = contentA.compareTo(contentB);
                if (cmp != 0) return cmp;
                return a.compareTo(b);
            }
        });
        String[] result = new String[logs.length];
        int i = 0;
        for (String s : letterLogs) result[i++] = s;
        for (String s : digitLogs) result[i++] = s;
        return result;
    }
}

