class Solution {
    public static int[] movesToStamp(String stamp, String target) {
        int m = stamp.length();
        int n = target.length();
        char[] t = target.toCharArray();
        boolean[] visited = new boolean[n];
        List<Integer> ans = new ArrayList<>();
        int stars = 0;
        boolean changed = true;
        while (stars < n && changed) {
            changed = false;
            for (int i = 0; i <= n - m; i++) {
                if (!visited[i] && canStamp(t, i, stamp)) {
                    int replaced = doStamp(t, i, m);
                    if (replaced > 0) {
                        visited[i] = true;
                        changed = true;
                        stars += replaced;
                        ans.add(i);
                        break;
                    }
                }
            }
        }
        if (stars != n) return new int[0];
        int[] res = new int[ans.size()];
        for (int i = 0; i < ans.size(); i++) {
            res[i] = ans.get(ans.size() - 1 - i);
        }
        return res;
    }

    private static boolean canStamp(char[] t, int pos, String stamp) {
        int m = stamp.length();
        boolean hasNonQuestion = false;
        for (int j = 0; j < m; j++) {
            char c = t[pos + j];
            if (c != '?' && c != stamp.charAt(j)) {
                return false;
            }
            if (c != '?') {
                hasNonQuestion = true;
            }
        }
        return hasNonQuestion;
    }

    private static int doStamp(char[] t, int pos, int m) {
        int cnt = 0;
        for (int j = 0; j < m; j++) {
            if (t[pos + j] != '?') {
                t[pos + j] = '?';
                cnt++;
            }
        }
        return cnt;
    }
}

