class Solution {
    public static int rangeSumBST(TreeNode root, int low, int high) {
        int[] sum = new int[1];
        dfs(root, low, high, sum);
        return sum[0];
    }

    private static void dfs(TreeNode node, int low, int high, int[] sum) {
        if (node == null) return;
        dfs(node.left, low, high, sum);
        if (node.val >= low && node.val <= high) sum[0] += node.val;
        dfs(node.right, low, high, sum);
    }
}

