class Solution {
    public static int distinctSubseqII(String s) {
        final int MOD = 1_000_000_007;
        int n = s.length();
        int[] dp = new int[n + 1];
        dp[0] = 1;
        int[] last = new int[65536];
        for (int i = 1; i <= n; i++) {
            long cur = (dp[i - 1] * 2L) % MOD;
            char ch = s.charAt(i - 1);
            if (last[ch] != 0) {
                cur = (cur - dp[last[ch] - 1] + MOD) % MOD;
            }
            dp[i] = (int) cur;
            last[ch] = i;
        }
        return (dp[n] - 1 + MOD) % MOD;
    }
}

