        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                int max = Math.min(words[i].length(), words[j].length());
                for (int k = max; k > 0; k--) {
                    if (words[i].substring(words[i].length() - k).equals(words[j].substring(0, k))) {
                        overlap[i][j] = k;
                        break;
                    }
                }
            }
        }

        int total = 1 << n;
        String[][] dp = new String[total][n];
        String[][] path = new String[total][n];

        for (int i = 0; i < n; i++) {
            dp[1 << i][i] = words[i];
            path[1 << i][i] = Integer.toString(i);
        }

        for (int mask = 1; mask < total; mask++) {
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) == 0) continue;
                int prevMask = mask ^ (1 << i);
                if (prevMask == 0) continue;
                for (int j = 0; j < n; j++) {
                    if ((prevMask & (1 << j)) == 0) continue;
                    if (dp[prevMask][j] == null) continue;
                    String cand = dp[prevMask][j] + words[i].substring(overlap[j][i]);
                    String candPath = path[prevMask][j] + "," + i;
                    if (dp[mask][i] == null ||
                        cand.length() < dp[mask][i].length() ||
                        (cand.length() == dp[mask][i].length() && candPath.compareTo(path[mask][i]) < 0)) {
                        dp[mask][i] = cand;
                        path[mask][i] = candPath;
                    }
                }
            }
        }

        int fullMask = total - 1;
        String result = null;
        String resultPath = null;
        for (int i = 0; i < n; i++) {
            if (dp[fullMask][i] == null) continue;
            if (result == null ||
                dp[fullMask][i].length() < result.length() ||
                (dp[fullMask][i].length() == result.length() && path[fullMask][i].compareTo(resultPath) < 0)) {
                result = dp[fullMask][i];
                resultPath = path[fullMask][i];
            }
        }
        return result;
    }
}

