public class Solution {
    public static String largestTimeFromDigits(int[] arr) {
        int[] maxTime = new int[]{-1};
        permute(arr, 0, arr.length - 1, maxTime);
        if (maxTime[0] == -1) return "";
        int hours = maxTime[0] / 60;
        int minutes = maxTime[0] % 60;
        return String.format("%02d:%02d", hours, minutes);
    }

    private static void permute(int[] arr, int l, int r, int[] maxTime) {
        if (l == r) {
            int hours = arr[0] * 10 + arr[1];
            int minutes = arr[2] * 10 + arr[3];
            if (hours < 24 && minutes < 60) {
                maxTime[0] = Math.max(maxTime[0], hours * 60 + minutes);
            }
        } else {
            for (int i = l; i <= r; i++) {
                swap(arr, l, i);
                permute(arr, l + 1, r, maxTime);
                swap(arr, l, i);
            }
        }
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

import java.util.*;

class Solution {
    public static int removeStones(int[][] stones) {
        int n = stones.length;
        int[] parent = new int[n];
        int[] rank = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }

        java.util.function.IntUnaryOperator find = new java.util.function.IntUnaryOperator() {
            @Override
            public int applyAsInt(int x) {
                if (parent[x] != x) {
                    parent[x] = applyAsInt(parent[x]);
                }
                return parent[x];
            }
        };

        java.util.function.BiConsumer<Integer, Integer> union = (x, y) -> {
            int rootx = find.applyAsInt(x);
            int rooty = find.applyAsInt(y);
            if (rootx == rooty) return;
            if (rank[rootx] < rank[rooty]) {
                parent[rootx] = rooty;
            } else if (rank[rootx] > rank[rooty]) {
                parent[rooty] = rootx;
            } else {
                parent[rooty] = rootx;
                rank[rootx]++;
            }
        };

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (stones[i][0] == stones[j][0] || stones[i][1] == stones[j][1]) {
                    union.accept(i, j);
                }
            }
        }

        int count = 0;
        for (int i = 0; i < n; i++) {
            if (parent[i] == i) {
                count++;
            }
        }

        return n - count;
    }
}

