class Solution {
    public static int largestComponentSize(int[] nums) {
        int n = nums.length;
        DSU dsu = new DSU(n);
        Map<Integer, Integer> factorToIndex = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int num = nums[i];
            for (int factor : getPrimeFactors(num)) {
                if (!factorToIndex.containsKey(factor)) {
                    factorToIndex.put(factor, i);
                } else {
                    dsu.union(i, factorToIndex.get(factor));
                }
            }
        }
        int max = 0;
        for (int i = 0; i < n; i++) {
            max = Math.max(max, dsu.size[dsu.find(i)]);
        }
        return max == 0 ? 1 : max;
    }

    private static Set<Integer> getPrimeFactors(int n) {
        Set<Integer> factors = new HashSet<>();
        int num = n;
        for (int i = 2; i * i <= num; i++) {
            if (num % i == 0) {
                factors.add(i);
                while (num % i == 0) {
                    num /= i;
                }
            }
        }
        if (num > 1) {
            factors.add(num);
        }
        return factors;
    }

    private static class DSU {
        int[] parent;
        int[] size;

        DSU(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);
            if (rootA == rootB) return;
            if (size[rootA] < size[rootB]) {
                parent[rootA] = rootB;
                size[rootB] += size[rootA];
            } else {
                parent[rootB] = rootA;
                size[rootA] += size[rootB];
            }
        }
    }
}

