class Solution {
    public static int tallestBillboard(int[] rods) {
        Map<Integer, Integer> dp = new HashMap<>();
        dp.put(0, 0);
        for (int rod : rods) {
            Map<Integer, Integer> temp = new HashMap<>();
            for (Map.Entry<Integer, Integer> entry : dp.entrySet()) {
                int diff = entry.getKey();
                int val = entry.getValue();
                temp.put(diff, Math.max(temp.getOrDefault(diff, Integer.MIN_VALUE), val));
                int diffPlus = diff + rod;
                temp.put(diffPlus, Math.max(temp.getOrDefault(diffPlus, Integer.MIN_VALUE), val));
                int diffMinus = Math.abs(diff - rod);
                int newVal = val + Math.min(diff, rod);
                temp.put(diffMinus, Math.max(temp.getOrDefault(diffMinus, Integer.MIN_VALUE), newVal));
            }
            dp = temp;
        }
        return dp.getOrDefault(0, 0);
    }
}

