class Solution {
    public static boolean canReorderDoubled(int[] arr) {
        Map<Integer, Integer> count = new HashMap<>();
        for (int v : arr) {
            count.put(v, count.getOrDefault(v, 0) + 1);
        }
        int zeroCount = count.getOrDefault(0, 0);
        if (zeroCount % 2 != 0) {
            return false;
        }
        Integer[] sorted = new Integer[arr.length];
        for (int i = 0; i < arr.length; i++) {
            sorted[i] = arr[i];
        }
        Arrays.sort(sorted, (a, b) -> Integer.compare(Math.abs(a), Math.abs(b)));
        for (int v : sorted) {
            int cur = count.getOrDefault(v, 0);
            if (cur == 0) {
                continue;
            }
            int target = v * 2;
            int targetCount = count.getOrDefault(target, 0);
            if (targetCount < cur) {
                return false;
            }
            count.put(v, 0);
            count.put(target, targetCount - cur);
        }
        return true;
    }
}

