public class LeastOps {
    static int leastOpsExpressTarget(int x, long target) {
        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        pq.offer(new long[]{0, target});
        Set<Long> visited = new HashSet<>();
        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            long c = cur[0], t = cur[1];
            if (t == 0) return (int) (c - 1);
            if (visited.contains(t)) continue;
            visited.add(t);
            long n = 0, p = 1;
            while (p * x <= t) { p *= x; n++; }
            long l = t - p;
            pq.offer(new long[]{c + (n == 0 ? 2 : n), l});
            long h = p * x - t;
            pq.offer(new long[]{c + (n + 1), h});
        }
        return -1;
    }
}

