class Solution {
    public static double minAreaFreeRect(int[][] points) {
        int n = points.length;
        Map<Key, List<int[]>> map = new HashMap<>();
        double minArea = Double.POSITIVE_INFINITY;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int midX = points[i][0] + points[j][0];
                int midY = points[i][1] + points[j][1];
                int dx = points[i][0] - points[j][0];
                int dy = points[i][1] - points[j][1];
                int lenSq = dx * dx + dy * dy;
                Key key = new Key(midX, midY, lenSq);
                List<int[]> list = map.get(key);
                if (list != null) {
                    double mx = midX / 2.0;
                    double my = midY / 2.0;
                    double v1x = points[i][0] - mx;
                    double v1y = points[i][1] - my;
                    for (int[] pair : list) {
                        int a = pair[0];
                        double v2x = points[a][0] - mx;
                        double v2y = points[a][1] - my;
                        double cross = v1x * v2y - v1y * v2x;
                        double area = Math.abs(cross) * 2.0;
                        if (area > 0 && area < minArea) {
                            minArea = area;
                        }
                    }
                } else {
                    list = new ArrayList<>();
                    map.put(key, list);
                }
                list.add(new int[]{i, j});
            }
        }
        return minArea == Double.POSITIVE_INFINITY ? 0 : minArea;
    }

    private static class Key {
        int midX, midY, lenSq;
        Key(int mx, int my, int l) {
            this.midX = mx;
            this.midY = my;
            this.lenSq = l;
        }
        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Key)) return false;
            Key k = (Key) o;
            return midX == k.midX && midY == k.midY && lenSq == k.lenSq;
        }
        @Override
        public int hashCode() {
            int h = midX;
            h = 31 * h + midY;
            h = 31 * h + lenSq;
            return h;
        }
    }
}

