class Solution {
    public static int regionsBySlashes(String[] grid) {
        int n = grid.length;
        int size = n * 3;
        int[][] newGrid = new int[size][size];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                char c = grid[i].charAt(j);
                if (c == '/') {
                    newGrid[i * 3][j * 3 + 2] = 1;
                    newGrid[i * 3 + 1][j * 3 + 1] = 1;
                    newGrid[i * 3 + 2][j * 3] = 1;
                } else if (c == '\\') {
                    newGrid[i * 3][j * 3] = 1;
                    newGrid[i * 3 + 1][j * 3 + 1] = 1;
                    newGrid[i * 3 + 2][j * 3 + 2] = 1;
                }
            }
        }
        int count = 0;
        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (newGrid[i][j] == 0) {
                    dfs(newGrid, i, j, directions);
                    count++;
                }
            }
        }
        return count;
    }

    private static void dfs(int[][] grid, int i, int j, int[][] dirs) {
        int n = grid.length;
        if (i < 0 || i >= n || j < 0 || j >= n || grid[i][j] != 0) {
            return;
        }
        grid[i][j] = 1;
        for (int[] d : dirs) {
            dfs(grid, i + d[0], j + d[1], dirs);
        }
    }
}

