class Solution {
    public static String[] spellchecker(String[] wordlist, String[] queries) {
        Set<String> wordSet = new HashSet<>(Arrays.asList(wordlist));
        Map<String, String> lowerCaseMap = new HashMap<>();
        Map<String, String> vowelMap = new HashMap<>();
        for (String word : wordlist) {
            String lowerCaseWord = word.toLowerCase();
            lowerCaseMap.putIfAbsent(lowerCaseWord, word);
            String vowelIgnoredWord = lowerCaseWord.replaceAll("[aeiou]", "*");
            vowelMap.putIfAbsent(vowelIgnoredWord, word);
        }
        List<String> result = new ArrayList<>();
        for (String query : queries) {
            if (wordSet.contains(query)) {
                result.add(query);
            } else {
                String lowerCaseQuery = query.toLowerCase();
                if (lowerCaseMap.containsKey(lowerCaseQuery)) {
                    result.add(lowerCaseMap.get(lowerCaseQuery));
                } else {
                    String vowelIgnoredQuery = lowerCaseQuery.replaceAll("[aeiou]", "*");
                    if (vowelMap.containsKey(vowelIgnoredQuery)) {
                        result.add(vowelMap.get(vowelIgnoredQuery));
                    } else {
                        result.add("");
                    }
                }
            }
        }
        return result.toArray(new String[0]);
    }
}

