class Solution {
    public static List<Integer> numsSameConsecDiff(int n, int k) {
        List<Integer> result = new ArrayList<>();
        if (n == 1) {
            result.add(0);
        }
        for (int i = 1; i <= 9; i++) {
            backtrack(result, i, i, n, k);
        }
        Collections.sort(result);
        return result;
    }

    private static void backtrack(List<Integer> result, int num, int lastDigit, int n, int k) {
        if (String.valueOf(num).length() == n) {
            result.add(num);
            return;
        }
        if (lastDigit + k < 10) {
            backtrack(result, num * 10 + (lastDigit + k), lastDigit + k, n, k);
        }
        if (k != 0 && lastDigit - k >= 0) {
            backtrack(result, num * 10 + (lastDigit - k), lastDigit - k, n, k);
        }
    }
}

