class Solution {
    public static List<Integer> flipMatchVoyage(TreeNode root, int[] voyage) {
        List<Integer> result = new ArrayList<>();
        int[] idx = new int[]{0};
        if (dfs(root, voyage, idx, result)) {
            return result;
        } else {
            return Arrays.asList(-1);
        }
    }
    private static boolean dfs(TreeNode node, int[] voyage, int[] idx, List<Integer> result) {
        if (node == null) return true;
        if (node.val != voyage[idx[0]++]) return false;
        if (node.left != null && node.left.val != voyage[idx[0]]) {
            result.add(node.val);
            TreeNode temp = node.left;
            node.left = node.right;
            node.right = temp;
        }
        return dfs(node.left, voyage, idx, result) && dfs(node.right, voyage, idx, result);
    }
}

