class Solution {
    public static int[] pancakeSort(int[] arr) {
        int n = arr.length;
        List<Integer> flips = new ArrayList<>();
        for (int size = n; size > 1; size--) {
            int maxIdx = 0;
            for (int i = 1; i < size; i++) {
                if (arr[i] > arr[maxIdx]) {
                    maxIdx = i;
                }
            }
            if (maxIdx == size - 1) {
                continue;
            }
            if (maxIdx != 0) {
                flip(arr, size);
                flips.add(size);
                int k = size - maxIdx;
                flip(arr, k);
                flips.add(k);
                flip(arr, size);
                flips.add(size);
            } else {
                flip(arr, size);
                flips.add(size);
            }
        }
        int[] result = new int[flips.size()];
        for (int i = 0; i < flips.size(); i++) {
            result[i] = flips.get(i);
        }
        return result;
    }

    private static void flip(int[] arr, int k) {
        int i = 0, j = k - 1;
        while (i < j) {
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
            i++;
            j--;
        }
    }
}

