    }
}

import java.math.BigInteger;

class Solution {
    public static boolean isRationalEqual(String s, String t) {
        Fraction f1 = toFraction(s);
        Fraction f2 = toFraction(t);
        return f1.numerator.multiply(f2.denominator).equals(f2.numerator.multiply(f1.denominator));
    }

    private static Fraction toFraction(String str) {
        int dot = str.indexOf('.');
        String intPartStr;
        String fracPartStr = "";
        if (dot == -1) {
            intPartStr = str;
        } else {
            intPartStr = str.substring(0, dot);
            if (dot + 1 < str.length()) {
                fracPartStr = str.substring(dot + 1);
            }
        }
        if (intPartStr.isEmpty()) intPartStr = "0";

        String nonRep = "";
        String repeat = "";
        int parenIdx = fracPartStr.indexOf('(');
        if (parenIdx != -1) {
            nonRep = fracPartStr.substring(0, parenIdx);
            int closeIdx = fracPartStr.indexOf(')');
            repeat = fracPartStr.substring(parenIdx + 1, closeIdx);
        } else {
            nonRep = fracPartStr;
        }

        BigInteger intPart = new BigInteger(intPartStr);
        if (repeat.isEmpty()) {
            if (nonRep.isEmpty()) {
                return new Fraction(intPart, BigInteger.ONE);
            }
            BigInteger denom = BigInteger.TEN.pow(nonRep.length());
            BigInteger numer = intPart.multiply(denom).add(new BigInteger(nonRep));
            return reduce(numer, denom);
        } else {
            int n = nonRep.length();
            int r = repeat.length();
            BigInteger pow10n = BigInteger.TEN.pow(n);
            BigInteger pow10r = BigInteger.TEN.pow(r);
            BigInteger repeatNum = new BigInteger(repeat);
            BigInteger nonRepNum = nonRep.isEmpty() ? BigInteger.ZERO : new BigInteger(nonRep);
            BigInteger nineR = pow10r.subtract(BigInteger.ONE);
            BigInteger numerator = intPart.multiply(pow10n).multiply(nineR)
                    .add(nonRepNum.multiply(nineR))
                    .add(repeatNum);
            BigInteger denominator = pow10n.multiply(nineR);
            return reduce(numerator, denominator);
        }
    }

    private static Fraction reduce(BigInteger numer, BigInteger denom) {
        BigInteger g = numer.gcd(denom);
        return new Fraction(numer.divide(g), denom.divide(g));
    }

    private static class Fraction {
        BigInteger numerator;
        BigInteger denominator;
        Fraction(BigInteger n, BigInteger d) {
            numerator = n;
            denominator = d;
        }
    }
}

