public class Solution {
    public static int oddEvenJumps(int[] arr) {
        int n = arr.length;
        int[] nextHigher = new int[n];
        int[] nextLower = new int[n];
        Arrays.fill(nextHigher, -1);
        Arrays.fill(nextLower, -1);

        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;

        Arrays.sort(idx, (a, b) -> {
            if (arr[a] != arr[b]) return Integer.compare(arr[a], arr[b]);
            return Integer.compare(a, b);
        });
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i : idx) {
            while (!stack.isEmpty() && i > stack.peek()) {
                nextHigher[stack.pop()] = i;
            }
            stack.push(i);
        }

        Arrays.sort(idx, (a, b) -> {
            if (arr[a] != arr[b]) return Integer.compare(arr[b], arr[a]);
            return Integer.compare(a, b);
        });
        stack.clear();
        for (int i : idx) {
            while (!stack.isEmpty() && i > stack.peek()) {
                nextLower[stack.pop()] = i;
            }
            stack.push(i);
        }

        boolean[] canReachHigher = new boolean[n];
        boolean[] canReachLower = new boolean[n];
        canReachHigher[n - 1] = true;
        canReachLower[n - 1] = true;

        for (int i = n - 2; i >= 0; i--) {
            if (nextHigher[i] != -1) {
                canReachHigher[i] = canReachLower[nextHigher[i]];
            }
            if (nextLower[i] != -1) {
                canReachLower[i] = canReachHigher[nextLower[i]];
            }
        }

        int count = 0;
        for (boolean b : canReachHigher) {
            if (b) count++;
        }
        return count;
    }
}

