    public int distributeCoins(TreeNode root) {
        int[] moves = new int[1];
        dfs(root, moves);
        return moves[0];
    }
    private int dfs(TreeNode node, int[] moves) {
        if (node == null) return 0;
        int left = dfs(node.left, moves);
