    public String get(String key, int timestamp) {
        List<Node> list = map.get(key);
        if (list == null) return "";
        int lo = 0, hi = list.size() - 1, ans = -1;
        while (lo <= hi) {
            int mid = (lo+hi)>>>1;
            if (list.get(mid).timestamp <= timestamp) { ans = mid; lo = mid+1; }
            else hi = mid-1;
        }
        return ans == -1 ? "" : list.get(ans).value;
    }
}

