class Solution {
    public static int uniquePathsIII(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int nonObstacles = 0;
        int startRow = 0, startCol = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] != -1) nonObstacles++;
                if (grid[i][j] == 1) {
                    startRow = i;
                    startCol = j;
                }
            }
        }
        grid[startRow][startCol] = -2;
        int[] result = new int[1];
        backtrack(grid, startRow, startCol, 1, rows, cols, nonObstacles, result);
        return result[0];
    }

    private static void backtrack(int[][] grid, int row, int col, int steps, int rows, int cols, int nonObstacles, int[] result) {
        if (grid[row][col] == 2) {
            if (steps == nonObstacles) {
                result[0]++;
            }
            return;
        }
        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
        for (int[] d : directions) {
            int newRow = row + d[0];
            int newCol = col + d[1];
            if (newRow < 0 || newRow >= rows || newCol < 0 || newCol >= cols) continue;
            if (grid[newRow][newCol] == -1 || grid[newRow][newCol] == -2) continue;
            if (grid[newRow][newCol] == 2) {
                backtrack(grid, newRow, newCol, steps + 1, rows, cols, nonObstacles, result);
            } else {
                int temp = grid[newRow][newCol];
                grid[newRow][newCol] = -2;
                backtrack(grid, newRow, newCol, steps + 1, rows, cols, nonObstacles, result);
                grid[newRow][newCol] = temp;
            }
        }
    }
}

