class Solution {
    public static long[] sumEvenAfterQueries(int[] nums, int[][] queries) {
        long evenSum = 0;
        for (int num : nums) {
            if (num % 2 == 0) {
                evenSum += num;
            }
        }
        long[] result = new long[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int val = queries[i][0];
            int index = queries[i][1];
            if (nums[index] % 2 == 0) {
                evenSum -= nums[index];
