class Solution {
    public static String strWithout3a3b(int a, int b) {
        StringBuilder sb = new StringBuilder();
        while (a > 0 || b > 0) {
            int len = sb.length();
            boolean canPlaceA = a > 0 && !(len >= 2 && sb.charAt(len - 1) == 'a' && sb.charAt(len - 2) == 'a');
            if (canPlaceA) {
                int aRem = a - 1;
                int bRem = b;
                if (Math.max(aRem, bRem) <= 2 * (Math.min(aRem, bRem) + 1)) {
                    sb.append('a');
                    a--;
                    continue;
                }
            }
            sb.append('b');
            b--;
        }
        return sb.toString();
    }
}

