class Solution {
    public boolean isCousins(TreeNode root, int x, int y) {
        class NodeInfo {
            TreeNode node;
            int depth;
            Integer parent;
            NodeInfo(TreeNode node, int depth, Integer parent) {
                this.node = node;
                this.depth = depth;
                this.parent = parent;
            }
        }
        Queue<NodeInfo> queue = new LinkedList<>();
        queue.offer(new NodeInfo(root, 0, null));
        Integer xParent = null, yParent = null;
        int xDepth = -1, yDepth = -1;
        while (!queue.isEmpty()) {
            NodeInfo cur = queue.poll();
            TreeNode node = cur.node;
            int depth = cur.depth;
            Integer parent = cur.parent;
            if (node.val == x) {
                xDepth = depth;
                xParent = parent;
            }
            if (node.val == y) {
                yDepth = depth;
                yParent = parent;
            }
            if (xDepth != -1 && yDepth != -1) break;
            if (node.left != null) queue.offer(new NodeInfo(node.left, depth + 1, node.val));
            if (node.right != null) queue.offer(new NodeInfo(node.right, depth + 1, node.val));
        }
        return xDepth == yDepth && !Objects.equals(xParent, yParent);
    }
}

