class Solution {
    public List<List<Integer>> verticalTraversal(TreeNode root) {
        if (root == null) return new ArrayList<>();
        Map<Integer, List<Integer>> columnTable = new HashMap<>();
        int minColumn = 0, maxColumn = 0;
        Queue<NodeInfo> queue = new LinkedList<>();
        queue.offer(new NodeInfo(root, 0));
        while (!queue.isEmpty()) {
            int size = queue.size();
            Map<Integer, List<Integer>> temp = new HashMap<>();
            for (int i = 0; i < size; i++) {
                NodeInfo cur = queue.poll();
                TreeNode node = cur.node;
                int column = cur.column;
                minColumn = Math.min(minColumn, column);
                maxColumn = Math.max(maxColumn, column);
                temp.computeIfAbsent(column, k -> new ArrayList<>()).add(node.val);
                if (node.left != null) queue.offer(new NodeInfo(node.left, column - 1));
                if (node.right != null) queue.offer(new NodeInfo(node.right, column + 1));
            }
            for (Map.Entry<Integer, List<Integer>> entry : temp.entrySet()) {
                List<Integer> list = entry.getValue();
                Collections.sort(list);
                columnTable.computeIfAbsent(entry.getKey(), k -> new ArrayList<>()).addAll(list);
            }
        }
        List<List<Integer>> result = new ArrayList<>();
        for (int i = minColumn; i <= maxColumn; i++) {
            result.add(columnTable.get(i));
        }
        return result;
    }

    static class NodeInfo {
        TreeNode node;
        int column;
        NodeInfo(TreeNode node, int column) {
            this.node = node;
            this.column = column;
        }
    }
}

