public class Solution {
    public static int numSquarefulPerms(int[] nums) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int num : nums) {
            freq.put(num, freq.getOrDefault(num, 0) + 1);
        }
        int m = freq.size();
        int[] uniq = new int[m];
        int[] cnt = new int[m];
        int idx = 0;
        for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
            uniq[idx] = e.getKey();
            cnt[idx] = e.getValue();
            idx++;
        }
        List<Integer>[] adj = new List[m];
        for (int i = 0; i < m; i++) {
            adj[i] = new ArrayList<>();
            for (int j = 0; j < m; j++) {
                if (isPerfectSquare(uniq[i] + uniq[j])) {
                    adj[i].add(j);
                }
            }
        }
        int[] result = new int[1];
        int n = nums.length;
        for (int i = 0; i < m; i++) {
            if (cnt[i] == 0) continue;
            cnt[i]--;
            backtrack(i, 1, n, cnt, adj, result);
            cnt[i]++;
        }
        return result[0];
    }

    private static void backtrack(int last, int depth, int targetLen, int[] cnt, List<Integer>[] adj, int[] result) {
        if (depth == targetLen) {
            result[0]++;
            return;
        }
        for (int nxt : adj[last]) {
            if (cnt[nxt] == 0) continue;
            cnt[nxt]--;
            backtrack(nxt, depth + 1, targetLen, cnt, adj, result);
            cnt[nxt]++;
        }
    }

    private static boolean isPerfectSquare(int n) {
        int r = (int) Math.sqrt(n);
        return r * r == n;
    }
}

