                int minFreq = Math.min(entry.getValue(), wordChars.getOrDefault(c, 0));
                entry.setValue(minFreq);
            }
        }
        List<String> result = new ArrayList<>();
        for (Map.Entry<Character, Integer> entry : commonChars.entrySet()) {
            for (int i = 0; i < entry.getValue(); i++) {
                result.add(String.valueOf(entry.getKey()));
            }
        }
        return result;
    }
}

