public class Solution {
    public static int mergeStones(int[] stones, int k) {
        int n = stones.length;
        if ((n - 1) % (k - 1) != 0) return -1;
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + stones[i];
        }
        long INF = Long.MAX_VALUE / 4;
        long[][] dp = new long[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(dp[i], INF);
            dp[i][i] = 0;
        }
        for (int len = 2; len <= n; len++) {
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1;
                for (int m = i; m < j; m += k - 1) {
                    if (dp[i][m] != INF && dp[m + 1][j] != INF) {
                        dp[i][j] = Math.min(dp[i][j], dp[i][m] + dp[m + 1][j]);
                    }
                }
                if ((j - i) % (k - 1) == 0 && dp[i][j] != INF) {
                    dp[i][j] += prefix[j + 1] - prefix[i];
                }
            }
        }
        return (int) dp[0][n - 1];
    }
}

import java.util.HashSet;
import java.util.Set;

class Solution {
    public static int[] gridIllumination(int n, int[][] lamps, int[][] queries) {
        Set<String> lampSet = new HashSet<>();
        for (int[] lamp : lamps) {
            lampSet.add(lamp[0] + "," + lamp[1]);
        }

        int[] rowMap = new int[n];
        int[] colMap = new int[n];
        int[] diagMap1 = new int[2 * n - 1];
        int[] diagMap2 = new int[2 * n - 1];

        for (int[] lamp : lamps) {
            int row = lamp[0];
            int col = lamp[1];
            rowMap[row]++;
            colMap[col]++;
            diagMap1[row + col]++;
            diagMap2[row - col + n - 1]++;
        }

        int[] result = new int[queries.length];

        for (int i = 0; i < queries.length; i++) {
            int row = queries[i][0];
            int col = queries[i][1];

            if (rowMap[row] > 0 || colMap[col] > 0 || diagMap1[row + col] > 0 || diagMap2[row - col + n - 1] > 0) {
                result[i] = 1;
            }

            for (int r = Math.max(0, row - 1); r <= Math.min(n - 1, row + 1); r++) {
                for (int c = Math.max(0, col - 1); c <= Math.min(n - 1, col + 1); c++) {
                    String key = r + "," + c;
                    if (lampSet.contains(key)) {
                        rowMap[r]--;
                        colMap[c]--;
                        diagMap1[r + c]--;
                        diagMap2[r - c + n - 1]--;
                        lampSet.remove(key);
                    }
                }
            }
        }

        return result;
    }
}

class Solution {
    public static int longestOnes(int[] nums, int k) {
        int maxConsecutiveOnes = 0;
        int left = 0;
        int zerosInWindow = 0;
        for (int right = 0; right < nums.length; right++) {
            if (nums[right] == 0) zerosInWindow++;
            while (zerosInWindow > k) {
                if (nums[left] == 0) zerosInWindow--;
                left++;
            }
            maxConsecutiveOnes = Math.max(maxConsecutiveOnes, right - left + 1);
        }
        return maxConsecutiveOnes;
    }
}

