class Solution {
    public static int minDominoRotations(int[] tops, int[] bottoms) {
        int rotations = check(tops, bottoms, tops[0]);
        if (rotations == -1 || rotations == tops.length) {
            rotations = check(tops, bottoms, bottoms[0]);
        }
        return rotations;
    }

    private static int check(int[] tops, int[] bottoms, int x) {
        int rotationsA = 0;
        int rotationsB = 0;
        for (int i = 0; i < tops.length; i++) {
            if (tops[i] != x && bottoms[i] != x) {
                return -1;
            }
            if (tops[i] != x) {
                rotationsA++;
            }
            if (bottoms[i] != x) {
                rotationsB++;
            }
        }
        return Math.min(rotationsA, rotationsB);
    }
}

