class Solution {
    public static int numDupDigitsAtMostN(int n) {
        int count = 0;
        int i = 1;
        while (i <= n) {
            int num = i;
            Set<Integer> seen = new HashSet<>();
            boolean hasRepeated = false;
            while (num > 0) {
                int digit = num % 10;
                if (seen.contains(digit)) {
                    hasRepeated = true;
                    break;
                }
                seen.add(digit);
                num = num / 10;
            }
            if (!hasRepeated) {
                count++;
            }
            i++;
        }
        return n - count;
    }
}

