class Solution {
    public static int videoStitching(int[][] clips, int time) {
        Arrays.sort(clips, (a, b) -> Integer.compare(a[0], b[0]));
        int count = 0, currEnd = 0, farEnd = 0, i = 0;
        while (i < clips.length && clips[i][0] <= currEnd) {
            while (i < clips.length && clips[i][0] <= currEnd) {
                farEnd = Math.max(farEnd, clips[i][1]);
