class Solution {
    public static int longestArithmeticSubsequence(int[] nums) {
        int maxLength = 0;
        Map<Integer, Map<Integer, Integer>> sequenceLengths = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            for (int j = 0; j < i; j++) {
                int difference = nums[i] - nums[j];
                Map<Integer, Integer> inner = sequenceLengths.get(difference);
                if (inner != null && inner.containsKey(j)) {
                    inner.put(i, inner.get(j) + 1);
                } else {
                    if (inner == null) {
                        inner = new HashMap<>();
                        sequenceLengths.put(difference, inner);
                    }
                    inner.put(i, 2);
                }
                maxLength = Math.max(maxLength, inner.get(i));
            }
        }
        return maxLength;
    }
}

