class Solution {
    public static int twoCitySchedCost(int[][] costs) {
        Arrays.sort(costs, (a, b) -> (a[0] - a[1]) - (b[0] - b[1]));
        int totalCost = 0;
        int n = costs.length;
        for (int i = 0; i < n; i++) {
            totalCost += (i < n / 2) ? costs[i][0] : costs[i][1];
        }
        return totalCost;
    }
}

