class Solution {
    public static int[] numMovesStones(int a, int b, int c) {
        int[] stones = new int[]{a, b, c};
        Arrays.sort(stones);
        int left = stones[0];
        int middle = stones[1];
        int right = stones[2];
        if (right - left == 2) {
            return new int[]{0, 0};
        }
        int minMoves = 1;
        int maxMoves = right - left - 2;
        if (middle - left > 2 && right - middle > 2) {
            minMoves = 2;
        }
        return new int[]{minMoves, maxMoves};
    }
}

class Solution {
    public static int maxSumTwoNoOverlap(int[] nums, int firstLen, int secondLen) {
        int[] prefixSum = new int[nums.length + 1];
        for (int i = 0; i < nums.length; i++) {
            prefixSum[i + 1] = prefixSum[i] + nums[i];
        }
        int maxSum = Integer.MIN_VALUE;
        for (int i = 0; i <= nums.length - firstLen; i++) {
            int sum1 = prefixSum[i + firstLen] - prefixSum[i];
            for (int j = 0; j <= nums.length - secondLen; j++) {
                if (j + secondLen <= i || j >= i + firstLen) {
                    int sum2 = prefixSum[j + secondLen] - prefixSum[j];
                    maxSum = Math.max(maxSum, sum1 + sum2);
                }
            }
        }
        return maxSum;
    }
}

import java.util.*;
class StreamChecker {
    static class Node {
        Map<Character,Node> children = new HashMap<>();
        boolean end;
    }
    Node trie = new Node();
    StringBuilder stream = new StringBuilder();
    public StreamChecker(String[] words) {
        for (String word : words) {
            Node node = trie;
            for (int i = word.length()-1; i >= 0; i--) {
                char ch = word.charAt(i);
                node.children.putIfAbsent(ch, new Node());
                node = node.children.get(ch);
            }
            node.end = true;
        }
    }
    public boolean query(char letter) {
        stream.append(letter);
        Node node = trie;
        for (int i = stream.length()-1; i >= 0; i--) {
            char ch = stream.charAt(i);
            if (!node.children.containsKey(ch)) return false;
            node = node.children.get(ch);
            if (node.end) return true;
        }
        return false;
    }
}

