class Solution {
    public static int[][] colorBorder(int[][] grid, int row, int col, int color) {
        int rows = grid.length;
        int cols = grid[0].length;
        int originalColor = grid[row][col];
        Set<String> visited = new HashSet<>();
        Set<String> borderCells = new HashSet<>();
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        dfs(row, col, grid, originalColor, rows, cols, visited, borderCells, directions);
        for (String cell : borderCells) {
            String[] parts = cell.split(",");
            int r = Integer.parseInt(parts[0]);
            int c = Integer.parseInt(parts[1]);
            grid[r][c] = color;
        }
        return grid;
    }

    private static void dfs(int r, int c, int[][] grid, int originalColor, int rows, int cols,
                            Set<String> visited, Set<String> borderCells, int[][] directions) {
        if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] != originalColor) {
            return;
        }
        String key = r + "," + c;
        if (r == 0 || r == rows - 1 || c == 0 || c == cols - 1 ||
            grid[r - 1][c] != originalColor || grid[r + 1][c] != originalColor ||
            grid[r][c - 1] != originalColor || grid[r][c + 1] != originalColor) {
            borderCells.add(key);
        }
        visited.add(key);
        for (int[] dir : directions) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            String nKey = nr + "," + nc;
            if (!visited.contains(nKey)) {
                dfs(nr, nc, grid, originalColor, rows, cols, visited, borderCells, directions);
            }
        }
    }
}

