class Solution {
    public static int minScoreTriangulation(int[] values) {
        int n = values.length;
        int[][] dp = new int[n][n];
        for (int length = 2; length < n; length++) {
            for (int i = 0; i < n - length; i++) {
                int j = i + length;
                dp[i][j] = Integer.MAX_VALUE;
                for (int k = i + 1; k < j; k++) {
                    int score = values[i] * values[k] * values[j] + dp[i][k] + dp[k][j];
                    if (score < dp[i][j]) {
                        dp[i][j] = score;
                    }
                }
            }
        }
        return dp[0][n - 1];
    }
}

