class Solution {
    public static int[] numMovesStonesII(int[] stones) {
        Arrays.sort(stones);
        int n = stones.length;
        int maxMoves = Math.max(stones[n - 2] - stones[0] - n + 2,
                                stones[n - 1] - stones[1] - n + 2);
        int maxInWindow = 0;
        int left = 0;
        for (int right = 0; right < n; right++) {
            while (stones[right] - stones[left] + 1 > n) {
                left++;
            }
            maxInWindow = Math.max(maxInWindow, right - left + 1);
        }
        int minMoves = n - maxInWindow;
        if (maxInWindow == n - 1) {
            if (stones[n - 2] - stones[0] == n - 2 || stones[n - 1] - stones[1] == n - 2) {
                minMoves = 2;
            }
        }
        return new int[]{minMoves, maxMoves};
    }
}

