class Solution {
    public static boolean isEscapePossible(int[][] blocked, int[] source, int[] target) {
        Set<String> blockedSet = new HashSet<>();
        for (int i = 0; i < blocked.length; i++) {
            blockedSet.add(blocked[i][0] + "," + blocked[i][1]);
        }
        int[][] moves = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        Queue<int[]> queue = new LinkedList<>();
        Set<String> visited = new HashSet<>();
        queue.offer(new int[]{source[0], source[1]});
        visited.add(source[0] + "," + source[1]);
        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            if (current[0] == target[0] && current[1] == target[1]) {
                return true;
            }
            for (int i = 0; i < moves.length; i++) {
                int newX = current[0] + moves[i][0];
                int newY = current[1] + moves[i][1];
                if (newX >= 0 && newX < 1000000 && newY >= 0 && newY < 1000000) {
                    String key = newX + "," + newY;
                    if (!blockedSet.contains(key) && !visited.contains(key)) {
                        queue.offer(new int[]{newX, newY});
                        visited.add(key);
                    }
                }
            }
            if (queue.size() > 200) {
                return true;
            }
        }
        return false;
    }
}

