class Solution {
    public static boolean isRobotBounded(String instructions) {
        int x = 0, y = 0, dx = 0, dy = 1;
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < instructions.length(); j++) {
                char c = instructions.charAt(j);
                if (c == 'G') {
                    x += dx;
                    y += dy;
                } else if (c == 'L') {
                    int temp = dx;
                    dx = -dy;
                    dy = temp;
                } else if (c == 'R') {
                    int temp = dx;
                    dx = dy;
                    dy = -temp;
                }
            }
        }
        return x == 0 && y == 0;
    }
}

