class Solution {
    public static int lastStoneWeight(int[] stones) {
        List<Integer> list = new ArrayList<>();
        for (int s : stones) {
            list.add(s);
        }
        while (list.size() > 1) {
            list.sort(Collections.reverseOrder());
            int x = list.remove(0);
            int y = list.remove(0);
            if (x != y) {
                list.add(Math.abs(x - y));
            }
        }
        return list.isEmpty() ? 0 : list.get(0);
    }
}

