class Solution {
    public static int longestStrChain(String[] words) {
        Arrays.sort(words, Comparator.comparingInt(String::length));
        Map<String, Integer> dp = new HashMap<>();
        int maxChainLength = 1;
        for (String word : words) {
            dp.put(word, 1);
            for (int i = 0; i < word.length(); i++) {
                String predecessor = word.substring(0, i) + word.substring(i + 1);
                if (dp.containsKey(predecessor)) {
                    dp.put(word, Math.max(dp.get(word), dp.get(predecessor) + 1));
                }
            }
            maxChainLength = Math.max(maxChainLength, dp.get(word));
        }
        return maxChainLength;
    }
}

import java.util.*;

class Solution {
    private static final long BASE = 256;
    private static final long MOD = 1_000_000_007L;

    public static String longestDuplicateSubstring(String s) {
        int n = s.length();
        int left = 1, right = n - 1;
        int start = -1, maxLen = 0;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            int idx = search(s, mid);
            if (idx != -1) {
                start = idx;
                maxLen = mid;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return start == -1 ? "" : s.substring(start, start + maxLen);
    }

    private static int search(String s, int len) {
        if (len == 0) return -1;
        int n = s.length();
        long hash = 0;
        long power = 1;
        for (int i = 0; i < len; i++) {
            hash = (hash * BASE + (s.charAt(i) - 'a')) % MOD;
            if (i > 0) power = (power * BASE) % MOD;
        }
        Map<Long, List<Integer>> map = new HashMap<>();
        map.computeIfAbsent(hash, k -> new ArrayList<>()).add(0);
        for (int i = 1; i + len <= n; i++) {
            int leftChar = s.charAt(i - 1) - 'a';
            int rightChar = s.charAt(i + len - 1) - 'a';
            hash = (hash - (leftChar * power) % MOD + MOD) % MOD;
            hash = (hash * BASE + rightChar) % MOD;
            List<Integer> list = map.get(hash);
            if (list != null) {
                for (int prev : list) {
                    if (s.regionMatches(prev, s, i, len)) {
                        return i;
                    }
                }
            }
            map.computeIfAbsent(hash, k -> new ArrayList<>()).add(i);
        }
        return -1;
    }
}

