class Solution {
    public static int[] prevPermOpt1(int[] arr) {
        for (int i = arr.length - 2; i >= 0; i--) {
            if (arr[i] > arr[i + 1]) {
                int maxSmaller = Integer.MIN_VALUE;
                int maxSmallerIndex = -1;
                for (int j = i + 1; j < arr.length; j++) {
                    if (arr[j] < arr[i] && arr[j] > maxSmaller) {
                        maxSmaller = arr[j];
                        maxSmallerIndex = j;
                    }
                }
                int temp = arr[i];
                arr[i] = arr[maxSmallerIndex];
                arr[maxSmallerIndex] = temp;
                return arr;
            }
        }
        return arr;
    }
}

import java.lang.Math;

class Solution {
    public static int maxSatisfied(int[] customers, int[] grumpy, int minutes) {
        int totalSatisfied = 0;
        for (int i = 0; i < customers.length; i++) {
            if (grumpy[i] == 0) {
                totalSatisfied += customers[i];
            }
        }
        int maxAdditionalSatisfied = 0;
        int currentAdditionalSatisfied = 0;
        for (int i = 0; i < customers.length; i++) {
            currentAdditionalSatisfied += customers[i] * grumpy[i];
            if (i >= minutes) {
                currentAdditionalSatisfied -= customers[i - minutes] * grumpy[i - minutes];
            }
            maxAdditionalSatisfied = Math.max(maxAdditionalSatisfied, currentAdditionalSatisfied);
        }
        return totalSatisfied + maxAdditionalSatisfied;
    }
}

import java.util.*;

class Solution {
    public static int[] rearrangeBarcodes(int[] barcodes) {
        Map<Integer, Integer> freqMap = new HashMap<>();
        for (int v : barcodes) {
            freqMap.put(v, freqMap.getOrDefault(v, 0) + 1);
        }
        List<int[]> list = new ArrayList<>();
        for (Map.Entry<Integer, Integer> e : freqMap.entrySet()) {
            list.add(new int[]{e.getKey(), e.getValue()});
        }
        list.sort((a, b) -> {
            if (b[1] != a[1]) return b[1] - a[1];
            return b[0] - a[0];
        });
        int n = barcodes.length;
        int[] result = new int[n];
        int idx = 0;
        for (int[] pair : list) {
            int val = pair[0];
            int cnt = pair[1];
            while (cnt-- > 0) {
                if (idx >= n) idx = 1;
                result[idx] = val;
                idx += 2;
            }
        }
        return result;
    }
}

