class Solution {
    private static char find(char x, char[] parent) {
        int idx = x - 'a';
        if (parent[idx] != x) {
            parent[idx] = find(parent[idx], parent);
        }
        return parent[idx];
    }

    private static void union(char x, char y, char[] parent) {
        char rootX = find(x, parent);
        char rootY = find(y, parent);
        if (rootX > rootY) {
            parent[rootX - 'a'] = rootY;
        } else {
            parent[rootY - 'a'] = rootX;
        }
    }

    public static String smallestEquivalentString(String s1, String s2, String baseStr) {
        char[] parent = new char[26];
        for (int i = 0; i < 26; i++) {
            parent[i] = (char) ('a' + i);
        }
        for (int i = 0; i < s1.length(); i++) {
            union(s1.charAt(i), s2.charAt(i), parent);
        }
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < baseStr.length(); i++) {
            result.append(find(baseStr.charAt(i), parent));
        }
        return result.toString();
    }
}

public class Solution {
    public static String gcdOfStrings(String str1, String str2) {
        if (!((str1 + str2).equals(str2 + str1))) {
            return "";
        }
        int gcd = gcd(str1.length(), str2.length());
        return str1.substring(0, gcd);
    }
    private static int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static int maxEqualRowsAfterFlips(int[][] matrix) {
        Map<String, Integer> rowFrequency = new HashMap<>();
        int maxCount = 0;
        for (int i = 0; i < matrix.length; i++) {
            int[] row = matrix[i];
            StringBuilder sb = new StringBuilder();
            for (int val : row) {
                sb.append(val);
            }
            String hash = sb.toString();
            sb.setLength(0);
            for (int val : row) {
                sb.append(1 - val);
            }
            String flippedHash = sb.toString();
            rowFrequency.put(hash, rowFrequency.getOrDefault(hash, 0) + 1);
            rowFrequency.put(flippedHash, rowFrequency.getOrDefault(flippedHash, 0) + 1);
            int countHash = rowFrequency.get(hash);
            int countFlipped = rowFrequency.get(flippedHash);
            maxCount = Math.max(maxCount, Math.max(countHash, countFlipped));
        }
        return maxCount;
    }
}

import java.util.ArrayList;
import java.util.Collections;

class Solution {
    public static int[] addNegabinary(int[] arr1, int[] arr2) {
        int i = arr1.length - 1;
        int j = arr2.length - 1;
        int carry = 0;
        ArrayList<Integer> rev = new ArrayList<>();
        while (i >= 0 || j >= 0 || carry != 0) {
            int a = i >= 0 ? arr1[i] : 0;
            int b = j >= 0 ? arr2[j] : 0;
            int sum = a + b + carry;
            int digit = sum & 1; // equivalent to sum % 2 but always non‑negative
            rev.add(digit);
            carry = (sum - digit) / -2;
            i--;
            j--;
        }
        while (rev.size() > 1 && rev.get(rev.size() - 1) == 0) {
            rev.remove(rev.size() - 1);
        }
        Collections.reverse(rev);
        int[] result = new int[rev.size()];
        for (int k = 0; k < rev.size(); k++) {
            result[k] = rev.get(k);
        }
        return result;
    }
}

