class Solution {
    public static int numSubmatrixSumTarget(int[][] matrix, int target) {
        int count = 0;
        int rows = matrix.length;
        int cols = matrix[0].length;
        int[][] prefixSum = new int[rows + 1][cols + 1];
        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                prefixSum[i][j] = prefixSum[i - 1][j] + prefixSum[i][j - 1] - prefixSum[i - 1][j - 1] + matrix[i - 1][j - 1];
            }
        }
        for (int x1 = 0; x1 < rows; x1++) {
            for (int y1 = 0; y1 < cols; y1++) {
                for (int x2 = x1; x2 < rows; x2++) {
                    for (int y2 = y1; y2 < cols; y2++) {
                        int sum = prefixSum[x2 + 1][y2 + 1] - prefixSum[x2 + 1][y1] - prefixSum[x1][y2 + 1] + prefixSum[x1][y1];
                        if (sum == target) {
                            count++;
                        }
                    }
                }
            }
        }
        return count;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static int numTilePossibilities(String tiles) {
        int[] count = new int[1];
        Map<Character, Integer> frequency = new HashMap<>();
        for (int i = 0; i < tiles.length(); i++) {
            char c = tiles.charAt(i);
            frequency.put(c, frequency.getOrDefault(c, 0) + 1);
        }
        backtrack(frequency, count);
        return count[0];
    }

    private static void backtrack(Map<Character, Integer> frequency, int[] count) {
        for (char tile : frequency.keySet()) {
            int freq = frequency.get(tile);
            if (freq > 0) {
                count[0]++;
                frequency.put(tile, freq - 1);
                backtrack(frequency, count);
                frequency.put(tile, freq);
            }
        }
    }
}

