class Solution {
    public static long largestValuesFromLabels(int[] values, int[] labels, int numWanted, int useLimit) {
        class Item {
            int value;
            int label;
            Item(int v, int l) {
                this.value = v;
                this.label = l;
            }
        }
        Item[] items = new Item[values.length];
        for (int i = 0; i < values.length; i++) {
            items[i] = new Item(values[i], labels[i]);
        }
        Arrays.sort(items, (a, b) -> Integer.compare(b.value, a.value));
        Map<Integer, Integer> labelCount = new HashMap<>();
        long sum = 0;
        int selected = 0;
        for (Item item : items) {
            if (selected == numWanted) break;
            int cnt = labelCount.getOrDefault(item.label, 0);
            if (cnt < useLimit) {
                sum += item.value;
                labelCount.put(item.label, cnt + 1);
                selected++;
            }
        }
        return sum;
    }
}

