public class Solution {
    public static boolean carPooling(int[][] trips, int capacity) {
        int n = trips.length;
        int[][] locations = new int[n * 2][2];
        int idx = 0;
        for (int i = 0; i < n; i++) {
            locations[idx][0] = trips[i][1];
            locations[idx][1] = trips[i][0];
            idx++;
            locations[idx][0] = trips[i][2];
            locations[idx][1] = -trips[i][0];
            idx++;
        }
        Arrays.sort(locations, (a, b) -> {
            if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
            return Integer.compare(a[1], b[1]);
        });
        int currentPassengers = 0;
        for (int i = 0; i < locations.length; i++) {
            currentPassengers += locations[i][1];
            if (currentPassengers > capacity) return false;
        }
        return true;
    }
}

