interface MountainArray {
    int get(int index);
    int length();
}

public class Solution {
    public static int findInMountainArray(int target, MountainArray mountainArr) {
        int n = mountainArr.length();
        int peak = findPeak(mountainArr, n);
        int idx = binarySearch(mountainArr, target, 0, peak, true);
        if (idx != -1) {
            return idx;
        }
        return binarySearch(mountainArr, target, peak + 1, n - 1, false);
    }

    private static int findPeak(MountainArray arr, int n) {
        int left = 0, right = n - 1;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (arr.get(mid) < arr.get(mid + 1)) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }

    private static int binarySearch(MountainArray arr, int target, int left, int right, boolean asc) {
        while (left <= right) {
            int mid = left + (right - left) / 2;
            int val = arr.get(mid);
            if (val == target) {
                return mid;
            }
            if (asc) {
                if (val < target) {
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            } else {
                if (val > target) {
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }
        }
        return -1;
    }
}

import java.util.*;

class Solution {
    public static List<String> braceExpansionII(String expression) {
        int[] idx = new int[]{0};
        Set<String> resultSet = parseExpression(expression, idx);
        List<String> result = new ArrayList<>(resultSet);
        Collections.sort(result);
        return result;
    }

    private static Set<String> parseExpression(String s, int[] i) {
        Set<String> cur = new HashSet<>();
        cur.add("");
        while (i[0] < s.length() && s.charAt(i[0]) != '}' && s.charAt(i[0]) != ',') {
            Set<String> term = parseFactor(s, i);
            Set<String> next = new HashSet<>();
            for (String a : cur) {
                for (String b : term) {
                    next.add(a + b);
                }
            }
            cur = next;
        }
        return cur;
    }

    private static Set<String> parseFactor(String s, int[] i) {
        if (s.charAt(i[0]) == '{') {
            i[0]++; // skip '{'
            Set<String> union = new HashSet<>();
            while (true) {
                Set<String> expr = parseExpression(s, i);
                union.addAll(expr);
                if (i[0] < s.length() && s.charAt(i[0]) == ',') {
                    i[0]++; // skip ','
                } else {
                    break;
                }
            }
            if (i[0] < s.length() && s.charAt(i[0]) == '}') {
                i[0]++; // skip '}'
            }
            return union;
        } else {
            char c = s.charAt(i[0]++);
            return Collections.singleton(String.valueOf(c));
        }
    }
}

class Solution {
    public static int[] distributeCandies(int candies, int num_people) {
        int[] distribution = new int[num_people];
        int i = 0;
        int candiesGiven = 1;
        while (candies > 0) {
            int candiesToGive = Math.min(candiesGiven, candies);
            distribution[i] += candiesToGive;
            candies -= candiesToGive;
            i = (i + 1) % num_people;
            candiesGiven++;
        }
        return distribution;
    }
}

