class Solution {
    public static List<Integer> pathInZigZagTree(int label) {
        LinkedList<Integer> result = new LinkedList<>();
        int level = 1;
        while ((1 << level) <= label) {
            level++;
        }
        int cur = label;
        while (true) {
            result.addFirst(cur);
            if (cur == 1) {
                break;
            }
            int left = 1 << (level - 1);
            int right = (1 << level) - 1;
            cur = (left + right - cur) / 2;
            level--;
        }
        return result;
    }
}

