class Solution {
    public static int minHeightShelves(int[][] books, int shelfWidth) {
        int n = books.length;
        int[] dp = new int[n + 1];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0;
        for (int i = 1; i <= n; i++) {
            int width = 0;
            int height = 0;
            for (int j = i - 1; j >= 0; j--) {
                width += books[j][0];
                height = Math.max(height, books[j][1]);
                if (width > shelfWidth) {
                    break;
                }
                dp[i] = Math.min(dp[i], dp[j] + height);
            }
        }
        return dp[n];
    }
}

