class Solution {
    private int idx;
    private String s;
    public boolean parseBoolExpr(String expression) {
        s = expression; idx = 0;
        return parse();
    }
    private boolean parse() {
        char c = s.charAt(idx);
        if (c == 't') { idx++; return true; }
        if (c == 'f') { idx++; return false; }
        if (c == '!') {
            idx += 2;
            boolean v = parse();
            idx++;
            return !v;
        }
        if (c == '&') {
            idx += 2;
            boolean v = true;
            while (s.charAt(idx) != ')') {
                v &= parse();
                if (s.charAt(idx) == ',') idx++;
            }
            idx++;
            return v;
        }
        // c == '|'
        idx += 2;
        boolean v = false;
        while (s.charAt(idx) != ')') {
            v |= parse();
            if (s.charAt(idx) == ',') idx++;
        }
        idx++;
        return v;
    }
}

