class Solution {
    public static TreeNode lcaDeepestLeaves(TreeNode root) {
        Pair result = dfs(root);
        return result.lca;
    }

    private static Pair dfs(TreeNode node) {
        if (node == null) return new Pair(0, null);
        Pair left = dfs(node.left);
        Pair right = dfs(node.right);
        if (left.depth == right.depth) return new Pair(left.depth + 1, node);
        else if (left.depth > right.depth) return new Pair(left.depth + 1, left.lca);
        else return new Pair(right.depth + 1, right.lca);
    }

    private static class Pair {
        int depth;
        TreeNode lca;
        Pair(int depth, TreeNode lca) {
            this.depth = depth;
            this.lca = lca;
        }
    }
}

