class Solution {
    public static List<Integer> smallestSufficientTeam(String[] req_skills, List<List<String>> people) {
        Map<String, Integer> skillToBit = new HashMap<>();
        for (int i = 0; i < req_skills.length; i++) {
            skillToBit.put(req_skills[i], 1 << i);
        }
        int[] personSkills = new int[people.size()];
        for (int i = 0; i < people.size(); i++) {
            int skillBitmask = 0;
            for (String skill : people.get(i)) {
                Integer bit = skillToBit.get(skill);
                if (bit != null) {
                    skillBitmask |= bit;
                }
            }
            personSkills[i] = skillBitmask;
        }
        int totalMasks = 1 << req_skills.length;
        List<Integer>[] dp = new List[totalMasks];
        dp[0] = new ArrayList<>();
        for (int i = 0; i < people.size(); i++) {
            for (int j = totalMasks - 1; j >= 0; j--) {
                if (dp[j] != null) {
                    int combined = j | personSkills[i];
                    int newLen = dp[j].size() + 1;
                    int existingLen = dp[combined] == null ? Integer.MAX_VALUE : dp[combined].size();
                    if (newLen < existingLen) {
                        List<Integer> newTeam = new ArrayList<>(dp[j]);
                        newTeam.add(i);
                        dp[combined] = newTeam;
                    }
                }
            }
        }
        return dp[totalMasks - 1];
    }
}

