class Solution {
    public static int mctFromLeafValues(int[] arr) {
        long result = 0;
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(Integer.MAX_VALUE);
        for (int num : arr) {
            while (stack.peek() < num) {
                int mid = stack.pop();
                result += (long) mid * Math.min(stack.peek(), num);
            }
            stack.push(num);
        }
        while (stack.size() > 2) {
            int mid = stack.pop();
            result += (long) mid * stack.peek();
        }
        return (int) result;
    }
}

