class Solution {
    public static int[] shortestAlternatingPaths(int n, int[][] redEdges, int[][] blueEdges) {
        List<Integer>[] redGraph = new ArrayList[n];
        List<Integer>[] blueGraph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            redGraph[i] = new ArrayList<>();
            blueGraph[i] = new ArrayList<>();
        }
        for (int[] edge : redEdges) {
            redGraph[edge[0]].add(edge[1]);
        }
        for (int[] edge : blueEdges) {
            blueGraph[edge[0]].add(edge[1]);
        }
        int[] result = new int[n];
        Arrays.fill(result, -1);
        result[0] = 0;
        Deque<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{0, 0, 1});
        queue.add(new int[]{0, 0, 0});
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int node = cur[0];
            int length = cur[1];
            int isRed = cur[2];
            if (isRed == 1) {
                for (int neighbor : blueGraph[node]) {
                    if (result[neighbor] == -1) {
                        result[neighbor] = length + 1;
                        queue.add(new int[]{neighbor, length + 1, 0});
                    }
                }
            } else {
                for (int neighbor : redGraph[node]) {
                    if (result[neighbor] == -1) {
                        result[neighbor] = length + 1;
                        queue.add(new int[]{neighbor, length + 1, 1});
                    }
                }
            }
        }
        return result;
    }
}

