class Solution {
    public static String alphabetBoardPath(String target) {
        StringBuilder sb = new StringBuilder();
        int curRow = 0, curCol = 0;
        for (int i = 0; i < target.length(); i++) {
            char ch = target.charAt(i);
            int idx = ch - 'a';
            int targetRow = idx / 5;
            int targetCol = idx % 5;
            while (curRow > targetRow) { sb.append('U'); curRow--; }
            while (curCol > targetCol) { sb.append('L'); curCol--; }
            while (curRow < targetRow) { sb.append('D'); curRow++; }
            while (curCol < targetCol) { sb.append('R'); curCol++; }
            sb.append('!');
        }
        return sb.toString();
    }
}

import java.util.Arrays;

class Solution {
    public static int stoneGameII(int[] piles) {
        int n = piles.length;
        int[] suffixSum = new int[n + 1];
        for (int i = n - 1; i >= 0; i--) {
            suffixSum[i] = suffixSum[i + 1] + piles[i];
        }
        int[][] memo = new int[n][n + 1];
        for (int i = 0; i < n; i++) {
            Arrays.fill(memo[i], -1);
        }
        return dp(0, 1, suffixSum, memo, n);
    }

    private static int dp(int i, int m, int[] suffixSum, int[][] memo, int n) {
        if (i + 2 * m >= n) {
            return suffixSum[i];
        }
        if (memo[i][m] != -1) {
            return memo[i][m];
        }
        int maxScore = Integer.MIN_VALUE;
        for (int x = 1; x <= 2 * m; x++) {
            int score = suffixSum[i] - dp(i + x, Math.max(x, m), suffixSum, memo, n);
            if (score > maxScore) {
                maxScore = score;
            }
        }
        memo[i][m] = maxScore;
        return maxScore;
    }
}

