public class Solution {
    public static int longestDecomposition(String text) {
        return decompose(text, 0, text.length() - 1);
    }

    private static int decompose(String s, int left, int right) {
        if (left > right) {
            return 0;
        }
        for (int len = 1; len * 2 <= right - left + 1; len++) {
            if (s.substring(left, left + len).equals(s.substring(right - len + 1, right + 1))) {
                return 2 + decompose(s, left + len, right - len);
            }
        }
        return 1;
    }
}

