class Solution {
    public static boolean btreeGameWinningMove(TreeNode root, int n, int x) {
        TreeNode[] targetNode = new TreeNode[1];
        findNode(root, x, targetNode);
        int leftCount = countSize(targetNode[0].left);
        int rightCount = countSize(targetNode[0].right);
        return leftCount > n / 2 || rightCount > n / 2 || n - leftCount - rightCount - 1 > n / 2;
    }

    private static void findNode(TreeNode node, int x, TreeNode[] result) {
        if (node == null) return;
        if (node.val == x) result[0] = node;
        if (node.left != null) findNode(node.left, x, result);
        if (node.right != null) findNode(node.right, x, result);
    }

    private static int countSize(TreeNode node) {
        if (node == null) return 0;
        return 1 + countSize(node.left) + countSize(node.right);
    }
}

