class SnapshotArray {
    Map<Integer,Integer>[] snapshots;
    int snapId = 0;
    @SuppressWarnings("unchecked")
    public SnapshotArray(int length) {
        snapshots = new HashMap[length];
        for (int i = 0; i < length; i++) snapshots[i] = new HashMap<>();
    }
    public void set(int index, int val) { snapshots[index].put(snapId, val); }
    public int snap() { return snapId++; }
    public int get(int index, int snap_id) {
        int bestId = -1, bestVal = 0;
        for (Map.Entry<Integer,Integer> e : snapshots[index].entrySet()) {
            if (e.getKey() <= snap_id && e.getKey() > bestId) { bestId = e.getKey(); bestVal = e.getValue(); }
        }
        return bestVal;
    }
}

class Solution {
    public static int numRollsToTarget(int n, int k, int target) {
        final int MOD = 1_000_000_007;
        int[][] dp = new int[n + 1][target + 1];
        dp[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= target; j++) {
                for (int x = 1; x <= Math.min(j, k); x++) {
                    dp[i][j] = (int)(((long)dp[i][j] + dp[i - 1][j - x]) % MOD);
                }
            }
        }
        return dp[n][target];
    }
}

