class Solution {
    public static int maxRepOpt1(String text) {
        int[] total = new int[26];
        for (char c : text.toCharArray()) {
            total[c - 'a']++;
        }
        int max = 0;
        int n = text.length();
        int i = 0;
        while (i < n) {
            char ch = text.charAt(i);
            int j = i;
            while (j < n && text.charAt(j) == ch) {
                j++;
            }
            int curLen = j - i;
            max = Math.max(max, Math.min(curLen + 1, total[ch - 'a']));
            if (j < n && j + 1 < n && text.charAt(j + 1) == ch) {
                int k = j + 1;
                while (k < n && text.charAt(k) == ch) {
                    k++;
                }
                int nextLen = k - (j + 1);
                int merged = curLen + nextLen;
                if (total[ch - 'a'] > merged) {
                    merged++;
                }
                max = Math.max(max, merged);
            }
            i = j;
        }
        return max;
    }
}

