class MajorityChecker {
    Map<Integer,List<Integer>> indexMap = new HashMap<>();
    public MajorityChecker(int[] arr) {
        for (int i = 0; i < arr.length; i++) indexMap.computeIfAbsent(arr[i], k -> new ArrayList<>()).add(i);
    }
    public int query(int left, int right, int threshold) {
        for (Map.Entry<Integer,List<Integer>> entry : indexMap.entrySet()) {
            int count = 0;
            for (int idx : entry.getValue()) if (idx >= left && idx <= right) count++;
            if (count >= threshold) return entry.getKey();
        }
        return -1;
    }
}

