class Solution {
    public static int largest1BorderedSquare(int[][] grid) {
        int rows = grid.length;
        if (rows == 0) return 0;
        int cols = grid[0].length;
        int maxSize = Math.min(rows, cols);
        int result = 0;
        for (int size = 1; size <= maxSize; size++) {
            for (int i = 0; i <= rows - size; i++) {
                for (int j = 0; j <= cols - size; j++) {
                    if (hasBorder(grid, i, j, size)) {
                        result = Math.max(result, size * size);
                    }
                }
            }
        }
        return result;
    }

    private static boolean hasBorder(int[][] grid, int i, int j, int size) {
        int end = size - 1;
        for (int k = 0; k < size; k++) {
            if (grid[i][j + k] != 1) return false;
            if (grid[i + end][j + k] != 1) return false;
            if (grid[i + k][j] != 1) return false;
            if (grid[i + k][j + end] != 1) return false;
        }
        return true;
    }
}

