class Solution {
    public static int[] numSmallerByFrequency(String[] queries, String[] words) {
        int[] wordFreqs = new int[words.length];
        for (int i = 0; i < words.length; i++) {
            String word = words[i];
            char minChar = word.charAt(0);
            for (int j = 1; j < word.length(); j++) {
                char c = word.charAt(j);
                if (c < minChar) {
                    minChar = c;
                }
            }
            int count = 0;
            for (int j = 0; j < word.length(); j++) {
                if (word.charAt(j) == minChar) {
                    count++;
                }
            }
            wordFreqs[i] = count;
        }
        Arrays.sort(wordFreqs);
        int[] result = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            String query = queries[i];
            char minChar = query.charAt(0);
            for (int j = 1; j < query.length(); j++) {
                char c = query.charAt(j);
                if (c < minChar) {
                    minChar = c;
                }
            }
            int queryFreq = 0;
            for (int j = 0; j < query.length(); j++) {
                if (query.charAt(j) == minChar) {
                    queryFreq++;
                }
            }
            int left = 0, right = wordFreqs.length;
            while (left < right) {
                int mid = (left + right) / 2;
                if (wordFreqs[mid] > queryFreq) {
                    right = mid;
                } else {
                    left = mid + 1;
                }
            }
            result[i] = wordFreqs.length - left;
        }
        return result;
    }
}

