class Solution {
    public static int numPrimeArrangements(int n) {
        boolean[] isPrime = new boolean[n + 1];
        Arrays.fill(isPrime, true);
        isPrime[0] = false;
        isPrime[1] = false;
        for (int i = 2; i * i <= n; i++) {
            if (isPrime[i]) {
                for (int j = i * i; j <= n; j += i) {
                    isPrime[j] = false;
                }
            }
        }
        int primeCount = 0;
        int nonPrimeCount = 0;
        for (int i = 1; i <= n; i++) {
            if (isPrime[i]) {
                primeCount++;
            } else {
                nonPrimeCount++;
            }
        }
        long result = 1;
        final long MOD = 1_000_000_007L;
        for (int i = 2; i <= primeCount; i++) {
            result = (result * i) % MOD;
        }
        for (int i = 2; i <= nonPrimeCount; i++) {
            result = (result * i) % MOD;
        }
        return (int) result;
    }
}

