class Solution {
    public static List<Integer> findNumOfValidWords(String[] words, String[] puzzles) {
        Map<Integer, Integer> wordCount = new HashMap<>();
        for (String word : words) {
            int mask = 0;
            for (char c : word.toCharArray()) {
                mask |= 1 << (c - 'a');
            }
            wordCount.put(mask, wordCount.getOrDefault(mask, 0) + 1);
        }
        List<Integer> result = new ArrayList<>();
        for (String puzzle : puzzles) {
            int count = 0;
            int mask = 0;
            for (char c : puzzle.toCharArray()) {
                mask |= 1 << (c - 'a');
            }
            int firstBit = 1 << (puzzle.charAt(0) - 'a');
            for (Map.Entry<Integer, Integer> entry : wordCount.entrySet()) {
                int wordMask = entry.getKey();
                if ((wordMask & mask) == wordMask && (wordMask & firstBit) != 0) {
                    count += entry.getValue();
                }
            }
            result.add(count);
        }
        return result;
    }
}

