class Solution {
    public static String reverseParentheses(String s) {
        Deque<StringBuilder> stack = new ArrayDeque<>();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') {
                stack.push(new StringBuilder());
            } else if (c == ')') {
                StringBuilder sb = stack.pop().reverse();
                if (stack.isEmpty()) {
                    stack.push(sb);
                } else {
                    stack.peek().append(sb);
                }
            } else {
                if (stack.isEmpty()) {
                    stack.push(new StringBuilder().append(c));
                } else {
                    stack.peek().append(c);
                }
            }
        }
        return stack.isEmpty() ? "" : stack.peek().toString();
    }
}

public class Solution {
    public static int maximumSum(int[] arr) {
        int n = arr.length;
        int[] forward = new int[n];
        int[] backward = new int[n];
        int maxSum = arr[0];
        forward[0] = arr[0];
        for (int i = 1; i < n; i++) {
            forward[i] = Math.max(arr[i], forward[i - 1] + arr[i]);
            maxSum = Math.max(maxSum, forward[i]);
        }
        backward[n - 1] = arr[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            backward[i] = Math.max(arr[i], backward[i + 1] + arr[i]);
            maxSum = Math.max(maxSum, backward[i]);
        }
        for (int i = 1; i < n - 1; i++) {
            maxSum = Math.max(maxSum, forward[i - 1] + backward[i + 1]);
        }
        return maxSum;
    }
}

import java.lang.Math;

class Solution {
    public static long kConcatenationMaxSum(int[] arr, long k) {
        long MOD = 1_000_000_007L;
        long total = 0;
        long maxSub = Long.MIN_VALUE;
        long cur = 0;
        for (int v : arr) {
            total += v;
            cur = Math.max(v, cur + v);
            maxSub = Math.max(maxSub, cur);
        }
        if (k == 1) {
            long result = Math.max(0, maxSub);
            return ((result % MOD) + MOD) % MOD;
        }
        long maxPrefix = Long.MIN_VALUE;
        long prefix = 0;
        for (int v : arr) {
            prefix += v;
            maxPrefix = Math.max(maxPrefix, prefix);
        }
        long maxSuffix = Long.MIN_VALUE;
        long suffix = 0;
        for (int i = arr.length - 1; i >= 0; i--) {
            suffix += arr[i];
            maxSuffix = Math.max(maxSuffix, suffix);
        }
        long result = Math.max(maxSub, maxSuffix + maxPrefix);
        if (total > 0) {
            result = Math.max(result, maxSuffix + maxPrefix + (k - 2) * total);
        }
        result = Math.max(0, result);
        return ((result % MOD) + MOD) % MOD;
    }
}

import java.util.*;

class Solution {
    public static int makeArrayIncreasing(int[] arr1, int[] arr2) {
        int[] sortedArr2 = Arrays.stream(arr2).distinct().sorted().toArray();
        final int INF = Integer.MAX_VALUE / 2;
        Map<Integer, Integer> dp = new HashMap<>();
        dp.put(Integer.MIN_VALUE, 0);
        for (int a : arr1) {
            Map<Integer, Integer> next = new HashMap<>();
            for (Map.Entry<Integer, Integer> entry : dp.entrySet()) {
                int prev = entry.getKey();
                int ops = entry.getValue();
                if (a > prev) {
                    next.merge(a, ops, Math::min);
                }
                for (int v : sortedArr2) {
                    if (v > prev) {
                        next.merge(v, ops + 1, Math::min);
                    }
                }
            }
            dp = next;
        }
        int ans = INF;
        for (int ops : dp.values()) {
            ans = Math.min(ans, ops);
        }
        return ans == INF ? -1 : ans;
    }
}

