class Solution {
    public static List<List<Integer>> criticalConnections(int n, List<List<Integer>> connections) {
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int i = 0; i < connections.size(); i++) {
            int u = connections.get(i).get(0);
            int v = connections.get(i).get(1);
            graph[u].add(v);
            graph[v].add(u);
        }
        int[] low = new int[n];
        int[] disc = new int[n];
        boolean[] visited = new boolean[n];
        int[] parent = new int[n];
        Arrays.fill(parent, -1);
        int[] rank = new int[]{0};
        List<List<Integer>> result = new ArrayList<>();
        dfs(0, graph, low, disc, visited, parent, rank, result);
        return result;
    }

    private static void dfs(int u, List<Integer>[] graph, int[] low, int[] disc, boolean[] visited, int[] parent, int[] rank, List<List<Integer>> result) {
        disc[u] = rank[0];
        low[u] = rank[0];
        rank[0]++;
        visited[u] = true;
        for (int i = 0; i < graph[u].size(); i++) {
            int v = graph[u].get(i);
            if (!visited[v]) {
                parent[v] = u;
                dfs(v, graph, low, disc, visited, parent, rank, result);
                low[u] = Math.min(low[u], low[v]);
                if (low[v] > disc[u]) {
                    result.add(Arrays.asList(u, v));
                }
            } else if (v != parent[u]) {
                low[u] = Math.min(low[u], disc[v]);
            }
        }
    }
}

