import java.util.Deque;

class Solution {
    public static String removeDuplicates(String s, int k) {
        Deque<int[]> stack = new ArrayDeque<>();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (!stack.isEmpty() && stack.peekLast()[0] == c) {
                int[] top = stack.peekLast();
                top[1]++;
                if (top[1] == k) {
                    stack.pollLast();
                }
            } else {
                stack.addLast(new int[]{c, 1});
            }
        }
        StringBuilder result = new StringBuilder();
        for (int[] entry : stack) {
            for (int i = 0; i < entry[1]; i++) {
                result.append((char) entry[0]);
            }
        }
        return result.toString();
    }
}

import java.util.*;

class Solution {
    public static String smallestStringWithSwaps(String s, List<int[]> pairs) {
        int n = s.length();
        int[] parent = new int[n];
        int[] rank = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;

        java.util.function.IntUnaryOperator find = new java.util.function.IntUnaryOperator() {
            @Override
            public int applyAsInt(int x) {
                if (parent[x] != x) parent[x] = applyAsInt(parent[x]);
                return parent[x];
            }
        };

        java.util.function.BiConsumer<Integer, Integer> union = (x, y) -> {
            int rootX = find.applyAsInt(x);
            int rootY = find.applyAsInt(y);
            if (rootX == rootY) return;
            if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        };

        for (int[] p : pairs) union.accept(p[0], p[1]);

        Map<Integer, List<Character>> map = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int root = find.applyAsInt(i);
            map.computeIfAbsent(root, k -> new ArrayList<>()).add(s.charAt(i));
        }

        for (List<Character> list : map.values()) {
            Collections.sort(list);
        }

        char[] result = new char[n];
        for (int i = 0; i < n; i++) {
            int root = find.applyAsInt(i);
            List<Character> list = map.get(root);
            result[i] = list.remove(0);
        }

        return new String(result);
    }
}

import java.util.*;
class Skiplist {
    static class Node {
        int val; Node[] forward;
        Node(int val, int level) { this.val = val; this.forward = new Node[level]; }
    }
    int levels = 16;
    double p = 0.5;
    Node head = new Node(0, levels);
    Random rand = new Random();
    int randomLevel() {
        int lvl = 1;
        while (rand.nextDouble() < p && lvl < levels) lvl++;
        return lvl;
    }
    public boolean search(int target) {
        Node node = head;
        for (int i = levels-1; i >= 0; i--) {
            while (node.forward[i] != null && node.forward[i].val < target) node = node.forward[i];
        }
        node = node.forward[0];
        return node != null && node.val == target;
    }
    public void add(int num) {
        Node[] update = new Node[levels];
        Node node = head;
        for (int i = levels-1; i >= 0; i--) {
            while (node.forward[i] != null && node.forward[i].val < num) node = node.forward[i];
            update[i] = node;
        }
        int lvl = randomLevel();
        Node newNode = new Node(num, lvl);
        for (int i = 0; i < lvl; i++) {
            newNode.forward[i] = update[i].forward[i];
            update[i].forward[i] = newNode;
        }
    }
    public boolean erase(int num) {
        Node[] update = new Node[levels];
        Node node = head;
        for (int i = levels-1; i >= 0; i--) {
            while (node.forward[i] != null && node.forward[i].val < num) node = node.forward[i];
            update[i] = node;
        }
        node = node.forward[0];
        if (node == null || node.val != num) return false;
        for (int i = 0; i < levels; i++) {
            if (update[i].forward[i] != node) break;
            update[i].forward[i] = node.forward[i];
        }
        return true;
    }
}

import java.util.*;

public class H3 {
    static List<Integer> topo(List<List<Integer>> adj, int[] indegIn, int count) {
        int[] indeg = indegIn.clone();
        Deque<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < count; i++) if (indeg[i] == 0) q.add(i);
        List<Integer> order = new ArrayList<>();
        while (!q.isEmpty()) {
            int u = q.poll();
            order.add(u);
            for (int v : adj.get(u)) {
                if (--indeg[v] == 0) q.add(v);
            }
        }
        return order.size() == count ? order : null;
    }

    static int[] sortItems(int n, int m, int[] groupIn, List<List<Integer>> beforeItems) {
        int[] group = groupIn.clone();
        int nextGroupId = m;
        for (int i = 0; i < n; i++) {
            if (group[i] == -1) group[i] = nextGroupId++;
        }
        int totalGroups = nextGroupId;

        List<List<Integer>> itemAdj = new ArrayList<>();
        for (int i = 0; i < n; i++) itemAdj.add(new ArrayList<>());
        int[] itemIndeg = new int[n];
        List<List<Integer>> groupAdj = new ArrayList<>();
        for (int i = 0; i < totalGroups; i++) groupAdj.add(new ArrayList<>());
        int[] groupIndeg = new int[totalGroups];

        for (int i = 0; i < n; i++) {
            for (int b : beforeItems.get(i)) {
                itemAdj.get(b).add(i);
                itemIndeg[i]++;
                if (group[b] != group[i]) {
                    groupAdj.get(group[b]).add(group[i]);
                    groupIndeg[group[i]]++;
                }
            }
        }

        List<Integer> itemOrder = topo(itemAdj, itemIndeg, n);
        if (itemOrder == null) return new int[0];
        List<Integer> groupOrder = topo(groupAdj, groupIndeg, totalGroups);
        if (groupOrder == null) return new int[0];

        List<List<Integer>> itemsByGroup = new ArrayList<>();
        for (int i = 0; i < totalGroups; i++) itemsByGroup.add(new ArrayList<>());
        for (int item : itemOrder) itemsByGroup.get(group[item]).add(item);

        int[] result = new int[n];
        int idx = 0;
        for (int g : groupOrder) {
            for (int item : itemsByGroup.get(g)) result[idx++] = item;
        }
        return result;
    }

    static boolean isValid(int n, int[] group, List<List<Integer>> beforeItems, int[] order) {
        if (order.length != n) return false;
        int[] pos = new int[n];
        for (int i = 0; i < n; i++) pos[order[i]] = i;
        for (int i = 0; i < n; i++) {
            for (int b : beforeItems.get(i)) {
                if (pos[b] > pos[i]) return false;
            }
        }
        Map<Integer, int[]> seen = new HashMap<>();
        for (int idx = 0; idx < n; idx++) {
            int g = group[order[idx]];
            if (g == -1) continue;
            if (!seen.containsKey(g)) seen.put(g, new int[]{idx, idx});
            else seen.get(g)[1] = idx;
        }
        for (Map.Entry<Integer, int[]> e : seen.entrySet()) {
            int g = e.getKey();
            for (int idx = e.getValue()[0]; idx <= e.getValue()[1]; idx++) {
                if (group[order[idx]] != g) return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        int n = 8, m = 2;
        int[] group = {-1,-1,1,0,0,1,0,-1};
        List<List<Integer>> before = Arrays.asList(
            Arrays.asList(), Arrays.asList(6), Arrays.asList(5), Arrays.asList(6),
            Arrays.asList(3,6), Arrays.asList(), Arrays.asList(), Arrays.asList()
        );
        int[] got = sortItems(n, m, group, before);
        System.out.println(Arrays.toString(got) + " valid? " + isValid(n, group, before, got));

        List<List<Integer>> before2 = Arrays.asList(
            Arrays.asList(), Arrays.asList(6), Arrays.asList(5), Arrays.asList(6),
            Arrays.asList(3), Arrays.asList(), Arrays.asList(4), Arrays.asList()
        );
        int[] got2 = sortItems(n, m, group, before2);
        System.out.println("size=" + got2.length + " expected 0");
    }
}

import java.util.*;

class Solution {
    public static int minimumMoves(int[][] grid) {
        int n = grid.length;
        boolean[][][] visited = new boolean[n][n][2];
        ArrayDeque<int[]> q = new ArrayDeque<>();
        // orientation: 0 = horizontal, 1 = vertical
        q.offer(new int[]{0, 0, 0, 0});
        visited[0][0][0] = true;
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1], o = cur[2], steps = cur[3];
            if (o == 0 && r == n - 1 && c == n - 2) {
                return steps;
            }
            if (o == 0) { // horizontal
                // move right
                if (c + 2 < n && grid[r][c + 2] == 0 && !visited[r][c + 1][0]) {
                    visited[r][c + 1][0] = true;
                    q.offer(new int[]{r, c + 1, 0, steps + 1});
                }
                // move down
                if (r + 1 < n && grid[r + 1][c] == 0 && grid[r + 1][c + 1] == 0 && !visited[r + 1][c][0]) {
                    visited[r + 1][c][0] = true;
                    q.offer(new int[]{r + 1, c, 0, steps + 1});
                }
                // rotate clockwise to vertical
                if (r + 1 < n && grid[r + 1][c] == 0 && grid[r + 1][c + 1] == 0 && !visited[r][c][1]) {
                    visited[r][c][1] = true;
                    q.offer(new int[]{r, c, 1, steps + 1});
                }
            } else { // vertical
                // move down
                if (r + 2 < n && grid[r + 2][c] == 0 && !visited[r + 1][c][1]) {
                    visited[r + 1][c][1] = true;
                    q.offer(new int[]{r + 1, c, 1, steps + 1});
                }
                // move right
                if (c + 1 < n && grid[r][c + 1] == 0 && grid[r + 1][c + 1] == 0 && !visited[r][c + 1][1]) {
                    visited[r][c + 1][1] = true;
                    q.offer(new int[]{r, c + 1, 1, steps + 1});
                }
                // rotate counterclockwise to horizontal
                if (c + 1 < n && grid[r][c + 1] == 0 && grid[r + 1][c + 1] == 0 && !visited[r][c][0]) {
                    visited[r][c][0] = true;
                    q.offer(new int[]{r, c, 0, steps + 1});
                }
            }
        }
        return -1;
    }
}

