class Solution {
    public static int countVowelPermutation(int n) {
        final int MOD = 1_000_000_007;
        long[] dp = {1, 1, 1, 1, 1};
        for (int i = 2; i <= n; i++) {
            long[] temp = new long[5];
            temp[1] = (temp[1] + dp[0]) % MOD; // a -> e
            temp[0] = (temp[0] + dp[1]) % MOD; // e -> a
            temp[2] = (temp[2] + dp[1]) % MOD; // e -> i
            temp[0] = (temp[0] + dp[2]) % MOD; // i -> a
            temp[1] = (temp[1] + dp[2]) % MOD; // i -> e
            temp[3] = (temp[3] + dp[2]) % MOD; // i -> o
            temp[4] = (temp[4] + dp[2]) % MOD; // i -> u
            temp[2] = (temp[2] + dp[3]) % MOD; // o -> i
            temp[4] = (temp[4] + dp[3]) % MOD; // o -> u
            temp[0] = (temp[0] + dp[4]) % MOD; // u -> a (only)
            dp = temp;
        }
        long total = 0;
        for (long v : dp) total = (total + v) % MOD;
        return (int) total;
    }
}

