class Solution {
    private static int maxGold;

    public static int getMaximumGold(int[][] grid) {
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        maxGold = 0;
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                if (grid[i][j] != 0) {
                    Set<String> visited = new HashSet<>();
                    visited.add(i + "," + j);
                    backtrack(grid, directions, i, j, grid[i][j], visited);
                }
            }
        }
        return maxGold;
    }

    private static void backtrack(int[][] grid, int[][] directions, int row, int col, int currentGold, Set<String> visited) {
        maxGold = Math.max(maxGold, currentGold);
        for (int i = 0; i < 4; i++) {
            int newRow = row + directions[i][0];
            int newCol = col + directions[i][1];
            if (newRow >= 0 && newRow < grid.length && newCol >= 0 && newCol < grid[0].length
                    && grid[newRow][newCol] != 0 && !visited.contains(newRow + "," + newCol)) {
                visited.add(newRow + "," + newCol);
                backtrack(grid, directions, newRow, newCol, currentGold + grid[newRow][newCol], visited);
                visited.remove(newRow + "," + newCol);
            }
        }
    }
}

public class Solution {
    public static boolean checkStraightLine(int[][] coordinates) {
        int x0 = coordinates[0][0];
        int y0 = coordinates[0][1];
        int x1 = coordinates[1][0];
        int y1 = coordinates[1][1];
        if (x1 - x0 == 0) {
            for (int i = 2; i < coordinates.length; i++) {
                if (coordinates[i][0] != x0) return false;
            }
            return true;
        } else {
            double slope = (double) (y1 - y0) / (x1 - x0);
            for (int i = 2; i < coordinates.length; i++) {
                int xi = coordinates[i][0];
                int yi = coordinates[i][1];
                if ((double) (yi - y0) / (xi - x0) != slope) return false;
            }
            return true;
        }
    }
}

