class Solution {
    public static int[] circularPermutation(int n, int start) {
        int size = 1 << n;
        int[] gray = new int[size];
        for (int i = 0; i < size; i++) {
            gray[i] = i ^ (i >> 1);
        }
        int startIdx = 0;
        while (startIdx < size && gray[startIdx] != start) {
            startIdx++;
        }
        int[] result = new int[size];
        for (int i = 0; i < size; i++) {
            result[i] = gray[(startIdx + i) % size];
        }
        return result;
    }
}

