class Solution {
    public static List<int[]> findSolution(int function_id, int z) {
        List<int[]> result = new ArrayList<>();
        for (int x = 1; x <= z; x++) {
            for (int y = 1; y <= z; y++) {
                if (evaluate(function_id, x, y) == z) {
                    result.add(new int[]{x, y});
                }
            }
        }
        return result;
    }

    private static int evaluate(int function_id, int x, int y) {
        if (function_id == 1) {
            return x + y;
        } else if (function_id == 2) {
            return x * y;
        }
        return 0;
    }
}

