        int currentSum = 0;
        long count = 0;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] % 2 != 0) currentSum++;
            Integer freq = prefixSumCount.get(currentSum - k);
            if (freq != null) count += freq;
            prefixSumCount.put(currentSum, prefixSumCount.getOrDefault(currentSum, 0) + 1);
        }
        return count;
    }
}

