class Solution {
    public static int balancedString(String s) {
        int n = s.length();
        int[] count = new int[256];
        for (int i = 0; i < n; i++) {
            count[s.charAt(i)]++;
        }
        int target = n / 4;
        int diff = 0;
        for (int i = 0; i < 4; i++) {
            char ch = (char) ('Q' + i);
            if (count[ch] > target) {
                diff += count[ch] - target;
            }
        }
        if (diff == 0) {
            return 0;
        }
        int res = n;
        int left = 0;
        for (int right = 0; right < n; right++) {
            char rc = s.charAt(right);
            count[rc]--;
            if (count[rc] >= target) {
                diff--;
            }
            while (diff == 0) {
                res = Math.min(res, right - left + 1);
                char lc = s.charAt(left);
                count[lc]++;
                if (count[lc] > target) {
                    diff++;
                }
                left++;
            }
        }
        return res;
    }
}

