class Solution {
    public static int maxSumDivisibleByThree(int[] nums) {
        int sentinel = Integer.MIN_VALUE;
        int[] dp = new int[3];
        dp[0] = 0;
        dp[1] = sentinel;
        dp[2] = sentinel;
        for (int cur : nums) {
            int[] next = dp.clone();
            for (int r = 0; r < 3; r++) {
                if (dp[r] != sentinel) {
                    int newR = (r + cur) % 3;
                    next[newR] = Math.max(next[newR], dp[r] + cur);
                }
            }
            dp = next;
        }
        return dp[0];
    }
}

