class Solution {
    public static int[][] shiftGrid(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;
        int total = m * n;
        k %= total;
        if (k == 0) {
            return grid;
        }
        int[][] result = new int[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int oldIdx = i * n + j;
                int newIdx = (oldIdx + k) % total;
                int newRow = newIdx / n;
                int newCol = newIdx % n;
                result[newRow][newCol] = grid[i][j];
            }
        }
        return result;
    }
}

