class Solution {
    public static List<List<String>> suggestedProducts(List<String> products, String searchWord) {
        Collections.sort(products);
        List<List<String>> result = new ArrayList<>();
        int n = products.size();
        for (int i = 1; i <= searchWord.length(); i++) {
            String prefix = searchWord.substring(0, i);
            int left = 0, right = n;
            while (left < right) {
                int mid = (left + right) >>> 1;
                if (products.get(mid).compareTo(prefix) < 0) {
                    left = mid + 1;
                } else {
                    right = mid;
                }
            }
            List<String> suggestions = new ArrayList<>();
            for (int j = left; j < Math.min(left + 3, n); j++) {
                if (products.get(j).startsWith(prefix)) {
                    suggestions.add(products.get(j));
                } else {
                    break;
                }
            }
            result.add(suggestions);
        }
        return result;
    }
}

