public class Solution {
    public static int minPushBox(char[][] grid) {
        int m = grid.length, n = grid[0].length;
        int sx = -1, sy = -1, bx = -1, by = -1, tx = -1, ty = -1;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                char c = grid[i][j];
                if (c == 'S') {
                    sx = i;
                    sy = j;
                } else if (c == 'B') {
                    bx = i;
                    by = j;
                } else if (c == 'T') {
                    tx = i;
                    ty = j;
                }
            }
        }
        if (bx == tx && by == ty) return 0;
        int[] dx = {1, -1, 0, 0};
        int[] dy = {0, 0, 1, -1};
        boolean[][][][] visited = new boolean[m][n][m][n];
        ArrayDeque<int[]> q = new ArrayDeque<>();
        q.offer(new int[]{bx, by, sx, sy, 0});
        visited[bx][by][sx][sy] = true;
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int cbx = cur[0], cby = cur[1], cpx = cur[2], cpy = cur[3], pushes = cur[4];
            if (cbx == tx && cby == ty) return pushes;
            for (int dir = 0; dir < 4; dir++) {
                int nbx = cbx + dx[dir];
                int nby = cby + dy[dir];
                int reqPx = cbx - dx[dir];
                int reqPy = cby - dy[dir];
                if (!inside(nbx, nby, m, n) || grid[nbx][nby] == '#') continue;
                if (!inside(reqPx, reqPy, m, n) || grid[reqPx][reqPy] == '#') continue;
                if (!canReach(grid, cpx, cpy, reqPx, reqPy, cbx, cby)) continue;
                if (!visited[nbx][nby][cbx][cby]) {
                    visited[nbx][nby][cbx][cby] = true;
                    q.offer(new int[]{nbx, nby, cbx, cby, pushes + 1});
                }
            }
        }
        return -1;
    }

    private static boolean inside(int x, int y, int m, int n) {
        return x >= 0 && x < m && y >= 0 && y < n;
    }

    private static boolean canReach(char[][] grid, int sx, int sy, int tx, int ty, int bx, int by) {
        int m = grid.length, n = grid[0].length;
        if (sx == tx && sy == ty) return true;
        boolean[][] visited = new boolean[m][n];
        ArrayDeque<int[]> dq = new ArrayDeque<>();
        dq.offer(new int[]{sx, sy});
        visited[sx][sy] = true;
        int[] dx = {1, -1, 0, 0};
        int[] dy = {0, 0, 1, -1};
        while (!dq.isEmpty()) {
            int[] cur = dq.poll();
            int x = cur[0], y = cur[1];
            for (int dir = 0; dir < 4; dir++) {
                int nx = x + dx[dir];
                int ny = y + dy[dir];
                if (!inside(nx, ny, m, n) || visited[nx][ny]) continue;
                if (grid[nx][ny] == '#') continue;
                if (nx == bx && ny == by) continue;
                if (nx == tx && ny == ty) return true;
                visited[nx][ny] = true;
                dq.offer(new int[]{nx, ny});
            }
        }
        return false;
    }
}

