class Solution {
    public static String tictactoe(int[][] moves) {
        int[] rowsA = {0, 0, 0};
        int[] colsA = {0, 0, 0};
        int diagA = 0, antiA = 0;
        int[] rowsB = {0, 0, 0};
        int[] colsB = {0, 0, 0};
        int diagB = 0, antiB = 0;

        for (int i = 0; i < moves.length; i++) {
            int r = moves[i][0];
            int c = moves[i][1];
            boolean isA = i % 2 == 0;
            int[] rows = isA ? rowsA : rowsB;
            int[] cols = isA ? colsA : colsB;
            int diag = isA ? diagA : diagB;
            int anti = isA ? antiA : antiB;

            rows[r]++;
            cols[c]++;
            if (r == c) diag++;
            if (r + c == 2) anti++;

            if (rows[r] == 3 || cols[c] == 3 || diag == 3 || anti == 3) {
                return isA ? "A" : "B";
            }

            if (isA) {
                diagA = diag;
                antiA = anti;
            } else {
                diagB = diag;
                antiB = anti;
            }
        }

        return moves.length == 9 ? "Draw" : "Pending";
    }
}

