class Solution {
    public static int countSquares(int[][] matrix) {
        int rows = matrix.length;
        if (rows == 0) return 0;
        int cols = matrix[0].length;
        int[] dp = new int[cols];
        int total = 0;
        int prevDiag = 0;
        for (int i = 0; i < rows; i++) {
            prevDiag = 0;
            for (int j = 0; j < cols; j++) {
                int temp = dp[j];
                if (matrix[i][j] == 1) {
                    if (i == 0 || j == 0) {
                        dp[j] = 1;
                    } else {
                        dp[j] = Math.min(Math.min(dp[j], dp[j - 1]), prevDiag) + 1;
                    }
                    total += dp[j];
                } else {
                    dp[j] = 0;
                }
                prevDiag = temp;
            }
        }
        return total;
    }
}

import java.util.Arrays;

class Solution {
    public static int palindromePartition(String s, int k) {
        int n = s.length();
        int INF = 1_000_000_000;
        int[][] cost = new int[n][n];
        for (int len = 2; len <= n; ++len) {
            for (int i = 0; i + len - 1 < n; ++i) {
                int j = i + len - 1;
                if (len == 2) {
                    cost[i][j] = s.charAt(i) == s.charAt(j) ? 0 : 1;
                } else {
                    cost[i][j] = cost[i + 1][j - 1] + (s.charAt(i) == s.charAt(j) ? 0 : 1);
                }
            }
        }
        int[] dpPrev = new int[n + 1];
        int[] dpCurr = new int[n + 1];
        Arrays.fill(dpPrev, INF);
        dpPrev[0] = 0;
        for (int p = 1; p <= k; ++p) {
            Arrays.fill(dpCurr, INF);
            for (int i = 1; i <= n; ++i) {
                int best = INF;
                for (int j = 0; j < i; ++j) {
                    int cand = dpPrev[j] + cost[j][i - 1];
                    if (cand < best) {
                        best = cand;
                    }
                }
                dpCurr[i] = best;
            }
            int[] tmp = dpPrev;
            dpPrev = dpCurr;
            dpCurr = tmp;
        }
        return dpPrev[n];
    }
}

public class Solution {
    public static int subtractProductAndSum(int n) {
        if (n == 0) return 0;
        int product = 1;
        int sum = 0;
        while (n > 0) {
            int digit = n % 10;
            product *= digit;
            sum += digit;
            n = n / 10;
        }
        return product - sum;
    }
}

