class Solution {
    public static int smallestDivisor(int[] nums, int threshold) {
        int low = 1;
        int high = nums[0];
        for (int num : nums) {
            if (num > high) high = num;
        }
        int answer = high;
        while (low <= high) {
            int mid = (low + high) / 2;
            long sum = 0;
            for (int num : nums) {
                sum += (int) Math.ceil((double) num / mid);
                if (sum > threshold) break;
            }
            if (sum <= threshold) {
                answer = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return answer;
    }
}

