class CombinationIterator {
    List<String> combos = new ArrayList<>();
    int idx = 0;
    public CombinationIterator(String characters, int combinationLength) {
        int n = characters.length();
        StringBuilder cur = new StringBuilder();
        dfs(0, characters, combinationLength, n, cur);
    }
    void dfs(int start, String characters, int combinationLength, int n, StringBuilder cur) {
        if (cur.length() == combinationLength) { combos.add(cur.toString()); return; }
        for (int i = start; i < n; i++) {
            cur.append(characters.charAt(i));
            dfs(i+1, characters, combinationLength, n, cur);
            cur.deleteCharAt(cur.length()-1);
        }
    }
    public String next() { return combos.get(idx++); }
    public boolean hasNext() { return idx < combos.size(); }
}

