class Solution {
    public static int minFallingPathSum(int[][] grid) {
        int n = grid.length;
        if (n == 0) return 0;
        int[] prev = grid[0].clone();
        int min1 = Integer.MAX_VALUE, min2 = Integer.MAX_VALUE, idx1 = -1;
        for (int j = 0; j < n; j++) {
            int v = prev[j];
            if (v < min1) {
                min2 = min1;
                min1 = v;
                idx1 = j;
            } else if (v < min2) {
                min2 = v;
            }
        }
        for (int i = 1; i < n; i++) {
            int[] cur = new int[n];
            int newMin1 = Integer.MAX_VALUE, newMin2 = Integer.MAX_VALUE, newIdx1 = -1;
            for (int j = 0; j < n; j++) {
                int bestPrev = (j == idx1) ? min2 : min1;
                cur[j] = grid[i][j] + bestPrev;
                int val = cur[j];
                if (val < newMin1) {
                    newMin2 = newMin1;
                    newMin1 = val;
                    newIdx1 = j;
                } else if (val < newMin2) {
                    newMin2 = val;
                }
            }
            prev = cur;
            min1 = newMin1;
            min2 = newMin2;
            idx1 = newIdx1;
        }
        return min1;
    }
}

