class Solution {
    public static int minFlips(int[][] mat) {
        int m = mat.length;
        int n = mat[0].length;
        int total = m * n;

        int startMask = 0;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (mat[r][c] == 1) {
                    startMask |= 1 << (r * n + c);
                }
            }
        }
        if (startMask == 0) return 0;

        int[] flipMask = new int[total];
        int[][] dirs = {{0,0},{1,0},{-1,0},{0,1},{0,-1}};
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                int mask = 0;
                for (int[] d : dirs) {
                    int nr = r + d[0];
                    int nc = c + d[1];
                    if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                        mask |= 1 << (nr * n + nc);
                    }
                }
                flipMask[r * n + c] = mask;
            }
        }

        Set<Integer> visited = new HashSet<>();
        Deque<int[]> queue = new ArrayDeque<>();
        visited.add(startMask);
        queue.offer(new int[]{startMask, 0});

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int curMask = cur[0];
            int steps = cur[1];
            for (int i = 0; i < total; i++) {
                int nextMask = curMask ^ flipMask[i];
                if (nextMask == 0) return steps + 1;
                if (!visited.contains(nextMask)) {
                    visited.add(nextMask);
                    queue.offer(new int[]{nextMask, steps + 1});
                }
            }
        }
        return -1;
    }
}

