class Solution {
    public static int maxSideLength(int[][] mat, int threshold) {
        int m = mat.length;
        int n = mat[0].length;
        long[][] pref = new long[m + 1][n + 1];
        for (int i = 0; i < m; i++) {
            long rowSum = 0;
            for (int j = 0; j < n; j++) {
                rowSum += mat[i][j];
                pref[i + 1][j + 1] = pref[i][j + 1] + rowSum;
            }
        }
        int lo = 0, hi = Math.min(m, n);
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            if (canFit(mid, pref, m, n, threshold)) {
                lo = mid;
            } else {
                hi = mid - 1;
            }
        }
        return lo;
    }

    private static boolean canFit(int k, long[][] pref, int m, int n, int threshold) {
        for (int i = k; i <= m; i++) {
            for (int j = k; j <= n; j++) {
                long total = pref[i][j] - pref[i - k][j] - pref[i][j - k] + pref[i - k][j - k];
                if (total <= threshold) {
                    return true;
                }
            }
        }
        return false;
    }
}

