import java.util.ArrayDeque;
import java.util.Arrays;

class Solution {
    public static int shortestPath(int[][] grid, int k) {
        int rows = grid.length;
        int cols = grid[0].length;
        if (k >= rows + cols - 2) return rows + cols - 2;
        if (rows == 1 && cols == 1) return 0;
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        int[][] visited = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            Arrays.fill(visited[i], -1);
        }
        ArrayDeque<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{0, 0, k, 0});
        visited[0][0] = k;
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0];
            int c = cur[1];
            int remain = cur[2];
            int steps = cur[3];
            for (int[] d : dirs) {
                int nr = r + d[0];
                int nc = c + d[1];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
                int newRemain = remain - grid[nr][nc];
                if (newRemain < 0) continue;
                if (nr == rows - 1 && nc == cols - 1) return steps + 1;
                if (visited[nr][nc] >= newRemain) continue;
                visited[nr][nc] = newRemain;
                queue.offer(new int[]{nr, nc, newRemain, steps + 1});
            }
        }
        return -1;
    }
}

