class Solution {
    public static boolean divideArray(int[] nums, int k) {
        if (nums.length % k != 0) return false;
        Arrays.sort(nums);
        Map<Integer, Integer> freq = new HashMap<>();
        for (int v : nums) {
            freq.put(v, freq.getOrDefault(v, 0) + 1);
        }
        for (int v : nums) {
            int cnt = freq.getOrDefault(v, 0);
            if (cnt > 0) {
                for (int i = 0; i < k; i++) {
                    int cur = v + i;
                    int curCnt = freq.getOrDefault(cur, 0);
                    if (curCnt < cnt) return false;
                    freq.put(cur, curCnt - cnt);
                }
            }
        }
        return true;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static int maxFreq(String s, int maxLetters, int minSize, int maxSize) {
        int n = s.length();
        Map<String, Integer> freq = new HashMap<>();
        int[] cnt = new int[26];
        int unique = 0;
        for (int i = 0; i < minSize; i++) {
            int idx = s.charAt(i) - 'a';
            if (cnt[idx] == 0) unique++;
            cnt[idx]++;
        }
        if (unique <= maxLetters) {
            String sub = s.substring(0, minSize);
            freq.put(sub, freq.getOrDefault(sub, 0) + 1);
        }
        for (int i = minSize; i < n; i++) {
            int outIdx = s.charAt(i - minSize) - 'a';
            cnt[outIdx]--;
            if (cnt[outIdx] == 0) unique--;
            int inIdx = s.charAt(i) - 'a';
            if (cnt[inIdx] == 0) unique++;
            cnt[inIdx]++;
            if (unique <= maxLetters) {
                String sub = s.substring(i - minSize + 1, i + 1);
                freq.put(sub, freq.getOrDefault(sub, 0) + 1);
            }
        }
        int ans = 0;
        for (int v : freq.values()) {
            if (v > ans) ans = v;
        }
        return ans;
    }
}

import java.util.Arrays;

class Solution {
    public static int findBestValue(int[] arr, int target) {
        Arrays.sort(arr);
        int n = arr.length;
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + arr[i];
        }
        int max = arr[n - 1];
        int low = 0, high = max;
        while (low < high) {
            int mid = (low + high) >>> 1;
            long sum = mutatedSum(arr, prefix, mid);
            if (sum < target) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        int best = low;
        long bestDiff = Math.abs(mutatedSum(arr, prefix, best) - target);
        if (best > 0) {
            long diffPrev = Math.abs(mutatedSum(arr, prefix, best - 1) - target);
            if (diffPrev <= bestDiff) {
                best = best - 1;
            }
        }
        return best;
    }

    private static long mutatedSum(int[] arr, long[] prefix, int value) {
        int idx = upperBound(arr, value);
        return prefix[idx] + (long) (arr.length - idx) * value;
    }

    private static int upperBound(int[] arr, int value) {
        int l = 0, r = arr.length;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (arr[m] <= value) {
                l = m + 1;
            } else {
                r = m;
            }
        }
        return l;
    }
}

class Solution {
