public class Solution {
    private static final int MOD = 1_000_000_007;

    public static int[] pathsWithMaxScore(String[] board) {
        int n = board.length;
        int[][] score = new int[n][n];
        int[][] ways = new int[n][n];
        for (int[] row : score) Arrays.fill(row, -1);
        score[n - 1][n - 1] = 0;
        ways[n - 1][n - 1] = 1;

        for (int i = n - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                if (i == n - 1 && j == n - 1) continue;
                char c = board[i].charAt(j);
                if (c == 'X') continue;
                int cellVal = (c >= '0' && c <= '9') ? c - '0' : 0;
                int best = -1;
                int cnt = 0;
                // from down
                if (i + 1 < n && score[i + 1][j] != -1) {
                    int cand = score[i + 1][j] + cellVal;
                    if (cand > best) {
                        best = cand;
                        cnt = ways[i + 1][j];
                    } else if (cand == best) {
                        cnt = (cnt + ways[i + 1][j]) % MOD;
                    }
                }
                // from right
                if (j + 1 < n && score[i][j + 1] != -1) {
                    int cand = score[i][j + 1] + cellVal;
                    if (cand > best) {
                        best = cand;
                        cnt = ways[i][j + 1];
                    } else if (cand == best) {
                        cnt = (cnt + ways[i][j + 1]) % MOD;
                    }
                }
                // from down-right
                if (i + 1 < n && j + 1 < n && score[i + 1][j + 1] != -1) {
                    int cand = score[i + 1][j + 1] + cellVal;
                    if (cand > best) {
                        best = cand;
                        cnt = ways[i + 1][j + 1];
                    } else if (cand == best) {
                        cnt = (cnt + ways[i + 1][j + 1]) % MOD;
                    }
                }
                if (best != -1) {
                    score[i][j] = best;
                    ways[i][j] = cnt % MOD;
                }
            }
        }
        if (score[0][0] == -1) return new int[]{0, 0};
        return new int[]{score[0][0], ways[0][0]};
    }
}

