public class Solution {
    public static int deepestLeavesSum(TreeNode root) {
        Holder h = new Holder();
        h.maxDepth = -1;
        h.sumAtMax = 0;
        dfs(root, 0, h);
        return h.sumAtMax;
    }

    private static void dfs(TreeNode node, int depth, Holder h) {
        if (node == null) return;
        if (node.left == null && node.right == null) {
            if (depth > h.maxDepth) {
                h.maxDepth = depth;
                h.sumAtMax = node.val;
            } else if (depth == h.maxDepth) {
                h.sumAtMax += node.val;
            }
        }
        dfs(node.left, depth + 1, h);
        dfs(node.right, depth + 1, h);
    }

    private static class Holder {
        int maxDepth;
        int sumAtMax;
    }
}

