class Solution {
    public static int maxCandies(int[] status, int[] candies, int[][] keys, int[][] containedBoxes, int[] initialBoxes) {
        int n = status.length;
        boolean[] haveBox = new boolean[n];
        boolean[] opened = new boolean[n];
        Deque<Integer> queue = new ArrayDeque<>();
        for (int b : initialBoxes) {
            if (!haveBox[b]) {
                haveBox[b] = true;
                if (status[b] == 1) {
                    queue.add(b);
                }
            }
        }
        int total = 0;
        while (!queue.isEmpty()) {
            int i = queue.poll();
            if (opened[i]) continue;
            opened[i] = true;
            total += candies[i];
            for (int k : keys[i]) {
                if (status[k] == 0) {
                    status[k] = 1;
                    if (haveBox[k] && !opened[k]) {
                        queue.add(k);
                    }
                }
            }
            for (int b : containedBoxes[i]) {
                if (!haveBox[b]) {
                    haveBox[b] = true;
                    if (status[b] == 1 && !opened[b]) {
                        queue.add(b);
                    }
                }
            }
        }
        return total;
    }
}

