class Solution {
    public static List<Integer> getAllElements(TreeNode root1, TreeNode root2) {
        List<Integer> list1 = new ArrayList<>();
        List<Integer> list2 = new ArrayList<>();
        inorder(root1, list1);
        inorder(root2, list2);
        List<Integer> merged = new ArrayList<>();
        int i = 0, j = 0;
        while (i < list1.size() && j < list2.size()) {
            if (list1.get(i) <= list2.get(j)) {
                merged.add(list1.get(i++));
            } else {
                merged.add(list2.get(j++));
            }
        }
        while (i < list1.size()) {
            merged.add(list1.get(i++));
        }
        while (j < list2.size()) {
            merged.add(list2.get(j++));
        }
        return merged;
    }

    private static void inorder(TreeNode node, List<Integer> arr) {
        if (node == null) return;
        inorder(node.left, arr);
        arr.add(node.val);
        inorder(node.right, arr);
    }
}

public class Solution {
    public static String decryptString(String s) {
        int n = s.length();
        StringBuilder sb = new StringBuilder();
        int i = n - 1;
        while (i >= 0) {
            if (s.charAt(i) == '#') {
                int num = (s.charAt(i - 2) - '0') * 10 + (s.charAt(i - 1) - '0');
                sb.append((char) (96 + num));
                i -= 3;
            } else {
                int num = s.charAt(i) - '0';
                sb.append((char) (96 + num));
                i -= 1;
            }
        }
        return sb.reverse().toString();
    }
}

class Solution {
    public static boolean canReach(int[] arr, int start) {
        int n = arr.length;
        boolean[] visited = new boolean[n];
        int[] queue = new int[n];
        int head = 0, tail = 0;
        queue[tail++] = start;
        visited[start] = true;
        while (head < tail) {
            int i = queue[head++];
            if (arr[i] == 0) return true;
            int jump = arr[i];
            int forward = i + jump;
            int backward = i - jump;
            if (forward < n && !visited[forward]) {
                visited[forward] = true;
                queue[tail++] = forward;
            }
            if (backward >= 0 && !visited[backward]) {
                visited[backward] = true;
                queue[tail++] = backward;
            }
        }
        return false;
    }
}

class Solution {
    public static int[] findZeroSumArray(int n) {
        java.util.List<Integer> result = new java.util.ArrayList<>();
        if (n % 2 == 0) {
            for (int i = 1; i <= n/2; i++) { result.add(i); result.add(-i); }
        } else {
            if (n == 1) result.add(0);
            else if (n == 3) { result.add(-1); result.add(0); result.add(1); }
            else {
                result.add(-1); result.add(1);
                int sumPos = 0;
                for (int i = 3; i <= n-1; i++) { result.add(i); sumPos += i; }
                result.add(-sumPos);
            }
        }
        java.util.Collections.sort(result);
        int[] arr = new int[result.size()];
        for (int i = 0; i < arr.length; i++) arr[i] = result.get(i);
        return arr;
    }
}

import java.util.*;

class Solution {
    public static boolean isSolvable(String[] words, String result) {
        int[] assign = new int[26];
        Arrays.fill(assign, -1);
        boolean[] used = new boolean[10];
        boolean[] leading = new boolean[26];

        for (String w : words) {
            if (w.length() > 1) leading[w.charAt(0) - 'A'] = true;
        }
        if (result.length() > 1) leading[result.charAt(0) - 'A'] = true;

        Set<Character> distinct = new HashSet<>();
        for (String w : words) {
            for (char c : w.toCharArray()) distinct.add(c);
        }
        for (char c : result.toCharArray()) distinct.add(c);
        if (distinct.size() > 10) return false;

        int maxLen = result.length();
        for (String w : words) maxLen = Math.max(maxLen, w.length());

        int[][] addendsIdx = new int[words.length][maxLen];
        for (int i = 0; i < words.length; i++) {
            String w = words[i];
            for (int col = 0; col < maxLen; col++) {
                int idx = w.length() - 1 - col;
                addendsIdx[i][col] = idx >= 0 ? w.charAt(idx) - 'A' : -1;
            }
        }
        int[] resultIdx = new int[maxLen];
        for (int col = 0; col < maxLen; col++) {
            int idx = result.length() - 1 - col;
            resultIdx[col] = idx >= 0 ? result.charAt(idx) - 'A' : -1;
        }

        return dfs(0, 0, words.length, maxLen, assign, used, leading, addendsIdx, resultIdx);
    }

    private static boolean dfs(int col, int carry, int rows, int maxLen,
                               int[] assign, boolean[] used, boolean[] leading,
                               int[][] addendsIdx, int[] resultIdx) {
        if (col == maxLen) return carry == 0;
        return solveColumn(col, 0, carry, 0, rows, assign, used, leading, addendsIdx, resultIdx);
    }

    private static boolean solveColumn(int col, int row, int carry, int sum, int rows,
                                        int[] assign, boolean[] used, boolean[] leading,
                                        int[][] addendsIdx, int[] resultIdx) {
        if (row == rows) {
            int total = sum + carry;
            int expected = total % 10;
            int newCarry = total / 10;
            int rIdx = resultIdx[col];
            if (rIdx == -1) {
                if (expected != 0) return false;
                return dfs(col + 1, newCarry, rows, resultIdx.length, assign, used, leading, addendsIdx, resultIdx);
            }
            if (assign[rIdx] != -1) {
                if (assign[rIdx] != expected) return false;
                return dfs(col + 1, newCarry, rows, resultIdx.length, assign, used, leading, addendsIdx, resultIdx);
            }
            if (used[expected]) return false;
            if (expected == 0 && leading[rIdx]) return false;
            assign[rIdx] = expected;
            used[expected] = true;
            boolean ok = dfs(col + 1, newCarry, rows, resultIdx.length, assign, used, leading, addendsIdx, resultIdx);
            assign[rIdx] = -1;
            used[expected] = false;
            return ok;
        }

        int idx = addendsIdx[row][col];
        if (idx == -1) {
            return solveColumn(col, row + 1, carry, sum, rows, assign, used, leading, addendsIdx, resultIdx);
        }
        if (assign[idx] != -1) {
            return solveColumn(col, row + 1, carry, sum + assign[idx], rows, assign, used, leading, addendsIdx, resultIdx);
        }
        for (int d = 0; d < 10; d++) {
            if (used[d]) continue;
            if (d == 0 && leading[idx]) continue;
            assign[idx] = d;
            used[d] = true;
            if (solveColumn(col, row + 1, carry, sum + d, rows, assign, used, leading, addendsIdx, resultIdx)) {
                return true;
            }
            assign[idx] = -1;
            used[d] = false;
        }
        return false;
    }
}

