import java.util.HashSet;
import java.util.Set;

class Solution {
    public static int distinctEchoSubstrings(String text) {
        int n = text.length();
        long base = 91138233L;
        long mod1 = 1000000007L;
        long mod2 = 1000000009L;

        long[] pref1 = new long[n + 1];
        long[] pref2 = new long[n + 1];
        long[] pow1 = new long[n + 1];
        long[] pow2 = new long[n + 1];
        pow1[0] = 1;
        pow2[0] = 1;

        for (int i = 0; i < n; i++) {
            int code = text.charAt(i);
            pref1[i + 1] = (pref1[i] * base + code) % mod1;
            pref2[i + 1] = (pref2[i] * base + code) % mod2;
            pow1[i + 1] = (pow1[i] * base) % mod1;
            pow2[i + 1] = (pow2[i] * base) % mod2;
        }

        Set<Long> seen = new HashSet<>();

        for (int len = 2; len <= n; len += 2) {
            int half = len >> 1;
            for (int i = 0; i + len <= n; i++) {
                long[] left = getHash(i, i + half, pref1, pref2, pow1, pow2, mod1, mod2);
                long[] right = getHash(i + half, i + len, pref1, pref2, pow1, pow2, mod1, mod2);
                if (left[0] == right[0] && left[1] == right[1]) {
                    long[] whole = getHash(i, i + len, pref1, pref2, pow1, pow2, mod1, mod2);
                    long combined = (whole[0] << 32) ^ whole[1];
                    seen.add(combined);
                }
            }
        }

        return seen.size();
    }

    private static long[] getHash(int l, int r, long[] pref1, long[] pref2, long[] pow1, long[] pow2, long mod1, long mod2) {
        long h1 = (pref1[r] - (pref1[l] * pow1[r - l]) % mod1 + mod1) % mod1;
        long h2 = (pref2[r] - (pref2[l] * pow2[r - l]) % mod2 + mod2) % mod2;
        return new long[]{h1, h2};
    }
}

import java.util.*;

class Solution {
    public static int[][] matrixBlockSum(int[][] mat, int k) {
        int m = mat.length;
        int n = mat[0].length;
        int[][] pref = new int[m + 1][n + 1];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                pref[i + 1][j + 1] = mat[i][j] + pref[i][j + 1] + pref[i + 1][j] - pref[i][j];
            }
        }
        int[][] answer = new int[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int top = Math.max(0, i - k);
                int bottom = Math.min(m - 1, i + k);
                int left = Math.max(0, j - k);
                int right = Math.min(n - 1, j + k);
                answer[i][j] = pref[bottom + 1][right + 1] - pref[top][right + 1] - pref[bottom + 1][left] + pref[top][left];
            }
        }
        return answer;
    }
}

public class Solution {
    public static int minFlips(int a, int b, int c) {
        int flips = 0;
        for (int i = 0; i < 32; i++) {
            int mask = 1 << i;
            int bitA = (a & mask) >>> i;
            int bitB = (b & mask) >>> i;
            int bitC = (c & mask) >>> i;
            if (bitC == 1) {
                if (bitA == 0 && bitB == 0) flips += 1;
            } else {
                flips += bitA + bitB;
            }
        }
        return flips;
    }
}

public class Solution {
    public static int[] sumNoZeroIntegers(int n) {
        for (int a = 1; a < n; ++a) {
            int b = n - a;
            if (!hasZero(a) && !hasZero(b)) {
                return new int[]{a, b};
            }
        }
        return new int[0];
    }
    private static boolean hasZero(int x) {
        while (x > 0) {
            if (x % 10 == 0) return true;
            x /= 10;
        }
        return false;
    }
}

import java.util.Arrays;

class Solution {
    public static int minimumDistance(String word) {
        int n = word.length();
        if (n <= 1) return 0;
        int[] w = new int[n];
        for (int i = 0; i < n; i++) w[i] = word.charAt(i) - 'A';
        final int INF = Integer.MAX_VALUE / 2;
        int[] dp = new int[27];
        Arrays.fill(dp, INF);
        dp[26] = 0;
        int prev = w[0];
        for (int i = 1; i < n; i++) {
            int next = w[i];
            int[] ndp = new int[27];
            Arrays.fill(ndp, INF);
            for (int j = 0; j <= 26; j++) {
                int curCost = dp[j];
                if (curCost == INF) continue;
                int costSame = curCost + dist(prev, next);
                if (costSame < ndp[j]) ndp[j] = costSame;
                int add = (j == 26) ? 0 : dist(j, next);
                int costOther = curCost + add;
                if (costOther < ndp[prev]) ndp[prev] = costOther;
            }
            dp = ndp;
            prev = next;
        }
        int ans = INF;
        for (int v : dp) if (v < ans) ans = v;
        return ans;
    }

    private static int dist(int a, int b) {
        int ra = a / 6, ca = a % 6;
        int rb = b / 6, cb = b % 6;
        return Math.abs(ra - rb) + Math.abs(ca - cb);
    }
}

