import java.util.Set;

class Solution {
    public static int makeConnected(int n, int[][] connections) {
        if (connections.length < n - 1) return -1;
        int[] parent = new int[n];
        int[] rank = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
        int extraEdges = 0;
        for (int[] edge : connections) {
            if (!union(edge[0], edge[1], parent, rank)) extraEdges++;
        }
        Set<Integer> components = new HashSet<>();
        for (int i = 0; i < n; i++) components.add(find(i, parent));
        int needed = components.size() - 1;
        return extraEdges >= needed ? needed : -1;
    }

    private static int find(int x, int[] parent) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    private static boolean union(int a, int b, int[] parent, int[] rank) {
        int rootA = find(a, parent);
        int rootB = find(b, parent);
        if (rootA == rootB) return false;
        if (rank[rootA] < rank[rootB]) {
            parent[rootA] = rootB;
        } else if (rank[rootA] > rank[rootB]) {
            parent[rootB] = rootA;
        } else {
            parent[rootB] = rootA;
            rank[rootA]++;
        }
        return true;
    }
}

import java.lang.*;

class Solution {
    public static int maximum69Number(int num) {
        int n = num;
        int place = 1;
        int mostSignificantSix = -1;
        while (n > 0) {
            int digit = n % 10;
            if (digit == 6) {
                mostSignificantSix = place;
            }
            n = n / 10;
            place *= 10;
        }
        if (mostSignificantSix == -1) return num;
        return num + 3 * mostSignificantSix;
    }
}

