public class Solution {
    public static List<String> printVertically(String s) {
        String[] words = s.split(" ");
        int maxLen = 0;
        for (String w : words) {
            if (w.length() > maxLen) {
                maxLen = w.length();
            }
        }
        List<String> result = new ArrayList<>();
        for (int i = 0; i < maxLen; i++) {
            StringBuilder col = new StringBuilder();
            for (String w : words) {
                col.append(i < w.length() ? w.charAt(i) : ' ');
            }
            int end = col.length();
            while (end > 0 && col.charAt(end - 1) == ' ') {
                end--;
            }
            result.add(col.substring(0, end));
        }
        return result;
    }
}

class Solution {
    public static int maxValueAfterReverse(int[] nums) {
        int n = nums.length;
        long base = 0;
        for (int i = 0; i < n - 1; i++) {
            base += Math.abs(nums[i] - nums[i + 1]);
        }
        long best = base;
        for (int i = 1; i < n; i++) {
            long gain = -Math.abs(nums[i] - nums[i - 1]) + Math.abs(nums[i] - nums[0]);
            best = Math.max(best, base + gain);
        }
        for (int i = 0; i < n - 1; i++) {
            long gain = -Math.abs(nums[i + 1] - nums[i]) + Math.abs(nums[i + 1] - nums[n - 1]);
            best = Math.max(best, base + gain);
        }
        int mn = Integer.MAX_VALUE;
        int mx = Integer.MIN_VALUE;
        for (int i = 0; i < n - 1; i++) {
            int a = nums[i];
            int b = nums[i + 1];
            mn = Math.min(mn, Math.max(a, b));
            mx = Math.max(mx, Math.min(a, b));
        }
        long gain = 2L * Math.max(0, mx - mn);
        best = Math.max(best, base + gain);
        return (int) best;
    }
}

