class Solution {
    public static TreeNode deleteLeaves(TreeNode root, int target) {
        return prune(root, target);
    }
    private static TreeNode prune(TreeNode node, int target) {
        if (node == null) return null;
        node.left = prune(node.left, target);
        node.right = prune(node.right, target);
        if (node.left == null && node.right == null && node.val == target) {
            return null;
        }
        return node;
    }
}

import java.util.*;

class Solution {
    public static int minTaps(int n, int[] ranges) {
        int[] maxReach = new int[n + 1];
        for (int i = 0; i <= n; i++) {
            int left = Math.max(0, i - ranges[i]);
            int right = Math.min(n, i + ranges[i]);
            if (right > maxReach[left]) {
                maxReach[left] = right;
            }
        }
        int taps = 0;
        int curEnd = 0;
        int farthest = 0;
        for (int i = 0; i <= n; i++) {
            farthest = Math.max(farthest, maxReach[i]);
            if (i == curEnd) {
                taps++;
                curEnd = farthest;
                if (curEnd <= i) {
                    return -1;
                }
            }
            if (curEnd >= n) {
                break;
            }
        }
        return curEnd >= n ? taps : -1;
    }
}

