class Solution {
    public static int[] filterRestaurants(int[][] restaurants, int veganFriendly, int maxPrice, int maxDistance) {
        List<int[]> filtered = new ArrayList<>();
        for (int i = 0; i < restaurants.length; i++) {
            int id = restaurants[i][0];
            int rating = restaurants[i][1];
            int vegan = restaurants[i][2];
            int price = restaurants[i][3];
            int distance = restaurants[i][4];
            if ((veganFriendly == 0 || vegan == 1) && price <= maxPrice && distance <= maxDistance) {
                filtered.add(new int[]{id, rating});
            }
        }
        Collections.sort(filtered, (a, b) -> {
            if (b[1] != a[1]) return b[1] - a[1];
            return b[0] - a[0];
        });
        int[] result = new int[filtered.size()];
        for (int i = 0; i < filtered.size(); i++) {
            result[i] = filtered.get(i)[0];
        }
        return result;
    }
}

import java.util.*;

class Solution {
    public static int findTheCity(int n, int[][] edges, int distanceThreshold) {
        final int INF = Integer.MAX_VALUE / 2;
        int[][] dist = new int[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(dist[i], INF);
            dist[i][i] = 0;
        }
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            int w = edge[2];
            dist[u][v] = w;
            dist[v][u] = w;
        }
        for (int k = 0; k < n; k++) {
            for (int i = 0; i < n; i++) {
                int dik = dist[i][k];
                if (dik == INF) continue;
                for (int j = 0; j < n; j++) {
                    long newDist = (long) dik + dist[k][j];
                    if (newDist < dist[i][j]) {
                        dist[i][j] = (int) newDist;
                    }
                }
            }
        }
        int bestCity = -1;
        int bestCount = INF;
        for (int i = 0; i < n; i++) {
            int cnt = 0;
            for (int j = 0; j < n; j++) {
                if (i != j && dist[i][j] <= distanceThreshold) {
                    cnt++;
                }
            }
            if (cnt < bestCount || (cnt == bestCount && i > bestCity)) {
                bestCount = cnt;
                bestCity = i;
            }
        }
        return bestCity;
    }
}

import java.util.Arrays;
import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public static int minDifficulty(int[] jobDifficulty, int d) {
        int n = jobDifficulty.length;
        if (d > n) return -1;
        long INF = Long.MAX_VALUE / 4;
        long[] dpPrev = new long[n];
        long max = 0;
        for (int i = 0; i < n; i++) {
            max = Math.max(max, jobDifficulty[i]);
            dpPrev[i] = max;
        }
        for (int day = 2; day <= d; day++) {
            long[] dpCurr = new long[n];
            Arrays.fill(dpCurr, INF);
            Deque<Integer> stack = new ArrayDeque<>();
            for (int i = day - 1; i < n; i++) {
                long best = dpPrev[i - 1] + jobDifficulty[i];
                while (!stack.isEmpty() && jobDifficulty[stack.peek()] <= jobDifficulty[i]) {
                    int idx = stack.pop();
                    best = Math.min(best, dpPrev[idx] + jobDifficulty[i]);
                }
                if (!stack.isEmpty()) {
                    best = Math.min(best, dpCurr[stack.peek()] + jobDifficulty[i]);
                }
                dpCurr[i] = best;
                stack.push(i);
            }
            dpPrev = dpCurr;
        }
        long ans = dpPrev[n - 1];
        return ans >= INF ? -1 : (int) ans;
    }
}

