class Solution {
    public static int[] rankTransform(int[] arr) {
        Set<Integer> set = new HashSet<>();
        for (int v : arr) {
            set.add(v);
        }
        List<Integer> sortedUnique = new ArrayList<>(set);
        Collections.sort(sortedUnique);
        Map<Integer, Integer> rankMap = new HashMap<>();
        for (int i = 0; i < sortedUnique.size(); i++) {
            rankMap.put(sortedUnique.get(i), i + 1);
        }
        int[] result = new int[arr.length];
        for (int i = 0; i < arr.length; i++) {
            result[i] = rankMap.get(arr[i]);
        }
        return result;
    }
}

import java.util.*;

class Solution {
    public static int[] kWeakestRows(int[][] mat, int k) {
        List<int[]> heap = new ArrayList<>();
        for (int i = 0; i < mat.length; i++) {
            int soldiers = countOnes(mat[i]);
            heapPush(heap, new int[]{soldiers, i});
            if (heap.size() > k) {
                heapPop(heap);
            }
        }
        heap.sort((a, b) -> {
            int diff = a[0] - b[0];
            return diff != 0 ? diff : a[1] - b[1];
        });
        int[] result = new int[heap.size()];
        for (int i = 0; i < heap.size(); i++) {
            result[i] = heap.get(i)[1];
        }
        return result;
    }

    private static int countOnes(int[] row) {
        int lo = 0, hi = row.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (row[mid] == 1) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    private static boolean greater(int[] a, int[] b) {
        if (a[0] != b[0]) return a[0] > b[0];
        return a[1] > b[1];
    }

    private static void heapPush(List<int[]> heap, int[] node) {
        heap.add(node);
        int i = heap.size() - 1;
        while (i > 0) {
            int p = (i - 1) >>> 1;
            if (greater(heap.get(p), heap.get(i))) break;
            int[] temp = heap.get(p);
            heap.set(p, heap.get(i));
            heap.set(i, temp);
            i = p;
        }
    }

    private static int[] heapPop(List<int[]> heap) {
        int[] top = heap.get(0);
        int[] last = heap.remove(heap.size() - 1);
        if (!heap.isEmpty()) {
            heap.set(0, last);
            int i = 0;
            while (true) {
                int l = i * 2 + 1;
                int r = i * 2 + 2;
                int largest = i;
                if (l < heap.size() && !greater(heap.get(largest), heap.get(l))) largest = l;
                if (r < heap.size() && !greater(heap.get(largest), heap.get(r))) largest = r;
                if (largest == i) break;
                int[] temp = heap.get(i);
                heap.set(i, heap.get(largest));
                heap.set(largest, temp);
                i = largest;
            }
        }
        return top;
    }
}

import java.math.BigInteger;

class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

public class Solution {
    public int maxProduct(TreeNode root) {
        final BigInteger MOD = BigInteger.valueOf(1_000_000_007L);
        BigInteger total = sum(root);
        BigInteger[] best = new BigInteger[]{BigInteger.ZERO};
        dfs(root, total, best);
        return best[0].mod(MOD).intValue();
    }

    private BigInteger sum(TreeNode node) {
        if (node == null) return BigInteger.ZERO;
        BigInteger left = sum(node.left);
        BigInteger right = sum(node.right);
        return BigInteger.valueOf(node.val).add(left).add(right);
    }

    private BigInteger dfs(TreeNode node, BigInteger total, BigInteger[] best) {
        if (node == null) return BigInteger.ZERO;
        BigInteger left = dfs(node.left, total, best);
        BigInteger right = dfs(node.right, total, best);
        BigInteger cur = BigInteger.valueOf(node.val).add(left).add(right);
        BigInteger product = cur.multiply(total.subtract(cur));
        if (product.compareTo(best[0]) > 0) best[0] = product;
        return cur;
    }
}

