class Solution {
    public static int minSetSize(int[] arr) {
        Map<Integer, Integer> freqMap = new HashMap<>();
        for (int v : arr) {
            freqMap.put(v, freqMap.getOrDefault(v, 0) + 1);
        }
        List<Integer> frequencies = new ArrayList<>(freqMap.values());
        frequencies.sort(Collections.reverseOrder());
        int target = (arr.length + 1) / 2;
        int removed = 0, setSize = 0;
        for (int f : frequencies) {
            removed += f;
            setSize++;
            if (removed >= target) break;
        }
        return setSize;
    }
}

import java.util.*;

class Solution {
    public static int maxJumps(int[] arr, int d) {
        int n = arr.length;
        int[] memo = new int[n];
        int answer = 0;
        for (int i = 0; i < n; i++) {
            answer = Math.max(answer, dfs(i, arr, d, memo));
        }
        return answer;
    }

    private static int dfs(int i, int[] arr, int d, int[] memo) {
        if (memo[i] != 0) return memo[i];
        int best = 1;
        for (int step = 1; step <= d && i - step >= 0; step++) {
            if (arr[i] > arr[i - step]) {
                best = Math.max(best, 1 + dfs(i - step, arr, d, memo));
            } else {
                break;
            }
        }
        for (int step = 1; step <= d && i + step < arr.length; step++) {
            if (arr[i] > arr[i + step]) {
                best = Math.max(best, 1 + dfs(i + step, arr, d, memo));
            } else {
                break;
            }
        }
        memo[i] = best;
        return best;
    }
}

import java.lang.*;

class Solution {
    public static int numOfSubarrays(int[] arr, int k, int threshold) {
        long requiredSum = (long) k * threshold;
        long windowSum = 0;
        int answer = 0;
        for (int i = 0; i < arr.length; i++) {
            windowSum += arr[i];
            if (i >= k) {
                windowSum -= arr[i - k];
            }
            if (i >= k - 1 && windowSum >= requiredSum) {
                answer++;
            }
        }
        return answer;
    }
}

