class Solution {
    public static int minJumps(int[] arr) {
        int n = arr.length;
        if (n <= 1) return 0;
        Map<Integer, List<Integer>> posMap = new HashMap<>();
        for (int i = 0; i < n; i++) {
            posMap.computeIfAbsent(arr[i], k -> new ArrayList<>()).add(i);
        }
        boolean[] visited = new boolean[n];
        Deque<Integer> queue = new ArrayDeque<>();
        visited[0] = true;
        queue.add(0);
        int steps = 0;
        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            for (int k = 0; k < levelSize; k++) {
                int i = queue.poll();
                if (i == n - 1) return steps;
                List<Integer> neighbours = new ArrayList<>();
                if (i - 1 >= 0) neighbours.add(i - 1);
                if (i + 1 < n) neighbours.add(i + 1);
                if (posMap.containsKey(arr[i])) {
                    neighbours.addAll(posMap.get(arr[i]));
                    posMap.remove(arr[i]);
                }
                for (int nb : neighbours) {
                    if (!visited[nb]) {
                        visited[nb] = true;
                        queue.add(nb);
                    }
                }
            }
            steps++;
        }
        return -1;
    }
}

public class Solution {
    public static int numberOfSteps(int num) {
        int steps = 0;
        while (num > 0) {
            if ((num & 1) != 0) {
                num--;
            } else {
                num >>= 1;
            }
            steps++;
        }
        return steps;
    }
}

class Solution {
    public static int minSteps(String s, String t) {
        int[] freq = new int[26];
        for (int i = 0; i < s.length(); i++) {
            freq[s.charAt(i) - 'a']++;
        }
        int steps = 0;
        for (int i = 0; i < t.length(); i++) {
            int idx = t.charAt(i) - 'a';
            freq[idx]--;
            if (freq[idx] < 0) {
                steps++;
            }
        }
        return steps;
    }
}

import java.util.*;
class TweetCounts {
    private Map<String, List<Integer>> tweets = new HashMap<>();
    private Set<String> sorted = new HashSet<>();
    public void recordTweet(String tweetName, int time) {
        tweets.computeIfAbsent(tweetName, k -> new ArrayList<>()).add(time);
        sorted.remove(tweetName);
    }
    public List<Integer> getTweetCountsPerFrequency(String freq, String tweetName, int startTime, int endTime) {
        int interval = "minute".equals(freq) ? 60 : "hour".equals(freq) ? 3600 : 86400;
        if (!sorted.contains(tweetName) && tweets.containsKey(tweetName)) {
            Collections.sort(tweets.get(tweetName));
            sorted.add(tweetName);
        }
        int bucketCount = (endTime - startTime) / interval + 1;
        List<Integer> result = new ArrayList<>(Collections.nCopies(bucketCount, 0));
        List<Integer> times = tweets.getOrDefault(tweetName, Collections.emptyList());
        for (int t : times) {
            if (t < startTime || t > endTime) continue;
            int idx = (t - startTime) / interval;
            result.set(idx, result.get(idx) + 1);
        }
        return result;
    }
}

import java.util.*;

class Solution {
    public static int maxStudents(char[][] seats) {
        int m = seats.length;
        int n = seats[0].length;
        int[] rowMask = new int[m];
        for (int i = 0; i < m; i++) {
            int mask = 0;
            for (int j = 0; j < n; j++) {
                if (seats[i][j] == '.') {
                    mask |= (1 << j);
                }
            }
            rowMask[i] = mask;
        }
        int limit = 1 << n;
        int[] bitCount = new int[limit];
        for (int i = 0; i < limit; i++) {
            bitCount[i] = Integer.bitCount(i);
        }
        boolean[][] compatible = new boolean[limit][limit];
        for (int cur = 0; cur < limit; cur++) {
            for (int prev = 0; prev < limit; prev++) {
                if ((cur & (prev << 1)) == 0 && (cur & (prev >> 1)) == 0) {
                    compatible[cur][prev] = true;
                }
            }
        }
        int[][] validMasks = new int[m][];
        for (int i = 0; i < m; i++) {
            int[] temp = new int[limit];
            int cnt = 0;
            for (int mask = 0; mask < limit; mask++) {
                if ((mask & ~rowMask[i]) != 0) continue;
                if ((mask & (mask << 1)) != 0) continue;
                temp[cnt++] = mask;
            }
            validMasks[i] = Arrays.copyOf(temp, cnt);
        }
        int[] dpPrev = new int[limit];
        int[] dpCurr = new int[limit];
        Arrays.fill(dpPrev, -1);
        for (int mask : validMasks[0]) {
            dpPrev[mask] = bitCount[mask];
        }
        for (int i = 1; i < m; i++) {
            Arrays.fill(dpCurr, -1);
            for (int curMask : validMasks[i]) {
                int curCnt = bitCount[curMask];
                for (int prevMask : validMasks[i - 1]) {
                    if (dpPrev[prevMask] < 0) continue;
                    if (!compatible[curMask][prevMask]) continue;
                    int val = dpPrev[prevMask] + curCnt;
                    if (val > dpCurr[curMask]) dpCurr[curMask] = val;
                }
            }
            int[] tmp = dpPrev;
            dpPrev = dpCurr;
            dpCurr = tmp;
        }
        int ans = 0;
        for (int v : dpPrev) {
            if (v > ans) ans = v;
        }
        return ans;
    }
}

import java.util.*;
class ProductOfNumbers {
    private final ArrayList<Long> pref = new ArrayList<>();
    public ProductOfNumbers() { pref.add(1L); }
    public void add(int num) {
        if (num == 0) { pref.clear(); pref.add(1L); }
        else pref.add(pref.get(pref.size()-1) * num);
    }
    public long getProduct(int k) {
        int n = pref.size() - 1;
        if (k > n) return 0;
        return pref.get(n) / pref.get(n-k);
    }
}

