class Solution {
    public static boolean isPossible(int[] target) {
        if (target.length == 1) return target[0] == 1;
        PriorityQueue<Long> heap = new PriorityQueue<>(Collections.reverseOrder());
        long total = 0;
        for (int v : target) {
            heap.add((long) v);
            total += v;
        }
        while (true) {
            long max = heap.poll();
            long rest = total - max;
            if (max == 1 || rest == 1) return true;
            if (rest == 0) return false;
            long prev = max % rest;
            if (prev == 0) prev = rest;
            if (prev == 0 || prev == max) return false;
            heap.add(prev);
            total = rest + prev;
        }
    }
}

import java.lang.*;

class Solution {
    public static int countNegatives(int[][] grid) {
        int m = grid.length;
        if (m == 0) return 0;
        int n = grid[0].length;
        int row = 0, col = n - 1, negatives = 0;
        while (row < m && col >= 0) {
            if (grid[row][col] < 0) {
                negatives += m - row;
                col--;
            } else {
                row++;
            }
        }
        return negatives;
    }
}

import java.util.*;

class Solution {
    private static void push(List<Integer> heap, int x) {
        heap.add(x);
        int i = heap.size() - 1;
        while (i > 0) {
            int p = (i - 1) >> 1;
            if (heap.get(p) <= heap.get(i)) break;
            int tmp = heap.get(p);
            heap.set(p, heap.get(i));
            heap.set(i, tmp);
            i = p;
        }
    }

    private static int pop(List<Integer> heap) {
        if (heap.isEmpty()) return -1;
        int min = heap.get(0);
        int last = heap.remove(heap.size() - 1);
        if (!heap.isEmpty()) {
            heap.set(0, last);
            int i = 0;
            while (true) {
                int l = i * 2 + 1;
                int r = i * 2 + 2;
                int s = i;
                if (l < heap.size() && heap.get(l) < heap.get(s)) s = l;
                if (r < heap.size() && heap.get(r) < heap.get(s)) s = r;
                if (s == i) break;
                int tmp = heap.get(i);
                heap.set(i, heap.get(s));
                heap.set(s, tmp);
                i = s;
            }
        }
        return min;
    }

    public static int maxEvents(int[][] events) {
        Arrays.sort(events, (a, b) -> Integer.compare(a[0], b[0]));
        List<Integer> heap = new ArrayList<>();
        int day = 0, i = 0, attended = 0;
        while (i < events.length || !heap.isEmpty()) {
            if (heap.isEmpty()) {
                day = events[i][0];
            }
            while (i < events.length && events[i][0] <= day) {
                push(heap, events[i][1]);
                i++;
            }
            while (!heap.isEmpty() && heap.get(0) < day) {
                pop(heap);
            }
            if (!heap.isEmpty()) {
                pop(heap);
                attended++;
                day++;
            }
        }
        return attended;
    }
}

import java.util.*;

class Solution {
    public static int[] sortByBits(int[] arr) {
        Map<Integer, Integer> cache = new HashMap<>();
        Integer[] boxed = new Integer[arr.length];
        for (int i = 0; i < arr.length; i++) {
            boxed[i] = arr[i];
        }
        Arrays.sort(boxed, (a, b) -> {
            int pa = popCount(a, cache);
            int pb = popCount(b, cache);
            if (pa != pb) return pa - pb;
            return a - b;
        });
        for (int i = 0; i < arr.length; i++) {
            arr[i] = boxed[i];
        }
        return arr;
    }

    private static int popCount(int x, Map<Integer, Integer> cache) {
        if (cache.containsKey(x)) return cache.get(x);
        int cnt = 0;
        int y = x;
        while (y != 0) {
            y &= y - 1;
            cnt++;
        }
        cache.put(y, cnt);
        return cnt;
    }
}

import java.util.*;
class Cashier {
    private final int n, discount;
    private final Map<Integer,Integer> priceMap;
    private int served = 0;
    public Cashier(int n, int discount, int[] products, int[] prices) {
        this.n = n; this.discount = discount;
        priceMap = new HashMap<>();
        for (int i = 0; i < products.length; i++) priceMap.put(products[i], prices[i]);
    }
    public double getBill(int[] product, int[] amount) {
        double subtotal = 0;
        for (int i = 0; i < product.length; i++) subtotal += amount[i]*priceMap.get(product[i]);
        served++;
        if (served % n == 0) subtotal = subtotal*(100-discount)/100.0;
        return subtotal;
    }
}

import java.math.BigInteger;

class Solution {
    public static int countOrders(int n) {
        final BigInteger MOD = BigInteger.valueOf(1000000007L);
        BigInteger fact = BigInteger.ONE;
        for (long i = 2; i <= 2L * n; i++) {
            fact = fact.multiply(BigInteger.valueOf(i)).mod(MOD);
        }
        BigInteger pow2 = modPow(BigInteger.valueOf(2), BigInteger.valueOf(n), MOD);
        BigInteger invPow2 = modPow(pow2, MOD.subtract(BigInteger.TWO), MOD);
        return fact.multiply(invPow2).mod(MOD).intValue();
    }

    private static BigInteger modPow(BigInteger base, BigInteger exp, BigInteger mod) {
        BigInteger result = BigInteger.ONE;
        BigInteger b = base.mod(mod);
        BigInteger e = exp;
        while (e.compareTo(BigInteger.ZERO) > 0) {
            if (e.testBit(0)) {
                result = result.multiply(b).mod(mod);
            }
            b = b.multiply(b).mod(mod);
            e = e.shiftRight(1);
        }
        return result;
    }
}

class Solution {
    public static long numberOfSubstrings(String s) {
        int n = s.length();
        int[] cnt = new int[3];
        int left = 0, right = 0;
        long ans = 0;
        while (left < n) {
            while (right < n && (cnt[0] == 0 || cnt[1] == 0 || cnt[2] == 0)) {
                cnt[s.charAt(right) - 'a']++;
                right++;
            }
            if (cnt[0] > 0 && cnt[1] > 0 && cnt[2] > 0) {
                ans += n - right + 1;
            } else {
                break;
            }
            cnt[s.charAt(left) - 'a']--;
            left++;
        }
        return ans;
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public static boolean validateBinaryTreeNodes(int n, int[] leftChild, int[] rightChild) {
        int[] indegree = new int[n];
        for (int i = 0; i < n; i++) {
            int l = leftChild[i];
            int r = rightChild[i];
            if (l != -1) indegree[l]++;
            if (r != -1) indegree[r]++;
        }
        int root = -1;
        for (int i = 0; i < n; i++) {
            if (indegree[i] == 0) {
                if (root != -1) return false;
                root = i;
            } else if (indegree[i] > 1) {
                return false;
            }
        }
        if (root == -1) return false;
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(root);
        boolean[] visited = new boolean[n];
        visited[root] = true;
        int visitedCount = 0;
        while (!stack.isEmpty()) {
            int node = stack.pop();
            visitedCount++;
            int l = leftChild[node];
            int r = rightChild[node];
            if (l != -1) {
                if (visited[l]) return false;
                visited[l] = true;
                stack.push(l);
            }
            if (r != -1) {
                if (visited[r]) return false;
                visited[r] = true;
                stack.push(r);
            }
        }
        return visitedCount == n;
    }
}

import java.time.*;

public class Solution {
    public static double daysBetween(String date1, String date2) {
        long t1 = LocalDate.of(
                Integer.parseInt(date1.substring(0, 4)),
                Integer.parseInt(date1.substring(5, 7)),
                Integer.parseInt(date1.substring(8, 10))
        ).atStartOfDay(ZoneOffset.UTC).toInstant().toEpochMilli();
        long t2 = LocalDate.of(
                Integer.parseInt(date2.substring(0, 4)),
                Integer.parseInt(date2.substring(5, 7)),
                Integer.parseInt(date2.substring(8, 10))
        ).atStartOfDay(ZoneOffset.UTC).toInstant().toEpochMilli();
        return Math.abs(t2 - t1) / (1000d * 60 * 60 * 24);
    }
}

public class Solution {
    public static int[] closestDivisors(int num) {
        int[] bestPair = null;
        int bestDiff = Integer.MAX_VALUE;
        for (int add = 1; add <= 2; add++) {
            int target = num + add;
            int i = (int) Math.floor(Math.sqrt(target));
            while (i >= 1 && target % i != 0) {
                i--;
            }
            int a = i;
            int b = target / i;
            int diff = Math.abs(a - b);
            if (diff < bestDiff) {
                bestDiff = diff;
                bestPair = new int[]{a, b};
            }
        }
        return bestPair;
    }
}

