class Solution {
    public static String largestMultipleOfThree(int[] digits) {
        int[] cnt = new int[10];
        int sum = 0;
        for (int d : digits) {
            cnt[d]++;
            sum += d;
        }
        int rem = sum % 3;
        if (rem == 1) {
            if (!tryRemove(cnt, 1, 1)) {
                if (!tryRemove(cnt, 2, 2)) {
                    return "";
                }
            }
        } else if (rem == 2) {
            if (!tryRemove(cnt, 2, 1)) {
                if (!tryRemove(cnt, 1, 2)) {
                    return "";
                }
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int d = 9; d >= 0; d--) {
            for (int i = 0; i < cnt[d]; i++) {
                sb.append(d);
            }
        }
        String result = sb.toString();
        if (result.length() == 0) {
            return "";
        }
        int firstNonZero = -1;
        for (int i = 0; i < result.length(); i++) {
            if (result.charAt(i) != '0') {
                firstNonZero = i;
                break;
            }
        }
        if (firstNonZero == -1) {
            return "0";
        }
        return result.substring(firstNonZero);
    }

    private static boolean tryRemove(int[] cnt, int target, int need) {
        for (int d = 0; d <= 9 && need > 0; d++) {
            if (d % 3 == target) {
                int take = Math.min(cnt[d], need);
                cnt[d] -= take;
                need -= take;
            }
        }
        return need == 0;
    }
}

