class Solution {
    public boolean isSubPath(ListNode head, TreeNode root) {
        if (root == null) return false;
        if (match(root, head)) return true;
        return isSubPath(head, root.left) || isSubPath(head, root.right);
    }

    private boolean match(TreeNode node, ListNode list) {
        if (list == null) return true;
        if (node == null) return false;
        if (node.val != list.val) return false;
        return match(node.left, list.next) || match(node.right, list.next);
    }
}

import java.util.*;

class Solution {
    public static int minCost(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int INF = 1 << 30;
        int[][] dist = new int[m][n];
        for (int i = 0; i < m; i++) {
            Arrays.fill(dist[i], INF);
        }
        int[][] dirs = {
            {0, 1, 1},
            {0, -1, 2},
            {1, 0, 3},
            {-1, 0, 4}
        };
        Deque<int[]> dq = new ArrayDeque<>();
        dist[0][0] = 0;
        dq.offerFirst(new int[]{0, 0});
        while (!dq.isEmpty()) {
            int[] cur = dq.pollFirst();
            int x = cur[0];
            int y = cur[1];
            int curCost = dist[x][y];
            for (int[] d : dirs) {
                int nx = x + d[0];
                int ny = y + d[1];
                if (nx < 0 || nx >= m || ny < 0 || ny >= n) continue;
                int w = (grid[x][y] == d[2]) ? 0 : 1;
                int newCost = curCost + w;
                if (newCost < dist[nx][ny]) {
                    dist[nx][ny] = newCost;
                    if (w == 0) {
                        dq.offerFirst(new int[]{nx, ny});
                    } else {
                        dq.offerLast(new int[]{nx, ny});
                    }
                }
            }
        }
        return dist[m - 1][n - 1];
    }
}

import java.util.*;

class Solution {
    public static String rankTeams(String[] votes) {
        if (votes == null || votes.length == 0) return "";
        int m = votes[0].length();
        int[][] cnt = new int[26][m];
        boolean[] present = new boolean[26];
        for (String vote : votes) {
            for (int i = 0; i < m; i++) {
                char c = vote.charAt(i);
                cnt[c - 'A'][i]++;
                present[c - 'A'] = true;
            }
        }
        List<Character> teams = new ArrayList<>();
        for (int i = 0; i < 26; i++) {
            if (present[i]) teams.add((char) ('A' + i));
        }
        teams.sort((a, b) -> {
            int idxA = a - 'A';
            int idxB = b - 'A';
            for (int i = 0; i < m; i++) {
                if (cnt[idxA][i] != cnt[idxB][i]) {
                    return cnt[idxB][i] - cnt[idxA][i];
                }
            }
            return a.compareTo(b);
        });
        StringBuilder sb = new StringBuilder();
        for (char c : teams) sb.append(c);
        return sb.toString();
    }
}

