class Solution {
    public static String sortString(String s) {
        int[] cnt = new int[26];
        for (int i = 0; i < s.length(); i++) {
            cnt[s.charAt(i) - 'a']++;
        }
        StringBuilder res = new StringBuilder();
        int n = s.length();
        while (res.length() < n) {
            for (int i = 0; i < 26; i++) {
                if (cnt[i] > 0) {
                    res.append((char) ('a' + i));
                    cnt[i]--;
                }
            }
            for (int i = 25; i >= 0; i--) {
                if (cnt[i] > 0) {
                    res.append((char) ('a' + i));
                    cnt[i]--;
                }
            }
        }
        return res.toString();
    }
}

