class Solution {
    private static int maxLen;

    public static int longestZigZag(TreeNode root) {
        maxLen = 0;
        dfs(root);
        return maxLen;
    }

    private static int[] dfs(TreeNode node) {
        if (node == null) {
            return new int[]{-1, -1};
        }
        int[] leftChild = dfs(node.left);
        int[] rightChild = dfs(node.right);
        int leftZig = 1 + leftChild[1];
        int rightZig = 1 + rightChild[0];
        if (leftZig > maxLen) maxLen = leftZig;
        if (rightZig > maxLen) maxLen = rightZig;
        return new int[]{leftZig, rightZig};
    }
}

import java.util.Arrays;

class Solution {
    public static int longestEvenVowelSubstring(String s) {
        int[] firstIdx = new int[32];
        Arrays.fill(firstIdx, Integer.MAX_VALUE);
        firstIdx[0] = -1;
        int mask = 0;
        int best = 0;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == 'a') mask ^= 1 << 0;
            else if (ch == 'e') mask ^= 1 << 1;
            else if (ch == 'i') mask ^= 1 << 2;
            else if (ch == 'o') mask ^= 1 << 3;
            else if (ch == 'u') mask ^= 1 << 4;
            if (firstIdx[mask] != Integer.MAX_VALUE) {
                int length = i - firstIdx[mask];
                if (length > best) best = length;
            } else {
                firstIdx[mask] = i;
            }
        }
        return best;
    }
}

