class Solution {
    private static long maxSum = 0;

    public static int maxSumBST(TreeNode root) {
        maxSum = 0;
        dfs(root);
        return (int) maxSum;
    }

    private static class Result {
        boolean isBST;
        long sum;
        long min;
        long max;
        Result(boolean isBST, long sum, long min, long max) {
            this.isBST = isBST;
            this.sum = sum;
            this.min = min;
            this.max = max;
        }
    }

    private static Result dfs(TreeNode node) {
        if (node == null) {
            return new Result(true, 0, Long.MAX_VALUE, Long.MIN_VALUE);
        }
        Result left = dfs(node.left);
        Result right = dfs(node.right);
        boolean isBST = left.isBST && right.isBST && node.val > left.max && node.val < right.min;
        long sum = isBST ? left.sum + right.sum + node.val : 0;
        if (isBST) {
            maxSum = Math.max(maxSum, sum);
        }
        long min = Math.min(node.val, left.min);
        long max = Math.max(node.val, right.max);
        return new Result(isBST, sum, min, max);
    }
}

