class Solution {
    public static int numOfMinutes(int n, int headID, int[] manager, int[] informTime) {
        List<Integer>[] subordinates = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            subordinates[i] = new ArrayList<>();
        }
        for (int i = 0; i < n; i++) {
            int mgr = manager[i];
            if (mgr != -1) {
                subordinates[mgr].add(i);
            }
        }
        return dfs(headID, subordinates, informTime);
    }

    private static int dfs(int emp, List<Integer>[] subordinates, int[] informTime) {
        int longest = 0;
        for (int sub : subordinates[emp]) {
            int subTime = dfs(sub, subordinates, informTime);
            if (subTime > longest) {
                longest = subTime;
            }
        }
        return longest + informTime[emp];
    }
}

import java.util.*;

class Solution {
    public double frogPosition(int n, int[][] edges, int t, int target) {
        List<Integer>[] adj = new ArrayList[n + 1];
        for (int i = 0; i <= n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            int u = e[0], v = e[1];
            adj[u].add(v);
            adj[v].add(u);
        }

        Deque<State> queue = new ArrayDeque<>();
        queue.addLast(new State(1, 1.0, 0));
        boolean[] visited = new boolean[n + 1];
        visited[1] = true;

        while (!queue.isEmpty()) {
            State cur = queue.pollFirst();
            int node = cur.node;
            double prob = cur.prob;
            int time = cur.time;

            List<Integer> unvisited = new ArrayList<>();
            for (int nb : adj[node]) {
                if (!visited[nb]) {
                    unvisited.add(nb);
                }
            }

            if (node == target) {
                if (time == t || (time < t && unvisited.isEmpty())) {
                    return prob;
                }
            }

            if (time == t) continue;

            int cnt = unvisited.size();
            if (cnt == 0) continue;

            double nextProb = prob / cnt;
            for (int nb : unvisited) {
                visited[nb] = true;
                queue.addLast(new State(nb, nextProb, time + 1));
            }
        }
        return 0.0;
    }

    private static class State {
        int node;
        double prob;
        int time;
        State(int node, double prob, int time) {
            this.node = node;
            this.prob = prob;
            this.time = time;
        }
    }
}

class CustomStack {
    private final int[] stack;
    private final int[] inc;
    private int size;
    private final int maxSize;
    public CustomStack(int maxSize) {
        this.maxSize = maxSize;
        this.stack = new int[maxSize];
        this.inc = new int[maxSize];
        this.size = 0;
    }
    public void push(int x) { if (size < maxSize) stack[size++] = x; }
    public int pop() {
        if (size == 0) return -1;
        int i = size - 1;
        int val = stack[i] + inc[i];
        if (i > 0) inc[i-1] += inc[i];
        inc[i] = 0;
        size--;
        return val;
    }
    public void increment(int k, int val) {
        int i = Math.min(k, size) - 1;
        if (i >= 0) inc[i] += val;
    }
}

