class Solution {
    public static TreeNode getTargetCopy(TreeNode original, TreeNode cloned, TreeNode target) {
        if (original == null) return null;
        if (original == target) return cloned;
        TreeNode leftResult = getTargetCopy(original.left, cloned.left, target);
        if (leftResult != null) return leftResult;
        return getTargetCopy(original.right, cloned.right, target);
    }
}

import java.util.*;

public class Solution {
    public static TreeNode balanceBST(TreeNode root) {
        List<Integer> sorted = new ArrayList<>();
        inorder(root, sorted);
        return build(sorted, 0, sorted.size() - 1);
    }
    private static void inorder(TreeNode node, List<Integer> sorted) {
        if (node == null) return;
        inorder(node.left, sorted);
        sorted.add(node.val);
        inorder(node.right, sorted);
    }
    private static TreeNode build(List<Integer> sorted, int l, int r) {
        if (l > r) return null;
        int m = (l + r) >> 1;
        TreeNode node = new TreeNode(sorted.get(m));
        node.left = build(sorted, l, m - 1);
        node.right = build(sorted, m + 1, r);
        return node;
    }
}
