class Solution {
    private static class Pair {
        int value;
        int col;
        Pair(int value, int col) {
            this.value = value;
            this.col = col;
        }
    }

    public static List<Integer> luckyNumbers(int[][] matrix) {
        int rowCount = matrix.length;
        int colCount = matrix[0].length;
        Pair[] rowMins = new Pair[rowCount];
        int[] colMaxes = new int[colCount];
        Arrays.fill(colMaxes, Integer.MIN_VALUE);

        for (int i = 0; i < rowCount; i++) {
            int minVal = Integer.MAX_VALUE;
            int minCol = -1;
            for (int j = 0; j < colCount; j++) {
                int cur = matrix[i][j];
                if (cur < minVal) {
                    minVal = cur;
                    minCol = j;
                }
                if (cur > colMaxes[j]) {
                    colMaxes[j] = cur;
                }
            }
            rowMins[i] = new Pair(minVal, minCol);
        }

        List<Integer> lucky = new ArrayList<>();
        for (int i = 0; i < rowCount; i++) {
            Pair info = rowMins[i];
            if (info.value == colMaxes[info.col]) {
                lucky.add(info.value);
            }
        }
        return lucky;
    }
}

import java.util.Arrays;
import java.util.PriorityQueue;

class Solution {
    public static int maxPerformance(int n, int[] speed, int[] efficiency, int k) {
        final long MOD = 1_000_000_007L;
        int[][] engineers = new int[n][2];
        for (int i = 0; i < n; i++) {
            engineers[i][0] = efficiency[i];
            engineers[i][1] = speed[i];
        }
        Arrays.sort(engineers, (a, b) -> Integer.compare(b[0], a[0]));
        PriorityQueue<Integer> heap = new PriorityQueue<>();
        long sumSpeeds = 0;
        long best = 0;
        for (int[] e : engineers) {
            int eff = e[0];
            int spd = e[1];
            heap.add(spd);
            sumSpeeds += spd;
            if (heap.size() > k) {
                sumSpeeds -= heap.poll();
            }
            long perf = (sumSpeeds * eff) % MOD;
            if (perf > best) {
                best = perf;
            }
        }
        return (int) best;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static int maxNumberOfFamilies(int n, int[][] reservedSeats) {
        Map<Integer, Integer> rowMask = new HashMap<>();
        for (int[] seat : reservedSeats) {
            int r = seat[0];
            int s = seat[1] - 1;
            rowMask.put(r, rowMask.getOrDefault(r, 0) | (1 << s));
        }
        int families = (n - rowMask.size()) * 2;
        int leftMask = (1 << 1) | (1 << 2) | (1 << 3) | (1 << 4);
        int rightMask = (1 << 5) | (1 << 6) | (1 << 7) | (1 << 8);
        int middleMask = (1 << 3) | (1 << 4) | (1 << 5) | (1 << 6);
        for (int mask : rowMask.values()) {
            boolean leftFree = (mask & leftMask) == 0;
            boolean rightFree = (mask & rightMask) == 0;
            if (leftFree && rightFree) {
                families += 2;
            } else if (leftFree || rightFree) {
                families += 1;
            } else if ((mask & middleMask) == 0) {
                families += 1;
            }
        }
        return families;
    }
}

