class Solution {
    public static int getKth(int lo, int hi, int k) {
        Map<Long, Integer> memo = new HashMap<>();
        memo.put(1L, 0);
        List<int[]> pairs = new ArrayList<>();
        for (int n = lo; n <= hi; n++) {
            pairs.add(new int[]{n, power(n, memo)});
        }
        pairs.sort((a, b) -> a[1] == b[1] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));
        return pairs.get(k - 1)[0];
    }

    private static int power(long x, Map<Long, Integer> memo) {
        if (memo.containsKey(x)) {
            return memo.get(x);
        }
        long next = (x % 2 == 0) ? x / 2 : 3 * x + 1;
        int val = 1 + power(next, memo);
        memo.put(x, val);
        return val;
    }
}

