class Solution {
    public static int distanceValue(int[] arr1, int[] arr2, int d) {
        Arrays.sort(arr2);
        int count = 0;
        for (int x : arr1) {
            int lo = 0, hi = arr2.length;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (arr2[mid] < x) {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }
            boolean ok = true;
            if (lo < arr2.length && Math.abs(arr2[lo] - x) <= d) ok = false;
            if (lo > 0 && Math.abs(arr2[lo - 1] - x) <= d) ok = false;
            if (ok) count++;
        }
        return count;
    }
}

