class Solution {
    public static boolean hasValidPath(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        int[][][] dirs = new int[7][][];
        dirs[1] = new int[][]{{0, -1}, {0, 1}};
        dirs[2] = new int[][]{{-1, 0}, {1, 0}};
        dirs[3] = new int[][]{{0, -1}, {1, 0}};
        dirs[4] = new int[][]{{0, 1}, {1, 0}};
        dirs[5] = new int[][]{{0, -1}, {-1, 0}};
        dirs[6] = new int[][]{{0, 1}, {-1, 0}};

        Map<String, int[]> opposite = new HashMap<>();
        opposite.put("-1,0", new int[]{1, 0});
        opposite.put("1,0", new int[]{-1, 0});
        opposite.put("0,-1", new int[]{0, 1});
        opposite.put("0,1", new int[]{0, -1});

        boolean[][] visited = new boolean[rows][cols];
        Deque<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{0, 0});
        visited[0][0] = true;

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0];
            int c = cur[1];
            if (r == rows - 1 && c == cols - 1) {
                return true;
            }
            for (int[] d : dirs[grid[r][c]]) {
                int dr = d[0];
                int dc = d[1];
                int nr = r + dr;
                int nc = c + dc;
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                    continue;
                }
                if (visited[nr][nc]) {
                    continue;
                }
                int[] needed = opposite.get(dr + "," + dc);
                int[][] neighDirs = dirs[grid[nr][nc]];
                boolean compatible = false;
                for (int[] nd : neighDirs) {
                    if (nd[0] == needed[0] && nd[1] == needed[1]) {
                        compatible = true;
                        break;
                    }
                }
                if (compatible) {
                    visited[nr][nc] = true;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return false;
    }
}

