class Solution {
    public static int maxSizeSlices(int[] slices) {
        int n = slices.length / 3;
        int ans1 = maxSum(slices, 0, slices.length - 1, n);
        int ans2 = maxSum(slices, 1, slices.length, n);
        return Math.max(ans1, ans2);
    }

    private static int maxSum(int[] slices, int start, int end, int picks) {
        int len = end - start;
        int INF = Integer.MIN_VALUE / 2;
        int[] prevPrev = new int[picks + 1];
        int[] prev = new int[picks + 1];
        Arrays.fill(prevPrev, INF);
        Arrays.fill(prev, INF);
        prevPrev[0] = 0;
        prev[0] = 0;
        if (picks >= 1) {
            prevPrev[1] = slices[start];
            if (len > 1) {
                prev[1] = Math.max(slices[start], slices[start + 1]);
            }
        }
        for (int i = 2; i < len; i++) {
            int[] cur = new int[picks + 1];
            Arrays.fill(cur, INF);
            cur[0] = 0;
            for (int j = 1; j <= picks; j++) {
                int notTake = prev[j];
                int take = slices[start + i] + prevPrev[j - 1];
                cur[j] = Math.max(notTake, take);
            }
            prevPrev = prev;
            prev = cur;
        }
        return prev[picks];
    }
}

