class Solution {
    public static long sumFourDivisors(int[] nums) {
        int maxNum = 0;
        for (int v : nums) {
            if (v > maxNum) maxNum = v;
        }
        int limit = (int) Math.floor(Math.sqrt(maxNum));
        boolean[] isComposite = new boolean[limit + 1];
        List<Integer> primes = new ArrayList<>();
        for (int i = 2; i <= limit; i++) {
            if (!isComposite[i]) {
                primes.add(i);
                if ((long) i * i <= limit) {
                    for (int j = i * i; j <= limit; j += i) {
                        isComposite[j] = true;
                    }
                }
            }
        }

        long total = 0;
        for (int num : nums) {
            if (num < 2) continue;
            int n = num;
            int distinct = 0;
            int firstPrime = 0, secondPrime = 0;
            int firstExp = 0, secondExp = 0;

            for (int p : primes) {
                if ((long) p * p > n) break;
                if (n % p == 0) {
                    distinct++;
                    int exp = 0;
                    while (n % p == 0) {
                        n /= p;
                        exp++;
                    }
                    if (distinct == 1) {
                        firstPrime = p;
                        firstExp = exp;
                    } else {
                        secondPrime = p;
                        secondExp = exp;
                    }
                    if (distinct > 2) break;
                }
            }
            if (n > 1) {
                distinct++;
                if (distinct == 1) {
                    firstPrime = n;
                    firstExp = 1;
                } else {
                    secondPrime = n;
                    secondExp = 1;
                }
            }

            if (distinct == 1 && firstExp == 3) {
                long p = firstPrime;
                total += 1 + p + p * p + p * p * p;
            } else if (distinct == 2 && firstExp == 1 && secondExp == 1) {
                long p = firstPrime;
                long q = secondPrime;
                total += 1 + p + q + p * q;
            }
        }
        return total;
    }
}

