class Solution {
    public static String longestHappyPrefix(String s) {
        int n = s.length();
        if (n == 0) return "";
        int[] pi = new int[n];
        int j = 0;
        for (int i = 1; i < n; i++) {
            while (j > 0 && s.charAt(i) != s.charAt(j)) {
                j = pi[j - 1];
            }
            if (s.charAt(i) == s.charAt(j)) j++;
            pi[i] = j;
        }
        int len = pi[n - 1];
        return s.substring(0, len);
    }
}

