import java.util.*;

class Solution {
    public static int countTeams(int[] rating) {
        int n = rating.length;
        if (n < 3) return 0;
        int[] sorted = rating.clone();
        Arrays.sort(sorted);
        int m = 1;
        for (int i = 1; i < sorted.length; i++) {
            if (sorted[i] != sorted[i - 1]) sorted[m++] = sorted[i];
        }
        int[] comp = new int[n];
        for (int i = 0; i < n; i++) {
            int idx = Arrays.binarySearch(sorted, 0, m, rating[i]);
            comp[i] = idx + 1; // 1‑based for Fenwick
        }
        Fenwick ft = new Fenwick(m);
        int[] leftLess = new int[n];
        int[] leftGreater = new int[n];
        for (int i = 0; i < n; i++) {
            int idx = comp[i];
            leftLess[i] = ft.query(idx - 1);
            leftGreater[i] = i - leftLess[i];
            ft.update(idx, 1);
        }
        ft = new Fenwick(m);
        int[] rightLess = new int[n];
        int[] rightGreater = new int[n];
        for (int i = n - 1; i >= 0; i--) {
            int idx = comp[i];
            rightGreater[i] = ft.query(m) - ft.query(idx);
            rightLess[i] = (n - 1 - i) - rightGreater[i];
            ft.update(idx, 1);
        }
        long total = 0;
        for (int i = 0; i < n; i++) {
            total += (long) leftLess[i] * rightGreater[i] + (long) leftGreater[i] * rightLess[i];
        }
        return (int) total;
    }

    private static class Fenwick {
        private final int[] tree;
        Fenwick(int size) {
            tree = new int[size + 2];
        }
        void update(int index, int delta) {
            for (int i = index; i < tree.length; i += i & -i) {
                tree[i] += delta;
            }
        }
        int query(int index) {
            int sum = 0;
            for (int i = index; i > 0; i -= i & -i) {
                sum += tree[i];
            }
            return sum;
        }
    }
}

import java.util.*;

class Solution {
    private static final int MOD = 1_000_000_007;

    public static int findGoodStrings(String s1, String s2, String evil) {
        int n = s1.length();
        int m = evil.length();

        int[] pi = new int[m];
        for (int i = 1; i < m; i++) {
            int j = pi[i - 1];
            while (j > 0 && evil.charAt(i) != evil.charAt(j)) {
                j = pi[j - 1];
            }
            if (evil.charAt(i) == evil.charAt(j)) {
                j++;
            }
            pi[i] = j;
        }

        int[][] next = new int[m + 1][26];
        for (int k = 0; k <= m; k++) {
            for (int c = 0; c < 26; c++) {
                if (k < m && c == evil.charAt(k) - 'a') {
                    next[k][c] = k + 1;
                } else if (k == 0) {
                    next[k][c] = 0;
                } else {
                    next[k][c] = next[pi[k - 1]][c];
                }
            }
        }

        int[][][] cur = new int[2][2][m];
        int[][][] nxt = new int[2][2][m];
        cur[1][1][0] = 1;

        for (int pos = 0; pos < n; pos++) {
            for (int low = 0; low <= 1; low++) {
                for (int high = 0; high <= 1; high++) {
                    for (int k = 0; k < m; k++) {
                        int curVal = cur[low][high][k];
                        if (curVal == 0) continue;
                        char lowerChar = low == 1 ? s1.charAt(pos) : 'a';
                        char upperChar = high == 1 ? s2.charAt(pos) : 'z';
                        for (char ch = lowerChar; ch <= upperChar; ch++) {
                            int idx = ch - 'a';
                            int nk = next[k][idx];
                            if (nk == m) continue;
                            int nLow = (low == 1 && ch == lowerChar) ? 1 : 0;
                            int nHigh = (high == 1 && ch == upperChar) ? 1 : 0;
                            int sum = nxt[nLow][nHigh][nk] + curVal;
                            if (sum >= MOD) sum -= MOD;
                            nxt[nLow][nHigh][nk] = sum;
                        }
                    }
                }
            }
            for (int low = 0; low <= 1; low++) {
                for (int high = 0; high <= 1; high++) {
                    Arrays.fill(cur[low][high], 0);
                }
            }
            int[][][] temp = cur;
            cur = nxt;
            nxt = temp;
        }

        long ans = 0;
        for (int low = 0; low <= 1; low++) {
            for (int high = 0; high <= 1; high++) {
                for (int k = 0; k < m; k++) {
                    ans += cur[low][high][k];
                }
            }
        }
        return (int) (ans % MOD);
    }
}

