class Solution {
    public static String stoneGameIII(int[] stoneValue) {
        int n = stoneValue.length;
        int[] diff = new int[n + 3];
        for (int i = n - 1; i >= 0; i--) {
            int best = Integer.MIN_VALUE;
            int sum = 0;
            for (int k = 1; k <= 3 && i + k <= n; k++) {
                sum += stoneValue[i + k - 1];
                int candidate = sum - diff[i + k];
                if (candidate > best) {
                    best = candidate;
                }
            }
            diff[i] = best;
        }
        if (diff[0] > 0) return "Alice";
        if (diff[0] < 0) return "Bob";
        return "Tie";
    }
}

