class Solution {
    private static void add(int[] bit, int i, int delta) {
        int size = bit.length;
        for (; i < size; i += i & -i) {
            bit[i] += delta;
        }
    }
    private static int sum(int[] bit, int i) {
        int res = 0;
        for (; i > 0; i -= i & -i) {
            res += bit[i];
        }
        return res;
    }
    public static int[] processQueries(int[] queries, int m) {
        int n = queries.length;
        int size = n + m + 2;
        int[] bit = new int[size];
        int[] pos = new int[m + 1];
        for (int v = 1; v <= m; v++) {
            int idx = n + v;
            pos[v] = idx;
            add(bit, idx, 1);
        }
        int[] result = new int[n];
        int front = n;
        for (int i = 0; i < n; i++) {
            int x = queries[i];
            int idx = pos[x];
            result[i] = sum(bit, idx) - 1;
            add(bit, idx, -1);
            add(bit, front, 1);
            pos[x] = front;
            front--;
        }
        return result;
    }
}

