class Solution {
    public static String longestDiverseString(int a, int b, int c) {
        class Pair {
            char ch;
            int cnt;
            Pair(char ch, int cnt) {
                this.ch = ch;
                this.cnt = cnt;
            }
        }
        StringBuilder result = new StringBuilder();
        Pair[] pool = {new Pair('a', a), new Pair('b', b), new Pair('c', c)};
        while (true) {
            Arrays.sort(pool, (x, y) -> y.cnt - x.cnt);
            if (pool[0].cnt == 0) break;
            if (result.length() >= 2 &&
                result.charAt(result.length() - 1) == pool[0].ch &&
                result.charAt(result.length() - 2) == pool[0].ch) {
                if (pool[1].cnt == 0) break;
                result.append(pool[1].ch);
                pool[1].cnt--;
                continue;
            }
            int maxAdd = result.length() > 0 && result.charAt(result.length() - 1) == pool[0].ch ? 1 : 2;
            int use = Math.min(pool[0].cnt, maxAdd);
            for (int i = 0; i < use; i++) {
                result.append(pool[0].ch);
            }
            pool[0].cnt -= use;
        }
        return result.toString();
    }
}

