import java.util.Map;

class Solution {
    public static String htmlEntityParser(String text) {
        Map<String, String> entityMap = new HashMap<>();
        entityMap.put("&quot;", "\"");
        entityMap.put("&apos;", "'");
        entityMap.put("&amp;", "&");
        entityMap.put("&gt;", ">");
        entityMap.put("&lt;", "<");
        entityMap.put("&frasl;", "/");
        int maxLen = 7;
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < text.length(); i++) {
            if (text.charAt(i) == '&') {
                boolean replaced = false;
                for (int l = 2; l <= maxLen && i + l < text.length(); l++) {
                    String candidate = text.substring(i, i + l + 1);
                    if (entityMap.containsKey(candidate)) {
                        result.append(entityMap.get(candidate));
                        i += l;
                        replaced = true;
                        break;
                    }
                }
                if (!replaced) {
                    result.append('&');
                }
            } else {
                result.append(text.charAt(i));
            }
        }
        return result.toString();
    }
}

import java.util.ArrayList;
import java.util.List;

class Solution {
    public static int minFibonacciNumbers(long k) {
        List<Long> fib = new ArrayList<>();
        fib.add(1L);
        fib.add(2L);
        while (fib.get(fib.size() - 1) + fib.get(fib.size() - 2) <= k) {
            fib.add(fib.get(fib.size() - 1) + fib.get(fib.size() - 2));
        }
        int count = 0;
        while (k > 0) {
            int lo = 0, hi = fib.size() - 1;
            while (lo < hi) {
                int mid = (lo + hi + 1) / 2;
                if (fib.get(mid) <= k) {
                    lo = mid;
                } else {
                    hi = mid - 1;
                }
            }
            k -= fib.get(lo);
            count++;
        }
        return count;
    }
}

import java.lang.*;

class Solution {
    public static int restoreArray(String s, int k) {
        final int MOD = 1000000007;
        int n = s.length();
        int maxLen = Integer.toString(k).length();
        int[] dp = new int[n + 1];
        dp[0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = i - 1; j >= 0 && i - j <= maxLen; j--) {
                if (s.charAt(j) == '0') continue;
                long num = Long.parseLong(s.substring(j, i));
                if (num > k) continue;
                dp[i] = (dp[i] + dp[j]) % MOD;
            }
        }
        return dp[n];
    }
}

