class Solution {
    public static int numberOfWays(int n) {
        final long MOD = 1000000007L;
        long a = 6, b = 6;
        for (int i = 2; i <= n; i++) {
            long newA = (a * 3 + b * 2) % MOD;
            long newB = (a * 2 + b * 2) % MOD;
            a = newA;
            b = newB;
        }
        return (int) ((a + b) % MOD);
    }
}

