class Solution {
    public static String getHappyString(int n, int k) {
        long total = 3L * (1L << (n - 1));
        if (k > total) return "";
        char[] letters = {'a', 'b', 'c'};
        StringBuilder result = new StringBuilder();
        char prev = 0;
        long kk = k;
        for (int i = 0; i < n; i++) {
            int remaining = n - i - 1;
            long blockSize = 1L << remaining;
            for (char ch : letters) {
                if (ch == prev) continue;
                if (kk > blockSize) {
                    kk -= blockSize;
                } else {
                    result.append(ch);
                    prev = ch;
                    break;
                }
            }
        }
        return result.toString();
    }
}

class Solution {
    public static int minStartValue(int[] nums) {
        int prefix = 0;
        int minPrefix = 0;
        for (int i = 0; i < nums.length; i++) {
            prefix += nums[i];
            if (prefix < minPrefix) {
                minPrefix = prefix;
            }
        }
        return minPrefix < 1 ? 1 - minPrefix : 1;
    }
}

import java.util.ArrayList;

class Solution {
    public static String reformatString(String s) {
        ArrayList<Character> letters = new ArrayList<>();
        ArrayList<Character> digits = new ArrayList<>();
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch >= '0' && ch <= '9') {
                digits.add(ch);
            } else {
                letters.add(ch);
            }
        }
        if (Math.abs(letters.size() - digits.size()) > 1) {
            return "";
        }
        StringBuilder res = new StringBuilder();
        int li = 0, di = 0;
        boolean startWithLetter = letters.size() > digits.size();
        while (li < letters.size() || di < digits.size()) {
            if (startWithLetter) {
                if (li < letters.size()) {
                    res.append(letters.get(li++));
                }
                if (di < digits.size()) {
                    res.append(digits.get(di++));
                }
            } else {
                if (di < digits.size()) {
                    res.append(digits.get(di++));
                }
                if (li < letters.size()) {
                    res.append(letters.get(li++));
                }
            }
        }
        return res.toString();
    }
}

