class Solution {
    public static List<List<String>> displayTable(List<List<String>> orders) {
        Set<String> foodSet = new HashSet<>();
        Map<String, Map<String, Integer>> tableMap = new HashMap<>();
        for (List<String> order : orders) {
            String tableStr = order.get(1);
            String food = order.get(2);
            foodSet.add(food);
            tableMap.computeIfAbsent(tableStr, k -> new HashMap<>());
            Map<String, Integer> foodCountMap = tableMap.get(tableStr);
            foodCountMap.put(food, foodCountMap.getOrDefault(food, 0) + 1);
        }
        List<String> foods = new ArrayList<>(foodSet);
        Collections.sort(foods);
        List<String> tables = new ArrayList<>(tableMap.keySet());
        tables.sort(Comparator.comparingInt(Integer::parseInt));
        List<List<String>> result = new ArrayList<>();
        List<String> header = new ArrayList<>();
        header.add("Table");
        header.addAll(foods);
        result.add(header);
        for (String tbl : tables) {
            List<String> row = new ArrayList<>();
            row.add(tbl);
            Map<String, Integer> foodCountMap = tableMap.get(tbl);
            for (String f : foods) {
                row.add(String.valueOf(foodCountMap.getOrDefault(f, 0)));
            }
            result.add(row);
        }
        return result;
    }
}

class Solution {
    public static int minNumberOfFrogs(String croakOfFrogs) {
        int[] cnt = new int[4];
        int active = 0;
        int max = 0;
        for (int i = 0; i < croakOfFrogs.length(); i++) {
            char ch = croakOfFrogs.charAt(i);
            switch (ch) {
                case 'c':
                    cnt[0]++;
                    active++;
                    if (active > max) max = active;
                    break;
                case 'r':
                    if (cnt[0] == 0) return -1;
                    cnt[0]--;
                    cnt[1]++;
                    break;
                case 'o':
                    if (cnt[1] == 0) return -1;
                    cnt[1]--;
                    cnt[2]++;
                    break;
                case 'a':
                    if (cnt[2] == 0) return -1;
                    cnt[2]--;
                    cnt[3]++;
                    break;
                case 'k':
                    if (cnt[3] == 0) return -1;
                    cnt[3]--;
                    active--;
                    break;
                default:
                    return -1;
            }
        }
        return active == 0 ? max : -1;
    }
}

