public class Solution {
    private static final long MOD = 1_000_000_007L;

    public static int countArrays(int n, int m, int k) {
        if (k == 0) return 0;
        long[][] prev = new long[m + 1][k + 1];
        for (int v = 1; v <= m; v++) prev[v][1] = 1;
        for (int i = 1; i < n; i++) {
            long[][] cur = new long[m + 1][k + 1];
            long[] prefix = new long[m + 1];
            for (int cnt = 1; cnt <= k; cnt++) {
                prefix[0] = 0;
                for (int curMax = 1; curMax <= m; curMax++) {
                    prefix[curMax] = (prefix[curMax - 1] + prev[curMax][cnt]) % MOD;
                }
                if (cnt + 1 <= k) {
                    for (int newMax = 1; newMax <= m; newMax++) {
                        long add = prefix[newMax - 1];
                        if (add != 0) {
                            cur[newMax][cnt + 1] = (cur[newMax][cnt + 1] + add) % MOD;
                        }
                    }
                }
                for (int curMax = 1; curMax <= m; curMax++) {
                    long ways = prev[curMax][cnt];
                    if (ways != 0) {
                        cur[curMax][cnt] = (cur[curMax][cnt] + ways * curMax) % MOD;
                    }
                }
            }
            prev = cur;
        }
        long ans = 0;
        for (int curMax = 1; curMax <= m; curMax++) ans = (ans + prev[curMax][k]) % MOD;
        return (int) ans;
    }
}

