class Solution {
    public static List<Integer> diagonalTraverse(List<List<Integer>> nums) {
        List<List<Integer>> buckets = new ArrayList<>();
        for (int i = 0; i < nums.size(); i++) {
            List<Integer> row = nums.get(i);
            for (int j = 0; j < row.size(); j++) {
                int d = i + j;
                while (buckets.size() <= d) {
                    buckets.add(null);
                }
                if (buckets.get(d) == null) {
                    buckets.set(d, new ArrayList<>());
                }
                buckets.get(d).add(row.get(j));
            }
        }
        List<Integer> result = new ArrayList<>();
        for (int d = 0; d < buckets.size(); d++) {
            List<Integer> bucket = buckets.get(d);
            if (bucket == null) continue;
            for (int k = bucket.size() - 1; k >= 0; k--) {
                result.add(bucket.get(k));
            }
        }
        return result;
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public static int constrainedSubsequenceSum(int[] nums, int k) {
        int n = nums.length;
        int[] dp = new int[n];
        Deque<Integer> deque = new ArrayDeque<>();
        int best = Integer.MIN_VALUE;
        for (int i = 0; i < n; i++) {
            while (!deque.isEmpty() && deque.peekFirst() < i - k) {
                deque.pollFirst();
            }
            int maxPrev = deque.isEmpty() ? 0 : dp[deque.peekFirst()];
            dp[i] = nums[i] + Math.max(0, maxPrev);
            while (!deque.isEmpty() && dp[deque.peekLast()] <= dp[i]) {
                deque.pollLast();
            }
            deque.offerLast(i);
            if (dp[i] > best) {
                best = dp[i];
            }
        }
        return best;
    }
}

