class Solution {
    public static int maxScore(int[] cardPoints, int k) {
        int n = cardPoints.length;
        int windowSize = n - k;
        if (windowSize == 0) {
            int sum = 0;
            for (int v : cardPoints) sum += v;
            return sum;
        }
        long total = 0;
        for (int v : cardPoints) total += v;
        long current = 0;
        for (int i = 0; i < windowSize; i++) current += cardPoints[i];
        long minSum = current;
        for (int i = windowSize; i < n; i++) {
            current += cardPoints[i] - cardPoints[i - windowSize];
            if (current < minSum) minSum = current;
        }
        return (int) (total - minSum);
    }
}

