class Solution {
    public static boolean checkIfCanBreak(String s1, String s2) {
        char[] a = s1.toCharArray();
        char[] b = s2.toCharArray();
        Arrays.sort(a);
        Arrays.sort(b);
        boolean aBreaksB = true;
        boolean bBreaksA = true;
        for (int i = 0; i < a.length; i++) {
            if (a[i] < b[i]) aBreaksB = false;
            if (b[i] < a[i]) bBreaksA = false;
            if (!aBreaksB && !bBreaksA) break;
        }
        return aBreaksB || bBreaksA;
    }
}

public class Solution {
    public static long maxDiff(long num) {
        String s = Long.toString(num);
        String maxStr = s;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) != '9') {
                char target = s.charAt(i);
                maxStr = s.replace(target, '9');
                break;
            }
        }
        String minStr = s;
        if (s.charAt(0) != '1') {
            char target = s.charAt(0);
            minStr = s.replace(target, '1');
        } else {
            for (int i = 1; i < s.length(); i++) {
                char c = s.charAt(i);
                if (c != '0' && c != '1') {
                    char target = c;
                    minStr = s.replace(target, '0');
                    break;
                }
            }
        }
        return Long.parseLong(maxStr) - Long.parseLong(minStr);
    }
}

import java.util.*;

class Solution {
    public static int numberOfWays(List<List<Integer>> hats) {
        final int MOD = 1_000_000_007;
        int n = hats.size();
        int fullMask = (1 << n) - 1;

        List<Integer>[] hatToPeople = new List[41];
        for (int i = 0; i <= 40; i++) {
            hatToPeople[i] = new ArrayList<>();
        }
        for (int person = 0; person < n; person++) {
            for (int h : hats.get(person)) {
                hatToPeople[h].add(person);
            }
        }

        int[] dp = new int[1 << n];
        dp[0] = 1;

        for (int h = 1; h <= 40; h++) {
            int[] next = dp.clone();
            for (int mask = 0; mask <= fullMask; mask++) {
                int ways = dp[mask];
                if (ways == 0) continue;
                for (int p : hatToPeople[h]) {
                    if ((mask & (1 << p)) == 0) {
                        int newMask = mask | (1 << p);
                        next[newMask] = (int) ((next[newMask] + (long) ways) % MOD);
                    }
                }
            }
            dp = next;
        }
        return dp[fullMask];
    }
}

