class Solution {
    public static int kthSmallestSum(int[][] mat, int k) {
        int[] sums = Arrays.copyOf(mat[0], mat[0].length);
        for (int r = 1; r < mat.length; r++) {
            int[] row = mat[r];
            PriorityQueue<Node> pq = new PriorityQueue<>();
            int limit = Math.min(k, sums.length);
            for (int i = 0; i < limit; i++) {
                pq.offer(new Node(sums[i] + row[0], i, 0));
            }
            int[] newSums = new int[Math.min(k, limit * row.length)];
            int cnt = 0;
            while (cnt < k && !pq.isEmpty()) {
                Node cur = pq.poll();
                newSums[cnt++] = cur.sum;
                if (cur.j + 1 < row.length) {
                    pq.offer(new Node(sums[cur.i] + row[cur.j + 1], cur.i, cur.j + 1));
                }
            }
            sums = Arrays.copyOf(newSums, cnt);
        }
        return sums[k - 1];
    }

    private static class Node implements Comparable<Node> {
        int sum, i, j;
        Node(int sum, int i, int j) {
            this.sum = sum;
            this.i = i;
            this.j = j;
        }
        public int compareTo(Node o) {
            return Integer.compare(this.sum, o.sum);
        }
    }
}

