class Solution {
    public static int minTime(int n, int[][] edges, boolean[] hasApple) {
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            graph[u].add(v);
            graph[v].add(u);
        }
        return dfs(0, -1, graph, hasApple);
    }

    private static int dfs(int node, int parent, List<Integer>[] graph, boolean[] hasApple) {
        int total = 0;
        for (int nxt : graph[node]) {
            if (nxt == parent) continue;
            int childTime = dfs(nxt, node, graph, hasApple);
            if (childTime > 0 || hasApple[nxt]) {
                total += childTime + 2;
            }
        }
        return total;
    }
}

