class Solution {
    private static final int MOD = 1_000_000_007;

    public static int ways(String[] pizza, int k) {
        int rows = pizza.length;
        int cols = pizza[0].length();
        int[][] apples = new int[rows + 1][cols + 1];
        for (int i = rows - 1; i >= 0; i--) {
            for (int j = cols - 1; j >= 0; j--) {
                apples[i][j] = (pizza[i].charAt(j) == 'A' ? 1 : 0)
                        + apples[i + 1][j] + apples[i][j + 1] - apples[i + 1][j + 1];
            }
        }
        int[][][] dp = new int[k + 1][rows][cols];
        for (int i = rows - 1; i >= 0; i--) {
            for (int j = cols - 1; j >= 0; j--) {
                dp[1][i][j] = apples[i][j] > 0 ? 1 : 0;
            }
        }
        for (int cuts = 2; cuts <= k; cuts++) {
            for (int i = rows - 1; i >= 0; i--) {
                for (int j = cols - 1; j >= 0; j--) {
                    long ways = 0;
                    for (int row = i + 1; row < rows; row++) {
                        if (apples[i][j] - apples[row][j] > 0) {
                            ways += dp[cuts - 1][row][j];
                        }
                    }
                    for (int col = j + 1; col < cols; col++) {
                        if (apples[i][j] - apples[i][col] > 0) {
                            ways += dp[cuts - 1][i][col];
                        }
                    }
                    dp[cuts][i][j] = (int) (ways % MOD);
                }
            }
        }
        return dp[k][0][0];
    }
}

