import java.util.*;

class Solution {
    private static class Item {
        String word;
        int len;
        int idx;
        Item(String word, int len, int idx) {
            this.word = word;
            this.len = len;
            this.idx = idx;
        }
    }

    public static String rearrangeWords(String text) {
        String[] words = text.split(" ");
        String[] lower = new String[words.length];
        for (int i = 0; i < words.length; i++) {
            lower[i] = words[i].toLowerCase();
        }

        List<Item> items = new ArrayList<>(lower.length);
        for (int i = 0; i < lower.length; i++) {
            items.add(new Item(lower[i], lower[i].length(), i));
        }

        Collections.sort(items, (a, b) -> {
            if (a.len != b.len) return a.len - b.len;
            return a.idx - b.idx;
        });

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < items.size(); i++) {
            String w = items.get(i).word;
            if (i == 0) {
                w = Character.toUpperCase(w.charAt(0)) + w.substring(1);
            }
            sb.append(w);
            if (i < items.size() - 1) sb.append(' ');
        }
        return sb.toString();
    }
}

