class Solution {
    public static int maxPower(String s) {
        int maxLen = 0;
        int curLen = 0;
        char prevChar = '\0';
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == prevChar) {
                curLen++;
            } else {
                curLen = 1;
                prevChar = c;
            }
            if (curLen > maxLen) {
                maxLen = curLen;
            }
        }
        return maxLen;
    }
}

