class Solution {
    public static List<String> simplifiedFractions(int n) {
        List<String> result = new ArrayList<>();
        for (int num = 1; num < n; num++) {
            for (int den = num + 1; den <= n; den++) {
                if (gcd(num, den) == 1) {
                    result.add(num + "/" + den);
                }
            }
        }
        return result;
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

