import java.util.Arrays;

class Solution {
    public static String largestNumber(int[] cost, int target) {
        int NEG_INF = -1000000000;
        int[] dp = new int[target + 1];
        Arrays.fill(dp, NEG_INF);
        dp[0] = 0;
        for (int t = 1; t <= target; t++) {
            for (int d = 1; d <= 9; d++) {
                int c = cost[d - 1];
                if (t >= c && dp[t - c] != NEG_INF) {
                    dp[t] = Math.max(dp[t], dp[t - c] + 1);
                }
            }
        }
        if (dp[target] <= 0) {
            return "0";
        }
        int remaining = dp[target];
        StringBuilder result = new StringBuilder();
        while (remaining > 0) {
            for (int d = 9; d >= 1; d--) {
                int c = cost[d - 1];
                if (target >= c && dp[target - c] == remaining - 1) {
                    result.append(d);
                    target -= c;
                    remaining--;
                    break;
                }
            }
        }
        return result.toString();
    }
}

