class Solution {
    public static int maxVowels(String s, int k) {
        Set<Character> vowels = new HashSet<>();
        vowels.add('a');
        vowels.add('e');
        vowels.add('i');
        vowels.add('o');
        vowels.add('u');
        int windowCount = 0;
        for (int i = 0; i < k; i++) {
            if (vowels.contains(s.charAt(i))) windowCount++;
        }
        int maxCount = windowCount;
        for (int i = k; i < s.length(); i++) {
            if (vowels.contains(s.charAt(i))) windowCount++;
            if (vowels.contains(s.charAt(i - k))) windowCount--;
            if (windowCount > maxCount) maxCount = windowCount;
        }
        return maxCount;
    }
}

