class Solution {
    public static List<Integer> peopleIndexes(List<List<String>> favoriteCompanies) {
        int n = favoriteCompanies.size();
        List<Set<String>> sets = new ArrayList<>(n);
        for (List<String> arr : favoriteCompanies) {
            sets.add(new HashSet<>(arr));
        }
        class Info {
            int idx;
            Set<String> set;
            int size;
            Info(int idx, Set<String> set) {
                this.idx = idx;
                this.set = set;
                this.size = set.size();
            }
        }
        List<Info> info = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            info.add(new Info(i, sets.get(i)));
        }
        Collections.sort(info, (a, b) -> Integer.compare(b.size, a.size));
        boolean[] keep = new boolean[n];
        Arrays.fill(keep, true);
        for (int i = 0; i < n; i++) {
            Info cur = info.get(i);
            for (int j = 0; j < i; j++) {
                Info larger = info.get(j);
                boolean isSubset = true;
                for (String val : cur.set) {
                    if (!larger.set.contains(val)) {
                        isSubset = false;
                        break;
                    }
                }
                if (isSubset) {
                    keep[cur.idx] = false;
                    break;
                }
            }
        }
        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (keep[i]) {
                result.add(i);
            }
        }
        return result;
    }
}

import java.util.*;

public class Solution {
    public static int maxDarts(double[][] darts, double r) {
        int n = darts.length;
        if (n <= 1) return n;
        double TWO_PI = 2 * Math.PI;
        int bestOverall = 1;
        double maxDist = 2 * r;
        double eps = 1e-9;
        for (int i = 0; i < n; ++i) {
            List<double[]> events = new ArrayList<>();
            double xi = darts[i][0];
            double yi = darts[i][1];
            for (int j = 0; j < n; ++j) {
                if (i == j) continue;
                double dx = darts[j][0] - xi;
                double dy = darts[j][1] - yi;
                double d = Math.hypot(dx, dy);
                if (d > maxDist + eps) continue;
                double base = Math.atan2(dy, dx);
                double delta = Math.acos(Math.min(1.0, d / (2 * r)));
                double start = base - delta;
                double end = base + delta;
                if (start < 0) start += TWO_PI;
                if (end < 0) end += TWO_PI;
                if (start > end) {
                    events.add(new double[]{start, 1});
                    events.add(new double[]{TWO_PI, -1});
                    events.add(new double[]{0, 1});
                    events.add(new double[]{end, -1});
                } else {
                    events.add(new double[]{start, 1});
                    events.add(new double[]{end, -1});
                }
            }
            events.sort((a, b) -> {
                if (Math.abs(a[0] - b[0]) < 1e-12) {
                    return Double.compare(b[1], a[1]); // start (+1) before end (-1)
                }
                return Double.compare(a[0], b[0]);
            });
            int cur = 0, best = 0;
            for (double[] ev : events) {
                cur += (int) ev[1];
                if (cur > best) best = cur;
            }
            bestOverall = Math.max(bestOverall, best + 1);
        }
        return bestOverall;
    }
}

