class Solution {
    public static int isPrefixOfWord(String sentence, String searchWord) {
        int i = 0;
        int wordIdx = 1;
        while (i < sentence.length()) {
            int start = i;
            while (i < sentence.length()
                    && sentence.charAt(i) != ' '
                    && i - start < searchWord.length()
                    && sentence.charAt(i) == searchWord.charAt(i - start)) {
                i++;
            }
            if (i - start == searchWord.length()) {
                return wordIdx;
            }
            while (i < sentence.length() && sentence.charAt(i) != ' ') {
                i++;
            }
            if (i < sentence.length() && sentence.charAt(i) == ' ') {
                i++;
            }
            wordIdx++;
        }
        return -1;
    }
}

