class Solution {
    public static boolean canMakeEqual(int[] target, int[] arr) {
        HashMap<Integer, Integer> freq = new HashMap<>();
        for (int i = 0; i < target.length; i++) {
            int v = target[i];
            freq.put(v, freq.getOrDefault(v, 0) + 1);
        }
        for (int i = 0; i < arr.length; i++) {
            int v = arr[i];
