class Solution {
    public static int pseudoPalindromicPaths(TreeNode root) {
        int result = 0;
        Deque<NodeMask> stack = new ArrayDeque<>();
        stack.push(new NodeMask(root, 0));
        while (!stack.isEmpty()) {
            NodeMask nm = stack.pop();
            TreeNode node = nm.node;
            int mask = nm.mask;
            if (node == null) continue;
            int newMask = mask ^ (1 << node.val);
            if (node.left == null && node.right == null) {
                if ((newMask & (newMask - 1)) == 0) result++;
            } else {
                if (node.right != null) stack.push(new NodeMask(node.right, newMask));
                if (node.left != null) stack.push(new NodeMask(node.left, newMask));
            }
        }
        return result;
    }

    private static class NodeMask {
        TreeNode node;
        int mask;
        NodeMask(TreeNode n, int m) {
            node = n;
            mask = m;
        }
    }
}

