class Solution {
    public static int maxDotProduct(int[] nums1, int[] nums2) {
        int m = nums1.length, n = nums2.length;
        final int NEG_INF = Integer.MIN_VALUE;
        int[] dp = new int[n + 1];
        Arrays.fill(dp, NEG_INF);
        for (int i = 1; i <= m; i++) {
            int[] newRow = new int[n + 1];
            Arrays.fill(newRow, NEG_INF);
            int prevDiag = NEG_INF;
            for (int j = 1; j <= n; j++) {
                int prod = nums1[i - 1] * nums2[j - 1];
                int extend = (prevDiag == NEG_INF) ? NEG_INF : prevDiag + prod;
                int best = Math.max(Math.max(extend, prod), Math.max(dp[j], newRow[j - 1]));
                newRow[j] = best;
                prevDiag = dp[j];
            }
            System.arraycopy(newRow, 0, dp, 0, n + 1);
        }
        return dp[n];
    }
}

import java.util.Arrays;

class Solution {
    public static int maxArea(int h, int w, int[] horizontalCuts, int[] verticalCuts) {
        final long MOD = 1_000_000_007L;
        Arrays.sort(horizontalCuts);
        Arrays.sort(verticalCuts);
        int maxHeight = horizontalCuts[0];
        for (int i = 1; i < horizontalCuts.length; i++) {
            int gap = horizontalCuts[i] - horizontalCuts[i - 1];
            if (gap > maxHeight) maxHeight = gap;
        }
        int lastHeightGap = h - horizontalCuts[horizontalCuts.length - 1];
        if (lastHeightGap > maxHeight) maxHeight = lastHeightGap;
        int maxWidth = verticalCuts[0];
        for (int i = 1; i < verticalCuts.length; i++) {
            int gap = verticalCuts[i] - verticalCuts[i - 1];
            if (gap > maxWidth) maxWidth = gap;
        }
        int lastWidthGap = w - verticalCuts[verticalCuts.length - 1];
        if (lastWidthGap > maxWidth) maxWidth = lastWidthGap;
        long area = ((long) maxHeight * (long) maxWidth) % MOD;
        return (int) area;
    }
}

import java.util.Arrays;

class Solution {
    public static int cherryPickup(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int INF_NEG = Integer.MIN_VALUE;
        int[][] dp = new int[cols][cols];
        for (int i = 0; i < cols; i++) {
            Arrays.fill(dp[i], INF_NEG);
        }
        dp[0][cols - 1] = grid[0][0] + (cols == 1 ? 0 : grid[0][cols - 1]);
        for (int r = 1; r < rows; r++) {
            int[][] next = new int[cols][cols];
            for (int i = 0; i < cols; i++) {
                Arrays.fill(next[i], INF_NEG);
            }
            for (int c1 = 0; c1 < cols; c1++) {
                for (int c2 = 0; c2 < cols; c2++) {
                    if (dp[c1][c2] == INF_NEG) continue;
                    for (int d1 = -1; d1 <= 1; d1++) {
                        int nc1 = c1 + d1;
                        if (nc1 < 0 || nc1 >= cols) continue;
                        for (int d2 = -1; d2 <= 1; d2++) {
                            int nc2 = c2 + d2;
                            if (nc2 < 0 || nc2 >= cols) continue;
                            int add = grid[r][nc1];
                            if (nc1 != nc2) add += grid[r][nc2];
                            int candidate = dp[c1][c2] + add;
                            if (candidate > next[nc1][nc2]) {
                                next[nc1][nc2] = candidate;
                            }
                        }
                    }
                }
            }
            dp = next;
        }
        int ans = 0;
        for (int c1 = 0; c1 < cols; c1++) {
            for (int c2 = 0; c2 < cols; c2++) {
                if (dp[c1][c2] > ans) {
                    ans = dp[c1][c2];
                }
            }
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    public static double getProbability(int[] balls) {
        int k = balls.length;
        int total = 0;
        for (int b : balls) total += b;
        int n = total / 2;

        long[][] comb = new long[total + 1][total + 1];
        for (int i = 0; i <= total; i++) {
            comb[i][0] = comb[i][i] = 1;
            for (int j = 1; j < i; j++) {
                comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
            }
        }

        int diffSize = 2 * k + 1;
        int offset = k;
        long[][] cur = new long[n + 1][diffSize];
        long[][] next = new long[n + 1][diffSize];
        cur[0][offset] = 1L;

        for (int idx = 0; idx < k; idx++) {
            int cnt = balls[idx];
            for (int i = 0; i <= n; i++) Arrays.fill(next[i], 0L);
            for (int sel = 0; sel <= n; sel++) {
                for (int d = 0; d < diffSize; d++) {
                    long ways = cur[sel][d];
                    if (ways == 0) continue;
                    for (int x = 0; x <= cnt; x++) {
                        int newSel = sel + x;
                        if (newSel > n) continue;
                        int delta = (x == 0) ? -1 : (x == cnt ? 1 : 0);
                        int newD = d + delta;
                        if (newD < 0 || newD >= diffSize) continue;
                        next[newSel][newD] += ways * comb[cnt][x];
                    }
                }
            }
            long[][] tmp = cur;
            cur = next;
            next = tmp;
        }

        long favorable = cur[n][offset];
        long totalWays = comb[total][n];
        double prob = (double) favorable / (double) totalWays;
        return Math.round(prob * 1e5) / 1e5;
    }
}

