class Solution {
    public static boolean hasAllCodes(String s, int k) {
        int totalCodes = 1 << k;
        if (s.length() < k) return false;
        byte[] seen = new byte[totalCodes];
        int hash = 0;
        for (int i = 0; i < k; i++) {
            hash = (hash << 1) | (s.charAt(i) - '0');
        }
        seen[hash] = 1;
        int found = 1;
        int mask = totalCodes - 1;
        for (int i = k; i < s.length(); i++) {
            hash = ((hash << 1) & mask) | (s.charAt(i) - '0');
            if (seen[hash] == 0) {
                seen[hash] = 1;
                if (++found == totalCodes) return true;
            }
        }
        return found == totalCodes;
    }
}

