class Solution {
    public static int minReorder(int n, int[][] connections) {
        List<int[]>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int[] conn : connections) {
            int a = conn[0];
            int b = conn[1];
            adj[a].add(new int[]{b, 1});
            adj[b].add(new int[]{a, 0});
        }
        boolean[] visited = new boolean[n];
        int changes = 0;
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(0);
        visited[0] = true;
        while (!stack.isEmpty()) {
            int node = stack.pop();
            for (int[] edge : adj[node]) {
                int next = edge[0];
                int needReverse = edge[1];
                if (!visited[next]) {
                    changes += needReverse;
                    visited[next] = true;
                    stack.push(next);
                }
            }
        }
        return changes;
    }
}

