class Solution {
    public static int minCost(int[] houses, int[][] cost, int m, int n, int target) {
        if (target > m) return -1;
        long INF = Long.MAX_VALUE / 4;
        long[][] dpPrev = new long[target + 1][n + 1];
        for (int t = 0; t <= target; t++) Arrays.fill(dpPrev[t], INF);
        if (houses[0] != 0) {
            dpPrev[1][houses[0]] = 0;
        } else {
            for (int c = 1; c <= n; c++) {
                dpPrev[1][c] = cost[0][c - 1];
            }
        }
        for (int i = 1; i < m; i++) {
            long[][] dpCurr = new long[target + 1][n + 1];
            for (int t = 0; t <= target; t++) Arrays.fill(dpCurr[t], INF);
            long[] bestVal = new long[target + 1];
            int[] bestColor = new int[target + 1];
            long[] secondBest = new long[target + 1];
            for (int t = 1; t <= target; t++) {
                long b1 = INF, b2 = INF;
                int bc = -1;
                for (int c = 1; c <= n; c++) {
                    long v = dpPrev[t][c];
                    if (v < b1) {
                        b2 = b1;
                        b1 = v;
                        bc = c;
                    } else if (v < b2) {
                        b2 = v;
                    }
                }
                bestVal[t] = b1;
                bestColor[t] = bc;
                secondBest[t] = b2;
            }
            int[] colors;
            if (houses[i] != 0) {
                colors = new int[]{houses[i]};
            } else {
                colors = new int[n];
                for (int idx = 0; idx < n; idx++) colors[idx] = idx + 1;
            }
            for (int curC : colors) {
                long addCost = houses[i] == 0 ? cost[i][curC - 1] : 0;
                for (int t = 1; t <= target; t++) {
                    long best = INF;
                    long same = dpPrev[t][curC];
                    if (same != INF) best = same + addCost;
                    if (t > 1) {
                        long diff = (bestColor[t - 1] != curC) ? bestVal[t - 1] : secondBest[t - 1];
                        if (diff != INF) best = Math.min(best, diff + addCost);
                    }
                    dpCurr[t][curC] = best;
                }
            }
            dpPrev = dpCurr;
        }
        long ans = INF;
        for (int c = 1; c <= n; c++) ans = Math.min(ans, dpPrev[target][c]);
        return ans == INF ? -1 : (int) ans;
    }
}

