class Solution {
    public static int[] strongestValues(int[] arr, int k) {
        int n = arr.length;
        int[] sorted = arr.clone();
        Arrays.sort(sorted);
        int centre = sorted[(n - 1) / 2];
        int[] result = new int[k];
        int idx = 0;
        int l = 0, r = n - 1;
        while (idx < k) {
            int leftDist = Math.abs(sorted[l] - centre);
            int rightDist = Math.abs(sorted[r] - centre);
            if (rightDist > leftDist) {
                result[idx++] = sorted[r--];
            } else if (leftDist > rightDist) {
                result[idx++] = sorted[l++];
            } else {
                if (sorted[r] > sorted[l]) {
                    result[idx++] = sorted[r--];
                } else {
                    result[idx++] = sorted[l++];
                }
            }
        }
        return result;
    }
}

