class Solution {
    public static int minSumOfLengths(int[] arr, int target) {
        int n = arr.length;
        int INF = Integer.MAX_VALUE;
        int[] minLenEndingAt = new int[n];
        int[] minLenStartingAt = new int[n];
        Arrays.fill(minLenEndingAt, INF);
        Arrays.fill(minLenStartingAt, INF);
        int left = 0;
        long sum = 0;
        for (int right = 0; right < n; right++) {
            sum += arr[right];
            while (sum > target && left <= right) {
                sum -= arr[left++];
            }
            if (sum == target) {
                int len = right - left + 1;
                minLenEndingAt[right] = len;
                minLenStartingAt[left] = len;
            }
        }
        int[] bestPrefix = new int[n];
        for (int i = 0; i < n; i++) {
            bestPrefix[i] = i == 0 ? minLenEndingAt[i] : Math.min(bestPrefix[i - 1], minLenEndingAt[i]);
        }
        int[] bestSuffix = new int[n];
        for (int i = n - 1; i >= 0; i--) {
            bestSuffix[i] = i == n - 1 ? minLenStartingAt[i] : Math.min(bestSuffix[i + 1], minLenStartingAt[i]);
        }
        int answer = INF;
        for (int i = 0; i < n - 1; i++) {
            if (bestPrefix[i] < INF && bestSuffix[i + 1] < INF) {
                answer = Math.min(answer, bestPrefix[i] + bestSuffix[i + 1]);
            }
        }
        return answer == INF ? -1 : answer;
    }
}

import java.util.Arrays;

class Solution {
    public static int allocateMailboxes(int[] houses, int k) {
        Arrays.sort(houses);
        int n = houses.length;
        if (k >= n) return 0;
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + houses[i];
        }
        long INF = Long.MAX_VALUE / 4;
        long[] prev = new long[n];
        long[] cur = new long[n];
        for (int i = 0; i < n; i++) {
            prev[i] = cost(0, i, houses, prefix);
        }
        for (int m = 2; m <= k; m++) {
            Arrays.fill(cur, INF);
            for (int i = m - 1; i < n; i++) {
                long best = INF;
                for (int p = m - 2; p < i; p++) {
                    long cand = prev[p] + cost(p + 1, i, houses, prefix);
                    if (cand < best) best = cand;
                }
                cur[i] = best;
            }
            long[] temp = prev;
            prev = cur;
            cur = temp;
        }
        return (int) prev[n - 1];
    }

    private static long cost(int i, int j, int[] houses, long[] prefix) {
        int mid = (i + j) >>> 1;
        long left = (long) houses[mid] * (mid - i) - (prefix[mid] - prefix[i]);
        long right = (prefix[j + 1] - prefix[mid + 1]) - (long) houses[mid] * (j - mid);
        return left + right;
    }
}

