public class Solution {
    public static int xorOperation(int n, int start) {
        int a = start >> 1;
        int b = start & 1;
        int highXor = xor0To(a + n - 1) ^ xor0To(a - 1);
        return (highXor << 1) | (b & (n & 1));
    }
    private static int xor0To(int k) {
        switch (k & 3) {
            case 0: return k;
            case 1: return 1;
            case 2: return k + 1;
            default: return 0;
        }
    }
}

