class TreeAncestor {
    int LOG;
    int[][] up;
    public TreeAncestor(int n, int[] parent) {
        LOG = (int) Math.ceil(Math.log(Math.max(n,2)) / Math.log(2)) + 1;
        up = new int[LOG][n];
        for (int i = 0; i < n; i++) up[0][i] = parent[i];
        for (int j = 1; j < LOG; j++) {
            for (int i = 0; i < n; i++) {
                int mid = up[j-1][i];
                up[j][i] = mid == -1 ? -1 : up[j-1][mid];
            }
        }
    }
    public int getKthAncestor(int node, int k) {
        for (int j = 0; j < LOG && node != -1; j++) if ((k & (1<<j)) != 0) node = up[j][node];
        return node;
    }
}

