class Solution {
    public static int[] avoidFlood(int[] rains) {
        int n = rains.length;
        int[] ans = new int[n];
        Arrays.fill(ans, 1);
        TreeSet<Integer> dryDays = new TreeSet<>();
        Map<Integer, Integer> lakeLastRain = new HashMap<>();
        for (int i = 0; i < n; i++) {
            if (rains[i] == 0) {
                dryDays.add(i);
            } else {
                int lake = rains[i];
                if (lakeLastRain.containsKey(lake)) {
                    int prevDay = lakeLastRain.get(lake);
                    Integer dryDay = dryDays.higher(prevDay);
                    if (dryDay == null) {
                        return new int[0];
                    }
                    ans[dryDay] = lake;
                    dryDays.remove(dryDay);
                }
                lakeLastRain.put(lake, i);
                ans[i] = -1;
            }
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    private static class Edge {
        int u, v, w, idx;
        Edge(int u, int v, int w, int idx) {
            this.u = u;
            this.v = v;
            this.w = w;
            this.idx = idx;
        }
    }

    private static class DSU {
        int[] parent;
        int[] rank;
        DSU(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) parent[i] = i;
        }
        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }
        boolean union(int x, int y) {
            int rx = find(x), ry = find(y);
            if (rx == ry) return false;
            if (rank[rx] < rank[ry]) {
                parent[rx] = ry;
            } else if (rank[rx] > rank[ry]) {
                parent[ry] = rx;
            } else {
                parent[ry] = rx;
                rank[rx]++;
            }
            return true;
        }
    }

    private static int kruskal(int n, Edge[] edges, int skipIdx, Edge forced) {
        DSU dsu = new DSU(n);
        int total = 0, used = 0;
        if (forced != null && dsu.union(forced.u, forced.v)) {
            total += forced.w;
            used++;
        }
        for (Edge e : edges) {
            if (e.idx == skipIdx) continue;
            if (forced != null && e.idx == forced.idx) continue;
            if (dsu.union(e.u, e.v)) {
                total += e.w;
                used++;
                if (used == n - 1) break;
            }
        }
        return used == n - 1 ? total : Integer.MAX_VALUE;
    }

    public static List<List<Integer>> findCriticalAndPseudoCriticalEdges(int n, int[][] edges) {
        Edge[] edgeObjs = new Edge[edges.length];
        for (int i = 0; i < edges.length; i++) {
            edgeObjs[i] = new Edge(edges[i][0], edges[i][1], edges[i][2], i);
        }
        Arrays.sort(edgeObjs, Comparator.comparingInt(e -> e.w));
        int originalWeight = kruskal(n, edgeObjs, -1, null);
        List<Integer> critical = new ArrayList<>();
        List<Integer> pseudo = new ArrayList<>();
        for (Edge e : edgeObjs) {
            int weightWithout = kruskal(n, edgeObjs, e.idx, null);
            if (weightWithout > originalWeight) {
                critical.add(e.idx);
            } else {
                int weightWith = kruskal(n, edgeObjs, -1, e);
                if (weightWith == originalWeight) {
                    pseudo.add(e.idx);
                }
            }
        }
        List<List<Integer>> result = new ArrayList<>(2);
        result.add(critical);
        result.add(pseudo);
        return result;
    }
}

