class Solution {
    public static boolean canArrange(int[] arr, int k) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int i = 0; i < arr.length; i++) {
            int rem = ((arr[i] % k) + k) % k;
            freq.put(rem, freq.getOrDefault(rem, 0) + 1);
        }
        if (freq.getOrDefault(0, 0) % 2 != 0) return false;
        if (k % 2 == 0 && freq.getOrDefault(k / 2, 0) % 2 != 0) return false;
        for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
            int rem = entry.getKey();
            int cnt = entry.getValue();
            if (rem == 0 || (k % 2 == 0 && rem == k / 2)) continue;
            int complement = k - rem;
            if (freq.getOrDefault(complement, 0) != cnt) return false;
        }
        return true;
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    private static class Node {
        int x;
        long val;
        Node(int x, long val) {
            this.x = x;
            this.val = val;
        }
    }

    public static long maxValueOfEquation(int[][] points, int k) {
        Deque<Node> deque = new ArrayDeque<>();
        long best = Long.MIN_VALUE;
        for (int i = 0; i < points.length; i++) {
            int xj = points[i][0];
            int yj = points[i][1];
            while (!deque.isEmpty() && deque.peekFirst().x < xj - k) {
                deque.pollFirst();
            }
            if (!deque.isEmpty()) {
                long candidate = deque.peekFirst().val + yj + xj;
                if (candidate > best) {
                    best = candidate;
                }
            }
            long curVal = (long) yj - xj;
            while (!deque.isEmpty() && deque.peekLast().val <= curVal) {
                deque.pollLast();
            }
            deque.offerLast(new Node(xj, curVal));
        }
        return best;
    }
}

