import java.util.*;

class Solution {
    private static final long MOD = 1_000_000_007L;

    public static int rangeSum(int[] nums, int n, int left, int right) {
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] + nums[i];
        }
        long[] uniq = pref.clone();
        Arrays.sort(uniq);
        int m = 0;
        for (int i = 0; i < uniq.length; i++) {
            if (i == 0 || uniq[i] != uniq[i - 1]) {
                uniq[m++] = uniq[i];
            }
        }
        uniq = Arrays.copyOf(uniq, m);
        long sumRight = prefixSum(pref, uniq, right);
        long sumLeft = prefixSum(pref, uniq, left - 1);
        long ans = (sumRight - sumLeft) % MOD;
        if (ans < 0) ans += MOD;
        return (int) ans;
    }

    private static long prefixSum(long[] pref, long[] uniq, long k) {
        if (k <= 0) return 0;
        long low = 0;
        long high = pref[pref.length - 1];
        while (low < high) {
            long mid = (low + high) >>> 1;
            long cnt = countAndSum(pref, uniq, mid)[0];
            if (cnt >= k) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        long[] cs = countAndSum(pref, uniq, low);
        long cnt = cs[0];
        long sum = cs[1];
        long extra = cnt - k;
        sum -= extra * low;
        return sum;
    }

    private static long[] countAndSum(long[] pref, long[] uniq, long limit) {
        int m = uniq.length;
        BIT bitCnt = new BIT(m);
        BIT bitSum = new BIT(m);
        long totalCnt = 0;
        long totalSum = 0;
        long sumPrev = 0;
        for (int j = 0; j < pref.length; j++) {
            long p = pref[j];
            long target = p - limit;
            int idx = lowerBound(uniq, target);
            int pos = idx; // number of elements < target
            long cntLess = bitCnt.query(pos);
            long sumLess = bitSum.query(pos);
            long cntGe = j - cntLess;
            long sumGe = sumPrev - sumLess;
            totalCnt += cntGe;
            totalSum += cntGe * p - sumGe;
            int pIdx = lowerBound(uniq, p) + 1;
            bitCnt.add(pIdx, 1);
            bitSum.add(pIdx, p);
            sumPrev += p;
        }
        return new long[]{totalCnt, totalSum};
    }

    private static int lowerBound(long[] arr, long key) {
        int l = 0, r = arr.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (arr[mid] < key) {
                l = mid + 1;
            } else {
                r = mid;
            }
        }
        return l;
    }

    private static class BIT {
        private final int n;
        private final long[] tree;

        BIT(int n) {
            this.n = n;
            this.tree = new long[n + 2];
        }

        void add(int idx, long val) {
            for (int i = idx; i <= n; i += i & -i) {
                tree[i] += val;
            }
        }

        long query(int idx) {
            long res = 0;
            for (int i = idx; i > 0; i -= i & -i) {
                res += tree[i];
            }
            return res;
        }
    }
}

