class Solution {
    public static int[] countSubTrees(int n, int[][] edges, String labels) {
        List<Integer>[] g = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            g[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            g[u].add(v);
            g[v].add(u);
        }
        int[] ans = new int[n];
        boolean[] visited = new boolean[n];
        dfs(0, g, visited, ans, labels);
        return ans;
    }

    private static int[] dfs(int u, List<Integer>[] g, boolean[] visited, int[] ans, String labels) {
        visited[u] = true;
        int[] cnt = new int[26];
        int idx = labels.charAt(u) - 'a';
        cnt[idx] = 1;
        for (int v : g[u]) {
            if (!visited[v]) {
                int[] childCnt = dfs(v, g, visited, ans, labels);
                for (int i = 0; i < 26; i++) {
                    cnt[i] += childCnt[i];
                }
            }
        }
        ans[u] = cnt[idx];
        return cnt;
    }
}

import java.lang.Math;

class Solution {
    public static double bestPosition(double[][] positions) {
        double eps = 1e-7;
        double x = 0.0, y = 0.0;
        for (double[] p : positions) {
            x += p[0];
            y += p[1];
        }
        x /= positions.length;
        y /= positions.length;
        while (true) {
            double numX = 0.0, numY = 0.0, den = 0.0;
            for (double[] p : positions) {
                double dx = x - p[0];
                double dy = y - p[1];
                double dist = Math.hypot(dx, dy);
                if (dist < eps) {
                    x = p[0];
                    y = p[1];
                    numX = x;
                    numY = y;
                    den = 1.0;
                    break;
                }
                double w = 1.0 / dist;
                numX += p[0] * w;
                numY += p[1] * w;
                den += w;
            }
            double newX = numX / den;
            double newY = numY / den;
            if (Math.hypot(newX - x, newY - y) < eps) {
                x = newX;
                y = newY;
                break;
            }
            x = newX;
            y = newY;
        }
        double total = 0.0;
        for (double[] p : positions) {
            total += Math.hypot(x - p[0], y - p[1]);
        }
        return Math.round(total * 100000.0) / 100000.0;
    }
}

import java.util.*;

class Solution {
    public static List<String> maxNumOfSubstrings(String s) {
        int n = s.length();
        int[] left = new int[26];
        int[] right = new int[26];
        Arrays.fill(left, -1);
        Arrays.fill(right, -1);
        for (int i = 0; i < n; ++i) {
            int idx = s.charAt(i) - 'a';
            if (left[idx] == -1) left[idx] = i;
            right[idx] = i;
        }
        List<int[]> intervals = new ArrayList<>();
        for (int i = 0; i < n; ++i) {
            int idx = s.charAt(i) - 'a';
            if (i != left[idx]) continue;
            int start = i;
            int end = right[idx];
            int j = start;
            boolean ok = true;
            while (j <= end) {
                int curIdx = s.charAt(j) - 'a';
                if (left[curIdx] < start) {
                    ok = false;
                    break;
                }
                end = Math.max(end, right[curIdx]);
                ++j;
            }
            if (ok) intervals.add(new int[]{start, end});
        }
        intervals.sort(Comparator.comparingInt(a -> a[1]));
        List<int[]> selected = new ArrayList<>();
        int lastEnd = -1;
        for (int[] seg : intervals) {
            if (seg[0] > lastEnd) {
                selected.add(seg);
                lastEnd = seg[1];
            }
        }
        selected.sort((a, b) -> {
            int lenA = a[1] - a[0];
            int lenB = b[1] - b[0];
            if (lenA != lenB) return Integer.compare(lenA, lenB);
            return Integer.compare(a[0], b[0]);
        });
        List<String> result = new ArrayList<>();
        for (int[] seg : selected) {
            result.add(s.substring(seg[0], seg[1] + 1));
        }
        return result;
    }
}

