        long evenCnt = 1;
        long oddCnt = 0;
        int parity = 0;
        long ans = 0;
        for (int i = 0; i < arr.length; i++) {
            parity ^= (arr[i] & 1);
            if (parity == 1) {
                ans = (ans + evenCnt) % MOD;
