class Solution {
    public static int numberOfGoodSplits(String s) {
        int n = s.length();
        int[] freq = new int[26];
        for (int i = 0; i < n; i++) {
            freq[s.charAt(i) - 'a']++;
        }
        int rightDistinct = 0;
        for (int count : freq) {
            if (count > 0) rightDistinct++;
        }
        boolean[] leftSeen = new boolean[26];
        int leftDistinct = 0;
        int goodSplits = 0;
        for (int i = 0; i < n - 1; i++) {
            int idx = s.charAt(i) - 'a';
            if (!leftSeen[idx]) {
                leftSeen[idx] = true;
                leftDistinct++;
            }
            freq[idx]--;
            if (freq[idx] == 0) {
                rightDistinct--;
            }
            if (leftDistinct == rightDistinct) {
                goodSplits++;
            }
        }
        return goodSplits;
    }
}

