    public static int minSuffixFlips(String target) {
        int flips = 0;
        int parity = 0;
        for (int i = 0; i < target.length(); i++) {
            int bit = target.charAt(i) - '0';
            if ((bit ^ parity) == 1) {
                flips++;
                parity ^= 1;
            }
        }
        return flips;
    }
}

class Solution {
    public static long minNumberOperations(int[] target) {
        if (target == null || target.length == 0) {
            return 0;
        }
        long ops = target[0];
        for (int i = 1; i < target.length; i++) {
            int diff = target[i] - target[i - 1];
            if (diff > 0) {
                ops += diff;
            }
        }
        return ops;
    }
}

