class Solution {
    private static int goodPairs;

    public static int countPairs(TreeNode root, int distance) {
        goodPairs = 0;
        dfs(root, distance);
        return goodPairs;
    }

    private static List<Integer> dfs(TreeNode node, int distance) {
        if (node == null) {
            return new ArrayList<>();
        }
        if (node.left == null && node.right == null) {
            List<Integer> leafList = new ArrayList<>(1);
            leafList.add(1);
            return leafList;
        }

        List<Integer> leftDist = dfs(node.left, distance);
        List<Integer> rightDist = dfs(node.right, distance);

        for (int l : leftDist) {
            for (int r : rightDist) {
                if (l + r <= distance) {
                    goodPairs++;
                }
            }
        }

        List<Integer> curDist = new ArrayList<>();
        for (int d : leftDist) {
            if (d + 1 <= distance) {
                curDist.add(d + 1);
            }
        }
        for (int d : rightDist) {
            if (d + 1 <= distance) {
                curDist.add(d + 1);
            }
        }
        return curDist;
    }
}

