class Solution {
    public static int getLengthOfOptimalCompression(String s, int k) {
        int n = s.length();
        int INF = 1_000_000;
        int[][] dp = new int[n + 1][k + 1];
        for (int i = 0; i <= n; i++) {
            Arrays.fill(dp[i], INF);
        }
        for (int del = 0; del <= k; del++) {
            dp[n][del] = 0;
        }
        for (int i = n - 1; i >= 0; i--) {
            for (int del = 0; del <= k; del++) {
                if (del > 0) {
                    dp[i][del] = Math.min(dp[i][del], dp[i + 1][del - 1]);
                }
                int same = 0;
                for (int j = i; j < n; j++) {
                    if (s.charAt(j) == s.charAt(i)) {
                        same++;
                    }
                    int deletionsNeeded = (j - i + 1) - same;
                    if (deletionsNeeded > del) {
                        continue;
                    }
                    int cost = getLen(same) + dp[j + 1][del - deletionsNeeded];
                    dp[i][del] = Math.min(dp[i][del], cost);
                }
            }
        }
        return dp[0][k];
    }

    private static int getLen(int cnt) {
        if (cnt == 1) return 1;
        if (cnt < 10) return 2;
        if (cnt < 100) return 3;
        return 4;
    }
}

class Solution {
    public static int countGoodTriplets(int[] arr, int a, int b, int c) {
        int n = arr.length;
        int good = 0;
        for (int i = 0; i < n - 2; i++) {
            for (int j = i + 1; j < n - 1; j++) {
                if (Math.abs(arr[i] - arr[j]) > a) continue;
                for (int k = j + 1; k < n; k++) {
                    if (Math.abs(arr[j] - arr[k]) <= b && Math.abs(arr[i] - arr[k]) <= c) {
                        good++;
                    }
                }
            }
        }
        return good;
    }
}

