class Solution {
    public static boolean canConvertString(String s, String t, int k) {
        if (s.length() != t.length()) return false;
        int[] need = new int[26];
        for (int i = 0; i < s.length(); i++) {
            int diff = (t.charAt(i) - s.charAt(i) + 26) % 26;
            if (diff != 0) need[diff]++;
        }
        for (int r = 1; r < 26; r++) {
            if (need[r] == 0) continue;
            if (k < r) return false;
            int maxMoves = (k - r) / 26 + 1;
            if (need[r] > maxMoves) return false;
        }
        return true;
    }
}

