            for (int v : arr) {
                if (v > champion) champion = v;
            }
            return champion;
        }
        for (int i = 1; i < arr.length; i++) {
            if (champion > arr[i]) {
                winCnt++;
            } else {
                champion = arr[i];
                winCnt = 1;
            }
            if (winCnt == k) return champion;
        }
        return champion;
    }
