class Solution {
    public static int findKthMissingPositive(int[] arr, int k) {
        int left = 0, right = arr.length - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            int missing = arr[mid] - (mid + 1);
            if (missing < k) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        if (left == arr.length) {
            int totalMissing = arr[arr.length - 1] - arr.length;
            return arr[arr.length - 1] + (k - totalMissing);
        }
        int missingAtLeft = arr[left] - (left + 1);
        return arr[left] - (missingAtLeft - k + 1);
    }
}

