class Solution {
    public static String makeGoodString(String s) {
        Deque<Character> stack = new ArrayDeque<>();
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            Character top = stack.peekLast();
            if (!stack.isEmpty() && ch != top && Character.toLowerCase(ch) == Character.toLowerCase(top)) {
                stack.pollLast();
            } else {
                stack.addLast(ch);
            }
        }
        StringBuilder sb = new StringBuilder(stack.size());
        for (char c : stack) {
            sb.append(c);
        }
        return sb.toString();
    }
}

