class Solution {
    public static int longestAwesome(String s) {
        int[] earliest = new int[1 << 10];
        Arrays.fill(earliest, -1);
        earliest[0] = 0;
        int mask = 0;
        int maxLen = 0;
        for (int i = 0; i < s.length(); i++) {
            mask ^= 1 << (s.charAt(i) - '0');
            if (earliest[mask] != -1) {
                maxLen = Math.max(maxLen, i + 1 - earliest[mask]);
            } else {
                earliest[mask] = i + 1;
            }
            for (int b = 0; b < 10; b++) {
                int toggled = mask ^ (1 << b);
                if (earliest[toggled] != -1) {
                    maxLen = Math.max(maxLen, i + 1 - earliest[toggled]);
                }
            }
        }
        return maxLen;
    }
}

