class Solution {
    public static int minCost(int n, int[] cuts) {
        int[] sortedCuts = cuts.clone();
        Arrays.sort(sortedCuts);
        int m = sortedCuts.length + 2;
        int[] pos = new int[m];
        pos[0] = 0;
        for (int i = 0; i < sortedCuts.length; i++) {
            pos[i + 1] = sortedCuts[i];
        }
        pos[m - 1] = n;
        int[][] dp = new int[m][m];
        int[][] opt = new int[m][m];
        for (int i = 0; i < m - 1; i++) {
            dp[i][i + 1] = 0;
            opt[i][i + 1] = i + 1;
        }
        int INF = Integer.MAX_VALUE / 2;
        for (int len = 2; len < m; len++) {
            for (int i = 0; i + len < m; i++) {
                int j = i + len;
                dp[i][j] = INF;
                int start = opt[i][j - 1];
                int end = opt[i + 1][j];
                for (int k = start; k <= end; k++) {
                    int cost = dp[i][k] + dp[k][j] + pos[j] - pos[i];
                    if (cost < dp[i][j]) {
                        dp[i][j] = cost;
                        opt[i][j] = k;
                    }
                }
            }
        }
        return dp[0][m - 1];
    }
}

