class Solution {
    public static int minDays(int n) {
        Map<Integer, Integer> memo = new HashMap<>();
        return dfs(n, memo);
    }

    private static int dfs(int x, Map<Integer, Integer> memo) {
        if (x <= 1) return x;
        Integer cached = memo.get(x);
        if (cached != null) return cached;
        int daysVia2 = x % 2 + dfs(x / 2, memo);
        int daysVia3 = x % 3 + dfs(x / 3, memo);
        int result = 1 + Math.min(daysVia2, daysVia3);
        memo.put(x, result);
        return result;
    }
}

