class Solution {
    public static int maxMagneticForce(int[] position, int m) {
        Arrays.sort(position);
        int low = 0;
        int high = position[position.length - 1] - position[0];
        while (low < high) {
            int mid = (low + high + 1) / 2;
            if (canPlace(position, m, mid)) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return low;
    }

    private static boolean canPlace(int[] position, int m, int dist) {
        int count = 1;
        int last = position[0];
        for (int i = 1; i < position.length; i++) {
            if (position[i] - last >= dist) {
                count++;
                last = position[i];
                if (count >= m) {
                    return true;
                }
            }
        }
        return false;
    }
}

class Solution {
    public static int minOperations(int[] nums) {
        int totalOnes = 0;
        int max = 0;
        for (int v : nums) {
            totalOnes += Integer.bitCount(v);
            if (v > max) max = v;
        }
        if (max == 0) {
            return totalOnes;
        }
        int bitLength = 32 - Integer.numberOfLeadingZeros(max);
        return totalOnes + bitLength - 1;
    }
}

