class Solution {
    public static int stoneGameV(int[] stoneValue) {
        int n = stoneValue.length;
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + stoneValue[i];
        }
        long[][] dp = new long[n][n];
        for (int i = n - 2; i >= 0; i--) {
            int k = i;
            for (int j = i + 1; j < n; j++) {
                while (k < j) {
                    long left = prefix[k + 1] - prefix[i];
                    long right = prefix[j + 1] - prefix[k + 1];
                    if (left < right) {
                        k++;
                    } else {
                        break;
                    }
                }
                long best = 0;
                if (k < j) {
                    long left = prefix[k + 1] - prefix[i];
                    long right = prefix[j + 1] - prefix[k + 1];
                    if (left < right) {
                        best = Math.max(best, left + dp[i][k]);
                    } else if (left > right) {
                        best = Math.max(best, right + dp[k + 1][j]);
                    } else {
                        best = Math.max(best, left + Math.max(dp[i][k], dp[k + 1][j]));
                    }
                }
                if (k - 1 >= i) {
                    int kk = k - 1;
                    long left = prefix[kk + 1] - prefix[i];
                    long right = prefix[j + 1] - prefix[kk + 1];
                    if (left < right) {
                        best = Math.max(best, left + dp[i][kk]);
                    } else if (left > right) {
                        best = Math.max(best, right + dp[kk + 1][j]);
                    } else {
                        best = Math.max(best, left + Math.max(dp[i][kk], dp[kk + 1][j]));
                    }
                }
                dp[i][j] = best;
            }
        }
        return (int) dp[0][n - 1];
    }
}

