class Solution {
    public static boolean detectCycle(char[][] grid) {
        int rows = grid.length;
        if (rows == 0) return false;
        int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!visited[r][c]) {
                    if (dfs(r, c, -1, -1, grid[r][c], grid, visited, rows, cols, dirs)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private static boolean dfs(int r, int c, int pr, int pc, char ch,
                               char[][] grid, boolean[][] visited,
                               int rows, int cols, int[][] dirs) {
        visited[r][c] = true;
        for (int[] d : dirs) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
            if (grid[nr][nc] != ch) continue;
            if (nr == pr && nc == pc) continue;
            if (visited[nr][nc]) return true;
            if (dfs(nr, nc, r, c, ch, grid, visited, rows, cols, dirs)) return true;
        }
        return false;
    }
}

