public class Solution {
    private static int countIslands(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        boolean[][] visited = new boolean[m][n];
        int islands = 0;
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        Deque<int[]> stack = new ArrayDeque<>();
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1 && !visited[i][j]) {
                    islands++;
                    stack.push(new int[]{i, j});
                    visited[i][j] = true;
                    while (!stack.isEmpty()) {
                        int[] cur = stack.pop();
                        int x = cur[0], y = cur[1];
                        for (int[] d : dirs) {
                            int nx = x + d[0], ny = y + d[1];
                            if (nx >= 0 && nx < m && ny >= 0 && ny < n && grid[nx][ny] == 1 && !visited[nx][ny]) {
                                visited[nx][ny] = true;
                                stack.push(new int[]{nx, ny});
                            }
                        }
                    }
                }
            }
        }
        return islands;
    }

    private static void dfsArticulation(int[][] grid, boolean[][] visited, int[][] disc, int[][] low,
                                         int x, int y, int px, int py, int[] time, boolean[] found) {
        visited[x][y] = true;
        disc[x][y] = low[x][y] = ++time[0];
        int children = 0;
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        for (int[] d : dirs) {
            int nx = x + d[0], ny = y + d[1];
            if (nx < 0 || nx >= grid.length || ny < 0 || ny >= grid[0].length || grid[nx][ny] == 0) continue;
            if (!visited[nx][ny]) {
                children++;
                dfsArticulation(grid, visited, disc, low, nx, ny, x, y, time, found);
                low[x][y] = Math.min(low[x][y], low[nx][ny]);
                if (px == -1 && children > 1) found[0] = true;
                if (px != -1 && low[nx][ny] >= disc[x][y]) found[0] = true;
            } else if (nx != px || ny != py) {
                low[x][y] = Math.min(low[x][y], disc[nx][ny]);
            }
        }
    }

    public static int minDays(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int landCount = 0;
        for (int[] row : grid) for (int v : row) if (v == 1) landCount++;
        if (landCount <= 1) return landCount;
        if (countIslands(grid) != 1) return 0;
        boolean[][] visited = new boolean[m][n];
        int[][] disc = new int[m][n];
        int[][] low = new int[m][n];
        int[] time = {0};
        boolean[] found = {false};
        outer:
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    dfsArticulation(grid, visited, disc, low, i, j, -1, -1, time, found);
                    break outer;
                }
            }
        }
        return found[0] ? 1 : 2;
    }
}

