class Solution {
    public static int findLatestStep(int[] arr, int m) {
        int n = arr.length;
        if (m == n) return n;
        int[] len = new int[n + 2];
        int groupsM = 0;
        int answer = -1;
        for (int step = 0; step < n; step++) {
            int pos = arr[step];
            int leftLen = len[pos - 1];
            int rightLen = len[pos + 1];
            int totalLen = leftLen + 1 + rightLen;
            if (leftLen == m) groupsM--;
            if (rightLen == m) groupsM--;
            if (totalLen == m) groupsM++;
            len[pos - leftLen] = totalLen;
            len[pos + rightLen] = totalLen;
            if (groupsM > 0) answer = step + 1;
        }
        return answer;
    }
}

import java.util.*;

public class Solution {
    private static final long MOD = 1_000_000_007L;
    private static long[] fact;
    private static long[] invFact;
    private static int N;

    public static int numOfWays(int[] nums) {
        N = nums.length;
        precomputeFactorials(N);
        TreeNode root = new TreeNode(nums[0]);
        for (int i = 1; i < N; i++) {
            insert(root, nums[i]);
        }
        long ways = dfs(root)[1];
        ways = (ways - 1 + MOD) % MOD;
        return (int) ways;
    }

    private static void precomputeFactorials(int n) {
        fact = new long[n + 1];
        invFact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[n] = modPow(fact[n], MOD - 2);
        for (int i = n - 1; i >= 0; i--) {
            invFact[i] = invFact[i + 1] * (i + 1) % MOD;
        }
    }

    private static long[] dfs(TreeNode node) {
        if (node == null) {
            return new long[]{0, 1};
        }
        long[] left = dfs(node.left);
        long[] right = dfs(node.right);
        long leftSize = left[0];
        long rightSize = right[0];
        long leftWays = left[1];
        long rightWays = right[1];
        long interleave = nCr(leftSize + rightSize, leftSize);
        long ways = interleave * leftWays % MOD * rightWays % MOD;
        return new long[]{leftSize + rightSize + 1, ways};
    }

    private static long nCr(long n, long k) {
        if (k < 0 || k > n) return 0;
        return fact[(int) n] * invFact[(int) k] % MOD * invFact[(int) (n - k)] % MOD;
    }

    private static long modPow(long base, long exp) {
        long result = 1;
        long b = base % MOD;
        long e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = result * b % MOD;
            }
            b = b * b % MOD;
            e >>= 1;
        }
        return result;
    }

    private static void insert(TreeNode root, int val) {
        while (true) {
            if (val < root.val) {
                if (root.left == null) {
                    root.left = new TreeNode(val);
                    break;
                }
                root = root.left;
            } else {
                if (root.right == null) {
                    root.right = new TreeNode(val);
                    break;
                }
                root = root.right;
            }
        }
    }
}

