class Solution {
    public static boolean detectPattern(int[] arr, int m, int k) {
        int n = arr.length;
        if ((long) m * k > n) return false;
        final long MOD = 1_000_000_007L;
        final long BASE = 1_000_003L;
        long[] prefix = new long[n + 1];
        long[] power = new long[n + 1];
        power[0] = 1;
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = (prefix[i] * BASE + arr[i]) % MOD;
            power[i + 1] = (power[i] * BASE) % MOD;
        }
        int[] repeat = new int[n];
        for (int i = n - m; i >= 0; i--) {
            if (i + 2 * m <= n) {
                long hash1 = (prefix[i + m] - (prefix[i] * power[m]) % MOD + MOD) % MOD;
                long hash2 = (prefix[i + 2 * m] - (prefix[i + m] * power[m]) % MOD + MOD) % MOD;
                if (hash1 == hash2) {
                    repeat[i] = repeat[i + m] + 1;
                } else {
                    repeat[i] = 1;
                }
            } else {
                repeat[i] = 1;
            }
            if (repeat[i] >= k) return true;
        }
        return false;
    }
}

