class Solution {
    public static int getMaxLen(int[] nums) {
        int pos = 0;
        int neg = 0;
        int best = 0;
        for (int i = 0; i < nums.length; i++) {
            int x = nums[i];
            if (x > 0) {
                pos = pos + 1;
                neg = (neg > 0) ? neg + 1 : 0;
            } else if (x < 0) {
                int newPos = (neg > 0) ? neg + 1 : 0;
                int newNeg = pos + 1;
                pos = newPos;
                neg = newNeg;
            } else {
                pos = 0;
                neg = 0;
            }
            if (pos > best) best = pos;
        }
        return best;
    }
}

import java.util.Arrays;

class Solution {
    public static int countRoutes(int[] locations, int start, int finish, int fuel) {
        final int MOD = 1_000_000_007;
        int n = locations.length;
        int[][] memo = new int[n][fuel + 1];
        for (int i = 0; i < n; i++) {
            Arrays.fill(memo[i], -1);
        }
        return dfs(start, fuel, locations, finish, memo, n, MOD);
    }

    private static int dfs(int city, int remaining, int[] locations, int finish, int[][] memo, int n, int MOD) {
        if (memo[city][remaining] != -1) return memo[city][remaining];
        int ways = (city == finish) ? 1 : 0;
        for (int nxt = 0; nxt < n; nxt++) {
            if (nxt == city) continue;
            int cost = Math.abs(locations[city] - locations[nxt]);
            if (cost <= remaining) {
                ways = (int) ((ways + dfs(nxt, remaining - cost, locations, finish, memo, n, MOD)) % MOD);
            }
        }
        memo[city][remaining] = ways;
        return ways;
    }
}

