class Solution {
    public static String replaceQuestionMarks(String s) {
        int n = s.length();
        char[] res = s.toCharArray();
        for (int i = 0; i < n; i++) {
            if (res[i] == '?') {
                for (int c = 97; c <= 99; c++) {
                    char ch = (char) c;
                    boolean leftOk = (i == 0) || (ch != res[i - 1]);
                    boolean rightOk = (i == n - 1) || (s.charAt(i + 1) == '?') || (ch != s.charAt(i + 1));
                    if (leftOk && rightOk) {
                        res[i] = ch;
                        break;
                    }
                }
            }
        }
        return new String(res);
    }
}

class Solution {
    public static int diagonalSum(int[][] mat) {
