public class Solution {
    public static int numberOfWays(String s) {
        final long MOD = 1_000_000_007L;
        int n = s.length();
        int totalOnes = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '1') totalOnes++;
        }
        if (totalOnes % 3 != 0) return 0;
        if (totalOnes == 0) {
            long ways = ((long) (n - 1) * (n - 2) / 2) % MOD;
            return (int) ways;
        }
        int target = totalOnes / 3;
        int onesSeen = 0;
        long zerosAfterFirst = 0;
        long zerosAfterSecond = 0;
        int i = 0;
        while (i < n) {
            if (s.charAt(i) == '1') onesSeen++;
            if (onesSeen == target) {
                i++;
                while (i < n && s.charAt(i) == '0') {
                    zerosAfterFirst++;
                    i++;
                }
                break;
            }
            i++;
        }
        while (i < n) {
            if (s.charAt(i) == '1') onesSeen++;
            if (onesSeen == 2 * target) {
                i++;
                while (i < n && s.charAt(i) == '0') {
                    zerosAfterSecond++;
                    i++;
                }
                break;
            }
            i++;
        }
        long ways = ((zerosAfterFirst + 1) * (zerosAfterSecond + 1)) % MOD;
        return (int) ways;
    }
}

public class Solution {
    public static int findLengthOfShortestSubarray(int[] arr) {
        int n = arr.length;
        if (n == 0) return 0;
        int left = 0;
        while (left + 1 < n && arr[left] <= arr[left + 1]) {
            left++;
        }
        if (left == n - 1) {
            return 0;
        }
        int right = n - 1;
        while (right > 0 && arr[right - 1] <= arr[right]) {
            right--;
        }
        int answer = Math.min(n - left - 1, right);
        int i = 0;
        int j = right;
        while (i <= left && j < n) {
            if (arr[i] <= arr[j]) {
                answer = Math.min(answer, j - i - 1);
                i++;
            } else {
                j++;
            }
        }
        return answer;
    }
}

