class Solution {
    public static int maxNumEdgesToRemove(int n, int[][] edges) {
        class DSU {
            int[] parent;
            byte[] rank;
            int components;
            DSU(int size) {
                parent = new int[size + 1];
                rank = new byte[size + 1];
                for (int i = 1; i <= size; i++) parent[i] = i;
                components = size;
            }
            int find(int x) {
                while (parent[x] != x) {
                    parent[x] = parent[parent[x]];
                    x = parent[x];
                }
                return x;
            }
            boolean union(int a, int b) {
                int ra = find(a);
                int rb = find(b);
                if (ra == rb) return false;
                if (rank[ra] < rank[rb]) {
                    int tmp = ra;
                    ra = rb;
                    rb = tmp;
                }
                parent[rb] = ra;
                if (rank[ra] == rank[rb]) rank[ra]++;
                components--;
                return true;
            }
        }

        DSU alice = new DSU(n);
        DSU bob = new DSU(n);
        int used = 0;

        for (int[] e : edges) {
            if (e[0] == 3) {
                boolean a = alice.union(e[1], e[2]);
                boolean b = bob.union(e[1], e[2]);
                if (a || b) used++;
            }
        }

        for (int[] e : edges) {
            int type = e[0];
            if (type == 1) {
                if (alice.union(e[1], e[2])) used++;
            } else if (type == 2) {
                if (bob.union(e[1], e[2])) used++;
            }
        }

        if (alice.components != 1 || bob.components != 1) return -1;
        return edges.length - used;
    }
}

