class Solution {
    public static long numTriplets(int[] nums1, int[] nums2) {
        Map<Integer, Integer> freq1 = new HashMap<>();
        Map<Integer, Integer> freq2 = new HashMap<>();
        for (int v : nums1) freq1.put(v, freq1.getOrDefault(v, 0) + 1);
        for (int v : nums2) freq2.put(v, freq2.getOrDefault(v, 0) + 1);
        long answer = 0L;
        for (Map.Entry<Integer, Integer> entry : freq1.entrySet()) {
            int val = entry.getKey();
            int cnt = entry.getValue();
            long target = (long) val * val;
            long pairCnt = countPairs(target, freq2);
            answer += (long) cnt * pairCnt;
        }
        for (Map.Entry<Integer, Integer> entry : freq2.entrySet()) {
            int val = entry.getKey();
            int cnt = entry.getValue();
            long target = (long) val * val;
            long pairCnt = countPairs(target, freq1);
            answer += (long) cnt * pairCnt;
        }
        return answer;
    }

    private static long countPairs(long target, Map<Integer, Integer> freq) {
        long pairs = 0L;
        for (long d = 1; d * d <= target; ++d) {
            if (target % d != 0) continue;
            long e = target / d;
            int fd = freq.getOrDefault((int) d, 0);
            int fe = freq.getOrDefault((int) e, 0);
            if (fd != 0 && fe != 0) {
                if (d == e) {
                    pairs += (long) fd * (fd - 1) / 2;
                } else {
                    pairs += (long) fd * fe;
                }
            }
        }
        return pairs;
    }
}

