class Solution {
    public static boolean isTransformable(String s, String t) {
        int n = s.length();
        int[][] pos = new int[10][n];
        int[] size = new int[10];
        for (int i = 0; i < n; i++) {
            int d = s.charAt(i) - '0';
            pos[d][size[d]++] = i;
        }
        int[] ptr = new int[10];
        for (int i = 0; i < n; i++) {
            int need = t.charAt(i) - '0';
            if (ptr[need] == size[need]) {
                return false;
            }
            int idx = pos[need][ptr[need]++];
            for (int d = 0; d < need; d++) {
                if (ptr[d] < size[d] && pos[d][ptr[d]] < idx) {
                    return false;
                }
            }
        }
        return true;
    }
}

