class Solution {
    public static int minSubarray(int[] nums, int p) {
        long total = 0;
        for (int i = 0; i < nums.length; i++) {
            total = (total + nums[i]) % p;
        }
        int target = (int) total;
        if (target == 0) return 0;
        long prefix = 0;
        int best = nums.length;
        Map<Integer, Integer> firstIdx = new HashMap<>();
        firstIdx.put(0, -1);
        for (int i = 0; i < nums.length; i++) {
            prefix = (prefix + nums[i]) % p;
            int need = (int) ((prefix - target + p) % p);
            if (firstIdx.containsKey(need)) {
                int len = i - firstIdx.get(need);
                if (len < best) best = len;
            }
            firstIdx.put((int) prefix, i);
        }
        return best == nums.length ? -1 : best;
    }
}

