class Solution {
    public static String rearrangeSpaces(String text) {
        int totalSpaces = 0;
        for (int i = 0; i < text.length(); i++) {
            if (text.charAt(i) == ' ') {
                totalSpaces++;
            }
        }
        String[] words = text.trim().split("\\s+");
        int wordCount = words.length;
        if (wordCount == 1) {
            return words[0] + " ".repeat(totalSpaces);
        }
        int gapSpaces = totalSpaces / (wordCount - 1);
        int extraSpaces = totalSpaces % (wordCount - 1);
        String between = " ".repeat(gapSpaces);
        return String.join(between, words) + " ".repeat(extraSpaces);
    }
}

