class Solution {
    public static int maxUniqueSplit(String s) {
        int n = s.length();
        int[] best = new int[1];
        Set<String> used = new HashSet<>();
        dfs(s, n, 0, 0, best, used);
        return best[0];
    }

    private static void dfs(String s, int n, int pos, int cnt, int[] best, Set<String> used) {
        if (pos == n) {
            if (cnt > best[0]) best[0] = cnt;
            return;
        }
        if (cnt + (n - pos) <= best[0]) return;
        for (int i = pos + 1; i <= n; i++) {
            String sub = s.substring(pos, i);
            if (!used.contains(sub)) {
                used.add(sub);
                dfs(s, n, i, cnt + 1, best, used);
                used.remove(sub);
            }
        }
    }
}

import java.util.ArrayDeque;
import java.util.Queue;

class Solution {
    public static boolean isPrintable(int[][] targetGrid) {
        int m = targetGrid.length;
        int n = targetGrid[0].length;
        final int MAX_COLOR = 60;
        int[] minRow = new int[MAX_COLOR + 1];
        int[] maxRow = new int[MAX_COLOR + 1];
        int[] minCol = new int[MAX_COLOR + 1];
        int[] maxCol = new int[MAX_COLOR + 1];
        boolean[] present = new boolean[MAX_COLOR + 1];
        for (int i = 0; i <= MAX_COLOR; i++) {
            minRow[i] = Integer.MAX_VALUE;
            maxRow[i] = -1;
            minCol[i] = Integer.MAX_VALUE;
            maxCol[i] = -1;
        }
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                int col = targetGrid[r][c];
                if (col == 0) continue;
                present[col] = true;
                if (r < minRow[col]) minRow[col] = r;
                if (r > maxRow[col]) maxRow[col] = r;
                if (c < minCol[col]) minCol[col] = c;
                if (c > maxCol[col]) maxCol[col] = c;
            }
        }
        boolean[][] adj = new boolean[MAX_COLOR + 1][MAX_COLOR + 1];
        int[] indegree = new int[MAX_COLOR + 1];
        int colorCount = 0;
        for (int col = 1; col <= MAX_COLOR; col++) {
            if (!present[col]) continue;
            colorCount++;
            for (int r = minRow[col]; r <= maxRow[col]; r++) {
                for (int c = minCol[col]; c <= maxCol[col]; c++) {
                    int inner = targetGrid[r][c];
                    if (inner != col && inner != 0 && !adj[col][inner]) {
                        adj[col][inner] = true;
                        indegree[inner]++;
                    }
                }
            }
        }
        Queue<Integer> queue = new ArrayDeque<>();
        for (int col = 1; col <= MAX_COLOR; col++) {
            if (present[col] && indegree[col] == 0) {
                queue.offer(col);
            }
        }
        int visited = 0;
        while (!queue.isEmpty()) {
            int cur = queue.poll();
            visited++;
            for (int nxt = 1; nxt <= MAX_COLOR; nxt++) {
                if (adj[cur][nxt]) {
                    indegree[nxt]--;
                    if (indegree[nxt] == 0) {
                        queue.offer(nxt);
                    }
                }
            }
        }
        return visited == colorCount;
    }
}

import java.math.BigInteger;

class Solution {
    public static int maxProductPath(int[][] grid) {
        final BigInteger MOD = BigInteger.valueOf(1_000_000_007L);
        int rows = grid.length;
        int cols = grid[0].length;
        BigInteger[] prevMax = new BigInteger[cols];
        BigInteger[] prevMin = new BigInteger[cols];
        BigInteger[] curMax = new BigInteger[cols];
        BigInteger[] curMin = new BigInteger[cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                BigInteger val = BigInteger.valueOf(grid[i][j]);
                if (i == 0 && j == 0) {
                    curMax[j] = val;
                    curMin[j] = val;
                } else {
                    BigInteger bestMax = null;
                    BigInteger bestMin = null;
                    if (i > 0) {
                        BigInteger a = prevMax[j].multiply(val);
                        BigInteger b = prevMin[j].multiply(val);
                        bestMax = max(bestMax, a, b);
                        bestMin = min(bestMin, a, b);
                    }
                    if (j > 0) {
                        BigInteger a = curMax[j - 1].multiply(val);
                        BigInteger b = curMin[j - 1].multiply(val);
                        bestMax = max(bestMax, a, b);
                        bestMin = min(bestMin, a, b);
                    }
                    curMax[j] = bestMax;
                    curMin[j] = bestMin;
                }
            }
            BigInteger[] tempMax = prevMax;
            prevMax = curMax;
            curMax = tempMax;
            BigInteger[] tempMin = prevMin;
            prevMin = curMin;
            curMin = tempMin;
        }
        BigInteger finalMax = prevMax[cols - 1];
        if (finalMax.compareTo(BigInteger.ZERO) < 0) {
            return -1;
        }
        return finalMax.mod(MOD).intValue();
    }

    private static BigInteger max(BigInteger current, BigInteger... candidates) {
        for (BigInteger cand : candidates) {
            if (cand != null && (current == null || cand.compareTo(current) > 0)) {
                current = cand;
            }
        }
        return current;
    }

    private static BigInteger min(BigInteger current, BigInteger... candidates) {
        for (BigInteger cand : candidates) {
            if (cand != null && (current == null || cand.compareTo(current) < 0)) {
                current = cand;
            }
        }
        return current;
    }
}

