class Solution {
    public static int maxSumRangeQuery(int[] nums, int[][] requests) {
        final int MOD = 1_000_000_007;
        int n = nums.length;
        int[] diff = new int[n + 1];
        for (int i = 0; i < requests.length; i++) {
            int l = requests[i][0];
            int r = requests[i][1];
            diff[l] += 1;
            if (r + 1 < n) diff[r + 1] -= 1;
        }
        int[] freq = new int[n];
        int cur = 0;
        for (int i = 0; i < n; i++) {
            cur += diff[i];
            freq[i] = cur;
        }
        Arrays.sort(nums);
        Arrays.sort(freq);
        long ans = 0;
        for (int i = 0; i < n; i++) {
            ans = (ans + ((long) nums[i] * freq[i]) % MOD) % MOD;
        }
        return (int) ans;
    }
}

import java.util.*;

class Solution {
    public static int minCostConnectTwoGroups(int[][] cost) {
        int m = cost.length;
        int n = cost[0].length;
        int size = 1 << n;
        int INF = Integer.MAX_VALUE / 4;
        int[] dp = new int[size];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int i = 0; i < m; i++) {
            int[] ndp = new int[size];
            Arrays.fill(ndp, INF);
            for (int mask = 0; mask < size; mask++) {
                if (dp[mask] == INF) continue;
                for (int j = 0; j < n; j++) {
                    int newMask = mask | (1 << j);
                    int newCost = dp[mask] + cost[i][j];
                    if (newCost < ndp[newMask]) {
                        ndp[newMask] = newCost;
                    }
                }
            }
            dp = ndp;
        }
        int[] minCol = new int[n];
        Arrays.fill(minCol, INF);
        for (int j = 0; j < n; j++) {
            for (int i = 0; i < m; i++) {
                minCol[j] = Math.min(minCol[j], cost[i][j]);
            }
        }
        int ans = INF;
        for (int mask = 0; mask < size; mask++) {
            if (dp[mask] == INF) continue;
            int extra = 0;
            for (int j = 0; j < n; j++) {
                if ((mask & (1 << j)) == 0) {
                    extra += minCol[j];
                }
            }
            ans = Math.min(ans, dp[mask] + extra);
        }
        return ans;
    }
}

