class Solution {
    public static int maximumRequests(int n, int[][] requests) {
        int m = requests.length;
        int[] balance = new int[n];
        int[] best = new int[1];
        dfs(0, 0, n, m, requests, balance, best);
        return best[0];
    }

    private static void dfs(int idx, int cnt, int n, int m, int[][] requests, int[] balance, int[] best) {
        if (cnt + (m - idx) <= best[0]) return;
        if (idx == m) {
            for (int i = 0; i < n; i++) {
                if (balance[i] != 0) return;
            }
            if (cnt > best[0]) best[0] = cnt;
            return;
        }
        dfs(idx + 1, cnt, n, m, requests, balance, best);
        int from = requests[idx][0];
        int to = requests[idx][1];
        balance[from]--;
        balance[to]++;
        dfs(idx + 1, cnt + 1, n, m, requests, balance, best);
        balance[from]++;
        balance[to]--;
    }
}

