class Solution {
    public static int maxProfitRotation(int[] customers, int boardingCost, int runningCost) {
        long waiting = 0;
        int i = 0;
        long rotations = 0;
        long served = 0;
        long profit = 0;
        long maxProfit = 0;
        int bestRot = -1;
        while (i < customers.length || waiting > 0) {
            if (i < customers.length) waiting += customers[i++];
            long board = Math.min(waiting, 4L);
            waiting -= board;
            served += board;
            rotations++;
            profit = served * boardingCost - rotations * runningCost;
            if (profit > maxProfit) {
                maxProfit = profit;
                bestRot = (int) rotations;
            }
        }
        return maxProfit > 0 ? bestRot : -1;
    }
}

