class Solution {
    public static List<Integer> busiestServers(int k, int[] arrival, int[] load) {
        int n = arrival.length;
        int[] count = new int[k];
        TreeSet<Integer> free = new TreeSet<>();
        for (int i = 0; i < k; i++) {
            free.add(i);
        }
        PriorityQueue<long[]> busy = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
        for (int i = 0; i < n; i++) {
            long curTime = arrival[i];
            while (!busy.isEmpty() && busy.peek()[0] <= curTime) {
                long[] finished = busy.poll();
                free.add((int) finished[1]);
            }
            if (free.isEmpty()) {
                continue;
            }
            int target = i % k;
            Integer server = free.ceiling(target);
            if (server == null) {
                server = free.first();
            }
            free.remove(server);
            count[server]++;
            busy.offer(new long[]{curTime + load[i], server});
        }
        int max = 0;
        for (int c : count) {
            if (c > max) {
                max = c;
            }
        }
        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            if (count[i] == max) {
                result.add(i);
            }
        }
        return result;
    }
}

