class Solution {
    public static int[][] restoreMatrix(int[] rowSum, int[] colSum) {
        int m = rowSum.length;
        int n = colSum.length;
        int[] rows = rowSum.clone();
        int[] cols = colSum.clone();
        int[][] matrix = new int[m][n];
        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> {
            if (cols[a] != cols[b]) return Integer.compare(cols[a], cols[b]);
            return Integer.compare(a, b);
        });
        for (int j = 0; j < n; j++) {
            if (cols[j] > 0) pq.offer(j);
        }
        for (int i = 0; i < m; i++) {
            int remaining = rows[i];
            while (remaining > 0) {
                int colIdx = pq.poll();
                int take = Math.min(remaining, cols[colIdx]);
                matrix[i][colIdx] = take;
                remaining -= take;
                cols[colIdx] -= take;
                if (cols[colIdx] > 0) pq.offer(colIdx);
            }
        }
        return matrix;
    }
}

