class Solution {
    public static int visiblePoints(int[][] points, int angle, int[] location) {
        int locX = location[0];
        int locY = location[1];
        int samePlace = 0;
        List<Double> angles = new ArrayList<>();
        for (int[] p : points) {
            int x = p[0];
            int y = p[1];
            int dx = x - locX;
            int dy = y - locY;
            if (dx == 0 && dy == 0) {
                samePlace++;
                continue;
            }
            double deg = Math.toDegrees(Math.atan2(dy, dx));
            if (deg < 0) deg += 360.0;
            angles.add(deg);
        }
        if (angles.isEmpty()) return samePlace;
        if (angle >= 360) return points.length;
        Collections.sort(angles);
        int n = angles.size();
        double[] extended = new double[n * 2];
        for (int i = 0; i < n; i++) {
            extended[i] = angles.get(i);
            extended[i + n] = angles.get(i) + 360.0;
        }
        int maxInWindow = 0;
        int left = 0;
        double viewAngle = angle;
        double eps = 1e-9;
        for (int right = 0; right < extended.length; right++) {
            while (extended[right] - extended[left] > viewAngle + eps) {
                left++;
            }
            int windowSize = right - left + 1;
            if (windowSize > maxInWindow) maxInWindow = windowSize;
        }
        return maxInWindow + samePlace;
    }
}

