class Solution {
    public static int[] countSubgraphsForEachDiameter(int n, int[][] edges) {
        int[] adjMask = new int[n];
        for (int[] e : edges) {
            int u = e[0] - 1;
            int v = e[1] - 1;
            adjMask[u] |= 1 << v;
            adjMask[v] |= 1 << u;
        }
        int[] ans = new int[n - 1];
        int total = 1 << n;
        int[] dist = new int[n];
        int[] queue = new int[n];
        for (int mask = 1; mask < total; mask++) {
            int size = Integer.bitCount(mask);
            if (size == 1) continue;
            int start = Integer.numberOfTrailingZeros(mask);
            Arrays.fill(dist, -1);
            int head = 0, tail = 0;
            dist[start] = 0;
            queue[tail++] = start;
            int visited = 0;
            int far = start;
            while (head < tail) {
                int u = queue[head++];
                visited++;
                if (dist[u] > dist[far]) far = u;
                int neighbors = adjMask[u] & mask;
                while (neighbors != 0) {
                    int v = Integer.numberOfTrailingZeros(neighbors);
                    neighbors &= ~(1 << v);
                    if (dist[v] == -1) {
                        dist[v] = dist[u] + 1;
                        queue[tail++] = v;
                    }
                }
            }
            if (visited != size) continue;
            Arrays.fill(dist, -1);
            head = 0;
            tail = 0;
            dist[far] = 0;
            queue[tail++] = far;
            int maxDist = 0;
            while (head < tail) {
                int u = queue[head++];
                maxDist = Math.max(maxDist, dist[u]);
                int neighbors = adjMask[u] & mask;
                while (neighbors != 0) {
                    int v = Integer.numberOfTrailingZeros(neighbors);
                    neighbors &= ~(1 << v);
                    if (dist[v] == -1) {
                        dist[v] = dist[u] + 1;
                        queue[tail++] = v;
                    }
                }
            }
            ans[maxDist - 1]++;
        }
        return ans;
    }
}

