class Solution {
    public static int maximalNetworkRank(int n, int[][] roads) {
        int[] degree = new int[n];
        List<Set<Integer>> adjacency = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adjacency.add(new HashSet<>());
        }
        for (int[] road : roads) {
            int a = road[0];
            int b = road[1];
            degree[a]++;
            degree[b]++;
            adjacency.get(a).add(b);
            adjacency.get(b).add(a);
        }
        int best = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int rank = degree[i] + degree[j] - (adjacency.get(i).contains(j) ? 1 : 0);
                if (rank > best) {
                    best = rank;
                }
            }
        }
        return best;
    }
}

