class Solution {
    public static int[] coordinateWithMaxNetworkQuality(int[][] towers, int radius) {
        int minX = Integer.MAX_VALUE, maxX = Integer.MIN_VALUE;
        int minY = Integer.MAX_VALUE, maxY = Integer.MIN_VALUE;
        for (int i = 0; i < towers.length; i++) {
            int x = towers[i][0];
            int y = towers[i][1];
            if (x < minX) minX = x;
            if (x > maxX) maxX = x;
            if (y < minY) minY = y;
            if (y > maxY) maxY = y;
        }

        int bestQuality = -1, bestX = 0, bestY = 0;

        for (int x = minX - radius; x <= maxX + radius; x++) {
            for (int y = minY - radius; y <= maxY + radius; y++) {
                int total = 0;
                for (int i = 0; i < towers.length; i++) {
                    int tx = towers[i][0];
                    int ty = towers[i][1];
                    int q = towers[i][2];
                    int dx = x - tx;
                    int dy = y - ty;
                    double dist = Math.sqrt(dx * dx + dy * dy);
                    if (dist <= radius) {
                        total += (int) Math.floor(q / (1 + dist));
                    }
                }
                if (total > bestQuality || (total == bestQuality && (x < bestX || (x == bestX && y < bestY)))) {
                    bestQuality = total;
                    bestX = x;
                    bestY = y;
                }
            }
        }
        return new int[]{bestX, bestY};
    }
}

