public class Solution {
    private static final int MOD = 1_000_000_007;
    public static int numberOfSets(int n, int k) {
        if (k == 0) return 1;
        long[] dpPrev = new long[k + 1];
        long[] prefPrev = new long[k + 1];
        long[] dpCurr = new long[k + 1];
        long[] prefCurr = new long[k + 1];
        dpPrev[0] = 1;
        prefPrev[0] = 1;
        for (int i = 1; i < n; i++) {
            dpCurr[0] = 1;
            prefCurr[0] = (prefPrev[0] + 1) % MOD;
            for (int j = 1; j <= k; j++) {
                dpCurr[j] = (dpPrev[j] + prefPrev[j - 1]) % MOD;
                prefCurr[j] = (prefPrev[j] + dpCurr[j]) % MOD;
            }
            long[] temp = dpPrev;
            dpPrev = dpCurr;
            dpCurr = temp;
            temp = prefPrev;
            prefPrev = prefCurr;
            prefCurr = temp;
        }
        return (int) dpPrev[k];
    }
}

