class Solution {
    static class Player {
        int age;
        int score;
        Player(int age, int score) {
            this.age = age;
            this.score = score;
        }
    }

    public static int bestTeamScore(int[] scores, int[] ages) {
        int n = scores.length;
        Player[] players = new Player[n];
        for (int i = 0; i < n; i++) {
            players[i] = new Player(ages[i], scores[i]);
        }
        Arrays.sort(players, (a, b) -> {
            if (a.age != b.age) return a.age - b.age;
            return a.score - b.score;
        });
        int[] allScores = new int[n];
        for (int i = 0; i < n; i++) {
            allScores[i] = players[i].score;
        }
        int[] sorted = allScores.clone();
        Arrays.sort(sorted);
        int[] uniq = new int[n];
        int uniqCount = 0;
        for (int v : sorted) {
            if (uniqCount == 0 || v != uniq[uniqCount - 1]) {
                uniq[uniqCount++] = v;
            }
        }
        int[] bit = new int[uniqCount + 2];
        int best = 0;
        for (Player p : players) {
            int idx = Arrays.binarySearch(uniq, 0, uniqCount, p.score) + 1;
            int cur = query(bit, idx) + p.score;
            update(bit, idx, cur);
            if (cur > best) best = cur;
        }
        return best;
    }

    private static void update(int[] bit, int idx, int val) {
        for (int i = idx; i < bit.length; i += i & -i) {
            if (val > bit[i]) bit[i] = val;
        }
    }

    private static int query(int[] bit, int idx) {
        int res = 0;
        for (int i = idx; i > 0; i -= i & -i) {
            if (bit[i] > res) res = bit[i];
        }
        return res;
    }
}

import java.util.ArrayList;
class Fancy {
    private static final long MOD = 1_000_000_007L;
    private final ArrayList<Long> vals = new ArrayList<>();
    private final ArrayList<Long> mulAt = new ArrayList<>();
    private final ArrayList<Long> addAt = new ArrayList<>();
    private long curMul = 1L, curAdd = 0L;
    private long modPow(long base, long exp) {
        long result = 1L; base %= MOD;
        while (exp > 0) { if ((exp&1L)==1L) result = result*base%MOD; base = base*base%MOD; exp >>= 1; }
        return result;
    }
    public void append(int val) { vals.add((long) val % MOD); mulAt.add(curMul); addAt.add(curAdd); }
    public void addAll(int inc) { curAdd = (curAdd + inc) % MOD; }
    public void multAll(int m) { curMul = curMul*m%MOD; curAdd = curAdd*m%MOD; }
    public int getIndex(int idx) {
        if (idx < 0 || idx >= vals.size()) return -1;
        long inv = modPow(mulAt.get(idx), MOD-2);
        long factor = curMul*inv%MOD;
        long addPart = ((curAdd - addAt.get(idx)*factor%MOD) % MOD + MOD) % MOD;
        return (int) ((vals.get(idx)*factor%MOD + addPart) % MOD);
    }
}

public class Solution {
