public class Solution {
    public static int minimumEffortPath(int[][] heights) {
        int rows = heights.length;
        int cols = heights[0].length;
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        int INF = Integer.MAX_VALUE;
        int[][] distance = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            Arrays.fill(distance[i], INF);
        }
        distance[0][0] = 0;
        PriorityQueue<int[]> heap = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        heap.offer(new int[]{0, 0, 0});
        while (!heap.isEmpty()) {
            int[] cur = heap.poll();
            int curEffort = cur[0];
            int r = cur[1];
            int c = cur[2];
            if (r == rows - 1 && c == cols - 1) {
                return curEffort;
            }
            if (curEffort != distance[r][c]) {
                continue;
            }
            for (int[] d : dirs) {
                int nr = r + d[0];
                int nc = c + d[1];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                    continue;
                }
                int edge = Math.abs(heights[nr][nc] - heights[r][c]);
                int newEffort = Math.max(curEffort, edge);
                if (newEffort < distance[nr][nc]) {
                    distance[nr][nc] = newEffort;
                    heap.offer(new int[]{newEffort, nr, nc});
                }
            }
        }
        return -1;
    }
}

import java.util.*;

class Solution {
    public static boolean[] areConnected(int n, int threshold, int[][] queries) {
        int[] parent = new int[n + 1];
        byte[] rank = new byte[n + 1];
        for (int i = 1; i <= n; ++i) parent[i] = i;

        java.util.function.IntUnaryOperator find = new java.util.function.IntUnaryOperator() {
            public int applyAsInt(int x) {
                while (parent[x] != x) {
                    parent[x] = parent[parent[x]];
                    x = parent[x];
                }
                return x;
            }
        };

        java.util.function.BiConsumer<Integer, Integer> union = (a, b) -> {
            int ra = find.applyAsInt(a);
            int rb = find.applyAsInt(b);
            if (ra == rb) return;
            if (rank[ra] < rank[rb]) {
                int tmp = ra;
                ra = rb;
                rb = tmp;
            }
            parent[rb] = ra;
            if (rank[ra] == rank[rb]) rank[ra]++;
        };

        for (int d = threshold + 1; d <= n; ++d) {
            for (int multiple = d * 2; multiple <= n; multiple += d) {
                union.accept(d, multiple);
            }
        }

        boolean[] ans = new boolean[queries.length];
        for (int i = 0; i < queries.length; ++i) {
            int a = queries[i][0];
            int b = queries[i][1];
            ans[i] = find.applyAsInt(a) == find.applyAsInt(b);
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    public static String findLexSmallestString(String s, int a, int b) {
        Set<String> visited = new HashSet<>();
        Deque<String> queue = new ArrayDeque<>();
        visited.add(s);
        queue.offer(s);
        String best = s;
        while (!queue.isEmpty()) {
            String cur = queue.poll();
            if (cur.compareTo(best) < 0) {
                best = cur;
            }
            String added = addOdd(cur, a);
            if (visited.add(added)) {
                queue.offer(added);
            }
            String rotated = rotateRight(cur, b);
            if (visited.add(rotated)) {
                queue.offer(rotated);
            }
        }
        return best;
    }

    private static String addOdd(String s, int a) {
        char[] ch = s.toCharArray();
        for (int i = 1; i < ch.length; i += 2) {
            int d = ch[i] - '0';
            d = (d + a) % 10;
            ch[i] = (char) ('0' + d);
        }
        return new String(ch);
    }

    private static String rotateRight(String s, int b) {
        int n = s.length();
        b %= n;
        if (b == 0) return s;
        return s.substring(n - b) + s.substring(0, n - b);
    }
}

import java.util.*;

public class Solution {
    public static List<Boolean> checkArithmeticSubarrays(int[] nums, int[] l, int[] r) {
        int m = l.length;
        boolean[] answer = new boolean[m];
        for (int i = 0; i < m; i++) {
            int start = l[i];
            int end = r[i];
            int len = end - start + 1;
            if (len <= 2) {
                answer[i] = true;
                continue;
            }
            int min = nums[start];
            int max = nums[start];
            for (int j = start + 1; j <= end; j++) {
                int v = nums[j];
                if (v < min) min = v;
                if (v > max) max = v;
            }
            long range = (long) max - (long) min;
            if (range % (len - 1) != 0) {
                answer[i] = false;
                continue;
            }
            long diffLong = range / (len - 1);
            if (diffLong == 0) {
                answer[i] = true;
                continue;
            }
            int diff = (int) diffLong;
            boolean[] seen = new boolean[len];
            boolean ok = true;
            for (int j = start; j <= end && ok; j++) {
                int v = nums[j];
                long offset = (long) v - (long) min;
                if (offset % diff != 0) {
                    ok = false;
                    break;
                }
                int idx = (int) (offset / diff);
                if (idx < 0 || idx >= len || seen[idx]) {
                    ok = false;
                    break;
                }
                seen[idx] = true;
            }
            answer[i] = ok;
        }
        List<Boolean> result = new ArrayList<>(m);
        for (boolean b : answer) {
            result.add(b);
        }
        return result;
    }
}

import java.util.*;

public class Solution {
    private static class Cell {
        int val;
        int row;
        int col;
        Cell(int v, int r, int c) {
            this.val = v;
            this.row = r;
            this.col = c;
        }
    }

    public static int[][] matrixRankTransform(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;
        int total = m * n;
        Cell[] cells = new Cell[total];
        int idx = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                cells[idx++] = new Cell(matrix[i][j], i, j);
            }
        }
        Arrays.sort(cells, new Comparator<Cell>() {
            @Override
            public int compare(Cell c1, Cell c2) {
                return Integer.compare(c1.val, c2.val);
            }
        });
        int[][] ans = new int[m][n];
        int[] rank = new int[m + n];
        int[] parent = new int[m + n];
        int[] seen = new int[m + n];
        int stamp = 1;
        int i = 0;
        while (i < total) {
            int j = i;
            while (j < total && cells[j].val == cells[i].val) j++;
            stamp++;
            for (int k = i; k < j; k++) {
                Cell cell = cells[k];
                union(cell.row, m + cell.col, parent, seen, stamp);
            }
            Map<Integer, Integer> compMax = new HashMap<>();
            for (int k = i; k < j; k++) {
                Cell cell = cells[k];
                int root = find(cell.row, parent, seen, stamp);
                int curMax = Math.max(rank[cell.row], rank[m + cell.col]);
                compMax.put(root, Math.max(compMax.getOrDefault(root, 0), curMax));
            }
            for (int k = i; k < j; k++) {
                Cell cell = cells[k];
                int root = find(cell.row, parent, seen, stamp);
                int newRank = compMax.get(root) + 1;
                ans[cell.row][cell.col] = newRank;
                rank[cell.row] = newRank;
                rank[m + cell.col] = newRank;
            }
            i = j;
        }
        return ans;
    }

    private static int find(int x, int[] parent, int[] seen, int stamp) {
        if (seen[x] != stamp) {
            seen[x] = stamp;
            parent[x] = x;
            return x;
        }
        int root = x;
        while (parent[root] != root) {
            root = parent[root];
        }
        while (x != root) {
            int next = parent[x];
            parent[x] = root;
            x = next;
        }
        return root;
    }

    private static void union(int a, int b, int[] parent, int[] seen, int stamp) {
        int ra = find(a, parent, seen, stamp);
        int rb = find(b, parent, seen, stamp);
        if (ra != rb) {
            parent[ra] = rb;
        }
    }
}

