class Solution {
    public static int numWays(String[] words, String target) {
        final long MOD = 1_000_000_007L;
        int n = words.length;
        int m = words[0].length();
        int tLen = target.length();

        int[][] count = new int[26][m];
        for (int w = 0; w < n; ++w) {
            String word = words[w];
            for (int c = 0; c < m; ++c) {
                int idx = word.charAt(c) - 'a';
                ++count[idx][c];
            }
        }

        long[] dp = new long[tLen + 1];
        dp[0] = 1;

        for (int col = 0; col < m; ++col) {
            int maxI = Math.min(tLen - 1, col);
            for (int i = maxI; i >= 0; --i) {
                int chIdx = target.charAt(i) - 'a';
                int ways = count[chIdx][col];
                if (ways != 0) {
                    dp[i + 1] = (dp[i + 1] + dp[i] * ways) % MOD;
                }
            }
        }
        return (int) dp[tLen];
    }
}

