class Solution {
    public static long countSubstrings(String s, String t) {
        int n = s.length();
        int m = t.length();
        int[][] pre = new int[n + 1][m + 1];
        int[][] post = new int[n + 1][m + 1];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (s.charAt(i) == t.charAt(j)) {
                    pre[i + 1][j + 1] = pre[i][j] + 1;
                }
            }
        }

        for (int i = n - 1; i >= 0; i--) {
            for (int j = m - 1; j >= 0; j--) {
                if (s.charAt(i) == t.charAt(j)) {
                    post[i][j] = post[i + 1][j + 1] + 1;
                }
            }
        }

        long ans = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (s.charAt(i) != t.charAt(j)) {
                    ans += (long) (pre[i][j] + 1) * (post[i + 1][j + 1] + 1);
                }
            }
        }
        return ans;
    }
}

import java.math.BigInteger;

class Solution {
    public static String kthSmallestInstruction(int[] destination, long k) {
        int row = destination[0];
        int col = destination[1];
        int v = row;
        int h = col;
        BigInteger kk = BigInteger.valueOf(k);
        StringBuilder result = new StringBuilder();

        while (v > 0 || h > 0) {
            BigInteger countH = h > 0 ? nCr(v + h - 1, v) : BigInteger.ZERO;
            if (h > 0 && kk.compareTo(countH) <= 0) {
                result.append('H');
                h--;
            } else {
                if (h > 0) {
                    kk = kk.subtract(countH);
                }
                result.append('V');
                v--;
            }
        }
        return result.toString();
    }

    private static BigInteger nCr(int n, int r) {
        if (r < 0 || r > n) return BigInteger.ZERO;
        if (r > n - r) r = n - r;
        BigInteger res = BigInteger.ONE;
        for (int i = 1; i <= r; i++) {
            res = res.multiply(BigInteger.valueOf(n - r + i)).divide(BigInteger.valueOf(i));
        }
        return res;
    }
}

