class Solution {
    public static int getMaximumGenerated(int n) {
        if (n == 0) return 0;
        int[] nums = new int[n + 1];
        nums[0] = 0;
        nums[1] = 1;
        int maxVal = 1;
        for (int i = 2; i <= n; i++) {
            if ((i & 1) == 0) {
                nums[i] = nums[i >> 1];
            } else {
                int k = i >> 1;
                nums[i] = nums[k] + nums[k + 1];
            }
            if (nums[i] > maxVal) maxVal = nums[i];
        }
        return maxVal;
    }
}

