class Solution {
    public static int createSortedArray(int[] instructions) {
        final int MOD = 1_000_000_007;
        int n = instructions.length;
        if (n == 0) return 0;
        int maxVal = 0;
        for (int v : instructions) {
            if (v > maxVal) maxVal = v;
        }
        int[] bit = new int[maxVal + 2];

        java.util.function.BiConsumer<Integer, Integer> add = (idx, delta) -> {
            for (int i = idx + 1; i < bit.length; i += i & -i) {
                bit[i] += delta;
            }
        };

        java.util.function.Function<Integer, Long> sum = (idx) -> {
            long res = 0;
            for (int i = idx + 1; i > 0; i -= i & -i) {
                res += bit[i];
            }
            return res;
        };

        long total = 0;
        for (int i = 0; i < n; i++) {
            int x = instructions[i];
            long less = sum.apply(x - 1);
            long lessOrEqual = sum.apply(x);
            long greater = i - lessOrEqual;
            total = (total + Math.min(less, greater)) % MOD;
            add.accept(x, 1);
        }
        return (int) total;
    }
}

import java.util.Arrays;
import java.math.BigInteger;

class Solution {
    public static int maxProfit(int[] inventory, int orders) {
        final BigInteger MOD = BigInteger.valueOf(1_000_000_007L);
        Arrays.sort(inventory);
        int n = inventory.length;
        BigInteger profit = BigInteger.ZERO;
        BigInteger remaining = BigInteger.valueOf(orders);
        for (int i = n - 1; i >= 0; i--) {
            BigInteger cur = BigInteger.valueOf(inventory[i]);
            BigInteger next = (i > 0) ? BigInteger.valueOf(inventory[i - 1]) : BigInteger.ZERO;
            BigInteger diff = cur.subtract(next);
            BigInteger cnt = BigInteger.valueOf(n - i);
            BigInteger balls = diff.multiply(cnt);
            if (remaining.compareTo(balls) >= 0) {
                BigInteger levelSum = (cur.add(next).add(BigInteger.ONE)).multiply(diff).divide(BigInteger.valueOf(2));
                profit = profit.add(levelSum.multiply(cnt));
                remaining = remaining.subtract(balls);
            } else {
                BigInteger fullRounds = remaining.divide(cnt);
                BigInteger remainder = remaining.remainder(cnt);
                BigInteger low = cur.subtract(fullRounds);
                BigInteger sumFull = (cur.add(low).add(BigInteger.ONE)).multiply(fullRounds).divide(BigInteger.valueOf(2));
                profit = profit.add(sumFull.multiply(cnt));
                profit = profit.add(remainder.multiply(low));
                remaining = BigInteger.ZERO;
                break;
            }
        }
        return profit.mod(MOD).intValue();
    }
}

import java.util.*;

class Solution {
    public static boolean canDistribute(int[] nums, int[] quantity) {
        Map<Integer, Integer> freqMap = new HashMap<>();
        for (int v : nums) {
            freqMap.put(v, freqMap.getOrDefault(v, 0) + 1);
        }
        int[] counts = new int[freqMap.size()];
        int idx = 0;
        for (int val : freqMap.values()) {
            counts[idx++] = val;
        }

        int m = quantity.length;
        int fullMask = (1 << m) - 1;

        int[] need = new int[1 << m];
        for (int mask = 1; mask <= fullMask; ++mask) {
            int lsb = mask & -mask;
            int bitIdx = Integer.numberOfTrailingZeros(lsb);
            need[mask] = need[mask ^ lsb] + quantity[bitIdx];
        }

        boolean[] dp = new boolean[1 << m];
        dp[0] = true;

        for (int c : counts) {
            boolean[] next = dp.clone();
            for (int mask = 0; mask <= fullMask; ++mask) {
                if (!dp[mask]) continue;
                int remaining = fullMask ^ mask;
                for (int sub = remaining; sub != 0; sub = (sub - 1) & remaining) {
                    if (need[sub] <= c) {
                        next[mask | sub] = true;
                    }
                }
            }
            dp = next;
        }

        return dp[fullMask];
    }
}

import java.util.*;

class Solution {
    public static int[] decrypt(int[] code, int k) {
        int n = code.length;
        int[] result = new int[n];
        if (k == 0) {
            return result;
        }
        if (k > 0) {
            int windowSum = 0;
            for (int i = 1; i <= k; i++) {
                windowSum += code[i % n];
            }
            for (int i = 0; i < n; i++) {
                result[i] = windowSum;
                windowSum -= code[(i + 1) % n];
                windowSum += code[(i + k + 1) % n];
            }
        } else {
            int m = -k;
            int windowSum = 0;
            for (int i = 0; i < m; i++) {
                windowSum += code[(n - 1 - i + n) % n];
            }
            for (int i = 0; i < n; i++) {
                result[i] = windowSum;
                windowSum -= code[(i - m + n) % n];
                windowSum += code[i];
            }
        }
        return result;
    }
}

