class Solution {
    public static int minimumJumps(int[] forbidden, int a, int b, int x) {
        Set<Integer> forbiddenSet = new HashSet<>();
        for (int v : forbidden) {
            forbiddenSet.add(v);
        }
        int maxForbidden = 0;
        for (int v : forbidden) {
            if (v > maxForbidden) maxForbidden = v;
        }
        int limit = Math.max(maxForbidden, x) + a + b;
        Deque<int[]> queue = new ArrayDeque<>();
        Set<String> visited = new HashSet<>();
        queue.offer(new int[]{0, 0, 0}); // position, steps, lastBack (0 false, 1 true)
        visited.add("0,0");
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int pos = cur[0];
            int steps = cur[1];
            int lastBack = cur[2];
            if (pos == x) return steps;
            int forward = pos + a;
            String fKey = forward + ",0";
            if (forward <= limit && !forbiddenSet.contains(forward) && !visited.contains(fKey)) {
                visited.add(fKey);
                queue.offer(new int[]{forward, steps + 1, 0});
            }
            if (lastBack == 0) {
                int backward = pos - b;
                String bKey = backward + ",1";
                if (backward >= 0 && !forbiddenSet.contains(backward) && !visited.contains(bKey)) {
                    visited.add(bKey);
                    queue.offer(new int[]{backward, steps + 1, 1});
                }
            }
        }
        return -1;
    }
}

