public class Solution {
    public static int waysToMakeFair(int[] nums) {
        long totalEven = 0, totalOdd = 0;
        for (int i = 0; i < nums.length; i++) {
            if ((i & 1) == 0) totalEven += nums[i];
            else totalOdd += nums[i];
        }
        long leftEven = 0, leftOdd = 0;
        int answer = 0;
        for (int i = 0; i < nums.length; i++) {
            long rightEven = totalEven - leftEven - ((i & 1) == 0 ? nums[i] : 0);
            long rightOdd = totalOdd - leftOdd - ((i & 1) == 1 ? nums[i] : 0);
            if (leftEven + rightOdd == leftOdd + rightEven) answer++;
            if ((i & 1) == 0) leftEven += nums[i];
            else leftOdd += nums[i];
        }
        return answer;
    }
}

