        int[] base = {0, 120, 40};
        int[][] adjDelta = new int[3][3];
        adjDelta[1][1] = -60;
        adjDelta[1][2] = -10;
        adjDelta[2][1] = -10;
        adjDelta[2][2] = 40;
        int[] pow3 = new int[n];
        pow3[0] = 1;
        for (int i = 1; i < n; i++) pow3[i] = pow3[i - 1] * 3;
        int maxMask = pow3[n - 1] * 3;
        Map<Long, Integer> memo = new HashMap<>();
        return dfs(0, introvertsCount, extrovertsCount, 0, 0, m, n, totalCells, base, adjDelta, pow3, maxMask, memo);
    }

    private static int dfs(int pos, int introLeft, int extroLeft, int mask, int left,
                           int m, int n, int totalCells, int[] base, int[][] adjDelta,
                           int[] pow3, int maxMask, Map<Long, Integer> memo) {
        if (pos == totalCells) return 0;
        long key = (((((long) pos * (introLeft + 1) + introLeft) * (extroLeft + 1) + extroLeft) * maxMask) + mask) << 2 | left;
        Integer cached = memo.get(key);
        if (cached != null) return cached;
        int row = pos / n;
        int col = pos % n;
        int up = (mask / pow3[col]) % 3;
        int best = dfs(pos + 1, introLeft, extroLeft, mask, 0, m, n, totalCells, base, adjDelta, pow3, maxMask, memo);
        if (introLeft > 0) {
            int add = base[1];
            if (left != 0) add += adjDelta[1][left];
            if (up != 0) add += adjDelta[1][up];
            int newMask = mask + (1 - up) * pow3[col];
            int nextLeft = (col == n - 1) ? 0 : 1;
            int val = add + dfs(pos + 1, introLeft - 1, extroLeft, newMask, nextLeft, m, n, totalCells, base, adjDelta, pow3, maxMask, memo);
            if (val > best) best = val;
        }
        if (extroLeft > 0) {
            int add = base[2];
            if (left != 0) add += adjDelta[2][left];
            if (up != 0) add += adjDelta[2][up];
            int newMask = mask + (2 - up) * pow3[col];
            int nextLeft = (col == n - 1) ? 0 : 2;
            int val = add + dfs(pos + 1, introLeft, extroLeft - 1, newMask, nextLeft, m, n, totalCells, base, adjDelta, pow3, maxMask, memo);
            if (val > best) best = val;
        }
        memo.put(key, best);
        return best;
    }
}

