class Solution {
    public static int maxRepeating(String sequence, String word) {
        int n = sequence.length();
        int m = word.length();
        if (m == 0 || n < m) return 0;
        char[] s = sequence.toCharArray();
        char[] w = word.toCharArray();
        int[] dp = new int[n];
        int max = 0;
        for (int i = 0; i <= n - m; i++) {
            boolean match = true;
            for (int j = 0; j < m; j++) {
                if (s[i + j] != w[j]) {
                    match = false;
                    break;
                }
            }
            if (match) {
                dp[i] = (i >= m ? dp[i - m] + 1 : 1);
                if (dp[i] > max) {
                    max = dp[i];
                }
            }
        }
        return max;
    }
}

