class Solution {
    public static int minEnergy(int[][] tasks) {
        Arrays.sort(tasks, (a, b) -> (b[1] - b[0]) - (a[1] - a[0]));
        long cumulativeActual = 0;
        long required = 0;
        for (int[] task : tasks) {
            int actual = task[0];
            int minimum = task[1];
            required = Math.max(required, minimum + cumulativeActual);
            cumulativeActual += actual;
        }
        return (int) required;
    }
}

