class Solution {
    public static int minimumMountainRemovals(int[] nums) {
        int n = nums.length;
        int[] inc = new int[n];
        int[] dec = new int[n];
        int[] tails = new int[n];
        int size = 0;
        for (int i = 0; i < n; i++) {
            int x = nums[i];
            int l = 0, r = size;
            while (l < r) {
                int m = (l + r) >>> 1;
                if (tails[m] < x) {
                    l = m + 1;
                } else {
                    r = m;
                }
            }
            int pos = l;
            if (pos == size) {
                tails[size++] = x;
            } else {
                tails[pos] = x;
            }
            inc[i] = pos + 1;
        }
        tails = new int[n];
        size = 0;
        for (int i = n - 1; i >= 0; i--) {
            int x = nums[i];
            int l = 0, r = size;
            while (l < r) {
                int m = (l + r) >>> 1;
                if (tails[m] < x) {
                    l = m + 1;
                } else {
                    r = m;
                }
            }
            int pos = l;
            if (pos == size) {
                tails[size++] = x;
            } else {
                tails[pos] = x;
            }
            dec[i] = pos + 1;
        }
        int best = 0;
        for (int i = 1; i < n - 1; i++) {
            if (inc[i] > 1 && dec[i] > 1) {
                int cur = inc[i] + dec[i] - 1;
                if (cur > best) {
                    best = cur;
                }
            }
        }
        return n - best;
    }
}

class ListNode {
    int val;
    ListNode next;
