class Solution {
    public static ListNode mergeInBetween(ListNode list1, int a, int b, ListNode list2) {
        ListNode prevA = null;
        ListNode cur = list1;
        int idx = 0;
        while (idx < a) {
            prevA = cur;
            cur = cur.next;
            idx++;
        }
        while (idx <= b) {
            cur = cur.next;
            idx++;
        }
        ListNode postB = cur;
        if (prevA != null) {
            prevA.next = list2;
        } else {
            list1 = list2;
        }
        ListNode tail2 = list2;
        while (tail2.next != null) {
            tail2 = tail2.next;
        }
        tail2.next = postB;
        return list1;
    }
}

