class Solution {
    public static int[] mostCompetitive(int[] nums, int k) {
        int n = nums.length;
        int[] stack = new int[k];
        int size = 0;
        for (int i = 0; i < n; i++) {
            int cur = nums[i];
            while (size > 0 && stack[size - 1] > cur && size - 1 + (n - i) >= k) {
                size--;
            }
            if (size < k) {
                stack[size++] = cur;
            }
        }
        return stack;
    }
}

