class Solution {
    public static int concatenatedBinary(int n) {
        final long MOD = 1000000007L;
        long result = 0;
        int bits = 0;
        for (int i = 1; i <= n; i++) {
            if ((i & (i - 1)) == 0) bits++;
            long shift = 1L << bits;
            result = (result * shift) % MOD;
            result = (result + i) % MOD;
        }
        return (int) result;
    }
}

