class Solution {
    public static int minMoves(int[] nums, int limit) {
        int n = nums.length;
        int maxSum = 2 * limit;
        int[] diff = new int[maxSum + 2];
        for (int i = 0; i < n / 2; ++i) {
            int a = nums[i];
            int b = nums[n - 1 - i];
            int sum = a + b;
            diff[2] += 2;
            diff[sum] -= 1;
            diff[sum + 1] += 1;
            int low = Math.min(a, b) + 1;
            int high = Math.max(a, b) + limit;
            diff[low] -= 1;
            diff[high + 1] += 1;
        }
        int cur = 0;
        int answer = Integer.MAX_VALUE;
        for (int s = 2; s <= maxSum; ++s) {
            cur += diff[s];
            if (cur < answer) answer = cur;
        }
        return answer;
    }
}

