class Solution {
    public static long[] sumAbsDifferences(int[] nums) {
        int n = nums.length;
        long[] result = new long[n];
        long totalSum = 0;
        for (int v : nums) totalSum += v;
        long leftSum = 0;
        for (int i = 0; i < n; i++) {
            long cur = nums[i];
            long left = (long) i * cur - leftSum;
            long right = (totalSum - leftSum - cur) - (long) (n - i - 1) * cur;
            result[i] = left + right;
            leftSum += cur;
        }
        return result;
    }
}

