        if (aliceScore < bobScore) return -1;
        return 0;
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public static int boxDelivering(int[][] boxes, int portsCount, int maxBoxes, int maxWeight) {
        int n = boxes.length;
        int[] port = new int[n + 1];
        int[] weight = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            port[i] = boxes[i - 1][0];
            weight[i] = boxes[i - 1][1];
        }

        long[] prefWeight = new long[n + 1];
        int[] diff = new int[n + 1];
        int[] prefDiff = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            prefWeight[i] = prefWeight[i - 1] + weight[i];
            if (i > 1 && port[i] != port[i - 1]) {
                diff[i] = 1;
            }
            prefDiff[i] = prefDiff[i - 1] + diff[i];
        }

        int[] dp = new int[n + 1];
        Deque<Integer> deque = new ArrayDeque<>();
        deque.addLast(0);
        int left = 1;

        for (int i = 1; i <= n; i++) {
            while (i - left + 1 > maxBoxes) {
                left++;
            }
            while (prefWeight[i] - prefWeight[left - 1] > maxWeight) {
                left++;
            }
            while (!deque.isEmpty() && deque.peekFirst() < left - 1) {
                deque.pollFirst();
            }
            int j = deque.peekFirst();
            dp[i] = prefDiff[i] + 2 + dp[j] - prefDiff[j + 1];

            if (i < n) {
                int val = dp[i] - prefDiff[i + 1];
                while (!deque.isEmpty()) {
                    int last = deque.peekLast();
                    int lastVal = dp[last] - prefDiff[last + 1];
                    if (val <= lastVal) {
                        deque.pollLast();
                    } else {
                        break;
                    }
                }
                deque.addLast(i);
            }
        }
        return dp[n];
    }
}

import java.util.*;

class Solution {
    public static int minIncompatibility(int[] nums, int k) {
        int n = nums.length;
        int g = n / k;
        Map<Integer, Integer> freq = new HashMap<>();
        for (int v : nums) {
            freq.put(v, freq.getOrDefault(v, 0) + 1);
            if (freq.get(v) > k) return -1;
        }
        int totalMask = 1 << n;
        int[] inc = new int[totalMask];
        Arrays.fill(inc, -1);
        for (int mask = 0; mask < totalMask; mask++) {
            if (popcnt(mask) != g) continue;
            int min = Integer.MAX_VALUE;
            int max = Integer.MIN_VALUE;
            Set<Integer> seen = new HashSet<>();
            boolean ok = true;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    int v = nums[i];
                    if (seen.contains(v)) {
                        ok = false;
                        break;
                    }
                    seen.add(v);
                    if (v < min) min = v;
                    if (v > max) max = v;
                }
            }
            if (ok) inc[mask] = max - min;
        }
        int INF = 1_000_000_000;
        int[] dp = new int[totalMask];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int mask = 1; mask < totalMask; mask++) {
            if (popcnt(mask) % g != 0) continue;
            for (int sub = mask; sub != 0; sub = (sub - 1) & mask) {
                int cost = inc[sub];
                if (cost == -1) continue;
                int prev = dp[mask ^ sub];
                if (prev + cost < dp[mask]) dp[mask] = prev + cost;
            }
        }
        int ans = dp[totalMask - 1];
        return ans >= INF ? -1 : ans;
    }

    private static int popcnt(int x) {
        int c = 0;
        while (x != 0) {
            x &= x - 1;
            c++;
        }
        return c;
    }
}

import java.util.Arrays;
