        int allowedMask = 0;
        for (int i = 0; i < allowed.length(); i++) {
            allowedMask |= 1 << (allowed.charAt(i) - 'a');
        }

        int consistentCount = 0;
        for (int w = 0; w < words.length; w++) {
            String word = words[w];
            boolean isConsistent = true;
            for (int j = 0; j < word.length(); j++) {
