class Solution {
    public static boolean[] checkEdgeLimitedPaths(int n, int[][] edgeList, int[][] queries) {
        int[] parent = new int[n];
        int[] rank = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
        class UF {
            int find(int x) {
                while (parent[x] != x) {
                    parent[x] = parent[parent[x]];
                    x = parent[x];
                }
                return x;
            }
            void union(int a, int b) {
                int ra = find(a);
                int rb = find(b);
                if (ra == rb) return;
                if (rank[ra] < rank[rb]) parent[ra] = rb;
                else if (rank[ra] > rank[rb]) parent[rb] = ra;
                else {
                    parent[rb] = ra;
                    rank[ra]++;
                }
            }
        }
        UF uf = new UF();
        Arrays.sort(edgeList, (e1, e2) -> Integer.compare(e1[2], e2[2]));
        class Query {
            int p, q, limit, idx;
            Query(int p, int q, int limit, int idx) {
                this.p = p;
                this.q = q;
                this.limit = limit;
                this.idx = idx;
            }
        }
        Query[] qs = new Query[queries.length];
        for (int i = 0; i < queries.length; i++) {
            qs[i] = new Query(queries[i][0], queries[i][1], queries[i][2], i);
        }
        Arrays.sort(qs, (a, b) -> Integer.compare(a.limit, b.limit));
        boolean[] answer = new boolean[queries.length];
        int eIdx = 0;
        for (Query query : qs) {
            while (eIdx < edgeList.length && edgeList[eIdx][2] < query.limit) {
                uf.union(edgeList[eIdx][0], edgeList[eIdx][1]);
                eIdx++;
            }
            answer[query.idx] = uf.find(query.p) == uf.find(query.q);
        }
        return answer;
    }
}

class Solution {
    public static String maximumBinaryString(String binary) {
        char[] arr = binary.toCharArray();
        int n = arr.length;
        int firstZero = -1;
        for (int i = 0; i < n; i++) {
            if (arr[i] == '0') {
                firstZero = i;
                break;
            }
        }
        if (firstZero == -1) {
            return binary;
        }
        int zerosCount = 0;
        for (int i = firstZero; i < n; i++) {
            if (arr[i] == '0') {
                zerosCount++;
            }
        }
        for (int i = firstZero; i < n; i++) {
            arr[i] = '1';
        }
        arr[firstZero + zerosCount - 1] = '0';
        return new String(arr);
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public static long maxResult(int[] nums, int k) {
        int n = nums.length;
        long[] dp = new long[n];
        dp[0] = nums[0];
        Deque<Integer> deque = new ArrayDeque<>();
        deque.addLast(0);
        for (int i = 1; i < n; i++) {
            while (!deque.isEmpty() && deque.peekFirst() < i - k) {
                deque.pollFirst();
            }
            dp[i] = nums[i] + dp[deque.peekFirst()];
            while (!deque.isEmpty() && dp[i] >= dp[deque.peekLast()]) {
                deque.pollLast();
            }
            deque.addLast(i);
        }
        return dp[n - 1];
    }
}

public class Solution {
    public static double averageWaitingTime(int[][] customers) {
        long totalWaiting = 0;
        long currentTime = 0;
        for (int i = 0; i < customers.length; i++) {
            long arrival = customers[i][0];
            long cook = customers[i][1];
            if (currentTime < arrival) {
                currentTime = arrival;
            }
            long finish = currentTime + cook;
            totalWaiting += finish - arrival;
            currentTime = finish;
        }
        return (double) totalWaiting / customers.length;
    }
}

