class Solution {
    public static long minMoves(int[] nums, int k) {
        List<Integer> onesList = new ArrayList<>();
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] == 1) {
                onesList.add(i);
            }
        }
        if (k <= 1) {
            return 0;
        }
        int m = onesList.size();
        long[] adjusted = new long[m];
        for (int i = 0; i < m; i++) {
            adjusted[i] = onesList.get(i) - i;
        }
        long[] pref = new long[m + 1];
        for (int i = 0; i < m; i++) {
            pref[i + 1] = pref[i] + adjusted[i];
        }
        long answer = Long.MAX_VALUE;
        for (int left = 0; left + k - 1 < m; left++) {
            int right = left + k - 1;
            int medianIdx = left + k / 2;
            long median = adjusted[medianIdx];
            long leftDist = median * (medianIdx - left) - (pref[medianIdx] - pref[left]);
            long rightDist = (pref[right + 1] - pref[medianIdx + 1]) - median * (right - medianIdx);
            long moves = leftDist + rightDist;
            if (moves < answer) {
                answer = moves;
            }
        }
        return answer;
    }
}

