import java.util.PriorityQueue;

class Solution {
    private static class Node {
        int expire;
        int count;
        Node(int expire, int count) {
            this.expire = expire;
            this.count = count;
        }
    }

    public static int maxEatenApples(int[] apples, int[] days) {
        PriorityQueue<Node> heap = new PriorityQueue<>((a, b) -> Integer.compare(a.expire, b.expire));
        int day = 0, eaten = 0;
        int n = apples.length;
        while (day < n || !heap.isEmpty()) {
            if (day < n && apples[day] > 0) {
                heap.offer(new Node(day + days[day], apples[day]));
            }
            while (!heap.isEmpty() && heap.peek().expire <= day) {
                heap.poll();
            }
            if (!heap.isEmpty()) {
                Node top = heap.peek();
                top.count--;
                eaten++;
                if (top.count == 0) {
                    heap.poll();
                }
            }
            day++;
        }
        return eaten;
    }
}

