class Solution {
    private static class Query {
        int x, m, idx;
        Query(int x, int m, int idx) {
            this.x = x;
            this.m = m;
            this.idx = idx;
        }
    }

    public static int[] maximizeXor(int[] nums, int[][] queries) {
        Arrays.sort(nums);
        int qLen = queries.length;
        Query[] qs = new Query[qLen];
        for (int i = 0; i < qLen; i++) {
            qs[i] = new Query(queries[i][0], queries[i][1], i);
        }
        Arrays.sort(qs, Comparator.comparingInt(a -> a.m));

        int maxBits = 31;
        int maxNodes = (nums.length + 1) * maxBits;
        int[][] trie = new int[maxNodes][2];
        int nodeCount = 1;

        int[] ans = new int[qLen];
        int numIdx = 0;
        for (Query q : qs) {
            while (numIdx < nums.length && nums[numIdx] <= q.m) {
                int val = nums[numIdx];
                int node = 0;
                for (int bit = 30; bit >= 0; bit--) {
                    int b = (val >> bit) & 1;
                    if (trie[node][b] == 0) {
                        trie[node][b] = nodeCount++;
                    }
                    node = trie[node][b];
                }
                numIdx++;
            }
            if (numIdx == 0) {
                ans[q.idx] = -1;
            } else {
                int node = 0;
                int xor = 0;
                for (int bit = 30; bit >= 0; bit--) {
                    int b = (q.x >> bit) & 1;
                    int desired = 1 - b;
                    if (trie[node][desired] != 0) {
                        xor |= (1 << bit);
                        node = trie[node][desired];
                    } else {
                        node = trie[node][b];
                    }
                }
                ans[q.idx] = xor;
            }
        }
        return ans;
    }
}

