class Solution {
    public static int waysToSplit(int[] nums) {
        int n = nums.length;
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] + nums[i];
        }
        long total = pref[n];
        final int MOD = 1_000_000_007;
        long ans = 0;
        int l = 2, r = 2;
        for (int i = 0; i <= n - 3; i++) {
            long left = pref[i + 1];
            while (l < n && pref[l] < 2L * left) {
                l++;
            }
            while (r < n && pref[r] <= (total + left) / 2) {
                r++;
            }
            int low = Math.max(l, i + 2);
            int high = Math.min(r - 1, n - 1);
            if (low <= high) {
                ans += (high - low + 1);
                if (ans >= MOD) ans %= MOD;
            }
        }
        return (int) (ans % MOD);
    }
}

