class Solution {
    public static int maximumScore(String s, int x, int y) {
        String first = x > y ? "ab" : "ba";
        int firstScore = Math.max(x, y);
        String second = x > y ? "ba" : "ab";
        int secondScore = Math.min(x, y);

        int total = 0;
        char[] stack = new char[s.length()];
        int top = 0;

        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (top > 0 && stack[top - 1] == first.charAt(0) && ch == first.charAt(1)) {
                top--;
                total += firstScore;
            } else {
                stack[top++] = ch;
            }
        }

        char[] stack2 = new char[top];
        int top2 = 0;
        for (int i = 0; i < top; i++) {
            char ch = stack[i];
            if (top2 > 0 && stack2[top2 - 1] == second.charAt(0) && ch == second.charAt(1)) {
                top2--;
                total += secondScore;
            } else {
                stack2[top2++] = ch;
            }
        }

        return total;
    }
}

