class Solution {
    public static int minOperations(int[] target, int[] arr) {
        HashMap<Integer, Integer> pos = new HashMap<>();
        for (int i = 0; i < target.length; i++) {
            pos.put(target[i], i);
        }
        ArrayList<Integer> seq = new ArrayList<>();
        for (int v : arr) {
            Integer index = pos.get(v);
            if (index != null) {
                seq.add(index);
            }
        }
        ArrayList<Integer> tails = new ArrayList<>();
        for (int idx : seq) {
            int lo = 0, hi = tails.size();
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (tails.get(mid) < idx) {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }
            if (lo == tails.size()) {
                tails.add(idx);
            } else {
                tails.set(lo, idx);
            }
        }
        return target.length - tails.size();
    }
}

class Solution {
    int[] result;
    boolean[] used;
    int n;

    public int[] constructDistancedSequence(int n) {
        this.n = n;
        int len = 2 * n - 1;
        result = new int[len];
        used = new boolean[n + 1];
        backtrack(0);
        return result;
    }

    private boolean backtrack(int idx) {
        int len = 2 * n - 1;
        if (idx == len) return true;
        if (result[idx] != 0) return backtrack(idx + 1);
        // greedily try the LARGEST unused number first for lexicographically largest result
        for (int num = n; num >= 1; num--) {
            if (used[num]) continue;
            if (num == 1) {
                result[idx] = 1;
                used[1] = true;
                if (backtrack(idx + 1)) return true;
                result[idx] = 0;
                used[1] = false;
            } else {
                int idx2 = idx + num;
                if (idx2 < len && result[idx2] == 0) {
                    result[idx] = num;
                    result[idx2] = num;
                    used[num] = true;
                    if (backtrack(idx + 1)) return true;
                    result[idx] = 0;
                    result[idx2] = 0;
                    used[num] = false;
                }
            }
        }
        return false;
    }
}

import java.util.*;

class Solution {
    public int minimumHammingDistance(int[] source, int[] target, List<List<Integer>> allowedSwaps) {
        int n = source.length;
        int[] parent = new int[n];
        int[] rank = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;

        java.util.function.IntUnaryOperator find = new java.util.function.IntUnaryOperator() {
            @Override
            public int applyAsInt(int x) {
                while (parent[x] != x) {
                    parent[x] = parent[parent[x]];
                    x = parent[x];
                }
                return x;
            }
        };

        java.util.function.BiConsumer<Integer, Integer> union = (x, y) -> {
            int rx = find.applyAsInt(x);
            int ry = find.applyAsInt(y);
            if (rx == ry) return;
            if (rank[rx] < rank[ry]) {
                parent[rx] = ry;
            } else if (rank[rx] > rank[ry]) {
                parent[ry] = rx;
            } else {
                parent[ry] = rx;
                rank[rx]++;
            }
        };

        for (List<Integer> pair : allowedSwaps) {
            union.accept(pair.get(0), pair.get(1));
        }

        Map<Integer, List<Integer>> groups = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int root = find.applyAsInt(i);
            groups.computeIfAbsent(root, k -> new ArrayList<>()).add(i);
        }

        int mismatches = 0;
        for (List<Integer> indices : groups.values()) {
            Map<Integer, Integer> freq = new HashMap<>();
            for (int idx : indices) {
                int val = source[idx];
                freq.put(val, freq.getOrDefault(val, 0) + 1);
            }
            for (int idx : indices) {
                int val = target[idx];
                Integer count = freq.get(val);
                if (count != null && count > 0) {
                    freq.put(val, count - 1);
                } else {
                    mismatches++;
                }
            }
        }
        return mismatches;
    }
}

