class Solution {
    public int checkWays(int[][] pairs) {
        boolean[][] connected = new boolean[510][510];
        List<Integer>[] adj = new List[510];
        for (int i = 0; i < 510; i++) adj[i] = new ArrayList<>();
        for (int[] p : pairs) {
            int a = p[0], b = p[1];
            connected[a][b] = connected[b][a] = true;
            adj[a].add(b); adj[b].add(a);
        }
        List<Integer> nodes = new ArrayList<>();
        for (int i = 0; i < 510; i++) {
            if (!adj[i].isEmpty()) {
                nodes.add(i);
                connected[i][i] = true;
            }
        }
        // Sort by degree ascending. For each node, its parent is the FIRST node later in
        // this order that's actually connected to it - not just any minimal-degree neighbor,
        // since with ties the sorted-position tiebreak matters for correctness.
        nodes.sort(Comparator.comparingInt(v -> adj[v].size()));
        boolean equalFlag = false;
        int rootCount = 0;
        for (int i = 0; i < nodes.size(); i++) {
            int x = nodes.get(i);
            int j = i + 1;
            while (j < nodes.size() && !connected[x][nodes.get(j)]) j++;
            if (j < nodes.size()) {
                int y = nodes.get(j);
                if (adj[x].size() == adj[y].size()) equalFlag = true;
                // transitivity: every relation x has must also hold for its chosen parent y
                for (int z : adj[x]) {
                    if (!connected[y][z]) return 0;
                }
            } else {
                rootCount++;
            }
        }
        if (rootCount > 1) return 0;
        return equalFlag ? 2 : 1;
    }
}

