class Solution {
    public static int minimumTimeRequired(int[] jobs, int k) {
        Integer[] jobsObj = new Integer[jobs.length];
        for (int i = 0; i < jobs.length; i++) {
            jobsObj[i] = jobs[i];
        }
        Arrays.sort(jobsObj, Collections.reverseOrder());
        int low = jobsObj[0];
        int high = 0;
        for (int v : jobsObj) {
            high += v;
        }
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (canFinish(jobsObj, k, mid)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    private static boolean canFinish(Integer[] jobs, int k, int limit) {
        int[] loads = new int[k];
        return dfs(0, jobs, limit, loads);
    }

    private static boolean dfs(int idx, Integer[] jobs, int limit, int[] loads) {
        if (idx == jobs.length) {
            return true;
        }
        int cur = jobs[idx];
        HashSet<Integer> seen = new HashSet<>();
        for (int i = 0; i < loads.length; i++) {
            if (loads[i] + cur > limit) {
                continue;
            }
            if (!seen.add(loads[i])) {
                continue;
            }
            loads[i] += cur;
            if (dfs(idx + 1, jobs, limit, loads)) {
                return true;
            }
            loads[i] -= cur;
            if (loads[i] == 0) {
                break;
            }
        }
        return false;
    }
}

