class Solution {
    public static int minimumTeachings(int n, List<List<Integer>> languages, int[][] friendships) {
        List<Set<Integer>> userLang = new ArrayList<>(languages.size());
        for (List<Integer> arr : languages) {
            userLang.add(new HashSet<>(arr));
        }
        Set<Integer> badUsers = new HashSet<>();
        for (int[] pair : friendships) {
            int a = pair[0] - 1;
            int b = pair[1] - 1;
            boolean share = false;
            for (int lang : userLang.get(a)) {
                if (userLang.get(b).contains(lang)) {
                    share = true;
                    break;
                }
            }
            if (!share) {
                badUsers.add(a);
                badUsers.add(b);
            }
        }
        if (badUsers.isEmpty()) return 0;
        int answer = Integer.MAX_VALUE;
        for (int L = 1; L <= n; ++L) {
            int teach = 0;
            for (int u : badUsers) {
                if (!userLang.get(u).contains(L)) ++teach;
            }
            if (teach < answer) answer = teach;
        }
        return answer;
    }
}

public class Solution {
    public static int[] decodeXorPermutation(int[] encoded) {
        int n = encoded.length + 1;
        int totalXor = 0;
        for (int i = 1; i <= n; i++) totalXor ^= i;
        int oddXor = 0;
        for (int i = 1; i < encoded.length; i += 2) oddXor ^= encoded[i];
        int[] perm = new int[n];
        perm[0] = totalXor ^ oddXor;
        for (int i = 1; i < n; i++) perm[i] = perm[i - 1] ^ encoded[i - 1];
        return perm;
    }
}

