class Solution {
    public static int largestSubmatrix(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;
        int[] heights = new int[n];
        int maxArea = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                heights[j] = matrix[i][j] == 1 ? heights[j] + 1 : 0;
            }
            int[] cnt = new int[m + 1];
            for (int h : heights) {
                cnt[h]++;
            }
            int colsAtLeast = 0;
            for (int h = m; h >= 1; h--) {
                colsAtLeast += cnt[h];
                int area = h * colsAtLeast;
                if (area > maxArea) {
                    maxArea = area;
                }
            }
        }
        return maxArea;
    }
}

