        mouseAdj = new List[total];
        catAdj = new List[total];
        for (int i = 0; i < total; i++) {
            mouseAdj[i] = computeMoves(i, mouseJump, grid);
            catAdj[i] = computeMoves(i, catJump, grid);
        }

        int[][][] result = new int[total][total][2]; // 0 unknown, 1 mouse win, 2 cat win
        int[][][] degree = new int[total][total][2];
        Deque<int[]> q = new ArrayDeque<>();

        for (int m = 0; m < total; m++) {
            for (int c = 0; c < total; c++) {
                if (isWall(m, grid) || isWall(c, grid)) continue;

                int cnt = 0;
                for (int nxtM : mouseAdj[m]) {
                    if (nxtM == c) continue;
                    cnt++;
                }
                degree[m][c][0] = cnt;

                cnt = 0;
                for (int nxtC : catAdj[c]) {
                    if (nxtC == m) continue;
                    cnt++;
                }
                degree[m][c][1] = cnt;

                if (m == foodPos) {
                    result[m][c][0] = result[m][c][1] = 1;
                    q.add(new int[]{m, c, 0});
                    q.add(new int[]{m, c, 1});
                } else if (c == foodPos || c == m) {
                    result[m][c][0] = result[m][c][1] = 2;
                    q.add(new int[]{m, c, 0});
                    q.add(new int[]{m, c, 1});
                }
            }
        }

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int m = cur[0], c = cur[1], turn = cur[2];
            int curRes = result[m][c][turn];
            int prevTurn = 1 - turn;

            if (turn == 0) { // current is mouse turn, predecessors are cat turn
                for (int prevC : catAdj[c]) {
                    if (prevC == m) continue;
                    if (isWall(prevC, grid)) continue;
                    if (result[m][prevC][prevTurn] != 0) continue;
                    if (curRes == 2) {
                        result[m][prevC][prevTurn] = 2;
                        q.add(new int[]{m, prevC, prevTurn});
                    } else {
                        degree[m][prevC][prevTurn]--;
                        if (degree[m][prevC][prevTurn] == 0) {
                            result[m][prevC][prevTurn] = 1;
                            q.add(new int[]{m, prevC, prevTurn});
                        }
                    }
                }
            } else { // turn == 1, current is cat turn, predecessors are mouse turn
                for (int prevM : mouseAdj[m]) {
                    if (prevM == c) continue;
                    if (isWall(prevM, grid)) continue;
                    if (result[prevM][c][prevTurn] != 0) continue;
                    if (curRes == 1) {
                        result[prevM][c][prevTurn] = 1;
                        q.add(new int[]{prevM, c, prevTurn});
                    } else {
                        degree[prevM][c][prevTurn]--;
                        if (degree[prevM][c][prevTurn] == 0) {
                            result[prevM][c][prevTurn] = 2;
                            q.add(new int[]{prevM, c, prevTurn});
                        }
                    }
                }
            }
        }

        return result[mouseStart][catStart][0] == 1;
    }

    private static List<Integer> computeMoves(int idx, int jump, String[] grid) {
        List<Integer> moves = new ArrayList<>();
        int r = idx / cols;
        int c = idx % cols;
        if (!isWall(idx, grid)) moves.add(idx);
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
        for (int d = 0; d < 4; d++) {
            for (int step = 1; step <= jump; step++) {
                int nr = r + dr[d] * step;
                int nc = c + dc[d] * step;
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) break;
                int nIdx = nr * cols + nc;
                if (isWall(nIdx, grid)) break;
                moves.add(nIdx);
            }
        }
        return moves;
    }

    private static boolean isWall(int idx, String[] grid) {
        int r = idx / cols;
        int c = idx % cols;
        return grid[r].charAt(c) == '#';
    }
}

import java.util.*;

class Solution {
    public static int minCharacters(String a, String b) {
        int[] cntA = new int[26];
        int[] cntB = new int[26];
        for (char ch : a.toCharArray()) cntA[ch - 'a']++;
        for (char ch : b.toCharArray()) cntB[ch - 'a']++;
        int lenA = a.length();
        int lenB = b.length();

        int minCost = Integer.MAX_VALUE;
        for (int c = 0; c < 26; c++) {
            int cost = (lenA - cntA[c]) + (lenB - cntB[c]);
            if (cost < minCost) minCost = cost;
        }

        int cumA = 0;
        int cumB = 0;
        for (int t = 0; t < 26; t++) {
            cumA += cntA[t];
            cumB += cntB[t];
            int cost1 = (lenA - cumA) + cumB;
            if (cost1 < minCost) minCost = cost1;
            int cost2 = (lenB - cumB) + cumA;
            if (cost2 < minCost) minCost = cost2;
        }

        return minCost;
    }
}

import java.util.PriorityQueue;

class Solution {
    public static int kthLargestXorCoordinate(int[][] matrix, int k) {
        int m = matrix.length;
        int n = matrix[0].length;
        int[] prev = new int[n];
        int[] cur = new int[n];
        PriorityQueue<Integer> heap = new PriorityQueue<>(k);
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int top = i > 0 ? prev[j] : 0;
                int left = j > 0 ? cur[j - 1] : 0;
                int diag = (i > 0 && j > 0) ? prev[j - 1] : 0;
                cur[j] = top ^ left ^ diag ^ matrix[i][j];
                if (heap.size() < k) {
                    heap.offer(cur[j]);
                } else if (cur[j] > heap.peek()) {
                    heap.poll();
                    heap.offer(cur[j]);
                }
            }
            int[] temp = prev;
            prev = cur;
            cur = temp;
        }
        return heap.peek();
    }
}

