class Solution {
    public static long minFloorBoxes(long n) {
        if (n <= 1) return 1;
        long s = floorSqrt(n);
        if (s * s == n) {
            return 2 * s - 1;
        }
        if (n <= s * (s + 1)) {
            return 2 * s;
        }
        return 2 * s + 1;
    }

    private static long floorSqrt(long n) {
        long lo = 0, hi = 3037000500L, res = 0;
        while (lo <= hi) {
            long mid = (lo + hi) >>> 1;
            if (mid <= n / mid) {
                res = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return res;
    }
}

