class Solution {
    public static int maxBallsInBox(int lowLimit, int highLimit) {
        Map<Integer, Integer> boxCount = new HashMap<>();
        int maxBalls = 0;
        for (int num = lowLimit; num <= highLimit; ++num) {
            int sum = 0;
            int x = num;
            while (x > 0) {
                sum += x % 10;
                x /= 10;
            }
            int newCount = boxCount.getOrDefault(sum, 0) + 1;
            boxCount.put(sum, newCount);
            if (newCount > maxBalls) {
                maxBalls = newCount;
            }
        }
        return maxBalls;
    }
}

import java.util.*;

class Solution {
    private static final int MOD = 1_000_000_007;

    private static long modPow(long a, long e) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = res * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return res;
    }

    private static long nCr(int n, int r, long[] fact, long[] invFact) {
        if (r < 0 || r > n) return 0;
        return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
    }

    public static int[] waysToMakeArray(int[][] queries) {
        int maxN = 0;
        int maxK = 0;
        for (int[] q : queries) {
            maxN = Math.max(maxN, q[0]);
            maxK = Math.max(maxK, q[1]);
        }
        int limit = maxN + 60;
        long[] fact = new long[limit + 1];
        long[] invFact = new long[limit + 1];
        fact[0] = 1;
        for (int i = 1; i <= limit; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[limit] = modPow(fact[limit], MOD - 2);
        for (int i = limit; i > 0; i--) invFact[i - 1] = invFact[i] * i % MOD;

        int sqrtMaxK = (int) Math.sqrt(maxK) + 1;
        boolean[] isComposite = new boolean[sqrtMaxK + 1];
        List<Integer> primes = new ArrayList<>();
        for (int i = 2; i <= sqrtMaxK; i++) {
            if (!isComposite[i]) {
                primes.add(i);
                if ((long) i * i <= sqrtMaxK) {
                    for (int j = i * i; j <= sqrtMaxK; j += i) {
                        isComposite[j] = true;
                    }
                }
            }
        }

        int m = queries.length;
        int[] ans = new int[m];
        for (int idx = 0; idx < m; idx++) {
            int n = queries[idx][0];
            int k = queries[idx][1];
            if (k == 1) {
                ans[idx] = 1;
                continue;
            }
            long ways = 1;
            int temp = k;
            for (int p : primes) {
                if ((long) p * p > temp) break;
                if (temp % p == 0) {
                    int cnt = 0;
                    while (temp % p == 0) {
                        cnt++;
                        temp /= p;
                    }
                    ways = ways * nCr(cnt + n - 1, n - 1, fact, invFact) % MOD;
                }
            }
            if (temp > 1) {
                ways = ways * nCr(1 + n - 1, n - 1, fact, invFact) % MOD;
            }
            ans[idx] = (int) ways;
        }
        return ans;
    }
}

