class Solution {
    public static boolean checkPartitioning(String s) {
        int n = s.length();
        if (n < 3) return false;
        boolean[] pref = new boolean[n];
        boolean[] suff = new boolean[n];
        for (int center = 0; center < n; center++) {
            int l = center, r = center;
            while (l >= 0 && r < n && s.charAt(l) == s.charAt(r)) {
                if (l == 0) pref[r] = true;
                if (r == n - 1) suff[l] = true;
                l--;
                r++;
            }
            l = center;
            r = center + 1;
            while (l >= 0 && r < n && s.charAt(l) == s.charAt(r)) {
                if (l == 0) pref[r] = true;
                if (r == n - 1) suff[l] = true;
                l--;
                r++;
            }
        }
        for (int center = 0; center < n; center++) {
            int l = center, r = center;
            while (l >= 0 && r < n && s.charAt(l) == s.charAt(r)) {
                if (l > 0 && r < n - 1 && pref[l - 1] && suff[r + 1]) return true;
                l--;
                r++;
            }
            l = center;
            r = center + 1;
            while (l >= 0 && r < n && s.charAt(l) == s.charAt(r)) {
                if (l > 0 && r < n - 1 && pref[l - 1] && suff[r + 1]) return true;
                l--;
                r++;
            }
        }
        return false;
    }
}

class Solution {
    public static long maxAbsoluteSubarraySum(int[] nums) {
        long maxEnding = 0, maxOverall = Long.MIN_VALUE;
        long minEnding = 0, minOverall = Long.MAX_VALUE;
        for (int i = 0; i < nums.length; i++) {
            long x = nums[i];
            maxEnding = Math.max(x, maxEnding + x);
            maxOverall = Math.max(maxOverall, maxEnding);
            minEnding = Math.min(x, minEnding + x);
            minOverall = Math.min(minOverall, minEnding);
        }
        return Math.max(Math.max(maxOverall, -minOverall), 0L);
    }
}

