class Solution {
    public static long closestSubsequenceSum(int[] nums, int goal) {
        int mid = nums.length / 2;
        int[] left = Arrays.copyOfRange(nums, 0, mid);
        int[] right = Arrays.copyOfRange(nums, mid, nums.length);

        long[] leftSums = allSums(left);
        long[] rightSums = allSums(right);
        Arrays.sort(rightSums);

        long best = Long.MAX_VALUE;

        for (long sL : leftSums) {
            long need = (long) goal - sL;
            int lo = 0, hi = rightSums.length;
            while (lo < hi) {
                int m = (lo + hi) >>> 1;
                if (rightSums[m] < need) {
                    lo = m + 1;
                } else {
                    hi = m;
                }
            }
            if (lo < rightSums.length) {
                long cur = Math.abs(sL + rightSums[lo] - goal);
                if (cur < best) best = cur;
            }
            if (lo > 0) {
                long cur = Math.abs(sL + rightSums[lo - 1] - goal);
                if (cur < best) best = cur;
            }
            if (best == 0) return 0;
        }
        return best;
    }

    private static long[] allSums(int[] arr) {
        int n = arr.length;
        int total = 1 << n;
        long[] sums = new long[total];
        for (int mask = 0; mask < total; ++mask) {
            long sum = 0;
            for (int i = 0; i < n; ++i) {
                if ((mask & (1 << i)) != 0) {
                    sum += arr[i];
                }
            }
            sums[mask] = sum;
        }
        return sums;
    }
}

