class Solution {
    public static boolean canChoose(int[][] groups, int[] nums) {
        int pos = 0;
        for (int[] g : groups) {
            int[] lps = new int[g.length];
            for (int i = 1, len = 0; i < g.length; ) {
                if (g[i] == g[len]) {
                    lps[i++] = ++len;
                } else if (len != 0) {
                    len = lps[len - 1];
                } else {
                    i++;
                }
            }
            int i = pos, j = 0, found = -1;
            while (i < nums.length) {
                if (nums[i] == g[j]) {
                    i++;
                    j++;
                    if (j == g.length) {
                        found = i - g.length;
                        break;
                    }
                } else if (j != 0) {
                    j = lps[j - 1];
                } else {
                    i++;
                }
            }
            if (found == -1) return false;
            pos = found + g.length;
        }
        return true;
    }
}

