class Solution {
    public static String longestNiceSubstring(String s) {
        int n = s.length();
        String best = "";
        for (int target = 1; target <= 26; target++) {
            int[] lower = new int[26];
            int[] upper = new int[26];
            int left = 0;
            int unique = 0;
            int both = 0;
            for (int right = 0; right < n; right++) {
                char c = s.charAt(right);
                int idx = Character.toLowerCase(c) - 'a';
                if (lower[idx] == 0 && upper[idx] == 0) {
                    unique++;
                }
                if (Character.isLowerCase(c)) {
                    lower[idx]++;
                    if (lower[idx] == 1 && upper[idx] > 0) {
                        both++;
                    }
                } else {
                    upper[idx]++;
                    if (upper[idx] == 1 && lower[idx] > 0) {
                        both++;
                    }
                }
                while (unique > target) {
                    char cl = s.charAt(left);
                    int idxl = Character.toLowerCase(cl) - 'a';
                    if (Character.isLowerCase(cl)) {
                        if (lower[idxl] == 1 && upper[idxl] > 0) {
                            both--;
                        }
                        lower[idxl]--;
                    } else {
                        if (upper[idxl] == 1 && lower[idxl] > 0) {
                            both--;
                        }
                        upper[idxl]--;
                    }
                    if (lower[idxl] == 0 && upper[idxl] == 0) {
                        unique--;
                    }
                    left++;
                }
                if (unique == target && both == target) {
                    if (right - left + 1 > best.length()) {
                        best = s.substring(left, right + 1);
                    }
                }
            }
        }
        return best;
    }
}

