import java.util.*;

class Solution {
    public static int[] getCoprimeAncestors(int[] nums, int[][] edges) {
        int n = nums.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0], v = e[1];
            graph[u].add(v);
            graph[v].add(u);
        }

        int[][] coprimeVals = new int[51][];
        for (int i = 1; i <= 50; i++) {
            List<Integer> list = new ArrayList<>();
            for (int j = 1; j <= 50; j++) {
                if (gcd(i, j) == 1) list.add(j);
            }
            coprimeVals[i] = list.stream().mapToInt(Integer::intValue).toArray();
        }

        int[] ans = new int[n];
        int[] lastNode = new int[51];
        int[] lastDepth = new int[51];
        Arrays.fill(lastNode, -1);
        Arrays.fill(lastDepth, -1);

        Deque<Frame> stack = new ArrayDeque<>();
        stack.push(new Frame(0, -1, 0, 0));

        while (!stack.isEmpty()) {
            Frame f = stack.pop();
            int node = f.node;
            if (f.state == 0) {
                int bestNode = -1;
                int bestDepth = -1;
                int val = nums[node];
                for (int v : coprimeVals[val]) {
                    if (lastNode[v] != -1 && lastDepth[v] > bestDepth) {
                        bestDepth = lastDepth[v];
                        bestNode = lastNode[v];
                    }
                }
                ans[node] = bestNode;

                f.prevNode = lastNode[val];
                f.prevDepth = lastDepth[val];
                lastNode[val] = node;
                lastDepth[val] = f.depth;

                f.state = 1;
                stack.push(f);
                for (int nb : graph[node]) {
                    if (nb == f.parent) continue;
                    stack.push(new Frame(nb, node, 0, f.depth + 1));
                }
            } else {
                int val = nums[node];
                lastNode[val] = f.prevNode;
                lastDepth[val] = f.prevDepth;
            }
        }
        return ans;
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    private static class Frame {
        int node;
        int parent;
        int state;
        int depth;
        int prevNode;
        int prevDepth;

        Frame(int node, int parent, int state, int depth) {
            this.node = node;
            this.parent = parent;
            this.state = state;
            this.depth = depth;
            this.prevNode = -1;
            this.prevDepth = -1;
        }
    }
}

import java.util.*;

class Solution {
    public static int longestPalindromeFromSubsequences(String word1, String word2) {
        int n = word1.length();
        int m = word2.length();
        String rev2 = new StringBuilder(word2).reverse().toString();
        int[] dp = new int[m + 1];
        for (int i = 1; i <= n; i++) {
            int prevDiag = 0;
            char c1 = word1.charAt(i - 1);
            for (int j = 1; j <= m; j++) {
                int temp = dp[j];
                if (c1 == rev2.charAt(j - 1)) {
                    dp[j] = prevDiag + 1;
                } else {
                    dp[j] = dp[j] > dp[j - 1] ? dp[j] : dp[j - 1];
                }
                prevDiag = temp;
            }
        }
        int k = dp[m];
        int ans = 2 * k;
        if (k > 0 && (word1.length() > k || word2.length() > k)) {
            ans = Math.max(ans, 2 * k + 1);
        }
        return ans;
    }
}

