class Solution {
    public static int closestDessertCost(int[] baseCosts, int[] toppingCosts, int target) {
        List<Integer> toppingSums = new ArrayList<>();
        dfs(0, 0, toppingCosts, toppingSums);
        Collections.sort(toppingSums);
        int best = Integer.MAX_VALUE;
        for (int base : baseCosts) {
            int need = target - base;
            int lo = 0, hi = toppingSums.size() - 1;
            while (lo <= hi) {
                int mid = (lo + hi) >>> 1;
                if (toppingSums.get(mid) < need) {
                    lo = mid + 1;
                } else {
                    hi = mid - 1;
                }
            }
            if (lo < toppingSums.size()) {
                best = update(best, base + toppingSums.get(lo), target);
            }
            if (hi >= 0) {
                best = update(best, base + toppingSums.get(hi), target);
            }
        }
        return best;
    }

    private static void dfs(int i, int cur, int[] toppingCosts, List<Integer> list) {
        if (i == toppingCosts.length) {
            list.add(cur);
            return;
        }
        dfs(i + 1, cur, toppingCosts, list);
        dfs(i + 1, cur + toppingCosts[i], toppingCosts, list);
        dfs(i + 1, cur + 2 * toppingCosts[i], toppingCosts, list);
    }

    private static int update(int best, int cost, int target) {
        int diff = Math.abs(cost - target);
        int bestDiff = Math.abs(best - target);
        if (diff < bestDiff || (diff == bestDiff && cost < best)) {
            return cost;
        }
        return best;
    }
}

import java.util.Arrays;

class Solution {
    public static double[] getCollisionTimes(double[][] cars) {
        int n = cars.length;
        double[] answer = new double[n];
        Arrays.fill(answer, -1.0);
        int[] stack = new int[n];
        int stackSize = 0;

        for (int i = n - 1; i >= 0; i--) {
            while (stackSize > 0) {
                int j = stack[stackSize - 1];
                double speedI = cars[i][1];
                double speedJ = cars[j][1];

                if (speedI <= speedJ) {
                    stackSize--;
                    continue;
                }

                double time = (cars[j][0] - cars[i][0]) / (speedI - speedJ);

                if (answer[j] == -1.0 || time <= answer[j]) {
                    answer[i] = time;
                    break;
                }

                stackSize--;
            }
            stack[stackSize++] = i;
        }
        return answer;
    }
}

