class Solution {
    public static int minOperations(int[] nums1, int[] nums2) {
        int sum1 = 0, sum2 = 0;
        for (int v : nums1) sum1 += v;
        for (int v : nums2) sum2 += v;
        if (sum1 == sum2) return 0;
        if (sum1 > sum2) {
            int[] tmpArr = nums1;
            nums1 = nums2;
            nums2 = tmpArr;
            int tmpSum = sum1;
            sum1 = sum2;
            sum2 = tmpSum;
        }
        int diff = sum2 - sum1;
        int[] gainCount = new int[6];
        for (int v : nums1) {
            int gain = 6 - v;
            if (gain > 0) gainCount[gain]++;
        }
        for (int v : nums2) {
            int gain = v - 1;
            if (gain > 0) gainCount[gain]++;
        }
        int ops = 0;
        for (int g = 5; g >= 1 && diff > 0; g--) {
            int use = Math.min(gainCount[g], (diff + g - 1) / g);
            diff -= use * g;
            ops += use;
        }
        return diff > 0 ? -1 : ops;
    }
}

