class Solution {
    public int minChanges(int[] nums, int k) {
        final int INF = Integer.MAX_VALUE / 2;
        final int MAXV = 1024; // nums[i] < 2^10 per constraints
        int n = nums.length;
        // group indices by residue mod k; each group must independently XOR to the same target
        // value x across all groups for every length-k window to XOR to 0 (classic residue-class insight)
        Map<Integer, Integer>[] groups = new HashMap[k];
        int[] size = new int[k];
        for (int i = 0; i < k; i++) groups[i] = new HashMap<>();
        for (int i = 0; i < n; i++) {
            groups[i % k].merge(nums[i], 1, Integer::sum);
            size[i % k]++;
        }
        // dp[x] = min changes across processed groups achieving cumulative XOR x
        int[] dp = new int[MAXV];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int i = 0; i < k; i++) {
            int minPrev = Integer.MAX_VALUE;
            for (int v : dp) minPrev = Math.min(minPrev, v);
            int[] ndp = new int[MAXV];
            // baseline: change EVERY element in this group to some fresh value, achieving ANY
            // target XOR contribution freely, at cost = size[i], from the best prior state
            Arrays.fill(ndp, minPrev + size[i]);
            for (int x = 0; x < MAXV; x++) {
                if (dp[x] == INF) continue;
                // alternative: keep one of the group's EXISTING values as the "free" contribution,
                // only changing the other occurrences (cost = size[i] - frequency of that value)
                for (Map.Entry<Integer, Integer> e : groups[i].entrySet()) {
                    int v = e.getKey(), freq = e.getValue();
                    int nx = x ^ v;
                    int cost = dp[x] + (size[i] - freq);
                    if (cost < ndp[nx]) ndp[nx] = cost;
                }
            }
            dp = ndp;
        }
        return dp[0];
    }
}

