class Solution {
    private static double gain(int p, int t) {
        return ((double) (p + 1)) / (t + 1) - ((double) p) / t;
    }

    private static class Node {
        int p;
        int t;
        double gain;

        Node(int p, int t, double gain) {
            this.p = p;
            this.t = t;
            this.gain = gain;
        }
    }

    public static double maxAverageRatio(int[][] classes, int extraStudents) {
        PriorityQueue<Node> heap = new PriorityQueue<>((a, b) -> Double.compare(b.gain, a.gain));
        for (int[] cls : classes) {
            int p = cls[0];
            int t = cls[1];
            heap.offer(new Node(p, t, gain(p, t)));
        }
        for (int i = 0; i < extraStudents; i++) {
            Node best = heap.poll();
            best.p += 1;
            best.t += 1;
            best.gain = gain(best.p, best.t);
            heap.offer(best);
        }
        double sum = 0.0;
        for (Node node : heap) {
            sum += (double) node.p / node.t;
        }
        double result = sum / classes.length;
        return Math.round(result * 100000.0) / 100000.0;
    }
}

