public class Solution {
    public static long maxScore(int[] nums) {
        int m = nums.length;
        int fullMask = (1 << m) - 1;
        int[][] gcd = new int[m][m];
        for (int i = 0; i < m; i++) {
            for (int j = i + 1; j < m; j++) {
                gcd[i][j] = computeGcd(nums[i], nums[j]);
            }
        }
        long[] dp = new long[1 << m];
        for (int mask = 0; mask <= fullMask; mask++) {
            int used = Integer.bitCount(mask);
            if ((used & 1) == 1) continue;
            int op = used / 2 + 1;
            int i = 0;
            while (i < m && ((mask >> i) & 1) == 1) i++;
            if (i == m) continue;
            for (int j = i + 1; j < m; j++) {
                if (((mask >> j) & 1) == 1) continue;
                int newMask = mask | (1 << i) | (1 << j);
                long candidate = dp[mask] + (long) op * gcd[i][j];
                if (candidate > dp[newMask]) dp[newMask] = candidate;
            }
        }
        return dp[fullMask];
    }

    private static int computeGcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

