import java.util.PriorityQueue;

class Solution {
    private static final int MOD = 1_000_000_007;

    private static class Node {
        int price;
        long amount;
        Node(int price, long amount) {
            this.price = price;
            this.amount = amount;
        }
    }

    public static int getNumberOfBacklogOrders(int[][] orders) {
        PriorityQueue<Node> buyHeap = new PriorityQueue<>((a, b) -> Integer.compare(b.price, a.price));
        PriorityQueue<Node> sellHeap = new PriorityQueue<>((a, b) -> Integer.compare(a.price, b.price));

        for (int[] order : orders) {
            int price = order[0];
            long amount = order[1];
            int type = order[2];

            if (type == 0) { // BUY
                while (amount > 0 && !sellHeap.isEmpty() && sellHeap.peek().price <= price) {
                    Node sell = sellHeap.peek();
                    long matched = Math.min(amount, sell.amount);
                    amount -= matched;
                    sell.amount -= matched;
                    if (sell.amount == 0) {
                        sellHeap.poll();
                    }
                }
                if (amount > 0) {
                    buyHeap.offer(new Node(price, amount));
                }
            } else { // SELL
                while (amount > 0 && !buyHeap.isEmpty() && buyHeap.peek().price >= price) {
                    Node buy = buyHeap.peek();
                    long matched = Math.min(amount, buy.amount);
                    amount -= matched;
                    buy.amount -= matched;
                    if (buy.amount == 0) {
                        buyHeap.poll();
                    }
                }
                if (amount > 0) {
                    sellHeap.offer(new Node(price, amount));
                }
            }
        }

        long total = 0;
        for (Node node : buyHeap) {
            total = (total + node.amount) % MOD;
        }
        for (Node node : sellHeap) {
            total = (total + node.amount) % MOD;
        }
        return (int) total;
    }
}

class Solution {
    public static int maxValue(int n, int index, int maxSum) {
        long low = 1;
        long high = maxSum;
        while (low < high) {
            long mid = (low + high + 1) >>> 1;
            if (canFit(mid, n, index, maxSum)) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return (int) low;
    }

    private static boolean canFit(long x, int n, int index, int maxSum) {
        long leftLen = index;
        long rightLen = n - index - 1;
        long leftSum = sideSum(x, leftLen);
        long rightSum = sideSum(x, rightLen);
        long total = leftSum + rightSum + x;
        return total <= maxSum;
    }

    private static long sideSum(long peak, long len) {
        if (len == 0) return 0;
        if (peak > len) {
            long first = peak - 1;
            long last = peak - len;
            return len * (first + last) / 2;
        } else {
            long decreasingSum = (peak - 1) * peak / 2;
            long ones = len - (peak - 1);
            return decreasingSum + ones;
        }
    }
}

