class Solution {
    private static class Node {
        int cnt;
        Node[] child = new Node[2];
    }

    private static void insert(Node root, int num, int maxBit) {
        Node node = root;
        for (int i = maxBit; i >= 0; i--) {
            int bit = (num >> i) & 1;
            if (node.child[bit] == null) node.child[bit] = new Node();
            node = node.child[bit];
            node.cnt++;
        }
    }

    private static long query(Node root, int num, int k, int maxBit) {
        Node node = root;
        long total = 0;
        for (int i = maxBit; i >= 0; i--) {
            if (node == null) break;
            int bitNum = (num >> i) & 1;
            int bitK = (k >> i) & 1;
            if (bitK == 1) {
                if (node.child[bitNum] != null) total += node.child[bitNum].cnt;
                node = node.child[1 - bitNum];
            } else {
                node = node.child[bitNum];
            }
        }
        if (node != null) total += node.cnt;
        return total;
    }

    private static long countLessOrEqual(int[] nums, int bound) {
        if (bound < 0) return 0L;
        Node root = new Node();
        int maxBit = 30;
        long ans = 0;
        for (int num : nums) {
            ans += query(root, num, bound, maxBit);
            insert(root, num, maxBit);
        }
        return ans;
    }

    public static long countPairs(int[] nums, int low, int high) {
        return countLessOrEqual(nums, high) - countLessOrEqual(nums, low - 1);
    }
}

