class Solution {
    private static final long MOD = 1000000007L;

    private static long modPow(long base, long exp) {
        long res = 1L;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1L) == 1L) {
                res = (res * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }

    public static long maxNiceDivisors(long primeFactors) {
        if (primeFactors == 1L) return 1L;
        long a = primeFactors / 3L;
        long r = primeFactors % 3L;
        if (r == 0L) {
            return modPow(3L, a);
        }
        if (r == 1L) {
            return (modPow(3L, a - 1L) * 4L) % MOD;
        }
        return (modPow(3L, a) * 2L) % MOD;
    }
}

