class Solution {
    public static int maxHappyGroups(int batchSize, int[] groups) {
        int[] cnt = new int[batchSize];
        int baseHappy = 0;
        for (int g : groups) {
            int r = g % batchSize;
            if (r == 0) {
                baseHappy++;
            } else {
                cnt[r]++;
            }
        }
        long state = 0L;
        for (int r = 1; r < batchSize; r++) {
            state |= ((long) cnt[r]) << (5 * (r - 1));
        }
        Map<Long, Integer> memo = new HashMap<>();
        int extraHappy = dfs(state, 0, batchSize, memo);
        return baseHappy + extraHappy;
    }

    private static int dfs(long state, int curMod, int batchSize, Map<Long, Integer> memo) {
        if (state == 0L) {
            return 0;
        }
        long key = (state << 4) | curMod;
        Integer cached = memo.get(key);
        if (cached != null) {
            return cached;
        }
        int best = 0;
        for (int r = 1; r < batchSize; r++) {
            int shift = 5 * (r - 1);
            int count = (int) ((state >> shift) & 31L);
            if (count == 0) continue;
            long newState = state - (1L << shift);
            int newMod = (curMod + r) % batchSize;
            int add = (curMod == 0) ? 1 : 0;
            int candidate = add + dfs(newState, newMod, batchSize, memo);
            if (candidate > best) best = candidate;
        }
        memo.put(key, best);
        return best;
    }
}

