        Map<Integer, Set<Integer>> minutesPerUser = new HashMap<>();
        for (int[] log : logs) {
            int id = log[0];
            int minute = log[1];
            minutesPerUser.computeIfAbsent(id, x -> new HashSet<>()).add(minute);
