public class Solution {
    public static int minAbsoluteSumDiff(int[] nums1, int[] nums2) {
        final int MOD = 1_000_000_007;
        int n = nums1.length;
        int[] sorted = nums1.clone();
        Arrays.sort(sorted);
        long totalDiff = 0;
        long bestGain = 0;
        for (int i = 0; i < n; i++) {
            int a = nums1[i];
            int b = nums2[i];
            long curDiff = Math.abs((long) a - b);
            totalDiff = (totalDiff + curDiff) % MOD;
            int pos = lowerBound(sorted, b);
            long minDiff = curDiff;
            if (pos < n) {
                long cand = Math.abs((long) sorted[pos] - b);
                if (cand < minDiff) minDiff = cand;
            }
            if (pos > 0) {
                long cand = Math.abs((long) sorted[pos - 1] - b);
                if (cand < minDiff) minDiff = cand;
            }
            long gain = curDiff - minDiff;
            if (gain > bestGain) bestGain = gain;
        }
        long answer = (totalDiff - bestGain + MOD) % MOD;
        return (int) answer;
    }

    private static int lowerBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

