class Solution {
    public static int countNicePairs(int[] nums) {
        final long MOD = 1_000_000_007L;
        Map<Integer, Integer> freq = new HashMap<>();
        for (int num : nums) {
            int diff = num - rev(num);
            freq.put(diff, freq.getOrDefault(diff, 0) + 1);
        }
        long ans = 0;
        for (int cnt : freq.values()) {
            if (cnt > 1) {
                ans = (ans + ((long) cnt * (cnt - 1) / 2)) % MOD;
            }
        }
        return (int) ans;
    }

    private static int rev(int x) {
        int r = 0;
        while (x > 0) {
            r = r * 10 + x % 10;
            x /= 10;
        }
        return r;
    }
}

