class Solution {
    public static int minSideJumps(int[] obstacles) {
        int[] dp = {1, 0, 1};
        for (int i = 1; i < obstacles.length; i++) {
            int obs = obstacles[i] - 1;
            if (obs >= 0) dp[obs] = Integer.MAX_VALUE;
            int minAll = Math.min(dp[0], Math.min(dp[1], dp[2]));
            for (int l = 0; l < 3; l++) {
                if (l != obs) {
                    dp[l] = Math.min(dp[l], minAll + 1);
                }
            }
        }
        return Math.min(dp[0], Math.min(dp[1], dp[2]));
    }
}

