class Solution {
    public static int countDifferentSubsequenceGCDs(int[] nums) {
        if (nums == null || nums.length == 0) {
            return 0;
        }
        int maxVal = 0;
        for (int v : nums) {
            if (v > maxVal) {
                maxVal = v;
            }
        }
        int[] freq = new int[maxVal + 1];
        for (int v : nums) {
            freq[v]++;
        }
        int answer = 0;
        for (int g = 1; g <= maxVal; g++) {
            int cur = 0;
            for (int m = g; m <= maxVal; m += g) {
                if (freq[m] != 0) {
                    cur = (cur != 0) ? gcd(cur, m) : m;
                }
            }
            if (cur == g) {
                answer++;
            }
        }
        return answer;
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

