public class Solution {
    private static final long MOD = 1_000_000_007L;

    private static long modPow(long a, long e) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = (res * a) % MOD;
            a = (a * a) % MOD;
            e >>= 1;
        }
        return res;
    }

    public static int minOperations(String s) {
        int n = s.length();
        long[] fact = new long[n + 1];
        long[] invFact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[n] = modPow(fact[n], MOD - 2);
        for (int i = n - 1; i >= 0; i--) invFact[i] = invFact[i + 1] * (i + 1) % MOD;

        int[] cnt = new int[26];
        for (int i = 0; i < n; i++) cnt[s.charAt(i) - 'a']++;

        long curProd = 1;
        for (int i = 0; i < 26; i++) curProd = curProd * invFact[cnt[i]] % MOD;

        long rank = 0;
        int remaining = n;
        for (int i = 0; i < n; i++) {
            int curIdx = s.charAt(i) - 'a';
            for (int c = 0; c < curIdx; c++) {
                if (cnt[c] == 0) continue;
                long newProd = curProd;
                newProd = newProd * fact[cnt[c]] % MOD;
                newProd = newProd * invFact[cnt[c] - 1] % MOD;
                long perm = fact[remaining - 1] * newProd % MOD;
                rank = (rank + perm) % MOD;
            }
            curProd = curProd * fact[cnt[curIdx]] % MOD;
            curProd = curProd * invFact[cnt[curIdx] - 1] % MOD;
            cnt[curIdx]--;
            remaining--;
        }
        return (int) rank;
    }
}

import java.util.*;
class MKAverage {
    int m, k;
    Deque<Integer> window = new ArrayDeque<>();
    TreeMap<Integer,Integer> low = new TreeMap<>(), mid = new TreeMap<>(), high = new TreeMap<>();
    int sizeLow = 0, sizeMid = 0, sizeHigh = 0;
    long sumMid = 0;
    void add(TreeMap<Integer,Integer> map, int v) { map.merge(v, 1, Integer::sum); }
    void remove(TreeMap<Integer,Integer> map, int v) {
        int c = map.get(v);
        if (c == 1) map.remove(v); else map.put(v, c-1);
    }
    public MKAverage(int m, int k) { this.m = m; this.k = k; }
    public void addElement(int num) {
        window.addLast(num);
        add(low, num); sizeLow++;
        while (sizeLow > k) {
            int mv = low.lastKey(); remove(low, mv); sizeLow--;
            add(mid, mv); sizeMid++; sumMid += mv;
        }
        while (sizeMid > m - 2*k) {
            int mv = mid.lastKey(); remove(mid, mv); sizeMid--; sumMid -= mv;
            add(high, mv); sizeHigh++;
        }
        if (window.size() > m) {
            int old = window.removeFirst();
            if (low.containsKey(old)) { remove(low, old); sizeLow--; }
            else if (high.containsKey(old)) { remove(high, old); sizeHigh--; }
            else { remove(mid, old); sizeMid--; sumMid -= old; }
            while (sizeLow < k && sizeMid > 0) {
                int mv = mid.firstKey(); remove(mid, mv); sizeMid--; sumMid -= mv;
                add(low, mv); sizeLow++;
            }
            while (sizeMid < m - 2*k && sizeHigh > 0) {
                int mv = high.firstKey(); remove(high, mv); sizeHigh--;
                add(mid, mv); sizeMid++; sumMid += mv;
            }
        }
    }
    public int calculateMKAverage() {
        if (window.size() < m) return -1;
        return (int)(sumMid / (m - 2*k));
    }
}

