class Solution {
    public static int[] getMaximumXor(int[] nums, int maximumBit) {
        int n = nums.length;
        int mask = (1 << maximumBit) - 1;
        int xorAll = 0;
        for (int v : nums) {
            xorAll ^= v;
        }
        int[] answer = new int[n];
        for (int i = 0; i < n; i++) {
            answer[i] = xorAll ^ mask;
