class Solution {
    public static int[] getOrder(int[][] tasks) {
        int n = tasks.length;
        int[][] tasksWithIdx = new int[n][3];
        for (int i = 0; i < n; i++) {
            tasksWithIdx[i][0] = tasks[i][0];
            tasksWithIdx[i][1] = tasks[i][1];
            tasksWithIdx[i][2] = i;
        }
        Arrays.sort(tasksWithIdx, (a, b) -> Integer.compare(a[0], b[0]));

        List<int[]> heap = new ArrayList<>();

        int time = 0, i = 0, orderPos = 0;
        int[] order = new int[n];

        while (orderPos < n) {
            while (i < n && tasksWithIdx[i][0] <= time) {
                heapPush(heap, tasksWithIdx[i]);
                i++;
            }
            if (heap.isEmpty()) {
                time = tasksWithIdx[i][0];
                continue;
            }
            int[] node = heapPop(heap);
            order[orderPos++] = node[2];
            time += node[1];
        }
        return order;
    }

    private static boolean less(int[] a, int[] b) {
        if (a[1] != b[1]) return a[1] < b[1];
        return a[2] < b[2];
    }

    private static void heapPush(List<int[]> heap, int[] node) {
        heap.add(node);
        int cur = heap.size() - 1;
        while (cur > 0) {
            int parent = (cur - 1) >> 1;
            if (less(heap.get(parent), heap.get(cur))) break;
            int[] temp = heap.get(parent);
            heap.set(parent, heap.get(cur));
            heap.set(cur, temp);
            cur = parent;
        }
    }

    private static int[] heapPop(List<int[]> heap) {
        int[] top = heap.get(0);
        int[] last = heap.remove(heap.size() - 1);
        if (!heap.isEmpty()) {
            heap.set(0, last);
            int cur = 0;
            while (true) {
                int left = cur * 2 + 1;
                int right = left + 1;
                int smallest = cur;
                if (left < heap.size() && less(heap.get(left), heap.get(smallest))) smallest = left;
                if (right < heap.size() && less(heap.get(right), heap.get(smallest))) smallest = right;
                if (smallest == cur) break;
                int[] temp = heap.get(cur);
                heap.set(cur, heap.get(smallest));
                heap.set(smallest, temp);
                cur = smallest;
            }
        }
        return top;
    }
}

