class Solution {
    public static int maxBuilding(int n, int[][] restrictions) {
        List<int[]> list = new ArrayList<>();
        for (int[] r : restrictions) {
            list.add(new int[]{r[0], r[1]});
        }
        list.add(new int[]{1, 0});
        list.add(new int[]{n, n - 1});
        list.sort(Comparator.comparingInt(a -> a[0]));
        for (int i = 1; i < list.size(); i++) {
            int dist = list.get(i)[0] - list.get(i - 1)[0];
            list.get(i)[1] = Math.min(list.get(i)[1], list.get(i - 1)[1] + dist);
        }
        for (int i = list.size() - 2; i >= 0; i--) {
            int dist = list.get(i + 1)[0] - list.get(i)[0];
            list.get(i)[1] = Math.min(list.get(i)[1], list.get(i + 1)[1] + dist);
        }
        int answer = 0;
        for (int i = 0; i < list.size() - 1; i++) {
            int leftPos = list.get(i)[0];
            int rightPos = list.get(i + 1)[0];
            int leftH = list.get(i)[1];
            int rightH = list.get(i + 1)[1];
            int distance = rightPos - leftPos;
            int peak = (leftH + rightH + distance) / 2;
            answer = Math.max(answer, Math.max(peak, Math.max(leftH, rightH)));
        }
        return answer;
    }
}

