class Solution {
    public static int longestBeautifulSubstring(String word) {
        int maxLen = 0;
        int start = 0;
        int prev = -1;
        int mask = 0;
        for (int i = 0; i < word.length(); i++) {
            char ch = word.charAt(i);
            int cur;
            switch (ch) {
                case 'a': cur = 0; break;
                case 'e': cur = 1; break;
                case 'i': cur = 2; break;
                case 'o': cur = 3; break;
                case 'u': cur = 4; break;
                default: cur = -1; break;
            }
            if (cur < prev) {
                start = i;
                mask = 0;
            }
            mask |= 1 << cur;
            prev = cur;
            if (mask == 0b11111) {
                int len = i - start + 1;
                if (len > maxLen) maxLen = len;
            }
        }
        return maxLen;
    }
}

