import java.util.Arrays;
import java.util.TreeSet;

class Solution {
    public static int[] closestRoom(int[][] rooms, int[][] queries) {
        int n = rooms.length;
        int k = queries.length;
        Room[] roomArr = new Room[n];
        for (int i = 0; i < n; i++) {
            roomArr[i] = new Room(rooms[i][0], rooms[i][1]);
        }
        Arrays.sort(roomArr, (a, b) -> Integer.compare(b.size, a.size));

        Query[] queryArr = new Query[k];
        for (int i = 0; i < k; i++) {
            queryArr[i] = new Query(queries[i][0], queries[i][1], i);
        }
        Arrays.sort(queryArr, (a, b) -> Integer.compare(b.minSize, a.minSize));

        TreeSet<Integer> eligibleIds = new TreeSet<>();
        int[] answer = new int[k];
        int idx = 0;
        for (Query q : queryArr) {
            while (idx < n && roomArr[idx].size >= q.minSize) {
                eligibleIds.add(roomArr[idx].id);
                idx++;
            }
            if (eligibleIds.isEmpty()) {
                answer[q.index] = -1;
            } else {
                Integer lower = eligibleIds.floor(q.preferred);
                Integer higher = eligibleIds.ceiling(q.preferred);
                int bestId;
                if (lower == null) {
                    bestId = higher;
                } else if (higher == null) {
                    bestId = lower;
                } else {
                    int diffLow = q.preferred - lower;
                    int diffHigh = higher - q.preferred;
                    if (diffLow <= diffHigh) {
                        bestId = lower;
                    } else {
                        bestId = higher;
                    }
                }
                answer[q.index] = bestId;
            }
        }
        return answer;
    }

    private static class Room {
        int id;
        int size;
        Room(int id, int size) {
            this.id = id;
            this.size = size;
        }
    }

    private static class Query {
        int preferred;
        int minSize;
        int index;
        Query(int preferred, int minSize, int index) {
            this.preferred = preferred;
            this.minSize = minSize;
            this.index = index;
        }
    }
}

