public class Solution {
    public static int maximumPopulation(int[][] logs) {
        final int OFFSET = 1950;
        final int RANGE = 101;
        int[] diff = new int[RANGE + 1];
        for (int i = 0; i < logs.length; i++) {
            int birth = logs[i][0] - OFFSET;
            int death = logs[i][1] - OFFSET;
            diff[birth] += 1;
            diff[death] -= 1;
        }
        int cur = 0, best = -1, answer = OFFSET;
        for (int y = 0; y < RANGE; y++) {
