                answer = y + OFFSET;
            }
        }
        return answer;
    }
}

import java.math.BigInteger;

class Solution {
    public boolean splitString(String s) {
        return dfs(s, 0, null, 0);
    }

    private boolean dfs(String s, int idx, BigInteger prev, int count) {
        int n = s.length();
        if (idx == n) {
            return count >= 2;
        }
        for (int len = 1; idx + len <= n; len++) {
            BigInteger cur = new BigInteger(s.substring(idx, idx + len));
            if (prev != null) {
                if (!cur.equals(prev.subtract(BigInteger.ONE))) {
                    continue;
                }
            }
            if (dfs(s, idx + len, cur, count + 1)) {
                return true;
            }
        }
        return false;
    }
}

