class Solution {
    public static int minSwaps(String num, int k) {
        char[] target = num.toCharArray();
        for (int step = 0; step < k; step++) {
            int i = target.length - 2;
            while (i >= 0 && target[i] >= target[i + 1]) i--;
            int j = target.length - 1;
            while (target[j] <= target[i]) j--;
            char temp = target[i];
            target[i] = target[j];
            target[j] = temp;
            int left = i + 1, right = target.length - 1;
            while (left < right) {
                char t = target[left];
                target[left] = target[right];
                target[right] = t;
                left++;
                right--;
            }
        }
        char[] orig = num.toCharArray();
        int swaps = 0;
        for (int i = 0; i < orig.length; i++) {
            if (orig[i] == target[i]) continue;
            int j = i + 1;
            while (orig[j] != target[i]) j++;
            while (j > i) {
                char t = orig[j];
                orig[j] = orig[j - 1];
                orig[j - 1] = t;
                swaps++;
                j--;
            }
        }
        return swaps;
    }
}

