class Solution {
    public static int[] minInterval(int[][] intervals, int[] queries) {
        int[][] sortedIntervals = intervals.clone();
        Arrays.sort(sortedIntervals, (a, b) -> Integer.compare(a[0], b[0]));
        int n = queries.length;
        int[][] qWithIdx = new int[n][2];
        for (int i = 0; i < n; i++) {
            qWithIdx[i][0] = queries[i];
            qWithIdx[i][1] = i;
        }
        Arrays.sort(qWithIdx, (a, b) -> Integer.compare(a[0], b[0]));
        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> {
            if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
            return Integer.compare(a[1], b[1]);
        });
        int[] ans = new int[n];
        Arrays.fill(ans, -1);
        int intPtr = 0;
        for (int[] qPair : qWithIdx) {
            int q = qPair[0];
            int idx = qPair[1];
            while (intPtr < sortedIntervals.length && sortedIntervals[intPtr][0] <= q) {
                int l = sortedIntervals[intPtr][0];
                int r = sortedIntervals[intPtr][1];
                int size = r - l + 1;
                heap.offer(new int[]{size, r});
                intPtr++;
            }
            while (!heap.isEmpty() && heap.peek()[1] < q) {
                heap.poll();
            }
            if (!heap.isEmpty()) {
                ans[idx] = heap.peek()[0];
            }
        }
        return ans;
    }
}

