class Solution {
    public static int largestPathValue(String colors, int[][] edges) {
        int n = colors.length();
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        int[] indeg = new int[n];
        for (int[] edge : edges) {
            int a = edge[0];
            int b = edge[1];
            adj[a].add(b);
            indeg[b]++;
        }

        int[][] dp = new int[n][26];
        for (int i = 0; i < n; i++) {
            dp[i][colors.charAt(i) - 'a'] = 1;
        }

        Deque<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < n; i++) if (indeg[i] == 0) queue.add(i);
        int processed = 0;
        int answer = 0;

        while (!queue.isEmpty()) {
            int u = queue.poll();
            processed++;
            for (int c = 0; c < 26; c++) {
                if (dp[u][c] > answer) answer = dp[u][c];
            }
            for (int v : adj[u]) {
                for (int c = 0; c < 26; c++) {
                    int cand = dp[u][c] + ((colors.charAt(v) - 'a' == c) ? 1 : 0);
                    if (cand > dp[v][c]) dp[v][c] = cand;
                }
                if (--indeg[v] == 0) queue.add(v);
            }
        }

        return processed == n ? answer : -1;
    }
}

