import java.math.BigInteger;

class Solution {
    public static int maxSumMinProduct(int[] nums) {
        int n = nums.length;
        BigInteger MOD = BigInteger.valueOf(1_000_000_007L);
        BigInteger[] pref = new BigInteger[n + 1];
        pref[0] = BigInteger.ZERO;
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i].add(BigInteger.valueOf(nums[i]));
        }
        int[] left = new int[n];
        int[] right = new int[n];
        int[] stack = new int[n];
        int top = -1;
        for (int i = 0; i < n; i++) {
            while (top >= 0 && nums[stack[top]] >= nums[i]) {
                top--;
            }
            left[i] = (top >= 0) ? stack[top] : -1;
            stack[++top] = i;
        }
        top = -1;
        for (int i = n - 1; i >= 0; i--) {
            while (top >= 0 && nums[stack[top]] >= nums[i]) {
                top--;
            }
            right[i] = (top >= 0) ? stack[top] : n;
            stack[++top] = i;
        }
        BigInteger best = BigInteger.ZERO;
        for (int i = 0; i < n; i++) {
            BigInteger sum = pref[right[i]].subtract(pref[left[i] + 1]);
            BigInteger prod = BigInteger.valueOf(nums[i]).multiply(sum);
            if (prod.compareTo(best) > 0) {
                best = prod;
            }
        }
        return best.mod(MOD).intValue();
    }
}

public class Solution {
