class FindSumPairs {
    private final int[] nums1;
    private final int[] nums2;
    private final Map<Integer,Integer> freq;
    public FindSumPairs(int[] nums1, int[] nums2) {
        this.nums1 = nums1; this.nums2 = nums2;
        freq = new HashMap<>();
        for (int v : nums2) freq.put(v, freq.getOrDefault(v,0)+1);
    }
    public void add(int index, int val) {
        int oldVal = nums2[index];
        int newVal = oldVal + val;
        nums2[index] = newVal;
        int oldCount = freq.get(oldVal);
        if (oldCount == 1) freq.remove(oldVal); else freq.put(oldVal, oldCount-1);
        freq.put(newVal, freq.getOrDefault(newVal,0)+1);
    }
    public int count(int tot) {
        int pairs = 0;
        for (int x : nums1) pairs += freq.getOrDefault(tot-x, 0);
        return pairs;
    }
}

