class Solution {
    public static char[][] rotateTheBox(char[][] boxGrid) {
        int m = boxGrid.length;
        int n = boxGrid[0].length;
        for (int i = 0; i < m; i++) {
            int empty = 0;
            for (int j = n - 1; j >= 0; j--) {
                char cell = boxGrid[i][j];
                if (cell == '.') {
                    empty++;
                } else if (cell == '*') {
                    empty = 0;
                } else if (cell == '#') {
                    if (empty > 0) {
                        boxGrid[i][j] = '.';
                        boxGrid[i][j + empty] = '#';
                    }
                }
            }
        }
        char[][] result = new char[n][m];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                result[j][m - 1 - i] = boxGrid[i][j];
            }
        }
        return result;
    }
}

