class Solution {
    public static long sumOfFlooredPairs(int[] nums) {
        if (nums == null || nums.length == 0) {
            return 0L;
        }
        int max = 0;
        for (int v : nums) {
            if (v > max) {
                max = v;
            }
        }
        int[] cnt = new int[max + 1];
        for (int v : nums) {
            cnt[v]++;
        }
        int[] pref = new int[max + 1];
        for (int i = 1; i <= max; i++) {
            pref[i] = pref[i - 1] + cnt[i];
        }
        long ans = 0L;
        for (int d = 1; d <= max; d++) {
            int cd = cnt[d];
            if (cd == 0) continue;
            for (int multiple = d; multiple <= max; multiple += d) {
                int k = multiple / d;
                int left = multiple;
                int right = Math.min(multiple + d - 1, max);
                int rangeCount = pref[right] - pref[left - 1];
                if (rangeCount == 0) continue;
                ans += (long) cd * k * rangeCount;
            }
        }
        return ans;
    }
}

