class Solution {
    public static int minSwaps(String s) {
        int n = s.length();
        int zeros = 0, ones = 0;
        for (int i = 0; i < n; i++) {
            char ch = s.charAt(i);
            if (ch == '0') zeros++;
            else ones++;
        }
        int ans = Math.min(swapsIfPossible(s, zeros, ones, '0'), swapsIfPossible(s, zeros, ones, '1'));
        return ans == Integer.MAX_VALUE ? -1 : ans;
    }

    private static int swapsIfPossible(String s, int zeros, int ones, char startChar) {
        int n = s.length();
        int needZeros = (startChar == '0') ? (n + 1) / 2 : n / 2;
        int needOnes = n - needZeros;
        if (zeros != needZeros || ones != needOnes) return Integer.MAX_VALUE;
        int zeroToOne = 0;
        for (int i = 0; i < n; i++) {
            char expected = (i % 2 == 0) ? startChar : (startChar == '0' ? '1' : '0');
            char actual = s.charAt(i);
            if (actual != expected) {
                if (actual == '0') zeroToOne++;
            }
        }
        return zeroToOne;
    }
}

class Solution {
    public static boolean longerOnesThanZeros(String s) {
        int maxOnes = 0, maxZeros = 0;
        char currChar = s.charAt(0);
        int currLen = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == currChar) {
                currLen++;
            } else {
                if (currChar == '1') maxOnes = Math.max(maxOnes, currLen);
                else maxZeros = Math.max(maxZeros, currLen);
                currChar = s.charAt(i);
                currLen = 1;
            }
        }
        if (currChar == '1') maxOnes = Math.max(maxOnes, currLen);
        else maxZeros = Math.max(maxZeros, currLen);
        return maxOnes > maxZeros;
    }
}

public class Solution {
    public static long rearrangeSticks(int n, int k) {
        final long MOD = 1_000_000_007L;
        if (k > n) return 0L;
        long[] dp = new long[k + 1];
        dp[0] = 1L;
        for (int i = 1; i <= n; i++) {
            long[] ndp = new long[k + 1];
            int limit = Math.min(i, k);
            for (int j = 1; j <= limit; j++) {
                ndp[j] = (dp[j - 1] + (long) (i - 1) * dp[j]) % MOD;
            }
            dp = ndp;
        }
        return dp[k];
    }
}

