class Solution {
    public static int minSpeedOnTime(int[] dist, double hour) {
        int n = dist.length;
        if (hour < n - 1) return -1;
        int lo = 1, hi = 10000000;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (can(mid, dist, hour)) hi = mid;
            else lo = mid + 1;
        }
        return can(lo, dist, hour) ? lo : -1;
    }

    private static boolean can(int speed, int[] dist, double hour) {
        int n = dist.length;
        double total = 0.0;
        for (int i = 0; i < n - 1; ++i) {
            total += Math.ceil((double) dist[i] / speed);
        }
        total += (double) dist[n - 1] / speed;
        return total <= hour + 1e-9;
    }
}

class Solution {
    public static boolean canReach(String s, int minJump, int maxJump) {
        int n = s.length();
        if (s.charAt(0) != '0' || s.charAt(n - 1) != '0') return false;
        boolean[] reachable = new boolean[n];
        reachable[0] = true;
        int windowSum = 0;
        for (int i = 1; i < n; i++) {
            if (i - minJump >= 0 && reachable[i - minJump]) {
                windowSum++;
            }
            if (i - maxJump - 1 >= 0 && reachable[i - maxJump - 1]) {
                windowSum--;
            }
            if (s.charAt(i) == '0' && windowSum > 0) {
                reachable[i] = true;
            }
        }
        return reachable[n - 1];
    }
}

