class Solution {
    public static int[] getBiggestThree(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int[][] diag1 = new int[m][n];
        int[][] diag2 = new int[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                diag1[i][j] = grid[i][j] + (i > 0 && j > 0 ? diag1[i - 1][j - 1] : 0);
                diag2[i][j] = grid[i][j] + (i > 0 && j + 1 < n ? diag2[i - 1][j + 1] : 0);
            }
        }
        Set<Integer> seen = new HashSet<>();
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (seen.add(grid[i][j])) {
                    pq.offer(grid[i][j]);
                    if (pq.size() > 3) pq.poll();
                }
                int maxK = Math.min((m - i - 1) / 2, Math.min(j, n - j - 1));
                for (int k = 1; k <= maxK; k++) {
                    int topI = i, topJ = j;
                    int leftI = i + k, leftJ = j - k;
                    int bottomI = i + 2 * k, bottomJ = j;
                    int rightI = i + k, rightJ = j + k;
                    int sum1 = diag2[leftI][leftJ] - (topI > 0 && topJ + 1 < n ? diag2[topI - 1][topJ + 1] : 0);
                    int sum2 = diag1[bottomI][bottomJ] - (leftI > 0 && leftJ > 0 ? diag1[leftI - 1][leftJ - 1] : 0);
                    int sum3 = diag2[bottomI][bottomJ] - (rightI > 0 && rightJ + 1 < n ? diag2[rightI - 1][rightJ + 1] : 0);
                    int sum4 = diag1[rightI][rightJ] - (topI > 0 && topJ > 0 ? diag1[topI - 1][topJ - 1] : 0);
                    int total = sum1 + sum2 + sum3 + sum4
                            - (grid[topI][topJ] + grid[leftI][leftJ] + grid[bottomI][bottomJ] + grid[rightI][rightJ]);
                    if (seen.add(total)) {
                        pq.offer(total);
                        if (pq.size() > 3) pq.poll();
                    }
                }
            }
        }
        int size = pq.size();
        int[] result = new int[size];
        for (int i = size - 1; i >= 0; i--) {
            result[i] = pq.poll();
        }
        return result;
    }
}

