public class Solution {
    public static long stoneGameVIII(int[] stones) {
        int n = stones.length;
        long[] pref = new long[n];
        pref[0] = stones[0];
        for (int i = 1; i < n; i++) {
            pref[i] = pref[i - 1] + stones[i];
        }
        long best = Long.MIN_VALUE;
        long nextDP = 0;
        for (int i = n - 2; i >= 0; i--) {
            long candidate = pref[i + 1] - nextDP;
            if (candidate > best) {
                best = candidate;
            }
            nextDP = best;
        }
        return best;
    }
}

