class Solution {
    private static class Server {
        int w;
        int i;
        Server(int w, int i) {
            this.w = w;
            this.i = i;
        }
    }

    private static class BusyServer {
        long time;
        int w;
        int i;
        BusyServer(long time, int w, int i) {
            this.time = time;
            this.w = w;
            this.i = i;
        }
    }

    public static int[] assignTasks(int[] servers, int[] tasks) {
        int n = servers.length;
        int m = tasks.length;

        PriorityQueue<Server> free = new PriorityQueue<>(new Comparator<Server>() {
            public int compare(Server a, Server b) {
                if (a.w != b.w) return a.w - b.w;
                return a.i - b.i;
            }
        });

        PriorityQueue<BusyServer> busy = new PriorityQueue<>(new Comparator<BusyServer>() {
            public int compare(BusyServer a, BusyServer b) {
                if (a.time != b.time) return Long.compare(a.time, b.time);
                if (a.w != b.w) return a.w - b.w;
                return a.i - b.i;
            }
        });

        for (int i = 0; i < n; ++i) {
            free.add(new Server(servers[i], i));
        }

        int[] ans = new int[m];
        long curTime = 0;

        for (int j = 0; j < m; ++j) {
            curTime = Math.max(curTime, j);

            while (!busy.isEmpty() && busy.peek().time <= curTime) {
                BusyServer s = busy.poll();
                free.add(new Server(s.w, s.i));
            }

            if (free.isEmpty()) {
                curTime = busy.peek().time;
                while (!busy.isEmpty() && busy.peek().time <= curTime) {
                    BusyServer s = busy.poll();
                    free.add(new Server(s.w, s.i));
                }
            }

            Server srv = free.poll();
            ans[j] = srv.i;
            busy.add(new BusyServer(curTime + tasks[j], srv.w, srv.i));
        }

        return ans;
    }
}

import java.util.Arrays;

class Solution {
    public static int minSkips(double[] dist, double speed, double hoursBefore) {
        int n = dist.length;
        if (canFinish(dist, speed, hoursBefore, 0)) return 0;
        int lo = 1, hi = n - 1, answer = -1;
        while (lo <= hi) {
            int mid = (lo + hi) >> 1;
            if (canFinish(dist, speed, hoursBefore, mid)) {
                answer = mid;
                hi = mid - 1;
            } else {
                lo = mid + 1;
            }
        }
        return answer;
    }

    private static boolean canFinish(double[] dist, double speed, double hoursBefore, int maxSkips) {
        int n = dist.length;
        double INF = 1e30;
        double[] dp = new double[maxSkips + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0.0;
        for (int i = 0; i < n; ++i) {
            double[] ndp = new double[maxSkips + 1];
            Arrays.fill(ndp, INF);
            double travel = dist[i] / speed;
            for (int used = 0; used <= maxSkips; ++used) {
                if (dp[used] == INF) continue;
                double arrive = dp[used] + travel;
                if (i == n - 1) {
                    ndp[used] = Math.min(ndp[used], arrive);
                } else {
                    double wait = Math.ceil(arrive);
                    ndp[used] = Math.min(ndp[used], wait);
                    if (used < maxSkips) {
                        ndp[used + 1] = Math.min(ndp[used + 1], arrive);
                    }
                }
            }
            dp = ndp;
        }
        for (int used = 0; used <= maxSkips; ++used) {
            if (dp[used] <= hoursBefore + 1e-9) return true;
        }
        return false;
    }
}

import java.util.Arrays;

class Solution {
    public static long minimumXORSum(int[] nums1, int[] nums2) {
        int n = nums1.length;
        int fullMask = (1 << n) - 1;
        long INF = (long) 1e15;
        long[] dp = new long[1 << n];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int mask = 0; mask <= fullMask; ++mask) {
            int k = Integer.bitCount(mask);
            if (k >= n) continue;
            long cur = dp[mask];
            for (int j = 0; j < n; ++j) {
                if ((mask & (1 << j)) == 0) {
                    int newMask = mask | (1 << j);
                    long cand = cur + (nums1[k] ^ nums2[j]);
                    if (cand < dp[newMask]) dp[newMask] = cand;
                }
            }
        }
        return dp[fullMask];
    }
}

