            char expectedA = (i % 2 == 0) ? '0' : '1';
            char expectedB = (i % 2 == 0) ? '1' : '0';
            if (ch != expectedA) diffA++;
            if (ch != expectedB) diffB++;
            if (i >= n) {
                int j = i - n;
                char left = doubled.charAt(j);
                char leftExpA = (j % 2 == 0) ? '0' : '1';
                char leftExpB = (j % 2 == 0) ? '1' : '0';
                if (left != leftExpA) diffA--;
                if (left != leftExpB) diffB--;
            }
            if (i >= n - 1) {
                best = Math.min(best, Math.min(diffA, diffB));
            }
        }
        return best;
    }
}

import java.util.Arrays;

class Solution {
    private static final int MOD = 1_000_000_007;

    private static int upperBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] <= target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    public static int minWastedSpace(int[] packages, int[][] boxes) {
        Arrays.sort(packages);
        int n = packages.length;
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + packages[i];
        }

        long best = Long.MAX_VALUE;

        for (int[] supplier : boxes) {
            Arrays.sort(supplier);
            if (supplier[supplier.length - 1] < packages[n - 1]) {
                continue;
            }

            long waste = 0;
            int prevIdx = 0;

            for (int size : supplier) {
                int idx = upperBound(packages, size);
                int cnt = idx - prevIdx;
                if (cnt > 0) {
                    waste += (long) size * cnt - (prefix[idx] - prefix[prevIdx]);
                }
                prevIdx = idx;
                if (prevIdx == n) {
                    break;
                }
            }

            if (prevIdx == n) {
                best = Math.min(best, waste);
            }
        }

        return best == Long.MAX_VALUE ? -1 : (int) (best % MOD);
    }
}

