class Solution {
    public static boolean isCovered(int[][] ranges, int left, int right) {
        int maxCoord = right;
        for (int i = 0; i < ranges.length; i++) {
            if (ranges[i][1] > maxCoord) maxCoord = ranges[i][1];
        }
        int[] diff = new int[maxCoord + 2];
        for (int i = 0; i < ranges.length; i++) {
            int start = ranges[i][0];
            int end = ranges[i][1];
            diff[start] += 1;
            diff[end + 1] -= 1;
        }
        int cur = 0;
        for (int x = 0; x <= maxCoord; x++) {
            cur += diff[x];
            if (x >= left && x <= right && cur == 0) return false;
        }
        return true;
    }
}

