class Solution {
    public static int findStudent(int[] chalk, int k) {
        long total = 0;
        for (int value : chalk) {
            total += value;
        }
        long remaining = k % total;
        long prefix = 0;
        long[] prefixSum = new long[chalk.length];
        for (int i = 0; i < chalk.length; i++) {
            prefix += chalk[i];
            prefixSum[i] = prefix;
        }
        int left = 0, right = chalk.length - 1;
        while (left <= right) {
            int mid = (left + right) >> 1;
            if (prefixSum[mid] <= remaining) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return left;
    }
}

