class Solution {
    public static int largestMagicSquare(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int[][] rowPref = new int[m][n + 1];
        int[][] colPref = new int[m + 1][n];
        int[][] diag1 = new int[m + 1][n + 1];
        int[][] diag2 = new int[m + 1][n + 1];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                rowPref[i][j + 1] = rowPref[i][j] + grid[i][j];
                colPref[i + 1][j] = colPref[i][j] + grid[i][j];
                diag1[i + 1][j + 1] = diag1[i][j] + grid[i][j];
                diag2[i + 1][j] = diag2[i][j + 1] + grid[i][j];
            }
        }

        int maxK = Math.min(m, n);
        for (int k = maxK; k >= 1; k--) {
            for (int i = 0; i + k <= m; i++) {
                for (int j = 0; j + k <= n; j++) {
                    int target = rowPref[i][j + k] - rowPref[i][j];
                    boolean ok = true;

                    for (int r = i; r < i + k; r++) {
                        if (rowPref[r][j + k] - rowPref[r][j] != target) {
                            ok = false;
                            break;
                        }
                    }
                    if (!ok) continue;

                    for (int c = j; c < j + k; c++) {
                        if (colPref[i + k][c] - colPref[i][c] != target) {
                            ok = false;
                            break;
                        }
                    }
                    if (!ok) continue;

                    if (diag1[i + k][j + k] - diag1[i][j] != target) continue;
                    if (diag2[i + k][j] - diag2[i][j + k] != target) continue;

                    return k;
                }
            }
        }
        return 1;
    }
}

public class Solution {
    public static boolean mergeTriplets(int[][] triplets, int[] target) {
        int needA = target[0], needB = target[1], needC = target[2];
        int curA = 0, curB = 0, curC = 0;
        for (int i = 0; i < triplets.length; i++) {
            int a = triplets[i][0], b = triplets[i][1], c = triplets[i][2];
            if (a <= needA && b <= needB && c <= needC) {
                if (a > curA) curA = a;
                if (b > curB) curB = b;
                if (c > curC) curC = c;
            }
        }
        return curA == needA && curB == needB && curC == needC;
    }
}

