class Solution {
    public static int maximumRemovals(String s, String p, int[] removable) {
        int n = s.length();
        int[] order = new int[n];
        Arrays.fill(order, Integer.MAX_VALUE);
        for (int i = 0; i < removable.length; i++) {
            order[removable[i]] = i;
        }
        int lo = 0, hi = removable.length;
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            if (can(s, p, order, mid)) {
                lo = mid;
            } else {
                hi = mid - 1;
            }
        }
        return lo;
    }

    private static boolean can(String s, String p, int[] order, int k) {
        int j = 0;
        for (int i = 0; i < s.length() && j < p.length(); i++) {
            if (order[i] < k) continue;
            if (s.charAt(i) == p.charAt(j)) j++;
        }
        return j == p.length();
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public static int minOperations(String expression) {
        Deque<int[]> values = new ArrayDeque<>();
        Deque<Character> ops = new ArrayDeque<>();
        int n = expression.length();
        for (int i = 0; i < n; i++) {
            char c = expression.charAt(i);
            if (c == '0' || c == '1') {
                int[] leaf = new int[2];
                if (c == '0') {
                    leaf[0] = 0;
                    leaf[1] = 1;
                } else {
                    leaf[0] = 1;
                    leaf[1] = 0;
                }
                values.push(leaf);
            } else if (c == '(') {
                ops.push(c);
            } else if (c == '&' || c == '|') {
                while (!ops.isEmpty() && ops.peek() != '(' && precedence(ops.peek()) >= precedence(c)) {
                    evaluateTop(values, ops);
                }
                ops.push(c);
            } else if (c == ')') {
                while (!ops.isEmpty() && ops.peek() != '(') {
                    evaluateTop(values, ops);
                }
                if (!ops.isEmpty() && ops.peek() == '(') {
                    ops.pop();
                }
            }
        }
        while (!ops.isEmpty()) {
            evaluateTop(values, ops);
        }
        int[] finalCosts = values.pop();
        return finalCosts[0] == 0 ? finalCosts[1] : finalCosts[0];
    }

    private static void evaluateTop(Deque<int[]> values, Deque<Character> ops) {
        char op = ops.pop();
        int[] right = values.pop();
        int[] left = values.pop();
        values.push(combine(left, right, op));
    }

    private static int[] combine(int[] left, int[] right, char op) {
        int[] keep = computeCost(left, right, op);
        int[] flip = computeCost(left, right, op == '&' ? '|' : '&');
        int cost0 = Math.min(keep[0], flip[0] + 1);
        int cost1 = Math.min(keep[1], flip[1] + 1);
        return new int[]{cost0, cost1};
    }

    private static int[] computeCost(int[] left, int[] right, char op) {
        int l0 = left[0], l1 = left[1];
        int r0 = right[0], r1 = right[1];
        if (op == '&') {
            int cost0 = Math.min(l0 + r0, Math.min(l0 + r1, l1 + r0));
            int cost1 = l1 + r1;
            return new int[]{cost0, cost1};
        } else { // '|'
            int cost0 = l0 + r0;
            int cost1 = Math.min(l1 + r1, Math.min(l1 + r0, l0 + r1));
            return new int[]{cost0, cost1};
        }
    }

    private static int precedence(char op) {
        return op == '&' ? 2 : 1;
    }
}

