    }
}

import java.util.*;

class Solution {
    public static int[] minimumAbsoluteDifferenceQueries(int[] nums, int[][] queries) {
        int n = nums.length;
        int q = queries.length;
        int blockSize = (int) Math.sqrt(n) + 1;
        Query[] qs = new Query[q];
        for (int i = 0; i < q; i++) {
            qs[i] = new Query(queries[i][0], queries[i][1], i);
        }
        Arrays.sort(qs, (a, b) -> {
            int blockA = a.l / blockSize;
            int blockB = b.l / blockSize;
            if (blockA != blockB) return blockA - blockB;
            return (blockA & 1) == 0 ? a.r - b.r : b.r - a.r;
        });
        int[] ans = new int[q];
        HashMap<Integer, Integer> freq = new HashMap<>();
        TreeSet<Integer> set = new TreeSet<>();
        TreeMap<Integer, Integer> diffCounts = new TreeMap<>();
        int curL = 0, curR = -1;
        for (Query query : qs) {
            while (curL > query.l) add(--curL, nums, freq, set, diffCounts);
            while (curR < query.r) add(++curR, nums, freq, set, diffCounts);
            while (curL < query.l) remove(curL++, nums, freq, set, diffCounts);
            while (curR > query.r) remove(curR--, nums, freq, set, diffCounts);
            if (set.size() < 2) {
                ans[query.idx] = -1;
            } else {
                ans[query.idx] = diffCounts.firstKey();
            }
        }
        return ans;
    }

    private static void add(int idx, int[] nums, HashMap<Integer, Integer> freq,
                            TreeSet<Integer> set, TreeMap<Integer, Integer> diffCounts) {
        int x = nums[idx];
        int cnt = freq.getOrDefault(x, 0);
        if (cnt == 0) {
            Integer lower = set.lower(x);
            Integer higher = set.higher(x);
            if (lower != null) {
                int d = x - lower;
                diffCounts.put(d, diffCounts.getOrDefault(d, 0) + 1);
            }
            if (higher != null) {
                int d = higher - x;
                diffCounts.put(d, diffCounts.getOrDefault(d, 0) + 1);
            }
            if (lower != null && higher != null) {
                int d = higher - lower;
                decrement(diffCounts, d);
            }
            set.add(x);
        }
        freq.put(x, cnt + 1);
    }

    private static void remove(int idx, int[] nums, HashMap<Integer, Integer> freq,
                               TreeSet<Integer> set, TreeMap<Integer, Integer> diffCounts) {
        int x = nums[idx];
        int cnt = freq.get(x);
        if (cnt == 1) {
            Integer lower = set.lower(x);
            Integer higher = set.higher(x);
            if (lower != null) {
                int d = x - lower;
                decrement(diffCounts, d);
            }
            if (higher != null) {
                int d = higher - x;
                decrement(diffCounts, d);
            }
            if (lower != null && higher != null) {
                int d = higher - lower;
                diffCounts.put(d, diffCounts.getOrDefault(d, 0) + 1);
            }
            set.remove(x);
            freq.remove(x);
        } else {
            freq.put(x, cnt - 1);
        }
    }

    private static void decrement(TreeMap<Integer, Integer> map, int key) {
        int c = map.get(key);
        if (c == 1) map.remove(key);
        else map.put(key, c - 1);
    }

    private static class Query {
        int l, r, idx;
        Query(int l, int r, int idx) {
            this.l = l;
            this.r = r;
            this.idx = idx;
        }
    }
}

class Solution {
    Map<Long, int[]> memo = new HashMap<>();

    long key(int l, int r, int n) {
        return ((long) l * 40 + r) * 40 + n;
    }

    int[] dfs(int l, int r, int n) {
        if (l + r == n - 1) return new int[]{1, 1};
        long k = key(l, r, n);
        if (memo.containsKey(k)) return memo.get(k);
        int mn = Integer.MAX_VALUE, mx = Integer.MIN_VALUE;
        int m = n >> 1;
        for (int i = 0; i < (1 << m); i++) {
            boolean[] win = new boolean[n];
            for (int j = 0; j < m; j++) {
                if (((i >> j) & 1) != 0) win[j] = true;
                else win[n-1-j] = true;
            }
            if ((n & 1) != 0) win[m] = true;
            win[n-1-l] = false;
            win[n-1-r] = false;
            win[l] = true;
            win[r] = true;
            int a = 0, b = 0, c = 0;
            for (int j = 0; j < n; j++) {
                if (j == l) a = c;
                if (j == r) b = c;
                if (win[j]) c++;
            }
            int[] res = dfs(a, b, c);
            mn = Math.min(mn, res[0] + 1);
            mx = Math.max(mx, res[1] + 1);
        }
        int[] result = new int[]{mn, mx};
        memo.put(k, result);
        return result;
    }

    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        memo.clear();
        return dfs(firstPlayer-1, secondPlayer-1, n);
    }
}

