class Solution {
    public static int[] findPeakGrid(int[][] mat) {
        int rows = mat.length;
        int cols = mat[0].length;
        int top = 0, bottom = rows - 1;
        while (top <= bottom) {
            int midRow = top + (bottom - top) / 2;
            int maxCol = 0;
            for (int c = 1; c < cols; c++) {
                if (mat[midRow][c] > mat[midRow][maxCol]) {
                    maxCol = c;
                }
            }
            int upVal = (midRow > 0) ? mat[midRow - 1][maxCol] : Integer.MIN_VALUE;
            int downVal = (midRow < rows - 1) ? mat[midRow + 1][maxCol] : Integer.MIN_VALUE;
            int curVal = mat[midRow][maxCol];
            if (curVal > upVal && curVal > downVal) {
                return new int[]{midRow, maxCol};
            }
            if (upVal > curVal) {
                bottom = midRow - 1;
            } else {
                top = midRow + 1;
            }
        }
        return null;
    }
}

