public class Solution {
    public static long maxAlternatingSum(int[] nums) {
        long bestEven = 0;
        long bestOdd = Long.MIN_VALUE;
        for (int v : nums) {
            long x = v;
            long newEven = Math.max(bestEven, bestOdd + x);
            newEven = Math.max(newEven, x);
            long newOdd = Math.max(bestOdd, bestEven - x);
            bestEven = newEven;
            bestOdd = newOdd;
        }
        return bestEven;
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public static int countSubIslands(int[][] grid1, int[][] grid2) {
        int m = grid1.length;
        int n = grid1[0].length;
        int subCount = 0;
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid2[i][j] == 1) {
                    Deque<int[]> stack = new ArrayDeque<>();
                    boolean isSub = true;
                    grid2[i][j] = 0;
                    stack.push(new int[]{i, j});
                    while (!stack.isEmpty()) {
                        int[] pos = stack.pop();
                        int x = pos[0];
                        int y = pos[1];
                        if (grid1[x][y] == 0) {
                            isSub = false;
                        }
                        for (int[] d : dirs) {
                            int nx = x + d[0];
                            int ny = y + d[1];
                            if (nx >= 0 && nx < m && ny >= 0 && ny < n && grid2[nx][ny] == 1) {
                                grid2[nx][ny] = 0;
                                stack.push(new int[]{nx, ny});
                            }
                        }
                    }
                    if (isSub) {
                        subCount++;
                    }
                }
            }
        }
        return subCount;
    }
}

class Solution {
    public static int maxProductDifference(int[] nums) {
        int max1 = Integer.MIN_VALUE, max2 = Integer.MIN_VALUE;
        int min1 = Integer.MAX_VALUE, min2 = Integer.MAX_VALUE;
        for (int i = 0; i < nums.length; i++) {
            int v = nums[i];
            if (v > max1) { max2 = max1; max1 = v; }
            else if (v > max2) { max2 = v; }
            if (v < min1) { min2 = min1; min1 = v; }
            else if (v < min2) { min2 = v; }
        }
        return max1 * max2 - min1 * min2;
    }
}

