class Solution {
    public static String removeOccurrences(String s, String part) {
        int m = part.length();
        int[] lps = new int[m];
        for (int i = 1, len = 0; i < m; ) {
            if (part.charAt(i) == part.charAt(len)) {
                lps[i++] = ++len;
            } else if (len != 0) {
                len = lps[len - 1];
            } else {
                lps[i++] = 0;
            }
        }
        int n = s.length();
        char[] stack = new char[n];
        int[] matchStack = new int[n];
        int top = 0;
        for (int i = 0; i < n; i++) {
            char ch = s.charAt(i);
            stack[top] = ch;
            int k = top > 0 ? matchStack[top - 1] : 0;
            while (k > 0 && ch != part.charAt(k)) {
                k = lps[k - 1];
            }
            if (ch == part.charAt(k)) {
                k++;
            }
            matchStack[top] = k;
            top++;
            if (k == m) {
                top -= m;
            }
        }
        return new String(stack, 0, top);
    }
}

