            }
        }
        return true;
    }
}

import java.util.ArrayList;
import java.util.List;

class Solution {
    public static int[][] rotateGrid(int[][] grid, int k) {
        int rows = grid.length;
        int cols = grid[0].length;
        int layers = Math.min(rows, cols) / 2;
        for (int layer = 0; layer < layers; layer++) {
            int top = layer, left = layer;
            int bottom = rows - 1 - layer, right = cols - 1 - layer;
            List<Integer> vals = new ArrayList<>();
            for (int c = left; c <= right; c++) vals.add(grid[top][c]);
            for (int r = top + 1; r < bottom; r++) vals.add(grid[r][right]);
            for (int c = right; c >= left; c--) vals.add(grid[bottom][c]);
            for (int r = bottom - 1; r > top; r--) vals.add(grid[r][left]);
            int len = vals.size();
            int shift = k % len;
            List<Integer> shifted = new ArrayList<>(len);
            for (int i = 0; i < len; i++) {
                shifted.add(vals.get((i + shift) % len));
            }
            int idx = 0;
            for (int c = left; c <= right; c++) grid[top][c] = shifted.get(idx++);
            for (int r = top + 1; r < bottom; r++) grid[r][right] = shifted.get(idx++);
            for (int c = right; c >= left; c--) grid[bottom][c] = shifted.get(idx++);
            for (int r = bottom - 1; r > top; r--) grid[r][left] = shifted.get(idx++);
        }
        return grid;
    }
}

import java.util.*;
class MovieRentingSystem {
    Map<Long,Integer> priceMap = new HashMap<>();
    Map<Integer, TreeSet<int[]>> available = new HashMap<>();
    TreeSet<int[]> rentedOrdered = new TreeSet<>((a,b) -> {
        if (a[0]!=b[0]) return a[0]-b[0];
        if (a[1]!=b[1]) return a[1]-b[1];
        return a[2]-b[2];
    });
    Set<Long> rentedPairs = new HashSet<>();
    long key(int shop, int movie) { return (long) shop * 1_000_000L + movie; }
    public MovieRentingSystem(int n, int[][] entries) {
        for (int[] e : entries) {
            int shop = e[0], movie = e[1], price = e[2];
            priceMap.put(key(shop, movie), price);
            available.computeIfAbsent(movie, k -> new TreeSet<>((a,b) -> a[0]!=b[0] ? a[0]-b[0] : a[1]-b[1]))
                     .add(new int[]{price, shop});
        }
    }
    public List<Integer> search(int movie) {
        List<Integer> result = new ArrayList<>();
        TreeSet<int[]> set = available.get(movie);
        if (set == null) return result;
        for (int[] entry : set) {
            if (result.size() >= 5) break;
            result.add(entry[1]);
        }
        return result;
    }
    public void rent(int shop, int movie) {
        int price = priceMap.get(key(shop, movie));
        removeByValue(available.get(movie), price, shop);
        rentedPairs.add(key(shop, movie));
        rentedOrdered.add(new int[]{price, shop, movie});
    }
    private void removeByValue(TreeSet<int[]> set, int price, int shop) {
        Iterator<int[]> it = set.iterator();
        while (it.hasNext()) { int[] e = it.next(); if (e[0]==price && e[1]==shop) { it.remove(); return; } }
    }
    public void drop(int shop, int movie) {
        int price = priceMap.get(key(shop, movie));
        rentedPairs.remove(key(shop, movie));
        Iterator<int[]> it = rentedOrdered.iterator();
        while (it.hasNext()) { int[] e = it.next(); if (e[0]==price && e[1]==shop && e[2]==movie) { it.remove(); break; } }
        available.computeIfAbsent(movie, k -> new TreeSet<>((a,b) -> a[0]!=b[0] ? a[0]-b[0] : a[1]-b[1]))
                 .add(new int[]{price, shop});
    }
    public List<List<Integer>> report() {
        List<List<Integer>> result = new ArrayList<>();
        for (int[] e : rentedOrdered) {
            if (result.size() >= 5) break;
            result.add(Arrays.asList(e[1], e[2]));
        }
        return result;
    }
}

