class Solution {
    public static int eliminateMaximum(int[] dist, int[] speed) {
        int n = dist.length;
        int[] deadline = new int[n];
        for (int i = 0; i < n; i++) {
            deadline[i] = (dist[i] + speed[i] - 1) / speed[i];
        }
        Arrays.sort(deadline);
        int killed = 0;
        for (int i = 0; i < n; i++) {
            if (deadline[i] <= i) break;
            killed++;
        }
        return killed;
    }
}

import java.util.*;

class Solution {
    private static final long MOD = 1_000_000_007L;

    public static int waysToBuildRooms(int[] prevRoom) {
        int n = prevRoom.length;
        @SuppressWarnings("unchecked")
        ArrayList<Integer>[] children = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            children[i] = new ArrayList<>();
        }
        for (int i = 1; i < n; i++) {
            children[prevRoom[i]].add(i);
        }

        long[] fact = new long[n + 1];
        long[] invFact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[n] = modPow(fact[n], MOD - 2);
        for (int i = n; i > 0; i--) {
            invFact[i - 1] = invFact[i] * i % MOD;
        }

        int[] size = new int[n];
        long[] ways = new long[n];

        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{0, 0}); // node, state (0 = first visit, 1 = after children)

        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            int node = cur[0];
            int state = cur[1];
            if (state == 0) {
                stack.push(new int[]{node, 1});
                for (int child : children[node]) {
                    stack.push(new int[]{child, 0});
                }
            } else {
                int total = 0;
                long w = 1;
                for (int child : children[node]) {
                    total += size[child];
                    w = w * ways[child] % MOD;
                }
                w = w * fact[total] % MOD;
                for (int child : children[node]) {
                    w = w * invFact[size[child]] % MOD;
                }
                size[node] = total + 1;
                ways[node] = w;
            }
        }

        return (int) ways[0];
    }

    private static long modPow(long base, long exp) {
        long result = 1;
        long b = base % MOD;
        long e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = result * b % MOD;
            }
            b = b * b % MOD;
            e >>= 1;
        }
        return result;
    }
}

