import java.util.Set;

class Solution {
    private static final long MOD1 = 1_000_000_007L;
    private static final long MOD2 = 1_000_000_009L;
    private static final long BASE = 100_007L;

    public static int longestCommonSubpath(int n, int[][] paths) {
        int m = paths.length;
        int minLen = Integer.MAX_VALUE;
        int maxLen = 0;
        for (int[] p : paths) {
            minLen = Math.min(minLen, p.length);
            maxLen = Math.max(maxLen, p.length);
        }
        if (minLen == 0) return 0;

        long[] pow1 = new long[maxLen + 1];
        long[] pow2 = new long[maxLen + 1];
        pow1[0] = pow2[0] = 1;
        for (int i = 1; i <= maxLen; i++) {
            pow1[i] = (pow1[i - 1] * BASE) % MOD1;
            pow2[i] = (pow2[i - 1] * BASE) % MOD2;
        }

        long[][] pref1 = new long[m][];
        long[][] pref2 = new long[m][];
        for (int i = 0; i < m; i++) {
            int len = paths[i].length;
            pref1[i] = new long[len + 1];
            pref2[i] = new long[len + 1];
            for (int j = 0; j < len; j++) {
                pref1[i][j + 1] = (pref1[i][j] * BASE + paths[i][j]) % MOD1;
                pref2[i][j + 1] = (pref2[i][j] * BASE + paths[i][j]) % MOD2;
            }
        }

        int low = 0, high = minLen;
        while (low < high) {
            int mid = (low + high + 1) >>> 1;
            if (existsCommon(mid, paths, pref1, pref2, pow1, pow2)) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return low;
    }

    private static boolean existsCommon(int L, int[][] paths, long[][] pref1, long[][] pref2,
                                         long[] pow1, long[] pow2) {
        if (L == 0) return true;
        Set<Long> common = null;
        for (int i = 0; i < paths.length; i++) {
            int len = paths[i].length;
            if (len < L) return false;
            Set<Long> cur = new HashSet<>();
            for (int start = 0; start + L <= len; start++) {
                int end = start + L;
                long h1 = (pref1[i][end] - (pref1[i][start] * pow1[L]) % MOD1 + MOD1) % MOD1;
                long h2 = (pref2[i][end] - (pref2[i][start] * pow2[L]) % MOD2 + MOD2) % MOD2;
                long key = (h1 << 32) | h2;
                if (common == null) {
                    cur.add(key);
                } else if (common.contains(key)) {
                    cur.add(key);
                }
            }
            if (common == null) {
                common = cur;
            } else {
                common = cur;
                if (common.isEmpty()) return false;
            }
        }
        return !common.isEmpty();
    }
}

import java.lang.Math;

class Solution {
    public static long countSquareSumTriples(int n) {
        long count = 0;
        int limit = (int) Math.sqrt(n) + 1;
        for (int m = 2; m * m <= n; m++) {
            for (int n2 = 1; n2 < m; n2++) {
                if (((m - n2) & 1) == 0) continue;
                if (gcd(m, n2) != 1) continue;
                long a0 = (long) m * m - (long) n2 * n2;
                long b0 = 2L * m * n2;
                long c0 = (long) m * m + (long) n2 * n2;
                if (c0 > n) break;
                for (long k = 1; k * c0 <= n; k++) {
                    long a = k * a0;
                    long b = k * b0;
                    long c = k * c0;
                    if (a <= n && b <= n) {
                        count += 2;
                    }
                }
            }
        }
        return count;
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

class Solution {
    public static boolean sumGame(String num) {
        int n = num.length();
        int half = n / 2;
        long leftSum = 0;
        long rightSum = 0;
        int qLeft = 0;
        int qRight = 0;
        for (int i = 0; i < half; i++) {
            char c = num.charAt(i);
            if (c == '?') {
                qLeft++;
            } else {
                leftSum += c - '0';
            }
        }
        for (int i = half; i < n; i++) {
            char c = num.charAt(i);
            if (c == '?') {
                qRight++;
            } else {
                rightSum += c - '0';
            }
        }
        int totalQ = qLeft + qRight;
        if ((totalQ & 1) == 1) {
            return true;
        }
        long diff = leftSum - rightSum;
        long needed = 9L * (qRight - qLeft) / 2;
        return diff != needed;
    }
}

import java.math.BigInteger;

class Solution {
    public static int countGoodNumbers(int n) {
        final BigInteger MOD = new BigInteger("1000000007");
        long evenCnt = (n + 1L) / 2L;
        long oddCnt = n / 2L;

        BigInteger pow5 = modPow(5L, evenCnt, MOD);
        BigInteger pow4 = modPow(4L, oddCnt, MOD);

        BigInteger ans = pow5.multiply(pow4).mod(MOD);
        return ans.intValue();
    }

    private static BigInteger modPow(long base, long exp, BigInteger mod) {
        BigInteger result = BigInteger.ONE;
        BigInteger b = BigInteger.valueOf(base).mod(mod);
        long e = exp;
        while (e > 0) {
            if ((e & 1L) == 1L) {
                result = result.multiply(b).mod(mod);
            }
            b = b.multiply(b).mod(mod);
            e >>= 1;
        }
        return result;
    }
}

