class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

class Solution {
    private static class NodeInfo {
        TreeNode node;
        long low;
        long high;
        NodeInfo(TreeNode node, long low, long high) {
            this.node = node;
            this.low = low;
            this.high = high;
        }
    }

    public static TreeNode canMerge(TreeNode[] trees) {
        if (trees == null || trees.length == 0) return null;
        Map<Integer, TreeNode> rootMap = new HashMap<>();
        Set<Integer> leafVals = new HashSet<>();
        for (TreeNode root : trees) {
            rootMap.put(root.val, root);
            collectLeaves(root, leafVals);
        }
        TreeNode overallRoot = null;
        for (TreeNode root : trees) {
            if (!leafVals.contains(root.val)) {
                if (overallRoot != null) return null;
                overallRoot = root;
            }
        }
        if (overallRoot == null) return null;
        rootMap.remove(overallRoot.val);
        if (!validateAndMerge(overallRoot, rootMap)) return null;
        return rootMap.isEmpty() ? overallRoot : null;
    }

    private static void collectLeaves(TreeNode root, Set<Integer> leafVals) {
        Deque<TreeNode> stack = new ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            TreeNode node = stack.pop();
            if (node.left == null && node.right == null) {
                leafVals.add(node.val);
            } else {
                if (node.right != null) stack.push(node.right);
                if (node.left != null) stack.push(node.left);
            }
        }
    }

    private static boolean validateAndMerge(TreeNode root, Map<Integer, TreeNode> map) {
        Deque<NodeInfo> stack = new ArrayDeque<>();
        stack.push(new NodeInfo(root, Long.MIN_VALUE, Long.MAX_VALUE));
        while (!stack.isEmpty()) {
            NodeInfo cur = stack.pop();
            TreeNode node = cur.node;
            long low = cur.low;
            long high = cur.high;
            if (node == null) continue;
            if (node.val <= low || node.val >= high) return false;
            if (node.left == null && node.right == null) {
                TreeNode sub = map.remove(node.val);
                if (sub != null) {
                    node.left = sub.left;
                    node.right = sub.right;
                }
            }
            if (node.right != null) stack.push(new NodeInfo(node.right, node.val, high));
            if (node.left != null) stack.push(new NodeInfo(node.left, low, node.val));
        }
        return true;
    }
}

import java.util.*;

class Solution {
    public static int minCost(int maxTime, int[][] edges, int[] passingFees) {
        int n = passingFees.length;
        List<int[]>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0], v = e[1], t = e[2];
            adj[u].add(new int[]{v, t});
            adj[v].add(new int[]{u, t});
        }
        long INF = Long.MAX_VALUE / 4;
        long[][] best = new long[n][maxTime + 1];
        for (int i = 0; i < n; i++) Arrays.fill(best[i], INF);
        best[0][0] = passingFees[0];
        PriorityQueue<State> pq = new PriorityQueue<>();
        pq.offer(new State(passingFees[0], 0, 0));
        while (!pq.isEmpty()) {
            State cur = pq.poll();
            long cost = cur.cost;
            int city = cur.city;
            int time = cur.time;
            if (cost != best[city][time]) continue;
            if (city == n - 1) return (int) cost;
            for (int[] edge : adj[city]) {
                int next = edge[0];
                int travel = edge[1];
                int newTime = time + travel;
                if (newTime > maxTime) continue;
                long newCost = cost + passingFees[next];
                if (newCost < best[next][newTime]) {
                    best[next][newTime] = newCost;
                    pq.offer(new State(newCost, next, newTime));
                }
            }
        }
        long ans = INF;
        for (int t = 0; t <= maxTime; t++) {
            ans = Math.min(ans, best[n - 1][t]);
        }
        return ans == INF ? -1 : (int) ans;
    }

    private static class State implements Comparable<State> {
        long cost;
        int city;
        int time;
        State(long cost, int city, int time) {
            this.cost = cost;
            this.city = city;
            this.time = time;
        }
        public int compareTo(State o) {
            return Long.compare(this.cost, o.cost);
        }
    }
}

