class Solution {
    public static int countPalindromicSubsequence(String s) {
        int n = s.length();
        int[] first = new int[26];
        int[] last = new int[26];
        for (int i = 0; i < 26; i++) {
            first[i] = -1;
            last[i] = -1;
        }
        for (int i = 0; i < n; i++) {
            int c = s.charAt(i) - 'a';
            if (first[c] == -1) first[c] = i;
            last[c] = i;
        }
        int count = 0;
        boolean[] middleSeen = new boolean[26];
        for (int c = 0; c < 26; c++) {
            if (first[c] != -1 && last[c] - first[c] >= 2) {
                Arrays.fill(middleSeen, false);
                for (int i = first[c] + 1; i < last[c]; i++) {
                    middleSeen[s.charAt(i) - 'a'] = true;
                }
                for (int m = 0; m < 26; m++) {
                    if (middleSeen[m]) count++;
                }
            }
        }
        return count;
    }
}

import java.util.*;

class Solution {
    private static final int MOD = 1_000_000_007;

    public static int colorTheGrid(int m, int n) {
        int maxState = 1;
        for (int i = 0; i < m; i++) maxState *= 3;

        List<int[]> colorsList = new ArrayList<>();
        for (int state = 0; state < maxState; state++) {
            int[] colColors = new int[m];
            int temp = state;
            boolean ok = true;
            for (int i = 0; i < m; i++) {
                colColors[i] = temp % 3;
                temp /= 3;
                if (i > 0 && colColors[i] == colColors[i - 1]) {
                    ok = false;
                    break;
                }
            }
            if (ok) colorsList.add(colColors);
        }

        int sz = colorsList.size();
        int[][] compatible = new int[sz][];
        for (int i = 0; i < sz; i++) {
            List<Integer> list = new ArrayList<>();
            int[] a = colorsList.get(i);
            for (int j = 0; j < sz; j++) {
                int[] b = colorsList.get(j);
                boolean ok = true;
                for (int row = 0; row < m; row++) {
                    if (a[row] == b[row]) {
                        ok = false;
                        break;
                    }
                }
                if (ok) list.add(j);
            }
            compatible[i] = list.stream().mapToInt(Integer::intValue).toArray();
        }

        long[] dpPrev = new long[sz];
        Arrays.fill(dpPrev, 1L);

        for (int col = 1; col < n; col++) {
            long[] dpCurr = new long[sz];
            for (int i = 0; i < sz; i++) {
                long sum = 0;
                for (int j : compatible[i]) {
                    sum += dpPrev[j];
                    if (sum >= MOD) sum -= MOD;
                }
                dpCurr[i] = sum;
            }
            dpPrev = dpCurr;
        }

        long result = 0;
        for (long v : dpPrev) {
            result += v;
            if (result >= MOD) result -= MOD;
        }
        return (int) result;
    }
}

public class Solution {
    public static int addMinimumRungs(int[] rungs, int dist) {
        int added = 0;
        int previousHeight = 0;
        for (int i = 0; i < rungs.length; i++) {
            int gap = rungs[i] - previousHeight;
            if (gap > dist) {
                added += (int)Math.ceil((double)gap / dist) - 1;
            }
            previousHeight = rungs[i];
        }
        return added;
    }
}

public class Solution {
    public static int maxPoints(int[][] points) {
        int m = points.length;
        int n = points[0].length;
        int[] dp = points[0].clone();
        int[] left = new int[n];
        int[] newDp = new int[n];
        for (int i = 1; i < m; i++) {
            left[0] = dp[0];
            for (int j = 1; j < n; j++) {
                left[j] = Math.max(dp[j], left[j - 1] - 1);
            }
            int rightBest = dp[n - 1];
            for (int j = n - 1; j >= 0; j--) {
                if (j < n - 1) {
                    rightBest = Math.max(dp[j], rightBest - 1);
                }
                newDp[j] = points[i][j] + Math.max(left[j], rightBest);
            }
            int[] tmp = dp;
            dp = newDp;
            newDp = tmp;
        }
        int ans = dp[0];
        for (int v : dp) {
            if (v > ans) ans = v;
        }
        return ans;
    }
}

