        for (int i = 0; i < n; i++) tree[i] = new ArrayList<>();
        int root = -1;
        for (int i = 0; i < n; i++) {
            if (parents[i] == -1) {
                root = i;
            } else {
                tree[parents[i]].add(i);
            }
        }

        List<Query>[] qAtNode = new ArrayList[n];
        for (int i = 0; i < n; i++) qAtNode[i] = new ArrayList<>();
        int maxVal = n - 1;
        for (int i = 0; i < queries.length; i++) {
            int node = queries[i][0];
            int val = queries[i][1];
            qAtNode[node].add(new Query(i, val));
            if (val > maxVal) maxVal = val;
        }

        int maxBit = maxVal == 0 ? 0 : 31 - Integer.numberOfLeadingZeros(maxVal);
        int maxNodes = (n + 1) * (maxBit + 1) + 5;
        int[] left = new int[maxNodes];
        int[] right = new int[maxNodes];
        int[] cnt = new int[maxNodes];
        int nodeCount = 1; // 0 is root

        int[] ans = new int[queries.length];
        Deque<State> stack = new ArrayDeque<>();
        stack.push(new State(root, -1));

        while (!stack.isEmpty()) {
            State cur = stack.peek();
            int u = cur.node;
            if (cur.childIdx == -1) {
                // enter node
                int curNode = 0;
                for (int b = maxBit; b >= 0; b--) {
                    int bit = (u >> b) & 1;
                    if (bit == 0) {
                        if (left[curNode] == 0) left[curNode] = nodeCount++;
                        curNode = left[curNode];
                    } else {
                        if (right[curNode] == 0) right[curNode] = nodeCount++;
                        curNode = right[curNode];
                    }
                    cnt[curNode]++;
                }
                for (Query q : qAtNode[u]) {
                    int curNodeQ = 0;
                    int xor = 0;
                    for (int b = maxBit; b >= 0; b--) {
                        int bit = (q.val >> b) & 1;
                        int desired = bit ^ 1;
                        int next = (desired == 0) ? left[curNodeQ] : right[curNodeQ];
                        if (next != 0 && cnt[next] > 0) {
                            xor |= (1 << b);
                            curNodeQ = next;
                        } else {
                            curNodeQ = (desired == 0) ? right[curNodeQ] : left[curNodeQ];
                        }
                    }
                    ans[q.idx] = xor;
                }
                cur.childIdx = 0;
            } else if (cur.childIdx < tree[u].size()) {
                int v = tree[u].get(cur.childIdx);
                cur.childIdx++;
                stack.push(new State(v, -1));
            } else {
                // exit node
                int curNode = 0;
                for (int b = maxBit; b >= 0; b--) {
                    int bit = (u >> b) & 1;
                    curNode = (bit == 0) ? left[curNode] : right[curNode];
                    cnt[curNode]--;
                }
                stack.pop();
            }
        }
        return ans;
    }
}

