import java.util.*;

class Solution {
    public static int smallestChair(int[][] times, int targetFriend) {
        int n = times.length;
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> Integer.compare(times[a][0], times[b][0]));
        PriorityQueue<int[]> occupied = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        PriorityQueue<Integer> free = new PriorityQueue<>();
        int nextChair = 0;
        for (int idx : order) {
            int arrival = times[idx][0];
            int leave = times[idx][1];
            while (!occupied.isEmpty() && occupied.peek()[0] <= arrival) {
                free.offer(occupied.poll()[1]);
            }
            int chair = free.isEmpty() ? nextChair++ : free.poll();
            if (idx == targetFriend) {
                return chair;
            }
            occupied.offer(new int[]{leave, chair});
        }
        return -1;
    }
}

public class Solution {
    public static int sumOfDigitsAfterConvert(String s, int k) {
        int total = 0;
        for (int i = 0; i < s.length(); i++) {
            int v = s.charAt(i) - 96;
            if (v < 10) total += v;
            else total += v / 10 + v % 10;
        }
        int result = total;
        for (int i = 1; i < k; i++) {
            int sum = 0;
            while (result > 0) {
                sum += result % 10;
                result = result / 10;
            }
            result = sum;
        }
        return result;
    }
}

