public class Solution {
    public static List<int[]> describePainting(int[][] segments) {
        List<int[]> events = new ArrayList<>();
        for (int i = 0; i < segments.length; i++) {
            int l = segments[i][0];
            int r = segments[i][1];
            int c = segments[i][2];
            events.add(new int[]{l, c});
            events.add(new int[]{r, -c});
        }
        events.sort((a, b) -> Integer.compare(a[0], b[0]));
        List<int[]> result = new ArrayList<>();
        if (events.isEmpty()) {
            return result;
        }
        int curSum = 0;
        int prev = events.get(0)[0];
        int i = 0;
        while (i < events.size()) {
            int x = events.get(i)[0];
            if (prev < x && curSum != 0) {
                result.add(new int[]{prev, x, curSum});
            }
            while (i < events.size() && events.get(i)[0] == x) {
                curSum += events.get(i)[1];
                i++;
            }
            prev = x;
        }
        return result;
    }
}

