class Solution {
    public static int[] numberOfVisiblePeople(int[] heights) {
        int n = heights.length;
        int[] answer = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = n - 1; i >= 0; i--) {
            int visible = 0;
            while (!stack.isEmpty() && heights[stack.peekLast()] < heights[i]) {
                stack.pollLast();
                visible++;
            }
            if (!stack.isEmpty()) {
                visible++;
            }
            answer[i] = visible;
            stack.addLast(i);
        }
        return answer;
    }
}

class Solution {
    public static boolean isThreeDivisors(long n) {
        long root = (long) Math.sqrt(n);
        if (root * root != n) return false;
        if (root < 2) return false;
        for (long i = 2; i * i <= root; i++) {
            if (root % i == 0) return false;
        }
        return true;
    }
}

class Solution {
    public static String largestNumber(String num, int[] change) {
        char[] digits = num.toCharArray();
        int i = 0;
        int n = digits.length;
        while (i < n && change[digits[i] - '0'] <= digits[i] - '0') {
            i++;
        }
        while (i < n && change[digits[i] - '0'] >= digits[i] - '0') {
            digits[i] = (char) ('0' + change[digits[i] - '0']);
            i++;
        }
        return new String(digits);
    }
}

class Solution {
