public class Solution {
    public static int countSpecialSubsequences(int[] nums) {
        final int MOD = 1000000007;
        long zeros = 0;
        long zeroOne = 0;
        long zeroOneTwo = 0;
        for (int v : nums) {
            if (v == 0) {
                zeros = (zeros * 2 + 1) % MOD;
            } else if (v == 1) {
                zeroOne = (zeroOne * 2 + zeros) % MOD;
            } else {
                zeroOneTwo = (zeroOneTwo * 2 + zeroOne) % MOD;
            }
        }
        return (int) zeroOneTwo;
    }
}

