class Solution {
    public static int minTotalSpaceWasted(int[] nums, int k) {
        int n = nums.length;
        int maxSeg = k + 1;
        long INF = Long.MAX_VALUE / 4;
        long[][] dp = new long[maxSeg + 1][n + 1];
        for (int seg = 0; seg <= maxSeg; seg++) {
            Arrays.fill(dp[seg], INF);
        }
        dp[0][0] = 0;
        for (int seg = 1; seg <= maxSeg; seg++) {
            for (int i = seg; i <= n; i++) {
                long best = INF;
                int max = 0;
                long sum = 0;
                for (int p = i - 1; p >= seg - 1; p--) {
                    max = Math.max(max, nums[p]);
                    sum += nums[p];
                    long waste = (long) max * (i - p) - sum;
                    if (dp[seg - 1][p] != INF) {
                        long cand = dp[seg - 1][p] + waste;
                        if (cand < best) {
                            best = cand;
                        }
                    }
                }
                dp[seg][i] = best;
            }
        }
        long ans = INF;
        for (int seg = 1; seg <= maxSeg; seg++) {
            ans = Math.min(ans, dp[seg][n]);
        }
        return (int) ans;
    }
}

import java.util.ArrayList;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import java.util.function.Supplier;

class Solution {
    public static long minimizeStoneSum(int[] piles, int k) {
        ArrayList<Integer> heap = new ArrayList<>();
        BiConsumer<Integer, Integer> swap = (i, j) -> {
            int t = heap.get(i);
            heap.set(i, heap.get(j));
            heap.set(j, t);
        };
        Consumer<Integer> heapifyUp = new Consumer<Integer>() {
            public void accept(Integer idx) {
                int i = idx;
                while (i > 0) {
                    int p = (i - 1) >> 1;
                    if (heap.get(p) >= heap.get(i)) break;
                    swap.accept(p, i);
                    i = p;
                }
            }
        };
        Consumer<Integer> heapifyDown = new Consumer<Integer>() {
            public void accept(Integer idx) {
                int i = idx;
                int n = heap.size();
                while (true) {
                    int largest = i;
                    int l = i * 2 + 1;
                    int r = i * 2 + 2;
                    if (l < n && heap.get(l) > heap.get(largest)) largest = l;
                    if (r < n && heap.get(r) > heap.get(largest)) largest = r;
                    if (largest == i) break;
                    swap.accept(i, largest);
                    i = largest;
                }
            }
        };
        Consumer<Integer> push = (val) -> {
            heap.add(val);
            heapifyUp.accept(heap.size() - 1);
        };
        Supplier<Integer> pop = () -> {
            int top = heap.get(0);
            int last = heap.remove(heap.size() - 1);
            if (!heap.isEmpty()) {
                heap.set(0, last);
                heapifyDown.accept(0);
            }
            return top;
        };
        for (int v : piles) {
            push.accept(v);
        }
        for (int i = 0; i < k; ++i) {
            int largest = pop.get();
            int reduced = largest - largest / 2;
            push.accept(reduced);
        }
        long total = 0;
        for (int v : heap) {
            total += v;
        }
        return total;
    }
}

