class Solution {
    public static int[] longestObstacleCourseAtEachPosition(int[] obstacles) {
        int n = obstacles.length;
        int[] ans = new int[n];
        int[] tails = new int[n];
        int size = 0;
        for (int i = 0; i < n; i++) {
            int x = obstacles[i];
            int l = 0, r = size;
            while (l < r) {
                int m = (l + r) >>> 1;
                if (tails[m] <= x) {
                    l = m + 1;
                } else {
                    r = m;
                }
            }
            int pos = l;
            ans[i] = pos + 1;
            if (pos == size) {
                tails[size++] = x;
            } else {
                tails[pos] = x;
            }
        }
        return ans;
    }
}

