class Solution {
    public static int maxProduct(String s) {
        int n = s.length();
        char[] ch = s.toCharArray();
        int[] d1 = new int[n];
        int l = 0, r = -1;
        for (int i = 0; i < n; i++) {
            int k = (i > r) ? 1 : Math.min(d1[l + r - i], r - i + 1);
            while (i - k >= 0 && i + k < n && ch[i - k] == ch[i + k]) {
                k++;
            }
            d1[i] = k;
            if (i + k - 1 > r) {
                l = i - k + 1;
                r = i + k - 1;
            }
        }
        int[] d2 = new int[n];
        l = 0;
        r = -1;
        for (int i = 0; i < n; i++) {
            int k = (i > r) ? 0 : Math.min(d2[l + r - i + 1], r - i + 1);
            while (i - k - 1 >= 0 && i + k < n && ch[i - k - 1] == ch[i + k]) {
                k++;
            }
            d2[i] = k;
            if (i + k - 1 > r) {
                l = i - k;
                r = i + k - 1;
            }
        }
        int[] leftMax = new int[n];
        int[] rightMax = new int[n];
        for (int i = 0; i < n; i++) {
            int len = 2 * d1[i] - 1;
            int start = i - d1[i] + 1;
            int end = i + d1[i] - 1;
            leftMax[end] = Math.max(leftMax[end], len);
            rightMax[start] = Math.max(rightMax[start], len);
            if (d2[i] > 0) {
                len = 2 * d2[i];
                start = i - d2[i];
                end = i + d2[i] - 1;
                leftMax[end] = Math.max(leftMax[end], len);
                rightMax[start] = Math.max(rightMax[start], len);
            }
        }
        for (int i = 1; i < n; i++) {
            leftMax[i] = Math.max(leftMax[i], leftMax[i - 1]);
        }
        for (int i = n - 2; i >= 0; i--) {
            rightMax[i] = Math.max(rightMax[i], rightMax[i + 1]);
        }
        long ans = 0;
        for (int i = 0; i < n - 1; i++) {
            ans = Math.max(ans, (long) leftMax[i] * rightMax[i + 1]);
        }
        return (int) ans;
    }
}

import java.lang.*;

class Solution {
    private static final long MOD = 1_000_000_007L;
    private static final long MOD_MINUS_ONE = MOD - 1;

    public static int minNonZeroProduct(int p) {
        long pow2p = modPow(2L, p, MOD);
        long maxVal = (pow2p - 1 + MOD) % MOD;
        long base = (pow2p - 2 + MOD) % MOD;
        long exponent = (modPow(2L, p - 1, MOD_MINUS_ONE) - 1 + MOD_MINUS_ONE) % MOD_MINUS_ONE;
        long product = modPow(base, exponent, MOD);
        long result = (maxVal * product) % MOD;
        return (int) result;
    }

    private static long modPow(long base, long exp, long mod) {
        long result = 1L;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1L) == 1L) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}

import java.util.*;

class Solution {
    public static int latestDayToCross(int row, int col, int[][] cells) {
        int total = row * col;
        DSU dsu = new DSU(total + 2);
        int top = total;
        int bottom = total + 1;
        boolean[] open = new boolean[total];
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        for (int i = cells.length - 1; i >= 0; i--) {
            int r = cells[i][0] - 1;
            int c = cells[i][1] - 1;
            int idx = r * col + c;
            open[idx] = true;

            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr >= 0 && nr < row && nc >= 0 && nc < col) {
                    int nIdx = nr * col + nc;
                    if (open[nIdx]) {
                        dsu.union(idx, nIdx);
                    }
                }
            }

            if (r == 0) dsu.union(idx, top);
            if (r == row - 1) dsu.union(idx, bottom);

            if (dsu.find(top) == dsu.find(bottom)) {
                return i;
            }
        }
        return 0;
    }

    private static class DSU {
        private final int[] parent;
        private final int[] rank;

        DSU(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                rank[i] = 1;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int x, int y) {
            int rx = find(x);
            int ry = find(y);
            if (rx == ry) return;
            if (rank[rx] < rank[ry]) {
                parent[rx] = ry;
            } else if (rank[rx] > rank[ry]) {
                parent[ry] = rx;
            } else {
                parent[ry] = rx;
                rank[rx]++;
            }
        }
    }
}

