class Solution {
    public static int[] rearrange(int[] nums) {
        Arrays.sort(nums);
        int n = nums.length;
        int[] res = new int[n];
        int left = 0, right = n - 1, idx = 0;
        while (left <= right) {
            res[idx++] = nums[left++];
            if (left <= right) {
                res[idx++] = nums[right--];
            }
        }
        return res;
    }
}

