    public static int numberOfPatterns(String[] patterns, String word) {
        List<Node> nodes = new ArrayList<>();
        nodes.add(new Node()); // root at index 0

        // build trie
        for (int i = 0; i < patterns.length; i++) {
            int cur = 0;
            for (char ch : patterns[i].toCharArray()) {
                Node curNode = nodes.get(cur);
                Integer next = curNode.children.get(ch);
                if (next == null) {
                    next = nodes.size();
                    curNode.children.put(ch, next);
                    nodes.add(new Node());
                }
                cur = next;
            }
            nodes.get(cur).out.add(i);
        }

        // build failure links
        Deque<Integer> queue = new ArrayDeque<>();
        for (Map.Entry<Character, Integer> entry : nodes.get(0).children.entrySet()) {
            int child = entry.getValue();
            nodes.get(child).fail = 0;
            queue.add(child);
        }
        while (!queue.isEmpty()) {
            int v = queue.poll();
            Node vNode = nodes.get(v);
            for (Map.Entry<Character, Integer> entry : vNode.children.entrySet()) {
                char ch = entry.getKey();
                int u = entry.getValue();
                int f = vNode.fail;
                while (f != 0 && !nodes.get(f).children.containsKey(ch)) {
                    f = nodes.get(f).fail;
                }
                if (nodes.get(f).children.containsKey(ch)) {
                    nodes.get(u).fail = nodes.get(f).children.get(ch);
                } else {
                    nodes.get(u).fail = 0;
                }
                nodes.get(u).out.addAll(nodes.get(nodes.get(u).fail).out);
                queue.add(u);
            }
        }

        // search word
        boolean[] found = new boolean[patterns.length];
        int state = 0;
        for (char ch : word.toCharArray()) {
            while (state != 0 && !nodes.get(state).children.containsKey(ch)) {
                state = nodes.get(state).fail;
            }
            state = nodes.get(state).children.getOrDefault(ch, 0);
            for (int idx : nodes.get(state).out) {
                found[idx] = true;
            }
        }

        // count results
        int cnt = 0;
        for (boolean f : found) {
            if (f) cnt++;
        }
        return cnt;
    }
}

import java.lang.Math;

class Solution {
    public static int minTimeToType(String word) {
        int total = 0;
        int curPos = 0;
        for (int i = 0; i < word.length(); i++) {
            int targetPos = word.charAt(i) - 'a';
            int diff = Math.abs(targetPos - curPos);
            int steps = Math.min(diff, 26 - diff);
            total += steps + 1;
            curPos = targetPos;
        }
        return total;
    }
}

public class Solution {
    public static long maxMatrixSum(int[][] matrix) {
        long sumAbs = 0;
        int negCount = 0;
        int minAbs = Integer.MAX_VALUE;
        boolean hasZero = false;
        for (int i = 0; i < matrix.length; i++) {
            int[] row = matrix[i];
            for (int j = 0; j < row.length; j++) {
                int v = row[j];
                int a = Math.abs(v);
                sumAbs += a;
                if (v < 0) negCount++;
                if (a < minAbs) minAbs = a;
                if (v == 0) hasZero = true;
            }
        }
        if (negCount % 2 == 1 && !hasZero) {
            sumAbs -= 2L * minAbs;
        }
        return sumAbs;
    }
}

import java.util.*;

class Solution {
    public static boolean validPath(int n, int[][] edges, int source, int destination) {
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int i = 0; i < edges.length; i++) {
            int u = edges[i][0];
            int v = edges[i][1];
            graph[u].add(v);
            graph[v].add(u);
        }
        boolean[] visited = new boolean[n];
        Queue<Integer> queue = new ArrayDeque<>();
        queue.add(source);
        visited[source] = true;
        while (!queue.isEmpty()) {
            int node = queue.poll();
            if (node == destination) {
                return true;
            }
            for (int nxt : graph[node]) {
                if (!visited[nxt]) {
                    visited[nxt] = true;
                    queue.add(nxt);
                }
            }
        }
        return false;
    }
}

import java.util.*;

class Solution {
    public static int numberOfWays(int n, int[][] roads) {
        final long MOD = 1_000_000_007L;
        List<int[]>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int[] road : roads) {
            int u = road[0];
            int v = road[1];
            int w = road[2];
            adj[u].add(new int[]{v, w});
            adj[v].add(new int[]{u, w});
        }
        long[] dist = new long[n];
        Arrays.fill(dist, Long.MAX_VALUE);
        long[] ways = new long[n];
        dist[0] = 0;
        ways[0] = 1;
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
        pq.offer(new long[]{0L, 0L});
        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            long d = cur[0];
            int u = (int) cur[1];
            if (d != dist[u]) continue;
            for (int[] edge : adj[u]) {
                int v = edge[0];
                int w = edge[1];
                long nd = d + w;
                if (nd < dist[v]) {
                    dist[v] = nd;
                    ways[v] = ways[u];
                    pq.offer(new long[]{nd, v});
                } else if (nd == dist[v]) {
                    ways[v] = (ways[v] + ways[u]) % MOD;
                }
            }
        }
        return (int) (ways[n - 1] % MOD);
    }
}

import java.util.*;

class Solution {
    public static int findGCDofArray(int[] nums) {
        int min = nums[0];
        int max = nums[0];
        for (int i = 1; i < nums.length; i++) {
            int v = nums[i];
            if (v < min) {
                min = v;
            } else if (v > max) {
                max = v;
            }
        }
        return gcd(min, max);
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int r = a % b;
            a = b;
            b = r;
        }
        return a;
    }
}

