class Solution {
    public static int minAbsDifference(int[][] mat, int target) {
        int maxSum = 0;
        for (int[] row : mat) {
            int rowMax = Integer.MIN_VALUE;
            for (int val : row) {
                if (val > rowMax) rowMax = val;
            }
            maxSum += rowMax;
        }
        byte[] dp = new byte[maxSum + 1];
        dp[0] = 1;
        for (int[] row : mat) {
            byte[] next = new byte[maxSum + 1];
            for (int val : row) {
                for (int s = 0; s + val <= maxSum; s++) {
                    if (dp[s] != 0) next[s + val] = 1;
                }
            }
            dp = next;
        }
        int best = Integer.MAX_VALUE;
        for (int s = 0; s <= maxSum; s++) {
            if (dp[s] != 0) {
                int diff = Math.abs(target - s);
                if (diff < best) best = diff;
                if (best == 0) break;
            }
        }
        return best;
    }
}

class Solution {
    public int[] recoverArray(int n, int[] sums) {
        int m = Arrays.stream(sums).min().getAsInt();
        m = -m;
        TreeMap<Integer,Integer> st = new TreeMap<>();
        for (int x : sums) st.merge(x+m, 1, Integer::sum);
        removeOne(st, st.firstKey());
        List<Integer> ans = new ArrayList<>();
        ans.add(st.firstKey());
        for (int i = 1; i < n; i++) {
            for (int j = 0; j < (1<<i); j++) {
                if ((j >> (i-1) & 1) == 1) {
                    int s = 0;
                    for (int k = 0; k < i; k++) if ((j>>k&1)==1) s += ans.get(k);
                    removeOne(st, s);
                }
            }
            ans.add(st.firstKey());
        }
        for (int i = 0; i < (1<<n); i++) {
            int s = 0;
            for (int j = 0; j < n; j++) if ((i>>j&1)==1) s += ans.get(j);
            if (s == m) {
                for (int j = 0; j < n; j++) if ((i>>j&1)==1) ans.set(j, -ans.get(j));
                break;
            }
        }
        int[] res = new int[n];
        for (int i = 0; i < n; i++) res[i] = ans.get(i);
        return res;
    }
    private void removeOne(TreeMap<Integer,Integer> st, int key) {
        int c = st.get(key);
        if (c == 1) st.remove(key); else st.put(key, c-1);
    }
}

