public class Solution {
    public static int numberOfWaysSeparateNumbers(String num) {
        final int MOD = 1_000_000_007;
        int n = num.length();
        int[][] lcp = new int[n + 1][n + 1];
        for (int i = n - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                if (num.charAt(i) == num.charAt(j)) {
                    lcp[i][j] = lcp[i + 1][j + 1] + 1;
                }
            }
        }
        int[][] dp = new int[n + 1][n + 1];
        int[][] pref = new int[n + 1][n + 1];
        for (int i = 1; i <= n; i++) {
            for (int len = 1; len <= i; len++) {
                int start = i - len;
                if (num.charAt(start) == '0') {
                    continue;
                }
                if (start == 0) {
                    dp[i][len] = 1;
                } else {
                    int total = 0;
                    if (len > 1) {
                        total = pref[start][len - 1];
                    }
                    if (len <= start) {
                        int a = start - len;
                        int b = start;
                        int common = lcp[a][b];
                        if (common < len && num.charAt(a + common) < num.charAt(b + common)) {
                            total = (total + dp[start][len]) % MOD;
                        }
                    }
                    dp[i][len] = total;
                }
                pref[i][len] = (pref[i][len - 1] + dp[i][len]) % MOD;
            }
        }
        return pref[n][n];
    }
}

import java.util.HashSet;
import java.util.Set;

class Solution {
    public static String findUniqueBinaryString(String[] nums) {
        int n = nums.length;
        Set<String> seen = new HashSet<>();
        for (String s : nums) {
            seen.add(s);
        }
        StringBuilder xorBuilder = new StringBuilder();
        for (int i = 0; i < n; i++) {
            int countOnes = 0;
            for (String s : nums) {
                if (s.charAt(i) == '1') {
                    countOnes++;
                }
            }
            xorBuilder.append((countOnes % 2) == 1 ? '1' : '0');
        }
        String xorStr = xorBuilder.toString();
        if (!seen.contains(xorStr)) {
            return xorStr;
        }
        for (int i = 0; i < n; i++) {
            char flipped = xorStr.charAt(i) == '0' ? '1' : '0';
            String candidate = xorStr.substring(0, i) + flipped + xorStr.substring(i + 1);
            if (!seen.contains(candidate)) {
                return candidate;
            }
        }
        // Fallback (should never reach here)
        return xorStr;
    }
}

import java.util.*;

class Solution {
    public static int minimumSessions(int[] tasks, int sessionTime) {
        int n = tasks.length;
        int totalMask = 1 << n;
        int[][] dp = new int[totalMask][];
        dp[0] = new int[]{1, 0};
        for (int mask = 0; mask < totalMask; mask++) {
            if (dp[mask] == null) continue;
            int sess = dp[mask][0];
            int used = dp[mask][1];
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue;
                int newMask = mask | (1 << i);
                int newSess = sess;
                int newUsed = used + tasks[i];
                if (newUsed > sessionTime) {
                    newSess = sess + 1;
                    newUsed = tasks[i];
                }
                if (dp[newMask] == null ||
                    newSess < dp[newMask][0] ||
                    (newSess == dp[newMask][0] && newUsed < dp[newMask][1])) {
                    dp[newMask] = new int[]{newSess, newUsed};
                }
            }
        }
        return dp[totalMask - 1][0];
    }
}

