class Solution {
    private static final int MOD = 1_000_000_007;

    private static long distinctCount(String s, int start) {
        long dp = 1;
        long[] last = new long[2];
        for (int i = start; i < s.length(); i++) {
            int ch = s.charAt(i) - '0';
            long newDp = (dp * 2) % MOD;
            newDp = (newDp - last[ch] + MOD) % MOD;
            last[ch] = dp;
            dp = newDp;
        }
        return dp;
    }

    private static long distinctCount(String s) {
        return distinctCount(s, 0);
    }

    public static int numberOfUniqueGoodSubsequences(String binary) {
        long totalDistinct = distinctCount(binary);
        int firstZero = binary.indexOf('0');
        long ans;
        if (firstZero == -1) {
            ans = (totalDistinct - 1 + MOD) % MOD;
        } else {
            long suffixDistinct = distinctCount(binary, firstZero + 1);
            ans = (totalDistinct - suffixDistinct) % MOD;
            if (ans < 0) ans += MOD;
        }
        return (int) ans;
    }
}

