class Solution {
    public static int[] smallestMissingValueSubtree(int[] parents, int[] nums) {
        int n = parents.length;
        List<Integer>[] children = new ArrayList[n];
        for (int i = 0; i < n; i++) children[i] = new ArrayList<>();
        for (int i = 1; i < n; i++) children[parents[i]].add(i);
        int[] ans = new int[n];
        Arrays.fill(ans, 1);
        int nodeOne = -1;
        for (int i = 0; i < n; i++) {
            if (nums[i] == 1) {
                nodeOne = i;
                break;
            }
        }
        if (nodeOne == -1) return ans;
        int limit = n + 2;
        boolean[] seen = new boolean[limit];
        boolean[] visitedNode = new boolean[n];
        int missing = 1;
        int cur = nodeOne;
        Deque<Integer> stack = new ArrayDeque<>();
        while (cur != -1) {
            stack.push(cur);
            while (!stack.isEmpty()) {
                int u = stack.pop();
                if (visitedNode[u]) continue;
                visitedNode[u] = true;
                int val = nums[u];
                if (val < limit) seen[val] = true;
                for (int v : children[u]) {
                    if (!visitedNode[v]) stack.push(v);
                }
            }
            while (missing < limit && seen[missing]) missing++;
            ans[cur] = missing;
            cur = parents[cur];
        }
        return ans;
    }
}

class Solution {
    public static int countQuadruplets(int[] nums) {
        int n = nums.length;
        int answer = 0;
        int[] freq = new int[201];
        for (int c = 1; c < n - 1; c++) {
            for (int a = 0; a < c - 1; a++) {
                int sum = nums[a] + nums[c - 1];
                freq[sum]++;
            }
            for (int d = c + 1; d < n; d++) {
                int need = nums[d] - nums[c];
                if (need >= 0 && need <= 200) {
                    answer += freq[need];
                }
            }
        }
        return answer;
    }
}

