class Solution {
    public static int firstDayBeenInAllRooms(int[] nextVisit) {
        final int MOD = 1000000007;
        int n = nextVisit.length;
        int[] first = new int[n];
        first[0] = 0;
        for (int i = 1; i < n; i++) {
            long val = (2L * first[i - 1]) % MOD;
            val = (val - first[nextVisit[i - 1]] + MOD) % MOD;
            first[i] = (int) ((val + 2) % MOD);
        }
        return first[n - 1];
    }
}

