class Solution {
    public static long interchangeableRectangles(int[][] rectangles) {
        Map<String, Integer> ratioCount = new HashMap<>();
        long pairs = 0;
        for (int i = 0; i < rectangles.length; i++) {
            int w = rectangles[i][0];
            int h = rectangles[i][1];
            int g = gcd(w, h);
            String key = (w / g) + "/" + (h / g);
            int cnt = ratioCount.getOrDefault(key, 0);
            pairs += cnt;
            ratioCount.put(key, cnt + 1);
        }
        return pairs;
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

