class Solution {
    public static int maxProduct(String s) {
        int n = s.length();
        int total = 1 << n;
        int[] pal = new int[total];
        for (int mask = 1; mask < total; mask++) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    sb.append(s.charAt(i));
                }
            }
            if (isPalindrome(sb)) {
                pal[mask] = Integer.bitCount(mask);
            }
        }
        for (int i = 0; i < n; i++) {
            for (int mask = 0; mask < total; mask++) {
                if ((mask & (1 << i)) != 0) {
                    int sub = mask ^ (1 << i);
                    if (pal[sub] > pal[mask]) {
                        pal[mask] = pal[sub];
                    }
                }
            }
        }
        int ans = 0;
        int fullMask = total - 1;
        for (int mask = 0; mask < total; mask++) {
            int other = fullMask ^ mask;
            ans = Math.max(ans, pal[mask] * pal[other]);
        }
        return ans;
    }

    private static boolean isPalindrome(StringBuilder sb) {
        int l = 0, r = sb.length() - 1;
        while (l < r) {
            if (sb.charAt(l++) != sb.charAt(r--)) return false;
        }
        return true;
    }
}

