class Solution {
    public static int[] findOriginalArray(int[] changed) {
        if (changed.length % 2 != 0) {
            return new int[0];
        }
        Map<Integer, Integer> freq = new HashMap<>();
        for (int v : changed) {
            freq.put(v, freq.getOrDefault(v, 0) + 1);
        }
        Integer[] sorted = Arrays.stream(changed).boxed().toArray(Integer[]::new);
        Arrays.sort(sorted, (a, b) -> Integer.compare(Math.abs(a), Math.abs(b)));
        int n = changed.length / 2;
        int[] original = new int[n];
        int idx = 0;
        for (int v : sorted) {
            int cnt = freq.getOrDefault(v, 0);
            if (cnt == 0) {
                continue;
            }
            if (v == 0) {
                if (cnt % 2 != 0) {
                    return new int[0];
                }
                int pairs = cnt / 2;
                for (int i = 0; i < pairs; i++) {
                    original[idx++] = 0;
                }
                freq.put(0, 0);
                continue;
            }
            long doubleValLong = (long) v * 2;
            if (doubleValLong < Integer.MIN_VALUE || doubleValLong > Integer.MAX_VALUE) {
                return new int[0];
            }
            int doubleVal = (int) doubleValLong;
            int doubleCnt = freq.getOrDefault(doubleVal, 0);
            if (doubleCnt < cnt) {
                return new int[0];
            }
            for (int i = 0; i < cnt; i++) {
                original[idx++] = v;
            }
            freq.put(v, 0);
            freq.put(doubleVal, doubleCnt - cnt);
        }
        return original;
    }
}

import java.util.Arrays;

class Solution {
    public static long maxTaxiEarnings(int n, int[][] rides) {
        if (rides == null || rides.length == 0) return 0L;
        Arrays.sort(rides, (a, b) -> {
            if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
            return Integer.compare(a[1], b[1]);
        });
        int m = rides.length;
        int[] starts = new int[m];
        for (int i = 0; i < m; i++) starts[i] = rides[i][0];
        long[] dp = new long[m + 1];
        for (int i = m - 1; i >= 0; i--) {
            long profit = (long) rides[i][1] - rides[i][0] + rides[i][2];
            int lo = i + 1, hi = m;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (starts[mid] >= rides[i][1]) hi = mid;
                else lo = mid + 1;
            }
            dp[i] = Math.max(dp[i + 1], profit + dp[lo]);
        }
        return dp[0];
    }
}

class Solution {
    public static String longestSubsequenceRepeatedKTimes(String s, int k) {
        int[] freq = new int[26];
        for (char c : s.toCharArray()) freq[c-'a']++;
        StringBuilder validChars = new StringBuilder();
        for (int i = 0; i < 26; i++) if (freq[i] >= k) validChars.append((char)('a'+i));

        String best = "";
        java.util.List<String> queue = new java.util.ArrayList<>();
        for (char c : validChars.toString().toCharArray()) queue.add(String.valueOf(c));
        while (!queue.isEmpty()) {
            java.util.List<String> next = new java.util.ArrayList<>();
            for (String cand : queue) {
                if (isValid(cand, s, k)) {
                    if (cand.length() > best.length() || (cand.length()==best.length() && cand.compareTo(best) > 0)) best = cand;
                    for (char c : validChars.toString().toCharArray()) next.add(cand + c);
                }
            }
            queue = next;
        }
        return best;
    }
    private static boolean isValid(String candidate, String s, int k) {
        int count = 0, pos = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == candidate.charAt(pos)) {
                pos++;
                if (pos == candidate.length()) { count++; pos = 0; if (count >= k) return true; }
            }
        }
        return count >= k;
    }
}

