public class Solution {
    public static int minOperations(int[] nums) {
        int n = nums.length;
        Set<Integer> set = new HashSet<>();
        for (int num : nums) {
            set.add(num);
        }
        int[] uniq = new int[set.size()];
        int idx = 0;
        for (int val : set) {
            uniq[idx++] = val;
        }
        Arrays.sort(uniq);
        int left = 0;
        int best = 0;
        for (int right = 0; right < uniq.length; right++) {
            while (uniq[right] - uniq[left] > n - 1) {
                left++;
            }
            int windowSize = right - left + 1;
            if (windowSize > best) {
                best = windowSize;
            }
        }
        return n - best;
    }
}

