class DetectSquares {
    private final Map<Integer, Map<Integer,Integer>> pointsMap = new HashMap<>();
    public void add(int[] point) {
        pointsMap.computeIfAbsent(point[0], k -> new HashMap<>()).merge(point[1], 1, Integer::sum);
    }
    public int count(int[] point) {
        int x = point[0], y = point[1];
        Map<Integer,Integer> yMap = pointsMap.get(x);
        if (yMap == null) return 0;
        int total = 0;
        for (Map.Entry<Integer,Integer> entry : yMap.entrySet()) {
            int y2 = entry.getKey(), cnt = entry.getValue();
            if (y2 == y) continue;
            int d = Math.abs(y2 - y);
            for (int xOther : new int[]{x+d, x-d}) {
                Map<Integer,Integer> m = pointsMap.get(xOther);
                if (m != null) {
                    int cnt1 = m.getOrDefault(y, 0), cnt2 = m.getOrDefault(y2, 0);
                    total += cnt * cnt1 * cnt2;
                }
            }
        }
        return total;
    }
}

class Solution {
    public static long gridGame(int[][] grid) {
        int[] top = grid[0];
        int[] bottom = grid[1];
        int n = top.length;
        long totalTop = 0;
        for (int value : top) {
            totalTop += value;
        }
        long topRemain = totalTop;
        long bottomRemain = 0;
        long answer = Long.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            topRemain -= top[i];
            long worst = topRemain > bottomRemain ? topRemain : bottomRemain;
            if (worst < answer) {
                answer = worst;
            }
            bottomRemain += bottom[i];
        }
        return answer;
    }
}

