class Solution {
    private static boolean matches(char[] seg, String w) {
        for (int i = 0; i < seg.length; i++) {
            if (seg[i] != ' ' && seg[i] != w.charAt(i)) {
                return false;
            }
        }
        return true;
    }

    public static boolean placeWordInCrossword(char[][] board, String word) {
        int rows = board.length;
        int cols = board[0].length;
        String rev = new StringBuilder(word).reverse().toString();

        for (int r = 0; r < rows; r++) {
            int c = 0;
            while (c < cols) {
                while (c < cols && board[r][c] == '#') c++;
                if (c >= cols) break;
                int start = c;
                while (c < cols && board[r][c] != '#') c++;
                int len = c - start;
                if (len == word.length()) {
                    char[] segment = new char[len];
                    for (int i = 0; i < len; i++) {
                        segment[i] = board[r][start + i];
                    }
                    if (matches(segment, word) || matches(segment, rev)) {
                        return true;
                    }
                }
            }
        }

        for (int c = 0; c < cols; c++) {
            int r = 0;
            while (r < rows) {
                while (r < rows && board[r][c] == '#') r++;
                if (r >= rows) break;
                int start = r;
                while (r < rows && board[r][c] != '#') r++;
                int len = r - start;
                if (len == word.length()) {
                    char[] segment = new char[len];
                    for (int i = 0; i < len; i++) {
                        segment[i] = board[start + i][c];
                    }
                    if (matches(segment, word) || matches(segment, rev)) {
                        return true;
                    }
                }
            }
        }

        return false;
    }
}

