class Solution {
    public static int gradeStudents(String s, int[] answers) {
        int correct = 0;
        int product = s.charAt(0) - '0';
        for (int i = 1; i < s.length(); i += 2) {
            char op = s.charAt(i);
            int val = s.charAt(i + 1) - '0';
            if (op == '*') {
                product *= val;
            } else {
                correct += product;
                product = val;
            }
        }
        correct += product;
        int leftToRight = s.charAt(0) - '0';
        for (int i = 1; i < s.length(); i += 2) {
            char op = s.charAt(i);
            int val = s.charAt(i + 1) - '0';
            if (op == '+') {
                leftToRight += val;
            } else {
                leftToRight *= val;
            }
        }
        int totalPoints = 0;
        for (int ans : answers) {
            if (ans == correct) {
                totalPoints += 5;
            } else if (ans == leftToRight) {
                totalPoints += 2;
            }
        }
        return totalPoints;
    }
}

