import java.util.Map;

class Solution {
    public static int waysToPartition(int[] nums, int k) {
        int n = nums.length;
        long[] pref = new long[n];
        long sum = 0;
        for (int i = 0; i < n; i++) {
            sum += nums[i];
            pref[i] = sum;
        }

        Map<Long, Integer> leftCount = new HashMap<>();
        Map<Long, Integer> rightCount = new HashMap<>();
        for (int i = 0; i < n - 1; i++) {
            rightCount.put(pref[i], rightCount.getOrDefault(pref[i], 0) + 1);
        }

        int baseWays = 0;
        for (int i = 0; i < n - 1; i++) {
            if (pref[i] * 2 == sum) {
                baseWays++;
            }
        }
        int answer = baseWays;

        for (int j = 0; j < n; j++) {
            long delta = (long) k - nums[j];
            long newTotal = sum + delta;
            if ((newTotal & 1L) == 0L) {
                long target = newTotal / 2;
                int leftWays = leftCount.getOrDefault(target, 0);
                int rightWays = rightCount.getOrDefault(target - delta, 0);
                answer = Math.max(answer, leftWays + rightWays);
            }
            if (j < n - 1) {
                long cur = pref[j];
                int cnt = rightCount.get(cur);
                if (cnt == 1) {
                    rightCount.remove(cur);
                } else {
                    rightCount.put(cur, cnt - 1);
                }
                leftCount.put(cur, leftCount.getOrDefault(cur, 0) + 1);
            }
        }
        return answer;
    }
}

