class Solution {
    public static int[] findMissingObservations(int[] rolls, int mean, int n) {
        int m = rolls.length;
        long totalNeeded = (long) mean * (n + m);
        long knownSum = 0;
        for (int v : rolls) {
            knownSum += v;
        }
        long missingSum = totalNeeded - knownSum;
        if (missingSum < n || missingSum > 6L * n) {
            return new int[0];
        }
        int base = (int) (missingSum / n);
        int extra = (int) (missingSum % n);
        int[] result = new int[n];
        Arrays.fill(result, base);
        for (int i = 1; i <= extra; i++) {
            result[i]++;
        }
        return result;
    }
}

