import java.util.*;
class StockPrice {
    private Map<Integer, Integer> timePrice;
    private PriorityQueue<int[]> maxHeap;
    private PriorityQueue<int[]> minHeap;
    private int latestTimestamp;
    public StockPrice() {
        timePrice = new HashMap<>();
        maxHeap = new PriorityQueue<>((a, b) -> b[0] - a[0]);
        minHeap = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        latestTimestamp = 0;
    }
    public void update(int timestamp, int price) {
        timePrice.put(timestamp, price);
        maxHeap.offer(new int[]{price, timestamp});
        minHeap.offer(new int[]{price, timestamp});
        if (timestamp >= latestTimestamp) latestTimestamp = timestamp;
    }
    public int current() { return timePrice.get(latestTimestamp); }
    public int maximum() {
        while (true) {
            int[] top = maxHeap.peek();
            if (timePrice.get(top[1]) != null && timePrice.get(top[1]) == top[0]) return top[0];
            maxHeap.poll();
        }
    }
    public int minimum() {
        while (true) {
            int[] top = minHeap.peek();
            if (timePrice.get(top[1]) != null && timePrice.get(top[1]) == top[0]) return top[0];
            minHeap.poll();
        }
    }
}

