class Solution {
    public static String smallestSubsequence(String s, int k, char letter, int repetition) {
        int n = s.length();
        int totalLetter = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == letter) totalLetter++;
        }
        char[] stack = new char[k];
        int size = 0;
        int selectedLetterCount = 0;
        int seenLetter = 0;
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            int remainingLetter = totalLetter - seenLetter;
            while (size > 0 && c < stack[size - 1] && size - 1 + (n - i) >= k) {
                char top = stack[size - 1];
                int afterPopLetterCount = selectedLetterCount - (top == letter ? 1 : 0);
                if (afterPopLetterCount + remainingLetter >= repetition) {
                    if (top == letter) selectedLetterCount--;
                    size--;
                } else {
                    break;
                }
            }
            if (size < k) {
                if (c == letter) {
                    stack[size++] = c;
                    selectedLetterCount++;
                } else {
                    if (selectedLetterCount + remainingLetter >= repetition) {
                        stack[size++] = c;
                    }
                }
            }
            if (c == letter) seenLetter++;
        }
        return new String(stack, 0, k);
    }
}

