class Solution {
    public static List<Integer> twoOutOfThree(int[] nums1, int[] nums2, int[] nums3) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int[] arr : new int[][]{nums1, nums2, nums3}) {
            Set<Integer> seen = new HashSet<>();
            for (int v : arr) {
                seen.add(v);
            }
            for (int v : seen) {
                freq.put(v, freq.getOrDefault(v, 0) + 1);
            }
        }
        Map<Integer, Integer> posInNums2 = new HashMap<>();
        for (int i = 0; i < nums2.length; i++) {
            posInNums2.putIfAbsent(nums2[i], i);
        }
        List<Integer> result = new ArrayList<>();
        for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
            if (e.getValue() >= 2) {
                result.add(e.getKey());
            }
        }
        result.sort((a, b) -> {
            int cmp = Integer.compare(freq.get(b), freq.get(a));
            if (cmp != 0) return cmp;
            int posA = posInNums2.getOrDefault(a, Integer.MAX_VALUE);
            int posB = posInNums2.getOrDefault(b, Integer.MAX_VALUE);
            if (posA != posB) return Integer.compare(posA, posB);
            return Integer.compare(a, b);
        });
        return result;
    }
}

import java.util.*;

class Solution {
    public static long minOperations(int[][] grid, int x) {
        List<Integer> values = new ArrayList<>();
        for (int i = 0; i < grid.length; i++) {
            int[] row = grid[i];
            for (int j = 0; j < row.length; j++) {
                values.add(row[j]);
            }
        }
        int base = values.get(0);
        for (int i = 1; i < values.size(); i++) {
            if ((values.get(i) - base) % x != 0) return -1;
        }
        Collections.sort(values);
        int median = values.get(values.size() / 2);
        long ops = 0;
        for (int v : values) {
            ops += Math.abs(v - median) / x;
        }
        return ops;
    }
}

