class Solution {
    public static boolean canAliceWin(String colors) {
        int alice = 0, bob = 0;
        int i = 0, n = colors.length();
        while (i < n) {
            int j = i;
            while (j < n && colors.charAt(j) == colors.charAt(i)) j++;
            int runLen = j - i;
            if (runLen >= 3) {
                if (colors.charAt(i) == 'A') alice += runLen - 2;
                else bob += runLen - 2;
            }
            i = j;
        }
        return alice > bob;
    }
}

import java.util.*;

class Solution {
    public static long minDifference(int[] nums) {
        long total = 0;
        for (int v : nums) total += v;
        double half = total / 2.0;
        int n = nums.length >> 1;
        int[] left = Arrays.copyOfRange(nums, 0, n);
        int[] right = Arrays.copyOfRange(nums, n, nums.length);

        List<List<Long>> leftSums = allSums(left);
        List<List<Long>> rightSums = allSums(right);

        for (int i = 0; i <= n; ++i) Collections.sort(rightSums.get(i));

        long best = Long.MAX_VALUE;

        for (int i = 0; i <= n; ++i) {
            List<Long> L = leftSums.get(i);
            List<Long> R = rightSums.get(n - i);
            if (L.isEmpty() || R.isEmpty()) continue;

            for (long sL : L) {
                double target = half - sL;
                int lo = 0, hi = R.size() - 1;
                while (lo < hi) {
                    int mid = (lo + hi) >> 1;
                    if (R.get(mid) < target) lo = mid + 1;
                    else hi = mid;
                }
                for (int idx : new int[]{lo, lo - 1}) {
                    if (idx < 0 || idx >= R.size()) continue;
                    long s = sL + R.get(idx);
                    long diff = Math.abs(total - 2 * s);
                    if (diff < best) best = diff;
                    if (best == 0) return 0;
                }
            }
        }
        return best;
    }

    private static List<List<Long>> allSums(int[] arr) {
        int m = arr.length;
        List<List<Long>> sumsByCnt = new ArrayList<>(m + 1);
        for (int i = 0; i <= m; ++i) sumsByCnt.add(new ArrayList<>());
        int limit = 1 << m;
        for (int mask = 0; mask < limit; ++mask) {
            int cnt = 0;
            long sum = 0;
            for (int i = 0; i < m; ++i) {
                if ((mask & (1 << i)) != 0) {
                    cnt++;
                    sum += arr[i];
                }
            }
            sumsByCnt.get(cnt).add(sum);
        }
        return sumsByCnt;
    }
}

import java.util.*;

class Solution {
    public static long kthSmallestProduct(int[] nums1, int[] nums2, long k) {
        int n1 = nums1.length;
        int n2 = nums2.length;

        int negA = 0;
        while (negA < n1 && nums1[negA] < 0) negA++;
        int zeroA = 0;
        while (negA + zeroA < n1 && nums1[negA + zeroA] == 0) zeroA++;
        int posA = n1 - negA - zeroA;

        int[] aNeg = Arrays.copyOfRange(nums1, 0, negA);
        int[] aPos = Arrays.copyOfRange(nums1, n1 - posA, n1);

        int negB = 0;
        while (negB < n2 && nums2[negB] < 0) negB++;
        int zeroB = 0;
        while (negB + zeroB < n2 && nums2[negB + zeroB] == 0) zeroB++;
        int posB = n2 - negB - zeroB;

        int[] bNeg = Arrays.copyOfRange(nums2, 0, negB);
        int[] bPos = Arrays.copyOfRange(nums2, n2 - posB, n2);

        long[] aNegAbs = new long[negA];
        for (int i = 0; i < negA; i++) aNegAbs[i] = -(long) aNeg[negA - 1 - i];
        long[] bNegAbs = new long[negB];
        for (int i = 0; i < negB; i++) bNegAbs[i] = -(long) bNeg[negB - 1 - i];

        long low = -100000L * 100000L - 1;
        long high = 100000L * 100000L + 1;

        while (low < high) {
            long mid = low + (high - low) / 2;
            if (countLE(mid, aNeg, aPos, bNeg, bPos, aNegAbs, bNegAbs, zeroA, zeroB, n1, n2) >= k) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    private static long countLE(long x, int[] aNeg, int[] aPos, int[] bNeg, int[] bPos,
                                long[] aNegAbs, long[] bNegAbs,
                                int zeroA, int zeroB, int n1, int n2) {
        long cnt = 0;

        if (x >= 0) {
            cnt += (long) zeroA * n2 + (long) zeroB * n1 - (long) zeroA * zeroB;
        }

        if (aNeg.length > 0 && bPos.length > 0) {
            if (x >= 0) {
                cnt += (long) aNeg.length * bPos.length;
            } else {
                for (int a : aNeg) {
                    long threshold = x / a;
                    if (x % a != 0) threshold++;
                    int idx = lowerBound(bPos, threshold);
                    cnt += bPos.length - idx;
                }
            }
        }

        if (aPos.length > 0 && bNeg.length > 0) {
            if (x >= 0) {
                cnt += (long) aPos.length * bNeg.length;
            } else {
                for (int a : aPos) {
                    long threshold = x / a;
                    if (x % a != 0) threshold--;
                    int idx = upperBound(bNeg, threshold);
                    cnt += idx;
                }
            }
        }

        if (aPos.length > 0 && bPos.length > 0 && x >= 0) {
            cnt += countPosPos(aPos, bPos, x);
        }

        if (aNegAbs.length > 0 && bNegAbs.length > 0 && x >= 0) {
            cnt += countPosPosAbs(aNegAbs, bNegAbs, x);
        }

        return cnt;
    }

    private static long countPosPos(int[] A, int[] B, long x) {
        long cnt = 0;
        int j = B.length - 1;
        for (int a : A) {
            while (j >= 0 && (long) a * B[j] > x) {
                j--;
            }
            if (j < 0) break;
            cnt += j + 1;
        }
        return cnt;
    }

    private static long countPosPosAbs(long[] A, long[] B, long x) {
        long cnt = 0;
        int j = B.length - 1;
        for (long a : A) {
            while (j >= 0 && a * B[j] > x) {
                j--;
            }
            if (j < 0) break;
            cnt += j + 1;
        }
        return cnt;
    }

    private static int lowerBound(int[] arr, long target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (arr[m] < target) l = m + 1;
            else r = m;
        }
        return l;
    }

    private static int upperBound(int[] arr, long target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (arr[m] <= target) l = m + 1;
            else r = m;
        }
        return l;
    }
}

class Bank {
    long[] bal;
    int n;
    public Bank(long[] balance) { bal = balance; n = balance.length; }
    public boolean withdraw(int account, long money) {
        int acc = account - 1;
        if (acc < 0 || acc >= n || bal[acc] < money) return false;
        bal[acc] -= money;
        return true;
    }
    public boolean deposit(int account, long money) {
        int acc = account - 1;
        if (acc < 0 || acc >= n) return false;
        bal[acc] += money;
        return true;
    }
    public boolean transfer(int account1, int account2, long money) {
        int a1 = account1-1, a2 = account2-1;
        if (a1<0||a1>=n||a2<0||a2>=n||bal[a1]<money) return false;
        bal[a1] -= money; bal[a2] += money;
        return true;
    }
}

import java.util.*;

class Solution {
    public static int secondMinimum(int n, int[][] edges, int time, int change) {
        List<Integer>[] graph = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }

        int INF = Integer.MAX_VALUE;
        int[] first = new int[n + 1];
        int[] second = new int[n + 1];
        Arrays.fill(first, INF);
        Arrays.fill(second, INF);
        first[1] = 0;

        ArrayDeque<int[]> q = new ArrayDeque<>();
        q.offer(new int[]{1, 0});

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int node = cur[0];
            int dist = cur[1];
            for (int nb : graph[node]) {
                int nd = dist + 1;
                if (nd < first[nb]) {
                    second[nb] = first[nb];
                    first[nb] = nd;
                    q.offer(new int[]{nb, nd});
                } else if (nd > first[nb] && nd < second[nb]) {
                    second[nb] = nd;
                    q.offer(new int[]{nb, nd});
                }
            }
        }

        int steps = second[n];
        long curTime = 0;
        for (int i = 0; i < steps; i++) {
            if ((curTime / change) % 2 == 1) {
                curTime += change - (curTime % change);
            }
            curTime += time;
        }
        return (int) curTime;
    }
}

