public class Solution {
    public static int networkBecomesIdle(int[][] edges, int[] patience) {
        int n = patience.length;
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            adj[u].add(v);
            adj[v].add(u);
        }
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        int[] queue = new int[n];
        int head = 0, tail = 0;
        queue[tail++] = 0;
        dist[0] = 0;
        while (head < tail) {
            int cur = queue[head++];
            for (int nb : adj[cur]) {
                if (dist[nb] == -1) {
                    dist[nb] = dist[cur] + 1;
                    queue[tail++] = nb;
                }
            }
        }
        long answer = 0;
        for (int i = 1; i < n; i++) {
            long roundTrip = dist[i] * 2L;
            long lastSend = ((roundTrip - 1) / patience[i]) * patience[i];
            long arrival = lastSend + roundTrip;
            if (arrival > answer) {
                answer = arrival;
            }
        }
        return (int) (answer + 1);
    }
}

public class Solution {
    public static boolean areNumbersAscending(String s) {
        int prev = -1;
        int i = 0;
        int n = s.length();
        while (i < n) {
            while (i < n && s.charAt(i) == ' ') i++;
            if (i >= n) break;
            if (s.charAt(i) >= '0' && s.charAt(i) <= '9') {
                int num = 0;
                while (i < n && s.charAt(i) != ' ') {
                    num = num * 10 + (s.charAt(i) - '0');
                    i++;
                }
                if (num <= prev) return false;
                prev = num;
            } else {
                while (i < n && s.charAt(i) != ' ') i++;
            }
        }
        return true;
    }
}

