class Solution {
    public static long countMaxOrSubsets(int[] nums) {
        int maxOr = 0;
        for (int v : nums) {
            maxOr |= v;
        }
        Map<Integer, Long> cnt = new HashMap<>();
        for (int x : nums) {
            Map<Integer, Long> add = new HashMap<>();
            for (Map.Entry<Integer, Long> entry : cnt.entrySet()) {
                int newOr = entry.getKey() | x;
                add.put(newOr, add.getOrDefault(newOr, 0L) + entry.getValue());
            }
            add.put(x, add.getOrDefault(x, 0L) + 1L);
            for (Map.Entry<Integer, Long> entry : add.entrySet()) {
                cnt.put(entry.getKey(), cnt.getOrDefault(entry.getKey(), 0L) + entry.getValue());
            }
        }
        return cnt.getOrDefault(maxOr, 0L);
    }
}

import java.util.*;

class Solution {
    private static final List<Integer> BEAUTIFUL_NUMBERS = new ArrayList<>();

    static {
        generateBeautifulNumbers();
        Collections.sort(BEAUTIFUL_NUMBERS);
    }

    public static int nextBeautifulNumber(int n) {
        int left = 0, right = BEAUTIFUL_NUMBERS.size();
        while (left < right) {
            int mid = (left + right) >>> 1;
            if (BEAUTIFUL_NUMBERS.get(mid) <= n) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return BEAUTIFUL_NUMBERS.get(left);
    }

    private static void generateBeautifulNumbers() {
        int[] cur = new int[10];
        dfs(1, cur, 0);
    }

    private static void dfs(int digit, int[] cur, int len) {
        if (digit > 9) {
            if (len > 0) {
                int[] perm = Arrays.copyOf(cur, len);
                do {
                    long val = 0;
                    for (int d : perm) {
                        val = val * 10 + d;
                    }
                    if (val <= Integer.MAX_VALUE) {
                        BEAUTIFUL_NUMBERS.add((int) val);
                    }
                } while (nextPermutation(perm));
            }
            return;
        }
        dfs(digit + 1, cur, len);
        if (len + digit <= 10) {
            for (int i = 0; i < digit; i++) {
                cur[len + i] = digit;
            }
            dfs(digit + 1, cur, len + digit);
        }
    }

    private static boolean nextPermutation(int[] arr) {
        int i = arr.length - 2;
        while (i >= 0 && arr[i] >= arr[i + 1]) i--;
        if (i < 0) return false;
        int j = arr.length - 1;
        while (arr[j] <= arr[i]) j--;
        int tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
        for (int l = i + 1, r = arr.length - 1; l < r; l++, r--) {
            tmp = arr[l];
            arr[l] = arr[r];
            arr[r] = tmp;
        }
        return true;
    }
}

