import java.math.BigInteger;

class Solution {
    public static int countHighestScoreNodes(int[] parents) {
        int n = parents.length;
        List<Integer>[] children = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            children[i] = new ArrayList<>();
        }
        for (int i = 1; i < n; i++) {
            children[parents[i]].add(i);
        }
        int[] order = new int[n];
        int orderIdx = 0;
        int[] stack = new int[n];
        int sp = 0;
        stack[sp++] = 0;
        while (sp > 0) {
            int v = stack[--sp];
            order[orderIdx++] = v;
            for (int c : children[v]) {
                stack[sp++] = c;
            }
        }
        int[] subSize = new int[n];
        for (int i = n - 1; i >= 0; i--) {
            int v = order[i];
            int sz = 1;
            for (int c : children[v]) {
                sz += subSize[c];
            }
            subSize[v] = sz;
        }
        BigInteger maxScore = BigInteger.valueOf(-1);
        int count = 0;
        for (int i = 0; i < n; i++) {
            BigInteger product = BigInteger.ONE;
            int rest = n - subSize[i];
            if (rest > 0) {
                product = product.multiply(BigInteger.valueOf(rest));
            }
            for (int c : children[i]) {
                product = product.multiply(BigInteger.valueOf(subSize[c]));
            }
            int cmp = product.compareTo(maxScore);
            if (cmp > 0) {
                maxScore = product;
                count = 1;
            } else if (cmp == 0) {
                count++;
            }
        }
        return count;
    }
}

import java.util.*;

class Solution {
    public static int minimumTime(int n, int[][] relations, int[] time) {
        int[] indeg = new int[n];
        int[] outCount = new int[n];
        for (int[] rel : relations) {
            int u = rel[0] - 1;
            int v = rel[1] - 1;
            indeg[v]++;
            outCount[u]++;
        }
        int[][] adj = new int[n][];
        for (int i = 0; i < n; i++) {
            adj[i] = new int[outCount[i]];
        }
        int[] pos = new int[n];
        for (int[] rel : relations) {
            int u = rel[0] - 1;
            int v = rel[1] - 1;
            adj[u][pos[u]++] = v;
        }
        int[] dp = new int[n];
        int[] queue = new int[n];
        int head = 0, tail = 0;
        for (int i = 0; i < n; i++) {
            if (indeg[i] == 0) {
                dp[i] = time[i];
                queue[tail++] = i;
            }
        }
        while (head < tail) {
            int u = queue[head++];
            for (int v : adj[u]) {
                int cand = dp[u] + time[v];
                if (cand > dp[v]) dp[v] = cand;
                if (--indeg[v] == 0) {
                    queue[tail++] = v;
                }
            }
        }
        int ans = 0;
        for (int val : dp) if (val > ans) ans = val;
        return ans;
    }
}

import java.util.*;

class Solution {
    public static int countValidWords(String sentence) {
        String[] tokens = sentence.split(" ");
        int validCount = 0;
        for (int i = 0; i < tokens.length; i++) {
            String token = tokens[i];
            if (token.length() == 0) continue;
            boolean hyphenSeen = false, punctSeen = false;
            boolean ok = true;
            for (int j = 0; j < token.length(); j++) {
                int c = token.charAt(j);
                if (c >= '0' && c <= '9') { ok = false; break; }
                if (c == '-') {
                    if (hyphenSeen) { ok = false; break; }
                    if (j == 0 || j == token.length() - 1) { ok = false; break; }
                    int prev = token.charAt(j - 1);
                    int next = token.charAt(j + 1);
                    if (!(prev >= 'a' && prev <= 'z' && next >= 'a' && next <= 'z')) {
                        ok = false; break;
                    }
                    hyphenSeen = true;
                    continue;
                }
                if (c == '!' || c == '.' || c == ',') {
                    if (punctSeen) { ok = false; break; }
                    if (j != token.length() - 1) { ok = false; break; }
                    punctSeen = true;
                    continue;
                }
                if (c >= 'a' && c <= 'z') continue;
                ok = false; break;
            }
            if (ok) validCount++;
        }
        return validCount;
    }
}

