import java.util.Arrays;

public class Solution {
    public static int maxTwoEvents(int[][] events) {
        int n = events.length;
        int[][] ev = Arrays.copyOf(events, n);
        Arrays.sort(ev, (a, b) -> Integer.compare(a[1], b[1]));
        int[] ends = new int[n];
        int[] prefMax = new int[n];
        int bestSingle = 0;
        int bestTwo = 0;
        for (int i = 0; i < n; i++) {
            ends[i] = ev[i][1];
            int val = ev[i][2];
            prefMax[i] = i == 0 ? val : Math.max(prefMax[i - 1], val);
            bestSingle = Math.max(bestSingle, val);
        }
        for (int i = 0; i < n; i++) {
            int start = ev[i][0];
            int val = ev[i][2];
            int lo = 0, hi = i - 1, j = -1;
            while (lo <= hi) {
                int mid = (lo + hi) >>> 1;
                if (ends[mid] < start) {
                    j = mid;
                    lo = mid + 1;
                } else {
                    hi = mid - 1;
                }
            }
            if (j != -1) {
                bestTwo = Math.max(bestTwo, val + prefMax[j]);
            }
        }
        return Math.max(bestSingle, bestTwo);
    }
}

