class Solution {
    public static int countValidMoveCombinations(String[] pieces, int[][] positions) {
        int n = pieces.length;
        List<long[]> optionsList = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            optionsList.add(generateMasks(pieces[i], positions[i][0], positions[i][1]));
        }
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, Comparator.comparingInt(i -> optionsList.get(i).length));
        long[][] orderedOptions = new long[n][];
        for (int i = 0; i < n; i++) {
            orderedOptions[i] = optionsList.get(order[i]);
        }
        @SuppressWarnings("unchecked")
        HashMap<Long, Long>[] memo = new HashMap[n];
        for (int i = 0; i < n; i++) memo[i] = new HashMap<>();
        long result = dfs(0, 0L, orderedOptions, memo);
        return (int) result;
    }

    private static long[] generateMasks(String type, int r0, int c0) {
        List<Long> list = new ArrayList<>();
        for (int r = 1; r <= 8; r++) {
            for (int c = 1; c <= 8; c++) {
                int dr = r - r0;
                int dc = c - c0;
                int absDr = Math.abs(dr);
                int absDc = Math.abs(dc);
                boolean ok;
                if (type.equals("rook")) {
                    ok = (r == r0 || c == c0);
                } else if (type.equals("bishop")) {
                    ok = (absDr == absDc);
                } else {
                    ok = (r == r0 || c == c0 || absDr == absDc);
                }
                if (!ok) continue;
                int stepR = Integer.signum(dr);
                int stepC = Integer.signum(dc);
                long mask = 0L;
                int curR = r0;
                int curC = c0;
                while (true) {
                    int idx = (curR - 1) * 8 + (curC - 1);
                    mask |= 1L << idx;
                    if (curR == r && curC == c) break;
                    curR += stepR;
                    curC += stepC;
                }
                list.add(mask);
            }
        }
        long[] arr = new long[list.size()];
        for (int i = 0; i < list.size(); i++) arr[i] = list.get(i);
        return arr;
    }

    private static long dfs(int idx, long usedMask, long[][] options, HashMap<Long, Long>[] memo) {
        if (idx == options.length) return 1L;
        Long cached = memo[idx].get(usedMask);
        if (cached != null) return cached;
        long total = 0L;
        for (long optMask : options[idx]) {
            if ((usedMask & optMask) == 0L) {
                total += dfs(idx + 1, usedMask | optMask, options, memo);
            }
        }
        memo[idx].put(usedMask, total);
        return total;
    }
}

import java.util.*;

class Solution {
    public static boolean possiblyEquals(String s1, String s2) {
        int n1 = s1.length(), n2 = s2.length();
        Set<Long> visited = new HashSet<>();
        return dfs(s1, s2, 0, 0, 0, visited);
    }

    private static boolean dfs(String s1, String s2, int i, int j, int diff, Set<Long> visited) {
        long key = ((long) i << 32) | ((long) j << 16) | (diff + 5000);
        if (!visited.add(key)) return false;
        int n1 = s1.length(), n2 = s2.length();
        if (i == n1 && j == n2) return diff == 0;

        if (diff > 0) {
            if (j >= n2) return false;
            char c = s2.charAt(j);
            if (Character.isLetter(c)) {
                return dfs(s1, s2, i, j + 1, diff - 1, visited);
            } else {
                for (int[] num : numbers(s2, j)) {
                    if (dfs(s1, s2, i, num[1], diff - num[0], visited)) return true;
                }
                return false;
            }
        } else if (diff < 0) {
            if (i >= n1) return false;
            char c = s1.charAt(i);
            if (Character.isLetter(c)) {
                return dfs(s1, s2, i + 1, j, diff + 1, visited);
            } else {
                for (int[] num : numbers(s1, i)) {
                    if (dfs(s1, s2, num[1], j, diff + num[0], visited)) return true;
                }
                return false;
            }
        } else {
            if (i < n1 && Character.isLetter(s1.charAt(i)) && j < n2 && Character.isLetter(s2.charAt(j))) {
                if (s1.charAt(i) == s2.charAt(j)) {
                    return dfs(s1, s2, i + 1, j + 1, 0, visited);
                }
                return false;
            }
            if (i < n1 && Character.isDigit(s1.charAt(i))) {
                for (int[] num : numbers(s1, i)) {
                    if (dfs(s1, s2, num[1], j, diff + num[0], visited)) return true;
                }
            }
            if (j < n2 && Character.isDigit(s2.charAt(j))) {
                for (int[] num : numbers(s2, j)) {
                    if (dfs(s1, s2, i, num[1], diff - num[0], visited)) return true;
                }
            }
            return false;
        }
    }

    private static List<int[]> numbers(String s, int idx) {
        List<int[]> list = new ArrayList<>();
        int val = 0;
        int n = s.length();
        for (int k = idx; k < n && k < idx + 3; k++) {
            char c = s.charAt(k);
            if (!Character.isDigit(c)) break;
            val = val * 10 + (c - '0');
            list.add(new int[]{val, k + 1});
        }
        return list;
    }
}

