class Solution {
    public static int[] findCriticalPoints(ListNode head) {
        if (head == null || head.next == null || head.next.next == null) {
            return new int[]{-1, -1};
        }
        int idx = 0;
        int prevVal = head.val;
        ListNode cur = head.next;
        ListNode next = cur.next;
        int firstCrit = -1;
        int prevCrit = -1;
        int minDist = Integer.MAX_VALUE;
        int maxDist = 0;
        while (next != null) {
            if ((cur.val > prevVal && cur.val > next.val) ||
                (cur.val < prevVal && cur.val < next.val)) {
                if (firstCrit == -1) {
                    firstCrit = idx;
                } else {
                    int diff = idx - prevCrit;
                    if (diff < minDist) {
                        minDist = diff;
                    }
                    int span = idx - firstCrit;
                    if (span > maxDist) {
                        maxDist = span;
                    }
                }
                prevCrit = idx;
            }
            prevVal = cur.val;
            cur = next;
            next = next.next;
            idx++;
        }
        if (prevCrit == firstCrit) {
            return new int[]{-1, -1};
        }
        return new int[]{minDist, maxDist};
    }
}

