class Solution {
    public static int maxPathQuality(int[] values, int[][] edges, int maxTime) {
        int n = values.length;
        List<int[]>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0], v = e[1], t = e[2];
            graph[u].add(new int[]{v, t});
            graph[v].add(new int[]{u, t});
        }
        boolean[] visited = new boolean[n];
        int totalSum = 0;
        for (int v : values) totalSum += v;
        int[] best = new int[1];
        visited[0] = true;
        dfs(0, maxTime, values[0], values[0], totalSum, graph, visited, best, values);
        return best[0];
    }

    private static void dfs(int node, int timeLeft, int quality, int visitedSum, int totalSum,
                            List<int[]>[] graph, boolean[] visited, int[] best, int[] values) {
        if (node == 0) {
            if (quality > best[0]) best[0] = quality;
        }
        if (quality + (totalSum - visitedSum) <= best[0]) return;
        for (int[] edge : graph[node]) {
            int next = edge[0];
            int cost = edge[1];
            if (cost > timeLeft) continue;
            if (!visited[next]) {
                visited[next] = true;
                dfs(next, timeLeft - cost, quality + values[next], visitedSum + values[next],
                    totalSum, graph, visited, best, values);
                visited[next] = false;
            } else {
                dfs(next, timeLeft - cost, quality, visitedSum, totalSum, graph, visited, best, values);
            }
        }
    }
}

