import java.util.ArrayDeque;

class Solution {
    public static int minimumOperations(int[] nums, int start, int goal) {
        if (start == goal) return 0;
        final int MAX = 1000;
        boolean[] visited = new boolean[MAX + 1];
        ArrayDeque<int[]> queue = new ArrayDeque<>();
        if (0 <= start && start <= MAX) {
            visited[start] = true;
            queue.offer(new int[]{start, 0});
        }
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int x = cur[0];
            int steps = cur[1];
            for (int i = 0; i < nums.length; i++) {
                int add = x + nums[i];
                int sub = x - nums[i];
                if (add == goal || sub == goal) return steps + 1;
                if (0 <= add && add <= MAX && !visited[add]) {
                    visited[add] = true;
                    queue.offer(new int[]{add, steps + 1});
                }
                if (0 <= sub && sub <= MAX && !visited[sub]) {
                    visited[sub] = true;
                    queue.offer(new int[]{sub, steps + 1});
                }
            }
        }
        return -1;
    }
}

