class Solution {
    public static int countVowelSubstrings(String word) {
        int n = word.length();
        int total = 0;
        int i = 0;
        while (i < n) {
            if (!isVowel(word.charAt(i))) {
                i++;
                continue;
            }
            int start = i;
            while (i < n && isVowel(word.charAt(i))) {
                i++;
            }
            int end = i;
            total += countBlock(word, start, end);
        }
        return total;
    }

    private static int countBlock(String s, int start, int end) {
        int[] freq = new int[5];
        int missing = 5;
        int left = start;
        int total = 0;
        for (int right = start; right < end; right++) {
            int idx = vowelIndex(s.charAt(right));
            if (freq[idx] == 0) {
                missing--;
            }
            freq[idx]++;
            while (missing == 0) {
                total += end - right;
                int lIdx = vowelIndex(s.charAt(left));
                freq[lIdx]--;
                if (freq[lIdx] == 0) {
                    missing++;
                }
                left++;
            }
        }
        return total;
    }

    private static boolean isVowel(char c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    private static int vowelIndex(char c) {
        switch (c) {
            case 'a': return 0;
            case 'e': return 1;
            case 'i': return 2;
            case 'o': return 3;
            case 'u': return 4;
            default: return -1;
        }
    }
}

import java.util.TreeMap;

class Solution {
    public static int maxTaskAssign(int[] tasks, int[] workers, int pills, int strength) {
        java.util.Arrays.sort(tasks);
        java.util.Arrays.sort(workers);
        int low = 0;
        int high = Math.min(tasks.length, workers.length);
        while (low < high) {
            int mid = (low + high + 1) >>> 1;
            if (canAssign(mid, tasks, workers, pills, strength)) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return low;
    }

    private static boolean canAssign(int k, int[] tasks, int[] workers, int pills, int strength) {
        TreeMap<Integer, Integer> map = new TreeMap<>();
        for (int w : workers) {
            map.merge(w, 1, Integer::sum);
        }
        for (int i = k - 1; i >= 0; i--) {
            int task = tasks[i];
            Integer key = map.ceilingKey(task);
            if (key != null) {
                decrement(map, key);
                continue;
            }
            if (pills == 0) {
                return false;
            }
            int needed = task - strength;
            Integer key2 = map.ceilingKey(needed);
            if (key2 == null) {
                return false;
            }
            decrement(map, key2);
            pills--;
        }
        return true;
    }

    private static void decrement(TreeMap<Integer, Integer> map, int key) {
        int cnt = map.get(key);
        if (cnt == 1) {
            map.remove(key);
        } else {
            map.put(key, cnt - 1);
        }
    }
}

