class Solution {
    public static int[] mostBeautifulItem(int[][] items, int[] queries) {
        int n = items.length;
        int[][] sorted = items.clone();
        Arrays.sort(sorted, (a, b) -> Integer.compare(a[0], b[0]));

        int[] priceList = new int[n];
        int[] bestList = new int[n];
        int curMax = 0;
        for (int i = 0; i < n; i++) {
            int price = sorted[i][0];
            int beauty = sorted[i][1];
            curMax = Math.max(curMax, beauty);
            priceList[i] = price;
            bestList[i] = curMax;
        }

        int m = queries.length;
        int[] answers = new int[m];
        for (int i = 0; i < m; i++) {
            int q = queries[i];
            int lo = 0, hi = n - 1, idx = -1;
            while (lo <= hi) {
                int mid = (lo + hi) >>> 1;
                if (priceList[mid] <= q) {
                    idx = mid;
                    lo = mid + 1;
                } else {
                    hi = mid - 1;
                }
            }
            answers[i] = idx == -1 ? 0 : bestList[idx];
        }
        return answers;
    }
}

