class Solution {
    public static int minimizedMaximum(int n, int[] quantities) {
        int low = 1;
        int high = 0;
        for (int q : quantities) {
            if (q > high) high = q;
        }
        while (low < high) {
            int mid = (low + high) / 2;
            long needed = 0;
            for (int q : quantities) {
                needed += (q + mid - 1) / mid;
                if (needed > n) break;
            }
            if (needed <= n) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}

