class Solution {
    public ListNode reverseEvenLengthGroups(ListNode head) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode prevGroupTail = dummy;
        ListNode current = head;
        int groupSize = 1;

        while (current != null) {
            ListNode groupHead = current;
            int count = 0;
            ListNode prev = null;
            while (count < groupSize && current != null) {
                prev = current;
                current = current.next;
                count++;
            }
            ListNode groupTail = prev;
            ListNode nextGroupHead = current;

            if (count % 2 == 0) {
                ListNode prevNode = null;
                ListNode node = groupHead;
                while (node != nextGroupHead) {
                    ListNode nxt = node.next;
                    node.next = prevNode;
                    prevNode = node;
                    node = nxt;
                }
                prevGroupTail.next = groupTail;
                groupHead.next = nextGroupHead;
                prevGroupTail = groupHead;
            } else {
                prevGroupTail = groupTail;
            }

            groupSize++;
        }

        return dummy.next;
    }
}

