public class Solution {
    private static int find(int[] parent, int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    private static void union(int[] parent, int[] rank, int a, int b) {
        int ra = find(parent, a);
        int rb = find(parent, b);
        if (ra == rb) return;
        if (rank[ra] < rank[rb]) {
            parent[ra] = rb;
        } else if (rank[ra] > rank[rb]) {
            parent[rb] = ra;
        } else {
            parent[rb] = ra;
            rank[ra]++;
        }
    }

    public static List<Boolean> processRestrictedFriendRequests(int n, int[][] restrictions, int[][] requests) {
        int[] parent = new int[n];
        int[] rank = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
        List<Boolean> answer = new ArrayList<>();
        for (int[] req : requests) {
            int u = req[0];
            int v = req[1];
            int ru = find(parent, u);
            int rv = find(parent, v);
            if (ru == rv) {
                answer.add(true);
                continue;
            }
            boolean conflict = false;
            for (int[] restr : restrictions) {
                int x = restr[0];
                int y = restr[1];
                int rx = find(parent, x);
                int ry = find(parent, y);
                if ((rx == ru && ry == rv) || (rx == rv && ry == ru)) {
                    conflict = true;
                    break;
                }
            }
            if (conflict) {
                answer.add(false);
            } else {
                answer.add(true);
                union(parent, rank, ru, rv);
            }
        }
        return answer;
    }
}

import java.util.*;

class Solution {
    public static long sumOfMirroredNumbers(int k, int n) {
        long sum = 0;
        int found = 0;
        int length = 1;
        while (found < n) {
            int half = (length + 1) / 2;
            long start = (half == 1) ? 1 : pow10(half - 1);
            long end = pow10(half) - 1;
            for (long prefix = start; prefix <= end && found < n; prefix++) {
                long palindrome = buildPalindrome(prefix, length % 2 == 0);
                if (isPalindromeInBase(palindrome, k)) {
                    sum += palindrome;
                    found++;
                }
            }
            length++;
        }
        return sum;
    }

    private static long buildPalindrome(long prefix, boolean even) {
        long pal = prefix;
        long x = even ? prefix : prefix / 10;
        while (x > 0) {
            pal = pal * 10 + (x % 10);
            x /= 10;
        }
        return pal;
    }

    private static boolean isPalindromeInBase(long num, int base) {
        int[] digits = new int[64];
        int len = 0;
        long x = num;
        while (x > 0) {
            digits[len++] = (int) (x % base);
            x /= base;
        }
        for (int i = 0, j = len - 1; i < j; i++, j--) {
            if (digits[i] != digits[j]) return false;
        }
        return true;
    }

    private static long pow10(int exp) {
        long result = 1;
        for (int i = 0; i < exp; i++) result *= 10;
        return result;
    }
}

class Solution {
    public static int maxDistance(int[] colors) {
        int n = colors.length;
        if (colors[0] != colors[n - 1]) return n - 1;

        int leftDiff = -1;
        int rightColor = colors[n - 1];
        for (int i = 0; i < n; i++) {
            if (colors[i] != rightColor) {
                leftDiff = i;
                break;
            }
        }

        int rightDiff = -1;
        int leftColor = colors[0];
        for (int i = n - 1; i >= 0; i--) {
            if (colors[i] != leftColor) {
                rightDiff = i;
                break;
            }
        }

        int distFromLeft = leftDiff == -1 ? 0 : n - 1 - leftDiff;
        int distFromRight = rightDiff == -1 ? 0 : rightDiff;

        return Math.max(distFromLeft, distFromRight);
    }
}

import java.util.*;
class RangeFreqQuery {
    private final Map<Integer, int[]> posMap;
    public RangeFreqQuery(int[] nums) {
        Map<Integer, List<Integer>> tempMap = new HashMap<>();
        for (int i = 0; i < nums.length; i++) tempMap.computeIfAbsent(nums[i], k -> new ArrayList<>()).add(i);
        posMap = new HashMap<>();
        for (Map.Entry<Integer, List<Integer>> e : tempMap.entrySet()) {
            List<Integer> list = e.getValue();
            int[] arr = new int[list.size()];
            for (int i = 0; i < list.size(); i++) arr[i] = list.get(i);
            posMap.put(e.getKey(), arr);
        }
    }
    public int query(int left, int right, int value) {
        int[] list = posMap.get(value);
        if (list == null) return 0;
        return upperBound(list, right) - lowerBound(list, left);
    }
    private static int lowerBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) { int mid = (lo+hi)>>>1; if (arr[mid]<target) lo=mid+1; else hi=mid; }
        return lo;
    }
    private static int upperBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) { int mid = (lo+hi)>>>1; if (arr[mid]<=target) lo=mid+1; else hi=mid; }
        return lo;
    }
}

