            if (s[i] != 'H') continue;
            boolean fed = false;
            if (i > 0 && s[i - 1] == 'B') fed = true;
            if (i + 1 < n && s[i + 1] == 'B') fed = true;
            if (fed) continue;
            if (i + 1 < n && s[i + 1] == '.') {
                s[i + 1] = 'B';
                ans++;
            } else if (i - 1 >= 0 && s[i - 1] == '.') {
                s[i - 1] = 'B';
                ans++;
            } else {
                return -1;
            }
        }
        return ans;
    }
}

