        int n = grid[0].length;
        long total = 0;
        int[] prev = new int[n];
        int[] cur = new int[n];
        for (int i = m - 1; i >= 0; i--) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    if (i == m - 1 || j == 0 || j == n - 1) {
                        cur[j] = 1;
                    } else {
                        int min = prev[j - 1];
                        if (prev[j] < min) min = prev[j];
                        if (prev[j + 1] < min) min = prev[j + 1];
                        cur[j] = 1 + min;
                    }
                    if (cur[j] > 1) total += cur[j] - 1;
                } else {
                    cur[j] = 0;
                }
            }
            int[] temp = prev;
            prev = cur;
            cur = temp;
        }
        int[] prevInv = new int[n];
        int[] curInv = new int[n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    if (i == 0 || j == 0 || j == n - 1) {
                        curInv[j] = 1;
                    } else {
                        int min = prevInv[j - 1];
                        if (prevInv[j] < min) min = prevInv[j];
                        if (prevInv[j + 1] < min) min = prevInv[j + 1];
                        curInv[j] = 1 + min;
                    }
                    if (curInv[j] > 1) total += curInv[j] - 1;
                } else {
                    curInv[j] = 0;
                }
            }
            int[] temp = prevInv;
            prevInv = curInv;
            curInv = temp;
        }
        return (int) total;
    }
}

import java.util.Arrays;

class Solution {
    public static int[] kRadiusAverages(int[] nums, int k) {
        int n = nums.length;
        int[] result = new int[n];
        Arrays.fill(result, -1);
        int windowSize = 2 * k + 1;
        if (windowSize > n) return result;
        long sum = 0;
        for (int i = 0; i < windowSize; i++) sum += nums[i];
        for (int i = k; i <= n - k - 1; i++) {
            if (i > k) sum += nums[i + k] - nums[i - k - 1];
            result[i] = (int) (sum / windowSize);
        }
        return result;
    }
}

