class Solution {
    public static List<Integer> findEvenNumbers(int[] digits) {
        int[] freq = new int[10];
        for (int d : digits) {
            freq[d]++;
        }

        Set<Integer> resultSet = new HashSet<>();

        for (int a = 1; a <= 9; a++) {
            if (freq[a] == 0) continue;
            for (int b = 0; b <= 9; b++) {
                if (freq[b] == 0) continue;
                for (int c = 0; c <= 9; c += 2) {
                    if (freq[c] == 0) continue;

                    int[] need = new int[10];
                    need[a]++;
                    need[b]++;
                    need[c]++;

                    boolean ok = true;
                    for (int d = 0; d <= 9; d++) {
                        if (need[d] > freq[d]) {
                            ok = false;
                            break;
                        }
                    }
                    if (!ok) continue;

                    int number = 100 * a + 10 * b + c;
                    resultSet.add(number);
                }
            }
        }

        List<Integer> result = new ArrayList<>(resultSet);
        Collections.sort(result);
        return result;
    }
}

class Solution {
    public static ListNode deleteMiddle(ListNode head) {
        if (head == null || head.next == null) return null;
        ListNode slow = head;
        ListNode fast = head;
        ListNode prev = null;
        while (fast != null && fast.next != null) {
            fast = fast.next;
            if (fast != null) fast = fast.next;
            prev = slow;
            slow = slow.next;
        }
        prev.next = slow.next;
        return head;
    }
}

