public class Solution {
    public static int minDeletion(int[] nums) {
        int n = nums.length;
        int minIdx = 0, maxIdx = 0;
        for (int i = 1; i < n; i++) {
            if (nums[i] < nums[minIdx]) minIdx = i;
            if (nums[i] > nums[maxIdx]) maxIdx = i;
        }
        int frontBoth = Math.max(minIdx, maxIdx) + 1;
        int backBoth = n - Math.min(minIdx, maxIdx);
        int frontMinBackMax = minIdx + 1 + (n - maxIdx);
        int frontMaxBackMin = maxIdx + 1 + (n - minIdx);
        int ans = Math.min(Math.min(frontBoth, backBoth), Math.min(frontMinBackMax, frontMaxBackMin));
        return ans;
    }
}

