class Solution {
    private static int find(int v, Map<Integer, Integer> parent) {
        int p = parent.get(v);
        if (p != v) {
            int r = find(p, parent);
            parent.put(v, r);
            return r;
        }
        return v;
    }

    private static void union(int a, int b, Map<Integer, Integer> parent) {
        int ra = find(a, parent);
        int rb = find(b, parent);
        if (ra != rb) {
            parent.put(rb, ra);
        }
    }

    public static List<Integer> findAllPeople(int n, int[][] meetings, int firstPerson) {
        Arrays.sort(meetings, (a, b) -> Integer.compare(a[2], b[2]));

        boolean[] knows = new boolean[n];
        knows[0] = true;
        knows[firstPerson] = true;

        int i = 0;
        while (i < meetings.length) {
            int curTime = meetings[i][2];
            List<int[]> group = new ArrayList<>();
            Set<Integer> nodesSet = new HashSet<>();

            while (i < meetings.length && meetings[i][2] == curTime) {
                int x = meetings[i][0];
                int y = meetings[i][1];
                group.add(new int[]{x, y});
                nodesSet.add(x);
                nodesSet.add(y);
                i++;
            }

            Map<Integer, Integer> parent = new HashMap<>();
            for (int v : nodesSet) {
                parent.put(v, v);
            }

            for (int[] pair : group) {
                union(pair[0], pair[1], parent);
            }

            Map<Integer, Boolean> compHasSecret = new HashMap<>();
            for (int v : nodesSet) {
                int root = find(v, parent);
                if (knows[v]) {
                    compHasSecret.put(root, true);
                }
            }

            for (int v : nodesSet) {
                int root = find(v, parent);
                if (compHasSecret.getOrDefault(root, false)) {
                    knows[v] = true;
                }
            }
        }

        List<Integer> result = new ArrayList<>();
        for (int p = 0; p < n; p++) {
            if (knows[p]) {
                result.add(p);
            }
        }
        return result;
    }
}

