class Solution {
    private static class Pair {
        int value;
        int idx;
        Pair(int value, int idx) {
            this.value = value;
            this.idx = idx;
        }
    }

    public static int[] maxSubsequence(int[] nums, int k) {
        PriorityQueue<Pair> heap = new PriorityQueue<>(new Comparator<Pair>() {
            @Override
            public int compare(Pair a, Pair b) {
                if (a.value != b.value) {
                    return Integer.compare(a.value, b.value);
                }
                return Integer.compare(b.idx, a.idx);
            }
        });
        for (int i = 0; i < nums.length; i++) {
            heap.offer(new Pair(nums[i], i));
            if (heap.size() > k) {
                heap.poll();
            }
        }
        List<Pair> selected = new ArrayList<>(heap);
        selected.sort(Comparator.comparingInt(p -> p.idx));
        int[] result = new int[k];
        for (int i = 0; i < k; i++) {
            result[i] = selected.get(i).value;
        }
        return result;
    }
}

