class Solution {
    public String getDirections(TreeNode root, int startValue, int destValue) {
        TreeNode lca = findLCA(root, startValue, destValue);
        int upSteps = distance(lca, startValue);
        String downPath = pathFromNode(lca, destValue);
        return "U".repeat(upSteps) + (downPath == null ? "" : downPath);
    }

    private TreeNode findLCA(TreeNode node, int startValue, int destValue) {
        if (node == null) return null;
        if (node.val == startValue || node.val == destValue) return node;
        TreeNode left = findLCA(node.left, startValue, destValue);
        TreeNode right = findLCA(node.right, startValue, destValue);
        if (left != null && right != null) return node;
        return left != null ? left : right;
    }

    private int distance(TreeNode node, int target) {
        if (node == null) return -1;
        if (node.val == target) return 0;
        int left = distance(node.left, target);
        if (left != -1) return left + 1;
        int right = distance(node.right, target);
        if (right != -1) return right + 1;
        return -1;
    }

    private String pathFromNode(TreeNode node, int target) {
        if (node == null) return null;
        if (node.val == target) return "";
        String left = pathFromNode(node.left, target);
        if (left != null) return "L" + left;
        String right = pathFromNode(node.right, target);
        if (right != null) return "R" + right;
        return null;
    }
}

