class Solution {
    public static int[][] validArrangement(int[][] pairs) {
        if (pairs == null || pairs.length == 0) {
            return new int[0][0];
        }
        Map<Integer, Deque<Integer>> adj = new HashMap<>();
        Map<Integer, Integer> outDeg = new HashMap<>();
        Map<Integer, Integer> inDeg = new HashMap<>();
        Set<Integer> nodes = new HashSet<>();
        for (int[] p : pairs) {
            int u = p[0];
            int v = p[1];
            adj.computeIfAbsent(u, k -> new ArrayDeque<>()).add(v);
            outDeg.put(u, outDeg.getOrDefault(u, 0) + 1);
            inDeg.put(v, inDeg.getOrDefault(v, 0) + 1);
            nodes.add(u);
            nodes.add(v);
        }
        int start = -1;
        for (int node : nodes) {
            int out = outDeg.getOrDefault(node, 0);
            int in = inDeg.getOrDefault(node, 0);
            if (out - in == 1) {
                start = node;
                break;
            }
        }
        if (start == -1) {
            for (int node : nodes) {
                if (outDeg.getOrDefault(node, 0) > 0) {
                    start = node;
                    break;
                }
            }
        }
        Deque<Integer> stack = new ArrayDeque<>();
        int[][] ans = new int[pairs.length][2];
        int idx = pairs.length - 1;
        stack.push(start);
        while (!stack.isEmpty()) {
            int u = stack.peek();
            Deque<Integer> list = adj.get(u);
            if (list != null && !list.isEmpty()) {
                int v = list.pollFirst();
                stack.push(v);
            } else {
                stack.pop();
                if (!stack.isEmpty()) {
                    int prev = stack.peek();
                    ans[idx--] = new int[]{prev, u};
                }
            }
        }
        return ans;
    }
}

