class Solution {
    public static long subArrayRanges(int[] nums) {
        int n = nums.length;
        long[] left = new long[n];
        Deque<Integer> stack = new ArrayDeque<>();
        long maxSum = 0;
        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && nums[stack.peek()] <= nums[i]) {
                stack.pop();
            }
            left[i] = stack.isEmpty() ? i + 1L : i - stack.peek();
            stack.push(i);
        }
        stack.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && nums[stack.peek()] < nums[i]) {
                stack.pop();
            }
            long right = stack.isEmpty() ? n - i : stack.peek() - i;
            maxSum += (long) nums[i] * left[i] * right;
            stack.push(i);
        }
        long minSum = 0;
        stack.clear();
        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && nums[stack.peek()] >= nums[i]) {
                stack.pop();
            }
            left[i] = stack.isEmpty() ? i + 1L : i - stack.peek();
            stack.push(i);
        }
        stack.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && nums[stack.peek()] > nums[i]) {
                stack.pop();
            }
            long right = stack.isEmpty() ? n - i : stack.peek() - i;
            minSum += (long) nums[i] * left[i] * right;
            stack.push(i);
        }
        return maxSum - minSum;
    }
}

