public class Solution {
    public static int maxTotalFruits(int[][] fruits, int startPos, int k) {
        int n = fruits.length;
        long sum = 0, best = 0;
        int left = 0;
        for (int right = 0; right < n; right++) {
            sum += fruits[right][1];
            while (left <= right && !isFeasible(fruits[left][0], fruits[right][0], startPos, k)) {
                sum -= fruits[left][1];
                left++;
            }
            if (sum > best) {
                best = sum;
            }
        }
        return (int) best;
    }

    private static boolean isFeasible(int L, int R, int startPos, int k) {
        if (R <= startPos) {
            return startPos - L <= k;
        }
        if (L >= startPos) {
            return R - startPos <= k;
        }
        int leftDist = startPos - L;
        int rightDist = R - startPos;
        int steps1 = 2 * leftDist + rightDist;
        int steps2 = 2 * rightDist + leftDist;
        return Math.min(steps1, steps2) <= k;
    }
}

