class Solution {
    public static int maximumDetonation(int[][] bombs) {
        int n = bombs.length;
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int xi = bombs[i][0];
            int yi = bombs[i][1];
            int ri = bombs[i][2];
            int ri2 = ri * ri;
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                int xj = bombs[j][0];
                int yj = bombs[j][1];
                int dx = xi - xj;
                int dy = yi - yj;
                if (dx * dx + dy * dy <= ri2) adj[i].add(j);
            }
        }
        int best = 0;
        for (int start = 0; start < n; start++) {
            boolean[] visited = new boolean[n];
            Deque<Integer> queue = new ArrayDeque<>();
            queue.add(start);
            visited[start] = true;
            int count = 0;
            while (!queue.isEmpty()) {
                int v = queue.poll();
                count++;
                for (int w : adj[v]) {
                    if (!visited[w]) {
                        visited[w] = true;
                        queue.add(w);
                    }
                }
            }
            if (count > best) best = count;
        }
        return best;
    }
}

