public class Solution {
    private static class Location {
        String name;
        int score;
        Location(String name, int score) {
            this.name = name;
            this.score = score;
        }
    }

    private final PriorityQueue<Location> good;
    private final PriorityQueue<Location> bad;

    public Solution() {
        good = new PriorityQueue<>((a, b) -> {
            int cmp = Integer.compare(a.score, b.score);
            if (cmp != 0) return cmp;
            return b.name.compareTo(a.name);
        });
        bad = new PriorityQueue<>((a, b) -> {
            int cmp = Integer.compare(b.score, a.score);
            if (cmp != 0) return cmp;
            return a.name.compareTo(b.name);
        });
    }

    public void add(String name, int score) {
        Location loc = new Location(name, score);
        if (!good.isEmpty() && better(loc, good.peek())) {
            good.offer(loc);
            Location moved = good.poll();
            bad.offer(moved);
        } else {
            bad.offer(loc);
        }
    }

    public String get() {
        Location moved = bad.poll();
        good.offer(moved);
        return good.peek().name;
    }

    private boolean better(Location a, Location b) {
        if (a.score != b.score) return a.score > b.score;
        return a.name.compareTo(b.name) < 0;
    }
}

class Solution {
