class Solution {
    public static int wateringPlants(int[] plants, int capacityA, int capacityB) {
        int left = 0, right = plants.length - 1;
        int waterA = capacityA, waterB = capacityB;
        int refill = 0;

        while (left <= right) {
            if (left == right) {
                if (waterA < plants[left]) {
                    refill++;
                    waterA = capacityA;
                }
                break;
            }

            if (waterA < plants[left]) {
                refill++;
                waterA = capacityA;
            }
            waterA -= plants[left];
            left++;

            if (waterB < plants[right]) {
                refill++;
                waterB = capacityB;
            }
            waterB -= plants[right];
            right--;
        }

        return refill;
    }
}

