class Solution {
    public static int minOperations(int[] arr, int k) {
        int n = arr.length;
        int kept = 0;
        for (int start = 0; start < k; ++start) {
            int groupSize = (n - start + k - 1) / k;
            int[] tails = new int[groupSize];
            int len = 0;
            for (int i = start; i < n; i += k) {
                int x = arr[i];
                int lo = 0, hi = len;
                while (lo < hi) {
                    int mid = (lo + hi) >>> 1;
                    if (tails[mid] > x) {
                        hi = mid;
                    } else {
                        lo = mid + 1;
                    }
                }
                int pos = lo;
                if (pos == len) {
                    tails[len++] = x;
                } else {
                    tails[pos] = x;
                }
            }
            kept += len;
        }
        return n - kept;
    }
}

