class Solution {
    public static List<String> findAllRecipes(String[] recipes, List<List<String>> ingredients, String[] supplies) {
        Set<String> available = new HashSet<>(Arrays.asList(supplies));
        Set<String> recipeSet = new HashSet<>(Arrays.asList(recipes));

        Map<String, Integer> indegree = new HashMap<>();
        Map<String, List<String>> graph = new HashMap<>();
        Map<String, Boolean> possible = new HashMap<>();

        for (String r : recipes) {
            indegree.put(r, 0);
            possible.put(r, true);
        }

        for (int i = 0; i < recipes.length; i++) {
            String rec = recipes[i];
            for (String ing : ingredients.get(i)) {
                if (recipeSet.contains(ing)) {
                    indegree.put(rec, indegree.get(rec) + 1);
                    graph.computeIfAbsent(ing, k -> new ArrayList<>()).add(rec);
                } else if (!available.contains(ing)) {
                    possible.put(rec, false);
                }
            }
        }

        List<String> queue = new ArrayList<>();
        int qHead = 0;
        for (String r : recipes) {
            if (possible.get(r) && indegree.get(r) == 0) {
                queue.add(r);
            }
        }

        List<String> result = new ArrayList<>();
        while (qHead < queue.size()) {
            String cur = queue.get(qHead++);
            result.add(cur);
            available.add(cur);
            if (!graph.containsKey(cur)) continue;
            for (String nxt : graph.get(cur)) {
                indegree.put(nxt, indegree.get(nxt) - 1);
                if (indegree.get(nxt) == 0 && possible.get(nxt)) {
                    queue.add(nxt);
                }
            }
        }
        return result;
    }
}

