class Solution {
    public static boolean canBeValid(String s, String locked) {
        int n = s.length();
        if (n % 2 == 1) return false;
        int balance = 0;
        int free = 0;
        for (int i = 0; i < n; i++) {
            if (locked.charAt(i) == '1') {
                balance += s.charAt(i) == '(' ? 1 : -1;
            } else {
                free++;
            }
            if (balance < 0) {
                if (free == 0) return false;
                free--;
                balance++;
            }
        }
        return balance <= free;
    }
}

