public class Solution {
    public static String abbreviateProduct(int left, int right) {
        BigInteger prod = BigInteger.ONE;
        int zeroCnt = 0;
        for (int i = left; i <= right; i++) {
            prod = prod.multiply(BigInteger.valueOf(i));
            while (prod.mod(BigInteger.TEN).equals(BigInteger.ZERO)) {
                prod = prod.divide(BigInteger.TEN);
                zeroCnt++;
            }
        }
        String s = prod.toString();
        if (s.length() > 10) s = s.substring(0, 10);
        return s + "e" + zeroCnt;
    }
}

