class Solution {
    public static long[] intervalsBetweenIdentical(int[] arr) {
        Map<Integer, List<Integer>> groups = new HashMap<>();
        for (int i = 0; i < arr.length; i++) {
            int v = arr[i];
            groups.computeIfAbsent(v, k -> new ArrayList<>()).add(i);
        }

        long[] ans = new long[arr.length];
        for (List<Integer> indices : groups.values()) {
            int m = indices.size();
            if (m == 1) continue;
            long[] pref = new long[m];
            pref[0] = indices.get(0);
            for (int i = 1; i < m; i++) {
                pref[i] = pref[i - 1] + indices.get(i);
            }
            long total = pref[m - 1];
            for (int i = 0; i < m; i++) {
                int idx = indices.get(i);
                long left = (long) idx * i - (i > 0 ? pref[i - 1] : 0);
                long right = (total - pref[i]) - (long) idx * (m - i - 1);
                ans[idx] = left + right;
            }
        }
        return ans;
    }
}

