class Solution {
    public static int[] recoverArray(int[] nums) {
        int m = nums.length;
        int n = m / 2;
        Arrays.sort(nums);
        int smallest = nums[0];
        for (int i = 1; i < m; i++) {
            int diff = nums[i] - smallest;
            if (diff <= 0 || (diff & 1) == 1) continue;
            int k = diff / 2;
            if (k <= 0) continue;
            Map<Integer, Integer> freq = new HashMap<>();
            for (int v : nums) {
                freq.put(v, freq.getOrDefault(v, 0) + 1);
            }
            List<Integer> original = new ArrayList<>(n);
            boolean ok = true;
            for (int v : nums) {
                Integer cntLow = freq.get(v);
                if (cntLow == null || cntLow == 0) continue;
                if (cntLow == 1) freq.remove(v);
                else freq.put(v, cntLow - 1);
                int high = v + 2 * k;
                Integer cntHigh = freq.get(high);
                if (cntHigh == null || cntHigh == 0) {
                    ok = false;
                    break;
                }
                if (cntHigh == 1) freq.remove(high);
                else freq.put(high, cntHigh - 1);
                original.add(v + k);
                if (original.size() > n) {
                    ok = false;
                    break;
                }
            }
            if (ok && original.size() == n) {
                int[] result = new int[n];
                for (int j = 0; j < n; j++) result[j] = original.get(j);
                return result;
            }
        }
        return new int[0];
    }
}

