class ListNode {
    int val;
    ListNode next;
    ListNode() {}
    ListNode(int val) { this.val = val; }
    ListNode(int val, ListNode next) { this.val = val; this.next = next; }
}

class Solution {
    public static int maxTwinSum(ListNode head) {
        ListNode slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }
        ListNode prev = null, curr = slow;
        while (curr != null) {
            ListNode nxt = curr.next;
            curr.next = prev;
            prev = curr;
            curr = nxt;
        }
        int maxSum = 0;
        ListNode left = head, right = prev;
        while (right != null) {
            int twinSum = left.val + right.val;
            if (twinSum > maxSum) maxSum = twinSum;
            left = left.next;
            right = right.next;
        }
        return maxSum;
    }
}

