import java.util.*;

class Solution {
    public static int maximumInvitations(int[] favorite) {
        int n = favorite.length;
        int[] indeg = new int[n];
        for (int i = 0; i < n; i++) indeg[favorite[i]]++;
        int[] longest = new int[n];
        Deque<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < n; i++) if (indeg[i] == 0) queue.add(i);
        while (!queue.isEmpty()) {
            int u = queue.poll();
            int v = favorite[u];
            longest[v] = Math.max(longest[v], longest[u] + 1);
            if (--indeg[v] == 0) queue.add(v);
        }
        int maxCycle = 0;
        int[] visited = new int[n];
        int[] depth = new int[n];
        for (int i = 0; i < n; i++) {
            if (visited[i] != 0) continue;
            int cur = i;
            int step = 1;
            while (visited[cur] == 0) {
                visited[cur] = i + 1;
                depth[cur] = step;
                step++;
                cur = favorite[cur];
            }
            if (visited[cur] == i + 1) {
                int cycleLen = step - depth[cur];
                if (cycleLen > maxCycle) maxCycle = cycleLen;
            }
        }
        int sumPairs = 0;
        for (int i = 0; i < n; i++) {
            int j = favorite[i];
            if (i < j && favorite[j] == i) {
                sumPairs += 2 + longest[i] + longest[j];
            }
        }
        return Math.max(maxCycle, sumPairs);
    }
}

