class Solution {
    public static int minSwaps(int[] nums) {
        int n = nums.length;
        int totalOnes = 0;
        for (int i = 0; i < n; ++i) totalOnes += nums[i];
        if (totalOnes <= 1) return 0;
        int onesInWindow = 0;
        for (int i = 0; i < totalOnes; ++i) onesInWindow += nums[i];
        int maxOnes = onesInWindow;
        for (int start = 1; start < n; ++start) {
            int outIdx = start - 1;
            int inIdx = (start + totalOnes - 1) % n;
            onesInWindow += nums[inIdx] - nums[outIdx];
            if (onesInWindow > maxOnes) maxOnes = onesInWindow;
        }
        return totalOnes - maxOnes;
    }
}

