class Solution {
    public static int longestPalindrome(String[] words) {
        Map<String, Integer> freq = new HashMap<>();
        for (String w : words) {
            freq.put(w, freq.getOrDefault(w, 0) + 1);
        }

        int length = 0;
        boolean hasCenter = false;

        for (String w : freq.keySet()) {
            int cnt = freq.get(w);
            if (cnt == 0) continue;
            String rev = "" + w.charAt(1) + w.charAt(0);

            if (w.equals(rev)) {
                int pairs = cnt / 2;
                length += pairs * 4;
                if (cnt % 2 == 1) hasCenter = true;
            } else if (freq.containsKey(rev)) {
                int revCnt = freq.get(rev);
                int pairs = Math.min(cnt, revCnt);
                length += pairs * 4;
                freq.put(rev, 0);
            }
        }

        if (hasCenter) length += 2;
        return length;
    }
}

