        for (int i = 0; i < n; i++) {
            seeds[i] = new Seed(plantTime[i], growTime[i]);
        }
        Arrays.sort(seeds, (a, b) -> Integer.compare(b.grow, a.grow));
        long currentDay = 0;
        long answer = 0;
        for (Seed seed : seeds) {
            currentDay += seed.plant;
            long bloomDay = currentDay + seed.grow;
            if (bloomDay > answer) {
                answer = bloomDay;
            }
        }
        return (int) answer;
    }
}

