class Solution {
    public static boolean isValidMatrix(int[][] matrix) {
        int n = matrix.length;
        for (int i = 0; i < n; i++) {
            if (matrix[i] == null || matrix[i].length != n) return false;
        }
        byte[] seenRow = new byte[n + 1];
        byte[] seenCol = new byte[n + 1];
        for (int i = 0; i < n; i++) {
            Arrays.fill(seenRow, (byte) 0);
            Arrays.fill(seenCol, (byte) 0);
            for (int j = 0; j < n; j++) {
                int rowVal = matrix[i][j];
                if (rowVal < 1 || rowVal > n || seenRow[rowVal] != 0) return false;
                seenRow[rowVal] = 1;
                int colVal = matrix[j][i];
                if (colVal < 1 || colVal > n || seenCol[colVal] != 0) return false;
                seenCol[colVal] = 1;
            }
        }
        return true;
    }
}

