class Solution {
    public static int maxPoints(int[][] questions) {
        int n = questions.length;
        int[] dp = new int[n + 1];
        for (int i = n - 1; i >= 0; i--) {
            int pts = questions[i][0];
            int skip = questions[i][1];
            int next = i + skip + 1;
            int take = pts + (next < n ? dp[next] : 0);
            int skipIt = dp[i + 1];
            dp[i] = take > skipIt ? take : skipIt;
        }
        return dp[0];
    }
}

