class Solution {
    public static int countWords(String[] startWords, String[] targetWords) {
        Set<Integer> startMasks = new HashSet<>();
        for (String w : startWords) {
            int mask = 0;
            for (int i = 0; i < w.length(); i++) {
                mask |= 1 << (w.charAt(i) - 'a');
            }
            startMasks.add(mask);
        }
        int answer = 0;
        for (String w : targetWords) {
            int mask = 0;
            for (int i = 0; i < w.length(); i++) {
                mask |= 1 << (w.charAt(i) - 'a');
            }
            for (int i = 0; i < w.length(); i++) {
                int without = mask ^ (1 << (w.charAt(i) - 'a'));
                if (startMasks.contains(without)) {
                    answer++;
                    break;
                }
            }
        }
        return answer;
    }
}

