        int pref = 0;
        int maxLow = lower;
        int minHigh = upper;
        for (int i = 0; i < differences.length; i++) {
            pref += differences[i];
            maxLow = Math.max(maxLow, lower - pref);
            minHigh = Math.min(minHigh, upper - pref);
        }
        int ans = Math.max(0, minHigh - maxLow + 1);
        return ans;
    }
}

public class Solution {
    public static long maxRunTime(int n, int[] batteries) {
        if (batteries.length < n) return 0;
        long totalSum = 0;
        for (int v : batteries) totalSum += v;
        long low = 0, high = totalSum / n;
        while (low < high) {
            long mid = (low + high + 1) / 2;
            long available = 0;
            for (int v : batteries) {
                available += v < mid ? v : mid;
                if (available >= (long) n * mid) break;
            }
            if (available >= (long) n * mid) low = mid;
            else high = mid - 1;
        }
        return low;
    }
}

