class Solution {
    public static long numberOfWays(String corridor) {
        List<Integer> seats = new ArrayList<>();
        for (int i = 0; i < corridor.length(); i++) {
            if (corridor.charAt(i) == 'S') {
                seats.add(i);
            }
        }
        if (seats.size() % 2 != 0) {
            return 0L;
        }
        long ways = 1L;
        for (int i = 1; i + 1 < seats.size(); i += 2) {
            long gap = seats.get(i + 1) - seats.get(i);
            ways *= gap;
        }
        return ways;
    }
}

