import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.PriorityQueue;
import java.util.Queue;

class Solution {
    public static List<List<Integer>> highestRankedKItems(int[][] grid, int[] pricing, int[] start, int k) {
        List<List<Integer>> result = new ArrayList<>();
        if (k <= 0) return result;
        int m = grid.length;
        int n = grid[0].length;
        int low = pricing[0];
        int high = pricing[1];
        boolean[][] visited = new boolean[m][n];
        if (grid[start[0]][start[1]] == 0) return result;
        Queue<int[]> q = new ArrayDeque<>();
        q.offer(new int[]{start[0], start[1], 0});
        visited[start[0]][start[1]] = true;
        Comparator<int[]> worstFirst = (a, b) -> {
            if (a[0] != b[0]) return Integer.compare(b[0], a[0]); // distance descending
            if (a[1] != b[1]) return Integer.compare(b[1], a[1]); // price descending
            if (a[2] != b[2]) return Integer.compare(b[2], a[2]); // row descending
            return Integer.compare(b[3], a[3]); // col descending
        };
        PriorityQueue<int[]> heap = new PriorityQueue<>(k, worstFirst);
        int maxDist = Integer.MAX_VALUE;
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1], d = cur[2];
            if (heap.size() == k && d > maxDist) break;
            int price = grid[r][c];
            if (price >= low && price <= high) {
                int[] cand = {d, price, r, c};
                if (heap.size() < k) {
                    heap.offer(cand);
                } else if (worstFirst.compare(cand, heap.peek()) < 0) {
                    heap.poll();
                    heap.offer(cand);
                }
                if (heap.size() == k) {
                    maxDist = heap.peek()[0];
                }
            }
            for (int[] dir : dirs) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc] && grid[nr][nc] > 0) {
                    visited[nr][nc] = true;
                    q.offer(new int[]{nr, nc, d + 1});
                }
            }
        }
        List<int[]> candidates = new ArrayList<>(heap);
        Collections.sort(candidates, (a, b) -> {
            if (a[0] != b[0]) return Integer.compare(a[0], b[0]); // distance
            if (a[1] != b[1]) return Integer.compare(a[1], b[1]); // price
            if (a[2] != b[2]) return Integer.compare(a[2], b[2]); // row
            return Integer.compare(a[3], b[3]); // col
        });
        for (int[] item : candidates) {
            List<Integer> pos = new ArrayList<>(2);
            pos.add(item[2]);
            pos.add(item[3]);
            result.add(pos);
        }
        return result;
    }
}

class Solution {
    public static int countElements(int[] nums) {
        int min = nums[0];
        int max = nums[0];
        for (int i = 1; i < nums.length; i++) {
            if (nums[i] < min) {
                min = nums[i];
            } else if (nums[i] > max) {
                max = nums[i];
            }
        }
        int cnt = 0;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] > min && nums[i] < max) {
                cnt++;
            }
        }
        return cnt;
    }
}

