public class Solution {
    public static String subStrHash(String s, int power, int modulo, int k, int hashValue) {
        int n = s.length();
        long mod = modulo;
        long powerK = 1;
        for (int i = 0; i < k - 1; i++) {
            powerK = (powerK * power) % mod;
        }
        long cur = 0;
        long curPow = 1;
        for (int i = n - k; i < n; i++) {
            int v = s.charAt(i) - 'a' + 1;
            cur = (cur + v * curPow) % mod;
            curPow = (curPow * power) % mod;
        }
        int ansIdx = -1;
        if (cur == hashValue) {
            ansIdx = n - k;
        }
        for (int i = n - k - 1; i >= 0; i--) {
            int leftVal = s.charAt(i) - 'a' + 1;
            int rightVal = s.charAt(i + k) - 'a' + 1;
            cur = (cur - (rightVal * powerK) % mod + mod) % mod;
            cur = (cur * power) % mod;
            cur = (cur + leftVal) % mod;
            if (cur == hashValue) {
                ansIdx = i;
            }
        }
        return ansIdx == -1 ? "" : s.substring(ansIdx, ansIdx + k);
    }
}

