class Solution {
    public static int[] groupStrings(String[] words) {
        int n = words.length;
        int[] masks = new int[n];
        Map<Integer, Integer> maskToIdx = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int mask = 0;
            for (char c : words[i].toCharArray()) {
                mask |= 1 << (c - 'a');
            }
            masks[i] = mask;
            if (!maskToIdx.containsKey(mask)) {
                maskToIdx.put(mask, maskToIdx.size());
            }
        }
        int m = maskToIdx.size();
        int[] count = new int[m];
        for (int mask : masks) {
            count[maskToIdx.get(mask)]++;
        }
        DSU dsu = new DSU(m);
        int[] uniqueMasks = new int[m];
        for (Map.Entry<Integer, Integer> e : maskToIdx.entrySet()) {
            uniqueMasks[e.getValue()] = e.getKey();
        }
        for (int i = 0; i < m; i++) {
            int mask = uniqueMasks[i];
            for (int b = 0; b < 26; b++) {
                if ((mask & (1 << b)) != 0) {
                    int neighbor = mask ^ (1 << b);
                    Integer nbIdx = maskToIdx.get(neighbor);
                    if (nbIdx != null) dsu.union(i, nbIdx);
                } else {
                    int neighbor = mask | (1 << b);
                    Integer nbIdx = maskToIdx.get(neighbor);
                    if (nbIdx != null) dsu.union(i, nbIdx);
                }
            }
            for (int b = 0; b < 26; b++) {
                if ((mask & (1 << b)) == 0) continue;
                int maskWithoutB = mask ^ (1 << b);
                for (int c = 0; c < 26; c++) {
                    if ((maskWithoutB & (1 << c)) != 0) continue;
                    int neighbor = maskWithoutB | (1 << c);
                    Integer nbIdx = maskToIdx.get(neighbor);
                    if (nbIdx != null) dsu.union(i, nbIdx);
                }
            }
        }
        int[] compCount = new int[m];
        for (int i = 0; i < m; i++) {
            int root = dsu.find(i);
            compCount[root] += count[i];
        }
        int groups = 0, maxSize = 0;
        for (int sz : compCount) {
            if (sz > 0) {
                groups++;
                if (sz > maxSize) maxSize = sz;
            }
        }
        return new int[]{groups, maxSize};
    }

    private static class DSU {
        int[] parent;
        int[] rank;
        DSU(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) parent[i] = i;
        }
        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }
        void union(int a, int b) {
            int ra = find(a), rb = find(b);
            if (ra == rb) return;
            if (rank[ra] < rank[rb]) parent[ra] = rb;
            else if (rank[ra] > rank[rb]) parent[rb] = ra;
            else {
                parent[rb] = ra;
                rank[ra]++;
            }
        }
    }
}

