class Solution {
    public static List<Integer> maxScoreDivisions(int[] nums) {
        int n = nums.length;
        int totalOnes = 0;
        for (int i = 0; i < n; i++) {
            if (nums[i] == 1) totalOnes++;
        }

        int zerosLeft = 0, onesSeen = 0;
        int maxScore = -1;
        List<Integer> answer = new ArrayList<>();

        for (int i = 0; i <= n; i++) {
            int onesRight = totalOnes - onesSeen;
            int score = zerosLeft + onesRight;

            if (score > maxScore) {
                maxScore = score;
                answer.clear();
                answer.add(i);
            } else if (score == maxScore) {
                answer.add(i);
            }

            if (i < n) {
                if (nums[i] == 0) zerosLeft++;
                else onesSeen++;
            }
        }
        return answer;
    }
}

