class Solution {
    public static int minCostSetTime(int startAt, int moveCost, int pushCost, int targetSeconds) {
        int best = Integer.MAX_VALUE;
        for (int minutes = 0; minutes <= 99; minutes++) {
            int seconds = targetSeconds - minutes * 60;
            if (seconds < 0 || seconds > 99) continue;
            int code = minutes * 100 + seconds;
            if (code == 0) continue;
            int[] d = new int[4];
            d[0] = code / 1000;
            d[1] = (code / 100) % 10;
            d[2] = (code / 10) % 10;
            d[3] = code % 10;
            int startIdx = 0;
            while (startIdx < 4 && d[startIdx] == 0) startIdx++;
            int cost = 0;
            int prev = d[startIdx];
            if (prev != startAt) cost += moveCost;
            cost += pushCost;
            for (int i = startIdx + 1; i < 4; i++) {
                int cur = d[i];
                if (cur != prev) cost += moveCost;
                cost += pushCost;
                prev = cur;
            }
            if (cost < best) best = cost;
        }
        return best;
    }
}

import java.util.PriorityQueue;
import java.util.Collections;

class Solution {
    public static long minimumDifference(int[] nums) {
        int n = nums.length / 3;
        int len = nums.length;

        long[] left = new long[len];
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        long sumLeft = 0;
        for (int i = 0; i < len; i++) {
            sumLeft += nums[i];
            maxHeap.offer(nums[i]);
            if (maxHeap.size() > n) {
                sumLeft -= maxHeap.poll();
            }
            if (i >= n - 1) {
                left[i] = sumLeft;
            }
        }

        long[] right = new long[len];
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();
        long sumRight = 0;
        for (int i = len - 1; i >= 0; i--) {
            sumRight += nums[i];
            minHeap.offer(nums[i]);
            if (minHeap.size() > n) {
                sumRight -= minHeap.poll();
            }
            if (i <= 2 * n) {
                right[i] = sumRight;
            }
        }

        long answer = Long.MAX_VALUE;
        for (int i = n; i <= 2 * n; i++) {
            long diff = left[i - 1] - right[i];
            if (diff < answer) {
                answer = diff;
            }
        }
        return answer;
    }
}

