class Solution {
    public static long smallestRearranged(long num) {
        if (num == 0) return 0;
        boolean isNeg = num < 0;
        char[] chars = Long.toString(Math.abs(num)).toCharArray();
        Character[] digits = new Character[chars.length];
        for (int i = 0; i < chars.length; i++) digits[i] = chars[i];
        if (isNeg) {
            Arrays.sort(digits, (a, b) -> b - a);
            StringBuilder sb = new StringBuilder(digits.length);
            for (Character c : digits) sb.append(c);
            return -Long.parseLong(sb.toString());
        } else {
            Arrays.sort(digits, (a, b) -> a - b);
            if (digits[0] == '0') {
                int i = 0;
                while (i < digits.length && digits[i] == '0') i++;
                if (i < digits.length) {
                    char firstNonZero = digits[i];
                    digits[i] = digits[0];
                    digits[0] = firstNonZero;
                }
            }
            StringBuilder sb = new StringBuilder(digits.length);
            for (Character c : digits) sb.append(c);
            return Long.parseLong(sb.toString());
        }
    }
}

class Bitset {
    private final byte[] bits;
    private boolean flipped;
    private int onesCount;
    private final int size;
    public Bitset(int size) {
        this.size = size; this.bits = new byte[size]; this.flipped = false; this.onesCount = 0;
    }
    public void fix(int idx) {
        if ((bits[idx] ^ (flipped ? 1 : 0)) == 0) { bits[idx] = (byte)(flipped ? 0 : 1); onesCount++; }
    }
    public void unfix(int idx) {
        if ((bits[idx] ^ (flipped ? 1 : 0)) == 1) { bits[idx] = (byte)(flipped ? 1 : 0); onesCount--; }
    }
    public void flip() { flipped = !flipped; onesCount = size - onesCount; }
    public boolean all() { return onesCount == size; }
    public boolean one() { return onesCount > 0; }
    public int count() { return onesCount; }
    public String toString() {
        StringBuilder sb = new StringBuilder(size);
        for (int i = 0; i < size; i++) sb.append(bits[i] ^ (flipped ? 1 : 0));
        return sb.toString();
    }
}

