import java.util.Map;

class Solution {
    public static int minOperations(int[] nums) {
        Map<Integer, Integer> evenFreq = new HashMap<>();
        Map<Integer, Integer> oddFreq = new HashMap<>();

        for (int i = 0; i < nums.length; i++) {
            Map<Integer, Integer> map = (i & 1) == 0 ? evenFreq : oddFreq;
            map.put(nums[i], map.getOrDefault(nums[i], 0) + 1);
        }

        int[][] evenTop = topTwo(evenFreq);
        int[][] oddTop = topTwo(oddFreq);

        int[] evenBest = evenTop[0];
        int[] evenSecond = evenTop[1];
        int[] oddBest = oddTop[0];
        int[] oddSecond = oddTop[1];

        int keep;
        if (evenBest[0] != oddBest[0]) {
            keep = evenBest[1] + oddBest[1];
        } else {
            keep = Math.max(evenBest[1] + oddSecond[1], evenSecond[1] + oddBest[1]);
        }

        return nums.length - keep;
    }

    private static int[][] topTwo(Map<Integer, Integer> freqMap) {
        int[] first = new int[]{-1, 0};
        int[] second = new int[]{-1, 0};
        for (Map.Entry<Integer, Integer> entry : freqMap.entrySet()) {
            int val = entry.getKey();
            int cnt = entry.getValue();
            if (cnt > first[1]) {
                second = first;
                first = new int[]{val, cnt};
            } else if (cnt > second[1]) {
                second = new int[]{val, cnt};
            }
        }
        return new int[][]{first, second};
    }
}

