public class Solution {
    public static int countPairs(int[] nums, int k) {
        int n = nums.length;
        long ans = 0L;
        Map<Integer, List<Integer>> positions = new HashMap<>();
        for (int i = 0; i < n; i++) {
            positions.computeIfAbsent(nums[i], v -> new ArrayList<>()).add(i);
        }
        List<Integer> divisors = new ArrayList<>();
        for (int d = 1; d * d <= k; d++) {
            if (k % d == 0) {
                divisors.add(d);
                if (d != k / d) divisors.add(k / d);
            }
        }
        for (List<Integer> idxList : positions.values()) {
            Map<Integer, Integer> countMap = new HashMap<>();
            for (int idx : idxList) {
                for (int d : divisors) {
                    if (idx % d == 0) {
                        ans += countMap.getOrDefault(d, 0);
                    }
                }
                int required = k / gcd(idx, k);
                countMap.put(required, countMap.getOrDefault(required, 0) + 1);
            }
        }
        return (int) ans;
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int tmp = a % b;
            a = b;
            b = tmp;
        }
        return a;
    }
}

