public class Solution {
    public static int maximumANDSum(int[] nums, int numSlots) {
        int n = nums.length;
        int totalPositions = numSlots * 2;
        int totalMask = 1 << totalPositions;
        int[] dp = new int[totalMask];
        Arrays.fill(dp, Integer.MIN_VALUE);
        dp[0] = 0;
        for (int mask = 0; mask < totalMask; mask++) {
            int placed = Integer.bitCount(mask);
            if (placed >= n) continue;
            for (int pos = 0; pos < totalPositions; pos++) {
                if ((mask & (1 << pos)) != 0) continue;
                int nextMask = mask | (1 << pos);
                int slot = pos / 2 + 1;
                int cand = dp[mask] + (nums[placed] & slot);
                if (cand > dp[nextMask]) dp[nextMask] = cand;
            }
        }
        int ans = 0;
        for (int mask = 0; mask < totalMask; mask++) {
            if (Integer.bitCount(mask) == n) {
                ans = Math.max(ans, dp[mask]);
            }
        }
        return ans;
    }
}

