class Solution {
    public static String repeatLimitedString(String s, int repeatLimit) {
        int[] cnt = new int[26];
        for (int k = 0; k < s.length(); k++) {
            cnt[s.charAt(k) - 'a']++;
        }
        StringBuilder res = new StringBuilder();
        int lastIdx = -1;
        int lastRun = 0;
        while (true) {
            int i = 25;
            while (i >= 0 && cnt[i] == 0) i--;
            if (i < 0) break;
            if (i == lastIdx && lastRun == repeatLimit) {
                int j = i - 1;
                while (j >= 0 && cnt[j] == 0) j--;
                if (j < 0) break;
                res.append((char) (j + 'a'));
                cnt[j]--;
                lastIdx = j;
                lastRun = 1;
            } else {
                res.append((char) (i + 'a'));
                cnt[i]--;
                if (i == lastIdx) {
                    lastRun++;
                } else {
                    lastIdx = i;
                    lastRun = 1;
                }
            }
        }
        return res.toString();
    }
}

public class Solution {
    public static long countGoodTriplets(int[] nums1, int[] nums2) {
        int n = nums1.length;
        int[] posInSecond = new int[n];
        for (int i = 0; i < n; i++) {
            posInSecond[nums2[i]] = i;
        }
        int[] p = new int[n];
        for (int i = 0; i < n; i++) {
            p[i] = posInSecond[nums1[i]];
        }
        long[] left = new long[n];
        Fenwick fenwick = new Fenwick(n);
        for (int i = 0; i < n; i++) {
            int v = p[i];
            left[i] = fenwick.prefixSum(v - 1);
            fenwick.add(v, 1);
        }
        Fenwick fenwickR = new Fenwick(n);
        long answer = 0;
        for (int i = n - 1; i >= 0; i--) {
            int v = p[i];
            long right = fenwickR.totalSum() - fenwickR.prefixSum(v);
            answer += left[i] * right;
            fenwickR.add(v, 1);
        }
        return answer;
    }

    private static class Fenwick {
        private final int size;
        private final long[] tree;
        Fenwick(int n) {
            size = n;
            tree = new long[n + 2];
        }
        void add(int index, long delta) {
            for (int i = index + 1; i <= size; i += i & -i) {
                tree[i] += delta;
            }
        }
        long prefixSum(int index) {
            if (index < 0) return 0;
            long sum = 0;
            for (int i = index + 1; i > 0; i -= i & -i) {
                sum += tree[i];
            }
            return sum;
        }
        long totalSum() {
            return prefixSum(size - 1);
        }
    }
}

