class Solution {
    public static long countEvenDigitSum(long num) {
        String s = Long.toString(num);
        int n = s.length();
        long[][] memo = new long[n][2];
        for (int i = 0; i < n; i++) {
            Arrays.fill(memo[i], -1L);
        }
        return dfs(s, n, memo, 0, 0, true) - 1;
    }

    private static long dfs(String s, int n, long[][] memo, int pos, int parity, boolean tight) {
        if (pos == n) {
            return parity == 0 ? 1L : 0L;
        }
        if (!tight && memo[pos][parity] != -1L) {
            return memo[pos][parity];
        }
        int limit = tight ? s.charAt(pos) - '0' : 9;
        long res = 0L;
        for (int d = 0; d <= limit; d++) {
            int nextParity = (parity + d) & 1;
            boolean nextTight = tight && d == limit;
            res += dfs(s, n, memo, pos + 1, nextParity, nextTight);
        }
        if (!tight) {
            memo[pos][parity] = res;
        }
        return res;
    }
}

