class Solution {
    public static long countPairs(int[] nums, int k) {
        java.util.Map<Integer, Integer> cnt = new java.util.HashMap<>();
        for (int i = 0; i < nums.length; ++i) {
            int g = gcd(nums[i], k);
            cnt.put(g, cnt.getOrDefault(g, 0) + 1);
        }
        java.util.List<Integer> divisors = new java.util.ArrayList<>(cnt.keySet());
        long ans = 0;
        for (int i = 0; i < divisors.size(); ++i) {
            int d1 = divisors.get(i);
            int c1 = cnt.get(d1);
            for (int j = i; j < divisors.size(); ++j) {
                int d2 = divisors.get(j);
                if (((long) d1 * d2) % k != 0) continue;
                int c2 = cnt.get(d2);
                if (i == j) {
                    ans += (long) c1 * (c1 - 1) / 2;
                } else {
                    ans += (long) c1 * c2;
                }
            }
        }
        return ans;
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

