            String s = Integer.toString(num);
            StringBuilder sb = new StringBuilder(s.length());
            for (int j = 0; j < s.length(); j++) {
                int digit = s.charAt(j) - '0';
                sb.append(mapping[digit]);
            }
            long mapped = Long.parseLong(sb.toString());
            items[i] = new Item(mapped, num, i);
        }
        Arrays.sort(items, (a, b) -> {
            int cmp = Long.compare(a.mapped, b.mapped);
            return cmp != 0 ? cmp : Integer.compare(a.idx, b.idx);
        });
        int[] result = new int[n];
        for (int i = 0; i < n; i++) {
            result[i] = items[i].original;
        }
        return result;
    }

    private static class Item {
        long mapped;
        int original;
        int idx;

        Item(long mapped, int original, int idx) {
            this.mapped = mapped;
            this.original = original;
            this.idx = idx;
        }
    }
}

import java.util.*;

class Solution {
    public static List<List<Integer>> getAncestors(int n, int[][] edges) {
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }
        int[] indeg = new int[n];
        for (int[] edge : edges) {
            int a = edge[0];
            int b = edge[1];
            adj[a].add(b);
            indeg[b]++;
        }

        Set<Integer>[] ancestors = new HashSet[n];
        for (int i = 0; i < n; i++) {
            ancestors[i] = new HashSet<>();
        }

        Deque<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            if (indeg[i] == 0) {
                queue.offer(i);
            }
        }

        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v : adj[u]) {
                ancestors[v].add(u);
                for (int anc : ancestors[u]) {
                    ancestors[v].add(anc);
                }
                if (--indeg[v] == 0) {
                    queue.offer(v);
                }
            }
        }

        List<List<Integer>> answer = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            List<Integer> list = new ArrayList<>(ancestors[i]);
            Collections.sort(list);
            answer.add(list);
        }
        return answer;
    }
}

class Solution {
    public static long minimumTime(int[] time, int totalTrips) {
        long low = 1L;
        int min = Integer.MAX_VALUE;
        for (int t : time) {
            if (t < min) min = t;
        }
        long high = (long) min * totalTrips;
        while (low < high) {
            long mid = (low + high) / 2;
            long trips = 0;
            for (int t : time) {
                trips += mid / t;
                if (trips >= totalTrips) break;
            }
            if (trips >= totalTrips) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}

import java.util.Arrays;

class Solution {
    public static int minimumFinishTime(int[][] tires, int changeTime, int numLaps) {
        long INF = Long.MAX_VALUE / 4;
        long[] best = new long[numLaps + 1];
        Arrays.fill(best, INF);
        for (int[] tire : tires) {
            long f = tire[0];
            long r = tire[1];
            long cur = f;
            long sum = 0;
            for (int k = 1; k <= numLaps; k++) {
                sum += cur;
                if (sum < best[k]) {
                    best[k] = sum;
                }
                long next = cur * r;
                if (next > changeTime + f) {
                    break;
                }
                cur = next;
            }
        }
        long[] dp = new long[numLaps + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int i = 1; i <= numLaps; i++) {
            dp[i] = best[i];
            for (int k = 1; k < i; k++) {
                long candidate = dp[i - k] + changeTime + best[k];
                if (candidate < dp[i]) {
                    dp[i] = candidate;
                }
            }
        }
        return (int) dp[numLaps];
    }
}

