class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int x) { val = x; }
}

class Solution {
    public static TreeNode createBinaryTree(int[][] descriptions) {
        Map<Integer, TreeNode> nodes = new HashMap<>();
        Set<Integer> children = new HashSet<>();
        java.util.function.Function<Integer, TreeNode> getNode = v -> {
            if (!nodes.containsKey(v)) nodes.put(v, new TreeNode(v));
            return nodes.get(v);
        };
        for (int[] desc : descriptions) {
            int parentVal = desc[0];
            int childVal = desc[1];
            int isLeft = desc[2];
            TreeNode parentNode = getNode.apply(parentVal);
            TreeNode childNode = getNode.apply(childVal);
            if (isLeft == 1) parentNode.left = childNode;
            else parentNode.right = childNode;
            children.add(childVal);
        }
        for (int val : nodes.keySet()) {
            if (!children.contains(val)) return nodes.get(val);
        }
        return null;
    }
}

