class Solution {
    public static long[] replaceNonCoprime(long[] nums) {
        List<Long> stack = new ArrayList<>();
        for (long num : nums) {
            stack.add(num);
            while (stack.size() >= 2) {
                long b = stack.get(stack.size() - 1);
                long a = stack.get(stack.size() - 2);
                long g = gcd(a, b);
                if (g == 1) break;
                stack.remove(stack.size() - 1);
                stack.remove(stack.size() - 1);
                long lcm = (a / g) * b;
                stack.add(lcm);
            }
        }
        long[] result = new long[stack.size()];
        for (int i = 0; i < stack.size(); i++) {
            result[i] = stack.get(i);
        }
        return result;
    }

    private static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

