class Solution {
    public static long minMovesToMakePalindrome(String s) {
        char[] arr = s.toCharArray();
        int n = arr.length;
        long moves = 0;
        int i = 0, j = n - 1;
        while (i < j) {
            if (arr[i] == arr[j]) {
                i++;
                j--;
                continue;
            }
            int k = j;
            while (k > i && arr[k] != arr[i]) {
                k--;
            }
            if (k == i) {
                // middle character, swap with next
                char temp = arr[i];
                arr[i] = arr[i + 1];
                arr[i + 1] = temp;
                moves++;
            } else {
                // bring matching character to position j
                for (int l = k; l < j; l++) {
                    char temp = arr[l];
                    arr[l] = arr[l + 1];
                    arr[l + 1] = temp;
                    moves++;
                }
                i++;
                j--;
            }
        }
        return moves;
    }
}

import java.util.Arrays;

class Solution {
    public static long minimalAppendSum(int[] nums, int k) {
        int[] arr = nums.clone();
        Arrays.sort(arr);
        long sum = 0;
        int added = 0;
        int candidate = 1;
        int i = 0;
        int n = arr.length;
        while (added < k && i < n) {
            int val = arr[i];
            if (val < candidate) {
                i++;
                continue;
            }
            if (val == candidate) {
                candidate++;
                i++;
                continue;
            }
            sum += candidate;
            added++;
            candidate++;
        }
        if (added < k) {
            int remaining = k - added;
            long first = candidate;
            long last = candidate + remaining - 1L;
            sum += (first + last) * remaining / 2;
        }
        return sum;
    }
}

