class Solution {
    public static List<Integer> findKDistantIndices(int[] nums, int key, int k) {
        int n = nums.length;
        int[] diff = new int[n + 1];
        for (int i = 0; i < n; i++) {
            if (nums[i] == key) {
                int l = Math.max(0, i - k);
                int r = Math.min(n - 1, i + k);
                diff[l] += 1;
                diff[r + 1] -= 1;
            }
        }
        List<Integer> result = new ArrayList<>();
        int cur = 0;
        for (int i = 0; i < n; i++) {
            cur += diff[i];
            if (cur > 0) {
                result.add(i);
            }
        }
        return result;
    }
}

