class Solution {
    public static int maximumTop(int[] nums, int k) {
        int n = nums.length;
        if (k == 0) {
            return nums[0];
        }
        if (n == 1) {
            return (k % 2 == 0) ? nums[0] : -1;
        }
        if (k == 1) {
            return nums[1];
        }
        int limit = Math.min(k - 1, n);
        int max = Integer.MIN_VALUE;
        for (int i = 0; i < limit; i++) {
            max = Math.max(max, nums[i]);
        }
        if (k < n) {
            max = Math.max(max, nums[k]);
        }
        return max;
    }
}

