class Solution {
    public static int countArtifacts(int n, int[][] artifacts, int[][] dig) {
        Map<String, Integer> cellToArtifact = new HashMap<>();
        int[] remaining = new int[artifacts.length];
        for (int i = 0; i < artifacts.length; ++i) {
            int r1 = artifacts[i][0];
            int c1 = artifacts[i][1];
            int r2 = artifacts[i][2];
            int c2 = artifacts[i][3];
            int area = (r2 - r1 + 1) * (c2 - c1 + 1);
            remaining[i] = area;
            for (int r = r1; r <= r2; ++r) {
                for (int c = c1; c <= c2; ++c) {
                    cellToArtifact.put(r + "," + c, i);
                }
            }
        }
        for (int[] d : dig) {
            int r = d[0];
            int c = d[1];
            String key = r + "," + c;
            Integer idx = cellToArtifact.get(key);
            if (idx != null) {
                remaining[idx]--;
                cellToArtifact.remove(key);
            }
        }
        int extracted = 0;
        for (int i = 0; i < remaining.length; ++i) {
            if (remaining[i] == 0) ++extracted;
        }
        return extracted;
    }
}

