class Solution {
    private static final long INF = Long.MAX_VALUE / 4;

    public static long minimumWeight(int n, int[][] edges, int src1, int src2, int dest) {
        List<int[]>[] adj = new ArrayList[n];
        List<int[]>[] rev = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
            rev[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            int u = e[0], v = e[1], w = e[2];
            adj[u].add(new int[]{v, w});
            rev[v].add(new int[]{u, w});
        }
        long[] dist1 = dijkstra(src1, adj);
        long[] dist2 = dijkstra(src2, adj);
        long[] distDest = dijkstra(dest, rev);
        long ans = INF;
        for (int v = 0; v < n; v++) {
            if (dist1[v] == INF || dist2[v] == INF || distDest[v] == INF) continue;
            long total = dist1[v] + dist2[v] + distDest[v];
            if (total < ans) ans = total;
        }
        return ans == INF ? -1 : ans;
    }

    private static long[] dijkstra(int start, List<int[]>[] graph) {
        int n = graph.length;
        long[] dist = new long[n];
        Arrays.fill(dist, INF);
        dist[start] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
        pq.offer(new long[]{0, start});
        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            long d = cur[0];
            int u = (int) cur[1];
            if (d != dist[u]) continue;
            for (int[] edge : graph[u]) {
                int v = edge[0];
                int w = edge[1];
                long nd = d + w;
                if (nd < dist[v]) {
                    dist[v] = nd;
                    pq.offer(new long[]{nd, v});
                }
            }
        }
        return dist;
    }
}

import java.util.Arrays;

class Solution {
    public static int minOperations(int[] nums) {
        double total = 0;
        for (int v : nums) total += v;
        double target = total / 2.0;
        double reduced = 0;
        double[] init = new double[nums.length];
        for (int i = 0; i < nums.length; i++) init[i] = (double) nums[i];
        MaxHeap heap = new MaxHeap(init);
        int ops = 0;
        while (reduced < target) {
            double maxVal = heap.pop();
            double half = maxVal / 2.0;
            reduced += half;
            heap.push(half);
            ops++;
        }
        return ops;
    }

    static class MaxHeap {
        double[] heap;
        int size;

        MaxHeap(double[] arr) {
            heap = arr.clone();
            size = heap.length;
            for (int i = size / 2 - 1; i >= 0; i--) bubbleDown(i);
        }

        void bubbleUp(int idx) {
            while (idx > 0) {
                int parent = (idx - 1) >> 1;
                if (heap[parent] >= heap[idx]) break;
                double tmp = heap[parent];
                heap[parent] = heap[idx];
                heap[idx] = tmp;
                idx = parent;
            }
        }

        void bubbleDown(int idx) {
            int n = size;
            while (true) {
                int largest = idx;
                int left = idx * 2 + 1;
                int right = left + 1;
                if (left < n && heap[left] > heap[largest]) largest = left;
                if (right < n && heap[right] > heap[largest]) largest = right;
                if (largest == idx) break;
                double tmp = heap[largest];
                heap[largest] = heap[idx];
                heap[idx] = tmp;
                idx = largest;
            }
        }

        double pop() {
            double top = heap[0];
            double last = heap[--size];
            if (size > 0) {
                heap[0] = last;
                bubbleDown(0);
            }
            return top;
        }

        void push(double val) {
            if (size == heap.length) {
                heap = Arrays.copyOf(heap, heap.length * 2 + 1);
            }
            heap[size++] = val;
            bubbleUp(size - 1);
        }
    }
}

