public class Solution {
    public static long maximumSubsequenceCount(String text, String pattern) {
        char a = pattern.charAt(0);
        char b = pattern.charAt(1);
        int n = text.length();
        if (a == b) {
            long cnt = 0;
            for (int i = 0; i < n; i++) {
                if (text.charAt(i) == a) cnt++;
            }
            long baseline = cnt * (cnt - 1) / 2;
            return baseline + cnt;
        }
        long totalB = 0;
        for (int i = 0; i < n; i++) {
            if (text.charAt(i) == b) totalB++;
        }
        long countA = 0;
        long countB = 0;
        long baseline = 0;
        long maxAdd = totalB;
        for (int i = 0; i < n; i++) {
            char ch = text.charAt(i);
            if (ch == a) {
                countA++;
            } else if (ch == b) {
                baseline += countA;
                countB++;
            }
            long addA = totalB - countB;
            long addB = countA;
            if (addA > maxAdd) maxAdd = addA;
            if (addB > maxAdd) maxAdd = addB;
        }
        return baseline + maxAdd;
    }
}

