class Solution {
    public static int minimumWhiteTiles(String floor, int numCarpets, int carpetLen) {
        int n = floor.length();
        int[] pref = new int[n + 1];
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] + (floor.charAt(i) == '1' ? 1 : 0);
        }
        int[] dpPrev = pref.clone();
        for (int k = 1; k <= numCarpets; k++) {
            int[] dpCurr = new int[n + 1];
            dpCurr[0] = 0;
            for (int i = 1; i <= n; i++) {
                int notCover = dpCurr[i - 1] + (floor.charAt(i - 1) == '1' ? 1 : 0);
                int j = i - carpetLen >= 0 ? i - carpetLen : 0;
                int cover = dpPrev[j];
                dpCurr[i] = Math.min(notCover, cover);
            }
            dpPrev = dpCurr;
        }
        return dpPrev[n];
    }
}

