class Solution {
    public static int countHillValley(int[] nums) {
        if (nums.length < 3) return 0;
        ArrayList<Integer> comp = new ArrayList<>();
        for (int v : nums) {
            if (comp.isEmpty() || comp.get(comp.size() - 1) != v) {
                comp.add(v);
            }
        }
        int ans = 0;
        for (int i = 1; i < comp.size() - 1; i++) {
            int cur = comp.get(i);
            int left = comp.get(i - 1);
            int right = comp.get(i + 1);
            if (cur > left && cur > right) ans++;
            else if (cur < left && cur < right) ans++;
        }
        return ans;
    }
}

class Solution {
    public static int[] maximumBobArrows(int numArrows, int[] aliceArrows) {
        int n = 12;
        int bestScore = -1;
        int bestMask = 0;
        for (int mask = 0; mask < (1 << n); mask++) {
            int arrowsNeeded = 0;
            int score = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    arrowsNeeded += aliceArrows[i] + 1;
                    score += i;
                }
            }
            if (arrowsNeeded > numArrows) continue;
            if (score > bestScore) {
                bestScore = score;
                bestMask = mask;
            }
        }
        int[] bobArrows = new int[n];
        int used = 0;
        for (int i = 0; i < n; i++) {
            if ((bestMask & (1 << i)) != 0) {
                bobArrows[i] = aliceArrows[i] + 1;
                used += bobArrows[i];
            }
        }
        bobArrows[0] += numArrows - used;
        return bobArrows;
    }
}

