import java.util.*;

class Solution {
    private static class Interval {
        int start;
        int end;
        char ch;
        Interval(int s, int e, char c) {
            this.start = s;
            this.end = e;
            this.ch = c;
        }
        int length() {
            return end - start + 1;
        }
    }

    public static int[] longestRepeating(String s, String queryCharacters, int[] queryIndices) {
        int n = s.length();
        int k = queryIndices.length;
        int[] ans = new int[k];
        char[] arr = s.toCharArray();

        TreeMap<Integer, Interval> intervals = new TreeMap<>();
        TreeMap<Integer, Integer> lengthCount = new TreeMap<>();

        // Build initial intervals
        int i = 0;
        while (i < n) {
            int j = i;
            while (j + 1 < n && arr[j + 1] == arr[i]) j++;
            Interval iv = new Interval(i, j, arr[i]);
            intervals.put(iv.start, iv);
            addLength(lengthCount, iv.length());
            i = j + 1;
        }

        for (int q = 0; q < k; q++) {
            int idx = queryIndices[q];
            char newChar = queryCharacters.charAt(q);
            if (arr[idx] == newChar) {
                ans[q] = lengthCount.isEmpty() ? 0 : lengthCount.lastKey();
                continue;
            }

            // Find current interval containing idx
            Map.Entry<Integer, Interval> entry = intervals.floorEntry(idx);
            Interval cur = entry.getValue(); // guaranteed to contain idx
            // Remove current interval
            intervals.remove(cur.start);
            removeLength(lengthCount, cur.length());

            // Split left part if any
            if (cur.start <= idx - 1) {
                Interval leftPart = new Interval(cur.start, idx - 1, cur.ch);
                intervals.put(leftPart.start, leftPart);
                addLength(lengthCount, leftPart.length());
            }
            // Split right part if any
            if (idx + 1 <= cur.end) {
                Interval rightPart = new Interval(idx + 1, cur.end, cur.ch);
                intervals.put(rightPart.start, rightPart);
                addLength(lengthCount, rightPart.length());
            }

            // Prepare to merge with neighbours of the same newChar
            int newStart = idx;
            int newEnd = idx;

            // Left neighbour
            Map.Entry<Integer, Interval> leftEntry = intervals.floorEntry(idx - 1);
            if (leftEntry != null) {
                Interval left = leftEntry.getValue();
                if (left.end == idx - 1 && left.ch == newChar) {
                    intervals.remove(left.start);
                    removeLength(lengthCount, left.length());
                    newStart = left.start;
                }
            }

            // Right neighbour
            Interval right = intervals.get(idx + 1);
            if (right != null && right.ch == newChar) {
                intervals.remove(right.start);
                removeLength(lengthCount, right.length());
                newEnd = right.end;
            }

            // Insert merged interval
            Interval merged = new Interval(newStart, newEnd, newChar);
            intervals.put(merged.start, merged);
            addLength(lengthCount, merged.length());

            // Update the character array
            arr[idx] = newChar;

            ans[q] = lengthCount.lastKey();
        }

        return ans;
    }

    private static void addLength(TreeMap<Integer, Integer> map, int len) {
        map.merge(len, 1, Integer::sum);
    }

    private static void removeLength(TreeMap<Integer, Integer> map, int len) {
        int cnt = map.get(len);
        if (cnt == 1) map.remove(len);
        else map.put(len, cnt - 1);
    }
}

