class Solution {
    public static List<List<Integer>> findDifference(int[] nums1, int[] nums2) {
        Set<Integer> set1 = new HashSet<>();
        for (int v : nums1) {
            set1.add(v);
        }
        Set<Integer> set2 = new HashSet<>();
        for (int v : nums2) {
            set2.add(v);
        }
        List<Integer> onlyInFirst = new ArrayList<>();
        List<Integer> onlyInSecond = new ArrayList<>();
        for (int v : set1) {
            if (!set2.contains(v)) {
                onlyInFirst.add(v);
            }
        }
        for (int v : set2) {
            if (!set1.contains(v)) {
                onlyInSecond.add(v);
            }
        }
        List<List<Integer>> result = new ArrayList<>();
        result.add(onlyInFirst);
        result.add(onlyInSecond);
        return result;
    }
}

public class Solution {
    public static int minDeletion(int[] nums) {
        int pairs = 0;
        boolean waiting = false;
        int waitingVal = 0;
        for (int num : nums) {
            if (!waiting) {
                waiting = true;
                waitingVal = num;
            } else if (num > waitingVal) {
                pairs++;
                waiting = false;
            }
        }
        return nums.length - pairs * 2;
    }
}

import java.util.*;

class Solution {
    public static int maxValueOfCoins(int[][] piles, int k) {
        int[] dp = new int[k + 1];
        for (int pileIdx = 0; pileIdx < piles.length; pileIdx++) {
            int[] pile = piles[pileIdx];
            int maxTake = Math.min(pile.length, k);
            int[] pref = new int[maxTake + 1];
            for (int t = 1; t <= maxTake; t++) {
                pref[t] = pref[t - 1] + pile[t - 1];
            }
            int[] next = dp.clone();
            for (int j = 0; j <= k; j++) {
                int limit = Math.min(maxTake, j);
                for (int t = 1; t <= limit; t++) {
                    int candidate = dp[j - t] + pref[t];
                    if (candidate > next[j]) {
                        next[j] = candidate;
                    }
                }
            }
            System.arraycopy(next, 0, dp, 0, k + 1);
        }
        return dp[k];
    }
}

