class Solution {
    public static long[] findPalindromes(int[] queries, int intLength) {
        int halfLen = (int) Math.ceil(intLength / 2.0);
        long start = (long) Math.pow(10, halfLen - 1);
        long maxCount = 9L * (long) Math.pow(10, halfLen - 1);
        long[] res = new long[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int k = queries[i];
            if (k > maxCount) {
                res[i] = -1;
                continue;
            }
            long halfNum = start + k - 1;
            String halfStr = Long.toString(halfNum);
            String rev = new StringBuilder(halfStr).reverse().toString();
            String palStr = (intLength % 2 == 0) ? halfStr + rev : halfStr + rev.substring(1);
            res[i] = Long.parseLong(palStr);
        }
        return res;
    }
}

public class Solution {
    public static long numberOfWays(String s) {
        int n = s.length();
        if (n < 3) return 0L;
        char[] arr = s.toCharArray();
        long totalZero = 0;
        for (char c : arr) if (c == '0') totalZero++;
        long totalOne = n - totalZero;
        long prefixZero = 0;
        long prefixOne = 0;
        long answer = 0;
        for (int j = 0; j < n; ++j) {
            if (arr[j] == '0') {
                long left = prefixOne;
                long right = totalOne - prefixOne;
                answer += left * right;
                prefixZero++;
            } else {
                long left = prefixZero;
                long right = totalZero - prefixZero;
                answer += left * right;
                prefixOne++;
            }
        }
        return answer;
    }
}

