public class Solution {
    public static int maximumCandies(int[] candies, int k) {
        if (k == 0) {
            return 0;
        }
        int low = 1;
        int high = 0;
        for (int v : candies) {
            if (v > high) high = v;
        }
        int best = 0;
        while (low <= high) {
            int mid = (low + high) / 2;
            long pieces = 0;
            for (int v : candies) {
                pieces += v / mid;
            }
            if (pieces >= k) {
                best = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return best;
    }
}

