class Encrypter {
    private final Map<Character, String> charToVal = new HashMap<>();
    private final Map<String, Integer> encCount = new HashMap<>();
    public Encrypter(char[] keys, String[] values, String[] dictionary) {
        for (int i = 0; i < keys.length; i++) charToVal.put(keys[i], values[i]);
        for (String word : dictionary) {
            StringBuilder sb = new StringBuilder();
            boolean ok = true;
            for (int j = 0; j < word.length(); j++) {
                String v = charToVal.get(word.charAt(j));
                if (v == null) { ok = false; break; }
                sb.append(v);
            }
            if (ok) encCount.merge(sb.toString(), 1, Integer::sum);
        }
    }
    public String encrypt(String word1) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < word1.length(); i++) {
            String v = charToVal.get(word1.charAt(i));
            if (v == null) return "";
            sb.append(v);
        }
        return sb.toString();
    }
    public int decrypt(String word2) {
        return encCount.getOrDefault(word2, 0);
    }
}

