class Solution {
    public static long largestNumberAfterParitySwaps(long num) {
        String s = Long.toString(num);
        int[] evenCnt = new int[10];
        int[] oddCnt = new int[10];
        for (int i = 0; i < s.length(); i++) {
            int d = s.charAt(i) - '0';
            if ((d & 1) == 0) {
                evenCnt[d]++;
            } else {
                oddCnt[d]++;
            }
        }
        int evenPtr = 8;
        int oddPtr = 9;
        StringBuilder res = new StringBuilder(s.length());
        for (int i = 0; i < s.length(); i++) {
            int d = s.charAt(i) - '0';
            if ((d & 1) == 0) {
                while (evenPtr >= 0 && evenCnt[evenPtr] == 0) {
                    evenPtr -= 2;
                }
                res.append((char) (evenPtr + '0'));
                evenCnt[evenPtr]--;
            } else {
                while (oddPtr >= 1 && oddCnt[oddPtr] == 0) {
                    oddPtr -= 2;
                }
                res.append((char) (oddPtr + '0'));
                oddCnt[oddPtr]--;
            }
        }
        return Long.parseLong(res.toString());
    }
}

import java.util.Arrays;

class Solution {
    private static final long MOD = 1_000_000_007L;

    public static int maxProductAfterKIncrements(int[] nums, int k) {
        int n = nums.length;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = nums[i];
        }
        Arrays.sort(a);
        long remaining = k;
        int i = 0;
        while (i < n && remaining > 0) {
            int j = i + 1;
            while (j < n && a[j] == a[i]) {
                j++;
            }
            if (j == n) {
                break;
            }
            long diff = a[j] - a[i];
            long need = diff * (j - i);
            if (remaining >= need) {
                for (int t = i; t < j; t++) {
                    a[t] = a[j];
                }
                remaining -= need;
                i = j;
            } else {
                long add = remaining / (j - i);
                long rem = remaining % (j - i);
                for (int t = i; t < j; t++) {
                    a[t] += add;
                }
                for (int t = i; t < i + rem; t++) {
                    a[t] += 1;
                }
                remaining = 0;
            }
        }
        if (remaining > 0) {
            long add = remaining / n;
            long rem = remaining % n;
            for (int t = 0; t < n; t++) {
                a[t] += add;
            }
            for (int t = 0; t < rem; t++) {
                a[t] += 1;
            }
        }
        long product = 1L;
        for (long v : a) {
            product = (product * (v % MOD)) % MOD;
        }
        return (int) product;
    }
}

