class Solution {
    public static String minimizeResult(String expression) {
        int plusIdx = expression.indexOf('+');
        int n = expression.length();
        char[] ch = expression.toCharArray();
        long[][] sub = new long[n + 1][n + 1];
        for (int i = 0; i < n; i++) {
            long val = 0;
            for (int j = i; j < n; j++) {
                val = val * 10 + (ch[j] - '0');
                sub[i][j + 1] = val;
            }
        }
        long bestVal = Long.MAX_VALUE;
        int bestI = 0, bestJ = n - 1;
        for (int i = 0; i < plusIdx; i++) {
            long leftFactor = (i == 0) ? 1 : sub[0][i];
            for (int j = plusIdx + 1; j < n; j++) {
                long rightFactor = (j == n - 1) ? 1 : sub[j + 1][n];
                long insideLeft = sub[i][plusIdx];
                long insideRight = sub[plusIdx + 1][j + 1];
                long val = leftFactor * (insideLeft + insideRight) * rightFactor;
                if (val < bestVal) {
                    bestVal = val;
                    bestI = i;
                    bestJ = j;
                }
            }
        }
        String leftOutside = expression.substring(0, bestI);
        String insideLeft = expression.substring(bestI, plusIdx);
        String insideRight = expression.substring(plusIdx + 1, bestJ + 1);
        String rightOutside = expression.substring(bestJ + 1);
        return leftOutside + "(" + insideLeft + "+" + insideRight + ")" + rightOutside;
    }
}

import java.util.Arrays;

class Solution {
    public static long maximumBeauty(int[] flowers, long newFlowers, int target, int full, int partial) {
        int n = flowers.length;
        int[] a = flowers.clone();
        Arrays.sort(a);
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + a[i];
        }
        long[] need = new long[n + 1];
        need[0] = 0;
        for (int i = n - 1, k = 1; i >= 0; i--, k++) {
            need[k] = need[k - 1] + Math.max(0, target - a[i]);
        }
        long ans = 0;
        for (int k = 0; k <= n; k++) {
            if (need[k] > newFlowers) continue;
            long remaining = newFlowers - need[k];
            if (k == n) {
                ans = Math.max(ans, (long) full * n);
                continue;
            }
            int limit = n - k;
            int low = a[0];
            int high = target - 1;
            int best = low;
            while (low <= high) {
                int mid = low + (high - low) / 2;
                int pos = lowerBound(a, 0, limit, mid);
                long cost = (long) mid * pos - prefix[pos];
                if (cost <= remaining) {
                    best = mid;
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }
            long beauty = (long) full * k + (long) partial * best;
            ans = Math.max(ans, beauty);
        }
        return ans;
    }

    private static int lowerBound(int[] arr, int from, int to, int value) {
        int l = from, r = to;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (arr[m] < value) {
                l = m + 1;
            } else {
                r = m;
            }
        }
        return l;
    }
}

