class ATM {
    private final int[] values = {20, 50, 100, 200, 500};
    private final int[] stock = new int[5];
    public void deposit(int[] banknotesCount) {
        for (int i = 0; i < 5; i++) stock[i] += banknotesCount[i];
    }
    public int[] withdraw(int amount) {
        int[] used = new int[5];
        for (int i = 4; i >= 0; i--) {
            int maxTake = Math.min(amount / values[i], stock[i]);
            if (maxTake > 0) { used[i] = maxTake; amount -= maxTake * values[i]; }
        }
        if (amount != 0) return new int[]{-1};
        for (int i = 0; i < 5; i++) stock[i] -= used[i];
        return used;
    }
}

