class Solution {
    public static int maximumScore(int[] scores, int[][] edges) {
        int n = scores.length;
        int[][] top = new int[n][3];
        for (int i = 0; i < n; i++) {
            Arrays.fill(top[i], -1);
        }
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            insert(top, scores, u, v);
            insert(top, scores, v, u);
        }
        int best = -1;
        for (int[] e : edges) {
            int b = e[0];
            int c = e[1];
            for (int i = 0; i < 3; i++) {
                int a = top[b][i];
                if (a == -1 || a == c) continue;
                for (int j = 0; j < 3; j++) {
                    int d = top[c][j];
                    if (d == -1 || d == b || d == a) continue;
                    int sum = scores[a] + scores[b] + scores[c] + scores[d];
                    if (sum > best) best = sum;
                }
            }
        }
        return best;
    }

    private static void insert(int[][] top, int[] scores, int node, int neighbor) {
        int neighborScore = scores[neighbor];
        for (int i = 0; i < 3; i++) {
            int cur = top[node][i];
            if (cur == -1) {
                top[node][i] = neighbor;
                break;
            }
            if (neighborScore > scores[cur]) {
                for (int j = 2; j > i; j--) {
                    top[node][j] = top[node][j - 1];
                }
                top[node][i] = neighbor;
                break;
            }
        }
    }
}

