class Solution {
    public static int maxTrailingZeros(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int[][] twos = new int[m][n];
        int[][] fives = new int[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int val = grid[i][j];
                int cnt2 = 0, cnt5 = 0;
                while (val % 2 == 0) {
                    cnt2++;
                    val /= 2;
                }
                while (val % 5 == 0) {
                    cnt5++;
                    val /= 5;
                }
                twos[i][j] = cnt2;
                fives[i][j] = cnt5;
            }
        }

        int[][] row2 = new int[m][n];
        int[][] row5 = new int[m][n];
        int[][] col2 = new int[m][n];
        int[][] col5 = new int[m][n];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                row2[i][j] = twos[i][j] + (j > 0 ? row2[i][j - 1] : 0);
                row5[i][j] = fives[i][j] + (j > 0 ? row5[i][j - 1] : 0);
                col2[i][j] = twos[i][j] + (i > 0 ? col2[i - 1][j] : 0);
                col5[i][j] = fives[i][j] + (i > 0 ? col5[i - 1][j] : 0);
            }
        }

        int best = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int up2 = col2[i][j];
                int up5 = col5[i][j];
                int down2 = col2[m - 1][j] - (i > 0 ? col2[i - 1][j] : 0);
                int down5 = col5[m - 1][j] - (i > 0 ? col5[i - 1][j] : 0);
                int left2 = row2[i][j];
                int left5 = row5[i][j];
                int right2 = row2[i][n - 1] - (j > 0 ? row2[i][j - 1] : 0);
                int right5 = row5[i][n - 1] - (j > 0 ? row5[i][j - 1] : 0);

                int total2 = up2 + left2 - twos[i][j];
                int total5 = up5 + left5 - fives[i][j];
                best = Math.max(best, Math.min(total2, total5));

                total2 = up2 + right2 - twos[i][j];
                total5 = up5 + right5 - fives[i][j];
                best = Math.max(best, Math.min(total2, total5));

                total2 = down2 + left2 - twos[i][j];
                total5 = down5 + left5 - fives[i][j];
                best = Math.max(best, Math.min(total2, total5));

                total2 = down2 + right2 - twos[i][j];
                total5 = down5 + right5 - fives[i][j];
                best = Math.max(best, Math.min(total2, total5));
            }
        }
        return best;
    }
}

