class Solution {
    public static int[] countRectangles(int[][] rectangles, int[][] points) {
        Arrays.sort(rectangles, (a, b) -> Integer.compare(b[0], a[0]));
        int n = points.length;
        int[][] pts = new int[n][3];
        for (int i = 0; i < n; i++) {
            pts[i][0] = points[i][0];
            pts[i][1] = points[i][1];
            pts[i][2] = i;
        }
        Arrays.sort(pts, (a, b) -> Integer.compare(b[0], a[0]));
        List<Integer> allHeights = new ArrayList<>();
        for (int[] rect : rectangles) allHeights.add(rect[1]);
        for (int[] p : points) allHeights.add(p[1]);
        Collections.sort(allHeights);
        List<Integer> uniqList = new ArrayList<>();
        Integer prev = null;
        for (Integer v : allHeights) {
            if (!v.equals(prev)) {
                uniqList.add(v);
                prev = v;
            }
        }
        int size = uniqList.size();
        Map<Integer, Integer> idx = new HashMap<>();
        for (int i = 0; i < size; i++) {
            idx.put(uniqList.get(i), i + 1);
        }
        int[] bit = new int[size + 2];
        int[] ans = new int[n];
        int r = 0;
        for (int[] p : pts) {
            int x = p[0];
            int y = p[1];
            int orig = p[2];
            while (r < rectangles.length && rectangles[r][0] >= x) {
                int hIdx = idx.get(rectangles[r][1]);
                for (int xIdx = hIdx; xIdx <= size; xIdx += xIdx & -xIdx) {
                    bit[xIdx] += 1;
                }
                r++;
            }
            int total = r;
            int yIdx = idx.get(y);
            int sum = 0;
            for (int xIdx = yIdx - 1; xIdx > 0; xIdx -= xIdx & -xIdx) {
                sum += bit[xIdx];
            }
            ans[orig] = total - sum;
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    public static int longestPath(int[] parent, String s) {
        int n = parent.length;
        List<Integer>[] children = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            children[i] = new ArrayList<>();
        }
        for (int i = 1; i < n; i++) {
            children[parent[i]].add(i);
        }
        int[] bestDown = new int[n];
        int answer = 1;
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{0, 0});
        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            int node = cur[0];
            int state = cur[1];
            if (state == 0) {
                stack.push(new int[]{node, 1});
                for (int child : children[node]) {
                    stack.push(new int[]{child, 0});
                }
            } else {
                int best1 = 0, best2 = 0;
                for (int child : children[node]) {
                    if (s.charAt(child) == s.charAt(node)) continue;
                    int len = bestDown[child];
                    if (len > best1) {
                        best2 = best1;
                        best1 = len;
                    } else if (len > best2) {
                        best2 = len;
                    }
                }
                bestDown[node] = best1 + 1;
                answer = Math.max(answer, best1 + best2 + 1);
            }
        }
        return answer;
    }
}

