class Solution {
    public static int countLatticePoints(int[][] circles) {
        Set<String> visited = new HashSet<>();
        for (int i = 0; i < circles.length; i++) {
            int cx = circles[i][0];
            int cy = circles[i][1];
            int r = circles[i][2];
            int r2 = r * r;
            for (int x = cx - r; x <= cx + r; x++) {
                int dx = x - cx;
                int maxDy = (int) Math.floor(Math.sqrt(r2 - dx * dx));
                for (int y = cy - maxDy; y <= cy + maxDy; y++) {
                    visited.add(x + "," + y);
                }
            }
        }
        return visited.size();
    }
}

