class Solution {
    public static int[] fullBloomFlowers(int[][] flowers, int[] people) {
        int n = flowers.length;
        int[] starts = new int[n];
        int[] ends = new int[n];
        for (int i = 0; i < n; i++) {
            starts[i] = flowers[i][0];
            ends[i] = flowers[i][1];
        }
        Arrays.sort(starts);
        Arrays.sort(ends);
        int[] ans = new int[people.length];
        for (int i = 0; i < people.length; i++) {
            int t = people[i];
            int started = upperBound(starts, t);
            int ended = lowerBound(ends, t);
            ans[i] = started - ended;
        }
        return ans;
    }

    private static int upperBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] <= target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    private static int lowerBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }
}

class Solution {
    public static int minimumAverageDifference(int[] nums) {
        int n = nums.length;
        long totalSum = 0;
        for (int v : nums) totalSum += v;
        long prefixSum = 0;
        int bestIdx = 0;
        long bestDiff = Long.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            prefixSum += nums[i];
            int leftAvg = (int)(prefixSum / (i + 1));
            int rightCount = n - i - 1;
            int rightAvg = rightCount > 0 ? (int)((totalSum - prefixSum) / rightCount) : 0;
            long diff = Math.abs((long)leftAvg - (long)rightAvg);
            if (diff < bestDiff) {
                bestDiff = diff;
                bestIdx = i;
            }
        }
        return bestIdx;
    }
}

