class Solution {
    public static int countUnguarded(int m, int n, int[][] guards, int[][] walls) {
        int[][] grid = new int[m][n];
        for (int[] g : guards) grid[g[0]][g[1]] = 1;
        for (int[] w : walls) grid[w[0]][w[1]] = 2;
        boolean[][] guarded = new boolean[m][n];
        for (int i = 0; i < m; i++) {
            boolean seen = false;
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) seen = true;
                else if (grid[i][j] == 2) seen = false;
                else if (seen) guarded[i][j] = true;
            }
            seen = false;
            for (int j = n - 1; j >= 0; j--) {
                if (grid[i][j] == 1) seen = true;
                else if (grid[i][j] == 2) seen = false;
                else if (seen) guarded[i][j] = true;
            }
        }
        for (int j = 0; j < n; j++) {
            boolean seen = false;
            for (int i = 0; i < m; i++) {
                if (grid[i][j] == 1) seen = true;
                else if (grid[i][j] == 2) seen = false;
                else if (seen) guarded[i][j] = true;
            }
            seen = false;
            for (int i = m - 1; i >= 0; i--) {
                if (grid[i][j] == 1) seen = true;
                else if (grid[i][j] == 2) seen = false;
                else if (seen) guarded[i][j] = true;
            }
        }
        int unguarded = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 0 && !guarded[i][j]) unguarded++;
            }
        }
        return unguarded;
    }
}

import java.util.*;

class Solution {
    private static final int[][] DIRS = {{-1,0},{1,0},{0,-1},{0,1}};

    public int maximumMinutes(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[][] fire = new int[m][n];
        for (int[] row : fire) Arrays.fill(row, Integer.MAX_VALUE);
        Deque<int[]> q = new ArrayDeque<>();
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (grid[i][j] == 1) { fire[i][j] = 0; q.add(new int[]{i,j}); }
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            for (int[] d : DIRS) {
                int ni = cur[0]+d[0], nj = cur[1]+d[1];
                if (ni>=0 && ni<m && nj>=0 && nj<n && grid[ni][nj]!=2 && fire[ni][nj]==Integer.MAX_VALUE) {
                    fire[ni][nj] = fire[cur[0]][cur[1]] + 1;
                    q.add(new int[]{ni,nj});
                }
            }
        }
        if (fire[m-1][n-1] == Integer.MAX_VALUE) {
            return canReach(grid, fire, 0) ? 1_000_000_000 : -1;
        }
        if (!canReach(grid, fire, 0)) return -1;
        int lo = 0, hi = fire[m-1][n-1], ans = 0;
        while (lo <= hi) {
            int mid = lo + (hi-lo)/2;
            if (canReach(grid, fire, mid)) { ans = mid; lo = mid+1; }
            else hi = mid-1;
        }
        return ans;
    }

    private boolean canReach(int[][] grid, int[][] fire, int wait) {
        int m = grid.length, n = grid[0].length;
        if (wait >= fire[0][0]) return false;
        int[][] person = new int[m][n];
        for (int[] row : person) Arrays.fill(row, Integer.MAX_VALUE);
        person[0][0] = wait;
        Deque<int[]> q = new ArrayDeque<>();
        q.add(new int[]{0,0});
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            for (int[] d : DIRS) {
                int ni = cur[0]+d[0], nj = cur[1]+d[1];
                if (ni>=0 && ni<m && nj>=0 && nj<n && grid[ni][nj]!=2 && person[ni][nj]==Integer.MAX_VALUE) {
                    int t = person[cur[0]][cur[1]] + 1;
                    if (ni==m-1 && nj==n-1) {
                        if (t <= fire[ni][nj]) { person[ni][nj]=t; q.add(new int[]{ni,nj}); }
                    } else {
                        if (t < fire[ni][nj]) { person[ni][nj]=t; q.add(new int[]{ni,nj}); }
                    }
                }
            }
        }
        return person[m-1][n-1] != Integer.MAX_VALUE;
    }
}

