class Solution {
    public static int countDistinctSubarrays(int[] nums, int k, int p) {
        int n = nums.length;
        final long MOD1 = 1000000007L;
        final long MOD2 = 1000000009L;
        final long BASE = 91138233L;

        long[] pref1 = new long[n + 1];
        long[] pref2 = new long[n + 1];
        long[] pow1 = new long[n + 1];
        long[] pow2 = new long[n + 1];
        pow1[0] = 1;
        pow2[0] = 1;
        for (int i = 0; i < n; ++i) {
            pref1[i + 1] = (pref1[i] * BASE + nums[i]) % MOD1;
            pref2[i + 1] = (pref2[i] * BASE + nums[i]) % MOD2;
            pow1[i + 1] = (pow1[i] * BASE) % MOD1;
            pow2[i + 1] = (pow2[i] * BASE) % MOD2;
        }

        Set<String> seen = new HashSet<>();

        for (int i = 0; i < n; ++i) {
            int divCnt = 0;
            for (int j = i; j < n; ++j) {
                if (nums[j] % p == 0) ++divCnt;
                if (divCnt > k) break;

                int len = j - i + 1;
                long h1 = (pref1[j + 1] - pref1[i] * pow1[len]) % MOD1;
                long h2 = (pref2[j + 1] - pref2[i] * pow2[len]) % MOD2;
                if (h1 < 0) h1 += MOD1;
                if (h2 < 0) h2 += MOD2;

                seen.add(h1 + "," + h2);
            }
        }
        return seen.size();
    }
}

