class Solution {
    private static int answer;
    public static int countNodesEqualToAverage(TreeNode root) {
        answer = 0;
        dfs(root);
        return answer;
    }
    private static long[] dfs(TreeNode node) {
        if (node == null) return new long[]{0, 0};
        long[] left = dfs(node.left);
        long[] right = dfs(node.right);
        long subtreeSum = node.val + left[0] + right[0];
        long subtreeSize = 1 + left[1] + right[1];
        if (node.val == subtreeSum / subtreeSize) answer++;
        return new long[]{subtreeSum, subtreeSize};
    }
}

