class Solution {
    private static final int MOD = 1_000_000_007;

    public static int countTexts(String pressedKeys) {
        int n = pressedKeys.length();
        int maxRun = 0;
        for (int i = 0; i < n; ) {
            char c = pressedKeys.charAt(i);
            int j = i;
            while (j < n && pressedKeys.charAt(j) == c) j++;
            int len = j - i;
            if (len > maxRun) maxRun = len;
            i = j;
        }
        long[] dp3 = new long[maxRun + 1];
        long[] dp4 = new long[maxRun + 1];
        dp3[0] = 1;
        dp4[0] = 1;
        for (int i = 1; i <= maxRun; i++) {
            dp3[i] = dp3[i - 1];
            if (i >= 2) dp3[i] = (dp3[i] + dp3[i - 2]) % MOD;
            if (i >= 3) dp3[i] = (dp3[i] + dp3[i - 3]) % MOD;

            dp4[i] = dp4[i - 1];
            if (i >= 2) dp4[i] = (dp4[i] + dp4[i - 2]) % MOD;
            if (i >= 3) dp4[i] = (dp4[i] + dp4[i - 3]) % MOD;
            if (i >= 4) dp4[i] = (dp4[i] + dp4[i - 4]) % MOD;
        }
        long ans = 1;
        for (int i = 0; i < n; ) {
            char c = pressedKeys.charAt(i);
            int j = i;
            while (j < n && pressedKeys.charAt(j) == c) j++;
            int len = j - i;
            if (c == '7' || c == '9') {
                ans = ans * dp4[len] % MOD;
            } else {
                ans = ans * dp3[len] % MOD;
            }
            i = j;
        }
        return (int) ans;
    }
}

