class Solution {
    public static boolean hasValidPath(char[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int maxBal = m + n;
        byte[][] dpPrev = new byte[n][];
        byte[][] dpCurr = new byte[n][];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                byte[] curBal = new byte[maxBal + 1];
                char ch = grid[i][j];
                if (i == 0 && j == 0) {
                    if (ch == '(') {
                        curBal[1] = 1;
                    }
                } else {
                    byte[] fromTop = i > 0 ? dpPrev[j] : null;
                    byte[] fromLeft = j > 0 ? dpCurr[j - 1] : null;
                    for (int b = 0; b <= maxBal; b++) {
                        boolean reachable = false;
                        if (fromTop != null && fromTop[b] != 0) reachable = true;
                        if (fromLeft != null && fromLeft[b] != 0) reachable = true;
                        if (reachable) {
                            if (ch == '(' && b + 1 <= maxBal) {
                                curBal[b + 1] = 1;
                            } else if (ch == ')' && b > 0) {
                                curBal[b - 1] = 1;
                            }
                        }
                    }
                }
                dpCurr[j] = curBal;
            }
            dpPrev = dpCurr;
            dpCurr = new byte[n][];
        }
        return dpPrev[n - 1][0] == 1;
    }
}

