public class Solution {
    public static int kBeauty(int num, int k) {
        String s = Integer.toString(num);
        int n = s.length();
        if (k > n || k <= 0) return 0;
        long power = 1;
        for (int i = 1; i < k; i++) power *= 10;
        long cur = 0;
        for (int i = 0; i < k; i++) cur = cur * 10 + (s.charAt(i) - '0');
        int ans = 0;
        if (cur != 0 && num % cur == 0) ans++;
        for (int i = k; i < n; i++) {
            int outDigit = s.charAt(i - k) - '0';
            int inDigit = s.charAt(i) - '0';
            cur = (cur - outDigit * power) * 10 + inDigit;
            if (cur != 0 && num % cur == 0) ans++;
        }
        return ans;
    }
}

class Solution {
