class Solution {
    public static int maximumWhiteTiles(int[][] tiles, int carpetLen) {
        Arrays.sort(tiles, (a, b) -> Integer.compare(a[0], b[0]));
        int n = tiles.length;
        int left = 0;
        long curLen = 0;
        int best = 0;
        for (int right = 0; right < n; right++) {
            curLen += tiles[right][1] - tiles[right][0] + 1;
            int carpetStart = tiles[right][1] - carpetLen + 1;
            while (left <= right && tiles[left][1] < carpetStart) {
                curLen -= tiles[left][1] - tiles[left][0] + 1;
                left++;
            }
            long covered = curLen;
            if (tiles[left][0] < carpetStart) {
                covered -= carpetStart - tiles[left][0];
            }
            if (covered > best) {
                best = (int) covered;
            }
        }
        return best;
    }
}

