import java.util.*;

class Solution {
    private static final long MOD = 1_000_000_007L;

    public static long totalStrength(int[] strength) {
        int n = strength.length;
        int[] left = new int[n];
        int[] right = new int[n];

        Deque<Integer> stack = new ArrayDeque<>();

        // previous less (strict)
        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && strength[stack.peek()] >= strength[i]) {
                stack.pop();
            }
            left[i] = stack.isEmpty() ? -1 : stack.peek();
            stack.push(i);
        }

        stack.clear();

        // next less or equal
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && strength[stack.peek()] > strength[i]) {
                stack.pop();
            }
            right[i] = stack.isEmpty() ? n : stack.peek();
            stack.push(i);
        }

        long[] pref = new long[n + 1];      // prefix sums of strengths
        for (int i = 0; i < n; i++) {
            pref[i + 1] = (pref[i] + strength[i]) % MOD;
        }

        long[] pref2 = new long[n + 2];     // prefix sums of pref
        for (int i = 0; i <= n; i++) {
            pref2[i + 1] = (pref2[i] + pref[i]) % MOD;
        }

        long ans = 0;
        for (int i = 0; i < n; i++) {
            int l = left[i];
            int r = right[i];

            long leftCount = i - l;
            long rightCount = r - i;

            long sumRight = (pref2[r + 1] - pref2[i + 1] + MOD) % MOD; // Σ_{t=i+1}^{r} pref[t]
            long sumLeft = (pref2[i + 1] - pref2[l + 1] + MOD) % MOD;  // Σ_{t=l+1}^{i} pref[t]

            long contrib = (leftCount % MOD) * sumRight % MOD;
            contrib = (contrib - (rightCount % MOD) * sumLeft % MOD + MOD) % MOD;
            contrib = contrib * (strength[i] % MOD) % MOD;

            ans = (ans + contrib) % MOD;
        }

        return ans;
    }
}

public class Solution {
