    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static String largestWordCount(String[] messages, String[] senders) {
        Map<String, Integer> counts = new HashMap<>();
        for (int i = 0; i < messages.length; i++) {
            String msg = messages[i];
            String sender = senders[i];
            int wordCount = 1 + (msg.split(" ").length - 1);
            counts.put(sender, counts.getOrDefault(sender, 0) + wordCount);
        }
        String bestSender = "";
        int bestCount = -1;
        for (Map.Entry<String, Integer> entry : counts.entrySet()) {
            String sender = entry.getKey();
            int cnt = entry.getValue();
            if (cnt > bestCount || (cnt == bestCount && sender.compareTo(bestSender) > 0)) {
                bestCount = cnt;
                bestSender = sender;
            }
        }
        return bestSender;
    }
}

import java.util.Arrays;

public class Solution {
    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    public static int minLines(int[][] stockPrices) {
        int n = stockPrices.length;
        if (n <= 1) return 0;
        Arrays.sort(stockPrices, (p, q) -> Integer.compare(p[0], q[0]));
        int dy = stockPrices[1][1] - stockPrices[0][1];
        int dx = stockPrices[1][0] - stockPrices[0][0];
        int g = gcd(Math.abs(dy), Math.abs(dx));
        dy /= g;
        dx /= g;
        if (dx < 0) {
            dx = -dx;
            dy = -dy;
        }
        if (dx == 0) dy = 1;
        int lines = 1;
        for (int i = 2; i < n; ++i) {
            int ndy = stockPrices[i][1] - stockPrices[i - 1][1];
            int ndx = stockPrices[i][0] - stockPrices[i - 1][0];
            int ng = gcd(Math.abs(ndy), Math.abs(ndx));
            ndy /= ng;
            ndx /= ng;
            if (ndx < 0) {
                ndx = -ndx;
                ndy = -ndy;
            }
            if (ndx == 0) ndy = 1;
            if (ndy != dy || ndx != dx) {
                ++lines;
                dy = ndy;
                dx = ndx;
            }
        }
        return lines;
    }
}

