class Solution {
    public static long maximumImportance(int n, int[][] roads) {
        int[] degree = new int[n];
        for (int[] road : roads) {
            int a = road[0];
            int b = road[1];
            degree[a]++;
            degree[b]++;
        }
        Integer[] degObj = new Integer[n];
        for (int i = 0; i < n; i++) {
            degObj[i] = degree[i];
        }
        Arrays.sort(degObj, Collections.reverseOrder());
