    }
}

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;

class Solution {
    public static int minimumObstacles(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int[][] dist = new int[m][n];
        for (int i = 0; i < m; i++) {
            Arrays.fill(dist[i], Integer.MAX_VALUE);
        }
        Deque<int[]> deque = new ArrayDeque<>();
        dist[0][0] = 0;
        deque.offerFirst(new int[]{0, 0});
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (!deque.isEmpty()) {
            int[] cur = deque.pollFirst();
            int x = cur[0], y = cur[1];
            int curDist = dist[x][y];
            if (x == m - 1 && y == n - 1) {
                return curDist;
            }
            for (int[] d : dirs) {
                int nx = x + d[0];
                int ny = y + d[1];
                if (nx < 0 || ny < 0 || nx >= m || ny >= n) continue;
                int nd = curDist + grid[nx][ny];
                if (nd < dist[nx][ny]) {
                    dist[nx][ny] = nd;
                    if (grid[nx][ny] == 0) {
                        deque.offerFirst(new int[]{nx, ny});
                    } else {
                        deque.offerLast(new int[]{nx, ny});
                    }
                }
            }
        }
        return dist[m - 1][n - 1];
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static int rearrange(String s, String target) {
        Map<Character, Integer> sCount = new HashMap<>();
        Map<Character, Integer> tCount = new HashMap<>();

        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            sCount.put(ch, sCount.getOrDefault(ch, 0) + 1);
        }

        for (int i = 0; i < target.length(); i++) {
            char ch = target.charAt(i);
            tCount.put(ch, tCount.getOrDefault(ch, 0) + 1);
        }

        int copies = Integer.MAX_VALUE;
        for (char ch : tCount.keySet()) {
            int available = sCount.getOrDefault(ch, 0);
            copies = Math.min(copies, available / tCount.get(ch));
        }
        return copies == Integer.MAX_VALUE ? 0 : copies;
    }
}

