    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public static int stepsToMakeNonDecreasing(int[] nums) {
        int maxSteps = 0;
        Deque<int[]> stack = new ArrayDeque<>();
        for (int i = 0; i < nums.length; i++) {
            int curSteps = 0;
            while (!stack.isEmpty() && nums[i] >= stack.peekLast()[0]) {
                curSteps = Math.max(curSteps, stack.peekLast()[1]);
                stack.pollLast();
            }
            if (stack.isEmpty()) {
                curSteps = 0;
            } else {
                curSteps += 1;
            }
            maxSteps = Math.max(maxSteps, curSteps);
            stack.addLast(new int[]{nums[i], curSteps});
        }
        return maxSteps;
    }
}

import java.util.*;
class BookMyShow {
    private final int n;
    private final int m;
    private final int[] rem;
    private final int[] mx;
    private final long[] sum;
    public BookMyShow(int n, int m) {
        this.n = n; this.m = m;
        this.rem = new int[n];
        Arrays.fill(this.rem, m);
        this.mx = new int[4 * n];
        this.sum = new long[4 * n];
        build(1, 0, n - 1);
    }
    private void build(int node, int l, int r) {
        if (l == r) { sum[node] = m; mx[node] = m; }
        else {
            int mid = (l+r)>>1;
            build(node*2, l, mid); build(node*2+1, mid+1, r);
            pull(node);
        }
    }
    private void pull(int node) {
        sum[node] = sum[node*2] + sum[node*2+1];
        mx[node] = Math.max(mx[node*2], mx[node*2+1]);
    }
    private void update(int node, int l, int r, int idx, int val) {
        if (l == r) { sum[node] = val; mx[node] = val; }
        else {
            int mid = (l+r)>>1;
            if (idx <= mid) update(node*2, l, mid, idx, val);
            else update(node*2+1, mid+1, r, idx, val);
            pull(node);
        }
    }
    private int findGather(int node, int l, int r, int maxRow, int k) {
        if (l > maxRow || mx[node] < k) return -1;
        if (l == r) return l;
        int mid = (l+r)>>1;
        int left = findGather(node*2, l, mid, maxRow, k);
        if (left != -1) return left;
        return findGather(node*2+1, mid+1, r, maxRow, k);
    }
    private long querySum(int node, int l, int r, int ql, int qr) {
        if (ql > r || qr < l) return 0;
        if (ql <= l && r <= qr) return sum[node];
        int mid = (l+r)>>1;
        return querySum(node*2, l, mid, ql, qr) + querySum(node*2+1, mid+1, r, ql, qr);
    }
    private int findFirstPositive(int node, int l, int r, int maxRow) {
        if (l > maxRow || mx[node] == 0) return -1;
        if (l == r) return l;
        int mid = (l+r)>>1;
        int left = findFirstPositive(node*2, l, mid, maxRow);
        if (left != -1) return left;
        return findFirstPositive(node*2+1, mid+1, r, maxRow);
    }
    public List<Integer> gather(int k, int maxRow) {
        int row = findGather(1, 0, n-1, maxRow, k);
        if (row == -1) return new ArrayList<>();
        int startSeat = m - rem[row];
        rem[row] -= k;
        update(1, 0, n-1, row, rem[row]);
        return Arrays.asList(row, startSeat);
    }
    public boolean scatter(int k, int maxRow) {
        long total = querySum(1, 0, n-1, 0, maxRow);
        if (total < k) return false;
        while (k > 0) {
            int row = findFirstPositive(1, 0, n-1, maxRow);
            int take = Math.min(rem[row], k);
            rem[row] -= take;
            update(1, 0, n-1, row, rem[row]);
            k -= take;
        }
        return true;
    }
}

