class TextEditor {
    private Deque<Character> left;
    private Deque<Character> right;
    public TextEditor() { left = new ArrayDeque<>(); right = new ArrayDeque<>(); }
    public void addText(String txt) { for (int i = 0; i < txt.length(); i++) left.addLast(txt.charAt(i)); }
    public int deleteText(int k) {
        int removed = 0;
        while (removed < k && !left.isEmpty()) { left.removeLast(); removed++; }
        return removed;
    }
    public String cursorLeft(int k) {
        int moved = 0;
        while (moved < k && !left.isEmpty()) { right.addLast(left.removeLast()); moved++; }
        return getLastLeft(10);
    }
    public String cursorRight(int k) {
        int moved = 0;
        while (moved < k && !right.isEmpty()) { left.addLast(right.removeLast()); moved++; }
        return getLastLeft(10);
    }
    private String getLastLeft(int limit) {
        StringBuilder sb = new StringBuilder();
        Iterator<Character> it = left.descendingIterator();
        int count = 0;
        while (it.hasNext() && count < limit) { sb.append(it.next()); count++; }
        return sb.reverse().toString();
    }
}

class Solution {
    public static int minMaxGame(int[] nums) {
        int n = nums.length;
        while (n > 1) {
            for (int i = 0; i < n / 2; i++) {
                if (i % 2 == 0) {
                    nums[i] = Math.min(nums[2 * i], nums[2 * i + 1]);
                } else {
                    nums[i] = Math.max(nums[2 * i], nums[2 * i + 1]);
                }
            }
            n = n / 2;
        }
        return nums[0];
    }
}

