class Solution {
    public static int minSubsequences(int[] nums, int k) {
        if (nums.length == 0) return 0;
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        int groups = 1;
        int start = sorted[0];
        for (int i = 1; i < sorted.length; i++) {
            if (sorted[i] - start > k) {
                groups++;
                start = sorted[i];
            }
        }
        return groups;
    }
}

