class Solution {
    public static int[] successfulPairs(int[] spells, int[] potions, long success) {
        Arrays.sort(potions);
        int m = potions.length;
        int[] answer = new int[spells.length];
        for (int i = 0; i < spells.length; i++) {
            int spell = spells[i];
            long need = (success + spell - 1) / spell;
            int lo = 0, hi = m;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (potions[mid] < need) {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }
            answer[i] = m - lo;
        }
        return answer;
    }
}

