class Solution {
    public static double calculateTax(double[][] brackets, double income) {
        double tax = 0.0;
        double prevUpper = 0.0;
        for (int i = 0; i < brackets.length; i++) {
            double upper = brackets[i][0];
            double percent = brackets[i][1];
            double taxable = Math.min(income, upper) - prevUpper;
            if (taxable <= 0) {
                break;
            }
            tax += taxable * percent / 100.0;
            prevUpper = upper;
            if (income <= upper) {
                break;
            }
        }
        return tax;
    }
}

public class Solution {
    public static long countSubarrays(int[] nums, int k) {
        if (k <= 0) return 0L;
        long kLong = k;
        int left = 0;
        long sum = 0;
        long answer = 0;
        for (int right = 0; right < nums.length; right++) {
            sum += nums[right];
            while (left <= right && sum * (right - left + 1) >= kLong) {
                sum -= nums[left++];
            }
            answer += right - left + 1;
        }
        return answer;
    }
}

