class Solution {
    public static int minimumPathCost(int[][] grid, int[][] moveCost) {
        int m = grid.length;
        int n = grid[0].length;
        int[] dpPrev = new int[n];
        for (int j = 0; j < n; ++j) {
            dpPrev[j] = grid[0][j];
        }
        for (int i = 1; i < m; ++i) {
            int[] dpCur = new int[n];
            for (int j = 0; j < n; ++j) {
                int best = Integer.MAX_VALUE;
                for (int k = 0; k < n; ++k) {
                    int cand = dpPrev[k] + moveCost[grid[i - 1][k]][j];
                    if (cand < best) {
                        best = cand;
                    }
                }
                dpCur[j] = grid[i][j] + best;
            }
            dpPrev = dpCur;
        }
        int answer = Integer.MAX_VALUE;
        for (int v : dpPrev) {
            if (v < answer) {
                answer = v;
            }
        }
        return answer;
    }
}

import java.util.*;

public class Solution {
    public static int distributeCookies(int[] cookies, int k) {
        int n = cookies.length;
        Integer[] sorted = new Integer[n];
        for (int i = 0; i < n; i++) sorted[i] = cookies[i];
        Arrays.sort(sorted, Collections.reverseOrder());
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) arr[i] = sorted[i];
        if (k >= n) {
            return arr[0];
        }
        int total = 0;
        int low = arr[0];
        for (int v : arr) total += v;
        int high = total;
        while (low < high) {
            int mid = (low + high) / 2;
            int[] load = new int[k];
            if (dfs(0, arr, k, mid, load)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    private static boolean dfs(int idx, int[] cookies, int k, int limit, int[] load) {
        if (idx == cookies.length) return true;
        int cur = cookies[idx];
        for (int i = 0; i < k; i++) {
            if (load[i] + cur > limit) continue;
            load[i] += cur;
            if (dfs(idx + 1, cookies, k, limit, load)) return true;
            load[i] -= cur;
            if (load[i] == 0) break;
        }
        return false;
    }
}

