public class Solution {
    public static int maxProfit(int m, int n, int[][] prices) {
        int[][] priceMap = new int[m + 1][n + 1];
        for (int[] pInfo : prices) {
            int h = pInfo[0];
            int w = pInfo[1];
            int p = pInfo[2];
            if (h <= m && w <= n && p > priceMap[h][w]) {
                priceMap[h][w] = p;
            }
        }
        int[][] dp = new int[m + 1][n + 1];
        for (int h = 1; h <= m; ++h) {
            for (int w = 1; w <= n; ++w) {
                int best = priceMap[h][w];
                for (int cut = 1; cut < h; ++cut) {
                    int cur = dp[cut][w] + dp[h - cut][w];
                    if (cur > best) best = cur;
                }
                for (int cut = 1; cut < w; ++cut) {
                    int cur = dp[h][cut] + dp[h][w - cut];
                    if (cur > best) best = cur;
                }
                dp[h][w] = best;
            }
        }
        return dp[m][n];
    }
}

public class Solution {
    public static int longestBinarySubsequenceLength(String s, int k) {
        long remaining = k;
        int length = 0;
        for (int i = s.length() - 1; i >= 0; i--) {
            char c = s.charAt(i);
            if (c == '0') {
                length++;
            } else {
                if (length >= 63) continue;
                long weight = 1L << length;
                if (weight <= remaining) {
                    remaining -= weight;
                    length++;
                }
            }
        }
        return length;
    }
}

