class Solution {
    public static int minimumSetSize(int num, int k) {
        if (num == 0) return 0;
        if (k == 0) return (num % 10 == 0) ? 1 : -1;
        int target = num % 10;
        int g = gcd(k, 10);
        if (target % g != 0) return -1;
        int mod = 10 / g;
        int kReduced = k / g;
        int targetReduced = target / g;
        int inv = modInverse(kReduced, mod);
        int m = (int) ((long) targetReduced * inv % mod);
        if (m == 0) m = mod;
        if ((long) m * k > num) return -1;
        return m;
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    private static int modInverse(int a, int mod) {
        int[] res = extendedGcd(a, mod);
        int x = res[1];
        x %= mod;
        if (x < 0) x += mod;
        return x;
    }

    private static int[] extendedGcd(int a, int b) {
        if (b == 0) return new int[]{a, 1, 0};
        int[] vals = extendedGcd(b, a % b);
        int d = vals[0];
        int x1 = vals[2];
        int y1 = vals[1] - (a / b) * vals[2];
        return new int[]{d, x1, y1};
    }
}

