import java.lang.*;

class Solution {
    private static final long MOD = 1000000007L;

    private static long[] fib(long k) {
        if (k == 0) return new long[]{0L, 1L};
        long[] ab = fib(k / 2);
        long a = ab[0];
        long b = ab[1];
        long twoBminusA = (2L * b % MOD - a + MOD) % MOD;
        long c = (a * twoBminusA) % MOD;
        long d = (a * a % MOD + b * b % MOD) % MOD;
        if ((k & 1L) == 0L) {
            return new long[]{c, d};
        } else {
            return new long[]{d, (c + d) % MOD};
        }
    }

    public static long countWays(long n) {
        long f = fib(n + 2)[0];
        return (f * f) % MOD;
    }
}

