class ListNode {
    int val;
    ListNode next;
    ListNode(int x) { val = x; }
}

class Solution {
    public static int[][] spiralMatrix(int m, int n, ListNode head) {
        int[][] matrix = new int[m][n];
        for (int i = 0; i < m; i++) {
            Arrays.fill(matrix[i], -1);
        }
        int top = 0, bottom = m - 1, left = 0, right = n - 1;
        ListNode cur = head;
        int filled = 0, total = m * n;
        while (filled < total && cur != null) {
            for (int col = left; col <= right && cur != null; col++) {
                matrix[top][col] = cur.val;
                cur = cur.next;
                filled++;
            }
            top++;
            for (int row = top; row <= bottom && cur != null; row++) {
                matrix[row][right] = cur.val;
                cur = cur.next;
                filled++;
            }
            right--;
            for (int col = right; col >= left && cur != null; col--) {
                matrix[bottom][col] = cur.val;
                cur = cur.next;
                filled++;
            }
            bottom--;
            for (int row = bottom; row >= top && cur != null; row--) {
                matrix[row][left] = cur.val;
                cur = cur.next;
                filled++;
            }
            left++;
        }
        return matrix;
    }
}

class Solution {
    public static int peopleAwareOfSecret(int n, int delay, int forget) {
        final long MOD = 1_000_000_007L;
        long[] diff = new long[n + 2];
        if (1 + delay <= n) diff[1 + delay] = (diff[1 + delay] + 1) % MOD;
        if (1 + forget <= n) diff[1 + forget] = (diff[1 + forget] - 1 + MOD) % MOD;
        long active = 0;
        long result = 0;
        if (1 + forget > n) result = (result + 1) % MOD;
        for (int day = 2; day <= n; day++) {
            active = (active + diff[day] + MOD) % MOD;
            long dp = active;
            if (day + delay <= n) diff[day + delay] = (diff[day + delay] + dp) % MOD;
            if (day + forget <= n) diff[day + forget] = (diff[day + forget] - dp + MOD) % MOD;
            if (day + forget > n) result = (result + dp) % MOD;
        }
        return (int) result;
    }
}

