class Solution {
    public static long maximumScore(int[] nums1, int[] nums2) {
        int n = nums1.length;
        long sum1 = 0, sum2 = 0;
        for (int i = 0; i < n; ++i) {
            sum1 += nums1[i];
            sum2 += nums2[i];
        }
        long maxDiff = Long.MIN_VALUE, curMax = 0;
        long minDiff = Long.MAX_VALUE, curMin = 0;
        for (int i = 0; i < n; ++i) {
            long d = (long) nums2[i] - nums1[i];
            curMax = Math.max(d, curMax + d);
            maxDiff = Math.max(maxDiff, curMax);
            curMin = Math.min(d, curMin + d);
            minDiff = Math.min(minDiff, curMin);
        }
        long result = Math.max(sum1, sum2);
        result = Math.max(result, sum1 + maxDiff);
        result = Math.max(result, sum2 - minDiff);
        return result;
    }
}

import java.util.*;

class Solution {
    private static int timer;
    private static int[] tin;
    private static int[] tout;
    private static int[] subXor;
    private static List<Integer>[] graph;

    public static int minimumScore(int[] nums, int[][] edges) {
        int n = nums.length;
        graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            int a = e[0], b = e[1];
            graph[a].add(b);
            graph[b].add(a);
        }
        tin = new int[n];
        tout = new int[n];
        subXor = new int[n];
        timer = 0;
        dfs(0, -1, nums);
        int totalXor = subXor[0];
        int ans = Integer.MAX_VALUE;
        for (int a = 1; a < n; a++) {
            for (int b = a + 1; b < n; b++) {
                int comp1, comp2, comp3;
                if (isAncestor(a, b)) {
                    int X = subXor[a];
                    int Y = subXor[b];
                    comp1 = Y;
                    comp2 = X ^ Y;
                    comp3 = totalXor ^ X;
                } else if (isAncestor(b, a)) {
                    int X = subXor[b];
                    int Y = subXor[a];
                    comp1 = Y;
                    comp2 = X ^ Y;
                    comp3 = totalXor ^ X;
                } else {
                    int X = subXor[a];
                    int Y = subXor[b];
                    comp1 = X;
                    comp2 = Y;
                    comp3 = totalXor ^ X ^ Y;
                }
                int max = Math.max(comp1, Math.max(comp2, comp3));
                int min = Math.min(comp1, Math.min(comp2, comp3));
                ans = Math.min(ans, max - min);
            }
        }
        return ans;
    }

    private static void dfs(int node, int parent, int[] nums) {
        tin[node] = ++timer;
        int xor = nums[node];
        for (int nb : graph[node]) {
            if (nb == parent) continue;
            dfs(nb, node, nums);
            xor ^= subXor[nb];
        }
        subXor[node] = xor;
        tout[node] = timer;
    }

    private static boolean isAncestor(int u, int v) {
        return tin[u] <= tin[v] && tout[v] <= tout[u];
    }
}

import java.util.HashMap;

class Solution {
    public static String decodeMessage(String key, String message) {
        HashMap<Character, Character> map = new HashMap<>();
        int nextCharCode = (int) 'a';
        for (int i = 0; i < key.length(); i++) {
            char ch = key.charAt(i);
            if (ch == ' ') continue;
            if (!map.containsKey(ch)) {
                map.put(ch, (char) nextCharCode++);
            }
        }
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < message.length(); i++) {
            char ch = message.charAt(i);
            result.append(ch == ' ' ? ' ' : map.get(ch));
        }
        return result.toString();
    }
}

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

class Solution {
    public static int latestTimeCatchTheBus(int[] buses, int[] passengers, int capacity) {
        Arrays.sort(buses);
        Arrays.sort(passengers);
        Set<Integer> passengerSet = new HashSet<>();
        for (int p : passengers) {
            passengerSet.add(p);
        }
        int i = 0;
        int lastBoarded = -1;
        int cnt = 0;
        int lastBus = buses[buses.length - 1];
        for (int bus : buses) {
            cnt = 0;
            while (i < passengers.length && passengers[i] <= bus && cnt < capacity) {
                lastBoarded = passengers[i];
                i++;
                cnt++;
            }
            if (bus == lastBus) {
                // after processing the last bus, break to avoid unnecessary work
                break;
            }
        }
        int answer;
        if (cnt < capacity) {
            answer = lastBus;
        } else {
            answer = lastBoarded - 1;
        }
        while (passengerSet.contains(answer)) {
            answer--;
        }
        return answer;
    }
}

import java.util.*;

class Solution {
    private static final int MOD = 1_000_000_007;
    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    private static int dfs(int i, int j, int[][] grid, int[][] dp, int m, int n) {
        if (dp[i][j] != 0) return dp[i][j];
        long total = 1;
        for (int[] d : DIRS) {
            int x = i + d[0];
            int y = j + d[1];
            if (x < 0 || x >= m || y < 0 || y >= n) continue;
            if (grid[x][y] <= grid[i][j]) continue;
            total = (total + dfs(x, y, grid, dp, m, n)) % MOD;
        }
        dp[i][j] = (int) total;
        return dp[i][j];
    }

    public static int countIncreasingPaths(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int[][] dp = new int[m][n];
        long answer = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                answer = (answer + dfs(i, j, grid, dp, m, n)) % MOD;
            }
        }
        return (int) answer;
    }
}

