class SmallestInfiniteSet {
    private int next = 1;
    private PriorityQueue<Integer> heap = new PriorityQueue<>();
    private HashSet<Integer> inHeap = new HashSet<>();
    public int popSmallest() {
        if (!heap.isEmpty()) { int val = heap.poll(); inHeap.remove(val); return val; }
        return next++;
    }
    public void addBack(int num) {
        if (num < next && !inHeap.contains(num)) { heap.offer(num); inHeap.add(num); }
    }
}

import java.util.*;

public class Solution {
    private static final int MOD = 1_000_000_007;

    public static int idealArrays(int n, int maxValue) {
        int limit = n + 20;
        long[] fact = new long[limit + 1];
        long[] invFact = new long[limit + 1];
        fact[0] = 1;
        for (int i = 1; i <= limit; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[limit] = modPow(fact[limit], MOD - 2);
        for (int i = limit; i > 0; i--) {
            invFact[i - 1] = invFact[i] * i % MOD;
        }

        int[] spf = new int[maxValue + 1];
        for (int i = 2; i <= maxValue; i++) {
            if (spf[i] == 0) {
                for (int j = i; j <= maxValue; j += i) {
                    if (spf[j] == 0) spf[j] = i;
                }
            }
        }

        long ans = 0;
        for (int a = 1; a <= maxValue; a++) {
            int x = a;
            long ways = 1;
            while (x > 1) {
                int p = spf[x];
                int cnt = 0;
                while (x % p == 0) {
                    x /= p;
                    cnt++;
                }
                ways = ways * nCr(cnt + n - 1, n - 1, fact, invFact) % MOD;
            }
            ans += ways;
            if (ans >= MOD) ans -= MOD;
        }
        return (int) ans;
    }

    private static long nCr(int n, int r, long[] fact, long[] invFact) {
        if (r < 0 || r > n) return 0;
        return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
    }

    private static long modPow(long base, long exp) {
        long res = 1;
        long b = base % MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) res = res * b % MOD;
            b = b * b % MOD;
            exp >>= 1;
        }
        return res;
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public static int subarraySize(int[] nums, int threshold) {
        int n = nums.length;
        int[] left = new int[n];
        int[] right = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && nums[stack.peek()] >= nums[i]) {
                stack.pop();
            }
            left[i] = stack.isEmpty() ? -1 : stack.peek();
            stack.push(i);
        }
        stack.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && nums[stack.peek()] >= nums[i]) {
                stack.pop();
            }
            right[i] = stack.isEmpty() ? n : stack.peek();
            stack.push(i);
        }
        int answer = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            long need = threshold / (long) nums[i] + 1;
            int maxLen = right[i] - left[i] - 1;
            if (need <= maxLen) {
                answer = Math.min(answer, (int) need);
            }
        }
        return answer == Integer.MAX_VALUE ? -1 : answer;
    }
}

