public class Solution {
    public static int minSumSquareDiff(int[] nums1, int[] nums2, int k1, int k2) {
        final long MOD = 1_000_000_007L;
        int n = nums1.length;
        PriorityQueue<Integer> heap = new PriorityQueue<>(Collections.reverseOrder());
        for (int i = 0; i < n; ++i) {
            int diff = Math.abs(nums1[i] - nums2[i]);
            heap.offer(diff);
        }
        int ops = k1 + k2;
        while (ops-- > 0 && !heap.isEmpty()) {
            int top = heap.poll();
            if (top == 0) {
                heap.offer(0);
                break;
            }
            heap.offer(top - 1);
        }
        long ans = 0;
        for (int v : heap) {
            ans = (ans + ((long) v * v) % MOD) % MOD;
        }
        return (int) ans;
    }
}

import java.util.*;

class Solution {
    public static int[] smallestTrimmedNumbers(String[] nums, int[][] queries) {
        int n = nums.length;
        int q = queries.length;
        int maxTrim = 0;
        for (int[] query : queries) {
            maxTrim = Math.max(maxTrim, query[1]);
        }
        String[][] trimmed = new String[n][maxTrim + 1];
        for (int i = 0; i < n; i++) {
            String s = nums[i];
            int len = s.length();
            for (int t = 1; t <= maxTrim; t++) {
                trimmed[i][t] = s.substring(len - t);
            }
        }
        int[] answers = new int[q];
        for (int qi = 0; qi < q; qi++) {
            int k = queries[qi][0];
            int trim = queries[qi][1];
            Integer[] idx = new Integer[n];
            for (int i = 0; i < n; i++) idx[i] = i;
            Arrays.sort(idx, (a, b) -> {
                String sa = trimmed[a][trim];
                String sb = trimmed[b][trim];
                int cmp = compareNumeric(sa, sb);
                if (cmp != 0) return cmp;
                return a - b;
            });
            answers[qi] = idx[k - 1];
        }
        return answers;
    }

    private static int compareNumeric(String a, String b) {
        int i = 0;
        while (i < a.length() && a.charAt(i) == '0') i++;
        int j = 0;
        while (j < b.length() && b.charAt(j) == '0') j++;
        int lenA = a.length() - i;
        int lenB = b.length() - j;
        if (lenA != lenB) return lenA - lenB;
        for (int k = 0; k < lenA; k++) {
            char ca = a.charAt(i + k);
            char cb = b.charAt(j + k);
            if (ca != cb) return ca - cb;
        }
        return 0;
    }
}

import java.util.Arrays;

class Solution {
    public static int minDeletion(int[] nums, int[] numsDivide) {
        int g = numsDivide[0];
        for (int i = 1; i < numsDivide.length; i++) {
            g = gcd(g, numsDivide[i]);
        }
        Arrays.sort(nums);
        for (int i = 0; i < nums.length; i++) {
            if (i > 0 && nums[i] == nums[i - 1]) continue;
            if (g % nums[i] == 0) return i;
        }
        return -1;
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static int maxSum(int[] nums) {
        Map<Integer, int[]> best = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            int num = nums[i];
            int ds = 0;
            int x = num;
            while (x > 0) {
                ds += x % 10;
                x = x / 10;
            }
            if (!best.containsKey(ds)) {
                best.put(ds, new int[]{num, -1});
            } else {
                int[] arr = best.get(ds);
                if (num > arr[0]) {
                    arr[1] = arr[0];
                    arr[0] = num;
                } else if (num > arr[1]) {
                    arr[1] = num;
                }
            }
        }
        int answer = -1;
        for (int[] pair : best.values()) {
            if (pair[1] != -1) {
                int cur = pair[0] + pair[1];
                if (cur > answer) {
                    answer = cur;
                }
            }
        }
        return answer;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static int[] maxPairs(int[] nums) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            int v = nums[i];
            freq.put(v, freq.getOrDefault(v, 0) + 1);
        }
        int pairs = 0, leftovers = 0;
        for (int cnt : freq.values()) {
            pairs += cnt >> 1;
            leftovers += cnt & 1;
        }
        return new int[]{pairs, leftovers};
    }
}

