public class Solution {
    public static int shortestImpossibleSequence(int[] rolls, int k) {
        int n = rolls.length;
        boolean[] present = new boolean[k + 1];
        for (int r : rolls) {
            if (r >= 1 && r <= k) present[r] = true;
        }
        for (int v = 1; v <= k; v++) {
            if (!present[v]) return 1;
        }
        int[][] next = new int[n + 1][k + 1];
        for (int v = 1; v <= k; v++) next[n][v] = n;
        for (int i = n - 1; i >= 0; i--) {
            for (int v = 1; v <= k; v++) {
                next[i][v] = next[i + 1][v];
            }
            next[i][rolls[i]] = i;
        }
        long[] cur = new long[n + 1];
        cur[0] = 1;
        long power = 1;
        for (int len = 1; ; len++) {
            if (power > Long.MAX_VALUE / k) {
                power = Long.MAX_VALUE;
            } else {
                power *= k;
            }
            long[] nxt = new long[n + 1];
            for (int pos = 0; pos <= n; pos++) {
                long cnt = cur[pos];
                if (cnt == 0) continue;
                for (int v = 1; v <= k; v++) {
                    int idx = next[pos][v];
                    if (idx < n) {
                        int np = idx + 1;
                        long sum = nxt[np] + cnt;
                        nxt[np] = sum > power ? power : sum;
                    }
                }
            }
            long total = 0;
            for (long val : nxt) {
                total += val;
                if (total > power) {
                    total = power;
                    break;
                }
            }
            if (power > total) return len;
            cur = nxt;
        }
    }
}

