class NumberContainers {
    private final Map<Integer,Integer> idxToNum = new HashMap<>();
    private final Map<Integer, PriorityQueue<Integer>> numToHeap = new HashMap<>();
    public void change(int index, int number) {
        idxToNum.put(index, number);
        numToHeap.computeIfAbsent(number, k -> new PriorityQueue<>()).offer(index);
    }
    public int find(int number) {
        PriorityQueue<Integer> heap = numToHeap.get(number);
        if (heap == null) return -1;
        while (!heap.isEmpty()) {
            int top = heap.peek();
            if (idxToNum.get(top) != null && idxToNum.get(top) == number) return top;
            heap.poll();
        }
        return -1;
    }
}

