public class Solution {
    public static long countExcellentPairs(int[] nums, int k) {
        Set<Integer> unique = new HashSet<>();
        for (int num : nums) {
            unique.add(num);
        }
        int[] cnt = new int[31];
        for (int num : unique) {
            cnt[Integer.bitCount(num)]++;
        }
        int[] suffix = new int[32];
        for (int i = 30; i >= 0; i--) {
            suffix[i] = suffix[i + 1] + cnt[i];
        }
        long ans = 0;
        for (int i = 0; i <= 30; i++) {
            if (cnt[i] == 0) continue;
            int need = k - i;
            if (need < 0) need = 0;
            if (need > 30) continue;
            ans += (long) cnt[i] * suffix[need];
        }
        return ans;
    }
}

