import java.util.*;
class FoodRatings {
    static class Node {
        int rating; String food;
        Node(int rating, String food) { this.rating = rating; this.food = food; }
    }
    static class Heap {
        List<Node> data; Comparator<Node> cmp;
        Heap(Comparator<Node> cmp) { this.cmp = cmp; this.data = new ArrayList<>(); }
        Node peek() { return data.isEmpty() ? null : data.get(0); }
        void push(Node x) {
            List<Node> a = data;
            a.add(x);
            int i = a.size() - 1;
            while (i > 0) {
                int p = (i-1)>>1;
                if (cmp.compare(a.get(p), a.get(i)) <= 0) break;
                Node tmp = a.get(p); a.set(p, a.get(i)); a.set(i, tmp);
                i = p;
            }
        }
        Node pop() {
            List<Node> a = data;
            if (a.isEmpty()) return null;
            Node top = a.get(0);
            Node last = a.remove(a.size()-1);
            if (!a.isEmpty()) {
                a.set(0, last);
                int i = 0;
                while (true) {
                    int l = i*2+1, r = i*2+2, best = i;
                    if (l < a.size() && cmp.compare(a.get(best), a.get(l)) > 0) best = l;
                    if (r < a.size() && cmp.compare(a.get(best), a.get(r)) > 0) best = r;
                    if (best == i) break;
                    Node tmp = a.get(i); a.set(i, a.get(best)); a.set(best, tmp);
                    i = best;
                }
            }
            return top;
        }
    }
    private final Map<String,String> foodToCuisine = new HashMap<>();
    private final Map<String,Integer> foodToRating = new HashMap<>();
    private final Map<String,Heap> cuisineHeap = new HashMap<>();
    public FoodRatings(String[] foods, int[] ratings, String[] cuisines) {
        Comparator<Node> cmp = (a,b) -> a.rating != b.rating ? b.rating - a.rating : a.food.compareTo(b.food);
        for (int i = 0; i < foods.length; i++) {
            foodToCuisine.put(foods[i], cuisines[i]);
            foodToRating.put(foods[i], ratings[i]);
            cuisineHeap.computeIfAbsent(cuisines[i], k -> new Heap(cmp)).push(new Node(ratings[i], foods[i]));
        }
    }
    public void changeRating(String food, int newRating) {
        String c = foodToCuisine.get(food);
        foodToRating.put(food, newRating);
        cuisineHeap.get(c).push(new Node(newRating, food));
    }
    public String highestRated(String cuisine) {
        Heap heap = cuisineHeap.get(cuisine);
        while (true) {
            Node top = heap.peek();
            if (foodToRating.get(top.food) == top.rating) break;
            heap.pop();
        }
        return heap.peek().food;
    }
}

