class Solution {
    public static int findClosestNode(int[] edges, int node1, int node2) {
        int n = edges.length;
        int[] dist1 = new int[n];
        int[] dist2 = new int[n];
        Arrays.fill(dist1, Integer.MAX_VALUE);
        Arrays.fill(dist2, Integer.MAX_VALUE);
        int cur = node1;
        int d = 0;
        while (cur != -1 && dist1[cur] == Integer.MAX_VALUE) {
            dist1[cur] = d++;
            cur = edges[cur];
        }
        cur = node2;
        d = 0;
        while (cur != -1 && dist2[cur] == Integer.MAX_VALUE) {
            dist2[cur] = d++;
            cur = edges[cur];
        }
        int bestNode = -1;
        int bestDist = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            if (dist1[i] != Integer.MAX_VALUE && dist2[i] != Integer.MAX_VALUE) {
                int curMax = Math.max(dist1[i], dist2[i]);
                if (curMax < bestDist || (curMax == bestDist && i < bestNode)) {
                    bestDist = curMax;
                    bestNode = i;
                }
            }
        }
        return bestNode;
    }
}

