class Solution {
    public static int longestCycle(int[] edges) {
        int n = edges.length;
        boolean[] visited = new boolean[n];
        int best = -1;
        for (int i = 0; i < n; i++) {
            if (visited[i]) continue;
            int cur = i;
            int step = 0;
            Map<Integer, Integer> localStep = new HashMap<>();
            while (cur != -1 && !visited[cur]) {
                visited[cur] = true;
                localStep.put(cur, step);
                cur = edges[cur];
                step++;
            }
            if (cur != -1 && localStep.containsKey(cur)) {
                int cycleLen = step - localStep.get(cur);
                if (cycleLen > best) best = cycleLen;
            }
        }
        return best;
    }
}

class Solution {
    public static long minimumReplacement(int[] nums) {
        long operations = 0;
        long limit = nums[nums.length - 1];
        for (int i = nums.length - 2; i >= 0; i--) {
            long val = nums[i];
            if (val <= limit) {
                limit = val;
            } else {
                long parts = (val + limit - 1) / limit;
                operations += parts - 1;
                limit = val / parts;
            }
        }
        return operations;
    }
}

public class Solution {
    public static boolean validPartition(int[] nums) {
        int n = nums.length;
        boolean[] dp = new boolean[n + 1];
        dp[0] = true;
        for (int i = 2; i <= n; i++) {
            if (nums[i - 2] == nums[i - 1] && dp[i - 2]) {
                dp[i] = true;
            }
            if (!dp[i] && i >= 3) {
                int a = nums[i - 3];
                int b = nums[i - 2];
                int c = nums[i - 1];
                if ((a == b && b == c && dp[i - 3]) || (a + 1 == b && b + 1 == c && dp[i - 3])) {
                    dp[i] = true;
                }
            }
        }
        return dp[n];
    }
}

