class Solution {
    public static int reachableNodes(int n, int[][] edges, int[] restricted) {
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            adj[u].add(v);
            adj[v].add(u);
        }
        Set<Integer> restrictedSet = new HashSet<>();
        for (int r : restricted) {
            restrictedSet.add(r);
        }
        boolean[] visited = new boolean[n];
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(0);
        visited[0] = true;
        int reachableCount = 0;
        while (!stack.isEmpty()) {
            int node = stack.pop();
            reachableCount++;
            for (int nb : adj[node]) {
                if (!visited[nb] && !restrictedSet.contains(nb)) {
                    visited[nb] = true;
                    stack.push(nb);
                }
            }
        }
        return reachableCount;
    }
}

