class Solution {
    public static int longestIdealString(String s, int k) {
        int[] dp = new int[26];
        for (int i = 0; i < s.length(); i++) {
            int cur = s.charAt(i) - 'a';
            int best = 1;
            for (int j = 0; j < 26; j++) {
                if (Math.abs(j - cur) <= k) {
                    int candidate = dp[j] + 1;
                    if (candidate > best) {
                        best = candidate;
                    }
                }
            }
            if (best > dp[cur]) {
                dp[cur] = best;
            }
        }
        int ans = 0;
        for (int v : dp) {
            if (v > ans) {
                ans = v;
            }
        }
        return ans;
    }
}

