class Solution {
    public static int countSpecialNumbers(int n) {
        String s = Integer.toString(n);
        int len = s.length();
        long count = 0;
        for (int k = 1; k < len; k++) {
            long ways = 9;
            int available = 9;
            for (int i = 1; i < k; i++) {
                ways *= available;
                available--;
            }
            count += ways;
        }
        boolean[] used = new boolean[10];
        for (int i = 0; i < len; i++) {
            int cur = s.charAt(i) - '0';
            for (int d = (i == 0 ? 1 : 0); d < cur; d++) {
                if (used[d]) continue;
                int remaining = len - i - 1;
                long ways = 1;
                int available = 10 - (i + 1);
                for (int j = 0; j < remaining; j++) {
                    ways *= available;
                    available--;
                }
                count += ways;
            }
            if (used[cur]) {
                return (int) count;
            }
            used[cur] = true;
            if (i == len - 1) {
                count++;
            }
        }
        return (int) count;
    }
}

public class Solution {
    public static String shiftingLettersII(String s, int[][] shifts) {
        int n = s.length();
        int[] diff = new int[n + 1];
        for (int i = 0; i < shifts.length; i++) {
            int l = shifts[i][0];
            int r = shifts[i][1];
            int dir = shifts[i][2];
            int val = dir == 1 ? 1 : -1;
            diff[l] += val;
            diff[r + 1] -= val;
        }
        int cur = 0;
        StringBuilder sb = new StringBuilder(n);
        for (int i = 0; i < n; i++) {
            cur += diff[i];
            int shift = ((cur % 26) + 26) % 26;
            int code = s.charAt(i) - 'a';
            int newCode = (code + shift) % 26;
            sb.append((char) (newCode + 'a'));
        }
        return sb.toString();
    }
}

