class Solution {
    public static String largestPalindromic(String num) {
        int[] cnt = new int[10];
        for (int i = 0; i < num.length(); ++i) {
            cnt[num.charAt(i) - '0']++;
        }
        StringBuilder leftBuilder = new StringBuilder();
        for (int d = 9; d >= 0; --d) {
            int pair = cnt[d] / 2;
            if (pair > 0) {
                leftBuilder.append(String.valueOf(d).repeat(pair));
                cnt[d] -= pair * 2;
            }
        }
        String middle = "";
        for (int d = 9; d >= 0; --d) {
            if (cnt[d] > 0) {
                middle = String.valueOf(d);
                break;
            }
        }
        String left = leftBuilder.toString();
        int idx = 0;
        while (idx < left.length() && left.charAt(idx) == '0') {
            idx++;
        }
        left = left.substring(idx);
        if (left.isEmpty() && middle.isEmpty()) return "0";
        String right = new StringBuilder(left).reverse().toString();
        return left + middle + right;
    }
}

public class Solution {
    public static int minRecolors(String blocks, int k) {
        int n = blocks.length();
        if (k == 0) return 0;
        if (k > n) return 0;
        int whiteInWindow = 0;
        for (int i = 0; i < k; i++) {
            if (blocks.charAt(i) == 'W') whiteInWindow++;
        }
        int minWhite = whiteInWindow;
        for (int i = k; i < n; i++) {
            if (blocks.charAt(i - k) == 'W') whiteInWindow--;
            if (blocks.charAt(i) == 'W') whiteInWindow++;
            if (whiteInWindow < minWhite) minWhite = whiteInWindow;
        }
        return minWhite;
    }
}

import java.util.Arrays;
import java.util.PriorityQueue;

class Solution {
    public static long kthLargestSubsequenceSum(int[] nums, int k) {
        long base = 0;
        int n = nums.length;
        long[] abs = new long[n];
        for (int i = 0; i < n; i++) {
            if (nums[i] > 0) base += nums[i];
            abs[i] = Math.abs((long) nums[i]);
        }
        Arrays.sort(abs);
        PriorityQueue<Node> pq = new PriorityQueue<>();
        long[] reductions = new long[k];
        reductions[0] = 0L;
        int size = 1;
        if (n > 0) {
            pq.offer(new Node(abs[0], 0));
        }
        while (size < k && !pq.isEmpty()) {
            Node cur = pq.poll();
            reductions[size++] = cur.sum;
            int idx = cur.idx;
            if (idx + 1 < n) {
                pq.offer(new Node(cur.sum + abs[idx + 1], idx + 1));
                pq.offer(new Node(cur.sum - abs[idx] + abs[idx + 1], idx + 1));
            }
        }
        long reduction = reductions[k - 1];
        return base - reduction;
    }

    private static class Node implements Comparable<Node> {
        long sum;
        int idx;
        Node(long sum, int idx) {
            this.sum = sum;
            this.idx = idx;
        }
        public int compareTo(Node o) {
            return Long.compare(this.sum, o.sum);
        }
    }
}

