        Set<Integer> visited = new HashSet<>();
        queue.offer(start);
        visited.add(start);
        int minutes = -1;
        while (!queue.isEmpty()) {
            int size = queue.size();
            minutes++;
            for (int i = 0; i < size; i++) {
