class Solution {
    public static int[] longestSubsequenceWithLimitedSum(int[] nums, int[] queries) {
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        long[] pref = new long[sorted.length];
        for (int i = 0; i < sorted.length; i++) {
            pref[i] = (i > 0 ? pref[i - 1] : 0) + sorted[i];
        }
        int[] answer = new int[queries.length];
        for (int idx = 0; idx < queries.length; idx++) {
            int q = queries[idx];
            int lo = 0, hi = sorted.length - 1, best = -1;
            while (lo <= hi) {
                int mid = (lo + hi) >>> 1;
                if (pref[mid] <= q) {
                    best = mid;
                    lo = mid + 1;
                } else {
                    hi = mid - 1;
                }
            }
            answer[idx] = best + 1;
        }
        return answer;
    }
}

import java.util.*;

class Solution {
    public static int[][] buildMatrix(int k, int[][] rowConditions, int[][] colConditions) {
        int[] rowOrder = topoSort(k, rowConditions);
        int[] colOrder = topoSort(k, colConditions);
        if (rowOrder == null || colOrder == null) {
            return new int[0][0];
        }
        int[] rowPos = new int[k + 1];
        int[] colPos = new int[k + 1];
        for (int i = 0; i < k; i++) {
            rowPos[rowOrder[i]] = i;
            colPos[colOrder[i]] = i;
        }
        int[][] ans = new int[k][k];
        for (int v = 1; v <= k; v++) {
            ans[rowPos[v]][colPos[v]] = v;
        }
        return ans;
    }

    private static int[] topoSort(int k, int[][] edges) {
        List<Integer>[] adj = new ArrayList[k + 1];
        for (int i = 0; i <= k; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
        }
        int[] state = new int[k + 1];
        List<Integer> order = new ArrayList<>(k);
        for (int i = 1; i <= k; i++) {
            if (state[i] == 0) {
                if (!dfs(i, adj, state, order)) {
                    return null;
                }
            }
        }
        Collections.reverse(order);
        int[] res = new int[k];
        for (int i = 0; i < k; i++) {
            res[i] = order.get(i);
        }
        return res;
    }

    private static boolean dfs(int u, List<Integer>[] adj, int[] state, List<Integer> order) {
        state[u] = 1;
        for (int v : adj[u]) {
            if (state[v] == 1) {
                return false;
            }
            if (state[v] == 0) {
                if (!dfs(v, adj, state, order)) {
                    return false;
                }
            }
        }
        state[u] = 2;
        order.add(u);
        return true;
    }
}

