class Solution {
    public static int maxRowsCovered(int[][] matrix, int numSelect) {
        int m = matrix.length;
        if (m == 0) return 0;
        int n = matrix[0].length;
        if (numSelect > n) return 0;
        int size = 1 << n;
        int[] freq = new int[size];
        for (int[] row : matrix) {
            int mask = 0;
            for (int j = 0; j < n; j++) {
                if (row[j] == 1) {
                    mask |= 1 << j;
                }
            }
            freq[mask]++;
        }
        int[] dp = freq.clone();
        for (int i = 0; i < n; i++) {
            int bit = 1 << i;
            for (int mask = 0; mask < size; mask++) {
                if ((mask & bit) != 0) {
                    dp[mask] += dp[mask ^ bit];
                }
            }
        }
        int best = 0;
        for (int mask = 0; mask < size; mask++) {
            if (Integer.bitCount(mask) == numSelect) {
                if (dp[mask] > best) best = dp[mask];
            }
        }
        return best;
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public static int maxRobots(int[] chargeTimes, int[] runningCosts, long budget) {
        int n = chargeTimes.length;
        int left = 0;
        long sumRun = 0;
        int best = 0;
        Deque<Integer> deque = new ArrayDeque<>();

        for (int right = 0; right < n; right++) {
            sumRun += runningCosts[right];

            while (!deque.isEmpty() && chargeTimes[right] >= chargeTimes[deque.peekLast()]) {
                deque.pollLast();
            }
            deque.addLast(right);

            while (left <= right) {
                int maxCharge = chargeTimes[deque.peekFirst()];
                int windowSize = right - left + 1;
                long cost = maxCharge + (long) windowSize * sumRun;
                if (cost <= budget) {
                    break;
                }
                if (deque.peekFirst() == left) {
                    deque.pollFirst();
                }
                sumRun -= runningCosts[left];
                left++;
            }

            best = Math.max(best, right - left + 1);
        }
        return best;
    }
}

import java.lang.*;

class Solution {
    private static final long MOD = 1_000_000_007L;

    public static int numberOfWays(int startPos, int endPos, int k) {
        int distance = Math.abs(endPos - startPos);
        if (distance > k || ((k - distance) & 1) == 1) {
            return 0;
        }
        int rightMoves = (k + distance) / 2;
        long factK = factorial(k);
        long factR = factorial(rightMoves);
        long factKMinusR = factorial(k - rightMoves);
        long result = factK;
        result = result * modPow(factR, MOD - 2) % MOD;
        result = result * modPow(factKMinusR, MOD - 2) % MOD;
        return (int) result;
    }

    private static long factorial(int n) {
        long res = 1;
        for (int i = 2; i <= n; i++) {
            res = res * i % MOD;
        }
        return res;
    }

    private static long modPow(long base, long exp) {
        long result = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = result * base % MOD;
            }
            base = base * base % MOD;
            exp >>= 1;
        }
        return result;
    }
}

