class Solution {
    public static int tilingRectangle(int n, int m) {
        if (n == m) return 1;
        if (n > m) {
            int tmp = n;
            n = m;
            m = tmp;
        }
        int[] heights = new int[n];
        int[] best = new int[]{n * m};
        dfs(heights, m, 0, best);
        return best[0];
    }

    private static void dfs(int[] heights, int totalHeight, int used, int[] best) {
        if (used >= best[0]) return;
        int minHeight = Integer.MAX_VALUE;
        int idx = -1;
        for (int i = 0; i < heights.length; i++) {
            if (heights[i] < minHeight) {
                minHeight = heights[i];
                idx = i;
            }
        }
        if (minHeight == totalHeight) {
            best[0] = used;
            return;
        }
        int maxSize = Math.min(heights.length - idx, totalHeight - minHeight);
        int size = 0;
        for (int s = 1; s <= maxSize; s++) {
            boolean ok = true;
            for (int k = idx; k < idx + s; k++) {
                if (heights[k] != minHeight) {
                    ok = false;
                    break;
                }
            }
            if (!ok) break;
            size = s;
        }
        for (int s = size; s >= 1; s--) {
            for (int k = idx; k < idx + s; k++) heights[k] += s;
            dfs(heights, totalHeight, used + 1, best);
            for (int k = idx; k < idx + s; k++) heights[k] -= s;
        }
    }
}

