class Solution {
    public static int[][] reconstructMatrix(int upper, int lower, int[] colsum) {
        int n = colsum.length;
        int[][] matrix = new int[2][n];
        int upperSum = upper;
        int lowerSum = lower;
        for (int i = 0; i < n; i++) {
            if (colsum[i] == 2) {
                matrix[0][i] = 1;
                matrix[1][i] = 1;
                upperSum--;
                lowerSum--;
                if (upperSum < 0 || lowerSum < 0) {
                    return new int[0][];
                }
            }
        }
        for (int i = 0; i < n; i++) {
            if (colsum[i] == 1) {
                if (upperSum > 0) {
                    matrix[0][i] = 1;
                    upperSum--;
                } else if (lowerSum > 0) {
                    matrix[1][i] = 1;
                    lowerSum--;
                } else {
                    return new int[0][];
                }
            }
        }
        if (upperSum != 0 || lowerSum != 0) {
            return new int[0][];
        }
        return matrix;
    }
}

