class Solution {
    public static int[] smallestSubarraysWithMaximumBitwiseOR(int[] nums) {
        int n = nums.length;
        int[] answer = new int[n];
        for (int i = 0; i < n; i++) {
            int maxBitwiseOR = 0;
            for (int j = i; j < n; j++) {
                int[] slice = Arrays.copyOfRange(nums, i, j + 1);
                int bitwiseOR = calculateBitwiseOR(slice);
                if (bitwiseOR > maxBitwiseOR) {
                    maxBitwiseOR = bitwiseOR;
                    answer[i] = j - i + 1;
                }
            }
        }
        return answer;
    }

    private static int calculateBitwiseOR(int[] subarray) {
        int bitwiseOR = 0;
        for (int num : subarray) {
            bitwiseOR |= num;
        }
        return bitwiseOR;
    }
}

