class Solution {
    public static int minTrainingHours(int initialEnergy, int initialExperience, int[] energy, int[] experience) {
        int trainingHours = 0;
        int curEnergy = initialEnergy;
        int curExp = initialExperience;
        for (int i = 0; i < energy.length; i++) {
            if (curEnergy <= energy[i]) {
                int addEnergy = energy[i] - curEnergy + 1;
                trainingHours += addEnergy;
                curEnergy += addEnergy;
            }
            if (curExp <= experience[i]) {
                int addExp = experience[i] - curExp + 1;
                trainingHours += addExp;
                curExp += addExp;
            }
            curEnergy -= energy[i];
            curExp += experience[i];
        }
        return trainingHours;
    }
