class Solution {
    public static long[] maximumSegmentSum(int[] nums, int[] removeQueries) {
        int n = nums.length;
        int[] parent = new int[n];
        Arrays.fill(parent, -1);
        long[] segSum = new long[n];
        boolean[] added = new boolean[n];
        long[] answer = new long[n];
        long curMax = 0;

        for (int i = n - 1; i >= 0; i--) {
            answer[i] = curMax;
            int idx = removeQueries[i];
            added[idx] = true;
            parent[idx] = idx;
            segSum[idx] = nums[idx];

            if (idx > 0 && added[idx - 1]) {
                curMax = Math.max(curMax, union(idx, idx - 1, parent, segSum));
            }
            if (idx + 1 < n && added[idx + 1]) {
                curMax = Math.max(curMax, union(idx, idx + 1, parent, segSum));
            }
            curMax = Math.max(curMax, segSum[find(idx, parent)]);
        }

        return answer;
    }

    private static int find(int x, int[] parent) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    private static long union(int a, int b, int[] parent, long[] segSum) {
        int ra = find(a, parent);
        int rb = find(b, parent);
        if (ra == rb) {
            return segSum[ra];
        }
        parent[rb] = ra;
        segSum[ra] += segSum[rb];
        return segSum[ra];
    }
}

