class Solution {
    public static boolean canEqualizeWord(String word) {
        Map<Character, Integer> charFreq = new HashMap<>();
        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);
            charFreq.put(c, charFreq.getOrDefault(c, 0) + 1);
        }
        Map<Integer, Integer> freqCount = new HashMap<>();
        for (int f : charFreq.values()) {
            freqCount.put(f, freqCount.getOrDefault(f, 0) + 1);
        }
        if (freqCount.size() == 1) {
            int freq = freqCount.keySet().iterator().next();
            if (freq == 1) return true;
            if (freqCount.get(freq) == 1) return true;
            return false;
        }
        if (freqCount.size() > 2) return false;
        List<Integer> freqs = new ArrayList<>(freqCount.keySet());
        Collections.sort(freqs);
        int low = freqs.get(0);
        int high = freqs.get(1);
        int countLow = freqCount.get(low);
        int countHigh = freqCount.get(high);
        if (low == 1 && countLow == 1) return true;
        if (high - low == 1 && countHigh == 1) return true;
        return false;
    }
}

