class Solution {
    public static long numberOfGoodPaths(int[] vals, int[][] edges) {
        int n = vals.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }

        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, Comparator.comparingInt(i -> vals[i]));

        int[] parent = new int[n];
        int[] size = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            size[i] = 1;
        }

        long ans = n;
        int idx = 0;
        while (idx < n) {
            int curVal = vals[order[idx]];
            int j = idx;
            while (j < n && vals[order[j]] == curVal) {
                int node = order[j];
                for (int nb : graph[node]) {
                    if (vals[nb] <= curVal) {
                        union(node, nb, parent, size);
                    }
                }
                j++;
            }
            Map<Integer, Integer> compCount = new HashMap<>();
            for (int k = idx; k < j; k++) {
                int root = find(order[k], parent);
                compCount.merge(root, 1, Integer::sum);
            }
            for (int cnt : compCount.values()) {
                ans += (long) cnt * (cnt - 1) / 2;
            }
            idx = j;
        }
        return ans;
    }

    private static int find(int x, int[] parent) {
        if (parent[x] != x) parent[x] = find(parent[x], parent);
        return parent[x];
    }

    private static void union(int a, int b, int[] parent, int[] size) {
        int ra = find(a, parent);
        int rb = find(b, parent);
        if (ra == rb) return;
        if (size[ra] < size[rb]) {
            int tmp = ra;
            ra = rb;
            rb = tmp;
        }
        parent[rb] = ra;
        size[ra] += size[rb];
    }
}

