public class Solution {
    public static long minimizeXor(long num1, long num2) {
        int setBitsInNum2 = countSetBits(num2);
        int setBitsInNum1 = countSetBits(num1);
        if (setBitsInNum1 == setBitsInNum2) return num1;
        return smallestNumberWithSetBits(setBitsInNum2);
    }

    private static int countSetBits(long n) {
        int count = 0;
        while (n != 0) {
            count++;
            n &= (n - 1);
        }
        return count;
    }

    private static long smallestNumberWithSetBits(int k) {
        if (k == 0) return 0L;
        return (1L << k) - 1L;
    }
}

