class Solution {
    public static int deleteString(String s) {
        int n = s.length();
        char[] a = s.toCharArray();
        final int MOD1 = 1_000_000_007;
        final int MOD2 = 1_000_000_009;
        final int BASE = 91138233 % MOD1;

        int[] pow1 = new int[n + 1];
        int[] pow2 = new int[n + 1];
        int[] pref1 = new int[n + 1];
        int[] pref2 = new int[n + 1];
        pow1[0] = 1;
        pow2[0] = 1;
        for (int i = 0; i < n; i++) {
            pow1[i + 1] = (int) ((long) pow1[i] * BASE % MOD1);
            pow2[i + 1] = (int) ((long) pow2[i] * BASE % MOD2);
            int val = a[i] - 'a' + 1;
            pref1[i + 1] = (int) (((long) pref1[i] * BASE + val) % MOD1);
            pref2[i + 1] = (int) (((long) pref2[i] * BASE + val) % MOD2);
        }

        // helper lambda for hash equality
        java.util.function.BiPredicate<Integer, Integer> equal = (len, start) -> {
            int l1 = start;
            int l2 = start + len;
            int r1 = start + len;
            int r2 = start + 2 * len;
            long h1a = (pref1[r1] - (long) pref1[l1] * pow1[r1 - l1]) % MOD1;
            if (h1a < 0) h1a += MOD1;
            long h1b = (pref1[r2] - (long) pref1[l2] * pow1[r2 - l2]) % MOD1;
            if (h1b < 0) h1b += MOD1;
            if (h1a != h1b) return false;
            long h2a = (pref2[r1] - (long) pref2[l1] * pow2[r1 - l1]) % MOD2;
            if (h2a < 0) h2a += MOD2;
            long h2b = (pref2[r2] - (long) pref2[l2] * pow2[r2 - l2]) % MOD2;
            if (h2b < 0) h2b += MOD2;
            return h2a == h2b;
        };

        int[] dp = new int[n + 1];
        dp[n] = 0;
        for (int i = n - 1; i >= 0; i--) {
            int best = 1; // delete all remaining in one operation
            int maxLen = (n - i) / 2;
            for (int len = 1; len <= maxLen; len++) {
                if (equal.test(len, i)) {
                    best = Math.max(best, 1 + dp[i + len]);
                }
            }
            dp[i] = best;
        }
        return dp[0];
    }
}

