import java.util.*;

class Solution {
    private static final long MOD = 1_000_000_007L;

    public static long[] productQueries(int n, int[][] queries) {
        List<Long> powers = new ArrayList<>();
        int bit = 0;
        int temp = n;
        while (temp > 0) {
            if ((temp & 1) == 1) {
                powers.add(1L << bit);
            }
            temp >>= 1;
            bit++;
        }
        int m = powers.size();
        long[] pref = new long[m + 1];
        pref[0] = 1;
        for (int i = 0; i < m; i++) {
            pref[i + 1] = (pref[i] * (powers.get(i) % MOD)) % MOD;
        }
        long[] invPref = new long[m + 1];
        for (int i = 0; i <= m; i++) {
            invPref[i] = modPow(pref[i], MOD - 2);
        }
        long[] result = new long[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int l = queries[i][0];
            int r = queries[i][1];
            result[i] = (pref[r + 1] * invPref[l]) % MOD;
        }
        return result;
    }

    private static long modPow(long base, long exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }
}

