public class Solution {
    public static long countSubarrays(int[] nums, int minK, int maxK) {
        long result = 0;
        int left = 0;
        int lastMin = -1;
        int lastMax = -1;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] < minK || nums[i] > maxK) {
                left = i + 1;
                lastMin = -1;
                lastMax = -1;
                continue;
            }
            if (nums[i] == minK) {
                lastMin = i;
            }
            if (nums[i] == maxK) {
                lastMax = i;
            }
            int validStart = Math.min(lastMin, lastMax);
            if (validStart >= left) {
                result += (long) (validStart - left + 1);
            }
        }
        return result;
    }
}

