class Solution {
    public static int componentValue(int[] nums, int[][] edges) {
        int n = nums.length;
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }
        long total = 0;
        for (int v : nums) total += v;
        if (total == 0) return n - 1;
        int maxEdges = 0;
        List<Long> divisors = new ArrayList<>();
        for (long d = 1; d * d <= total; d++) {
            if (total % d == 0) {
                divisors.add(d);
                if (d != total / d) divisors.add(total / d);
            }
        }
        for (long target : divisors) {
            int components = (int) (total / target);
            if (components <= 1) continue;
            int[] count = new int[1];
            long leftover = dfs(0, -1, adj, nums, target, count);
            if (leftover == 0) {
                maxEdges = Math.max(maxEdges, components - 1);
            }
        }
        return maxEdges;
    }

    private static long dfs(int node, int parent, List<Integer>[] adj, int[] nums, long target, int[] count) {
        long sum = nums[node];
        for (int nb : adj[node]) {
            if (nb == parent) continue;
            long childSum = dfs(nb, node, adj, nums, target, count);
            if (childSum == -1) return -1;
            sum += childSum;
        }
        if (sum > target) return -1;
        if (sum == target) {
            count[0]++;
            return 0;
        }
        return sum;
    }
}

