class Solution {
    public static long minCost(int[] nums, int[] cost) {
        int n = nums.length;
        long[][] pairs = new long[n][2];
        for (int i = 0; i < n; i++) {
            pairs[i][0] = nums[i];
            pairs[i][1] = cost[i];
        }
        Arrays.sort(pairs, Comparator.comparingLong(a -> a[0]));
        long totalWeight = 0;
        for (int i = 0; i < n; i++) {
            totalWeight += pairs[i][1];
        }
        long half = (totalWeight + 1) / 2;
        long cumulative = 0;
        long median = 0;
        for (int i = 0; i < n; i++) {
            cumulative += pairs[i][1];
            if (cumulative >= half) {
                median = pairs[i][0];
                break;
            }
        }
        long result = 0;
        for (int i = 0; i < n; i++) {
            result += Math.abs(pairs[i][0] - median) * pairs[i][1];
        }
        return result;
    }
}

