class Solution {
    private static final long MOD = 1_000_000_007L;

    public static int pathsDivisible(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;
        int[][] dpPrev = new int[n][k];

        for (int i = 0; i < m; i++) {
            int[][] dpCurr = new int[n][k];
            for (int j = 0; j < n; j++) {
                int valMod = grid[i][j] % k;
                int[] cur = dpCurr[j];

                if (i == 0 && j == 0) {
                    cur[valMod] = 1;
                    continue;
                }

                if (i > 0) {
                    int[] top = dpPrev[j];
                    for (int r = 0; r < k; r++) {
                        int cnt = top[r];
                        if (cnt != 0) {
                            int nr = (r + valMod) % k;
                            cur[nr] = (int) ((cur[nr] + (long) cnt) % MOD);
                        }
                    }
                }

                if (j > 0) {
                    int[] left = dpCurr[j - 1];
                    for (int r = 0; r < k; r++) {
                        int cnt = left[r];
                        if (cnt != 0) {
                            int nr = (r + valMod) % k;
                            cur[nr] = (int) ((cur[nr] + (long) cnt) % MOD);
                        }
                    }
                }
            }
            dpPrev = dpCurr;
        }

        return dpPrev[n - 1][0];
    }
}

