class Solution {
    public static String robotPrint(String s) {
        int n = s.length();
        char[] minSuffix = new char[n];
        for (int i = n - 1; i >= 0; i--) {
            if (i == n - 1) {
                minSuffix[i] = s.charAt(i);
            } else {
                char c = s.charAt(i);
                minSuffix[i] = c < minSuffix[i + 1] ? c : minSuffix[i + 1];
            }
        }
        char[] stack = new char[n];
        int top = 0;
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < n; i++) {
            stack[top++] = s.charAt(i);
            while (top > 0 && (i == n - 1 || stack[top - 1] <= minSuffix[i + 1])) {
                result.append(stack[--top]);
            }
        }
        while (top > 0) {
            result.append(stack[--top]);
        }
        return result.toString();
    }
}

