            this.views = views;
        }
    }

    public static List<List<String>> mostPopularCreator(String[] creators, String[] ids, int[] views) {
        Map<String, Long> creatorViews = new HashMap<>();
        for (int i = 0; i < creators.length; i++) {
            creatorViews.put(creators[i], creatorViews.getOrDefault(creators[i], 0L) + views[i]);
        }

        long maxViews = Long.MIN_VALUE;
        for (long v : creatorViews.values()) {
            if (v > maxViews) maxViews = v;
        }

        Map<String, VideoInfo> mostViewedVideos = new HashMap<>();
        for (int i = 0; i < creators.length; i++) {
            if (creatorViews.get(creators[i]) == maxViews) {
                VideoInfo current = mostViewedVideos.get(creators[i]);
                if (current == null) {
                    mostViewedVideos.put(creators[i], new VideoInfo(ids[i], views[i]));
                } else if (views[i] > current.views) {
                    mostViewedVideos.put(creators[i], new VideoInfo(ids[i], views[i]));
                } else if (views[i] == current.views && ids[i].compareTo(current.id) < 0) {
                    mostViewedVideos.put(creators[i], new VideoInfo(ids[i], views[i]));
                }
            }
        }

        List<String> creatorsWithMax = new ArrayList<>(mostViewedVideos.keySet());
        Collections.sort(creatorsWithMax);
        List<List<String>> result = new ArrayList<>();
        for (String creator : creatorsWithMax) {
            VideoInfo vi = mostViewedVideos.get(creator);
            List<String> pair = new ArrayList<>(2);
            pair.add(creator);
            pair.add(vi.id);
            result.add(pair);
        }
        return result;
    }
}

