class Solution {
    public static int destroyTargets(int[] nums, int space) {
        Map<Integer, Integer> countMap = new HashMap<>();
        Map<Integer, Integer> minMap = new HashMap<>();
        for (int num : nums) {
            int seed = num % space;
            countMap.put(seed, countMap.getOrDefault(seed, 0) + 1);
            minMap.put(seed, Math.min(minMap.getOrDefault(seed, Integer.MAX_VALUE), num));
        }
        int maxCount = 0;
        int answer = Integer.MAX_VALUE;
        for (Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
            int seed = entry.getKey();
            int cnt = entry.getValue();
            int curMin = minMap.get(seed);
            if (cnt > maxCount) {
                maxCount = cnt;
                answer = curMin;
            } else if (cnt == maxCount && curMin < answer) {
                answer = curMin;
            }
        }
        return answer;
    }
}

