class Solution {
    public static int[] treeQueries(TreeNode root, int[] queries) {
        Map<Integer, Integer> parentMap = new HashMap<>();
        Map<Integer, Integer> depthMap = new HashMap<>();
        List<int[]> leaves = new ArrayList<>(); // {val, depth}

        buildInfo(root, null, 0, parentMap, depthMap, leaves);

        int[] result = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int q = queries[i];
            int best = 0;
            for (int[] leaf : leaves) {
                if (!isDescendantOrSelf(leaf[0], q, parentMap)) {
                    best = Math.max(best, leaf[1]);
                }
            }
            result[i] = best;
        }
        return result;
    }

    private static boolean isDescendantOrSelf(int node, int ancestor, Map<Integer, Integer> parentMap) {
        while (true) {
            if (node == ancestor) return true;
            Integer p = parentMap.get(node);
            if (p == null) return false;
            node = p;
        }
    }

    private static void buildInfo(TreeNode node, Integer parentVal, int depth,
                                   Map<Integer, Integer> parentMap,
                                   Map<Integer, Integer> depthMap,
                                   List<int[]> leaves) {
        if (node == null) return;
        parentMap.put(node.val, parentVal);
        depthMap.put(node.val, depth);
        if (node.left == null && node.right == null) {
            leaves.add(new int[]{node.val, depth});
            return;
        }
        buildInfo(node.left, node.val, depth + 1, parentMap, depthMap, leaves);
        buildInfo(node.right, node.val, depth + 1, parentMap, depthMap, leaves);
    }
}

