class Solution {
    public static long mostProfitablePath(int[][] edges, int bob, int[] amount) {
        int n = amount.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0], v = e[1];
            graph[u].add(v);
            graph[v].add(u);
        }

        int[] parent = new int[n];
        int[] depth = new int[n];
        Arrays.fill(parent, -1);
        Queue<Integer> q = new ArrayDeque<>();
        q.add(0);
        parent[0] = 0;
        depth[0] = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : graph[u]) {
                if (parent[v] == -1) {
                    parent[v] = u;
                    depth[v] = depth[u] + 1;
                    q.add(v);
                }
            }
        }

        int INF = 1_000_000_000;
        int[] bobDist = new int[n];
        Arrays.fill(bobDist, INF);
        int cur = bob;
        int d = 0;
        while (true) {
            bobDist[cur] = d;
            if (cur == 0) break;
            cur = parent[cur];
            d++;
        }

        long answer = Long.MIN_VALUE;
        Deque<State> stack = new ArrayDeque<>();
        stack.push(new State(0, -1, 0L));

        while (!stack.isEmpty()) {
            State s = stack.pop();
            int u = s.node;
            long sum = s.sum;

            if (depth[u] < bobDist[u]) {
                sum += amount[u];
            } else if (depth[u] == bobDist[u]) {
                sum += amount[u] / 2;
            }

            boolean isLeaf = (u == 0 ? graph[u].isEmpty() : graph[u].size() == 1);
            if (isLeaf) {
                answer = Math.max(answer, sum);
            }

            for (int v : graph[u]) {
                if (v == s.parent) continue;
                stack.push(new State(v, u, sum));
            }
        }

        return answer;
    }

    private static class State {
        int node;
        int parent;
        long sum;
        State(int node, int parent, long sum) {
            this.node = node;
            this.parent = parent;
            this.sum = sum;
        }
    }
}

