class Solution {
    public static ListNode removeNodes(ListNode head) {
        ListNode prev = null;
        ListNode cur = head;
        while (cur != null) {
            ListNode nxt = cur.next;
            cur.next = prev;
            prev = cur;
            cur = nxt;
        }
        int maxSoFar = Integer.MIN_VALUE;
        ListNode newHead = null;
        cur = prev;
        while (cur != null) {
            ListNode nxt = cur.next;
            if (cur.val >= maxSoFar) {
                maxSoFar = cur.val;
                cur.next = newHead;
                newHead = cur;
            }
            cur = nxt;
        }
        return newHead;
    }
}

