class Solution {
    public static int minimumPenalty(String customers) {
        int n = customers.length();
        int totalY = 0;
        for (int i = 0; i < n; i++) {
            if (customers.charAt(i) == 'Y') totalY++;
        }
        int prefixN = 0;
        int suffixY = totalY;
        int minPenalty = Integer.MAX_VALUE;
        int minIndex = 0;
        for (int i = 0; i <= n; i++) {
            int penalty = prefixN + suffixY;
            if (penalty < minPenalty) {
                minPenalty = penalty;
                minIndex = i;
            }
            if (i < n) {
                char c = customers.charAt(i);
                if (c == 'Y') {
                    suffixY--;
                } else {
                    prefixN++;
                }
            }
        }
        return minIndex;
    }
}

