class Solution {
    public static int magnificentSets(int n, List<List<Integer>> edges) {
        List<Integer>[] adj = new ArrayList[n + 1];
        for (int i = 0; i <= n; i++) adj[i] = new ArrayList<>();
        for (List<Integer> e : edges) {
            int u = e.get(0), v = e.get(1);
            adj[u].add(v);
            adj[v].add(u);
        }

        boolean[] visited = new boolean[n + 1];
        int[] color = new int[n + 1];
        Arrays.fill(color, -1);
        int totalGroups = 0;

        for (int i = 1; i <= n; i++) {
            if (visited[i]) continue;

            List<Integer> component = new ArrayList<>();
            ArrayDeque<Integer> queue = new ArrayDeque<>();
            queue.add(i);
            visited[i] = true;
            color[i] = 0;
            component.add(i);

            int[] dist = new int[n + 1];
            Arrays.fill(dist, -1);
            dist[i] = 0;
            boolean bipartite = true;
            int farNode = i;
            int maxDist = 0;

            while (!queue.isEmpty()) {
                int u = queue.poll();
                for (int v : adj[u]) {
                    if (!visited[v]) {
                        visited[v] = true;
                        color[v] = color[u] ^ 1;
                        dist[v] = dist[u] + 1;
                        queue.add(v);
                        component.add(v);
                        if (dist[v] > maxDist) {
                            maxDist = dist[v];
                            farNode = v;
                        }
                    } else if (color[v] == color[u]) {
                        bipartite = false;
                    }
                }
            }

            if (!bipartite) return -1;

            int[] dist2 = new int[n + 1];
            for (int node : component) dist2[node] = -1;
            ArrayDeque<Integer> q2 = new ArrayDeque<>();
            q2.add(farNode);
            dist2[farNode] = 0;
            int diameter = 0;

            while (!q2.isEmpty()) {
                int u = q2.poll();
                for (int v : adj[u]) {
                    if (dist2[v] == -1) {
                        dist2[v] = dist2[u] + 1;
                        q2.add(v);
                        if (dist2[v] > diameter) diameter = dist2[v];
                    }
                }
            }

            totalGroups += diameter + 1;
        }

        return totalGroups;
    }
}

