class Solution {
    public static long dividePlayers(int[] skill) {
        int n = skill.length;
        if (n % 2 != 0) {
            return -1;
        }
        Arrays.sort(skill);
        long target = (long) skill[0] + skill[n - 1];
        long chemistrySum = 0;
        for (int i = 0; i < n / 2; i++) {
            int a = skill[i];
            int b = skill[n - 1 - i];
            if ((long) a + b != target) {
                return -1;
            }
            chemistrySum += (long) a * b;
        }
        return chemistrySum;
    }
}

