public class Solution {
    public static int longestSquareStreak(int[] nums) {
        Set<Integer> present = new HashSet<>();
        for (int n : nums) {
            present.add(n);
        }
        Map<Integer, Integer> memo = new HashMap<>();
        int best = 0;
        for (int v : present) {
            best = Math.max(best, chainLen(v, present, memo));
        }
        return best >= 2 ? best : -1;
    }

    private static int chainLen(int x, Set<Integer> present, Map<Integer, Integer> memo) {
        if (!present.contains(x)) return 0;
        if (memo.containsKey(x)) return memo.get(x);
        int next = x * x;
        int len = 1;
        if (present.contains(next)) {
            len = 1 + chainLen(next, present, memo);
        }
        memo.put(x, len);
        return len;
    }
}

import java.util.PriorityQueue;

class Solution {
    public static long totalCost(int[] costs, int k, int candidates) {
        long total = 0;
        int n = costs.length;
        int leftIdx = 0;
        int rightIdx = n - 1;
        PriorityQueue<Integer> leftPQ = new PriorityQueue<>();
        PriorityQueue<Integer> rightPQ = new PriorityQueue<>();

        int leftLimit = Math.min(candidates, n);
        for (; leftIdx < leftLimit; leftIdx++) {
            leftPQ.add(costs[leftIdx]);
        }

        int rightLimit = Math.max(n - candidates, leftIdx);
        for (; rightIdx >= rightLimit; rightIdx--) {
            rightPQ.add(costs[rightIdx]);
        }

        for (int hired = 0; hired < k; hired++) {
            if (rightPQ.isEmpty() || (!leftPQ.isEmpty() && leftPQ.peek() <= rightPQ.peek())) {
                total += leftPQ.poll();
                if (leftIdx <= rightIdx) {
                    leftPQ.add(costs[leftIdx++]);
                }
            } else {
                total += rightPQ.poll();
                if (leftIdx <= rightIdx) {
                    rightPQ.add(costs[rightIdx--]);
                }
            }
        }
        return total;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Stack;

class Solution {
    public static int minScore(int n, int[][] roads) {
        List<int[]>[] adj = new ArrayList[n + 1];
        for (int i = 0; i <= n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int[] road : roads) {
            int a = road[0];
            int b = road[1];
            int w = road[2];
            adj[a].add(new int[]{b, w});
            adj[b].add(new int[]{a, w});
        }
        boolean[] visited = new boolean[n + 1];
        Stack<Integer> stack = new Stack<>();
        stack.push(1);
        visited[1] = true;
        int best = Integer.MAX_VALUE;
        while (!stack.isEmpty()) {
            int v = stack.pop();
            for (int[] edge : adj[v]) {
                int to = edge[0];
                int w = edge[1];
                if (w < best) {
                    best = w;
                }
                if (!visited[to]) {
                    visited[to] = true;
                    stack.push(to);
                }
            }
        }
        return best;
    }
}

