class Solution {
    public static long minimumTotalCost(int[] nums1, int[] nums2) {
        int n = nums1.length;
        Map<Integer, Integer> count1 = new HashMap<>();
        Map<Integer, Integer> count2 = new HashMap<>();
        for (int v : nums1) count1.merge(v, 1, Integer::sum);
        for (int v : nums2) count2.merge(v, 1, Integer::sum);
        for (Map.Entry<Integer, Integer> e : count1.entrySet()) {
            int v = e.getKey();
            int c1 = e.getValue();
            int c2 = count2.getOrDefault(v, 0);
            if (c1 > n - c2) return -1;
        }
        return (long) n * (n - 1) / 2;
    }
}

public class Solution {
    public static int minimumCost(int[] stones) {
        int n = stones.length;
        if (n <= 2) {
            return stones[n - 1] - stones[0];
        }
        int maxGap = 0;
        for (int i = 0; i + 2 < n; i++) {
