class Solution {
    public static int deleteGreatestValue(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        for (int i = 0; i < m; i++) {
            Arrays.sort(grid[i]);
            for (int l = 0, r = n - 1; l < r; l++, r--) {
                int tmp = grid[i][l];
                grid[i][l] = grid[i][r];
                grid[i][r] = tmp;
            }
        }
        int answer = 0;
        for (int col = 0; col < n; col++) {
            int colMax = 0;
            for (int row = 0; row < m; row++) {
                if (grid[row][col] > colMax) {
                    colMax = grid[row][col];
                }
            }
            answer += colMax;
        }
        return answer;
    }
}

