import java.util.*;
class MemoryAllocator {
    static class Interval implements Comparable<Interval> {
        int start, end;
        Interval(int s, int e) { start = s; end = e; }
        public int compareTo(Interval o) { return Integer.compare(start, o.start); }
    }
    private final TreeSet<Interval> intervals = new TreeSet<>();
    private final Map<Integer, List<int[]>> allocations = new HashMap<>();
    public MemoryAllocator(int n) { intervals.add(new Interval(0, n-1)); }
    public int allocate(int size, int mID) {
        for (Interval iv : intervals) {
            int length = iv.end - iv.start + 1;
            if (length >= size) {
                int allocStart = iv.start;
                intervals.remove(iv);
                if (length > size) intervals.add(new Interval(iv.start + size, iv.end));
                allocations.computeIfAbsent(mID, k -> new ArrayList<>()).add(new int[]{allocStart, size});
                return allocStart;
            }
        }
        return -1;
    }
    private void freeInterval(int start, int size) {
        int newStart = start, newEnd = start + size - 1;
        Interval probe = new Interval(newStart, 0);
        Interval lower = intervals.lower(probe);
        if (lower != null && lower.end + 1 >= newStart) {
            newStart = Math.min(newStart, lower.start);
            newEnd = Math.max(newEnd, lower.end);
            intervals.remove(lower);
        }
        Interval cur;
        while ((cur = intervals.ceiling(new Interval(newStart, 0))) != null && cur.start <= newEnd + 1) {
            newEnd = Math.max(newEnd, cur.end);
            intervals.remove(cur);
        }
        intervals.add(new Interval(newStart, newEnd));
    }
    public int free(int mID) {
        List<int[]> blocks = allocations.remove(mID);
        if (blocks == null) return 0;
        int freed = 0;
        for (int[] b : blocks) { freeInterval(b[0], b[1]); freed += b[1]; }
        return freed;
    }
}

import java.util.*;

class Solution {
    public static boolean isPossible(int n, int[][] edges) {
        int[] degree = new int[n + 1];
        Set<Long> edgeSet = new HashSet<>();
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            degree[u]++;
            degree[v]++;
            edgeSet.add(encode(u, v));
        }

        List<Integer> odd = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            if ((degree[i] & 1) == 1) {
                odd.add(i);
            }
        }

        int oddCount = odd.size();
        if (oddCount == 0) {
            return true;
        }
        if (oddCount > 4) {
            return false;
        }

        if (oddCount == 2) {
            int a = odd.get(0);
            int b = odd.get(1);
            if (!edgeSet.contains(encode(a, b))) {
                return true;
            }
            for (int c = 1; c <= n; c++) {
                if (c == a || c == b) continue;
                if (!edgeSet.contains(encode(a, c)) && !edgeSet.contains(encode(b, c))) {
                    return true;
                }
            }
            return false;
        }

        // oddCount == 4
        int[] o = new int[4];
        for (int i = 0; i < 4; i++) o[i] = odd.get(i);
        int[][] pairings = {
            {0, 1, 2, 3},
            {0, 2, 1, 3},
            {0, 3, 1, 2}
        };
        for (int[] p : pairings) {
            int a = o[p[0]], b = o[p[1]];
            int c = o[p[2]], d = o[p[3]];
            if (!edgeSet.contains(encode(a, b)) && !edgeSet.contains(encode(c, d))) {
                return true;
            }
        }
        return false;
    }

    private static long encode(int u, int v) {
        if (u > v) {
            int tmp = u;
            u = v;
            v = tmp;
        }
        return ((long) u << 32) | (v & 0xffffffffL);
    }
}

