class Solution {
    public static long countSimilarPairs(String[] words) {
        Map<Integer, Integer> maskCount = new HashMap<>();
        for (int i = 0; i < words.length; i++) {
            int mask = 0;
            String w = words[i];
            for (int j = 0; j < w.length(); j++) {
                mask |= 1 << (w.charAt(j) - 'a');
            }
            maskCount.put(mask, maskCount.getOrDefault(mask, 0) + 1);
        }
        long pairs = 0;
        for (int cnt : maskCount.values()) {
            pairs += (long) cnt * (cnt - 1) / 2;
        }
        return pairs;
    }
}

