class Solution {
    public static long smallestValue(long n) {
        while (n > 1 && !isPrime(n)) {
            n = sumPrimeFactors(n);
        }
        return n;
    }

    private static boolean isPrime(long x) {
        if (x < 2) return false;
        if (x % 2 == 0) return x == 2;
        for (long d = 3; d * d <= x; d += 2) {
            if (x % d == 0) return false;
        }
        return true;
    }

    private static long sumPrimeFactors(long x) {
        long sum = 0;
        while (x % 2 == 0) {
            sum += 2;
            x /= 2;
        }
        for (long d = 3; d * d <= x; d += 2) {
            while (x % d == 0) {
                sum += d;
                x /= d;
            }
        }
        if (x > 1) sum += x;
        return sum;
    }
}

