            }
        }
        return maxCaptured;
    }
}

import java.util.*;

class Solution {
    static class Node {
        int id;
        int pts;
        Node(int id, int pts) {
            this.id = id;
            this.pts = pts;
        }
    }

    public static int[] topStudents(String[] positive_feedback, String[] negative_feedback, String[] report, int[] student_id, int k) {
        Set<String> posSet = new HashSet<>(Arrays.asList(positive_feedback));
        Set<String> negSet = new HashSet<>(Arrays.asList(negative_feedback));

        Map<Integer, Integer> points = new HashMap<>();
        for (int i = 0; i < report.length; ++i) {
            String[] words = report[i].split(" ");
            int cur = 0;
            for (String w : words) {
                if (posSet.contains(w)) cur += 3;
                else if (negSet.contains(w)) cur -= 1;
            }
            int id = student_id[i];
            points.put(id, points.getOrDefault(id, 0) + cur);
        }

        List<Node> heap = new ArrayList<>();

        java.util.function.BiPredicate<Node, Node> less = (a, b) ->
                a.pts < b.pts || (a.pts == b.pts && a.id > b.id);

        java.util.function.BiConsumer<Integer, Integer> swap = (i, j) -> {
            Node t = heap.get(i);
            heap.set(i, heap.get(j));
            heap.set(j, t);
        };

        java.util.function.Consumer<Integer> heapifyUp = new java.util.function.Consumer<Integer>() {
            public void accept(Integer idx) {
                while (idx > 0) {
                    int p = (idx - 1) >> 1;
                    if (!less.test(heap.get(idx), heap.get(p))) break;
                    swap.accept(idx, p);
                    idx = p;
                }
            }
        };

        java.util.function.Consumer<Integer> heapifyDown = new java.util.function.Consumer<Integer>() {
            public void accept(Integer idx) {
                int n = heap.size();
                while (true) {
                    int left = idx * 2 + 1;
                    int right = left + 1;
                    int smallest = idx;
                    if (left < n && less.test(heap.get(left), heap.get(smallest))) smallest = left;
                    if (right < n && less.test(heap.get(right), heap.get(smallest))) smallest = right;
                    if (smallest == idx) break;
                    swap.accept(idx, smallest);
                    idx = smallest;
                }
            }
        };

        java.util.function.Consumer<Node> push = new java.util.function.Consumer<Node>() {
            public void accept(Node node) {
                heap.add(node);
                heapifyUp.accept(heap.size() - 1);
                if (heap.size() > k) {
                    heap.set(0, heap.remove(heap.size() - 1));
                    heapifyDown.accept(0);
                }
            }
        };

        for (Map.Entry<Integer, Integer> entry : points.entrySet()) {
            push.accept(new Node(entry.getKey(), entry.getValue()));
        }

        heap.sort((a, b) -> {
            int diff = b.pts - a.pts;
            if (diff != 0) return diff;
            return a.id - b.id;
        });

        int[] result = new int[heap.size()];
        for (int i = 0; i < heap.size(); ++i) {
            result[i] = heap.get(i).id;
        }
        return result;
    }
}

