class Solution {
    public static int maximumTastiness(int[] price, int k) {
        Arrays.sort(price);
        int low = 0;
        int high = price[price.length - 1] - price[0];
        while (low < high) {
            int mid = (low + high + 1) / 2;
            if (canPlace(price, k, mid)) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return low;
    }

    private static boolean canPlace(int[] price, int k, int dist) {
        int count = 1;
        int last = price[0];
        for (int i = 1; i < price.length; i++) {
            if (price[i] - last >= dist) {
                count++;
                last = price[i];
                if (count == k) {
                    return true;
                }
            }
        }
        return false;
    }
}

public class Solution {
    public static int minMinutes(String s, int k) {
        int n = s.length();
        int totalA = 0, totalB = 0, totalC = 0;
        for (int i = 0; i < n; i++) {
            char ch = s.charAt(i);
            if (ch == 'a') totalA++;
            else if (ch == 'b') totalB++;
            else totalC++;
        }
        if (totalA < k || totalB < k || totalC < k) return -1;
        if (k == 0) return 0;
        int allowedA = totalA - k;
        int allowedB = totalB - k;
        int allowedC = totalC - k;
        int cntA = 0, cntB = 0, cntC = 0;
        int left = 0;
        int maxLen = 0;
        for (int right = 0; right < n; right++) {
            char ch = s.charAt(right);
            if (ch == 'a') cntA++;
            else if (ch == 'b') cntB++;
            else cntC++;
            while (cntA > allowedA || cntB > allowedB || cntC > allowedC) {
                char leftChar = s.charAt(left);
                if (leftChar == 'a') cntA--;
                else if (leftChar == 'b') cntB--;
                else cntC--;
                left++;
            }
            int curLen = right - left + 1;
            if (curLen > maxLen) maxLen = curLen;
        }
        return n - maxLen;
    }
}

import java.util.*;

class Solution {
    private static final long MOD = 1_000_000_007L;

    public static long countAnagrams(String s) {
        String[] words = s.split(" ");
        int maxLen = 0;
        for (String w : words) {
            if (w.length() > maxLen) maxLen = w.length();
        }

        long[] fact = new long[maxLen + 1];
        long[] invFact = new long[maxLen + 1];
        fact[0] = 1L;
        for (int i = 1; i <= maxLen; ++i) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }

        invFact[maxLen] = modPow(fact[maxLen], MOD - 2);
        for (int i = maxLen; i > 0; --i) {
            invFact[i - 1] = (invFact[i] * i) % MOD;
        }

        long answer = 1L;
        for (String w : words) {
            long ways = fact[w.length()];
            Map<Character, Integer> freq = new HashMap<>();
            for (char ch : w.toCharArray()) {
                freq.merge(ch, 1, Integer::sum);
            }
            for (int cnt : freq.values()) {
                ways = (ways * invFact[cnt]) % MOD;
            }
            answer = (answer * ways) % MOD;
        }

        return answer;
    }

    private static long modPow(long base, long exp) {
        long result = 1L;
        long b = base % MOD;
        long e = exp;
        while (e > 0) {
            if ((e & 1L) == 1L) {
                result = (result * b) % MOD;
            }
            b = (b * b) % MOD;
            e >>= 1;
        }
        return result;
    }
}

