class Solution {
    public static int distinctPrimeFactors(int[] nums) {
        Set<Integer> primes = new HashSet<>();
        for (int i = 0; i < nums.length; i++) {
            int x = nums[i];
            if (x < 2) continue;
            if (x % 2 == 0) {
                primes.add(2);
                while (x % 2 == 0) x /= 2;
            }
            for (int d = 3; d * d <= x; d += 2) {
                if (x % d == 0) {
                    primes.add(d);
                    while (x % d == 0) x /= d;
                }
            }
            if (x > 1) primes.add(x);
        }
        return primes.size();
    }
}

