class Solution {
    public static int shortestDistance(String[] words, String target, int startIndex) {
        int n = words.length;
        int minDist = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            if (words[i].equals(target)) {
                int forward = (i - startIndex + n) % n;
                int backward = (startIndex - i + n) % n;
                int dist = Math.min(forward, backward);
                if (dist < minDist) {
                    minDist = dist;
                }
            }
        }
        return minDist == Integer.MAX_VALUE ? -1 : minDist;
    }
}

class Solution {
    public static int minPartitions(String s, int k) {
        if (s == null || s.isEmpty()) return 0;
        int parts = 0;
        long cur = 0;
        for (int i = 0; i < s.length(); i++) {
            int d = s.charAt(i) - '0';
            if (d > k) return -1;
            long next = cur * 10 + d;
            if (next > k) {
                parts++;
                cur = d;
            } else {
                cur = next;
            }
        }
        return parts + 1;
    }
}

public class Solution {
    public static long minimizeMaximum(int divisor1, int divisor2, int uniqueCnt1, int uniqueCnt2) {
        long d1 = divisor1;
        long d2 = divisor2;
        long cnt1 = uniqueCnt1;
        long cnt2 = uniqueCnt2;
        long g = gcd(d1, d2);
        long lcm = d1 / g * d2;
        long low = 1;
        long high = Math.max(d1, d2) * (cnt1 + cnt2);
        if (high < 1) high = 1;
        while (!can(high, d1, d2, cnt1, cnt2, lcm)) {
            high <<= 1;
        }
        while (low < high) {
            long mid = low + (high - low) / 2;
            if (can(mid, d1, d2, cnt1, cnt2, lcm)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    private static boolean can(long m, long d1, long d2, long cnt1, long cnt2, long lcm) {
        long only1 = m / d2 - m / lcm;
        long only2 = m / d1 - m / lcm;
        long both = m - m / d1 - m / d2 + m / lcm;
        long needBoth1 = cnt1 > only1 ? cnt1 - only1 : 0;
        long needBoth2 = cnt2 > only2 ? cnt2 - only2 : 0;
        return needBoth1 + needBoth2 <= both;
    }

    private static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

public class Solution {
    private static final int MOD = 1_000_000_007;
    public static int numberOfGreatPartitions(int[] nums, int k) {
        int total = 0;
        for (int v : nums) total += v;
        if (k > total) return 0;
        int[] dp = new int[total + 1];
        dp[0] = 1;
        int curMax = 0;
        for (int v : nums) {
            for (int t = curMax; t >= 0; --t) {
                int nxt = t + v;
                int add = dp[t];
                if (add != 0) {
                    int val = dp[nxt] + add;
                    if (val >= MOD) val -= MOD;
                    dp[nxt] = val;
                }
            }
            curMax += v;
        }
        int ans = 0;
        int upper = total - k;
        for (int t = k; t <= upper; ++t) {
            ans += dp[t];
            if (ans >= MOD) ans -= MOD;
        }
        return ans;
    }
}

