public class Solution {
    public static long maxPower(int[] stations, int r, int k) {
        int n = stations.length;
        long sum = 0;
        for (int v : stations) sum += v;
        long low = 0;
        long high = sum + k;
        while (low < high) {
            long mid = (low + high + 1) >>> 1;
            if (canAchieve(mid, stations, r, k)) low = mid;
            else high = mid - 1;
        }
        return low;
    }

    private static boolean canAchieve(long target, int[] stations, int r, int k) {
        int n = stations.length;
        long[] diff = new long[n];
        long curAdded = 0;
        long used = 0;
        long windowSum = 0;
        int left = 0, right = -1;
        for (int i = 0; i < n; i++) {
            curAdded += diff[i];
            int newRight = Math.min(n - 1, i + r);
            while (right < newRight) {
                right++;
                windowSum += stations[right];
            }
            int newLeft = Math.max(0, i - r);
            while (left < newLeft) {
                windowSum -= stations[left];
                left++;
            }
            long total = windowSum + curAdded;
            if (total < target) {
                long need = target - total;
                used += need;
                if (used > k) return false;
                curAdded += need;
                int pos = Math.min(n - 1, i + r);
                int end = pos + r + 1;
                if (end < n) diff[end] -= need;
            }
        }
        return true;
    }
}

