class Solution {
    public static int[] closestPrimes(int left, int right) {
        int limit = right;
        byte[] isPrime = new byte[limit + 1];
        Arrays.fill(isPrime, (byte) 1);
        if (limit >= 0) isPrime[0] = 0;
        if (limit >= 1) isPrime[1] = 0;
        for (int p = 2; p * p <= limit; ++p) {
            if (isPrime[p] == 1) {
                for (int mult = p * p; mult <= limit; mult += p) {
                    isPrime[mult] = 2;
                }
            }
        }
        ArrayList<Integer> primesInRange = new ArrayList<>();
        int start = Math.max(2, left);
        for (int i = start; i <= right; ++i) {
            if (isPrime[i] == 1) {
                primesInRange.add(i);
            }
        }
        if (primesInRange.size() < 2) {
            return new int[]{-1, -1};
        }
        int bestGap = Integer.MAX_VALUE;
        int[] bestPair = new int[]{-1, -1};
        for (int i = 1; i < primesInRange.size(); ++i) {
            int gap = primesInRange.get(i) - primesInRange.get(i - 1);
            if (gap < bestGap) {
                bestGap = gap;
                bestPair[0] = primesInRange.get(i - 1);
                bestPair[1] = primesInRange.get(i);
            }
        }
        return bestPair;
    }
}

