class Solution {
    public static int maximumCount(int[] nums) {
        int n = nums.length;
        int firstNonNeg = firstGE(nums, 0);
        int firstPos = firstGreater(nums, 0);
        int negCount = firstNonNeg;
        int posCount = n - firstPos;
        return negCount > posCount ? negCount : posCount;
    }

    private static int firstGreater(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] > target) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        return lo;
    }

    private static int firstGE(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] >= target) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        return lo;
    }
}

