public class Solution {
    public static long maximalScore(int[] nums, int k) {
        List<Integer> heap = new ArrayList<>();
        for (int val : nums) {
            heapPush(heap, val);
        }
        long answer = 0;
        for (int i = 0; i < k; i++) {
            int cur = heapPop(heap);
            answer += cur;
            int next = (cur + 2) / 3;
            heapPush(heap, next);
        }
        return answer;
    }

    private static void heapPush(List<Integer> heap, int val) {
        heap.add(val);
        int idx = heap.size() - 1;
        while (idx > 0) {
            int parent = (idx - 1) >> 1;
            if (heap.get(parent) >= heap.get(idx)) break;
            int tmp = heap.get(parent);
            heap.set(parent, heap.get(idx));
            heap.set(idx, tmp);
            idx = parent;
        }
    }

    private static int heapPop(List<Integer> heap) {
        int top = heap.get(0);
        int last = heap.remove(heap.size() - 1);
        if (!heap.isEmpty()) {
            heap.set(0, last);
            int idx = 0;
            while (true) {
                int left = idx * 2 + 1;
                int right = left + 1;
                int largest = idx;
                if (left < heap.size() && heap.get(left) > heap.get(largest)) largest = left;
                if (right < heap.size() && heap.get(right) > heap.get(largest)) largest = right;
                if (largest == idx) break;
                int tmp = heap.get(idx);
                heap.set(idx, heap.get(largest));
                heap.set(largest, tmp);
                idx = largest;
            }
        }
        return top;
    }
}

public class Solution {
    public static boolean isItPossible(String word1, String word2) {
        int[] f1 = new int[26];
        int[] f2 = new int[26];
        for (char c : word1.toCharArray()) f1[c - 'a']++;
        for (char c : word2.toCharArray()) f2[c - 'a']++;
        int d1 = 0, d2 = 0;
        for (int i = 0; i < 26; i++) {
            if (f1[i] > 0) d1++;
            if (f2[i] > 0) d2++;
        }
        if (d1 == d2) return true;
        for (int x = 0; x < 26; x++) {
            if (f1[x] == 0) continue;
            for (int y = 0; y < 26; y++) {
                if (f2[y] == 0) continue;
                if (x == y) continue;
                int newD1 = d1;
                int newD2 = d2;
                if (f1[x] == 1) newD1--;
                if (f1[y] == 0) newD1++;
                if (f2[y] == 1) newD2--;
                if (f2[x] == 0) newD2++;
                if (newD1 == newD2) return true;
            }
        }
        return false;
    }
}

