        int count = 1;
        for (int child : graph[node]) {
            if (child == parent) continue;
            count += dfs(child, node, graph, seats, result);
        }
        if (node > 0) {
            result[0] += (count + seats - 1) / seats;
        }
        return count;
    }
}

