class Solution {
    private static final int MOD = 1_000_000_007;

    public static int countPalindromes(String s) {
        int n = s.length();
        if (n < 5) return 0;
        int[] d = new int[n];
        for (int i = 0; i < n; i++) d[i] = s.charAt(i) - '0';

        long[][][] right = new long[n][10][10];
        long[] cntRight = new long[10];
        long[][] pairRight = new long[10][10];

        for (int i = n - 1; i >= 0; i--) {
            for (int a = 0; a < 10; a++) {
                System.arraycopy(pairRight[a], 0, right[i][a], 0, 10);
            }
            int cur = d[i];
            for (int a = 0; a < 10; a++) {
                pairRight[cur][a] += cntRight[a];
            }
            cntRight[cur]++;
        }

        long[] cntLeft = new long[10];
        long[][] leftPairs = new long[10][10];
        long ans = 0;

        for (int k = 0; k < n; k++) {
            long[][] rp = right[k];
            for (int a = 0; a < 10; a++) {
                for (int b = 0; b < 10; b++) {
                    long left = leftPairs[a][b] % MOD;
                    long rightVal = rp[b][a] % MOD;
                    ans = (ans + left * rightVal) % MOD;
                }
            }
            int cur = d[k];
            for (int a = 0; a < 10; a++) {
                leftPairs[a][cur] += cntLeft[a];
            }
            cntLeft[cur]++;
        }

        return (int) ans;
    }
}

import java.util.ArrayList;
