class Solution {
    public static List<String> splitMessage(String message, int limit) {
        int msgLen = message.length();
        for (int totalParts = 1; totalParts <= msgLen; totalParts++) {
            int idx = 0;
            boolean possible = true;
            for (int i = 1; i <= totalParts; i++) {
                int suffixLen = 3 + digits(i) + digits(totalParts);
                int avail = limit - suffixLen;
                if (avail <= 0) {
                    possible = false;
                    break;
                }
                int take = Math.min(avail, msgLen - idx);
                idx += take;
                if (idx == msgLen && i < totalParts) {
                    possible = false;
                    break;
                }
            }
            if (possible && idx == msgLen) {
                List<String> result = new ArrayList<>();
                idx = 0;
                for (int i = 1; i <= totalParts; i++) {
                    int suffixLen = 3 + digits(i) + digits(totalParts);
                    int avail = limit - suffixLen;
                    int take = Math.min(avail, msgLen - idx);
                    String suffix = "<" + i + "/" + totalParts + ">";
                    result.add(message.substring(idx, idx + take) + suffix);
                    idx += take;
                }
                return result;
            }
        }
        return new ArrayList<>();
    }

    private static int digits(int n) {
        return Integer.toString(n).length();
    }
}

