class Solution {
    public static int minimumOperations(TreeNode root) {
        int result = 0;
        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);
        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            List<Integer> levelValues = new ArrayList<>(levelSize);
            for (int i = 0; i < levelSize; i++) {
                TreeNode node = queue.poll();
                levelValues.add(node.val);
                if (node.left != null) queue.offer(node.left);
                if (node.right != null) queue.offer(node.right);
            }
            List<Integer> sortedLevelValues = new ArrayList<>(levelValues);
            Collections.sort(sortedLevelValues);
            Map<Integer,Integer> indexMapping = new HashMap<>();
            for (int i = 0; i < levelSize; i++) indexMapping.put(levelValues.get(i), i);
            boolean[] visited = new boolean[levelSize];
            for (int i = 0; i < levelSize; i++) {
                if (visited[i] || levelValues.get(i).equals(sortedLevelValues.get(i))) continue;
                int cycleSize = 0, j = i;
                while (!visited[j]) {
                    visited[j] = true;
                    j = indexMapping.get(sortedLevelValues.get(j));
                    cycleSize++;
                }
                result += (cycleSize - 1);
            }
        }
        return result;
    }
}

