class Solution {
    public static int numberOfBeautifulPartitions(String s, int k, int minLength) {
        final long MOD = 1_000_000_007L;
        int n = s.length();
        boolean[] primeStart = new boolean[n];
        boolean[] nonPrimeEnd = new boolean[n];
        for (int i = 0; i < n; i++) {
            int d = s.charAt(i) - '0';
            boolean isPrime = d == 2 || d == 3 || d == 5 || d == 7;
            primeStart[i] = isPrime;
            nonPrimeEnd[i] = !isPrime;
        }
        long[] dpPrev = new long[n + 1];
        dpPrev[0] = 1;
        for (int part = 1; part <= k; part++) {
            long[] prefix = new long[n + 1];
            for (int i = 0; i <= n; i++) {
                if (i > 0) prefix[i] = prefix[i - 1];
                if (i < n && primeStart[i]) {
                    prefix[i] = (prefix[i] + dpPrev[i]) % MOD;
                }
            }
            long[] dpCurr = new long[n + 1];
            for (int i = 1; i <= n; i++) {
                if (nonPrimeEnd[i - 1]) {
                    int idx = i - minLength;
                    if (idx >= 0) {
                        dpCurr[i] = prefix[idx];
                    }
                }
            }
            dpPrev = dpCurr;
        }
        return (int) (dpPrev[n] % MOD);
    }
}

