class Solution {
    public static int[] cycleLengthQueries(int n, int[][] queries) {
        int[] answer = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int a = queries[i][0];
            int b = queries[i][1];
            int lca = findLCA(a, b);
            int depthA = findDepth(a);
            int depthB = findDepth(b);
            int depthLCA = findDepth(lca);
            int cycleLength = (depthA - depthLCA) + (depthB - depthLCA) + 1;
            answer[i] = cycleLength;
        }
        return answer;
    }

    private static int findDepth(int node) {
        return 32 - Integer.numberOfLeadingZeros(node);
    }

    private static int findLCA(int a, int b) {
        int depthA = findDepth(a);
        int depthB = findDepth(b);
        while (depthA > depthB) {
            a /= 2;
            depthA--;
        }
        while (depthB > depthA) {
            b /= 2;
            depthB--;
        }
        while (a != b) {
            a /= 2;
            b /= 2;
        }
        return a;
    }
}

