class Solution {
    public static long maxStarSum(int[] vals, int[][] edges, int k) {
        List<Integer>[] graph = new ArrayList[vals.length];
        for (int i = 0; i < vals.length; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] edge : edges) {
            int a = edge[0];
            int b = edge[1];
            graph[a].add(b);
            graph[b].add(a);
        }
        long maxSum = Long.MIN_VALUE;
        for (int i = 0; i < vals.length; i++) {
            List<Integer> neighbors = graph[i];
            neighbors.sort((a, b) -> Integer.compare(vals[b], vals[a]));
            long sum = vals[i];
            int limit = Math.min(k, neighbors.size());
            for (int j = 0; j < limit; j++) {
                sum += vals[neighbors.get(j)];
            }
            if (sum > maxSum) {
                maxSum = sum;
            }
        }
        return maxSum;
    }
}

