class Solution {
    public static int minOperations(int[] nums1, int[] nums2, int k) {
        long pos = 0, neg = 0;
        for (int i = 0; i < nums1.length; i++) {
            int diff = nums1[i] - nums2[i];
            if (diff % k != 0) return -1;
            int units = diff / k;
            if (units > 0) pos += units;
            else if (units < 0) neg -= units;
        }
        if (pos != neg) return -1;
        return (int) pos;
    }
}

import java.util.*;

class Solution {
    public static long maxDifferenceBetweenMaxAndMinPriceSum(int n, int[][] edges, int[] price) {
        int[] head = new int[n];
        Arrays.fill(head, -1);
        int m = edges.length;
        int[] to = new int[2 * m];
        int[] next = new int[2 * m];
        int idx = 0;
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            to[idx] = v;
            next[idx] = head[u];
            head[u] = idx++;
            to[idx] = u;
            next[idx] = head[v];
            head[v] = idx++;
        }

        long[] dist0 = computeDist(0, head, to, next, price, n);
        int A = 0;
        for (int i = 1; i < n; i++) {
            if (dist0[i] > dist0[A]) A = i;
        }

        long[] distA = computeDist(A, head, to, next, price, n);
        int B = A;
        for (int i = 0; i < n; i++) {
            if (distA[i] > distA[B]) B = i;
        }

        long[] distB = computeDist(B, head, to, next, price, n);

        long answer = 0;
        for (int i = 0; i < n; i++) {
            long maxPath = Math.max(distA[i], distB[i]);
            long cost = maxPath - price[i];
            if (cost > answer) answer = cost;
        }
        return answer;
    }

    private static long[] computeDist(int start, int[] head, int[] to, int[] next, int[] price, int n) {
        long[] dist = new long[n];
        int[] parent = new int[n];
        Arrays.fill(parent, -2);
        int[] stack = new int[n];
        int top = 0;
        stack[top] = start;
        parent[start] = -1;
        dist[start] = price[start];
        while (top >= 0) {
            int u = stack[top--];
            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                if (v == parent[u]) continue;
                parent[v] = u;
                dist[v] = dist[u] + price[v];
                stack[++top] = v;
            }
        }
        return dist;
    }
}

