class Solution {
    public static int distinctIntegers(int n) {
        Set<Integer> seen = new HashSet<>();
        Deque<Integer> queue = new ArrayDeque<>();
        seen.add(n);
        queue.add(n);
        while (!queue.isEmpty()) {
            int x = queue.poll();
            int m = x - 1;
            if (m >= 2) {
                if (seen.add(m)) {
                    queue.add(m);
                }
                for (int i = 2; i * i <= m; i++) {
                    if (m % i == 0) {
                        int d1 = i;
                        int d2 = m / i;
                        if (seen.add(d1)) {
                            queue.add(d1);
                        }
                        if (d2 != d1 && seen.add(d2)) {
                            queue.add(d2);
                        }
                    }
                }
            }
        }
        return seen.size();
    }
}

