class Solution {
    public static long countCollisions(int n) {
        final long MOD = 1_000_000_007L;
        long result = 1;
        long base = 2;
        int exp = n;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        result = (result - 2) % MOD;
        if (result < 0) {
            result += MOD;
        }
        return result;
    }
}

