class Solution {
    public static long maxScore(int[] nums1, int[] nums2, int k) {
        int n = nums1.length;
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) {
            order[i] = i;
        }
        Arrays.sort(order, (a, b) -> Integer.compare(nums2[b], nums2[a]));
        PriorityQueue<Integer> heap = new PriorityQueue<>();
        long sum = 0;
        long best = 0;
        for (int i = 0; i < n; i++) {
            int idx = order[i];
            int v = nums1[idx];
            heap.offer(v);
            sum += v;
            if (heap.size() > k) {
                sum -= heap.poll();
            }
            if (heap.size() == k) {
                long score = sum * (long) nums2[idx];
                if (score > best) {
                    best = score;
                }
            }
        }
        return best;
    }
}

