class Solution {
    public static boolean isPossibleToDisconnect(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        boolean[][] fromStart = new boolean[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    if (i == 0 && j == 0) {
                        fromStart[i][j] = true;
                    } else {
                        boolean up = i > 0 && fromStart[i - 1][j];
                        boolean left = j > 0 && fromStart[i][j - 1];
                        fromStart[i][j] = up || left;
                    }
                }
            }
        }
        if (!fromStart[m - 1][n - 1]) {
            return true;
        }
        boolean[][] toEnd = new boolean[m][n];
        for (int i = m - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                if (grid[i][j] == 1) {
                    if (i == m - 1 && j == n - 1) {
                        toEnd[i][j] = true;
                    } else {
                        boolean down = i + 1 < m && toEnd[i + 1][j];
                        boolean right = j + 1 < n && toEnd[i][j + 1];
                        toEnd[i][j] = down || right;
                    }
                }
            }
        }
        int maxSum = m + n - 2;
        int[] cnt = new int[maxSum + 1];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (fromStart[i][j] && toEnd[i][j]) {
                    cnt[i + j]++;
                }
            }
        }
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (fromStart[i][j] && toEnd[i][j] && cnt[i + j] == 1) {
                    if (!((i == 0 && j == 0) || (i == m - 1 && j == n - 1))) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
}

