class Solution {
    public static int minimumImpossibleOR(int[] nums) {
        int maxOr = 0;
        for (int v : nums) {
            maxOr |= v;
        }
        for (int x = 1; x <= maxOr + 1; x++) {
            int union = 0;
            for (int v : nums) {
                if ((v | x) == x) {
                    union |= v;
                }
            }
            if (union != x) {
                return x;
            }
        }
        return maxOr + 1;
    }
}

import java.util.ArrayList;

class Solution {
    public static long takeGifts(int[] gifts, int k) {
        ArrayList<Integer> heap = new ArrayList<>();

        java.util.function.BiConsumer<Integer, Integer> heapSwap = (i, j) -> {
            int tmp = heap.get(i);
            heap.set(i, heap.get(j));
            heap.set(j, tmp);
        };

        java.util.function.Consumer<Integer> heapPush = (val) -> {
            heap.add(val);
            int idx = heap.size() - 1;
            while (idx > 0) {
                int parent = (idx - 1) >> 1;
                if (heap.get(parent) >= heap.get(idx)) break;
                heapSwap.accept(parent, idx);
                idx = parent;
            }
        };

        java.util.function.Supplier<Integer> heapPop = () -> {
            int top = heap.get(0);
            int last = heap.remove(heap.size() - 1);
            if (!heap.isEmpty()) {
                heap.set(0, last);
                int idx = 0;
                while (true) {
                    int left = idx * 2 + 1;
                    int right = left + 1;
                    int largest = idx;
                    if (left < heap.size() && heap.get(left) > heap.get(largest)) largest = left;
                    if (right < heap.size() && heap.get(right) > heap.get(largest)) largest = right;
                    if (largest == idx) break;
                    heapSwap.accept(idx, largest);
                    idx = largest;
                }
            }
            return top;
        };

        for (int v : gifts) heapPush.accept(v);

        for (int i = 0; i < k; i++) {
            int mx = heapPop.get();
            int newVal = (int) Math.floor(Math.sqrt(mx));
            heapPush.accept(newVal);
            if (mx == 1) break;
        }

        long total = 0;
        for (int v : heap) total += v;
        return total;
    }
}

