class Solution {
    public static int[][] mergeArrays(int[][] nums1, int[][] nums2) {
        List<int[]> merged = new ArrayList<>();
        int i = 0, j = 0;
        int n1 = nums1.length, n2 = nums2.length;
        while (i < n1 && j < n2) {
            int id1 = nums1[i][0];
            int val1 = nums1[i][1];
            int id2 = nums2[j][0];
            int val2 = nums2[j][1];
            if (id1 == id2) {
                merged.add(new int[]{id1, val1 + val2});
                i++;
                j++;
            } else if (id1 < id2) {
                merged.add(nums1[i]);
                i++;
            } else {
                merged.add(nums2[j]);
                j++;
            }
        }
        while (i < n1) {
            merged.add(nums1[i]);
            i++;
        }
        while (j < n2) {
            merged.add(nums2[j]);
            j++;
        }
        int[][] result = new int[merged.size()][2];
        for (int k = 0; k < merged.size(); k++) {
            result[k] = merged.get(k);
        }
        return result;
    }
}

