        for (int i = 0; i < n; ++i) {
            if (lcp[i][i] != n - i) return "";
            for (int j = i + 1; j < n; ++j) {
                if (lcp[i][j] != lcp[j][i]) return "";
                int maxLen = Math.min(n - i, n - j);
                if (lcp[i][j] < 0 || lcp[i][j] > maxLen) return "";
            }
        }

        DSU dsu = new DSU(n);
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                int k = lcp[i][j];
                for (int t = 0; t < k; ++t) {
                    dsu.unite(i + t, j + t);
                }
            }
        }

        int[] compId = new int[n];
        Map<Integer, Integer> rootToIdx = new HashMap<>();
        int idx = 0;
        for (int i = 0; i < n; ++i) {
            int r = dsu.find(i);
            if (!rootToIdx.containsKey(r)) rootToIdx.put(r, idx++);
            compId[i] = rootToIdx.get(r);
        }
        int m = idx;
        boolean[][] conflict = new boolean[m][m];

        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                int k = lcp[i][j];
                int maxLen = Math.min(n - i, n - j);
                if (k < maxLen) {
                    int a = compId[i + k];
                    int b = compId[j + k];
                    if (a == b) return "";
                    conflict[a][b] = true;
                    conflict[b][a] = true;
                }
            }
        }

        int[] color = new int[m];
        Arrays.fill(color, -1);
        for (int c = 0; c < m; ++c) {
            if (color[c] != -1) continue;
            boolean[] used = new boolean[26];
            for (int nb = 0; nb < m; ++nb) {
                if (conflict[c][nb] && color[nb] != -1) used[color[nb]] = true;
            }
            int assign = -1;
            for (int d = 0; d < 26; ++d) {
                if (!used[d]) {
                    assign = d;
                    break;
                }
            }
            if (assign == -1) return "";
            color[c] = assign;
        }

        char[] result = new char[n];
        for (int i = 0; i < n; ++i) {
            result[i] = (char) ('a' + color[compId[i]]);
        }

        for (int i = 0; i < n; ++i) {
            for (int j = i; j < n; ++j) {
                int cnt = 0;
                while (i + cnt < n && j + cnt < n && result[i + cnt] == result[j + cnt]) ++cnt;
                if (cnt != lcp[i][j]) return "";
            }
        }
        return new String(result);
    }

    private static class DSU {
        int[] parent;
        int[] size;

        DSU(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; ++i) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }

        void unite(int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) return;
            if (size[a] < size[b]) {
                int tmp = a;
                a = b;
                b = tmp;
            }
            parent[b] = a;
            size[a] += size[b];
        }
    }
}

import java.util.*;

class Solution {
    public static int rootCount(int[][] edges, int[][] guesses, int k) {
        int n = edges.length + 1;
        int[] degree = new int[n];
        for (int[] e : edges) {
            degree[e[0]]++;
            degree[e[1]]++;
        }
        int[][] adj = new int[n][];
        for (int i = 0; i < n; i++) adj[i] = new int[degree[i]];
        int[] idx = new int[n];
        for (int[] e : edges) {
            int u = e[0], v = e[1];
            adj[u][idx[u]++] = v;
            adj[v][idx[v]++] = u;
        }

        Set<Long> guessSet = new HashSet<>(guesses.length * 2);
        for (int[] g : guesses) {
            long key = ((long) g[0] << 32) | (g[1] & 0xffffffffL);
            guessSet.add(key);
        }

        int[] parent = new int[n];
        Arrays.fill(parent, -1);
        int[] order = new int[n];
        int orderSize = 0;
        int[] stack = new int[n];
        int sp = 0;
        stack[sp++] = 0;
        while (sp > 0) {
            int node = stack[--sp];
            order[orderSize++] = node;
            for (int nb : adj[node]) {
                if (nb == parent[node]) continue;
                parent[nb] = node;
                stack[sp++] = nb;
            }
        }

        int initialCorrect = 0;
        for (int[] g : guesses) {
            if (parent[g[1]] == g[0]) initialCorrect++;
        }

        int[] correctCount = new int[n];
        correctCount[0] = initialCorrect;
        int answer = initialCorrect >= k ? 1 : 0;

        for (int i = 0; i < orderSize; i++) {
            int node = order[i];
            int cur = correctCount[node];
            for (int nb : adj[node]) {
                if (parent[nb] != node) continue;
                int newCorrect = cur;
                long keyParentToChild = ((long) node << 32) | (nb & 0xffffffffL);
                long keyChildToParent = ((long) nb << 32) | (node & 0xffffffffL);
                if (guessSet.contains(keyParentToChild)) newCorrect--;
                if (guessSet.contains(keyChildToParent)) newCorrect++;
                correctCount[nb] = newCorrect;
                if (newCorrect >= k) answer++;
            }
        }
        return answer;
    }
}

