class Solution {
    private static final long MOD = 1_000_000_007L;

    public static int waysToEarnPoints(int target, int[][] types) {
        long[] dp = new long[target + 1];
        dp[0] = 1;
        for (int[] type : types) {
            int count = type[0];
            int marks = type[1];
            long[] ndp = new long[target + 1];
            for (int r = 0; r < marks; r++) {
                long sum = 0;
                for (int j = r; j <= target; j += marks) {
                    sum += dp[j];
                    int removeIdx = j - (count + 1) * marks;
                    if (removeIdx >= 0) {
                        sum -= dp[removeIdx];
                    }
                    sum %= MOD;
                    if (sum < 0) sum += MOD;
                    ndp[j] = sum;
                }
            }
            dp = ndp;
        }
        return (int) dp[target];
    }
}

