class Solution {
    public static int minTime(int[][] tasks) {
        Arrays.sort(tasks, (a, b) -> {
            int cmp = Integer.compare(a[1], b[1]);
            if (cmp != 0) return cmp;
            return Integer.compare(a[0], b[0]);
        });
        int maxTime = 0;
        for (int[] t : tasks) {
            maxTime = Math.max(maxTime, t[1]);
        }
        boolean[] occupied = new boolean[maxTime + 2];
        Fenwick fenwick = new Fenwick(maxTime + 2);
        int total = 0;
        for (int[] task : tasks) {
            int l = task[0];
            int r = task[1];
            int d = task[2];
            int already = fenwick.sum(r) - fenwick.sum(l - 1);
            int need = d - already;
            for (int t = r; need > 0; --t) {
                if (!occupied[t]) {
                    occupied[t] = true;
                    fenwick.add(t, 1);
                    total++;
                    need--;
                }
            }
        }
        return total;
    }

    private static class Fenwick {
        private final int[] bit;
        Fenwick(int size) {
            bit = new int[size];
        }
        void add(int idx, int delta) {
            for (int i = idx; i < bit.length; i += i & -i) {
                bit[i] += delta;
            }
        }
        int sum(int idx) {
            int res = 0;
            for (int i = idx; i > 0; i -= i & -i) {
                res += bit[i];
            }
            return res;
        }
    }
}

