class Solution {
    public static int distributeMoney(int money, int children) {
        if (money < children) {
            return -1;
        }
        int extra = money - children;
        int maxEight = extra / 7;
        int remaining = extra % 7;
        if (remaining == 3) {
            if (maxEight > 0) {
                maxEight--;
            } else {
                return -1;
            }
        }
        return maxEight;
    }
}

