class Solution {
    public static int findScore(int[] nums) {
        int n = nums.length;
        Integer[] pos = new Integer[n];
        for (int i = 0; i < n; i++) {
            pos[i] = i;
        }
        Arrays.sort(pos, (a, b) -> {
            if (nums[a] == nums[b]) {
                return a - b;
            }
            return Integer.compare(nums[a], nums[b]);
        });
        boolean[] marked = new boolean[n];
        int score = 0;
        for (int i = 0; i < n; i++) {
            int p = pos[i];
            if (marked[p]) continue;
            score += nums[p];
            marked[p] = true;
            if (p > 0) marked[p - 1] = true;
            if (p < n - 1) marked[p + 1] = true;
        }
        return score;
    }
}

