class Solution {
    public static long beautifulSubsets(int[] nums, int k) {
        Arrays.sort(nums);
        int n = nums.length;
        int[] values = new int[n];
        int[] counts = new int[n];
        int m = 0;
        for (int i = 0; i < n; ) {
            int v = nums[i];
            int cnt = 0;
            while (i < n && nums[i] == v) {
                cnt++;
                i++;
            }
            values[m] = v;
            counts[m] = cnt;
            m++;
        }
        long total = 1;
        int i = 0;
        while (i < m) {
            long dpPrevPrev = 1;
            long w0 = (1L << counts[i]) - 1;
            long dpPrev = 1 + w0;
            i++;
            while (i < m && values[i] - values[i - 1] == k) {
                long w = (1L << counts[i]) - 1;
                long cur = dpPrev + dpPrevPrev * w;
                dpPrevPrev = dpPrev;
                dpPrev = cur;
                i++;
            }
            total *= dpPrev;
        }
        return total - 1;
    }
}

