class Solution {
    public static int maximumMex(int[] nums, int value) {
        if (value <= 0) {
            int mex = 0;
            Set<Integer> set = new HashSet<>();
            for (int num : nums) {
                if (num >= 0) set.add(num);
            }
            while (set.contains(mex)) {
                mex++;
            }
            return mex;
        }
        int[] cnt = new int[value];
        for (int num : nums) {
            int r = num % value;
            if (r < 0) r += value;
            cnt[r]++;
        }
        int mex = 0;
        while (true) {
            int r = mex % value;
            if (cnt[r] == 0) break;
            cnt[r]--;
            mex++;
        }
        return mex;
    }
}

