class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

public class Solution {
    public static long kthLargestLevelSum(TreeNode root, int k) {
        if (root == null) return -1;
        List<TreeNode> queue = new ArrayList<>();
        queue.add(root);
        int head = 0;
        List<Long> minHeap = new ArrayList<>();
        while (head < queue.size()) {
            int levelSize = queue.size() - head;
            long levelSum = 0;
            for (int i = 0; i < levelSize; i++) {
                TreeNode node = queue.get(head++);
                levelSum += node.val;
                if (node.left != null) queue.add(node.left);
                if (node.right != null) queue.add(node.right);
            }
            if (minHeap.size() < k) {
                heapPush(minHeap, levelSum);
            } else if (levelSum > minHeap.get(0)) {
                heapReplaceRoot(minHeap, levelSum);
            }
        }
        return minHeap.size() == k ? minHeap.get(0) : -1;
    }

    private static void heapPush(List<Long> heap, long val) {
        heap.add(val);
        int i = heap.size() - 1;
        while (i > 0) {
            int p = (i - 1) >> 1;
            if (heap.get(p) <= heap.get(i)) break;
            long tmp = heap.get(p);
            heap.set(p, heap.get(i));
            heap.set(i, tmp);
            i = p;
        }
    }

    private static void heapReplaceRoot(List<Long> heap, long val) {
        heap.set(0, val);
        int i = 0;
        while (true) {
            int l = i * 2 + 1;
            int r = i * 2 + 2;
            int smallest = i;
            if (l < heap.size() && heap.get(l) < heap.get(smallest)) smallest = l;
            if (r < heap.size() && heap.get(r) < heap.get(smallest)) smallest = r;
            if (smallest == i) break;
            long tmp = heap.get(i);
            heap.set(i, heap.get(smallest));
            heap.set(smallest, tmp);
            i = smallest;
        }
    }
}

