public class Solution {
    public static boolean primeSubtractionOperation(int[] nums) {
        int n = nums.length;
        if (n == 0) return true;
        int next = nums[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            if (nums[i] < next) {
                next = nums[i];
                continue;
            }
            int minP = nums[i] - (next - 1);
            int limit = nums[i] - 1;
            int p = Math.max(2, minP);
            int found = -1;
            for (int candidate = p; candidate <= limit; candidate++) {
                if (isPrime(candidate)) {
                    found = candidate;
                    break;
                }
            }
            if (found == -1) return false;
            next = nums[i] - found;
            if (next < 1) return false;
        }
        return true;
    }

    private static boolean isPrime(int x) {
        if (x < 2) return false;
        if (x % 2 == 0) return x == 2;
        for (int i = 3; i * i <= x; i += 2) {
            if (x % i == 0) return false;
        }
        return true;
    }
}

