class Solution {
    public static boolean checkValidKnightTour(int[][] grid) {
        int n = grid.length;
        int total = n * n;
        int[][] pos = new int[total][2];
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                int v = grid[r][c];
                if (v < 0 || v >= total) return false;
                pos[v][0] = r;
                pos[v][1] = c;
            }
        }
        if (grid[0][0] != 0) return false;
        for (int k = 0; k < total - 1; k++) {
            int r1 = pos[k][0];
            int c1 = pos[k][1];
            int r2 = pos[k + 1][0];
            int c2 = pos[k + 1][1];
            int dr = Math.abs(r1 - r2);
            int dc = Math.abs(c1 - c2);
            boolean ok = (dr == 1 && dc == 2) || (dr == 2 && dc == 1);
            if (!ok) return false;
        }
        return true;
    }
}

