public class Solution {
    public static long[] minOperations(int[] nums, int[] queries) {
        int n = nums.length;
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        long[] pref = new long[n];
        long sum = 0;
        for (int i = 0; i < n; i++) {
            sum += sorted[i];
            pref[i] = sum;
        }
        long total = sum;
        long[] res = new long[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            int t = queries[qi];
            int lo = 0, hi = n;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (sorted[mid] <= t) {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }
            int k = lo;
            long left = k == 0 ? 0 : (long) t * k - pref[k - 1];
            long right = k == n ? 0 : (total - (k == 0 ? 0 : pref[k - 1])) - (long) t * (n - k);
            res[qi] = left + right;
        }
        return res;
    }
}

