class Solution {
    public static int collectTheCoins(int[] coins, int[][] edges) {
        int n = coins.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            int a = e[0], b = e[1];
            graph[a].add(b);
            graph[b].add(a);
        }
        int[] degree = new int[n];
        for (int i = 0; i < n; i++) degree[i] = graph[i].size();
        boolean[] removed = new boolean[n];
        ArrayDeque<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            if (degree[i] == 1 && coins[i] == 0) q.add(i);
        }
        while (!q.isEmpty()) {
            int v = q.poll();
            removed[v] = true;
            for (int nb : graph[v]) {
                if (removed[nb]) continue;
                degree[nb]--;
                if (degree[nb] == 1 && coins[nb] == 0) q.add(nb);
            }
        }
        int remainingNodes = 0;
        for (int i = 0; i < n; i++) if (!removed[i]) remainingNodes++;
        if (remainingNodes == 0) return 0;
        ArrayDeque<Integer> leaves = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            if (!removed[i] && degree[i] == 1) leaves.add(i);
        }
        int rounds = 0;
        while (!leaves.isEmpty() && rounds < 2) {
            int sz = leaves.size();
            for (int i = 0; i < sz; i++) {
                int v = leaves.poll();
                removed[v] = true;
                for (int nb : graph[v]) {
                    if (removed[nb]) continue;
                    degree[nb]--;
                    if (degree[nb] == 1) leaves.add(nb);
                }
            }
            rounds++;
        }
        long remainingEdges = 0;
        for (int i = 0; i < n; i++) {
            if (!removed[i]) remainingEdges += degree[i];
        }
        remainingEdges /= 2;
        return (int) (remainingEdges * 2);
    }
}

