class Solution {
    public static List<List<Integer>> convertArray(int[] nums) {
        Map<Integer, Integer> freq = new HashMap<>();
        int maxFreq = 0;
        for (int v : nums) {
            int count = freq.getOrDefault(v, 0) + 1;
            freq.put(v, count);
            if (count > maxFreq) {
                maxFreq = count;
            }
        }
        List<List<Integer>> rows = new ArrayList<>(maxFreq);
        for (int i = 0; i < maxFreq; i++) {
            rows.add(new ArrayList<>());
        }
        List<Integer> values = new ArrayList<>(freq.keySet());
        values.sort((a, b) -> {
            int cmp = freq.get(b) - freq.get(a);
            if (cmp != 0) return cmp;
            return b - a;
        });
        for (int val : values) {
            int count = freq.get(val);
            for (int i = 0; i < count; i++) {
                rows.get(i).add(val);
            }
        }
        return rows;
    }
}

import java.util.Arrays;

class Solution {
    public static long makeKSubarraySumsEqual(int[] arr, int k) {
        int n = arr.length;
        int g = gcd(n, k);
        int cycleLen = n / g;
        long total = 0;
        int[] values = new int[cycleLen];
        for (int start = 0; start < g; start++) {
            int idx = start;
            for (int i = 0; i < cycleLen; i++) {
                values[i] = arr[idx];
                idx = (idx + k) % n;
            }
            Arrays.sort(values);
            int median = values[cycleLen / 2];
            for (int v : values) {
                long diff = (long) v - median;
                total += diff >= 0 ? diff : -diff;
            }
        }
        return total;
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

