class Solution {
    public static int longestBalancedSubstring(String s) {
        int maxLen = 0;
        int prevRunLen = 0;
        int curRunLen = 0;
        char prevRunChar = '\0';
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (i == 0) {
                curRunLen = 1;
                prevRunChar = c;
            } else {
                if (c == s.charAt(i - 1)) {
                    curRunLen++;
                } else {
                    prevRunLen = curRunLen;
                    prevRunChar = s.charAt(i - 1);
                    curRunLen = 1;
                }
            }
            if (prevRunChar == '0' && c == '1') {
                int candidate = 2 * Math.min(prevRunLen, curRunLen);
                if (candidate > maxLen) {
                    maxLen = candidate;
                }
            }
        }
        return maxLen;
    }
}

import java.util.Arrays;

class Solution {
    public static int[] minimumReverseOperations(int n, int p, int[] banned, int k) {
        int[] answer = new int[n];
        Arrays.fill(answer, -1);
        int[] nxt = new int[n + 2];
        for (int i = 0; i <= n + 1; i++) {
            nxt[i] = i;
        }
        for (int b : banned) {
            remove(b, n, nxt);
        }
        answer[p] = 0;
        remove(p, n, nxt);
        int[] queue = new int[n];
        int head = 0, tail = 0;
        queue[tail++] = p;
        while (head < tail) {
            int x = queue[head++];
            int dMin = Math.max(0, x - (n - k));
            int dMax = Math.min(k - 1, x);
            int L = x + (k - 1) - 2 * dMax;
            int R = x + (k - 1) - 2 * dMin;
            if (L < 0) L = 0;
            if (R >= n) R = n - 1;
            if (L > R) continue;
            int cur = find(L, n, nxt);
            while (cur <= R) {
                answer[cur] = answer[x] + 1;
                queue[tail++] = cur;
                int next = find(cur + 2, n, nxt);
                nxt[cur] = next;
                cur = next;
            }
        }
        return answer;
    }

    private static int find(int i, int n, int[] nxt) {
        if (i >= n) return n;
        int root = i;
        while (nxt[root] != root) {
            root = nxt[root];
        }
        while (i < n && nxt[i] != root) {
            int parent = nxt[i];
            nxt[i] = root;
            i = parent;
        }
        return root;
    }

    private static void remove(int i, int n, int[] nxt) {
        nxt[i] = find(i + 2, n, nxt);
    }
}

import java.util.*;

class Solution {
    public static int shortestCycle(int n, int[][] edges) {
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            adj[u].add(v);
            adj[v].add(u);
        }
        int best = Integer.MAX_VALUE;
        for (int start = 0; start < n; start++) {
            int[] dist = new int[n];
            int[] parent = new int[n];
            Arrays.fill(dist, -1);
            Arrays.fill(parent, -1);
            int[] queue = new int[n];
            int qHead = 0, qTail = 0;
            dist[start] = 0;
            queue[qTail++] = start;
            while (qHead < qTail) {
                int u = queue[qHead++];
                for (int v : adj[u]) {
                    if (dist[v] == -1) {
                        dist[v] = dist[u] + 1;
                        parent[v] = u;
                        queue[qTail++] = v;
                    } else if (parent[u] != v) {
                        int cycleLen = dist[u] + dist[v] + 1;
                        if (cycleLen < best) best = cycleLen;
                    }
                }
            }
        }
        return best == Integer.MAX_VALUE ? -1 : best;
    }
}

public class Solution {
    public static int maxSum(int numOnes, int numZeros, int numNegOnes, int k) {
        int onesTaken = Math.min(numOnes, k);
        int remaining = k - onesTaken;
        int zerosTaken = Math.min(numZeros, remaining);
        remaining -= zerosTaken;
        int negOnesTaken = remaining;
        return onesTaken - negOnesTaken;
    }
}

import java.util.ArrayDeque;
import java.util.NavigableSet;
import java.util.TreeSet;

class Solution {
    public static int minimumVisitedCells(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        @SuppressWarnings("unchecked")
        TreeSet<Integer>[] rowSets = new TreeSet[m];
        for (int i = 0; i < m; i++) {
            rowSets[i] = new TreeSet<>();
            for (int j = 0; j < n; j++) {
                rowSets[i].add(j);
            }
        }
        @SuppressWarnings("unchecked")
        TreeSet<Integer>[] colSets = new TreeSet[n];
        for (int j = 0; j < n; j++) {
            colSets[j] = new TreeSet<>();
            for (int i = 0; i < m; i++) {
                colSets[j].add(i);
            }
        }
        int[][] dist = new int[m][n];
        for (int i = 0; i < m; i++) {
            java.util.Arrays.fill(dist[i], -1);
        }
        ArrayDeque<int[]> q = new ArrayDeque<>();
        dist[0][0] = 1;
        q.add(new int[]{0, 0});
        rowSets[0].remove(0);
        colSets[0].remove(0);
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int i = cur[0];
            int j = cur[1];
            if (i == m - 1 && j == n - 1) {
                return dist[i][j];
            }
            int jump = grid[i][j];
            int left = j + 1;
            int right = Math.min(n - 1, j + jump);
            if (left <= right) {
                NavigableSet<Integer> cols = rowSets[i].subSet(left, true, right, true);
                while (true) {
                    Integer c = cols.pollFirst();
                    if (c == null) break;
                    colSets[c].remove(i);
                    dist[i][c] = dist[i][j] + 1;
                    q.add(new int[]{i, c});
                }
            }
            int top = i + 1;
            int bottom = Math.min(m - 1, i + jump);
            if (top <= bottom) {
                NavigableSet<Integer> rows = colSets[j].subSet(top, true, bottom, true);
                while (true) {
                    Integer r = rows.pollFirst();
                    if (r == null) break;
                    rowSets[r].remove(j);
                    dist[r][j] = dist[i][j] + 1;
                    q.add(new int[]{r, j});
                }
            }
        }
        return -1;
    }
}

import java.util.Arrays;

class Solution {
    public static long maxPoints(int[] reward1, int[] reward2, int k) {
        int n = reward1.length;
        long base = 0;
        long[] diffs = new long[n];
        for (int i = 0; i < n; i++) {
            base += reward2[i];
            diffs[i] = (long) reward1[i] - reward2[i];
        }
        Arrays.sort(diffs);
        long add = 0;
        for (int i = n - 1; i >= n - k; i--) {
            add += diffs[i];
        }
        return base + add;
    }
}

import java.util.*;

class Solution {
    public static int largestPrimeDiagonal(int[][] nums) {
        int rows = nums.length;
        int cols = nums[0].length;
        int maxPrime = 0;
        for (int i = 0; i < rows; i++) {
            if (i < cols) {
                int v = nums[i][i];
                if (v > maxPrime && isPrime(v)) {
                    maxPrime = v;
                }
            }
            int j = cols - 1 - i;
            if (j >= 0 && j < cols && j != i) {
                int v = nums[i][j];
                if (v > maxPrime && isPrime(v)) {
                    maxPrime = v;
                }
            }
        }
        return maxPrime;
    }

    private static boolean isPrime(int n) {
        if (n <= 1) return false;
        if (n == 2) return true;
        if (n % 2 == 0) return false;
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) return false;
        }
        return true;
    }
}

import java.util.*;

class Solution {
    public static int minimizeMaxDifference(int[] nums, int p) {
        if (p == 0) return 0;
        int[] a = Arrays.copyOf(nums, nums.length);
        Arrays.sort(a);
        int low = 0;
        int high = a[a.length - 1] - a[0];
        while (low < high) {
            int mid = (low + high) / 2;
            int cnt = 0;
            for (int i = 0; i + 1 < a.length; ) {
                if (a[i + 1] - a[i] <= mid) {
                    cnt++;
                    i += 2;
                } else {
                    i++;
                }
            }
            if (cnt >= p) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}

class Solution {
    public static boolean checkIfInstanceOf(Object value, Class<?> cls) {
        if (cls == null) return false;
        if (value == null) return false;
        Class<?> proto = value.getClass();
        while (proto != null) {
            if (proto == cls) return true;
            proto = proto.getSuperclass();
        }
        return false;
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;

class Solution {
    public static class TimeLimitedCache {
        private static class Entry {
            int value;
            long expire;
            ScheduledFuture<?> timeout;
            Entry(int value, long expire, ScheduledFuture<?> timeout) {
                this.value = value;
                this.expire = expire;
                this.timeout = timeout;
            }
        }
        private final Map<Integer, Entry> store = new HashMap<>();
        private int active = 0;
        private final ScheduledExecutorService scheduler = Executors.newSingleThreadScheduledExecutor();

        public boolean set(int key, int value, int duration) {
            long now = System.currentTimeMillis();
            Entry prev = store.get(key);
            boolean existed = prev != null && prev.expire > now;
            if (existed) {
                prev.timeout.cancel(false);
            } else {
                active++;
            }
            ScheduledFuture<?> future = scheduler.schedule(() -> {
                store.remove(key);
                active--;
            }, duration, TimeUnit.MILLISECONDS);
            store.put(key, new Entry(value, now + duration, future));
            return existed;
        }

        public int get(int key) {
            long now = System.currentTimeMillis();
            Entry entry = store.get(key);
            if (entry != null && entry.expire > now) {
                return entry.value;
            }
            if (entry != null) {
                entry.timeout.cancel(false);
                store.remove(key);
                active--;
            }
            return -1;
        }

        public int count() {
            return active;
        }
    }
}

import java.util.*;

class Solution {
    public static long[] sumOfDistances(int[] nums) {
        int n = nums.length;
        long[] answer = new long[n];
        Map<Integer, List<Integer>> groups = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int v = nums[i];
            groups.computeIfAbsent(v, k -> new ArrayList<>()).add(i);
        }
        for (List<Integer> positions : groups.values()) {
            int m = positions.size();
            if (m == 1) continue;
            long[] prefix = new long[m];
            for (int i = 0; i < m; i++) {
                prefix[i] = positions.get(i) + (i > 0 ? prefix[i - 1] : 0);
            }
            long total = prefix[m - 1];
            for (int i = 0; i < m; i++) {
                int pos = positions.get(i);
                long leftSum = i > 0 ? prefix[i - 1] : 0;
                long rightSum = total - prefix[i];
                int leftCnt = i;
                int rightCnt = m - i - 1;
                answer[pos] = (long) pos * leftCnt - leftSum + rightSum - (long) pos * rightCnt;
            }
        }
        return answer;
    }
}

