import java.util.*;

interface VarArgsFunction {
    Object apply(Object... args);
}

class Solution {
    public static VarArgsFunction memoize(VarArgsFunction fn) {
        return new MemoizedFunction(fn);
    }

    private static class MemoizedFunction implements VarArgsFunction {
        private final VarArgsFunction fn;
        private final Map<String, Object> cache = new HashMap<>();
        private int callCount = 0;

        MemoizedFunction(VarArgsFunction fn) {
            this.fn = fn;
        }

        public Object apply(Object... args) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < args.length; i++) {
                if (i > 0) sb.append('|');
                sb.append(String.valueOf(args[i]));
            }
            String key = sb.toString();
            if (cache.containsKey(key)) {
                return cache.get(key);
            }
            Object result = fn.apply(args);
            cache.put(key, result);
            callCount++;
            return result;
        }

        public int getCallCount() {
            return callCount;
        }
    }
}

import java.util.*;

class Solution {
    public static int[][] snail(int rowsCount, int colsCount, int[] data) {
        if (rowsCount <= 0 || colsCount <= 0 || rowsCount * colsCount != data.length) {
            return new int[0][0];
        }
        int[][] matrix = new int[rowsCount][colsCount];
        int idx = 0;
        for (int col = 0; col < colsCount; col++) {
            if (col % 2 == 0) {
                for (int row = 0; row < rowsCount; row++) {
                    matrix[row][col] = data[idx++];
                }
            } else {
                for (int row = rowsCount - 1; row >= 0; row--) {
                    matrix[row][col] = data[idx++];
                }
            }
        }
        return matrix;
    }
}

import java.util.Timer;
import java.util.TimerTask;

class Solution {
    @FunctionalInterface
    public interface VarArgsFunction {
        void apply(Object... args);
    }

    public static VarArgsFunction debounce(VarArgsFunction fn, long wait) {
        Timer timer = new Timer();
        final TimerTask[] timerId = new TimerTask[1];
        return (Object... args) -> {
            if (timerId[0] != null) {
                timerId[0].cancel();
            }
            timerId[0] = new TimerTask() {
                @Override
                public void run() {
                    fn.apply(args);
                }
            };
            timer.schedule(timerId[0], wait);
        };
    }
}

import java.util.*;

class Solution {
    public static List<Object> flattenDepth(List<?> arr, int n) {
        List<Object> result = new ArrayList<>();
        dfs(arr, 0, n, result);
        return result;
    }

    private static void dfs(List<?> subArr, int depth, int n, List<Object> result) {
        for (Object v : subArr) {
            if (v instanceof List && depth < n) {
                dfs((List<?>) v, depth + 1, n, result);
            } else {
                result.add(v);
            }
        }
    }
}

