public class Solution {
    @FunctionalInterface
    public interface Selector<T, K> {
        K apply(T item, int index, List<T> list);
    }
    public static <T, K> Map<K, List<T>> enableGroupBy(List<T> list, Selector<T, K> selector) {
        Map<K, List<T>> groups = new HashMap<>();
        for (int i = 0; i < list.size(); i++) {
            T item = list.get(i);
            K key = selector.apply(item, i, list);
            groups.computeIfAbsent(key, k -> new ArrayList<>()).add(item);
        }
        return groups;
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.function.Function;

class Solution {
    public static <R> Function<Object[], R> memoize(Function<Object[], R> fn) {
        Map<Object, Object> cache = new HashMap<>();
        final Object RESULT = new Object();
        return args -> {
            Map<Object, Object> node = cache;
            for (int i = 0; i < args.length; i++) {
                Object arg = args[i];
                if (!node.containsKey(arg)) {
                    node.put(arg, new HashMap<>());
                }
                node = (Map<Object, Object>) node.get(arg);
            }
            if (node.containsKey(RESULT)) {
                return (R) node.get(RESULT);
            }
            R result = fn.apply(args);
            node.put(RESULT, result);
            return result;
        };
    }
}

