public class Solution {
    public static <T> Function<T, T> compose(List<Function<T, T>> functions) {
        if (functions.isEmpty()) return x -> x;
        return x -> {
            for (int i = functions.size() - 1; i >= 0; i--) {
                x = functions.get(i).apply(x);
            }
            return x;
        };
    }
}

import java.util.concurrent.*;

public class Solution {
    @FunctionalInterface
    public interface AsyncFunction {
        CompletableFuture<?> apply(Object... args);
    }

    public static AsyncFunction timeLimit(AsyncFunction fn, long t) {
        return args -> {
            CompletableFuture<Object> result = new CompletableFuture<>();
            ScheduledExecutorService scheduler = Executors.newSingleThreadScheduledExecutor();
            ScheduledFuture<?> timer = scheduler.schedule(() -> result.completeExceptionally(new RuntimeException("Time Limit Exceeded")), t, TimeUnit.MILLISECONDS);
            fn.apply(args).whenComplete((value, err) -> {
                timer.cancel(false);
                scheduler.shutdown();
                if (err != null) {
                    result.completeExceptionally(err);
                } else {
                    result.complete(value);
                }
            });
            return result;
        };
    }
}

