import java.util.*;
class Graph {
    private final int n;
    private final List<List<long[]>> adj;
    public Graph(int n, int[][] edges) {
        this.n = n;
        adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) adj.get(e[0]).add(new long[]{e[1], e[2]});
    }
    public void addEdge(int[] edge) {
        adj.get(edge[0]).add(new long[]{edge[1], edge[2]});
    }
    public long shortestPath(int node1, int node2) {
        if (node1 == node2) return 0;
        long[] dist = new long[n];
        Arrays.fill(dist, Long.MAX_VALUE / 4);
        dist[node1] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>((a,b) -> Long.compare(a[0], b[0]));
        pq.offer(new long[]{0, node1});
        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            long d = cur[0]; int u = (int) cur[1];
            if (d != dist[u]) continue;
            if (u == node2) return d;
            for (long[] edge : adj.get(u)) {
                int v = (int) edge[0]; long w = edge[1];
                long nd = d + w;
                if (nd < dist[v]) { dist[v] = nd; pq.offer(new long[]{nd, v}); }
            }
        }
        return -1;
    }
}

class Solution {
    public static int[] columnWidths(Object[][] grid) {
        if (grid == null || grid.length == 0) {
            return new int[0];
        }
        int cols = grid[0].length;
        int[] ans = new int[cols];
        for (Object[] row : grid) {
            if (row == null) continue;
            for (int j = 0; j < cols; j++) {
                int len = String.valueOf(row[j]).length();
                if (len > ans[j]) {
                    ans[j] = len;
                }
            }
        }
        return ans;
    }
}

import java.util.*;

class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

class Solution {
    private static class NodeParent {
        TreeNode node;
        TreeNode parent;
        NodeParent(TreeNode n, TreeNode p) {
            node = n;
            parent = p;
        }
    }

    public static TreeNode replaceValueInTree(TreeNode root) {
        if (root == null) return null;
        Deque<NodeParent> queue = new ArrayDeque<>();
        queue.offer(new NodeParent(root, null));
        while (!queue.isEmpty()) {
            int size = queue.size();
            List<NodeParent> level = new ArrayList<>(size);
            long levelSum = 0;
            Map<TreeNode, Long> parentChildrenSum = new HashMap<>();
            for (int i = 0; i < size; i++) {
                NodeParent np = queue.poll();
                level.add(np);
                levelSum += np.node.val;
                if (np.parent != null) {
                    parentChildrenSum.put(np.parent,
                        parentChildrenSum.getOrDefault(np.parent, 0L) + np.node.val);
                }
            }
            for (NodeParent np : level) {
                long siblingGroupSum = (np.parent == null) ? np.node.val : parentChildrenSum.get(np.parent);
                np.node.val = (int) (levelSum - siblingGroupSum);
            }
            for (NodeParent np : level) {
                if (np.node.left != null) queue.offer(new NodeParent(np.node.left, np.node));
                if (np.node.right != null) queue.offer(new NodeParent(np.node.right, np.node));
            }
        }
        return root;
    }
}

public class Solution {
