        int bestDiv = 0;
        int bestScore = -1;
        for (int i = 0; i < divisors.length; i++) {
            int d = divisors[i];
            int score = 0;
            for (int j = 0; j < nums.length; j++) {
                if (nums[j] % d == 0) {
                    score++;
                }
            }
            if (score > bestScore || (score == bestScore && d < bestDiv)) {
                bestScore = score;
                bestDiv = d;
            }
        }
        return bestDiv;
    }
}

import java.util.*;

class Solution {
    public static int minimumTotalPrice(int n, int[][] edges, int[] price, int[][] trips) {
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }

        int LOG = 1;
        while ((1 << LOG) <= n) LOG++;
        int[][] up = new int[LOG][n];
        int[] depth = new int[n];
        int[] parent = new int[n];
        int[] order = new int[n];
        int idx = 0;

        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(0);
        parent[0] = -1;
        depth[0] = 0;
        while (!stack.isEmpty()) {
            int u = stack.pop();
            order[idx++] = u;
            for (int v : graph[u]) {
                if (v == parent[u]) continue;
                parent[v] = u;
                depth[v] = depth[u] + 1;
                up[0][v] = u;
                for (int k = 1; k < LOG; k++) {
                    int mid = up[k - 1][v];
                    up[k][v] = mid == -1 ? -1 : up[k - 1][mid];
                }
                stack.push(v);
            }
        }

        long[] delta = new long[n];
        for (int[] t : trips) {
            int u = t[0], v = t[1];
            delta[u]++;
            delta[v]++;
            int l = lca(u, v, depth, up, LOG);
            delta[l]--;
            if (parent[l] != -1) delta[parent[l]]--;
        }

        long[] cnt = new long[n];
        long[] dp0 = new long[n];
        long[] dp1 = new long[n];
        long totalWeight = 0;

        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            long curCnt = delta[u];
            long notSel = 0;
            long sel = 0;
            for (int v : graph[u]) {
                if (v == parent[u]) continue;
                curCnt += cnt[v];
                notSel += Math.max(dp0[v], dp1[v]);
                sel += dp0[v];
            }
            cnt[u] = curCnt;
            long w = (long) price[u] * curCnt;
            totalWeight += w;
            long saved = w / 2;
            dp0[u] = notSel;
            dp1[u] = saved + sel;
        }

        long maxSaved = Math.max(dp0[0], dp1[0]);
        long answer = totalWeight - maxSaved;
        return (int) answer;
    }

    private static int lca(int a, int b, int[] depth, int[][] up, int LOG) {
        if (depth[a] < depth[b]) {
            int tmp = a;
            a = b;
            b = tmp;
        }
        int diff = depth[a] - depth[b];
        for (int k = LOG - 1; k >= 0; k--) {
            if ((diff & (1 << k)) != 0) a = up[k][a];
        }
        if (a == b) return a;
        for (int k = LOG - 1; k >= 0; k--) {
            if (up[k][a] != up[k][b]) {
                a = up[k][a];
                b = up[k][b];
            }
        }
        return up[0][a];
    }
}

