class Solution {
    public static int findValidSplit(int[] nums) {
        int n = nums.length;
        Map<Integer, Integer> last = new HashMap<>();
        List<Integer>[] factors = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            factors[i] = new ArrayList<>();
            int x = nums[i];
            int temp = x;
            for (int p = 2; p * p <= temp; p++) {
                if (temp % p == 0) {
                    last.put(p, i);
                    factors[i].add(p);
                    while (temp % p == 0) {
                        temp /= p;
                    }
                }
            }
            if (temp > 1) {
                last.put(temp, i);
                factors[i].add(temp);
            }
        }
        int maxLast = -1;
        for (int i = 0; i < n - 1; i++) {
            for (int p : factors[i]) {
                int idx = last.get(p);
                if (idx > maxLast) {
                    maxLast = idx;
                }
            }
            if (maxLast == i) {
                return i;
            }
        }
        return -1;
    }
}

