class Solution {
    public static int[][] substringXorQueries(String s, int[][] queries) {
        int n = s.length();
        Map<Integer, int[]> best = new HashMap<>();
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '0') {
                int[] cur = best.get(0);
                if (cur == null || 1 < cur[0] || (1 == cur[0] && i < cur[1])) {
                    best.put(0, new int[]{1, i, i});
                }
                continue;
            }
            long val = 0;
            for (int j = i; j < n && j - i < 31; j++) {
                val = (val << 1) | (s.charAt(j) - '0');
                if (val > 1_000_000_000L) break;
                int v = (int) val;
                int len = j - i + 1;
                int[] cur = best.get(v);
                if (cur == null || len < cur[0] || (len == cur[0] && i < cur[1])) {
                    best.put(v, new int[]{len, i, j});
                }
            }
        }
        int[][] ans = new int[queries.length][2];
        for (int i = 0; i < queries.length; i++) {
            int xor = queries[i][0] ^ queries[i][1];
            int[] info = best.get(xor);
            if (info == null) {
                ans[i][0] = -1;
                ans[i][1] = -1;
            } else {
                ans[i][0] = info[1];
                ans[i][1] = info[2];
            }
        }
        return ans;
    }
}

