class Solution {
    public static long minCost(int[] basket1, int[] basket2) {
        Map<Integer, Integer> countA = new HashMap<>();
        Map<Integer, Integer> countB = new HashMap<>();
        int globalMin = Integer.MAX_VALUE;
        for (int v : basket1) {
            countA.put(v, countA.getOrDefault(v, 0) + 1);
            globalMin = Math.min(globalMin, v);
        }
        for (int v : basket2) {
            countB.put(v, countB.getOrDefault(v, 0) + 1);
            globalMin = Math.min(globalMin, v);
        }
        Map<Integer, Integer> total = new HashMap<>();
        for (int v : basket1) total.put(v, total.getOrDefault(v, 0) + 1);
        for (int v : basket2) total.put(v, total.getOrDefault(v, 0) + 1);
        for (int cnt : total.values()) {
            if ((cnt & 1) == 1) return -1;
        }
        List<Integer> surplusA = new ArrayList<>();
        List<Integer> surplusB = new ArrayList<>();
        for (int key : total.keySet()) {
            int diff = countA.getOrDefault(key, 0) - countB.getOrDefault(key, 0);
            if (diff > 0) {
                for (int i = 0; i < diff / 2; i++) surplusA.add(key);
            } else if (diff < 0) {
                for (int i = 0; i < (-diff) / 2; i++) surplusB.add(key);
            }
        }
        Collections.sort(surplusA);
        Collections.sort(surplusB);
        long cost = 0;
        int n = surplusA.size();
        for (int i = 0; i < n; i++) {
            int a = surplusA.get(i);
            int b = surplusB.get(i);
            int direct = Math.min(a, b);
            int viaMin = 2 * globalMin;
            cost += Math.min(direct, viaMin);
        }
        return cost;
    }
}

