class Solution {
    public static int maximizeWinFromTwoSegments(int[] prizePositions, int k) {
        int n = prizePositions.length;
        Arrays.sort(prizePositions);
        int[] window = new int[n];
        int[] next = new int[n];
        int j = 0;
        for (int i = 0; i < n; i++) {
            while (j < n && prizePositions[j] - prizePositions[i] <= k) {
                j++;
            }
            window[i] = j - i;
            next[i] = j;
        }
        int[] bestFrom = new int[n + 1];
        for (int i = n - 1; i >= 0; i--) {
            bestFrom[i] = Math.max(window[i], bestFrom[i + 1]);
        }
        int ans = 0;
        for (int i = 0; i < n; i++) {
            int total = window[i] + bestFrom[next[i]];
            if (total > ans) {
                ans = total;
            }
        }
        return ans;
    }
}

