class Solution {
    public static long countFairPairs(int[] nums, int lower, int upper) {
        Arrays.sort(nums);
        long count = 0;
        int n = nums.length;
        for (int i = 0; i < n - 1; i++) {
            int left = lowerBound(nums, i + 1, n, lower - nums[i]);
            int right = upperBound(nums, i + 1, n, upper - nums[i]);
            count += Math.max(0, right - left);
        }
        return count;
    }

    private static int lowerBound(int[] arr, int start, int end, int target) {
        int lo = start, hi = end;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    private static int upperBound(int[] arr, int start, int end, int target) {
        int lo = start, hi = end;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] <= target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }
}

