class Solution {
    public static long minCost(int[] nums, int k) {
        int n = nums.length;
        long INF = Long.MAX_VALUE / 4;
        long[] dp = new long[n + 1];
        for (int i = 0; i <= n; i++) dp[i] = INF;
        dp[0] = 0;
        for (int start = 0; start < n; start++) {
            int[] freq = new int[n];
            int trimmed = 0;
            for (int end = start; end < n; end++) {
                int val = nums[end];
                int f = ++freq[val];
                if (f == 2) {
                    trimmed += 2;
                } else if (f > 2) {
                    trimmed += 1;
                }
                long cost = (long) k + trimmed;
                long candidate = dp[start] + cost;
                if (candidate < dp[end + 1]) {
                    dp[end + 1] = candidate;
                }
            }
        }
        return dp[n];
    }
}

