class Solution {
    public static int[] vowelStrings(String[] words, int[][] queries) {
        int n = words.length;
        int[] prefixSum = new int[n];
        String vowels = "aeiou";
        for (int i = 0; i < n; i++) {
            String w = words[i];
            boolean isVowel = false;
            if (w.length() > 0) {
                char first = w.charAt(0);
                char last = w.charAt(w.length() - 1);
                if (vowels.indexOf(first) >= 0 && vowels.indexOf(last) >= 0) {
                    isVowel = true;
                }
            }
            prefixSum[i] = (i > 0 ? prefixSum[i - 1] : 0) + (isVowel ? 1 : 0);
        }
        int m = queries.length;
        int[] ans = new int[m];
        for (int i = 0; i < m; i++) {
            int left = queries[i][0];
            int right = queries[i][1];
            ans[i] = prefixSum[right] - (left > 0 ? prefixSum[left - 1] : 0);
        }
        return ans;
    }
}

