class Solution {
    public static long putMarblesInBags(int[] weights, int k) {
        int n = weights.length;
        if (k == 1) {
            return 0L;
        }
        long[] pairSums = new long[n - 1];
        for (int i = 0; i < n - 1; i++) {
            pairSums[i] = (long) weights[i] + weights[i + 1];
        }
        Arrays.sort(pairSums);
        long base = (long) weights[0] + weights[n - 1];
        long minScore = base;
        long maxScore = base;
        for (int i = 0; i < k - 1; i++) {
            minScore += pairSums[i];
            maxScore += pairSums[n - 2 - i];
        }
        return maxScore - minScore;
    }
}

