class Solution {
    public static int minOperations(int[] nums) {
        int n = nums.length;
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> nums[a] - nums[b]);
        int[] tree = new int[n + 1];
        for (int i = 0; i < n; i++) update(tree, n, i, 1);

        int cur = 0;
        long total = 0;
        for (int idx : order) {
            int activeBefore;
            if (idx >= cur) {
                activeBefore = query(tree, n, idx) - query(tree, n, cur - 1) - 1;
            } else {
                activeBefore = (query(tree, n, n - 1) - query(tree, n, cur - 1)) + query(tree, n, idx) - 1;
            }
            total += activeBefore + 1;
            update(tree, n, idx, -1);
            cur = idx + 1;
            if (cur == n) cur = 0;
        }
        return (int) total;
    }

    private static void update(int[] tree, int n, int i, int delta) {
        i++;
        while (i <= n) { tree[i] += delta; i += i & (-i); }
    }

    private static int query(int[] tree, int n, int i) {
        i++;
        int s = 0;
        while (i > 0) { s += tree[i]; i -= i & (-i); }
        return s;
    }
}

