class Solution {
    private static final int[][] DIRS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    public static int maxFish(int[][] grid) {
        if (grid == null || grid.length == 0) return 0;
        int m = grid.length;
        int n = grid[0].length;
        int maxFishCount = 0;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] > 0) {
                    int count = dfs(grid, r, c, m, n);
                    if (count > maxFishCount) maxFishCount = count;
                }
            }
        }
        return maxFishCount;
    }

    private static int dfs(int[][] grid, int r, int c, int m, int n) {
        if (r < 0 || r >= m || c < 0 || c >= n || grid[r][c] == 0) return 0;
        int fishCount = grid[r][c];
        grid[r][c] = 0;
        for (int[] dir : DIRS) {
            fishCount += dfs(grid, r + dir[0], c + dir[1], m, n);
        }
        return fishCount;
    }
}

