class Solution {
    public static int minOperations(int[] nums) {
        int n = nums.length;
        int ones = 0;
        for (int v : nums) {
            if (v == 1) {
                ones++;
            }
        }
        if (ones > 0) {
            return n - ones;
        }
        int minLen = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            int g = nums[i];
            for (int j = i; j < n; j++) {
                g = getGcd(g, nums[j]);
                if (g == 1) {
                    minLen = Math.min(minLen, j - i + 1);
                    break;
                }
            }
        }
        if (minLen == Integer.MAX_VALUE) {
            return -1;
        }
        return (minLen - 1) + (n - 1);
    }

    private static int getGcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

