        final boolean[] cancelled = new boolean[1];
        final CompletableFuture<Object> promise = new CompletableFuture<>();
        Runnable cancel = () -> {
            cancelled[0] = true;
            try {
                generator.throwException("Cancelled");
            } catch (Exception ignored) {}
        };
        java.util.function.Consumer<Result> step = new java.util.function.Consumer<Result>() {
            @Override
            public void accept(Result result) {
                if (cancelled[0]) {
                    promise.completeExceptionally(new RuntimeException("Cancelled"));
                    return;
                }
                try {
                    if (result.done) {
                        promise.complete(result.value);
                    } else {
                        Object yielded = result.value;
                        if (yielded instanceof CompletableFuture) {
                            @SuppressWarnings("unchecked")
                            CompletableFuture<Object> cf = (CompletableFuture<Object>) yielded;
                            cf.whenComplete((val, err) -> {
                                if (cancelled[0]) {
                                    promise.completeExceptionally(new RuntimeException("Cancelled"));
                                    return;
                                }
                                if (err != null) {
                                    try {
                                        Result r = generator.throwException(err);
                                        accept(r);
                                    } catch (Exception e) {
                                        promise.completeExceptionally(e);
                                    }
                                } else {
                                    try {
                                        Result r = generator.next(val);
                                        accept(r);
                                    } catch (Exception e) {
                                        promise.completeExceptionally(e);
                                    }
                                }
                            });
                        } else {
                            try {
                                Result r = generator.next(yielded);
                                accept(r);
                            } catch (Exception e) {
                                promise.completeExceptionally(e);
                            }
                        }
                    }
                } catch (Exception e) {
                    promise.completeExceptionally(e);
                }
            }
        };
        try {
            step.accept(generator.next(null));
        } catch (Exception e) {
            promise.completeExceptionally(e);
        }
        return new Object[]{cancel, promise};
    }
}

