public class Solution {
    public static int determineWinner(int[] player1, int[] player2) {
        int score1 = calculateScore(player1);
        int score2 = calculateScore(player2);
        if (score1 > score2) return 1;
        if (score2 > score1) return 2;
        return 0;
    }

    private static int calculateScore(int[] frames) {
        int score = 0;
        int limit = Math.min(10, frames.length);
        for (int i = 0; i < limit; i++) {
            int pins = frames[i];
            if (pins == 10) {
                int bonus = (i + 1 < frames.length) ? frames[i + 1] : 0;
                score += 10 + bonus;
            } else {
                score += pins;
            }
        }
        return score;
    }
}

import java.util.*;

public class Solution {
    public static long minimumCost(int[] start, int[] target, int[][] specialRoads) {
        List<int[]> points = new ArrayList<>();
        points.add(start);
        points.add(target);
        for (int[] road : specialRoads) {
            points.add(new int[]{road[0], road[1]});
            points.add(new int[]{road[2], road[3]});
        }
        Map<String, int[]> uniq = new LinkedHashMap<>();
        for (int[] p : points) {
            String key = p[0] + "," + p[1];
            if (!uniq.containsKey(key)) {
                uniq.put(key, p);
            }
        }
        points = new ArrayList<>(uniq.values());
        Map<String, Long> distances = new HashMap<>();
        for (int[] p : points) {
            distances.put(p[0] + "," + p[1], Long.MAX_VALUE);
        }
        String startKey = start[0] + "," + start[1];
        distances.put(startKey, 0L);
        class Node {
            long dist;
            int[] point;
            Node(long d, int[] p) { dist = d; point = p; }
        }
        List<Node> queue = new ArrayList<>();
        queue.add(new Node(0L, start));
        while (!queue.isEmpty()) {
            Node cur = queue.remove(0);
            long dist = cur.dist;
            int[] point = cur.point;
            String pointKey = point[0] + "," + point[1];
            if (dist > distances.get(pointKey)) {
                continue;
            }
            for (int[] road : specialRoads) {
                if (point[0] == road[0] && point[1] == road[1]) {
                    long newDist = dist + road[4];
                    int[] newPoint = new int[]{road[2], road[3]};
                    String newKey = newPoint[0] + "," + newPoint[1];
                    if (newDist < distances.get(newKey)) {
                        distances.put(newKey, newDist);
                        queue.add(new Node(newDist, newPoint));
                        queue.sort(Comparator.comparingLong(n -> n.dist));
                    }
                }
            }
            for (int[] other : points) {
                long newDist = dist + Math.abs(other[0] - point[0]) + Math.abs(other[1] - point[1]);
                String otherKey = other[0] + "," + other[1];
                if (newDist < distances.get(otherKey)) {
                    distances.put(otherKey, newDist);
                    queue.add(new Node(newDist, other));
                    queue.sort(Comparator.comparingLong(n -> n.dist));
                }
            }
        }
        String targetKey = target[0] + "," + target[1];
        return distances.get(targetKey);
    }
}

