class Solution {
    public static String smallestBeautifulString(String s, int k) {
        int n = s.length();
        char[] original = s.toCharArray();
        char limit = (char) ('a' + k - 1);
        for (int i = n - 1; i >= 0; i--) {
            for (char c = (char) (original[i] + 1); c <= limit; c++) {
                if (i > 0 && c == original[i - 1]) continue;
                char[] candidate = new char[n];
                System.arraycopy(original, 0, candidate, 0, i);
                candidate[i] = c;
                boolean possible = true;
                for (int j = i + 1; j < n; j++) {
                    char ch = 'a';
                    if (ch == candidate[j - 1]) ch++;
                    if (ch > limit) {
                        possible = false;
                        break;
                    }
                    candidate[j] = ch;
                }
                if (possible) {
                    return new String(candidate);
                }
            }
        }
        return "";
    }
}

