public class Solution {
    public static int[] findPrefixScores(int[] nums) {
        int n = nums.length;
        int[] ans = new int[n];
        long prefixSum = 0;
        long maxSum = 0;
        int currentMax = Integer.MIN_VALUE;
        for (int i = 0; i < n; i++) {
            prefixSum += nums[i];
            if (nums[i] > currentMax) {
                currentMax = nums[i];
            }
            maxSum += currentMax;
            ans[i] = (int) (prefixSum + maxSum);
        }
        return ans;
    }
}

