class Solution {
    private static long totalIncrements;

    private static long dfs(int i, int n, int[] cost) {
        int left = 2 * i + 1;
        int right = 2 * i + 2;
        if (left >= n) {
            return cost[i];
        }
        long leftSum = dfs(left, n, cost);
        long rightSum = dfs(right, n, cost);
        totalIncrements += Math.abs(leftSum - rightSum);
        return cost[i] + Math.max(leftSum, rightSum);
    }

    public static long minIncrements(int n, int[] cost) {
        totalIncrements = 0;
        if (n > 0) {
            dfs(0, n, cost);
        }
        return totalIncrements;
    }
}

