class FrequencyTracker {
    private final Map<Integer,Integer> countMap = new HashMap<>();
    private final Map<Integer,Integer> freqMap = new HashMap<>();
    public void add(int number) {
        if (countMap.containsKey(number)) {
            int old = countMap.get(number);
            freqMap.merge(old, -1, Integer::sum);
            if (freqMap.get(old) == 0) freqMap.remove(old);
        }
        countMap.merge(number, 1, Integer::sum);
        freqMap.merge(countMap.get(number), 1, Integer::sum);
    }
    public void deleteOne(int number) {
        if (countMap.containsKey(number)) {
            int old = countMap.get(number);
            freqMap.merge(old, -1, Integer::sum);
            if (freqMap.get(old) == 0) freqMap.remove(old);
            int newCount = old - 1;
            if (newCount > 0) { countMap.put(number, newCount); freqMap.merge(newCount, 1, Integer::sum); }
            else countMap.remove(number);
        }
    }
    public boolean hasFrequency(int frequency) { return freqMap.containsKey(frequency); }
}

