public class Solution {
    public static Iterator<Integer> nestedArrayGenerator(List<?> arr) {
        return new NestedArrayIterator(arr);
    }

    private static class NestedArrayIterator implements Iterator<Integer> {
        private final Deque<Iterator<?>> stack = new ArrayDeque<>();
        private Integer nextVal;
        private boolean nextReady = false;

        NestedArrayIterator(List<?> nested) {
            if (nested != null) {
                stack.push(nested.iterator());
            }
        }

        private void fetchNext() {
            while (!stack.isEmpty()) {
                Iterator<?> it = stack.peek();
                if (!it.hasNext()) {
                    stack.pop();
                    continue;
                }
                Object obj = it.next();
                if (obj == null) {
                    continue;
                }
                if (obj instanceof Integer) {
                    nextVal = (Integer) obj;
                    nextReady = true;
                    return;
                } else if (obj instanceof List) {
                    stack.push(((List<?>) obj).iterator());
                } else if (obj instanceof Object[]) {
                    stack.push(Arrays.asList((Object[]) obj).iterator());
                } else if (obj instanceof int[]) {
                    stack.push(new IntArrayIterator((int[]) obj));
                }
            }
            nextReady = false;
        }

        @Override
        public boolean hasNext() {
            if (!nextReady) {
                fetchNext();
            }
            return nextReady;
        }

        @Override
        public Integer next() {
            if (!hasNext()) {
                throw new NoSuchElementException();
            }
            nextReady = false;
            return nextVal;
        }

        private static class IntArrayIterator implements Iterator<Integer> {
            private final int[] array;
            private int index;

            IntArrayIterator(int[] array) {
                this.array = array;
            }

            @Override
            public boolean hasNext() {
                return index < array.length;
            }

            @Override
            public Integer next() {
                if (!hasNext()) {
                    throw new NoSuchElementException();
                }
                return array[index++];
            }
        }
    }
}

