class Solution {
    public static int maximumOr(int[] nums, int k) {
        int maxOr = 0;
        for (int i = 0; i < nums.length; i++) {
            int[] temp = Arrays.copyOf(nums, nums.length);
            int remainingK = k;
            int j = i;
            while (remainingK > 0 && temp[j] < (1 << 30)) {
                temp[j] *= 2;
                remainingK--;
            }
            int orValue = 0;
            for (int num : temp) {
                orValue |= num;
            }
            maxOr = Math.max(maxOr, orValue);
        }
        return maxOr;
    }
}

