class Solution {
    private static final long MOD = 1_000_000_007L;

    public static int sumOfPower(int[] nums) {
        Arrays.sort(nums);
        long total = 0;
        long s = 0; // S_j
        for (int val : nums) {
            long v = val % MOD;
            long v2 = (v * v) % MOD;
            long v3 = (v2 * v) % MOD;
            long contribution = (v3 + (v2 * s) % MOD) % MOD;
            total = (total + contribution) % MOD;
            s = ((s * 2) % MOD + v) % MOD;
        }
        return (int) total;
    }
}

