class Solution {
    public static int[] findLosers(int n, int k) {
        boolean[] visited = new boolean[n + 1];
        int current = 1;
        visited[current] = true;
        int multiplier = 1;
        while (true) {
            int steps = k * multiplier;
            current = ((current - 1 + steps) % n) + 1;
            if (visited[current]) {
                break;
            }
            visited[current] = true;
            multiplier++;
        }
        List<Integer> losers = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            if (!visited[i]) {
                losers.add(i);
            }
        }
        int[] result = new int[losers.size()];
        for (int i = 0; i < losers.size(); i++) {
            result[i] = losers.get(i);
        }
        return result;
    }
}

