class Solution {
    public static int maximumMoves(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int[][] dp = new int[m][n];
        for (int i = 0; i < m; i++) {
            Arrays.fill(dp[i], -1);
            dp[i][0] = 0;
        }
        int maxMoves = 0;
        for (int j = 1; j < n; j++) {
            for (int i = 0; i < m; i++) {
                int best = -1;
                for (int d = -1; d <= 1; d++) {
                    int k = i + d;
                    if (k < 0 || k >= m) continue;
                    if (grid[k][j - 1] < grid[i][j] && dp[k][j - 1] != -1) {
                        best = Math.max(best, dp[k][j - 1]);
                    }
                }
                if (best != -1) {
                    dp[i][j] = best + 1;
                    maxMoves = Math.max(maxMoves, dp[i][j]);
                }
            }
        }
        return maxMoves;
    }
}

