class Solution {
    public static long punishmentNumber(int n) {
        long result = 0;
        for (int i = 1; i <= n; i++) {
            long square = (long) i * i;
            if (canPartition(Long.toString(square), i)) {
                result += square;
            }
        }
        return result;
    }

    private static boolean canPartition(String s, int target) {
        return dfs(s, 0, 0, target);
    }

    private static boolean dfs(String s, int index, int currentSum, int target) {
        if (index == s.length()) {
            return currentSum == target;
        }
        for (int i = index + 1; i <= s.length(); i++) {
            int value = Integer.parseInt(s.substring(index, i));
            int newSum = currentSum + value;
            if (newSum > target) {
                break;
            }
            if (dfs(s, i, newSum, target)) {
                return true;
            }
        }
        return false;
    }
}

