class Solution {
    public static long maximumStrength(int[] nums) {
        long maxStrength = 0;
        int n = nums.length;
        int totalMasks = 1 << n;
        for (int mask = 0; mask < totalMasks; mask++) {
            long subsetProduct = 1;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    subsetProduct *= nums[i];
                }
            }
            if (subsetProduct > maxStrength) {
                maxStrength = subsetProduct;
            }
        }
        return maxStrength;
    }
}

