    public static int[][] modifiedGraphEdges(int n, int[][] edges, int source, int destination, int target) {
        List<Edge>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        Edge[] edgeRef = new Edge[edges.length];

        for (int i = 0; i < edges.length; i++) {
            int a = edges[i][0];
            int b = edges[i][1];
            int w = edges[i][2];
            Edge e1 = new Edge(b, i, w);
            Edge e2 = new Edge(a, i, w);
            e1.rev = e2;
            e2.rev = e1;
            adj[a].add(e1);
            adj[b].add(e2);
            edgeRef[i] = e1; // reference to one direction
        }

        long INF = Long.MAX_VALUE / 4;
        long[] distS = dijkstra(n, adj, source, true, INF);
        long[] distT = dijkstra(n, adj, destination, true, INF);

        if (distS[destination] > target) return new int[0][];
        if (distS[destination] == target) {
            // set all unknown edges to 1
            for (Edge e : edgeRef) {
                if (e.w == -1) {
                    e.w = 1;
                    e.rev.w = 1;
                }
            }
            return buildResult(edges, edgeRef);
        }

        // need to adjust
        long[] dist = new long[n];
        Arrays.fill(dist, INF);
        dist[source] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
        pq.offer(new long[]{0, source});

        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            long d = cur[0];
            int u = (int) cur[1];
            if (d != dist[u]) continue;
            for (Edge e : adj[u]) {
                long w;
                if (e.w != -1) {
                    w = e.w;
                } else {
                    long need = (long) target - (dist[u] + distT[e.to]);
                    if (need > 0) {
                        w = need;
                        e.w = (int) w;
                        e.rev.w = (int) w;
                    } else {
                        w = 1;
                        e.w = 1;
                        e.rev.w = 1;
                    }
                }
                long nd = d + w;
                if (nd < dist[e.to]) {
                    dist[e.to] = nd;
                    pq.offer(new long[]{nd, e.to});
                }
            }
        }

        if (dist[destination] != target) return new int[0][];

        // any remaining unknown edges set to 1
        for (Edge e : edgeRef) {
            if (e.w == -1) {
                e.w = 1;
                e.rev.w = 1;
            }
        }

        return buildResult(edges, edgeRef);
    }

    private static long[] dijkstra(int n, List<Edge>[] adj, int src, boolean treatMinusOneAsOne, long INF) {
        long[] dist = new long[n];
        Arrays.fill(dist, INF);
        dist[src] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
        pq.offer(new long[]{0, src});
        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            long d = cur[0];
            int u = (int) cur[1];
            if (d != dist[u]) continue;
            for (Edge e : adj[u]) {
                long w = e.w;
                if (w == -1 && treatMinusOneAsOne) w = 1;
                long nd = d + w;
                if (nd < dist[e.to]) {
                    dist[e.to] = nd;
                    pq.offer(new long[]{nd, e.to});
                }
            }
        }
        return dist;
    }

    private static int[][] buildResult(int[][] original, Edge[] refs) {
        int[][] res = new int[original.length][3];
        for (int i = 0; i < original.length; i++) {
            res[i][0] = original[i][0];
            res[i][1] = original[i][1];
            res[i][2] = refs[i].w;
        }
        return res;
    }
}

import java.util.*;

public class Solution {
    public static boolean gcdTraversal(int[] nums) {
        int n = nums.length;
        int[] parent = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (gcd(nums[i], nums[j]) > 1) {
                    union(parent, i, j);
                }
            }
        }
        int root = find(parent, 0);
        for (int i = 1; i < n; i++) {
            if (find(parent, i) != root) {
                return false;
            }
        }
        return true;
    }

    private static int find(int[] parent, int x) {
        if (parent[x] != x) {
            parent[x] = find(parent, parent[x]);
        }
        return parent[x];
    }

    private static void union(int[] parent, int x, int y) {
        int rootX = find(parent, x);
        int rootY = find(parent, y);
        if (rootX != rootY) {
            parent[rootX] = rootY;
        }
    }

    private static int gcd(int a, int b) {
        if (b == 0) {
            return a;
        }
        return gcd(b, a % b);
    }
}

