class Solution {
    public static int[][] diffOfDiagonals(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[][] answer = new int[m][n];
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                Set<Integer> tl = new HashSet<>(), br = new HashSet<>();
                int i = r - 1, j = c - 1;
                while (i >= 0 && j >= 0) { tl.add(grid[i][j]); i--; j--; }
                i = r + 1; j = c + 1;
                while (i < m && j < n) { br.add(grid[i][j]); i++; j++; }
                answer[r][c] = Math.abs(tl.size() - br.size());
            }
        }
        return answer;
    }
}

