class EventEmitter {
    private final Map<String, List<Function<Object[], Object>>> events = new HashMap<>();
    public Subscription subscribe(String eventName, Function<Object[], Object> callback) {
        events.computeIfAbsent(eventName, k -> new ArrayList<>()).add(callback);
        return new Subscription(eventName, callback);
    }
    public List<Object> emit(String eventName, Object[] args) {
        List<Object> results = new ArrayList<>();
        for (Function<Object[], Object> cb : events.getOrDefault(eventName, Collections.emptyList())) {
            results.add(cb.apply(args));
        }
        return results;
    }
    public class Subscription {
        private final String eventName;
        private final Function<Object[], Object> callback;
        Subscription(String eventName, Function<Object[], Object> callback) {
            this.eventName = eventName; this.callback = callback;
        }
        public void unsubscribe() {
            List<Function<Object[], Object>> list = events.get(eventName);
            if (list != null) list.remove(callback);
        }
    }
}

public class Solution {
    public static int sumInMatrix(int[][] nums) {
        if (nums == null || nums.length == 0) return 0;
        int rows = nums.length;
        int cols = nums[0].length;
        int score = 0;
        for (int c = 0; c < cols; c++) {
            int colMax = Integer.MIN_VALUE;
            for (int r = 0; r < rows; r++) {
                if (nums[r][c] > colMax) colMax = nums[r][c];
            }
            score += colMax;
        }
        return score;
    }
}

