public class Solution {
    public static int minSwaps(int[] nums) {
        int n = nums.length;
        int pos1 = -1, posN = -1;
        for (int i = 0; i < n; i++) {
            if (nums[i] == 1) {
                pos1 = i;
            } else if (nums[i] == n) {
                posN = i;
            }
        }
        int swaps = pos1 + (n - 1 - posN);
        if (pos1 > posN) {
            swaps--;
        }
        return swaps;
    }
}

import java.util.*;

class Solution {
    public static int maxCellsInMatrix(int[][] mat) {
        if (mat == null || mat.length == 0 || mat[0].length == 0) {
            return 0;
        }
        int rows = mat.length;
        int cols = mat[0].length;
        List<int[]> cells = new ArrayList<>(rows * cols);
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                cells.add(new int[]{mat[i][j], i, j});
            }
        }
        cells.sort(Comparator.comparingInt(a -> a[0]));
        int[] rowBest = new int[rows];
        int[] colBest = new int[cols];
        int[][] dp = new int[rows][cols];
        int max = 0;
        int idx = 0;
        while (idx < cells.size()) {
            int end = idx;
            while (end < cells.size() && cells.get(end)[0] == cells.get(idx)[0]) {
                end++;
            }
            for (int k = idx; k < end; k++) {
                int[] cell = cells.get(k);
                int r = cell[1];
                int c = cell[2];
                dp[r][c] = 1 + Math.max(rowBest[r], colBest[c]);
                if (dp[r][c] > max) {
                    max = dp[r][c];
                }
            }
            for (int k = idx; k < end; k++) {
                int[] cell = cells.get(k);
                int r = cell[1];
                int c = cell[2];
                if (dp[r][c] > rowBest[r]) {
                    rowBest[r] = dp[r][c];
                }
                if (dp[r][c] > colBest[c]) {
                    colBest[c] = dp[r][c];
                }
            }
            idx = end;
        }
        return max;
    }
}

