import java.util.Arrays;

class Solution {
    public static long sumOfMatrixAfterQueries(int n, int[][] queries) {
        int[][] matrix = new int[n][n];
        long sum = 0;
        for (int[] q : queries) {
            int type = q[0];
            int idx = q[1];
            int val = q[2];
            if (type == 0) {
                long oldRowSum = 0;
                for (int v : matrix[idx]) {
                    oldRowSum += v;
                }
                sum -= oldRowSum;
                Arrays.fill(matrix[idx], val);
                sum += (long) val * n;
            } else {
                long oldColSum = 0;
                for (int i = 0; i < n; i++) {
                    oldColSum += matrix[i][idx];
                }
                sum -= oldColSum;
                for (int i = 0; i < n; i++) {
                    matrix[i][idx] = val;
                }
                sum += (long) val * n;
            }
        }
        return sum;
    }
}

import java.util.*;

class Solution {
    private static final int MOD = 1_000_000_007;
    private static int minSum;
    private static int maxSum;
    private static String bound;
    private static int[][][] memo;

    public static int countGoodIntegers(String num1, String num2, int min_sum, int max_sum) {
        minSum = min_sum;
        maxSum = max_sum;
        int countUpToNum2 = countUpTo(num2);
        String num1MinusOne = subtractOne(num1);
        int countUpToNum1MinusOne = countUpTo(num1MinusOne);
        int result = countUpToNum2 - countUpToNum1MinusOne;
        if (result < 0) result += MOD;
        return result;
    }

    private static int countUpTo(String s) {
        bound = s;
        int n = bound.length();
        memo = new int[n][maxSum + 1][2];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= maxSum; j++) {
                Arrays.fill(memo[i][j], -1);
            }
        }
        return (int) dfs(0, 0, 1);
    }

    private static long dfs(int pos, int sum, int tight) {
        if (sum > maxSum) return 0;
        if (pos == bound.length()) {
            return (sum >= minSum) ? 1 : 0;
        }
        if (memo[pos][sum][tight] != -1) return memo[pos][sum][tight];
        int limit = tight == 1 ? bound.charAt(pos) - '0' : 9;
        long res = 0;
        for (int d = 0; d <= limit; d++) {
            int nextTight = (tight == 1 && d == limit) ? 1 : 0;
            res += dfs(pos + 1, sum + d, nextTight);
            if (res >= MOD) res -= MOD;
        }
        memo[pos][sum][tight] = (int) res;
        return res;
    }

    private static String subtractOne(String s) {
        StringBuilder sb = new StringBuilder(s);
        int i = sb.length() - 1;
        while (i >= 0 && sb.charAt(i) == '0') {
            sb.setCharAt(i, '9');
            i--;
        }
        if (i >= 0) {
            sb.setCharAt(i, (char) (sb.charAt(i) - 1));
        }
        // Remove leading zeros
        int start = 0;
        while (start < sb.length() - 1 && sb.charAt(start) == '0') {
            start++;
        }
        return sb.substring(start);
    }
}

