class Solution {
    public static CompletableFuture<Map<String, Object>> promiseAll(List<Supplier<CompletableFuture<Object>>> functions) {
        int n = functions.size();
        AtomicInteger resolvedCount = new AtomicInteger(0);
        Object[] results = new Object[n];
        long startTime = System.currentTimeMillis();
        CompletableFuture<Map<String, Object>> main = new CompletableFuture<>();
        if (n == 0) {
            Map<String, Object> map = new HashMap<>();
            map.put("t", 0L);
            map.put("resolved", Collections.emptyList());
            main.complete(map);
            return main;
        }
        for (int i = 0; i < n; i++) {
            final int index = i;
            Supplier<CompletableFuture<Object>> func = functions.get(i);
            CompletableFuture<Object> cf = func.get();
            cf.whenComplete((result, throwable) -> {
                if (throwable == null) {
                    results[index] = result;
                    if (resolvedCount.incrementAndGet() == n) {
                        long timeTaken = System.currentTimeMillis() - startTime;
                        Map<String, Object> map = new HashMap<>();
                        map.put("t", timeTaken);
                        map.put("resolved", Arrays.asList(results));
                        main.complete(map);
                    }
                } else {
                    long timeTaken = System.currentTimeMillis() - startTime;
                    Map<String, Object> map = new HashMap<>();
                    map.put("t", timeTaken);
                    map.put("rejected", throwable);
                    main.complete(map);
                }
            });
        }
        return main;
    }
}

