class Solution {
    public static boolean isFascinating(int n) {
        Set<Integer> digitSet = new HashSet<>();
        String concatenated = "" + n + (2 * n) + (3 * n);
        for (int i = 0; i < concatenated.length(); i++) {
            int digit = concatenated.charAt(i) - '0';
            if (digit >= 1 && digit <= 9) {
                digitSet.add(digit);
            } else {
