class Solution {
    public static long robotDistances(int[] nums, String s, int d) {
        final long MOD = 1_000_000_007L;
        int n = nums.length;
        long[] positions = new long[n];
        for (int i = 0; i < n; i++) positions[i] = nums[i];
        char[] dirs = s.toCharArray();
        for (int step = 0; step < d; step++) {
            for (int i = 0; i < n; i++) {
                positions[i] += dirs[i] == 'L' ? -1 : 1;
            }
            HashMap<Long, ArrayList<Integer>> map = new HashMap<>();
            for (int i = 0; i < n; i++) {
                long p = positions[i];
                map.computeIfAbsent(p, k -> new ArrayList<>()).add(i);
            }
            for (ArrayList<Integer> list : map.values()) {
                if (list.size() > 1) {
                    for (int idx : list) {
                        dirs[idx] = dirs[idx] == 'L' ? 'R' : 'L';
                    }
                }
            }
        }
        Arrays.sort(positions);
        long total = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                total = (total + Math.abs(positions[i] - positions[j])) % MOD;
            }
        }
        return total;
    }
}

public class Solution {
    public static int longestSemiRepetitiveSubstring(String s) {
        int maxLength = 0;
        for (int i = 0; i < s.length(); i++) {
            for (int j = i + 1; j <= s.length(); j++) {
                String substring = s.substring(i, j);
                int count = 0;
                char prev = '\0';
                for (int k = 0; k < substring.length(); k++) {
                    char c = substring.charAt(k);
                    if (c == prev) {
                        count++;
                    }
                    prev = c;
                }
                if (count <= 1) {
                    maxLength = Math.max(maxLength, substring.length());
                }
            }
        }
        return maxLength;
    }
}

