class Solution {
    public static String lexicographicallySmallestString(String s) {
        char[] arr = s.toCharArray();
        int n = arr.length;
        int i = 0;
        while (i < n && arr[i] == 'a') {
            i++;
        }
        if (i == n) {
            arr[n - 1] = 'z';
        } else {
            while (i < n && arr[i] != 'a') {
                arr[i] = (char) (arr[i] - 1);
                i++;
            }
        }
        return new String(arr);
    }
}

