import java.util.*;

class Solution {
    private static final int MOD = 1_000_000_007;
    private static int n;
    private static long[][] memo;
    private static boolean[][] can;

    public static int countSpecialPermutations(int[] nums) {
        n = nums.length;
        can = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                can[i][j] = (nums[i] % nums[j] == 0) || (nums[j] % nums[i] == 0);
            }
        }
        int fullMask = (1 << n) - 1;
        memo = new long[1 << n][n];
        for (long[] row : memo) Arrays.fill(row, -1);
        long result = 0;
        for (int i = 0; i < n; i++) {
            result = (result + dfs(1 << i, i, fullMask)) % MOD;
        }
        return (int) result;
    }

    private static long dfs(int mask, int last, int fullMask) {
        if (mask == fullMask) return 1;
        if (memo[mask][last] != -1) return memo[mask][last];
        long ways = 0;
        for (int nxt = 0; nxt < n; nxt++) {
            if ((mask & (1 << nxt)) == 0 && can[last][nxt]) {
                ways = (ways + dfs(mask | (1 << nxt), nxt, fullMask)) % MOD;
            }
        }
        memo[mask][last] = ways;
        return ways;
    }
}

