class Solution {
    public static int longestEvenOddSubarray(int[] nums, int threshold) {
        int best = 0;
        int len = 0;
        int prevParity = -1;
        for (int num : nums) {
            if (num > threshold) {
                len = 0;
                prevParity = -1;
                continue;
            }
            int curParity = num & 1;
            if (len == 0) {
                if (curParity == 0) {
                    len = 1;
                    prevParity = curParity;
                }
            } else {
                if (curParity == prevParity) {
                    if (curParity == 0) {
                        len = 1;
                        prevParity = curParity;
                    } else {
                        len = 0;
                        prevParity = -1;
                    }
                } else {
                    len++;
                    prevParity = curParity;
                }
            }
            if (len > best) best = len;
        }
        return best;
    }
}

