class Solution {
    public static int[] relocateMarbles(int[] nums, int[] moveFrom, int[] moveTo) {
        Set<Integer> occupied = new HashSet<>();
        for (int num : nums) {
            occupied.add(num);
        }
        for (int i = 0; i < moveFrom.length; i++) {
            int src = moveFrom[i];
            int dst = moveTo[i];
            if (occupied.contains(src)) {
                occupied.remove(src);
                occupied.add(dst);
            }
        }
        List<Integer> list = new ArrayList<>(occupied);
        Collections.sort(list);
        int[] result = new int[list.size()];
        for (int i = 0; i < list.size(); i++) {
            result[i] = list.get(i);
        }
        return result;
    }
}

