class Solution {
    public static List<int[]> primePairs(int n) {
        if (n < 4) return new ArrayList<>();
        byte[] isPrime = new byte[n + 1];
        for (int i = 2; i <= n; i++) isPrime[i] = 1;
        for (int p = 2; p * p <= n; p++) {
            if (isPrime[p] == 1) {
                for (int m = p * p; m <= n; m += p) {
                    isPrime[m] = 0;
                }
            }
        }
        List<int[]> result = new ArrayList<>();
        for (int x = 2; x <= n / 2; x++) {
            int y = n - x;
            if (isPrime[x] == 1 && isPrime[y] == 1) {
                result.add(new int[]{x, y});
            }
        }
        return result;
    }
}

import java.util.*;

class Solution {
    public static int minimumLength(String[] words) {
        int n = words.length;
        int totalLen = 0;
        for (String w : words) totalLen += w.length();
        int[][] match = new int[n][n];
        for (int i = 0; i < n; i++) {
            char end = words[i].charAt(words[i].length() - 1);
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                char start = words[j].charAt(0);
                match[i][j] = (end == start) ? 1 : 0;
            }
        }
        int size = 1 << n;
        int[][] dp = new int[size][n];
        for (int[] row : dp) Arrays.fill(row, -1);
        for (int i = 0; i < n; i++) dp[1 << i][i] = 0;
        for (int mask = 0; mask < size; mask++) {
            for (int last = 0; last < n; last++) {
                if ((mask & (1 << last)) == 0 || dp[mask][last] < 0) continue;
                for (int nxt = 0; nxt < n; nxt++) {
                    if ((mask & (1 << nxt)) != 0) continue;
                    int newMask = mask | (1 << nxt);
                    int val = dp[mask][last] + match[last][nxt];
                    if (val > dp[newMask][nxt]) dp[newMask][nxt] = val;
                }
            }
        }
        int fullMask = size - 1;
        int maxMatches = 0;
        for (int i = 0; i < n; i++) {
            maxMatches = Math.max(maxMatches, dp[fullMask][i]);
        }
        return totalLen - maxMatches;
    }
}

