import java.math.BigInteger;

class Solution {
    public static int minBeautifulSubstrings(String s) {
        int n = s.length();
        List<String> powers = new ArrayList<>();
        BigInteger val = BigInteger.ONE;
        while (true) {
            String bin = val.toString(2);
            if (bin.length() > n) break;
            powers.add(bin);
            val = val.multiply(BigInteger.valueOf(5));
        }
        int INF = n + 1;
        int[] dp = new int[n + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int i = 1; i <= n; i++) {
            for (String b : powers) {
                int len = b.length();
                if (len <= i && s.regionMatches(i - len, b, 0, len)) {
                    if (dp[i - len] != INF) {
                        dp[i] = Math.min(dp[i], dp[i - len] + 1);
                    }
                }
            }
        }
        return dp[n] == INF ? -1 : dp[n];
    }
}

import java.util.*;

class Solution {
    public static int maxJumps(int[] nums, int target) {
        int n = nums.length;
        if (n == 0) return -1;
        if (n == 1) return 0;
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        int[] uniq = new int[n];
        int uniqCount = 0;
        for (int v : sorted) {
            if (uniqCount == 0 || v != uniq[uniqCount - 1]) {
                uniq[uniqCount++] = v;
            }
        }
        int size = uniqCount;
        int[] seg = new int[4 * size];
        Arrays.fill(seg, Integer.MIN_VALUE);
        int[] dp = new int[n];
        Arrays.fill(dp, Integer.MIN_VALUE);
        dp[0] = 0;
        int idx0 = Arrays.binarySearch(uniq, 0, uniqCount, nums[0]);
        update(seg, 1, 0, size - 1, idx0, 0);
        for (int i = 1; i < n; i++) {
            int lowVal = nums[i] - target;
            int highVal = nums[i] + target;
            int l = lowerBound(uniq, uniqCount, lowVal);
            int r = upperBound(uniq, uniqCount, highVal) - 1;
            int best = Integer.MIN_VALUE;
            if (l <= r) {
                best = query(seg, 1, 0, size - 1, l, r);
            }
            if (best != Integer.MIN_VALUE) {
                dp[i] = best + 1;
            }
            int idx = Arrays.binarySearch(uniq, 0, uniqCount, nums[i]);
            update(seg, 1, 0, size - 1, idx, dp[i]);
        }
        return dp[n - 1] == Integer.MIN_VALUE ? -1 : dp[n - 1];
    }

    private static int lowerBound(int[] arr, int len, int key) {
        int l = 0, r = len;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (arr[m] < key) l = m + 1;
            else r = m;
        }
        return l;
    }

    private static int upperBound(int[] arr, int len, int key) {
        int l = 0, r = len;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (arr[m] <= key) l = m + 1;
            else r = m;
        }
        return l;
    }

    private static void update(int[] seg, int node, int l, int r, int pos, int val) {
        if (l == r) {
            seg[node] = Math.max(seg[node], val);
            return;
        }
        int mid = (l + r) >>> 1;
        if (pos <= mid) update(seg, node * 2, l, mid, pos, val);
        else update(seg, node * 2 + 1, mid + 1, r, pos, val);
        seg[node] = Math.max(seg[node * 2], seg[node * 2 + 1]);
    }

    private static int query(int[] seg, int node, int l, int r, int ql, int qr) {
        if (ql > r || qr < l) return Integer.MIN_VALUE;
        if (ql <= l && r <= qr) return seg[node];
        int mid = (l + r) >>> 1;
        int left = query(seg, node * 2, l, mid, ql, qr);
        int right = query(seg, node * 2 + 1, mid + 1, r, ql, qr);
        return Math.max(left, right);
    }
}

class Solution {
    public int sumImbalanceNumbers(int[] nums) {
        int n = nums.length;
        int total = 0;
        for (int i = 0; i < n; i++) {
            TreeSet<Integer> set = new TreeSet<>();
            int imbalance = 0;
            for (int j = i; j < n; j++) {
                int x = nums[j];
                if (set.contains(x)) {
                    total += imbalance;
                    continue;
                }
                Integer lower = set.lower(x);
                Integer higher = set.higher(x);
                if (lower != null && higher != null) {
                    if (higher - lower > 1) imbalance--; // the gap they used to form is now split
                    if (x - lower > 1) imbalance++;
                    if (higher - x > 1) imbalance++;
                } else if (lower != null) {
                    if (x - lower > 1) imbalance++;
                } else if (higher != null) {
                    if (higher - x > 1) imbalance++;
                }
                set.add(x);
                total += imbalance;
            }
        }
        return total;
    }
}

public class Solution {
    public static boolean checkArray(int[] nums, int k) {
        int n = nums.length;
        long[] expire = new long[k];
        long cur = 0;
        for (int i = 0; i < n; i++) {
            cur -= expire[i % k];
            expire[i % k] = 0;
            long need = nums[i] - cur;
            if (need < 0) {
                return false;
            }
            if (need > 0) {
                if (i + k > n) {
                    return false;
                }
                cur += need;
                expire[(i + k) % k] = need;
            }
        }
        return true;
    }
}

import java.util.*;

class Solution {
    public static int[] numberOfBlackBlocks(int m, int n, int[][] coordinates) {
        Map<Integer, Integer> blockCount = new HashMap<>();
        for (int i = 0; i < coordinates.length; i++) {
            int x = coordinates[i][0];
            int y = coordinates[i][1];
            for (int dx = -1; dx <= 0; dx++) {
                int r = x + dx;
                if (r < 0 || r >= m - 1) continue;
                for (int dy = -1; dy <= 0; dy++) {
                    int c = y + dy;
                    if (c < 0 || c >= n - 1) continue;
                    int key = r * n + c;
                    blockCount.put(key, blockCount.getOrDefault(key, 0) + 1);
                }
            }
        }
        int[] ans = new int[5];
        int totalBlocks = Math.max(0, (m - 1) * (n - 1));
        ans[0] = totalBlocks - blockCount.size();
        for (int cnt : blockCount.values()) {
            ans[cnt]++;
        }
        return ans;
    }
}

public class Solution {
    public static int longestNonDecreasingSubarray(int[] nums1, int[] nums2) {
        int n = nums1.length;
        if (n == 0) return 0;
        int prev1 = 1, prev2 = 1;
        int answer = 1;
        for (int i = 1; i < n; i++) {
            int cur1 = 1;
            if (nums1[i - 1] <= nums1[i]) cur1 = Math.max(cur1, prev1 + 1);
            if (nums2[i - 1] <= nums1[i]) cur1 = Math.max(cur1, prev2 + 1);
            int cur2 = 1;
            if (nums1[i - 1] <= nums2[i]) cur2 = Math.max(cur2, prev1 + 1);
            if (nums2[i - 1] <= nums2[i]) cur2 = Math.max(cur2, prev2 + 1);
            answer = Math.max(answer, Math.max(cur1, cur2));
            prev1 = cur1;
            prev2 = cur2;
        }
        return answer;
    }
}

