class Solution {
    public static int maxBeauty(int[] nums, int k) {
        List<int[]> events = new ArrayList<>();
        for (int num : nums) {
            int l = num - k;
            int r = num + k;
            events.add(new int[]{l, 1});
            events.add(new int[]{r + 1, -1});
        }
        events.sort((a, b) -> {
            if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
            return Integer.compare(a[1], b[1]);
        });
        int cur = 0, best = 0;
        for (int[] e : events) {
            cur += e[1];
            if (cur > best) best = cur;
        }
        return best;
    }
}

public class Solution {
    public static long sumOfSquaresSpecial(int[] nums) {
        int n = nums.length;
        long total = 0;
        for (int d = 1; d * d <= n; d++) {
            if (n % d == 0) {
                total += (long) nums[d - 1] * nums[d - 1];
                int other = n / d;
                if (other != d) {
                    total += (long) nums[other - 1] * nums[other - 1];
                }
            }
        }
        return total;
    }
}

class Solution {
    public static boolean isGoodArray(int[] nums) {
        if (nums.length == 0) return false;
        int max = 0;
        for (int v : nums) {
            if (v > max) max = v;
        }
        if (nums.length != max + 1) return false;
        int[] freq = new int[max + 1];
        for (int v : nums) {
            if (v < 1 || v > max) return false;
            freq[v]++;
        }
        for (int i = 1; i < max; i++) {
            if (freq[i] != 1) return false;
        }
        if (freq[max] != 2) return false;
        return true;
    }
}

class Solution {
    public static int minValidSplit(int[] nums) {
        int candidate = 0;
        int cnt = 0;
        for (int v : nums) {
            if (cnt == 0) {
                candidate = v;
                cnt = 1;
            } else if (v == candidate) {
                cnt++;
            } else {
                cnt--;
            }
        }
        int d = candidate;
        int total = 0;
        for (int v : nums) {
            if (v == d) total++;
        }
        int leftCnt = 0;
        int n = nums.length;
        for (int i = 0; i < n - 1; i++) {
            if (nums[i] == d) leftCnt++;
            int leftLen = i + 1;
            int rightLen = n - leftLen;
            if (leftCnt * 2 > leftLen && (total - leftCnt) * 2 > rightLen) {
                return i;
            }
        }
        return -1;
    }
}

