class ListNode {
    int val;
    ListNode next;
    ListNode(int x) { val = x; }
}

class Solution {
    public static int longestValidSubstring(String word, List<String> forbidden) {
        class Node {
            Map<Character, Integer> next = new HashMap<>();
            int fail = 0;
            List<Integer> out = new ArrayList<>();
        }

        List<Node> nodes = new ArrayList<>();
        nodes.add(new Node());

        for (String pat : forbidden) {
            int cur = 0;
            for (char ch : pat.toCharArray()) {
                Node curNode = nodes.get(cur);
                if (!curNode.next.containsKey(ch)) {
                    curNode.next.put(ch, nodes.size());
                    nodes.add(new Node());
                }
                cur = curNode.next.get(ch);
            }
            nodes.get(cur).out.add(pat.length());
        }

        Deque<Integer> queue = new ArrayDeque<>();
        for (Map.Entry<Character, Integer> entry : nodes.get(0).next.entrySet()) {
            int nxt = entry.getValue();
            nodes.get(nxt).fail = 0;
            queue.add(nxt);
        }

        while (!queue.isEmpty()) {
            int v = queue.poll();
            for (Map.Entry<Character, Integer> entry : nodes.get(v).next.entrySet()) {
                char ch = entry.getKey();
                int u = entry.getValue();
                int f = nodes.get(v).fail;
                while (f != 0 && !nodes.get(f).next.containsKey(ch)) {
                    f = nodes.get(f).fail;
                }
                if (nodes.get(f).next.containsKey(ch)) {
                    f = nodes.get(f).next.get(ch);
                }
                nodes.get(u).fail = f;
                nodes.get(u).out.addAll(nodes.get(f).out);
                queue.add(u);
            }
        }

        int state = 0;
        int lastBad = -1;
        int best = 0;

        for (int i = 0; i < word.length(); ++i) {
            char ch = word.charAt(i);
            while (state != 0 && !nodes.get(state).next.containsKey(ch)) {
                state = nodes.get(state).fail;
            }
            if (nodes.get(state).next.containsKey(ch)) {
                state = nodes.get(state).next.get(ch);
            }
            for (int len : nodes.get(state).out) {
                int badStart = i - len + 1;
                if (badStart > lastBad) {
                    lastBad = badStart;
                }
            }
            int curLen = i - lastBad;
            if (curLen > best) {
                best = curLen;
            }
        }
        return best;
    }
}

class Solution {
    public static long maxScore(int[] nums, int x) {
        int n = nums.length;
        long NEG = Long.MIN_VALUE / 4;
        long bestEven = NEG, bestOdd = NEG;
        long ans = nums[0];
        if ((nums[0] & 1) == 0) bestEven = nums[0];
        else bestOdd = nums[0];
        for (int i = 1; i < n; i++) {
            boolean isEven = (nums[i] & 1) == 0;
            long same = isEven ? bestEven : bestOdd;
            long opp = isEven ? bestOdd : bestEven;
            long cand = same;
            if (opp != NEG) cand = Math.max(cand, opp - x);
            long dp = nums[i] + cand;
            if (isEven) bestEven = Math.max(bestEven, dp);
            else bestOdd = Math.max(bestOdd, dp);
            ans = Math.max(ans, dp);
        }
        return ans;
    }
}

