class Solution {
    public static int maxPossibleElement(int[] nums) {
        if (nums == null || nums.length == 0) {
            return 0;
        }
        int[] stack = new int[nums.length];
        int top = -1;
        int max = 0;
        for (int i = nums.length - 1; i >= 0; i--) {
            int cur = nums[i];
            while (top >= 0 && cur <= stack[top]) {
                cur += stack[top--];
            }
            stack[++top] = cur;
            if (cur > max) {
                max = cur;
            }
        }
        return max;
    }
}

