class Solution {
    public static String sortVowels(String s) {
        char[] vowels = {'A','E','I','O','U','a','e','i','o','u'};
        Set<Character> isVowel = new HashSet<>();
        for (char v : vowels) {
            isVowel.add(v);
        }
        int[] cnt = new int[10];
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (isVowel.contains(ch)) {
                for (int j = 0; j < vowels.length; j++) {
                    if (vowels[j] == ch) {
                        cnt[j]++;
                        break;
                    }
                }
            }
        }
        int idx = 0;
        StringBuilder res = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (!isVowel.contains(ch)) {
                res.append(ch);
            } else {
                while (cnt[idx] == 0) {
                    idx++;
                }
                res.append(vowels[idx]);
                cnt[idx]--;
            }
        }
        return res.toString();
    }
}

