class Solution {
    public static long countPalindromePairs(int[] parent, String s) {
        int n = parent.length;
        List<int[]>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int i = 1; i < n; i++) {
            int p = parent[i];
            int bit = 1 << (s.charAt(i) - 'a');
            adj[p].add(new int[]{i, bit});
            adj[i].add(new int[]{p, bit});
        }

        Map<Integer, Integer> freq = new HashMap<>();
        long ans = 0L;

        int[] stackNode = new int[n];
        int[] stackMask = new int[n];
        int[] stackParent = new int[n];
        int sp = 0;
        stackNode[sp] = 0;
        stackMask[sp] = 1 << (s.charAt(0) - 'a');
        stackParent[sp] = -1;
        sp++;

        while (sp > 0) {
            sp--;
            int node = stackNode[sp];
            int mask = stackMask[sp];
            int par = stackParent[sp];

            int same = freq.getOrDefault(mask, 0);
            ans += same;
            for (int b = 0; b < 26; b++) {
                int m2 = mask ^ (1 << b);
                ans += freq.getOrDefault(m2, 0);
            }
            freq.put(mask, same + 1);

            for (int[] e : adj[node]) {
                int nb = e[0];
                if (nb == par) continue;
                int nmask = mask ^ e[1];
                stackNode[sp] = nb;
                stackMask[sp] = nmask;
                stackParent[sp] = node;
                sp++;
            }
        }

        return ans;
    }
}

import java.lang.Math;

class Solution {
    public static int countWays(int n, int x) {
        final int MOD = 1_000_000_007;
        int maxBase = (int) Math.floor(Math.pow(n, 1.0 / x));
        int[] dp = new int[n + 1];
        dp[0] = 1;
        for (int i = 1; i <= maxBase; ++i) {
            long v = (long) Math.pow(i, x);
            if (v > n) continue;
            int vi = (int) v;
            for (int s = n; s >= vi; --s) {
                int sum = dp[s] + dp[s - vi];
                if (sum >= MOD) sum -= MOD;
                dp[s] = sum;
            }
        }
        return dp[n];
    }
}

