class Solution {
    public static long countCompleteSubarrays(int[] nums) {
        int n = nums.length;
        Set<Integer> unique = new HashSet<>();
        for (int v : nums) {
            unique.add(v);
        }
        int required = unique.size();
        Map<Integer, Integer> freq = new HashMap<>();
        int distinct = 0;
        int right = 0;
        long answer = 0;
        for (int left = 0; left < n; left++) {
            while (right < n && distinct < required) {
                int v = nums[right];
                int cnt = freq.getOrDefault(v, 0) + 1;
                freq.put(v, cnt);
                if (cnt == 1) {
                    distinct++;
                }
                right++;
            }
            if (distinct == required) {
                answer += n - (right - 1);
            } else {
                break;
            }
            int vL = nums[left];
            int cntL = freq.get(vL) - 1;
            if (cntL == 0) {
                freq.remove(vL);
                distinct--;
            } else {
                freq.put(vL, cntL);
            }
        }
        return answer;
    }
}

