class Solution {
    private static boolean isSub(String t, String s) {
        return t.indexOf(s) != -1;
    }

    private static String merge(String s, String t) {
        if (isSub(s, t)) return s;
        int max = 0;
        int limit = Math.min(s.length(), t.length());
        for (int k = limit; k > 0; k--) {
            if (s.regionMatches(s.length() - k, t, 0, k)) {
                max = k;
                break;
            }
        }
        return s + t.substring(max);
    }

    private static void dfs(List<String> filtered, boolean[] used, List<String> cur, List<List<String>> perms) {
        if (cur.size() == filtered.size()) {
            perms.add(new ArrayList<>(cur));
            return;
        }
        for (int i = 0; i < filtered.size(); i++) {
            if (!used[i]) {
                used[i] = true;
                cur.add(filtered.get(i));
                dfs(filtered, used, cur, perms);
                cur.remove(cur.size() - 1);
                used[i] = false;
            }
        }
    }

    public static String shortestString(String a, String b, String c) {
        String[] arr = new String[]{a, b, c};
        List<String> filtered = new ArrayList<>();
        for (int i = 0; i < 3; i++) {
            boolean keep = true;
            for (int j = 0; j < 3; j++) {
                if (i != j && isSub(arr[j], arr[i])) {
                    keep = false;
                    break;
                }
            }
            if (keep) filtered.add(arr[i]);
        }

        int n = filtered.size();
        if (n == 0) return "";
        if (n == 1) return filtered.get(0);

        List<List<String>> perms = new ArrayList<>();
        boolean[] used = new boolean[n];
        List<String> cur = new ArrayList<>();
        dfs(filtered, used, cur, perms);

        String best = null;
        for (List<String> p : perms) {
            String merged = p.get(0);
            for (int i = 1; i < p.size(); i++) {
                merged = merge(merged, p.get(i));
            }
            if (best == null || merged.length() < best.length() ||
                (merged.length() == best.length() && merged.compareTo(best) < 0)) {
                best = merged;
            }
        }
        return best;
    }
}

