class Solution {
    private static final long MOD = 1_000_000_007L;

    private static long countUpTo(String s) {
        int n = s.length();
        long[][][] dp = new long[2][11][2];
        dp[1][10][0] = 1;
        for (int pos = 0; pos < n; pos++) {
            long[][][] ndp = new long[2][11][2];
            int boundDigit = s.charAt(pos) - '0';
            for (int tight = 0; tight <= 1; tight++) {
                for (int prev = 0; prev <= 10; prev++) {
                    for (int started = 0; started <= 1; started++) {
                        long cur = dp[tight][prev][started];
                        if (cur == 0) continue;
                        int limit = tight == 1 ? boundDigit : 9;
                        if (started == 0) {
                            // stay not started with digit 0
                            int nt = (tight == 1 && 0 == limit) ? 1 : 0;
                            ndp[nt][10][0] = (ndp[nt][10][0] + cur) % MOD;
                            // start with non-zero digit
                            for (int d = 1; d <= limit; d++) {
                                nt = (tight == 1 && d == limit) ? 1 : 0;
                                ndp[nt][d][1] = (ndp[nt][d][1] + cur) % MOD;
                            }
                        } else {
                            int prevDigit = prev;
                            for (int d = 0; d <= 9; d++) {
                                if (Math.abs(d - prevDigit) != 1) continue;
                                if (d > limit) continue;
                                int nt = (tight == 1 && d == limit) ? 1 : 0;
                                ndp[nt][d][1] = (ndp[nt][d][1] + cur) % MOD;
                            }
                        }
                    }
                }
            }
            dp = ndp;
        }
        long ans = 0;
        for (int tight = 0; tight <= 1; tight++) {
            for (int prev = 0; prev <= 9; prev++) {
                ans = (ans + dp[tight][prev][1]) % MOD;
            }
        }
        return ans;
    }

    private static String subtractOne(String s) {
        StringBuilder sb = new StringBuilder(s);
        int i = sb.length() - 1;
        while (i >= 0 && sb.charAt(i) == '0') {
            sb.setCharAt(i, '9');
            i--;
        }
        if (i < 0) {
            return "0";
        }
        sb.setCharAt(i, (char) (sb.charAt(i) - 1));
        int start = 0;
        while (start < sb.length() - 1 && sb.charAt(start) == '0') {
            start++;
        }
        return sb.substring(start);
    }

    public int countSteppingNumbers(String low, String high) {
        long highCount = countUpTo(high);
        String lowMinusOne = subtractOne(low);
        long lowCount = countUpTo(lowMinusOne);
        long ans = (highCount - lowCount) % MOD;
        if (ans < 0) ans += MOD;
        return (int) ans;
    }
}

