class Solution {
    public static long maxElegance(int[][] items, int k) {
        Arrays.sort(items, (a, b) -> Integer.compare(b[0], a[0]));
        Set<Integer> seen = new HashSet<>();
        PriorityQueue<Integer> dupHeap = new PriorityQueue<>();
        long profitSum = 0;
        int distinct = 0;
        for (int i = 0; i < k; ++i) {
            int p = items[i][0];
            int c = items[i][1];
            profitSum += p;
            if (seen.contains(c)) {
                dupHeap.add(p);
            } else {
                seen.add(c);
                ++distinct;
            }
        }
        long best = profitSum + (long) distinct * distinct;
        for (int i = k; i < items.length; ++i) {
            int p = items[i][0];
            int c = items[i][1];
            if (seen.contains(c)) continue;
            if (dupHeap.isEmpty()) break;
            int removed = dupHeap.poll();
            profitSum = profitSum - removed + p;
            seen.add(c);
            ++distinct;
            long cur = profitSum + (long) distinct * distinct;
            if (cur > best) best = cur;
        }
        return best;
    }
}

