class Solution {
    public static int minimumSeconds(int[] nums) {
        int n = nums.length;
        Map<Integer, Info> map = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int val = nums[i];
            Info info = map.get(val);
            if (info == null) {
                info = new Info();
                info.first = i;
                info.prev = i;
                info.last = i;
                map.put(val, info);
            } else {
                int gap = i - info.prev - 1;
                if (gap > info.maxGap) {
                    info.maxGap = gap;
                }
                info.prev = i;
                info.last = i;
            }
        }
        int answer = Integer.MAX_VALUE;
        for (Info info : map.values()) {
            int wrapGap = (info.first + n) - info.last - 1;
            if (wrapGap > info.maxGap) {
                info.maxGap = wrapGap;
            }
            int seconds = (info.maxGap + 1) / 2;
            if (seconds < answer) {
                answer = seconds;
            }
        }
        return answer;
    }

    private static class Info {
        int first;
        int last;
        int prev;
        int maxGap;
    }
}

