class Solution {
    public static boolean canSplitArray(int[] nums, int m) {
        if (nums == null || nums.length == 0) {
            return false;
        }
        long target = m;
        long sum = 0;
        int left = 0;
        for (int right = 0; right < nums.length; right++) {
            sum += nums[right];
            while (left <= right && sum > target) {
                sum -= nums[left++];
            }
            if (sum == target) {
                return true;
            }
        }
        return false;
    }
}

