class Solution {
    public static ListNode doubleLinkedList(ListNode head) {
        ListNode prev = null, cur = head;
        while (cur != null) {
            ListNode nxt = cur.next;
            cur.next = prev;
            prev = cur;
            cur = nxt;
        }
        ListNode node = prev;
        int carry = 0;
        ListNode last = null;
        while (node != null) {
            int sum = node.val * 2 + carry;
            node.val = sum % 10;
            carry = sum / 10;
            last = node;
            node = node.next;
        }
        if (carry != 0) {
            last.next = new ListNode(carry);
        }
        cur = prev;
        prev = null;
        while (cur != null) {
            ListNode nxt = cur.next;
            cur.next = prev;
            prev = cur;
            cur = nxt;
        }
        return prev;
    }
}

