class Solution {
    public static int minimumAbsoluteDifference(int[] nums, int x) {
        TreeMap<Integer, Integer> map = new TreeMap<>();
        int best = Integer.MAX_VALUE;
        for (int i = 0; i < nums.length; i++) {
            if (i - x >= 0) {
                int val = nums[i - x];
                map.put(val, map.getOrDefault(val, 0) + 1);
            }
            Integer ceil = map.ceilingKey(nums[i]);
            if (ceil != null) {
                best = Math.min(best, Math.abs(ceil - nums[i]));
                if (best == 0) return 0;
            }
            Integer floor = map.floorKey(nums[i]);
            if (floor != null) {
                best = Math.min(best, Math.abs(floor - nums[i]));
                if (best == 0) return 0;
            }
        }
        return best == Integer.MAX_VALUE ? 0 : best;
    }
}

class Solution {
    public static long maxScore(int[] nums, int k) {
        int n = nums.length;
        final long MOD = 1000000007;
        int[] scores = new int[n];
        for (int i = 0; i < n; i++) scores[i] = primeScore(nums[i]);
        int[] left = new int[n], right = new int[n];
        int[] stack = new int[n]; int top = -1;
        for (int i = 0; i < n; i++) {
            while (top >= 0 && scores[stack[top]] < scores[i]) top--;
            left[i] = top >= 0 ? stack[top] : -1;
            stack[++top] = i;
        }
        top = -1;
        for (int i = n-1; i >= 0; i--) {
            while (top >= 0 && scores[stack[top]] <= scores[i]) top--;
            right[i] = top >= 0 ? stack[top] : n;
            stack[++top] = i;
        }
        long[] count = new long[n];
        for (int i = 0; i < n; i++) count[i] = (long)(i - left[i]) * (right[i] - i);
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        java.util.Arrays.sort(order, (a, b) -> nums[b] - nums[a]);
        long remaining = k;
        long ans = 1;
        for (int i : order) {
            if (remaining <= 0) break;
            long take = Math.min(count[i], remaining);
            ans = (ans * modpow(nums[i], take, MOD)) % MOD;
            remaining -= take;
        }
        return ans;
    }
    private static int primeScore(int x) {
        int count = 0;
        for (int p = 2; (long)p*p <= x; p++) {
            if (x % p == 0) { count++; while (x % p == 0) x /= p; }
        }
        if (x > 1) count++;
        return count;
    }
    private static long modpow(long base, long exp, long mod) {
        base %= mod;
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}

