class Solution {
    public static int maxPairSum(int[] nums) {
        int[][] top = new int[10][2];
        for (int i = 0; i < 10; i++) {
            top[i][0] = -1;
            top[i][1] = -1;
        }

        for (int i = 0; i < nums.length; i++) {
            int n = nums[i];
            int maxDigit = 0;

            if (n == 0) {
                maxDigit = 0;
            } else {
                while (n > 0) {
                    int d = n % 10;
                    if (d > maxDigit) {
                        maxDigit = d;
                    }
                    n = n / 10;
                }
            }

            int[] arr = top[maxDigit];
            if (nums[i] > arr[0]) {
                arr[1] = arr[0];
                arr[0] = nums[i];
            } else if (nums[i] > arr[1]) {
                arr[1] = nums[i];
            }
        }

        int answer = -1;
        for (int d = 0; d < 10; d++) {
            int first = top[d][0];
            int second = top[d][1];
            if (second != -1) {
                int sum = first + second;
                if (sum > answer) {
                    answer = sum;
                }
            }
        }
        return answer;
    }
}

