class Solution {
    public static long maxProfit(int n, int[][] offers) {
        Arrays.sort(offers, (a, b) -> Integer.compare(a[1], b[1]));
        int m = offers.length;
        int[] ends = new int[m];
        for (int i = 0; i < m; ++i) {
            ends[i] = offers[i][1];
        }
        long[] dp = new long[m + 1];
        for (int i = 1; i <= m; ++i) {
            int start = offers[i - 1][0];
            int gold = offers[i - 1][2];
            int lo = 0, hi = i - 2, pos = 0;
            while (lo <= hi) {
                int mid = (lo + hi) >>> 1;
                if (ends[mid] < start) {
                    pos = mid + 1;
                    lo = mid + 1;
                } else {
                    hi = mid - 1;
                }
            }
            dp[i] = Math.max(dp[i - 1], gold + dp[pos]);
        }
        return dp[m];
    }
}

