class Solution {
    public static long minimumKAvoidingSum(int n, int k) {
        long m = Math.min(n, k / 2);
        long sum = m * (m + 1) / 2;
        long extra = n - m;
        sum += extra * (long) k + extra * (extra - 1) / 2;
        return sum;
    }
}

import java.util.*;

public class Solution {
    public static int numberOfBeautifulIntegers(int low, int high, int k) {
        return (int) (count(high, k) - count(low - 1, k));
    }

    private static long count(int bound, int k) {
        if (bound < 0) return 0;
        char[] digits = Integer.toString(bound).toCharArray();
        int n = digits.length;
        int offset = n;
        long[][][][] memo = new long[n + 1][2 * n + 1][k][2];
        for (int i = 0; i <= n; i++) {
            for (int d = 0; d < 2 * n + 1; d++) {
                for (int r = 0; r < k; r++) {
                    Arrays.fill(memo[i][d][r], -1L);
                }
            }
        }
        return dfs(0, 0, 0, false, true, digits, offset, k, memo);
    }

    private static long dfs(int pos, int diff, int rem, boolean started, boolean tight,
                            char[] digits, int offset, int k,
                            long[][][][] memo) {
        if (pos == digits.length) {
            return (started && diff == 0 && rem == 0) ? 1L : 0L;
        }
        if (!tight) {
            int diffIdx = diff + offset;
            int startedIdx = started ? 1 : 0;
            long cached = memo[pos][diffIdx][rem][startedIdx];
            if (cached != -1) return cached;
        }
        int limit = tight ? digits[pos] - '0' : 9;
        long ans = 0;
        for (int d = 0; d <= limit; d++) {
            boolean nStarted = started || d != 0;
            int nDiff = diff;
            int nRem = rem;
            if (nStarted) {
                if ((d & 1) == 0) {
                    nDiff--;
                } else {
                    nDiff++;
                }
                nRem = (rem * 10 + d) % k;
            }
            ans += dfs(pos + 1, nDiff, nRem, nStarted,
                       tight && d == limit, digits, offset, k, memo);
        }
        if (!tight) {
            int diffIdx = diff + offset;
            int startedIdx = started ? 1 : 0;
            memo[pos][diffIdx][rem][startedIdx] = ans;
        }
        return ans;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static int longestEqualSubarray(int[] nums, int k) {
        int n = nums.length;
        if (n == 0) return 0;
        Map<Integer, Integer> freq = new HashMap<>();
        Map<Integer, Integer> freqCount = new HashMap<>();
        int left = 0;
        int maxFreq = 0;
        int answer = 0;
        for (int right = 0; right < n; right++) {
            int val = nums[right];
            int oldFreq = freq.getOrDefault(val, 0);
            if (oldFreq > 0) {
                freqCount.put(oldFreq, freqCount.get(oldFreq) - 1);
            }
            int newFreq = oldFreq + 1;
            freq.put(val, newFreq);
            freqCount.put(newFreq, freqCount.getOrDefault(newFreq, 0) + 1);
            if (newFreq > maxFreq) {
                maxFreq = newFreq;
            }
            while ((right - left + 1) - maxFreq > k) {
                int leftVal = nums[left];
                int oldLeftFreq = freq.get(leftVal);
                freqCount.put(oldLeftFreq, freqCount.get(oldLeftFreq) - 1);
                int newLeftFreq = oldLeftFreq - 1;
                if (newLeftFreq > 0) {
                    freqCount.put(newLeftFreq, freqCount.getOrDefault(newLeftFreq, 0) + 1);
                }
                if (newLeftFreq == 0) {
                    freq.remove(leftVal);
                } else {
                    freq.put(leftVal, newLeftFreq);
                }
                left++;
                while (maxFreq > 0 && freqCount.getOrDefault(maxFreq, 0) == 0) {
                    maxFreq--;
                }
            }
            answer = Math.max(answer, maxFreq);
        }
        return answer;
    }
}

class Solution {
    public static int furthestPoint(String moves) {
        int cntL = 0, cntR = 0, cntU = 0;
        for (int i = 0; i < moves.length(); i++) {
            char ch = moves.charAt(i);
            if (ch == 'L') cntL++;
            else if (ch == 'R') cntR++;
            else cntU++;
        }
        int forced = cntR - cntL;
        return Math.abs(forced) + cntU;
    }
}

import java.lang.*;

class Solution {
    public static int minimumBeautifulArraySum(int n, int target) {
        final long MOD = 1_000_000_007L;
        long N = n;
        long T = target;
        long A = T / 2;
        long countUpToTarget = A + 1;
        long sum;
        if (N <= A) {
            sum = N * (N + 1) / 2;
        } else if (N == countUpToTarget) {
            sum = A * (A + 1) / 2 + T;
        } else {
            long extra = N - countUpToTarget;
            sum = A * (A + 1) / 2 + T + extra * T + extra * (extra + 1) / 2;
        }
        return (int) (sum % MOD);
    }
}

import java.util.*;

class Solution {
    public static long maxScore(int[] receiver, long k) {
        int n = receiver.length;
        long best = Long.MIN_VALUE;
        long target = k + 1; // number of nodes to include in the sum
        for (int start = 0; start < n; start++) {
            int cur = start;
            long steps = 0;
            long sum = 0;
            Map<Integer, Integer> visited = new HashMap<>();
            List<Integer> path = new ArrayList<>();
            while (steps < target) {
                if (visited.containsKey(cur)) {
                    break;
                }
                visited.put(cur, (int) steps);
                path.add(cur);
                sum += cur;
                steps++;
                cur = receiver[cur];
            }
            if (steps == target) {
                if (sum > best) best = sum;
                continue;
            }
            int cycleStartIdx = visited.get(cur);
            int cycleLen = (int) (steps - cycleStartIdx);
            long cycleSum = 0;
            for (int i = cycleStartIdx; i < steps; i++) {
                cycleSum += path.get(i);
            }
            long remaining = target - steps;
            if (cycleSum > 0) {
                long fullCycles = remaining / cycleLen;
                sum += fullCycles * cycleSum;
                remaining %= cycleLen;
            }
            for (int i = 0; i < remaining; i++) {
                sum += path.get(cycleStartIdx + i);
            }
            if (sum > best) best = sum;
        }
        return best;
    }
}

public class Solution {
    public static boolean canBeEqual(String s1, String s2) {
        if (s1.length() != s2.length()) return false;
        int[] even1 = new int[26];
        int[] odd1 = new int[26];
        int[] even2 = new int[26];
        int[] odd2 = new int[26];
        for (int i = 0; i < s1.length(); i++) {
            int c1 = s1.charAt(i) - 'a';
            int c2 = s2.charAt(i) - 'a';
            if (i % 2 == 0) {
                even1[c1]++;
                even2[c2]++;
            } else {
                odd1[c1]++;
                odd2[c2]++;
            }
        }
        for (int k = 0; k < 26; k++) {
            if (even1[k] != even2[k] || odd1[k] != odd2[k]) return false;
        }
        return true;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static int maxSumAlmostUnique(int[] nums, int m, int k) {
        if (k > nums.length || m > k) return 0;
        Map<Integer, Integer> freq = new HashMap<>();
        int distinctCnt = 0;
        int curSum = 0;
        for (int i = 0; i < k; i++) {
            curSum += nums[i];
            int count = freq.getOrDefault(nums[i], 0) + 1;
            freq.put(nums[i], count);
            if (count == 1) distinctCnt++;
        }
        int maxSum = distinctCnt >= m ? curSum : 0;
        for (int i = k; i < nums.length; i++) {
            int left = nums[i - k];
            int right = nums[i];
            int leftCount = freq.get(left) - 1;
            if (leftCount == 0) {
                freq.remove(left);
                distinctCnt--;
            } else {
                freq.put(left, leftCount);
            }
            curSum -= left;
            int rightCount = freq.getOrDefault(right, 0) + 1;
            if (rightCount == 1) distinctCnt++;
            freq.put(right, rightCount);
            curSum += right;
            if (distinctCnt >= m && curSum > maxSum) {
                maxSum = curSum;
            }
        }
        return maxSum;
    }
}

