class Solution {
    public static int minOperations(int[] nums, int target) {
        final int MAX_BITS = 31;
        int[] cnt = new int[MAX_BITS];
        for (int v : nums) {
            int e = Integer.numberOfTrailingZeros(v);
            if (e < MAX_BITS) cnt[e]++;
        }
        int ops = 0;
        for (int i = 0; i < MAX_BITS; i++) {
            if (((target >> i) & 1) == 1) {
                if (cnt[i] > 0) {
                    cnt[i]--;
                } else {
                    int j = i + 1;
                    while (j < MAX_BITS && cnt[j] == 0) j++;
                    if (j == MAX_BITS) return -1;
                    while (j > i) {
                        cnt[j]--;
                        cnt[j - 1] += 2;
                        ops++;
                        j--;
                    }
                    cnt[i]--;
                }
            }
            if (i + 1 < MAX_BITS) {
                cnt[i + 1] += cnt[i] / 2;
            }
        }
        return ops;
    }
}

public class Solution {
    public static boolean canBeEqual(String s1, String s2) {
        if (s1.length() != s2.length()) {
            return false;
        }
        int[] even = new int[26];
        int[] odd = new int[26];
        for (int i = 0; i < s1.length(); i++) {
            int idx = s1.charAt(i) - 'a';
            if ((i & 1) == 0) {
                even[idx]++;
            } else {
                odd[idx]++;
            }
        }
        for (int i = 0; i < s2.length(); i++) {
            int idx = s2.charAt(i) - 'a';
            if ((i & 1) == 0) {
                even[idx]--;
            } else {
                odd[idx]--;
            }
        }
        for (int v : even) {
            if (v != 0) {
                return false;
            }
        }
        for (int v : odd) {
            if (v != 0) {
                return false;
            }
        }
        return true;
    }
}

import java.util.*;

class Solution {
    public static int minOperations(String num) {
        int n = num.length();
        int best = n;
        char[][] targets = {{'0','0'}, {'2','5'}, {'5','0'}, {'7','5'}};
        for (char[] pair : targets) {
            char a = pair[0];
            char b = pair[1];
            int i = n - 1;
            while (i >= 0 && num.charAt(i) != b) i--;
            if (i < 0) continue;
            int j = i - 1;
            while (j >= 0 && num.charAt(j) != a) j--;
            if (j < 0) continue;
            best = Math.min(best, n - j - 2);
        }
        for (int i = 0; i < n; i++) {
            if (num.charAt(i) == '0') {
                best = Math.min(best, n - 1);
                break;
            }
        }
        return best;
    }
}

import java.util.*;

class Solution {
    public static int[] minOperations(int n, int[][] edges, int[][] queries) {
        List<int[]>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0], v = e[1], w = e[2];
            adj[u].add(new int[]{v, w});
            adj[v].add(new int[]{u, w});
        }

        int LOG = 32 - Integer.numberOfLeadingZeros(n);
        int[][] up = new int[n][LOG];
        int[] depth = new int[n];
        int[][] pref = new int[n][27];

        for (int i = 0; i < n; i++) Arrays.fill(up[i], -1);
        int[] parent = new int[n];
        Arrays.fill(parent, -1);

        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(0);
        depth[0] = 0;

        while (!stack.isEmpty()) {
            int v = stack.pop();
            for (int[] e : adj[v]) {
                int to = e[0];
                int w = e[1];
                if (to == parent[v]) continue;
                parent[to] = v;
                depth[to] = depth[v] + 1;
                up[to][0] = v;
                for (int k = 1; k < LOG; k++) {
                    int mid = up[to][k - 1];
                    up[to][k] = (mid == -1) ? -1 : up[mid][k - 1];
                }
                System.arraycopy(pref[v], 0, pref[to], 0, 27);
                pref[to][w]++;
                stack.push(to);
            }
        }

        int m = queries.length;
        int[] ans = new int[m];
        for (int i = 0; i < m; i++) {
            int a = queries[i][0];
            int b = queries[i][1];
            int l = lca(a, b, depth, up, LOG);
            int pathEdges = depth[a] + depth[b] - 2 * depth[l];
            int maxFreq = 0;
            for (int w = 1; w <= 26; w++) {
                int cnt = pref[a][w] + pref[b][w] - 2 * pref[l][w];
                if (cnt > maxFreq) maxFreq = cnt;
            }
            ans[i] = pathEdges - maxFreq;
        }
        return ans;
    }

    private static int lca(int a, int b, int[] depth, int[][] up, int LOG) {
        if (depth[a] < depth[b]) {
            int tmp = a; a = b; b = tmp;
        }
        int diff = depth[a] - depth[b];
        for (int k = 0; k < LOG; k++) {
            if ((diff & (1 << k)) != 0) {
                a = up[a][k];
            }
        }
        if (a == b) return a;
        for (int k = LOG - 1; k >= 0; k--) {
            if (up[a][k] != -1 && up[a][k] != up[b][k]) {
                a = up[a][k];
                b = up[b][k];
            }
        }
        return up[a][0];
    }
}

import java.util.*;

class Solution {
    public static int countSymmetricIntegers(int low, int high) {
        return (int) (countUpTo(high) - countUpTo(low - 1));
    }

    private static long countUpTo(int bound) {
        if (bound < 0) return 0;
        String s = Integer.toString(bound);
        int n = s.length();
        long total = 0;
        for (int len = 2; len <= n; len += 2) {
            if (len < n) {
                total += countExactLength(len);
            } else {
                total += countBoundedLength(s.toCharArray(), len);
            }
        }
        return total;
    }

    private static long countExactLength(int len) {
        int k = len / 2;
        int maxDiff = 9 * k;
        long[][] memo = new long[len + 1][2 * maxDiff + 1];
        for (long[] row : memo) Arrays.fill(row, -1);
        return dfsExact(0, 0, len, k, maxDiff, memo);
    }

    private static long dfsExact(int pos, int diff, int len, int k, int maxDiff, long[][] memo) {
        if (pos == len) return diff == 0 ? 1 : 0;
        int idx = diff + maxDiff;
        if (memo[pos][idx] != -1) return memo[pos][idx];
        long res = 0;
        int start = (pos == 0) ? 1 : 0;
        for (int d = start; d <= 9; d++) {
            int ndiff = diff + (pos < k ? d : -d);
            res += dfsExact(pos + 1, ndiff, len, k, maxDiff, memo);
        }
        memo[pos][idx] = res;
        return res;
    }

    private static long countBoundedLength(char[] digits, int len) {
        int k = len / 2;
        int maxDiff = 9 * k;
        Long[][][] memo = new Long[len + 1][2 * maxDiff + 1][2];
        return dfsBounded(0, 0, true, digits, len, k, maxDiff, memo);
    }

    private static long dfsBounded(int pos, int diff, boolean tight, char[] digits, int len, int k, int maxDiff, Long[][][] memo) {
        if (pos == len) return diff == 0 ? 1 : 0;
        int tIdx = tight ? 1 : 0;
        int idx = diff + maxDiff;
        if (memo[pos][idx][tIdx] != null) return memo[pos][idx][tIdx];
        long res = 0;
        int limit = tight ? digits[pos] - '0' : 9;
        int start = (pos == 0) ? 1 : 0;
        for (int d = start; d <= limit; d++) {
            int ndiff = diff + (pos < k ? d : -d);
            boolean ntight = tight && (d == limit);
            res += dfsBounded(pos + 1, ndiff, ntight, digits, len, k, maxDiff, memo);
        }
        memo[pos][idx][tIdx] = res;
        return res;
    }
}

import java.lang.Math;

class Solution {
    public static boolean canReach(int sx, int sy, int fx, int fy, int t) {
        int dx = Math.abs(fx - sx);
        int dy = Math.abs(fy - sy);
        int minSteps = Math.max(dx, dy);
        if (t < minSteps) return false;
        if (minSteps == 0) return t % 2 == 0;
        return true;
    }
}

import java.util.*;

public class Solution {
    private static final long MOD = 1_000_000_007L;
    private static final int MAX = 26;
    private static final long[] FACT = new long[MAX + 1];
    private static final long[] INV_FACT = new long[MAX + 1];

    static {
        FACT[0] = 1;
        for (int i = 1; i <= MAX; i++) {
            FACT[i] = FACT[i - 1] * i % MOD;
        }
        INV_FACT[MAX] = modPow(FACT[MAX], MOD - 2);
        for (int i = MAX; i > 0; i--) {
            INV_FACT[i - 1] = INV_FACT[i] * i % MOD;
        }
    }

    public static int countKSubsequencesWithMaxBeauty(String s, int k) {
        int[] freq = new int[26];
        for (char ch : s.toCharArray()) {
            freq[ch - 'a']++;
        }
        List<Integer> list = new ArrayList<>();
        for (int f : freq) {
            if (f > 0) list.add(f);
        }
        if (k > list.size()) return 0;
        list.sort(Collections.reverseOrder());
        int threshold = list.get(k - 1);
        int cntGreater = 0;
        long productGreater = 1L;
        for (int f : list) {
            if (f > threshold) {
                cntGreater++;
                productGreater = productGreater * f % MOD;
            }
        }
        int cntEqual = 0;
        for (int f : list) {
            if (f == threshold) cntEqual++;
        }
        int need = k - cntGreater;
        long comb = nCr(cntEqual, need);
        long pow = modPow(threshold, need);
        long ans = comb * productGreater % MOD;
        ans = ans * pow % MOD;
        return (int) ans;
    }

    private static long nCr(int n, int r) {
        if (r < 0 || r > n) return 0;
        return FACT[n] * INV_FACT[r] % MOD * INV_FACT[n - r] % MOD;
    }

    private static long modPow(long base, long exp) {
        long result = 1L;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) result = result * base % MOD;
            base = base * base % MOD;
            exp >>= 1;
        }
        return result;
    }
}

import java.util.*;

public class Solution {
    public static int minMoves(int[][] grid) {
        List<int[]> stones = new ArrayList<>();
        for (int r = 0; r < 3; r++) {
            for (int c = 0; c < 3; c++) {
                int cnt = grid[r][c];
                for (int i = 0; i < cnt; i++) {
                    stones.add(new int[]{r, c});
                }
            }
        }
        List<int[]> targets = new ArrayList<>();
        for (int r = 0; r < 3; r++) {
            for (int c = 0; c < 3; c++) {
                targets.add(new int[]{r, c});
            }
        }
        int n = 9;
        int[][] dist = new int[n][n];
        for (int i = 0; i < n; i++) {
            int[] s = stones.get(i);
            int sr = s[0];
            int sc = s[1];
            for (int j = 0; j < n; j++) {
                int[] t = targets.get(j);
                int tr = t[0];
                int tc = t[1];
                dist[i][j] = Math.abs(sr - tr) + Math.abs(sc - tc);
            }
        }
        int INF = 1_000_000_000;
        int size = 1 << n;
        int[] dp = new int[size];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int mask = 0; mask < size; mask++) {
            int k = Integer.bitCount(mask);
            if (k >= n) continue;
            int cur = dp[mask];
            if (cur == INF) continue;
            for (int j = 0; j < n; j++) {
                if ((mask & (1 << j)) != 0) continue;
                int nextMask = mask | (1 << j);
                int cand = cur + dist[k][j];
                if (cand < dp[nextMask]) dp[nextMask] = cand;
            }
        }
        return dp[size - 1];
    }
}

class Solution {
    static final long MOD = 1_000_000_007L;

    private int[] zFunction(String s) {
        int n = s.length();
        int[] z = new int[n];
        int l = 0, r = 0;
        for (int i = 1; i < n; i++) {
            if (i < r) z[i] = Math.min(r - i, z[i - l]);
            while (i + z[i] < n && s.charAt(z[i]) == s.charAt(i + z[i])) z[i]++;
            if (i + z[i] > r) { l = i; r = i + z[i]; }
        }
        return z;
    }

    private int countGood(String s, String t) {
        int n = s.length();
        String combined = t + "#" + s + s;
        int[] z = zFunction(combined);
        int base = n + 1;
        int cnt = 0;
        for (int d = 0; d < n; d++) if (z[base + d] >= n) cnt++;
        return cnt;
    }

    private long[][] matmul(long[][] a, long[][] b) {
        long[][] r = new long[2][2];
        for (int i = 0; i < 2; i++)
            for (int j = 0; j < 2; j++)
                r[i][j] = (a[i][0]*b[0][j] + a[i][1]*b[1][j]) % MOD;
        return r;
    }

    private long[][] matpow(long[][] m, long p) {
        long[][] r = {{1,0},{0,1}};
        while (p > 0) {
            if ((p & 1) == 1) r = matmul(r, m);
            m = matmul(m, m);
            p >>= 1;
        }
        return r;
    }

    public int numberOfWays(String s, String t, long k) {
        int n = s.length();
        int c = countGood(s, t);
        long g0 = s.equals(t) ? 1 : 0;
        long b0 = 1 - g0;
        long[][] m = {{(c-1+MOD)%MOD, c%MOD}, {(n-c+MOD)%MOD, (n-c-1+MOD)%MOD}};
        long[][] mp = matpow(m, k);
        long ans = (mp[0][0]*g0 + mp[0][1]*b0) % MOD;
        return (int) ans;
    }
}

import java.util.*;

class Solution {
    public static int countCoveredPoints(int[][] nums) {
        if (nums.length == 0) return 0;
        Arrays.sort(nums, (a, b) -> Integer.compare(a[0], b[0]));
        int total = 0;
        int curStart = nums[0][0];
        int curEnd = nums[0][1];
        for (int i = 1; i < nums.length; i++) {
            int s = nums[i][0];
            int e = nums[i][1];
            if (s <= curEnd + 1) {
                if (e > curEnd) curEnd = e;
            } else {
                total += curEnd - curStart + 1;
                curStart = s;
                curEnd = e;
            }
        }
        total += curEnd - curStart + 1;
        return total;
    }
}

public class Solution {
    public static int minRightShifts(int[] nums) {
        int n = nums.length;
        if (n <= 1) return 0;
        int breakIdx = -1;
        for (int i = 0; i < n; i++) {
            int next = (i + 1) % n;
            if (nums[i] > nums[next]) {
                if (breakIdx != -1) {
                    return -1;
                }
                breakIdx = i;
            }
        }
        if (breakIdx == -1) {
            return 0;
        }
        return (n - (breakIdx + 1)) % n;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static long countPairs(int[][] coordinates, int k) {
        Map<Long, Integer> freq = new HashMap<>(coordinates.length * 2);
        for (int[] pt : coordinates) {
            long key = ((long) pt[0] << 32) ^ (pt[1] & 0xffffffffL);
            freq.put(key, freq.getOrDefault(key, 0) + 1);
        }
        long ans = 0;
        for (int[] pt : coordinates) {
            int x = pt[0];
            int y = pt[1];
            long curKey = ((long) x << 32) ^ (y & 0xffffffffL);
            freq.put(curKey, freq.get(curKey) - 1);
            for (int a = 0; a <= k; ++a) {
                int b = k - a;
                int nx = x ^ a;
                int ny = y ^ b;
                long partnerKey = ((long) nx << 32) ^ (ny & 0xffffffffL);
                Integer cnt = freq.get(partnerKey);
                if (cnt != null) {
                    ans += cnt;
                }
            }
        }
        return ans;
    }
}

