class Solution {
    public static long countInterestingSubarrays(int[] nums, int modulo, int k) {
        Map<Integer, Integer> freq = new HashMap<>();
        freq.put(0, 1);
        int prefix = 0;
        long answer = 0;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] % modulo == k) {
                prefix++;
            }
            int curMod = prefix % modulo;
            int need = (curMod - k + modulo) % modulo;
            answer += freq.getOrDefault(need, 0);
            freq.put(curMod, freq.getOrDefault(curMod, 0) + 1);
        }
        return answer;
    }
}

class Solution {
    public static int minArrayLength(int[] nums) {
        int n = nums.length;
        int maxFreq = 0;
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && nums[j] == nums[i]) j++;
            int freq = j - i;
            if (freq > maxFreq) maxFreq = freq;
            i = j;
        }
        return Math.max(0, 2 * maxFreq - n);
    }
}

