class Solution {
    public static long maxCompleteSubsetSum(int[] nums) {
        int n = nums.length;
        int[] spf = new int[n + 1];
        for (int i = 2; i <= n; i++) {
            if (spf[i] == 0) {
                for (int j = i; j <= n; j += i) {
                    if (spf[j] == 0) spf[j] = i;
                }
            }
        }

        HashMap<Integer, Long> groupSum = new HashMap<>();
        long best = Long.MIN_VALUE;

        for (int idx = 1; idx <= n; idx++) {
            int x = idx;
            int sqFree = 1;
            while (x > 1) {
                int p = spf[x];
                int cnt = 0;
                while (x % p == 0) {
                    x /= p;
                    cnt++;
                }
                if ((cnt & 1) == 1) {
                    sqFree *= p;
                }
            }
            int key = sqFree;
            long newSum = groupSum.getOrDefault(key, 0L) + nums[idx - 1];
            groupSum.put(key, newSum);
            if (newSum > best) best = newSum;
        }
        return best;
    }
}

import java.util.*;

class Solution {
    public static long maxAlloys(int n, int k, long budget, int[][] composition, long[] stock, long[] cost) {
        long stockValue = 0;
        for (int j = 0; j < n; ++j) {
            stockValue += stock[j] * cost[j];
        }

        long best = 0;

        for (int i = 0; i < k; ++i) {
            long baseCost = 0;
            for (int j = 0; j < n; ++j) {
                baseCost += (long) composition[i][j] * cost[j];
            }

            long high = (budget + stockValue) / baseCost;
            long low = 0;

            while (low < high) {
                long mid = (low + high + 1) / 2;
                long needed = 0;
                for (int j = 0; j < n; ++j) {
                    long required = mid * composition[i][j];
                    if (required > stock[j]) {
                        needed += (required - stock[j]) * cost[j];
                        if (needed > budget) {
                            break;
                        }
                    }
                }
                if (needed <= budget) {
                    low = mid;
                } else {
                    high = mid - 1;
                }
            }
            if (low > best) {
                best = low;
            }
        }
        return best;
    }
}

