class Solution {
    public static long maximumSumOfHeights(int[] maxHeights) {
        int n = maxHeights.length;
        long[] left = new long[n];
        long[] right = new long[n];
        int[] stack = new int[n];
        int top = -1;
        for (int i = 0; i < n; i++) {
            while (top >= 0 && maxHeights[stack[top]] > maxHeights[i]) {
                top--;
            }
            if (top == -1) {
                left[i] = (long) maxHeights[i] * (i + 1);
            } else {
                int prev = stack[top];
                left[i] = left[prev] + (long) maxHeights[i] * (i - prev);
            }
            stack[++top] = i;
        }
        top = -1;
        for (int i = n - 1; i >= 0; i--) {
            while (top >= 0 && maxHeights[stack[top]] > maxHeights[i]) {
                top--;
            }
            if (top == -1) {
                right[i] = (long) maxHeights[i] * (n - i);
            } else {
                int next = stack[top];
                right[i] = right[next] + (long) maxHeights[i] * (next - i);
            }
            stack[++top] = i;
        }
        long ans = 0;
        for (int i = 0; i < n; i++) {
            long total = left[i] + right[i] - maxHeights[i];
            if (total > ans) {
                ans = total;
            }
        }
        return ans;
    }
}

