class Solution {
    public static long maximumSum(int[] heights) {
        int n = heights.length;
        long[] left = new long[n];
        long[] right = new long[n];
        long[] stackHeight = new long[n];
        long[] stackCount = new long[n];
        int sz = 0;
        long curSum = 0;
        for (int i = 0; i < n; i++) {
            long cnt = 1;
            while (sz > 0 && stackHeight[sz - 1] >= heights[i]) {
                cnt += stackCount[sz - 1];
                curSum -= stackHeight[sz - 1] * stackCount[sz - 1];
                sz--;
            }
            stackHeight[sz] = heights[i];
            stackCount[sz] = cnt;
            sz++;
            curSum += (long) heights[i] * cnt;
            left[i] = curSum;
        }
        sz = 0;
        curSum = 0;
        for (int i = n - 1; i >= 0; i--) {
            long cnt = 1;
            while (sz > 0 && stackHeight[sz - 1] >= heights[i]) {
                cnt += stackCount[sz - 1];
                curSum -= stackHeight[sz - 1] * stackCount[sz - 1];
                sz--;
            }
            stackHeight[sz] = heights[i];
            stackCount[sz] = cnt;
            sz++;
            curSum += (long) heights[i] * cnt;
            right[i] = curSum;
        }
        long ans = 0;
        for (int i = 0; i < n; i++) {
            long total = left[i] + right[i] - heights[i];
            if (total > ans) {
                ans = total;
            }
        }
        return ans;
    }
}

import java.util.Arrays;

public class Solution {
    public static long countValidPaths(int n, int[][] edges) {
        boolean[] isPrime = new boolean[n + 1];
        if (n >= 2) {
            Arrays.fill(isPrime, true);
            isPrime[0] = false;
            isPrime[1] = false;
            for (int i = 2; i * i <= n; i++) {
                if (isPrime[i]) {
                    for (int j = i * i; j <= n; j += i) {
                        isPrime[j] = false;
                    }
                }
            }
        }

        int m = edges.length * 2;
        int[] head = new int[n + 1];
        Arrays.fill(head, -1);
        int[] to = new int[m];
        int[] next = new int[m];
        int idx = 0;
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            to[idx] = v;
            next[idx] = head[u];
            head[u] = idx++;
            to[idx] = u;
            next[idx] = head[v];
            head[v] = idx++;
        }

        int[] compId = new int[n + 1];
        int[] compSize = new int[n + 1];
        int compCnt = 0;
        int[] stack = new int[n];
        for (int i = 1; i <= n; i++) {
            if (isPrime[i] || compId[i] != 0) continue;
            compCnt++;
            int sz = 0;
            int top = 0;
            stack[top++] = i;
            compId[i] = compCnt;
            while (top > 0) {
                int node = stack[--top];
                sz++;
                for (int e = head[node]; e != -1; e = next[e]) {
                    int nb = to[e];
                    if (!isPrime[nb] && compId[nb] == 0) {
                        compId[nb] = compCnt;
                        stack[top++] = nb;
                    }
                }
            }
            compSize[compCnt] = sz;
        }

        long answer = 0;
        for (int p = 1; p <= n; p++) {
            if (!isPrime[p]) continue;
            long total = 0;
            long sumSq = 0;
            for (int e = head[p]; e != -1; e = next[e]) {
                int nb = to[e];
                if (isPrime[nb]) continue;
                int sz = compSize[compId[nb]];
                total += sz;
                sumSq += (long) sz * sz;
            }
            if (total == 0) continue;
            long contribution = total + (total * total - sumSq) / 2;
            answer += contribution;
        }
        return answer;
    }
}

