class Solution {
    public static int maxKDivisibleComponents(int n, int[][] edges, int[] values, int k) {
        int[] head = new int[n];
        Arrays.fill(head, -1);
        int m = edges.length;
        int[] to = new int[2 * m];
        int[] next = new int[2 * m];
        int idx = 0;
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            to[idx] = v;
            next[idx] = head[u];
            head[u] = idx++;
            to[idx] = u;
            next[idx] = head[v];
            head[v] = idx++;
        }
        int[] parent = new int[n];
        int[] order = new int[n];
        int[] stack = new int[n];
        int top = 0;
        stack[top++] = 0;
        parent[0] = -1;
        int ordIdx = 0;
        while (top > 0) {
            int u = stack[--top];
            order[ordIdx++] = u;
            for (int eIdx = head[u]; eIdx != -1; eIdx = next[eIdx]) {
                int v = to[eIdx];
                if (v == parent[u]) continue;
                parent[v] = u;
                stack[top++] = v;
            }
        }
        int[] mod = new int[n];
        int count = 0;
        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            int sumMod = (int) ((values[u] % k + k) % k);
            for (int eIdx = head[u]; eIdx != -1; eIdx = next[eIdx]) {
                int v = to[eIdx];
                if (v == parent[u]) continue;
                if (mod[v] == 0) {
                    count++;
                } else {
                    sumMod = (sumMod + mod[v]) % k;
                }
            }
            mod[u] = sumMod;
        }
        return count + (mod[0] == 0 ? 1 : 0);
    }
}

