class Solution {
    public static long maxTripletValue(int[] nums) {
        int n = nums.length;
        if (n < 3) return 0;
        long maxPrefix = nums[0];
        long bestDiff = Long.MIN_VALUE;
        long answer = Long.MIN_VALUE;
        for (int idx = 1; idx < n; ++idx) {
            if (idx >= 2 && bestDiff != Long.MIN_VALUE) {
                answer = Math.max(answer, bestDiff * nums[idx]);
            }
            long diff = maxPrefix - nums[idx];
            if (diff > bestDiff) bestDiff = diff;
            if (nums[idx] > maxPrefix) maxPrefix = nums[idx];
        }
        return answer == Long.MIN_VALUE ? 0 : Math.max(0, answer);
    }
}

