public class Solution {
    public static long maxValue(int[] nums) {
        int n = nums.length;
        if (n < 3) return 0L;
        int[] suffixMax = new int[n];
        suffixMax[n - 1] = nums[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            suffixMax[i] = Math.max(suffixMax[i + 1], nums[i]);
        }
        long ans = 0;
        int leftMax = nums[0];
        for (int j = 1; j < n - 1; j++) {
            leftMax = Math.max(leftMax, nums[j - 1]);
            long diff = (long) leftMax - nums[j];
            if (diff > 0) {
                long candidate = diff * suffixMax[j + 1];
                if (candidate > ans) ans = candidate;
            }
        }
        return ans;
    }
}

import java.util.ArrayDeque;

class Solution {
    public static int[] countVisitedNodes(int[] edges) {
        int n = edges.length;
        int[] answer = new int[n];
        byte[] visited = new byte[n];
        for (int start = 0; start < n; start++) {
            if (answer[start] != 0) continue;
            int cur = start;
            ArrayDeque<Integer> stack = new ArrayDeque<>();
            while (visited[cur] == 0) {
                visited[cur] = 1;
                stack.push(cur);
                cur = edges[cur];
            }
            if (visited[cur] == 1) {
                int cycleLen = 1;
                int node = edges[cur];
                while (node != cur) {
                    cycleLen++;
                    node = edges[node];
                }
                node = cur;
                do {
                    answer[node] = cycleLen;
                    visited[node] = 2;
                    node = edges[node];
                } while (node != cur);
            }
            while (!stack.isEmpty()) {
                int node = stack.pop();
                if (answer[node] != 0) {
                    visited[node] = 2;
                    continue;
                }
                int nxt = edges[node];
                answer[node] = answer[nxt] + 1;
                visited[node] = 2;
            }
        }
        return answer;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static int minimumSizeSubarrayInInfiniteArray(int[] nums, long target) {
        int n = nums.length;
        long[] prefix = new long[n + 1];
        Map<Long, Integer> firstIndex = new HashMap<>();
        firstIndex.put(0L, 0);
        for (int i = 1; i <= n; i++) {
            prefix[i] = prefix[i - 1] + nums[i - 1];
            firstIndex.putIfAbsent(prefix[i], i);
        }
        long totalSum = prefix[n];
        long best = Long.MAX_VALUE;
        for (int s = 0; s < n; s++) {
            long startPref = prefix[s];
            long sumToEnd = totalSum - startPref;
            if (target == sumToEnd) {
                best = Math.min(best, n - s);
                continue;
            }
            if (target < sumToEnd) {
                long needed = target + startPref;
                Integer e = firstIndex.get(needed);
                if (e != null && e > s) {
                    best = Math.min(best, e - s);
                }
                continue;
            }
            long remaining = target - sumToEnd;
            if (totalSum == 0) {
                continue;
            }
            long cycles = remaining / totalSum;
            long leftover = remaining - cycles * totalSum;
            if (leftover == 0) {
                long len = (n - s) + cycles * n;
                best = Math.min(best, len);
            } else {
                Integer p = firstIndex.get(leftover);
                if (p != null) {
                    long len = (n - s) + cycles * n + p;
                    best = Math.min(best, len);
                }
            }
        }
        return best == Long.MAX_VALUE ? -1 : (int) best;
    }
}

