class Solution {
    public static int[] minimumEdgeReversals(int n, int[][] edges) {
        List<int[]>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            adj[u].add(new int[]{v, 0});
            adj[v].add(new int[]{u, 1});
        }

        int[] answer = new int[n];
        int[] stack = new int[n];
        int[] parent = new int[n];
        int top = 0;
        stack[top++] = 0;
        parent[0] = -1;
        int rootReversals = 0;
        while (top > 0) {
            int node = stack[--top];
            for (int[] edge : adj[node]) {
                int nei = edge[0];
                int cost = edge[1];
                if (nei == parent[node]) continue;
                rootReversals += cost;
                parent[nei] = node;
                stack[top++] = nei;
            }
        }
        answer[0] = rootReversals;

        top = 0;
        stack[top++] = 0;
        parent[0] = -1;
        while (top > 0) {
            int node = stack[--top];
            for (int[] edge : adj[node]) {
                int nei = edge[0];
                int cost = edge[1];
                if (nei == parent[node]) continue;
                answer[nei] = answer[node] + (cost == 0 ? 1 : -1);
                parent[nei] = node;
                stack[top++] = nei;
            }
        }

        return answer;
    }
}

