class Solution {
    public static int minCostToMakeEqual(String s1, String s2, int x) {
        int n = s1.length();
        int[] diff = new int[n];
        int m = 0;
        for (int i = 0; i < n; i++) {
            if (s1.charAt(i) != s2.charAt(i)) {
                diff[m++] = i;
            }
        }
        if (m % 2 == 1) {
            return -1;
        }
        if (m == 0) {
            return 0;
        }
        int dpPrev2 = 0; // dp[0]
        int dpPrev1 = 1; // dp[1] = flip the single mismatch
        for (int i = 2; i <= m; i++) {
            int costPair = (diff[i - 1] == diff[i - 2] + 1) ? Math.min(x, 2) : x;
            int cur = Math.min(dpPrev1 + 1, dpPrev2 + costPair);
            dpPrev2 = dpPrev1;
            dpPrev1 = cur;
        }
        return dpPrev1;
    }
}

