public class Solution {
    public static long maxSumOfSquares(int[] nums, int k) {
        final long MOD = 1_000_000_007L;
        int[] bitCounts = new int[31];
        for (int x : nums) {
            int v = x;
            while (v != 0) {
                int b = Integer.numberOfTrailingZeros(v);
                bitCounts[b]++;
                v &= v - 1;
            }
        }
        long[] arr = new long[k];
        for (int b = 30; b >= 0; b--) {
            int cnt = bitCounts[b];
            long add = 1L << b;
            int limit = cnt < k ? cnt : k;
            for (int i = 0; i < limit; i++) {
                arr[i] += add;
            }
        }
        long ans = 0;
        for (int i = 0; i < k; i++) {
            long v = arr[i] % MOD;
            ans = (ans + v * v) % MOD;
        }
        return ans;
    }
}

