            if (s.charAt(i) == '1') totalOnes++;
        }
        if (k > totalOnes) return "";
        int left = 0, ones = 0;
        int minLen = Integer.MAX_VALUE;
        for (int right = 0; right < n; right++) {
            if (s.charAt(right) == '1') ones++;
            while (ones > k) {
                if (s.charAt(left) == '1') ones--;
                left++;
            }
            while (ones == k && left <= right && s.charAt(left) == '0') {
                left++;
            }
            if (ones == k) {
                int curLen = right - left + 1;
                if (curLen < minLen) minLen = curLen;
            }
        }
        if (minLen == Integer.MAX_VALUE) return "";
        int bestStart = -1;
        int countOnes = 0;
        for (int i = 0; i < minLen; i++) {
            if (s.charAt(i) == '1') countOnes++;
        }
        if (countOnes == k) bestStart = 0;
        for (int start = 1; start + minLen <= n; start++) {
            if (s.charAt(start - 1) == '1') countOnes--;
            if (s.charAt(start + minLen - 1) == '1') countOnes++;
            if (countOnes == k) {
                if (bestStart == -1) {
                    bestStart = start;
                } else {
                    int a = start, b = bestStart;
                    while (a < start + minLen && s.charAt(a) == s.charAt(b)) {
                        a++;
                        b++;
                    }
                    if (a < start + minLen && s.charAt(a) < s.charAt(b)) {
                        bestStart = start;
                    }
                }
            }
        }
        return bestStart == -1 ? "" : s.substring(bestStart, bestStart + minLen);
    }
}

import java.util.*;

class Solution {
    public static List<String> longestUnequalAdjacentGroupsSubsequenceII(String[] words, int[] groups) {
        int n = words.length;
        int[] dp = new int[n];
        int[] prev = new int[n];
        for (int i = 0; i < n; i++) {
            dp[i] = 1;
            prev[i] = -1;
            for (int j = 0; j < i; j++) {
                if (groups[j] != groups[i]) {
                    if (dp[j] + 1 > dp[i]) {
                        dp[i] = dp[j] + 1;
                        prev[i] = j;
                    }
                }
            }
        }
        int maxLen = 0;
        for (int len : dp) {
            if (len > maxLen) maxLen = len;
        }
        List<String> bestSeq = null;
        for (int i = 0; i < n; i++) {
            if (dp[i] == maxLen) {
                List<String> seq = buildSequence(i, words, prev);
                if (bestSeq == null || compare(seq, bestSeq) < 0) {
                    bestSeq = seq;
                }
            }
        }
        return bestSeq == null ? new ArrayList<>() : bestSeq;
    }

    private static List<String> buildSequence(int idx, String[] words, int[] prev) {
        LinkedList<String> list = new LinkedList<>();
        while (idx != -1) {
            list.addFirst(words[idx]);
            idx = prev[idx];
        }
        return list;
    }

    private static int compare(List<String> a, List<String> b) {
        int m = Math.min(a.size(), b.size());
        for (int i = 0; i < m; i++) {
            int cmp = a.get(i).compareTo(b.get(i));
            if (cmp != 0) return cmp;
        }
        return Integer.compare(a.size(), b.size());
    }
}

