class Solution {
    public static int[] findIndices(int[] nums, int indexDifference, int valueDifference) {
        int n = nums.length;
        if (n == 0) return new int[]{-1, -1};
        if (indexDifference < 0) indexDifference = 0;
        if (valueDifference <= 0) {
            if (indexDifference < n) return new int[]{0, indexDifference};
            return new int[]{-1, -1};
        }
        long maxVal = Long.MIN_VALUE;
        int maxIdx = -1;
        long minVal = Long.MAX_VALUE;
        int minIdx = -1;
        for (int j = 0; j < n; ++j) {
            int i = j - indexDifference;
            if (i >= 0) {
                long v = nums[i];
                if (v > maxVal) {
                    maxVal = v;
                    maxIdx = i;
                }
                if (v < minVal) {
                    minVal = v;
                    minIdx = i;
                }
            }
            if (maxIdx != -1 && maxVal - nums[j] >= valueDifference) {
                return new int[]{maxIdx, j};
            }
            if (minIdx != -1 && nums[j] - minVal >= valueDifference) {
                return new int[]{minIdx, j};
            }
        }
        return new int[]{-1, -1};
    }
}

