class Solution {
    public static int minimumSum(int[] nums) {
        int n = nums.length;
        if (n < 3) return -1;
        int INF = Integer.MAX_VALUE;
        int[] left = new int[n];
        int[] right = new int[n];
        int pref = INF;
        for (int i = 0; i < n; i++) {
            left[i] = (pref < nums[i]) ? pref : INF;
            pref = Math.min(pref, nums[i]);
        }
        int suff = INF;
        for (int i = n - 1; i >= 0; i--) {
            right[i] = (suff < nums[i]) ? suff : INF;
            suff = Math.min(suff, nums[i]);
        }
        int ans = INF;
        for (int j = 1; j < n - 1; j++) {
            if (left[j] != INF && right[j] != INF) {
                int sum = left[j] + nums[j] + right[j];
                if (sum < ans) ans = sum;
            }
        }
        return ans == INF ? -1 : ans;
    }
}

import java.math.BigInteger;

class Solution {
    private static final BigInteger MOD = BigInteger.valueOf(12345);

    public static BigInteger[][] constructProductMatrix(int[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        int zeroCount = 0;
        BigInteger total = BigInteger.ONE;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 0) {
                    zeroCount++;
                } else {
                    total = total.multiply(BigInteger.valueOf(grid[i][j]));
                }
            }
        }
        BigInteger[][] result = new BigInteger[n][m];
        if (zeroCount > 1) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    result[i][j] = BigInteger.ZERO;
                }
            }
        } else if (zeroCount == 1) {
            BigInteger totalMod = total.mod(MOD);
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    result[i][j] = grid[i][j] == 0 ? totalMod : BigInteger.ZERO;
                }
            }
        } else {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    result[i][j] = total.divide(BigInteger.valueOf(grid[i][j])).mod(MOD);
                }
            }
        }
        return result;
    }
}

import java.util.Arrays;

class Solution {
    public static int minChanges(String s, int k) {
        int n = s.length();
        if (k >= n) return 0;
        int[][] cost = new int[n][n];
        for (int len = 2; len <= n; ++len) {
            for (int i = 0; i + len <= n; ++i) {
                int j = i + len - 1;
                if (s.charAt(i) == s.charAt(j)) {
                    cost[i][j] = (len == 2) ? 0 : cost[i + 1][j - 1];
                } else {
                    cost[i][j] = (len == 2) ? 1 : cost[i + 1][j - 1] + 1;
                }
            }
        }
        int INF = 1_000_000_000;
        int[] prev = new int[n + 1];
        int[] curr = new int[n + 1];
        Arrays.fill(prev, INF);
        prev[0] = 0;
        for (int p = 1; p <= k; ++p) {
            Arrays.fill(curr, INF);
            for (int i = 1; i <= n; ++i) {
                int best = INF;
                for (int t = p - 1; t < i; ++t) {
                    int prevVal = prev[t];
                    if (prevVal == INF) continue;
                    int cand = prevVal + cost[t][i - 1];
                    if (cand < best) best = cand;
                }
                curr[i] = best;
            }
            int[] tmp = prev;
            prev = curr;
            curr = tmp;
        }
        return prev[n];
    }
}

