class Solution {
    public static long subarraysDistinctElementSumSquares(int[] nums) {
        int n = nums.length;
        Map<Integer, Integer> compress = new HashMap<>();
        int idx = 0;
        for (int v : nums) {
            if (!compress.containsKey(v)) {
                compress.put(v, idx++);
            }
        }
        int[] compressed = new int[n];
        for (int i = 0; i < n; i++) {
            compressed[i] = compress.get(nums[i]);
        }
        int[] seen = new int[idx];
        long total = 0L;
        for (int i = 0; i < n; i++) {
            int distinct = 0;
            int stamp = i + 1;
            for (int j = i; j < n; j++) {
                int valIdx = compressed[j];
                if (seen[valIdx] != stamp) {
                    distinct++;
                    seen[valIdx] = stamp;
                }
                total += (long) distinct * distinct;
            }
        }
        return total;
    }
}

