import java.util.Map;

class Solution {
    public static int sumDistinctSquares(int[] nums) {
        final long MOD = 1_000_000_007L;
        int n = nums.length;
        if (n == 0) return 0;
        SegmentTree seg = new SegmentTree(n);
        Map<Integer, Integer> last = new HashMap<>();
        long total = 0L;
        for (int r = 0; r < n; r++) {
            int val = nums[r];
            int prev = last.getOrDefault(val, -1);
            int left = prev + 1;
            seg.update(left, r, 1L);
            long cur = seg.query(0, r);
            total += cur;
            if (total >= MOD) total %= MOD;
            last.put(val, r);
        }
        return (int) (total % MOD);
    }

    private static class SegmentTree {
        private final int n;
        private final long[] sum;
        private final long[] sumSq;
        private final long[] lazy;

        SegmentTree(int n) {
            this.n = n;
            int size = 4 * n;
            sum = new long[size];
            sumSq = new long[size];
            lazy = new long[size];
        }

        private void apply(int node, int l, int r, long val) {
            long len = r - l + 1;
            sumSq[node] = sumSq[node] + 2L * val * sum[node] + val * val * len;
            sum[node] = sum[node] + val * len;
            lazy[node] += val;
        }

        private void push(int node, int l, int r) {
            if (lazy[node] != 0) {
                int mid = (l + r) >>> 1;
                apply(node << 1, l, mid, lazy[node]);
                apply(node << 1 | 1, mid + 1, r, lazy[node]);
                lazy[node] = 0;
            }
        }

        void update(int ql, int qr, long val) {
            update(1, 0, n - 1, ql, qr, val);
        }

        private void update(int node, int l, int r, int ql, int qr, long val) {
            if (ql > r || qr < l) return;
            if (ql <= l && r <= qr) {
                apply(node, l, r, val);
                return;
            }
            push(node, l, r);
            int mid = (l + r) >>> 1;
            update(node << 1, l, mid, ql, qr, val);
            update(node << 1 | 1, mid + 1, r, ql, qr, val);
            sum[node] = sum[node << 1] + sum[node << 1 | 1];
            sumSq[node] = sumSq[node << 1] + sumSq[node << 1 | 1];
        }

        long query(int ql, int qr) {
            return query(1, 0, n - 1, ql, qr);
        }

        private long query(int node, int l, int r, int ql, int qr) {
            if (ql > r || qr < l) return 0L;
            if (ql <= l && r <= qr) return sumSq[node];
            push(node, l, r);
            int mid = (l + r) >>> 1;
            return query(node << 1, l, mid, ql, qr) + query(node << 1 | 1, mid + 1, r, ql, qr);
        }
    }
}

