class Solution {
    public static int maxNumberOfPairs(String[] words) {
        int[] cnt = new int[26 * 26];
        for (String w : words) {
            int idx = (w.charAt(0) - 'a') * 26 + (w.charAt(1) - 'a');
            cnt[idx]++;
        }
        int pairs = 0;
        for (int i = 0; i < 26 * 26; i++) {
            int a = i / 26;
            int b = i % 26;
            if (a == b) {
                pairs += cnt[i] / 2;
            } else {
                int revIdx = b * 26 + a;
                if (i < revIdx) {
                    pairs += Math.min(cnt[i], cnt[revIdx]);
                }
            }
        }
        return pairs;
    }
}

