public class Solution {
    @FunctionalInterface
    public interface Fn {
        Object apply(Object... args);
    }

    public static class Result {
        public long time;
        public Object returned;
        public Result(long time, Object returned) {
            this.time = time;
            this.returned = returned;
        }
    }

    public static Supplier<List<Result>> cancellable(Fn fn, Object[] args, long t) {
        List<Result> results = new ArrayList<>();
        results.add(new Result(0, fn.apply(args)));
        Timer timer = new Timer();
        TimerTask task = new TimerTask() {
            @Override
            public void run() {
                results.add(new Result(results.size() * t, fn.apply(args)));
            }
        };
        timer.scheduleAtFixedRate(task, t, t);
        return () -> {
            timer.cancel();
            return results;
        };
    }
}

