class Solution {
    public static int waysToSplit(int[] nums) {
        final long MOD = 1_000_000_007L;
        int n = nums.length;
        long[] prefixSum = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + nums[i];
        }
        long[] dp = new long[n];
        for (int i = 0; i < n; i++) {
            if (prefixSum[i + 1] - prefixSum[0] == 1) {
                dp[i] = 1;
            }
            for (int j = 0; j < i; j++) {
                if (prefixSum[i + 1] - prefixSum[j + 1] == 1) {
                    dp[i] = (dp[i] + dp[j]) % MOD;
                }
            }
        }
        return (int) dp[n - 1];
    }
}

import java.util.*;

class Solution {
    public static int[] countZeroRequestServers(int n, int[][] logs, int x, int[] queries) {
        class Log {
            int server;
            int time;
            Log(int s, int t) { server = s; time = t; }
        }
        class Query {
            int time;
            int idx;
            Query(int t, int i) { time = t; idx = i; }
        }

        Log[] logArr = new Log[logs.length];
        for (int i = 0; i < logs.length; i++) {
            logArr[i] = new Log(logs[i][0], logs[i][1]);
        }
        Arrays.sort(logArr, Comparator.comparingInt(l -> l.time));

        Query[] qArr = new Query[queries.length];
        for (int i = 0; i < queries.length; i++) {
            qArr[i] = new Query(queries[i], i);
        }
        Arrays.sort(qArr, Comparator.comparingInt(q -> q.time));

        int[] cnt = new int[n + 1];
        int active = 0;
        int left = 0, right = 0;
        int[] result = new int[queries.length];

        for (Query q : qArr) {
            int lower = q.time - x;
            while (right < logArr.length && logArr[right].time <= q.time) {
                int srv = logArr[right].server;
                if (cnt[srv] == 0) active++;
                cnt[srv]++;
                right++;
            }
            while (left < logArr.length && logArr[left].time < lower) {
                int srv = logArr[left].server;
                cnt[srv]--;
                if (cnt[srv] == 0) active--;
                left++;
            }
            result[q.idx] = n - active;
        }
        return result;
    }
}

