class Solution {
    public static int[] findGoodSubset(int[][] grid) {
        int n = grid.length;
        if (n == 0) {
            return new int[0];
        }
        int m = grid[0].length;
        List<int[]> subsets = new ArrayList<>();
        for (int mask = 1; mask < (1 << n); mask++) {
            int count = Integer.bitCount(mask);
            int[] subset = new int[count];
            int idx = 0;
            for (int j = 0; j < n; j++) {
                if ((mask & (1 << j)) != 0) {
                    subset[idx++] = j;
                }
            }
            subsets.add(subset);
        }
        for (int[] subset : subsets) {
            int k = subset.length;
            int[] columnSums = new int[m];
            for (int row : subset) {
                for (int j = 0; j < m; j++) {
                    columnSums[j] += grid[row][j];
                }
            }
            boolean isGood = true;
            int limit = k / 2;
            for (int sum : columnSums) {
                if (sum > limit) {
                    isGood = false;
                    break;
                }
            }
            if (isGood) {
                return subset;
            }
        }
        return new int[0];
    }
}

