class Solution {
    public static int countBeautifulPairs(int[] nums) {
        int n = nums.length;
        int[] first = new int[n];
        int[] last = new int[n];
        for (int i = 0; i < n; i++) {
            int x = nums[i];
            last[i] = x % 10;
            while (x >= 10) {
                x /= 10;
            }
            first[i] = x;
        }
        long ans = 0;
        int[] suffix = new int[10];
        for (int i = n - 1; i >= 0; i--) {
            int fd = first[i];
            for (int d = 1; d <= 9; d++) {
                if (suffix[d] > 0 && gcd(fd, d) == 1) {
                    ans += suffix[d];
                }
            }
            suffix[last[i]]++;
        }
        return (int) ans;
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

