class Solution {
    public static int[] robotCollisions(int[] positions, int[] healths, char[] directions) {
        int n = positions.length;
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> Integer.compare(positions[a], positions[b]));

        // stack entries: [origIdx, health, dir(1=R,-1=L)]
        List<int[]> st = new ArrayList<>();
        for (int idx : order) {
            int dir = (directions[idx] == 'R') ? 1 : -1;
            if (dir == 1) {
                st.add(new int[]{idx, healths[idx], 1});
            } else {
                int curIdx = idx;
                int curHealth = healths[idx];
                while (!st.isEmpty() && st.get(st.size() - 1)[2] == 1 && curHealth > 0) {
                    int[] top = st.get(st.size() - 1);
                    if (top[1] > curHealth) {
                        top[1] = top[1] - 1;
                        curHealth = 0;
                        break;
                    } else if (top[1] < curHealth) {
                        curHealth -= 1;
                        st.remove(st.size() - 1);
                    } else {
                        st.remove(st.size() - 1);
                        curHealth = 0;
                        break;
                    }
                }
                if (curHealth > 0) {
                    st.add(new int[]{curIdx, curHealth, -1});
                }
            }
        }
        st.sort((a, b) -> Integer.compare(a[0], b[0]));
        int[] result = new int[st.size()];
        for (int i = 0; i < st.size(); i++) result[i] = st.get(i)[1];
        return result;
    }
}

