class Solution {
    public static int makeTheIntegerZero(long num1, long num2) {
        if (num1 == 0) return 0;
        for (int k = 1; k <= 60; k++) {
            long remaining = num1 - (long) k * num2;
            if (remaining < k) continue; // need at least k (since each power >=1)
            int bits = Long.bitCount(remaining);
            if (bits <= k && k <= remaining) {
                return k;
            }
        }
        return -1;
    }
}

