class Solution {
    public static int longestSubsequenceSum(int[] nums, int target) {
        Map<Integer, Integer> dp = new HashMap<>();
        dp.put(0, 0);
        for (int x : nums) {
            Map<Integer, Integer> next = new HashMap<>(dp);
            for (Map.Entry<Integer, Integer> entry : dp.entrySet()) {
                int newSum = entry.getKey() + x;
                int newLen = entry.getValue() + 1;
                Integer existing = next.get(newSum);
                if (existing == null || existing < newLen) {
                    next.put(newSum, newLen);
                }
            }
            dp = next;
        }
        return dp.containsKey(target) ? dp.get(target) : -1;
    }
}

