            if (v == 0) {
                long mult = c + 1L;
                for (int i = 0; i <= maxSum; i++) {
                    dp[i] = (int) ((dp[i] * mult) % MOD);
                }
                continue;
            }
            int[] ndp = new int[maxSum + 1];
            for (int rem = 0; rem < v; rem++) {
                int sum = 0;
                int k = 0;
                for (int s = rem; s <= maxSum; s += v, k++) {
                    sum += dp[s];
                    if (sum >= MOD) sum -= MOD;
                    if (k - (c + 1) >= 0) {
                        int idx = s - (c + 1) * v;
                        sum -= dp[idx];
                        if (sum < 0) sum += MOD;
                    }
                    ndp[s] = sum;
                }
            }
            dp = ndp;
        }
        long ans = 0;
        int lower = Math.max(l, 0);
        int upper = Math.min(r, maxSum);
        for (int s = lower; s <= upper; s++) {
            ans += dp[s];
            if (ans >= MOD) ans -= MOD;
        }
        return (int) ans;
    }
}

