class Solution {
    public static int minimumSum(int[] nums) {
        int n = nums.length;
        if (n < 3) return -1;
        final int INF = Integer.MAX_VALUE;
        int[] left = new int[n];
        int minLeft = INF;
        for (int i = 0; i < n; i++) {
            left[i] = (minLeft < nums[i]) ? minLeft : INF;
            if (nums[i] < minLeft) minLeft = nums[i];
        }
        int[] right = new int[n];
        int minRight = INF;
        for (int i = n - 1; i >= 0; i--) {
            right[i] = (minRight < nums[i]) ? minRight : INF;
            if (nums[i] < minRight) minRight = nums[i];
        }
        long best = Long.MAX_VALUE;
        for (int j = 0; j < n; j++) {
            if (left[j] != INF && right[j] != INF) {
                long sum = (long) left[j] + nums[j] + right[j];
                if (sum < best) best = sum;
            }
        }
        return best == Long.MAX_VALUE ? -1 : (int) best;
    }
}

