class Solution {
    public static int makeArrayBeautiful(int[] nums, int k) {
        int operations = 0;
        int n = nums.length;
        if (n < 3) {
            return 0;
        }
        for (int i = 0; i <= n - 3; i++) {
            int a = nums[i];
            int b = nums[i + 1];
            int c = nums[i + 2];
            int maxVal = Math.max(a, Math.max(b, c));
            if (maxVal < k) {
                int diff = k - maxVal;
                if (c == maxVal) {
                    nums[i + 2] += diff;
                } else if (b == maxVal) {
                    nums[i + 1] += diff;
                } else {
                    nums[i] += diff;
                }
                operations += diff;
            }
        }
        return operations;
    }
}

