        for (int v : nums1) {
            if (v == 0) zeros1++;
            else sum1 += v;
        }
        for (int v : nums2) {
            if (v == 0) zeros2++;
            else sum2 += v;
        }
        long minSum1 = sum1 + zeros1;
        long minSum2 = sum2 + zeros2;
        if (zeros1 == 0 && zeros2 == 0) {
            return sum1 == sum2 ? (int) sum1 : -1;
        }
        if (zeros1 == 0) {
            return sum1 >= minSum2 ? (int) sum1 : -1;
        }
        if (zeros2 == 0) {
            return sum2 >= minSum1 ? (int) sum2 : -1;
        }
        return (int) Math.max(minSum1, minSum2);
    }
}

