class Solution {
    public long maximumScore(int[][] edges, int[] values) {
        int n = values.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }
        long total = 0;
        for (int v : values) total += v;
        long kept = dfs(0, -1, graph, values);
        return total - kept;
    }

    private long dfs(int node, int parent, List<Integer>[] graph, int[] values) {
        boolean isLeaf = (parent != -1 && graph[node].size() == 1) || (parent == -1 && graph[node].isEmpty());
        if (isLeaf) {
            return values[node];
        }
        long sumChildren = 0;
        for (int nb : graph[node]) {
            if (nb == parent) continue;
            sumChildren += dfs(nb, node, graph, values);
        }
        return Math.min((long) values[node], sumChildren);
    }
}

