class Solution {
    public static int maxPoints(int[][] edges, int[] coins, int k) {
        int n = coins.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }
        long sum = 0;
        for (int c : coins) sum += c;
        if (n == 1) return (int) sum;
        int far = farthestNode(0, graph);
        int diameter = maxDistanceFrom(far, graph);
        long cost = (long) k * (2L * (n - 1) - diameter);
        return (int) (sum - cost);
    }

    private static int farthestNode(int start, List<Integer>[] graph) {
        int n = graph.length;
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        Queue<Integer> q = new ArrayDeque<>();
        q.add(start);
        dist[start] = 0;
        int farNode = start;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : graph[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.add(v);
                    if (dist[v] > dist[farNode]) farNode = v;
                }
            }
        }
        return farNode;
    }

    private static int maxDistanceFrom(int start, List<Integer>[] graph) {
        int n = graph.length;
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        Queue<Integer> q = new ArrayDeque<>();
        q.add(start);
        dist[start] = 0;
        int maxDist = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : graph[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.add(v);
                    if (dist[v] > maxDist) maxDist = dist[v];
                }
            }
        }
        return maxDist;
    }
}

