class Solution {
    public static int maximumBalancedSubsequenceSum(int[] nums) {
        int n = nums.length;
        int[] dp = new int[n];
        int maxSum = Integer.MIN_VALUE;
        for (int i = 0; i < n; i++) {
            dp[i] = nums[i];
            for (int j = 0; j < i; j++) {
                if (nums[i] - nums[j] >= i - j) {
                    dp[i] = Math.max(dp[i], dp[j] + nums[i]);
                }
            }
            maxSum = Math.max(maxSum, dp[i]);
        }
        return maxSum;
    }
}

import java.math.*;

class Solution {
    private static final long MOD = 1_000_000_007L;

    private static long modPow(long base, long exp) {
        long result = 1L;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1L) == 1L) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    public static long numberOfStrings(int n) {
        long total = modPow(26, n);
        long pow25 = modPow(25, n);
        long pow24 = modPow(24, n);
        long pow23 = modPow(23, n);
        long nMod = n % MOD;

        long a = pow25; // no 'l'
        long c = pow25; // no 't'
        long b = (pow25 + nMod * modPow(25, n - 1) % MOD) % MOD; // at most one 'e'

        long ab = (pow24 + nMod * modPow(24, n - 1) % MOD) % MOD; // no 'l', at most one 'e'
        long ac = pow24; // no 'l' and no 't'
        long bc = (pow24 + nMod * modPow(24, n - 1) % MOD) % MOD; // no 't', at most one 'e'

        long abc = (pow23 + nMod * modPow(23, n - 1) % MOD) % MOD; // no 'l', no 't', at most one 'e'

        long ans = (total - a - b - c + ab + ac + bc - abc) % MOD;
        if (ans < 0) ans += MOD;
        return ans;
    }
}

