class Solution {
    public static int minOperationsToMakeIncreasing(int[] nums1, int[] nums2) {
        int n = nums1.length;
        int case1 = tryCase(nums1, nums2, nums1[n-1], nums2[n-1]);
        int case2 = tryCase(nums1, nums2, nums2[n-1], nums1[n-1]);
        int best = Integer.MAX_VALUE;
        if (case1 != -1) best = Math.min(best, case1);
        if (case2 != -1) best = Math.min(best, case2 + 1);
        return best == Integer.MAX_VALUE ? -1 : best;
    }
    private static int tryCase(int[] nums1, int[] nums2, int end1, int end2) {
        int ops = 0;
        int n = nums1.length;
        for (int i = 0; i < n-1; i++) {
            int a = nums1[i], b = nums2[i];
            boolean noSwapOk = a <= end1 && b <= end2;
            boolean swapOk = b <= end1 && a <= end2;
            if (noSwapOk) continue;
            else if (swapOk) ops++;
            else return -1;
        }
        return ops;
    }
}

