public class Solution {
    private static final int MAX_BIT = 20;
    private static int[][] child;
    private static int[] cnt;
    private static int nodeCount;

    private static void initTrie(int n) {
        int maxNodes = n * (MAX_BIT + 2) + 1;
        child = new int[maxNodes][2];
        cnt = new int[maxNodes];
        nodeCount = 0;
    }

    private static void insert(int val) {
        int node = 0;
        cnt[node]++;
        for (int i = MAX_BIT; i >= 0; i--) {
            int bit = (val >> i) & 1;
            int next = child[node][bit];
            if (next == 0) {
                next = ++nodeCount;
                child[node][bit] = next;
            }
            node = next;
            cnt[node]++;
        }
    }

    private static void remove(int val) {
        int node = 0;
        cnt[node]--;
        for (int i = MAX_BIT; i >= 0; i--) {
            int bit = (val >> i) & 1;
            node = child[node][bit];
            cnt[node]--;
        }
    }

    private static int query(int val) {
        int node = 0;
        int xor = 0;
        for (int i = MAX_BIT; i >= 0; i--) {
            int bit = (val >> i) & 1;
            int toggled = bit ^ 1;
            int next = child[node][toggled];
            if (next != 0 && cnt[next] > 0) {
                xor |= (1 << i);
                node = next;
            } else {
                node = child[node][bit];
            }
        }
        return xor;
    }

    public static int maximumStrongPairXor(int[] nums) {
        Arrays.sort(nums);
        initTrie(nums.length);
        int ans = 0;
        int left = 0;
        for (int right = 0; right < nums.length; right++) {
            while ((long) nums[right] > 2L * (long) nums[left]) {
                remove(nums[left]);
                left++;
            }
            insert(nums[right]);
            int cur = query(nums[right]);
            if (cur > ans) ans = cur;
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    private static class Node {
        int[] child = new int[2];
        int cnt = 0;
        Node() {
            child[0] = -1;
            child[1] = -1;
        }
    }

    private static final int HIGH_BIT = 30; // enough for int values up to 2^31-1

    private static void insert(List<Node> trie, int num) {
        int idx = 0;
        trie.get(idx).cnt++;
        for (int k = HIGH_BIT; k >= 0; k--) {
            int bit = (num >>> k) & 1;
            if (trie.get(idx).child[bit] == -1) {
                trie.add(new Node());
                trie.get(idx).child[bit] = trie.size() - 1;
            }
            idx = trie.get(idx).child[bit];
            trie.get(idx).cnt++;
        }
    }

    private static void delete(List<Node> trie, int num) {
        int idx = 0;
        trie.get(idx).cnt--;
        for (int k = HIGH_BIT; k >= 0; k--) {
            int bit = (num >>> k) & 1;
            idx = trie.get(idx).child[bit];
            trie.get(idx).cnt--;
        }
    }

    private static int query(List<Node> trie, int num) {
        int idx = 0;
        int xor = 0;
        for (int k = HIGH_BIT; k >= 0; k--) {
            int bit = (num >>> k) & 1;
            int desired = bit ^ 1;
            int next = -1;
            if (trie.get(idx).child[desired] != -1 && trie.get(trie.get(idx).child[desired]).cnt > 0) {
                next = trie.get(idx).child[desired];
                xor |= (1 << k);
            } else {
                next = trie.get(idx).child[bit];
            }
            idx = next;
        }
        return xor;
    }

    public static int maximumStrongPairXor(int[] nums) {
        int n = nums.length;
        if (n == 0) return 0;
        Arrays.sort(nums);
        List<Node> trie = new ArrayList<>();
        trie.add(new Node());
        int maxXor = 0;
        int r = 0;
        for (int l = 0; l < n; l++) {
            while (r < n && (long) nums[r] <= 2L * (long) nums[l]) {
                insert(trie, nums[r]);
                r++;
            }
            int candidate = query(trie, nums[l]);
            if (candidate > maxXor) maxXor = candidate;
            delete(trie, nums[l]);
        }
        return maxXor;
    }
}

class Solution {
    public static long minCoins(int[] prices) {
        int n = prices.length;
        long[] dp = new long[n+1];
        java.util.Arrays.fill(dp, Long.MAX_VALUE/2);
        dp[0] = 0;
        for (int i = 1; i <= n; i++) {
            int lo = (i+1)/2;
            for (int j = lo; j <= i; j++) {
                long cost = dp[j-1] + prices[j-1];
                if (cost < dp[i]) dp[i] = cost;
            }
        }
        return dp[n];
    }
}

