import java.util.*;

class Solution {
    private static int[] seg;
    private static int[] heights;

    private static void build(int node, int l, int r) {
        if (l == r) {
            seg[node] = heights[l];
            return;
        }
        int mid = (l + r) >>> 1;
        build(node << 1, l, mid);
        build(node << 1 | 1, mid + 1, r);
        seg[node] = Math.max(seg[node << 1], seg[node << 1 | 1]);
    }

    private static int queryFirst(int node, int l, int r, int ql, int threshold) {
        if (r < ql || seg[node] < threshold) {
            return -1;
        }
        if (l == r) {
            return l;
        }
        int mid = (l + r) >>> 1;
        int left = queryFirst(node << 1, l, mid, ql, threshold);
        if (left != -1) {
            return left;
        }
        return queryFirst(node << 1 | 1, mid + 1, r, ql, threshold);
    }

    public static int[] leftmostBuildingQueries(int[] heightsInput, int[][] queries) {
        heights = heightsInput;
        int n = heights.length;
        seg = new int[4 * n];
        build(1, 0, n - 1);
        int m = queries.length;
        int[] ans = new int[m];
        for (int i = 0; i < m; i++) {
            int a = queries[i][0];
            int b = queries[i][1];
            if (a == b) {
                ans[i] = a;
                continue;
            }
            int start = Math.max(a, b);
            int threshold = Math.max(heights[a], heights[b]);
            ans[i] = queryFirst(1, 0, n - 1, start, threshold);
        }
        return ans;
    }
}

