class Solution {
    public static int findMaximumLength(int[] nums) {
        long prevSum = 0;
        long curSum = 0;
        int count = 0;
        for (int x : nums) {
            curSum += x;
            if (curSum >= prevSum) {
                count++;
                prevSum = curSum;
                curSum = 0;
            }
        }
        // If there is leftover sum that couldn't form a non‑decreasing group,
        // it must be merged with the previous group, so count remains unchanged.
        return count;
    }
}

import java.util.*;

class Solution {
    public static boolean findRotation(int[][] mat, int k) {
        if (mat == null || mat.length == 0 || mat[0].length == 0) {
            return true;
        }
        int rows = mat.length;
        int cols = mat[0].length;
        int shift = k % cols;
        int[][] original = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            System.arraycopy(mat[i], 0, original[i], 0, cols);
        }
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int expected;
                if (i % 2 == 0) {
                    int origCol = (j - shift + cols) % cols;
                    expected = original[i][origCol];
                } else {
                    int origCol = (j + shift) % cols;
                    expected = original[i][origCol];
                }
                if (mat[i][j] != expected) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.lang.Math;

class Solution {
    public static int makeThreeStringsEqual(String s1, String s2, String s3) {
        int i = 0;
        int limit = Math.min(Math.min(s1.length(), s2.length()), s3.length());
        while (i < limit && s1.charAt(i) == s2.charAt(i) && s1.charAt(i) == s3.charAt(i)) {
            i++;
        }
        if (i == 0) return -1;
        return (s1.length() - i) + (s2.length() - i) + (s3.length() - i);
    }
}

import java.util.*;

class Solution {
    public static int[] smallestArray(int[] nums, int limit) {
        int n = nums.length;
        int[][] pairs = new int[n][2];
        for (int i = 0; i < n; i++) {
            pairs[i][0] = nums[i];
            pairs[i][1] = i;
        }
        Arrays.sort(pairs, Comparator.comparingInt(a -> a[0]));
        DSU dsu = new DSU(n);
        for (int i = 1; i < n; i++) {
            if (pairs[i][0] - pairs[i - 1][0] <= limit) {
                dsu.union(pairs[i][1], pairs[i - 1][1]);
            }
        }
        Map<Integer, List<Integer>> groups = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int root = dsu.find(i);
            groups.computeIfAbsent(root, k -> new ArrayList<>()).add(i);
        }
        for (List<Integer> idxList : groups.values()) {
            Collections.sort(idxList);
            List<Integer> vals = new ArrayList<>(idxList.size());
            for (int idx : idxList) {
                vals.add(nums[idx]);
            }
            Collections.sort(vals);
            for (int i = 0; i < idxList.size(); i++) {
                nums[idxList.get(i)] = vals.get(i);
            }
        }
        return nums;
    }

    private static class DSU {
        int[] parent;
        int[] rank;
        DSU(int size) {
            parent = new int[size];
            rank = new int[size];
            for (int i = 0; i < size; i++) parent[i] = i;
        }
        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }
        void union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return;
            if (rank[ra] < rank[rb]) {
                parent[ra] = rb;
            } else if (rank[ra] > rank[rb]) {
                parent[rb] = ra;
            } else {
                parent[rb] = ra;
                rank[ra]++;
            }
        }
    }
}

