class Solution {
    public static long countBeautifulSubstrings(String s, int k) {
        long count = 0;
        Set<Character> vowels = new HashSet<>();
        vowels.add('a');
        vowels.add('e');
        vowels.add('i');
        vowels.add('o');
        vowels.add('u');
        for (int i = 0; i < s.length(); i++) {
            for (int j = i + 1; j <= s.length(); j++) {
                int vowelCount = 0;
                int consonantCount = 0;
                for (int m = i; m < j; m++) {
                    char ch = s.charAt(m);
                    if (vowels.contains(ch)) vowelCount++;
                    else consonantCount++;
                }
                if (vowelCount == consonantCount && (vowelCount * consonantCount) % k == 0) {
                    count++;
                }
            }
        }
        return count;
    }
}

