class Solution {
    public static int minOperations(String word) {
        int n = word.length();
        if (n <= 1) return 0;
        int keep = 1;
        int notKeep = 0;
        for (int i = 1; i < n; i++) {
            boolean bad = Math.abs(word.charAt(i) - word.charAt(i - 1)) <= 1;
            int newKeep = bad ? notKeep + 1 : Math.max(keep, notKeep) + 1;
            int newNot = Math.max(keep, notKeep);
            keep = newKeep;
            notKeep = newNot;
        }
        int maxKept = Math.max(keep, notKeep);
        return n - maxKept;
    }
}

import java.util.*;

class Solution {
    private static final long MOD = 1_000_000_007L;

    private static long modPow(long base, long exp) {
        long result = 1;
        long b = base % MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * b) % MOD;
            }
            b = (b * b) % MOD;
            exp >>= 1;
        }
        return result;
    }

    public static long numInfectionSequences(int n, int[] sick) {
        Arrays.sort(sick);
        long[] fact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }
        if (sick.length == 0) {
            return fact[n];
        }
        long[] invFact = new long[n + 1];
        invFact[n] = modPow(fact[n], MOD - 2);
        for (int i = n; i > 0; i--) {
            invFact[i - 1] = (invFact[i] * i) % MOD;
        }
        int totalUninfected = n - sick.length;
        long res = fact[totalUninfected];
        int leftGap = sick[0];
        if (leftGap > 0) {
            res = (res * invFact[leftGap]) % MOD;
        }
        for (int i = 1; i < sick.length; i++) {
            int gap = sick[i] - sick[i - 1] - 1;
            if (gap > 0) {
                res = (res * invFact[gap]) % MOD;
                res = (res * modPow(2, gap - 1)) % MOD;
            }
        }
        int rightGap = (n - 1) - sick[sick.length - 1];
        if (rightGap > 0) {
            res = (res * invFact[rightGap]) % MOD;
        }
        return res;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static int longestSubarray(int[] nums, int k) {
        int maxLength = 0;
        Map<Integer, Integer> frequencyMap = new HashMap<>();
        int left = 0;
        int exceedCount = 0;
        for (int right = 0; right < nums.length; right++) {
            int val = nums[right];
            int newFreq = frequencyMap.getOrDefault(val, 0) + 1;
            frequencyMap.put(val, newFreq);
            if (newFreq == k + 1) {
                exceedCount++;
            }
            while (exceedCount > 0) {
                int leftVal = nums[left];
                int freq = frequencyMap.get(leftVal);
                if (freq == k + 1) {
                    exceedCount--;
                }
                freq--;
                if (freq == 0) {
                    frequencyMap.remove(leftVal);
                } else {
                    frequencyMap.put(leftVal, freq);
                }
                left++;
            }
            maxLength = Math.max(maxLength, right - left + 1);
        }
        return maxLength;
    }
}

