class Solution {
    public static int[] findErrorNums(int[][] grid) {
        int n = grid.length;
        int[] count = new int[n * n + 1];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                count[grid[i][j]]++;
            }
        }
        int a = 0, b = 0;
        for (int i = 1; i <= n * n; i++) {
            if (count[i] == 0) b = i;
            else if (count[i] == 2) a = i;
        }
        return new int[]{a, b};
    }
}

