class Solution {
    public static List<Integer> findGoodIndices(int[][] variables, int target) {
        List<Integer> goodIndices = new ArrayList<>();
        for (int i = 0; i < variables.length; i++) {
            int a = variables[i][0];
            int b = variables[i][1];
            int c = variables[i][2];
            int m = variables[i][3];
            int result = (int) (Math.pow((Math.pow(a, b) % 10), c) % m);
            if (result == target) {
                goodIndices.add(i);
            }
        }
        return goodIndices;
    }
}

class Solution {
    public static int countTestedDevices(int[] batteryPercentages) {
        int testedDevices = 0;
        for (int i = 0; i < batteryPercentages.length; i++) {
            if (batteryPercentages[i] > 0) {
                testedDevices++;
                for (int j = i + 1; j < batteryPercentages.length; j++) {
                    batteryPercentages[j]--;
                    if (batteryPercentages[j] < 0) {
                        batteryPercentages[j] = 0;
                    }
                }
            }
        }
        return testedDevices;
    }
}

