class Solution {
    public static int numberOfSubarrays(int[] nums, int k) {
        int n = nums.length;
        long count = 0;
        for (int i = 0; i < n; i++) {
            int max = Integer.MIN_VALUE;
            int freq = 0;
            for (int j = i; j < n; j++) {
                int v = nums[j];
                if (v > max) {
                    max = v;
                    freq = 1;
                } else if (v == max) {
                    freq++;
                }
                if (freq >= k) {
                    count++;
                }
            }
        }
        return (int) count;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static int countGoodPartitions(int[] nums) {
        final int MOD = 1_000_000_007;
        int n = nums.length;
        Map<Integer, Integer> lastPos = new HashMap<>();
        for (int i = 0; i < n; i++) {
            lastPos.put(nums[i], i);
        }
        int splits = 0;
        int maxReach = -1;
        for (int i = 0; i < n - 1; i++) {
            maxReach = Math.max(maxReach, lastPos.get(nums[i]));
            if (maxReach == i) {
                splits++;
            }
        }
        long result = 1;
        long base = 2;
        int exp = splits;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return (int) result;
    }
}

import java.util.*;

public class Solution {
    public static long numberOfSets(int n, int maxDistance, int[][] roads) {
        final long INF = Long.MAX_VALUE / 4;
        long ans = 0;
        int totalMasks = 1 << n;
        for (int mask = 0; mask < totalMasks; mask++) {
            int closedCount = Integer.bitCount(mask);
            int remaining = n - closedCount;
            if (remaining <= 1) {
                ans++;
                continue;
            }
            long[][] dist = new long[n][n];
            for (int i = 0; i < n; i++) {
                Arrays.fill(dist[i], INF);
                if ((mask & (1 << i)) == 0) {
                    dist[i][i] = 0;
                }
            }
            for (int[] r : roads) {
                int u = r[0];
                int v = r[1];
                int w = r[2];
                if ((mask & (1 << u)) != 0 || (mask & (1 << v)) != 0) continue;
                if (w < dist[u][v]) {
                    dist[u][v] = w;
                    dist[v][u] = w;
                }
            }
            for (int k = 0; k < n; k++) {
                if ((mask & (1 << k)) != 0) continue;
                for (int i = 0; i < n; i++) {
                    if ((mask & (1 << i)) != 0) continue;
                    if (dist[i][k] == INF) continue;
                    for (int j = 0; j < n; j++) {
                        if ((mask & (1 << j)) != 0) continue;
                        long nd = dist[i][k] + dist[k][j];
                        if (nd < dist[i][j]) {
                            dist[i][j] = nd;
                        }
                    }
                }
            }
            boolean ok = true;
            outer:
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue;
                for (int j = i + 1; j < n; j++) {
                    if ((mask & (1 << j)) != 0) continue;
                    long d = dist[i][j];
                    if (d == INF || d > maxDistance) {
                        ok = false;
                        break outer;
                    }
                }
            }
            if (ok) ans++;
        }
        return ans;
    }
}

