public class Solution {
    public static int numberOfSubarrays(int[] nums) {
        int count = 0;
        for (int i = 0; i < nums.length; i++) {
            for (int j = i; j < nums.length; j++) {
                int newLen = nums.length - (j - i + 1);
                int[] temp = new int[newLen];
                int idx = 0;
                for (int k = 0; k < i; k++) {
                    temp[idx++] = nums[k];
                }
                for (int k = j + 1; k < nums.length; k++) {
                    temp[idx++] = nums[k];
                }
                if (isIncreasing(temp)) {
                    count++;
                }
            }
        }
        return count;
    }

    private static boolean isIncreasing(int[] arr) {
        for (int i = 0; i + 1 < arr.length; i++) {
            if (arr[i] >= arr[i + 1]) {
                return false;
            }
        }
        return true;
    }
}

