class Solution {
    public static long minCostToMakeArrayEqualindromic(int[] nums) {
        if (nums == null || nums.length == 0) return 0L;
        int n = nums.length;
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        Set<Long> candidates = new HashSet<>();
        if (n % 2 == 1) {
            addCandidates(sorted[n / 2], candidates);
        } else {
            addCandidates(sorted[n / 2 - 1], candidates);
            addCandidates(sorted[n / 2], candidates);
        }
        long minCost = Long.MAX_VALUE;
        for (long p : candidates) {
            long cost = 0;
            for (int num : nums) {
                cost += Math.abs((long) num - p);
            }
            if (cost < minCost) minCost = cost;
        }
        return minCost;
    }

    private static void addCandidates(long num, Set<Long> set) {
        if (num < 0) return;
        set.add(0L);
        String s = Long.toString(num);
        int len = s.length();
        boolean odd = (len & 1) == 1;
        int prefixLen = (len + 1) / 2;
        long prefix = Long.parseLong(s.substring(0, prefixLen));
        for (int delta = -1; delta <= 1; delta++) {
            long newPrefix = prefix + delta;
            if (newPrefix <= 0) continue;
            String prefStr = Long.toString(newPrefix);
            String left = odd ? prefStr.substring(0, prefStr.length() - 1) : prefStr;
            StringBuilder rev = new StringBuilder(left).reverse();
            long pal = Long.parseLong(prefStr + rev.toString());
            set.add(pal);
        }
        long pow10 = 1;
        for (int i = 0; i < len; i++) pow10 *= 10;
        set.add(pow10 - 1); // 99...9
        set.add(pow10 + 1); // 100...001
        if (len > 1) {
            long pow10Prev = pow10 / 10;
            set.add(pow10Prev - 1); // 9...9 with one less digit
        }
    }
}

