class Solution {
    public static int maxFrequencyScore(int[] nums, int k) {
        Arrays.sort(nums);
        int n = nums.length;
        long[] prefix = new long[n];
        for (int i = 0; i < n; i++) {
            prefix[i] = nums[i] + (i > 0 ? prefix[i - 1] : 0);
        }
        int left = 0;
        int maxScore = 0;
        for (int right = 0; right < n; right++) {
            while (left <= right) {
                int mid = (left + right) >>> 1;
                long leftSum = prefix[mid] - (left > 0 ? prefix[left - 1] : 0);
                long rightSum = prefix[right] - prefix[mid];
                long leftCost = (long) nums[mid] * (mid - left + 1) - leftSum;
                long rightCost = rightSum - (long) nums[mid] * (right - mid);
                long totalCost = leftCost + rightCost;
                if (totalCost <= k) {
                    break;
                }
                left++;
            }
            maxScore = Math.max(maxScore, right - left + 1);
        }
        return maxScore;
    }
}

import java.util.Arrays;

class Solution {
    public static int largestPerimeter(int[] nums) {
        Arrays.sort(nums);
        long total = 0;
        for (int v : nums) {
            total += v;
        }
        for (int i = nums.length - 1; i >= 2; i--) {
            if (total - nums[i] > nums[i]) {
                return (int) total;
            }
            total -= nums[i];
        }
        return -1;
    }
}

