class Solution {
    public static List<Integer> minimumNumberGame(List<Integer> nums) {
        List<Integer> sorted = new ArrayList<>(nums);
        Collections.sort(sorted);
        List<Integer> result = new ArrayList<>(sorted.size());
        int i = 0;
        int n = sorted.size();
        while (i + 1 < n) {
            result.add(sorted.get(i + 1));
            result.add(sorted.get(i));
            i += 2;
        }
        if (i < n) {
            result.add(sorted.get(i));
        }
        return result;
    }
}

