class Solution {
    public static long[] placedCoins(int[][] edges, int[] cost) {
        int n = cost.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }
        long[] answer = new long[n];
        long[][] top = new long[n][3];
        int[] size = new int[n];
        dfs(0, -1, graph, cost, answer, top, size);
        return answer;
    }

    private static void dfs(int node, int parent, List<Integer>[] graph, int[] cost,
                            long[] answer, long[][] top, int[] size) {
        size[node] = 1;
        long[] cur = new long[]{cost[node], Long.MIN_VALUE, Long.MIN_VALUE};

        for (int nb : graph[node]) {
            if (nb == parent) continue;
            dfs(nb, node, graph, cost, answer, top, size);
            size[node] += size[nb];

            long[] childTop = top[nb];
            long[] merged = new long[6];
            merged[0] = cur[0];
            merged[1] = cur[1];
            merged[2] = cur[2];
            merged[3] = childTop[0];
            merged[4] = childTop[1];
            merged[5] = childTop[2];

            long[] newTop = new long[]{Long.MIN_VALUE, Long.MIN_VALUE, Long.MIN_VALUE};
            for (long v : merged) {
                if (v > newTop[0]) {
                    newTop[2] = newTop[1];
                    newTop[1] = newTop[0];
                    newTop[0] = v;
                } else if (v > newTop[1]) {
                    newTop[2] = newTop[1];
                    newTop[1] = v;
                } else if (v > newTop[2]) {
                    newTop[2] = v;
                }
            }
            cur = newTop;
        }

        top[node] = cur;
        if (size[node] < 3) {
            answer[node] = 1;
        } else {
            long prod = cur[0] * cur[1] * cur[2];
            answer[node] = prod > 0 ? prod : 0;
        }
    }
}

import java.util.*;

class Solution {
    public static int numberOfSubarrays(int[] nums) {
        int count = 0;
        for (int i = 0; i < nums.length; i++) {
            for (int j = i; j < nums.length; j++) {
                int newLen = nums.length - (j - i + 1);
                int[] temp = new int[newLen];
                int idx = 0;
                for (int p = 0; p < i; p++) {
                    temp[idx++] = nums[p];
                }
                for (int p = j + 1; p < nums.length; p++) {
                    temp[idx++] = nums[p];
                }
                boolean isIncreasing = true;
                for (int k = 0; k < temp.length - 1; k++) {
                    if (temp[k] >= temp[k + 1]) {
                        isIncreasing = false;
                        break;
                    }
                }
                if (isIncreasing) {
                    count++;
                }
            }
        }
        return count;
    }
}

