class Solution {
    public static long maximizeSquareArea(long m, long n, int[] hFences, int[] vFences) {
        Arrays.sort(hFences);
        Arrays.sort(vFences);

        long[] hPos = new long[hFences.length + 2];
        hPos[0] = 1;
        for (int i = 0; i < hFences.length; i++) {
            hPos[i + 1] = hFences[i];
        }
        hPos[hFences.length + 1] = m;

        long[] vPos = new long[vFences.length + 2];
        vPos[0] = 1;
        for (int i = 0; i < vFences.length; i++) {
            vPos[i + 1] = vFences[i];
        }
        vPos[vFences.length + 1] = n;

        int hGapCount = hPos.length - 1;
        long[] hGaps = new long[hGapCount];
        for (int i = 0; i < hGapCount; i++) {
            hGaps[i] = hPos[i + 1] - hPos[i];
        }

        int vGapCount = vPos.length - 1;
        long[] vGaps = new long[vGapCount];
        for (int i = 0; i < vGapCount; i++) {
            vGaps[i] = vPos[i + 1] - vPos[i];
        }

        HashSet<Long> possibleSides = new HashSet<>();
        for (int i = 0; i < hGapCount; i++) {
            long sum = 0;
            for (int j = i; j < hGapCount; j++) {
                sum += hGaps[j];
                possibleSides.add(sum);
            }
        }

        long maxSide = -1;
        for (int i = 0; i < vGapCount; i++) {
            long sum = 0;
            for (int j = i; j < vGapCount; j++) {
                sum += vGaps[j];
                if (possibleSides.contains(sum) && sum > maxSide) {
                    maxSide = sum;
                }
            }
        }

        if (maxSide == -1) {
            return -1;
        }

        long MOD = 1_000_000_007L;
        long sideMod = maxSide % MOD;
        return (sideMod * sideMod) % MOD;
    }
}

