class Solution {
    static class Edge {
        String to;
        int cost;
        Edge(String to, int cost) {
            this.to = to;
            this.cost = cost;
        }
    }
    static class Node {
        String str;
        long cost;
        Node(String str, long cost) {
            this.str = str;
            this.cost = cost;
        }
    }
    public int minimumCost(String source, String target, String[] original, String[] changed, int[] cost) {
        int n = source.length();
        // group operations by length
        Map<Integer, Map<String, Map<String, Integer>>> opsByLen = new HashMap<>();
        for (int i = 0; i < original.length; i++) {
            int len = original[i].length(); // same as changed[i].length()
            Map<String, Map<String, Integer>> mapOrig = opsByLen.computeIfAbsent(len, k -> new HashMap<>());
            Map<String, Integer> toMap = mapOrig.computeIfAbsent(original[i], k -> new HashMap<>());
            toMap.merge(changed[i], cost[i], Math::min);
        }

        long INF = Long.MAX_VALUE / 4;
        long[] dp = new long[n + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;

        for (int i = 0; i < n; i++) {
            if (dp[i] == INF) continue;
            for (int j = i + 1; j <= n; j++) {
                long intervalCost = getIntervalCost(source, target, i, j, opsByLen);
                if (intervalCost == INF) continue;
                if (dp[i] + intervalCost < dp[j]) {
                    dp[j] = dp[i] + intervalCost;
                }
            }
        }

        return dp[n] == INF ? -1 : (int) dp[n];
    }

    private long getIntervalCost(String source, String target, int start, int end,
                                 Map<Integer, Map<String, Map<String, Integer>>> opsByLen) {
        String src = source.substring(start, end);
        String tgt = target.substring(start, end);
        if (src.equals(tgt)) return 0;
        int len = end - start;
        Map<String, Map<String, Integer>> mapOrig = opsByLen.get(len);
        if (mapOrig == null) return Long.MAX_VALUE / 4;

        PriorityQueue<Node> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a.cost));
        Map<String, Long> dist = new HashMap<>();
        dist.put(src, 0L);
        pq.add(new Node(src, 0L));

        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            Long recorded = dist.get(cur.str);
            if (recorded == null || cur.cost != recorded) continue;
            if (cur.str.equals(tgt)) return cur.cost;
            Map<String, Integer> outs = mapOrig.get(cur.str);
            if (outs == null) continue;
            for (Map.Entry<String, Integer> e : outs.entrySet()) {
                long nd = cur.cost + e.getValue();
                Long prev = dist.get(e.getKey());
                if (prev == null || nd < prev) {
                    dist.put(e.getKey(), nd);
                    pq.add(new Node(e.getKey(), nd));
                }
            }
        }
        return Long.MAX_VALUE / 4;
    }
}

import java.util.*;

class Solution {
    public static int minimumCost(String source, String target, char[] original, char[] changed, int[] cost) {
        int n = 26;
        long INF = Long.MAX_VALUE / 4;
        long[][] dist = new long[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(dist[i], INF);
            dist[i][i] = 0;
        }
        for (int i = 0; i < original.length; i++) {
            int u = original[i] - 'a';
            int v = changed[i] - 'a';
            if (cost[i] < dist[u][v]) {
                dist[u][v] = cost[i];
            }
        }
        for (int k = 0; k < n; k++) {
            for (int i = 0; i < n; i++) {
                if (dist[i][k] == INF) continue;
                for (int j = 0; j < n; j++) {
                    if (dist[k][j] == INF) continue;
                    long nd = dist[i][k] + dist[k][j];
                    if (nd < dist[i][j]) {
                        dist[i][j] = nd;
                    }
                }
            }
        }
        long total = 0;
        for (int i = 0; i < source.length(); i++) {
            char sc = source.charAt(i);
            char tc = target.charAt(i);
            if (sc == tc) continue;
            long d = dist[sc - 'a'][tc - 'a'];
            if (d == INF) return -1;
            total += d;
        }
        return (int) total;
    }
}

import java.util.*;

class Solution {
    public static int longestSpecialSubstring(String s) {
        int n = s.length();
        if (n == 0) return -1;
        final long BASE = 91138233L;
        long[] pow = new long[n + 1];
        long[] pref = new long[n + 1];
        long[] revPref = new long[n + 1];
        pow[0] = 1;
        for (int i = 0; i < n; i++) {
            pow[i + 1] = pow[i] * BASE;
            pref[i + 1] = pref[i] * BASE + s.charAt(i);
            revPref[i + 1] = revPref[i] * BASE + s.charAt(n - 1 - i);
        }
        for (int len = n; len >= 1; len--) {
            HashMap<Long, Integer> countMap = new HashMap<>();
            for (int i = 0; i + len <= n; i++) {
                int l = i, r = i + len;
                long hash = pref[r] - pref[l] * pow[len];
                long revHash = revPref[n - l] - revPref[n - r] * pow[len];
                if (hash == revHash) {
                    countMap.merge(hash, 1, Integer::sum);
                }
            }
            for (int cnt : countMap.values()) {
                if (cnt >= 3) {
                    return len;
                }
            }
        }
        return -1;
    }
}

import java.util.*;

class Solution {
    public static int longestSpecialSubstring(String s) {
        int n = s.length();
        if (n == 0) return -1;
        int low = 1, high = n, best = -1;
        long[] pow1 = new long[n + 1];
        long[] pow2 = new long[n + 1];
        final long MOD1 = 1_000_000_007L;
        final long MOD2 = 1_000_000_009L;
        final long BASE = 91138233L;
        pow1[0] = 1;
        pow2[0] = 1;
        for (int i = 1; i <= n; i++) {
            pow1[i] = (pow1[i - 1] * BASE) % MOD1;
            pow2[i] = (pow2[i - 1] * BASE) % MOD2;
        }
        long[] pref1 = new long[n + 1];
        long[] pref2 = new long[n + 1];
        for (int i = 0; i < n; i++) {
            int val = s.charAt(i);
            pref1[i + 1] = (pref1[i] * BASE + val) % MOD1;
            pref2[i + 1] = (pref2[i] * BASE + val) % MOD2;
        }
        while (low <= high) {
            int mid = (low + high) >>> 1;
            if (exists(mid, n, pref1, pref2, pow1, pow2, MOD1, MOD2)) {
                best = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return best;
    }

    private static boolean exists(int len, int n, long[] pref1, long[] pref2,
                                  long[] pow1, long[] pow2, long mod1, long mod2) {
        if (len == 0) return true;
        Map<Long, Integer> count = new HashMap<>();
        for (int i = 0; i + len <= n; i++) {
            long h1 = (pref1[i + len] - (pref1[i] * pow1[len]) % mod1 + mod1) % mod1;
            long h2 = (pref2[i + len] - (pref2[i] * pow2[len]) % mod2 + mod2) % mod2;
            long key = (h1 << 32) ^ h2;
            int c = count.getOrDefault(key, 0) + 1;
            if (c >= 3) return true;
            count.put(key, c);
        }
        return false;
    }
}

