class Solution {
    public static List<Boolean> canMakePalindrome(String s, int[][] queries) {
        int n = s.length();
        List<Boolean> result = new ArrayList<>();
        for (int[] q : queries) {
            int a = q[0], b = q[1], c = q[2], d = q[3];
            boolean[] inside = new boolean[n];
            for (int i = a; i <= b; i++) inside[i] = true;
            for (int i = c; i <= d; i++) inside[i] = true;
            int[] freq = new int[26];
            for (int i = 0; i < n; i++) {
                if (inside[i]) freq[s.charAt(i) - 'a']++;
            }
            boolean ok = true;
            for (int i = 0; i < n; i++) {
                int j = n - 1 - i;
                if (i > j) break;
                boolean inI = inside[i];
                boolean inJ = inside[j];
                if (!inI && !inJ) {
                    if (s.charAt(i) != s.charAt(j)) {
                        ok = false;
                        break;
                    }
                } else if (!inI && inJ) {
                    freq[s.charAt(i) - 'a']--;
                } else if (inI && !inJ) {
                    freq[s.charAt(j) - 'a']--;
                }
            }
            if (ok) {
                for (int cnt : freq) {
                    if (cnt < 0) {
                        ok = false;
                        break;
                    }
                }
            }
            if (ok) {
                int odd = 0;
                for (int cnt : freq) {
                    if ((cnt & 1) == 1) odd++;
                }
                if (n % 2 == 1 && inside[n / 2]) {
                    if (odd > 1) ok = false;
                } else {
                    if (odd != 0) ok = false;
                }
            }
            result.add(ok);
        }
        return result;
    }
}

import java.util.*;
class Solution {
    public static int minOperations(int x, int y) {
        if (x == y) return 0;
        Queue<int[]> q = new LinkedList<>();
        q.add(new int[]{x, 0});
        Set<Integer> visited = new HashSet<>();
        visited.add(x);
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int current = cur[0], steps = cur[1];
            if (current == y) return steps;
            List<Integer> nexts = new ArrayList<>();
            if (current % 5 == 0) nexts.add(current/5);
            if (current % 11 == 0) nexts.add(current/11);
            nexts.add(current+1);
            nexts.add(current-1);
            for (int nxt : nexts) {
                if (nxt <= 0 || visited.contains(nxt)) continue;
                visited.add(nxt);
                q.add(new int[]{nxt, steps+1});
            }
        }
        return -1;
    }
}

public class Solution {
