            double diagonalLength = Math.sqrt(dimensions[i][0] * dimensions[i][0] + dimensions[i][1] * dimensions[i][1]);
            if (diagonalLength > maxDiagonal) {
                maxDiagonal = diagonalLength;
                maxArea = dimensions[i][0] * dimensions[i][1];
            }
        }
        return maxArea;
    }
}

