class Solution {
    public static int minMovesToCaptureTheQueen(int a, int b, int c, int d, int e, int f) {
        // Check if rook can capture queen in one move
        boolean rookCan = false;
        if (a == e) { // same row
            if (!(c == a && between(b, f, d))) { // bishop not blocking
                rookCan = true;
            }
        } else if (b == f) { // same column
            if (!(d == b && between(a, e, c))) { // bishop not blocking
                rookCan = true;
            }
        }

        // Check if bishop can capture queen in one move
        boolean bishopCan = false;
        if (Math.abs(c - e) == Math.abs(d - f)) { // same diagonal
            // check if rook blocks the diagonal
            if (!(Math.abs(a - e) == Math.abs(b - f) && between(c, e, a) && between(d, f, b))) {
                bishopCan = true;
            }
        }

        if (rookCan || bishopCan) {
            return 1;
        }
        return 2;
    }

    private static boolean between(int start, int end, int middle) {
        return (middle > Math.min(start, end)) && (middle < Math.max(start, end));
    }
}

import java.util.HashSet;
import java.util.Set;

class Solution {
    public static int maxPartitions(String s, int k) {
        int max = 0;
        for (int i = 0; i < s.length(); i++) {
            Set<Character> set = new HashSet<>();
            for (int j = 0; j < s.length(); j++) {
                if (i == j) {
                    for (int c = (int) 'a'; c <= (int) 'z'; c++) {
                        char ch = (char) c;
                        if (ch != s.charAt(j)) {
                            set.add(ch);
                        } else {
                            set.add(s.charAt(j));
                        }
                        if (set.size() <= k) {
                            int partitions = 1;
                            Set<Character> distinct = new HashSet<>();
                            for (int x = 0; x < s.length(); x++) {
                                if (x == j) {
                                    distinct.add(ch);
                                } else {
                                    distinct.add(s.charAt(x));
                                }
                                if (distinct.size() > k) {
                                    partitions++;
                                    distinct.clear();
                                    if (x == j) {
                                        distinct.add(ch);
                                    } else {
                                        distinct.add(s.charAt(x));
                                    }
                                }
                            }
                            max = Math.max(max, partitions);
                        }
                        set.clear();
                    }
                } else {
                    set.add(s.charAt(j));
                }
            }
        }
        Set<Character> set = new HashSet<>();
        int partitions = 1;
        for (int i = 0; i < s.length(); i++) {
            set.add(s.charAt(i));
            if (set.size() > k) {
                partitions++;
                set.clear();
                set.add(s.charAt(i));
            }
        }
        max = Math.max(max, partitions);
        return max;
    }
}

