        int added = 0;
        int i = 0;
        while (maxReach < target) {
            if (i < coins.length && coins[i] <= maxReach + 1) {
                maxReach += coins[i];
                i++;
            } else {
                added++;
                maxReach += maxReach + 1;
            }
        }
        return added;
    }
