class Solution {
    public static long findMaximumNumber(long k, int x) {
        long high = 1;
        while (true) {
            long price = accumulatedPriceCapped(high, x, k);
            if (price > k) break;
            if (high > Long.MAX_VALUE / 2) {
                high = Long.MAX_VALUE;
                break;
            }
            high <<= 1;
        }
        long low = 0;
        while (low < high) {
            long mid = low + (high - low + 1) / 2;
            if (accumulatedPriceCapped(mid, x, k) <= k) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return low;
    }

    private static long accumulatedPriceCapped(long n, int x, long cap) {
        long total = 0;
        for (int idx = x - 1; ; idx += x) {
            if (idx >= 63) break;
            long bit = 1L << idx;
            if (bit == 0) break;
            long period = bit << 1;
            if (period == 0) break;
            long fullCycles = (n + 1) / period;
            long remainder = (n + 1) % period;
            long setBits = fullCycles * bit + Math.max(0L, remainder - bit);
            if (setBits > cap) setBits = cap;
            total += setBits;
            if (total > cap) return cap + 1;
            if (bit > n) break;
        }
        return total;
    }
}

