class Solution {
    public static long minimumKeypresses(String word) {
        int[] freq = new int[26];
        for (char c : word.toCharArray()) {
            freq[c - 'a']++;
        }
        List<Integer> frequencies = new ArrayList<>();
        for (int f : freq) {
            if (f > 0) {
                frequencies.add(f);
            }
        }
        frequencies.sort(Collections.reverseOrder());
        long pushes = 0;
        int press = 1;
        int index = 0;
        while (index < frequencies.size()) {
            for (int i = 0; i < 8 && index < frequencies.size(); i++) {
                pushes += (long) press * frequencies.get(index++);
            }
            press++;
        }
        return pushes;
    }
}

