public class HousesFast {
    static long[] countOfPairs(int n, int x, int y) {
        x--; y--;
        if (x > y) { int t = x; x = y; y = t; }
        long[] diff = new long[n];
        for (int i = 0; i < n; i++) {
            diff[0] += 2;
            diff[Math.min(Math.abs(i - x), Math.abs(i - y) + 1)] += 1;
            diff[Math.min(Math.abs(i - y), Math.abs(i - x) + 1)] += 1;
            diff[Math.min(Math.abs(i - 0), Math.abs(i - y) + 1 + Math.abs(x - 0))] -= 1;
            diff[Math.min(Math.abs(i - (n - 1)), Math.abs(i - x) + 1 + Math.abs(y - (n - 1)))] -= 1;
            diff[Math.max(x - i, 0) + Math.max(i - y, 0) + (y - x) / 2] -= 1;
            diff[Math.max(x - i, 0) + Math.max(i - y, 0) + (y - x + 1) / 2] -= 1;
        }
        for (int i = 0; i + 1 < n; i++) diff[i+1] += diff[i];
        return diff;
    }
}

