class Solution {
    public static int countValidPairs(int[][] points) {
        int n = points.length;
        int[] xs = new int[n];
        int[] ys = new int[n];
        for (int i = 0; i < n; i++) {
            xs[i] = points[i][0];
            ys[i] = points[i][1];
        }
        Arrays.sort(xs);
        Arrays.sort(ys);
        int nx = 1;
        for (int i = 1; i < n; i++) if (xs[i] != xs[i - 1]) nx++;
        int ny = 1;
        for (int i = 1; i < n; i++) if (ys[i] != ys[i - 1]) ny++;
        int[] uniqX = new int[nx];
        int[] uniqY = new int[ny];
        uniqX[0] = xs[0];
        uniqY[0] = ys[0];
        int idx = 1;
        for (int i = 1; i < n; i++) if (xs[i] != xs[i - 1]) uniqX[idx++] = xs[i];
        idx = 1;
        for (int i = 1; i < n; i++) if (ys[i] != ys[i - 1]) uniqY[idx++] = ys[i];
        HashMap<Integer, Integer> xIndex = new HashMap<>(nx * 2);
        HashMap<Integer, Integer> yIndex = new HashMap<>(ny * 2);
        for (int i = 0; i < nx; i++) xIndex.put(uniqX[i], i + 1);
        for (int i = 0; i < ny; i++) yIndex.put(uniqY[i], i + 1);
        int[][] ps = new int[nx + 1][ny + 1];
        for (int[] p : points) {
            int xi = xIndex.get(p[0]);
            int yi = yIndex.get(p[1]);
            ps[xi][yi] = 1;
        }
        for (int i = 1; i <= nx; i++) {
            int rowSum = 0;
            for (int j = 1; j <= ny; j++) {
                rowSum += ps[i][j];
                ps[i][j] = ps[i - 1][j] + rowSum;
            }
        }
        int ans = 0;
        for (int a = 0; a < n; a++) {
            int xa = points[a][0];
            int ya = points[a][1];
            int xiA = xIndex.get(xa);
            int yiA = yIndex.get(ya);
            for (int b = 0; b < n; b++) {
                if (a == b) continue;
                int xb = points[b][0];
                int yb = points[b][1];
                if (xa > xb || ya < yb) continue;
                if (xa == xb && ya == yb) continue;
                int xiB = xIndex.get(xb);
                int yiB = yIndex.get(yb);
                int cnt = ps[xiB][yiA] - ps[xiA - 1][yiA] - ps[xiB][yiB - 1] + ps[xiA - 1][yiB - 1];
                if (cnt == 2) ans++;
            }
        }
        return ans;
    }
}

