class Solution {
    public static int minimumTime(String word, int k) {
        int n = word.length();
        int[] pi = new int[n];
        for (int i = 1; i < n; i++) {
            int j = pi[i - 1];
            while (j > 0 && word.charAt(i) != word.charAt(j)) {
                j = pi[j - 1];
            }
            if (word.charAt(i) == word.charAt(j)) {
                j++;
            }
            pi[i] = j;
        }
        int ans = (n + k - 1) / k;
        int len = n > 0 ? pi[n - 1] : 0;
        while (len > 0) {
            int diff = n - len;
            if (diff % k == 0) {
                int t = diff / k;
                if (t < ans) ans = t;
            }
            len = pi[len - 1];
        }
        return ans;
    }
}

