class Solution {
    public static int numberOfSubarrays(int[] nums, int[] pattern) {
        int n = nums.length;
        int m = pattern.length;
        if (m == 0) return n;
        if (m > n - 1) return 0;
        int[] lps = new int[m];
        int len = 0;
        for (int i = 1; i < m; ) {
            if (pattern[i] == pattern[len]) {
                lps[i++] = ++len;
            } else if (len != 0) {
                len = lps[len - 1];
            } else {
                lps[i++] = 0;
            }
        }
        int count = 0;
        int j = 0;
        for (int i = 0; i < n - 1; i++) {
            int delta = nums[i + 1] - nums[i];
            int sign = delta > 0 ? 1 : delta < 0 ? -1 : 0;
            while (j > 0 && sign != pattern[j]) {
                j = lps[j - 1];
            }
            if (sign == pattern[j]) {
                j++;
                if (j == m) {
                    count++;
                    j = lps[j - 1];
                }
            }
        }
        return count;
    }
}

