public class Solution {
    public static int maxPalindromes(String[] words) {
        int[] freq = new int[26];
        int n = words.length;
        int[] needPairs = new int[n];
        for (int i = 0; i < n; i++) {
            String w = words[i];
            needPairs[i] = w.length() / 2;
            for (int j = 0; j < w.length(); j++) {
                freq[w.charAt(j) - 'a']++;
            }
        }
        int totalPairs = 0;
        for (int f : freq) {
            totalPairs += f >> 1;
        }
        Arrays.sort(needPairs);
        int count = 0;
        for (int need : needPairs) {
            if (need <= totalPairs) {
                totalPairs -= need;
                count++;
            } else {
                break;
            }
        }
        return count;
    }
}

