        for (int i = 0; i < rows; i++) {
            answer[i] = matrix[i].clone();
        }
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (answer[i][j] == -1) answer[i][j] = colMax[j];
            }
        }
        return answer;
    }
}

