class Solution {
    public static String getStringBeforeLastOperation(String s) {
        if (s == null) return null;
        int n = s.length();
        char[] stack = new char[n];
        int top = -1;
        for (int i = 0; i < n; i++) {
            char ch = s.charAt(i);
            if (top >= 0 && stack[top] == ch) {
                top--;
            } else {
                stack[++top] = ch;
            }
        }
        return new String(stack, 0, top + 1);
    }
}

