class Solution {
    public static int maxConsecutiveElements(int[] nums) {
        if (nums == null || nums.length == 0) return 0;
        Arrays.sort(nums);
        HashSet<Integer> used = new HashSet<>(nums.length * 2);
        for (int x : nums) {
            if (!used.contains(x)) {
                used.add(x);
            } else if (!used.contains(x + 1)) {
                used.add(x + 1);
            }
        }
        int best = 0;
        for (int v : used) {
            if (!used.contains(v - 1)) {
                int cur = v;
                while (used.contains(cur)) {
                    cur++;
                }
                int length = cur - v;
                if (length > best) best = length;
            }
        }
        return best;
    }
}

