class Solution {
    public static int maxOperations(int[] nums) {
        int maxVal = 0;
        for (int num : nums) {
            if (num > maxVal) maxVal = num;
        }
        int[] freq = new int[maxVal + 1];
        for (int num : nums) {
            freq[num]++;
        }
        int best = 0;
        int maxSum = maxVal * 2;
        for (int sum = 2; sum <= maxSum; sum++) {
            int ops = 0;
            int limit = Math.min(maxVal, sum / 2);
            for (int x = 1; x <= limit; x++) {
                int y = sum - x;
                if (y > maxVal) continue;
                if (x == y) {
                    ops += freq[x] / 2;
                } else {
                    ops += Math.min(freq[x], freq[y]);
                }
            }
            if (ops > best) best = ops;
        }
        return best;
    }
}

