class Solution {
    public static int countPrefixSuffixPairs(String[] words) {
        Map<String, Integer> freq = new HashMap<>();
        int result = 0;
        for (String w : words) {
            int emptyCount = freq.getOrDefault("", 0);
            if (w.length() > 0) {
                result += emptyCount;
            }
            Integer sameCount = freq.get(w);
            if (sameCount != null) {
                result += sameCount;
            }
            int[] pi = computePrefixFunction(w);
            int border = w.length() == 0 ? 0 : pi[w.length() - 1];
            while (border > 0) {
                String prefix = w.substring(0, border);
                Integer cnt = freq.get(prefix);
                if (cnt != null) {
                    result += cnt;
                }
                border = pi[border - 1];
            }
            freq.put(w, freq.getOrDefault(w, 0) + 1);
        }
        return result;
    }

    private static int[] computePrefixFunction(String s) {
        int n = s.length();
        int[] pi = new int[n];
        for (int i = 1; i < n; i++) {
            int j = pi[i - 1];
            while (j > 0 && s.charAt(i) != s.charAt(j)) {
                j = pi[j - 1];
            }
            if (s.charAt(i) == s.charAt(j)) {
                j++;
            }
            pi[i] = j;
        }
        return pi;
    }
}

