class Solution {
    public static long countPrefixAndSuffixPairs(String[] words) {
        int totalLen = 0;
        for (String w : words) totalLen += w.length();
        int maxNodes = totalLen + 1;
        int[][] child = new int[maxNodes][26];
        for (int i = 0; i < maxNodes; i++) Arrays.fill(child[i], -1);
        int[] end = new int[maxNodes];
        int nodeCount = 1;
        long ans = 0;
        for (String w : words) {
            int n = w.length();
            int[] pi = new int[n];
            for (int i = 1; i < n; i++) {
                int j = pi[i - 1];
                while (j > 0 && w.charAt(i) != w.charAt(j)) j = pi[j - 1];
                if (w.charAt(i) == w.charAt(j)) j++;
                pi[i] = j;
            }
            boolean[] isBorder = new boolean[n + 1];
            int len = n;
            while (len > 0) {
                isBorder[len] = true;
                len = pi[len - 1];
            }
            int node = 0;
            for (int i = 0; i < n; i++) {
                int idx = w.charAt(i) - 'a';
                node = child[node][idx];
                if (node == -1) break;
                if (isBorder[i + 1]) ans += end[node];
            }
            node = 0;
            for (int i = 0; i < n; i++) {
                int idx = w.charAt(i) - 'a';
                if (child[node][idx] == -1) child[node][idx] = nodeCount++;
                node = child[node][idx];
            }
            end[node]++;
        }
        return ans;
    }
}

