import java.util.PriorityQueue;

class Solution {
    public static int minOperations(int[] nums, int k) {
        PriorityQueue<Long> pq = new PriorityQueue<>();
        for (int num : nums) {
            pq.offer((long) num);
        }
        int ops = 0;
        while (pq.size() >= 2) {
            long first = pq.poll();
            long second = pq.peek();
            if (first + second >= k) {
                pq.offer(first);
                break;
            }
            second = pq.poll();
            pq.offer(first + second);
            ops++;
        }
        return ops;
    }
}

