public class Connectable {
    static int signalSpeed;
    static List<List<int[]>> adj;

    static int dfs(int u, int parent, long dist) {
        int cnt = (dist % signalSpeed == 0) ? 1 : 0;
        for (int[] edge : adj.get(u)) {
            int v = edge[0], w = edge[1];
            if (v == parent) continue;
            cnt += dfs(v, u, dist + w);
        }
        return cnt;
    }

    static int[] countPairsOfConnectableServers(int[][] edges, int ss) {
        int n = edges.length + 1;
        signalSpeed = ss;
        adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(new int[]{e[1], e[2]});
            adj.get(e[1]).add(new int[]{e[0], e[2]});
        }
        int[] count = new int[n];
        for (int root = 0; root < n; root++) {
            long total = 0, pairs = 0;
            for (int[] edge : adj.get(root)) {
                int child = edge[0], w = edge[1];
                long branchCount = dfs(child, root, w);
                pairs += total * branchCount;
                total += branchCount;
            }
            count[root] = (int) pairs;
        }
        return count;
    }
}

public class Solution {
    public static long maxNodeValueSum(long[] nums, long k, int[][] edges) {
        int n = nums.length;
        long baseSum = 0;
        for (long v : nums) baseSum += v;
        long posSum = 0;
        long posCnt = 0;
        long minPos = Long.MAX_VALUE;
        long maxNeg = Long.MIN_VALUE;
        boolean hasPos = false, hasNeg = false;
        for (int i = 0; i < n; i++) {
            long diff = (nums[i] ^ k) - nums[i];
            if (diff > 0) {
                posSum += diff;
                posCnt++;
                if (diff < minPos) minPos = diff;
                hasPos = true;
            } else {
                if (diff > maxNeg) maxNeg = diff;
                hasNeg = true;
            }
        }
        long ans;
        if ((posCnt & 1) == 0) {
            ans = baseSum + posSum;
        } else {
            long cand1 = hasPos ? baseSum + posSum - minPos : Long.MIN_VALUE;
            long cand2 = hasNeg ? baseSum + posSum + maxNeg : Long.MIN_VALUE;
            ans = Math.max(cand1, cand2);
        }
        return ans;
    }
}

