class Solution {
    public static int minimumOperations(int[][] grid) {
        int n = grid.length;
        int mid = n / 2;
        int[] yCount = new int[3];
        int[] oCount = new int[3];
        int total = n * n;
        for (int r = 0; r < n; r++) {
            int[] row = grid[r];
            for (int c = 0; c < n; c++) {
                boolean isY = false;
                if (c == mid && r >= mid) {
                    isY = true;
                } else if (r == c && r <= mid) {
                    isY = true;
                } else if (r + c == n - 1 && r <= mid) {
                    isY = true;
                }
                int val = row[c];
                if (isY) {
                    yCount[val]++;
                } else {
                    oCount[val]++;
                }
            }
        }
        int best = Integer.MAX_VALUE;
        for (int a = 0; a < 3; a++) {
            for (int b = 0; b < 3; b++) {
                if (a == b) continue;
                int correct = yCount[a] + oCount[b];
                int ops = total - correct;
                if (ops < best) best = ops;
            }
        }
        return best;
    }
}

