class Solution {
    public int[] resultArray(int[] nums) {
        int n = nums.length;
        // Coordinate compression
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        int m = 0;
        for (int i = 0; i < sorted.length; i++) {
            if (i == 0 || sorted[i] != sorted[i - 1]) {
                sorted[m++] = sorted[i];
            }
        }
        int[] uniq = Arrays.copyOf(sorted, m);
        Map<Integer, Integer> idxMap = new HashMap<>(m * 2);
        for (int i = 0; i < m; i++) {
            idxMap.put(uniq[i], i + 1); // 1‑based index for BIT
        }

        BIT bit1 = new BIT(m);
        BIT bit2 = new BIT(m);
        int total1 = 0, total2 = 0;

        List<Integer> arr1 = new ArrayList<>();
        List<Integer> arr2 = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            int val = nums[i];
            int idx = idxMap.get(val);
            if (i == 0) {
                arr1.add(val);
                bit1.update(idx, 1);
                total1++;
            } else if (i == 1) {
                arr2.add(val);
                bit2.update(idx, 1);
                total2++;
            } else {
                int cnt1 = total1 - bit1.query(idx);
                int cnt2 = total2 - bit2.query(idx);
                if (cnt1 > cnt2) {
                    arr1.add(val);
                    bit1.update(idx, 1);
                    total1++;
                } else if (cnt2 > cnt1) {
                    arr2.add(val);
                    bit2.update(idx, 1);
                    total2++;
                } else {
                    if (arr1.size() < arr2.size()) {
                        arr1.add(val);
                        bit1.update(idx, 1);
                        total1++;
                    } else if (arr2.size() < arr1.size()) {
                        arr2.add(val);
                        bit2.update(idx, 1);
                        total2++;
                    } else {
                        arr1.add(val);
                        bit1.update(idx, 1);
                        total1++;
                    }
                }
            }
        }

        int[] result = new int[n];
        int pos = 0;
        for (int v : arr1) result[pos++] = v;
        for (int v : arr2) result[pos++] = v;
        return result;
    }

    private static class BIT {
        private final int size;
        private final int[] tree;

        BIT(int n) {
            size = n;
            tree = new int[n + 2];
        }

        void update(int idx, int delta) {
            while (idx <= size) {
                tree[idx] += delta;
                idx += idx & -idx;
            }
        }

        int query(int idx) {
            int sum = 0;
            while (idx > 0) {
                sum += tree[idx];
                idx -= idx & -idx;
            }
            return sum;
        }
    }
}

