class Solution {
    public static String replaceQuestionMarks(String s) {
        int n = s.length();
        int[] counts = new int[26];
        for (int i = 0; i < n; i++) {
            char ch = s.charAt(i);
            if (ch != '?') {
                counts[ch - 'a']++;
            }
        }
        char[] result = new char[n];
        for (int i = 0; i < n; i++) {
            char ch = s.charAt(i);
            if (ch != '?') {
                result[i] = ch;
            } else {
                int bestIdx = 0;
                int bestCnt = counts[0];
                for (int j = 1; j < 26; j++) {
                    int cnt = counts[j];
                    if (cnt < bestCnt || (cnt == bestCnt && j < bestIdx)) {
                        bestCnt = cnt;
                        bestIdx = j;
                    }
                }
                char chosen = (char) ('a' + bestIdx);
                result[i] = chosen;
                counts[bestIdx]++;
            }
        }
        return new String(result);
    }
}

