class Solution {
    public static int minDeletions(String word, int k) {
        int[] cnt = new int[26];
        for (int i = 0; i < word.length(); i++) {
            cnt[word.charAt(i) - 'a']++;
        }
        int max = 0;
        for (int f : cnt) {
            if (f > max) max = f;
        }
        int ans = word.length();
        for (int target = 0; target <= max; target++) {
            int deletions = 0;
            int lower = target - k;
            for (int f : cnt) {
                if (f > target) {
                    deletions += f - target;
                } else if (f < lower) {
                    deletions += f;
                }
            }
            if (deletions < ans) ans = deletions;
        }
        return ans;
    }
}

