public class Solution {
    private static final int MOD = 1_000_000_007;

    public static int sumPower(int[] nums, int k) {
        long[] dp = new long[k + 1];
        dp[0] = 1;
        for (int num : nums) {
            for (int s = k; s >= 0; s--) {
                long val = (dp[s] * 2) % MOD;
                if (s >= num) {
                    val = (val + dp[s - num]) % MOD;
                }
                dp[s] = val;
            }
        }
        return (int) dp[k];
    }
}

