class Solution {
    public static long[] markElements(int[] nums, int[][] queries) {
        int n = nums.length;
        boolean[] marked = new boolean[n];
        long total = 0;
        for (int v : nums) total += v;

        PriorityQueue<long[]> heap = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
        for (int i = 0; i < n; ++i) heap.offer(new long[]{nums[i], i});

        List<Long> answerList = new ArrayList<>();

        for (int[] q : queries) {
            int idx = q[0];
            int k = q[1];

            if (!marked[idx]) {
                marked[idx] = true;
                total -= nums[idx];
            }

            int taken = 0;
            while (taken < k && !heap.isEmpty()) {
                long[] top = heap.poll();
                int i = (int) top[1];
                long val = top[0];
                if (marked[i]) continue;
                marked[i] = true;
                total -= val;
                ++taken;
            }

            answerList.add(total);
        }

        long[] answer = new long[answerList.size()];
        for (int i = 0; i < answer.length; ++i) answer[i] = answerList.get(i);
        return answer;
    }
}

public class Solution {
    public static long minimumMoves(int[] nums, long k, long maxChanges) {
        long n = nums.length;
        long[] cnt = new long[(int) n + 1];
        long[] s = new long[(int) n + 1];
        for (int i = 1; i <= n; i++) {
            long x = nums[i - 1];
            cnt[i] = cnt[i - 1] + x;
            s[i] = s[i - 1] + (long) i * x;
        }
        long ans = Long.MAX_VALUE;
        for (int i = 1; i <= n; i++) {
            long x = nums[i - 1];
            long t = 0;
            long need = k - x;
            for (int j : new int[]{i - 1, i + 1}) {
                if (need > 0 && j >= 1 && j <= n && nums[j - 1] == 1) { need -= 1; t += 1; }
            }
            long c = Math.min(need, maxChanges);
            need -= c;
            t += c * 2;
            if (need <= 0) { ans = Math.min(ans, t); continue; }
            long l = 2, r = Math.max(i - 1, n - i);
            while (l <= r) {
                long mid = (l + r) >> 1;
                long l1 = Math.max(1, i - mid), r1 = Math.max(0, i - 2);
                long l2 = Math.min(n + 1, i + 2), r2 = Math.min(n, i + mid);
                long c1 = cnt[(int) r1] - cnt[(int) l1 - 1];
                long c2 = cnt[(int) r2] - cnt[(int) l2 - 1];
                if (c1 + c2 >= need) {
                    long t1 = c1 * i - (s[(int) r1] - s[(int) l1 - 1]);
                    long t2 = s[(int) r2] - s[(int) l2 - 1] - c2 * i;
                    ans = Math.min(ans, t + t1 + t2);
                    r = mid - 1;
                } else {
                    l = mid + 1;
                }
            }
        }
        return ans;
    }
}

