class Solution {
    public static int minOperationsToReachK(int k) {
        if (k <= 1) return 0;
        int best = k - 1;
        int limit = (int) Math.sqrt(k) + 1;
        for (int v = 1; v <= limit && v <= k; ++v) {
            int copies = (k - 1) / v;
            int ops = (v - 1) + copies;
            if (ops < best) best = ops;
        }
        for (int copies = 1; copies <= limit; ++copies) {
            int v = (k - 1) / copies;
            if (v < 1) v = 1;
            int ops = (v - 1) + copies;
            if (ops < best) best = ops;
        }
        return best;
    }
}

