class Solution {
    private static class Node {
        Map<Character, Node> children = new HashMap<>();
        int bestIdx = -1;
    }

    public static int[] longestCommonSuffixQueries(String[] wordsContainer, String[] wordsQuery) {
        Node root = new Node();
        int[] lengths = new int[wordsContainer.length];
        for (int i = 0; i < wordsContainer.length; i++) {
            lengths[i] = wordsContainer[i].length();
        }

        java.util.function.BiConsumer<Node, Integer> update = (node, idx) -> {
            int cur = node.bestIdx;
            if (cur == -1 ||
                lengths[idx] < lengths[cur] ||
                (lengths[idx] == lengths[cur] && idx < cur)) {
                node.bestIdx = idx;
            }
        };

        for (int i = 0; i < wordsContainer.length; i++) {
            String s = wordsContainer[i];
            Node node = root;
            update.accept(node, i);
            for (int p = s.length() - 1; p >= 0; p--) {
                char ch = s.charAt(p);
                node = node.children.computeIfAbsent(ch, k -> new Node());
                update.accept(node, i);
            }
        }

        int[] answer = new int[wordsQuery.length];
        for (int qi = 0; qi < wordsQuery.length; qi++) {
            String q = wordsQuery[qi];
            Node node = root;
            int best = node.bestIdx;
            for (int p = q.length() - 1; p >= 0; p--) {
                char ch = q.charAt(p);
                if (!node.children.containsKey(ch)) {
                    break;
                }
                node = node.children.get(ch);
                best = node.bestIdx;
            }
            answer[qi] = best;
        }
        return answer;
    }
}

