class Solution {
    public static int[] mostFrequentIDs(int[] nums, int[] freq) {
        int n = nums.length;
        int[] ans = new int[n];
        Map<Integer, Integer> idCount = new HashMap<>();
        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> Integer.compare(b[0], a[0]));
        for (int i = 0; i < n; ++i) {
            int id = nums[i];
            int delta = freq[i];
            int prev = idCount.getOrDefault(id, 0);
            int now = prev + delta;
            if (now > 0) {
                idCount.put(id, now);
                heap.offer(new int[]{now, id});
            } else {
                idCount.remove(id);
            }
            while (!heap.isEmpty()) {
                int[] top = heap.peek();
                Integer cur = idCount.get(top[1]);
                if (cur != null && cur == top[0]) {
                    break;
                }
                heap.poll();
            }
            ans[i] = heap.isEmpty() ? 0 : heap.peek()[0];
        }
        return ans;
    }
}

public class Solution {
    public static int minLevels(int[] possible) {
        int n = possible.length;
        int total = 0;
        for (int i = 0; i < n; i++) {
            total += possible[i] == 1 ? 1 : -1;
        }
        int pref = 0;
        for (int i = 0; i < n - 1; i++) {
            pref += possible[i] == 1 ? 1 : -1;
            if (pref > total - pref) {
                return i + 1;
            }
        }
        return -1;
    }
}

