            int x = nums[right];
            for (int b = 0; b < B; b++) {
                if (((x >> b) & 1) != 0) {
                    cnt[b]++;
                    curOr |= (1 << b);
                }
            }
            while (curOr >= k && left <= right) {
                int len = right - left + 1;
                if (len < best) best = len;
                int y = nums[left];
                for (int b = 0; b < B; b++) {
                    if (((y >> b) & 1) != 0) {
                        cnt[b]--;
                        if (cnt[b] == 0) {
                            curOr &= ~(1 << b);
                        }
                    }
                }
                left++;
            }
        }
        return best == Integer.MAX_VALUE ? -1 : best;
    }
}

