class Solution {
    public static int shortestSubarrayOrAtLeastK(int[] nums, int k) {
        int n = nums.length;
        final int BIT = 31;
        int[] cnt = new int[BIT];
        int curOr = 0;
        int left = 0;
        int best = Integer.MAX_VALUE;

        for (int right = 0; right < n; right++) {
            int x = nums[right];
            for (int b = 0; b < BIT; b++) {
                if ((x & (1 << b)) != 0) {
                    cnt[b]++;
                    curOr |= (1 << b);
                }
            }

            while (curOr >= k && left <= right) {
                best = Math.min(best, right - left + 1);
                int y = nums[left];
                for (int b = 0; b < BIT; b++) {
                    if ((y & (1 << b)) != 0) {
                        cnt[b]--;
                        if (cnt[b] == 0) {
                            curOr &= ~(1 << b);
                        }
                    }
                }
                left++;
            }
        }
        return best == Integer.MAX_VALUE ? -1 : best;
    }
}

