public class Solution {
    private static final long MOD = 1_000_000_007L;

    public static long sumOfPowers(int[] nums, int k) {
        int n = nums.length;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nums[i];
        Arrays.sort(a);

        TreeSet<Long> gapSet = new TreeSet<>();
        gapSet.add(0L); // ensure zero gap is considered
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                gapSet.add(a[j] - a[i]);
            }
        }
        long[] gaps = new long[gapSet.size()];
        int idx = 0;
        for (Long g : gapSet) {
            gaps[idx++] = g;
        }

        long[] cntGe = new long[gaps.length];
        for (int gIdx = 0; gIdx < gaps.length; gIdx++) {
            cntGe[gIdx] = countAtLeast(gaps[gIdx], a, k);
        }

        long ans = 0;
        for (int i = 0; i < gaps.length; i++) {
            long next = (i + 1 < gaps.length) ? cntGe[i + 1] : 0L;
            long exact = (cntGe[i] - next) % MOD;
            if (exact < 0) exact += MOD;
            long contrib = (gaps[i] % MOD) * exact % MOD;
            ans = (ans + contrib) % MOD;
        }
        return ans;
    }

    private static long countAtLeast(long d, long[] a, int k) {
        int n = a.length;
        long[][] dp = new long[n][k + 1];
        for (int i = 0; i < n; i++) dp[i][1] = 1L;
        for (int len = 2; len <= k; len++) {
            for (int i = 0; i < n; i++) {
                long sum = 0L;
                for (int j = 0; j < i; j++) {
                    if (a[i] - a[j] >= d) {
                        sum += dp[j][len - 1];
                        if (sum >= MOD) sum -= MOD;
                    }
                }
                dp[i][len] = sum;
            }
        }
        long total = 0L;
        for (int i = 0; i < n; i++) {
            total += dp[i][k];
            if (total >= MOD) total -= MOD;
        }
        return total;
    }
}

