class Solution {
    public static int minMaxManhattanDistance(int[][] points) {
        int n = points.length;
        long[] u = new long[n];
        long[] v = new long[n];
        long maxU = Long.MIN_VALUE, secondMaxU = Long.MIN_VALUE;
        long minU = Long.MAX_VALUE, secondMinU = Long.MAX_VALUE;
        int cntMaxU = 0, cntMinU = 0;
        long maxV = Long.MIN_VALUE, secondMaxV = Long.MIN_VALUE;
        long minV = Long.MAX_VALUE, secondMinV = Long.MAX_VALUE;
        int cntMaxV = 0, cntMinV = 0;
        for (int i = 0; i < n; i++) {
            long x = points[i][0];
            long y = points[i][1];
            long valU = x + y;
            long valV = x - y;
            u[i] = valU;
            v[i] = valV;
            if (valU > maxU) {
                secondMaxU = maxU;
                maxU = valU;
                cntMaxU = 1;
            } else if (valU == maxU) {
                cntMaxU++;
            } else if (valU > secondMaxU) {
                secondMaxU = valU;
            }
            if (valU < minU) {
                secondMinU = minU;
                minU = valU;
                cntMinU = 1;
            } else if (valU == minU) {
                cntMinU++;
            } else if (valU < secondMinU) {
                secondMinU = valU;
            }
            if (valV > maxV) {
                secondMaxV = maxV;
                maxV = valV;
                cntMaxV = 1;
            } else if (valV == maxV) {
                cntMaxV++;
            } else if (valV > secondMaxV) {
                secondMaxV = valV;
            }
            if (valV < minV) {
                secondMinV = minV;
                minV = valV;
                cntMinV = 1;
            } else if (valV == minV) {
                cntMinV++;
            } else if (valV < secondMinV) {
                secondMinV = valV;
            }
        }
        if (secondMaxU == Long.MIN_VALUE) secondMaxU = maxU;
        if (secondMinU == Long.MAX_VALUE) secondMinU = minU;
        if (secondMaxV == Long.MIN_VALUE) secondMaxV = maxV;
        if (secondMinV == Long.MAX_VALUE) secondMinV = minV;
        long answer = Long.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            long curMaxU = (u[i] == maxU && cntMaxU == 1) ? secondMaxU : maxU;
            long curMinU = (u[i] == minU && cntMinU == 1) ? secondMinU : minU;
            long curMaxV = (v[i] == maxV && cntMaxV == 1) ? secondMaxV : maxV;
            long curMinV = (v[i] == minV && cntMinV == 1) ? secondMinV : minV;
            long candidate = Math.max(curMaxU - curMinU, curMaxV - curMinV);
            if (candidate < answer) {
                answer = candidate;
            }
        }
        return (int) answer;
    }
}

