class Solution {
    public static String smallestString(String s, int k) {
        int n = s.length();
        int aCode = (int) 'a';
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < n; i++) {
            int cur = s.charAt(i) - aCode;
            for (int c = 0; c < 26; c++) {
                int diff = Math.abs(cur - c);
                int cost = Math.min(diff, 26 - diff);
                int maxRemain = 13 * (n - i - 1);
                if (k - cost <= maxRemain && k - cost >= 0) {
                    result.append((char) (aCode + c));
                    k -= cost;
                    break;
                }
            }
        }
        return result.toString();
    }
}

