class Solution {
    public static long countSubarrays(int[] nums) {
        int n = nums.length;
        int[] nextGreater = new int[n];
        Arrays.fill(nextGreater, n);
        int[] stack = new int[n];
        int top = -1;
        for (int i = 0; i < n; i++) {
            while (top >= 0 && nums[i] > nums[stack[top]]) {
                nextGreater[stack[top--]] = i;
            }
            stack[++top] = i;
        }
        Map<Integer, Integer> lastPos = new HashMap<>();
        Map<Integer, Integer> runLen = new HashMap<>();
        long ans = 0;
        for (int i = 0; i < n; i++) {
            int v = nums[i];
            Integer prev = lastPos.get(v);
            if (prev != null && nextGreater[prev] > i) {
                int len = runLen.get(v) + 1;
                runLen.put(v, len);
                ans += len;
            } else {
                runLen.put(v, 1);
                ans += 1;
            }
            lastPos.put(v, i);
        }
        return ans;
    }
}

import java.util.*;

public class Solution {
    public static int[] minimumCostWalk(int n, int[][] edges, int[][] query) {
        DSU dsu = new DSU(n);
        for (int[] e : edges) {
            dsu.unite(e[0], e[1], e[2]);
        }
        int[] ans = new int[query.length];
        for (int i = 0; i < query.length; i++) {
            int s = query[i][0];
            int t = query[i][1];
            int rs = dsu.find(s);
            int rt = dsu.find(t);
            ans[i] = (rs != rt) ? -1 : dsu.compAnd[rs];
        }
        return ans;
    }

    private static class DSU {
        int[] parent;
        int[] size;
        int[] compAnd;

        DSU(int n) {
            parent = new int[n];
            size = new int[n];
            compAnd = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
                compAnd[i] = ~0;
            }
        }

        int find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }

        void unite(int a, int b, int w) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) {
                compAnd[ra] &= w;
                return;
            }
            int newAnd = compAnd[ra] & compAnd[rb] & w;
            if (size[ra] < size[rb]) {
                int tmp = ra;
                ra = rb;
                rb = tmp;
            }
            parent[rb] = ra;
            size[ra] += size[rb];
            compAnd[ra] = newAnd;
        }
    }
}

