class Solution {
    public static long[] minimumTime(int n, int[][] edges, long[] disappear) {
        int m = edges.length;
        int[] head = new int[n];
        Arrays.fill(head, -1);
        int[] to = new int[2 * m];
        int[] w = new int[2 * m];
        int[] next = new int[2 * m];
        int idx = 0;
        for (int[] e : edges) {
            int u = e[0], v = e[1], weight = e[2];
            to[idx] = v;
            w[idx] = weight;
            next[idx] = head[u];
            head[u] = idx++;
            to[idx] = u;
            w[idx] = weight;
            next[idx] = head[v];
            head[v] = idx++;
        }
        long INF = Long.MAX_VALUE / 4;
        long[] dist = new long[n];
        Arrays.fill(dist, INF);
        if (0 >= disappear[0]) {
            long[] res = new long[n];
            Arrays.fill(res, -1);
            return res;
        }
        dist[0] = 0;
        PriorityQueue<long[]> heap = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
        heap.offer(new long[]{0L, 0L});
        while (!heap.isEmpty()) {
            long[] cur = heap.poll();
            long time = cur[0];
            int node = (int) cur[1];
            if (time != dist[node]) continue;
            if (time >= disappear[node]) continue;
            for (int e = head[node]; e != -1; e = next[e]) {
                int nbr = to[e];
                long newTime = time + w[e];
                if (newTime < disappear[nbr] && newTime < dist[nbr]) {
                    dist[nbr] = newTime;
                    heap.offer(new long[]{newTime, nbr});
                }
            }
        }
        long[] result = new long[n];
        for (int i = 0; i < n; i++) {
            result[i] = (dist[i] == INF) ? -1 : dist[i];
        }
        return result;
    }
}

