public class Solution {
    private static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    private static long lcm(long a, long b) {
        long g = gcd(a, b);
        long div = a / g;
        if (div > Long.MAX_VALUE / b) return 0;
        return div * b;
    }

    private static long countLe(long X, long[] lcms, int[] signs) {
        long total = 0;
        for (int i = 1; i < lcms.length; i++) {
            long l = lcms[i];
            if (l == 0 || l > X) continue;
            total += signs[i] * (X / l);
        }
        return total;
    }

    public static long kthSmallestAmount(int[] coins, long k) {
        Arrays.sort(coins);
        List<Long> filtered = new ArrayList<>();
        for (int c : coins) {
            boolean keep = true;
            for (long f : filtered) {
                if (c % f == 0) {
                    keep = false;
                    break;
                }
            }
            if (keep) filtered.add((long) c);
        }
        int n = filtered.size();
        long[] coinVals = new long[n];
        for (int i = 0; i < n; i++) coinVals[i] = filtered.get(i);
        int maxMask = 1 << n;
        long[] lcms = new long[maxMask];
        int[] signs = new int[maxMask];
        lcms[0] = 1;
        for (int mask = 1; mask < maxMask; mask++) {
            int lsb = Integer.numberOfTrailingZeros(mask);
            int prev = mask ^ (1 << lsb);
            long prevLcm = lcms[prev];
            long curLcm = prevLcm == 0 ? 0 : lcm(prevLcm, coinVals[lsb]);
            lcms[mask] = curLcm;
            signs[mask] = (Integer.bitCount(mask) & 1) == 1 ? 1 : -1;
        }
        long minCoin = coinVals[0];
        long low = 1;
        long high = (minCoin > Long.MAX_VALUE / k) ? Long.MAX_VALUE : minCoin * k;
        while (low < high) {
            long mid = low + (high - low) / 2;
            if (countLe(mid, lcms, signs) >= k) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}

