public class Solution {
    public static int maxPrimeDifference(List<Integer> nums) {
        int first = -1;
        int last = -1;
        for (int i = 0; i < nums.size(); i++) {
            int val = nums.get(i);
            if (isPrime(val)) {
                if (first == -1) first = i;
                last = i;
            }
        }
        if (first == -1) return 0;
        return last - first;
    }

    private static boolean isPrime(int x) {
        if (x < 2) return false;
        if (x == 2) return true;
        if ((x & 1) == 0) return false;
        int limit = (int) Math.sqrt(x);
        for (int d = 3; d <= limit; d += 2) {
            if (x % d == 0) return false;
        }
        return true;
    }
}

