class Solution {
    public static long minimumValueSum(int[] nums, int[] andValues) {
        int n = nums.length;
        int m = andValues.length;
        final long INF = (long) 1e15;
        long[] dpPrev = new long[n];
        Arrays.fill(dpPrev, INF);
        for (int k = 1; k <= m; k++) {
            long target = andValues[k - 1];
            long[] dpCurr = new long[n];
            Arrays.fill(dpCurr, INF);
            Map<Long, Long> curMap = new HashMap<>();
            for (int i = 0; i < n; i++) {
                Map<Long, Long> nextMap = new HashMap<>();
                long startPrev = (i == 0) ? 0L : dpPrev[i - 1];
                if (startPrev < INF) {
                    long val = nums[i];
                    Long existing = nextMap.get(val);
                    if (existing == null || startPrev < existing) nextMap.put(val, startPrev);
                }
                for (Map.Entry<Long, Long> e : curMap.entrySet()) {
                    long newAnd = e.getKey() & nums[i];
                    long prevCost = e.getValue();
                    Long existing = nextMap.get(newAnd);
                    if (existing == null || prevCost < existing) nextMap.put(newAnd, prevCost);
                }
                Long best = nextMap.get(target);
                if (best != null) dpCurr[i] = best + nums[i];
                curMap = nextMap;
            }
            dpPrev = dpCurr;
        }
        long ans = dpPrev[n - 1];
        return ans >= INF ? -1 : ans;
    }
}

