class Solution {
    public long minEnd(int n, int x) {
        long result = x;
        long nn = n - 1;
        long bitPos = 1;
        // fill in the 0-bits of x with the bits of (n-1), in increasing bit-position order,
        // to get the smallest possible last element of the AND-x sequence
        while (nn > 0) {
            if ((result & bitPos) == 0) {
                if ((nn & 1) == 1) {
                    result |= bitPos;
                }
                nn >>= 1;
            }
            bitPos <<= 1;
        }
        return result;
    }
}

