class Solution {
    public static long countStableBinaryArrays(int zero, int one, int limit) {
        final int MOD = 1_000_000_007;
        int[][] dp0 = new int[zero + 1][one + 1];
        int[][] dp1 = new int[zero + 1][one + 1];
        long[] win1 = new long[one + 1];
        for (int i = 0; i <= zero; ++i) {
            if (i > 0) {
                int removeIdx = i - 1 - limit;
                for (int j = 0; j <= one; ++j) {
                    win1[j] = (win1[j] + dp1[i - 1][j]) % MOD;
                    if (removeIdx >= 0) {
                        win1[j] = (win1[j] - dp1[removeIdx][j] + MOD) % MOD;
                    }
                }
            }
            for (int j = 0; j <= one; ++j) {
                long val = 0;
                if (i > 0) {
                    val = win1[j];
                }
                if (j == 0 && i > 0 && i <= limit) {
                    val = (val + 1) % MOD;
                }
                dp0[i][j] = (int) val;
            }
            long win0 = 0;
            for (int j = 0; j <= one; ++j) {
                if (j > 0) {
                    win0 = (win0 + dp0[i][j - 1]) % MOD;
                    int removeIdx = j - 1 - limit;
                    if (removeIdx >= 0) {
                        win0 = (win0 - dp0[i][removeIdx] + MOD) % MOD;
                    }
                }
                long val = 0;
                if (j > 0) {
                    val = win0;
                }
                if (i == 0 && j > 0 && j <= limit) {
                    val = (val + 1) % MOD;
                }
                dp1[i][j] = (int) val;
            }
        }
        return (dp0[zero][one] + dp1[zero][one]) % MOD;
    }
}

