class Solution {
    public static int minOperations(String word, int k) {
        int n = word.length();
        int blockCount = n / k;
        HashMap<String, Integer> freq = new HashMap<>();
        int maxFreq = 0;
        for (int i = 0; i < n; i += k) {
            String block = word.substring(i, i + k);
            int cnt = freq.getOrDefault(block, 0) + 1;
            freq.put(block, cnt);
            if (cnt > maxFreq) {
                maxFreq = cnt;
            }
        }
        return blockCount - maxFreq;
    }
}

class Solution {
    public static long minLengthAnagramConcat(String s) {
        if (s == null || s.isEmpty()) {
            return 0L;
        }
        int[] freq = new int[256];
        for (int i = 0; i < s.length(); i++) {
            freq[s.charAt(i)]++;
        }
        long g = 0;
        for (int v : freq) {
            if (v > 0) {
                g = (g == 0) ? v : gcd(g, v);
            }
        }
        return s.length() / g;
    }
    private static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

