class Solution {
    public static long findMinimumX(int[] nums1, int[] nums2) {
        int n = nums1.length;
        int[] a = nums1.clone();
        int[] b = nums2.clone();
        Arrays.sort(a);
        Arrays.sort(b);
        int m = b.length;
        long best = Long.MAX_VALUE;
        int limit = Math.min(2, n - 1);
        for (int start = 0; start <= limit; start++) {
            long x = (long) b[0] - (long) a[start];
            int i = 0, j = 0, removed = 0;
            while (i < n && j < m) {
                long val = (long) a[i] + x;
                if (val == b[j]) {
                    i++;
                    j++;
                } else {
                    removed++;
                    i++;
                    if (removed > 2) break;
                }
            }
            if (j == m) {
                removed += (n - i);
                if (removed <= 2 && x < best) {
                    best = x;
                }
            }
        }
        return best;
    }
}

