public class Solution {
    private static long[] countBitsAndPosSum(long N) {
        long totalBits = 0;
        long totalPos = 0;
        for (int i = 0; i < 63; ++i) {
            long bitVal = 1L << i;
            if (bitVal > N) break;
            long block = bitVal << 1;
            long full = (N + 1) / block;
            long cnt = full * bitVal;
            long rem = (N + 1) % block;
            if (rem > bitVal) cnt += rem - bitVal;
            totalBits += cnt;
            totalPos += cnt * i;
        }
        return new long[]{totalBits, totalPos};
    }

    private static long prefixExponent(long t) {
        if (t == 0) return 0;
        long low = 1;
        long high = t;
        while (low < high) {
            long mid = low + ((high - low) >> 1);
            long bits = countBitsAndPosSum(mid)[0];
            if (bits >= t) high = mid;
            else low = mid + 1;
        }
        long N = low;
        long[] prev = countBitsAndPosSum(N - 1);
        long prevCount = prev[0];
        long prevSumPos = prev[1];
        long remaining = t - prevCount;
        long add = 0;
        for (int i = 0; remaining > 0; ++i) {
            if (((N >> i) & 1L) == 1L) {
                add += i;
                --remaining;
            }
        }
        return prevSumPos + add;
    }

    private static long modPow(long base, long exp, long mod) {
        if (mod == 1) return 0;
        long result = 1 % mod;
        long b = base % mod;
        while (exp != 0) {
            if ((exp & 1L) != 0) result = (result * b) % mod;
            b = (b * b) % mod;
            exp >>>= 1;
        }
        return result;
    }

    public static List<Integer> productQueries(List<List<Long>> queries) {
        List<Integer> ans = new ArrayList<>(queries.size());
        for (List<Long> q : queries) {
            long from = q.get(0);
            long to = q.get(1);
            long mod = q.get(2);
            long exp = prefixExponent(to + 1) - prefixExponent(from);
            ans.add((int) modPow(2, exp, mod));
        }
        return ans;
    }
}

