class Solution {
    public static long maxEnergy(int[] energy, int k) {
        int n = energy.length;
        if (n == 0) return 0L;
        long[] buffer = new long[k];
        long best = Long.MIN_VALUE;
        for (int i = n - 1; i >= 0; i--) {
            long sum = energy[i];
            int next = i + k;
            if (next < n) {
                sum += buffer[next % k];
            }
            buffer[i % k] = sum;
            if (sum > best) best = sum;
        }
        return best;
    }
}

