class Solution {
    public static long sumDigitDifferences(List<Long> nums) {
        int n = nums.size();
        if (n < 2) return 0L;
        long max = 0L;
        for (Long v : nums) {
            if (v > max) max = v;
        }
        int digitCount = max == 0 ? 1 : (int) Math.log10(max) + 1;
        long totalSum = 0L;
        long divisor = 1L;
        for (int pos = 0; pos < digitCount; ++pos) {
            long[] freq = new long[10];
            for (int i = 0; i < n; ++i) {
                long num = nums.get(i);
                int digit = (int) ((num / divisor) % 10);
                ++freq[digit];
            }
            long totalPairs = (long) n * (n - 1) / 2;
            long sameDigitPairs = 0L;
            for (int d = 0; d < 10; ++d) {
                sameDigitPairs += freq[d] * (freq[d] - 1) / 2;
            }
            totalSum += totalPairs - sameDigitPairs;
            divisor *= 10L;
        }
        return totalSum;
    }
}

