class Solution {
    public static int minBalancedPartitions(String s) {
        int n = s.length();
        final int INF = Integer.MAX_VALUE / 2;
        int[] dp = new int[n + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int i = 1; i <= n; ++i) {
            int[] cnt = new int[26];
            int distinct = 0;
            int maxFreq = 0;
            int maxFreqCount = 0;
            for (int j = i - 1; j >= 0; --j) {
                int idx = s.charAt(j) - 'a';
                cnt[idx]++;
                if (cnt[idx] == 1) {
                    distinct++;
                }
                if (cnt[idx] > maxFreq) {
                    maxFreq = cnt[idx];
                    maxFreqCount = 1;
                } else if (cnt[idx] == maxFreq) {
                    maxFreqCount++;
                }
                int len = i - j;
                if (maxFreq * distinct == len && maxFreqCount == distinct) {
                    dp[i] = Math.min(dp[i], dp[j] + 1);
                }
            }
        }
        return dp[n];
    }
}

