public class Solution {
    public static int maxScore(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return -1;
        }
        int m = grid.length;
        int n = grid[0].length;
        int[][] minPref = new int[m][n];
        int ans = Integer.MIN_VALUE;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int cur = grid[i][j];
                if (i == 0 && j == 0) {
                    minPref[i][j] = cur;
                    continue;
                }
                int minPrev = Integer.MAX_VALUE;
                if (i > 0) {
                    minPrev = Math.min(minPrev, minPref[i - 1][j]);
                }
                if (j > 0) {
                    minPrev = Math.min(minPrev, minPref[i][j - 1]);
                }
                ans = Math.max(ans, cur - minPrev);
                minPref[i][j] = Math.min(cur, minPrev);
            }
        }
        return ans <= 0 ? -1 : ans;
    }
}

public class Solution {
    public static boolean isSpecialArray(int[] nums) {
        for (int i = 0; i + 1 < nums.length; i++) {
            if ((nums[i] & 1) == (nums[i + 1] & 1)) {
                return false;
