class Solution {
    public static String stringCompression(String word) {
        int n = word.length();
        StringBuilder comp = new StringBuilder(2 * n);
        int i = 0;
        while (i < n) {
            char ch = word.charAt(i);
            int count = 0;
            while (i < n && word.charAt(i) == ch) {
                count++;
                i++;
            }
            while (count > 0) {
                int chunk = count > 9 ? 9 : count;
                comp.append((char) ('0' + chunk));
