class Solution {
    public static List<Integer> findDistinctColors(int limit, List<int[]> queries) {
        int[] ballColor = new int[limit + 1];
        Arrays.fill(ballColor, -1);
        Map<Integer, Integer> colorCount = new HashMap<>();
        List<Integer> result = new ArrayList<>(queries.size());
        for (int[] q : queries) {
            int ball = q[0];
            int newColor = q[1];
            int oldColor = ballColor[ball];
            if (oldColor != -1) {
                int cnt = colorCount.get(oldColor);
                if (cnt == 1) {
                    colorCount.remove(oldColor);
                } else {
                    colorCount.put(oldColor, cnt - 1);
                }
            }
            ballColor[ball] = newColor;
            colorCount.put(newColor, colorCount.getOrDefault(newColor, 0) + 1);
            result.add(colorCount.size());
        }
        return result;
    }
}

