public class Solution {
    public static int count_days_without_meetings(int days, List<List<Integer>> meetings) {
        if (meetings == null || meetings.isEmpty()) {
            return days > 0 ? days : 0;
        }
        meetings.sort((a, b) -> Integer.compare(a.get(0), b.get(0)));
        long covered = 0;
        int curStart = meetings.get(0).get(0);
        int curEnd = meetings.get(0).get(1);
        for (int i = 1; i < meetings.size(); i++) {
            int s = meetings.get(i).get(0);
            int e = meetings.get(i).get(1);
            if (s <= curEnd) {
                if (e > curEnd) {
                    curEnd = e;
                }
            } else {
                covered += (long) curEnd - curStart + 1;
                curStart = s;
                curEnd = e;
            }
        }
        covered += (long) curEnd - curStart + 1;
        long free = (long) days - covered;
        return free > 0 ? (int) free : 0;
    }
}

import java.util.*;

class Solution {
    private static final long MOD = 1000000007L;
    private static final long NEG = -(1L << 60);

    private static class Matrix {
        long a00, a01, a10, a11;
        Matrix() {}
        Matrix(long a00, long a01, long a10, long a11) {
            this.a00 = a00;
            this.a01 = a01;
            this.a10 = a10;
            this.a11 = a11;
        }
    }

    private static Matrix multiply(Matrix left, Matrix right) {
        Matrix res = new Matrix();
        long v;
        // res = right * left (max-plus multiplication)
        // a00
        v = NEG;
        if (right.a00 != NEG && left.a00 != NEG) v = Math.max(v, right.a00 + left.a00);
        if (right.a01 != NEG && left.a10 != NEG) v = Math.max(v, right.a01 + left.a10);
        res.a00 = v;
        // a01
        v = NEG;
        if (right.a00 != NEG && left.a01 != NEG) v = Math.max(v, right.a00 + left.a01);
        if (right.a01 != NEG && left.a11 != NEG) v = Math.max(v, right.a01 + left.a11);
        res.a01 = v;
        // a10
        v = NEG;
        if (right.a10 != NEG && left.a00 != NEG) v = Math.max(v, right.a10 + left.a00);
        if (right.a11 != NEG && left.a10 != NEG) v = Math.max(v, right.a11 + left.a10);
        res.a10 = v;
        // a11
        v = NEG;
        if (right.a10 != NEG && left.a01 != NEG) v = Math.max(v, right.a10 + left.a01);
        if (right.a11 != NEG && left.a11 != NEG) v = Math.max(v, right.a11 + left.a11);
        res.a11 = v;
        return res;
    }

    private static class SegmentTree {
        int n;
        Matrix[] tree;

        SegmentTree(int[] arr) {
            n = arr.length;
            tree = new Matrix[4 * n];
            build(1, 0, n - 1, arr);
        }

        void update(int idx, int val) {
            update(1, 0, n - 1, idx, val);
        }

        Matrix queryAll() {
            return tree[1];
        }

        private void build(int node, int l, int r, int[] arr) {
            if (l == r) {
                long a = arr[l];
                tree[node] = new Matrix(0, 0, a, NEG);
                return;
            }
            int mid = (l + r) >>> 1;
            build(node << 1, l, mid, arr);
            build(node << 1 | 1, mid + 1, r, arr);
            tree[node] = multiply(tree[node << 1 | 1], tree[node << 1]);
        }

        private void update(int node, int l, int r, int idx, int val) {
            if (l == r) {
                long a = val;
                tree[node] = new Matrix(0, 0, a, NEG);
                return;
            }
            int mid = (l + r) >>> 1;
            if (idx <= mid) {
                update(node << 1, l, mid, idx, val);
            } else {
                update(node << 1 | 1, mid + 1, r, idx, val);
            }
            tree[node] = multiply(tree[node << 1 | 1], tree[node << 1]);
        }
    }

    public static int maximumSumQueries(int[] nums, int[][] queries) {
        SegmentTree seg = new SegmentTree(nums);
        long total = 0;
        for (int[] q : queries) {
            seg.update(q[0], q[1]);
            Matrix root = seg.queryAll();
            long ans = Math.max(root.a00, root.a10);
            total = (total + ans) % MOD;
        }
        return (int) total;
    }
}

