class Solution {
    public static long countGoodPairs(int[] nums1, int[] nums2, int k) {
        if (nums1.length == 0 || nums2.length == 0) return 0L;
        int maxV = 0;
        for (int v : nums1) {
            if (v > maxV) maxV = v;
        }
