        for (int v : nums1) {
            freq[v]++;
        }
        int[] cnt = new int[maxV + 1];
        for (int d = 1; d <= maxV; d++) {
            for (int mult = d; mult <= maxV; mult += d) {
                cnt[d] += freq[mult];
            }
        }
        long ans = 0L;
        for (int b : nums2) {
            long target = (long) b * k;
            if (target > 0 && target <= maxV) {
                ans += cnt[(int) target];
            }
        }
        return ans;
    }
}

