public class Solution {
    public static int maximumLength(int[] nums, int k) {
        @SuppressWarnings("unchecked")
        HashMap<Integer, Integer>[] dp = new HashMap[k + 1];
        for (int i = 0; i <= k; i++) {
            dp[i] = new HashMap<>();
        }
        int[] best = new int[k + 1];
        int[] prevBest = new int[k + 1];
        for (int x : nums) {
            System.arraycopy(best, 0, prevBest, 0, k + 1);
            for (int t = 0; t <= k; t++) {
                int extend = dp[t].getOrDefault(x, 0);
                int cand = extend + 1;
                if (t > 0) {
                    int cand2 = prevBest[t - 1] + 1;
                    if (cand2 > cand) {
                        cand = cand2;
                    }
                }
                if (cand > extend) {
                    dp[t].put(x, cand);
                    if (cand > best[t]) {
                        best[t] = cand;
                    }
                }
            }
        }
        int ans = 0;
        for (int v : best) {
            if (v > ans) {
                ans = v;
            }
        }
        return ans;
    }
}

