class Solution {
    public static int minAbsDifference(int[] nums, int k) {
        long best = Long.MAX_VALUE;
        int[] cur = new int[0];
        int curSize = 0;
        for (int x : nums) {
            int[] nxt = new int[curSize + 1];
            int nxtSize = 0;
            nxt[nxtSize++] = x;
            for (int i = 0; i < curSize; i++) {
                int v = cur[i] | x;
                boolean exists = false;
                for (int j = 0; j < nxtSize; j++) {
                    if (nxt[j] == v) {
                        exists = true;
                        break;
                    }
                }
                if (!exists) {
                    nxt[nxtSize++] = v;
                }
            }
            cur = nxt;
            curSize = nxtSize;
            for (int i = 0; i < curSize; i++) {
                long diff = Math.abs((long) k - cur[i]);
                if (diff < best) {
                    best = diff;
                }
            }
        }
        return (int) best;
    }
}

