import java.util.HashMap;

class Solution {
    public static int maxLengthGoodSubsequence(int[] nums, int k) {
        HashMap<Integer, Integer> compress = new HashMap<>();
        for (int x : nums) {
            if (!compress.containsKey(x)) {
                compress.put(x, compress.size());
            }
        }
        int m = compress.size();
        int[][] dp = new int[k + 1][m];
        int[] best = new int[k + 1];
        for (int x : nums) {
            int idx = compress.get(x);
            int[] prevBest = best.clone();
            int same = dp[0][idx] + 1;
            int cur = dp[0][idx];
            if (same > cur) cur = same;
            if (cur < 1) cur = 1;
            dp[0][idx] = cur;
            if (best[0] < cur) best[0] = cur;
            for (int c = 1; c <= k; c++) {
                int extendSame = dp[c][idx] + 1;
                int extendChange = prevBest[c - 1] + 1;
                int newLen = dp[c][idx];
                if (extendSame > newLen) newLen = extendSame;
                if (extendChange > newLen) newLen = extendChange;
                dp[c][idx] = newLen;
                if (best[c] < newLen) best[c] = newLen;
            }
        }
        int ans = 0;
        for (int c = 0; c <= k; c++) {
            if (best[c] > ans) ans = best[c];
        }
        return ans;
    }
}

