class Solution {
    public static long maxTotalDamage(int[] power) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int d : power) {
            freq.put(d, freq.getOrDefault(d, 0) + 1);
        }
        List<Integer> values = new ArrayList<>(freq.keySet());
        Collections.sort(values);
        int m = values.size();
        if (m == 0) return 0L;
        long[] dp = new long[m];
        int j = -1;
        for (int i = 0; i < m; ++i) {
            int dmg = values.get(i);
            long gain = (long) dmg * freq.get(dmg);
            while (j + 1 < i && values.get(j + 1) <= dmg - 3) {
                j++;
            }
            long take = gain + (j >= 0 ? dp[j] : 0L);
            long skip = i > 0 ? dp[i - 1] : 0L;
            dp[i] = take > skip ? take : skip;
        }
        return dp[m - 1];
    }
}

