        if (nums == null || nums.length < 2) {
            return Double.NaN;
        }
        Arrays.sort(nums);
        int n = nums.length;
        int half = n / 2;
        double minAvg = (nums[0] + nums[n - 1]) / 2.0;
        for (int i = 1; i < half; i++) {
            double avg = (nums[i] + nums[n - 1 - i]) / 2.0;
            if (avg < minAvg) {
                minAvg = avg;
            }
        }
        return minAvg;
    }
