import java.util.*;

public class Solution {
    public static int maxLength(int[] nums, int k) {
        int n = nums.length;
        if (n == 0) return 0;
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        int uniq = 0;
        for (int v : sorted) {
            if (uniq == 0 || sorted[uniq - 1] != v) {
                sorted[uniq++] = v;
            }
        }
        sorted = Arrays.copyOf(sorted, uniq);
        int m = sorted.length;
        int size = 1;
        while (size < m) size <<= 1;
        int[] seg = new int[2 * size];
        int answer = 0;
        for (int num : nums) {
            int left = lowerBound(sorted, num - k);
            int right = lowerBound(sorted, num) - 1; // only values strictly less than num
            int best = 0;
            if (left <= right) {
                best = query(seg, size, left, right);
            }
            int cur = best + 1;
            int idx = Arrays.binarySearch(sorted, num);
            update(seg, size, idx, cur);
            if (cur > answer) answer = cur;
        }
        return answer;
    }

    private static int lowerBound(int[] arr, int target) {
        int idx = Arrays.binarySearch(arr, target);
        return idx >= 0 ? idx : -idx - 1;
    }

    private static void update(int[] seg, int size, int pos, int val) {
        pos += size;
        if (val > seg[pos]) seg[pos] = val;
        while (pos > 1) {
            pos >>= 1;
            seg[pos] = Math.max(seg[pos << 1], seg[(pos << 1) | 1]);
        }
    }

    private static int query(int[] seg, int size, int l, int r) {
        l += size;
        r += size;
        int res = 0;
        while (l <= r) {
            if ((l & 1) == 1) res = Math.max(res, seg[l++]);
            if ((r & 1) == 0) res = Math.max(res, seg[r--]);
            l >>= 1;
            r >>= 1;
        }
        return res;
    }
}

import java.util.*;

class Solution {
    private static class DiaRad {
        int diameter;
        int radius;
        DiaRad(int diameter, int radius) {
            this.diameter = diameter;
            this.radius = radius;
        }
    }

    private static class BFSResult {
        int far;
        int[] dist;
        BFSResult(int far, int[] dist) {
            this.far = far;
            this.dist = dist;
        }
    }

    private static DiaRad getDiameterAndRadius(List<List<Integer>> edges) {
        int n = edges.size() + 1;
        int[] degree = new int[n];
        for (List<Integer> e : edges) {
            int u = e.get(0);
            int v = e.get(1);
            degree[u]++;
            degree[v]++;
        }
        int[][] adj = new int[n][];
        for (int i = 0; i < n; i++) {
            adj[i] = new int[degree[i]];
        }
        int[] idx = new int[n];
        for (List<Integer> e : edges) {
            int u = e.get(0);
            int v = e.get(1);
            adj[u][idx[u]++] = v;
            adj[v][idx[v]++] = u;
        }
        int start = edges.isEmpty() ? 0 : edges.get(0).get(0);
        BFSResult first = bfs(start, adj, n);
        BFSResult second = bfs(first.far, adj, n);
        int diameter = second.dist[second.far];
        int radius = (diameter + 1) / 2;
        return new DiaRad(diameter, radius);
    }

    private static BFSResult bfs(int start, int[][] adj, int n) {
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        int[] q = new int[n];
        int head = 0, tail = 0;
        q[tail++] = start;
        dist[start] = 0;
        int far = start;
        while (head < tail) {
            int cur = q[head++];
            for (int nb : adj[cur]) {
                if (dist[nb] == -1) {
                    dist[nb] = dist[cur] + 1;
                    q[tail++] = nb;
                    if (dist[nb] > dist[far]) {
                        far = nb;
                    }
                }
            }
        }
        return new BFSResult(far, dist);
    }

    public static int findMinDiameter(List<List<Integer>> edges1, List<List<Integer>> edges2) {
        DiaRad t1 = getDiameterAndRadius(edges1);
        DiaRad t2 = getDiameterAndRadius(edges2);
        int candidate = t1.radius + 1 + t2.radius;
        return Math.max(Math.max(t1.diameter, t2.diameter), candidate);
    }
}

public class Solution {
    public static long countSubarrays(int[] nums, int k) {
        long ans = 0;
        int[] prevVals = new int[32];
        int[] prevCnts = new int[32];
        int[] curVals = new int[32];
        int[] curCnts = new int[32];
        int prevSize = 0;
        for (int x : nums) {
            int curSize = 0;
            curVals[curSize] = x;
            curCnts[curSize] = 1;
            curSize++;
            for (int i = 0; i < prevSize; i++) {
                int newVal = prevVals[i] & x;
                if (newVal == curVals[curSize - 1]) {
                    curCnts[curSize - 1] += prevCnts[i];
                } else {
                    curVals[curSize] = newVal;
                    curCnts[curSize] = prevCnts[i];
                    curSize++;
                }
            }
            for (int i = 0; i < curSize; i++) {
                if (curVals[i] == k) {
                    ans += curCnts[i];
                }
            }
            int[] tmpVals = prevVals;
            prevVals = curVals;
            curVals = tmpVals;
            int[] tmpCnts = prevCnts;
            prevCnts = curCnts;
            curCnts = tmpCnts;
            prevSize = curSize;
        }
        return ans;
    }
}

import java.util.ArrayList;
import java.util.List;

class Solution {
    public static List<String> generateBinaryStrings(int n) {
        int capacity = fib(n + 2);
        List<String> result = new ArrayList<>(capacity);
        char[] cur = new char[n];
        dfs(0, false, cur, n, result);
        return result;
    }

    private static void dfs(int pos, boolean prevZero, char[] cur, int n, List<String> result) {
        if (pos == n) {
            result.add(new String(cur));
            return;
        }
        if (!prevZero) {
            cur[pos] = '0';
            dfs(pos + 1, true, cur, n, result);
        }
        cur[pos] = '1';
        dfs(pos + 1, false, cur, n, result);
    }

    private static int fib(int k) {
        int a = 0, b = 1;
        for (int i = 0; i < k; i++) {
            int temp = a + b;
            a = b;
            b = temp;
        }
        return a;
    }
}

public class P3 {
