class Solution {
    public static int count_alternating_groups(List<Integer> colors) {
        int n = colors.size();
        if (n < 3) return 0;
        int groups = 0;
        for (int i = 0; i < n; ++i) {
            int left = (i - 1 + n) % n;
            int right = (i + 1) % n;
            int cur = colors.get(i);
            int l = colors.get(left);
            int r = colors.get(right);
            if (cur != l && l == r) ++groups;
        }
        return groups;
    }
}

