public class Solution {
    public static int numberOfAlternatingGroups(int[] colors, int k) {
        int n = colors.length;
        if (k == 1) return n;
        int need = k - 1;
        int[] diff = new int[n];
        for (int i = 0; i < n; ++i) {
            diff[i] = (colors[i] != colors[(i + 1) % n]) ? 1 : 0;
        }
        int sum = 0;
        for (int i = 0; i < need; ++i) {
            sum += diff[i];
        }
        int ans = 0;
        if (sum == need) ++ans;
        for (int start = 1; start < n; ++start) {
            sum -= diff[(start - 1) % n];
            sum += diff[(start + need - 1) % n];
            if (sum == need) ++ans;
        }
        return ans;
    }
}

