class Solution {
    public static long minCost(int m, int n, long[] horizontalCut, long[] verticalCut) {
        Arrays.sort(horizontalCut);
        Arrays.sort(verticalCut);
        int i = horizontalCut.length - 1;
        int j = verticalCut.length - 1;
        long horizPieces = 1, vertPieces = 1;
        long total = 0;
        while (i >= 0 && j >= 0) {
            if (horizontalCut[i] > verticalCut[j]) {
                total += horizontalCut[i] * vertPieces;
                horizPieces++;
                i--;
            } else {
                total += verticalCut[j] * horizPieces;
                vertPieces++;
                j--;
            }
        }
        while (i >= 0) {
            total += horizontalCut[i] * vertPieces;
            i--;
        }
        while (j >= 0) {
            total += verticalCut[j] * horizPieces;
            j--;
        }
        return total;
    }
}

