class Solution {
    public static ListNode deleteNodes(int[] nums, ListNode head) {
        Set<Integer> toDelete = new HashSet<>(nums.length);
        for (int num : nums) {
            toDelete.add(num);
        }
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode prev = dummy;
        ListNode curr = head;
        while (curr != null) {
            if (toDelete.contains(curr.val)) {
                prev.next = curr.next;
            } else {
                prev = curr;
            }
            curr = curr.next;
        }
        return dummy.next;
    }
}

class ListNode {
    int val;
    ListNode next;
    ListNode() { val = 0; next = null; }
    ListNode(int x) { val = x; next = null; }
    ListNode(int x, ListNode nextNode) { val = x; next = nextNode; }
}

class Solution {
    public static int minimumLengthAfterOperations(String s) {
        StringBuilder stack = new StringBuilder();
        for (char ch : s.toCharArray()) {
            stack.append(ch);
            while (stack.length() >= 2) {
                char a = stack.charAt(stack.length()-2), b = stack.charAt(stack.length()-1);
                if ((a=='a'&&b=='b')||(a=='b'&&b=='c')) { stack.setLength(stack.length()-2); }
                else break;
            }
        }
        return stack.length();
    }
}

class Solution {
    public int minChanges(int[] nums, int k) {
        int n = nums.length;
        int[] d = new int[k + 2];
        for (int i = 0; i < n / 2; i++) {
            int x = nums[i], y = nums[n - 1 - i];
            if (x > y) { int t = x; x = y; y = t; }
            d[0] += 1;
            d[y - x] -= 1;
            d[y - x + 1] += 1;
            int idx = Math.max(y, k - x) + 1;
            d[idx] += 1;
        }
        int ans = n, s = 0;
        for (int v : d) {
            s += v;
            ans = Math.min(ans, s);
        }
        return ans;
    }
}

