        for (int j = 0; j < n; j++)
            for (int i = 0; i < n; i++)
                colPrefix[j][i+1] = colPrefix[j][i] + grid[i][j];

        long[][] dp = new long[n+1][n+1];
        for (long[] row : dp) java.util.Arrays.fill(row, Long.MIN_VALUE/2);
        for (int h = 0; h <= n; h++) dp[0][h] = 0;

        for (int c = 1; c < n; c++) {
            long[][] ndp = new long[n+1][n+1];
            for (long[] row : ndp) java.util.Arrays.fill(row, Long.MIN_VALUE/2);
            for (int hPrev = 0; hPrev <= n; hPrev++) {
                for (int hCur = 0; hCur <= n; hCur++) {
                    if (dp[hPrev][hCur] <= Long.MIN_VALUE/4) continue;
                    for (int hNext = 0; hNext <= n; hNext++) {
                        int boundary = Math.max(hPrev, hNext);
                        long credit = rangeSum(colPrefix[c-1], hCur, boundary);
                        long val = dp[hPrev][hCur] + credit;
                        if (val > ndp[hCur][hNext]) ndp[hCur][hNext] = val;
                    }
                }
            }
            dp = ndp;
        }

        long best = Long.MIN_VALUE;
        for (int hPrev = 0; hPrev <= n; hPrev++) {
            for (int hCur = 0; hCur <= n; hCur++) {
                if (dp[hPrev][hCur] <= Long.MIN_VALUE/4) continue;
                int boundary = hPrev;
                long credit = rangeSum(colPrefix[n-1], hCur, boundary);
                long val = dp[hPrev][hCur] + credit;
                if (val > best) best = val;
            }
        }
        return best;
    }
    private static long rangeSum(long[] prefix, int lo, int hi) {
        if (hi <= lo) return 0;
        return prefix[hi] - prefix[lo];
    }
}

