public class Solution {
    public static long countNotSpecial(long l, long r) {
        long total = r - l + 1;
        long low = (long) Math.ceil(Math.sqrt(l));
        long high = (long) Math.floor(Math.sqrt(r));
        if (low > high) return total;
        if (high < 2) return total;
        int limit = (int) high;
        boolean[] isComposite = new boolean[limit + 1];
        for (int i = 2; i * i <= limit; i++) {
            if (!isComposite[i]) {
                for (int j = i * i; j <= limit; j += i) {
                    isComposite[j] = true;
                }
            }
        }
        long primeSquareCount = 0;
        for (long p = Math.max(low, 2); p <= high; p++) {
            if (!isComposite[(int) p]) {
                primeSquareCount++;
            }
        }
        return total - primeSquareCount;
    }
}

