public class Solution {
    public static boolean canAliceWin(String s) {
        int groups = 0;
        boolean inVowelGroup = false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            boolean isVowel = c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
            if (isVowel) {
                if (!inVowelGroup) {
                    groups++;
                    inVowelGroup = true;
                }
            } else {
                inVowelGroup = false;
            }
        }
        return (groups & 1) == 1;
    }
