public class Solution {
    public static int minFlips(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return 0;
        }
        int m = grid.length;
        int n = grid[0].length;
        int rowFlips = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n / 2; j++) {
                if (grid[i][j] != grid[i][n - 1 - j]) {
                    rowFlips++;
                }
            }
        }
        int colFlips = 0;
        for (int j = 0; j < n; j++) {
            for (int i = 0; i < m / 2; i++) {
                if (grid[i][j] != grid[m - 1 - i][j]) {
                    colFlips++;
                }
            }
        }
        return Math.min(rowFlips, colFlips);
    }
}

import java.util.*;

class Solution {
    static class DSU {
        private final int[] parent;
        private final byte[] rank;
        DSU(int n) {
            parent = new int[n];
            rank = new byte[n];
            for (int i = 0; i < n; i++) parent[i] = i;
        }
        int find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }
        void unite(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return;
            if (rank[ra] < rank[rb]) {
                parent[ra] = rb;
            } else if (rank[ra] > rank[rb]) {
                parent[rb] = ra;
            } else {
                parent[rb] = ra;
                rank[ra]++;
            }
        }
    }

    private static boolean touchesSide(long cx, long cy, long r, long X, long Y, int side) {
        long dx = 0, dy = 0;
        switch (side) {
            case 0: // left x=0
                dx = cx;
                if (cy < 0) dy = -cy;
                else if (cy > Y) dy = cy - Y;
                else dy = 0;
                break;
            case 1: // right x=X
                dx = cx - X;
                if (cy < 0) dy = -cy;
                else if (cy > Y) dy = cy - Y;
                else dy = 0;
                break;
            case 2: // bottom y=0
                dy = cy;
                if (cx < 0) dx = -cx;
                else if (cx > X) dx = cx - X;
                else dx = 0;
                break;
            case 3: // top y=Y
                dy = cy - Y;
                if (cx < 0) dx = -cx;
                else if (cx > X) dx = cx - X;
                else dx = 0;
                break;
        }
        long dist2 = dx * dx + dy * dy;
        return dist2 <= r * r;
    }

    public static boolean isPathPossible(int xCorner, int yCorner, int[][] circles) {
        int n = circles.length;
        int leftIdx = n;
        int rightIdx = n + 1;
        int bottomIdx = n + 2;
        int topIdx = n + 3;
        DSU dsu = new DSU(n + 4);
        long X = xCorner;
        long Y = yCorner;

        for (int i = 0; i < n; i++) {
            long cx = circles[i][0];
            long cy = circles[i][1];
            long r = circles[i][2];
            if (touchesSide(cx, cy, r, X, Y, 0)) dsu.unite(i, leftIdx);
            if (touchesSide(cx, cy, r, X, Y, 1)) dsu.unite(i, rightIdx);
            if (touchesSide(cx, cy, r, X, Y, 2)) dsu.unite(i, bottomIdx);
            if (touchesSide(cx, cy, r, X, Y, 3)) dsu.unite(i, topIdx);
        }

        for (int i = 0; i < n; i++) {
            long xi = circles[i][0];
            long yi = circles[i][1];
            long ri = circles[i][2];
            for (int j = i + 1; j < n; j++) {
                long xj = circles[j][0];
                long yj = circles[j][1];
                long rj = circles[j][2];
                long dx = xi - xj;
                long dy = yi - yj;
                long dist2 = dx * dx + dy * dy;
                long radSum = ri + rj;
                if (dist2 <= radSum * radSum) dsu.unite(i, j);
            }
        }

        if (dsu.find(leftIdx) == dsu.find(rightIdx)) return false;
        if (dsu.find(bottomIdx) == dsu.find(topIdx)) return false;
        if (dsu.find(leftIdx) == dsu.find(bottomIdx)) return false;
        if (dsu.find(rightIdx) == dsu.find(topIdx)) return false;
        return true;
    }
}

