class Solution {
    public static int minFlips(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        long INF = 1L << 60;
        long[] dp = new long[4];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int i = 0; i <= (m - 1) / 2; i++) {
            for (int j = 0; j <= (n - 1) / 2; j++) {
                int[] xs = {i, i, m - 1 - i, m - 1 - i};
                int[] ys = {j, n - 1 - j, j, n - 1 - j};
                int sz = 0;
                int ones = 0;
                for (int k = 0; k < 4; k++) {
                    int x = xs[k];
                    int y = ys[k];
                    boolean dup = false;
                    for (int t = 0; t < k; t++) {
                        if (xs[t] == x && ys[t] == y) {
                            dup = true;
                            break;
                        }
                    }
                    if (!dup) {
                        sz++;
                        ones += grid[x][y];
                    }
                }
                long cost0 = ones;
                long cost1 = sz - ones;
                long[] ndp = new long[4];
                Arrays.fill(ndp, INF);
                for (int mod = 0; mod < 4; mod++) {
                    if (dp[mod] == INF) continue;
                    ndp[mod] = Math.min(ndp[mod], dp[mod] + cost0);
                    int nmod = (mod + sz) & 3;
                    ndp[nmod] = Math.min(ndp[nmod], dp[mod] + cost1);
                }
                dp = ndp;
            }
        }
        return (int) dp[0];
    }
}

