class Solution {
    public static List<Double> shortest_distance_after_road_addition_queries_ii(int n, List<int[]> queries) {
        List<List<Integer>> extraAdj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) extraAdj.add(new ArrayList<>());
        int[] dist = new int[n];
        for (int i = 0; i < n; i++) dist[i] = i;
        List<Double> results = new ArrayList<>(queries.size());
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        boolean[] inQueue = new boolean[n];
        for (int[] q : queries) {
            int l = q[0];
            int r = q[1];
            extraAdj.get(l).add(r);
            if (dist[l] + 1 < dist[r]) {
                dist[r] = dist[l] + 1;
                queue.clear();
                Arrays.fill(inQueue, false);
                queue.add(r);
                inQueue[r] = true;
                while (!queue.isEmpty()) {
                    int u = queue.poll();
                    inQueue[u] = false;
                    int du = dist[u];
                    if (u + 1 < n && du + 1 < dist[u + 1]) {
                        dist[u + 1] = du + 1;
                        if (!inQueue[u + 1]) {
                            queue.add(u + 1);
                            inQueue[u + 1] = true;
                        }
                    }
                    for (int v : extraAdj.get(u)) {
                        if (du + 1 < dist[v]) {
                            dist[v] = du + 1;
                            if (!inQueue[v]) {
                                queue.add(v);
                                inQueue[v] = true;
                            }
                        }
                    }
                }
            }
            results.add((double) dist[n - 1]);
        }
        return results;
    }
}

