class Solution {
    private static int good;

    public static int countGoodNodes(List<List<Integer>> edges) {
        int n = edges.size() + 1;
        int[] degree = new int[n];
        for (List<Integer> e : edges) {
            int a = e.get(0);
            int b = e.get(1);
            degree[a]++;
            degree[b]++;
        }
        int[][] adj = new int[n][];
        for (int i = 0; i < n; i++) {
            adj[i] = new int[degree[i]];
        }
        int[] idx = new int[n];
        for (List<Integer> e : edges) {
            int a = e.get(0);
            int b = e.get(1);
            adj[a][idx[a]++] = b;
            adj[b][idx[b]++] = a;
        }
        good = 0;
        dfs(0, -1, adj);
        return good;
    }

    private static int dfs(int u, int parent, int[][] adj) {
        int firstSize = -1;
        boolean isGood = true;
        int total = 1;
        for (int v : adj[u]) {
            if (v == parent) continue;
            int sz = dfs(v, u, adj);
            if (firstSize == -1) {
                firstSize = sz;
            } else if (sz != firstSize) {
                isGood = false;
            }
            total += sz;
        }
        if (isGood) good++;
        return total;
    }
}

import java.util.HashSet;
