class Solution {
    public static int find_smallest_missing_integer(int[] nums) {
        long maxSum = 0;
        int maxLen = 0;
        long curSum = 0;
        int curLen = 0;
        for (int i = 0; i < nums.length; i++) {
            if (i == 0 || nums[i] == nums[i - 1] + 1) {
                curSum += nums[i];
                curLen++;
            } else {
                curSum = nums[i];
                curLen = 1;
            }
            if (curLen > maxLen) {
                maxLen = curLen;
                maxSum = curSum;
            }
        }
        Set<Integer> numSet = new HashSet<>();
        for (int v : nums) {
            numSet.add(v);
        }
        long candidate = maxSum;
        while (numSet.contains((int) candidate)) {
            candidate++;
        }
        return (int) candidate;
    }
}

import java.util.*;
class NeighborSum {
    int n;
    List<List<Integer>> grid;
    Map<Integer,int[]> pos = new HashMap<>();
    public NeighborSum(List<List<Integer>> grid) {
        this.grid = grid;
        this.n = grid.size();
        for (int i = 0; i < n; i++) for (int j = 0; j < grid.get(i).size(); j++) pos.put(grid.get(i).get(j), new int[]{i,j});
    }
    public int adjacentSum(int value) {
        int[] p = pos.get(value);
        if (p == null) return 0;
        int i = p[0], j = p[1], total = 0;
        if (i>0) total += grid.get(i-1).get(j);
        if (i<n-1) total += grid.get(i+1).get(j);
        if (j>0) total += grid.get(i).get(j-1);
        if (j<n-1) total += grid.get(i).get(j+1);
        return total;
    }
    public int diagonalSum(int value) {
        int[] p = pos.get(value);
        if (p == null) return 0;
        int i = p[0], j = p[1], total = 0;
        if (i>0 && j>0) total += grid.get(i-1).get(j-1);
        if (i>0 && j<n-1) total += grid.get(i-1).get(j+1);
        if (i<n-1 && j>0) total += grid.get(i+1).get(j-1);
        if (i<n-1 && j<n-1) total += grid.get(i+1).get(j+1);
        return total;
    }
}

