public class Solution {
    public static int countMonotonicPairs(int[] nums) {
        if (nums == null || nums.length == 0) return 0;
        final int MOD = 1_000_000_007;
        final int MAX = 50;
        int[] dp = new int[MAX + 1];
        for (int v = 0; v <= nums[0]; v++) dp[v] = 1;
        int[] pref = new int[MAX + 1];
        int[] next = new int[MAX + 1];
        for (int i = 0; i + 1 < nums.length; i++) {
            int diff = nums[i + 1] - nums[i];
            int need = diff > 0 ? diff : 0;
            pref[0] = dp[0];
            for (int v = 1; v <= MAX; v++) {
                pref[v] = pref[v - 1] + dp[v];
                if (pref[v] >= MOD) pref[v] -= MOD;
            }
            Arrays.fill(next, 0);
            for (int v = 0; v <= nums[i + 1]; v++) {
                int limit = v - need;
                if (limit >= 0) {
                    next[v] = pref[limit];
                }
            }
            int[] tmp = dp;
            dp = next;
            next = tmp;
        }
        int ans = 0;
        int last = nums[nums.length - 1];
        for (int v = 0; v <= last; v++) {
            ans += dp[v];
            if (ans >= MOD) ans -= MOD;
        }
        return ans;
    }
}

class Solution {
    public static long countDominantOnes(String s) {
        int n = s.length();
        int[] prefOnes = new int[n + 1];
        for (int i = 0; i < n; ++i) {
            prefOnes[i + 1] = prefOnes[i] + (s.charAt(i) == '1' ? 1 : 0);
        }
        int maxZeros = (int) Math.sqrt(n);
        long ans = 0;
        for (int r = 0; r < n; ++r) {
            for (int l = r; l >= 0; --l) {
                int ones = prefOnes[r + 1] - prefOnes[l];
                int length = r - l + 1;
                int zeros = length - ones;
                if (zeros > maxZeros) break;
                if (ones >= zeros * zeros) ++ans;
            }
        }
        return ans;
    }
}

