class Solution {
    public static int[] shortestDistanceAfterRoadAdditionQueriesI(int n, List<List<Integer>> queries) {
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int i = 0; i < n - 1; i++) {
            adj[i].add(i + 1);
        }
        int[] dist = new int[n];
        for (int i = 0; i < n; i++) {
            dist[i] = i;
        }
        int[] result = new int[queries.size()];
        int idx = 0;
        for (List<Integer> q : queries) {
            int u = q.get(0);
            int v = q.get(1);
            adj[u].add(v);
            if (dist[u] + 1 < dist[v]) {
                dist[v] = dist[u] + 1;
                ArrayDeque<Integer> queue = new ArrayDeque<>();
                queue.add(v);
                while (!queue.isEmpty()) {
                    int cur = queue.poll();
                    int curDist = dist[cur];
                    for (int nxt : adj[cur]) {
                        if (curDist + 1 < dist[nxt]) {
                            dist[nxt] = curDist + 1;
                            queue.add(nxt);
                        }
                    }
                }
            }
            result[idx++] = dist[n - 1];
        }
        return result;
    }
}

