class Solution {
    public static long[] alternatingGroups(int[] colors, int[][] queries) {
        int n = colors.length;
        int[] diff = new int[n];
        for (int i = 0; i < n; ++i) {
            diff[i] = (colors[i] != colors[(i + 1) % n]) ? 1 : 0;
        }
        List<Long> res = new ArrayList<>();
        for (int[] q : queries) {
            if (q[0] == 1) {
                int k = q[1];
                if (k == 1) {
                    res.add((long) n);
                    continue;
                }
                int L = k - 1;
                long ans = 0;
                int cur = 0;
                for (int i = 0; i < 2 * n; ++i) {
                    int idx = i % n;
                    if (diff[idx] == 1) {
                        ++cur;
                    } else {
                        cur = 0;
                    }
                    if (cur >= L) {
                        int start = i - (L - 1);
                        if (start < n) {
                            ++ans;
                        }
                    }
                }
                res.add(ans);
            } else {
                int i = q[1];
                int v = q[2];
                if (colors[i] == v) continue;
                colors[i] = v;
                int left = (i - 1 + n) % n;
                diff[left] = (colors[left] != colors[i]) ? 1 : 0;
                diff[i] = (colors[i] != colors[(i + 1) % n]) ? 1 : 0;
            }
        }
        long[] out = new long[res.size()];
        for (int i = 0; i < res.size(); ++i) out[i] = res.get(i);
        return out;
    }
}

import java.util.*;

class Solution {
    public static long maximumValueSum(int[][] board) {
        int m = board.length;
        int n = board[0].length;
        int K = Math.min(3, n);
        int[][] topCols = new int[m][K];
        long[][] topVals = new long[m][K];
        for (int i = 0; i < m; i++) {
            Arrays.fill(topCols[i], -1);
            Arrays.fill(topVals[i], Long.MIN_VALUE);
            for (int j = 0; j < n; j++) {
                long val = board[i][j];
                if (val > topVals[i][0]) {
                    for (int t = K - 1; t > 0; t--) {
                        topVals[i][t] = topVals[i][t - 1];
                        topCols[i][t] = topCols[i][t - 1];
                    }
                    topVals[i][0] = val;
                    topCols[i][0] = j;
                } else if (K > 1 && val > topVals[i][1]) {
                    for (int t = K - 1; t > 1; t--) {
                        topVals[i][t] = topVals[i][t - 1];
                        topCols[i][t] = topCols[i][t - 1];
                    }
                    topVals[i][1] = val;
                    topCols[i][1] = j;
                } else if (K > 2 && val > topVals[i][2]) {
                    topVals[i][2] = val;
                    topCols[i][2] = j;
                }
            }
        }
        long ans = Long.MIN_VALUE;
        for (int i = 0; i < m; i++) {
            for (int j = i + 1; j < m; j++) {
                for (int k = j + 1; k < m; k++) {
                    for (int a = 0; a < K; a++) {
                        int colA = topCols[i][a];
                        if (colA == -1) continue;
                        long valA = topVals[i][a];
                        for (int b = 0; b < K; b++) {
                            int colB = topCols[j][b];
                            if (colB == -1 || colB == colA) continue;
                            long valB = topVals[j][b];
                            for (int c = 0; c < K; c++) {
                                int colC = topCols[k][c];
                                if (colC == -1 || colC == colA || colC == colB) continue;
                                long sum = valA + valB + topVals[k][c];
                                if (sum > ans) ans = sum;
                            }
                        }
                    }
                }
            }
        }
        return ans;
    }
}

