class Solution {
    public static long countKConstraintSubstrings(String s, int k) {
        int n = s.length();
        long ans = 0;
        int zeros = 0, ones = 0;
        int r = 0;
        for (int l = 0; l < n; ++l) {
            while (r < n && !(zeros > k && ones > k)) {
                if (s.charAt(r) == '0') ++zeros;
                else ++ones;
                ++r;
            }
            if (zeros > k && ones > k) {
                ans += r - l - 1;
            } else {
                ans += n - l;
            }
            if (s.charAt(l) == '0') --zeros;
            else --ones;
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    public static int[] findPowerOfKSizeSubarrays(int[] nums, int k) {
        int n = nums.length;
        if (k > n) {
            return new int[0];
        }
        int[] result = new int[n - k + 1];
        if (k == 1) {
            for (int i = 0; i < result.length; i++) {
                result[i] = nums[i];
            }
            return result;
        }
        int[] inc = new int[n - 1];
        for (int i = 1; i < n; i++) {
            inc[i - 1] = nums[i] > nums[i - 1] ? 1 : 0;
        }
        int windowSum = 0;
        for (int i = 0; i < k - 1; i++) {
            windowSum += inc[i];
        }
        for (int i = 0; i <= n - k; i++) {
            result[i] = (windowSum == k - 1) ? nums[i + k - 1] : -1;
            if (i < n - k) {
                windowSum += inc[i + k - 1];
                windowSum -= inc[i];
            }
        }
        return result;
    }
}

import java.util.Arrays;

class Solution {
    public static long maximumValueSum(int[][] board) {
        int m = board.length;
        int n = board[0].length;
        long NEG_INF = Long.MIN_VALUE / 4;
        long answer = NEG_INF;

        if (m <= n) {
            for (int i = 0; i < m; ++i) {
                for (int j = i + 1; j < m; ++j) {
                    for (int k = j + 1; k < m; ++k) {
                        int[] rows = {i, j, k};
                        long[] dp = new long[8];
                        Arrays.fill(dp, NEG_INF);
                        dp[0] = 0;
                        long[] ndp = new long[8];
                        for (int col = 0; col < n; ++col) {
                            System.arraycopy(dp, 0, ndp, 0, 8);
                            for (int mask = 0; mask < 8; ++mask) {
                                long cur = dp[mask];
                                if (cur == NEG_INF) continue;
                                for (int r = 0; r < 3; ++r) {
                                    if ((mask & (1 << r)) != 0) continue;
                                    int nmask = mask | (1 << r);
                                    long val = cur + board[rows[r]][col];
                                    if (val > ndp[nmask]) ndp[nmask] = val;
                                }
                            }
                            long[] tmp = dp;
                            dp = ndp;
                            ndp = tmp;
                        }
                        if (dp[7] > answer) answer = dp[7];
                    }
                }
            }
        } else {
            for (int c1 = 0; c1 < n; ++c1) {
                for (int c2 = c1 + 1; c2 < n; ++c2) {
                    for (int c3 = c2 + 1; c3 < n; ++c3) {
                        int[] cols = {c1, c2, c3};
                        long[] dp = new long[8];
                        Arrays.fill(dp, NEG_INF);
                        dp[0] = 0;
                        long[] ndp = new long[8];
                        for (int row = 0; row < m; ++row) {
                            System.arraycopy(dp, 0, ndp, 0, 8);
                            for (int mask = 0; mask < 8; ++mask) {
                                long cur = dp[mask];
                                if (cur == NEG_INF) continue;
                                for (int c = 0; c < 3; ++c) {
                                    if ((mask & (1 << c)) != 0) continue;
                                    int nmask = mask | (1 << c);
                                    long val = cur + board[row][cols[c]];
                                    if (val > ndp[nmask]) ndp[nmask] = val;
                                }
                            }
                            long[] tmp = dp;
                            dp = ndp;
                            ndp = tmp;
                        }
                        if (dp[7] > answer) answer = dp[7];
                    }
                }
            }
        }
        return answer;
    }
}

public class Solution {
    public static int[] powerOfKSizeSubarrays(int[] nums, int k) {
        int n = nums.length;
        int[] results = new int[n - k + 1];
        int sumInc = 0;
        for (int i = 1; i < k; ++i) {
            if (nums[i] > nums[i - 1]) sumInc++;
        }
        int target = k - 1;
        for (int start = 0; start <= n - k; ++start) {
            results[start] = (sumInc == target) ? nums[start + k - 1] : -1;
            if (start < n - k) {
                int removeIdx = start + 1;
                int addIdx = start + k;
                if (nums[removeIdx] > nums[removeIdx - 1]) sumInc--;
                if (nums[addIdx] > nums[addIdx - 1]) sumInc++;
            }
        }
        return results;
    }
}

import java.util.*;

class Solution {
    static class Fenwick {
        int n;
        long[] bit;
        Fenwick(int size) {
            n = size;
            bit = new long[n + 1];
        }
        void add(int idx, long delta) {
            for (int i = idx; i <= n; i += i & -i) {
                bit[i] += delta;
            }
        }
        long sum(int idx) {
            long res = 0;
            for (int i = idx; i > 0; i -= i & -i) {
                res += bit[i];
            }
            return res;
        }
        long rangeSum(int l, int r) {
            return sum(r + 1) - sum(l);
        }
    }

    static class Query {
        int l, r, idx;
        Query(int l, int r, int idx) {
            this.l = l;
            this.r = r;
            this.idx = idx;
        }
    }

    public static long[] countKConstraintSubstrings(String s, int k, int[][] queries) {
        int n = s.length();
        int[] r0 = new int[n];
        int[] r1 = new int[n];
        int right = -1;
        int zeros = 0;
        for (int left = 0; left < n; ++left) {
            while (right + 1 < n && zeros + (s.charAt(right + 1) == '0' ? 1 : 0) <= k) {
                ++right;
                if (s.charAt(right) == '0') ++zeros;
            }
            r0[left] = right;
            if (right >= left) {
                if (s.charAt(left) == '0') --zeros;
            } else {
                right = left - 1;
            }
        }
        right = -1;
        int ones = 0;
        for (int left = 0; left < n; ++left) {
            while (right + 1 < n && ones + (s.charAt(right + 1) == '1' ? 1 : 0) <= k) {
                ++right;
                if (s.charAt(right) == '1') ++ones;
            }
            r1[left] = right;
            if (right >= left) {
                if (s.charAt(left) == '1') --ones;
            } else {
                right = left - 1;
            }
        }
        int[] maxGood = new int[n];
        for (int i = 0; i < n; ++i) {
            maxGood[i] = Math.max(r0[i], r1[i]);
        }
        Fenwick bitCnt = new Fenwick(n);
        Fenwick bitSum = new Fenwick(n);
        Query[] qObjs = new Query[queries.length];
        for (int i = 0; i < queries.length; ++i) {
            qObjs[i] = new Query(queries[i][0], queries[i][1], i);
        }
        Arrays.sort(qObjs, Comparator.comparingInt(a -> a.r));
        long[] ans = new long[queries.length];
        int pos = 0;
        for (Query q : qObjs) {
            while (pos < n && maxGood[pos] <= q.r) {
                bitCnt.add(pos + 1, 1);
                bitSum.add(pos + 1, maxGood[pos]);
                ++pos;
            }
            long len = (long) q.r - q.l + 1;
            long cntLe = bitCnt.rangeSum(q.l, q.r);
            long sumLe = bitSum.rangeSum(q.l, q.r);
            long cntGt = len - cntLe;
            long sumMin = sumLe + (long) q.r * cntGt;
            long sumI = ((long) q.l + q.r) * len / 2;
            ans[q.idx] = sumMin + len - sumI;
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    public static long[] finalArrayState(long[] nums, long k, long multiplier) {
        int n = nums.length;
        if (n == 0) return new long[0];
        long[] heapVals = new long[n];
        int[] heapIdx = new int[n];
        for (int i = 0; i < n; i++) {
            heapVals[i] = nums[i];
            heapIdx[i] = i;
        }
        for (int i = (n >> 1) - 1; i >= 0; i--) {
            heapifyDown(heapVals, heapIdx, i, n);
        }
        for (long op = 0; op < k; op++) {
            heapVals[0] *= multiplier;
            int idx = heapIdx[0];
            nums[idx] = heapVals[0];
            heapifyDown(heapVals, heapIdx, 0, n);
        }
        return nums;
    }

    private static void heapifyDown(long[] vals, int[] idxs, int pos, int size) {
        while (true) {
            int left = (pos << 1) + 1;
            int right = left + 1;
            int smallest = pos;
            if (left < size && less(vals, idxs, left, smallest)) smallest = left;
            if (right < size && less(vals, idxs, right, smallest)) smallest = right;
            if (smallest != pos) {
                swap(vals, idxs, pos, smallest);
                pos = smallest;
            } else {
                break;
            }
        }
    }

    private static boolean less(long[] vals, int[] idxs, int a, int b) {
        if (vals[a] != vals[b]) return vals[a] < vals[b];
        return idxs[a] < idxs[b];
    }

    private static void swap(long[] vals, int[] idxs, int i, int j) {
        long tmpVal = vals[i];
        vals[i] = vals[j];
        vals[j] = tmpVal;
        int tmpIdx = idxs[i];
        idxs[i] = idxs[j];
        idxs[j] = tmpIdx;
    }
}

class Solution {
    public static int maxEnergyBoost(int[] energyDrinkA, int[] energyDrinkB) {
        int n = energyDrinkA.length;
        if (n == 0) return 0;
        int a = energyDrinkA[0];
        int b = energyDrinkB[0];
        int s = 0;
        for (int i = 1; i < n; i++) {
            int prevA = a;
            int prevB = b;
            int prevS = s;
            a = Math.max(prevA, prevS) + energyDrinkA[i];
            b = Math.max(prevB, prevS) + energyDrinkB[i];
            s = Math.max(prevA, Math.max(prevB, prevS));
        }
        return Math.max(a, Math.max(b, s));
    }
}

