public class Solution {
    public static String largestPalindrome(int n, int k) {
        if (k == 0) return "";
        int m = (n + 1) / 2;
        int[] pow10 = new int[n];
        pow10[0] = 1 % k;
        for (int i = 1; i < n; ++i) {
            pow10[i] = (int) ((long) pow10[i - 1] * 10 % k);
        }
        int[] weight = new int[m];
        for (int i = 0; i < m; ++i) {
            int j = n - 1 - i;
            if (i == j) weight[i] = pow10[i] % k;
            else weight[i] = (pow10[i] + pow10[j]) % k;
        }
        boolean[][] reachable = new boolean[m + 1][k];
        reachable[m][0] = true;
        for (int i = m - 1; i >= 0; --i) {
            for (int r = 0; r < k; ++r) {
                if (!reachable[i + 1][r]) continue;
                for (int d = 0; d <= 9; ++d) {
                    if (i == 0 && d == 0) continue;
                    int nr = (int) ((d * (long) weight[i] + r) % k);
                    reachable[i][nr] = true;
                }
            }
        }
        if (!reachable[0][0]) return "";
        char[] firstHalf = new char[m];
        int need = 0;
        for (int i = 0; i < m; ++i) {
            for (int d = 9; d >= 0; --d) {
                if (i == 0 && d == 0) continue;
                int contrib = (int) (d * (long) weight[i] % k);
                int suffix = need - contrib;
                suffix %= k;
                if (suffix < 0) suffix += k;
                if (reachable[i + 1][suffix]) {
                    firstHalf[i] = (char) ('0' + d);
                    need = suffix;
                    break;
                }
            }
        }
        StringBuilder sb = new StringBuilder(n);
        for (char c : firstHalf) sb.append(c);
        int start = (n % 2 == 0) ? m - 1 : m - 2;
        for (int i = start; i >= 0; --i) sb.append(firstHalf[i]);
        return sb.toString();
    }
}

class Solution {
    public static int findKey(int num1, int num2, int num3) {
        int result = 0;
        int place = 1;
        for (int i = 0; i < 4; i++) {
            int d1 = num1 % 10;
            int d2 = num2 % 10;
            int d3 = num3 % 10;
            int min = Math.min(d1, Math.min(d2, d3));
            result += min * place;
            place *= 10;
            num1 /= 10;
            num2 /= 10;
            num3 /= 10;
        }
        return result;
    }
}

