class Solution {
    public static int countPairs(int[] nums) {
        int n = nums.length;
        int count = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (areAlmostEqual(nums[i], nums[j]) || areAlmostEqual(nums[j], nums[i])) {
                    count++;
                }
            }
        }
        return count;
    }

    private static boolean areAlmostEqual(int a, int b) {
        if (a == b) return true;
        char[] s = Integer.toString(a).toCharArray();
        int len = s.length;
        for (int i = 0; i < len; i++) {
            for (int j = i + 1; j < len; j++) {
                if (s[i] == s[j]) continue;
                char temp = s[i];
                s[i] = s[j];
                s[j] = temp;
                int val = Integer.parseInt(new String(s));
                if (val == b) {
                    return true;
                }
                temp = s[i];
                s[i] = s[j];
                s[j] = temp;
            }
        }
        return false;
    }
}

import java.util.*;

class Solution {
    private static int parse(char[] arr) {
        int i = 0;
        while (i < arr.length && arr[i] == '0') i++;
        if (i == arr.length) return 0;
        int val = 0;
        for (; i < arr.length; i++) {
            val = val * 10 + (arr[i] - '0');
        }
        return val;
    }

    private static void swap(char[] arr, int i, int j) {
        char tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }

    private static HashSet<Integer> generate(int num) {
        char[] original = Integer.toString(num).toCharArray();
        int L = original.length;
        HashSet<Integer> result = new HashSet<>();
        result.add(parse(original));
        for (int i = 0; i < L; i++) {
            for (int j = i + 1; j < L; j++) {
                swap(original, i, j);
                result.add(parse(original));
                swap(original, i, j);
            }
        }
        return result;
    }

    public static long countAlmostEqualPairsII(int[] nums) {
        int n = nums.length;
        Map<Integer, List<Integer>> valueMap = new HashMap<>();
        for (int i = 0; i < n; i++) {
            HashSet<Integer> reachable = generate(nums[i]);
            for (int v : reachable) {
                valueMap.computeIfAbsent(v, k -> new ArrayList<>()).add(i);
            }
        }
        HashSet<Long> seenPairs = new HashSet<>();
        long ans = 0;
        for (List<Integer> list : valueMap.values()) {
            int m = list.size();
            for (int a = 0; a < m; a++) {
                int i = list.get(a);
                for (int b = a + 1; b < m; b++) {
                    int j = list.get(b);
                    long code = (long) i * n + j;
                    if (seenPairs.add(code)) {
                        ans++;
                    }
                }
            }
        }
        return ans;
    }
}

import java.util.*;

public class Solution {
    private static long modPow(long base, long exp, long mod) {
        long result = 1 % mod;
        long b = base % mod;
        while (exp > 0) {
            if ((exp & 1L) == 1L) {
                result = (result * b) % mod;
            }
            b = (b * b) % mod;
            exp >>= 1;
        }
        return result;
    }

    public static int[] finalArrayState(int[] nums, long k, int multiplier) {
        final long MOD = 1_000_000_007L;
        int n = nums.length;
        if (k == 0 || multiplier == 1) {
            int[] res = new int[n];
            for (int i = 0; i < n; i++) {
                long v = nums[i] % MOD;
                if (v < 0) v += MOD;
                res[i] = (int) v;
            }
            return res;
        }
        if (multiplier == 0) {
            int minIdx = 0;
            for (int i = 1; i < n; i++) {
                if (nums[i] < nums[minIdx]) minIdx = i;
            }
            int[] res = new int[n];
            for (int i = 0; i < n; i++) {
                long v = (i == minIdx) ? 0 : nums[i];
                v %= MOD;
                if (v < 0) v += MOD;
                res[i] = (int) v;
            }
            return res;
        }

        long[] cnt = new long[n];
        double logM = Math.log((double) multiplier);
        double[] logAbs = new double[n];
        for (int i = 0; i < n; i++) {
            if (nums[i] == 0) {
                logAbs[i] = Double.NEGATIVE_INFINITY;
            } else {
                logAbs[i] = Math.log(Math.abs((long) nums[i]));
            }
        }

        int[] heapIdx = new int[n];
        double[] heapKey = new double[n];
        for (int i = 0; i < n; i++) {
            heapIdx[i] = i;
            heapKey[i] = (nums[i] < 0) ? -logAbs[i] : logAbs[i];
        }
        for (int i = (n >> 1) - 1; i >= 0; i--) {
            heapifyDown(i, heapIdx, heapKey, cnt, logAbs, logM);
        }

        for (long step = 0; step < k; step++) {
            int idx = heapIdx[0];
            cnt[idx]++;
            double newKey;
            if (nums[idx] == 0) {
                newKey = Double.NEGATIVE_INFINITY;
            } else {
                double magnitude = logAbs[idx] + cnt[idx] * logM;
                newKey = (nums[idx] < 0) ? -magnitude : magnitude;
            }
            heapKey[0] = newKey;
            heapifyDown(0, heapIdx, heapKey, cnt, logAbs, logM);
        }

        int[] result = new int[n];
        for (int i = 0; i < n; i++) {
            long base = nums[i] % MOD;
            if (base < 0) base += MOD;
            long mult = modPow(multiplier, cnt[i], MOD);
            long val = (base * mult) % MOD;
            result[i] = (int) val;
        }
        return result;
    }

    private static void heapifyDown(int pos, int[] heapIdx, double[] heapKey, long[] cnt,
                                    double[] logAbs, double logM) {
        int n = heapIdx.length;
        final double EPS = 1e-12;
        while (true) {
            int left = (pos << 1) + 1;
            int right = left + 1;
            int smallest = pos;
            if (left < n && less(heapKey[left], heapIdx[left], heapKey[smallest], heapIdx[smallest], EPS)) {
                smallest = left;
            }
            if (right < n && less(heapKey[right], heapIdx[right], heapKey[smallest], heapIdx[smallest], EPS)) {
                smallest = right;
            }
            if (smallest == pos) break;
            swap(pos, smallest, heapIdx, heapKey);
            pos = smallest;
        }
    }

    private static boolean less(double keyA, int idxA, double keyB, int idxB, double eps) {
        if (keyA < keyB - eps) return true;
        if (keyA > keyB + eps) return false;
        return idxA < idxB;
    }

    private static void swap(int i, int j, int[] heapIdx, double[] heapKey) {
        int tmpIdx = heapIdx[i];
        heapIdx[i] = heapIdx[j];
        heapIdx[j] = tmpIdx;
        double tmpKey = heapKey[i];
        heapKey[i] = heapKey[j];
        heapKey[j] = tmpKey;
    }
}

public class Solution {
