import java.util.*;

class Solution {
    private static class MaxHeap {
        private long[] heap;
        private int size;

        MaxHeap(int capacity) {
            heap = new long[capacity];
            size = 0;
        }

        private void swap(int i, int j) {
            long t = heap[i];
            heap[i] = heap[j];
            heap[j] = t;
        }

        private void bubbleUp(int idx) {
            int i = idx;
            while (i > 0) {
                int p = (i - 1) >> 1;
                if (heap[p] >= heap[i]) break;
                swap(p, i);
                i = p;
            }
        }

        private void bubbleDown(int idx) {
            int i = idx;
            while (true) {
                int largest = i;
                int l = i * 2 + 1;
                int r = i * 2 + 2;
                if (l < size && heap[l] > heap[largest]) largest = l;
                if (r < size && heap[r] > heap[largest]) largest = r;
                if (largest == i) break;
                swap(i, largest);
                i = largest;
            }
        }

        void push(long val) {
            if (size == heap.length) {
                heap = Arrays.copyOf(heap, heap.length * 2 + 1);
            }
            heap[size] = val;
            bubbleUp(size);
            size++;
        }

        long popMax() {
            long max = heap[0];
            long end = heap[--size];
            if (size > 0) {
                heap[0] = end;
                bubbleDown(0);
            }
            return max;
        }

        long peek() {
            return heap[0];
        }

        int size() {
            return size;
        }
    }

    public static List<Integer> kthNearestObstacle(List<int[]> queries, int k) {
        List<Integer> results = new ArrayList<>(queries.size());
        if (k <= 0) {
            for (int i = 0; i < queries.size(); i++) results.add(-1);
            return results;
        }
        MaxHeap heap = new MaxHeap(k);
        for (int[] p : queries) {
            long dist = Math.abs((long) p[0]) + Math.abs((long) p[1]);
            if (heap.size() < k) {
                heap.push(dist);
            } else if (dist < heap.peek()) {
                heap.popMax();
                heap.push(dist);
            }
            results.add(heap.size() == k ? (int) heap.peek() : -1);
        }
        return results;
    }
}

class Solution {
    public static String hashDividedString(String s, int k) {
        int n = s.length();
        char[] chars = s.toCharArray();
        StringBuilder sb = new StringBuilder(n / k);
        for (int i = 0; i < n; i += k) {
            int sum = 0;
            for (int j = i; j < i + k; j++) {
                sum += chars[j] - 'a';
            }
            sb.append((char) ((sum % 26) + 'a'));
        }
        return sb.toString();
    }
}

import java.util.*;

public class Solution {
    public static int maxScore(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        if (cols > rows) {
            int[][] trans = new int[cols][rows];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    trans[j][i] = grid[i][j];
                }
            }
            grid = trans;
            int tmp = rows;
            rows = cols;
            cols = tmp;
        }
        int maxMask = 1 << cols;
        int NEG = Integer.MIN_VALUE / 2;
        int[] dp = new int[maxMask];
        Arrays.fill(dp, NEG);
        dp[0] = 0;
        for (int i = 0; i < rows; i++) {
            for (int mask = maxMask - 1; mask >= 0; mask--) {
                if (dp[mask] == NEG) continue;
                for (int j = 0; j < cols; j++) {
                    if ((mask & (1 << j)) == 0) {
                        int nmask = mask | (1 << j);
                        int val = dp[mask] + grid[i][j];
                        if (val > dp[nmask]) dp[nmask] = val;
                    }
                }
            }
        }
        int ans = 0;
        for (int mask = 1; mask < maxMask; mask++) {
            if (dp[mask] > ans) ans = dp[mask];
        }
        return ans;
    }
}

class Solution {
    public static long[] maximumSubarrayXor(int[] nums, int[][] queries) {
        int n = nums.length;
        long[][] score = new long[n][n];
        long[][] best = new long[n][n];
        for (int i = 0; i < n; i++) { score[i][i] = nums[i]; best[i][i] = nums[i]; }
        for (int len = 2; len <= n; len++) {
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1;
                score[i][j] = score[i][j-1] ^ score[i+1][j];
                best[i][j] = Math.max(score[i][j], Math.max(best[i][j-1], best[i+1][j]));
            }
        }
        long[] result = new long[queries.length];
        for (int k = 0; k < queries.length; k++) result[k] = best[queries[k][0]][queries[k][1]];
        return result;
    }
}

import java.math.BigInteger;

class Solution {
    private static BigInteger[] fact;
    private static int N, K;
    private static BigInteger answer;
    private static int[] cnt = new int[10];

    private static BigInteger validOriginalPerms(int[] cnt) {
        BigInteger total = fact[N];
        for (int c = 0; c < 10; c++) total = total.divide(fact[cnt[c]]);
        if (cnt[0] == 0) return total;
        BigInteger leading = fact[N - 1];
        leading = leading.divide(fact[cnt[0] - 1]);
        for (int d = 1; d < 10; d++) leading = leading.divide(fact[cnt[d]]);
        return total.subtract(leading);
    }

    private static boolean backtrack(int pos, int halfLen, int[] half, int[] used, int[] halfCounts, int oddDigit) {
        if (pos == halfLen) {
            StringBuilder left = new StringBuilder();
            for (int i = 0; i < halfLen; i++) left.append((char) ('0' + half[i]));
            StringBuilder pal = new StringBuilder(left);
            if (N % 2 != 0) pal.append((char) ('0' + oddDigit));
            pal.append(left.reverse());
            if (pal.charAt(0) == '0') return false;
            long val = 0;
            for (int i = 0; i < pal.length(); i++) val = (val * 10 + (pal.charAt(i) - '0')) % K;
            return val == 0;
        }
        for (int d = 0; d < 10; d++) {
            if (halfCounts[d] - used[d] > 0) {
                used[d]++;
                half[pos] = d;
                if (backtrack(pos + 1, halfLen, half, used, halfCounts, oddDigit)) return true;
                used[d]--;
            }
        }
        return false;
    }

    private static void dfs(int digit, int remaining) {
        if (digit == 9) {
            cnt[digit] = remaining;
            int oddCnt = 0, oddDigit = -1;
            for (int i = 0; i < 10; i++) if (cnt[i] % 2 == 1) { oddCnt++; oddDigit = i; }
            if ((N % 2 == 0 && oddCnt != 0) || (N % 2 == 1 && oddCnt != 1)) return;
            int halfLen = N / 2;
            int[] halfCounts = new int[10];
            for (int i = 0; i < 10; i++) halfCounts[i] = cnt[i] / 2;
            int[] half = new int[halfLen];
            int[] used = new int[10];
            if (backtrack(0, halfLen, half, used, halfCounts, oddDigit)) {
                answer = answer.add(validOriginalPerms(cnt));
            }
            return;
        }
        for (int c = 0; c <= remaining; c++) { cnt[digit] = c; dfs(digit + 1, remaining - c); }
    }

    public static BigInteger countGoodIntegers(int n, int k) {
        N = n; K = k; answer = BigInteger.ZERO;
        fact = new BigInteger[n + 1];
        fact[0] = BigInteger.ONE;
        for (int i = 1; i <= n; i++) fact[i] = fact[i - 1].multiply(BigInteger.valueOf(i));
        dfs(0, n);
        return answer;
    }
}

import java.util.*;

class Solution {
    public static int maxMoves(int kx, int ky, List<List<Integer>> positions) {
        final int N = 50;
        int p = positions.size();
        List<int[]> nodes = new ArrayList<>(p + 1);
        nodes.add(new int[]{kx, ky});
        for (List<Integer> pos : positions) {
            nodes.add(new int[]{pos.get(0), pos.get(1)});
        }
        int m = p + 1;
        int[][] dist = new int[m][m];
        int[] dx = {2, 2, 1, 1, -1, -1, -2, -2};
        int[] dy = {1, -1, 2, -2, 2, -2, 1, -1};
        for (int s = 0; s < m; ++s) {
            int[][] d = new int[N][N];
            for (int i = 0; i < N; ++i) Arrays.fill(d[i], -1);
            ArrayDeque<int[]> q = new ArrayDeque<>();
            int sx = nodes.get(s)[0];
            int sy = nodes.get(s)[1];
            d[sx][sy] = 0;
            q.offer(new int[]{sx, sy});
            while (!q.isEmpty()) {
                int[] cur = q.poll();
                int x = cur[0];
                int y = cur[1];
                int curDist = d[x][y];
                for (int dir = 0; dir < 8; ++dir) {
                    int nx = x + dx[dir];
                    int ny = y + dy[dir];
                    if (nx < 0 || ny < 0 || nx >= N || ny >= N) continue;
                    if (d[nx][ny] == -1) {
                        d[nx][ny] = curDist + 1;
                        q.offer(new int[]{nx, ny});
                    }
                }
            }
            for (int t = 0; t < m; ++t) {
                int tx = nodes.get(t)[0];
                int ty = nodes.get(t)[1];
                dist[s][t] = d[tx][ty];
            }
        }
        int fullMask = (1 << p) - 1;
        int[][] dp = new int[1 << p][m];
        for (int[] row : dp) Arrays.fill(row, Integer.MIN_VALUE);
        return dfs(0, 0, dist, dp, fullMask, p);
    }

    private static int dfs(int mask, int cur, int[][] dist, int[][] dp, int fullMask, int p) {
        if (mask == fullMask) return 0;
        if (dp[mask][cur] != Integer.MIN_VALUE) return dp[mask][cur];
        boolean aliceTurn = (Integer.bitCount(mask) % 2 == 0);
        int best = aliceTurn ? Integer.MIN_VALUE : Integer.MAX_VALUE;
        int m = dist.length;
        for (int nxt = 1; nxt < m; ++nxt) {
            int bit = 1 << (nxt - 1);
            if ((mask & bit) != 0) continue;
            int cost = dist[cur][nxt];
            int total = cost + dfs(mask | bit, nxt, dist, dp, fullMask, p);
            if (aliceTurn) {
                if (total > best) best = total;
            } else {
                if (total < best) best = total;
            }
        }
        dp[mask][cur] = best;
        return best;
    }
}

class Solution {
    public int countOfPairs(int[] nums) {
        final int MOD = 1_000_000_007;
        int n = nums.length;
        int m = 0;
        for (int x : nums) m = Math.max(m, x);
        // f[i][j] = number of valid (arr1,arr2) prefixes for indices [0..i] with arr1[i] = j
        int[][] f = new int[n][m + 1];
        for (int j = 0; j <= nums[0]; j++) f[0][j] = 1;
        for (int i = 1; i < n; i++) {
            long[] s = new long[m + 1]; // prefix sum of f[i-1]
            s[0] = f[i - 1][0];
            for (int t = 1; t <= m; t++) s[t] = s[t - 1] + f[i - 1][t];
            for (int j = 0; j <= nums[i]; j++) {
                // arr1 non-decreasing needs prev <= j; arr2 non-increasing needs
                // nums[i]-j <= nums[i-1]-prev, i.e. prev <= j + nums[i-1] - nums[i]
                int k = Math.min(j, j + nums[i - 1] - nums[i]);
                if (k >= 0) f[i][j] = (int) (s[k] % MOD);
            }
        }
        long ans = 0;
        for (int j = 0; j <= nums[n - 1]; j++) ans += f[n - 1][j];
        return (int) (ans % MOD);
    }
}

import java.util.Arrays;

class Solution {
    public static int maxScore(int[] start, int d) {
        int n = start.length;
        Arrays.sort(start);
        long minL = start[0];
        long maxR = (long) start[n - 1] + d;
        long lo = 0;
        long hi = maxR - minL + 1;
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            if (feasible(start, d, mid)) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return (int) (lo - 1);
    }

    private static boolean feasible(int[] start, int d, long dist) {
        long prev = start[0];
        for (int i = 1; i < start.length; i++) {
            long need = prev + dist;
            long left = start[i];
            long right = (long) start[i] + d;
            long pos = left > need ? left : need;
            if (pos > right) {
                return false;
            }
            prev = pos;
        }
        return true;
    }
}

