import java.util.*;

class Solution {
    public static long maxScore(int[] nums) {
        int n = nums.length;
        if (n == 0) return 0;
        long[] dp = new long[n];
        dp[0] = 0;
        LiChaoTree cht = new LiChaoTree(0, n - 1);
        cht.addLine(nums[0], dp[0]);
        for (int i = 1; i < n; i++) {
            dp[i] = cht.query(i);
            cht.addLine(nums[i], dp[i] - (long) i * nums[i]);
        }
        return dp[n - 1];
    }

    private static class Line {
        long m, b;
        Line(long m, long b) { this.m = m; this.b = b; }
        long eval(long x) { return m * x + b; }
    }

    private static class Node {
        long l, r;
        Line line;
        Node left, right;
        Node(long l, long r) {
            this.l = l;
            this.r = r;
            this.line = new Line(0, Long.MIN_VALUE);
        }
    }

    private static class LiChaoTree {
        private final Node root;
        LiChaoTree(long minX, long maxX) { root = new Node(minX, maxX); }
        void addLine(long m, long b) { addLine(new Line(m, b), root); }
        private void addLine(Line newLine, Node node) {
            long l = node.l, r = node.r;
            long mid = (l + r) >> 1;
            boolean leftBetter = newLine.eval(l) > node.line.eval(l);
            boolean midBetter = newLine.eval(mid) > node.line.eval(mid);
            if (midBetter) {
                Line tmp = node.line;
                node.line = newLine;
                newLine = tmp;
            }
            if (l == r) return;
            if (leftBetter != midBetter) {
                if (node.left == null) node.left = new Node(l, mid);
                addLine(newLine, node.left);
            } else {
                if (node.right == null) node.right = new Node(mid + 1, r);
                addLine(newLine, node.right);
            }
        }
        long query(long x) { return query(x, root); }
        private long query(long x, Node node) {
            if (node == null) return Long.MIN_VALUE;
            long res = node.line.eval(x);
            if (node.l == node.r) return res;
            long mid = (node.l + node.r) >> 1;
            if (x <= mid) return Math.max(res, query(x, node.left));
            else return Math.max(res, query(x, node.right));
        }
    }
}

class Solution {
    public int maxValue(int[] nums, int k) {
        int m = 1 << 7;
        int n = nums.length;
        boolean[][][] f = new boolean[n + 1][k + 2][m];
        f[0][0][0] = true;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= k; j++) {
                for (int x = 0; x < m; x++) {
                    if (f[i][j][x]) {
                        f[i + 1][j][x] = true;
                        f[i + 1][j + 1][x | nums[i]] = true;
                    }
                }
            }
        }
        boolean[][][] g = new boolean[n + 1][k + 2][m];
        g[n][0][0] = true;
        for (int i = n; i > 0; i--) {
            for (int j = 0; j <= k; j++) {
                for (int y = 0; y < m; y++) {
                    if (g[i][j][y]) {
                        g[i - 1][j][y] = true;
                        g[i - 1][j + 1][y | nums[i - 1]] = true;
                    }
                }
            }
        }
        int ans = 0;
        for (int i = k; i <= n - k; i++) {
            for (int x = 0; x < m; x++) {
                if (f[i][k][x]) {
                    for (int y = 0; y < m; y++) {
                        if (g[i][k][y]) ans = Math.max(ans, x ^ y);
                    }
                }
            }
        }
        return ans;
    }
}

