import java.util.*;

class Solution {
    private static class Point {
        int x, y, idx, pos;
        Point(int x, int y, int idx) {
            this.x = x;
            this.y = y;
            this.idx = idx;
        }
    }

    private static class BIT {
        int[] tree;
        BIT(int n) {
            tree = new int[n + 2];
        }
        void update(int i, int val) {
            for (int n = tree.length; i < n; i += i & -i) {
                if (val > tree[i]) tree[i] = val;
            }
        }
        int query(int i) {
            int res = 0;
            for (; i > 0; i -= i & -i) {
                if (tree[i] > res) res = tree[i];
            }
            return res;
        }
    }

    public static int longestIncreasingPath(int[][] coordinates, int k) {
        int n = coordinates.length;
        Point[] points = new Point[n];
        for (int i = 0; i < n; i++) {
            points[i] = new Point(coordinates[i][0], coordinates[i][1], i);
        }
        // compress y
        int[] ys = new int[n];
        for (int i = 0; i < n; i++) ys[i] = points[i].y;
        Arrays.sort(ys);
        int m = 0;
        Map<Integer, Integer> yMap = new HashMap<>();
        for (int v : ys) {
            if (!yMap.containsKey(v)) {
                yMap.put(v, ++m);
            }
        }
        // sort by x asc, y asc
        Arrays.sort(points, (a, b) -> {
            if (a.x != b.x) return Integer.compare(a.x, b.x);
            return Integer.compare(a.y, b.y);
        });
        for (int i = 0; i < n; i++) points[i].pos = i;
        int targetPos = -1;
        for (int i = 0; i < n; i++) {
            if (points[i].idx == k) {
                targetPos = i;
                break;
            }
        }
        int[] forward = new int[n];
        BIT bit = new BIT(m);
        for (int i = 0; i < n; ) {
            int j = i;
            while (j < n && points[j].x == points[i].x) j++;
            for (int p = i; p < j; p++) {
                int yIdx = yMap.get(points[p].y);
                int best = bit.query(yIdx - 1);
                forward[p] = best + 1;
            }
            for (int p = i; p < j; p++) {
                int yIdx = yMap.get(points[p].y);
                bit.update(yIdx, forward[p]);
            }
            i = j;
        }
        int[] backward = new int[n];
        BIT bit2 = new BIT(m);
        for (int i = n - 1; i >= 0; ) {
            int j = i;
            while (j >= 0 && points[j].x == points[i].x) j--;
            for (int p = i; p > j; p--) {
                int yIdx = yMap.get(points[p].y);
                int revIdx = m - yIdx + 1;
                int best = bit2.query(revIdx - 1);
                backward[p] = best + 1;
            }
            for (int p = i; p > j; p--) {
                int yIdx = yMap.get(points[p].y);
                int revIdx = m - yIdx + 1;
                bit2.update(revIdx, backward[p]);
            }
            i = j;
        }
        return forward[targetPos] + backward[targetPos] - 1;
    }
}

import java.util.ArrayDeque;
import java.util.Arrays;

class Solution {
    public static boolean canReachSafe(int[][] grid, int health) {
        int m = grid.length;
        int n = grid[0].length;
        int[][] dist = new int[m][n];
        for (int i = 0; i < m; i++) {
            Arrays.fill(dist[i], Integer.MAX_VALUE);
        }
        dist[0][0] = grid[0][0];
        if (dist[0][0] > health - 1) {
            return false;
        }
        ArrayDeque<int[]> dq = new ArrayDeque<>();
        dq.offerFirst(new int[]{0, 0});
        int[] dx = {1, -1, 0, 0};
        int[] dy = {0, 0, 1, -1};
        while (!dq.isEmpty()) {
            int[] cur = dq.pollFirst();
            int x = cur[0];
            int y = cur[1];
            if (x == m - 1 && y == n - 1) {
                return dist[x][y] <= health - 1;
            }
            for (int k = 0; k < 4; k++) {
                int nx = x + dx[k];
                int ny = y + dy[k];
                if (nx < 0 || ny < 0 || nx >= m || ny >= n) {
                    continue;
                }
                int newCost = dist[x][y] + grid[nx][ny];
                if (newCost < dist[nx][ny] && newCost <= health - 1) {
                    dist[nx][ny] = newCost;
                    if (grid[nx][ny] == 0) {
                        dq.offerFirst(new int[]{nx, ny});
                    } else {
                        dq.offerLast(new int[]{nx, ny});
                    }
                }
            }
        }
        return false;
    }
}

class Solution {
    public static long maxMultiplicationScore(long[] a, long[] b) {
        long dp0 = 0L, dp1 = Long.MIN_VALUE, dp2 = Long.MIN_VALUE, dp3 = Long.MIN_VALUE, dp4 = Long.MIN_VALUE;
        long a0 = a[0], a1 = a[1], a2 = a[2], a3 = a[3];
        for (long x : b) {
            if (dp3 != Long.MIN_VALUE) {
                long cand = dp3 + a3 * x;
                if (cand > dp4) dp4 = cand;
            }
            if (dp2 != Long.MIN_VALUE) {
                long cand = dp2 + a2 * x;
                if (cand > dp3) dp3 = cand;
            }
            if (dp1 != Long.MIN_VALUE) {
                long cand = dp1 + a1 * x;
                if (cand > dp2) dp2 = cand;
            }
            if (dp0 != Long.MIN_VALUE) {
                long cand = dp0 + a0 * x;
                if (cand > dp1) dp1 = cand;
            }
        }
        return dp4;
    }
}

import java.util.*;

public class Solution {
    public static long minimumSeconds(int mountainHeight, int[] workerTimes) {
        long H = mountainHeight;
        long minT = Long.MAX_VALUE;
        for (int t : workerTimes) {
            if (t < minT) minT = t;
        }
        long low = 0;
        long high = minT * H * (H + 1) / 2; // fastest worker does all work
        while (low < high) {
            long mid = (low + high) >>> 1;
            long total = 0;
            for (int t : workerTimes) {
                long val = (2L * mid) / t; // 2*mid / t_i
                // solve k^2 + k - val <= 0
                long disc = 1L + 4L * val;
                long sqrt = (long) Math.sqrt(disc);
                while ((sqrt + 1) * (sqrt + 1) <= disc) sqrt++;
                while (sqrt * sqrt > disc) sqrt--;
                long k = (sqrt - 1) / 2;
                total += k;
                if (total >= H) break;
            }
            if (total >= H) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}

import java.util.*;

class Solution {
    static class Node {
        int[] child = new int[26];
        boolean isWord = false;
        Node() {
            Arrays.fill(child, -1);
        }
    }

    public static int minValidStrings(List<String> words, String target) {
        List<Node> nodes = new ArrayList<>();
        nodes.add(new Node());
        for (String w : words) {
            int len = w.length();
            for (int start = 0; start < len; start++) {
                int cur = 0;
                for (int pos = start; pos < len; pos++) {
                    int idx = w.charAt(pos) - 'a';
                    if (nodes.get(cur).child[idx] == -1) {
                        nodes.add(new Node());
                        nodes.get(cur).child[idx] = nodes.size() - 1;
                    }
                    cur = nodes.get(cur).child[idx];
                    nodes.get(cur).isWord = true;
                }
            }
        }

        int n = target.length();
        int INF = n + 1;
        int[] dp = new int[n + 1];
        Arrays.fill(dp, INF);
        dp[n] = 0;

        for (int i = n - 1; i >= 0; --i) {
            int cur = 0;
            for (int j = i; j < n; ++j) {
                int idx = target.charAt(j) - 'a';
                int next = nodes.get(cur).child[idx];
                if (next == -1) break;
                cur = next;
                if (nodes.get(cur).isWord) {
                    dp[i] = Math.min(dp[i], 1 + dp[j + 1]);
                }
            }
        }

        return dp[0] == INF ? -1 : dp[0];
    }
}

