    public static int minValidStrings(List<String> words, String target) {
        List<Node> nodes = new ArrayList<>();
        nodes.add(new Node());
        int maxLen = 0;
        for (String w : words) {
            int cur = 0;
            maxLen = Math.max(maxLen, w.length());
            for (char ch : w.toCharArray()) {
                int idx = ch - 'a';
                if (nodes.get(cur).next[idx] == -1) {
                    nodes.add(new Node());
                    nodes.get(cur).next[idx] = nodes.size() - 1;
                }
                cur = nodes.get(cur).next[idx];
            }
        }

        int n = target.length();
        int INF = Integer.MAX_VALUE / 2;
        int[] dp = new int[n + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;

        for (int i = 0; i < n; ++i) {
            if (dp[i] == INF) continue;
            int cur = 0;
            for (int j = i; j < n && j - i < maxLen; ++j) {
                int idx = target.charAt(j) - 'a';
                cur = nodes.get(cur).next[idx];
                if (cur == -1) break;
                if (dp[j + 1] > dp[i] + 1) {
                    dp[j + 1] = dp[i] + 1;
                }
            }
        }

        return dp[n] == INF ? -1 : dp[n];
    }
}

