public class Solution {
    public static long minElementAfterDigitSum(List<Long> nums) {
        long min = Long.MAX_VALUE;
        for (long x : nums) {
            long sum = 0;
            long t = x;
            while (t > 0) {
                sum += t % 10;
                t /= 10;
            }
            if (sum < min) {
                min = sum;
            }
        }
        return min;
    }
}

public class Solution {
    public static long countSubstrings(String word1, String word2) {
        int n = word1.length();
        int m = word2.length();
        if (m == 0) {
            return (long) n * (n + 1) / 2;
        }
        if (m > n) return 0L;
        int[] need = new int[26];
        int[] have = new int[26];
        for (int i = 0; i < m; ++i) {
            need[word2.charAt(i) - 'a']++;
        }
        int missing = 0;
        for (int v : need) missing += v;
        long ans = 0L;
        int R = 0;
        for (int L = 0; L < n; ++L) {
            while (R < n && missing > 0) {
                int idx = word1.charAt(R) - 'a';
                if (have[idx] < need[idx]) missing--;
                have[idx]++;
                ++R;
            }
            if (missing == 0) {
                ans += (long) (n - (R - 1));
            } else {
                break;
            }
            int idxL = word1.charAt(L) - 'a';
            if (have[idxL] <= need[idxL]) missing++;
            have[idxL]--;
        }
        return ans;
    }
}

