class Solution {
    private static class State {
        boolean reachable = false;
        List<Integer> seq = new ArrayList<>();
    }

    public static List<Integer> getLexicographicallySmallestValidSequence(String word1, String word2) {
        int n = word1.length();
        int m = word2.length();
        if (m == 0) return new ArrayList<>();
        State[][] dp = new State[m + 1][2];
        for (int i = 0; i <= m; i++) {
            for (int e = 0; e < 2; e++) {
                dp[i][e] = new State();
            }
        }
        dp[0][0].reachable = true;
        for (int idx = 0; idx < n; idx++) {
            for (int i = m - 1; i >= 0; i--) {
                for (int err = 0; err <= 1; err++) {
                    State cur = dp[i][err];
                    if (!cur.reachable) continue;
                    int lastPos = cur.seq.isEmpty() ? -1 : cur.seq.get(cur.seq.size() - 1);
                    if (lastPos >= idx) continue;
                    int newErr = err + (word1.charAt(idx) != word2.charAt(i) ? 1 : 0);
                    if (newErr > 1) continue;
                    List<Integer> cand = new ArrayList<>(cur.seq);
                    cand.add(idx);
                    State nxt = dp[i + 1][newErr];
                    if (!nxt.reachable || lexicographicallyLess(cand, nxt.seq)) {
                        nxt.reachable = true;
                        nxt.seq = cand;
                    }
                }
            }
        }
        List<Integer> best = null;
        boolean found = false;
        for (int err = 0; err <= 1; err++) {
            State st = dp[m][err];
            if (!st.reachable) continue;
            if (!found || lexicographicallyLess(st.seq, best)) {
                best = st.seq;
                found = true;
            }
        }
        return found ? best : new ArrayList<>();
    }

    private static boolean lexicographicallyLess(List<Integer> a, List<Integer> b) {
        int len = Math.min(a.size(), b.size());
        for (int i = 0; i < len; i++) {
            int av = a.get(i);
            int bv = b.get(i);
            if (av != bv) return av < bv;
        }
        return a.size() < b.size();
    }
}

