class Solution {
    public static long countSubstrings(String word1, String word2) {
        int n = word1.length();
        int m = word2.length();
        if (m == 0) return (long) n * (n + 1) / 2;
        if (m > n) return 0L;
        int[] need = new int[26];
        for (int i = 0; i < m; i++) need[word2.charAt(i) - 'a']++;
        int[] diff = new int[26];
        int deficit = 0;
        for (int i = 0; i < 26; i++) {
            diff[i] = -need[i];
            if (need[i] > 0) deficit++;
        }
        long ans = 0;
        int r = 0;
        char[] s = word1.toCharArray();
        for (int l = 0; l < n; l++) {
            while (r < n && deficit > 0) {
                int idx = s[r] - 'a';
                diff[idx]++;
                if (diff[idx] == 0) deficit--;
                r++;
            }
            if (deficit > 0) break;
            ans += (long) (n - r + 1);
            int idxL = s[l] - 'a';
            diff[idxL]--;
            if (diff[idxL] == -1) deficit++;
        }
        return ans;
    }
}

