class Solution {
    public static int findFirstAlmostEqual(String s, String pattern) {
        int n = s.length();
        int m = pattern.length();
        if (m > n) return -1;
        char[] sArr = s.toCharArray();
        char[] pArr = pattern.toCharArray();

        int[] zForward = computeZ(concat(pArr, (char) '#', sArr));
        char[] revP = reverse(pArr);
        char[] revS = reverse(sArr);
        int[] zReverse = computeZ(concat(revP, (char) '#', revS));

        for (int i = 0; i <= n - m; ++i) {
            int prefix = zForward[m + 1 + i];
            if (prefix >= m) return i;
            int revIndex = n - (i + m);
            int suffix = zReverse[m + 1 + revIndex];
            if (prefix + suffix >= m - 1) return i;
        }
        return -1;
    }

    private static int[] computeZ(char[] str) {
        int len = str.length;
        int[] z = new int[len];
        int l = 0, r = 0;
        for (int i = 1; i < len; ++i) {
            if (i <= r) {
                z[i] = Math.min(r - i + 1, z[i - l]);
            }
            while (i + z[i] < len && str[z[i]] == str[i + z[i]]) {
                ++z[i];
            }
            if (i + z[i] - 1 > r) {
                l = i;
                r = i + z[i] - 1;
            }
        }
        return z;
    }

    private static char[] concat(char[] a, char sep, char[] b) {
        char[] res = new char[a.length + 1 + b.length];
        System.arraycopy(a, 0, res, 0, a.length);
        res[a.length] = sep;
        System.arraycopy(b, 0, res, a.length + 1, b.length);
        return res;
    }

    private static char[] reverse(char[] arr) {
        char[] rev = new char[arr.length];
        for (int i = 0, j = arr.length - 1; i < arr.length; ++i, --j) {
            rev[i] = arr[j];
        }
        return rev;
    }
}

class Solution {
    public static char kthCharacter(long k) {
        if (k <= 0) return '\0';
        long len = 1;
        while (len < k) len <<= 1;
        int inc = 0;
        while (len > 1) {
            long half = len >> 1;
            if (k > half) {
                k -= half;
                inc = (inc + 1) % 26;
            }
            len = half;
        }
        return (char) ('a' + inc);
    }
}

