class Solution {
    public static long max_total_height(int[] maximum_height) {
        Arrays.sort(maximum_height);
        long prev = Long.MAX_VALUE;
        long total = 0;
        for (int i = maximum_height.length - 1; i >= 0; i--) {
            long cur = maximum_height[i];
            if (prev - 1 < cur) {
                cur = prev - 1;
            }
            if (cur <= 0) {
                return -1;
            }
            total += cur;
            prev = cur;
        }
        return total;
    }
}

class Solution {
    public static char findKthChar(long k, int[] operations) {
        final long INF = 4000000000000000000L;
        long length = 1;
        for (int op : operations) {
            if (length > INF / 2) {
                length = INF;
            } else {
                length <<= 1;
                if (length > INF) {
                    length = INF;
                }
            }
        }
        long pos = k;
        int shift = 0;
        for (int i = operations.length - 1; i >= 0; --i) {
            long prev = (length == INF) ? INF : (length >> 1);
            if (pos > prev) {
                pos -= prev;
                if (operations[i] == 1) {
                    shift = (shift + 1) % 26;
                }
            }
            length = prev;
        }
        return (char) ('a' + shift);
    }
}

