class Solution {
    public static long countVowelConsonantSubstrings(String word, int k) {
        Set<Character> vowelSet = Set.of('a', 'e', 'i', 'o', 'u');
        int n = word.length();
        int[] prefC = new int[n + 1];
        for (int i = 0; i < n; i++) {
            char ch = word.charAt(i);
            prefC[i + 1] = prefC[i] + (vowelSet.contains(ch) ? 0 : 1);
        }
        int[] last = new int[5];
        Arrays.fill(last, -1);
        @SuppressWarnings("unchecked")
        ArrayList<Integer>[] pos = new ArrayList[n + 1];
        pos[0] = new ArrayList<>();
        pos[0].add(0);
        long ans = 0;
        for (int i = 0; i < n; i++) {
            char ch = word.charAt(i);
            if (vowelSet.contains(ch)) {
                switch (ch) {
                    case 'a' -> last[0] = i;
                    case 'e' -> last[1] = i;
                    case 'i' -> last[2] = i;
                    case 'o' -> last[3] = i;
                    case 'u' -> last[4] = i;
                }
            }
            int minLast = Integer.MAX_VALUE;
            for (int v : last) {
                if (v == -1) {
                    minLast = -1;
                    break;
                }
                if (v < minLast) minLast = v;
            }
            if (minLast != -1) {
                int target = prefC[i + 1] - k;
                if (target >= 0 && target <= n) {
                    ArrayList<Integer> list = pos[target];
                    if (list != null) {
                        int cnt = upperBound(list, minLast);
                        ans += cnt;
                    }
                }
            }
            int pc = prefC[i + 1];
            if (pos[pc] == null) pos[pc] = new ArrayList<>();
            pos[pc].add(i + 1);
        }
        return ans;
    }

    private static int upperBound(ArrayList<Integer> list, int value) {
        int lo = 0, hi = list.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (list.get(mid) <= value) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }
}

class Solution {
    private static final int[] VOWEL_MAP = new int[26];
    static {
        for (int i = 0; i < 26; ++i) VOWEL_MAP[i] = -1;
        VOWEL_MAP['a' - 'a'] = 0;
        VOWEL_MAP['e' - 'a'] = 1;
        VOWEL_MAP['i' - 'a'] = 2;
        VOWEL_MAP['o' - 'a'] = 3;
        VOWEL_MAP['u' - 'a'] = 4;
    }

    public static long countVowelConsonantSubstrings(String word, int k) {
        int n = word.length();
        char[] s = word.toCharArray();
        int[] latest = new int[5];
        for (int i = 0; i < 5; ++i) latest[i] = -1;
        int leftAtMostK = 0, leftAtMostKm1 = 0;
        int cntConK = 0, cntConKm1 = 0;
        long ans = 0L;
        for (int r = 0; r < n; ++r) {
            int vIdx = VOWEL_MAP[s[r] - 'a'];
            if (vIdx == -1) {
                ++cntConK;
                ++cntConKm1;
            } else {
                latest[vIdx] = r;
            }
            while (cntConK > k) {
                if (VOWEL_MAP[s[leftAtMostK] - 'a'] == -1) --cntConK;
                ++leftAtMostK;
            }
            if (k > 0) {
                while (cntConKm1 > k - 1) {
                    if (VOWEL_MAP[s[leftAtMostKm1] - 'a'] == -1) --cntConKm1;
                    ++leftAtMostKm1;
                }
            }
            int minPos = n;
            for (int i = 0; i < 5; ++i) {
                if (latest[i] == -1) {
                    minPos = -1;
                    break;
                }
                if (latest[i] < minPos) minPos = latest[i];
            }
            long cntAtMostK = 0L, cntAtMostKm1 = 0L;
            if (minPos >= leftAtMostK) cntAtMostK = (long) (minPos - leftAtMostK + 1);
            if (k > 0 && minPos >= leftAtMostKm1) cntAtMostKm1 = (long) (minPos - leftAtMostKm1 + 1);
            ans += cntAtMostK - cntAtMostKm1;
        }
        return ans;
    }
}

