public class Solution {
    public static int[] removeMethods(int n, int k, int[][] invocations) {
        int[] outDeg = new int[n];
        for (int[] p : invocations) {
            outDeg[p[0]]++;
        }
        int[][] adj = new int[n][];
        for (int i = 0; i < n; i++) {
            adj[i] = new int[outDeg[i]];
        }
        int[] pos = new int[n];
        for (int[] p : invocations) {
            adj[p[0]][pos[p[0]]++] = p[1];
        }

        boolean[] suspicious = new boolean[n];
        int[] stack = new int[n];
        int top = 0;
        stack[top++] = k;
        while (top > 0) {
            int cur = stack[--top];
            if (suspicious[cur]) continue;
            suspicious[cur] = true;
            for (int nxt : adj[cur]) {
                if (!suspicious[nxt]) {
                    stack[top++] = nxt;
                }
            }
        }

        for (int[] p : invocations) {
            if (!suspicious[p[0]] && suspicious[p[1]]) {
                int[] all = new int[n];
                for (int i = 0; i < n; i++) all[i] = i;
                return all;
            }
        }

        int count = 0;
        for (int i = 0; i < n; i++) {
            if (!suspicious[i]) count++;
        }
        int[] result = new int[count];
        int idx = 0;
        for (int i = 0; i < n; i++) {
            if (!suspicious[i]) result[idx++] = i;
        }
        return result;
    }
}

