class Solution {
    public static int[] constructMinimumBitwiseArray(int[] nums) {
        int[] ans = new int[nums.length];
        for (int i = 0; i < nums.length; i++) {
            int p = nums[i];
            if ((p & 1) == 0) {
                ans[i] = -1;
                continue;
            }
            int t = Integer.numberOfTrailingZeros(~p);
            ans[i] = p - (1 << (t - 1));
        }
        return ans;
    }
}

class Solution {
    public static long maxBinaryConcat(int[] nums) {
        int[] bitLen = new int[3];
        for (int i = 0; i < 3; i++) {
            int v = nums[i];
            bitLen[i] = v == 0 ? 1 : 32 - Integer.numberOfLeadingZeros(v);
        }
        long best = 0;
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) if (j != i) {
                for (int k = 0; k < 3; k++) if (k != i && k != j) {
                    long a = nums[i];
                    long b = nums[j];
                    long c = nums[k];
                    int lenB = bitLen[j];
                    int lenC = bitLen[k];
                    long val = ((a << lenB) | b) << lenC | c;
                    if (val > best) best = val;
                }
            }
        }
        return best;
    }
}

