class Solution {
    public static int[][] constructGrid(int n, int[][] edges) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        int[] deg = new int[n];
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
            deg[e[0]]++; deg[e[1]]++;
        }
        int[] degCount = new int[5];
        for (int d : deg) if (d <= 4) degCount[d]++;
        int limit = (int) Math.sqrt(n);
        int H = -1, W = -1;
        for (int h = 1; h <= limit; h++) {
            if (n % h != 0) continue;
            int w = n / h;
            if (h == 1 && w == 1) continue;
            int[] expect = new int[5];
            if (h == 1 || w == 1) { expect[1] = 2; expect[2] = n - 2; }
            else { expect[2] = 4; expect[3] = 2*(h-2)+2*(w-2); expect[4] = (h-2)*(w-2); }
            boolean ok = true;
            for (int d = 0; d <= 4; d++) if (degCount[d] != expect[d]) { ok = false; break; }
            if (ok) { H = h; W = w; break; }
        }
        if (H == -1) throw new RuntimeException("Input graph is not a rectangular grid");

        int[][] grid = new int[H][W];
        for (int[] row : grid) Arrays.fill(row, -1);
        boolean[] placed = new boolean[n];

        if (H == 1 || W == 1) {
            int start = -1;
            for (int i = 0; i < n; i++) if (deg[i] == 1) { start = i; break; }
            List<Integer> path = new ArrayList<>();
            path.add(start); placed[start] = true;
            int cur = start;
            while (path.size() < n) {
                int nxt = -1;
                for (int x : adj.get(cur)) if (!placed[x]) { nxt = x; break; }
                path.add(nxt); placed[nxt] = true; cur = nxt;
            }
            if (H == 1) {
                int[][] res = new int[1][n];
                for (int i = 0; i < n; i++) res[0][i] = path.get(i);
                return res;
            } else {
                int[][] res = new int[n][1];
                for (int i = 0; i < n; i++) res[i][0] = path.get(i);
                return res;
            }
        }

        int corner = -1;
        for (int i = 0; i < n; i++) if (deg[i] == 2) { corner = i; break; }
        grid[0][0] = corner; placed[corner] = true;
        int X = adj.get(corner).get(0), Y = adj.get(corner).get(1);
        grid[0][1] = X; placed[X] = true;
        grid[1][0] = Y; placed[Y] = true;

        for (int d = 2; d <= H + W - 2; d++) {
            for (int i = Math.max(1, d - W + 1); i <= Math.min(d, H - 1); i++) {
                int j = d - i;
                if (j < 1 || j > W - 1) continue;
                int a = grid[i-1][j], b = grid[i][j-1], exclude = grid[i-1][j-1];
                Set<Integer> sa = new HashSet<>(adj.get(a));
                int val = -1;
                for (int x : adj.get(b)) if (x != exclude && sa.contains(x)) { val = x; break; }
                grid[i][j] = val; placed[val] = true;
            }
            if (d <= W - 1) {
                int a = grid[0][d-1];
                int val = -1;
                for (int x : adj.get(a)) if (!placed[x]) { val = x; break; }
                grid[0][d] = val; placed[val] = true;
            }
            if (d <= H - 1) {
                int a = grid[d-1][0];
                int val = -1;
                for (int x : adj.get(a)) if (!placed[x]) { val = x; break; }
                grid[d][0] = val; placed[val] = true;
            }
        }
        return grid;
    }
}

