class Solution {
    public static List<Long> xSumAllKLongSubarrays(int[] nums, int k, int x) {
        int n = nums.length;
        List<Long> result = new ArrayList<>();
        if (k > n) return result;
        Map<Integer, Integer> freqMap = new HashMap<>();
        TreeSet<Entry> set = new TreeSet<>((a, b) -> {
            if (a.freq != b.freq) return Integer.compare(b.freq, a.freq);
            return Integer.compare(b.val, a.val);
        });
        for (int i = 0; i < k; i++) {
            int v = nums[i];
            int old = freqMap.getOrDefault(v, 0);
            if (old > 0) set.remove(new Entry(v, old));
            int nw = old + 1;
            freqMap.put(v, nw);
            set.add(new Entry(v, nw));
        }
        result.add(topSum(set, x));
        for (int i = 1; i <= n - k; i++) {
            int out = nums[i - 1];
            int in = nums[i + k - 1];
            int oldOut = freqMap.get(out);
            set.remove(new Entry(out, oldOut));
            int newOut = oldOut - 1;
            if (newOut == 0) {
                freqMap.remove(out);
            } else {
                freqMap.put(out, newOut);
                set.add(new Entry(out, newOut));
            }
            int oldIn = freqMap.getOrDefault(in, 0);
            if (oldIn > 0) set.remove(new Entry(in, oldIn));
            int newIn = oldIn + 1;
            freqMap.put(in, newIn);
            set.add(new Entry(in, newIn));
            result.add(topSum(set, x));
        }
        return result;
    }

    private static long topSum(TreeSet<Entry> set, int x) {
        long sum = 0L;
        int cnt = 0;
        for (Entry e : set) {
            sum += (long) e.val * e.freq;
            if (++cnt == x) break;
        }
        return sum;
    }

    private static class Entry {
        int val;
        int freq;
        Entry(int v, int f) {
            this.val = v;
            this.freq = f;
        }
    }
}

