    private static class Info {
        boolean isPerfect;
        int height;
        int size;
        Info(boolean isPerfect, int height, int size) {
            this.isPerfect = isPerfect;
            this.height = height;
            this.size = size;
        }
    }

    private static Info dfs(TreeNode node, int k, PriorityQueue<Integer> heap) {
        if (node == null) {
            return new Info(true, -1, 0);
        }
        Info left = dfs(node.left, k, heap);
        Info right = dfs(node.right, k, heap);
        boolean perf = left.isPerfect && right.isPerfect && left.height == right.height;
        int h = Math.max(left.height, right.height) + 1;
        int sz;
        if (perf) {
            sz = left.size + right.size + 1;
            if (k > 0) {
                if (heap.size() < k) {
                    heap.offer(sz);
                } else if (sz > heap.peek()) {
                    heap.poll();
                    heap.offer(sz);
                }
            }
        } else {
            sz = Math.max(left.size, right.size);
        }
        return new Info(perf, h, sz);
    }

    public static int kthLargestPerfectSubtree(TreeNode root, int k) {
        if (k <= 0) return -1;
        PriorityQueue<Integer> heap = new PriorityQueue<>(k);
        dfs(root, k, heap);
        return heap.size() == k ? heap.peek() : -1;
    }
}

import java.util.*;

class Solution {
    public static List<Integer> sortedGCDPairQueries(List<Integer> nums, List<Integer> queries) {
        int maxVal = 0;
        for (int v : nums) {
            if (v > maxVal) maxVal = v;
        }
        if (maxVal == 0) {
            List<Integer> ans = new ArrayList<>(queries.size());
            for (int i = 0; i < queries.size(); i++) ans.add(0);
            return ans;
        }
        int[] freq = new int[maxVal + 1];
        for (int v : nums) {
            freq[v]++;
        }
        int[] cntDiv = new int[maxVal + 1];
        for (int d = 1; d <= maxVal; d++) {
            for (int m = d; m <= maxVal; m += d) {
                cntDiv[d] += freq[m];
            }
        }
        long[] exact = new long[maxVal + 1];
        for (int d = maxVal; d >= 1; d--) {
            long total = (long) cntDiv[d] * (cntDiv[d] - 1) / 2;
            for (int m = d * 2; m <= maxVal; m += d) {
                total -= exact[m];
            }
            exact[d] = total;
        }
        long[] prefix = new long[maxVal + 1];
        for (int d = 1; d <= maxVal; d++) {
            prefix[d] = prefix[d - 1] + exact[d];
        }
        List<Integer> answer = new ArrayList<>(queries.size());
        for (int q : queries) {
            long target = (long) q + 1;
            int lo = 1, hi = maxVal;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (prefix[mid] >= target) {
                    hi = mid;
                } else {
                    lo = mid + 1;
                }
            }
            answer.add(lo);
        }
        return answer;
    }
}

