class Solution {
    public int maximumRemovals(String source, String pattern, int[] targetIndices) {
        int n = source.length();
        int m = pattern.length();
        boolean[] deletable = new boolean[n];
        for (int idx : targetIndices) {
            if (idx >= 0 && idx < n) deletable[idx] = true;
        }
        int totalDel = targetIndices.length;
        int INF = 1_000_000_000;
        int[] prev = new int[m + 1];
        Arrays.fill(prev, INF);
        prev[0] = 0;
        for (int i = 1; i <= n; i++) {
            int[] cur = new int[m + 1];
            Arrays.fill(cur, INF);
            cur[0] = 0;
            char sc = source.charAt(i - 1);
            boolean isDel = deletable[i - 1];
            for (int j = 1; j <= m; j++) {
                // skip current character
                if (prev[j] < cur[j]) cur[j] = prev[j];
                // try to match
                if (sc == pattern.charAt(j - 1)) {
                    int cost = prev[j - 1] + (isDel ? 1 : 0);
                    if (cost < cur[j]) cur[j] = cost;
                }
            }
            prev = cur;
        }
        int minDelUsed = prev[m];
        if (minDelUsed > totalDel) return 0;
        return totalDel - minDelUsed;
    }
}

class Solution {
    private static final int MOD = 1_000_000_007;

    public static int countWinningSequences(String s) {
        int n = s.length();
        int offset = n;
        int range = 2 * n + 1;
        int[] alice = new int[n];
        for (int i = 0; i < n; ++i) {
            char c = s.charAt(i);
            alice[i] = c == 'F' ? 0 : (c == 'W' ? 1 : 2);
        }
        int[][] win = new int[3][3];
        for (int b = 0; b < 3; ++b) {
            for (int a = 0; a < 3; ++a) {
                if (b == a) win[b][a] = 0;
                else if ((b == 0 && a == 2) || (b == 1 && a == 0) || (b == 2 && a == 1))
                    win[b][a] = 1;
                else
                    win[b][a] = -1;
            }
        }
        int[][] dpPrev = new int[4][range];
        dpPrev[3][offset] = 1;
        for (int i = 0; i < n; ++i) {
            int[][] dpCurr = new int[4][range];
            for (int prev = 0; prev < 4; ++prev) {
                for (int sc = 0; sc < range; ++sc) {
                    int ways = dpPrev[prev][sc];
                    if (ways == 0) continue;
                    for (int cur = 0; cur < 3; ++cur) {
                        if (prev != 3 && cur == prev) continue;
                        int delta = win[cur][alice[i]];
                        int nsc = sc + delta;
                        if (nsc < 0 || nsc >= range) continue;
                        int sum = dpCurr[cur][nsc] + ways;
                        if (sum >= MOD) sum -= MOD;
                        dpCurr[cur][nsc] = sum;
                    }
                }
            }
            dpPrev = dpCurr;
        }
        long ans = 0;
        for (int prev = 0; prev < 3; ++prev) {
            for (int sc = offset + 1; sc < range; ++sc) {
                ans += dpPrev[prev][sc];
                if (ans >= MOD) ans -= MOD;
            }
        }
        return (int) (ans % MOD);
    }
}

import java.util.*;

class Solution {
    public static long[] xSumOfKSubarrays(int[] nums, int k, int x) {
        int n = nums.length;
        Map<Integer,Integer> freqOf = new HashMap<>();
        TreeSet<int[]> order = new TreeSet<>((a,b) -> {
            if (a[0] != b[0]) return b[0]-a[0];
            if (a[1] != b[1]) return b[1]-a[1];
            return 0;
        });
        Map<Integer,int[]> nodeOf = new HashMap<>();

        long[] result = new long[n - k + 1];
        int idx = 0;
        for (int i = 0; i < k; i++) {
            int v = nums[i];
            int f = freqOf.getOrDefault(v, 0);
            if (f > 0) order.remove(nodeOf.get(v));
            int[] node = new int[]{f + 1, v};
            nodeOf.put(v, node);
            order.add(node);
            freqOf.put(v, f + 1);
        }
        result[idx++] = currentXSum(order, x);
        for (int i = k; i < n; i++) {
            int outV = nums[i - k];
            int outF = freqOf.get(outV);
            order.remove(nodeOf.get(outV));
            if (outF - 1 > 0) {
                int[] node = new int[]{outF - 1, outV};
                nodeOf.put(outV, node);
                order.add(node);
                freqOf.put(outV, outF - 1);
            } else {
                freqOf.remove(outV);
                nodeOf.remove(outV);
            }
            int inV = nums[i];
            int inF = freqOf.getOrDefault(inV, 0);
            if (inF > 0) order.remove(nodeOf.get(inV));
            int[] node2 = new int[]{inF + 1, inV};
            nodeOf.put(inV, node2);
            order.add(node2);
            freqOf.put(inV, inF + 1);

            result[idx++] = currentXSum(order, x);
        }
        return result;
    }

    private static long currentXSum(TreeSet<int[]> order, int x) {
        long sum = 0;
        int cnt = 0;
        for (int[] node : order) {
            if (cnt >= x) break;
            sum += (long) node[0] * node[1];
            cnt++;
        }
        return sum;
    }
}

