class Solution {
    public static List<String> findScreenSequence(String target) {
        int total = 0;
        for (int i = 0; i < target.length(); i++) {
            total += 1 + (target.charAt(i) - 'a');
        }
        List<String> result = new ArrayList<>(total);
        StringBuilder cur = new StringBuilder();
        for (int i = 0; i < target.length(); i++) {
            cur.append('a');
            result.add(cur.toString());
            int steps = target.charAt(i) - 'a';
            for (int s = 0; s < steps; s++) {
                int idx = cur.length() - 1;
                char last = cur.charAt(idx);
                char next = (char) ((last - 'a' + 1) % 26 + 'a');
                cur.setCharAt(idx, next);
                result.add(cur.toString());
            }
        }
        return result;
    }
}

