public class Solution {
    public static int minimumOperations(int[] nums) {
        if (nums == null || nums.length == 0) return 0;
        int max = 0;
        for (int v : nums) if (v > max) max = v;
        int limit = Math.max(2, max);
        int[] spf = new int[limit + 1];
        for (int i = 2; i <= limit; i++) spf[i] = i;
        for (int i = 2; i * i <= limit; i++) {
            if (spf[i] == i) {
                for (int j = i * i; j <= limit; j += i) {
                    if (spf[j] == j) spf[j] = i;
                }
            }
        }
        final int INF = Integer.MAX_VALUE / 2;
        int prevOrig = nums[0];
        int prevSpf = (prevOrig == 1) ? 1 : spf[prevOrig];
        boolean prevHasSpf = prevSpf != prevOrig;
        int dp0 = 0;
        int dp1 = prevHasSpf ? 1 : INF;
        for (int i = 1; i < nums.length; i++) {
            int curOrig = nums[i];
            int curSpf = (curOrig == 1) ? 1 : spf[curOrig];
            boolean curHasSpf = curSpf != curOrig;
            int ndp0 = INF;
            int ndp1 = INF;
            if (dp0 < INF) {
                if (prevOrig <= curOrig) ndp0 = Math.min(ndp0, dp0);
                if (curHasSpf && prevOrig <= curSpf) ndp1 = Math.min(ndp1, dp0 + 1);
            }
            if (dp1 < INF) {
                if (prevSpf <= curOrig) ndp0 = Math.min(ndp0, dp1);
                if (curHasSpf && prevSpf <= curSpf) ndp1 = Math.min(ndp1, dp1 + 1);
            }
            dp0 = ndp0;
            dp1 = ndp1;
            prevOrig = curOrig;
            prevSpf = curSpf;
        }
        int ans = Math.min(dp0, dp1);
        return ans >= INF ? -1 : ans;
    }
}

