class Solution {
    public static boolean[] dfsStringsArePalindromes(int[] parent, String s) {
        int n = parent.length;
        List<Integer>[] children = new ArrayList[n];
        for (int i = 0; i < n; i++) children[i] = new ArrayList<>();
        for (int i = 1; i < n; i++) children[parent[i]].add(i);

        int[] order = new int[n];
        int orderSize = 0;
        int[] stack = new int[n];
        int top = 0;
        stack[top++] = 0;
        while (top > 0) {
            int u = stack[--top];
            order[orderSize++] = u;
            for (int v : children[u]) stack[top++] = v;
        }

        int[] mask = new int[n];
        boolean[] answer = new boolean[n];
        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            int m = 0;
            for (int v : children[u]) m ^= mask[v];
            m ^= 1 << (s.charAt(u) - 'a');
            mask[u] = m;
            answer[u] = (m & (m - 1)) == 0;
        }
        return answer;
    }
}

