public class Solution {
    private static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    private static long lcm(long a, long b) {
        if (a == 0 || b == 0) return 0;
        return a / gcd(a, b) * b;
    }

    public static long maxFactorScore(int[] nums) {
        int n = nums.length;
        long[] prefGcd = new long[n];
        long[] prefLcm = new long[n];
        prefGcd[0] = nums[0];
        prefLcm[0] = nums[0];
        for (int i = 1; i < n; i++) {
            prefGcd[i] = gcd(prefGcd[i - 1], nums[i]);
            prefLcm[i] = lcm(prefLcm[i - 1], nums[i]);
        }
        long best = prefLcm[n - 1] * prefGcd[n - 1];
        long suffixGcd = 0;
        long suffixLcm = 1;
        for (int i = n - 1; i >= 0; i--) {
            long leftGcd = (i > 0) ? prefGcd[i - 1] : 0;
            long curGcd;
            if (leftGcd == 0) curGcd = suffixGcd;
            else if (suffixGcd == 0) curGcd = leftGcd;
            else curGcd = gcd(leftGcd, suffixGcd);
            long leftLcm = (i > 0) ? prefLcm[i - 1] : 1;
            long curLcm = lcm(leftLcm, suffixLcm);
            long score = curLcm * curGcd;
            if (score > best) best = score;
            if (suffixGcd == 0) suffixGcd = nums[i];
            else suffixGcd = gcd(nums[i], suffixGcd);
            if (suffixLcm == 1) suffixLcm = nums[i];
            else suffixLcm = lcm(nums[i], suffixLcm);
        }
        return best;
    }
}

