public class Solution {
    private static final int MOD = 1_000_000_007;

    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    public int countPairs(int[] nums) {
        int max = 0;
        for (int v : nums) if (v > max) max = v;
        int M = max;
        long[][] dp = new long[M + 1][M + 1];
        dp[0][0] = 1;
        for (int x : nums) {
            long[][] ndp = new long[M + 1][M + 1];
            for (int i = 0; i <= M; i++) {
                System.arraycopy(dp[i], 0, ndp[i], 0, M + 1);
            }
            for (int g1 = 0; g1 <= M; g1++) {
                for (int g2 = 0; g2 <= M; g2++) {
                    long cur = dp[g1][g2];
                    if (cur == 0) continue;
                    int ng1 = (g1 == 0) ? x : gcd(g1, x);
                    ndp[ng1][g2] = (ndp[ng1][g2] + cur) % MOD;
                    int ng2 = (g2 == 0) ? x : gcd(g2, x);
                    ndp[g1][ng2] = (ndp[g1][ng2] + cur) % MOD;
                }
            }
            dp = ndp;
        }
        long ans = 0;
        for (int g = 1; g <= M; g++) {
            ans = (ans + dp[g][g]) % MOD;
        }
        return (int) ans;
    }
}

import java.util.Arrays;

class Solution {
    public static int[] findSubtreeSizes(int[] parent, String s) {
        int n = parent.length;
        int[] headOrig = new int[n];
        int[] nextOrig = new int[n];
        Arrays.fill(headOrig, -1);
        for (int i = 1; i < n; i++) {
            int p = parent[i];
            nextOrig[i] = headOrig[p];
            headOrig[p] = i;
        }

        int[] newParent = parent.clone();
        int[] savedPrev = new int[n];
        Arrays.fill(savedPrev, -1);
        int[] lastSeen = new int[26];
        Arrays.fill(lastSeen, -1);

        int[] stack = new int[2 * n];
        int top = 0;
        stack[top++] = 0; // pre-order marker for root

        while (top > 0) {
            int cur = stack[--top];
            if (cur >= 0) {
                int u = cur;
                int c = s.charAt(u) - 'a';
                savedPrev[u] = lastSeen[c];
                lastSeen[c] = u;
                stack[top++] = ~u; // post-order marker
                for (int e = headOrig[u]; e != -1; e = nextOrig[e]) {
                    int v = e;
                    int cc = s.charAt(v) - 'a';
                    if (lastSeen[cc] != -1) newParent[v] = lastSeen[cc];
                    else newParent[v] = parent[v];
                    stack[top++] = v;
                }
            } else {
                int u = ~cur;
                int c = s.charAt(u) - 'a';
                lastSeen[c] = savedPrev[u];
            }
        }

        int[] headNew = new int[n];
        int[] nextNew = new int[n];
        Arrays.fill(headNew, -1);
        for (int i = 1; i < n; i++) {
            int p = newParent[i];
            nextNew[i] = headNew[p];
            headNew[p] = i;
        }

        int[] ans = new int[n];
        Arrays.fill(ans, 1);
        top = 0;
        stack[top++] = 0;
        while (top > 0) {
            int cur = stack[--top];
            if (cur >= 0) {
                int u = cur;
                stack[top++] = ~u;
                for (int e = headNew[u]; e != -1; e = nextNew[e]) {
                    stack[top++] = e;
                }
            } else {
                int u = ~cur;
                for (int e = headNew[u]; e != -1; e = nextNew[e]) {
                    ans[u] += ans[e];
                }
            }
        }
        return ans;
    }
}

