public class Solution {
    private static final int MOD = 1_000_000_007;

    public static int originalStringCount(String word, int k) {
        int n = word.length();
        List<Integer> groups = new ArrayList<>();
        for (int i = 0; i < n; ) {
            int j = i;
            while (j < n && word.charAt(j) == word.charAt(i)) {
                ++j;
            }
            groups.add(j - i);
            i = j;
        }

        long totalWays = 1;
        for (int g : groups) {
            totalWays = (totalWays * g) % MOD;
        }

        if (k == 0) {
            return (int) totalWays;
        }

        int[] dp = new int[k];
        int[] ndp = new int[k];
        dp[0] = 1;

        for (int g : groups) {
            int limit = Math.min(g, k - 1);
            long window = 0;
            ndp[0] = 0;
            for (int t = 1; t < k; ++t) {
                window += dp[t - 1];
                if (window >= MOD) window -= MOD;
                int removeIdx = t - 1 - limit;
                if (removeIdx >= 0) {
                    window -= dp[removeIdx];
                    if (window < 0) window += MOD;
                }
                ndp[t] = (int) window;
            }
            int[] tmp = dp;
            dp = ndp;
            ndp = tmp;
        }

        long lessThanK = 0;
        for (int val : dp) {
            lessThanK += val;
            if (lessThanK >= MOD) lessThanK -= MOD;
        }

        long ans = (totalWays - lessThanK) % MOD;
        if (ans < 0) ans += MOD;
        return (int) ans;
    }
}

import java.util.Arrays;

class Solution {
    public static long maxPoints(int n, int k, long[][] stayScore, long[][] travelScore) {
        if (k == 0 || n == 0) return 0L;
        long[] dpPrev = new long[n];
        for (int c = 0; c < n; ++c) dpPrev[c] = stayScore[0][c];
        long[] dpCurr = new long[n];
        long[] bestTravel = new long[n];
        for (int day = 1; day < k; ++day) {
            Arrays.fill(bestTravel, Long.MIN_VALUE);
            for (int p = 0; p < n; ++p) {
                long base = dpPrev[p];
                for (int c = 0; c < n; ++c) {
                    if (c == p) continue;
                    long cand = base + travelScore[p][c];
                    if (cand > bestTravel[c]) bestTravel[c] = cand;
                }
            }
            for (int c = 0; c < n; ++c) {
                long stay = dpPrev[c] + stayScore[day][c];
                long travel = bestTravel[c];
                dpCurr[c] = stay > travel ? stay : travel;
            }
            long[] temp = dpPrev;
            dpPrev = dpCurr;
            dpCurr = temp;
        }
        long answer = Long.MIN_VALUE;
        for (long v : dpPrev) if (v > answer) answer = v;
        return answer;
    }
}

