class Solution {
    private static final long MOD = 1_000_000_007L;
    private static long[][] multiply(long[][] a, long[][] b) {
        int n = a.length;
        long[][] c = new long[n][n];
        for (int i = 0; i < n; i++) {
            for (int k = 0; k < n; k++) {
                if (a[i][k] == 0) continue;
                long aik = a[i][k];
                for (int j = 0; j < n; j++) {
                    if (b[k][j] == 0) continue;
                    c[i][j] = (c[i][j] + aik * b[k][j]) % MOD;
                }
            }
        }
        return c;
    }

    private static long[][] power(long[][] base, long exp) {
        int n = base.length;
        long[][] result = new long[n][n];
        for (int i = 0; i < n; i++) result[i][i] = 1;
        long[][] cur = base;
        long e = exp;
        while (e > 0) {
            if ((e & 1) == 1) result = multiply(cur, result);
            cur = multiply(cur, cur);
            e >>= 1;
        }
        return result;
    }

    public static int totalLengthAfterTransformations(String s, int t) {
        long[] cnt = new long[26];
        for (int i = 0; i < s.length(); i++) {
            cnt[s.charAt(i) - 'a'] = (cnt[s.charAt(i) - 'a'] + 1) % MOD;
        }

        long[][] trans = new long[26][26];
        for (int i = 0; i < 25; i++) trans[i + 1][i] = 1;
        trans[0][25] = 2;

        long[][] transPow = power(trans, t);

        long[] finalCnt = new long[26];
        for (int i = 0; i < 26; i++) {
            long sum = 0;
            for (int j = 0; j < 26; j++) {
                if (transPow[i][j] != 0 && cnt[j] != 0) {
                    sum = (sum + transPow[i][j] * cnt[j]) % MOD;
                }
            }
            finalCnt[i] = sum;
        }

        long ans = 0;
        for (long v : finalCnt) ans = (ans + v) % MOD;
        return (int) ans;
    }
}

public class Solution {
    public static boolean is_balanced_string(String num) {
        if (num == null) return false;
        int evenSum = 0;
        int oddSum = 0;
        for (int i = 0; i < num.length(); i++) {
            int digit = num.charAt(i) - '0';
            if ((i & 1) == 0) {
                evenSum += digit;
            } else {
                oddSum += digit;
            }
        }
        return evenSum == oddSum;
    }
}

import java.util.*;

public class Solution {
    private static final long MOD = 1_000_000_007L;
    private static long[][] multiply(long[][] a, long[][] b) {
        long[][] c = new long[26][26];
        for (int i = 0; i < 26; i++) {
            for (int k = 0; k < 26; k++) {
                long aik = a[i][k];
                if (aik == 0) continue;
                for (int j = 0; j < 26; j++) {
                    c[i][j] = (c[i][j] + aik * b[k][j]) % MOD;
                }
            }
        }
        return c;
    }
    private static long[][] power(long[][] base, long exp) {
        long[][] result = new long[26][26];
        for (int i = 0; i < 26; i++) result[i][i] = 1;
        long[][] cur = base;
        while (exp > 0) {
            if ((exp & 1L) != 0) result = multiply(cur, result);
            cur = multiply(cur, cur);
            exp >>= 1;
        }
        return result;
    }
    private static long[] multiplyVector(long[][] m, long[] v) {
        long[] res = new long[26];
        for (int i = 0; i < 26; i++) {
            long sum = 0;
            for (int j = 0; j < 26; j++) {
                sum = (sum + m[i][j] * v[j]) % MOD;
            }
            res[i] = sum;
        }
        return res;
    }
    public static int totalCharactersAfterTransformationsII(String s, int t, int[] nums) {
        long[][] a = new long[26][26];
        for (int c = 0; c < 26; c++) {
            int cnt = nums[c];
            for (int d = 1; d <= cnt; d++) {
                int nxt = (c + d) % 26;
                a[c][nxt] = (a[c][nxt] + 1) % MOD;
            }
        }
        long[][] p = power(a, t);
        long[] ones = new long[26];
        Arrays.fill(ones, 1L);
        long[] rowSums = multiplyVector(p, ones);
        long ans = 0;
        for (int i = 0; i < s.length(); i++) {
            int idx = s.charAt(i) - 'a';
            ans = (ans + rowSums[idx]) % MOD;
        }
        return (int) ans;
    }
}

