class Solution {
    public static long minimumTime(int[][] moveTime) {
        int n = moveTime.length;
        int m = moveTime[0].length;
        long INF = Long.MAX_VALUE / 4;
        long[][] dist0 = new long[n][m];
        long[][] dist1 = new long[n][m];
        for (int i = 0; i < n; i++) {
            Arrays.fill(dist0[i], INF);
            Arrays.fill(dist1[i], INF);
        }
        PriorityQueue<State> pq = new PriorityQueue<>();
        dist0[0][0] = 0;
        pq.offer(new State(0L, 0, 0, 0));
        int[] di = {-1, 1, 0, 0};
        int[] dj = {0, 0, -1, 1};
        while (!pq.isEmpty()) {
            State cur = pq.poll();
            long curTime = cur.time;
            int i = cur.i;
            int j = cur.j;
            int par = cur.par;
            if (i == n - 1 && j == m - 1) {
                return curTime;
            }
            if (par == 0 && curTime != dist0[i][j]) continue;
            if (par == 1 && curTime != dist1[i][j]) continue;
            long moveCost = (par == 0) ? 1L : 2L;
            int nextPar = 1 - par;
            for (int dir = 0; dir < 4; dir++) {
                int ni = i + di[dir];
                int nj = j + dj[dir];
                if (ni < 0 || ni >= n || nj < 0 || nj >= m) continue;
                long start = Math.max(curTime, (long) moveTime[ni][nj]);
                long arrival = start + moveCost;
                if (nextPar == 0) {
                    if (arrival < dist0[ni][nj]) {
                        dist0[ni][nj] = arrival;
                        pq.offer(new State(arrival, ni, nj, 0));
                    }
                } else {
                    if (arrival < dist1[ni][nj]) {
                        dist1[ni][nj] = arrival;
                        pq.offer(new State(arrival, ni, nj, 1));
                    }
                }
            }
        }
        return Math.min(dist0[n - 1][m - 1], dist1[n - 1][m - 1]);
    }

    private static class State implements Comparable<State> {
        long time;
        int i, j, par;
        State(long time, int i, int j, int par) {
            this.time = time;
            this.i = i;
            this.j = j;
            this.par = par;
        }
        public int compareTo(State other) {
            return Long.compare(this.time, other.time);
        }
    }
}

import java.util.*;

class Solution {
    private static class MinHeap {
        private final long[] times;
        private final int[] nodes;
        private int size;
        MinHeap(int capacity) {
            times = new long[capacity];
            nodes = new int[capacity];
            size = 0;
        }
        void add(long t, int n) {
            int i = size++;
            while (i > 0) {
                int p = (i - 1) >>> 1;
                if (times[p] <= t) break;
                times[i] = times[p];
                nodes[i] = nodes[p];
                i = p;
            }
            times[i] = t;
            nodes[i] = n;
        }
        boolean isEmpty() {
            return size == 0;
        }
        long topTime() {
            return times[0];
        }
        int topNode() {
            return nodes[0];
        }
        void poll() {
            int last = --size;
            long t = times[last];
            int n = nodes[last];
            int i = 0;
            while (true) {
                int left = (i << 1) + 1;
                if (left >= size) break;
                int right = left + 1;
                int child = (right < size && times[right] < times[left]) ? right : left;
                if (times[child] >= t) break;
                times[i] = times[child];
                nodes[i] = nodes[child];
                i = child;
            }
            times[i] = t;
            nodes[i] = n;
        }
    }

    public static long minimumTime(int[][] moveTime) {
        int n = moveTime.length;
        int m = moveTime[0].length;
        int total = n * m;
        long INF = Long.MAX_VALUE / 4;
        long[] dist = new long[total];
        Arrays.fill(dist, INF);
        MinHeap pq = new MinHeap(total);
        dist[0] = 0;
        pq.add(0L, 0);
        int[] dx = {1, -1, 0, 0};
        int[] dy = {0, 0, 1, -1};
        int target = total - 1;
        while (!pq.isEmpty()) {
            long curTime = pq.topTime();
            int idx = pq.topNode();
            pq.poll();
            if (curTime != dist[idx]) continue;
            if (idx == target) break;
            int x = idx / m;
            int y = idx % m;
            for (int dir = 0; dir < 4; dir++) {
                int nx = x + dx[dir];
                int ny = y + dy[dir];
                if (nx < 0 || nx >= n || ny < 0 || ny >= m) continue;
                int nIdx = nx * m + ny;
                long arrive = Math.max(curTime + 1L, (long) moveTime[nx][ny] + 1L);
                if (arrive < dist[nIdx]) {
                    dist[nIdx] = arrive;
                    pq.add(arrive, nIdx);
                }
            }
        }
        return dist[target];
    }
}

