class Solution {
    public static long smallestDivisibleDigitProduct(long n, long t) {
        if (containsZero(n)) return n;
        if (hasNonAllowedPrimeFactors(t)) {
            return ((n + 9) / 10) * 10;
        }
        long cur = n;
        while (true) {
            long prod = digitProduct(cur);
            if (prod % t == 0) return cur;
            cur++;
        }
    }

    private static boolean containsZero(long x) {
        if (x == 0) return true;
        while (x > 0) {
            if (x % 10 == 0) return true;
            x /= 10;
        }
        return false;
    }

    private static boolean hasNonAllowedPrimeFactors(long t) {
        if (t == 0) return false;
        long[] primes = {2, 3, 5, 7};
        for (long p : primes) {
            while (t % p == 0) t /= p;
        }
        return t != 1;
    }

    private static long digitProduct(long x) {
        if (x == 0) return 0;
        long prod = 1;
        while (x > 0) {
            int d = (int) (x % 10);
            prod *= d;
            if (prod == 0) break;
            x /= 10;
        }
        return prod;
    }
}

