public class Solution {
    public static boolean check(int[] nums, int k) {
        int n = nums.length;
        if (k == 1) return n >= 2;
        if (n < 2 * k) return false;
        int len = k - 1;
        int sum1 = 0, sum2 = 0;
        for (int i = 0; i < len; i++) {
            if (nums[i] < nums[i + 1]) sum1++;
        }
        for (int i = k; i < k + len; i++) {
            if (nums[i] < nums[i + 1]) sum2++;
        }
        for (int a = 0; a + 2 * k <= n; a++) {
            if (sum1 == len && sum2 == len) return true;
            if (a + 2 * k == n) break;
            // update sums for next a
            if (nums[a] < nums[a + 1]) sum1--;
            if (nums[a + len] < nums[a + len + 1]) sum1++;
            if (nums[a + k] < nums[a + k + 1]) sum2--;
            if (nums[a + k + len] < nums[a + k + len + 1]) sum2++;
        }
        return false;
    }
}

