class Solution {
    public static int maxFrequency(int[] nums, int k, int numOperations) {
        if (k == 0) {
            Map<Integer, Integer> cnt = new HashMap<>();
            int best = 0;
            for (int v : nums) {
                int c = cnt.getOrDefault(v, 0) + 1;
                cnt.put(v, c);
                if (c > best) best = c;
            }
            return best;
        }
        Map<Integer, List<Long>> groups = new HashMap<>(nums.length * 2);
        for (int v : nums) {
            int r = ((v % k) + k) % k;
            long base = ((long) v - r) / k;
            groups.computeIfAbsent(r, key -> new ArrayList<>()).add(base);
        }
        int answer = 0;
        long limit = numOperations;
        for (List<Long> bases : groups.values()) {
            Collections.sort(bases);
            long sum = 0;
            int left = 0;
            for (int right = 0; right < bases.size(); ++right) {
                sum += bases.get(right);
                while (bases.get(right) * (right - left + 1) - sum > limit) {
                    sum -= bases.get(left);
                    left++;
                }
                int size = right - left + 1;
                if (size > answer) answer = size;
            }
        }
        return answer;
    }
}

