class Solution {
    public static int maxFrequencyAfterOperations(int[] nums, int k, int numOperations) {
        int n = nums.length;
        int[] sorted = Arrays.copyOf(nums, n);
        Arrays.sort(sorted);
        Map<Integer, Integer> freq = new HashMap<>();
        for (int v : nums) {
            freq.put(v, freq.getOrDefault(v, 0) + 1);
        }
        int ans = 0;
        int left = 0;
        for (int right = 0; right < n; right++) {
            while ((long) sorted[right] - (long) sorted[left] > k) {
                left++;
            }
            int windowSize = right - left + 1;
            int v = sorted[right];
            int cntSame = freq.get(v);
            int cntOther = windowSize - cntSame;
            int possible = cntSame + Math.min(numOperations, cntOther);
            if (possible > ans) ans = possible;
        }
        return ans;
    }
}

