public class Solution {
    public static int max_adjacent_increasing_subarrays(int[] nums) {
        int n = nums.length;
        if (n < 2) return 0;
        int[] inc = new int[n];
        inc[n - 1] = 1;
        for (int i = n - 2; i >= 0; --i) {
            inc[i] = (nums[i] < nums[i + 1]) ? inc[i + 1] + 1 : 1;
        }
        int low = 0, high = n / 2;
        while (low < high) {
            int mid = (low + high + 1) >>> 1;
            if (can(mid, inc, n)) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return low;
    }

    private static boolean can(int k, int[] inc, int n) {
        int limit = n - 2 * k;
        if (limit < 0) return false;
        for (int i = 0; i <= limit; ++i) {
            if (inc[i] >= k && inc[i + k] >= k) return true;
        }
        return false;
    }
}

class Solution {
    public static int countValidSelections(int[] nums) {
        long total = 0;
        for (int v : nums) total += v;
        long leftSum = 0;
        int zerosEqual = 0;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] == 0) {
                long rightSum = total - leftSum - nums[i];
                if (leftSum == rightSum) zerosEqual++;
            }
            leftSum += nums[i];
        }
        return zerosEqual * 2;
    }
}

