class Solution {
    public static long sumGoodSubsequences(int[] nums) {
        final long MOD = 1_000_000_007L;
        if (nums == null || nums.length == 0) return 0L;
        Map<Integer, Long> cnt = new HashMap<>();
        Map<Integer, Long> sum = new HashMap<>();
        long answer = 0L;
        for (int a : nums) {
            long leftCnt = cnt.getOrDefault(a - 1, 0L);
            long rightCnt = cnt.getOrDefault(a + 1, 0L);
            long leftSum = sum.getOrDefault(a - 1, 0L);
            long rightSum = sum.getOrDefault(a + 1, 0L);
            long addCnt = (1L + leftCnt + rightCnt) % MOD;
            long aMod = ((long) a % MOD + MOD) % MOD;
            long addSum = (aMod + (leftSum + rightSum) % MOD
                    + aMod * ((leftCnt + rightCnt) % MOD) % MOD) % MOD;
            cnt.put(a, (cnt.getOrDefault(a, 0L) + addCnt) % MOD);
            sum.put(a, (sum.getOrDefault(a, 0L) + addSum) % MOD);
            answer = (answer + addSum) % MOD;
        }
        return answer;
    }
}

