class Solution {
    private static final long MOD = 1_000_000_007L;

    public static int countKReducibleNumbers(String s, int k) {
        int L = s.length();
        long[] fact = new long[L + 1];
        long[] invFact = new long[L + 1];
        fact[0] = 1;
        for (int i = 1; i <= L; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[L] = modPow(fact[L], MOD - 2);
        for (int i = L; i > 0; i--) invFact[i - 1] = invFact[i] * i % MOD;

        int[] steps = new int[L + 1];
        if (L >= 1) steps[1] = 0;
        for (int c = 2; c <= L; c++) {
            int pc = Integer.bitCount(c);
            steps[c] = 1 + steps[pc];
        }

        List<Integer> good = new ArrayList<>();
        for (int c = 1; c <= L; c++) {
            if (steps[c] <= k - 1) good.add(c);
        }

        long total = 0;
        for (int target : good) {
            long ans = 0;
            int onesSoFar = 0;
            for (int i = 0; i < L; i++) {
                if (s.charAt(i) == '1') {
                    int remaining = L - i - 1;
                    int need = target - onesSoFar;
                    if (need >= 0 && need <= remaining) {
                        ans = (ans + nCr(remaining, need, fact, invFact)) % MOD;
                    }
                    onesSoFar++;
                    if (onesSoFar > target) break;
                }
            }
            total = (total + ans) % MOD;
        }
        return (int) total;
    }

    private static long nCr(int n, int r, long[] fact, long[] invFact) {
        if (r < 0 || r > n) return 0;
        return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
    }

    private static long modPow(long base, long exp) {
        long res = 1;
        long b = base % MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) res = res * b % MOD;
            b = b * b % MOD;
            exp >>= 1;
        }
        return res;
    }
}

