class Solution {
    public static boolean canTransformToZeroArray(int[] nums, int[][] queries) {
        int n = nums.length;
        int[] diff = new int[n + 1];
        for (int[] q : queries) {
            int l = q[0];
            int r = q[1];
            if (l < 0) l = 0;
            if (r >= n) r = n - 1;
            diff[l] += 1;
            if (r + 1 < n) diff[r + 1] -= 1;
        }
        int cover = 0;
        for (int i = 0; i < n; i++) {
            cover += diff[i];
            if (nums[i] > cover) return false;
        }
        return true;
    }
}

