public class Solution {
    public static long shiftDistance(String s, String t, int[] nextCost, int[] previousCost) {
        int n = s.length();
        long[] prefNext = new long[27];
        long[] prefPrev = new long[27];
        for (int i = 0; i < 26; i++) {
            prefNext[i + 1] = prefNext[i] + nextCost[i];
            prefPrev[i + 1] = prefPrev[i] + previousCost[i];
        }
        long totalNext = prefNext[26];
        long totalPrev = prefPrev[26];
        long total = 0;
        for (int i = 0; i < n; i++) {
            int a = s.charAt(i) - 'a';
            int b = t.charAt(i) - 'a';
            long forward;
            if (a <= b) {
                forward = prefNext[b] - prefNext[a];
            } else {
                forward = totalNext - (prefNext[a] - prefNext[b]);
            }
            long backward;
            if (a >= b) {
                backward = prefPrev[a + 1] - prefPrev[b + 1];
            } else {
                backward = totalPrev - (prefPrev[b + 1] - prefPrev[a + 1]);
            }
            total += Math.min(forward, backward);
        }
        return total;
    }
}

class Solution {
    public static long minimizeMaxDiff(int[] nums) {
        int n = nums.length;
        long base = 0;
        long minV = Long.MAX_VALUE;
        long maxV = Long.MIN_VALUE;
        for (int i = 0; i + 1 < n; ++i) {
            int a = nums[i];
            int b = nums[i + 1];
            if (a != -1 && b != -1) {
                long diff = Math.abs((long) a - b);
                if (diff > base) base = diff;
            } else if (a == -1 && b != -1) {
                if (b < minV) minV = b;
                if (b > maxV) maxV = b;
            } else if (a != -1 && b == -1) {
                if (a < minV) minV = a;
                if (a > maxV) maxV = a;
            }
        }
        if (minV == Long.MAX_VALUE) {
            return 0;
        }
        long diff = maxV - minV;
        long kDiff = (diff + 1) / 2;
        return Math.max(base, kDiff);
    }
}

class Solution {
    public int minZeroArray(int[] nums, int[][] queries) {
        int n = nums.length, m = queries.length;
        if (!feasible(nums, queries, m)) return -1;
        int lo = 0, hi = m;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (feasible(nums, queries, mid)) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
    private boolean feasible(int[] nums, int[][] queries, int k) {
        int n = nums.length;
        long[] diff = new long[n+1];
        for (int i = 0; i < k; i++) {
            int l = queries[i][0], r = queries[i][1], val = queries[i][2];
            diff[l] += val;
            diff[r+1] -= val;
        }
        long cur = 0;
        for (int i = 0; i < n; i++) {
            cur += diff[i];
            if (cur < nums[i]) return false;
        }
        return true;
    }
}

