    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static boolean canRearrange(String s, String t, int k) {
        int n = s.length();
        if (n != t.length() || k <= 0 || n % k != 0) return false;
        int blockSize = n / k;
        Map<Long, Integer> count = new HashMap<>(k * 2);
        for (int i = 0; i < n; i += blockSize) {
            long h = 0;
            for (int j = i; j < i + blockSize; j++) {
                h = h * 31 + s.charAt(j);
            }
            count.put(h, count.getOrDefault(h, 0) + 1);
        }
        for (int i = 0; i < n; i += blockSize) {
            long h = 0;
            for (int j = i; j < i + blockSize; j++) {
                h = h * 31 + t.charAt(j);
            }
            Integer cnt = count.get(h);
            if (cnt == null || cnt == 0) return false;
            if (cnt == 1) count.remove(h);
            else count.put(h, cnt - 1);
        }
        return true;
    }
}

import java.util.*;

public class P2 {
    static int minArraySum(int[] nums, int k, int op1, int op2) {
        int n = nums.length;
        final int INF = 1_000_000_000;
        int[][][] f = new int[n+1][op1+1][op2+1];
        for (int[][] a : f) for (int[] b : a) Arrays.fill(b, INF);
        f[0][0][0] = 0;
        for (int i = 1; i <= n; i++) {
            int x = nums[i-1];
            for (int j = 0; j <= op1; j++) {
                for (int kk = 0; kk <= op2; kk++) {
                    int best = INF;
                    if (f[i-1][j][kk] < INF) best = Math.min(best, f[i-1][j][kk] + x);
                    if (j > 0 && f[i-1][j-1][kk] < INF) best = Math.min(best, f[i-1][j-1][kk] + (x+1)/2);
                    if (kk > 0 && x >= k && f[i-1][j][kk-1] < INF) best = Math.min(best, f[i-1][j][kk-1] + (x-k));
                    if (j > 0 && kk > 0 && f[i-1][j-1][kk-1] < INF) {
                        int y = (x+1)/2;
                        if (y >= k) best = Math.min(best, f[i-1][j-1][kk-1] + (y-k));
                        if (x >= k) best = Math.min(best, f[i-1][j-1][kk-1] + (x-k+1)/2);
                    }
                    f[i][j][kk] = best;
                }
            }
        }
        int ans = INF;
        for (int j = 0; j <= op1; j++)
            for (int kk = 0; kk <= op2; kk++)
                ans = Math.min(ans, f[n][j][kk]);
        return ans;
    }

    public static void main(String[] args) {
        int got1 = minArraySum(new int[]{2,8,3,19,3}, 3, 1, 1);
        System.out.println("got=" + got1 + " expected=23 " + (got1==23?"OK":"FAIL"));
        int got2 = minArraySum(new int[]{2,4,3}, 3, 2, 1);
        System.out.println("got=" + got2 + " expected=3 " + (got2==3?"OK":"FAIL"));
    }
}

import java.util.TreeMap;

class Solution {
    public static int minPositiveSumSubarray(int[] nums, int l, int r) {
        int n = nums.length;
        if (l > n) return -1;
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] + nums[i];
        }
        TreeMap<Long, Integer> map = new TreeMap<>();
        int answer = Integer.MAX_VALUE;
        for (int j = 1; j <= n; j++) {
            int addIdx = j - l;
            if (addIdx >= 0) {
                long val = pref[addIdx];
                map.put(val, map.getOrDefault(val, 0) + 1);
            }
            int removeIdx = j - r - 1;
            if (removeIdx >= 0) {
                long val = pref[removeIdx];
                int cnt = map.get(val);
                if (cnt == 1) map.remove(val);
                else map.put(val, cnt - 1);
            }
            Long key = map.lowerKey(pref[j]);
            if (key != null) {
                long sum = pref[j] - key;
                if (sum > 0 && sum < answer) {
                    answer = (int) sum;
                }
            }
        }
        return answer == Integer.MAX_VALUE ? -1 : answer;
    }
}

import java.util.*;

public class Solution {
    public static int max_removable_queries(int[] nums, int[][] queries) {
        int n = nums.length;
        int q = queries.length;
        if (q == 0) {
            for (int v : nums) {
                if (v > 0) return -1;
            }
            return 0;
        }
        Arrays.sort(queries, (a, b) -> Integer.compare(a[0], b[0]));
        PriorityQueue<Integer> startHeap = new PriorityQueue<>();
        PriorityQueue<Integer> selectedHeap = new PriorityQueue<>();
        int active = 0;
        int used = 0;
        int idx = 0;
        for (int i = 0; i < n; i++) {
            while (idx < q && queries[idx][0] == i) {
                startHeap.offer(queries[idx][1]);
                idx++;
            }
            while (!selectedHeap.isEmpty() && selectedHeap.peek() < i) {
                selectedHeap.poll();
                active--;
            }
            while (active < nums[i]) {
                if (startHeap.isEmpty()) {
                    return -1;
                }
                int r = startHeap.poll();
                selectedHeap.offer(r);
                active++;
                used++;
            }
        }
        return q - used;
    }
}

