class Solution {
    public static int[] maximizeTargetNodes(List<List<Integer>> edges1, List<List<Integer>> edges2, int k) {
        int n = edges1.size() + 1;
        int m = edges2.size() + 1;

        List<List<Integer>> adj1 = buildAdj(n, edges1);
        List<List<Integer>> adj2 = buildAdj(m, edges2);

        int[][] dist1 = allPairsDist(n, adj1);
        int[][] dist2 = allPairsDist(m, adj2);

        int[] countFirst = new int[n];
        for (int i = 0; i < n; ++i) {
            int cnt = 0;
            int[] row = dist1[i];
            for (int d : row) {
                if (d != -1 && d <= k) ++cnt;
            }
            countFirst[i] = cnt;
        }

        int[] bestSecond = new int[k + 1];
        for (int v = 0; v < m; ++v) {
            int[] cnt = new int[k + 1];
            int[] row = dist2[v];
            for (int d : row) {
                if (d != -1 && d <= k) ++cnt[d];
            }
            for (int r = 1; r <= k; ++r) cnt[r] += cnt[r - 1];
            for (int r = 0; r <= k; ++r) {
                if (cnt[r] > bestSecond[r]) bestSecond[r] = cnt[r];
            }
        }

        int add = (k >= 1) ? bestSecond[k - 1] : 0;
        int[] result = new int[n];
        for (int i = 0; i < n; ++i) {
            result[i] = countFirst[i] + add;
        }
        return result;
    }

    private static List<List<Integer>> buildAdj(int num, List<List<Integer>> edges) {
        List<List<Integer>> adj = new ArrayList<>(num);
        for (int i = 0; i < num; ++i) adj.add(new ArrayList<>());
        for (List<Integer> e : edges) {
            int a = e.get(0);
            int b = e.get(1);
            adj.get(a).add(b);
            adj.get(b).add(a);
        }
        return adj;
    }

    private static int[][] allPairsDist(int num, List<List<Integer>> adj) {
        int[][] dist = new int[num][num];
        for (int i = 0; i < num; ++i) Arrays.fill(dist[i], -1);
        int[] queue = new int[num];
        for (int s = 0; s < num; ++s) {
            int[] d = dist[s];
            Arrays.fill(d, -1);
            int head = 0, tail = 0;
            d[s] = 0;
            queue[tail++] = s;
            while (head < tail) {
                int u = queue[head++];
                int du = d[u];
                for (int v : adj.get(u)) {
                    if (d[v] == -1) {
                        d[v] = du + 1;
                        queue[tail++] = v;
                    }
                }
            }
        }
        return dist;
    }
}

