class Solution {
    public static long smallestAllSetBits(long n) {
        if (n <= 0) {
            return 0L;
        }
        int len = 64 - Long.numberOfLeadingZeros(n);
        long candidate = (len == 64) ? -1L : (1L << len) - 1L;
        if (Long.compareUnsigned(candidate, n) >= 0) {
            return candidate;
        }
        return (len == 63) ? -1L : (1L << (len + 1)) - 1L;
    }
}

