import java.util.PriorityQueue;

public class Solution {
    private static boolean isPrime(long x) {
        if (x <= 1) return false;
        if (x == 2) return true;
        if ((x & 1) == 0) return false;
        long r = (long) Math.sqrt(x);
        for (long i = 3; i <= r; i += 2) {
            if (x % i == 0) return false;
        }
        return true;
    }

    public static long minimumTransformationCost(long n, long m) {
        String sn = String.valueOf(n);
        String sm = String.valueOf(m);
        int lenN = sn.length();
        int lenM = sm.length();
        if (lenN != lenM) return -1;
        int d = lenN;
        if (isPrime(n) || isPrime(m)) return -1;
        if (n == m) return n;

        int maxVal = 1;
        for (int i = 0; i < d; ++i) maxVal *= 10;
        maxVal -= 1;

        boolean[] primeCache = null;
        if (maxVal <= 2_000_000) {
            primeCache = new boolean[maxVal + 1];
            for (int i = 2; i <= maxVal; ++i) primeCache[i] = true;
            for (int p = 2; p * p <= maxVal; ++p) {
                if (primeCache[p]) {
                    for (int q = p * p; q <= maxVal; q += p) primeCache[q] = false;
                }
            }
        }

        long INF = Long.MAX_VALUE / 4;
        long[] dist = new long[maxVal + 1];
        boolean[] visited = new boolean[maxVal + 1];
        for (int i = 0; i <= maxVal; ++i) dist[i] = INF;

        class Node {
            long dist;
            int val;
            Node(long d, int v) { dist = d; val = v; }
        }

        PriorityQueue<Node> heap = new PriorityQueue<>((a, b) -> Long.compare(a.dist, b.dist));
        dist[(int) n] = n;
        heap.add(new Node(n, (int) n));

        int[] pow10 = new int[d];
        pow10[0] = 1;
        for (int i = 1; i < d; ++i) pow10[i] = pow10[i - 1] * 10;

        while (!heap.isEmpty()) {
            Node cur = heap.poll();
            if (visited[cur.val]) continue;
            visited[cur.val] = true;
            if (cur.val == m) return cur.dist;

            for (int pos = 0; pos < d; ++pos) {
                int digit = (cur.val / pow10[pos]) % 10;
                if (digit > 0) {
                    if (!(pos == d - 1 && digit == 1)) {
                        int v = cur.val - pow10[pos];
                        boolean prime = primeCache != null ? primeCache[v] : isPrime(v);
                        if (!prime && cur.dist + v < dist[v]) {
                            dist[v] = cur.dist + v;
                            heap.add(new Node(dist[v], v));
                        }
                    }
                }
                if (digit < 9) {
                    int v = cur.val + pow10[pos];
                    boolean prime = primeCache != null ? primeCache[v] : isPrime(v);
                    if (!prime && cur.dist + v < dist[v]) {
                        dist[v] = cur.dist + v;
                        heap.add(new Node(dist[v], v));
                    }
                }
            }
        }
        return -1;
    }
}

import java.util.*;

class Solution {
    private static class DSU {
        int[] parent;
        int[] size;
        DSU(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }
        int find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }
        void unite(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return;
            if (size[ra] < size[rb]) {
                int tmp = ra;
                ra = rb;
                rb = tmp;
            }
            parent[rb] = ra;
            size[ra] += size[rb];
        }
    }

    public static int countComponents(int[] nums, int threshold) {
        int n = nums.length;
        DSU dsu = new DSU(n);
        int[] firstIdx = new int[threshold + 1];
        for (int i = 0; i < n; i++) {
            int val = nums[i];
            if (val > threshold) continue;
            for (int mult = val; mult <= threshold; mult += val) {
                int stored = firstIdx[mult];
                if (stored == 0) {
                    firstIdx[mult] = i + 1;
                } else {
                    dsu.unite(i, stored - 1);
                }
            }
        }
        boolean[] seen = new boolean[n];
        int components = 0;
        for (int i = 0; i < n; i++) {
            int root = dsu.find(i);
            if (!seen[root]) {
                seen[root] = true;
                components++;
            }
        }
        return components;
    }
}

