class Solution {
    public static long maxSubarraySumDivisibleByK(int[] nums, int k) {
        long prefix = 0;
        long answer = Long.MIN_VALUE;
        long[] minPrefix = new long[k];
        boolean[] has = new boolean[k];
        Arrays.fill(minPrefix, Long.MAX_VALUE);
        minPrefix[0] = 0;
        has[0] = true;
        for (int i = 0; i < nums.length; ++i) {
            prefix += nums[i];
            int r = (i + 1) % k;
            if (has[r]) {
                answer = Math.max(answer, prefix - minPrefix[r]);
            }
            if (!has[r] || prefix < minPrefix[r]) {
                minPrefix[r] = prefix;
                has[r] = true;
            }
        }
        return answer;
    }
}

