class Solution {
    public static int maxAreaRectangle(List<List<Integer>> points) {
        int n = points.size();
        int[][] pts = new int[n][2];
        Set<Long> pointSet = new HashSet<Long>(n * 2);
        for (int i = 0; i < n; i++) {
            int x = points.get(i).get(0);
            int y = points.get(i).get(1);
