        }
        int best = -1;
        for (int i = 0; i < n; i++) {
            int x1 = pts[i][0];
            int y1 = pts[i][1];
            for (int j = i + 1; j < n; j++) {
                int x2 = pts[j][0];
                int y2 = pts[j][1];
                if (x1 == x2 || y1 == y2) continue;
                long keyC1 = ((long) x1 << 32) ^ (y2 & 0xffffffffL);
                long keyC2 = ((long) x2 << 32) ^ (y1 & 0xffffffffL);
                if (!pointSet.contains(keyC1) || !pointSet.contains(keyC2)) continue;
                int minX = Math.min(x1, x2);
                int maxX = Math.max(x1, x2);
                int minY = Math.min(y1, y2);
                int maxY = Math.max(y1, y2);
                int area = (maxX - minX) * (maxY - minY);
                if (area <= best) continue;
                boolean ok = true;
                for (int k = 0; k < n; k++) {
                    int x = pts[k][0];
                    int y = pts[k][1];
                    if ((x == x1 && y == y1) || (x == x2 && y == y2) ||
                        (x == x1 && y == y2) || (x == x2 && y == y1)) {
                        continue;
                    }
                    if (x >= minX && x <= maxX && y >= minY && y <= maxY) {
                        ok = false;
                        break;
                    }
                }
                if (ok) best = area;
            }
        }
        return best;
    }
}

import java.util.HashSet;
import java.util.Set;

public class Solution {
    private static long encode(int x, int y) {
        return ((long) x << 32) | (y & 0xffffffffL);
    }

    public static int maxArea(int[] xCoord, int[] yCoord) {
        int n = xCoord.length;
        Set<Long> points = new HashSet<>(n * 2);
        for (int i = 0; i < n; i++) {
            points.add(encode(xCoord[i], yCoord[i]));
        }
        int best = -1;
        for (int i = 0; i < n - 1; i++) {
            int x1 = xCoord[i];
            int y1 = yCoord[i];
            for (int j = i + 1; j < n; j++) {
                int x2 = xCoord[j];
                int y2 = yCoord[j];
                if (x1 == x2 || y1 == y2) continue;
                if (!points.contains(encode(x1, y2)) || !points.contains(encode(x2, y1))) continue;
                int minX = Math.min(x1, x2);
                int maxX = Math.max(x1, x2);
                int minY = Math.min(y1, y2);
                int maxY = Math.max(y1, y2);
                long c1 = encode(x1, y1);
                long c2 = encode(x1, y2);
                long c3 = encode(x2, y1);
                long c4 = encode(x2, y2);
                boolean hasOtherPoint = false;
                for (int k = 0; k < n; k++) {
                    long enc = encode(xCoord[k], yCoord[k]);
                    if (enc == c1 || enc == c2 || enc == c3 || enc == c4) continue;
                    int x = xCoord[k];
                    int y = yCoord[k];
                    if (x >= minX && x <= maxX && y >= minY && y <= maxY) {
                        hasOtherPoint = true;
                        break;
                    }
                }
                if (hasOtherPoint) continue;
                int area = (maxX - minX) * (maxY - minY);
                if (area > best) best = area;
            }
        }
        return best;
    }
}

