class Solution {
    public static int minOperationsToMakeGood(String s) {
        int n = s.length();
        if (n == 0) return 0;
        int[] freq = new int[26];
        for (int i = 0; i < n; i++) {
            freq[s.charAt(i) - 'a']++;
        }
        int[] desc = freq.clone();
        Arrays.sort(desc);
        for (int i = 0; i < 13; i++) {
            int tmp = desc[i];
            desc[i] = desc[25 - i];
            desc[25 - i] = tmp;
        }
        int[] prefix = new int[27];
        for (int i = 0; i < 26; i++) {
            prefix[i + 1] = prefix[i] + desc[i];
        }
        int best = n;
        int maxK = Math.min(26, n);
        for (int k = 1; k <= maxK; k++) {
            int sumTop = prefix[k];
            int extra = n - sumTop;
            int f = n / k;
            int ops = computeOps(k, f, extra, desc);
            best = Math.min(best, ops);
            if (f * k != n) {
                ops = computeOps(k, f + 1, extra, desc);
                best = Math.min(best, ops);
            }
        }
        return best;
    }

    private static int computeOps(int k, int f, int extra, int[] desc) {
        int surplus = extra;
        int deficit = 0;
        for (int i = 0; i < k; i++) {
            int cur = desc[i];
            if (cur > f) {
                surplus += cur - f;
            } else {
                deficit += f - cur;
            }
        }
        return surplus > deficit ? surplus : deficit;
    }
}

