class Solution {
    public static int countBeautifulSplits(int[] nums) {
        int n = nums.length;
        if (n < 2) return 0;
        int[] prefixMax = new int[n];
        int curMax = nums[0];
        for (int i = 0; i < n; i++) {
            if (nums[i] > curMax) curMax = nums[i];
            prefixMax[i] = curMax;
        }
        int count = 0;
        int curMin = nums[n - 1];
        for (int i = n - 1; i > 0; i--) {
            if (nums[i] < curMin) curMin = nums[i];
            if (prefixMax[i - 1] == curMin) count++;
        }
        return count;
    }
}

