class Solution {
    public boolean checkValidCuts(int n, int[][] rectangles) {
        int[][] xs = new int[rectangles.length][2];
        int[][] ys = new int[rectangles.length][2];
        for (int i = 0; i < rectangles.length; i++) {
            xs[i] = new int[]{rectangles[i][0], rectangles[i][2]};
            ys[i] = new int[]{rectangles[i][1], rectangles[i][3]};
        }
        return check(xs) || check(ys);
    }
    private boolean check(int[][] intervals) {
        Arrays.sort(intervals, (a,b) -> a[0]-b[0]);
        int cnt = 1;
        int curEnd = intervals[0][1];
        for (int i = 1; i < intervals.length; i++) {
            if (intervals[i][0] >= curEnd) {
                cnt++;
                curEnd = intervals[i][1];
            } else {
                curEnd = Math.max(curEnd, intervals[i][1]);
            }
        }
        return cnt >= 3;
    }
}

