class Solution {
    private static final int MOD = 1_000_000_007;
    private long nC2(long n) { return n * (n - 1) / 2 % MOD; }
    private long calc(int a, long other1, long other2, Map<Integer,Integer> count1, Map<Integer,Integer> count2) {
        long res = other1 * nC2(other2) % MOD;
        for (Map.Entry<Integer,Integer> e : count1.entrySet()) {
            int b = e.getKey();
            if (b == a) continue;
            long b1 = e.getValue();
            long b2 = count2.getOrDefault(b, 0);
            res = (res - b1 * nC2(b2) % MOD + MOD) % MOD;
            res = (res - b1 * b2 % MOD * (other2 - b2) % MOD + MOD) % MOD;
        }
        for (Map.Entry<Integer,Integer> e : count2.entrySet()) {
            int b = e.getKey();
            if (b == a) continue;
            long b2 = e.getValue();
            long b1 = count1.getOrDefault(b, 0);
            res = (res - (other1 - b1) * nC2(b2) % MOD + MOD) % MOD;
        }
        return res;
    }
    public int subsequencesWithMiddleMode(int[] nums) {
        int n = nums.length;
        long ans = 0;
        Map<Integer,Integer> left = new HashMap<>();
        Map<Integer,Integer> right = new HashMap<>();
        for (int i = 0; i < 2; i++) left.merge(nums[i], 1, Integer::sum);
        for (int i = 2; i < n; i++) right.merge(nums[i], 1, Integer::sum);
        for (int i = 2; i < n - 2; i++) {
            int num = nums[i];
            if (right.merge(num, -1, Integer::sum) == 0) right.remove(num);
            int leftCount = left.getOrDefault(num, 0);
            int rightCount = right.getOrDefault(num, 0);
            int leftOther = i - leftCount;
            int rightOther = n - 1 - i - rightCount;
            ans = (ans + nC2(leftCount) * nC2(rightCount)) % MOD;
            ans = (ans + nC2(leftCount) * rightCount % MOD * rightOther % MOD) % MOD;
            ans = (ans + leftCount * leftOther % MOD * nC2(rightCount) % MOD) % MOD;
            ans = (ans + nC2(leftCount) * nC2(rightOther) % MOD) % MOD;
            ans = (ans + nC2(leftOther) * nC2(rightCount) % MOD) % MOD;
            ans = (ans + leftCount * leftOther % MOD * rightCount % MOD * rightOther % MOD) % MOD;
            ans = (ans + leftCount * calc(num, leftOther, rightOther, left, right) % MOD) % MOD;
            ans = (ans + rightCount * calc(num, rightOther, leftOther, right, left) % MOD) % MOD;
            left.merge(num, 1, Integer::sum);
        }
        return (int) (ans % MOD);
    }
}

import java.util.*;

class Solution {
    public static int countPathsXor(int[][] grid, int k) {
        final int MOD = 1_000_000_007;
        int m = grid.length;
        int n = grid[0].length;
        int maxVal = 0;
        for (int[] row : grid) {
            for (int v : row) {
                if (v > maxVal) maxVal = v;
            }
        }
        int maxXor = 1;
        while (maxXor <= maxVal) maxXor <<= 1;
        maxXor <<= 1; // accommodate possible XOR combinations
        if (k >= maxXor) return 0;
        int[][] dpPrev = new int[n][maxXor];
        dpPrev[0][grid[0][0]] = 1;
        for (int j = 1; j < n; ++j) {
            int val = grid[0][j];
            int[] left = dpPrev[j - 1];
            int[] cur = dpPrev[j];
            for (int x = 0; x < maxXor; ++x) {
                int cnt = left[x];
                if (cnt != 0) {
                    int nx = x ^ val;
                    cur[nx] = (cur[nx] + cnt) % MOD;
                }
            }
        }
        for (int i = 1; i < m; ++i) {
            int[][] dpCurr = new int[n][maxXor];
            int valFirst = grid[i][0];
            int[] aboveFirst = dpPrev[0];
            for (int x = 0; x < maxXor; ++x) {
                int cnt = aboveFirst[x];
                if (cnt != 0) {
                    int nx = x ^ valFirst;
                    dpCurr[0][nx] = (dpCurr[0][nx] + cnt) % MOD;
                }
            }
            for (int j = 1; j < n; ++j) {
                int val = grid[i][j];
                int[] cur = dpCurr[j];
                int[] above = dpPrev[j];
                int[] left = dpCurr[j - 1];
                for (int x = 0; x < maxXor; ++x) {
                    int cnt = above[x];
                    if (cnt != 0) {
                        int nx = x ^ val;
                        cur[nx] = (cur[nx] + cnt) % MOD;
                    }
                }
                for (int x = 0; x < maxXor; ++x) {
                    int cnt = left[x];
                    if (cnt != 0) {
                        int nx = x ^ val;
                        cur[nx] = (cur[nx] + cnt) % MOD;
                    }
                }
            }
            dpPrev = dpCurr;
        }
        return dpPrev[n - 1][k];
    }
}

