public class Solution {
    public static int minLength(String s, int numOps) {
        int n = s.length();
        int[] runs = new int[n];
        int runCount = 0;
        int i = 0;
        while (i < n) {
            char c = s.charAt(i);
            int j = i;
            while (j < n && s.charAt(j) == c) j++;
            runs[runCount++] = j - i;
            i = j;
        }
        int lo = 1, hi = n;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            long needed = 0;
            int limit = mid + 1;
            for (int k = 0; k < runCount; k++) {
                needed += runs[k] / limit;
                if (needed > numOps) break;
            }
            if (needed <= numOps) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        return lo;
    }
}

class Solution {
    public static long minOperations(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return 0L;
        }
        int m = grid.length;
        int n = grid[0].length;
        long total = 0L;
        for (int col = 0; col < n; col++) {
            int prev = grid[0][col];
            for (int row = 1; row < m; row++) {
                long required = (long) prev + 1;
                int val = grid[row][col];
                if (val < required) {
                    total += required - val;
                    prev = (int) required;
                } else {
                    prev = val;
                }
            }
        }
        return total;
    }
}

