class Solution {
    public static int maxDistinctElements(int[] nums, int k) {
        Arrays.sort(nums);
        long current = Long.MIN_VALUE;
        int distinct = 0;
        for (int a : nums) {
            long left = (long) a - k;
            long right = (long) a + k;
            long candidate = Math.max(left, current);
            if (candidate <= right) {
                distinct++;
                current = candidate + 1;
            }
        }
        return distinct;
    }
}

