public class Solution {
    public static int smallestLongestSubstring(String s, int numOps) {
        int n = s.length();
        char[] arr = s.toCharArray();
        int low = 1, high = n, ans = n;
        while (low <= high) {
            int mid = (low + high) >>> 1;
            if (canAchieve(arr, n, numOps, mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }

    private static boolean canAchieve(char[] arr, int n, int numOps, int limit) {
        int flips = 0;
        char cur = arr[0];
        int run = 1;
        for (int i = 1; i < n; i++) {
            char ch = arr[i];
            if (ch == cur) {
                run++;
            } else {
                cur = ch;
                run = 1;
            }
            if (run > limit) {
                flips++;
                cur = (cur == '0') ? '1' : '0';
                run = 1;
                if (flips > numOps) {
                    return false;
                }
            }
        }
        return flips <= numOps;
    }
}

