class Solution {
    public static String findLexicographicallyLargestString(String word, int numFriends) {
        int n = word.length();
        int len = n - (numFriends - 1);
        int bestIdx = 0;
        for (int i = 1; i <= n - len; i++) {
            if (compare(word, i, bestIdx, len) > 0) {
                bestIdx = i;
            }
        }
        return word.substring(bestIdx, bestIdx + len);
    }

    private static int compare(String s, int i1, int i2, int len) {
        for (int k = 0; k < len; k++) {
            char c1 = s.charAt(i1 + k);
            char c2 = s.charAt(i2 + k);
            if (c1 != c2) {
                return c1 - c2;
            }
        }
        return 0;
    }
}

