class Solution {
    public long numberOfSubsequences(int[] nums) {
        int n = nums.length;
        Map<Integer,Integer>[] suffix = new HashMap[n + 1];
        suffix[n] = new HashMap<>();
        for (int i = n - 1; i >= 0; i--) {
            suffix[i] = new HashMap<>(suffix[i + 1]);
            suffix[i].merge(nums[i], 1, Integer::sum);
        }
        // leftCount lags behind q by one step: when processing q, it holds frequencies for p in [0, q-2]
        Map<Integer,Integer> leftCount = new HashMap<>();
        long ans = 0;
        for (int q = 0; q < n; q++) {
            for (int r = q + 2; r < n; r++) {
                Map<Integer,Integer> rightCount = (r + 2 <= n) ? suffix[r + 2] : suffix[n];
                long a = nums[q], b = nums[r];
                // condition: nums[p]*nums[r] == nums[q]*nums[s]  =>  s-value = v*b/a for each left value v
                for (Map.Entry<Integer,Integer> e : leftCount.entrySet()) {
                    long v = e.getKey(), cntV = e.getValue();
                    long num = v * b;
                    if (num % a == 0) {
                        long target = num / a;
                        Integer rc = rightCount.get((int) target);
                        if (rc != null) ans += cntV * rc;
                    }
                }
            }
            int idx = q - 1;
            if (idx >= 0) leftCount.merge(nums[idx], 1, Integer::sum);
        }
        return ans;
    }
}

