class Solution {
    public static boolean substringMatchingPattern(String s, String p) {
        int starPos = p.indexOf('*');
        String pre = p.substring(0, starPos);
        String suf = p.substring(starPos + 1);
        if (pre.isEmpty() && suf.isEmpty()) return true;
        if (pre.isEmpty()) return s.indexOf(suf) != -1;
        if (suf.isEmpty()) return s.indexOf(pre) != -1;
        int start = 0;
        while (true) {
            int preIdx = s.indexOf(pre, start);
            if (preIdx == -1) break;
            int after = preIdx + pre.length();
            if (s.indexOf(suf, after) != -1) return true;
            start = preIdx + 1;
        }
        return false;
    }
}

public class Solution {
    private static final long MOD = 1_000_000_007L;

    public static int countArrays(int n, int m, int k) {
        if (k < 0 || k > n - 1) return 0;
        int limit = n;
        long[] fact = new long[limit];
        fact[0] = 1;
        for (int i = 1; i < limit; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        long denom = fact[k] * fact[n - 1 - k] % MOD;
        long comb = fact[n - 1] * modPow(denom, MOD - 2) % MOD;
        long pow = modPow(m - 1L, n - 1 - k);
        long ans = comb * (m % MOD) % MOD * pow % MOD;
        return (int) ans;
    }

    private static long modPow(long base, long exp) {
        long result = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) result = result * base % MOD;
            base = base * base % MOD;
            exp >>= 1;
        }
        return result;
    }
}

import java.util.*;
class TaskManager {
    static class Node {
        int userId, taskId, priority;
        Node(int u, int t, int p) { userId=u; taskId=t; priority=p; }
    }
    ArrayList<Node> heap = new ArrayList<>();
    Map<Integer, Node> taskMap = new HashMap<>();
    boolean less(Node a, Node b) {
        if (a.priority != b.priority) return a.priority > b.priority;
        return a.taskId > b.taskId;
    }
    void swap(int i, int j) { Node t=heap.get(i); heap.set(i,heap.get(j)); heap.set(j,t); }
    void heapifyUp(int i) {
        while (i>0) { int p=(i-1)>>1; if (less(heap.get(i),heap.get(p))) { swap(i,p); i=p; } else break; }
    }
    void heapifyDown(int i) {
        int n = heap.size();
        while (true) {
            int l=i*2+1,r=i*2+2,best=i;
            if (l<n && less(heap.get(l),heap.get(best))) best=l;
            if (r<n && less(heap.get(r),heap.get(best))) best=r;
            if (best==i) break;
            swap(i,best); i=best;
        }
    }
    void push(Node node) { heap.add(node); heapifyUp(heap.size()-1); }
    Node pop() {
        Node top = heap.get(0);
        Node last = heap.remove(heap.size()-1);
        if (!heap.isEmpty()) { heap.set(0,last); heapifyDown(0); }
        return top;
    }
    public TaskManager(List<int[]> initialTasks) {
        for (int[] t : initialTasks) {
            Node node = new Node(t[0], t[1], t[2]);
            taskMap.put(t[1], node);
            push(node);
        }
    }
    public void add(int userId, int taskId, int priority) {
        Node node = new Node(userId, taskId, priority);
        taskMap.put(taskId, node);
        push(node);
    }
    public void edit(int taskId, int newPriority) {
        Node n = taskMap.get(taskId);
        if (n != null) {
            Node updated = new Node(n.userId, n.taskId, newPriority);
            taskMap.put(taskId, updated);
            push(updated);
        }
    }
    public void rmv(int taskId) { taskMap.remove(taskId); }
    public int execTop() {
        while (!heap.isEmpty()) {
            Node top = pop();
            Node cur = taskMap.get(top.taskId);
            if (cur == top) {
                taskMap.remove(top.taskId);
                return top.userId;
            }
        }
        return -1;
    }
}

import java.util.HashSet;
import java.util.Set;

class Solution {
    public static int maxSubarraySumAfterRemoval(int[] nums) {
        int cur = 0;
        int best = Integer.MIN_VALUE;
        for (int x : nums) {
            cur = Math.max(cur + x, x);
            best = Math.max(best, cur);
        }
        int answer = best;
        Set<Integer> distinct = new HashSet<>();
        for (int x : nums) {
            if (x <= 0) {
                distinct.add(x);
            }
        }
        for (int v : distinct) {
            int curV = 0;
            int bestV = Integer.MIN_VALUE;
            boolean hasNonV = false;
            for (int x : nums) {
                int val = (x == v) ? 0 : x;
                if (x != v) {
                    hasNonV = true;
                }
                curV = Math.max(curV + val, val);
                bestV = Math.max(bestV, curV);
            }
            if (hasNonV) {
                answer = Math.max(answer, bestV);
            }
        }
        return answer;
    }
}

import java.util.*;

class Solution {
    private static class Interval {
        long l, r, c;
        Interval(long l, long r, long c) {
            this.l = l;
            this.r = r;
            this.c = c;
        }
    }

    private static class Segment {
        long len, val;
        Segment(long len, long val) {
            this.len = len;
            this.val = val;
        }
    }

    public static long maxCoins(int[][] coins, int k) {
        int n = coins.length;
        Interval[] intervals = new Interval[n];
        for (int i = 0; i < n; i++) {
            intervals[i] = new Interval(coins[i][0], coins[i][1], coins[i][2]);
        }
        Arrays.sort(intervals, Comparator.comparingLong(a -> a.l));

        Deque<Segment> dq = new ArrayDeque<>();
        long curLen = 0;
        long curSum = 0;
        long maxSum = 0;
        long kLong = k;

        for (int i = 0; i < n; i++) {
            long gap = (i == 0) ? intervals[i].l - 1 : intervals[i].l - intervals[i - 1].r - 1;
            if (gap > 0) {
                dq.addLast(new Segment(gap, 0));
                curLen += gap;
                while (curLen > kLong) {
                    Segment front = dq.peekFirst();
                    long excess = curLen - kLong;
                    if (front.len <= excess) {
                        curLen -= front.len;
                        dq.pollFirst();
                    } else {
                        front.len -= excess;
                        curLen -= excess;
                        break;
                    }
                }
                if (curLen == kLong) {
                    maxSum = Math.max(maxSum, curSum);
                }
            }

            long segLen = intervals[i].r - intervals[i].l + 1;
            long val = intervals[i].c;
            dq.addLast(new Segment(segLen, val));
            curLen += segLen;
            curSum += segLen * val;

            while (curLen > kLong) {
                Segment front = dq.peekFirst();
                long excess = curLen - kLong;
                if (front.len <= excess) {
                    curLen -= front.len;
                    curSum -= front.len * front.val;
                    dq.pollFirst();
                } else {
                    front.len -= excess;
                    curLen -= excess;
                    curSum -= excess * front.val;
                    break;
                }
            }
            if (curLen == kLong) {
                maxSum = Math.max(maxSum, curSum);
            }
        }
        return maxSum;
    }
}

