public class Solution {
    public int longestProductEquivalentSubarray(int[] nums) {
        int n = nums.length;
        int[] primes = {2, 3, 5, 7};
        int pCount = primes.length;
        int[][] exps = new int[n][pCount];
        for (int i = 0; i < n; i++) {
            int val = nums[i];
            for (int j = 0; j < pCount; j++) {
                int p = primes[j];
                int cnt = 0;
                while (val % p == 0) {
                    cnt++;
                    val /= p;
                }
                exps[i][j] = cnt;
            }
        }
        int best = 0;
        for (int l = 0; l < n; l++) {
            int[] sum = new int[pCount];
            int[] max = new int[pCount];
            int[] min = new int[pCount];
            Arrays.fill(min, Integer.MAX_VALUE);
            for (int r = l; r < n; r++) {
                for (int j = 0; j < pCount; j++) {
                    int e = exps[r][j];
                    sum[j] += e;
                    if (e > max[j]) max[j] = e;
                    if (e < min[j]) min[j] = e;
                }
                boolean ok = true;
                for (int j = 0; j < pCount; j++) {
                    if (sum[j] == 0) continue;
                    if (sum[j] != max[j] + min[j]) {
                        ok = false;
                        break;
                    }
                }
                if (ok) {
                    int len = r - l + 1;
                    if (len > best) best = len;
                }
            }
        }
        return best;
    }
}

import java.util.*;

public class Solution {
    public int longestSubsequence(int[] nums) {
        int n = nums.length;
        int MAXD = 300; // maximum possible absolute difference (values are ≤300)
        int[][] dp = new int[n][MAXD + 1];
        int[][] suff = new int[n][MAXD + 1];
        int answer = 1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                int diff = Math.abs(nums[i] - nums[j]);
                int prev = suff[j][diff];
                if (prev == 0) prev = 1; // start from a single element subsequence
                int newLen = prev + 1;
                if (newLen > dp[i][diff]) dp[i][diff] = newLen;
                if (newLen > answer) answer = newLen;
            }
            int curMax = 0;
            for (int d = MAXD; d >= 0; d--) {
                if (dp[i][d] > curMax) curMax = dp[i][d];
                suff[i][d] = curMax;
            }
        }
        return answer;
    }
}

