public class Solution {
    public static long mirrorScore(String s) {
        int[][] stacks = new int[26][];
        int[] sizes = new int[26];
        long score = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            int idx = c - 'a';
            int mirrorIdx = 'z' - c;
            if (sizes[mirrorIdx] > 0) {
                int pos = stacks[mirrorIdx][--sizes[mirrorIdx]];
                score += i - pos;
            } else {
                if (stacks[idx] == null) {
                    stacks[idx] = new int[16];
                } else if (sizes[idx] == stacks[idx].length) {
                    int[] newArr = new int[stacks[idx].length << 1];
                    System.arraycopy(stacks[idx], 0, newArr, 0, stacks[idx].length);
                    stacks[idx] = newArr;
                }
                stacks[idx][sizes[idx]++] = i;
            }
        }
        return score;
    }
}

import java.util.*;

class Solution {
    public static int[] maxScore(int[][] intervals) {
        int n = intervals.length;
        class Interval {
            int l, r;
            long w;
            int idx;
            Interval(int l, int r, long w, int idx) {
                this.l = l;
                this.r = r;
                this.w = w;
                this.idx = idx;
            }
        }
        Interval[] arr = new Interval[n];
        for (int i = 0; i < n; i++) {
            arr[i] = new Interval(intervals[i][0], intervals[i][1], intervals[i][2], i);
        }
        Arrays.sort(arr, (a, b) -> {
            if (a.l != b.l) return Integer.compare(a.l, b.l);
            return Integer.compare(a.r, b.r);
        });
        int[] start = new int[n];
        int[] end = new int[n];
        long[] weight = new long[n];
        int[] origIdx = new int[n];
        for (int i = 0; i < n; i++) {
            start[i] = arr[i].l;
            end[i] = arr[i].r;
            weight[i] = arr[i].w;
            origIdx[i] = arr[i].idx;
        }
        int[] nextIdx = new int[n];
        for (int i = 0; i < n; i++) {
            int lo = i + 1, hi = n;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (start[mid] > end[i]) hi = mid;
                else lo = mid + 1;
            }
            nextIdx[i] = lo;
        }
        long[][] dpWeight = new long[n + 1][5];
        int[][] dpLen = new int[n + 1][5];
        int[][][] dpIdx = new int[n + 1][5][4];
        for (int i = n - 1; i >= 0; i--) {
            for (int c = 0; c <= 4; c++) {
                long bestW = dpWeight[i + 1][c];
                int bestL = dpLen[i + 1][c];
                int[] bestArr = new int[4];
                System.arraycopy(dpIdx[i + 1][c], 0, bestArr, 0, bestL);
                if (c > 0) {
                    int nxt = nextIdx[i];
                    long takeW = weight[i] + dpWeight[nxt][c - 1];
                    int takeL = 1 + dpLen[nxt][c - 1];
                    int[] takeArr = new int[4];
                    int insertPos = 0;
                    while (insertPos < dpLen[nxt][c - 1] && dpIdx[nxt][c - 1][insertPos] < origIdx[i]) {
                        insertPos++;
                    }
                    for (int p = 0; p < insertPos; p++) {
                        takeArr[p] = dpIdx[nxt][c - 1][p];
                    }
                    takeArr[insertPos] = origIdx[i];
                    for (int p = insertPos; p < dpLen[nxt][c - 1]; p++) {
                        takeArr[p + 1] = dpIdx[nxt][c - 1][p];
                    }
                    boolean takeBetter;
                    if (takeW != bestW) {
                        takeBetter = takeW > bestW;
                    } else {
                        takeBetter = isLexicographicallySmaller(takeArr, takeL, bestArr, bestL);
                    }
                    if (takeBetter) {
                        bestW = takeW;
                        bestL = takeL;
                        bestArr = takeArr;
                    }
                }
                dpWeight[i][c] = bestW;
                dpLen[i][c] = bestL;
                for (int p = 0; p < bestL; p++) {
                    dpIdx[i][c][p] = bestArr[p];
                }
            }
        }
        int finalLen = dpLen[0][4];
        int[] result = new int[finalLen];
        for (int i = 0; i < finalLen; i++) {
            result[i] = dpIdx[0][4][i];
        }
        return result;
    }

    private static boolean isLexicographicallySmaller(int[] a, int lenA, int[] b, int lenB) {
        int min = Math.min(lenA, lenB);
        for (int i = 0; i < min; i++) {
            if (a[i] != b[i]) return a[i] < b[i];
        }
        return lenA < lenB;
    }
}

class Solution {
    public int minMaxWeight(int n, int[][] edges, int threshold) {
        List<int[]>[] rev = new List[n];
        for (int i = 0; i < n; i++) rev[i] = new ArrayList<>();
        int maxW = 0;
        for (int[] e : edges) {
            rev[e[1]].add(new int[]{e[0], e[2]});
            maxW = Math.max(maxW, e[2]);
        }
        if (!feasible(rev, n, maxW)) return -1;
        int lo = 1, hi = maxW;
        while (lo < hi) {
            int mid = lo + (hi-lo)/2;
            if (feasible(rev, n, mid)) hi = mid; else lo = mid+1;
        }
        return lo;
    }

    private boolean feasible(List<int[]>[] rev, int n, int W) {
        boolean[] visited = new boolean[n];
        visited[0] = true;
        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(0);
        int count = 1;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int[] p : rev[u]) {
                int v = p[0], w = p[1];
                if (w <= W && !visited[v]) {
                    visited[v] = true;
                    count++;
                    q.add(v);
                }
            }
        }
        return count == n;
    }
}

import java.util.ArrayList;
import java.util.List;

class Solution {
    public static List<Integer> zigzagGridTraversal(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return new ArrayList<>();
        }
        int rows = grid.length;
        int cols = grid[0].length;
        int capacity = (rows * cols + 1) / 2;
        List<Integer> result = new ArrayList<>(capacity);
        for (int i = 0; i < rows; i++) {
            boolean take = (i % 2 == 0);
            for (int j = 0; j < cols; j++) {
                if (take) {
                    result.add(grid[i][j]);
                }
                take = !take;
            }
        }
        return result;
    }
}

