class Solution {
    public static long countNonDecreasingSubarrays(int[] nums, int k) {
        int n = nums.length;
        long answer = 0;
        for (int i = 0; i < n; i++) {
            int curMax = nums[i];
            long cost = 0;
            answer++;
            for (int j = i + 1; j < n; j++) {
                if (nums[j] >= curMax) {
                    curMax = nums[j];
                } else {
                    cost += curMax - nums[j];
                    if (cost > k) break;
                }
                answer++;
            }
        }
        return answer;
    }
}

