class Solution {
    public static long maxProfit(int[][] coins) {
        int m = coins.length;
        int n = coins[0].length;
        long NEG = Long.MIN_VALUE / 4;
        long[][] prev = new long[n][3];
        long[][] cur = new long[n][3];
        for (int i = 0; i < n; i++) {
            Arrays.fill(prev[i], NEG);
            Arrays.fill(cur[i], NEG);
        }
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                for (int k = 0; k <= 2; k++) {
                    long best = NEG;
                    if (i == 0 && j == 0) {
                        if (k == 0) {
                            best = coins[0][0];
                        } else if (k == 1) {
                            best = 0;
                        }
                    } else {
                        if (i > 0) {
                            long fromTop = prev[j][k];
                            if (fromTop != NEG) best = Math.max(best, fromTop + coins[i][j]);
                            if (k > 0) {
                                long skipTop = prev[j][k - 1];
                                if (skipTop != NEG) best = Math.max(best, skipTop);
                            }
                        }
                        if (j > 0) {
                            long fromLeft = cur[j - 1][k];
                            if (fromLeft != NEG) best = Math.max(best, fromLeft + coins[i][j]);
                            if (k > 0) {
                                long skipLeft = cur[j - 1][k - 1];
                                if (skipLeft != NEG) best = Math.max(best, skipLeft);
                            }
                        }
                    }
                    cur[j][k] = best;
                }
            }
            long[][] temp = prev;
            prev = cur;
            cur = temp;
            for (int j = 0; j < n; j++) {
                Arrays.fill(cur[j], NEG);
            }
        }
        long ans = NEG;
        for (int k = 0; k <= 2; k++) {
            ans = Math.max(ans, prev[n - 1][k]);
        }
        return ans;
    }
}

class Solution {
    public static int maxCircularAdjacentDiff(int[] nums) {
        if (nums == null || nums.length < 2) return 0;
        int maxDiff = 0;
        for (int i = 0, n = nums.length; i < n; i++) {
            int next = (i + 1) % n;
            int diff = nums[i] - nums[next];
            if (diff < 0) diff = -diff;
            if (diff > maxDiff) maxDiff = diff;
        }
        return maxDiff;
    }
}

import java.util.Arrays;

class Solution {
    private static final int MOD = 1_000_000_007;

    public long maxMinSum(int[] nums, int k) {
        int n = nums.length;
        Arrays.sort(nums);
        int maxR = k - 1;
        int[][] C = new int[n + 1][k];
        C[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            C[i][0] = 1;
            int limit = Math.min(maxR, i);
            for (int r = 1; r <= limit; r++) {
                int val = C[i - 1][r] + C[i - 1][r - 1];
                if (val >= MOD) val -= MOD;
                C[i][r] = val;
            }
        }
        long ans = 0;
        for (int i = 0; i < n; i++) {
            long sumLeft = 0;
            int limitL = Math.min(maxR, i);
            for (int r = 0; r <= limitL; r++) {
                sumLeft += C[i][r];
            }
            long sumRight = 0;
            int rightCount = n - 1 - i;
            int limitR = Math.min(maxR, rightCount);
            for (int r = 0; r <= limitR; r++) {
                sumRight += C[rightCount][r];
            }
            long contrib = (sumLeft + sumRight) % MOD;
            ans = (ans + (nums[i] % MOD) * contrib) % MOD;
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    private static class Edge {
        int to;
        int len;
        Edge(int t, int l) {
            this.to = t;
            this.len = l;
        }
    }

    private static class Frame {
        int node;
        int parent;
        int depth;
        long prefix;
        int startDepth;
        int childIdx;
        int prevDepth;
        boolean entered;
        Frame(int node, int parent, int depth, long prefix, int startDepth) {
            this.node = node;
            this.parent = parent;
            this.depth = depth;
            this.prefix = prefix;
            this.startDepth = startDepth;
            this.childIdx = 0;
            this.prevDepth = -1;
            this.entered = false;
        }
    }

    public static long[] longestSpecialPath(int[][] edges, int[] nums) {
        int n = nums.length;
        List<Edge>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0], v = e[1], w = e[2];
            adj[u].add(new Edge(v, w));
            adj[v].add(new Edge(u, w));
        }

        Map<Integer, Integer> comp = new HashMap<>();
        int idx = 0;
        for (int v : nums) {
            if (!comp.containsKey(v)) comp.put(v, idx++);
        }
        int[] lastPos = new int[idx];
        Arrays.fill(lastPos, -1);

        long[] prefix = new long[n];
        long bestLen = 0;
        int bestNodes = 1;

        Deque<Frame> stack = new ArrayDeque<>();
        stack.push(new Frame(0, -1, 0, 0L, 0));

        while (!stack.isEmpty()) {
            Frame f = stack.peek();
            if (!f.entered) {
                int val = nums[f.node];
                int compIdx = comp.get(val);
                int prev = lastPos[compIdx];
                f.prevDepth = prev;
                int newStart = Math.max(f.startDepth, prev + 1);
                f.startDepth = newStart;

                prefix[f.depth] = f.prefix;
                long curLen = f.prefix - prefix[newStart];
                int nodesCnt = f.depth - newStart + 1;

                if (curLen > bestLen) {
                    bestLen = curLen;
                    bestNodes = nodesCnt;
                } else if (curLen == bestLen && nodesCnt < bestNodes) {
                    bestNodes = nodesCnt;
                }

                lastPos[compIdx] = f.depth;
                f.entered = true;
            } else if (f.childIdx < adj[f.node].size()) {
                Edge e = adj[f.node].get(f.childIdx++);
                if (e.to == f.parent) continue;
                stack.push(new Frame(e.to, f.node, f.depth + 1, f.prefix + e.len, f.startDepth));
            } else {
                int val = nums[f.node];
                int compIdx = comp.get(val);
                if (f.prevDepth == -1) {
                    lastPos[compIdx] = -1;
                } else {
                    lastPos[compIdx] = f.prevDepth;
                }
                stack.pop();
            }
        }

        return new long[]{bestLen, bestNodes};
    }
}

import java.util.*;

public class Solution {
    private static final long MOD = 1_000_000_007L;

    private static long modPow(long a, long e) {
        long res = 1L;
        a %= MOD;
        while (e > 0) {
            if ((e & 1) == 1) res = (res * a) % MOD;
            a = (a * a) % MOD;
            e >>= 1;
        }
        return res;
    }

    public static long totalManhattanDistance(int m, int n, int k) {
        long N = (long) m * n;
        if (k < 2 || k > N) return 0L;

        int max = (int) N;
        long[] fact = new long[max + 1];
        long[] invFact = new long[max + 1];
        fact[0] = 1L;
        for (int i = 1; i <= max; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[max] = modPow(fact[max], MOD - 2);
        for (int i = max; i > 0; i--) {
            invFact[i - 1] = invFact[i] * i % MOD;
        }

        long comb = fact[(int) (N - 2)] * invFact[k - 2] % MOD * invFact[(int) (N - k)] % MOD;

        long inv6 = modPow(6, MOD - 2);
        long mMod = m % MOD;
        long nMod = n % MOD;

        long mCubed = mMod * mMod % MOD * mMod % MOD;
        long nCubed = nMod * nMod % MOD * nMod % MOD;

        long rowDiff = (mCubed - mMod + MOD) % MOD * inv6 % MOD;
        long colDiff = (nCubed - nMod + MOD) % MOD * inv6 % MOD;

        long nSq = nMod * nMod % MOD;
        long mSq = mMod * mMod % MOD;

        long totalDist = (nSq * rowDiff % MOD + mSq * colDiff % MOD) % MOD;

        return totalDist * comb % MOD;
    }
}

