class Solution {
    public int minCost(int n, int[][] cost) {
        int half = n / 2;
        Map<Long, Long> dp = new HashMap<>();
        for (int cL = 0; cL < 3; cL++) for (int cR = 0; cR < 3; cR++) if (cL != cR) {
            dp.put((long) cL * 10 + cR, (long) cost[0][cL] + cost[n - 1][cR]);
        }
        for (int i = 1; i < half; i++) {
            int j = n - 1 - i;
            Map<Long, Long> newDp = new HashMap<>();
            for (int cL = 0; cL < 3; cL++) for (int cR = 0; cR < 3; cR++) {
                if (cL == cR) continue;
                long best = Long.MAX_VALUE;
                for (int pL = 0; pL < 3; pL++) for (int pR = 0; pR < 3; pR++) {
                    if (pL == pR || pL == cL || pR == cR) continue;
                    Long v = dp.get((long) pL * 10 + pR);
                    if (v != null) best = Math.min(best, v);
                }
                if (best < Long.MAX_VALUE) newDp.put((long) cL * 10 + cR, best + cost[i][cL] + cost[j][cR]);
            }
            dp = newDp;
        }
        long ans = Long.MAX_VALUE;
        for (long v : dp.values()) ans = Math.min(ans, v);
        return (int) ans;
    }
}

import java.util.*;

class Solution {
    public static long maxMinSumAtMostK(int[] nums, int k) {
        int n = nums.length;
        int[] leftGreater = new int[n];
        int[] rightGreater = new int[n];
        int[] leftSmaller = new int[n];
        int[] rightSmaller = new int[n];
        int[] stack = new int[n];
        int top;

        top = 0;
        for (int i = 0; i < n; i++) {
            while (top > 0 && nums[stack[top - 1]] <= nums[i]) top--;
            leftGreater[i] = (top > 0) ? stack[top - 1] : -1;
            stack[top++] = i;
        }

        top = 0;
        for (int i = n - 1; i >= 0; i--) {
            while (top > 0 && nums[stack[top - 1]] < nums[i]) top--;
            rightGreater[i] = (top > 0) ? stack[top - 1] : n;
            stack[top++] = i;
        }

        top = 0;
        for (int i = 0; i < n; i++) {
            while (top > 0 && nums[stack[top - 1]] >= nums[i]) top--;
            leftSmaller[i] = (top > 0) ? stack[top - 1] : -1;
            stack[top++] = i;
        }

        top = 0;
        for (int i = n - 1; i >= 0; i--) {
            while (top > 0 && nums[stack[top - 1]] > nums[i]) top--;
            rightSmaller[i] = (top > 0) ? stack[top - 1] : n;
            stack[top++] = i;
        }

        final int S = k + 1;
        long ans = 0L;
        for (int i = 0; i < n; i++) {
            int Lmax = i - leftGreater[i];
            int Rmax = rightGreater[i] - i;
            long pairsMax = countPairs(Lmax, Rmax, S);
            ans += (long) nums[i] * pairsMax;

            int Lmin = i - leftSmaller[i];
            int Rmin = rightSmaller[i] - i;
            long pairsMin = countPairs(Lmin, Rmin, S);
            ans += (long) nums[i] * pairsMin;
        }
        return ans;
    }

    private static long countPairs(int L, int R, int S) {
        int limit = S - R;
        long a = 0L;
        if (limit > 0) a = Math.min(L, limit);
        long cnt = a * R;
        int start = (int) (a + 1);
        int end = Math.min(L, S - 1);
        if (start <= end) {
            long num = end - start + 1L;
            long sum = num * S - ((long) (start + end) * num) / 2L;
            cnt += sum;
        }
        return cnt;
    }
}

import java.util.*;

public class Solution {
    private static final class Pair {
        long value;
        int index;
        Pair(long v, int i) { this.value = v; this.index = i; }
    }

    public static long maxFreeTime(long eventTime, int k, long[] startTime, long[] endTime) {
        int n = startTime.length;
        int m = n + 1;
        long[] gaps = new long[m];
        gaps[0] = startTime[0];
        for (int i = 1; i < n; i++) {
            gaps[i] = startTime[i] - endTime[i - 1];
        }
        gaps[m - 1] = eventTime - endTime[n - 1];
        long totalFree = 0;
        for (long g : gaps) totalFree += g;
        if (k >= m - 1) return totalFree;
        Pair[] sorted = new Pair[m];
        for (int i = 0; i < m; i++) {
            sorted[i] = new Pair(gaps[i], i);
        }
        Arrays.sort(sorted, (a, b) -> Long.compare(b.value, a.value));
        long[] prefix = new long[m + 1];
        for (int i = 0; i < m; i++) {
            prefix[i + 1] = prefix[i] + sorted[i].value;
        }
        int[] rank = new int[m];
        for (int i = 0; i < m; i++) {
            rank[sorted[i].index] = i;
        }
        long answer = 0;
        for (int i = 0; i < m; i++) {
            long sumTopK;
            if (rank[i] < k) {
                sumTopK = prefix[k + 1] - gaps[i];
            } else {
                sumTopK = prefix[k];
            }
            long candidate = gaps[i] + sumTopK;
            if (candidate > answer) answer = candidate;
        }
        return answer;
    }
}

