public class Solution {
    public static int maxFrequency(int[] nums, int k) {
        int n = nums.length;
        int totalK = 0;
        int[] delta = new int[n];
        for (int i = 0; i < n; i++) {
            if (nums[i] == k) totalK++;
            delta[i] = k - nums[i];
        }
        int maxGain = 0;
        for (int d = -50; d <= 50; d++) {
            if (d == 0) continue;
            int cur = 0, best = 0;
            for (int i = 0; i < n; i++) {
                int val = 0;
                if (delta[i] == d) {
                    val = 1;
                } else if (nums[i] == k) {
                    val = -1;
                }
                cur = Math.max(0, cur + val);
                best = Math.max(best, cur);
            }
            maxGain = Math.max(maxGain, best);
        }
        return totalK + maxGain;
    }
}

import java.util.*;

class Solution {
    public static int[][] frequencies(String[] words) {
        Set<Character> distinctSet = new LinkedHashSet<>();
        for (String w : words) {
            distinctSet.add(w.charAt(0));
            distinctSet.add(w.charAt(1));
        }
        int L = distinctSet.size();
        if (L == 0) return new int[0][0];
        List<Character> lettersList = new ArrayList<>(distinctSet);
        Map<Character, Integer> idx = new HashMap<>();
        for (int i = 0; i < L; i++) idx.put(lettersList.get(i), i);

        int[] outMask = new int[L];
        int mandatoryMask = 0;
        for (String w : words) {
            char a = w.charAt(0);
            char b = w.charAt(1);
            int ia = idx.get(a);
            int ib = idx.get(b);
            if (ia == ib) {
                mandatoryMask |= (1 << ia);
            } else {
                outMask[ia] |= (1 << ib);
            }
        }

        int totalMask = (1 << L) - 1;
        int INF = Integer.MAX_VALUE / 4;
        int[] dp = new int[1 << L];
        Arrays.fill(dp, INF);
        @SuppressWarnings("unchecked")
        List<Integer>[] badMasks = new List[1 << L];
        dp[0] = 0;
        badMasks[0] = new ArrayList<>();
        badMasks[0].add(0);

        for (int mask = 0; mask <= totalMask; mask++) {
            if (dp[mask] == INF) continue;
            for (int v = 0; v < L; v++) {
                if ((mask & (1 << v)) != 0) continue;
                boolean extraNeeded = ((mandatoryMask >> v) & 1) == 1 || (outMask[v] & mask) != 0;
                int add = extraNeeded ? 1 : 0;
                int newMask = mask | (1 << v);
                int newCost = dp[mask] + add;
                if (newCost < dp[newMask]) {
                    dp[newMask] = newCost;
                    badMasks[newMask] = new ArrayList<>();
                }
                if (newCost == dp[newMask]) {
                    for (int oldBad : badMasks[mask]) {
                        int newBad = oldBad;
                        if (extraNeeded) newBad |= (1 << v);
                        badMasks[newMask].add(newBad);
                    }
                }
            }
        }

        List<int[]> resultList = new ArrayList<>();
        for (int badMask : badMasks[totalMask]) {
            int[] freq = new int[26];
            for (int i = 0; i < L; i++) {
                char c = lettersList.get(i);
                int count = 1 + ((badMask >> i) & 1);
                freq[c - 'a'] = count;
            }
            resultList.add(freq);
        }

        List<int[]> uniqueList = new ArrayList<>();
        Set<String> seen = new HashSet<>();
        for (int[] arr : resultList) {
            String key = Arrays.toString(arr);
            if (seen.add(key)) {
                uniqueList.add(arr);
            }
        }

        int[][] result = new int[uniqueList.size()][];
        for (int i = 0; i < uniqueList.size(); i++) result[i] = uniqueList.get(i);
        return result;
    }
}

import java.util.*;

class Solution {
    public static String minCostGoodCaption(String caption) {
        int n = caption.length();
        if (n < 3) return "";
        final int INF = 1000000000;
        int[][][] dp = new int[n][26][3];
        for (int[][] row : dp) for (int[] arr : row) Arrays.fill(arr, INF);
        int[] minCostArr = new int[n];
        Arrays.fill(minCostArr, INF);

        for (int c = 0; c < 26; c++) dp[n-1][c][0] = Math.abs((caption.charAt(n-1)-'a') - c);
        int mc = INF;
        for (int c = 0; c < 26; c++) mc = Math.min(mc, dp[n-1][c][0]);
        minCostArr[n-1] = mc;

        for (int i = n-2; i >= 0; i--) {
            int newMinCost = INF;
            int ci = caption.charAt(i) - 'a';
            for (int c = 0; c < 26; c++) {
                int changeCost = Math.abs(ci - c);
                dp[i][c][0] = changeCost + minCostArr[i+1];
                dp[i][c][1] = changeCost + dp[i+1][c][0];
                dp[i][c][2] = changeCost + Math.min(dp[i+1][c][1], dp[i+1][c][2]);
                newMinCost = Math.min(newMinCost, dp[i][c][2]);
            }
            minCostArr[i] = newMinCost;
        }

        int bestCost = INF;
        for (int c = 0; c < 26; c++) bestCost = Math.min(bestCost, dp[0][c][2]);
        if (bestCost >= INF) return "";

        StringBuilder ans = new StringBuilder();
        int letter = -1;
        for (int c = 0; c < 26; c++) if (dp[0][c][2] == bestCost) { letter = c; break; }
        int k = 2;
        for (int i = 0; i < n; i++) {
            ans.append((char) ('a' + letter));
            int ci = caption.charAt(i) - 'a';
            int changeCost = Math.abs(ci - letter);
            if (k == 2) {
                int target = dp[i][letter][2];
                int remaining = target - changeCost;
                if (i+1 < n && dp[i+1][letter][1] == remaining) k = 1;
                else k = 2;
            } else if (k == 1) {
                k = 0;
            } else {
                if (i+1 < n) {
                    for (int c2 = 0; c2 < 26; c2++) {
                        if (dp[i+1][c2][2] == minCostArr[i+1]) { letter = c2; k = 2; break; }
                    }
                }
            }
        }
        return ans.toString();
    }
}

class Solution {
    public static int maxDiffEvenOdd(String s) {
        int[] freq = new int[26];
        for (int i = 0; i < s.length(); i++) {
            freq[s.charAt(i) - 'a']++;
        }
        int maxOdd = -1;
        int minEven = Integer.MAX_VALUE;
        for (int f : freq) {
            if (f == 0) continue;
            if ((f & 1) == 1) {
                if (f > maxOdd) maxOdd = f;
            } else {
                if (f < minEven) minEven = f;
            }
        }
        if (maxOdd == -1 || minEven == Integer.MAX_VALUE) return 0;
        return maxOdd - minEven;
    }
}

class Solution {
    public static String findValidPair(String s) {
        int[] freq = new int[10];
        for (int i = 0; i < s.length(); i++) {
            freq[s.charAt(i) - '0']++;
        }
        for (int i = 0; i + 1 < s.length(); i++) {
            char d1 = s.charAt(i);
            char d2 = s.charAt(i + 1);
            if (d1 != d2 && freq[d1 - '0'] == d1 - '0' && freq[d2 - '0'] == d2 - '0') {
                return "" + d1 + d2;
            }
        }
        return "";
    }
}

