public class Solution {
    public static int maxManhattanDistanceAfterKChanges(String s, int k) {
        int x = 0, y = 0;
        int inward = 0;
        int answer = 0;
        for (int i = 0; i < s.length(); ++i) {
            char c = s.charAt(i);
            boolean outward;
            if (c == 'N') outward = (y >= 0);
            else if (c == 'S') outward = (y <= 0);
            else if (c == 'E') outward = (x >= 0);
            else outward = (x <= 0);
            if (!outward) ++inward;
            if (c == 'N') ++y;
            else if (c == 'S') --y;
            else if (c == 'E') ++x;
            else --x;
            int dist = Math.abs(x) + Math.abs(y);
            int best = dist + 2 * Math.min(k, inward);
            if (best > answer) answer = best;
        }
        return answer;
    }
}

import java.util.Arrays;

public class Solution {
    private static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    public static long minimumIncrements(int[] nums, int[] target) {
        int n = nums.length;
        int m = target.length;
        int fullMask = (1 << m) - 1;
        long INF = Long.MAX_VALUE / 4;

        long[] lcmMask = new long[1 << m];
        lcmMask[0] = 1L;
        for (int mask = 1; mask <= fullMask; ++mask) {
            int bit = Integer.numberOfTrailingZeros(mask);
            int prev = mask ^ (1 << bit);
            long prevL = lcmMask[prev];
            long t = target[bit];
            long g = gcd(prevL, t);
            long div = prevL / g;
            if (div > INF / t) {
                lcmMask[mask] = INF;
            } else {
                long l = div * t;
                lcmMask[mask] = l > INF ? INF : l;
            }
        }

        long[] dp = new long[1 << m];
        Arrays.fill(dp, INF);
        dp[0] = 0L;

        long[] costMask = new long[1 << m];

        for (int val : nums) {
            long cur = val;
            for (int mask = 1; mask <= fullMask; ++mask) {
                long L = lcmMask[mask];
                if (L == INF) {
                    costMask[mask] = INF;
                } else {
                    long mult = (cur + L - 1) / L;
                    long nxt = mult * L;
                    long diff = nxt - cur;
                    costMask[mask] = diff > INF ? INF : diff;
                }
            }
            costMask[0] = 0L;

            long[] ndp = dp.clone();
            for (int mask = 0; mask <= fullMask; ++mask) {
                long base = dp[mask];
                if (base == INF) continue;
                int remain = fullMask ^ mask;
                int sub = remain;
                while (true) {
                    long cand = base + costMask[sub];
                    int nmask = mask | sub;
                    if (cand < ndp[nmask]) ndp[nmask] = cand;
                    if (sub == 0) break;
                    sub = (sub - 1) & remain;
                }
            }
            dp = ndp;
        }

        return dp[fullMask];
    }
}

import java.util.*;

class Solution {
    public static int maxFreeTime(int eventTime, int[] startTime, int[] endTime) {
        int n = startTime.length;
        if (n == 0) return eventTime;
        long[] gaps = new long[n + 1];
        gaps[0] = startTime[0];
        for (int i = 1; i < n; ++i) {
            gaps[i] = (long) startTime[i] - endTime[i - 1];
        }
        gaps[n] = (long) eventTime - endTime[n - 1];

        long[] prefixMax = new long[n + 1];
        long[] suffixMax = new long[n + 1];
        prefixMax[0] = gaps[0];
        for (int i = 1; i <= n; ++i) {
            prefixMax[i] = Math.max(prefixMax[i - 1], gaps[i]);
        }
        suffixMax[n] = gaps[n];
        for (int i = n - 1; i >= 0; --i) {
            suffixMax[i] = Math.max(suffixMax[i + 1], gaps[i]);
        }

        long currentMaxGap = 0;
        for (long g : gaps) {
            if (g > currentMaxGap) currentMaxGap = g;
        }
        long answer = currentMaxGap;

        for (int i = 0; i < n; ++i) {
            long left_gap = gaps[i];
            long right_gap = gaps[i + 1];
            long duration = (long) endTime[i] - startTime[i];
            long merged_gap = left_gap + duration + right_gap;

            long max_other_gap = 0;
            if (i - 1 >= 0) max_other_gap = Math.max(max_other_gap, prefixMax[i - 1]);
            if (i + 2 <= n) max_other_gap = Math.max(max_other_gap, suffixMax[i + 2]);

            long candidate;
            if (max_other_gap >= duration) {
                candidate = merged_gap;
            } else {
                candidate = Math.max(merged_gap - duration, max_other_gap);
            }
            if (candidate > answer) answer = candidate;
        }

        return (int) answer;
    }
}

import java.util.*;

class Solution {
    public static int[][] sortMatrixByDiagonals(int[][] grid) {
        int rows = grid.length;
        if (rows == 0) return grid;
        int cols = grid[0].length;

        // Diagonals starting from first column (descending order)
        for (int i = 0; i < rows; i++) {
            List<Integer> vals = new ArrayList<>();
            int r = i, c = 0;
            while (r < rows && c < cols) {
                vals.add(grid[r][c]);
                r++;
                c++;
            }
            vals.sort(Collections.reverseOrder());
            r = i;
            c = 0;
            int idx = 0;
            while (r < rows && c < cols) {
                grid[r][c] = vals.get(idx++);
                r++;
                c++;
            }
        }

        // Diagonals starting from first row (excluding the main diagonal) (ascending order)
        for (int j = 1; j < cols; j++) {
            List<Integer> vals = new ArrayList<>();
            int r = 0, c = j;
            while (r < rows && c < cols) {
                vals.add(grid[r][c]);
                r++;
                c++;
            }
            Collections.sort(vals);
            r = 0;
            c = j;
            int idx = 0;
            while (r < rows && c < cols) {
                grid[r][c] = vals.get(idx++);
                r++;
                c++;
            }
        }

        return grid;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static int[] assignElements(int[] groups, int[] elements) {
        Map<Integer, Integer> firstIdx = new HashMap<>();
        for (int i = 0; i < elements.length; i++) {
            int v = elements[i];
            firstIdx.putIfAbsent(v, i);
        }
        int[] result = new int[groups.length];
        for (int i = 0; i < groups.length; i++) {
            int g = groups[i];
            int best = Integer.MAX_VALUE;
            for (int d = 1; d * d <= g; d++) {
                if (g % d == 0) {
                    Integer idx1 = firstIdx.get(d);
                    if (idx1 != null && idx1 < best) best = idx1;
                    int d2 = g / d;
                    if (d2 != d) {
                        Integer idx2 = firstIdx.get(d2);
                        if (idx2 != null && idx2 < best) best = idx2;
                    }
                }
            }
            result[i] = (best == Integer.MAX_VALUE) ? -1 : best;
        }
        return result;
    }
}

import java.util.*;

public class Solution {
    public static int maxDifferenceEvenOdd(String s, int k) {
        int n = s.length();
        if (k > n) return -1;
        int evenCount = 0, oddCount = 0;
        for (int i = 0; i < k; i++) {
            int d = s.charAt(i) - '0';
            if ((d & 1) == 0) evenCount++;
            else oddCount++;
        }
        int best = -1;
        if (evenCount > 0 && oddCount > 0) {
            int diff = evenCount - oddCount;
            if (diff > 0) best = diff;
        }
        for (int i = k; i < n; i++) {
            int out = s.charAt(i - k) - '0';
            if ((out & 1) == 0) evenCount--;
            else oddCount--;
            int in = s.charAt(i) - '0';
            if ((in & 1) == 0) evenCount++;
            else oddCount++;
            if (evenCount > 0 && oddCount > 0) {
                int diff = evenCount - oddCount;
                if (diff > 0 && diff > best) best = diff;
            }
        }
        return best;
    }
}

public class Solution {
    public static long maxScore(int[] points, long m) {
        long maxP = 0;
        for (int v : points) {
            if (v > maxP) maxP = v;
        }
        long low = 0;
        long high = maxP * m;
        if (high < 0) high = Long.MAX_VALUE;
        while (low < high) {
            long mid = (low + high + 1) >>> 1;
            long need = 0;
            for (int v : points) {
                need += (mid + v - 1) / v;
                if (need > m) break;
            }
            if (need <= m) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return low;
    }
}

