class Solution {
    public static long countDivisibleSubstrings(String s) {
        long[][] cnt = new long[10][10];
        long[][] ndcnt = new long[10][10];
        long answer = 0;
        for (char ch : s.toCharArray()) {
            int cur = ch - '0';
            for (int d = 1; d <= 9; ++d) {
                for (int r = 0; r < d; ++r) {
                    long ways = cnt[d][r];
                    if (ways != 0) {
                        int nr = (r * 10 + cur) % d;
                        ndcnt[d][nr] += ways;
                    }
                }
                int nr = cur % d;
                ndcnt[d][nr] += 1;
            }
            if (cur != 0) {
                answer += ndcnt[cur][0];
            }
            long[][] temp = cnt;
            cnt = ndcnt;
            ndcnt = temp;
            for (int d = 1; d <= 9; ++d) {
                for (int r = 0; r < d; ++r) {
                    ndcnt[d][r] = 0;
                }
            }
        }
        return answer;
    }
}

public class Solution {
    public static int sumGoodNumbers(int[] nums, int k) {
        int n = nums.length;
        int total = 0;
        for (int i = 0; i < n; i++) {
            boolean good = true;
            int left = i - k;
            if (left >= 0 && nums[i] <= nums[left]) {
                good = false;
            }
            int right = i + k;
            if (right < n && nums[i] <= nums[right]) {
                good = false;
            }
            if (good) {
                total += nums[i];
            }
        }
        return total;
    }
}

import java.util.*;

public class Solution {
    public static double separateSquares(List<List<Integer>> squares) {
        double totalArea = 0.0;
        List<Event> events = new ArrayList<>();
        double minY = Double.POSITIVE_INFINITY;
        for (List<Integer> sq : squares) {
            double y = sq.get(1);
            double l = sq.get(2);
            totalArea += l * l;
            double bottom = y;
            double top = y + l;
            events.add(new Event(bottom, -l));
            events.add(new Event(top, l));
            if (bottom < minY) {
                minY = bottom;
            }
        }
        if (events.isEmpty()) {
            return 0.0;
        }
        double half = totalArea / 2.0;
        events.sort(Comparator.comparingDouble(e -> e.pos));
        double curHeight = minY;
        double curArea = totalArea;
        double curSlope = 0.0;
        int i = 0;
        double result = curHeight;
        while (i < events.size()) {
            double pos = events.get(i).pos;
            double nextArea = curArea + curSlope * (pos - curHeight);
            if (curArea >= half && nextArea <= half) {
                if (curSlope == 0) {
                    result = curHeight;
                } else {
                    result = curHeight + (half - curArea) / curSlope;
                }
                return Math.round(result * 100000.0) / 100000.0;
            }
            curArea = nextArea;
            curHeight = pos;
            while (i < events.size() && events.get(i).pos == pos) {
                curSlope += events.get(i).delta;
                i++;
            }
        }
        return Math.round(curHeight * 100000.0) / 100000.0;
    }

    private static class Event {
        double pos;
        double delta;
        Event(double pos, double delta) {
            this.pos = pos;
            this.delta = delta;
        }
    }
}

