class Solution {
    public static boolean findSpecialSubstring(String s, int k) {
        if (s == null || k <= 0 || k > s.length()) return false;
        if (k == 1) return true;
        int consecutive = 1;
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) == s.charAt(i - 1)) {
                consecutive++;
                if (consecutive >= k) return true;
            } else {
                consecutive = 1;
            }
        }
        return false;
    }
}

import java.util.Arrays;

class Solution {
    public static int shortestMatchingSubstring(String s, String p) {
        int first = p.indexOf('*');
        int second = p.indexOf('*', first + 1);
        String A = p.substring(0, first);
        String B = p.substring(first + 1, second);
        String C = p.substring(second + 1);
        int n = s.length();
        int lenA = A.length();
        int lenB = B.length();
        int lenC = C.length();

        boolean[] isBStart = new boolean[n + 1];
        boolean[] isCStart = new boolean[n + 1];

        if (B.isEmpty()) {
            Arrays.fill(isBStart, true);
        } else {
            for (int idx = s.indexOf(B, 0); idx != -1; idx = s.indexOf(B, idx + 1)) {
                isBStart[idx] = true;
            }
        }

        if (C.isEmpty()) {
            Arrays.fill(isCStart, true);
        } else {
            for (int idx = s.indexOf(C, 0); idx != -1; idx = s.indexOf(C, idx + 1)) {
                isCStart[idx] = true;
            }
        }

        int[] nextB = new int[n + 1];
        int[] nextC = new int[n + 1];
        int next = -1;
        for (int i = n; i >= 0; --i) {
            if (isBStart[i]) next = i;
            nextB[i] = next;
        }
        next = -1;
        for (int i = n; i >= 0; --i) {
            if (isCStart[i]) next = i;
            nextC[i] = next;
        }

        int best = Integer.MAX_VALUE;

        if (A.isEmpty()) {
            for (int i = 0; i <= n; ++i) {
                int posB = i + lenA;
                if (posB > n) continue;
                int j = nextB[posB];
                if (j == -1) continue;
                int posC = j + lenB;
                if (posC > n) continue;
                int k = nextC[posC];
                if (k == -1) continue;
                int len = (k + lenC) - i;
                if (len < best) best = len;
            }
        } else {
            for (int i = s.indexOf(A, 0); i != -1; i = s.indexOf(A, i + 1)) {
                int posB = i + lenA;
                if (posB > n) continue;
                int j = nextB[posB];
                if (j == -1) continue;
                int posC = j + lenB;
                if (posC > n) continue;
                int k = nextC[posC];
                if (k == -1) continue;
                int len = (k + lenC) - i;
                if (len < best) best = len;
            }
        }

        return best == Integer.MAX_VALUE ? -1 : best;
    }
}

