class Solution {
    private static int lowerBound(double[] arr, double target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (arr[m] < target) l = m + 1;
            else r = m;
        }
        return l;
    }

    private static class Event {
        double y;
        int type;
        double x1;
        double x2;
        Event(double y, int type, double x1, double x2) {
            this.y = y;
            this.type = type;
            this.x1 = x1;
            this.x2 = x2;
        }
    }

    private static class SegTree {
        int[] cnt;
        double[] len;
        double[] xs;
        int m;
        SegTree(int m, double[] xs) {
            this.m = m;
            this.xs = xs;
            int size = (m + 2) * 4;
            cnt = new int[size];
            len = new double[size];
        }
        void update(int node, int l, int r, int ql, int qr, int delta) {
            if (ql > r || qr < l) return;
            if (ql <= l && r <= qr) {
                cnt[node] += delta;
            } else {
                int mid = (l + r) >> 1;
                update(node * 2, l, mid, ql, qr, delta);
                update(node * 2 + 1, mid + 1, r, ql, qr, delta);
            }
            if (cnt[node] > 0) {
                len[node] = xs[r + 1] - xs[l];
            } else if (l == r) {
                len[node] = 0.0;
            } else {
                len[node] = len[node * 2] + len[node * 2 + 1];
            }
        }
    }

    private static double computeTotalArea(List<Event> events, double[] xs) {
        if (events.isEmpty()) return 0.0;
        events.sort(Comparator.comparingDouble(e -> e.y));
        int m = xs.length - 1;
        SegTree st = new SegTree(m, xs);
        double area = 0.0;
        double prevY = events.get(0).y;
        int i = 0;
        while (i < events.size()) {
            double curY = events.get(i).y;
            double dy = curY - prevY;
            if (dy != 0.0) area += st.len[1] * dy;
            while (i < events.size() && events.get(i).y == curY) {
                Event e = events.get(i);
                int l = lowerBound(xs, e.x1);
                int r = lowerBound(xs, e.x2) - 1;
                if (l <= r) st.update(1, 0, m - 1, l, r, e.type);
                i++;
            }
            prevY = curY;
        }
        return area;
    }

    private static double findSplitY(List<Event> events, double[] xs, double halfArea) {
        if (events.isEmpty()) return 0.0;
        events.sort(Comparator.comparingDouble(e -> e.y));
        int m = xs.length - 1;
        SegTree st = new SegTree(m, xs);
        double cum = 0.0;
        double prevY = events.get(0).y;
        int i = 0;
        while (i < events.size()) {
            double curY = events.get(i).y;
            double dy = curY - prevY;
            double covered = st.len[1];
            if (covered > 0 && dy > 0) {
                double add = covered * dy;
                if (cum + add >= halfArea) {
                    return prevY + (halfArea - cum) / covered;
                }
                cum += add;
            }
            while (i < events.size() && events.get(i).y == curY) {
                Event e = events.get(i);
                int l = lowerBound(xs, e.x1);
                int r = lowerBound(xs, e.x2) - 1;
                if (l <= r) st.update(1, 0, m - 1, l, r, e.type);
                i++;
            }
            prevY = curY;
        }
        return prevY;
    }

    public static double separateSquaresII(double[][] squares) {
        int n = squares.length;
        if (n == 0) return 0.0;
        List<Double> xVals = new ArrayList<>(2 * n);
        List<Event> events = new ArrayList<>(2 * n);
        for (double[] s : squares) {
            double x = s[0], y = s[1], l = s[2];
            double x2 = x + l;
            double y2 = y + l;
            xVals.add(x);
            xVals.add(x2);
            events.add(new Event(y, 1, x, x2));
            events.add(new Event(y2, -1, x, x2));
        }
        Collections.sort(xVals);
        double[] uniqX = new double[xVals.size()];
        int cnt = 0;
        for (int i = 0; i < xVals.size(); ++i) {
            double v = xVals.get(i);
            if (i == 0 || v != xVals.get(i - 1)) {
                uniqX[cnt++] = v;
            }
        }
        uniqX = Arrays.copyOf(uniqX, cnt);
        double totalArea = computeTotalArea(events, uniqX);
        double halfArea = totalArea / 2.0;
        return findSplitY(events, uniqX, halfArea);
    }
}

import java.util.*;

class Solution {
    public static long maxSumWithAtMostK(List<List<Integer>> grid, List<Integer> limits, int k) {
        if (k <= 0) return 0L;
        PriorityQueue<Integer> topK = new PriorityQueue<>(k);
        for (int i = 0; i < grid.size(); i++) {
            int limit = (i < limits.size()) ? limits.get(i) : 0;
            if (limit <= 0) continue;
            List<Integer> row = grid.get(i);
            if (row.isEmpty()) continue;
            int take = Math.min(limit, row.size());
            PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
            maxHeap.addAll(row);
            for (int cnt = 0; cnt < take && !maxHeap.isEmpty(); cnt++) {
                int val = maxHeap.poll();
                if (topK.size() < k) {
                    topK.offer(val);
                } else if (val > topK.peek()) {
                    topK.poll();
                    topK.offer(val);
                }
            }
        }
        long sum = 0L;
        for (int v : topK) sum += v;
        return sum;
    }
}

