public class P5 {
    static long eatPizzas(int[] pizzas) {
        int[] a = pizzas.clone();
        Arrays.sort(a);
        int n = a.length;
        int days = n / 4;
        int odd = (days + 1) / 2;
        int even = days - odd;
        long total = 0;
        for (int i = 0; i < odd; i++) total += a[n - 1 - i];
        int idx = n - odd - 2;
        for (int i = 0; i < even; i++) {
            total += a[idx];
            idx -= 2;
        }
        return total;
    }

    public static void main(String[] args) {
        long g1 = eatPizzas(new int[]{1,2,3,4,5,6,7,8});
        System.out.println("got=" + g1 + " expected=14 " + (g1==14?"OK":"FAIL"));
        long g2 = eatPizzas(new int[]{2,1,1,1,1,1,1,1});
        System.out.println("got=" + g2 + " expected=3 " + (g2==3?"OK":"FAIL"));
    }
}

