class Solution {
    int m, n;
    int[] dirs = {1,1,-1,-1,1};
    int[][][][] memo;
    int[][] grid;

    int dfs(int i, int j, int k, int cnt) {
        if (memo[i][j][k][cnt] != -1) return memo[i][j][k][cnt];
        int target = grid[i][j]==2 ? 0 : 2;
        int best = 0;
        int x = i+dirs[k], y = j+dirs[k+1];
        if (x>=0 && x<m && y>=0 && y<n && grid[x][y]==target) {
            best = dfs(x, y, k, cnt) + 1;
        }
        if (cnt == 0) {
            int k2 = (k+1)%4;
            int x2 = i+dirs[k2], y2 = j+dirs[k2+1];
            if (x2>=0 && x2<m && y2>=0 && y2<n && grid[x2][y2]==target) {
                best = Math.max(best, dfs(x2, y2, k2, 1) + 1);
            }
        }
        memo[i][j][k][cnt] = best;
        return best;
    }

    public int lenOfVDiagonal(int[][] g) {
        grid = g;
        m = g.length; n = g[0].length;
        memo = new int[m][n][4][2];
        for (int[][][] a : memo) for (int[][] b : a) for (int[] c : b) java.util.Arrays.fill(c, -1);
        int ans = 0;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (grid[i][j] == 1)
                    for (int k = 0; k < 4; k++)
                        ans = Math.max(ans, dfs(i, j, k, 0) + 1);
        return ans;
    }
}

