import java.util.*;

public class Solution {
    public static class Pair {
        public long first;
        public long second;
        public Pair(long first, long second) {
            this.first = first;
            this.second = second;
        }
    }

    private static boolean feasible(long d, long[] dup, int N, long P, int k) {
        int size = dup.length;
        int[] next = new int[size];
        int j = 0;
        for (int i = 0; i < size; i++) {
            if (j < i + 1) j = i + 1;
            while (j < size && dup[j] - dup[i] < d) j++;
            next[i] = j;
        }
        int LOG = 0;
        while ((1 << LOG) <= k) LOG++;
        int[][] jump = new int[LOG][size];
        System.arraycopy(next, 0, jump[0], 0, size);
        for (int p = 1; p < LOG; p++) {
            int[] prev = jump[p - 1];
            int[] cur = jump[p];
            for (int i = 0; i < size; i++) {
                int mid = prev[i];
                cur[i] = (mid < size) ? prev[mid] : size;
            }
        }
        for (int i = 0; i < N; i++) {
            int pos = i;
            int remaining = k - 1;
            int bit = 0;
            while (remaining > 0 && pos < size) {
                if ((remaining & 1) == 1) {
                    pos = jump[bit][pos];
                    if (pos >= i + N) break;
                }
                remaining >>= 1;
                bit++;
            }
            if (remaining == 0 && pos < i + N) {
                long span = dup[pos] - dup[i];
                if (span <= P - d) return true;
            }
        }
        return false;
    }

    public static long maxMinManhattanDistance(long side, List<Pair> points, int k) {
        long P = 4 * side;
        int m = points.size();
        long[] s = new long[m];
        for (int i = 0; i < m; i++) {
            long x = points.get(i).first;
            long y = points.get(i).second;
            long pos;
            if (y == 0) {
                pos = x;
            } else if (x == side) {
                pos = side + y;
            } else if (y == side) {
                pos = 3 * side - x;
            } else {
                pos = 4 * side - y;
            }
            s[i] = pos;
        }
        Arrays.sort(s);
        int N = s.length;
        long[] dup = new long[2 * N];
        System.arraycopy(s, 0, dup, 0, N);
        for (int i = 0; i < N; i++) {
            dup[N + i] = s[i] + P;
        }
        long low = 0, high = P / 2;
        while (low < high) {
            long mid = (low + high + 1) >>> 1;
            if (feasible(mid, dup, N, P, k)) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return low;
    }
}

