class Solution {
    public static String smallestGeneratedString(String str1, String str2) {
        int n = str1.length();
        int m = str2.length();
        int L = n + m - 1;
        char[] result = new char[L];
        char[] s1 = str1.toCharArray();
        char[] s2 = str2.toCharArray();

        for (int i = 0; i < n; i++) {
            if (s1[i] == 'T') {
                for (int j = 0; j < m; j++) {
                    int pos = i + j;
                    char c = s2[j];
                    if (result[pos] == 0) {
                        result[pos] = c;
                    } else if (result[pos] != c) {
                        return "";
                    }
                }
            }
        }

        for (int i = 0; i < n; i++) {
            if (s1[i] == 'F') {
                boolean alreadyDiff = false;
                for (int j = 0; j < m; j++) {
                    int pos = i + j;
                    char c = s2[j];
                    if (result[pos] != 0 && result[pos] != c) {
                        alreadyDiff = true;
                        break;
                    }
                }
                if (alreadyDiff) continue;

                boolean changed = false;
                for (int j = m - 1; j >= 0; j--) {
                    int pos = i + j;
                    if (result[pos] == 0) {
                        char c = s2[j];
                        result[pos] = (c == 'a') ? 'b' : 'a';
                        changed = true;
                        break;
                    }
                }
                if (!changed) return "";
            }
        }

        for (int i = 0; i < L; i++) {
            if (result[i] == 0) result[i] = 'a';
        }
        return new String(result);
    }
}

import java.util.*;

class Solution {
    public static int minimumRemovalCost(int[] nums) {
        int n = nums.length;
        if (n == 0) {
            return 0;
        }
        int[] left = new int[n];
        int[] right = new int[n];
        int[] parent = new int[n];
        Arrays.fill(left, -1);
        Arrays.fill(right, -1);
        Arrays.fill(parent, -1);
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            int last = -1;
            while (!stack.isEmpty() && nums[i] > nums[stack.peek()]) {
                last = stack.pop();
            }
            if (!stack.isEmpty()) {
                right[stack.peek()] = i;
                parent[i] = stack.peek();
            }
            if (last != -1) {
                left[i] = last;
                parent[last] = i;
            }
            stack.push(i);
        }
        int root = 0;
        while (parent[root] != -1) {
            root = parent[root];
        }
        int[] memo = new int[n];
        boolean[] visited = new boolean[n];
        return dfs(root, nums, left, right, memo, visited);
    }

    private static int dfs(int node, int[] nums, int[] left, int[] right, int[] memo, boolean[] visited) {
        if (node == -1) {
            return 0;
        }
        if (visited[node]) {
            return memo[node];
        }
        int leftCost = dfs(left[node], nums, left, right, memo, visited);
        int rightCost = dfs(right[node], nums, left, right, memo, visited);
        int result = nums[node] + Math.min(leftCost, rightCost);
        visited[node] = true;
        memo[node] = result;
        return result;
    }
}

import java.util.*;

public class Solution {
    private static final long INF = 1000000000000000000L;
    private static long mulCap(long a, long b) {
        if (a == 0 || b == 0) return 0;
        if (a > INF / b) return INF;
        long res = a * b;
        return res > INF ? INF : res;
    }
    public static List<Integer> getPermutation(int n, long k) {
        int totalOdd = (n + 1) / 2;
        int totalEven = n / 2;
        long[][][] dp = new long[totalOdd + 1][totalEven + 1][2];
        dp[0][0][0] = 1;
        dp[0][0][1] = 1;
        for (int o = 0; o <= totalOdd; ++o) {
            for (int e = 0; e <= totalEven; ++e) {
                if (o == 0 && e == 0) continue;
                long val0 = 0, val1 = 0;
                if (o > 0) val0 = mulCap((long) o, dp[o - 1][e][1]);
                if (e > 0) val1 = mulCap((long) e, dp[o][e - 1][0]);
                dp[o][e][0] = val0;
                dp[o][e][1] = val1;
            }
        }
        List<Integer> ans = new ArrayList<>();
        boolean[] used = new boolean[n + 1];
        int oddLeft = totalOdd, evenLeft = totalEven;
        int lastParity = -1;
        long K = k;
        for (int pos = 0; pos < n; ++pos) {
            boolean placed = false;
            for (int x = 1; x <= n; ++x) {
                if (used[x]) continue;
                int parity = x & 1;
                if (pos > 0 && parity == lastParity) continue;
                int o = oddLeft - (parity == 1 ? 1 : 0);
                int e = evenLeft - (parity == 0 ? 1 : 0);
                long cnt = dp[o][e][parity];
                if (cnt >= K) {
                    ans.add(x);
                    used[x] = true;
                    oddLeft = o;
                    evenLeft = e;
                    lastParity = parity;
                    placed = true;
                    break;
                } else {
                    K -= cnt;
                }
            }
            if (!placed) {
                return new ArrayList<>();
            }
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    public static int longestPalindromeSubseqAfterOperations(String s, int k) {
        int n = s.length();
        if (n == 0) return 0;
        int K = k;
        int[][] dpPrevPrev = new int[n][K + 1];
        int[][] dpPrev = new int[n][K + 1];
        for (int i = 0; i < n; ++i) {
            for (int c = 0; c <= K; ++c) {
                dpPrev[i][c] = 1;
            }
        }
        for (int len = 2; len <= n; ++len) {
            int[][] dpCur = new int[n][K + 1];
            for (int l = 0; l + len - 1 < n; ++l) {
                int r = l + len - 1;
                int diff = Math.abs(s.charAt(l) - s.charAt(r));
                int d = Math.min(diff, 26 - diff);
                for (int c = 0; c <= K; ++c) {
                    int best = Math.max(dpPrev[l + 1][c], dpPrev[l][c]);
                    if (c >= d) {
                        int inner = (len > 2) ? dpPrevPrev[l + 1][c - d] : 0;
                        int cand = inner + 2;
                        if (cand > best) best = cand;
                    }
                    dpCur[l][c] = best;
                }
            }
            dpPrevPrev = dpPrev;
            dpPrev = dpCur;
        }
        int ans = 0;
        for (int c = 0; c <= K; ++c) {
            if (dpPrev[0][c] > ans) ans = dpPrev[0][c];
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    public static long maxSumKSubarrays(int[] nums, int k, int m) {
        int n = nums.length;
        if (k == 0) return 0L;
        long NEG_INF = Long.MIN_VALUE / 4;
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; ++i) {
            pref[i + 1] = pref[i] + (long) nums[i];
        }
        long[] dpPrev = new long[n + 1];
        Arrays.fill(dpPrev, NEG_INF);
        dpPrev[0] = 0L;
        for (int sub = 1; sub <= k; ++sub) {
            long[] dpCurr = new long[n + 1];
            Arrays.fill(dpCurr, NEG_INF);
            long best = NEG_INF;
            for (int i = m; i <= n; ++i) {
                long candidate = dpPrev[i - m] - pref[i - m];
                if (candidate > best) best = candidate;
                long val = best == NEG_INF ? NEG_INF : best + pref[i];
                dpCurr[i] = Math.max(dpCurr[i - 1], val);
            }
            dpPrev = dpCurr;
        }
        return dpPrev[n];
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static int largestAlmostMissingInteger(int[] nums, int k) {
        int n = nums.length;
        int maxStart = n - k;
        if (maxStart < 0) {
            return -1;
        }
        HashMap<Integer, int[]> info = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int val = nums[i];
            int L = i - k + 1;
            if (L < 0) L = 0;
            int R = i;
            if (R > maxStart) R = maxStart;
            if (L > R) continue;
            int[] data = info.get(val);
            if (data == null) {
                int len = R - L + 1;
                info.put(val, new int[]{len, R});
            } else {
                int total = data[0];
                int prevR = data[1];
                if (L > prevR) {
                    total += (R - L + 1);
                } else if (R > prevR) {
                    total += (R - prevR);
                }
                data[0] = total;
                data[1] = Math.max(prevR, R);
            }
        }
        int answer = -1;
        for (Map.Entry<Integer, int[]> entry : info.entrySet()) {
            if (entry.getValue()[0] == 1) {
                answer = Math.max(answer, entry.getKey());
            }
        }
        return answer;
    }
}

