public class Solution {
    public static int countUnplacedFruits(int[] fruits, int[] baskets) {
        TreeMap<Integer, Integer> capacityCount = new TreeMap<>();
        for (int cap : baskets) {
            capacityCount.merge(cap, 1, Integer::sum);
        }
        int unplaced = 0;
        for (int fruit : fruits) {
            Integer key = capacityCount.higherKey(fruit);
            if (key == null) {
                unplaced++;
            } else {
                int cnt = capacityCount.get(key);
                if (cnt == 1) {
                    capacityCount.remove(key);
                } else {
                    capacityCount.put(key, cnt - 1);
                }
            }
        }
        return unplaced;
    }
}

