class Solution {
    private static class Pair {
        int a, b, v, idx;
        Pair(int a, int b, int idx) {
            if (a > b) {
                int tmp = a;
                a = b;
                b = tmp;
            }
            this.a = a;
            this.b = b;
            this.v = a + 1;
            this.idx = idx;
        }
    }

    public static long maxSubarrays(int n, List<int[]> conflictingPairs) {
        int m = conflictingPairs.size();
        Pair[] pairs = new Pair[m];
        for (int i = 0; i < m; i++) {
            int[] p = conflictingPairs.get(i);
            pairs[i] = new Pair(p[0], p[1], i);
        }
        Arrays.sort(pairs, Comparator.comparingInt(p -> p.b));
        TreeMap<Integer, Integer> freq = new TreeMap<>();
        Map<Integer, Integer> firstIdxForValue = new HashMap<>();
        long[] contrib = new long[m];
        long baseTotal = 0;
        int ptr = 0;
        for (int r = 1; r <= n; r++) {
            while (ptr < m && pairs[ptr].b == r) {
                int v = pairs[ptr].v;
                freq.merge(v, 1, Integer::sum);
                if (freq.get(v) == 1) {
                    firstIdxForValue.put(v, pairs[ptr].idx);
                } else {
                    firstIdxForValue.remove(v);
                }
                ptr++;
            }
            int left = 1;
            int second = 0;
            int topIdx = -1;
            if (!freq.isEmpty()) {
                left = freq.lastKey();
                int cnt = freq.get(left);
                Integer lower = freq.lowerKey(left);
                second = (lower == null ? 0 : lower);
                if (cnt == 1) {
                    Integer idx = firstIdxForValue.get(left);
                    if (idx != null) {
                        topIdx = idx;
                    }
                }
            }
            baseTotal += (long) r - left + 1;
            if (topIdx != -1) {
                int secondEffective = (second == 0 ? 1 : second);
                contrib[topIdx] += (long) left - secondEffective;
            }
        }
        long best = baseTotal;
        for (int i = 0; i < m; i++) {
            long candidate = baseTotal + contrib[i];
            if (candidate > best) best = candidate;
        }
        return best;
    }
}

class Solution {
    private int maxLength = 0, minNodes = 1;
    private List<int[]>[] graph;
    private int[] nums;
    private List<Integer> prefix = new ArrayList<>();
    private Map<Integer,Integer> lastSeenDepth = new HashMap<>();

    public int[] longestSpecialPath(int[][] edges, int[] n0) {
        nums = n0;
        int n = nums.length;
        graph = new List[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(new int[]{e[1], e[2]});
            graph[e[1]].add(new int[]{e[0], e[2]});
        }
        prefix.add(0);
        dfs(0, -1, new int[]{0, 0});
        return new int[]{maxLength, minNodes};
    }
    private void dfs(int u, int prev, int[] leftBoundary) {
        int prevDepth = lastSeenDepth.getOrDefault(nums[u], 0);
        lastSeenDepth.put(nums[u], prefix.size());
        int[] lb = leftBoundary;
        if (prevDepth != 0) {
            int[] combined = {leftBoundary[0], leftBoundary[1], prevDepth};
            Arrays.sort(combined);
            lb = new int[]{combined[1], combined[2]};
        }
        int length = prefix.get(prefix.size() - 1) - prefix.get(lb[0]);
        int nodes = prefix.size() - lb[0];
        if (length > maxLength || (length == maxLength && nodes < minNodes)) {
            maxLength = length;
            minNodes = nodes;
        }
        for (int[] edge : graph[u]) {
            int v = edge[0], w = edge[1];
            if (v == prev) continue;
            prefix.add(prefix.get(prefix.size() - 1) + w);
            dfs(v, u, lb);
            prefix.remove(prefix.size() - 1);
        }
        lastSeenDepth.put(nums[u], prevDepth);
    }
}

