class Solution {
    public static int[] distanceToClosest(int[] nums, int[] queries) {
        int n = nums.length;
        HashMap<Integer, ArrayList<Integer>> map = new HashMap<>(n * 2);
        for (int i = 0; i < n; i++) {
            map.computeIfAbsent(nums[i], k -> new ArrayList<>()).add(i);
        }
        int[] minDist = new int[n];
        Arrays.fill(minDist, -1);
        for (ArrayList<Integer> list : map.values()) {
            int sz = list.size();
            if (sz == 1) {
                minDist[list.get(0)] = -1;
                continue;
            }
            for (int i = 0; i < sz; i++) {
                int cur = list.get(i);
                int next = list.get((i + 1) % sz);
                int prev = list.get((i - 1 + sz) % sz);
                int forward = (next - cur + n) % n;
                int backward = (cur - prev + n) % n;
                minDist[cur] = Math.min(forward, backward);
            }
        }
        int[] result = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            result[i] = minDist[queries[i]];
        }
        return result;
    }
}

