class Solution {
    public static int minimumQueriesToZeroArray(int[] nums, int[][] queries) {
        int n = nums.length;
        SegmentTree st = new SegmentTree(nums);
        if (st.nonZeroCount() == 0) return 0;
        for (int i = 0; i < queries.length; i++) {
            int l = queries[i][0];
            int r = queries[i][1];
            int val = queries[i][2];
            st.rangeDec(l, r, val);
            if (st.nonZeroCount() == 0) return i + 1;
        }
        return -1;
    }

    private static class SegmentTree {
        private final int n;
        private final long[] min;
        private final int[] cnt;
        private final long[] lazy;

        SegmentTree(int[] arr) {
            n = arr.length;
            min = new long[n * 4];
            cnt = new int[n * 4];
            lazy = new long[n * 4];
            build(1, 0, n - 1, arr);
        }

        int nonZeroCount() {
            return cnt[1];
        }

        void rangeDec(int l, int r, int val) {
            update(1, 0, n - 1, l, r, val);
        }

        private void build(int node, int l, int r, int[] arr) {
            if (l == r) {
                min[node] = arr[l];
                cnt[node] = arr[l] == 0 ? 0 : 1;
                return;
            }
            int mid = (l + r) >>> 1;
            build(node << 1, l, mid, arr);
            build(node << 1 | 1, mid + 1, r, arr);
            pull(node);
        }

        private void push(int node) {
            if (lazy[node] != 0) {
                apply(node << 1, lazy[node]);
                apply(node << 1 | 1, lazy[node]);
                lazy[node] = 0;
            }
        }

        private void apply(int node, long val) {
            min[node] -= val;
            lazy[node] += val;
        }

        private void pull(int node) {
            min[node] = Math.min(min[node << 1], min[node << 1 | 1]);
            cnt[node] = cnt[node << 1] + cnt[node << 1 | 1];
        }

        private void update(int node, int l, int r, int ql, int qr, int val) {
            if (qr < l || ql > r) return;
            if (ql <= l && r <= qr && min[node] > val) {
                min[node] -= val;
                lazy[node] += val;
                return;
            }
            if (l == r) {
                long newVal = Math.max(0, min[node] - val);
                min[node] = newVal;
                cnt[node] = newVal == 0 ? 0 : 1;
                return;
            }
            push(node);
            int mid = (l + r) >>> 1;
            update(node << 1, l, mid, ql, qr, val);
            update(node << 1 | 1, mid + 1, r, ql, qr, val);
            pull(node);
        }
    }
}

import java.util.*;

class Solution {
    private static class TrieNode {
        int[] next = new int[26];
        int cnt;
        int depth;
        TrieNode() {
            Arrays.fill(next, -1);
        }
    }

    public static int[] longestCommonPrefix(List<String> words, int k) {
        int n = words.size();
        if (n - 1 < k) {
            return new int[n];
        }

        List<TrieNode> nodes = new ArrayList<>();
        nodes.add(new TrieNode()); // root at index 0
        int maxWordLen = 0;

        for (String w : words) {
            int cur = 0;
            for (int i = 0; i < w.length(); i++) {
                int idx = w.charAt(i) - 'a';
                if (nodes.get(cur).next[idx] == -1) {
                    TrieNode newNode = new TrieNode();
                    newNode.depth = nodes.get(cur).depth + 1;
                    nodes.add(newNode);
                    nodes.get(cur).next[idx] = nodes.size() - 1;
                }
                cur = nodes.get(cur).next[idx];
                nodes.get(cur).cnt++;
            }
            if (w.length() > maxWordLen) maxWordLen = w.length();
        }

        int[] goodCount = new int[maxWordLen + 1];
        int globalMaxDepth = 0;
        for (int i = 1; i < nodes.size(); i++) {
            TrieNode node = nodes.get(i);
            if (node.cnt >= k) {
                goodCount[node.depth]++;
                if (node.depth > globalMaxDepth) globalMaxDepth = node.depth;
            }
        }

        int[] answer = new int[n];

        for (int i = 0; i < n; i++) {
            String w = words.get(i);
            int cur = 0;
            for (int j = 0; j < w.length(); j++) {
                int idx = w.charAt(j) - 'a';
                cur = nodes.get(cur).next[idx];
                TrieNode node = nodes.get(cur);
                node.cnt--;
                if (node.cnt == k - 1) {
                    goodCount[node.depth]--;
                    if (node.depth == globalMaxDepth && goodCount[node.depth] == 0) {
                        while (globalMaxDepth > 0 && goodCount[globalMaxDepth] == 0) {
                            globalMaxDepth--;
                        }
                    }
                }
            }

            answer[i] = globalMaxDepth;

            cur = 0;
            for (int j = 0; j < w.length(); j++) {
                int idx = w.charAt(j) - 'a';
                cur = nodes.get(cur).next[idx];
                TrieNode node = nodes.get(cur);
                node.cnt++;
                if (node.cnt == k) {
                    goodCount[node.depth]++;
                    if (node.depth > globalMaxDepth) globalMaxDepth = node.depth;
                }
            }
        }

        return answer;
    }
}

import java.util.*;

public class Solution {
    public static long countBeautiful(long l, long r) {
        return countUpTo(r) - countUpTo(l - 1);
    }

    private static long countUpTo(long X) {
        if (X <= 0) return 0L;
        char[] chars = Long.toString(X).toCharArray();
        int L = chars.length;
        int[] digits = new int[L];
        for (int i = 0; i < L; i++) digits[i] = chars[i] - '0';
        long total = 0L;
        int maxSum = 9 * L;
        for (int S = 1; S <= maxSum; S++) {
            int targetSum = S;
            long[][][][] memo = new long[L + 1][targetSum + 1][targetSum][2];
            for (int i = 0; i <= L; i++) {
                for (int a = 0; a <= targetSum; a++) {
                    for (int b = 0; b < targetSum; b++) {
                        memo[i][a][b][0] = -1L;
                        memo[i][a][b][1] = -1L;
                    }
                }
            }
            total += dfs(0, 0, 1 % targetSum, 0, true, digits, L, targetSum, memo);
        }
        return total;
    }

    private static long dfs(int pos, int sum, int prodMod, int started, boolean tight,
                            int[] digits, int L, int targetSum,
                            long[][][][] memo) {
        if (pos == L) {
            return (started == 1 && sum == targetSum && prodMod == 0) ? 1L : 0L;
        }
        if (!tight) {
            long cached = memo[pos][sum][prodMod][started];
            if (cached != -1L) return cached;
        }
        int limit = tight ? digits[pos] : 9;
        long res = 0L;
        for (int d = 0; d <= limit; d++) {
            int nStarted = (started == 1 || d != 0) ? 1 : 0;
            int nSum = sum + (nStarted == 1 ? d : 0);
            if (nSum > targetSum) continue;
            int nProdMod;
            if (nStarted == 0) {
                nProdMod = prodMod;
            } else {
                if (started == 0) {
                    nProdMod = d % targetSum;
                } else {
                    if (prodMod == 0) {
                        nProdMod = 0;
                    } else {
                        nProdMod = (int) ((1L * prodMod * (d % targetSum)) % targetSum);
                    }
                }
            }
            res += dfs(pos + 1, nSum, nProdMod, nStarted, tight && d == limit,
                       digits, L, targetSum, memo);
        }
        if (!tight) {
            memo[pos][sum][prodMod][started] = res;
        }
        return res;
    }
}

class Solution {
    public static long minBrewTime(int[] skill, int[] mana) {
        int n = skill.length, m = mana.length;
        long[] done = new long[n];
        for (int j = 0; j < m; j++) {
            long[] idealStart = new long[n];
            for (int i = 1; i < n; i++) idealStart[i] = idealStart[i-1] + (long) skill[i-1]*mana[j];
            long shift = 0;
            for (int i = 0; i < n; i++) shift = Math.max(shift, done[i] - idealStart[i]);
            long[] finish = new long[n];
            for (int i = 0; i < n; i++) {
                long start = idealStart[i] + shift;
                finish[i] = start + (long) skill[i]*mana[j];
            }
            done = finish;
        }
        return done[n-1];
    }
}

import java.util.HashMap;

public class Solution {
    public static long maxUniqueSubarraySum(int[] nums) {
        int left = 0;
        long curSum = 0;
        long best = Long.MIN_VALUE;
        HashMap<Integer, Integer> freq = new HashMap<>();
        for (int right = 0; right < nums.length; ++right) {
            int v = nums[right];
            while (freq.getOrDefault(v, 0) > 0) {
                int leftVal = nums[left];
                freq.put(leftVal, freq.get(leftVal) - 1);
                curSum -= leftVal;
                ++left;
            }
            freq.put(v, freq.getOrDefault(v, 0) + 1);
            curSum += v;
            if (curSum > best) {
                best = curSum;
            }
        }
        return best == Long.MIN_VALUE ? 0 : best;
    }
}

