class Solution {
    private static class DSU {
        private final int[] parent;
        private final int[] rank;
        DSU(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; ++i) parent[i] = i;
        }
        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }
        void unite(int a, int b) {
            int ra = find(a), rb = find(b);
            if (ra == rb) return;
            if (rank[ra] < rank[rb]) {
                int tmp = ra;
                ra = rb;
                rb = tmp;
            }
            parent[rb] = ra;
            if (rank[ra] == rank[rb]) ++rank[ra];
        }
    }

    public static int numberOfComponents(List<List<Integer>> properties, int k) {
        int n = properties.size();
        if (n == 0) return 0;
        if (k <= 0) return 1;
        Map<Integer, List<Integer>> propToNodes = new HashMap<>();
        for (int i = 0; i < n; ++i) {
            Set<Integer> uniq = new HashSet<>(properties.get(i));
            for (int v : uniq) {
                propToNodes.computeIfAbsent(v, key -> new ArrayList<>()).add(i);
            }
        }
        Map<Long, Integer> pairCount = new HashMap<>();
        for (List<Integer> nodes : propToNodes.values()) {
            int sz = nodes.size();
            for (int a = 0; a < sz; ++a) {
                int i = nodes.get(a);
                for (int b = a + 1; b < sz; ++b) {
                    int j = nodes.get(b);
                    long key = ((long) i << 32) | (j & 0xffffffffL);
                    pairCount.merge(key, 1, Integer::sum);
                }
            }
        }
        DSU dsu = new DSU(n);
        for (Map.Entry<Long, Integer> e : pairCount.entrySet()) {
            if (e.getValue() >= k) {
                long key = e.getKey();
                int i = (int) (key >> 32);
                int j = (int) key;
                dsu.unite(i, j);
            }
        }
        Set<Integer> roots = new HashSet<>();
        for (int i = 0; i < n; ++i) roots.add(dsu.find(i));
        return roots.size();
    }
}

