class Solution {
    public static int longestPalindromeAfterConcat(String s, String t) {
        int n = s.length();
        int m = t.length();
        int maxSingle = Math.max(longestPalSubstring(s), longestPalSubstring(t));
        String revT = new StringBuilder(t).reverse().toString();
        int[] prev = new int[m + 1];
        int[] curr = new int[m + 1];
        int maxLen = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (s.charAt(i) == revT.charAt(j)) {
                    curr[j + 1] = prev[j] + 1;
                    if (curr[j + 1] > maxLen) maxLen = curr[j + 1];
                } else {
                    curr[j + 1] = 0;
                }
            }
            int[] tmp = prev;
            prev = curr;
            curr = tmp;
        }
        int ans = Math.max(maxSingle, 2 * maxLen);
        if (maxLen < n || maxLen < m) ans = Math.max(ans, 2 * maxLen + 1);
        return ans;
    }

    private static int longestPalSubstring(String s) {
        int n = s.length();
        if (n == 0) return 0;
        char[] ch = s.toCharArray();
        int[] d1 = new int[n];
        int l = 0, r = -1;
        for (int i = 0; i < n; i++) {
            int k = (i > r) ? 1 : Math.min(d1[l + r - i], r - i + 1);
            while (i - k >= 0 && i + k < n && ch[i - k] == ch[i + k]) k++;
            d1[i] = k;
            if (i + k - 1 > r) {
                l = i - k + 1;
                r = i + k - 1;
            }
        }
        int[] d2 = new int[n];
        l = 0;
        r = -1;
        for (int i = 0; i < n; i++) {
            int k = (i > r) ? 0 : Math.min(d2[l + r - i + 1], r - i + 1);
            while (i - k - 1 >= 0 && i + k < n && ch[i - k - 1] == ch[i + k]) k++;
            d2[i] = k;
            if (i + k - 1 > r) {
                l = i - k;
                r = i + k - 1;
            }
        }
        int maxLen = 0;
        for (int i = 0; i < n; i++) {
            int len = 2 * d1[i] - 1;
            if (len > maxLen) maxLen = len;
            len = 2 * d2[i];
            if (len > maxLen) maxLen = len;
        }
        return maxLen;
    }
}

