import java.util.*;

class Solution {
    static TreeMap<Long, Integer> lo = new TreeMap<>(), hi = new TreeMap<>();
    static int loSize, hiSize;
    static long sumLo, sumHi;

    static void insertMap(TreeMap<Long,Integer> map, long v) { map.merge(v, 1, Integer::sum); }
    static void removeMap(TreeMap<Long,Integer> map, long v) {
        int c = map.get(v);
        if (c == 1) map.remove(v); else map.put(v, c-1);
    }
    static void rebalance() {
        while (loSize > hiSize + 1) {
            long v = lo.lastKey();
            removeMap(lo, v); sumLo -= v; loSize--;
            insertMap(hi, v); sumHi += v; hiSize++;
        }
        while (hiSize > loSize) {
            long v = hi.firstKey();
            removeMap(hi, v); sumHi -= v; hiSize--;
            insertMap(lo, v); sumLo += v; loSize++;
        }
    }
    static void add(long v) {
        if (lo.isEmpty() || v <= lo.lastKey()) { insertMap(lo, v); sumLo += v; loSize++; }
        else { insertMap(hi, v); sumHi += v; hiSize++; }
        rebalance();
    }
    static void remove(long v) {
        if (lo.containsKey(v)) { removeMap(lo, v); sumLo -= v; loSize--; }
        else { removeMap(hi, v); sumHi -= v; hiSize--; }
        rebalance();
    }
    static long cost() {
        long median = lo.lastKey();
        return (median * loSize - sumLo) + (sumHi - median * hiSize);
    }

    public static int minOperations(int[] nums, int x, int k) {
        int n = nums.length;
        if (x == 0 || k == 0) return 0;
        int m = n - x + 1;
        long[] cost = new long[m];
        lo = new TreeMap<>(); hi = new TreeMap<>(); loSize = hiSize = 0; sumLo = sumHi = 0;
        for (int i = 0; i < x; i++) add(nums[i]);
        cost[0] = cost();
        for (int start = 1; start < m; start++) {
            remove(nums[start-1]);
            add(nums[start+x-1]);
            cost[start] = cost();
        }
        final long INF = 1_000_000_000_000L;
        long[] dp = new long[n+1];
        for (int t = 0; t < k; t++) {
            long[] nxt = new long[n+1];
            Arrays.fill(nxt, INF);
            for (int pos = 0; pos < m; pos++) {
                long val = dp[pos] + cost[pos];
                int np = pos + x;
                if (val < nxt[np]) nxt[np] = val;
            }
            for (int i = 0; i < n; i++) if (nxt[i] < nxt[i+1]) nxt[i+1] = nxt[i];
            dp = nxt;
        }
        return (int) dp[n];
    }
}

class Solution {
    public int maxActiveSectionsAfterTrade(String s) {
        int n = s.length();
        int ans = 0, i = 0;
        int pre = Integer.MIN_VALUE, mx = 0;
        while (i < n) {
            int j = i + 1;
            while (j < n && s.charAt(j) == s.charAt(i)) j++;
            int cur = j - i;
            if (s.charAt(i) == '1') ans += cur;
            else { mx = Math.max(mx, pre + cur); pre = cur; }
            i = j;
        }
        ans += mx;
        return ans;
    }
}

class Solution {
    public long minimumCost(int[] nums, int[] cost, int k) {
        int n = nums.length;
        long[] prefixNums = new long[n + 1];
        long[] prefixCost = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefixNums[i + 1] = prefixNums[i] + nums[i];
            prefixCost[i + 1] = prefixCost[i] + cost[i];
        }
        long[] dp = new long[n + 1];
        Arrays.fill(dp, Long.MAX_VALUE);
        dp[n] = 0;
        for (int i = n - 1; i >= 0; i--) {
            for (int j = i; j < n; j++) {
                long val = prefixNums[j + 1] * (prefixCost[j + 1] - prefixCost[i]) +
                           (long) k * (prefixCost[n] - prefixCost[i]) + dp[j + 1];
                dp[i] = Math.min(dp[i], val);
            }
        }
        return dp[0];
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static long maxProductAlternatingSum(int[] nums, long k, long limit) {
        Map<Long, Long> dpEven = new HashMap<>();
        Map<Long, Long> dpOdd = new HashMap<>();
        for (int x : nums) {
            long val = (long) x;
            Map<Long, Long> nextEven = new HashMap<>(dpEven);
            Map<Long, Long> nextOdd = new HashMap<>(dpOdd);
            if (val <= limit) {
                Long existing = nextOdd.get(val);
                if (existing == null || val > existing) {
                    nextOdd.put(val, val);
                }
            }
            for (Map.Entry<Long, Long> p : dpEven.entrySet()) {
                long curProd = p.getValue();
                if (val != 0 && curProd > limit / val) continue;
                long newProd = curProd * val;
                long newSum = p.getKey() + val;
                Long existing = nextOdd.get(newSum);
                if (existing == null || newProd > existing) {
                    nextOdd.put(newSum, newProd);
                }
            }
            for (Map.Entry<Long, Long> p : dpOdd.entrySet()) {
                long curProd = p.getValue();
                if (val != 0 && curProd > limit / val) continue;
                long newProd = curProd * val;
                long newSum = p.getKey() - val;
                Long existing = nextEven.get(newSum);
                if (existing == null || newProd > existing) {
                    nextEven.put(newSum, newProd);
                }
            }
            dpEven = nextEven;
            dpOdd = nextOdd;
        }
        long ans = -1;
        Long valEven = dpEven.get(k);
        if (valEven != null) ans = Math.max(ans, valEven);
        Long valOdd = dpOdd.get(k);
        if (valOdd != null) ans = Math.max(ans, valOdd);
        return ans;
    }
}

