class Solution {
    private static int longestPalindromicSubstring(String s) {
        int n = s.length();
        if (n == 0) return 0;
        char[] a = s.toCharArray();
        int[] d1 = new int[n];
        int l = 0, r = -1;
        int best = 0;
        for (int i = 0; i < n; i++) {
            int k = (i > r) ? 1 : Math.min(d1[l + r - i], r - i + 1);
            while (i - k >= 0 && i + k < n && a[i - k] == a[i + k]) k++;
            d1[i] = k;
            int len = 2 * k - 1;
            if (len > best) best = len;
            if (i + k - 1 > r) {
                l = i - k + 1;
                r = i + k - 1;
            }
        }
        int[] d2 = new int[n];
        l = 0;
        r = -1;
        for (int i = 0; i < n; i++) {
            int k = (i > r) ? 0 : Math.min(d2[l + r - i + 1], r - i + 1);
            while (i - k - 1 >= 0 && i + k < n && a[i - k - 1] == a[i + k]) k++;
            d2[i] = k;
            int len = 2 * k;
            if (len > best) best = len;
            if (i + k - 1 > r) {
                l = i - k;
                r = i + k - 1;
            }
        }
        return best;
    }

    public static int longestPalindromeAfterSubstringConcatII(String s, String t) {
        int n = s.length();
        int m = t.length();
        String revT = new StringBuilder(t).reverse().toString();

        int[] dpPrev = new int[m + 1];
        int maxLen = 0;
        int maxOdd = 1;

        for (int i = 0; i < n; i++) {
            int[] dpCurr = new int[m + 1];
            for (int j = 0; j < m; j++) {
                if (s.charAt(i) == revT.charAt(j)) {
                    dpCurr[j + 1] = dpPrev[j] + 1;
                    int len = dpCurr[j + 1];
                    if (len > maxLen) maxLen = len;

                    boolean canExtendRightInS = i + 1 < n;
                    int startInT = m - 1 - j;
                    boolean canExtendLeftInT = startInT > 0;

                    if (canExtendRightInS || canExtendLeftInT) {
                        int oddLen = 2 * len + 1;
                        if (oddLen > maxOdd) maxOdd = oddLen;
                    }
                }
            }
            dpPrev = dpCurr;
        }

        int bestSingle = Math.max(longestPalindromicSubstring(s), longestPalindromicSubstring(t));
        int bestEven = 2 * maxLen;
        return Math.max(bestSingle, Math.max(bestEven, maxOdd));
    }
}

