class Solution {
    public static int minimumOperationsToMakeNonDecreasing(int[] nums) {
        int n = nums.length;
        if (n == 0) return 0;
        int[] tails = new int[n];
        int size = 0;
        for (int x : nums) {
            int l = 0, r = size;
            while (l < r) {
                int m = (l + r) >>> 1;
                if (tails[m] <= x) {
                    l = m + 1;
                } else {
