import java.util.List;

class Solution {
    public static long countUniqueXorTriplets(List<Integer> nums) {
        if (nums == null || nums.isEmpty()) {
            return 0L;
        }
        int max = 0;
        for (int v : nums) {
            if (v > max) {
                max = v;
            }
        }
        int size = 1;
        while (size <= max) {
            size <<= 1;
        }
        long[] a = new long[size];
        for (int v : nums) {
            a[v] = 1;
        }
        fwht(a, false);
        for (int i = 0; i < size; i++) {
            a[i] = a[i] * a[i] * a[i];
        }
        fwht(a, true);
        long count = 0;
        for (long v : a) {
            if (v > 0) {
                count++;
            }
        }
        return count;
    }

    private static void fwht(long[] a, boolean inverse) {
        int n = a.length;
        for (int len = 1; len < n; len <<= 1) {
            for (int i = 0; i < n; i += len << 1) {
                for (int j = 0; j < len; j++) {
                    long u = a[i + j];
                    long v = a[i + j + len];
                    a[i + j] = u + v;
                    a[i + j + len] = u - v;
                }
            }
        }
        if (inverse) {
            for (int i = 0; i < n; i++) {
                a[i] /= n;
            }
        }
    }
}

import java.util.*;
class Router {
    private final int limit;
    private final Deque<Triple> queue;
    private final HashSet<Triple> set;
    private final HashMap<Integer, TreeMap<Integer, Integer>> destMap;
    public Router(int memoryLimit) {
        this.limit = memoryLimit;
        this.queue = new ArrayDeque<>();
        this.set = new HashSet<>();
        this.destMap = new HashMap<>();
    }
    public boolean addPacket(int source, int destination, int timestamp) {
        Triple key = new Triple(source, destination, timestamp);
        if (set.contains(key)) return false;
        if (queue.size() == limit) {
            Triple old = queue.pollFirst();
            set.remove(old);
            TreeMap<Integer, Integer> ms = destMap.get(old.destination);
            if (ms != null) {
                Integer cnt = ms.get(old.timestamp);
                if (cnt != null) { if (cnt == 1) ms.remove(old.timestamp); else ms.put(old.timestamp, cnt - 1); }
                if (ms.isEmpty()) destMap.remove(old.destination);
            }
        }
        queue.addLast(key);
        set.add(key);
        destMap.computeIfAbsent(destination, k -> new TreeMap<>()).merge(timestamp, 1, Integer::sum);
        return true;
    }
    public int[] forwardPacket() {
        if (queue.isEmpty()) return new int[0];
        Triple p = queue.pollFirst();
        set.remove(p);
        TreeMap<Integer, Integer> ms = destMap.get(p.destination);
        if (ms != null) {
            Integer cnt = ms.get(p.timestamp);
            if (cnt != null) { if (cnt == 1) ms.remove(p.timestamp); else ms.put(p.timestamp, cnt - 1); }
            if (ms.isEmpty()) destMap.remove(p.destination);
        }
        return new int[]{p.source, p.destination, p.timestamp};
    }
    public int getCount(int destination, int startTime, int endTime) {
        TreeMap<Integer, Integer> ms = destMap.get(destination);
        if (ms == null) return 0;
        int total = 0;
        for (int cnt : ms.subMap(startTime, true, endTime, true).values()) total += cnt;
        return total;
    }
    private static class Triple {
        final int source, destination, timestamp;
        Triple(int s, int d, int t) { source=s; destination=d; timestamp=t; }
        @Override public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Triple)) return false;
            Triple other = (Triple) o;
            return source==other.source && destination==other.destination && timestamp==other.timestamp;
        }
        @Override public int hashCode() { int h = source; h = 31*h+destination; h = 31*h+timestamp; return h; }
    }
}

