public class Solution {
    public static int countUniqueXorTriplets(int[] nums) {
        final int LIMIT = 2048;
        boolean[] present = new boolean[LIMIT];
        for (int x : nums) {
            if (x >= 0 && x < LIMIT) {
                present[x] = true;
            }
        }

        boolean[] pairXor = new boolean[LIMIT];
        for (int a = 0; a < LIMIT; ++a) {
            if (present[a]) {
                for (int b = 0; b < LIMIT; ++b) {
                    if (present[b]) {
                        pairXor[a ^ b] = true;
                    }
                }
            }
        }

        boolean[] result = new boolean[LIMIT];
        for (int v = 0; v < LIMIT; ++v) {
            if (present[v]) {
                result[v] = true;
            }
        }

        for (int p = 0; p < LIMIT; ++p) {
            if (pairXor[p]) {
                for (int c = 0; c < LIMIT; ++c) {
                    if (present[c]) {
                        result[p ^ c] = true;
                    }
                }
            }
        }

        int count = 0;
        for (int v = 0; v < LIMIT; ++v) {
            if (result[v]) {
                ++count;
            }
        }
        return count;
    }
}

class Solution {
    public static String smallestPalindromicPermutation(String s) {
        int[] freq = new int[256];
        for (int i = 0; i < s.length(); i++) {
            freq[s.charAt(i) & 0xFF]++;
        }
        StringBuilder leftHalf = new StringBuilder();
        String middle = "";
        for (int code = 0; code < 256; code++) {
            int count = freq[code];
            if (count == 0) continue;
            int half = count >> 1;
            for (int i = 0; i < half; i++) {
                leftHalf.append((char) code);
            }
            if ((count & 1) != 0) {
                middle = String.valueOf((char) code);
            }
        }
        StringBuilder rightHalf = new StringBuilder(leftHalf).reverse();
        return leftHalf.append(middle).append(rightHalf).toString();
    }
}

