public class Solution {
    public static int maxSizeNonDecreasing(int[] nums) {
        int n = nums.length;
        int[] stack = new int[n];
        int size = 0;
        for (int cur : nums) {
            while (size > 0 && stack[size - 1] > cur) {
                cur = Math.max(stack[size - 1], cur);
                size--;
            }
            stack[size++] = cur;
        }
        return size;
    }
