class Solution {
    static class Node {
        int[] remain = new int[5];
        int prod = 1;
    }
    static class SegmentTree {
        int n, k;
        Node[] tree;
        SegmentTree(int[] nums, int k) {
            this.n = nums.length; this.k = k;
            tree = new Node[4*n];
            for (int i = 0; i < 4*n; i++) tree[i] = new Node();
            build(nums, 0, 0, n-1);
        }
        void update(int i, int val) { update(0, 0, n-1, i, val); }
        Node query(int i, int j) { return query(0, 0, n-1, i, j); }
        void build(int[] nums, int cur, int left, int right) {
            if (left == right) {
                tree[cur].remain[nums[left]] = 1;
                tree[cur].prod = nums[left];
                return;
            }
            int mid = (left+right)/2;
            build(nums, 2*cur+1, left, mid);
            build(nums, 2*cur+2, mid+1, right);
            tree[cur] = merge(tree[2*cur+1], tree[2*cur+2]);
        }
        void update(int ti, int lo, int hi, int i, int val) {
            if (lo == hi) {
                for (int j = 0; j < k; j++) tree[ti].remain[j] = 0;
                tree[ti].remain[val] = 1;
                tree[ti].prod = val;
                return;
            }
            int mid = (lo+hi)/2;
            if (i <= mid) update(2*ti+1, lo, mid, i, val);
            else update(2*ti+2, mid+1, hi, i, val);
            tree[ti] = merge(tree[2*ti+1], tree[2*ti+2]);
        }
        Node query(int ti, int lo, int hi, int i, int j) {
            if (i <= lo && hi <= j) return tree[ti];
            if (j < lo || hi < i) return new Node();
            int mid = (lo+hi)/2;
            return merge(query(2*ti+1, lo, mid, i, j), query(2*ti+2, mid+1, hi, i, j));
        }
        Node merge(Node left, Node right) {
            Node node = new Node();
            node.prod = (left.prod * right.prod) % k;
            for (int i = 0; i < k; i++) node.remain[i] = left.remain[i];
            for (int i = 0; i < k; i++) node.remain[(i*left.prod)%k] += right.remain[i];
            return node;
        }
    }
    public int[] resultArray(int[] nums, int k, int[][] queries) {
        for (int i = 0; i < nums.length; i++) nums[i] %= k;
        for (int[] q : queries) q[1] %= k;
        int n = nums.length;
        int[] ans = new int[queries.length];
        SegmentTree tree = new SegmentTree(nums, k);
        for (int qi = 0; qi < queries.length; qi++) {
            int[] q = queries[qi];
            int index=q[0], value=q[1], start=q[2], x=q[3];
            tree.update(index, value);
            ans[qi] = tree.query(start, n-1).remain[x];
        }
        return ans;
    }
}

