import java.math.BigInteger;

public class Solution {
    private static final long MOD = 1_000_000_007L;

    private static int[] toBase(String s, int b) {
        if (s.equals("0")) return new int[]{0};
        BigInteger n = new BigInteger(s);
        BigInteger base = BigInteger.valueOf(b);
        ArrayList<Integer> rev = new ArrayList<>();
        while (n.signum() > 0) {
            BigInteger[] dr = n.divideAndRemainder(base);
            rev.add(dr[1].intValue());
            n = dr[0];
        }
        int[] res = new int[rev.size()];
        for (int i = 0; i < rev.size(); i++) {
            res[i] = rev.get(rev.size() - 1 - i);
        }
        return res;
    }

    private static long countUpTo(int[] digits, int b) {
        int n = digits.length;
        long[][][] memo = new long[n][b][2];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < b; j++) {
                memo[i][j][0] = -1;
                memo[i][j][1] = -1;
            }
        }
        return dfs(0, 0, true, false, digits, b, memo);
    }

    private static long dfs(int idx, int prev, boolean tight, boolean started,
                            int[] digits, int b, long[][][] memo) {
        if (idx == digits.length) return 1L;
        int startedIdx = started ? 1 : 0;
        if (!tight && memo[idx][prev][startedIdx] != -1) {
            return memo[idx][prev][startedIdx];
        }
        int limit = tight ? digits[idx] : b - 1;
        long res = 0;
        for (int d = 0; d <= limit; d++) {
            boolean nstarted = started || d != 0;
            boolean ntight = tight && d == limit;
            if (!nstarted) {
                res += dfs(idx + 1, 0, ntight, false, digits, b, memo);
            } else {
                if (!started) {
                    res += dfs(idx + 1, d, ntight, true, digits, b, memo);
                } else if (d >= prev) {
                    res += dfs(idx + 1, d, ntight, true, digits, b, memo);
                }
            }
            if (res >= MOD) res -= MOD;
        }
        if (!tight) memo[idx][prev][startedIdx] = res % MOD;
        return res % MOD;
    }

    public static void solve() {
        Scanner scanner = new Scanner(System.in);
        String l = scanner.next();
        String r = scanner.next();
        int b = scanner.nextInt();
        int[] rDigits = toBase(r, b);
        long cntR = countUpTo(rDigits, b);
        long cntLMinus = 0;
        if (!l.equals("0")) {
            BigInteger lMinus = new BigInteger(l).subtract(BigInteger.ONE);
            int[] lDigits = toBase(lMinus.toString(), b);
            cntLMinus = countUpTo(lDigits, b);
        }
        long ans = (cntR - cntLMinus) % MOD;
        if (ans < 0) ans += MOD;
        System.out.println(ans);
    }
}

