public class Solution {
    public static long[] findXValue(int[] nums, int k) {
        long[] result = new long[k];
        if (k == 0) return result;
        if (k == 1) {
            long total = (long) nums.length * (nums.length + 1) / 2;
            result[0] = total;
            return result;
        }
        long[] dp = new long[k];
        long[] newDp = new long[k];
        for (int v : nums) {
            Arrays.fill(newDp, 0L);
            int singleRem = Math.floorMod(v, k);
            newDp[singleRem] += 1L;
            for (int r = 0; r < k; ++r) {
                long cnt = dp[r];
                if (cnt != 0) {
                    int newRem = (int) Math.floorMod((long) r * v, k);
                    newDp[newRem] += cnt;
                }
            }
            for (int r = 0; r < k; ++r) {
                long cnt = newDp[r];
                if (cnt != 0) result[r] += cnt;
            }
            long[] tmp = dp;
            dp = newDp;
            newDp = tmp;
        }
        return result;
    }
}

