    }
}

import java.util.*;

class Solution {
    public static List<Integer> smallestDivisiblePermutation(List<Integer> nums, int k) {
        int n = nums.size();
        int fullMask = (1 << n) - 1;
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) arr[i] = nums.get(i);
        int[] pow10mod = new int[n];
        for (int i = 0; i < n; i++) {
            int x = arr[i];
            int len = (x == 0) ? 1 : 0;
            int temp = x;
            while (temp > 0) {
                len++;
                temp /= 10;
            }
            int p = 1 % k;
            for (int j = 0; j < len; j++) p = (p * 10) % k;
            pow10mod[i] = p;
        }
        boolean[][] dp = new boolean[1 << n][k];
        dp[0][0] = true;
        for (int mask = 0; mask <= fullMask; mask++) {
            for (int rem = 0; rem < k; rem++) {
                if (!dp[mask][rem]) continue;
                for (int i = 0; i < n; i++) {
                    if ((mask & (1 << i)) != 0) continue;
                    int newMask = mask | (1 << i);
                    int newRem = (int) (((long) rem * pow10mod[i]) % k);
                    newRem = (newRem + arr[i] % k) % k;
                    dp[newMask][newRem] = true;
                }
            }
        }
        if (!dp[fullMask][0]) return new ArrayList<>();
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> Integer.compare(arr[a], arr[b]));
        List<Integer> answer = new ArrayList<>(n);
        int mask = 0, rem = 0;
        for (int pos = 0; pos < n; pos++) {
            for (int idx : order) {
                if ((mask & (1 << idx)) != 0) continue;
                int newRem = (int) (((long) rem * pow10mod[idx]) % k);
                newRem = (newRem + arr[idx] % k) % k;
                if (dp[mask | (1 << idx)][newRem]) {
                    answer.add(arr[idx]);
                    mask |= (1 << idx);
                    rem = newRem;
                    break;
                }
            }
        }
        return answer;
    }
}

