public class Solution {
    public static long maxProfit(int n, List<int[]> edges, long[] score) {
        int[] preMask = new int[n];
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            preMask[v] |= 1 << u;
        }
        int totalMask = (1 << n) - 1;
        long NEG_INF = Long.MIN_VALUE / 4;
        long[] dp = new long[1 << n];
        Arrays.fill(dp, NEG_INF);
        dp[0] = 0;
        int[] bits = new int[1 << n];
        for (int i = 1; i <= totalMask; i++) {
            bits[i] = bits[i >> 1] + (i & 1);
        }
        for (int mask = 0; mask <= totalMask; mask++) {
            long cur = dp[mask];
            if (cur == NEG_INF) continue;
            int pos = bits[mask] + 1;
            int candidates = (~mask) & totalMask;
            while (candidates != 0) {
                int v = Integer.numberOfTrailingZeros(candidates);
                candidates &= candidates - 1;
                if ((preMask[v] & ~mask) != 0) continue;
                int nextMask = mask | (1 << v);
                long profit = cur + score[v] * pos;
                if (profit > dp[nextMask]) dp[nextMask] = profit;
            }
        }
        return dp[totalMask];
    }
}

