public class Solution {
    public int[][] specialGrid(int n) {
        int size = 1 << n;
        int[][] grid = new int[size][size];
        fill(grid, 0, 0, n, 0);
        return grid;
    }

    private void fill(int[][] grid, int row, int col, int n, int base) {
        if (n == 0) {
            grid[row][col] = base;
            return;
        }
        int half = 1 << (n - 1);
        int quarter = half * half;
        // Top‑left quadrant (offset 3)
        fill(grid, row, col, n - 1, base + 3 * quarter);
        // Top‑right quadrant (offset 0)
        fill(grid, row, col + half, n - 1, base);
        // Bottom‑left quadrant (offset 2)
        fill(grid, row + half, col, n - 1, base + 2 * quarter);
        // Bottom‑right quadrant (offset 1)
        fill(grid, row + half, col + half, n - 1, base + quarter);
    }
}

