class Solution {
    public static int[] shortestPathLengths(int n, int[] nums, int maxDiff, int[][] queries) {
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> {
            int diff = nums[a] - nums[b];
            if (diff != 0) return diff;
            return Integer.compare(a, b);
        });
        int[] sortedVals = new int[n];
        int[] pos = new int[n];
        for (int i = 0; i < n; i++) {
            sortedVals[i] = nums[idx[i]];
            pos[idx[i]] = i;
        }
        int[] far = new int[n];
        int r = 0;
        for (int i = 0; i < n; i++) {
            if (r < i) r = i;
            while (r + 1 < n && sortedVals[r + 1] - sortedVals[i] <= maxDiff) {
                r++;
            }
            far[i] = r;
        }
        final int LOG = 32;
        int[][] up = new int[LOG][n];
        for (int i = 0; i < n; i++) up[0][i] = far[i];
        for (int k = 1; k < LOG; k++) {
            for (int i = 0; i < n; i++) {
                up[k][i] = up[k - 1][up[k - 1][i]];
            }
        }
        int[] answers = new int[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            int u = queries[qi][0];
            int v = queries[qi][1];
            if (u == v) {
                answers[qi] = 0;
                continue;
            }
            int pu = pos[u];
            int pv = pos[v];
            if (pu > pv) {
                int tmp = pu;
                pu = pv;
                pv = tmp;
            }
            int cur = pu;
            int steps = 0;
            for (int k = LOG - 1; k >= 0; k--) {
                int nxt = up[k][cur];
                if (nxt < pv) {
                    cur = nxt;
                    steps += 1 << k;
                }
            }
            answers[qi] = (far[cur] >= pv) ? steps + 1 : -1;
        }
        return answers;
    }
}

class Solution {
    public static int maxProductTwoDigits(long n) {
        if (n < 0) n = -n;
        if (n == 0) return 0;
        int max1 = -1, max2 = -1, countMax1 = 0;
        while (n > 0) {
            int d = (int) (n % 10);
            n /= 10;
            if (d > max1) {
                max2 = max1;
                max1 = d;
                countMax1 = 1;
            } else if (d == max1) {
                countMax1++;
            } else if (d > max2) {
                max2 = d;
            }
        }
        if (max1 == -1) return 0;
        if (countMax1 >= 2) return max1 * max1;
        if (max2 == -1) return 0;
        return max1 * max2;
    }
}

