class Solution {
    public static int minDeletions(String s, int k) {
        int[] freq = new int[26];
        for (char ch : s.toCharArray()) {
            freq[ch - 'a']++;
        }
        int distinct = 0;
        for (int f : freq) {
            if (f > 0) distinct++;
        }
        if (distinct <= k) return 0;
        int[] present = new int[distinct];
        int idx = 0;
        for (int f : freq) {
            if (f > 0) present[idx++] = f;
        }
        Arrays.sort(present);
        int deletions = 0;
        int toRemove = distinct - k;
        for (int i = 0; i < toRemove; i++) {
            deletions += present[i];
        }
        return deletions;
    }
}

class Solution {
    public long maxSum(int[][] edges, int[] nums, int k) {
        int n = nums.length;
        List<Integer>[] adj = new List[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) { adj[e[0]].add(e[1]); adj[e[1]].add(e[0]); }

        int[] parent = new int[n];
        Arrays.fill(parent, -1);
        int[] order = new int[n];
        int oi = 0;
        boolean[] visited = new boolean[n];
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(0);
        visited[0] = true;
        while (!stack.isEmpty()) {
            int u = stack.pop();
            order[oi++] = u;
            for (int v : adj[u]) {
                if (!visited[v]) { visited[v] = true; parent[v] = u; stack.push(v); }
            }
        }

        long[][][] dp = new long[n][][];
        for (int idx = n-1; idx >= 0; idx--) {
            int v = order[idx];
            List<Integer> children = new ArrayList<>();
            for (int c : adj[v]) if (c != parent[v]) children.add(c);
            long[][] table = new long[k+1][2];
            for (int dist = 0; dist <= k; dist++) {
                for (int sidx = 0; sidx < 2; sidx++) {
                    int sign = sidx == 0 ? 1 : -1;
                    long noInvert = (long) sign * nums[v];
                    int cdist = Math.min(dist+1, k);
                    for (int c : children) noInvert += dp[c][cdist][sidx];
                    long best = noInvert;
                    if (dist >= k) {
                        long invert = (long) -sign * nums[v];
                        for (int c : children) invert += dp[c][1][1-sidx];
                        best = Math.max(best, invert);
                    }
                    table[dist][sidx] = best;
                }
            }
            dp[v] = table;
        }
        return dp[0][k][0];
    }
}

class Solution {
    static final int N = 31;
    static final long MOD = 1_000_000_007L;
    private static final long[] f = new long[N];
    private static final long[] g = new long[N];
    private Long[][][][] dp;
    static {
        f[0] = 1; g[0] = 1;
        for (int i = 1; i < N; ++i) { f[i] = f[i-1]*i % MOD; g[i] = qpow(f[i], MOD-2); }
    }
    public static long qpow(long a, long k) {
        long res = 1;
        while (k != 0) { if ((k&1)==1) res = res*a%MOD; a = a*a%MOD; k >>= 1; }
        return res;
    }
    public static long comb(int m, int n) { return f[m]*g[n]%MOD*g[m-n]%MOD; }
    public int magicalSum(int m, int k, int[] nums) {
        int n = nums.length;
        dp = new Long[n+1][m+1][k+1][N];
        return (int) dfs(0, m, k, 0, nums);
    }
    private long dfs(int i, int j, int k, int st, int[] nums) {
        if (k < 0 || (i == nums.length && j > 0)) return 0;
        if (i == nums.length) {
            while (st > 0) { k -= (st&1); st >>= 1; }
            return k == 0 ? 1 : 0;
        }
        if (dp[i][j][k][st] != null) return dp[i][j][k][st];
        long res = 0;
        for (int t = 0; t <= j; t++) {
            int nt = t + st;
            int nk = k - (nt & 1);
            long p = qpow(nums[i], t);
            long tmp = comb(j, t) * p % MOD * dfs(i+1, j-t, nk, nt>>1, nums) % MOD;
            res = (res + tmp) % MOD;
        }
        return dp[i][j][k][st] = res;
    }
}

public class Solution {
    private static final boolean[] IS_VOWEL = new boolean[26];
    static {
        IS_VOWEL['a' - 'a'] = true;
        IS_VOWEL['e' - 'a'] = true;
        IS_VOWEL['i' - 'a'] = true;
        IS_VOWEL['o' - 'a'] = true;
        IS_VOWEL['u' - 'a'] = true;
    }
    public static int mostFrequentVowelConsonant(String s) {
        int[] freq = new int[26];
        int maxVowel = 0, maxConsonant = 0;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch < 'a' || ch > 'z') continue;
            int idx = ch - 'a';
            int count = ++freq[idx];
            if (IS_VOWEL[idx]) {
                if (count > maxVowel) maxVowel = count;
            } else {
                if (count > maxConsonant) maxConsonant = count;
            }
        }
        return maxVowel + maxConsonant;
    }
}

