class Solution {
    public static int maxWeightKEdgePath(int n, int[][] edges, int k, int t) {
        if (k == 0) {
            return t > 0 ? 0 : -1;
        }
        int[] prev = new int[n];
        int[] cur = new int[n];
        Arrays.fill(prev, 0);
        for (int step = 1; step <= k; step++) {
            Arrays.fill(cur, -1);
            for (int[] e : edges) {
                int u = e[0];
                int v = e[1];
                int w = e[2];
                if (prev[u] != -1) {
                    int newWeight = prev[u] + w;
                    if (newWeight < t) {
                        if (newWeight > cur[v]) {
                            cur[v] = newWeight;
                        }
                    }
                }
            }
            int[] temp = prev;
            prev = cur;
            cur = temp;
        }
        int ans = -1;
        for (int weight : prev) {
            if (weight > ans) {
                ans = weight;
            }
        }
        return ans;
    }
}

