public class Solution {
    public static boolean equalSumGridPartition(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) return false;
        int m = grid.length;
        int n = grid[0].length;
        long[] rowSums = new long[m];
        long[] colSums = new long[n];
        long total = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                long v = grid[i][j];
                total += v;
                rowSums[i] += v;
                colSums[j] += v;
            }
        }
        long prefix = 0;
        for (int i = 0; i < m - 1; i++) {
            prefix += rowSums[i];
            if (prefix * 2 == total) return true;
        }
        prefix = 0;
        for (int j = 0; j < n - 1; j++) {
            prefix += colSums[j];
            if (prefix * 2 == total) return true;
        }
        return false;
    }
}

