class Solution {
    public static long[] minimumWeightedSubgraph(int[][] edges, int[][] queries) {
        int maxNode = 0;
        for (int[] e : edges) {
            maxNode = Math.max(maxNode, Math.max(e[0], e[1]));
        }
        for (int[] q : queries) {
            maxNode = Math.max(maxNode, Math.max(q[0], Math.max(q[1], q[2])));
        }
        int n = maxNode + 1;
        List<int[]>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0], v = e[1], w = e[2];
            adj[u].add(new int[]{v, w});
            adj[v].add(new int[]{u, w});
        }
        int LOG = 1;
        while ((1 << LOG) <= n) LOG++;
        int[][] up = new int[LOG][n];
        int[] depth = new int[n];
        long[] dist = new long[n];
        boolean[] visited = new boolean[n];
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(0);
        visited[0] = true;
        up[0][0] = 0;
        while (!stack.isEmpty()) {
            int u = stack.pop();
            for (int[] nb : adj[u]) {
                int v = nb[0];
                int w = nb[1];
                if (!visited[v]) {
                    visited[v] = true;
                    up[0][v] = u;
                    depth[v] = depth[u] + 1;
                    dist[v] = dist[u] + w;
                    stack.push(v);
                }
            }
        }
        for (int k = 1; k < LOG; k++) {
            for (int v = 0; v < n; v++) {
                up[k][v] = up[k - 1][up[k - 1][v]];
            }
        }
        int q = queries.length;
        long[] ans = new long[q];
        for (int i = 0; i < q; i++) {
            int a = queries[i][0];
            int b = queries[i][1];
            int c = queries[i][2];
            long dAB = distance(a, b, up, depth, dist);
            long dAC = distance(a, c, up, depth, dist);
            long dBC = distance(b, c, up, depth, dist);
            ans[i] = (dAB + dAC + dBC) / 2;
        }
        return ans;
    }

    private static long distance(int u, int v, int[][] up, int[] depth, long[] dist) {
        int l = lca(u, v, up, depth);
        return dist[u] + dist[v] - 2L * dist[l];
    }

    private static int lca(int u, int v, int[][] up, int[] depth) {
        if (depth[u] < depth[v]) {
            int tmp = u; u = v; v = tmp;
        }
        int diff = depth[u] - depth[v];
        for (int k = up.length - 1; k >= 0; k--) {
            if ((diff & (1 << k)) != 0) {
                u = up[k][u];
            }
        }
        if (u == v) return u;
        for (int k = up.length - 1; k >= 0; k--) {
            if (up[k][u] != up[k][v]) {
                u = up[k][u];
                v = up[k][v];
            }
        }
        return up[0][u];
    }
}

import java.util.*;

public class H5 {
    static long maxScore(int n, int[][] edges) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        int m = edges.length;
        boolean isCycle = (m == n);

        List<Integer> order = new ArrayList<>();
        boolean[] visited = new boolean[n];
        int start = 0;
        if (!isCycle) {
            for (int i = 0; i < n; i++) {
                if (adj.get(i).size() <= 1) { start = i; break; }
            }
        }
        int prev = -1, cur = start;
        while (cur != -1) {
            order.add(cur);
            visited[cur] = true;
            int nxt = -1;
            for (int nb : adj.get(cur)) {
                if (nb != prev && !visited[nb]) { nxt = nb; break; }
            }
            prev = cur;
            cur = nxt;
            if (isCycle && cur == start) break;
        }

        int k = order.size();
        int[] vals = new int[k];
        for (int i = 0; i < k; i++) vals[i] = k - i;

        Deque<Integer> arrangement = new ArrayDeque<>();
        arrangement.add(vals[0]);
        for (int i = 1; i < k; i++) {
            if (i % 2 == 1) arrangement.addLast(vals[i]);
            else arrangement.addFirst(vals[i]);
        }
        List<Integer> arrList = new ArrayList<>(arrangement);

        int[] value = new int[n];
        for (int idx = 0; idx < k; idx++) value[order.get(idx)] = arrList.get(idx);

        long total = 0;
        for (int i = 0; i < k - 1; i++) total += (long) value[order.get(i)] * value[order.get(i+1)];
        if (isCycle) total += (long) value[order.get(k-1)] * value[order.get(0)];
        return total;
    }

    public static void main(String[] args) {
        System.out.println(maxScore(4, new int[][]{{0,1},{1,2},{2,3}}) + " expected 23");
        System.out.println(maxScore(6, new int[][]{{0,3},{4,5},{2,0},{1,3},{2,4},{1,5}}) + " expected 82");
    }
}

import java.util.*;

public class GridPartition {
    static boolean checkSection(int[][] mat) {
        int rows = mat.length, cols = mat[0].length;
        long[] rowSum = new long[rows];
        for (int i = 0; i < rows; i++) for (int v : mat[i]) rowSum[i] += v;
        long total = 0; for (long s : rowSum) total += s;
        long topSum = 0;
        Map<Integer,Integer> topFreq = new HashMap<>();
        Map<Integer,Integer> fullFreq = new HashMap<>();
        for (int[] row : mat) for (int v : row) fullFreq.merge(v, 1, Integer::sum);
        Map<Integer,Integer> botFreq = new HashMap<>(fullFreq);

        for (int r = 0; r < rows - 1; r++) {
            topSum += rowSum[r];
            for (int v : mat[r]) {
                topFreq.merge(v, 1, Integer::sum);
                int nb = botFreq.get(v) - 1;
                if (nb == 0) botFreq.remove(v); else botFreq.put(v, nb);
            }
            long botSum = total - topSum;
            int topRows = r + 1, botRows = rows - topRows;
            if (topSum == botSum) return true;
            long diff = Math.abs(topSum - botSum);
            int diffI = (int) diff;
            if (topSum > botSum) {
                if (topFreq.containsKey(diffI)) {
                    if (topRows >= 2 && cols >= 2) return true;
                    if (topRows == 1) {
                        if (mat[0][0] == diffI || mat[0][cols-1] == diffI) return true;
                    } else if (cols == 1) {
                        if (mat[0][0] == diffI || mat[topRows-1][0] == diffI) return true;
                    }
                }
            } else {
                if (botFreq.containsKey(diffI)) {
                    if (botRows >= 2 && cols >= 2) return true;
                    if (botRows == 1) {
                        if (mat[r+1][0] == diffI || mat[r+1][cols-1] == diffI) return true;
                    } else if (cols == 1) {
                        if (mat[r+1][0] == diffI || mat[rows-1][0] == diffI) return true;
                    }
                }
            }
        }
        return false;
    }

    static boolean equalSumGridPartition(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        if (checkSection(grid)) return true;
        int[][] t = new int[n][m];
        for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) t[j][i] = grid[i][j];
        if (checkSection(t)) return true;
        return false;
    }
}

import java.util.HashSet;
import java.util.PriorityQueue;

class Solution {
    public static int sumLargestPrimes(String s) {
        int n = s.length();
        HashSet<Integer> seen = new HashSet<>();
        PriorityQueue<Integer> top = new PriorityQueue<>(3);
        for (int i = 0; i < n; i++) {
            long cur = 0;
            for (int j = i; j < n; j++) {
                cur = cur * 10 + (s.charAt(j) - '0');
                if (cur > Integer.MAX_VALUE) break;
                int num = (int) cur;
                if (num < 2) continue;
                if (seen.add(num) && isPrime(num)) {
                    if (top.size() < 3) {
                        top.offer(num);
                    } else if (num > top.peek()) {
                        top.poll();
                        top.offer(num);
                    }
                }
            }
        }
        int sum = 0;
        while (!top.isEmpty()) {
            sum += top.poll();
        }
        return sum;
    }

    private static boolean isPrime(int num) {
        if (num % 2 == 0) return num == 2;
        int sqrt = (int) Math.sqrt(num);
        for (int i = 3; i <= sqrt; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }
}

import java.util.*;

class Solution {
    public int maxNumberOfSubstrings(String word) {
        int n = word.length();
        int[][] next = new int[n + 1][26];
        for (int c = 0; c < 26; c++) {
            next[n][c] = n;
        }
        for (int i = n - 1; i >= 0; i--) {
            for (int c = 0; c < 26; c++) {
                next[i][c] = next[i + 1][c];
            }
            next[i][word.charAt(i) - 'a'] = i;
        }

        List<int[]> intervals = new ArrayList<>();
        for (int i = 0; i + 3 < n; i++) {
            int c = word.charAt(i) - 'a';
            int j = next[i + 3][c];
            if (j < n) {
                intervals.add(new int[]{i, j});
            }
        }

        intervals.sort(Comparator.comparingInt(a -> a[1]));

        int count = 0;
        int lastEnd = -1;
        for (int[] seg : intervals) {
            if (seg[0] > lastEnd) {
                count++;
                lastEnd = seg[1];
            }
        }
        return count;
    }
}

import java.util.*;

class Solution {
    private static int digitSum(int n) {
        int sum = 0;
        while (n > 0) {
            sum += n % 10;
            n /= 10;
        }
        return sum;
    }

    private static class Pair {
        int value;
        int digitSum;
        int originalIdx;
        Pair(int value, int digitSum, int originalIdx) {
            this.value = value;
            this.digitSum = digitSum;
            this.originalIdx = originalIdx;
        }
    }

    public static int minSwaps(int[] nums) {
        int n = nums.length;
        if (n <= 1) return 0;
        Pair[] arr = new Pair[n];
        for (int i = 0; i < n; i++) {
            arr[i] = new Pair(nums[i], digitSum(nums[i]), i);
        }
        Arrays.sort(arr, (a, b) -> {
            if (a.digitSum != b.digitSum) return a.digitSum - b.digitSum;
            return a.value - b.value;
        });
        int[] target = new int[n];
        for (int i = 0; i < n; i++) {
            target[arr[i].originalIdx] = i;
        }
        boolean[] visited = new boolean[n];
        int swaps = 0;
        for (int i = 0; i < n; i++) {
            if (visited[i] || target[i] == i) continue;
            int cycleLen = 0;
            int j = i;
            while (!visited[j]) {
                visited[j] = true;
                j = target[j];
                cycleLen++;
            }
            if (cycleLen > 1) swaps += cycleLen - 1;
        }
        return swaps;
    }
}

