public class Solution {
    public static String removeAdjacent(String s) {
        int n = s.length();
        char[] stack = new char[n];
        int top = -1;
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (top >= 0) {
                char last = stack[top];
                if (c == last + 1 || c == last - 1 || (c == 'a' && last == 'z') || (c == 'z' && last == 'a')) {
                    top--;
                    continue;
                }
            }
            stack[++top] = c;
        }
        return new String(stack, 0, top + 1);
    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;

public class Solution {
    public static int minMoves(String[] matrix) {
        int m = matrix.length;
        int n = matrix[0].length();
        if (matrix[0].charAt(0) == '#' || matrix[m - 1].charAt(n - 1) == '#') {
            return -1;
        }
        int total = m * n;
        int[] dist = new int[total];
        for (int i = 0; i < total; i++) dist[i] = -1;

        List<List<Integer>> portals = new ArrayList<>(26);
        for (int i = 0; i < 26; i++) portals.add(new ArrayList<>());

        for (int i = 0; i < m; i++) {
            String row = matrix[i];
            for (int j = 0; j < n; j++) {
                char ch = row.charAt(j);
                if (ch >= 'A' && ch <= 'Z') {
                    portals.get(ch - 'A').add(i * n + j);
                }
            }
        }

        ArrayDeque<Integer> deque = new ArrayDeque<>();
        int start = 0;
        dist[start] = 0;
        deque.offerFirst(start);
        boolean[] used = new boolean[26];
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!deque.isEmpty()) {
            int cur = deque.pollFirst();
            int r = cur / n;
            int c = cur % n;
            int d = dist[cur];
            if (cur == total - 1) {
                return d;
            }

            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k];
                int nc = c + dc[k];
                if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
                if (matrix[nr].charAt(nc) == '#') continue;
                int nxt = nr * n + nc;
                if (dist[nxt] != -1) continue;
                dist[nxt] = d + 1;
                deque.offerLast(nxt);
            }

            char ch = matrix[r].charAt(c);
            if (ch >= 'A' && ch <= 'Z') {
                int idx = ch - 'A';
                if (!used[idx]) {
                    used[idx] = true;
                    for (int pos : portals.get(idx)) {
                        if (dist[pos] == -1) {
                            dist[pos] = d;
                            deque.offerFirst(pos);
                        }
                    }
                    portals.set(idx, null);
                }
            }
        }
        return -1;
    }
}

import java.util.*;

class Solution {
    private static final int MOD = 1_000_000_007;

    public static int numberOfWays(int[][] edges) {
        int n = edges.length + 1;
        List<Integer>[] graph = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            int u = e[0], v = e[1];
            graph[u].add(v);
            graph[v].add(u);
        }

        int[] depth = new int[n + 1];
        Arrays.fill(depth, -1);
        int[] queue = new int[n];
        int head = 0, tail = 0;
        queue[tail++] = 1;
        depth[1] = 0;
        int maxDepth = 0;

        while (head < tail) {
            int cur = queue[head++];
            for (int nxt : graph[cur]) {
                if (depth[nxt] == -1) {
                    depth[nxt] = depth[cur] + 1;
                    if (depth[nxt] > maxDepth) {
                        maxDepth = depth[nxt];
                    }
                    queue[tail++] = nxt;
                }
            }
        }

        long result = modPow(2, Math.max(0, maxDepth - 1));
        return (int) result;
    }

    private static long modPow(long base, int exp) {
        long res = 1;
        long b = base % MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * b) % MOD;
            }
            b = (b * b) % MOD;
            exp >>= 1;
        }
        return res;
    }
}

import java.util.*;

class Solution {
    private static final long MOD = 1_000_000_007L;

    public static long[] numberOfWays(int n, int[][] edges, int[][] queries) {
        List<Integer>[] adj = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0], v = e[1];
            adj[u].add(v);
            adj[v].add(u);
        }

        int LOG = 1;
        while ((1 << LOG) <= n) LOG++;

        int[][] up = new int[LOG][n + 1];
        int[] depth = new int[n + 1];
        int[] queue = new int[n];
        int head = 0, tail = 0;
        queue[tail++] = 1;
        depth[1] = 0;
        up[0][1] = 0;
        boolean[] visited = new boolean[n + 1];
        visited[1] = true;
        while (head < tail) {
            int node = queue[head++];
            for (int nb : adj[node]) {
                if (!visited[nb]) {
                    visited[nb] = true;
                    depth[nb] = depth[node] + 1;
                    up[0][nb] = node;
                    queue[tail++] = nb;
                }
            }
        }

        for (int k = 1; k < LOG; k++) {
            for (int v = 1; v <= n; v++) {
                int mid = up[k - 1][v];
                up[k][v] = mid == 0 ? 0 : up[k - 1][mid];
            }
        }

        long[] pow2 = new long[n];
        pow2[0] = 1;
        for (int i = 1; i < n; i++) {
            pow2[i] = (pow2[i - 1] << 1) % MOD;
        }

        long[] ans = new long[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int u = queries[i][0];
            int v = queries[i][1];
            int lca = lca(u, v, depth, up, LOG);
            int dist = depth[u] + depth[v] - 2 * depth[lca];
            ans[i] = dist == 0 ? 0 : pow2[dist - 1];
        }
        return ans;
    }

    private static int lca(int a, int b, int[] depth, int[][] up, int LOG) {
        if (depth[a] < depth[b]) {
            int tmp = a;
            a = b;
            b = tmp;
        }
        int diff = depth[a] - depth[b];
        for (int k = LOG - 1; k >= 0; k--) {
            if ((diff & (1 << k)) != 0) {
                a = up[k][a];
            }
        }
        if (a == b) return a;
        for (int k = LOG - 1; k >= 0; k--) {
            if (up[k][a] != up[k][b]) {
                a = up[k][a];
                b = up[k][b];
            }
        }
        return up[0][a];
    }
}

public class Solution {
    public static long minCost(int n, int m, int k) {
        long L = Math.max(n, m);
        if (L <= k) return 0L;
        long kk = k;
        return (L - kk) * kk;
    }
}

import java.util.*;

class Solution {
    public static int[][] minAbsDiffInSlidingSubmatrix(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;
        int rows = m - k + 1;
        int cols = n - k + 1;
        int[][] ans = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            TreeMap<Integer, Integer> multiset = new TreeMap<>();
            for (int x = i; x < i + k; x++) {
                for (int y = 0; y < k; y++) {
                    multiset.merge(grid[x][y], 1, Integer::sum);
                }
            }
            ans[i][0] = computeMinDiff(multiset);
            for (int j = 1; j < cols; j++) {
                for (int x = i; x < i + k; x++) {
                    remove(multiset, grid[x][j - 1]);
                    multiset.merge(grid[x][j + k - 1], 1, Integer::sum);
                }
                ans[i][j] = computeMinDiff(multiset);
            }
        }
        return ans;
    }

    private static void remove(TreeMap<Integer, Integer> map, int key) {
        int cnt = map.get(key);
        if (cnt == 1) {
            map.remove(key);
        } else {
            map.put(key, cnt - 1);
        }
    }

    private static int computeMinDiff(TreeMap<Integer, Integer> map) {
        if (map.isEmpty() || map.size() == 1) {
            return 0;
        }
        Integer prev = null;
        int minDiff = Integer.MAX_VALUE;
        for (Integer key : map.keySet()) {
            if (prev != null) {
                int diff = key - prev;
                if (diff < minDiff) {
                    minDiff = diff;
                }
            }
            prev = key;
        }
        return minDiff;
    }
}

import java.util.*;

class Solution {
    private static final long NEG = -1_000_000_000L;
    static int budget;
    static int[] present, future;
    static List<Integer>[] children;

    public static long maxProfitFromStocks(int n, int[] present_, int[] future_, int[][] hierarchy, int budget_) {
        present = present_; future = future_; budget = budget_;
        children = new List[n];
        for (int i = 0; i < n; i++) children[i] = new ArrayList<>();
        for (int[] e : hierarchy) children[e[0]-1].add(e[1]-1);
        long[][] rootRes = dfs(0);
        long best = 0;
        for (int c = 0; c <= budget; c++) best = Math.max(best, rootRes[0][c]);
        return best;
    }

    private static long[][] dfs(int node) {
        long[] dpNot = new long[budget+1]; Arrays.fill(dpNot, NEG); dpNot[0] = 0;
        long costFull = present[node]; long profitFull = future[node] - costFull;
        long[] dpBuyFull = new long[budget+1]; Arrays.fill(dpBuyFull, NEG);
        if (costFull <= budget) dpBuyFull[(int)costFull] = profitFull;
        long costDisc = present[node]/2; long profitDisc = future[node] - costDisc;
        long[] dpBuyDisc = new long[budget+1]; Arrays.fill(dpBuyDisc, NEG);
        if (costDisc <= budget) dpBuyDisc[(int)costDisc] = profitDisc;

        for (int ch : children[node]) {
            long[][] childRes = dfs(ch);
            long[] childF0 = childRes[0], childF1 = childRes[1];

            long[] newNot = new long[budget+1]; Arrays.fill(newNot, NEG);
            for (int cur = 0; cur <= budget; cur++) {
                if (dpNot[cur] == NEG) continue;
                for (int c = 0; c <= budget-cur; c++) {
                    if (childF0[c] == NEG) continue;
                    long val = dpNot[cur] + childF0[c];
                    if (val > newNot[cur+c]) newNot[cur+c] = val;
                }
            }
            dpNot = newNot;

            long[] newFull = new long[budget+1]; Arrays.fill(newFull, NEG);
            for (int cur = 0; cur <= budget; cur++) {
                if (dpBuyFull[cur] == NEG) continue;
                for (int c = 0; c <= budget-cur; c++) {
                    if (childF1[c] == NEG) continue;
                    long val = dpBuyFull[cur] + childF1[c];
                    if (val > newFull[cur+c]) newFull[cur+c] = val;
                }
            }
            dpBuyFull = newFull;

            long[] newDisc = new long[budget+1]; Arrays.fill(newDisc, NEG);
            for (int cur = 0; cur <= budget; cur++) {
                if (dpBuyDisc[cur] == NEG) continue;
                for (int c = 0; c <= budget-cur; c++) {
                    if (childF1[c] == NEG) continue;
                    long val = dpBuyDisc[cur] + childF1[c];
                    if (val > newDisc[cur+c]) newDisc[cur+c] = val;
                }
            }
            dpBuyDisc = newDisc;
        }

        long[] f0 = new long[budget+1], f1 = new long[budget+1];
        for (int c = 0; c <= budget; c++) {
            f0[c] = Math.max(dpNot[c], dpBuyFull[c]);
            f1[c] = Math.max(dpNot[c], dpBuyDisc[c]);
        }
        return new long[][]{f0, f1};
    }
}

class Solution {
    static boolean adjacent(char a, char b) {
        int diff = ((a - b) % 26 + 26) % 26;
        return diff == 1 || diff == 25;
    }

    public String smallestString(String s) {
        int n = s.length();
        // canEmpty[i][j]: substring s[i..j] can be fully reduced to nothing.
        // Standard bracket-matching decomposition: the character at i must eventually
        // cancel with some s[k+1], with everything strictly between them (s[i+1..k])
        // fully reducible first, and everything after (s[k+2..j]) independently reducible too.
        boolean[][] canEmpty = new boolean[n][n];
        for (int length = 2; length <= n; length += 2) {
            for (int i = 0; i + length - 1 < n; i++) {
                int j = i + length - 1;
                for (int k = i; k < j; k += 2) {
                    boolean midEmpty = (k == i) || canEmpty[i+1][k];
                    if (midEmpty && adjacent(s.charAt(i), s.charAt(k+1))) {
                        boolean restOk = (k+2 > j) || canEmpty[k+2][j];
                        if (restOk) { canEmpty[i][j] = true; break; }
                    }
                }
            }
        }
        // best[i]: lexicographically smallest achievable string for suffix s[i:] - either
        // keep s[i] as-is, or fully eliminate some range s[i..j] entirely and continue from j+1.
        String[] best = new String[n+1];
        best[n] = "";
        for (int i = n-1; i >= 0; i--) {
            String cand = s.charAt(i) + best[i+1];
            for (int j = i+1; j < n; j += 2) {
                if (canEmpty[i][j]) {
                    String c2 = best[j+1];
                    if (c2.compareTo(cand) < 0) cand = c2;
                }
            }
            best[i] = cand;
        }
        return best[0];
    }
}

import java.math.BigInteger;
import java.util.Arrays;
import java.util.Collections;

class Solution {
    public static boolean canPartition(int[] nums, int target) {
        BigInteger total = BigInteger.ONE;
        for (int n : nums) {
            total = total.multiply(BigInteger.valueOf(n));
        }
        BigInteger t = BigInteger.valueOf(target);
        if (!total.equals(t.multiply(t))) {
            return false;
        }
        if (target == 0) {
            int zeroCount = 0;
            for (int n : nums) {
                if (n == 0) zeroCount++;
            }
            return zeroCount >= 2;
        }
        Integer[] boxed = new Integer[nums.length];
        for (int i = 0; i < nums.length; i++) boxed[i] = nums[i];
        Arrays.sort(boxed, Collections.reverseOrder());
        int[] sorted = new int[nums.length];
        for (int i = 0; i < nums.length; i++) sorted[i] = boxed[i];
        return dfs(sorted, 0, BigInteger.ONE, 0, t);
    }

    private static boolean dfs(int[] nums, int idx, BigInteger prod, int cnt, BigInteger target) {
        if (prod.equals(target)) {
            return cnt > 0 && cnt < nums.length;
        }
        if (idx == nums.length || prod.compareTo(target) > 0) {
            return false;
        }
        BigInteger newProd = prod.multiply(BigInteger.valueOf(nums[idx]));
        if (newProd.compareTo(target) <= 0) {
            if (dfs(nums, idx + 1, newProd, cnt + 1, target)) {
                return true;
            }
        }
        return dfs(nums, idx + 1, prod, cnt, target);
    }
}

import java.util.ArrayDeque;
import java.util.Arrays;

class Solution {
    public static int minMoves(String[] classroom, int energy) {
        int m = classroom.length;
        int n = classroom[0].length();
        char[][] grid = new char[m][n];
        int startR = -1, startC = -1;
        int[][] litterIdx = new int[m][n];
        for (int i = 0; i < m; i++) {
            grid[i] = classroom[i].toCharArray();
            Arrays.fill(litterIdx[i], -1);
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'S') {
                    startR = i;
                    startC = j;
                }
            }
        }
        int litterCount = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'L') {
                    litterIdx[i][j] = litterCount++;
                }
            }
        }
        if (litterCount == 0) return 0;
        int allMask = (1 << litterCount) - 1;
        int totalStates = m * n * (energy + 1) * (1 << litterCount);
        boolean[] visited = new boolean[totalStates];
        int[] dist = new int[totalStates];
        Arrays.fill(dist, -1);
        int startState = encode(startR, startC, energy, 0, n, energy, litterCount);
        visited[startState] = true;
        dist[startState] = 0;
        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(startState);
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
        while (!q.isEmpty()) {
            int cur = q.poll();
            int curDist = dist[cur];
            int mask = cur & ((1 << litterCount) - 1);
            int tmp = cur >>> litterCount;
            int curEnergy = tmp % (energy + 1);
            tmp /= (energy + 1);
            int cellIdx = tmp;
            int r = cellIdx / n;
            int c = cellIdx % n;
            if (mask == allMask) return curDist;
            int usableEnergy = curEnergy;
            if (usableEnergy == 0 && grid[r][c] == 'R') usableEnergy = energy;
            if (usableEnergy == 0) continue;
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
                char ch = grid[nr][nc];
                if (ch == 'X') continue;
                int newEnergy = usableEnergy - 1;
                if (newEnergy == 0 && ch == 'R') newEnergy = energy;
                int newMask = mask;
                if (ch == 'L') {
                    int idx = litterIdx[nr][nc];
                    newMask = mask | (1 << idx);
                }
                int nextState = encode(nr, nc, newEnergy, newMask, n, energy, litterCount);
                if (!visited[nextState]) {
                    visited[nextState] = true;
                    dist[nextState] = curDist + 1;
                    q.add(nextState);
                }
            }
        }
        return -1;
    }

    private static int encode(int r, int c, int e, int mask, int n, int maxEnergy, int litterCount) {
        int cellIdx = r * n + c;
        return ((cellIdx * (maxEnergy + 1) + e) << litterCount) | mask;
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

class Solution {
    private static final int MOD = 1_000_000_007;
    private static final int MASK_SIZE = 1 << 10;
    private static final long NEG_INF = Long.MIN_VALUE / 4;

    public static int maximumGoodSubtreeScore(int[] vals, int[] par) {
        int n = vals.length;
        List<Integer>[] children = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            children[i] = new ArrayList<>();
        }
        for (int i = 1; i < n; i++) {
            children[par[i]].add(i);
        }

        int[] nodeMask = new int[n];
        for (int i = 0; i < n; i++) {
            int v = vals[i];
            int mask = 0;
            boolean ok = true;
            while (v > 0) {
                int d = v % 10;
                if ((mask & (1 << d)) != 0) {
                    ok = false;
                    break;
                }
                mask |= 1 << d;
                v /= 10;
            }
            nodeMask[i] = ok ? mask : -1;
        }

        long[] maxScore = new long[n];
        dfs(0, vals, nodeMask, children, maxScore);
        long total = 0;
        for (long s : maxScore) {
            total = (total + s) % MOD;
        }
        return (int) total;
    }

    private static long[] dfs(int u, int[] vals, int[] nodeMask, List<Integer>[] children, long[] maxScore) {
        long[] dp = new long[MASK_SIZE];
        Arrays.fill(dp, NEG_INF);
        dp[0] = 0;
        for (int v : children[u]) {
            long[] childDP = dfs(v, vals, nodeMask, children, maxScore);
            long[] newDP = new long[MASK_SIZE];
            Arrays.fill(newDP, NEG_INF);
            for (int m1 = 0; m1 < MASK_SIZE; m1++) {
                long val1 = dp[m1];
                if (val1 == NEG_INF) continue;
                for (int m2 = 0; m2 < MASK_SIZE; m2++) {
                    long val2 = childDP[m2];
                    if (val2 == NEG_INF) continue;
                    if ((m1 & m2) != 0) continue;
                    int nm = m1 | m2;
                    long sum = val1 + val2;
                    if (sum > newDP[nm]) newDP[nm] = sum;
                }
            }
            for (int m = 0; m < MASK_SIZE; m++) {
                if (newDP[m] > dp[m]) dp[m] = newDP[m];
            }
        }

        int mask = nodeMask[u];
        if (mask != -1) {
            for (int m = MASK_SIZE - 1; m >= 0; m--) {
                long cur = dp[m];
                if (cur == NEG_INF) continue;
                if ((m & mask) != 0) continue;
                int nm = m | mask;
                long sum = cur + vals[u];
                if (sum > dp[nm]) dp[nm] = sum;
            }
        }

        long best = 0;
        for (long v : dp) {
            if (v > best) best = v;
        }
        maxScore[u] = best;
        return dp;
    }
}

class Solution {
    static final int MAXV = 100000;
    static boolean[] IS_PRIME = buildSieve();

    static boolean[] buildSieve() {
        boolean[] isP = new boolean[MAXV + 1];
        Arrays.fill(isP, true);
        isP[0] = isP[1] = false;
        for (int i = 2; (long) i * i <= MAXV; i++)
            if (isP[i]) for (int j = i * i; j <= MAXV; j += i) isP[j] = false;
        return isP;
    }

    public int[] maximizeDistinctPrimeCount(int[] nums, int[][] queries) {
        int n = nums.length;
        int[] ans = new int[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            int idx = queries[qi][0], val = queries[qi][1];
            nums[idx] = val;
            Map<Integer, int[]> positions = new HashMap<>();
            int totalDistinct = 0;
            for (int i = 0; i < n; i++) {
                int v = nums[i];
                if (v <= MAXV && IS_PRIME[v]) {
                    if (!positions.containsKey(v)) {
                        positions.put(v, new int[]{i, i});
                        totalDistinct++;
                    } else {
                        positions.get(v)[1] = i;
                    }
                }
            }
            int[] diff = new int[n + 1];
            for (int[] pr : positions.values()) {
                int first = pr[0], last = pr[1];
                if (last > first) {
                    int l = first + 1, r = last;
                    diff[l] += 1;
                    diff[r + 1] -= 1;
                }
            }
            int bestOverlap = 0, cur = 0;
            for (int p = 1; p < n; p++) {
                cur += diff[p];
                bestOverlap = Math.max(bestOverlap, cur);
            }
            ans[qi] = totalDistinct + bestOverlap;
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    public static long maxScore(int[] nums, int k) {
        int n = nums.length;
        int[] prefixOdd = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefixOdd[i + 1] = prefixOdd[i] + (nums[i] & 1);
        }
        long best = 0;
        List<long[]> cur = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            List<long[]> nxt = new ArrayList<>();
            nxt.add(new long[]{nums[i], i});
            for (long[] p : cur) {
                long g = gcd(p[0], nums[i]);
                long start = p[1];
                long[] last = nxt.get(nxt.size() - 1);
                if (last[0] == g) {
                    if (start < last[1]) {
                        last[1] = start;
                    }
                } else {
                    nxt.add(new long[]{g, start});
                }
            }
            for (long[] p : nxt) {
                long g = p[0];
                int s = (int) p[1];
                int len = i - s + 1;
                long score = len * g;
                if (score > best) best = score;
                int odd = prefixOdd[i + 1] - prefixOdd[s];
                if (odd <= k) {
                    long doubled = score << 1;
                    if (doubled > best) best = doubled;
                }
            }
            cur = nxt;
        }
        return best;
    }

    private static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

