import java.util.HashMap;
import java.util.Map;

class Solution {
    public static int maxYSum(int[] x, int[] y) {
        Map<Integer, Integer> best = new HashMap<>();
        for (int i = 0; i < x.length; i++) {
            int curX = x[i];
            int curY = y[i];
            Integer prev = best.get(curX);
            if (prev == null || curY > prev) {
                best.put(curX, curY);
            }
        }
        if (best.size() < 3) {
            return -1;
        }
        int first = Integer.MIN_VALUE;
        int second = Integer.MIN_VALUE;
        int third = Integer.MIN_VALUE;
        for (int val : best.values()) {
            if (val > first) {
                third = second;
                second = first;
                first = val;
            } else if (val > second) {
                third = second;
                second = val;
            } else if (val > third) {
                third = val;
            }
        }
        return first + second + third;
    }
}

public class P9 {
    static final long NEG = Long.MIN_VALUE / 2;

    static long maximumProfit(int[] prices, int k) {
        int n = prices.length;
        long[][] f = new long[k+1][3];
        for (long[] row : f) java.util.Arrays.fill(row, NEG);
        f[0][0] = 0;
        for (int j = 1; j <= k; j++) {
            f[j][0] = 0;
            f[j][1] = -prices[0];
            f[j][2] = prices[0];
        }
        for (int i = 1; i < n; i++) {
            long[][] nf = new long[k+1][3];
            for (long[] row : nf) java.util.Arrays.fill(row, NEG);
            nf[0][0] = 0;
            for (int j = 1; j <= k; j++) {
                long best0 = f[j][0];
                if (f[j][1] > NEG) best0 = Math.max(best0, f[j][1] + prices[i]);
                if (f[j][2] > NEG) best0 = Math.max(best0, f[j][2] - prices[i]);
                nf[j][0] = best0;

                long best1 = f[j][1];
                if (f[j-1][0] > NEG) best1 = Math.max(best1, f[j-1][0] - prices[i]);
                nf[j][1] = best1;

                long best2 = f[j][2];
                if (f[j-1][0] > NEG) best2 = Math.max(best2, f[j-1][0] + prices[i]);
                nf[j][2] = best2;
            }
            f = nf;
        }
        return f[k][0];
    }

    public static void main(String[] args) {
        System.out.println("got=" + maximumProfit(new int[]{1,7,9,8,2}, 2) + " expected=14");
        System.out.println("got=" + maximumProfit(new int[]{12,16,19,19,8,1,19,13,9}, 3) + " expected=36");
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    private static final int MOD = 1_000_000_007;

    public static int countPartitions(int[] nums, int k) {
        int n = nums.length;
        int[] pref = new int[n + 1];
        pref[0] = 1;
        int left = 0;
        Deque<Integer> maxDeque = new ArrayDeque<>();
        Deque<Integer> minDeque = new ArrayDeque<>();
        int dpCurr = 0;
        for (int right = 0; right < n; right++) {
            while (!maxDeque.isEmpty() && nums[maxDeque.peekLast()] <= nums[right]) {
                maxDeque.pollLast();
            }
            maxDeque.addLast(right);
            while (!minDeque.isEmpty() && nums[minDeque.peekLast()] >= nums[right]) {
                minDeque.pollLast();
            }
            minDeque.addLast(right);
            while (!maxDeque.isEmpty() && !minDeque.isEmpty()
                    && (long) nums[maxDeque.peekFirst()] - (long) nums[minDeque.peekFirst()] > k) {
                if (maxDeque.peekFirst() == left) {
                    maxDeque.pollFirst();
                }
                if (minDeque.peekFirst() == left) {
                    minDeque.pollFirst();
                }
                left++;
            }
            int sum = pref[right];
            if (left > 0) {
                sum -= pref[left - 1];
                if (sum < 0) sum += MOD;
            }
            dpCurr = sum;
            int newPref = pref[right] + dpCurr;
            if (newPref >= MOD) newPref -= MOD;
            pref[right + 1] = newPref;
        }
        return dpCurr;
    }
}

