        }
        return sb.toString();
    }
}

import java.math.*;

public class Solution {
    private static final int MOD = 1_000_000_007;

    public static int countPermutations(int[] complexity) {
        int n = complexity.length;
        int min = Integer.MAX_VALUE;
        int countMin = 0;
        int minIndex = -1;
        for (int i = 0; i < n; i++) {
            int v = complexity[i];
            if (v < min) {
                min = v;
                countMin = 1;
                minIndex = i;
            } else if (v == min) {
                countMin++;
            }
        }
        if (countMin != 1 || minIndex != 0) {
            return 0;
        }
        long fact = 1;
        for (int i = 2; i <= n - 1; i++) {
            fact = (fact * i) % MOD;
        }
        return (int) fact;
    }
}

class Solution {
    private String W1, W2;
    private int calc(int l, int r, boolean rev) {
        int[][] cnt = new int[26][26];
        int res = 0;
        for (int i = l; i <= r; i++) {
            int j = rev ? r - (i - l) : i;
            int a = W1.charAt(j) - 'a';
            int b = W2.charAt(i) - 'a';
            if (a != b) {
                if (cnt[b][a] > 0) cnt[b][a]--;
                else { cnt[a][b]++; res++; }
            }
        }
        return res;
    }
    public int minOperations(String word1, String word2) {
        W1 = word1; W2 = word2;
        int n = word1.length();
        int[] f = new int[n + 1];
        java.util.Arrays.fill(f, Integer.MAX_VALUE);
        f[0] = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < i; j++) {
                if (f[j] == Integer.MAX_VALUE) continue;
                int a = calc(j, i - 1, false);
                int b = 1 + calc(j, i - 1, true);
                int t = Math.min(a, b);
                f[i] = Math.min(f[i], f[j] + t);
            }
        }
        return f[n];
    }
}

class Solution {
    public int[] findMedian(int n, int[][] edges, int[][] queries) {
        List<int[]>[] adj = new List[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(new int[]{e[1], e[2]});
            adj[e[1]].add(new int[]{e[0], e[2]});
        }
        int LOG = Math.max(1, 32 - Integer.numberOfLeadingZeros(Math.max(n,1)));
        int[][] up = new int[LOG][n];
        int[] depth = new int[n];
        long[] dist = new long[n];
        boolean[] visited = new boolean[n];
        int[] parent0 = new int[n];
        Arrays.fill(parent0, -1);
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{0, -1, 0});
        visited[0] = true;
        List<Integer> order = new ArrayList<>();
        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            int u = cur[0], p = cur[1], d = cur[2];
            order.add(u);
            parent0[u] = p;
            depth[u] = d;
            for (int[] nb : adj[u]) {
                int v = nb[0], w = nb[1];
                if (!visited[v]) {
                    visited[v] = true;
                    dist[v] = dist[u] + w;
                    stack.push(new int[]{v, u, d+1});
                }
            }
        }
        for (int v : order) up[0][v] = parent0[v] != -1 ? parent0[v] : v;
        for (int k = 1; k < LOG; k++)
            for (int v = 0; v < n; v++)
                up[k][v] = up[k-1][up[k-1][v]];

        int q = queries.length;
        int[] ans = new int[q];
        for (int qi = 0; qi < q; qi++) {
            int u = queries[qi][0], v = queries[qi][1];
            int a = u, b = v;
            if (depth[a] < depth[b]) { int t=a; a=b; b=t; }
            int diff = depth[a]-depth[b];
            for (int k = 0; k < LOG; k++) if (((diff>>k)&1)!=0) a = up[k][a];
            int l;
            if (a == b) l = a;
            else {
                for (int k = LOG-1; k >= 0; k--) {
                    if (up[k][a] != up[k][b]) { a = up[k][a]; b = up[k][b]; }
                }
                l = up[0][a];
            }
            long total = dist[u] + dist[v] - 2*dist[l];
            if (total == 0) { ans[qi] = u; continue; }
            long upWeight = dist[u] - dist[l];
            if (2*upWeight >= total) {
                int cur = u;
                for (int k = LOG-1; k >= 0; k--) {
                    int nxt = up[k][cur];
                    if (depth[nxt] >= depth[l] && 2*(dist[u]-dist[nxt]) < total) cur = nxt;
                }
                ans[qi] = up[0][cur];
            } else {
                long remaining = total - 2*upWeight;
                int cur = v;
                for (int k = LOG-1; k >= 0; k--) {
                    int nxt = up[k][cur];
                    if (depth[nxt] >= depth[l] && 2*(dist[nxt]-dist[l]) >= remaining) cur = nxt;
                }
                ans[qi] = cur;
            }
        }
        return ans;
    }
}

class Solution {
    public int specialTriplets(int[] nums) {
        Map<Integer, Long> right = new HashMap<>();
        Map<Integer, Long> left = new HashMap<>();
        for (int x : nums) right.merge(x, 1L, Long::sum);
        long ans = 0;
        long MOD = 1_000_000_007L;
        for (int x : nums) {
            right.merge(x, -1L, Long::sum);
            int t = 2 * x;
            long l = left.getOrDefault(t, 0L);
            long r = right.getOrDefault(t, 0L);
            ans = (ans + l * r) % MOD;
            left.merge(x, 1L, Long::sum);
        }
        return (int) ans;
    }
}

import java.lang.*;

class Solution {
    public static int minSwaps(int[] nums) {
        int n = nums.length;
        int evenCount = 0;
        for (int v : nums) {
            if ((v & 1) == 0) evenCount++;
        }
        int oddCount = n - evenCount;
        if (Math.abs(evenCount - oddCount) > 1) return -1;
        long answer = Long.MAX_VALUE;
        if (evenCount >= oddCount) {
            long swaps = 0;
            int idx = 0;
            for (int i = 0; i < n; i++) {
                if ((nums[i] & 1) == 0) {
                    int target = idx * 2;
                    swaps += Math.abs(i - target);
                    idx++;
                }
            }
            answer = Math.min(answer, swaps);
        }
        if (oddCount >= evenCount) {
            long swaps = 0;
            int idx = 0;
            for (int i = 0; i < n; i++) {
                if ((nums[i] & 1) == 0) {
                    int target = idx * 2 + 1;
                    swaps += Math.abs(i - target);
                    idx++;
                }
            }
            answer = Math.min(answer, swaps);
        }
        return (int) answer;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static long maxArea(int[][] coords) {
        if (coords == null || coords.length < 3) return -1;
        int minX = Integer.MAX_VALUE, maxX = Integer.MIN_VALUE;
        int minY = Integer.MAX_VALUE, maxY = Integer.MIN_VALUE;
        Map<Integer, int[]> xMap = new HashMap<>();
        Map<Integer, int[]> yMap = new HashMap<>();
        for (int[] p : coords) {
            int x = p[0];
            int y = p[1];
            if (x < minX) minX = x;
            if (x > maxX) maxX = x;
            if (y < minY) minY = y;
            if (y > maxY) maxY = y;
            int[] arrX = xMap.get(x);
            if (arrX == null) {
                arrX = new int[]{y, y};
                xMap.put(x, arrX);
            } else {
                if (y < arrX[0]) arrX[0] = y;
                if (y > arrX[1]) arrX[1] = y;
            }
            int[] arrY = yMap.get(y);
            if (arrY == null) {
                arrY = new int[]{x, x};
                yMap.put(y, arrY);
            } else {
                if (x < arrY[0]) arrY[0] = x;
                if (x > arrY[1]) arrY[1] = x;
            }
        }
        long best = 0;
        for (Map.Entry<Integer, int[]> e : xMap.entrySet()) {
            int x = e.getKey();
            int[] arr = e.getValue();
            long base = (long) arr[1] - arr[0];
            if (base == 0) continue;
            long height = Math.max((long) x - minX, (long) maxX - x);
            if (height == 0) continue;
            long area2 = base * height;
            if (area2 > best) best = area2;
        }
        for (Map.Entry<Integer, int[]> e : yMap.entrySet()) {
            int y = e.getKey();
            int[] arr = e.getValue();
            long base = (long) arr[1] - arr[0];
            if (base == 0) continue;
            long height = Math.max((long) y - minY, (long) maxY - y);
            if (height == 0) continue;
            long area2 = base * height;
            if (area2 > best) best = area2;
        }
        return best == 0 ? -1 : best;
    }
}

public class Solution {
    public static long maxProduct(int[] nums, int m) {
        int n = nums.length;
        if (m <= 0 || n == 0) return Long.MIN_VALUE;
        if (m == 1) {
            long ans = Long.MIN_VALUE;
            for (int v : nums) {
                long prod = (long) v * v;
                if (prod > ans) ans = prod;
            }
            return ans;
        }
        if (m > n) return Long.MIN_VALUE;
        long ans = Long.MIN_VALUE;
        long leftMax = nums[0];
        long leftMin = nums[0];
        for (int j = m - 1; j < n; j++) {
            int idx = j - m + 1;
            if (idx > 0) {
                long val = nums[idx];
                if (val > leftMax) leftMax = val;
                if (val < leftMin) leftMin = val;
            }
            long cur = nums[j];
            long cand1 = leftMax * cur;
            long cand2 = leftMin * cur;
            long best = cand1 > cand2 ? cand1 : cand2;
            if (best > ans) ans = best;
        }
        return ans;
    }
}

import java.util.*;
public class Solution {
    static class Query {
        int l, r, k, idx, block;
        Query(int l, int r, int k, int idx, int block) {
            this.l = l;
            this.r = r;
            this.k = k;
            this.idx = idx;
            this.block = block;
        }
    }
    static class BIT {
        int n;
        int[] tree;
        BIT(int n) {
            this.n = n;
            tree = new int[n + 2];
        }
        void add(int idx, int delta) {
            for (int i = idx; i <= n; i += i & -i) tree[i] += delta;
        }
        int sum(int idx) {
            int res = 0;
            for (int i = idx; i > 0; i -= i & -i) res += tree[i];
            return res;
        }
        int total() {
            return sum(n);
        }
        int kth(int k) {
            int idx = 0;
            int bitMask = Integer.highestOneBit(n);
            for (int step = bitMask; step != 0; step >>= 1) {
                int next = idx + step;
                if (next <= n && tree[next] < k) {
                    idx = next;
                    k -= tree[next];
                }
            }
            return idx + 1; // 1-indexed position
        }
    }
    public int[] kthSmallestPathXor(int[] par, int[] vals, int[][] queries) {
        int n = vals.length;
        List<Integer>[] g = new ArrayList[n];
        for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
        for (int i = 1; i < n; i++) {
            g[par[i]].add(i);
            g[i].add(par[i]);
        }
        int[] xorRoot = new int[n];
        int[] tin = new int[n];
        int[] tout = new int[n];
        int[] euler = new int[n];
        int time = 0;
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{0, -1, 0}); // node, parent, state 0=enter,1=exit
        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            int node = cur[0];
            int parent = cur[1];
            int state = cur[2];
            if (state == -1) { // exit
                tout[node] = time - 1;
                continue;
            }
            // enter
            tin[node] = time;
            euler[time++] = node;
            xorRoot[node] = (parent == -1 ? 0 : xorRoot[parent]) ^ vals[node];
            // push exit marker
            stack.push(new int[]{node, parent, -1});
            // push children
            for (int nei : g[node]) {
                if (nei == parent) continue;
                stack.push(new int[]{nei, node, 0});
            }
        }
        int maxVal = 0;
        for (int v : xorRoot) if (v > maxVal) maxVal = v;
        int sizeBIT = maxVal + 2; // shift by +1
        int q = queries.length;
        Query[] qs = new Query[q];
        int blockSize = (int) Math.sqrt(n) + 1;
        for (int i = 0; i < q; i++) {
            int u = queries[i][0];
            int k = queries[i][1];
            int l = tin[u];
            int r = tout[u];
            qs[i] = new Query(l, r, k, i, l / blockSize);
        }
        Arrays.sort(qs, (a, b) -> {
            if (a.block != b.block) return Integer.compare(a.block, b.block);
            if ((a.block & 1) == 0) return Integer.compare(a.r, b.r);
            else return Integer.compare(b.r, a.r);
        });
        int[] freq = new int[sizeBIT];
        BIT bit = new BIT(sizeBIT);
        int curL = 0, curR = -1;
        int[] ans = new int[q];
        for (Query qu : qs) {
            while (curL > qu.l) {
                curL--;
                int val = xorRoot[euler[curL]] + 1;
                if (++freq[val] == 1) bit.add(val, 1);
            }
            while (curR < qu.r) {
                curR++;
                int val = xorRoot[euler[curR]] + 1;
                if (++freq[val] == 1) bit.add(val, 1);
            }
            while (curL < qu.l) {
                int val = xorRoot[euler[curL]] + 1;
                if (--freq[val] == 0) bit.add(val, -1);
                curL++;
            }
            while (curR > qu.r) {
                int val = xorRoot[euler[curR]] + 1;
                if (--freq[val] == 0) bit.add(val, -1);
                curR--;
            }
            if (bit.total() < qu.k) ans[qu.idx] = -1;
            else {
                int pos = bit.kth(qu.k);
                ans[qu.idx] = pos - 1;
            }
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    public static double minimumTime(int[] time, int k, double[] mul) {
        int n = time.length;
        int m = mul.length;
        int FULL = (1 << n) - 1;
        double[] maskTime = new double[1 << n];
        for (int mask = 0; mask < (1<<n); mask++)
            for (int i = 0; i < n; i++)
                if ((mask & (1<<i)) != 0) maskTime[mask] = Math.max(maskTime[mask], time[i]);

        double INF = Double.POSITIVE_INFINITY;
        double[][][] dist = new double[1<<n][2][m];
        for (double[][] a : dist) for (double[] b : a) Arrays.fill(b, INF);

        PriorityQueue<double[]> pq = new PriorityQueue<>((a,b) -> Double.compare(a[0], b[0]));
        dist[FULL][0][0] = 0;
        pq.offer(new double[]{0.0, FULL, 0, 0});
        while (!pq.isEmpty()) {
            double[] top = pq.poll();
            double cost = top[0]; int ppl = (int)top[1]; int dir = (int)top[2]; int spd = (int)top[3];
            if (cost > dist[ppl][dir][spd] + 1e-12) continue;
            if (dir == 0) {
                for (int mask = 1; mask < (1<<n); mask++) {
                    if (Integer.bitCount(mask) <= k && (mask | ppl) == ppl) {
                        double d = maskTime[mask] * mul[spd];
                        double newCost = cost + d;
                        int newPpl = ppl ^ mask;
                        int newSpd = (int)((spd + Math.floor(d)) % m);
                        if (newCost < dist[newPpl][1][newSpd] - 1e-12) {
                            dist[newPpl][1][newSpd] = newCost;
                            pq.offer(new double[]{newCost, newPpl, 1, newSpd});
                        }
                    }
                }
            } else {
                if (ppl == 0) return cost;
                for (int i = 0; i < n; i++) {
                    int mask = 1 << i;
                    if ((mask & ppl) == 0) {
                        double d = maskTime[mask] * mul[spd];
                        double newCost = cost + d;
                        int newPpl = ppl ^ mask;
                        int newSpd = (int)((spd + Math.floor(d)) % m);
                        if (newCost < dist[newPpl][0][newSpd] - 1e-12) {
                            dist[newPpl][0][newSpd] = newCost;
                            pq.offer(new double[]{newCost, newPpl, 0, newSpd});
                        }
                    }
                }
            }
        }
        return -1.0;
    }
}

class Solution {
    static final int MAXV = 100000;
    static boolean[] IS_PRIME_PG = buildSieve();

    static boolean[] buildSieve() {
        boolean[] isP = new boolean[MAXV + 1];
        Arrays.fill(isP, true);
        isP[0] = isP[1] = false;
        for (int i = 2; (long) i * i <= MAXV; i++)
            if (isP[i]) for (int j = i * i; j <= MAXV; j += i) isP[j] = false;
        return isP;
    }

    public long primeSubarray(int[] nums, int k) {
        int n = nums.length;
        int[] marks = new int[n];
        for (int i = 0; i < n; i++) marks[i] = (nums[i] <= MAXV && IS_PRIME_PG[nums[i]]) ? nums[i] : 0;
        TreeMap<Integer, Integer> ms = new TreeMap<>(); // multiset via counted TreeMap
        int j1 = 0, cnt = 0, j2 = 0;
        long ans = 0;
        for (int i = 0; i < n; i++) {
            int x = marks[i];
            if (x > 0) { cnt++; ms.merge(x, 1, Integer::sum); }
            while (!ms.isEmpty() && ms.lastKey() - ms.firstKey() > k) {
                int v = marks[j1];
                if (v > 0) {
                    int c = ms.get(v);
                    if (c == 1) ms.remove(v); else ms.put(v, c - 1);
                }
                j1++;
            }
            while (cnt > 1) {
                if (marks[j2] > 0) cnt--;
                j2++;
            }
            ans += j2 - j1;
        }
        return ans;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static boolean hasPrimeFrequency(int[] nums) {
        Map<Integer, Integer> freq = new HashMap<>();
        int maxFreq = 0;
        for (int v : nums) {
            int count = freq.getOrDefault(v, 0) + 1;
            freq.put(v, count);
            if (count > maxFreq) {
                maxFreq = count;
            }
        }
        if (maxFreq < 2) {
            return false;
        }
        boolean[] isPrime = new boolean[maxFreq + 1];
        for (int i = 2; i <= maxFreq; i++) {
            isPrime[i] = true;
        }
        for (int p = 2; p * p <= maxFreq; p++) {
            if (isPrime[p]) {
                for (int multiple = p * p; multiple <= maxFreq; multiple += p) {
                    isPrime[multiple] = false;
                }
            }
        }
        for (int count : freq.values()) {
            if (isPrime[count]) {
                return true;
            }
        }
        return false;
    }
}

import java.util.ArrayList;
import java.util.List;

class Solution {
    public static int[] recoverDenominations(int[] numWays) {
        int m = numWays.length;
        int[] ways = new int[m + 1];
        ways[0] = 1;
        List<Integer> denoms = new ArrayList<>();
        for (int i = 1; i <= m; i++) {
            int target = numWays[i - 1];
            if (ways[i] == target) continue;
            if (ways[i] < target) {
                int diff = target - ways[i];
                if (diff != 1) return new int[0];
                denoms.add(i);
                for (int j = i; j <= m; j++) {
                    ways[j] += ways[j - i];
                }
                if (ways[i] != target) return new int[0];
            } else {
                return new int[0];
            }
        }
        int[] result = new int[denoms.size()];
        for (int i = 0; i < denoms.size(); i++) result[i] = denoms.get(i);
        return result;
    }
}

import java.util.*;

class Solution {
    public static int minNodesToIncrease(int n, int[][] edges, int[] cost) {
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            adj[u].add(v);
            adj[v].add(u);
        }

        int[] parent = new int[n];
        Arrays.fill(parent, -1);
        int[] order = new int[n];
        int idx = 0;
        int[] stack = new int[n];
        int top = 0;
        stack[0] = 0;
        parent[0] = 0;
        while (top >= 0) {
            int node = stack[top--];
            order[idx++] = node;
            for (int nb : adj[node]) {
                if (nb == parent[node]) continue;
                parent[nb] = node;
                stack[++top] = nb;
            }
        }

        long[] maxSum = new long[n];
        int[] touches = new int[n];

        for (int i = n - 1; i >= 0; i--) {
            int node = order[i];
            long maxChildSum = Long.MIN_VALUE;
            for (int nb : adj[node]) {
                if (nb == parent[node]) continue;
                if (maxSum[nb] > maxChildSum) maxChildSum = maxSum[nb];
            }
            if (maxChildSum == Long.MIN_VALUE) {
                maxSum[node] = cost[node];
                touches[node] = 0;
            } else {
                long total = 0;
                for (int nb : adj[node]) {
                    if (nb == parent[node]) continue;
                    total += touches[nb];
                    if (maxSum[nb] < maxChildSum) total += 1;
                }
                maxSum[node] = cost[node] + maxChildSum;
                touches[node] = (int) total;
            }
        }

        return touches[0];
    }
}

import java.util.*;

class Solution {
    public String[] partitionString(String s) {
        Set<String> used = new HashSet<>();
        List<String> segments = new ArrayList<>();
        int n = s.length();
        int i = 0;
        while (i < n) {
            StringBuilder sb = new StringBuilder();
            boolean found = false;
            for (int j = i; j < n; j++) {
                sb.append(s.charAt(j));
                String cur = sb.toString();
                if (!used.contains(cur)) {
                    used.add(cur);
                    segments.add(cur);
                    i = j + 1;
                    found = true;
                    break;
                }
            }
            if (!found) {
                break;
            }
        }
        return segments.toArray(new String[0]);
    }
}

import java.util.*;

class Solution {
    public static int[] longestCommonPrefixAfterRemoval(String[] words) {
        int n = words.length;
        int[] answer = new int[n];
        if (n <= 2) {
            return answer;
        }
        int m = n - 1;
        int[] lcp = new int[m];
        for (int i = 0; i < m; i++) {
            lcp[i] = commonPrefixLength(words[i], words[i + 1]);
        }
        int[] prefixMax = new int[m];
        int[] suffixMax = new int[m];
        prefixMax[0] = lcp[0];
        for (int i = 1; i < m; i++) {
            prefixMax[i] = Math.max(prefixMax[i - 1], lcp[i]);
        }
        suffixMax[m - 1] = lcp[m - 1];
        for (int i = m - 2; i >= 0; i--) {
            suffixMax[i] = Math.max(suffixMax[i + 1], lcp[i]);
        }
        for (int i = 0; i < n; i++) {
            int leftMax = (i - 2 >= 0) ? prefixMax[i - 2] : 0;
            int rightMax = (i + 1 <= m - 1) ? suffixMax[i + 1] : 0;
            int maxWithout = Math.max(leftMax, rightMax);
            int newLcp = 0;
            if (i > 0 && i < n - 1) {
                newLcp = commonPrefixLength(words[i - 1], words[i + 1]);
            }
            answer[i] = Math.max(maxWithout, newLcp);
        }
        return answer;
    }

    private static int commonPrefixLength(String a, String b) {
        int len = Math.min(a.length(), b.length());
        int i = 0;
        while (i < len && a.charAt(i) == b.charAt(i)) {
            i++;
        }
        return i;
    }
}

import java.util.*;

class Solution {
    public static int maxStability(int n, int[][] edges, int k) {
        Edge[] es = new Edge[edges.length];
        long maxPossible = 0;
        for (int i = 0; i < edges.length; i++) {
            int u = edges[i][0];
            int v = edges[i][1];
            int s = edges[i][2];
            int must = edges[i][3];
            es[i] = new Edge(u, v, s, must);
            long cand = (must == 0) ? s * 2L : s;
            if (cand > maxPossible) maxPossible = cand;
        }
        long low = 0, high = maxPossible;
        while (low < high) {
            long mid = low + (high - low + 1) / 2;
            if (canAchieve(es, n, k, mid)) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return low == 0 ? -1 : (int) low;
    }

    private static boolean canAchieve(Edge[] edges, int n, int k, long target) {
        UnionFind uf = new UnionFind(n);
        // process mandatory edges
        for (Edge e : edges) {
            if (e.must == 1) {
                if (e.s < target) return false;
                if (!uf.union(e.u, e.v)) return false; // creates a cycle
            }
        }
        // optional edges that already satisfy target without upgrade
        for (Edge e : edges) {
            if (e.must == 0 && e.s >= target) {
                uf.union(e.u, e.v);
            }
        }
        int upgradesUsed = 0;
        // optional edges that can be upgraded to meet target
        for (Edge e : edges) {
            if (e.must == 0 && e.s < target && e.s * 2L >= target) {
                if (uf.union(e.u, e.v)) {
                    upgradesUsed++;
                    if (upgradesUsed > k) return false;
                }
            }
        }
        return uf.getCount() == 1 && upgradesUsed <= k;
    }

    private static class Edge {
        int u, v, s, must;
        Edge(int u, int v, int s, int must) {
            this.u = u;
            this.v = v;
            this.s = s;
            this.must = must;
        }
    }

    private static class UnionFind {
        int[] parent;
        int[] rank;
        int count;

        UnionFind(int n) {
            parent = new int[n];
            rank = new int[n];
            count = n;
            for (int i = 0; i < n; i++) parent[i] = i;
        }

        int find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }

        boolean union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return false;
            if (rank[ra] < rank[rb]) {
                parent[ra] = rb;
            } else if (rank[ra] > rank[rb]) {
                parent[rb] = ra;
            } else {
                parent[rb] = ra;
                rank[ra]++;
            }
            count--;
            return true;
        }

        int getCount() {
            return count;
        }
    }
}

import java.util.*;

class Solution {
    public static int minMaxXor(int[] nums, int k) {
        int n = nums.length;
        int[] pref = new int[n + 1];
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] ^ nums[i];
        }
        int low = 0;
        int high = Integer.MAX_VALUE;
        while (low < high) {
            int mid = (low + high) >>> 1;
            if (can(pref, n, k, mid)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    private static boolean can(int[] pref, int n, int k, int limit) {
        boolean[][] dp = new boolean[n + 1][k + 1];
        dp[0][0] = true;
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < i; j++) {
                if ((pref[i] ^ pref[j]) <= limit) {
                    for (int cnt = 0; cnt < k; cnt++) {
                        if (dp[j][cnt]) {
                            dp[i][cnt + 1] = true;
                        }
                    }
                }
            }
        }
        return dp[n][k];
    }
}

class Solution {
    public long minCost(int m, int n, int[][] waitCost) {
        long[][] f = new long[m][n];
        f[0][0] = 1;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (i == 0 && j == 0) continue;
                long entry = (long)(i+1)*(j+1);
                long best = Long.MAX_VALUE;
                if (i > 0) {
                    long p = f[i-1][j];
                    if (!(i-1 == 0 && j == 0)) p += waitCost[i-1][j];
                    best = Math.min(best, p);
                }
                if (j > 0) {
                    long p = f[i][j-1];
                    if (!(i == 0 && j-1 == 0)) p += waitCost[i][j-1];
                    best = Math.min(best, p);
                }
                f[i][j] = entry + best;
            }
        }
        return f[m-1][n-1];
    }
}

public class Solution {
