import java.util.*;

class Solution {
    private static class Edge {
        int to;
        long start;
        long end;
        Edge(int to, long start, long end) {
            this.to = to;
            this.start = start;
            this.end = end;
        }
    }

    public static long minimumTime(int n, int[][] edges) {
        List<Edge>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            long s = e[2];
            long t = e[3];
            adj[u].add(new Edge(v, s, t));
        }

        long INF = Long.MAX_VALUE / 4;
        long[] dist = new long[n];
        Arrays.fill(dist, INF);
        dist[0] = 0;

        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
        pq.offer(new long[]{0, 0});

        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            long curTime = cur[0];
            int node = (int) cur[1];
            if (curTime != dist[node]) continue;
            if (node == n - 1) break;
            for (Edge e : adj[node]) {
                if (curTime > e.end) continue;
                long depart = Math.max(curTime, e.start);
                long arrival = depart + 1;
                if (arrival < dist[e.to]) {
                    dist[e.to] = arrival;
                    pq.offer(new long[]{arrival, e.to});
                }
            }
        }

        return dist[n - 1] == INF ? -1 : dist[n - 1];
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

class Solution {
    public static String[] solution(String[] code, String[] businessLine, boolean[] isActive) {
        int n = code.length;
        @SuppressWarnings("unchecked")
        List<String>[] groups = new List[4];
        for (int i = 0; i < 4; i++) groups[i] = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (!isActive[i]) continue;
            String line = businessLine[i];
            int idx;
            switch (line) {
                case "electronics": idx = 0; break;
                case "grocery": idx = 1; break;
                case "pharmacy": idx = 2; break;
                case "restaurant": idx = 3; break;
                default: continue;
            }
            String c = code[i];
            if (c == null || c.isEmpty()) continue;
            boolean ok = true;
            for (int j = 0; j < c.length(); j++) {
                char ch = c.charAt(j);
                if (!((ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z') || (ch >= '0' && ch <= '9') || ch == '_')) {
                    ok = false;
                    break;
                }
            }
            if (!ok) continue;
            groups[idx].add(c);
        }
        List<String> result = new ArrayList<>(n);
        for (int i = 0; i < 4; i++) {
            Collections.sort(groups[i]);
            result.addAll(groups[i]);
        }
        return result.toArray(new String[0]);
    }
}

import java.util.*;

class Solution {
    public static int minimumStabilityFactor(int[] nums, int maxC) {
        int n = nums.length;
        if (n == 0) return 0;
        int LOG = 32 - Integer.numberOfLeadingZeros(n);
        int[][] st = new int[LOG][n];
        for (int i = 0; i < n; i++) st[0][i] = nums[i];
        for (int k = 1; k < LOG; k++) {
            int len = 1 << k;
            int half = len >> 1;
            for (int i = 0; i + len <= n; i++) {
                st[k][i] = gcd(st[k - 1][i], st[k - 1][i + half]);
            }
        }
        int[] log = new int[n + 1];
        for (int i = 2; i <= n; i++) log[i] = log[i >> 1] + 1;

        int low = 0, high = n;
        while (low < high) {
            int mid = (low + high) >>> 1;
            if (feasible(mid, nums, n, maxC, st, log)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    private static boolean feasible(int L, int[] nums, int n, int maxC, int[][] st, int[] log) {
        int needed = 0;
        int lastSelected = -1;
        int windowSize = L + 1;
        for (int i = 0; i + windowSize - 1 < n; i++) {
            if (i <= lastSelected) continue;
            int g = rangeGcd(i, i + L, st, log);
            if (g >= 2) {
                needed++;
                if (needed > maxC) return false;
                lastSelected = i + L;
            }
        }
        return needed <= maxC;
    }

    private static int rangeGcd(int l, int r, int[][] st, int[] log) {
        int len = r - l + 1;
        int k = log[len];
        return gcd(st[k][l], st[k][r - (1 << k) + 1]);
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

import java.util.Arrays;

class Solution {
    public static int minimumTime(int n, int[][] edges, int k) {
        Arrays.sort(edges, (a, b) -> Integer.compare(b[2], a[2]));
        DSU dsu = new DSU(n);
        int components = n;
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            int t = e[2];
            if (dsu.find(u) != dsu.find(v)) {
                dsu.union(u, v);
                components--;
                if (components < k) {
                    return t;
                }
            }
        }
        return 0;
    }

    private static class DSU {
        int[] parent;
        int[] size;

        DSU(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }

        void union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return;
            if (size[ra] < size[rb]) {
                parent[ra] = rb;
                size[rb] += size[ra];
            } else {
                parent[rb] = ra;
                size[ra] += size[rb];
            }
        }
    }
}

import java.util.*;

class Solution {
    public static int minMovesGrid(int sx, int sy, int tx, int ty) {
        if (sx > tx || sy > ty) return -1;
        if (sx == tx && sy == ty) return 0;
        Deque<int[]> queue = new ArrayDeque<>();
        Set<Long> visited = new HashSet<>();
        queue.offer(new int[]{sx, sy});
        visited.add(((long) sx << 32) | (sy & 0xffffffffL));
        int steps = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                int[] cur = queue.poll();
                int x = cur[0], y = cur[1];
                if (x == tx && y == ty) return steps;
                int m = Math.max(x, y);
                int nx = x + m;
                if (nx <= tx) {
                    long key = ((long) nx << 32) | (y & 0xffffffffL);
                    if (!visited.contains(key)) {
                        visited.add(key);
                        queue.offer(new int[]{nx, y});
                    }
                }
                int ny = y + m;
                if (ny <= ty) {
                    long key = ((long) x << 32) | (ny & 0xffffffffL);
                    if (!visited.contains(key)) {
                        visited.add(key);
                        queue.offer(new int[]{x, ny});
                    }
                }
            }
            steps++;
        }
        return -1;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.TreeSet;

class Solution {
    private static int find(int x, int[] parent) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    private static void union(int a, int b, int[] parent, int[] rank) {
        int ra = find(a, parent);
        int rb = find(b, parent);
        if (ra == rb) return;
        if (rank[ra] < rank[rb]) {
            parent[ra] = rb;
        } else if (rank[ra] > rank[rb]) {
            parent[rb] = ra;
        } else {
            parent[rb] = ra;
            rank[ra]++;
        }
    }

    public static List<Integer> powerGridMaintenance(int c, int[][] connections, int[][] queries) {
        int[] parent = new int[c + 1];
        int[] rank = new int[c + 1];
        for (int i = 1; i <= c; i++) parent[i] = i;
        for (int[] edge : connections) {
            union(edge[0], edge[1], parent, rank);
        }
        @SuppressWarnings("unchecked")
        TreeSet<Integer>[] compSets = new TreeSet[c + 1];
        for (int i = 1; i <= c; i++) {
            int r = find(i, parent);
            if (compSets[r] == null) compSets[r] = new TreeSet<>();
            compSets[r].add(i);
        }
        List<Integer> ans = new ArrayList<>();
        for (int[] q : queries) {
            int type = q[0];
            int x = q[1];
            int r = find(x, parent);
            if (type == 2) {
                if (compSets[r] != null) compSets[r].remove(x);
            } else {
                if (compSets[r] == null) {
                    ans.add(-1);
                } else {
                    Integer cand = compSets[r].ceiling(x);
                    ans.add(cand == null ? -1 : cand);
                }
            }
        }
        return ans;
    }
}

import java.util.*;

public class Solution {
    public static String processString(String s) {
        int n = s.length();
        char[] result = new char[n];
        int resLen = 0;
        char[] deleted = new char[n];
        int delTop = -1;
        for (int i = 0; i < n; i++) {
            char ch = s.charAt(i);
            if (ch >= 'a' && ch <= 'z') {
                result[resLen++] = ch;
            } else if (ch == '#') {
                if (resLen > 0) {
                    char removed = result[--resLen];
                    deleted[++delTop] = removed;
                }
            } else if (ch == '%') {
                if (delTop >= 0) {
                    result[resLen++] = deleted[delTop--];
                }
            } else if (ch == '*') {
                delTop = -1;
            }
        }
        return new String(result, 0, resLen);
    }
}

import java.util.*;

class Solution {
    public static char getKthChar(String s, int k) {
        int n = s.length();
        long[] len = new long[n + 1];
        for (int i = 1; i <= n; i++) {
            char ch = s.charAt(i - 1);
            long prev = len[i - 1];
            if (ch >= 'a' && ch <= 'z') {
                len[i] = prev + 1;
            } else if (ch == '*') {
                len[i] = prev > 0 ? prev - 1 : 0;
            } else if (ch == '#') {
                len[i] = prev * 2;
            } else if (ch == '%') {
                len[i] = prev;
            }
        }
        if (k < 0 || (long) k >= len[n]) return '.';
        long idx = k;
        for (int i = n; i > 0; i--) {
            char ch = s.charAt(i - 1);
            long prev = len[i - 1];
            if (ch >= 'a' && ch <= 'z') {
                if (idx == prev) return ch;
            } else if (ch == '#') {
                if (idx >= prev) idx -= prev;
            } else if (ch == '%') {
                idx = prev - 1 - idx;
            }
        }
        return '.';
    }
}

import java.util.Arrays;
import java.util.Comparator;

class Solution {
    public static int minimizeMaxComponentCost(int n, int[][] edges, int k) {
        if (k >= n) return 0;
        int need = n - k;
        Arrays.sort(edges, Comparator.comparingInt(e -> e[2]));
        DSU dsu = new DSU(n);
        int added = 0;
        int ans = 0;
        for (int[] e : edges) {
            if (dsu.union(e[0], e[1])) {
                ans = e[2];
                added++;
                if (added == need) break;
            }
        }
        return ans;
    }

    private static class DSU {
        int[] parent;
        int[] rank;

        DSU(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) parent[i] = i;
        }

        int find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }

        boolean union(int x, int y) {
            int rx = find(x);
            int ry = find(y);
            if (rx == ry) return false;
            if (rank[rx] < rank[ry]) {
                parent[rx] = ry;
            } else if (rank[rx] > rank[ry]) {
                parent[ry] = rx;
            } else {
                parent[ry] = rx;
                rank[rx]++;
            }
            return true;
        }
    }
}

import java.util.*;

class Solution {
    public static int longestPalindromePath(int n, int[][] edges, String label) {
        int maxMask = 1 << n;
        int[][] dp = new int[maxMask][n];
        int[] adjMask = new int[n];
        for (int[] e : edges) {
            int u = e[0], v = e[1];
            adjMask[u] |= 1 << v;
            adjMask[v] |= 1 << u;
        }
        int ans = 0;
        for (int i = 0; i < n; i++) {
            int mask = 1 << i;
            dp[mask][i] = 1 << i;
            ans = Math.max(ans, 1);
        }
        for (int[] e : edges) {
            int u = e[0], v = e[1];
            if (label.charAt(u) == label.charAt(v)) {
                int mask = (1 << u) | (1 << v);
                dp[mask][u] |= 1 << v;
                dp[mask][v] |= 1 << u;
                ans = Math.max(ans, 2);
            }
        }
        for (int mask = 0; mask < maxMask; mask++) {
            for (int u = 0; u < n; u++) {
                int reachable = dp[mask][u];
                while (reachable != 0) {
                    int v = Integer.numberOfTrailingZeros(reachable);
                    reachable &= ~(1 << v);
                    int notInMask = ~mask;
                    int possibleX = adjMask[u] & notInMask;
                    for (int xBits = possibleX; xBits != 0; xBits &= xBits - 1) {
                        int x = Integer.numberOfTrailingZeros(xBits);
                        int possibleY = adjMask[v] & notInMask & ~(1 << x);
                        for (int yBits = possibleY; yBits != 0; yBits &= yBits - 1) {
                            int y = Integer.numberOfTrailingZeros(yBits);
                            if (label.charAt(x) != label.charAt(y)) continue;
                            int newMask = mask | (1 << x) | (1 << y);
                            dp[newMask][x] |= 1 << y;
                            int len = Integer.bitCount(newMask);
                            if (len > ans) ans = len;
                        }
                    }
                }
            }
        }
        return ans;
    }
}

import java.util.ArrayDeque;

class Solution {
    public static int countIslands(int[][] grid, int k) {
        int rows = grid.length;
        if (rows == 0) return 0;
        int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];
        int islandCount = 0;
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};
        ArrayDeque<Integer> stack = new ArrayDeque<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] > 0 && !visited[r][c]) {
                    int sum = 0;
                    stack.clear();
                    stack.push(r * cols + c);
                    visited[r][c] = true;
                    while (!stack.isEmpty()) {
                        int pos = stack.pop();
                        int cr = pos / cols;
                        int cc = pos % cols;
                        sum += grid[cr][cc];
                        for (int i = 0; i < 4; i++) {
                            int nr = cr + dr[i];
                            int nc = cc + dc[i];
                            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] > 0 && !visited[nr][nc]) {
                                visited[nr][nc] = true;
                                stack.push(nr * cols + nc);
                            }
                        }
                    }
                    if (sum % k == 0) islandCount++;
                }
            }
        }
        return islandCount;
    }
}

import java.util.*;

class Solution {
    private static class Edge {
        int to;
        int cost;
        Edge(int to, int cost) {
            this.to = to;
            this.cost = cost;
        }
    }

    public static int maxPathScore(int[][] edges, boolean[] online, long k) {
        int n = online.length;
        List<Edge>[] adj = new ArrayList[n];
        int[] indegree = new int[n];
        int maxCost = 0;
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            int c = e[2];
            adj[u].add(new Edge(v, c));
            indegree[v]++;
            if (c > maxCost) maxCost = c;
        }

        int[] order = new int[n];
        int idx = 0;
        Deque<Integer> dq = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            if (indegree[i] == 0) dq.add(i);
        }
        while (!dq.isEmpty()) {
            int u = dq.poll();
            order[idx++] = u;
            for (Edge e : adj[u]) {
                if (--indegree[e.to] == 0) dq.add(e.to);
            }
        }

        if (!can(0, adj, order, online, k, n)) return -1;

        int low = 0, high = maxCost;
        while (low < high) {
            int mid = low + (high - low + 1) / 2;
            if (can(mid, adj, order, online, k, n)) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return low;
    }

    private static boolean can(int B, List<Edge>[] adj, int[] order, boolean[] online, long k, int n) {
        long INF = Long.MAX_VALUE / 4;
        long[] dist = new long[n];
        Arrays.fill(dist, INF);
        if (!online[0]) return false;
        dist[0] = 0;
        for (int u : order) {
            if (!online[u] || dist[u] == INF) continue;
            for (Edge e : adj[u]) {
                if (!online[e.to] || e.cost < B) continue;
                long nd = dist[u] + e.cost;
                if (nd < dist[e.to]) dist[e.to] = nd;
            }
        }
        return dist[n - 1] <= k;
    }
}

import java.util.*;

public class Solution {
    private static final int MAX_BITS = 60;
    private static final long[][] C = new long[MAX_BITS + 1][MAX_BITS + 1];
    private static final int[] DEPTH = new int[MAX_BITS + 1];

    static {
        for (int i = 0; i <= MAX_BITS; i++) {
            C[i][0] = C[i][i] = 1L;
            for (int j = 1; j < i; j++) {
                C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
            }
        }
        DEPTH[1] = 0;
        for (int i = 2; i <= MAX_BITS; i++) {
            int pc = Integer.bitCount(i);
            DEPTH[i] = 1 + DEPTH[pc];
        }
    }

    private static long countWithPopcount(long n, int t) {
        if (t < 0) return 0L;
        long res = 0L;
        int onesSeen = 0;
        for (int i = MAX_BITS; i >= 0; i--) {
            if ((n & (1L << i)) != 0) {
                int remaining = i;
                int need = t - onesSeen;
                if (need >= 0 && remaining >= need) {
                    res += C[remaining][need];
                }
                onesSeen++;
                if (onesSeen > t) break;
            }
        }
        if (onesSeen == t) res++;
        return res;
    }

    public static long countNumbers(long n, int k) {
        if (n < 1) return 0L;
        if (k == 0) return n >= 1 ? 1L : 0L;
        List<Integer> targets = new ArrayList<>();
        for (int c = 1; c <= MAX_BITS; c++) {
            if (DEPTH[c] == k - 1) {
                targets.add(c);
            }
        }
        long ans = 0L;
        for (int t : targets) {
            ans += countWithPopcount(n, t);
        }
        if (k == 1 && n >= 1) {
            ans--; // exclude the number 1
        }
        return ans;
    }
}

class Solution {
    public static boolean isDivisibleBySumAndProduct(int n) {
        int temp = Math.abs(n);
        long sum = 0;
        long product = 1;
        if (temp == 0) {
            sum = 0;
            product = 1;
        } else {
            while (temp > 0) {
                int digit = temp % 10;
                sum += digit;
                product *= digit;
                temp /= 10;
                if (product == 0) {
                    // Once product is zero, further multiplication stays zero.
                    // No need to continue multiplying.
                }
            }
        }
        long total = sum + product;
        return total != 0 && n % total == 0;
    }
}

public class Solution {
    public static long splitArrayByPrimeIndices(int[] nums) {
        int n = nums.length;
        long total = 0;
        for (int v : nums) total += v;
        if (n <= 2) return Math.abs(total);
        boolean[] isComposite = new boolean[n];
        long sumPrime = 0;
        for (int i = 2; i < n; i++) {
            if (!isComposite[i]) {
                sumPrime += nums[i];
                if ((long) i * i < n) {
                    for (int j = i * i; j < n; j += i) {
                        isComposite[j] = true;
                    }
                }
            }
        }
        long sumNonPrime = total - sumPrime;
        return Math.abs(sumPrime - sumNonPrime);
    }
}

