public class Solution {
    private static final long MOD = 1_000_000_007L;
    private static final long INV2 = 500000004L;

    public static int countTrapezoids(int[][] points) {
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int[] p : points) {
            cnt.merge(p[1], 1, Integer::sum);
        }
        long sum = 0;
        long sumSq = 0;
        for (int c : cnt.values()) {
            if (c >= 2) {
                long choose2 = ((long) c * (c - 1) / 2) % MOD;
                sum = (sum + choose2) % MOD;
                sumSq = (sumSq + choose2 * choose2) % MOD;
            }
        }
        long ans = (sum * sum) % MOD;
        ans = (ans - sumSq + MOD) % MOD;
        ans = (ans * INV2) % MOD;
        return (int) ans;
    }
}

import java.util.*;

class Solution {
    private static int popDepth(long x) {
        if (x == 0) return 0;
        int depth = 0;
        while (x != 1) {
            x = Long.bitCount(x);
            depth++;
        }
        return depth;
    }

    private static class Fenwick {
        private final int n;
        private final int[] bit;

        Fenwick(int n) {
            this.n = n;
            this.bit = new int[n + 2];
        }

        void add(int idx, int delta) {
            for (int i = idx; i <= n; i += i & -i) {
                bit[i] += delta;
            }
        }

        int sum(int idx) {
            int res = 0;
            for (int i = idx; i > 0; i -= i & -i) {
                res += bit[i];
            }
            return res;
        }
    }

    public static List<Integer> countK(long[] nums, long[][] queries) {
        int n = nums.length;
        final int MAX_DEPTH = 5;
        Fenwick[] bits = new Fenwick[MAX_DEPTH + 1];
        for (int i = 0; i <= MAX_DEPTH; i++) {
            bits[i] = new Fenwick(n);
        }
        int[] depthArr = new int[n];
        for (int i = 0; i < n; i++) {
            int d = popDepth(nums[i]);
            depthArr[i] = d;
            bits[d].add(i + 1, 1);
        }

        List<Integer> ans = new ArrayList<>();
        for (long[] q : queries) {
            int type = (int) q[0];
            if (type == 1) {
                int l = (int) q[1];
                int r = (int) q[2];
                int k = (int) q[3];
                if (k < 0 || k > MAX_DEPTH) {
                    ans.add(0);
                } else {
                    int cnt = bits[k].sum(r + 1) - bits[k].sum(l);
                    ans.add(cnt);
                }
            } else {
                int idx = (int) q[1];
                long val = q[2];
                int oldDepth = depthArr[idx];
                int newDepth = popDepth(val);
                if (oldDepth != newDepth) {
                    bits[oldDepth].add(idx + 1, -1);
                    bits[newDepth].add(idx + 1, 1);
                    depthArr[idx] = newDepth;
                }
                nums[idx] = val;
            }
        }
        return ans;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static long countNumberOfTrapezoids(int[][] points) {
        int n = points.length;
        Map<Long, SlopeEntry> slopeMap = new HashMap<>();
        Map<Long, Integer> midMap = new HashMap<>();

        for (int i = 0; i < n; i++) {
            int xi = points[i][0];
            int yi = points[i][1];
            for (int j = i + 1; j < n; j++) {
                int xj = points[j][0];
                int yj = points[j][1];
                long dx = (long) xj - xi;
                long dy = (long) yj - yi;
                long g = gcd(Math.abs(dx), Math.abs(dy));
                dx /= g;
                dy /= g;
                if (dx < 0) {
                    dx = -dx;
                    dy = -dy;
                } else if (dx == 0 && dy < 0) {
                    dy = -dy;
                }
                long slopeKey = ((dy & 0xffffffffL) << 32) | (dx & 0xffffffffL);
                long c = dy * xi - dx * yi;
                long midKey = (((long) xi + xj) << 32) | ((long) yi + yj & 0xffffffffL);

                midMap.put(midKey, midMap.getOrDefault(midKey, 0) + 1);

                SlopeEntry slopeEntry = slopeMap.computeIfAbsent(slopeKey, k -> new SlopeEntry());
                slopeEntry.total++;

                slopeEntry.pointDeg.merge(i, 1, Integer::sum);
                slopeEntry.pointDeg.merge(j, 1, Integer::sum);

                LineEntry lineEntry = slopeEntry.lineMap.computeIfAbsent(c, k -> new LineEntry());
                lineEntry.count++;
                lineEntry.pointDegLine.merge(i, 1, Integer::sum);
                lineEntry.pointDegLine.merge(j, 1, Integer::sum);
            }
        }

        long trapezoidPairs = 0;
        for (SlopeEntry slopeEntry : slopeMap.values()) {
            long m = slopeEntry.total;
            long totalPairs = m * (m - 1) / 2;

            long sharePoint = 0;
            for (int deg : slopeEntry.pointDeg.values()) {
                sharePoint += (long) deg * (deg - 1) / 2;
            }

            long sameLinePairs = 0;
            long sameLineSharePoint = 0;
            for (LineEntry lineEntry : slopeEntry.lineMap.values()) {
                long t = lineEntry.count;
                sameLinePairs += t * (t - 1) / 2;
                for (int degL : lineEntry.pointDegLine.values()) {
                    sameLineSharePoint += (long) degL * (degL - 1) / 2;
                }
            }

            long valid = totalPairs - sharePoint - sameLinePairs + sameLineSharePoint;
            trapezoidPairs += valid;
        }

        long parallelogramCount = 0;
        for (int cnt : midMap.values()) {
            if (cnt > 1) {
                parallelogramCount += (long) cnt * (cnt - 1) / 2;
            }
        }

        return trapezoidPairs - parallelogramCount;
    }

    private static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    private static class SlopeEntry {
        int total = 0;
        Map<Integer, Integer> pointDeg = new HashMap<>();
        Map<Long, LineEntry> lineMap = new HashMap<>();
    }

    private static class LineEntry {
        int count = 0;
        Map<Integer, Integer> pointDegLine = new HashMap<>();
    }
}

