class Solution {
    public static long maxMedianSum(int[] nums) {
        if (nums == null || nums.length < 3) {
            return 0L;
        }
        Arrays.sort(nums);
        int n = nums.length;
        int groups = n / 3;
        long sum = 0L;
        for (int i = n - 2; i >= groups; i -= 2) {
            sum += nums[i];
        }
        return sum;
    }
}

