class Solution {
    public static long maxLCT(String s) {
        int n = s.length();
        long totalT = 0;
        long totalCT = 0;
        long cntT = 0;
        for (int i = n - 1; i >= 0; i--) {
            char ch = s.charAt(i);
            if (ch == 'T') {
                cntT++;
            } else if (ch == 'C') {
                totalCT += cntT;
            }
        }
        totalT = cntT;

        long prefixL = 0;
        long prefixLC = 0;
        long prefixT = 0;
        long prefixCT = 0;
        long original = 0;
        long bestInc = 0;

        for (int i = 0; i <= n; i++) {
            long incL = totalCT - prefixCT;
            long incT = prefixLC;
            long incC = prefixL * (totalT - prefixT);
            if (incL > bestInc) bestInc = incL;
            if (incT > bestInc) bestInc = incT;
            if (incC > bestInc) bestInc = incC;
            if (i == n) break;
            char ch = s.charAt(i);
            if (ch == 'L') {
                prefixL++;
            } else if (ch == 'C') {
                original += prefixL * (totalT - prefixT);
                prefixLC += prefixL;
                prefixCT += (totalT - prefixT);
            } else if (ch == 'T') {
                prefixT++;
            }
        }
        return original + bestInc;
    }
}

import java.util.*;
class Solution {
    public static int minJumpsPrimeTeleport(int[] nums) {
        int n = nums.length;
        if (n <= 1) return 0;
        int maxVal = 0;
        for (int v : nums) maxVal = Math.max(maxVal, v);
        int[] spf = new int[maxVal+1];
        for (int i = 2; i <= maxVal; i++) {
            if (spf[i] == 0) {
                spf[i] = i;
                if ((long)i*i <= maxVal) for (int j = i*i; j <= maxVal; j += i) if (spf[j]==0) spf[j] = i;
            }
        }
        Map<Integer, List<Integer>> primeToIndices = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int x = nums[i];
            Set<Integer> facs = new HashSet<>();
            while (x > 1) {
                int p = spf[x] != 0 ? spf[x] : x;
                facs.add(p);
                while (x % p == 0) x /= p;
            }
            for (int p : facs) primeToIndices.computeIfAbsent(p, k -> new ArrayList<>()).add(i);
        }
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        dist[0] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.add(0);
        while (!q.isEmpty()) {
            int cur = q.poll();
            int curDist = dist[cur];
            if (cur == n-1) return curDist;
            for (int nxt : new int[]{cur-1, cur+1}) {
                if (nxt >= 0 && nxt < n && dist[nxt] == -1) { dist[nxt] = curDist+1; q.add(nxt); }
            }
            if (nums[cur] > 1 && spf[nums[cur]] == nums[cur]) {
                int p = nums[cur];
                List<Integer> lst = primeToIndices.getOrDefault(p, new ArrayList<>());
                for (int nxt : lst) if (dist[nxt] == -1) { dist[nxt] = curDist+1; q.add(nxt); }
                lst.clear();
            }
        }
        return -1;
    }
}
