import java.util.*;

class Solution {
    public long maxValue(int[] nums) {
        int n = nums.length;
        int full = (1 << n) - 1;
        final int BITS = 30;
        final int FULLBITS = (1 << BITS) - 1;

        int[] andOf = new int[1 << n];
        int[] xorOf = new int[1 << n];
        for (int mask = 1; mask <= full; mask++) {
            int low = mask & (-mask);
            int i = Integer.numberOfTrailingZeros(low);
            int rest = mask ^ low;
            if (rest == 0) {
                andOf[mask] = nums[i];
                xorOf[mask] = nums[i];
            } else {
                andOf[mask] = andOf[rest] & nums[i];
                xorOf[mask] = xorOf[rest] ^ nums[i];
            }
        }

        long best = 0;
        int[] basis = new int[BITS];
        for (int maskB = 0; maskB <= full; maskB++) {
            int S = full ^ maskB;
            int andB = (maskB == 0) ? 0 : andOf[maskB];
            int xorS = (S == 0) ? 0 : xorOf[S];
            int M = (~xorS) & FULLBITS;

            Arrays.fill(basis, 0);
            int it = S;
            while (it != 0) {
                int low = it & (-it);
                int i = Integer.numberOfTrailingZeros(low);
                it ^= low;
                int cur = nums[i] & M;
                for (int b = BITS - 1; b >= 0; b--) {
                    if (((cur >> b) & 1) == 0) continue;
                    if (basis[b] == 0) {
                        basis[b] = cur;
                        break;
                    }
                    cur ^= basis[b];
                }
            }
            int maxMasked = 0;
            for (int b = BITS - 1; b >= 0; b--) {
                if (basis[b] != 0 && (maxMasked ^ basis[b]) > maxMasked) {
                    maxMasked ^= basis[b];
                }
            }
            long total = (long) andB + (long) xorS + 2L * maxMasked;
            if (total > best) best = total;
        }
        return best;
    }
}

import java.util.Arrays;

class Solution {
    public static int minRemovals(int[] nums, int k) {
        Arrays.sort(nums);
        int n = nums.length;
        int left = 0;
        int best = 0;
        for (int right = 0; right < n; right++) {
            while (left <= right && (long) nums[right] > (long) k * nums[left]) {
                left++;
            }
            int windowSize = right - left + 1;
            if (windowSize > best) {
                best = windowSize;
            }
        }
        return n - best;
    }
}

