class Solution {
    public static int earliestFinishTime(int[] landStartTime, int[] landDuration, int[] waterStartTime, int[] waterDuration) {
        int n = landStartTime.length;
        int m = waterStartTime.length;

        int[][] water = new int[m][3];
        for (int i = 0; i < m; i++) {
            water[i][0] = waterStartTime[i];
            water[i][1] = waterDuration[i];
            water[i][2] = waterStartTime[i] + waterDuration[i];
        }
        Arrays.sort(water, Comparator.comparingInt(a -> a[0]));
        int[] waterStarts = new int[m];
        long[] waterSuffixMinEnd = new long[m];
        long[] waterPrefixMinDur = new long[m];
        long curMin = Long.MAX_VALUE;
        for (int i = m - 1; i >= 0; i--) {
            curMin = Math.min(curMin, water[i][2]);
            waterSuffixMinEnd[i] = curMin;
        }
        curMin = Long.MAX_VALUE;
        for (int i = 0; i < m; i++) {
            waterStarts[i] = water[i][0];
            curMin = Math.min(curMin, water[i][1]);
            waterPrefixMinDur[i] = curMin;
        }

        int[][] land = new int[n][3];
        for (int i = 0; i < n; i++) {
            land[i][0] = landStartTime[i];
            land[i][1] = landDuration[i];
            land[i][2] = landStartTime[i] + landDuration[i];
        }
        Arrays.sort(land, Comparator.comparingInt(a -> a[0]));
        int[] landStarts = new int[n];
        long[] landSuffixMinEnd = new long[n];
        long[] landPrefixMinDur = new long[n];
        curMin = Long.MAX_VALUE;
        for (int i = n - 1; i >= 0; i--) {
            curMin = Math.min(curMin, land[i][2]);
            landSuffixMinEnd[i] = curMin;
        }
        curMin = Long.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            landStarts[i] = land[i][0];
            curMin = Math.min(curMin, land[i][1]);
            landPrefixMinDur[i] = curMin;
        }

        long answer = Long.MAX_VALUE;

        for (int i = 0; i < n; i++) {
            long landFinish = land[i][2];
            int idx = lowerBound(waterStarts, landFinish);
            if (idx < m) {
                answer = Math.min(answer, waterSuffixMinEnd[idx]);
            }
            if (idx > 0) {
                answer = Math.min(answer, landFinish + waterPrefixMinDur[idx - 1]);
            }
        }

        for (int i = 0; i < m; i++) {
            long waterFinish = water[i][2];
            int idx = lowerBound(landStarts, waterFinish);
            if (idx < n) {
                answer = Math.min(answer, landSuffixMinEnd[idx]);
            }
            if (idx > 0) {
                answer = Math.min(answer, waterFinish + landPrefixMinDur[idx - 1]);
            }
        }

        return answer == Long.MAX_VALUE ? -1 : (int) answer;
    }

    private static int lowerBound(int[] arr, long target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (arr[mid] < target) {
                l = mid + 1;
            } else {
                r = mid;
            }
        }
        return l;
    }
}

