class Solution {
    public static int earliestFinishTime(int[] landStartTime, int[] landDuration, int[] waterStartTime, int[] waterDuration) {
        int n = landStartTime.length;
        int m = waterStartTime.length;
        if (n == 0 || m == 0) return -1;
        int best = Integer.MAX_VALUE;

        // Water rides sorted by start
        int[][] water = new int[m][3];
        for (int i = 0; i < m; i++) {
            water[i][0] = waterStartTime[i];
            water[i][1] = waterStartTime[i] + waterDuration[i];
            water[i][2] = waterDuration[i];
        }
        Arrays.sort(water, Comparator.comparingInt(a -> a[0]));
        int[] waterStarts = new int[m];
        int[] waterSuffixMinFinish = new int[m];
        int[] waterPrefixMinDur = new int[m];
        for (int i = 0; i < m; i++) waterStarts[i] = water[i][0];
        waterSuffixMinFinish[m - 1] = water[m - 1][1];
        for (int i = m - 2; i >= 0; i--) {
            waterSuffixMinFinish[i] = Math.min(water[i][1], waterSuffixMinFinish[i + 1]);
        }
        waterPrefixMinDur[0] = water[0][2];
        for (int i = 1; i < m; i++) {
            waterPrefixMinDur[i] = Math.min(waterPrefixMinDur[i - 1], water[i][2]);
        }

        // Land rides sorted by start
        int[][] land = new int[n][3];
        for (int i = 0; i < n; i++) {
            land[i][0] = landStartTime[i];
            land[i][1] = landStartTime[i] + landDuration[i];
            land[i][2] = landDuration[i];
        }
        Arrays.sort(land, Comparator.comparingInt(a -> a[0]));
        int[] landStarts = new int[n];
        int[] landSuffixMinFinish = new int[n];
        int[] landPrefixMinDur = new int[n];
        for (int i = 0; i < n; i++) landStarts[i] = land[i][0];
        landSuffixMinFinish[n - 1] = land[n - 1][1];
        for (int i = n - 2; i >= 0; i--) {
            landSuffixMinFinish[i] = Math.min(land[i][1], landSuffixMinFinish[i + 1]);
        }
        landPrefixMinDur[0] = land[0][2];
        for (int i = 1; i < n; i++) {
            landPrefixMinDur[i] = Math.min(landPrefixMinDur[i - 1], land[i][2]);
        }

        // Land then Water
        for (int i = 0; i < n; i++) {
            int landEnd = landStartTime[i] + landDuration[i];
            int idx = Arrays.binarySearch(waterStarts, landEnd);
            if (idx < 0) idx = -idx - 1;
            if (idx < m) {
                best = Math.min(best, waterSuffixMinFinish[idx]);
            }
            if (idx > 0) {
                best = Math.min(best, landEnd + waterPrefixMinDur[idx - 1]);
            }
        }

        // Water then Land
        for (int j = 0; j < m; j++) {
            int waterEnd = waterStartTime[j] + waterDuration[j];
            int idx = Arrays.binarySearch(landStarts, waterEnd);
            if (idx < 0) idx = -idx - 1;
            if (idx < n) {
                best = Math.min(best, landSuffixMinFinish[idx]);
            }
            if (idx > 0) {
                best = Math.min(best, waterEnd + landPrefixMinDur[idx - 1]);
            }
        }

        return best == Integer.MAX_VALUE ? -1 : best;
    }
}

