class Solution {
    private static class Query {
        int l, r, t, idx;
        long ord;
        Query(int l, int r, int t, int idx, long ord) {
            this.l = l;
            this.r = r;
            this.t = t;
            this.idx = idx;
            this.ord = ord;
        }
    }

    public static int[] thresholdMajorityQueries(int[] nums, int[][] queries) {
        int n = nums.length;
        Map<Integer, Integer> map = new HashMap<>();
        int[] uniq = new int[n];
        int[] comp = new int[n];
        int m = 0;
        for (int i = 0; i < n; i++) {
            int v = nums[i];
            Integer id = map.get(v);
            if (id == null) {
                id = m;
                map.put(v, m);
                uniq[m] = v;
                m++;
            }
            comp[i] = id;
        }

        int q = queries.length;
        Query[] qs = new Query[q];
        int pow = 21; // enough for n up to 2^21
        for (int i = 0; i < q; i++) {
            int l = queries[i][0];
            int r = queries[i][1];
            int t = queries[i][2];
            long ord = hilbertOrder(l, r, pow, 0);
            qs[i] = new Query(l, r, t, i, ord);
        }
        Arrays.sort(qs, Comparator.comparingLong(a -> a.ord));

        int[] freq = new int[m];
        @SuppressWarnings("unchecked")
        TreeSet<Integer>[] buckets = new TreeSet[n + 1];
        for (int i = 0; i <= n; i++) buckets[i] = new TreeSet<>();
        int maxFreq = 0;

        int curL = 0, curR = -1;
        int[] ans = new int[q];

        for (Query qu : qs) {
            while (curL > qu.l) {
                curL--;
                add(comp[curL], uniq, freq, buckets);
                maxFreq = Math.max(maxFreq, freq[comp[curL]]);
            }
            while (curR < qu.r) {
                curR++;
                add(comp[curR], uniq, freq, buckets);
                maxFreq = Math.max(maxFreq, freq[comp[curR]]);
            }
            while (curL < qu.l) {
                remove(comp[curL], uniq, freq, buckets);
                curL++;
                while (maxFreq > 0 && buckets[maxFreq].isEmpty()) maxFreq--;
            }
            while (curR > qu.r) {
                remove(comp[curR], uniq, freq, buckets);
                curR--;
                while (maxFreq > 0 && buckets[maxFreq].isEmpty()) maxFreq--;
            }

            if (maxFreq >= qu.t && !buckets[maxFreq].isEmpty()) {
                ans[qu.idx] = buckets[maxFreq].first();
            } else {
                ans[qu.idx] = -1;
            }
        }
        return ans;
    }

    private static void add(int idx, int[] uniq, int[] freq, TreeSet<Integer>[] buckets) {
        int val = uniq[idx];
        int f = freq[idx];
        if (f > 0) buckets[f].remove(val);
        freq[idx] = f + 1;
        buckets[f + 1].add(val);
    }

    private static void remove(int idx, int[] uniq, int[] freq, TreeSet<Integer>[] buckets) {
        int val = uniq[idx];
        int f = freq[idx];
        buckets[f].remove(val);
        freq[idx] = f - 1;
        if (f - 1 > 0) buckets[f - 1].add(val);
    }

    private static long hilbertOrder(int x, int y, int pow, int rotate) {
        if (pow == 0) return 0;
        int h = 1 << (pow - 1);
        int seg = (x < h ? (y < h ? 0 : 3) : (y < h ? 1 : 2));
        seg = (seg + rotate) & 3;
        int[] rotateDelta = {0, 3, 0, 1};
        int nx = x & (h - 1);
        int ny = y & (h - 1);
        int nrot = (rotate + rotateDelta[seg]) & 3;
        long subSquareSize = 1L << (2 * pow - 2);
        long ord = seg * subSquareSize;
        long add = hilbertOrder(nx, ny, pow - 1, nrot);
        return ord + add;
    }
}

class Solution {
    public long maxSumTrionic(int[] nums) {
        int n = nums.length;
        int i = 0;
        long ans = Long.MIN_VALUE;
        while (i < n) {
            int l = i;
            i += 1;
            while (i < n && nums[i - 1] < nums[i]) i += 1;
            if (i == l + 1) continue;
            int p = i - 1;
            long s = (long) nums[p - 1] + nums[p];
            while (i < n && nums[i - 1] > nums[i]) { s += nums[i]; i += 1; }
            if (i == p + 1 || i == n || nums[i - 1] == nums[i]) continue;
            int q = i - 1;
            s += nums[i];
            i += 1;
            long mx = 0, t = 0;
            while (i < n && nums[i - 1] < nums[i]) { t += nums[i]; i += 1; mx = Math.max(mx, t); }
            s += mx;
            mx = 0; t = 0;
            int j = p - 2;
            while (j >= l) { t += nums[j]; mx = Math.max(mx, t); j -= 1; }
            s += mx;
            ans = Math.max(ans, s);
            i = q;
        }
        return ans;
    }
}

