class Solution {
    public static int minimumTime(String s, int[] order, long k) {
        int n = s.length();
        long total = (long) n * (n + 1) / 2;
        if (k > total) return -1;
        if (k <= 0) return 0;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, Comparator.comparingInt(i -> order[i]));
        TreeSet<Integer> stars = new TreeSet<>();
        stars.add(-1);
        stars.add(n);
        long bad = total;
        for (int pos : idx) {
            Integer left = stars.lower(pos);
            Integer right = stars.higher(pos);
            int L = right - left - 1;
            long oldBad = (long) L * (L + 1) / 2;
            int leftLen = pos - left - 1;
            int rightLen = right - pos - 1;
            long newBad = (long) leftLen * (leftLen + 1) / 2 + (long) rightLen * (rightLen + 1) / 2;
            bad = bad - oldBad + newBad;
            stars.add(pos);
            long good = total - bad;
            if (good >= k) {
                return order[pos];
            }
        }
        return -1;
    }
}

class Solution {
    public static int maxBalancedShipments(int[] weight) {
        int n = weight.length;
        if (n == 0) return 0;
        int shipments = 0;
        int i = 0;
        while (i < n) {
            int maxSoFar = weight[i];
            i++;
            while (i < n && weight[i] >= maxSoFar) {
                if (weight[i] > maxSoFar) {
                    maxSoFar = weight[i];
                }
                i++;
            }
            if (i < n) {
                shipments++;
                i++;
            }
        }
        return shipments;
    }
}

