class Solution {
    public static int[][] flipSquareSubmatrixVertically(int[][] matrix, int row, int col, int k) {
        for (int i = 0; i < k / 2; i++) {
            int top = row + i;
            int bottom = row + k - 1 - i;
            for (int j = col; j < col + k; j++) {
                int temp = matrix[top][j];
                matrix[top][j] = matrix[bottom][j];
                matrix[bottom][j] = temp;
            }
        }
        return matrix;
    }
}

