class Solution {
    public long numberOfPerfectPairs(int[] nums) {
        int n = nums.length;
        long[] arr = new long[n];
        for (int i = 0; i < n; i++) arr[i] = Math.abs((long) nums[i]);
        Arrays.sort(arr);
        int start = 0;
        long ans = 0;
        for (int i = 1; i < n; i++) {
            long need = (arr[i] + 1) / 2;
            while (arr[start] < need) start++;
            ans += i - start;
        }
        return ans;
    }
}

class Solution {
    public static long maxProfit(int[] prices, int[] strategy, int k) {
        int n = prices.length;
        int h = k / 2;
        long pOriginal = 0;
        for (int i = 0; i < n; i++) pOriginal += (long)strategy[i] * prices[i];
        long newSeg = 0;
        for (int i = h; i < k; i++) newSeg += prices[i];
        long oldSeg = 0;
        for (int i = 0; i < k; i++) oldSeg += (long)strategy[i] * prices[i];
        long maxDelta = Math.max(0L, newSeg - oldSeg);
        for (int j = 1; j <= n - k; j++) {
            oldSeg += -(long)strategy[j-1]*prices[j-1] + (long)strategy[j+k-1]*prices[j+k-1];
            newSeg += -prices[j-1+h] + prices[j+k-1];
            maxDelta = Math.max(maxDelta, newSeg - oldSeg);
        }
        return pOriginal + maxDelta;
    }
}

