class Solution {
    public static long minimumSumAfterDivisibleSumDeletions(int[] a, int K) {
        int n = a.length;
        long total = 0;
        for (int v : a) total += v;
        if (K == 0) return total;
        int mod = Math.abs(K);
        long dp = 0;
        long prefix = 0;
        Map<Integer, Long> best = new HashMap<>();
        best.put(0, 0L);
        for (int i = 0; i < n; i++) {
            prefix += a[i];
            int rem = (int) ((prefix % mod + mod) % mod);
            Long bestVal = best.get(rem);
            if (bestVal != null) {
                long candidate = bestVal + prefix;
                if (candidate > dp) dp = candidate;
            }
            long cur = dp - prefix;
            Long curBest = best.get(rem);
            if (curBest == null || cur > curBest) {
                best.put(rem, cur);
            }
        }
        return total - dp;
    }
}

