public class TwistedMirror {
    static final long MOD = 1000000007L;
    static int n, m;
    static int[][] grid;
    static Map<Long, Long> memo;

    static long dp(int i, int j, int direction) {
        while (i >= 0 && i < n && j >= 0 && j < m && grid[i][j] == 1) {
            direction = 1 - direction;
            if (direction == 0) i += 1; else j += 1;
        }
        if (i < 0 || i >= n || j < 0 || j >= m) return 0;
        if (i == n - 1 && j == m - 1) return 1;
        if (grid[i][j] == 0) {
            long key = (long) i * 100000 + j;
            if (memo.containsKey(key)) return memo.get(key);
            long res = (dp(i + 1, j, 0) + dp(i, j + 1, 1)) % MOD;
            memo.put(key, res);
            return res;
        }
        return 0;
    }

    static int uniquePaths(int[][] g) {
        grid = g;
        n = g.length; m = g[0].length;
        memo = new HashMap<>();
        return (int) (dp(0, 0, 0) % MOD);
    }
}

