class Solution {
    public static int minOperations(String s, int k) {
        int n = s.length();
        int cnt0=0; for(char c: s.toCharArray()) if(c=='0') cnt0++;
        boolean[] visited = new boolean[n+1];
        visited[cnt0]=true;
        List<Integer> queue = new ArrayList<>(); queue.add(cnt0);
        int ans=0;
        while(!queue.isEmpty()){
            List<Integer> nxt = new ArrayList<>();
            for(int cur: queue){
                if (cur==0) return ans;
                int l = cur+k-2*Math.min(cur,k);
                int r = cur+k-2*Math.max(k-n+cur,0);
                for(int v=l; v<=r; v+=2){
                    if (v<0 || v>n) continue;
                    if(!visited[v]){ visited[v]=true; nxt.add(v); }
                }
            }
            queue = nxt; ans++;
        }
        return -1;
    }
}

