class Solution {
    public static long countBowlSubarrays(int[] arr) {
        int n = arr.length;
        if (n < 3) return 0;

        int[] nextGreater = new int[n];
        int[] prevGreater = new int[n];
        Arrays.fill(nextGreater, -1);
        Arrays.fill(prevGreater, -1);

        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && arr[stack.peek()] < arr[i]) {
                nextGreater[stack.pop()] = i;
            }
            stack.push(i);
        }
        stack.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && arr[stack.peek()] < arr[i]) {
                prevGreater[stack.pop()] = i;
            }
            stack.push(i);
        }

        long count = 0;
        for (int l = 0; l < n; l++) {
            int r = nextGreater[l];
            if (r != -1 && r - l >= 2) count++;
        }
        for (int r = 0; r < n; r++) {
            int l = prevGreater[r];
            if (l != -1 && r - l >= 2) count++;
        }
        return count;
    }
}

