class Solution {
    public static long countBinaryPalindromes(long N) {
        if (N < 0) return 0;
        if (N == 0) return 1;
        long total = 1; // count zero
        int binLen = 64 - Long.numberOfLeadingZeros(N);
        for (int len = 1; len < binLen; len++) {
            int half = (len + 1) / 2;
            total += 1L << (half - 1);
        }
        int halfLen = (binLen + 1) / 2;
        long base = 1L << (halfLen - 1);
        long prefix = N >> (binLen / 2);
        long countSameLen = prefix - base;
        long palindrome = buildPalindrome(prefix, binLen);
        if (palindrome <= N) countSameLen++;
        total += countSameLen;
        return total;
    }

    private static long buildPalindrome(long prefix, int len) {
        boolean odd = (len & 1) == 1;
        long palindrome = prefix;
        long rev = odd ? (prefix >> 1) : prefix;
        while (rev > 0) {
            palindrome = (palindrome << 1) | (rev & 1L);
            rev >>= 1;
        }
        return palindrome;
    }
}

