class Solution {
    public static long maximumXOR(long[] arr) {
        final int MAX_BIT = 60;
        long[] basis = new long[MAX_BIT + 1];
        for (long num : arr) {
            long x = num;
            for (int b = MAX_BIT; b >= 0; b--) {
                if ((x & (1L << b)) == 0) continue;
                if (basis[b] == 0) {
                    basis[b] = x;
                    break;
                }
                x ^= basis[b];
            }
        }
        long result = 0;
        for (int b = MAX_BIT; b >= 0; b--) {
            long candidate = result ^ basis[b];
            if (candidate > result) {
                result = candidate;
            }
        }
        return result;
    }
}

class Solution {
    public boolean[] subsequenceSumAfterCapping(int[] nums, int k) {
        int n = nums.length;
        int[] freq = new int[n + 2];
        for (int v : nums) freq[v]++;
        java.math.BigInteger mask = java.math.BigInteger.ONE.shiftLeft(k + 1).subtract(java.math.BigInteger.ONE);
        // freeDP: achievable sums using items whose true value <= current x (uncapped, real value)
        java.math.BigInteger freeDP = java.math.BigInteger.ONE;
        int runningCappedCount = n; // items still strictly above current x, each contributing exactly x
        boolean[] ans = new boolean[n];
        for (int x = 1; x <= n; x++) {
            int cntX = freq[x];
            for (int i = 0; i < cntX; i++) {
                freeDP = freeDP.or(freeDP.shiftLeft(x)).and(mask);
            }
            runningCappedCount -= cntX;
            int m = runningCappedCount;
            int maxJ = Math.min(m, k / x);
            // combine freeDP with 0..m copies of value x (harmonic-series bitset trick)
            java.math.BigInteger combined = java.math.BigInteger.ZERO;
            java.math.BigInteger shifted = freeDP;
            for (int j = 0; j <= maxJ; j++) {
                combined = combined.or(shifted);
                shifted = shifted.shiftLeft(x).and(mask);
            }
            ans[x - 1] = combined.testBit(k);
        }
        return ans;
    }
}

