class Solution {
    public static int minArrivalsToDiscard(int[] arrivals, int w, int m) {
        int n = arrivals.length;
        boolean[] kept = new boolean[n];
        Map<Integer,Integer> cnt = new HashMap<>();
        int discards = 0;
        for (int i = 0; i < n; i++) {
            int x = arrivals[i];
            int left = i - w;
            if (left >= 0 && kept[left]) cnt.merge(arrivals[left], -1, Integer::sum);
            int c = cnt.getOrDefault(x, 0);
            if (c >= m) { discards++; kept[i] = false; }
            else { cnt.put(x, c+1); kept[i] = true; }
        }
        return discards;
    }
}

class Solution {
    public int[][] generateSchedule(int n) {
        if (n <= 4) return new int[0][];
        Map<Long, Boolean> remaining = new HashMap<>();
        int[] deg = new int[n];
        for (int a = 0; a < n; a++)
            for (int b = 0; b < n; b++)
                if (a != b) { remaining.put((long)a*1000+b, true); deg[a]++; deg[b]++; }

        List<int[]> seq = new ArrayList<>();
        int[] last = null;
        int total = n*(n-1);
        for (int step = 0; step < total; step++) {
            int bestA=-1, bestB=-1, bestScore=-1;
            for (var e : remaining.entrySet()) {
                if (!e.getValue()) continue;
                long key = e.getKey();
                int a = (int)(key/1000), b = (int)(key%1000);
                if (last != null && (a==last[0]||a==last[1]||b==last[0]||b==last[1])) continue;
                int score = deg[a]+deg[b];
                if (score > bestScore) { bestScore = score; bestA = a; bestB = b; }
            }
            if (bestA == -1) return new int[0][];
            remaining.put((long)bestA*1000+bestB, false);
            deg[bestA]--; deg[bestB]--;
            seq.add(new int[]{bestA,bestB});
            last = new int[]{bestA,bestB};
        }
        return seq.toArray(new int[0][]);
    }
}

