    public static int[] maxSumAtMostKDistinct(int[] arr, int K) {
        if (K <= 0) {
            return new int[0];
        }
        Set<Integer> distinct = new HashSet<>();
        for (int v : arr) {
            distinct.add(v);
        }
        List<Integer> sorted = new ArrayList<>(distinct);
        sorted.sort(Collections.reverseOrder());
        int limit = Math.min(K, sorted.size());
        int[] result = new int[limit];
        for (int i = 0; i < limit; i++) {
            result[i] = sorted.get(i);
        }
        return result;
    }
}

import java.util.*;

public class Solution {
    public int minSplitMerge(int[] nums1, int[] nums2) {
        int n = nums1.length;
        List<Integer> start = new ArrayList<>();
        for (int x : nums1) start.add(x);
        List<Integer> target = new ArrayList<>();
        for (int x : nums2) target.add(x);
        if (start.equals(target)) return 0;

        Set<List<Integer>> visited = new HashSet<>();
        visited.add(start);
        Deque<List<Integer>> queue = new ArrayDeque<>();
        queue.add(start);
        int steps = 0;

        while (!queue.isEmpty()) {
            steps++;
            int size = queue.size();
            for (int s = 0; s < size; s++) {
                List<Integer> cur = queue.poll();
                for (int l = 0; l < n; l++) {
                    for (int r = l; r < n; r++) {
                        List<Integer> sub = new ArrayList<>(cur.subList(l, r + 1));
                        List<Integer> rest = new ArrayList<>(cur.subList(0, l));
                        rest.addAll(cur.subList(r + 1, n));
                        for (int pos = 0; pos <= rest.size(); pos++) {
                            List<Integer> newState = new ArrayList<>(rest.subList(0, pos));
                            newState.addAll(sub);
                            newState.addAll(rest.subList(pos, rest.size()));
                            if (newState.equals(target)) return steps;
                            if (!visited.contains(newState)) {
                                visited.add(newState);
                                queue.add(newState);
                            }
                        }
                    }
                }
            }
        }
        return -1;
    }
}

public class Solution {
    static final long MOD = 1_000_000_007L;

    public int numberOfStableSubsequences(int[] nums) {
        // dp[p][0] = subsequences ending with exactly 1 consecutive element of parity p
        // dp[p][1] = subsequences ending with exactly 2 consecutive elements of parity p
        long[][] dp = new long[2][2];
        for (int x : nums) {
            int p = x % 2;
            int op = 1 - p;
            long extendFromOpposite = (dp[op][0] + dp[op][1]) % MOD;
            long newCount1 = (extendFromOpposite + 1) % MOD;
            long newCount2 = dp[p][0];
            dp[p][0] = (dp[p][0] + newCount1) % MOD;
            dp[p][1] = (dp[p][1] + newCount2) % MOD;
        }
        long ans = (dp[0][0] + dp[0][1] + dp[1][0] + dp[1][1]) % MOD;
        return (int) ans;
    }
}

