class Solution {
    public static String majorityFrequencyChars(String s) {
        if (s == null || s.isEmpty()) {
            return "";
        }
        Map<Character, Integer> freqMap = new HashMap<>();
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            freqMap.merge(ch, 1, Integer::sum);
        }
        Map<Integer, Integer> countMap = new HashMap<>();
        for (int f : freqMap.values()) {
            countMap.merge(f, 1, Integer::sum);
        }
        int bestFreq = -1;
        int bestCount = -1;
        for (Map.Entry<Integer, Integer> e : countMap.entrySet()) {
            int f = e.getKey();
            int cnt = e.getValue();
            if (cnt > bestCount || (cnt == bestCount && f > bestFreq)) {
                bestCount = cnt;
                bestFreq = f;
            }
        }
        List<Character> chars = new ArrayList<>();
        for (Map.Entry<Character, Integer> e : freqMap.entrySet()) {
            if (e.getValue() == bestFreq) {
                chars.add(e.getKey());
            }
        }
        Collections.sort(chars);
        StringBuilder sb = new StringBuilder();
        for (char c : chars) {
            sb.append(c);
        }
        return sb.toString();
    }
}

