public class Solution {
    public static int countDistinct(String s, int k) {
        int n = s.length();
        int[] xs = new int[n + 1];
        int[] ys = new int[n + 1];
        for (int i = 0; i < n; i++) {
            xs[i + 1] = xs[i];
            ys[i + 1] = ys[i];
            char c = s.charAt(i);
            if (c == 'L') xs[i + 1]--;
            else if (c == 'R') xs[i + 1]++;
            else if (c == 'U') ys[i + 1]++;
            else if (c == 'D') ys[i + 1]--;
        }
        int totalX = xs[n], totalY = ys[n];
        Set<Long> seen = new HashSet<>();
        for (int i = k; i <= n; i++) {
            int removedX = xs[i] - xs[i - k];
            int removedY = ys[i] - ys[i - k];
            int fx = totalX - removedX, fy = totalY - removedY;
            long key = ((long) fx << 32) ^ (fy & 0xffffffffL);
            seen.add(key);
        }
        return seen.size();
    }
}

import java.util.*;

class Solution {
    public static long maxAlternatingSum(int[] arr, int[][] swaps) {
        int n = arr.length;
        int[] parent = new int[n];
        int[] rank = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
        for (int[] p : swaps) union(p[0], p[1], parent, rank);
        Map<Integer, Component> map = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int root = find(i, parent);
            Component comp = map.computeIfAbsent(root, k -> new Component());
            if ((i & 1) == 0) comp.posCount++;
            comp.values.add(arr[i]);
        }
        long total = 0;
        for (Component comp : map.values()) {
            List<Integer> vals = comp.values;
            vals.sort(Collections.reverseOrder());
            long posSum = 0, negSum = 0;
            int posNeeded = comp.posCount;
            for (int i = 0; i < vals.size(); i++) {
                if (i < posNeeded) posSum += vals.get(i);
                else negSum += vals.get(i);
            }
            total += posSum - negSum;
        }
        return total;
    }

    private static int find(int x, int[] parent) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    private static void union(int a, int b, int[] parent, int[] rank) {
        int ra = find(a, parent);
        int rb = find(b, parent);
        if (ra == rb) return;
        if (rank[ra] < rank[rb]) {
            int t = ra; ra = rb; rb = t;
        }
        parent[rb] = ra;
        if (rank[ra] == rank[rb]) rank[ra]++;
    }

    private static class Component {
        int posCount = 0;
        List<Integer> values = new ArrayList<>();
    }
}

