class Solution {
    public static long climbStairs(int n, int[] costs) {
        long[] f = new long[n+1];
        java.util.Arrays.fill(f, Long.MAX_VALUE/2);
        f[0] = 0;
        for (int i = 1; i <= n; i++) {
            int x = costs[i-1];
            for (int j = Math.max(0, i-3); j < i; j++) {
                f[i] = Math.min(f[i], f[j] + x + (long)(i-j)*(i-j));
            }
        }
        return f[n];
    }
}

