class Solution {
    public static long splitArray(int[] nums) {
        int n = nums.length;
        if (n < 2) return -1;
        long[] s = new long[n];
        s[0] = nums[0];
        boolean[] f = new boolean[n];
        boolean[] g = new boolean[n];
        Arrays.fill(f, true);
        Arrays.fill(g, true);
        for (int i = 1; i < n; i++) {
            s[i] = s[i-1] + nums[i];
            f[i] = f[i-1] && nums[i] > nums[i-1];
        }
        for (int i = n-2; i >= 0; i--) {
            g[i] = g[i+1] && nums[i] > nums[i+1];
        }
        long ans = -1;
        boolean found = false;
        for (int i = 0; i < n-1; i++) {
            if (f[i] && g[i+1]) {
                long leftSum = s[i];
                long rightSum = s[n-1] - s[i];
                long diff = Math.abs(leftSum - rightSum);
                if (!found || diff < ans) { ans = diff; found = true; }
            }
        }
        return found ? ans : -1;
    }
}

import java.util.*;
class Solution {
    static final long MOD = 1000000007L;
    public static long numberOfZigZagArrays(int n, int m) {
        if (n == 1) return m % MOD;
        long[] dp = new long[m + 2];
        Arrays.fill(dp, 1L); dp[0] = 0;
        for (int i = 2; i <= n; i++) {
            long[] pref = new long[m + 2];
            for (int v = 1; v <= m; v++) pref[v] = (pref[v-1] + dp[v]) % MOD;
            long total = pref[m];
            long[] ndp = new long[m + 2];
            if (i % 2 == 0) { for (int v = 1; v <= m; v++) ndp[v] = pref[v-1]; }
            else { for (int v = 1; v <= m; v++) ndp[v] = (total - pref[v] + MOD) % MOD; }
            dp = ndp;
        }
        long half = 0;
        for (int v = 1; v <= m; v++) half = (half + dp[v]) % MOD;
        return (half * 2) % MOD;
    }
}

