class Solution {
    static final long MOD = 1000000007L;
    static long[][] matMul(long[][] A, long[][] B) {
        int n = A.length;
        long[][] C = new long[n][n];
        for (int i = 0; i < n; i++) for (int k = 0; k < n; k++) {
            if (A[i][k] == 0) continue;
            for (int j = 0; j < n; j++) { if (B[k][j] == 0) continue; C[i][j] = (C[i][j] + A[i][k]*B[k][j]) % MOD; }
        }
        return C;
    }
    static long[][] matPow(long[][] M, long e) {
        int n = M.length;
        long[][] R = new long[n][n];
        for (int i = 0; i < n; i++) R[i][i] = 1;
        while (e > 0) { if ((e & 1) == 1) R = matMul(R, M); M = matMul(M, M); e >>= 1; }
        return R;
    }
    public static int zigZagArrays(int n, int l, int r) {
        int m = r - l + 1;
        long[][] T = new long[m][m];
        for (int j = 0; j < m; j++) for (int i = m-j; i < m; i++) T[i][j] = 1;
        long[][] powT = matPow(T, n-1);
        long total = 0;
        for (int i = 0; i < m; i++) for (int j = 0; j < m; j++) total = (total + powT[i][j]) % MOD;
        return (int)((total * 2) % MOD);
    }
}

class Solution {
    public long countNoZeroPairs(long n) {
        char[] cs = Long.toString(n).toCharArray();
        int m = cs.length;
        int[] digits = new int[m + 1];
        for (int i = 0; i < m; i++) digits[i] = cs[m - 1 - i] - '0';
        digits[m] = 0;
        long[][][] dp = new long[2][2][2];
        dp[0][1][1] = 1;
        for (int pos = 0; pos < m + 1; pos++) {
            long[][][] ndp = new long[2][2][2];
            int target = digits[pos];
            for (int carry = 0; carry <= 1; carry++) {
                for (int aliveA = 0; aliveA <= 1; aliveA++) {
                    for (int aliveB = 0; aliveB <= 1; aliveB++) {
                        long ways = dp[carry][aliveA][aliveB];
                        if (ways == 0) continue;
                        int[] aDigits, aNext;
                        if (aliveA == 1) {
                            if (pos == 0) { aDigits = new int[]{1,2,3,4,5,6,7,8,9}; aNext = new int[]{1,1,1,1,1,1,1,1,1}; }
                            else { aDigits = new int[]{1,2,3,4,5,6,7,8,9,0}; aNext = new int[]{1,1,1,1,1,1,1,1,1,0}; }
                        } else { aDigits = new int[]{0}; aNext = new int[]{0}; }
                        int[] bDigits, bNext;
                        if (aliveB == 1) {
                            if (pos == 0) { bDigits = new int[]{1,2,3,4,5,6,7,8,9}; bNext = new int[]{1,1,1,1,1,1,1,1,1}; }
                            else { bDigits = new int[]{1,2,3,4,5,6,7,8,9,0}; bNext = new int[]{1,1,1,1,1,1,1,1,1,0}; }
                        } else { bDigits = new int[]{0}; bNext = new int[]{0}; }
                        for (int ai = 0; ai < aDigits.length; ai++) {
                            int da = aDigits[ai], na = aNext[ai];
                            for (int bi = 0; bi < bDigits.length; bi++) {
                                int db = bDigits[bi], nb = bNext[bi];
                                int s = da + db + carry;
                                if (s % 10 != target) continue;
                                ndp[s/10][na][nb] += ways;
                            }
                        }
                    }
                }
            }
            dp = ndp;
        }
        return dp[0][0][0];
    }
}

import java.util.*;
class ExamTracker {
    List<Integer> times = new ArrayList<>();
    List<Long> prefix = new ArrayList<>(List.of(0L));
    public void record(int time, int score) {
        times.add(time);
        prefix.add(prefix.get(prefix.size() - 1) + score);
    }
    public long totalScore(int startTime, int endTime) {
        int lo = lowerBound(startTime);
        int hi = upperBound(endTime);
        if (lo >= hi) return 0;
        return prefix.get(hi) - prefix.get(lo);
    }
    private int lowerBound(int key) {
        int lo = 0, hi = times.size();
        while (lo < hi) { int mid = (lo + hi) / 2; if (times.get(mid) < key) lo = mid + 1; else hi = mid; }
        return lo;
    }
    private int upperBound(int key) {
        int lo = 0, hi = times.size();
        while (lo < hi) { int mid = (lo + hi) / 2; if (times.get(mid) <= key) lo = mid + 1; else hi = mid; }
        return lo;
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    private static class Frame {
        StringBuilder sb;
        int pairs;
        Frame() {
            this.sb = new StringBuilder();
            this.pairs = 0;
        }
    }

    public static String removeKBalanced(String s, int k) {
        if (k <= 0) return s;
        Deque<Frame> stack = new ArrayDeque<>();
        stack.push(new Frame());
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == '(') {
                stack.push(new Frame());
            } else { // ch == ')'
                Frame inner = stack.pop();
                int totalPairs = inner.pairs + 1;
                if (totalPairs != k) {
                    inner.sb.insert(0, '(');
                    inner.sb.append(')');
                    Frame outer = stack.peek();
                    outer.sb.append(inner.sb);
                    outer.pairs += totalPairs;
                }
            }
        }
        while (stack.size() > 1) {
            Frame inner = stack.pop();
            inner.sb.insert(0, '(');
            Frame outer = stack.peek();
            outer.sb.append(inner.sb);
        }
        return stack.peek().sb.toString();
    }
}

import java.util.Arrays;

class Solution {
    public static int longestBalancedSubstring(String s) {
        int n = s.length();
        int maxLen = 0;
        int[] cnt = new int[26];
        for (int i = 0; i < n; i++) {
            Arrays.fill(cnt, 0);
            for (int j = i; j < n; j++) {
                cnt[s.charAt(j) - 'a']++;
                int min = Integer.MAX_VALUE;
                int max = 0;
                for (int k = 0; k < 26; k++) {
                    if (cnt[k] > 0) {
                        if (cnt[k] < min) min = cnt[k];
                        if (cnt[k] > max) max = cnt[k];
                    }
                }
                if (min != Integer.MAX_VALUE && min == max) {
                    int len = j - i + 1;
                    if (len > maxLen) maxLen = len;
                }
            }
        }
        return maxLen;
    }
}

import java.util.HashSet;

class Solution {
    public static boolean equalScoreSubstring(String s) {
        int total = 0;
        for (int i = 0; i < s.length(); i++) {
            total += s.charAt(i) - 'a' + 1;
        }
        if (total % 2 != 0) {
            return false;
        }
        int target = total / 2;
        int prefix = 0;
        HashSet<Integer> seen = new HashSet<>();
        for (int i = 0; i < s.length(); i++) {
            prefix += s.charAt(i) - 'a' + 1;
            if (prefix == target) {
                return true;
            }
            if (seen.contains(prefix - target)) {
                return true;
            }
            seen.add(prefix);
        }
        return false;
    }
}

public class Solution {
