import java.util.*;
class Solution {
    public static long sumOfAncestors(int n, int[][] edges, int[] nums) {
        long[] vals = new long[n];
        for (int i = 0; i < n; i++) {
            long num = nums[i];
            for (long j = 2; j*j <= num; j++) while (num % (j*j) == 0) num /= (j*j);
            vals[i] = num;
        }
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) graph.add(new ArrayList<>());
        for (int[] e : edges) { graph.get(e[0]).add(e[1]); graph.get(e[1]).add(e[0]); }
        long[] ans = {0};
        Map<Long,Integer> history = new HashMap<>();
        dfs(0, -1, vals, graph, ans, history);
        return ans[0];
    }
    private static void dfs(int u, int p, long[] vals, List<List<Integer>> graph, long[] ans, Map<Long,Integer> history) {
        long v = vals[u];
        ans[0] += history.getOrDefault(v, 0);
        history.put(v, history.getOrDefault(v, 0) + 1);
        for (int w : graph.get(u)) if (w != p) dfs(w, u, vals, graph, ans, history);
        history.put(v, history.get(v) - 1);
    }
}

class Solution {
    public static long maximumPartitionFactor(int[][] points) {
        if (points.length < 2) return 0;
        long maxSum = Long.MIN_VALUE, minSum = Long.MAX_VALUE, maxDiff = Long.MIN_VALUE, minDiff = Long.MAX_VALUE;
        for (int[] p : points) {
            long s = p[0] + p[1], d = p[0] - p[1];
            maxSum = Math.max(maxSum, s);
            minSum = Math.min(minSum, s);
            maxDiff = Math.max(maxDiff, d);
            minDiff = Math.min(minDiff, d);
        }
        return Math.max(maxSum - minSum, maxDiff - minDiff);
    }
}

import java.util.HashSet;

class Solution {
    public static int smallestMissingMultiple(int[] arr, int K) {
        if (K <= 0) {
            return 0;
        }
        HashSet<Integer> present = new HashSet<>(arr.length);
        for (int v : arr) {
            present.add(v);
        }
        long candidate = K;
        while (candidate <= Integer.MAX_VALUE && present.contains((int) candidate)) {
            candidate += K;
        }
        return (int) candidate;
    }
}

class Solution {
    public static String smallestPermutationGreater(String s, String target) {
        int n = s.length();
        int[] base = new int[26];
        for (char c : s.toCharArray()) base[c-'a']++;
        String best = null;
        for (int i = n-1; i >= 0; i--) {
            int[] count = base.clone();
            boolean ok = true;
            for (int j = 0; j < i; j++) {
                int idx = target.charAt(j)-'a';
                if (count[idx] == 0) { ok = false; break; }
                count[idx]--;
            }
            if (!ok) continue;
            int tIdx = target.charAt(i)-'a';
            int pick = -1;
            for (int d = tIdx+1; d < 26; d++) if (count[d] > 0) { pick = d; break; }
            if (pick == -1) continue;
            count[pick]--;
            StringBuilder suffix = new StringBuilder();
            for (int d = 0; d < 26; d++) for (int c = 0; c < count[d]; c++) suffix.append((char)('a'+d));
            String candidate = target.substring(0, i) + (char)('a'+pick) + suffix;
            if (best == null || candidate.compareTo(best) < 0) best = candidate;
        }
        return best == null ? "" : best;
    }
}

