import java.util.*;

public class Solution {
    private static final long MOD = 1_000_000_007L;

    public static long countWays(int[][] rows) {
        int n = rows.length;
        if (n == 0) return 0;
        int m = rows[0].length;
        int maxA = 0;
        for (int[] row : rows) {
            for (int val : row) {
                if (val > maxA) maxA = val;
            }
        }
        int[] mu = mobius(maxA);
        long[] prod = new long[maxA + 1];
        Arrays.fill(prod, 1L);
        int[] cntRow = new int[maxA + 1];

        for (int[] row : rows) {
            Arrays.fill(cntRow, 0);
            for (int val : row) {
                for (int d = 1; d * d <= val; d++) {
                    if (val % d == 0) {
                        cntRow[d]++;
                        int other = val / d;
                        if (other != d) cntRow[other]++;
                    }
                }
            }
            for (int d = 1; d <= maxA; d++) {
                prod[d] = (prod[d] * cntRow[d]) % MOD;
            }
        }

        long ans = 0;
        for (int d = 1; d <= maxA; d++) {
            if (mu[d] == 0) continue;
            long term = prod[d];
            if (mu[d] == -1) term = MOD - term;
            ans += term;
            if (ans >= MOD) ans -= MOD;
        }
        return ans % MOD;
    }

    private static int[] mobius(int limit) {
        int[] mu = new int[limit + 1];
        int[] primes = new int[limit + 1];
        boolean[] isComp = new boolean[limit + 1];
        int pcnt = 0;
        mu[1] = 1;
        for (int i = 2; i <= limit; i++) {
            if (!isComp[i]) {
                primes[pcnt++] = i;
                mu[i] = -1;
            }
            for (int j = 0; j < pcnt; j++) {
                int p = primes[j];
                long v = (long) i * p;
                if (v > limit) break;
                isComp[(int) v] = true;
                if (i % p == 0) {
                    mu[(int) v] = 0;
                    break;
                } else {
                    mu[(int) v] = -mu[i];
                }
            }
        }
        return mu;
    }
}

public class Solution {
    public static long removeZeros(long n) {
        boolean negative = n < 0;
        long value = negative ? -n : n;
        long rev = 0;
        while (value > 0) {
            long d = value % 10;
            if (d != 0) {
                rev = rev * 10 + d;
            }
            value /= 10;
        }
        long result = 0;
        while (rev > 0) {
            result = result * 10 + rev % 10;
            rev /= 10;
        }
        return negative ? -result : result;
    }
}

