class Solution {
    public static long maxAlternatingSumSquares(int[] arr) {
        int n = arr.length;
        long[] squares = new long[n];
        for (int i = 0; i < n; i++) {
            long v = arr[i];
            squares[i] = v * v;
        }
        Arrays.sort(squares);
        int left = 0, right = n - 1;
        long total = 0;
        boolean add = true;
        while (left <= right) {
            if (add) {
                total += squares[right];
                right--;
            } else {
                total -= squares[left];
                left++;
            }
            add = !add;
        }
        return total;
    }
}

