class Solution {
    public static long countStableSubarrays(int[] capacity) {
        int n = capacity.length;
        long[] s = new long[n + 1];
        for (int i = 1; i <= n; i++) s[i] = s[i - 1] + capacity[i - 1];

        Map<Long, Integer> cnt = new HashMap<>();
        long ans = 0;
        for (int r = 2; r < n; r++) {
            int l = r - 2;
            long lv = capacity[l];
            long leftKey = lv * 2_000_000_007L + (s[l] + 2 * lv); // simple combined key
            cnt.merge(leftKey, 1, Integer::sum);

            long rv = capacity[r];
            long rightKey = rv * 2_000_000_007L + s[r];
            ans += cnt.getOrDefault(rightKey, 0);
        }
        return ans;
    }
}

