import java.util.Set;

class Solution {
    public static int countDistinctSubarraysDivisibleByK(int[] arr, int K) {
        int n = arr.length;
        long[] prefixSum = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + arr[i];
        }
        final long BASE = 91138233L;
        long[] prefixHash = new long[n + 1];
        long[] pow = new long[n + 1];
        pow[0] = 1;
        for (int i = 0; i < n; i++) {
            pow[i + 1] = pow[i] * BASE;
            prefixHash[i + 1] = prefixHash[i] * BASE + (arr[i] + 1L);
        }
        Set<Long> seen = new HashSet<>();
        for (int start = 0; start < n; start++) {
            for (int end = start; end < n; end++) {
                long sum = prefixSum[end + 1] - prefixSum[start];
                if ((sum % K + K) % K == 0) {
                    int len = end - start + 1;
                    long subHash = prefixHash[end + 1] - prefixHash[start] * pow[len];
                    seen.add(subHash);
                }
            }
        }
        return seen.size();
    }
}

