class Solution {
    public static List<Integer> findMissingElements(int[] arr) {
        if (arr == null || arr.length == 0) {
            return new ArrayList<>();
        }
        Arrays.sort(arr);
        List<Integer> missing = new ArrayList<>();
        for (int i = 0; i < arr.length - 1; i++) {
            int current = arr[i];
            int next = arr[i + 1];
            if (next - current > 1) {
                for (int val = current + 1; val < next; val++) {
                    missing.add(val);
                }
            }
        }
        return missing;
    }
}

class Solution {
    // Since the product is linear in the replaced value, the optimum always uses an
    // extreme replacement value (+1e5 or -1e5). Three candidates cover every optimal
    // configuration: (a) two smallest * +1e5 (turns two negatives + a forced positive
    // into a big positive), (b) two largest * +1e5, (c) smallest * largest * -1e5
    // (manufactures a second negative to pair with an already-very-negative smallest
    // and a very-positive largest). Any other index can always serve as the "replaced"
    // slot since n >= 3.
    public long maxProductThree(int[] nums) {
        int[] a = nums.clone();
        java.util.Arrays.sort(a);
        int n = a.length;
        long REP = 100000L;
        long caseA = (long) a[0] * a[1] * REP;
        long caseB = (long) a[n-2] * a[n-1] * REP;
        long caseC = (long) a[0] * a[n-1] * (-REP);
        return Math.max(caseA, Math.max(caseB, caseC));
    }
}

