class Solution {
    private static String answer;

    public static String smallestPalindromicPermutationGreater(String s, String target) {
        if (s.length() != target.length()) {
            return "";
        }
        int n = s.length();
        int half = n / 2;
        boolean odd = (n % 2 == 1);
        int[] cnt = new int[256];
        for (char ch : s.toCharArray()) {
            cnt[ch]++;
        }
        int oddCount = 0;
        for (int v : cnt) {
            if ((v & 1) == 1) oddCount++;
        }
        if (odd) {
            if (oddCount != 1) return "";
        } else {
            if (oddCount != 0) return "";
        }
        answer = null;
        if (dfs(0, false, new StringBuilder(), cnt, half, odd, target)) {
            return answer;
        }
        return "";
    }

    private static boolean dfs(int pos, boolean greater, StringBuilder left, int[] cnt, int half, boolean odd, String target) {
        if (greater) {
            answer = buildSmallest(cnt, left);
            return true;
        }
        if (pos == half) {
            if (odd) {
                int start = target.charAt(half) + 1;
                for (int c = start; c < 256; c++) {
                    if (cnt[c] > 0) {
                        cnt[c]--;
                        if (allEven(cnt)) {
                            StringBuilder sb = new StringBuilder();
                            sb.append(left);
                            sb.append((char) c);
                            sb.append(new StringBuilder(left).reverse());
                            answer = sb.toString();
                            cnt[c]++;
                            return true;
                        }
                        cnt[c]++;
                    }
                }
                return false;
            } else {
                StringBuilder sb = new StringBuilder();
                sb.append(left);
                sb.append(new StringBuilder(left).reverse());
                if (sb.toString().compareTo(target) > 0) {
                    answer = sb.toString();
                    return true;
                }
                return false;
            }
        }
        int start = target.charAt(pos);
        for (int c = start; c < 256; c++) {
            if (cnt[c] >= 2) {
                cnt[c] -= 2;
                left.append((char) c);
                boolean newGreater = greater || (c > target.charAt(pos));
                if (dfs(pos + 1, newGreater, left, cnt, half, odd, target)) {
                    return true;
                }
                left.setLength(left.length() - 1);
                cnt[c] += 2;
            }
        }
        return false;
    }

    private static boolean allEven(int[] cnt) {
        for (int v : cnt) {
            if ((v & 1) == 1) return false;
        }
        return true;
    }

    private static String buildSmallest(int[] cntOrig, StringBuilder left) {
        int[] cnt = cntOrig.clone();
        StringBuilder sb = new StringBuilder();
        sb.append(left);
        char middle = 0;
        for (int i = 0; i < 256; i++) {
            if ((cnt[i] & 1) == 1) {
                middle = (char) i;
                cnt[i]--;
                break;
            }
        }
        for (int i = 0; i < 256; i++) {
            while (cnt[i] >= 2) {
                sb.append((char) i);
                cnt[i] -= 2;
            }
        }
        String leftPart = sb.toString();
        StringBuilder result = new StringBuilder();
        result.append(leftPart);
        if (middle != 0) result.append(middle);
        result.append(new StringBuilder(leftPart).reverse());
        return result.toString();
    }
}

import java.util.*;

class Solution {
    public static long countSubarrays(int[] nums, int x) {
        int n = nums.length;
        int offset = n;
        int size = 2 * n + 3;
        long[] bit = new long[size];
        java.util.function.BiConsumer<Integer, Long> add = (i, delta) -> {
            int idx = i;
            while (idx < size) {
                bit[idx] += delta;
                idx += idx & -idx;
            }
        };
        java.util.function.Function<Integer, Long> sum = i -> {
            long res = 0;
            int idx = i;
            while (idx > 0) {
                res += bit[idx];
                idx -= idx & -idx;
            }
            return res;
        };
        int pref = 0;
        add.accept(pref + offset + 1, 1L);
        long ans = 0;
        for (int num : nums) {
            pref += (num == x) ? 1 : -1;
            int idx = pref + offset + 1;
            ans += sum.apply(idx - 1);
            add.accept(idx, 1L);
        }
        return ans;
    }
}

class Solution {
    static long gcd(long a, long b) { return b == 0 ? a : gcd(b, a % b); }
    public static long minTime(long[] d, long[] r) {
        long d1 = d[0], d2 = d[1], r1 = r[0], r2 = r[1];
        long lcm = r1 / gcd(r1, r2) * r2;
        long lo = 1, hi = 4000000000L;
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            long a1 = mid - mid/r1;
            long a2 = mid - mid/r2;
            long atotal = mid - mid/lcm;
            boolean ok = a1 >= d1 && a2 >= d2 && atotal >= d1 + d2;
            if (ok) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
}

class Solution {
    public static long countSubarrays(int[] nums, int target) {
        int n = nums.length;
        int offset = n + 1;
        int size = 2 * n + 3;
        long[] bit = new long[size];
        long pref = 0, ans = 0;
        add(bit, offset, size);
        for (int x : nums) {
            pref += (x == target) ? 1 : -1;
            int idx = (int) (pref + offset);
            ans += query(bit, idx - 1);
            add(bit, idx, size);
        }
        return ans;
    }
    private static void add(long[] bit, int i, int size) {
        for (; i < size; i += i & -i) bit[i]++;
    }
    private static long query(long[] bit, int i) {
        long s = 0;
        for (; i > 0; i -= i & -i) s += bit[i];
        return s;
    }
}

import java.util.*;
class Solution {
    static final long NEG = Long.MIN_VALUE / 4;
    static long linearBest(int[] a, int k) {
        long[][] f = new long[k + 1][3];
        for (long[] r : f) Arrays.fill(r, NEG);
        f[0][1] = 0;
        for (int x : a) {
            long[][] g = new long[k + 1][3];
            for (int i = 0; i <= k; i++) g[i] = f[i].clone();
            for (int c = 0; c <= k; c++) for (int bi = 0; bi < 3; bi++) {
                long cur = f[c][bi];
                if (cur == NEG) continue;
                int b = bi - 1;
                for (int sign : new int[]{1, -1}) {
                    int nb = b + sign;
                    if (nb < -1 || nb > 1) continue;
                    int nc = c + (nb == 0 ? 1 : 0);
                    if (nc > k) continue;
                    long val = cur + (long) sign * x;
                    if (val > g[nc][nb + 1]) g[nc][nb + 1] = val;
                }
            }
            f = g;
        }
        long best = NEG;
        for (int c = 0; c <= k; c++) best = Math.max(best, f[c][1]);
        return best;
    }
    public static long maxCyclicPartitionScore(int[] nums, int k) {
        int n = nums.length;
        long ans = NEG;
        for (int r = 0; r < n; r++) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = nums[(r + i) % n];
            ans = Math.max(ans, linearBest(a, k));
        }
        return ans;
    }
}

class Solution {
    public static int longestNonDecreasingAfterOneReplace(int[] arr) {
        int n = arr.length;
        if (n <= 2) return n;
        int[] left = new int[n];
        left[0] = 1;
        for (int i = 1; i < n; i++) {
            left[i] = arr[i] >= arr[i - 1] ? left[i - 1] + 1 : 1;
        }
        int best = 1;
        for (int len : left) {
            if (len > best) best = len;
        }
        int rightLenNext = 0;
        for (int i = n - 1; i >= 0; i--) {
            int rightLen = (i == n - 1) ? 1 : (arr[i] <= arr[i + 1] ? rightLenNext + 1 : 1);
            if (i > 0) {
                int cand = left[i - 1] + 1;
                if (cand > best) best = cand;
            }
            if (i < n - 1) {
                int cand = rightLenNext + 1;
                if (cand > best) best = cand;
            }
            if (i > 0 && i < n - 1 && arr[i - 1] <= arr[i + 1]) {
                int cand = left[i - 1] + 1 + rightLenNext;
                if (cand > best) best = cand;
            }
            rightLenNext = rightLen;
        }
        return best > n ? n : best;
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public static int minimumDistance(int[] nums) {
        Map<Integer, Deque<Integer>> map = new HashMap<>();
        int best = Integer.MAX_VALUE;
        for (int i = 0; i < nums.length; i++) {
            int val = nums[i];
            Deque<Integer> dq = map.computeIfAbsent(val, k -> new ArrayDeque<>(2));
            if (dq.size() == 2) {
                int span = i - dq.peekFirst();
                int dist = 2 * span;
                if (dist < best) {
                    best = dist;
                }
                dq.pollFirst();
            }
            dq.offerLast(i);
        }
        return best == Integer.MAX_VALUE ? -1 : best;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public static int minimumDistance(int[] nums) {
        Map<Integer, Integer> first = new HashMap<>();
        Map<Integer, Integer> second = new HashMap<>();
        int best = Integer.MAX_VALUE;
        for (int i = 0; i < nums.length; i++) {
            int v = nums[i];
            if (!first.containsKey(v)) {
                first.put(v, i);
            } else if (!second.containsKey(v)) {
                second.put(v, i);
            } else {
                int dist = 2 * (i - first.get(v));
                if (dist < best) best = dist;
                first.put(v, second.get(v));
                second.put(v, i);
            }
        }
        return best == Integer.MAX_VALUE ? -1 : best;
    }
}

class Solution {
    public static int maxPathScore(int[][] grid, int k) {
        int m = grid.length, n = grid[0].length;
        final int NEG = -1000000000;
        int[][][] f = new int[m][n][k+1];
        for (int[][] a : f) for (int[] b : a) java.util.Arrays.fill(b, NEG);
        f[0][0][0] = 0;
        for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) for (int c = 0; c <= k; c++) {
            if (i == 0 && j == 0) continue;
            int cost = grid[i][j] > 0 ? 1 : 0;
            if (c < cost) continue;
            int best = NEG;
            if (i > 0 && f[i-1][j][c-cost] > NEG) best = Math.max(best, f[i-1][j][c-cost]);
            if (j > 0 && f[i][j-1][c-cost] > NEG) best = Math.max(best, f[i][j-1][c-cost]);
            if (best > NEG) f[i][j][c] = best + grid[i][j];
        }
        int ans = NEG;
        for (int c = 0; c <= k; c++) ans = Math.max(ans, f[m-1][n-1][c]);
        return ans <= NEG ? -1 : ans;
    }
}

class Solution {
    public static int minLengthAfterBalancedRemovals(String s) {
        int countA = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == 'a') countA++;
        }
        int countB = s.length() - countA;
        return Math.abs(countA - countB);
    }
}

