class Solution {
    public static long[] countStableSubarrays(int[] nums, int[][] queries) {
        int n = nums.length;
        int[] f = new int[n];
        Arrays.fill(f, 1);
        for (int i = 1; i < n; i++) f[i] = nums[i] >= nums[i-1] ? f[i-1] + 1 : 1;
        long[] out = new long[queries.length];
        for (int k = 0; k < queries.length; k++) {
