class Solution {
    public static long maxExpression(int[] nums) {
        int n = nums.length;
        long[] suf = new long[n];
        suf[n - 1] = nums[n - 1];
        for (int i = n - 2; i >= 0; i--) suf[i] = Math.max(suf[i + 1], nums[i]);
        long pre = nums[0], best = Long.MIN_VALUE;
        for (int j = 1; j < n - 1; j++) {
            best = Math.max(best, pre - nums[j] + suf[j + 1]);
            pre = Math.max(pre, nums[j]);
        }
        return best;
    }
}

