class Solution {
    public static int maxBalancedXorLength(int[] nums) {
        Map<Long, Integer> firstPos = new HashMap<>();
        firstPos.put(encode(0, 0), -1);
        int xorVal = 0, delta = 0, maxLen = 0;
        for (int i = 0; i < nums.length; i++) {
            xorVal ^= nums[i];
            delta += (nums[i] % 2 == 0) ? 1 : -1;
            long key = encode(xorVal, delta);
            Integer prev = firstPos.get(key);
            if (prev != null) {
                int len = i - prev;
                if (len > maxLen) maxLen = len;
            } else {
                firstPos.put(key, i);
            }
        }
        return maxLen;
    }
    private static long encode(int xorv, int delta) {
        return ((long) xorv << 32) | (delta & 0xFFFFFFFFL);
    }
}

