public class Solution {
    public static int[] lexSmallestNegatedPerm(int n, long target) {
        long totalAll = (long) n * (n + 1) / 2;
        if (Math.abs(target) > totalAll || ((totalAll - target) & 1L) != 0L) {
            return new int[0];
        }
        long needNegSum = (totalAll - target) / 2;
        boolean[] isNeg = new boolean[n + 1];
        for (int i = n; i >= 1; i--) {
            if (needNegSum >= i) {
                isNeg[i] = true;
                needNegSum -= i;
            }
        }
        int[] res = new int[n];
        int idx = 0;
        for (int i = n; i >= 1; i--) {
            if (isNeg[i]) {
                res[idx++] = -i;
            }
        }
        for (int i = 1; i <= n; i++) {
            if (!isNeg[i]) {
                res[idx++] = i;
            }
        }
        return res;
    }
}

