class Solution {
    public static long concatenateNonZeroMultiplySum(long N) {
        String s = Long.toString(N);
        long sum = 0;
        BigInteger nonZero = BigInteger.ZERO;
        for (int i = 0; i < s.length(); i++) {
            int d = s.charAt(i) - '0';
            sum += d;
            if (d != 0) {
                nonZero = nonZero.multiply(BigInteger.TEN).add(BigInteger.valueOf(d));
            }
        }
        return nonZero.multiply(BigInteger.valueOf(sum)).longValue();
    }
}

