class Solution {
    static final long MOD = 1000000007L;

    public int numberOfEffectiveSubsequences(int[] nums) {
        int n = nums.length;
        int maxVal = 0;
        for (int v : nums) maxVal = Math.max(maxVal, v);
        int B = 1;
        while ((1 << B) <= maxVal) B++;
        int size = 1 << B;
        int fullmask = size - 1;

        long[] subsetSum = new long[size];
        for (int v : nums) subsetSum[v]++;
        for (int bit = 0; bit < B; bit++) {
            for (int mask = 0; mask < size; mask++) {
                if ((mask & (1 << bit)) != 0) {
                    subsetSum[mask] += subsetSum[mask ^ (1 << bit)];
                }
            }
        }

        int activeBits = 0;
        for (int v : nums) activeBits |= v;

        long[] pow2 = new long[n + 1];
        pow2[0] = 1;
        for (int i = 1; i <= n; i++) pow2[i] = (pow2[i-1] * 2) % MOD;

        long answer = 0;
        int submask = activeBits;
        while (submask > 0) {
            int bitsSet = Integer.bitCount(submask);
            long elementsWithNone = subsetSum[fullmask ^ submask];
            long forced = n - elementsWithNone;
            long ways = pow2[(int)(n - forced)];
            if (bitsSet % 2 == 1) {
                answer = (answer + ways) % MOD;
            } else {
                answer = (answer - ways + MOD) % MOD;
            }
            submask = (submask - 1) & activeBits;
        }
        return (int)(answer % MOD);
    }
}

import java.util.Random;

class Solution {
    public static int countElements(int[] nums, int k) {
        int n = nums.length;
        if (k == 0) return n;
        if (k >= n) return 0;
        int[] copy = nums.clone();
        int targetIdx = n - k;
        int threshold = quickSelect(copy, 0, n - 1, targetIdx);
        int count = 0;
        for (int v : nums) {
            if (v < threshold) count++;
        }
        return count;
    }

    private static int quickSelect(int[] arr, int left, int right, int kIdx) {
        Random rand = new Random();
        while (true) {
            if (left == right) return arr[left];
            int pivotIdx = left + rand.nextInt(right - left + 1);
            int pivotVal = arr[pivotIdx];
            swap(arr, pivotIdx, right);
            int storeIdx = left;
            for (int i = left; i < right; i++) {
                if (arr[i] <= pivotVal) {
                    swap(arr, storeIdx, i);
                    storeIdx++;
                }
            }
            swap(arr, storeIdx, right);
            if (kIdx == storeIdx) {
                return arr[storeIdx];
            } else if (kIdx < storeIdx) {
                right = storeIdx - 1;
            } else {
                left = storeIdx + 1;
            }
        }
    }

    private static void swap(int[] arr, int i, int j) {
        int tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }
}

