class Solution {
    public static int minMirrorDistance(int[] arr) {
        if (arr == null || arr.length < 2) return -1;
        Map<Integer, Integer> revMap = new HashMap<>();
        int minDist = Integer.MAX_VALUE;
        for (int j = 0; j < arr.length; j++) {
            Integer i = revMap.get(arr[j]);
            if (i != null) {
                int dist = j - i;
                if (dist < minDist) minDist = dist;
            }
            revMap.put(reverse(arr[j]), j);
        }
        return minDist == Integer.MAX_VALUE ? -1 : minDist;
    }

    private static int reverse(int num) {
        boolean negative = num < 0;
        int n = Math.abs(num);
        int rev = 0;
        while (n > 0) {
            rev = rev * 10 + (n % 10);
            n /= 10;
        }
        return negative ? -rev : rev;
    }
}

class Solution {
    static final long MOD = 1000000007L;
    public static long[] sumAndMultiply(String s, int[][] queries) {
        int n = s.length();
        long[] presum = new long[n+1], conval = new long[n+1], pow10 = new long[n+1];
        int[] cnt = new int[n+1];
        pow10[0]=1;
        for (int i=1;i<=n;i++){
            int d = s.charAt(i-1)-'0';
            presum[i] = presum[i-1]+d;
            if (d==0){ conval[i]=conval[i-1]; cnt[i]=cnt[i-1]; }
            else { conval[i]=(conval[i-1]*10+d)%MOD; cnt[i]=cnt[i-1]+1; }
            pow10[i]=(pow10[i-1]*10)%MOD;
        }
        long[] ans = new long[queries.length];
        for (int qi=0;qi<queries.length;qi++){
            int l=queries[qi][0], r=queries[qi][1];
            long sum = presum[r+1]-presum[l];
            int k = cnt[r+1]-cnt[l];
            long removed = (conval[l]*pow10[k])%MOD;
            long x = ((conval[r+1]-removed)%MOD+MOD)%MOD;
            ans[qi] = (x*sum)%MOD;
        }
        return ans;
    }
}

