class Solution {
    public static long[] minimumOperations(int[] nums, int k, int[][] queries) {
        long[] results = new long[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            int l = queries[qi][0], r = queries[qi][1];
            int[] sub = Arrays.copyOfRange(nums, l, r + 1);
            int rem = ((sub[0] % k) + k) % k;
            boolean feasible = true;
            for (int v : sub) {
                if (((v % k) + k) % k != rem) { feasible = false; break; }
            }
            if (!feasible) { results[qi] = -1; continue; }
            int[] sorted = sub.clone();
            Arrays.sort(sorted);
            int target = sorted[sorted.length / 2];
            long ops = 0;
            for (int v : sub) ops += Math.abs(v - target);
            results[qi] = ops / k;
        }
        return results;
    }
}

