class Solution {
    private static void add(int[] bit, int size, int idx, int delta) {
        while (idx <= size) {
            bit[idx] += delta;
            idx += idx & -idx;
        }
    }

    private static int sum(int[] bit, int idx) {
        int res = 0;
        while (idx > 0) {
            res += bit[idx];
            idx -= idx & -idx;
        }
        return res;
    }

    public static long minInversionCount(int[] arr, int k) {
        int n = arr.length;
        if (k <= 0 || k > n) return 0L;

        Set<Integer> set = new HashSet<>();
        for (int v : arr) set.add(v);
        int[] sorted = new int[set.size()];
        int p = 0;
        for (int v : set) sorted[p++] = v;
        Arrays.sort(sorted);
        Map<Integer, Integer> comp = new HashMap<>(sorted.length * 2);
        for (int i = 0; i < sorted.length; i++) comp.put(sorted[i], i + 1);

        int size = sorted.length;
        int[] bit = new int[size + 1];

        long inv = 0;
        for (int i = 0; i < k; i++) {
            int idx = comp.get(arr[i]);
            inv += i - sum(bit, idx);
            add(bit, size, idx, 1);
        }

        long best = inv;

        for (int left = 0, right = k; right < n; left++, right++) {
            int outIdx = comp.get(arr[left]);
            int lessThanOut = sum(bit, outIdx - 1);
            inv -= lessThanOut;
            add(bit, size, outIdx, -1);

            int inIdx = comp.get(arr[right]);
            int greaterThanIn = (k - 1) - sum(bit, inIdx);
            inv += greaterThanIn;
            add(bit, size, inIdx, 1);

            if (inv < best) best = inv;
        }

        return best;
    }
}

