public class Solution {
    public static int[] sortByBinaryReflection(int[] arr) {
        int n = arr.length;
        long[] keys = new long[n];
        for (int i = 0; i < n; i++) {
            int num = arr[i];
            int reflected = reverseBits(num);
            keys[i] = ((long) reflected << 32) | (num & 0xffffffffL);
        }
        Arrays.sort(keys);
        int[] result = new int[n];
        for (int i = 0; i < n; i++) {
            result[i] = (int) keys[i];
        }
        return result;
    }
    private static int reverseBits(int x) {
        int rev = 0;
        while (x != 0) {
            rev = (rev << 1) | (x & 1);
            x >>>= 1;
        }
        return rev;
    }
}

