class Solution {
    public static long[] maxSubgraphScore(int n, int[][] edges, int[] good) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        int[] value = new int[n];
        for (int i = 0; i < n; i++) value[i] = good[i] == 1 ? 1 : -1;
        int[] parent = new int[n]; Arrays.fill(parent, -1);
        List<Integer> order = new ArrayList<>();
        boolean[] visited = new boolean[n];
        Deque<Integer> stack = new ArrayDeque<>(); stack.push(0); visited[0] = true;
        while (!stack.isEmpty()) {
            int u = stack.pop(); order.add(u);
            for (int v : adj.get(u)) if (!visited[v]) { visited[v] = true; parent[v] = u; stack.push(v); }
        }
        List<List<Integer>> children = new ArrayList<>();
        for (int i = 0; i < n; i++) children.add(new ArrayList<>());
        for (int v = 0; v < n; v++) if (parent[v] != -1) children.get(parent[v]).add(v);
        int[] depth = new int[n];
        for (int u : order) if (parent[u] != -1) depth[u] = depth[parent[u]] + 1;
        long[] down = new long[n];
        List<Integer> byDepthDesc = new ArrayList<>(order);
        byDepthDesc.sort((a, b) -> depth[b] - depth[a]);
        for (int u : byDepthDesc) {
            long s = value[u];
            for (int c : children.get(u)) s += Math.max(0L, down[c]);
            down[u] = s;
        }
        long[] totalChildContrib = new long[n];
        for (int u = 0; u < n; u++) totalChildContrib[u] = down[u] - value[u];
        long[] up = new long[n];
        List<Integer> byDepthAsc = new ArrayList<>(order);
        byDepthAsc.sort((a, b) -> depth[a] - depth[b]);
        for (int u : byDepthAsc) {
            for (int c : children.get(u)) {
                long siblingSum = totalChildContrib[u] - Math.max(0L, down[c]);
                up[c] = value[u] + Math.max(0L, up[u]) + siblingSum;
            }
        }
        long[] answer = new long[n];
        for (int i = 0; i < n; i++) answer[i] = down[i] + Math.max(0L, up[i]);
        return answer;
    }
}

