class Solution {
    public int largestPrime(int n) {
        if (n < 2) return 0;
        boolean[] isPrime = new boolean[n + 1];
        Arrays.fill(isPrime, true);
        isPrime[0] = false;
        isPrime[1] = false;
        for (int i = 2; (long) i * i <= n; i++) {
            if (isPrime[i]) {
                for (int j = i * i; j <= n; j += i) isPrime[j] = false;
            }
        }
        int best = 0;
        long total = 0;
        for (int p = 2; p <= n; p++) {
            if (isPrime[p]) {
                total += p;
                if (total > n) break;
                if (total <= n && isPrime[(int) total]) best = (int) total;
            }
        }
        return best;
    }
}

