class Solution {
    public int minSwaps(int[] nums, int[] forbidden) {
        int n = nums.length;
        Map<Integer, Integer> cntNums = new HashMap<>();
        Map<Integer, Integer> cntForb = new HashMap<>();
        for (int v : nums) cntNums.merge(v, 1, Integer::sum);
        for (int v : forbidden) cntForb.merge(v, 1, Integer::sum);
        Set<Integer> allVals = new HashSet<>(cntNums.keySet());
        allVals.addAll(cntForb.keySet());
        for (int v : allVals) {
            int cn = cntNums.getOrDefault(v, 0);
            int cf = cntForb.getOrDefault(v, 0);
            if (cn > n - cf) return -1;
        }
        Map<Integer, Integer> bad = new HashMap<>();
        int s = 0;
        for (int i = 0; i < n; i++) {
            if (nums[i] == forbidden[i]) {
                bad.merge(nums[i], 1, Integer::sum);
                s++;
            }
        }
        if (s == 0) return 0;
        int m = 0;
        for (int v : bad.values()) m = Math.max(m, v);
        return Math.max((s + 1) / 2, m);
    }
}

