import java.util.*;
class Solution {
    public int lastRemaining(int n) {
        List<Integer> arr = new ArrayList<>();
        for (int i = 1; i <= n; i++) arr.add(i);
        boolean left = true;
        while (arr.size() > 1) {
            List<Integer> next_;
            if (left) {
                // keep 1-indexed odd positions (0-indexed even)
                next_ = new ArrayList<>();
                for (int i = 0; i < arr.size(); i += 2) next_.add(arr.get(i));
            } else {
                // "delete every second from the right" = reverse, do the same left-style keep, reverse back
                List<Integer> rev = new ArrayList<>(arr);
                Collections.reverse(rev);
                List<Integer> kept = new ArrayList<>();
                for (int i = 0; i < rev.size(); i += 2) kept.add(rev.get(i));
                Collections.reverse(kept);
                next_ = kept;
            }
            arr = next_;
            left = !left;
        }
        return arr.get(0);
    }
}

