class Solution {
    public static int maxSumDivisibleByThree(int[] nums) {
        int[] top0 = {Integer.MIN_VALUE, Integer.MIN_VALUE, Integer.MIN_VALUE};
        int[] top1 = {Integer.MIN_VALUE, Integer.MIN_VALUE, Integer.MIN_VALUE};
        int[] top2 = {Integer.MIN_VALUE, Integer.MIN_VALUE, Integer.MIN_VALUE};
        for (int v : nums) {
            int mod = ((v % 3) + 3) % 3;
            if (mod == 0) {
                insert(top0, v);
            } else if (mod == 1) {
                insert(top1, v);
            } else {
                insert(top2, v);
            }
        }
        int max = 0;
        boolean found = false;
        if (top0[2] != Integer.MIN_VALUE) {
            max = top0[0] + top0[1] + top0[2];
            found = true;
        }
        if (top1[2] != Integer.MIN_VALUE) {
            int sum = top1[0] + top1[1] + top1[2];
            if (!found || sum > max) {
                max = sum;
                found = true;
            }
        }
        if (top2[2] != Integer.MIN_VALUE) {
            int sum = top2[0] + top2[1] + top2[2];
            if (!found || sum > max) {
                max = sum;
                found = true;
            }
        }
        if (top0[0] != Integer.MIN_VALUE && top1[0] != Integer.MIN_VALUE && top2[0] != Integer.MIN_VALUE) {
            int sum = top0[0] + top1[0] + top2[0];
            if (!found || sum > max) {
                max = sum;
                found = true;
            }
        }
        return found ? max : 0;
    }

    private static void insert(int[] top, int val) {
        if (val <= top[2]) return;
        if (val > top[0]) {
            top[2] = top[1];
            top[1] = top[0];
            top[0] = val;
        } else if (val > top[1]) {
            top[2] = top[1];
            top[1] = val;
        } else {
            top[2] = val;
        }
    }
}

