class Solution {
    public static long totalInteractionCost(int n, int[][] edges, int[] group) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        final int maxG = 21;
        long[] totalFreq = new long[maxG];
        for (int g : group) totalFreq[g]++;
        long total = 0;
        int[] parent = new int[n]; Arrays.fill(parent, -1);
        List<Integer> order = new ArrayList<>();
        boolean[] visited = new boolean[n];
        Deque<Integer> stack = new ArrayDeque<>(); stack.push(0); visited[0] = true;
        while (!stack.isEmpty()) {
            int u = stack.pop(); order.add(u);
            for (int v : adj.get(u)) if (!visited[v]) { visited[v] = true; parent[v] = u; stack.push(v); }
        }
        long[][] subFreq = new long[n][maxG];
        for (int i = order.size() - 1; i >= 0; i--) {
            int u = order.get(i);
            subFreq[u][group[u]]++;
            for (int v : adj.get(u)) {
                if (v == parent[u]) continue;
                for (int g = 0; g < maxG; g++) {
                    long cnt = subFreq[v][g];
                    if (cnt > 0) total += cnt * (totalFreq[g] - cnt);
                    subFreq[u][g] += cnt;
                }
            }
        }
        return total;
    }
}

import java.util.*;
class Solution {
    Map<String, Long> memo;
    int[] digits;
    int length;

    long dfsCount(int pos, int diff, boolean tight) {
        if (pos == length) return diff == 0 ? 1 : 0;
        String key = pos + "," + diff + "," + tight;
        if (memo.containsKey(key)) return memo.get(key);
        int lo = pos > 0 ? 0 : 1;
        int hi = tight ? digits[pos] : 9;
        long total = 0;
        for (int d = lo; d <= hi; d++) {
            int sign = (pos % 2 == 0) ? 1 : -1;
            total += dfsCount(pos + 1, diff + sign * d, tight && d == hi);
        }
        memo.put(key, total);
        return total;
    }

    long countLeLength(long x, int len) {
        long lowBound = 1;
        for (int i = 0; i < len - 1; i++) lowBound *= 10;
        if (x < lowBound) return 0;
        long highBound = lowBound * 10 - 1;
        x = Math.min(x, highBound);
        String s = Long.toString(x);
        if (s.length() != len) return 0;
        digits = new int[len];
        for (int i = 0; i < len; i++) digits[i] = s.charAt(i) - '0';
        length = len;
        memo = new HashMap<>();
        return dfsCount(0, 0, true);
    }

    long countUpto(long n) {
        if (n < 10) return 0;
        String s = Long.toString(n);
        long total = 0;
        for (int len = 2; len <= s.length(); len++) {
            total += countLeLength(n, len);
        }
        return total;
    }

    public long numberOfBalancedIntegers(long low, long high) {
        return countUpto(high) - countUpto(low - 1);
    }
}

class Solution {
    public long maximumScore(int[] nums) {
        int n = nums.length;
        long[] sufMin = new long[n];
        sufMin[n - 1] = nums[n - 1];
        for (int i = n - 2; i >= 0; i--) sufMin[i] = Math.min(nums[i], sufMin[i + 1]);
        long best = Long.MIN_VALUE;
        long prefix = 0;
        for (int i = 0; i < n - 1; i++) {
            prefix += nums[i];
            best = Math.max(best, prefix - sufMin[i + 1]);
        }
        return best;
    }
}

import java.util.*;

class Solution {
    public static long numberOfRoutes(String[] grid, int d) {
        final long MOD = 1000000007L;
        int n = grid.length, m = grid[0].length();
        long wUpSq = (long) d * d - 1;
        long wUp = -1;
        if (wUpSq >= 0) {
            wUp = (long) Math.sqrt((double) wUpSq);
            while (wUp >= 0 && wUp * wUp > wUpSq) wUp--;
            while ((wUp + 1) * (wUp + 1) <= wUpSq) wUp++;
        }
        long wStay = d;

        long[] dpUp = new long[m];
        long[] dpStay = new long[m];
        for (int c = 0; c < m; c++) if (grid[n-1].charAt(c) == '.') dpUp[c] = 1;

        for (int r = n - 1; r > 0; r--) {
            long[] preUp = new long[m + 1];
            for (int c = 0; c < m; c++) preUp[c+1] = (preUp[c] + dpUp[c]) % MOD;
            long[] newStay = new long[m];
            for (int c = 0; c < m; c++) {
                if (grid[r].charAt(c) != '.') continue;
                int lo = Math.max(0, (int)(c - wStay)), hi = Math.min(m - 1, (int)(c + wStay));
                long total = (preUp[hi+1] - preUp[lo] + MOD) % MOD;
                total = (total - dpUp[c] + MOD) % MOD;
                newStay[c] = total;
            }
            dpStay = newStay;

            long[] combined = new long[m];
            for (int c = 0; c < m; c++) combined[c] = (dpUp[c] + dpStay[c]) % MOD;
            long[] preComb = new long[m + 1];
            for (int c = 0; c < m; c++) preComb[c+1] = (preComb[c] + combined[c]) % MOD;

            long[] newUp = new long[m];
            for (int c = 0; c < m; c++) {
                if (grid[r-1].charAt(c) != '.' || wUp < 0) continue;
                int lo = Math.max(0, (int)(c - wUp)), hi = Math.min(m - 1, (int)(c + wUp));
                newUp[c] = (preComb[hi+1] - preComb[lo] + MOD) % MOD;
            }
            dpUp = newUp;
            dpStay = new long[m];
        }

        long[] preUp0 = new long[m + 1];
        for (int c = 0; c < m; c++) preUp0[c+1] = (preUp0[c] + dpUp[c]) % MOD;
        long[] dpStay0 = new long[m];
        for (int c = 0; c < m; c++) {
            if (grid[0].charAt(c) != '.') continue;
            int lo = Math.max(0, (int)(c - wStay)), hi = Math.min(m - 1, (int)(c + wStay));
            long total = (preUp0[hi+1] - preUp0[lo] + MOD) % MOD;
            dpStay0[c] = (total - dpUp[c] + MOD) % MOD;
        }

        long ans = 0;
        for (int c = 0; c < m; c++) ans = (ans + dpUp[c] + dpStay0[c]) % MOD;
        return ans;
    }
}

