class Solution {
    public static long maxValueOfSequence(int n, int[][] restrictions, int[] diff) {
        long INF = Long.MAX_VALUE/2;
        long[] a = new long[n]; Arrays.fill(a, INF);
        a[0] = 0;
        for (int[] r : restrictions) a[r[0]] = Math.min(a[r[0]], (long) r[1]);
        for (int i = 1; i < n; i++) a[i] = Math.min(a[i], a[i-1] + diff[i-1]);
        for (int i = n-2; i >= 0; i--) a[i] = Math.min(a[i], a[i+1] + diff[i]);
        long mx = Long.MIN_VALUE;
        for (long x : a) mx = Math.max(mx, x);
        return mx;
    }
}

import java.util.*;
class Solution {
    public int minCost(List<List<Integer>> lists) {
        int n = lists.size();
        int full = 1 << n;
        List<Integer>[] sortedArr = new List[full];
        sortedArr[0] = new ArrayList<>();
        for (int mask = 1; mask < full; mask++) {
            int low = mask & (-mask);
            int idx = Integer.numberOfTrailingZeros(low);
            List<Integer> a = sortedArr[mask ^ low];
            List<Integer> b = lists.get(idx);
            List<Integer> merged = new ArrayList<>();
            int i = 0, j = 0;
            while (i < a.size() && j < b.size()) {
                if (a.get(i) <= b.get(j)) merged.add(a.get(i++));
                else merged.add(b.get(j++));
            }
            while (i < a.size()) merged.add(a.get(i++));
            while (j < b.size()) merged.add(b.get(j++));
            sortedArr[mask] = merged;
        }
        long INF = Long.MAX_VALUE / 2;
        long[] dp = new long[full];
        for (int mask = 1; mask < full; mask++) {
            if ((mask & (mask - 1)) == 0) { dp[mask] = 0; continue; }
            long best = INF;
            for (int sub = (mask - 1) & mask; sub > 0; sub = (sub - 1) & mask) {
                int comp = mask ^ sub;
                if (comp == 0) continue;
                List<Integer> A = sortedArr[sub], B = sortedArr[comp];
                int medA = A.get((A.size() - 1) / 2);
                int medB = B.get((B.size() - 1) / 2);
                long cost = dp[sub] + dp[comp] + A.size() + B.size() + Math.abs(medA - medB);
                if (cost < best) best = cost;
            }
            dp[mask] = best;
        }
        return (int) dp[full - 1];
    }
}

class Solution {
    public static long minimumCost(String s, String t, long flipCost, long swapCost, long crossCost) {
        long diff0 = 0, diff1 = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) != t.charAt(i)) { if (s.charAt(i) == '0') diff0++; else diff1++; }
        }
        long mx = Math.max(diff0, diff1), mn = Math.min(diff0, diff1);
        long ans = (diff0 + diff1) * flipCost;
        ans = Math.min(ans, mn * swapCost + (mx - mn) * flipCost);
        long avg = (mx + mn) / 2;
        ans = Math.min(ans, (avg - mn) * crossCost + avg * swapCost + (mx + mn - avg * 2) * flipCost);
        return ans;
    }
}

