class Solution {
    // s only contains '1' and '2'; a subsequence is even iff it ends in '2'. To maximize
    // value, keep the longest possible prefix ending in a '2' - i.e. truncate right after
    // the last '2' in s (everything after the last '2' can only be '1's, so this is
