class Solution {
    public static long countCaesarCipherPairs(String[] words) {
        Map<Long, Integer> freq = new HashMap<>();
        long totalPairs = 0;
        for (String w : words) {
            int base = w.charAt(0);
            long hash = w.length();
            for (int i = 0; i < w.length(); i++) {
                int diff = (w.charAt(i) - base + 26) % 26;
                hash = hash * 31 + diff;
            }
            int prev = freq.getOrDefault(hash, 0);
            totalPairs += prev;
            freq.put(hash, prev + 1);
        }
        return totalPairs;
    }
}

