class Solution {
    public static long alternatingXOR(int[] nums, int target1, int target2) {
        final long MOD = 1_000_000_007L;
        Map<Integer, Long> cnt1 = new HashMap<>();
        Map<Integer, Long> cnt2 = new HashMap<>();
        cnt2.put(0, 1L);
        int pre = 0;
        long ans = 0;
        for (int x : nums) {
            pre ^= x;
            long a = cnt2.getOrDefault(pre ^ target1, 0L);
            long b = cnt1.getOrDefault(pre ^ target2, 0L);
            ans = (a + b) % MOD;
            cnt1.put(pre, (cnt1.getOrDefault(pre, 0L) + a) % MOD);
            cnt2.put(pre, (cnt2.getOrDefault(pre, 0L) + b) % MOD);
        }
        return ans;
    }
}

