class Solution {
    public static List<Integer> minimumEdgeToggles(int n, int[][] edges, String start, String target) {
        List<int[]>[] adj = new List[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int idx = 0; idx < edges.length; idx++) {
            int u = edges[idx][0], v = edges[idx][1];
            adj[u].add(new int[]{v, idx});
            adj[v].add(new int[]{u, idx});
        }

        int[] d = new int[n];
        for (int i = 0; i < n; i++) d[i] = (start.charAt(i) == target.charAt(i)) ? 0 : 1;

        int[] parent = new int[n];
        int[] edgeToParent = new int[n];
        Arrays.fill(parent, -1);
        Arrays.fill(edgeToParent, -1);
        int[] order = new int[n];
        int oi = 0;
        boolean[] visited = new boolean[n];
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(0);
        visited[0] = true;
        while (!stack.isEmpty()) {
            int u = stack.pop();
            order[oi++] = u;
            for (int[] e : adj[u]) {
                int v = e[0], idx = e[1];
                if (!visited[v]) {
                    visited[v] = true;
                    parent[v] = u;
                    edgeToParent[v] = idx;
                    stack.push(v);
                }
            }
        }

        int[] need = new int[n];
        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            int parity = 0;
            for (int[] e : adj[u]) {
                if (e[0] != parent[u]) parity ^= need[e[0]];
            }
            need[u] = d[u] ^ parity;
        }

        if (need[0] != 0) return List.of(-1);

        List<Integer> result = new ArrayList<>();
        for (int u = 1; u < n; u++) {
            if (need[u] == 1) result.add(edgeToParent[u]);
        }
        Collections.sort(result);
        return result;
    }
}

import java.util.*;
class Solution {
    public static long maxCapacity(int[] costs, int[] capacity, int budget) {
        int n = costs.length;
        List<int[]> arr = new ArrayList<>();
        for (int i = 0; i < n; i++) if (costs[i] < budget) arr.add(new int[]{costs[i], capacity[i]});
        if (arr.isEmpty()) return 0;
        arr.sort((a, b) -> a[0] - b[0]);
        int m = arr.size();
        long ans = 0;
        for (int[] p : arr) ans = Math.max(ans, (long) p[1]);
        int LOG = Math.max(1, (int) Math.ceil(Math.log(m + 1) / Math.log(2)));
        int[][] sparse = new int[LOG][m];
        for (int i = 0; i < m; i++) sparse[0][i] = arr.get(i)[1];
        for (int j = 1; (1 << j) <= m; j++) {
            int half = 1 << (j - 1);
            for (int i = 0; i + (1 << j) <= m; i++) sparse[j][i] = Math.max(sparse[j-1][i], sparse[j-1][i+half]);
        }
        int hi = m - 1;
        for (int i = 0; i < m; i++) {
            if (hi < i) hi = i;
            while (hi > i && arr.get(i)[0] + arr.get(hi)[0] >= budget) hi--;
            if (hi > i) {
                int l = i + 1, r = hi;
                int length = r - l + 1;
                int k = (int) (Math.log(length) / Math.log(2));
                long bp = Math.max(sparse[k][l], sparse[k][r - (1 << k) + 1]);
                ans = Math.max(ans, (long) arr.get(i)[1] + bp);
            }
        }
        return ans;
    }
}

