class Solution {
    public static int[] rotateNonNegative(int[] nums, int k) {
        java.util.List<Integer> idxs = new java.util.ArrayList<>();
        java.util.List<Integer> vals = new java.util.ArrayList<>();
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] >= 0) { idxs.add(i); vals.add(nums[i]); }
        }
        int m = vals.size();
        if (m == 0) return nums;
        int shift = ((k % m) + m) % m;
        int[] rotated = new int[m];
        for (int i = 0; i < m; i++) rotated[i] = vals.get((i + shift) % m);
        for (int i = 0; i < idxs.size(); i++) nums[idxs.get(i)] = rotated[i];
        return nums;
    }
}

class Solution {
    public static String removeDuplicateLetters(String s) {
        int[] cnt = new int[26];
        for (int i = 0; i < s.length(); i++) cnt[s.charAt(i)-'a']++;
        StringBuilder stk = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            while (stk.length() > 0 && stk.charAt(stk.length()-1) > c && cnt[stk.charAt(stk.length()-1)-'a'] > 1) {
                cnt[stk.charAt(stk.length()-1)-'a']--;
                stk.setLength(stk.length()-1);
            }
            stk.append(c);
        }
        while (cnt[stk.charAt(stk.length()-1)-'a'] > 1) {
            cnt[stk.charAt(stk.length()-1)-'a']--;
            stk.setLength(stk.length()-1);
        }
        return stk.toString();
    }
}

