        Map<Integer, Integer> bids = items.get(itemId);
        if (bids == null || bids.isEmpty()) return -1;
        int bestUser = -1, bestAmt = -1;
        for (Map.Entry<Integer, Integer> e : bids.entrySet()) {
            int uid = e.getKey(), amt = e.getValue();
            if (amt > bestAmt || (amt == bestAmt && uid > bestUser)) {
                bestAmt = amt;
                bestUser = uid;
            }
        }
        return bestUser;
    }
}

