public class LongestSubseqNonZeroAnd {
    static int longestSubseqAndOptimal(int[] nums) {
        final int BITS = 20;
        int best = 0;
        for (int b = 0; b < BITS; b++) {
            List<Integer> filtered = new ArrayList<>();
            for (int v : nums) if (((v >> b) & 1) != 0) filtered.add(v);
            if (filtered.isEmpty()) continue;
            List<Integer> tails = new ArrayList<>();
            for (int v : filtered) {
                int lo = 0, hi = tails.size();
                while (lo < hi) { int mid = (lo+hi)/2; if (tails.get(mid) < v) lo = mid+1; else hi = mid; }
                if (lo == tails.size()) tails.add(v); else tails.set(lo, v);
            }
            best = Math.max(best, tails.size());
        }
        return best;
    }
    static int longestSubseqAndAlgo(int[] nums) {
        int n = nums.length, best = 0;
        for (int mask = 1; mask < (1<<n); mask++) {
            List<Integer> sub = new ArrayList<>();
            for (int i=0;i<n;i++) if ((mask&(1<<i))!=0) sub.add(nums[i]);
            boolean inc = true;
            for (int i=1;i<sub.size();i++) if (sub.get(i)<=sub.get(i-1)) { inc=false; break; }
            if (!inc) continue;
            int andVal = sub.get(0);
            for (int i=1;i<sub.size();i++) andVal &= sub.get(i);
            if (andVal != 0) best = Math.max(best, sub.size());
        }
        return best;
    }
}

class Solution {
    static final int MX = 51;
    static long[][] C = new long[MX][MX + 1];
    static {
        for (int i = 0; i < MX; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
        }
    }
    // Build answer bit by bit from position 49 down to 0. For bit i, C[i][k] counts
    // how many valid numbers have bit i = 0 (remaining k ones chosen from lower i bits).
    // If n exceeds that count, bit i must be 1 in the answer; consume that block from n.
    public long nthSmallest(long n, int k) {
        long ans = 0;
        for (int i = 49; i >= 0 && k > 0; i--) {
            long cnt = (i >= k) ? C[i][k] : 0;
            if (n > cnt) {
                n -= cnt;
                ans |= (1L << i);
                k--;
            }
        }
        return ans;
    }
}

class Solution {
    public static String reverseLettersThenSpecials(String s) {
        char[] chars = s.toCharArray();
        int left = 0, right = chars.length - 1;
        while (left < right) {
            while (left < right && !isLetter(chars[left])) left++;
            while (left < right && !isLetter(chars[right])) right--;
            if (left < right) {
                char tmp = chars[left];
                chars[left] = chars[right];
                chars[right] = tmp;
                left++;
                right--;
            }
        }
        left = 0;
        right = chars.length - 1;
        while (left < right) {
            while (left < right && isLetter(chars[left])) left++;
            while (left < right && isLetter(chars[right])) right--;
            if (left < right) {
                char tmp = chars[left];
                chars[left] = chars[right];
                chars[right] = tmp;
                left++;
                right--;
            }
        }
        return new String(chars);
    }

    private static boolean isLetter(char c) {
        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
    }
}

