class RideSharingSystem {
    private final Deque<Integer> riders = new ArrayDeque<>();
    private final Deque<Integer> drivers = new ArrayDeque<>();
    private final Set<Integer> cancelled = new HashSet<>();

    public void addRider(int riderId) { riders.addLast(riderId); }
    public void addDriver(int driverId) { drivers.addLast(driverId); }
    public int[] matchDriverWithRider() {
        while (!riders.isEmpty() && cancelled.contains(riders.peekFirst())) {
            cancelled.remove(riders.pollFirst());
        }
        if (riders.isEmpty() || drivers.isEmpty()) return new int[]{-1, -1};
        int riderId = riders.pollFirst();
        int driverId = drivers.pollFirst();
        return new int[]{driverId, riderId};
    }
    public void cancelRider(int riderId) {
        if (riders.contains(riderId)) cancelled.add(riderId);
    }
}

class Solution {
    public static long maxScore(int[] nums1, int[] nums2, int K) {
        int n = nums1.length, m = nums2.length;
        final long NEG = Long.MIN_VALUE/4;
        long[][] dp = new long[m+1][K+1];
        for (long[] row : dp) java.util.Arrays.fill(row, NEG);
        for (int j = 0; j <= m; j++) dp[j][0] = 0;
        for (int i = 1; i <= n; i++) {
            long[][] ndp = new long[m+1][K+1];
            for (long[] row : ndp) java.util.Arrays.fill(row, NEG);
            ndp[0][0] = 0;
            for (int j = 1; j <= m; j++) {
                for (int t = 0; t <= K; t++) {
                    long best = Math.max(ndp[j-1][t], dp[j][t]);
                    if (t >= 1 && dp[j-1][t-1] > NEG) {
                        best = Math.max(best, dp[j-1][t-1] + (long) nums1[i-1]*nums2[j-1]);
                    }
                    ndp[j][t] = best;
                }
            }
            dp = ndp;
        }
        return dp[m][K];
    }
}

class Solution {
    public static int longestAlternatingSubarray(int[] nums) {
        int n = nums.length;
        if (n == 0) return 0;
        int[] l1 = new int[n], l2 = new int[n], r1 = new int[n], r2 = new int[n];
        java.util.Arrays.fill(l1,1); java.util.Arrays.fill(l2,1);
        java.util.Arrays.fill(r1,1); java.util.Arrays.fill(r2,1);
        int ans = 1;
        for (int i = 1; i < n; i++) {
            if (nums[i-1] < nums[i]) l1[i] = l2[i-1]+1;
            else if (nums[i-1] > nums[i]) l2[i] = l1[i-1]+1;
            ans = Math.max(ans, Math.max(l1[i], l2[i]));
        }
        for (int i = n-2; i >= 0; i--) {
            if (nums[i+1] > nums[i]) r1[i] = r2[i+1]+1;
            else if (nums[i+1] < nums[i]) r2[i] = r1[i+1]+1;
        }
        for (int i = 1; i < n-1; i++) {
            if (nums[i-1] < nums[i+1]) ans = Math.max(ans, l2[i-1]+r2[i+1]);
            else if (nums[i-1] > nums[i+1]) ans = Math.max(ans, l1[i-1]+r1[i+1]);
        }
        return ans;
    }
}

public class Solution {
    static class TreeNode {
        int val;
        TreeNode left, right;
        TreeNode(int x) { val = x; }
    }

    private static int[] dfsRob(TreeNode node) {
        if (node == null) return new int[]{0, 0};
        int[] l = dfsRob(node.left);
        int[] r = dfsRob(node.right);
        int rob = node.val + l[1] + r[1];
        int skip = Math.max(l[0], l[1]) + Math.max(r[0], r[1]);
        return new int[]{rob, skip};
    }

    public static int houseRobberV(TreeNode root) {
        int[] res = dfsRob(root);
        return Math.max(res[0], res[1]);
    }
}

