class Solution {
    // Two-pass hashmap: count each value's frequency, then count how many
    // distinct values share each frequency. First value whose frequency-count == 1 wins.
    public int firstUniqueFreq(int[] nums) {
        Map<Integer,Integer> cnt = new HashMap<>();
        for (int x : nums) cnt.merge(x, 1, Integer::sum);
        Map<Integer,Integer> freq = new HashMap<>();
        for (int v : cnt.values()) freq.merge(v, 1, Integer::sum);
        for (int x : nums) if (freq.get(cnt.get(x)) == 1) return x;
        return -1;
    }
}

class Solution {
    public static int longestAlmostPalindromicSubstring(String s) {
        int n = s.length();
        if (n == 0) return 0;
        int[][] delp = new int[n][n];
        for (int[] row : delp) java.util.Arrays.fill(row, 2);
        int best = 1;
        for (int i = 0; i < n; i++) delp[i][i] = 0;
        for (int len = 2; len <= n; len++) {
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1;
                if (s.charAt(i) == s.charAt(j)) delp[i][j] = (len==2) ? 0 : delp[i+1][j-1];
                else {
                    int a = delp[i+1][j], b = delp[i][j-1];
                    delp[i][j] = Math.min(1+Math.min(a,b), 2);
                }
                if (delp[i][j] <= 1) best = Math.max(best, len);
            }
        }
        return best;
    }
}

