class Solution {
    static long[] fact = new long[10];
    static {
        fact[0] = 1;
        for (int i = 1; i <= 9; i++) fact[i] = fact[i - 1] * i;
    }

    public boolean isDigitorialPermutation(int n) {
        // digit-factorial sum is invariant under permutation, so just compute it once for n
        long sum = 0;
        int[] cntN = new int[10];
        int x = n;
        while (x > 0) {
            int d = x % 10;
            cntN[d]++;
            sum += fact[d];
            x /= 10;
        }
        // if the digit multisets of n and sum match, sum itself (written normally, no leading
        // zero issue since it's a positive integer) IS a valid permutation of n's digits
        int[] cntSum = new int[10];
        long s = sum;
        do {
            int d = (int) (s % 10);
            cntSum[d]++;
            s /= 10;
        } while (s > 0);
        for (int i = 0; i < 10; i++) if (cntN[i] != cntSum[i]) return false;
        return true;
    }
}

import java.util.*;

public class P7 {
    static List<Boolean> solve(int n, int[][] edges, String s, String[] queries) {
        int LOG = Math.max(1, (int)Math.ceil(Math.log(n+1)/Math.log(2)));
        List<List<Integer>> adj = new ArrayList<>();
        for (int i=0;i<n;i++) adj.add(new ArrayList<>());
        for (int[] e: edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        int[] charBit = new int[n];
        for (int i=0;i<n;i++) charBit[i] = 1 << (s.charAt(i)-'a');
        int[][] up = new int[n][LOG];
        int[] depth = new int[n], tin = new int[n], tout = new int[n], initMask = new int[n];
        int[] timer = {0};
        Deque<int[]> stk = new ArrayDeque<>();
        stk.push(new int[]{0,-1,0});
        while (!stk.isEmpty()) {
            int[] cur = stk.pop();
            int node = cur[0], parent = cur[1], state = cur[2];
            if (state == 0) {
                tin[node] = timer[0]++;
                up[node][0] = parent != -1 ? parent : node;
                for (int k=1;k<LOG;k++) up[node][k] = up[up[node][k-1]][k-1];
                depth[node] = parent == -1 ? 0 : depth[parent]+1;
                initMask[node] = (parent != -1 ? initMask[parent] : 0) ^ charBit[node];
                stk.push(new int[]{node,parent,1});
                for (int nb : adj.get(node)) if (nb != parent) stk.push(new int[]{nb,node,0});
            } else {
                tout[node] = timer[0]-1;
            }
        }
        int[] bit = new int[n+1];
        int finalLOG = LOG;
        java.util.function.BiFunction<Integer,Integer,Integer> lca = null;
        // implement lca inline via lambda referencing arrays
        int[] depthArr = depth;
        int[][] upArr = up;
        java.util.function.IntBinaryOperator lcaFn = (u,v) -> {
            int uu=u, vv=v;
            if (depthArr[uu] < depthArr[vv]) { int t=uu; uu=vv; vv=t; }
            int diff = depthArr[uu]-depthArr[vv], b=0;
            while (diff != 0) { if ((diff&1)!=0) uu = upArr[uu][b]; diff >>= 1; b++; }
            if (uu == vv) return uu;
            for (int k=finalLOG-1;k>=0;k--) if (upArr[uu][k] != upArr[vv][k]) { uu = upArr[uu][k]; vv = upArr[vv][k]; }
            return upArr[uu][0];
        };
        List<Boolean> answers = new ArrayList<>();
        for (String q : queries) {
            String[] parts = q.split(" ");
            if (parts[0].equals("update")) {
                int node = Integer.parseInt(parts[1]);
                int newBit = 1 << (parts[2].charAt(0)-'a');
                int oldBit = charBit[node];
                if (newBit != oldBit) {
                    int delta = oldBit ^ newBit;
                    int i = tin[node]+1; while (i<=n) { bit[i]^=delta; i += i&(-i); }
                    if (tout[node]+1 < n) { i = tout[node]+2; while (i<=n) { bit[i]^=delta; i += i&(-i); } }
                    charBit[node] = newBit;
                }
            } else {
                int u = Integer.parseInt(parts[1]), v = Integer.parseInt(parts[2]);
                int w = lcaFn.applyAsInt(u,v);
                int maskU = initMask[u] ^ bitPrefix(bit, tin[u], n);
                int maskV = initMask[v] ^ bitPrefix(bit, tin[v], n);
                int curW = charBit[w];
                int pathMask = maskU ^ maskV ^ curW;
                answers.add((pathMask & (pathMask-1)) == 0);
            }
        }
        return answers;
    }
    static int bitPrefix(int[] bit, int idx, int n) {
        int res=0, i=idx+1;
        while (i>0) { res ^= bit[i]; i -= i&(-i); }
        return res;
    }
    public static void main(String[] args) {
        System.out.println(solve(3, new int[][]{{0,1},{1,2}}, "aac", new String[]{"query 0 2","update 1 b","query 0 2"}) + " expect [true, false]");
        System.out.println(solve(4, new int[][]{{0,1},{0,2},{0,3}}, "abca", new String[]{"query 1 2","update 0 b","query 2 3","update 3 a","query 1 3"}) + " expect [false, false, true]");
    }
}

