import java.util.*;

public class P8 {
    static int maxSubarrayXorBounded(int[] nums, int k) {
        int n = nums.length;
        int[] prefix = new int[n+1];
        for (int i=0;i<n;i++) prefix[i+1]=prefix[i]^nums[i];
        int maxPref=0; for (int p: prefix) maxPref=Math.max(maxPref,p);
        int maxbit = Math.max(1, maxPref==0?1:(32-Integer.numberOfLeadingZeros(maxPref)));
        List<int[]> trie = new ArrayList<>();
        trie.add(new int[]{-1,-1,0});
        final int MB = maxbit;
        // insert/query as closures using trie list
        return run(nums,k,prefix,trie,MB);
    }
    static int run(int[] nums, int k, int[] prefix, List<int[]> trie, int maxbit) {
        int n = nums.length;
        Deque<Integer> maxdq = new ArrayDeque<>(), mindq = new ArrayDeque<>();
        int l=0, ans=0;
        boolean[] inserted = new boolean[n+1];
        for (int r=0;r<n;r++) {
            while(!maxdq.isEmpty() && nums[maxdq.peekLast()]<=nums[r]) maxdq.pollLast();
            maxdq.addLast(r);
            while(!mindq.isEmpty() && nums[mindq.peekLast()]>=nums[r]) mindq.pollLast();
            mindq.addLast(r);
            while (nums[maxdq.peekFirst()]-nums[mindq.peekFirst()] > k) {
                if (inserted[l]) { insert(trie, prefix[l], -1, maxbit); inserted[l]=false; }
                if (maxdq.peekFirst()==l) maxdq.pollFirst();
                if (mindq.peekFirst()==l) mindq.pollFirst();
                l++;
            }
            insert(trie, prefix[r], 1, maxbit);
            inserted[r]=true;
            ans = Math.max(ans, query(trie, prefix[r+1], maxbit));
        }
        return ans;
    }
    static void insert(List<int[]> trie, int val, int delta, int maxbit) {
        int node=0; trie.get(node)[2]+=delta;
        for (int b=maxbit-1;b>=0;b--) {
            int bit=(val>>b)&1;
            if (trie.get(node)[bit]==-1) { trie.add(new int[]{-1,-1,0}); trie.get(node)[bit]=trie.size()-1; }
            node = trie.get(node)[bit];
            trie.get(node)[2]+=delta;
        }
    }
    static int query(List<int[]> trie, int val, int maxbit) {
        int node=0, res=0;
        for (int b=maxbit-1;b>=0;b--) {
            int bit=(val>>b)&1, want=1-bit;
            if (trie.get(node)[want]!=-1 && trie.get(trie.get(node)[want])[2]>0) { res |= (1<<b); node = trie.get(node)[want]; }
            else node = trie.get(node)[bit];
        }
        return res;
    }
    public static void main(String[] a) {
        int[] nums = {5,4,5,6};
        System.out.println(maxSubarrayXorBounded(nums,2) + " expect 7");
        System.out.println(maxSubarrayXorBounded(nums,1) + " expect 6");
    }
}

