class Solution {
    static final long MOD = 1_000_000_007L;
    static final long INV9 = modPow(9, MOD - 2);

    static long modPow(long base, long exp) {
        long res = 1 % MOD;
        base %= MOD;
        if (base < 0) base += MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }

    public static long sumKDigitNumbers(long L, long R, long K) {
        if (K <= 0) return 0;
        long base = R - L + 1;
        long waysPerPos = modPow(base, K - 1);
        long sumDigits = (L + R) * base / 2;
        long pow10k = modPow(10, K);
        long geoSum = ((pow10k - 1 + MOD) % MOD) * INV9 % MOD;
        long result = waysPerPos * (sumDigits % MOD) % MOD;
        result = result * geoSum % MOD;
        return result;
    }
}

import java.util.*;

class Solution {
    private Map<String, Long> f = new HashMap<>();
    private int[] nums;
    private int n;
    private long k;

    public long countSequences(int[] nums, long k) {
        this.nums = nums;
        this.n = nums.length;
        this.k = k;
        this.f.clear();
        return dfs(0, 1L, 1L);
    }

    private long dfs(int i, long p, long q) {
        if (i == n) return (p == k && q == 1L) ? 1 : 0;
        String key = i + "," + p + "," + q;
        if (f.containsKey(key)) return f.get(key);
        long res = dfs(i + 1, p, q);
        long x = nums[i];
        long g1 = gcd(p * x, q);
        res += dfs(i + 1, (p * x) / g1, q / g1);
        long g2 = gcd(p, q * x);
        res += dfs(i + 1, p / g2, (q * x) / g2);
        f.put(key, res);
        return res;
    }

    private long gcd(long a, long b) {
        while (b != 0) { long t = a % b; a = b; b = t; }
        return a;
    }
}

class Solution {
    public String maxXorAfterRearrangement(String s, String t) {
        int n = s.length();
        int ones = 0;
        for (char c : t.toCharArray()) if (c == '1') ones++;
        int zeros = n - ones;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (c == '0') {
                if (ones > 0) { sb.append('1'); ones--; } else { sb.append('0'); zeros--; }
            } else {
                if (zeros > 0) { sb.append('1'); zeros--; } else { sb.append('0'); ones--; }
            }
        }
        return sb.toString();
    }
}

