class Solution {
    public static int minBitwiseOr(int[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        int answer = 0;
        for (int bit = 30; bit >= 0; bit--) {
            int mask = answer | ((1 << bit) - 1);
            boolean possible = true;
            for (int i = 0; i < n && possible; i++) {
                boolean rowHas = false;
                for (int j = 0; j < m; j++) {
                    if ((grid[i][j] | mask) == mask) {
                        rowHas = true;
                        break;
                    }
                }
                if (!rowHas) possible = false;
            }
            if (!possible) {
                answer |= (1 << bit);
            }
        }
        return answer;
    }
}

