class Solution {
    public static int firstUniqueEven(int[] arr) {
        Set<Integer> seen = new HashSet<>();
        Set<Integer> duplicates = new HashSet<>();
        for (int val : arr) {
            if ((val & 1) == 0) {
                if (!seen.add(val)) {
                    duplicates.add(val);
                }
            }
        }
        for (int val : arr) {
            if ((val & 1) == 0 && !duplicates.contains(val)) {
