public class Solution {
    static int gcd(int a, int b) { while (b != 0) { int t = a % b; a = b; b = t; } return a; }

    public long gcdSum(int[] nums) {
        int n = nums.length;
        int[] prefixGcd = new int[n];
        int mx = 0;
        for (int i = 0; i < n; i++) {
            mx = Math.max(mx, nums[i]);
            prefixGcd[i] = gcd(nums[i], mx);
        }
        Arrays.sort(prefixGcd);
        long ans = 0;
        for (int i = 0; i < n / 2; i++) {
            ans += gcd(prefixGcd[i], prefixGcd[n - i - 1]);
        }
        return ans;
    }
}

import java.util.*;

public class H8 {
    static List<Integer> digitsOf(long x) {
        String s = Long.toString(x);
        List<Integer> d = new ArrayList<>();
        for (char c : s.toCharArray()) d.add(c - '0');
        return d;
    }

    static boolean isGood(long x) {
        List<Integer> d = digitsOf(x);
        if (d.size() == 1) return true;
        boolean inc = true, dec = true;
        for (int i = 0; i + 1 < d.size(); i++) {
            if (!(d.get(i) < d.get(i+1))) inc = false;
            if (!(d.get(i) > d.get(i+1))) dec = false;
        }
        return inc || dec;
    }

    static int digitSum(long x) {
        int s = 0;
        for (int d : digitsOf(x)) s += d;
        return s;
    }

    static long[] GOOD_SORTED;
    static Set<Integer> GOOD_SUMS = new HashSet<>();

    static void buildGoodSet() {
        TreeSet<Long> good = new TreeSet<>();
        for (int mask = 1; mask < (1<<9); mask++) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 9; i++) if ((mask & (1<<i)) != 0) sb.append((char)('1'+i));
            good.add(Long.parseLong(sb.toString()));
        }
        for (int mask = 1; mask < (1<<10); mask++) {
            StringBuilder sb = new StringBuilder();
            for (int i = 9; i >= 0; i--) if ((mask & (1<<i)) != 0) sb.append((char)('0'+i));
            good.add(Long.parseLong(sb.toString()));
        }
        GOOD_SORTED = new long[good.size()];
        int idx = 0;
        for (long v : good) GOOD_SORTED[idx++] = v;
        for (int s = 0; s < 300; s++) if (isGood(s)) GOOD_SUMS.add(s);
    }

    static long countGoodUpTo(long n) {
        if (n < 0) return 0;
        int lo = 0, hi = GOOD_SORTED.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (GOOD_SORTED[mid] <= n) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    static long[][] memo;

    static long dpDigitSum(int pos, boolean tight, int total, String s) {
        int length = s.length();
        if (pos == length) return GOOD_SUMS.contains(total) ? 1 : 0;
        if (!tight && memo[pos][total] != -1) return memo[pos][total];
        int limit = tight ? (s.charAt(pos) - '0') : 9;
        long res = 0;
        for (int d = 0; d <= limit; d++) {
            res += dpDigitSum(pos + 1, tight && d == limit, total + d, s);
        }
        if (!tight) memo[pos][total] = res;
        return res;
    }

    static long countDigitSumGoodUpTo(long n) {
        if (n < 0) return 0;
        String s = Long.toString(n);
        memo = new long[s.length() + 1][300];
        for (long[] row : memo) Arrays.fill(row, -1);
        return dpDigitSum(0, true, 0, s);
    }

    static long countBothUpTo(long n) {
        if (n < 0) return 0;
        long cnt = 0;
        for (long x : GOOD_SORTED) {
            if (x > n) break;
            if (GOOD_SUMS.contains(digitSum(x))) cnt++;
        }
        return cnt;
    }

    static long fancyCountUpTo(long n) {
        if (n < 0) return 0;
        return countGoodUpTo(n) + countDigitSumGoodUpTo(n) - countBothUpTo(n);
    }

    static long countFancyNumbers(long l, long r) {
        return fancyCountUpTo(r) - fancyCountUpTo(l - 1);
    }

    public static void main(String[] args) {
        buildGoodSet();
        System.out.println(countFancyNumbers(8, 10) + " expected 3");
        System.out.println(countFancyNumbers(12340, 12341) + " expected 1");
        System.out.println(countFancyNumbers(123456788, 123456788) + " expected 0");
    }
}

class Solution {
    public int minOperations(String s) {
        boolean isSorted = true;
        char[] cs = s.toCharArray();
        int n = cs.length;
        char mn = cs[0], mx = cs[0];
        for (int i = 1; i < n; ++i) {
            mn = (char) Math.min(mn, cs[i]);
            mx = (char) Math.max(mx, cs[i]);
            if (cs[i] < cs[i - 1]) isSorted = false;
        }
        if (isSorted) return 0;
        if (n == 2) return -1;
        if (cs[0] == mn || cs[n - 1] == mx) return 1;
        for (int i = 1; i < n - 1; ++i) if (cs[i] == mn || cs[i] == mx) return 2;
        return 3;
    }
}

import java.util.*;
public class Solution {
    public static long minCost(String s, long encCost, long flatCost) {
        int n = s.length();
        long[] pre = new long[n+1];
        for (int i = 0; i < n; i++) pre[i+1] = pre[i] + (s.charAt(i) == '1' ? 1 : 0);
        Map<Long, Long> memo = new HashMap<>();
        return dfs(0, n, pre, encCost, flatCost, memo);
    }
    static long dfs(int x, int y, long[] pre, long encCost, long flatCost, Map<Long,Long> memo) {
        long key = (long)x * 200000 + y;
        if (memo.containsKey(key)) return memo.get(key);
        long L = y - x;
        long X = pre[y] - pre[x];
        long whole = (X == 0) ? flatCost : L * X * encCost;
        long res = whole;
        if (L % 2 == 0) {
            int mid = x + (int)(L/2);
            long split = dfs(x, mid, pre, encCost, flatCost, memo) + dfs(mid, y, pre, encCost, flatCost, memo);
            res = Math.min(whole, split);
        }
        memo.put(key, res);
        return res;
    }
}

class Solution {
    public int longestArithmetic(int[] nums) {
        int n = nums.length;
        if (n <= 2) return n;
        int[] left = new int[n];   // left[i] = length of longest arithmetic run ending at i (unmodified)
        int[] right = new int[n];  // right[i] = length of longest arithmetic run starting at i (unmodified)
        Arrays.fill(left, 1);
        Arrays.fill(right, 1);
        left[1] = 2;
        for (int i = 2; i < n; i++) {
            if (nums[i] - nums[i - 1] == nums[i - 1] - nums[i - 2]) left[i] = left[i - 1] + 1;
            else left[i] = 2;
        }
        right[n - 2] = 2;
        for (int i = n - 3; i >= 0; i--) {
            if (nums[i + 1] - nums[i] == nums[i + 2] - nums[i + 1]) right[i] = right[i + 1] + 1;
            else right[i] = 2;
        }
        int ans = 0;
        for (int v : left) ans = Math.max(ans, v);
        ans = Math.max(ans, right[1] + 1);   // modify the leftmost element
        ans = Math.max(ans, left[n - 2] + 1); // modify the rightmost element
        for (int i = 1; i < n - 1; i++) {
            ans = Math.max(ans, left[i - 1] + 1);
            ans = Math.max(ans, right[i + 1] + 1);
            boolean hasDl = (i - 1 >= 1);
            boolean hasDr = (i + 1 <= n - 2);
            Integer dl = hasDl ? nums[i - 1] - nums[i - 2] : null;
            Integer dr = hasDr ? nums[i + 2] - nums[i + 1] : null;
            // try every "natural" candidate diff: the left run's own diff, the right run's own
            // diff, and the exact bridging diff that connects nums[i-1] to nums[i+1] directly
            Set<Integer> candidates = new HashSet<>();
            if (hasDl) candidates.add(dl);
            if (hasDr) candidates.add(dr);
            int gap = nums[i + 1] - nums[i - 1];
            if (gap % 2 == 0) candidates.add(gap / 2);
            for (int d : candidates) {
                int leftExt = (hasDl && d == dl) ? left[i - 1] : 1;
                boolean step1Ok = (nums[i + 1] - nums[i - 1] == 2 * d);
                int rightExt;
                if (!step1Ok) rightExt = 0;
                else rightExt = (hasDr && d == dr) ? right[i + 1] : 1;
                ans = Math.max(ans, leftExt + 1 + rightExt);
            }
        }
        return ans;
    }
}

class Solution {
    class UnionFind {
        Map<Long, Long> p = new HashMap<>();
        Map<Long, Integer> size = new HashMap<>();
        long find(long x) {
            if (!p.containsKey(x)) { p.put(x, x); size.put(x, 1); }
            if (p.get(x) != x) p.put(x, find(p.get(x)));
            return p.get(x);
        }
        boolean union(long a, long b) {
            long pa = find(a), pb = find(b);
            if (pa == pb) return false;
            int sa = size.get(pa), sb = size.get(pb);
            if (sa > sb) { p.put(pb, pa); size.put(pa, sa + sb); }
            else { p.put(pa, pb); size.put(pb, sa + sb); }
            return true;
        }
    }
    public int maxActivated(int[][] points) {
        UnionFind uf = new UnionFind();
        long m = (long) 3e9;
        for (int[] pt : points) uf.union(pt[0], pt[1] + m);
        Map<Long, Integer> cnt = new HashMap<>();
        for (int[] pt : points) cnt.merge(uf.find(pt[0]), 1, Integer::sum);
        int mx1 = 0, mx2 = 0;
        for (int x : cnt.values()) {
            if (mx1 < x) { mx2 = mx1; mx1 = x; }
            else if (mx2 < x) mx2 = x;
        }
        return mx1 + mx2 + 1;
    }
}

