public class Solution {
    public static long solve(int[] A, int[] B) {
        if (A.length != B.length) return -1;
        Map<Integer,Integer> diff = new HashMap<>();
        for (int v : A) diff.merge(v, 1, Integer::sum);
        for (int v : B) diff.merge(v, -1, Integer::sum);
        long swapsNeeded = 0;
        for (int d : diff.values()) {
            if (d % 2 != 0) return -1;
            swapsNeeded += Math.abs(d) / 2;
        }
        return swapsNeeded / 2;
    }
}

class Solution {
    public static long countCommasInRange(long L, long R) {
        return totalUpTo(R) - totalUpTo(L - 1);
    }

    private static long totalUpTo(long N) {
        if (N <= 0) return 0;
        long total = 0;
        long power = 1;
        int digit = 1;
        while (power <= N) {
            long nextPower = power * 10;
            long end = Math.min(N, nextPower - 1);
            long countNumbers = end - power + 1;
            long commasPerNumber = (digit - 1) / 3;
            total += countNumbers * commasPerNumber;
            power = nextPower;
            digit++;
        }
        return total;
    }
}

import java.util.*;
public class P19 {
    static long countGoodSubarrays(int[] nums) {
        int n = nums.length;
        int[] l = new int[n], r = new int[n];
        Arrays.fill(l,-1); Arrays.fill(r,n);
        Deque<Integer> stk = new ArrayDeque<>();
        for (int i=0;i<n;i++) {
            while (!stk.isEmpty() && (nums[stk.peek()]|nums[i])==nums[i]) stk.pop();
            l[i] = stk.isEmpty()? -1: stk.peek();
            stk.push(i);
        }
        stk.clear();
        for (int i=n-1;i>=0;i--) {
            while (!stk.isEmpty() && ((nums[stk.peek()]|nums[i])==nums[i]) && nums[stk.peek()]!=nums[i]) stk.pop();
            r[i] = stk.isEmpty()? n: stk.peek();
            stk.push(i);
        }
        long ans=0;
        for (int i=0;i<n;i++) ans += (long)(i-l[i]) * (r[i]-i);
        return ans;
    }
    public static void main(String[] a) {
        System.out.println(countGoodSubarrays(new int[]{4,2,3})+" expect 4");
        System.out.println(countGoodSubarrays(new int[]{1,3,1})+" expect 6");
    }
}

import java.math.BigInteger;

class Solution {
    public static String countCommas(String L, String R) {
        BigInteger left = new BigInteger(L);
        BigInteger right = new BigInteger(R);
        BigInteger total = BigInteger.ZERO;
        BigInteger start = BigInteger.ONE;
        int d = 1;
        while (start.compareTo(right) <= 0) {
            BigInteger end = start.multiply(BigInteger.TEN).subtract(BigInteger.ONE);
            BigInteger lo = left.max(start);
            BigInteger hi = right.min(end);
            if (lo.compareTo(hi) <= 0) {
                BigInteger count = hi.subtract(lo).add(BigInteger.ONE);
                int commas = (d - 1) / 3;
                total = total.add(count.multiply(BigInteger.valueOf(commas)));
            }
            start = start.multiply(BigInteger.TEN);
            d++;
        }
        return total.toString();
    }
}

public class P20 {
    static final long MOD = 1_000_000_007L;
    static long modpow(long b, long e, long m) { b%=m; long r=1; while(e>0){ if((e&1)==1) r=r*b%m; b=b*b%m; e>>=1;} return r; }
    static long countVisiblePeople(int n, int pos, int k) {
        int l = pos, r = n-pos-1;
        int maxN = Math.max(l,r)+1;
        long[] fact = new long[maxN+1], invFact = new long[maxN+1];
        fact[0]=1;
        for (int i=1;i<=maxN;i++) fact[i]=fact[i-1]*i%MOD;
        invFact[maxN]=modpow(fact[maxN],MOD-2,MOD);
        for (int i=maxN;i>0;i--) invFact[i-1]=invFact[i]*i%MOD;
        long ans=0;
        for (int a=0;a<=Math.min(k,l);a++) {
            int b=k-a;
            if (b<=r) {
                long cl = (a<0||a>l)?0:fact[l]*invFact[a]%MOD*invFact[l-a]%MOD;
                long cr = (b<0||b>r)?0:fact[r]*invFact[b]%MOD*invFact[r-b]%MOD;
                ans=(ans+2*cl%MOD*cr)%MOD;
            }
        }
        return ans;
    }
    public static void main(String[] a) {
        System.out.println(countVisiblePeople(4,1,1)+" expect 6");
        System.out.println(countVisiblePeople(2,0,0)+" expect 2");
    }
}

