import java.util.Map;

class Solution {
    public static int minRemovals(int[] arr, int target) {
        int n = arr.length;
        Map<Integer, Integer> dp = new HashMap<>();
        dp.put(0, 0);
        for (int v : arr) {
            Map<Integer, Integer> updates = new HashMap<>();
            for (Map.Entry<Integer, Integer> entry : dp.entrySet()) {
                int newXor = entry.getKey() ^ v;
                int newSize = entry.getValue() + 1;
                updates.merge(newXor, newSize, Math::max);
            }
            for (Map.Entry<Integer, Integer> e : updates.entrySet()) {
                dp.merge(e.getKey(), e.getValue(), Math::max);
            }
        }
        Integer best = dp.get(target);
        return best == null ? -1 : n - best;
    }
}

