public class EventManager {
    private final TreeMap<Integer, String> tsToName = new TreeMap<>();
    private final Map<String, Integer> nameToTs = new HashMap<>();

    public void addEvent(String name, int timestamp) {
        if (nameToTs.containsKey(name)) return;
        nameToTs.put(name, timestamp);
        tsToName.put(timestamp, name);
    }

    public void deleteEvent(String name) {
        Integer ts = nameToTs.remove(name);
        if (ts != null) tsToName.remove(ts);
    }

    public String getNextEvent(String name) {
        Integer ts = nameToTs.get(name);
        if (ts == null) return "-1";
        Map.Entry<Integer, String> e = tsToName.higherEntry(ts);
        return e == null ? "-1" : e.getValue();
    }

    public String getPreviousEvent(String name) {
        Integer ts = nameToTs.get(name);
        if (ts == null) return "-1";
        Map.Entry<Integer, String> e = tsToName.lowerEntry(ts);
        return e == null ? "-1" : e.getValue();
    }
}

class Solution {
    public long sortableIntegers(int[] nums) {
        int n = nums.length;
        long total = 0;
        for (int k = 1; k <= n; k++) {
            if (n % k != 0) continue;
            int d = n / k;
            boolean ok = true;
            int prevMax = Integer.MIN_VALUE;
            for (int b = 0; b < d && ok; b++) {
                int descents = 0;
                int curMin = Integer.MAX_VALUE, curMax = Integer.MIN_VALUE;
                for (int i = 0; i < k; i++) {
                    int idx = b*k+i;
                    curMin = Math.min(curMin, nums[idx]);
                    curMax = Math.max(curMax, nums[idx]);
                    int nextIdx = b*k + (i+1)%k;
                    if (nums[idx] > nums[nextIdx]) descents++;
                }
                if (descents > 1) { ok = false; break; }
                if (curMin < prevMax) { ok = false; break; }
                prevMax = curMax;
            }
            if (ok) total += k;
        }
        return total;
    }
}

class Solution {
    public int minAbsoluteDifference(int[] nums) {
        int n = nums.length;
        int lastOne = -1, lastTwo = -1;
        int ans = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            if (nums[i] == 1) {
                if (lastTwo != -1) ans = Math.min(ans, i - lastTwo);
                lastOne = i;
            } else if (nums[i] == 2) {
                if (lastOne != -1) ans = Math.min(ans, i - lastOne);
                lastTwo = i;
            }
        }
        return ans == Integer.MAX_VALUE ? -1 : ans;
    }
}

import java.util.HashSet;

class Solution {
    public static int minXorPath(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        @SuppressWarnings("unchecked")
        HashSet<Integer>[] dp = new HashSet[n];
        for (int j = 0; j < n; j++) {
            dp[j] = new HashSet<>();
        }
        dp[0].add(grid[0][0]);
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (i == 0 && j == 0) continue;
                HashSet<Integer> cur = new HashSet<>();
                int val = grid[i][j];
                if (i > 0) {
                    for (int x : dp[j]) {
                        cur.add(x ^ val);
                    }
                }
                if (j > 0) {
                    for (int x : dp[j - 1]) {
                        cur.add(x ^ val);
                    }
                }
                dp[j] = cur;
            }
        }
        int answer = Integer.MAX_VALUE;
        for (int x : dp[n - 1]) {
            if (x < answer) answer = x;
        }
        return answer;
    }
}

class Solution {
    public int mirrorFrequency(String s) {
        Map<Character, Integer> freq = new HashMap<>();
        for (char c : s.toCharArray()) freq.merge(c, 1, Integer::sum);
        Set<Character> visited = new HashSet<>();
        int ans = 0;
        for (char c : freq.keySet()) {
            if (visited.contains(c)) continue; // avoid double-counting the (c,m)/(m,c) pair
            char m;
            if (c >= 'a' && c <= 'z') m = (char) ('a' + 25 - (c - 'a'));
            else m = (char) ('0' + 9 - (c - '0'));
            visited.add(c);
            visited.add(m);
            int mv = freq.getOrDefault(m, 0); // mirror char may not appear in s at all -> freq 0
            ans += Math.abs(freq.get(c) - mv);
        }
        return ans;
    }
}

