public class P26 {
    static int[] parent, parity;
    static int[] find(int x) {
        if (parent[x] == x) return new int[]{x,0};
        int[] res = find(parent[x]);
        parity[x] ^= res[1];
        parent[x] = res[0];
        return new int[]{parent[x], parity[x]};
    }
    static int numberOfGoodEdges(int n, int[][] edges) {
        parent = new int[n]; parity = new int[n];
        for (int i=0;i<n;i++) parent[i]=i;
        int count=0;
        for (int[] e: edges) {
            int u=e[0], v=e[1], w=e[2];
            int[] ru = find(u), rv = find(v);
            if (ru[0] != rv[0]) {
                parent[ru[0]] = rv[0];
                parity[ru[0]] = ru[1] ^ rv[1] ^ w;
                count++;
            } else {
                if ((ru[1]^rv[1]) == w) count++;
            }
        }
        return count;
    }
    public static void main(String[] a) {
        System.out.println(numberOfGoodEdges(3, new int[][]{{0,1,1},{1,2,1},{0,2,1}})+" expect 2");
        System.out.println(numberOfGoodEdges(3, new int[][]{{0,1,1},{1,2,1},{0,2,0}})+" expect 3");
    }
}

class Solution {
    int n;
    int[] nums;
    final long INF = (long) 1e16;

    long dp(int i, int need, int end, long[][] memo) {
        if (need == 0) return 0;
        if (i >= end) return INF;
        if (memo[i][need] != -1) return memo[i][need];
        long skip = dp(i + 1, need, end, memo);
        int prevV = nums[(i - 1 + n) % n];
        int nextV = nums[(i + 1) % n];
        long cost = Math.max((long) Math.max(prevV, nextV) + 1, (long) nums[i]) - nums[i];
        long take = cost + dp(i + 2, need - 1, end, memo);
        return memo[i][need] = Math.min(skip, take);
    }

    long solve(int start, int end, int k) {
        long[][] memo = new long[n + 2][k + 1];
        for (long[] row : memo) Arrays.fill(row, -1);
        return dp(start, k, end, memo);
    }

    public int minOperations(int[] nums_, int k) {
        nums = nums_;
        n = nums.length;
        long ans = Math.min(solve(0, n - 1, k), solve(1, n, k));
        return ans >= INF ? -1 : (int) ans;
    }
}

