class Solution {
    public double[] internalAngles(int[] sides) {
        int[] s = sides.clone();
        Arrays.sort(s);
        double a = s[0], b = s[1], c = s[2];
        if (a + b <= c) return new double[0];
        double A1 = angleOpp(a, b, c);
        double A2 = angleOpp(b, a, c);
        double A3 = angleOpp(c, a, b);
        return new double[]{A1, A2, A3};
    }
    private double angleOpp(double a, double b, double c) {
        double cosv = (b*b + c*c - a*a) / (2.0*b*c);
        cosv = Math.max(-1.0, Math.min(1.0, cosv));
        return Math.toDegrees(Math.acos(cosv));
    }
}

class Solution {
    public int longestBalanced(String s) {
        int n = s.length();
        int cnt0 = 0;
        for (char c : s.toCharArray()) if (c == '0') cnt0++;
        int cnt1 = n - cnt0;
        // pos[x]: sorted list of indices where the running (+1 for '1', -1 for '0') prefix sum equals x
        Map<Integer, List<Integer>> pos = new HashMap<>();
        pos.put(0, new ArrayList<>(List.of(-1)));
        int ans = 0, pre = 0;
        for (int i = 0; i < n; i++) {
            pre += (s.charAt(i) == '1') ? 1 : -1;
            pos.computeIfAbsent(pre, k -> new ArrayList<>()).add(i);
            List<Integer> cur = pos.get(pre);
            ans = Math.max(ans, i - cur.get(0)); // already balanced (sum 0 relative to earliest match)
            // substring with sum +2 (two extra '1's) is fixable by one swap IF a '0' exists outside it
            if (pos.containsKey(pre - 2)) {
                List<Integer> p = pos.get(pre - 2);
                int length = i - p.get(0);
                int zerosInside = (length - 2) / 2;
                if (zerosInside < cnt0) ans = Math.max(ans, i - p.get(0));
                else if (p.size() > 1) ans = Math.max(ans, i - p.get(1)); // shrink to free up a zero
            }
            // substring with sum -2 (two extra '0's) is fixable by one swap IF a '1' exists outside it
            if (pos.containsKey(pre + 2)) {
                List<Integer> p = pos.get(pre + 2);
                int length = i - p.get(0);
                int onesInside = (length - 2) / 2;
                if (onesInside < cnt1) ans = Math.max(ans, i - p.get(0));
                else if (p.size() > 1) ans = Math.max(ans, i - p.get(1));
            }
        }
        return ans;
    }
}

import java.util.*;
class Solution {
    public static int[][] multiSourceFloodFill(int rows, int cols, int[][] sources) {
        int[][] result = new int[rows][cols];
        boolean[][] visited = new boolean[rows][cols];
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] != b[0] ? a[0]-b[0] : a[1]-b[1]);
        for (int[] s : sources) pq.add(new int[]{0, -s[2], s[0], s[1]});
        int[] dr = {1,-1,0,0}, dc = {0,0,1,-1};
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int dist = cur[0], negV = cur[1], r = cur[2], c = cur[3];
            if (visited[r][c]) continue;
            visited[r][c] = true;
            result[r][c] = -negV;
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i], nc = c + dc[i];
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && !visited[nr][nc]) pq.add(new int[]{dist+1, negV, nr, nc});
            }
        }
        return result;
    }
}

public class P32 {
    static int firstStableIndex(int[] nums, long k) {
        int n = nums.length;
        int[] right = new int[n];
        right[n-1] = nums[n-1];
        for (int i=n-2;i>=0;i--) right[i]=Math.min(right[i+1], nums[i]);
        long left = Long.MIN_VALUE;
        for (int i=0;i<n;i++) {
            left = Math.max(left, (long)nums[i]);
            if (left - right[i] <= k) return i;
        }
        return -1;
    }
    public static void main(String[] a) {
        System.out.println(firstStableIndex(new int[]{5,0,1,4},3)+" expect 3");
        System.out.println(firstStableIndex(new int[]{3,2,1},1)+" expect -1");
        System.out.println(firstStableIndex(new int[]{0},0)+" expect 0");
    }
}

class Solution {
    public static int smallestStableIndex(int[] nums, int k) {
        int n = nums.length;
        long[] prefixMax = new long[n];
        long[] suffixMin = new long[n];
        prefixMax[0] = nums[0];
        for (int i = 1; i < n; i++) prefixMax[i] = Math.max(prefixMax[i-1], nums[i]);
        suffixMin[n-1] = nums[n-1];
        for (int i = n-2; i >= 0; i--) suffixMin[i] = Math.min(suffixMin[i+1], nums[i]);
        for (int i = 0; i < n; i++) if (prefixMax[i] - suffixMin[i] <= k) return i;
        return -1;
    }
}

import java.util.*;

class Solution {
    public static long countEvenConnectedSubgraphs(int[] values, int[][] edges) {
        int n = values.length;
        if (n == 0) return 0;
        long oddMask = 0L;
        for (int i = 0; i < n; i++) {
            if ((values[i] & 1) != 0) oddMask |= 1L << i;
        }
        long[] adjMask = new long[n];
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            adjMask[u] |= 1L << v;
            adjMask[v] |= 1L << u;
        }
        long totalMasks = 1L << n;
        long answer = 0L;
        for (long mask = 1L; mask < totalMasks; mask++) {
            if ((Long.bitCount(mask & oddMask) & 1) == 1) continue;
            int start = Long.numberOfTrailingZeros(mask);
            long visited = 0L;
            long frontier = 1L << start;
            while (frontier != 0L) {
                visited |= frontier;
                long neighbors = 0L;
                long bits = frontier;
                while (bits != 0L) {
                    int v = Long.numberOfTrailingZeros(bits);
                    bits &= bits - 1;
                    neighbors |= adjMask[v];
                }
                frontier = (neighbors & mask) & ~visited;
            }
            if (visited == mask) answer++;
        }
        return answer;
    }
}

import java.util.*;
class Solution {
    static boolean[] key16 = new boolean[16];
    static String s16;
    static long[][] memo = new long[16][10];
    static boolean[][] memoSet = new boolean[16][10];
    static long dfs(int pos, int last, boolean lim) {
        if (pos == 16) return 1;
        if (!lim && memoSet[pos][last]) return memo[pos][last];
        long res = 0;
        int start = key16[pos] ? last : 0;
        int end = lim ? (s16.charAt(pos)-'0') : 9;
        for (int i = start; i <= end; i++) {
            res += dfs(pos+1, key16[pos] ? i : last, lim && (i==end));
        }
        if (!lim) { memo[pos][last]=res; memoSet[pos][last]=true; }
        return res;
    }
    static long calc(long x) {
        if (x < 0) return 0;
        String t = Long.toString(x);
        StringBuilder sb = new StringBuilder();
        for (int i=0;i<16-t.length();i++) sb.append('0');
        sb.append(t);
        s16 = sb.toString();
        for (boolean[] row: memoSet) Arrays.fill(row, false);
        return dfs(0, 0, true);
    }
    public static long countGoodIntegersOnPath(long l, long r, String directions) {
        Arrays.fill(key16, false);
        int row=0, col=0;
        key16[0]=true;
        for (char c: directions.toCharArray()) {
            if (c=='D') row++; else col++;
            key16[row*4+col]=true;
        }
        return calc(r) - calc(l-1);
    }
}

class Solution {
    public int[] answerQueries(int[] nums, int[][] queries) {
        int n = nums.length;
        int[] prefixEven = new int[n + 1];
        for (int i = 0; i < n; i++) prefixEven[i + 1] = prefixEven[i] + (nums[i] % 2 == 0 ? 1 : 0);

        int q = queries.length;
        int[] ans = new int[q];
        for (int qi = 0; qi < q; qi++) {
            int li = queries[qi][0], ri = queries[qi][1];
            long k = queries[qi][2];
            int rangeLen = ri - li + 1;
            // Binary search on e where candidate even value x = 2e. remainingCount(e) = e - removedEvensLE(2e)
            // is non-decreasing in e (each step either adds 1 to remaining, or removes it because that even
            // value is in the subarray), so find the smallest e whose remaining count reaches k.
            long lo = 1, hi = k + rangeLen + 2;
            while (lo < hi) {
                long mid = lo + (hi - lo) / 2;
                long removed = removedEvensLE(nums, prefixEven, li, ri, 2 * mid);
                if (mid - removed >= k) hi = mid; else lo = mid + 1;
            }
            ans[qi] = (int) (2 * lo);
        }
        return ans;
    }

    // Count of nums[li..ri] that are even and <= x (nums is strictly increasing, so binary search the range).
    private long removedEvensLE(int[] nums, int[] prefixEven, int li, int ri, long x) {
        int lo = li, hi = ri, pos = li - 1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (nums[mid] <= x) { pos = mid; lo = mid + 1; } else hi = mid - 1;
        }
        if (pos < li) return 0;
        return prefixEven[pos + 1] - prefixEven[li];
    }
}

class Solution {
    public List<Integer> findValidElements(int[] nums) {
        int n = nums.length;
        int[] sufMax = new int[n];
        sufMax[n - 1] = nums[n - 1];
        for (int i = n - 2; i >= 0; i--) sufMax[i] = Math.max(sufMax[i + 1], nums[i]);
        List<Integer> ans = new ArrayList<>();
        int preMax = Integer.MIN_VALUE;
        for (int i = 0; i < n; i++) {
            int x = nums[i];
            if (x > preMax || i == n - 1 || x > sufMax[i + 1]) ans.add(x);
            preMax = Math.max(preMax, x);
        }
        return ans;
    }
}

