class Solution {
    public static int compareSums(int[] arr) {
        if (arr.length == 0) return -1;
        long total = 0;
        int peakVal = arr[0];
        long leftSum = 0, cum = 0;
        for (int v : arr) {
            total += v;
            if (v > peakVal) { peakVal = v; leftSum = cum; }
            cum += v;
        }
        long rightSum = total - leftSum - peakVal;
        if (leftSum > rightSum) return 0;
        if (leftSum < rightSum) return 1;
        return -1;
    }
}

