class Solution {
    static final int MAXV = 100001;

    public long maxAlternatingSum(int[] nums, int k) {
        int n = nums.length;
        long[] bitDown = new long[MAXV + 2]; // prefix-max Fenwick keyed by value, holds best "down"-state score
        long[] bitUp = new long[MAXV + 2];   // prefix-max Fenwick keyed by (MAXV+1-value), holds best "up"-state score
        long[] up = new long[n], down = new long[n];
        long ans = Long.MIN_VALUE;
        int inserted = -1;
        for (int i = 0; i < n; i++) {
            // release every earlier index that is now far enough away (>= k) to be a valid predecessor
            int limit = i - k;
            while (inserted < limit) {
                inserted++;
                update(bitDown, nums[inserted], down[inserted]);
                update(bitUp, MAXV + 1 - nums[inserted], up[inserted]);
            }
            // up[i]: last transition into i was an increase, so predecessor must be in "down" state with smaller value
            long bestDown = query(bitDown, nums[i] - 1);
            up[i] = nums[i] + Math.max(0, bestDown);
            // down[i]: last transition into i was a decrease, so predecessor must be in "up" state with larger value
            long bestUp = query(bitUp, MAXV + 1 - (nums[i] + 1));
            down[i] = nums[i] + Math.max(0, bestUp);
            ans = Math.max(ans, Math.max(up[i], down[i]));
        }
        return ans;
    }

    private void update(long[] bit, int i, long val) {
        for (; i <= MAXV; i += i & (-i)) bit[i] = Math.max(bit[i], val);
    }
    private long query(long[] bit, int i) {
        long res = 0;
        for (; i > 0; i -= i & (-i)) res = Math.max(res, bit[i]);
        return res;
    }
}

class Solution {
    public String sortVowels(String s) {
        int[] freq = new int[128];
        int[] firstOcc = new int[128];
        Arrays.fill(firstOcc, -1);
        List<Integer> vowelPositions = new ArrayList<>();
        String vowelsOrder = "aeiou";
        char[] arr = s.toCharArray();
        for (int i = 0; i < arr.length; i++) {
            char c = arr[i];
            if (vowelsOrder.indexOf(c) >= 0) {
                vowelPositions.add(i);
                freq[c]++;
                if (firstOcc[c] == -1) firstOcc[c] = i;
            }
        }
        char[] vowels = vowelsOrder.toCharArray();
        List<Character> present = new ArrayList<>();
        for (char c : vowels) if (freq[c] > 0) present.add(c);
        present.sort((a, b) -> {
            if (freq[a] != freq[b]) return freq[b] - freq[a];
            return firstOcc[a] - firstOcc[b];
        });
        int idx = 0;
        for (char c : present) {
            for (int k = 0; k < freq[c]; k++) {
                arr[vowelPositions.get(idx++)] = c;
            }
        }
        return new String(arr);
    }
}

import java.util.ArrayList;
import java.util.List;

class Solution {
    public static long sumPrimesBetweenReverse(int num) {
        int rev = 0, tmp = num;
        while (tmp > 0) {
            rev = rev * 10 + (tmp % 10);
            tmp /= 10;
        }
        int low = Math.min(num, rev);
        int high = Math.max(num, rev);
        if (high < 2) return 0L;
        int limit = (int) Math.sqrt(high);
        boolean[] isPrimeSmall = new boolean[limit + 1];
        for (int i = 2; i <= limit; i++) isPrimeSmall[i] = true;
        for (int i = 2; i * i <= limit; i++) {
            if (isPrimeSmall[i]) {
                for (int j = i * i; j <= limit; j += i) {
                    isPrimeSmall[j] = false;
                }
            }
        }
        List<Integer> primes = new ArrayList<>();
        for (int i = 2; i <= limit; i++) {
            if (isPrimeSmall[i]) primes.add(i);
        }
        int segmentSize = high - low + 1;
        boolean[] isCompositeSeg = new boolean[segmentSize];
        for (int p : primes) {
            long start = Math.max((long) p * p, ((low + p - 1) / p) * (long) p);
            for (long j = start; j <= high; j += p) {
                isCompositeSeg[(int) (j - low)] = true;
            }
        }
        long sum = 0L;
        for (int i = low; i <= high; i++) {
            if (i >= 2 && !isCompositeSeg[i - low]) {
                sum += i;
            }
        }
        return sum;
    }
}

class Solution {
    // A coherent string can only take one of a few shapes (verified by exhaustive
    // enumeration for small n: exactly n+3 valid strings total):
    //   - all zeros
    //   - all ones
    //   - a single '1' surrounded by zeros (any position)
    //   - a '1' at both ends with zeros strictly in between
    // Any other arrangement creates either "011" or "110" as a subsequence.
    // Take the minimum Hamming distance from s to the best member of each family.
    public int minFlips(String s) {
        int n = s.length();
        int totalOnes = 0;
        for (char c : s.toCharArray()) if (c == '1') totalOnes++;

        int costAll0 = totalOnes;
        int costAll1 = n - totalOnes;
        // cheapest single-1 target: keep an existing '1' in place if one exists
        int bestSingle1 = (totalOnes >= 1) ? (totalOnes - 1) : 1;

        int costTwoEnds;
        if (n == 1) {
            costTwoEnds = (s.charAt(0) == '1') ? 0 : 1;
        } else {
            int left = (s.charAt(0) == '1') ? 0 : 1;
            int right = (s.charAt(n - 1) == '1') ? 0 : 1;
            int middleOnes = 0;
            for (int i = 1; i < n - 1; i++) if (s.charAt(i) == '1') middleOnes++;
            costTwoEnds = left + right + middleOnes;
        }

        return Math.min(Math.min(costAll0, costAll1), Math.min(bestSingle1, costTwoEnds));
    }
}

import java.util.*;
class Solution {
    public int[] minCosts(int[] nums, int[][] queries) {
        int n = nums.length;
        int[] closest = new int[n];
        for (int i = 0; i < n; i++) {
            if (i == 0) closest[i] = 1;
            else if (i == n-1) closest[i] = n-2;
            else {
                int dl = nums[i]-nums[i-1], dr = nums[i+1]-nums[i];
                closest[i] = dl <= dr ? i-1 : i+1;
            }
        }
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int i = 0; i < n-1; i++) {
            int w = nums[i+1]-nums[i];
            adj.get(i).add(new int[]{i+1, w});
            adj.get(i+1).add(new int[]{i, w});
        }
        for (int i = 0; i < n; i++) adj.get(i).add(new int[]{closest[i], 1});

        Map<Integer, long[]> cache = new HashMap<>();
        int[] ans = new int[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            int l = queries[qi][0], r = queries[qi][1];
            long[] dist = cache.get(l);
            if (dist == null) {
                dist = new long[n];
                Arrays.fill(dist, Long.MAX_VALUE/2);
                dist[l] = 0;
                PriorityQueue<long[]> pq = new PriorityQueue<>((a,b) -> Long.compare(a[0], b[0]));
                pq.add(new long[]{0, l});
                while (!pq.isEmpty()) {
                    long[] cur = pq.poll();
                    long d = cur[0]; int u = (int) cur[1];
                    if (d > dist[u]) continue;
                    for (int[] e : adj.get(u)) {
                        int v = e[0], w = e[1];
                        if (d + w < dist[v]) {
                            dist[v] = d + w;
                            pq.add(new long[]{dist[v], v});
                        }
                    }
                }
                cache.put(l, dist);
            }
            ans[qi] = (int) dist[r];
        }
        return ans;
    }
}

