class Solution {
    public static boolean isArmstrong(long num) {
        if (num < 0) return false;
        long temp = num;
        int digitCount = 0;
        do {
            digitCount++;
            temp /= 10;
        } while (temp != 0);
        long[] pow = new long[10];
        for (int d = 0; d <= 9; d++) {
            long p = 1;
            for (int i = 0; i < digitCount; i++) p *= d;
            pow[d] = p;
        }
        long sum = 0;
        temp = num;
        while (temp != 0) {
            int digit = (int) (temp % 10);
            sum += pow[digit];
            temp /= 10;
        }
        return sum == num;
    }
}

