        int[] arr = new int[n];
        System.arraycopy(nums, 0, arr, 0, n);
        for (int i = 0; i < n; i++) {
            add(bit, i + 1, arr[i]);
        }
        List<Long> answers = new ArrayList<>();
        for (List<Object> q : queries) {
            String type = (String) q.get(0);
            if (type.equals("update")) {
                int idx = (int) q.get(1);
                int val = (int) q.get(2);
                long delta = (long) val - arr[idx];
                arr[idx] = val;
                add(bit, idx + 1, delta);
            } else {
                int left = (int) q.get(1);
                int right = (int) q.get(2);
                long sum = query(bit, right + 1) - query(bit, left);
                answers.add(sum);
            }
        }
        return answers;
    }

    private static void add(long[] bit, int idx, long delta) {
        int n = bit.length - 1;
        while (idx <= n) {
            bit[idx] += delta;
            idx += idx & -idx;
        }
    }

    private static long query(long[] bit, int idx) {
        long sum = 0;
        while (idx > 0) {
            sum += bit[idx];
            idx -= idx & -idx;
        }
        return sum;
    }
}

public class Solution {
    public static int bestTimeToBuySellCooldown(int[] prices) {
        if (prices == null || prices.length == 0) return 0;
        int cash = 0;
        int hold = -prices[0];
        int prevCash = 0;
        for (int i = 1; i < prices.length; i++) {
            int newCash = Math.max(cash, hold + prices[i]);
            int newHold = Math.max(hold, prevCash - prices[i]);
            prevCash = cash;
            cash = newCash;
            hold = newHold;
        }
        return cash;
    }
}

import java.util.ArrayList;
import java.util.List;

class Solution {
    public static List<Integer> findStableMountains(int[] height, int threshold) {
        List<Integer> stableMountains = new ArrayList<>(height != null ? height.length : 0);
        if (height == null) return stableMountains;
        for (int i = 1; i < height.length; i++) {
            if (height[i - 1] > threshold) {
                stableMountains.add(i);
            }
        }
        return stableMountains;
    }
}

import java.util.*;
class Solution {
    public static int[] countHouses(int n, int x, int y) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
        for (int i = 1; i < n; i++) { adj.get(i).add(i+1); adj.get(i+1).add(i); }
        if (x != y) { adj.get(x).add(y); adj.get(y).add(x); }
        int[] result = new int[n];
        for (int src = 1; src <= n; src++) {
            int[] dist = new int[n+1];
            Arrays.fill(dist, -1);
            dist[src] = 0;
            Queue<Integer> q = new LinkedList<>();
            q.add(src);
            while (!q.isEmpty()) {
                int cur = q.poll();
                for (int nxt : adj.get(cur)) if (dist[nxt]==-1) { dist[nxt]=dist[cur]+1; q.add(nxt); }
            }
            for (int dest = 1; dest <= n; dest++) {
                if (dest==src) continue;
                int d = dist[dest];
                if (d>=1 && d<=n-1) result[d-1]++;
            }
        }
        return result;
    }
}

class Solution {
    public static int minCost(int[] nums) {
        int n = nums.length;
        if (n < 3) {
            return 0;
        }
        int minLeft = nums[1];
        int minSum = Integer.MAX_VALUE;
        for (int q = 2; q < n; q++) {
            int candidate = minLeft + nums[q];
            if (candidate < minSum) {
                minSum = candidate;
            }
            if (nums[q] < minLeft) {
                minLeft = nums[q];
            }
        }
        return nums[0] + minSum;
    }
}

class Solution {
    public int minOperations(int[] nums, int k) {
        int x = k;
        for (int v : nums) x ^= v;
        return Integer.bitCount(x);
    }
}

class Solution {
    public long maximumSubarraySum(int[] nums, int k) {
        // valToMinPrefix: for each value seen, the smallest prefix-sum-before-it (best possible
        // subarray start using that value as the first element)
        Map<Integer, Long> valToMinPrefix = new HashMap<>();
        long prefix = 0;
        Long best = null;
        for (int x : nums) {
            if (valToMinPrefix.containsKey(x - k)) {
                long cand = prefix + x - valToMinPrefix.get(x - k);
                best = (best == null) ? cand : Math.max(best, cand);
            }
            if (valToMinPrefix.containsKey(x + k)) {
                long cand = prefix + x - valToMinPrefix.get(x + k);
                best = (best == null) ? cand : Math.max(best, cand);
            }
            if (!valToMinPrefix.containsKey(x) || valToMinPrefix.get(x) > prefix) {
                valToMinPrefix.put(x, prefix);
            }
            prefix += x;
        }
        return best != null ? best : 0;
    }
}

class Solution {
    private long[] countLeSamelen(String bound, int limit) {
        int n = bound.length();
        long total = 0;
        boolean exactAchievable = true;
        for (int i = 0; i < n; i++) {
            int d = bound.charAt(i) - '0';
            int lo = (i == 0) ? 1 : 0;
            int hi = Math.min(d - 1, limit);
            if (hi >= lo) {
                int ways = hi - lo + 1;
                int remaining = n - i - 1;
                total += (long) ways * (long) Math.pow(limit + 1, remaining);
            }
            if (d > limit) { exactAchievable = false; break; }
        }
        return new long[]{total, exactAchievable ? 1 : 0};
    }

    private long countUpto(long x, int limit, String s) {
        if (x <= 0) return 0;
        String sx = Long.toString(x);
        int n = sx.length(), ls = s.length();
        for (char c : s.toCharArray()) if (c - '0' > limit) return 0;
        if (n < ls) return 0;
        long total = 0;
        for (int L = ls; L < n; L++) {
            if (L == ls) {
                if (s.charAt(0) != '0') total += 1;
            } else {
                int free = L - ls;
                total += (long) limit * (long) Math.pow(limit + 1, free - 1);
            }
        }
        int preLen = n - ls;
        if (preLen == 0) {
            if (s.charAt(0) != '0' && s.compareTo(sx) <= 0) total += 1;
        } else {
            String prefixOfX = sx.substring(0, preLen);
            String suffixOfX = sx.substring(preLen);
            long[] r = countLeSamelen(prefixOfX, limit);
            long cnt = r[0];
            if (r[1] == 1 && suffixOfX.compareTo(s) >= 0) cnt += 1;
            total += cnt;
        }
        return total;
    }

    public long numberOfPowerfulInt(long start, long finish, int limit, String s) {
        return countUpto(finish, limit, s) - countUpto(start - 1, limit, s);
    }
}

import java.util.Arrays;

class Solution {
    public static int minimumKeypresses(String word) {
        int[] freq = new int[26];
        for (int i = 0; i < word.length(); i++) {
            freq[word.charAt(i) - 'a']++;
        }
        Arrays.sort(freq);
        int result = 0;
        int presses = 1;
        int count = 0;
        for (int i = 25; i >= 0; i--) {
            if (freq[i] == 0) break;
            result += freq[i] * presses;
            count++;
            if (count % 8 == 0) presses++;
        }
        return result;
    }
}

import java.util.*;

class Solution {
    public static List<Integer> beautifulIndices(String s, String a, String b, int k) {
        List<Integer> aPos = new ArrayList<>();
        List<Integer> bPos = new ArrayList<>();
        int idx = s.indexOf(a);
        while (idx != -1) {
            aPos.add(idx);
            idx = s.indexOf(a, idx + 1);
        }
        idx = s.indexOf(b);
        while (idx != -1) {
            bPos.add(idx);
            idx = s.indexOf(b, idx + 1);
        }
        List<Integer> result = new ArrayList<>();
        int p = 0;
        for (int i : aPos) {
            while (p < bPos.size() && bPos.get(p) < i - k) {
                p++;
            }
            if (p < bPos.size() && bPos.get(p) <= i + k) {
                result.add(i);
            }
        }
        return result;
    }
}

import java.util.*;

class Solution {
    public int maximumSetSize(int[] nums1, int[] nums2) {
        int n = nums1.length;
        int half = n / 2;
        Set<Integer> set1 = new HashSet<>(), set2 = new HashSet<>();
        for (int x : nums1) set1.add(x);
        for (int x : nums2) set2.add(x);
        Set<Integer> common = new HashSet<>(set1);
        common.retainAll(set2);
        int only1 = set1.size() - common.size();
        int only2 = set2.size() - common.size();
        // prioritize values unique to each array first (common values can be covered by either side)
        int take1 = Math.min(only1, half);
        int remain1 = half - take1;
        int take2 = Math.min(only2, half);
        int remain2 = half - take2;
        int commonUsed = Math.min(common.size(), remain1 + remain2);
        return take1 + take2 + commonUsed;
    }
}

class Solution {
    public static long minCost(int[] nums, int k, int dist) {
        int n = nums.length;
        final long INF = Long.MAX_VALUE/2;
        long answer = INF;
        for (int i1 = 1; i1 < n; i1++) {
            int maxLast = Math.min(n-1, i1+dist);
            int minLast = i1 + (k-2) - 1;
            if (minLast > maxLast) continue;
            for (int iLast = minLast; iLast <= maxLast; iLast++) {
                int interiorLen = iLast - i1 - 1;
                int need = Math.max(k-3, 0);
                if (interiorLen < need) continue;
                int[] interior = java.util.Arrays.copyOfRange(nums, i1+1, iLast);
                java.util.Arrays.sort(interior);
                long sumSmallest = 0;
                for (int x = 0; x < need; x++) sumSmallest += interior[x];
                long total = nums[0]+nums[i1]+nums[iLast]+sumSmallest;
                if (total < answer) answer = total;
            }
        }
        return answer==INF ? -1 : answer;
    }
}

class Solution {
    public long minDamage(int power, int[] damage, int[] health) {
        int n = damage.length;
        long[][] a = new long[n][2]; // [hits needed, damage per second]
        for (int i = 0; i < n; i++) {
            a[i][0] = (health[i] - 1) / power + 1;
            a[i][1] = damage[i];
        }
        // Exchange-argument greedy: kill enemies in increasing order of hits[i]/damage[i]
        // (compare via cross-multiplication to avoid floating point).
        Arrays.sort(a, (p, q) -> Long.compare(p[0]*q[1], q[0]*p[1]));
        long ans = 0;
        long s = 0; // cumulative hits so far - kept as long throughout (a known accepted
                    // solution used a plain int here and overflowed on a large hack test,
                    // per LeetCode-Feedback #23837)
        for (long[] p : a) {
            s += p[0];
            ans += s * p[1];
        }
        return ans;
    }
}

import java.util.Arrays;

class Solution {
    public static boolean canSortArray(int[] nums) {
        int[] sorted = Arrays.copyOf(nums, nums.length);
        Arrays.sort(sorted);
        for (int i = 0; i < nums.length; i++) {
            if (Integer.bitCount(nums[i]) != Integer.bitCount(sorted[i])) {
                return false;
            }
        }
        return true;
    }
}
